INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1, 'عق', 'عق', 'عق', 'قال الليث: قال الخليل: العرب تقول: عق الرجل عن ابنه يعق إذا حلق عقيقته وذبح عنه شاة وتسمى الشاة التي تذبح لذلك: عقيقة قال ليث: توفر اعضاؤها فتطبخ بماء وملح وتطعم المساكين. ومن الحديث كل امرىء مرتهن بعقيقته. وفي الحديث: أن رسول الله ص عق عن الحسن والحسين بزنة شعرهما ورقا. والعقة: العقيقة وتجمع عققا. والعقيقة: الشعر الذي يولد الولد به وتسمى الشاة التي تذبح لذلك عقيقة يقع اسم الذبح على الطعام، كما وقع اسم الجزور التي تنقع على النقيعة وقال زهير في العقيقة: أذلك أم أقب البطن جأب ... عليه من عقيقته عفاء 1 . وقال امرؤ القيس: يا هند لا تنكحي بوهة ... عليه عقيقته أحسبا ويقال: أعقت الحامل إذا نبتت العقيقة على ولدها في بطنها فهي معق وعقوق. العقوق: عقق. قال رؤبة: قد عتق الأجدع بعد رق ... بقارح أو زولة معق وقال: وسوس يدعو مخلصا رب الفلق ... سرا وقد أون تأوين العقق وقال أيضا: كالهروي انجاب عن لون السرق 1 ... طير عنها النسر 2 حولي العقق أي جماعة العقة. وقال عدي بن زيد في العقة أي العقيقة: صخب التعشير نوام الضحى 3 ... ناسل عقته مثل المسد ونوى العقوق: نوى هش لين رخو المضغة. تعلفه الناقة العقوق إلطافا لها فلذلك أضيف إليها، وتأكله العجوز. وهي من كلام أهل البصرة، ولا تعرفه الأعراب في بواديها. وعقيقة البرق: ما يبقى في السحاب من شعاعه. وجمعه العقائق، قال عمرو بن كلثوم: بسمر من قنا الخطي لدن ... وبيض كالعقائق يختلينا 4 وانعق البرق إذا تسرب في السحاب، وانعق الغبار: إذا سطع. قال رؤبة: 5 إذا العجاج المستطار انعقا قال أبو عبد الله: أصل العق الشق. وأليه يرجع عقوق الوالدين وهو قطعهما، لأن الشق والقطع واحد، يقال: عق ثوبه إذا شقه. عق والديه يعقهما عقا وعقوقا، قال زهير: فأصبحتما منها على خير موطن ... بعيدين فيها عن عقوق ومأثم وقال آخر: ان البنين شرارهم أمثاله ... من عق والده وبر الأبعدا وقال أبو سفيان بن حرب (لحمزة سيد الشهداء، يوم أحد حين مر به وهو مقتول: ذق عقق أي ذق جزاء ما فعلت 1 يا عاق لأنك قطعت رحمك وخالفت آباءك. والمعقة والعقوق واحد، قال النابغة: أحلام عاد وأجسام 2 مطهرة ... من المعقة والآفات والإثم والعقيق: خرز أحمر ينظم ويتخذ منه الفصوص، الواحدة عقيقة. (والعقيق واد بالحجاز كأنه عق أي شق، غلبت عليه الصفة غلبة الاسم ولزمته الألف واللام كأنه جعل الشيء بعينه) 3 ، وقال جرير: فهيهات هيهات العقيق وأهله ... وهيهات خل بالعقيق نواصله 4 أي بعد العقيق: والعقعق: طائر طويل الذيل أبلق يعقعق بصوته وجمعه عقاعق.'),
(2, 'قع', 'قع', 'قع', 'القعاع: ماء مر غليظ، ويجمع أقعة. وأقع القوم إقعاعا: أذا حضروا فوقعوا على قعاع والقعقاع: الطريق من اليمامة إلى الكوفة، قال ابن أحمر: ولما أن بدا القعقاع لحت ... على شرك تناقله نقالا والقعقعة: حكاية صوت (السلاح والترسة) 5 والحلي والجلود اليابسة والخطاف والبكرة أو نحو ذلك، قال النابغة: يسهد من نوم العشاء سليمها 6 ... لحلي النساء في يديه قعاقع القعاقع جمع قعقعة، قال: إنا إذا خطافنا تقعقعا ... وصرت البكرة يوما أجمعا ذلك أن الملدوغ يوضع في يديه شيء من الحلي حتى يحركه به فيسلي به الهم، ويقال: يمنع من النوم لئلا يدب فيه السم. ورجل قعقعاني: إذا مشى سمعت لمفاصل رجليه تقعقعا. وحمار قعقعاني: إذا حمل على العانة 1 صك لحييه. والقعقاع مثل القعقعاني، قال رؤبة: شاحي لحيي قعقعاني الصلق ... قعقعة المحور خطاف العلق والأسد ذو قعاقع، إذا مشى سمعت لمفاصله صوتا، قال متمم بن نويرة يرثي أخاه مالكا: ولا برم تهدي النساء لعرسه 2 ... إذا القشع من برد الشتاء تقعقعا والقعاقع: ضرب من الحجارة ترمى بها النخل لتنثر من تمرها 3 . قال زائدة: القعقعان 4 : ضرب من التمر. والقعقع: طائر أبلق ببياض وسواد، طويل المنقار والرجلين ضخم، من طيور البر يظهر أيام الربيع ويذهب في الشتاء. وقعيقعان: اسم جبل بالحجاز، تنحت منه الأساطين، في حجارته رخاوة، بنيت أساطين مسجد البصرة. ويقال للمهزول قد صار عظاما يتقعقع من هزاله. والرعد يقعقع بصوته.'),
(3, 'عك', 'عك', 'عك', '1 العكة عكة السمن أصغر من القربة، وتجمع عكاكا وعكا. والأكة لغة في العكة فورة الحر شديدة في القيظ، تجعل الهمزة بدل العين. قال الساجع: وإذا طلعت العذرة، لم يبق بعمان بسرة، ولا لأكار برة، وكانت عكة نكرة على أهل البصرة 2 . وتجمع عكاكا. والعكة: رملة حميت عليها الشمس 3 . وحر عكيك، ويوم عكيك، أي شديد الحر، قال طرفة: تطرد القر بحر صادق ... وعكيك القيظ إن جاء بقر يصف جارية وعكيك الصيف: إذا جاء بحر مع سكون الريح وعك بن عدنان أو معد، وهو أبو قوم 4 باليمن. والعكوك: الرجل القصير الملزز المقتدر الخلق، إلى القصر كله. والمعك- مشدد الكاف- من الخيل: الذي يجري قليلا فيحتاج إلى الضرب والعكنكع: الذكر الخبيث من السعالي، قال الراجز يذكر امرأة وزوجها: كأنها وهو إذا استبا معا ... غول تداهي شرسا عكنكعا'),
(4, 'كع', 'كع', 'كع', 'رجل كع، كاع- بالتشديد- وقد كع كعوعا: إذا تلكأ وجبن، قال: وإني لكرار بسيفي لدى الوغى ... إذا كان كع القوم للرحل لازما وأكعه الفرق عن ذلك، فهو لا يمضي في حزم ولا عزم، وهو العاجز الناكص على عقبيه وكعكعة الخوف تجري مجرى الاكعاع، قال: كعكعته بالرجم والتنجه 1 . والكعك: الخبز اليابس، قال: 2 يا حبذا الكعك بلحم مثرود ... وخشكنان بسويق مقنود ويقال: أكعه الرجل عن كذا يكعه إذا حبسه عن وجهه.'),
(5, 'عج', 'عج', 'عج', 'العج: رفع الصوت، يقال: عج يعج عجا وعجيجا. وفي الحديث: أفضل الحج العج والثج فالعج رفع الصوت بالتلبية، والثج صب الدماء، يعني الذبائح، قال ورقة بن نوفل: ولوجا 3 في الذي كرهت قريش ... وإن عجت بمكتها عجيجا وقال العجاج: حتى يعج ثخنا من عجعجا والعجاج: الغبار، والتعجيج إثارة الريح الغبار، وفاعله العجاج والمعجاج، تقول: عججته 4 الريح تعجيجا، وعججت البيت دخانا حتى تعجج، أي امتلأ بالدخان. والبعير يعج في هديره عجيجا وعجا، قال: أنعت قرما بالهدير عاججا 1 وعجعجت بالناقة: عطفتها إلى شيء 2 . جع: جعجعت الإبل: حركتها للإناخة. قال الأغلب: 3 عود إذا جعجع بعد الهب ... جرجر في حنجرة كالجب وجعجعت بالرجل: حبسته في مجلس سوء. والجعجاع من الأرض: معركة الأبطال قال أبو ذؤيب: فأبدهن حتوفهن فهارب ... بدمائه أو بارك متجعجع.'),
(6, 'عش', 'عش', 'عش', 'العش: ما يتخذه الطائر في رؤوس الأشجار للتفريخ، ويجمع عششة واعتش الطائر إذا اتخذ عشا، قال يصف الناقة: 1 يتبعها ذو كدنة جرائض ... الخشب الطلح هصور هائض بحيث يعتش الغراب البائض قال: البائض وهو ذكر، فإن قال قائل: الذكر لا يبيض، قيل: هو في البيض سبب ولذلك جعله بائضا، على قياس والد بمعنى الأب، وكذلك البائض، لأن الولد من الوالد 2 ، والولد والبيض في مذهبه شيء واحد. وشجرة عشة: دقيقة القضبان، متفرقتها، وتجمع عشات، قال جرير: فما شجرات عيصك في قريش ... بعشات الفروع ولا ضواح العيص: منبت خيار الشجر، وامرأة عشة، ورجل عش: دقيق عظام اليدين والرجلين، وقد عش يعش عشوشا، قال العجاج يصف نعمة البدن: أمر منها قصبا خدلجا ... لا قفرا عشا ولا مهبجا وقال آخر: لعمرك ما ليلى بورهاء عنفص ... ولا عشة خلخالها يتقعقع والرجل يعش المعروف عشا، ويسقي سجلا عشا: أي قليلا نزرا ركيكا 3 وعطية معشوشة: قليلة قال: يسقين لا عشا ولا مصردا وقال رؤبة: حجاج ما نيلك بالمعشوش 1 ... ولا جدا وبلك بالطشيش المعشوش: القليل. والمعش: المطلب، والمعس بالسين لغة فيه، قال الأخطل: معفرة لا ينكه السيف وسطها ... إذا لم يكن فيها معش لطالب 2 وأعششته عن أمره، أي أعجلته، وكذلك إذا ما تأذى بمكانك فذهب كراهة قربك. قال الفرزدق يصف قطاة: ولو تركت نامت ولكن أعشها ... أذى من قلاص كالحني المعطف الحني: القوس، وقول الفرزدق: عزفت بأعشاش وما كنت تعزف ... وأنكرت من حدراء ما كنت تعرف فأعشاش اسم موضع، وفي الحديث نهى عن تعشيش الخبز وهو أن يترك منضدا حتى يتكرج، ويقال: عشش الخبز أي تكرج. وقول العرب: عش ولا تغتر: أي عش إبلك هنا ولا تطلب أفضل منه، فلعلك لا تجده، ويفوتك هذا فتكون قد غررت بمالك. شع: شعشعت الشراب: مزجته، قال عمرو بن كلثوم: مشعشعة كأن الحص فيها ... إذا ما الماء خالطها سخينا يعني أنها ممزوجة. ويقال للثريدة الزريقاء 1 : شعشعتها بالزيت إذا سغبلتها به. والشعشع والشعشاع والشعشعان: الطويل العنق من كل شيء، قال العجاج: تحت حجاجي شذقم مضبور ... في شعشعان عنق مسجور وقال: يمطون من شعشاع 2 غير مودن أي غير قصير. وأشعت الشمس أي نشرت شعاعها وهو ما ترى كالرماح ويجمع على شعع وأشعة. وشعاع السنبل: سفاه ما دام عليه يابسا قال أبو النجم: لمة قفر كشعاع السنبل وتطاير القوم شعاعا، أي متفرقين، قال سليمان: وطار الجفاة الغواة العمون ... شعاعا تفرق أديانها أي عمون عن دينهم، ولو ضربت على حائط قصبا فطارت قطعا قلت: تفرقت شعاعا، قال: لطار شعاعا رمحه وتشققا'),
(7, 'عض', 'عض', 'عض', 'العض 1 بالأسنان والفعل منه عضضت أنا وعض يعض. وتقول: كلب عضوض وفرس عضوض. وتقول: برئت إليك من العضاض والنفار والخراط والحران والشماس. والعض: الرجل السيء الخلق، قال: 2 ولم أك عضا في الندامى ملوما والجمع أعضاض والعض: الشجر الشائك، وبنو فلان معضون أي يرعون العض. وإبل معضة: ترعاه. وشارسة ترعى الشرس، وهو ما صغر من شجر الشوك والعض: النوى المرضوخ تعلفه الإبل، قال الأعشى: من شراة الهجان صلبها العض ... ورعي الحمى وطول الحيال وطول الحيال ألا تحمل الناقة والتعضوض: ضرب من التمر (أسود، شديد الحلاوة موطنه هجر وقراها) 3'),
(8, 'ضع', 'ضع', 'ضع', '4 الضعضعة: الخضوع والتذلل. وضعضعه الهم فتضعضع، قال أبو ذؤيب: وتجلدي للشامتين أريهمو ... أني لريب الدهر لا أتضعضع وفي الحديث: ما تضعضع امرؤ لاخر يريد به عرض الدنيا إلا ذهب ثلثا دينه يعنى خضع وذل) 5'),
(9, 'عص', 'عص', 'عص', 'العصعص: أصل الذنب ويجمع عصوصا وعصاعص، قال ذو الرمة: 1 توصل منها بامريء القيس نسبة ... كما نيط في طول العسيب العصاعص صع: الصعصعة: التفريق. صعصعتهم فتصعصعوا وذهبت الإبل صعاصع أي نادة متفرقة في وجوه شتى. وصعصعة بن صوحان سيد معروف من رجال علي بن أبي طالب رضي الله عنه 2'),
(10, 'عس', 'عس', 'عس', 'عسعست السحابة أي دنت من الأرض ليلا في ظلمة وبرق. وعسعس الليل: أقبل ودنا ظلامه من الأرض، قال في عسعسة السحابة: فعسعس حتى لو يشاء إذا دنا ... كأن لنا من ناره متقبس 1 ويروي لكان والعس: نفض الليل عن أهل الريبة. (عس يعس عسا فهو عاس، وبه سمي العسس الذي يطوف للسلطان بالليل) 2 ، ويجمع العساس 3 والعسسة والأعساس. والمعس: 4 المطلب والعس: القدح الضخم ويجمع على عساس وعسسة. وعسعس: موضع. والعسعاس: من أسماء الذئب. ويقع على كل سبع إذا تعسعس وطلب الصيد بالليل. والعسوس: ناقة تضرب برجلها فتصب اللبن. (وقيل: هي التي أثيرت للحلب مشت ساعة ثم طوفت فإذا حلبت درت) 5 سع: السعسعة: الاضطراب من الكبر تسعسع الإنسان: كبر وتولى حتى يهرم، قال رؤبة: قالت ولم تأل به أن يسمعا ... يا هند ما أسرع ما تسعسعا بعد أن كان فتى سرعرعا أي شابا قويا. وعن عمر: أن الشهر قد تسعسع فلو صمنا بقيته. ويروى: تشعشع والأول أصح وأفصح.'),
(11, 'عز', 'عز', 'عز', 'العزة لله تبارك وتعالى، والله العزيز يعز من يشاء ويذل من يشاء. من اعتز بالله أعزه الله ويقال: عز الشيء، جامع 1 لكل شيء إذا قل حتى يكاد لا يوجد من قلته يعز عزة، وهو عزيز بين العزازة، وملك أعز أي عزيز، قال الفرزدق: إن الذي سمك السماء بنى لنا ... بيتا دعائمه أعز وأطول والعزاء: السنة الشديدة، قال العجاج: 2 ويعبط الكوم في العزاء إن طرقا وقيل: هي الشدة والعزوز: الشاة الضيقة الإحليل التي لا تدر بحلبة فتحلبها بجهدك 3 ويقال: قد تعززت. وعز الرجل: بلغ حد العزة ويقال: إذا عز أخوك فهن. واعتز بفلان: تشرف به والمعازة: المغالبة في العز. وقوله تعالى: وعزني في الخطاب 4 أي غلبني، ويقال أعزز علي بما أصاب فلانا أي أعظم 5 علي، ولا يقال: أعززت. والمطر يعزز الأرض تعزيزا إذا لبدها. ويقال للوابل إذا ضرب الأرض السهلة فشددها حتى لا تسوخ فيها الرجل: قد عززها وقد أعززنا فيها: أي وقعنا فيها. والعزاز: أرض صلبة ليست بذات حجارة، لا يعلوها الماء، قال الراجز: يروي العزاز أي سيل فائض 1 وقال العجاج: من الصفا القاسي 2 ويدعسن الغدر ... عزازه ويهتمرن 3 ما انهمر زع: الزعزعة: تحريك الشيء لتقلعه وتزيله. (زعزعه زعزعة فتزعزع) 4 والريح تزعزع الشجر ونحوه، قال: 5 فو الله لولا الله لا شيء 6 غيره ... لزعزع من هذا السرير جوانبه'),
(12, 'عط', 'عط', 'عط', 'العط: شق الثوب طولا أو عرضا من غير بينونة. عطعطت الثوب: شققته. وجذبت بثوبه فانعط، قال أبو النجم: كأن تحت درعها المنعط ... شطا رميت فوقه بشط إذا بدا منها الذي تغطي وقال ساعدة بن جؤية: 1 بضرب في القوانس ذي فروغ ... وطعن مثل تعطيط الرهاط 2 والعطعطة: تتابع الأصوات واختلاطها في الحرب. وهي أيضا حكاية أصوات المجان إذا غلبوا فقالوا: عيط عيط، فإذا صاحوا بها وأراد قائل أن يحكي كلامهم قال: هم يعطعطون وقد عطعطوا.'),
(13, 'طع', 'طع', 'طع', 'الطعطعة: حكاية صوت اللاطع والمتمطق إذا ألصق لسانه بالغار الأعلى، ثم لطع من طيب شيء يأكله، أو كأنه أكله، فذلك الصوت الطعطعة والطعطع: المطمئن من الأرض.'),
(14, 'عد', 'عد', 'عد', 'عددت الشيء عدا: (حسبته وأحصيته) 1 قال عز وجل: نعد لهم عدا 2 يعني أن الأنفاس تحصى إحصاء ولها عدد معلوم. وفلان في عداد الصالحين، أي يعد فيهم وعداده في بني فلان: إذا كان ديوانه معهم وعدة المرأة: أيام قروئها والعدة جماعة قلت أو كثرت. والعد مصدر كالعدد والعديد: الكثرة، ويقال: (ما أكثر عديدة 3 . وهذه الدراهم عديدة هذه: إذا كانت في العدد مثلها وإنهم ليتعددون على عشرة آلاف أي يزيدون في العدد وهم يتعادون: إذا اشتركوا فيما يعدد به بعضهم على بعض من المكارم وغير ذلك من الأشياء كلها. والعدة: ما يعد لأمر يحدث فيدخر له وأعددت الشيء: هيأته. والعد: مجتمع الماء وجمعه أعداد، وهو ما يعده الناس، فالماء عد. وموضع مجتمعه عد، قال ذو الرمة: دعت مية الأعداد واستبدلت بها ... خناطيل 4 آجال من العين 5 خذل ويقال: بنو فلان ذوو عد وفيض يغنى بهما 6 . ويقال: كان ذلك في عدان شبابه. وعدان ملكه: وهو أفضله وأكثره، قال العجاج: 1 ولي على عدان ملك محتضر 2 قال: واشتقاقه من أن ذلك كان مهيأ معدا، وقال: والملك مخبوء على عدانه 3 والعداد: اهتياج وجع اللديغ، وذلك إذا تمت له سنة مذ يوم لدغ هاج به الألم. وكأن اشتقاقه من الحساب من قبل عدد الشهور والأيام، كأن الوجع يعد ما يمضي السنة، فإذا تمت عاودت الملدوغ، ولو قيل: عادته لكان صوابا. وفي الحديث: ما زالت أكلة خيبر تعادني 4 فهذا أوان قطع أبهري ، (أي تراجعني، ويعاودني ألم سمها في أوقات معلومة قال الشاعر: يلاقي من تذكر آل سلمى ... كما يلقى السليم من العداد 5 وقيل: عداد السليم أن تعد سبعة أيام، فإن مضت رجوت له البرء. وإذا لم تمض قيل: هو في عداده) 6 دع: دعه يدعه الدع: دفع في جفوة. وفي التنزيل العزيز: فذلك الذي يدع اليتيم 7 أي يعنف به عنفا شديدا دفعا وانتهارا، أي يدفعه حقه وصلته 8 . قال: ألم أكف أهلك فقدانه ... إذا القوم في المحل دعوا اليتيما والدعدعة تحريكك جوالقا أو مكيالا ليكتنز 1 ، قال لبيد: المطعمن الجفنة المدعدعه ... والضاربون الهام تحت الخيضعه والدعدعة: أن يقال للرجل إذا عثر: دع دع أي قم، قال رؤبة: وإن هوى العاثر قلنا دعدعا ... له وعالينا بتنعيش 2 لعا والدعدعه: عدو في بطء والتواء، قال: أسعى على كل قوم كان سعيهم ... وسط العشيرة سعيا غير دعداع والدعداع: الرجل القصير. والراعي يدعدع بالغنم: إذا قال لها: داع داع 3 فإن شئت جررت ونونت، وإن شئت على توهم الوقف. والدعاعة: 4 حبة سوداء، تأكلها بنو فزارة (وتجمع الدعاع) 5 والدعاعة: نملة ذات جناحين شبهت بتلك الحبة.'),
(15, 'عت', 'عت', 'عت', 'العت: ردك القول على الانسان مرة بعد مرة. تقول: عتت قوله عليه أعته عتا. ويقال: عتته تعتيتا. وتعتت فلان في الكلام تعتتا: تردد فيه، ولم يستمر في كلامه. (والعتعت: الطويل التام من الرجال. وأنشد: لما رأتني مودنا عظيرا ... قالت أريد العتت الذفرا 1 فلا سقاها الوابل الجورا ... إلاهها ولا وقاها العرا) 2 تع: التعتعة: أن يعيا الرجل بكلامه ويتردد من عي أو حصر. ويقال: ما الذي تعتعه؟ فتقول: العي. وبه شبه ارتطام الدابة في الرمل، قال الشاعر: 3 يتعتع في الخبار إذا علاه ... ويعثر في الطريق المستقيم'),
(16, 'عظ', 'عظ', 'عظ', 'العظعظة: نكوص الجبان والتواء السهم وارتعاشه في مضيه إذا لم يقصد قال رؤبة: 1 لما رأونا عظعظت عظعاظا ... نبالهم وصدقوا الوعاظا ويقال: في أمثال العرب لا تعظني وتعظعظ 2 . أي اتعظ أنت ودع موعظتي. والعظ: الشدة في الحرب كأنه من عض الحرب إياه، ولكن لم يفرق بينهما كما يفرق بين الدعث والدعظ لاختلاف الوضعين، قال الشاعر: بصير 3 في الكريهة والعظاظ وتقول: عظته الحرب بمعني عضته. والرجل الجبان يعظعظ عن مقاتله: إذا نكص عنه، قال العجاج: وعظعظ الجبان والزئني 4 أراد الكلب الصيني.'),
(17, 'ذع', 'ذع', 'ذع', 'الذعذعة: تحريك الريح الشيء حتى تفرقه وتمزقه، يقال: قد ذعذعته، وذعذعت الريح التراب: وفرقته وسفته فتذعذع، قال النابغة: غشيت لها منازل مقويات 1 ... تذعذعها مذعذعة حنون'),
(18, 'عث', 'عث', 'عث', 'العثة: السوسة عثت 2 العثة الصوف تعثه عثا: أي أكلته والعثعث: ظهر الكثيب إذا لم يكن عليه نبات، قال القطامي: كأنها بيضة غراء 3 خد لها ... في عثعث ينبت الحوذان والعذما ثع: الثعثعة: حكاية كلام الرجل يغلب عليه الثاء والعين فهي لثغة في كلامه'),
(19, 'عر', 'عر', 'عر', 'العر والعر والعرة: الجرب، قال النابغة: فحملتني ذنب امرىء وتركتني 1 ... كذي العر يكوي غيره وهو راتع وقال الأخطل: إن العداوة تلقاها وإن قدمت 2 ... كالعر يكمن حينا ثم ينتشر والعرة اللطخ والعيب. تقول: أصابتني من فلان عرة، وإنه ليعر قومه: إذا أدخل عليهم مكروها. وعررته: أصبته بمكروه. ورجل معرور: ملطوخ بشر، قال الأخطل: نعر أناسا عرة يكرهونها ... فنحيا كراما أو نموت فنعذرا ورجل معرور: وقع العر في إبله. واستعر بهم الجرب: فشا. والعرة الشدة في الحرب والاسم منه العرار والعرار. والعر: سلح الحمام ونحوه، قال: 3 في شناظي أقن بينها ... عرة الطير كصوم النعام والمعرة: ما يصيب من الإثم. وحمار أعر: إذا كان السمن في صدره وعنقه أكثر مما في سائر جسده والتعار: السهر والتقلب على الفراش، ويقال: لا يكون ذلك إلا مع كلام وصوت، أخذ من عرار الظليم وهو صوته، يقال: عر الظليم يعر عرارا، قال لبيد: تحمل أهلها إلا عرارا ... وعزفا بعد أحياء حلال والعر والعرة الغلام والجارية والعرار والعرارة المعجلان عن وقت الفطام 1 . والمعتر: الذي يتعرض ليصيب خيرا من غير سؤال. ورجل معرور: أصابه ما لا يستقر عليه والمعرور: المغرور والعرارة: السؤدد. قال الأخطل: إن العرارة والنبوح لدارم ... والمستخف، أخوهم، الأثقالا والعرعر: شجر لا يزال أخضر، يسمى بالفارسية سروا، والعرار: نبت، قال: لها مقلتا أدماء طل 2 خميلها ... من الوحش ما تنفك ترعى عرارها ويقال: هو شجر له ورق أصفر والعرعرة: استخراج صمام القارورة، قال مهلهل: وصفراء في وكرين عرعرت رأسها ... لأبلي إذا فارقت في صاحبي العذرا والعرعرة: رأس السنام. والعراعر: الرجل الشريف: قال الكميت: قتل الملوك وسار تحت لوائه ... شجر العرا وعراعر الأقوام 3 وهو جمع العراعر وشجر العرا: الذي يبقى 4 على الجدب 5 ، ويقال: يعني به سوقة الناس. رع: شاب رعرع: حسن الاعتدال. رعرعه الله فترعرع. ويجمع الرعارع. قال لبيد: تبكي على أثر الشباب الذي مضى ... ولكن أخدان الشباب الرعارع 1 وترعرع الصبي: أي تحرك ونبت. والرعاع من الناس: الشباب ويوصف به القوم إذا عزبت أحلامهم. قال معاوية لرجل: 2 إني أخشى عليك رعاع الناس أي فراغهم.'),
(20, 'عل', 'عل', 'عل', 'العلل: الشربة الثانية، والفعل: عل القوم إبلهم يعلونها علا وعللا. والإبل تعل نفسها عللا، قال: 1 إذا ما نديمي علي ثم علي ... ثلاث زجاجات لهن هدير والأم تعلل الصبي بالمرق والخبز ليجتزيء به عن اللبن، قال لبيد: إنما يعطن من يرجو العلل والعلالة بقية اللبن، وبقية كل شيء، حتى بقية جري الفرس. قال الراجز: أحمل أمي وهي الحماله ... ترضعني الدره والعلاله أي بقية اللبن: والعلة: المرض. وصاحبها معتل. والعلة: حدث يشغل صاحبه عن وجهه. والعليل: المريض. والعل القراد الضخم، قال: 2 عل طويل الطوى كبالية السفع ... متى يلق العلو يصطعده . أي متى يلق مرتقى يرقه (والعل: الرجل الذي يزور النساء. والعل: التيس الضخم العظيم، قال: وعلهبا من التيوس علا وبنو العلات: بنو أمهات شتى لرجل واحد) 3 قال القطامي: كأن الناس كلهمو لأم ... ونحن لعلة علت ارتفاعا والعلعل: اسم الذكر، وهو رأس الرهابة أيضا، والعلعال: الذكر من القنابر. ويقال: عل أخاك: أي لعل أخاك، وهو حرف يقرب من قضاء الحاجة ويطمع، وقال العجاج: عل الاله الباعث الأثقالا ... يعقبني من جنة ظلالا ويقال: لعلني في معنى لعلي قال: 1 وأشرف من فوق البطاح لعلني ... أرى نار ليلي أو يراني بصيرها لع: قال زائدة: جاءت الإبل تلعلع في كلأ خفيف أي تتبع قليلة. وتلعلع وتلهله واحد. واللعلع: الساب نفسه. واللعلعة: بصيصه. والتلعلع: التلألؤ. والتلعلع: التكسر، قال العجاج: 2 . ومن همزنا رأسه تلعلعا واللعاع: ثمر الحشيش الذي يؤكل والكلب يتلعلع إذا دلع لسانه من العطش ورجل لعاعة: يتكلف الألحان من غير صواب وامرأة لعة: عفيفة مليحه. ولعلع: موضع قال: 3 فصدهم عن لعلع وبارق ... ضرب يشظيهم على الخنادق'),
(21, 'عن', 'عن', 'عن', 'العنة: الحظيرة (من الخشب أو الشجر تعمل للإبل أو الغنم أو الخيل تكون على باب الرجل) 1 . والجمع العنن، قال الأعشى: ترى اللحم من ذابل قد ذوى ... ورطب يرفع فوق العنن وعن لنا كذا يعن عننا وعنونا: أي ظهر أمامنا. والعنون من الدواب: المتقدمة في السير، قال النابغة: كأن الرحل شد به خنوف ... 2 من الحونات هادئة عنون ورجل عنين: وهو الذي لا يقدر أن يحبس ريح نفسه وتقول: إنه ليأخذ في كل فن وسن وعن بمعني واحد. والعنان من اللجام: السير الذي بيد الفارس الذي يقوم به رأس الفرس، ويجمع على أعنة وعنن 3 . وعنان السماء: ما عن لك منها أي: بدا لك إذا نظرت إليها، ويقال: بل عنان السماء: السحاب، الواحدة عنانة، ويجمع على أعنان وعنان، قال الشماخ: طوى ظمأها في بيضة الصيف 4 بعد ما ... جرت في عنان الشعريين الأماعز ويقال: أعنان السماء: نواحيها. وعننت الكتاب أعنه عنا وعنونت وعنويت عنونة وعنوانا. ويقال: من ترك عنعنة تميم وكشكشة ربيعة فهم الفصحاء، أما تميم فإنهم يجعلون بدل الهمزة العين، قال شاعرهم: إن الفؤاد على الذلفاء قد كمدا ... وحبها موشك عن يصدع الكبدا وربيعة تجعل مكان الكاف 1 المكسورة شيئا، قال: تضحك مني أن رأتني أحترش ... ولو حرشت لكشفت عن حرش ويقال: بل يقولون: عليكش وبكش. ويقال: بل يبدلون في كل ذلك. والعنان: الشوط. يقال: جرى عنانا وعنانين، قال: لقد شد بالخيل الهديل عليكمو ... عنانين يبدي الخيل ثم يعيدها نع: النعنعة: حكاية صوت. تقول: سمعت نعنعة وهي رنة في اللسان إذا أراد أن يقول: لع فيقول: نع والنعنع: الذكر المسترخي والنعنع: بقلة طيبة الريح وهو الفوذينج قال زائدة: الذي أعرفه: النعناع'),
(22, 'عف', 'عف', 'عف', 'العفة: الكف عما لا يحل. ورجل عفيف، يعف عفة، وقوم عفون، قال العجاج: عف 1 فلا لاص ولا ملصي أي لا قاذف ولا مقذوف وأعففته عن كذا: كففته، وامرأة عفة بينة العفاف والعفافة 2 بقية اللبن في الضرع والعفعف: 3 ثمر الطلح. فع: الفعفعة: حكاية بعض الأصوات، وبعض أصوات الجراء والسباع وشبهها، وهذيل تقول للقصاب الفعفعاني، قال صخر: 4 فنادى أخاه ثم قام بشفرة ... إليه فعال الفعفعي المناهب يقال للجزار: الفعفعي والفعفعاني.'),
(23, 'عب', 'عب', 'عب', 'العب: شرب الماء من غير مص، يعب عبا، والكباد يكون منه والعب: صوت الغرب إذا غرف الماء يعب عبا وعباب الأمر وغيره: أوله. واليعبوب: الفرس الكثير العدو والعرق، وكذلك الجدول الكثير الماء الشديد الجرية. والعبعب: ضرب من الأكسية، ناعم رقيق، وهو نعمة 1 الشباب أيضا، والعيبة: شراب يتخذ من مغافر العرفط، وهو عرق كالصمغ يكون حلوا، يضرب بمجدح حتى ينضج ثم يشرب قال زائدة: هو بالغين، وهو شراب يضرب بالمجدحة ثم يجعل في سقاء حار يوما وليلة ثم يمخض فيخرج منه الزبد. بع: البعاع: ثقل السحاب، بع السحاب والمطر بعا وبعاعا: إذا ألح بالمكان والبعاع أيضا: نبات، قال امرؤ القيس: ويأكلن من قو بعاعا وربة ... 2 تجبر بعد الأكل فهو نميص قال زائدة: بعاعا 3 لا شيء، إنما هو لعاعا وبطن قو: واد قال: والبعبعة: صوت التيس أيضا. والبعبعة: حكاية بعض الأصوات.'),
(24, 'مع', 'مع', 'مع', 'المعمعة: صوت الحريق، وصوت الشجعان في الحرب واسعارها، كل ذلك معمعة. قال: 2 سبوحا جموحا وإحضارها ... كمعمعة السعف الموقد وقال: 3 ومعمعت في وعكة ومعمعا والمعمعة: شدة الحر، وكذلك المعمعان وكان عمر 4 يتتبع اليوم المعمعاني فيصومه، قال 5 : حتى إذا معمعان الصيف هب له ... بأجة نش عنها الماء والرطب وأما مع فهو حرف يضم الشيء إلى الشيء: تقول: هذا مع ذاك 6'),
(25, 'عهق', 'عهق', 'عهق', 'العوهق: الغراب الأسود، والبعير الأسود الجسيم، ويقال: هو اسم جمل كان في الزمن الأول، ينسب إليه كرام النجائب، يقال: كان طويل القرا 3 ، قال رؤبة: جاذبت أعلاه بعنس ممشق ... خطارة مثل الفنيق المحنق 1 قرواء فيها من بنات العوهق ... ضرب وتصفيح كصفح الرونق 2 والعوهق: الثور الذي لونه آخذ 3 إلى السواد والعوهق: الخطاف الجبلي الأسود والعوهق: لون كلون السماء مشرب سوادا. قال زائدة: العوهق: الحمامة إلى الورقة، وأنشد 4 : يتبعن ورقاء كلون العوهق ... بهن جن وبها كالأولق زيافة المشي أمام الأينق ... لاحقة الرحل عتود المرفق يصف نوقا تقدمتها ناقة من نشاطها. قال عرام: العوهق من الظباء الطويلة. والعوهق: كوكب إلى جنب الفرقدين (على نسق طريقهما مما يلي القطب) 5 قال: بحيث بارى الفرقدان العوهقا ... عند مسد 6 القطب حين استوسقا والعيهقة: عيهقة النشاط والاستنان، قال: 7 إن لريعان الشباب عيهقا قال الضرير: هو بالغين وهو الجنون، وقد عاقب بين العين والغين: قال زائدة: هو بالعين المهملة 8 ) .'),
(26, 'هكع', 'هكع', 'هكع', 'يقال: هكع يهكع هكوعا: أي سكن واطمأن، قال الطرماح 1 ترى العين فيها من لدن متع الضحى ... إلى الليل في الغيضات وهي هكوع'),
(27, 'عهج', 'عهج', 'عهج', 'العوهج: ظبية حسنة اللون طويلة العنق، يقال: هي التي في حقويها خطتان سوداوان. والناقة الفتية: عوهج والنعامة: عوهج، لطول عنقها، قال العجاج: كالحبشي التف أو تسبجا ... في شملة أو ذات زف عوهجا . شبه الظليم بحبشي لف على نفسه كساء. وعن عرام: يقال للناقة الفتية وللمرأة الفتية عوهج. هجع: الهجوع: نوم الليل دون النهار، يقال: لقيته بعد هجعة. وقوم هجع وهجوع وهاجعون، وامرأة هاجعة، ونسوة هواجع وهاجعات. ورجل هجع أي أحمق غافل سريع الاستنامة. الهجعة ومثلها الجعة 2 ، عن أبي سعيد: نبيذ الشعير والذرة، وعن أبي عبيد: نبيذ الشعير.'),
(28, 'عضه', 'عضه', 'عضه', 'العضيهة: الإفك والبهتان والقول الزور. وأعضهت إعضاها أي أتيت بمنكر. وعضهت فلانا عضها، وهو أيضا من كلام الكهنة وأهل السحر والإسم العضيهة. قال الشاعر: أعوذ بربي من النافثات ... ومن عضه العاضه المعضه 1 والعضاه: من شجر الشوك كالطلح والعوسج حتى الينبوت والسدر، يقال: هي من العضاه ونحوها مما كان له أرومة تبقى على الشتاء. يقال: عضاهة واحدة، وعضة أيضا على قياس عزة، تحذف منها الهاء الأصلية كما حذفت من الشفة، ثم ردت في الشفاه. والتعضية: قطع العضاه واحتطابه. وبعير عضه: يأكل العضاه، قال: وقربوا كل جمالي عضه ... قريبة ندوته عن محمضه 2 أي بإبطه لأنه به ينهض:'),
(29, 'عزه', 'عزه', 'عزه', 'العزهاة: اللئيم من الرجال، الذي لا يخالط الناس، ولا يطرب للسماع، ولا يحب اللهو، وجمعه عزهون، تسقط منه الهاء والألف الممالة، لأنها زائدة، لا تستخلف فتحة. ولو كانت أصلية، مثل ألف مثنى لاستخلفت فتحة كقولهم: مثنون، وكل ياء ممالة مثل ياء عيسى وموسى على فعلي وفعلى فهو مضموم بلا فتحة، تقول: عبسون وموسون. وأعشى ويحيى مفتوحان في الجميع لأنهما على أفعل ويفعل فيقال: أعشون ويحيون، وقيل: هو خطأ إنما هو عشو، قال: كيفما تجعلين حرا كريما ... مثل فسل مخالف عزهاة جمع اللؤم والفجور جميعا ... واتباع الردى وأمر الدناة هزع: تقول: لقيته بعد هزيع من الليل، أي بعد مضي صدره والأهزع من السهام: ما يبقى في الكنانة وحده. وهو أردؤها، يقال: ما في الجعبة إلا سهم هزاع وأهزع، قال: وبقيت بعدهم كسهم هزاع وقال رؤبة: 1 لا تك كالرامي بغير أهزعا (يعني كمن ليس في كنانته أهزع ولا غيره. وهو الذي يتكلف الرمي ولا سهم معه) 1 والتهزع شبه التكسر والعبوس. يقال: تهزع فلان لفلان، واشتقاقه من هزيع الليل، وتلك ساعة وحشة.'),
(30, 'هطع', 'هطع', 'هطع', 'المهطع: المقبل ببصره على الشيء لا يرفعه عنه قال الله- عز وجل-: مهطعين مقنعي رؤسهم 2 وفي قول الخليل: هطع هطوعا، قال 3 : تعبدني نمر بن سعد وقد أرى ... ونمر بن سعد لي مطيع ومهطع يقول: كان ذليلا لي فصار فوقي. قال عرام: أهطع في العدو إذا أسرع وبعير مهطع: في عنقه تصويب خلقة.'),
(31, 'عهد', 'عهد', 'عهد', 'العهد: الوصية والتقدم إلى صاحبك (بشيء) 1 ، ومنه اشتق العهد الذي يكتب للولاة، ويجمع على عهود. وقد عهد إليه يعهد عهدا والعهد: الموثق وجمعه عهود والعهد: الالتقاء والإلمام يقال: ما لي عهد بكذا، وإنه لقريب العهد به والعهد: المنزل الذي لا يكاد القوم إذا انتأوا عنه رجعوا إليه قال: هل تعرف العهد المحيل أرسمه 2 والمعهد: الموضع الذي (كنت عهدته أو عهدت فيه هوى لك، أو كنت) 3 تعهد به شيئا يجمع المعاهد والعهد من المطر: أن يكون الوسمي قد مضى قبله وهو الولي، ثم يردفه الربيع بمطر يدرك آخره بلل أوله وندوته ويجمع على عهاد. وكل مطر يكون بعد مطر فهو عهاد، قال: هراقت نجوم الصيف فيها عهادها ... سجالا لنجم المربع المتقدم 4 وقال أبو النجم: ترعى السحاب العهد والغيوما وعهدت الروضة فهي معهودة أي أصابها عهاد من المطر قال الطرماح: 5 عقائل رملة نازعن منها ... دفوف أقاح معهود ودين والمعاهد: الذمي لأنه معاهد ومبايع على ما عليه من إعطاء الجزية والكف عنه. وهم أهل العهد، فإذا أسلم ذهب عنه اسم المعاهد. والعهدة: كتاب الشراء وجمعه عهد. ويقال للشيء الذي فيه فساد: أن فيه لعهدة ولما يحكم بعد وعهيدك: الذي يعاهدك وتعاهده قال نصر بن سيار 1 : فللترك أوفى من نزار بعهدها ... فلا يأمنن الغدر يوما عهيدها والتعاهد: الاحتفاظ بالشيء، وإحداث العهد به، وكذلك التعهد والاعتهاد، قال الطرماح 2 : ويضيع الذي قد أوجبه الله عليه فليس يعتهد وأعهدته: أعطيته عهدا.'),
(32, 'عده', 'عده', 'عده', 'يقال: في فلان عيدهية وعيدهة أي كبر وسوء خلق والعيده: السيء الخلق من الإبل، قال رؤبة: 3 وخاف صقع القارعات الكده ... وخبط صهميم اليدين عيده أشدق يفتر افترار الأفوه دهع: دهع الراعي بالنوق ودهدع بها: إذا قال لها دهاع أو دهداع الأول مجرور. قال زائدة: ودهدع بالسخل إذا أشلاه.'),
(33, 'عته', 'عته', 'عته', 'عته الرجل يعته عتها وعتاها 1 فهو معتوه أي مدهوش من غير مس وجنون. والتعته: التجنن. قال رؤبة: بعد لجاج لا يكاد ينتهي ... عن التصابي وعن التعته وعته به: أولع به وتعته في كذا: أسرف فيه. وكل من حاكى غيره فيما قد عته فهو عتيه بمعنى معتوه. والقوم عته في هذا. واشتقاق العتاهية والعتاهة من عته، مثل كراهية وكراهة، وفراهية وفراهة.'),
(34, 'عهر', 'عهر', 'عهر', 'العهر: الفجور، عهر إليها يعهر عهرا: أتاها ليلا للفجور ويعاهرها: يزانيها. وكل منهما عاهر، قال: لا تلجأن سرا إلى خائن ... يوما ولا تدن إلى عاهر 1 وعن رسول الله صلى الله عليه وسلم: الولد للفراش وللعاهر الحجر.'),
(35, 'هعر', 'هعر', 'هعر', 'الهيعرة: المرأة التي لا تستقر مكانها نزفا من غير عفة. يقال: عيهرت وهيعرت، وهذه الياء لازمة، إلا أنها لزمت لزوم الحرف الأصلي، لأن العين بعد الهاء لا تأتلف إلا بفضل لازم هرع: الهراع والإهراع والهرع: شدة السوق. يهرعون: يساقون ويعجلون وتهرعت الرماح إليه إذا أقبلت شوارع، قال: عند الكريهة والرماح تهرع 2 أراد: تتهرع. وأهرعوها: أشرعوها ثم مضوا بها. ورجل هرع: سريع المشي والبكاء. والهرعة: 3 القملة الكبيرة. وكذلك الهرنع والحنبج.'),
(36, 'عهل', 'عهل', 'عهل', 'العيهل: الناقة السريعة، قال: وبلدة تجهم الجهوما ... زجرت فيها عيهلا رسوما مخلصة الأنقاء أو زعوما وامرأة عيهلة: لا تستقر إنما هي تردد إقبالا وإدبارا وعيهل أيضا بغير الهاء. فأما الناقة فلا يقال إلا عيهل 1 بغير الهاء قال: ليبك أبا الجدعاء ضيف ومعيل 2 ... وأرملة تغشى الدواجن عيهل وأنشد غيره: 3 فنعم مناخ ضيفان وتجر ... وملقى زفر عيهلة بجال'),
(37, 'عله', 'عله', 'عله', 'العلهان: من تنازعه نفسه إلى الشيء، عله يعله علها، وعله الرجل: إذا اشتد جوعه، والعلهان: الجائع. وامرأة علهى، ويجمع على علاه ونسوة علاهى. وعله الرجل: إذا وقع في الملامة. والعلهان: الظليم. والعاله: النعامة. والعله: خبث النفس والحدة والانهماك، قال: بجرد يعله الداعي إليها ... متى ركب الفوارس أو متى لا 4 والعله: أذى الخمار 1 . وعلهان: رجل من بني تميم، قال جرير: جيئوا بمثل قعنب والعلهان'),
(38, 'هلع', 'هلع', 'هلع', 'الهلع: بعد الحرص. رجل هلع هلوع هلواع هلواعة: جزوع حريص. يقال: جاع فهلع أي قل صبره قال عمرو بن معديكرب الزبيدي: 2 كم من أخ لي ماجد ... بوأته بيدي لحدا ما إن جزعت ولا هلعت ... ولا يرد بكاي رشدا والهلاع: الجزع وأهلعني: أجزعني وناقة هلواعة: حديدة سريعة مذعان، قال الطرماح: 3 قد تبطنت بهلواعة ... عبر أسفار كتوم البغام والهوالع من النعام: الواحد هالع وهالعة، وهي الحديدة في مضيها. وهلوعت فمضيت: إذا عدوت فأسرعت. ويقال: ما له هلع ولا هلعة: أي ما له جدي ولا عناق. لهع: اللهع: المسترسل إلى كل شيء. وقد لهع لهعا ولهاعة فهو لهع.'),
(39, 'عهن', 'عهن', 'عهن', 'العهن: المصبوغ ألوانا من الصوف. ويقال: كل صوف عهن. قال عرام: لا يقال إلا للمصبوغ، والقطعة عهنة والجمع عهون والعهنة انكسار في قضيب من غير بينونة إذا نظرت إليه حسبته صحيحا وإذا هززته انثنى. وقضيب عاهن أي منكسر. وسمي الفقير عاهنا لانكساره. قال زائدة: لا أعرف العهنة في ذلك، ونحن نسميه الشرج، انشرجت القوس والقناة أي أصابها انكسار غير بات. قال غير الخليل: العواهن السعف الذي يقرب من لب النخلة 1 . ومال عاهن، يغدو من عند أهله ويروح عليهم. وأعطاهم من عاهن ماله أي من تلاده، قال: وأهل الأولى اللائي على عهد تبع ... على كل ذي مال غريب وعاهن'),
(40, 'هنع', 'هنع', 'هنع', 'الهنع: التواء في العنق وقصر، والنعت أهنع وهنعاء، وأكمة هنعاء أي قصيرة. وظليم أهنع ونعامة هنعاء: لالتواء 2 في عنقها حتى يقصر لذلك، كما يفعل الطائر الطويل العنق من بنات البر والماء. نهع: النهوع: تهوع لا قلس معه، نهع نهوعا.'),
(41, 'عهب', 'عهب', 'عهب', 'العيهب: البليد من الرجال الضعيف عن طلب وتره، قال: 1 حللت به وتري وأدركت ثؤرتي ... إذا ما تناسى خله كل عيهب قال أبو سعيد: أعرفه الغيهب، وربما عاقبوا. يقال: غهبت عن هذا أي سهوت عنه وجهلته. هبع: الهبوع: مشي كمشي الحمر البليدة. ويقال: الحمر كلها تهبع، وهو مشيها خاصة. ويقال: الهبوع أن يفاجئوك من كل جانب، قال 2 : فأقبلت حمرهمو هوابعا ... في السكتين تحمل الألاكعا ويقال: هو مد العنق، قال رؤبة 3 : كلفتها ذاهبة 4 هجنعا ... عوجاتهن الذابلات الهبعا الهبع: الفصيل ينتج في حمارة القيظ، والأنثى هبعة. ويقال: ما له هبع ولا ربع'),
(42, 'عهم', 'عهم', 'عهم', 'العيهامة: الناقة الماضية ويقال: هي الطويلة الضخمة الرأس، قال لبيد: 1 وردت بعيهامة حرة ... فعنت شمالا وهبت جنوبا وقال ذو الرمة: هيهات خرقاء إلا أن يقربها ... ذو العرش والشعشعانات العياهيم والذكر: عيهام. وعيهمتها: سرعتها. وقال بعضهم: عياهمة مثل عذافرة، وعياهم عذافر ... وعيهم: اسم موضع، قال لبيد: 2 بوادي السليل بين علوى وعيهم'),
(43, 'عمه', 'عمه', 'عمه', 'عمه يعمه عمها. فهو عمه وهم عمهون: إذا تردوا في الضلالة. همع: الهيمع: الموت الوحي، قال 3 : إذا بلغوا مصرهم عاجلوا ... من الموت بالهيمع الذاعط وبالغين خطأ لأن الهاء لا تجتمع مع الغين في كلمة واحدة وتهمع الرجل أي تباكى. وسحاب همع أي ماطر، قال: 4 تنكر رسمها إلا بقايا ... خلا عنها جدا همع هتون وعين همعة: سائلة الدمع. ورجل همع: لا يزال تدمع عينه وهمع الدمع هموعا أي انهمل، قال رؤبة: 1 بادرن من طل وليل أهمعا أي هامع. وذبحته ذبحا هميعا أي سريعا.'),
(44, 'خشع', 'خشع', 'خشع', 'الخشوع: رميك ببصرك إلى الأرض. وتخاشعت: تشبهت بالخاشعين ورجل متخشع متضرع. والخشوع والتخشع والتضرع واحد، قال: ومدجج يحمي الكتيبة لا يرى ... عند الكريهة ضارعا متخشعا 1 وأخشعت أي طأطأت الرأس كالمتواضع. والخشوع المعنى من الخضوع إلا أن الخضوع في البدن وهو الإقرار بالاستخدام، والخشوع في البدن والصوت والبصر 2 قال الله- عز وجل- خاشعة أبصارهم* 3 : وخشعت الأصوات للرحمن 4 أي سكنت. والخشعة: قف 5 غلبت عليه السهولة، قف خاشع وأكمة خاشعة أي ملتزمة لاطئة بالأرض. وفي الحديث: كانت الكعبة خشعة على الماء فدحيت منها الأرض 6 .'),
(45, 'خضع', 'خضع', 'خضع', 'الخضوع: الذل والاستخذاء. والتخاضع: التذلل والتقاصر والخضيعة: صوت بطن الفرس، قال 1 : كأن خضيعة بطن الجواد ... وعوعة الذئب في الفدفد والأخضع والخضعاء: الراضيان بالذل، قال العجاج: وصرت عبدا للبعوض أخضعا ... يمصني مص الصبي المرضعا والخيضعة: معركة الأبطال، قال لبيد: المطعمون الجفنة المدعدعه ... الضاربون الهام تحت الخيضعه 2 ويقال: هو غبار المعركة.'),
(46, 'خزع', 'خزع', 'خزع', 'الخزوع: تخلف الرجل عن أصحابه في مسيرهم وسميت خزاعة بذلك. لأنهم ساروا مع قومهم من سبأ أيام سيل العرم، فلما انتهوا إلى مكة تخزعوا عنهم فأقاموا وسار الآخرون إلى الشام. واسم أبيهم حارثة بن عمرو، قال حسان 1 : فلما هبطنا بطن مر تخزعت ... خزاعة عنا في الحلول الكراكر'),
(47, 'خدع', 'خدع', 'خدع', 'خدعة خدعا وخديعة، والخدعة المرة الواحدة والانخداع: الرضا بالخدع والتخادع: التشبه بالمخدوع. والخدعة: الرجل المخدوع. ويقال: هو الخيدع أيضا 1 . والخدعة: قبيلة من تميم، قال: 2 من عاذري من عشيرة ظلموا ... يا قوم من عاذري من الخدعة 3 والمخدع: الذي خدع مرارا في الحرب وفي غيرها، قال أبو ذؤيب: فتنازعا وتواقفت خيلاهما ... وكلاهما بطل النزاع مخدع وغول خيدع، وطريق خيدع: مخالف للقصد، جائر عن وجهه لا يفطن له، وخادع أيضا، قال الطرماح: خادعة المسلك أرصادها ... تمسي وكونا فوق ارامها والإخداع: إخفاء الشيء، وبه سميت الخزانة مخدعا. والأخدعان: عرقان في اللبتين لأنهما خفيا وبطنا ويجمع على أخادع، قال 4 : وكنا إذا الجبار صعر خده ... ضربناه حتى تستقيم الأخادع ورجل مخدوع: قطع أخدعاه.'),
(48, 'ختع', 'ختع', 'ختع', 'الختوع: ركوب الظلمة والمضي 1 فيها على القصد بالليل كما يختع الدليل بالقوم تحت الليل، قال رؤبة: أعيت أدلاء الفلاة الختعا والختعة: النمرة الأنثي. والختيعة: شيء يتخذ من الأدم يغشي بها الإبهام لرمي السهام.'),
(49, 'خذع', 'خذع', 'خذع', 'الخذع: تحزير اللحم في مواضع من غير أن يكون قطعا في عظم أو صلابة، إنما هو كما يخذع القرع بالسكين والخذيعة: طعام يتخذ من اللحم بالشام. ومن روى بيت أبي ذؤيب: وكلاهما بطل اللقاء مخدع 2 يقول: إنه مقطع بالسيف في مواضع.'),
(50, 'خرع', 'خرع', 'خرع', 'الخرع: رخاوة في كل شيء. ورجل خرع العظم أي رخو العظم. قال: لا خرع العظم ولا موصما 1 ومنه اشتق اسم الخروع، وهي شجرة تحمل. حبا كأنه بيض العصافير يسمى سمسما هنديا. والخريعة: المرأة التي لا تمنع يد لامس فجورا، وقد انخرعت له ضعفا ولينا. وانخرعت أعضاء البعير: أي زالت عن مواضعها. وتخرع الرجل: انكسر وضعف. والخرع: شقك الثوب. والتخرع: التشقق والتفتت المفسد، قال العجاج 2 : ومن غمزنا رأسه تخرعا أي تفتت من شدة الغمز. واخترع فلان باطلا وكذبا أي اشتقه والخريع. مشفر البعير المدلى المشقق وجمعه خرائع، قال الطرماح: خريع النعو مضطرب النواحي ... كأخلاق الغريفة ذا 3 غضون');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(51, 'خلع', 'خلع', 'خلع', 'الخلع: اسم خلع رداءه وخفه وخفة وقيده 1 وامرأته، قال: وكل أناس قاربوا قيد فحلهم ... ونحن خلعنا قيده فهو سارب والخلع كالنزع إلا أن في الخلع مهلة. واختلعت المرأة اختلاعا وخلعة. وخلع العذار: أي الرسن فعدا على الناس بالشر لا طالب له فهو مخلوع الرسن، قال: وأخرى تكادر 2 مخلوعة ... على الناس في الشر أرسانها والخلعة: كل ثوب تخلعه عنك. ويقال: هو ما كان على الإنسان من ثيابه تاما. والخلعة: أجود مال الرجل، يقال: أخذت خلعة ماله أي خيرت فيها فأخذت الأجود فالأجود منها. والخليع: اسم الولد الذي يخلعه أبوه مخافة أن يجني عليه، فيقول: هذا ابني قد خلعته فإن جر 3 لم أضمن، وإن جر عليه أطلب، فلا يؤخذ بعد ذلك بجريرته، كانوا يفعلونه في الجاهلية، وهو المخلوع أيضا، والجمع الخلعاء، ومنه يسمى كل شاطر وشاطرة خليعا وخليعة، وفعله اللازم خلع خلاعة أي صار خليعا. والخليع: الصياد لانفراده عن الناس، قال امرؤ القيس: وواد كجوف العير قفر قطعته ... به الذئب يعوي كالخليع المعيل 4 ويقال: الخليع هاهنا الصياد، ويقال: هو هاهنا الشاطر: والمخلع من الناس: الذي كأن به هبة أو مسا 1 ورجل مخلع: ضعيف رخو. وفي الحديث: خلع ربقة الإسلام من عنقه إذا ضيع ما أعطى من العهد وخرج على الناس. والخولع: فزع يبقى في الفؤاد حتى يكاد يعتري صاحبه الوسواس منه. وقيل: الضعف والفزع، قال جرير: لا يعجبنك أن ترى لمجاشع ... جلد الرجال وفي الفؤاد الخولع والمتخلع 2 : الذي يهز منكبيه إذا مشى ويشير بيديه. والمخلوع الفؤاد: الذي انخلع فؤاده من فزع. والخلع: زوال في المفاصل من غير بينونة، يقال: أصابه خلع في يده ورجله والخلع: القديد يشوى فيجعل في وعاء بإهالته. والخالع: البسرة إذا نضجت كلها. والخالع: السنبل إذا سفا. وخلع الزرع خلاعة. والمخلع من الشعر: ضرب من البسيط يحذف من أجزائه كما قال الأسود بن يعفر: 3 ماذا وقوفي على رسم عفا ... مخلولق دارس مستعجم 4 قلت للخليل: ماذا تقول في المخلع؟ قال: المخلع من العروض ضرب من البسيط وأورده. والخليع: القدح الذي يفوز أولا والجمع أخلعة 5 والخليع من أسماء الغول، قال عرام: هي الخلوع لأنها تخلع قلوب الناس ولم نعرف الخليع 6 . خعل: الخيلع والخيعل مقلوب 7 ، وهو من الثياب غير منصوح الفرجين تلبسه العروس وجمعه خياعل، قال 1 السالك الثغرة اليقظان كالئها ... مشي الهلوك عليها الخيعل الفضل (وقيل: الخيعل قميص لا كمين له) 2 . والخيعل والخيلع من أسماء الذئب.'),
(52, 'خنع', 'خنع', 'خنع', 'الخنع: ضرب من الفجور. خنع إليها: أتاها ليلا للفجور. ووقفت منه على خنعة: أي فجرة وخنع فلان لفلان أي ضرع إليه إذا لم يكن صاحبه أهلا لذلك. وأخنعته الحاجة إليه: أخضعته، والاسم الخنعة. وفي الحديث: أخنع الأسماء إلى الله من تسمى باسم ملك الأملاك أي أذلها، قال الأعشي: هم الخضارم إن غابوا وإن شهدوا ... ولا يرون إلى جاراتهم خنعا والخنع جمع خنوع. أي لا يخضعون لهن بالقول، بل يغازلونهن 1 . وخناعة: قبيلة 2 نخع: النخاع والنخاع والنخاع، ثلاث لغات: عرق أبيض مستبطن فقار العنق متصل بالدماغ، قال: ألا ذهب الخداع فلا خداعا ... ة أبدى السيف عن طبق نخاعا (يقول: مضى السيف في قطع طبق العنق فبدا النخاع) 3 . ونخعت الشاة: قطعت نخاعها. ومنه يقال: تنخع الرجل: إذا رمى بنخاعته 4 ، (وهي نخامته. وفي الحديث: النخاعة في المسجد خطيئة. قال: هي البزقة التي تخرج من أصل الفم مما يلي النخاع) 1 والمنخع: مفصل الفهقة بين العنق والرأس من باطن. وفي الحديث: لا تنخعوا الذبيحة، ولا تفرسوا، ودعوا الذبيحة حتى تجب فإذا وجبت فكلوا. الفرس: كسر العنق. والنخع: أن يبلغ القطع إلى النخاع. وفي الحديث: أنخع الأسماء إلى الله- أي أقتله من تسمى بملك الملوك.'),
(53, 'خفع', 'خفع', 'خفع', '1 خفع الرجل: إذا دير به فسقط، وانخفعت كبده من الجوع، وانخفعت رئته إذا انشقت من داء، قال جرير: 2 يمشون قد نفخ الخزير بطونهم ... وغدوا وضيف بني عقال يخفع أي تحترق كبده من الجوع. والخوفع: الذي به اكتئاب ووجوم شبه النعاس.'),
(54, 'خبع', 'خبع', 'خبع', 'الخبع: الخبء في لغة تميم، يجعلون بدل الهمزة عينا 3 وخبع الصبي خبوعا: أي فحم من شدة البكاء حتى انقطع نفسه. بخع: بخع نفسه: قتلها غيظا من شدة الوجد، قال ذو الرمة: 4 ألا أيهذا الباخع الوجد نفسه . بخعت به بخوعا أي أقررت به على نفسي، وبخع بالطاعة: أي أذعن وانقاد وسلس.'),
(55, 'خمع', 'خمع', 'خمع', 'الخوامع: الضباع لأنها تخمع خموعا وخمعا إذا مشت وكل من خمع في مشيته كأن به عرجا فهو خامع. والخماع اسم لذلك الفعل. قال عرام: الخميع والخموع: المرأة الفاجرة وخماعة 1 : اسم امرأة خعم: الخيعامة: نعت سوء للرجل'),
(56, 'عشق', 'عشق', 'عشق', 'عشقها عشقا والاسم العشق، قال رؤبة: فعف عن إسرارها بعد العسق 2 ... ولم يضعها بين فرك وعشق وفلان عشيق فلانة، وفلانة عشيقته، وهؤلاء عشاق وعشاشيق 3 فلانة.'),
(57, 'قعش', 'قعش', 'قعش', 'القعش: عطف الشيء كالقعص. قعشت العصا من الشجرة إذا عطفت رءوسها إليك. والقعوش من مراكب النساء، قال رؤبة: جدباء فكت أسر القعوش يصف سنة جدباء باردة أحوجت إلى أن حلوا قعوشهم فاستوقدوا حطبها.'),
(58, 'قشع', 'قشع', 'قشع', 'القشع: بيت من أدم. وربما اتخذ من جلود الإبل صوانا 1 للمتاع، ويجمع على قشوع، قال متمم: إذا القشع من برد الشتاء تقعقعا والقشعة: قطعة سحاب تبقى في نواحي الأفق بعد ما ينقشع الغيم. وكل شيء يغشى وجه ثم يذهب فقد انقشع وانقشع الهم عن القلب. وانقشع البلاء والبرد: أي ذهب، وقشعت الريح السحاب فتقشع وانقشع: أذهبته فذهب، والقشع: السحاب الذاهب عن وجه السماء. وأقشع القوم عنه: أي تفرقوا بعد اجتماعهم عليه، والقشعة العجوز التي قد انقشع عنها لحمها، قال الشاعر 2 لا تجتوي القشعة الخرقاء مبناها ... الناس ناس وأرض الله سراها (قوله: مبناها: حيث تنبت القشعة. والاجتواء: ألا يوافقك المكان ولا هواؤه) 3 شقع: شقع في الإناء: كرع فيه. ومثله قبع وقمع ومقع، وكله من شدة الشرب.'),
(59, 'قعض', 'قعض', 'قعض', 'القعض: عطفك رأس الخشبة كعطفك عروش الكرم والهودج، 1 يقال: قعضها فانقعضت أي حناها فانحنت، قال رؤبة يخاطب امرأته: 2 إما تري دهري حناني خفضا ... أطر الصناعين العريش القعضا فقد أفدي مرجما منقضا. قضع: قضاعة: اسم كلب الماء والقضع: القهر. وإن قضاعة قهروا قوما فسموا بذلك، (وقيل: هو اسم رجل سمي بذلك لانقضاعه عن أمه 3 . وقيل: هو من القهر لأنه قهر قوما فسمي به. وهو أبو حي من اليمن واسمه قضاعة بن مالك بن حمير بن سبأ. وتزعم نسابة مضر أنه قضاعة بن معد بن عدنان. قال: وكانوا أشداء على أعدائهم في الحروب ونحوها) 4'),
(60, 'عقص', 'عقص', 'عقص', 'العقص: التواء في قرن الشاة والتيس، ويستعمل في كل ذي قرن، يقال: شاة عقصاء أي ملتوية القرن. وهو أيضا دخول الثنايا في الفم. والنعت أعقص وعقصاء. ويجمع على عقص. والعقص أخذك خصلة من شعر فتلويها ثم تعقدها حتى يبقى فيها التواء. ثم ترسلها، فكل خصلة عقيصة، وجمعها عقائص وعقاص. قال امرؤ القيس: غدائره مستشزرات إلى العلا ... تضل العقاص في مثنى ومرسل 1 (والمعقص: سهم ينكسر نصله فيبقى سنخه في السهم فيخرج ويضرب حتى يطول ويرد إلى موطنه فلا يسد مسده لأنه طول ودقق، قال الأعشى: ولو كنتم نخلا لكنتم جرامة ... ولو كنتم نبلا لكنتم معاقصا) 2'),
(61, 'قعص', 'قعص', 'قعص', 'القعص: القتل. ضربه فقعصه وأقعصه: أي قتله في مكانه، قال يصف الحرب: فأقعصتهم وحكت بركها بهم ... وأعطت النهب هيان بن بيان ومات فلان قعصا أي أصابته ضربة أو رمية 3 فمات مكانه والقعاص: داء يأخذ في الصدر كأنه يكسر العنق، ويقال: هو القعاس، واشتقاقه من القعس وهو انتصاب النحر وانحناؤه نحو الظهر، وهو أقعس، والأنثى قعساء. والقعاص أيضا داء يأخذ الدواب فيسيل من أنوفها شيء، قعصت فهي مقعوصة وشاة قعوص: تضرب حالبها وتمنع الدرة. ويقال: ما كنت قعوصا، ولقد قعصت قعصا، قال الشاعر: قعوص شري درها غير منزل'),
(62, 'قصع', 'قصع', 'قصع', 'القصع: ابتلاع جرع الماء. والبعير يقصع جرته إذا ردها إلى جوفه قال: ولم يقصعنه نغب 1 والماء يقصع العطش: أي يقتله وقصع صؤابا أو قملة: أي قتلها بين ظفريه. وقصعت رأس الصبي: ضربته ببسط الكف على هامته، وقصع الله شبابه: أي ذهب به وقتله. وغلام قصع وقصيع (إذا كان قميئا لا يشب) 2 ، وقد قصع يقصع قصاعة. (والجارية بالهاء) 3 إذا كانت قميئا (لا تشب ولا تزداد) 4 . والقصاع جمع القصعة. والقاصعاء: جحر اليربوع الأول الذي يدخل فيه، اسم جامع له. ولا تجوز السين في الكلمة التي جاءت القاف فيها قبل الصاد إلا أن تكون الكلمة سينية لا لغة فيها للصاد.'),
(63, 'صعق', 'صعق', 'صعق', 'الصعاق: الصوت الشديد للثور والحمار، صعق صعاقا، قال رؤبة: صعق ذبانه في غيطل 5 (أي يموت الذباب من شدة نهيقه) 6 إذا دنا منه. قال رؤبة يصف حمارا وأتانه: ينصاع من حيلة ضم مدهق 7 ... إذا تتلاهن صلصال الصعق وحمار صعق الصوت أي شديده. والصعاق: الشديد الصوت. والصاعقة: صيحة العذاب. والصاعقة: الوقع الشديد من صوت الرعد، يسقط معه قطعة من نار يقال: إنها من صوت الملك. ويجمع صواعق. والصعق: المغشي عليه. صعق صعقا: غشي عليه من صوت يسمعه أو حس أو نحوه. وصعق صعقا: مات. صقع: الصقع: الضرب ببسط الكف، صقعت رأسه بيدي، والسين لغة فيه. والديك يصقع بصوته، والسين جائز. وخطيب مصقع: بليغ، وبالسين أحسن. والصقيع: الجليد يصقع النبات، وبالسين قبيح. والصوقعة من العمامة والرداء ونحوهما: الموضع الذي يلي الرأس، وهو أسرع وسخا، وبالسين أجود. والصوقعة وقبة الثريد، وبالسين أحسن، والصقع: ناحية من الأرض أو البيت، والصاد قبيح، والصقع: ما تحت الركية وحولها من نواحيها، والجمع: الأصقع. والأصقع من العقبان والطير: ما كان على رأسه بياض باللغتين معا. وان أردت الأصقع نعتا فجمعه على صقع. قال الحارث بن وعلة الجرمي: خدارية صقعاء لثق رشها ... بطخفة يوم ذو أهاضيب ماطر والأصقع: طوير كأنه عصفور في ريشه خضرة، ورأسه أبيض يكون بقرب الماء. والجمع صقع وأصاقع. قال الخليل 1 : كل صاد قبل القاف إن شئت جعلتها سينا لا تبالي متصلة كانت بالقاف أو منفصلة، بعد أن تكونا في كلمة واحدة، إلا أن الصاد في بعض الأحيان أحسن، والسين في مواطن أخرى أجود.'),
(64, 'عسق', 'عسق', 'عسق', 'العسق: لزق الشيء بالشيء عسق بها عسقا. وعسقت الناقة بالفحل: أربت به ولازمته، قال رؤبة: فعف عن إسرارها بعد العسق 1 ويقال: في خلقه عسر وعسق أي التواء يصفه بسوء الخلق وسوء المعاملة. والعسق العرجون الرديء أزدية 2'),
(65, 'قعس', 'قعس', 'قعس', 'القعس: نقيض الحدب. قعس قعسا فهو أقعس، والأنثى قعساء، وجمعه قعس. والقعساء من النمل: الرافعة صدرها وذنبها، ويجمع قعسا، (وقعساوات على غلبة الصفة) 3 . القعاس: التواء يأخذ في العنق من ريح كأنما يكسره إلى الوراء ورجل أقعس: أي منيع. وعز أقعس: ثابت ممتنع، قال العجاج: 4 والعزة القعساء للأعز وقال: تقاعس العز بنا فاقعنسسا والاقعناس: التقعس. شبع السين بالسين للتوكيد. وتقاعس فلان: إذا لم ينفذ ولم يمض لما كلف. والقوعس: الغليظ العنق الشديد الظهر من كل شيء، سقع: السقع مستعمل في الصقع 1 في بابه.'),
(66, 'عزق', 'عزق', 'عزق', 'المعزقة: المسحاة، قال ذو الرمة: إذا رعشت أيديكم بالمعازق 1 والمعزق: المر من الحديد ونحوه مما يحفر به، ويجمع معازق. والعزق علاج في عسر. رجل عزق ومتعزق وعزوق: فيه شدة وبخل وعسر في خلقه. والعزوق: 2 حمل الفستق في السنة التي لا يعقد لبه وهو دباغ وعزوقته: تقبضه. وأنشد: ما يصنع العنز بذي عزوق ... يثيبه العزوق في جلده 3 وذلك لأنه يدبغ جلده بالعزوق'),
(67, 'قزع', 'قزع', 'قزع', 'القزع: قطع السحاب، الواحدة قزعة وهي رقيقة الظل 4 مر تحت السحاب الكثير. قال: مقانب بعضها يبرى لبعض ... كأن زهاءها قزع الظلال والقزع من الصوف: ما تناتف في الربيع، ورجل مقزع: ليس على رأسه إلا شعيرات تتطاير في الريح، قال ذو الرمة: مقزع أطلس الأطمار ليس له ... إلا الضراء وإلا صيدها نشب والمقزع من الخيل: ما نتفت ناصيته حتى ترق، وأنشد: نزائع للصريح وأعوجي ... من الخيل المقزعة العجال وسهم مقزع خفف ريشه والقزع: السهم الذي خف ريشه. وكبش أقزع، وشاة قزعاء: سقط بعض صوفهما. والفرس يقزع بفارسه: إذا مر يسرع به. وفي الحديث 1 : يخرج رجل في آخر الزمان يسمى أمير الغصب له أصحاب منحون مطرودون مقصون عن أبواب السلطان يأتونه من كل أوب، كأنهم قزع الخريف، يورثهم الله مشارق الأرض ومغاربها. وقال في وصف السحاب: وهاجت الريح بطراد القزع ونهى عن القزع وهو أخذ بعض الشعر وترك بعضه'),
(68, 'زعق', 'زعق', 'زعق', 'الزعاق: ماء مر غليظ. وأزعق القوم: أي حفروا فهجموا على ماء زعاق. قال علي بن أبي طالب: دونكها مترعة دهاقا ... كأسا زعاقا مزجت زعاقا 2 وبئر زعقة: ملحة الماء. وطعام زعاق: مزعوق: أي كثر ملحه فأمر. والزعقوقة: فرخ القبج، ويجمع الزعاقيق، وأنشد: كأن الزعاقيق والحيقطان ... يبادرن في المنزل الضيونا (ويقال: أرض مزعوقة ومذعوقة وممعوقة ومبعوقة ومشحوذة ومسحورة ومسنية بمعنى واحد أي أصابها مطر وابل شديد. وزعقت الريح التراب: أثارته) 3 . زقع: 1 زقع زقعا وزقاعا لأشد ضراط الحمار. قال زائدة 2 : أعرفه صقع بضرطة لها رطبة منتشرة ذات صوت. والزقاقيع: فراخ القبج 3'),
(69, 'قطع', 'قطع', 'قطع', 'قطعته قطعا ومقطعا فانقطع، وقطعت النهر قطوعا. والطير تقطع في طيرانها قطوعا، وهن قواطع أي ذواهب ورواجع. وقطع بفلان: انقطع رجاؤه. ورجل منقطع به أي انقطع به السفر دون طية. ويقال قطعه. ومنقطع كل شيء حيث تنتهي غايته. والقطعة: طائفة من كل شيء والجمع القطعات والقطع والأقطاع 1 . والقطعة فعلة واحدة. وقال بعضهم: القطعة 2 بمعنى القطعة. وقال أعرابي: غلبني فلان على قطعة أرضي. والأقطع: المقطوع اليد والجمع قطعان، والقياس أن تقول: قطع لأن جمع أفعل فعل إلا قليلا، ولكنهم يقولون: قطع الرجل لأنه فعل به. ويقال: ما كان قطيع اللسان، ولقد قطع قطاعة: إذا ذهبت السلاطة منه. وأقطع الوالي قطيعة أي: طائفة من أرض الخراج فاستقطعته. وأقطعني نهرا ونحوه، وأقطعت فلانا: أي جاوزت به نهرا ونحوه وأقطعني قضبانا: أذن لي قطعها. ويسمى القضيب الذي تبرى منه السهام القطع، ويجمع على قطعان 3 وأقطع، قال أبو ذؤيب: وتميمة من قابض متلبب ... في كفه جشأ أجش وأقطع 4 يعني بالجشأ الأجش: القوس، والأقطع: السهام، والفرس الجواد يقطع الخيل تقطيعا إذا خلفها ومضى، قال أبو الخشناء: 5 يقطعهن بتقريبه ... ويأوي إلى حضر ملهب ويقال للأرنب السريعة مقطعة النياط، كأنها تقطع عرقا في بطنها من العدو ومن قال: النياط بعد المفازة فهي تقطعه أي تجاوزه (ويقال لها أيضا مقطعة الأسحار ومقطعة) 1 السحور، جمع السحر وهي الرئة. والتقطيع: مغس تجده في الأمعاء. قال عرام: مغص لا غير. والمغص: أن تجد وجعا والتواء في الأمعاء، فإذا كان الوجع معه (شديدا فهو التقطيع. وجاءت الخيل مقطوطعات: أي سراعا، بعضها في إثر بعض. وفلان منقطع القرين في الكرم والسخاء إذا لم يكن له مثل، وكذلك منقطع العقال في الشر والخبث أي لا زاجر له، قال الشماخ: رأيت عرابة الأوسي يسمو 2 ... إلى الخيرات منقطع القرين والمنقطع: الشيء نفسه، وانقطع الشيء: ذهب وقته، ومنه قولهم: انقطع البرد والحر. وأقطع: ضعف عن النكاح. وانقطع بالرجل والبعير: كلا، وقطع بفلان فهو مقطوع به. وانقطع به فهو منقطع به: إذا عجز عن سفره من نفقة ذهبت أو قامت عليه راحلته، أو أتاه أمر لا يقدر أن يتحرك معه. وقيل: هو إذا كان مسافرا فأقطع به وعطبت راحلته ونفذ زاده وماله، وتقول العرب: فلان قطيع القيام أي) 3 منقطع، إذا أراد القيام انقطع من ثقل أو سمنة، وربما كان من شدة ضعفه، قال: رخيم الكلام قطيع القيام ... أمسى الفؤاد بها فاتنا 4 أي مفتونا، كقولك: طريق قاصد سابل أي مقصور مسبول، ومنه قوله تعالى: في عيشة راضية 1 * أي مرضية. ومنه قول النابغة: كليني لهم يا أميمة ناصب ... وليل أقاسيه بطيء الكواكب أي منصب. ورخيم وقطيع فعيل في موضع مفعول، يستوي فيه الذكر والأنثى، تقول: رجل قتيل وامرأة قتيل. وربما خالف شاذا أو نادرا بعض العرب 2 والإستقطاع: كلمة جامعة (لمعاني القطع) 3 . وتقول أقطعني قطيعة وثوبا ونهرا. تقول في هذل كله استقطعته. وأقطع فلان من مال فلان طائفة ونحوها من كل شيء أي أخذ منه شيئا أو ذهب ببعضه وقطع الرجل بحبل: أي اختنق ومنه قوله [تعالى] : ثم ليقطع 4 أي ليختنق. وقاطع فلان وفلان سيفيهما: أي نظرا أيهما أقطع. والمقطع: كل شيء يقطع به ورجل مقطاع: لا يثبت على مؤاخاة أخ. وهذا شيء حسن التقطيع أي القد. ويقال لقاطع الرحم: إنه لقطع وقطعة. من قطع رحمه إذا هجرها. وبنو قطيعة: حي من العرب، والنسبة إليهم قطعي، وبنوا قطعة: بطن أيضا. والقطعة في طيء كالعنعنة في تميم وهي: أن يقول: يا أبا الحكا وهو يريد يا أبا الحكم، فيقطع كلامه عن إبانة بقية الكلمة. ولبن قاطع: 5 وقطعت عليه العذاب تقطيعا: أي لونته وجزأته عليه. والقطيع: طائفة من الغنم والنعم ونحوها. ويجمع على قطعان وقطاع وأقطاع، (وجمع الأقطاع أقاطيع) 1 . والقطع: نصل صغير يجعل في السهم وجمعه أقطاع. والقطيع: السوط المقطوع طرفه، قال: لما علاني بالقطيع علوته ... بأبيض عضب ذي سفاسق مفصل والقطيع: شبه النظير. تقول: (هذا قطيع هذا أي شبهه في خلقه وقده) 2 . والأقطوعة: علامة تبعث بها الجارية إلى الجارية أنها صارمتها، قال: 3 وقالت بجاريتيها اذهبا- ... إليه بأقطوعة إذ هجر وما إن هجرتك من جفوة ... ولكن أخاف وشاة الحضر وانقطاع كل شيء: ذهاب وقته. والهجر مقطعة للود: أي سبب قطعه. ومقطع الحق: موضع التقاء الحكم فيه، وهو ما يفصل الحق من الباطل، قال زهير: وإن الحق مقطعه ثلاث ... شهود أو يمين أو جلاء 4 ينجلي: ينكشف. ولصوص قطاع، وقطع (وهذه تخفيف تلك) 5 والمقطع: ما يقطع به الأديم والثوب ونحوه. والمقطعات من الثياب: شبه الجباب ونحوها من الخز والبز والألوان. ومثله من الشعر الأراحيز، ومن كل شيء. قال غير الخليل: هي الثياب المختلفة الألوان على بدن واحد، وتحتها ثوب على لون اخر. ويقال للرجل الكثير الاختراق قطيع وقطعات الشجر: أطراف أبنها إذا قطعت أغصانها. (ومقطعة السحر من الأرانب) 6 : هنات صغار من أسرع الأرانب. قال: مرطي مقطعة سحور بغاتها ... من سوسها التاببر مهما تطلب 1 والقطع من الثياب: ضرب منها على صنعة الزرابي الحيرية لأن وشيها مقطوع وتجمع على قطوع، قال 2 أتتك العيس تنفخ في براها ... تكشف عن مناكبها القطوع والقطع: بهر يأخذ الفرس فهو مقطوع، وبه قطع، قال أبو جندب: وإني إذا آنست بالصبح مقبلا ... يعاودني قطع جواه ثقيل ورواية عرام: وإني إذا ما آنس الناس مقبلا ... يعاودني قطع علي ثقيل وكذلك إن انقطع عرق في بطنه أو مشحمه، فهو مقطوع. والقطع: طائفة من الليل، قال: افتحي الباب فانظري في النجوم ... كم علينا من قطع ليل بهيم ويجوز قطع، لغتان. وفي التنزيل: قطعا من الليل مظلما 3 وقرىء: قطعا. قعط: يقال: اقتعط بالعمامة: إذا اعتم بها، ولم يدرها تحت الحنك. قال عرام: القعط: شبه العصابة. والمقعطة: ما تعصب به رأسك. ويقال: قطعت العمامة: في معنى اقتعطتها. وأنكر مبتكر قعطت بمعنى اقتعطت.'),
(70, 'عقد', 'عقد', 'عقد', 'الأعقاد والعقود: جماعة عقد البناء. وعقده تعقيدا أي جعل له عقودا. وعقدت الحبل عقدا، ونحوه فانعقد والعقدة: موضع العقد من النظام ونحوه. وتعقد السحاب: إذا صار كأنه عقد مضروب مبني. وأعقدت العسل فانعقد، قال: 1 كأن ربا سال بعد الإعقاد (وعقد اليمين: أن يحلف 2 يمينا لا لغو فيها ولا استثناء فيجب عليه الوفاء بها. (وعقدة كل شيء: إبرامه) 3 . وعقدة النكاح: وجوبه. وعقدة البيع: وجوبه والعقدة: الضيعة ويجمع على عقد. (واعتقدت مالا) 4 : جمعته. وعقد قلبه على شيء: لم ينزع عنه. واليعقيد: طعام يعقد بالعسل. وظبية عاقد: تعقد طرف ذنبها. ويقال: بل العواقد: عواطف ثواني الأعطاف، قال النابغة: 5 ويضربن بالأيدي وراء براغز ... حسان الوجوه كالظباء العواقد واعتقد الشيء: صلب. واعتقد الإخاء والمودة بينهما: أي ثبت والأعقد من التيوس والظباء: الذي في قرنه عقدة ورجل أعقد، وقد عقد يعقد عقدا أي في لسانه عقدة) 6 وغلظ في وسطه فهو عسر الكلام، قال الله- عز وجل-. واحلل عقدة من لساني 7 . والعقد مثل العهد، عاقدته عقدا مثل عاهدته عهدا. وعقد القلادة: ما يكون طوار العنق غير متدل. والمعاقد: (مواضع العقد من النظام) 1 ونحوه قال: 2 منه معاقد سلكه لم توصل والعقد من الرمل: ما تراكم واجتمع وجمعه أعقاد. ومن قال: عقدة فإنه يجمع على عقدات. قال 3 : بين النهار وبين الليل من عقد ... على جوانبه الأسباط والهدب والعقدان: ضرب من التمر. قال زائدة سمعت به وليس من لغتي، وأعرف القعقعان من التمر. وجمل عقد ممر الخلق، قال النابغة: الديوان. فكيف مزارها إلا بعقد ... ممر ليس ينقضه الخؤون وقال آخر: موترة الأنساء معقودة القرى ... زفونا إذا كل العتاق المراسل 4 والعاقد: الناقة التي تعقد بذنبها عند اللقاح فيعلم أنها قد حملت.'),
(71, 'عدق', 'عدق', 'عدق', 'العودق على تقدير فوعل، وهي العودقة أيضا: حديدة لها ثلاث شعب يستخرج بها الدلو من البئر، وهو الخطاف. والرجل يعدق بيده (يدخل يده) 1 في نواحي الحوض 2 كأنه يطلب شيئا في الماء ولا يراه. يقال: اعدق بيدك. قال: زائدة: أقول: يعودق بيده في نواحي البئر لا يعدق.'),
(72, 'قعد', 'قعد', 'قعد', 'قعد يقعد قعودا (خلاف قام) 3 والقعدة: المرة الواحدة. والقعد: القوم الذين لا ديوان لهم. والمقعد والمقعدة اللذان لا يطيقان المشي. والمقعدات: فراخ القطا والنسر قبل أن تنهض للطيران 4 ، قال ذو الرمة: إلى مقعدات تطرح الريح بالضحى ... عليهن رفضا من حصاد القلاقل القلاقل: أول ما ينبت من البقل، وأول ما تدوي له خشخشة إذا حركته الريح. يقول: الريح تطرح عليهن كسارات القلاقل. والمقعدات أيضا الضفادع. والمقعد: الثدي الناهد على النحر، قال النابغة: والبطن ذو عكن لطيف طيه ... والاتب تنفجه بثدي مقعد والقعدة ضرب من القعود، يقال: قعد قعد الدب وقعدة الرجل: مقدار ما أخذ من الأرض، يقال: أتانا بثريدة مثل قعدة الرجل. و [ذو] القعدة: اسم شهر كانت العرب تقعد فيه ثم تحج في ذي الحجة. والقعدة: ما يقتعده الرجل من الدواب للركوب خاصة. والقعود والقعودة من الإبل: ما يقتعدها الراعي فيركبها ويحمل عليها زاده. ويجمع على القعدان. وقعيدتك: امرأتك، قال الأسعر الجعفي: لكن قعيدة بيننا مجفوة ... باد جناجن صدرها ولها عنا 1 وقال آخر: إنني شيخ كبير ... ليس في بيتي قعيده (ومثل قعيدة قعاد والجمع قعائد. قال عبد الله بن أوفى الخزاعي في امرأته: منجدة مثل كلب الهراش ... إذا هجع الناس لم تهجع فليست تباركه محرما ... ولو حف بالأسل المشرع فبئس قعاد الفتى وحده ... وبئست موفية الأربع 2 وقعيدك: جليسك. وقعيدا كل حي: حافظاه الموكلان به عن يمينه وشماله. والقعيدة: ما أتاك من خلفك من ظبي أو طائر. وامرأة قاعد، وتجمع قواعد وهن اللواتي قعدن عن الولد فلا يرجون نكاحا والقواعد: أساس البيت، الواحدة قاعد وقياسه قاعدة بالهاء، وقعائد الرمل وقواعده: ما ارتكن بعضه فوق بعض. وقواعد الهودج: خشبات أربع معترضات في أسفله قد ركب الهودج فيهن والإقتعاد مصدر اقتعد من قولك: ما اقتعد فلانا عن السخاء إلا لوم أصله. ومنه قول الشاعر: فاز قدح الكلبي واقتعدت معزاء ... 3 عن سعيه عروق لئيم ورجل قعدد وقعددة: جبان لئيم قاعد عن الحرب، قال الحطيئة للزبرقان: دع المكارم لا ترحل لبغيتها ... واقعد فإنك أنت الطاعم الكاسي قال حسان لعمر: ما هجاه ولكن ذرق عليه. والقعدد أقرب القرابة إلى الحي ، يقال: هذا أقعد من ذاك في النسب أي أسرع انتهاء وأقرب أبا وورثت فلانا بالقعود: أي لم يوجد في أهل بيته أقعد نسبا مني إلى أجداده. والإقعاد والقعاد: داء يأخذ في أوراك الإبل، وهو شبه ميل العجز إلى الأرض، أقعد البعير فهو مقعد، ولا يعتري ذلك إلا الرجلية أي النجيبة، والمقعدة من الابار: التي أقعدت فلم ينته بها إلى الماء فتركت، قال الراجز (وهو عاصم بن ثابت الأنصاري) 1 أبو سليمان وريش المقعد ... ومخبأ من مسك ثور أجرد 2 وضالة مثل الجحيم الموقد يعني: أنا أبو سليمان ومعي سهامي راشها المقعد، وهو اسم رجل كان يريش السهام. والضالة من شجر السدر يعمل منها السهام. شبه السهام بالجمر لتوقدها وقعدت الرخمة: جثمت. وما قعدت واقتعدك؟ أي حبسك والقعد: النخل الصغار وهو جمع قاعد كما قالوا: خادم وخدم. وقعدت الفسيلة وهي قاعد: صار لها جذع تقعد عليه. وفي أرض فلان من القاعد كذا وكذا أصلا، ذهبوا إلى الجنس والقاعد من النخل: الذي تناله اليد 3'),
(73, 'قدع', 'قدع', 'قدع', 'القدع: كفك انسانا عن الشيء بيدك أو بلسانك أو برأيك فينقدع 4 لمكانك، قال: قياما تقدع الذبان عنها ... بأذناب كأجنحة النسور وامرأة قدعة: قليلة الكلام كثيرة الحياء. ونسوة قدعات 5 . والتقادع: التهافت في الشيء كتهافت الفراش في النار. وتقادع القوم: إذا مات بعضهم في إثر بعض. والقدوع: الكاف عن الصوت. قال عرام: وقدوع إذا كان يأنف من كل شيء وبالذال أيضا قال الطرماح: إذا ما رآنا شد للقوم صوته ... وإلا فمدخول الغناء قدوع'),
(74, 'دقع', 'دقع', 'دقع', 'الدقعاء: التراب المنثور على وجه الأرض. وأدقعت: التزقت بالأرض فقرا. والداقع: الذي يطلب مداق الكسب. والداقع: الكئيب المهتم، قال الكميت: ولم يدقعوا عند ما نابهم ... لوقع الحروب ولم يخجلوا أي لم يخضعوا للحرب.'),
(75, 'دعق', 'دعق', 'دعق', 'دعقت الدواب في الأرض لشدة الوطء حتى تصير فيها اثار من دعقها، قال رؤبة: في رسم آثار ومدعاس دعق ... يردن تحت الأثل سياح الدسق قال الضرير: الأثر والرسم واحد، لكن اختلف اللفظان (فجاز له الجمع بينهما) 1 وأراد بالدعق: الدفع الكثير، وأراد بالدسق الدسع (ولكن ألجأت الضرورة فجعل العين قافا) 2 الدسع: القيء، وهو أخف القيء يغلب المتقي 3'),
(76, 'عتق', 'عتق', 'عتق', 'أعتقت الغلام إعتاقا فعتق. وهو يعتق عتقا وعتاقا وعتاقة. وحلف بالعتاق. والعبد عتيق أي معتق 1 . (ولا يقال عاتق إلا أن ينوي فعل القابل فيقال: عاتق غدا) 2 . وامرأة عتيقة: حرة من الأموة. وجارية عاتق شابة أول ما أدركت. وامرأة عتيقة: جميلة كريمة. عتقت عتقا. وكلما وجدت من نعت النوق في الشعر عتيقة فاعلم أنها نجيبة والعتيق القديم من كل شيء. وقد عتق عتقا وعتاقة: أي أتى عليه زمن طويل. والبيت العتيق: هو الكعبة لأنه أول بيت وضع للناس، قال الله تعالى: وليطوفوا بالبيت العتيق 3 . والعاتق من الطير: فوق الناهض، وأول ما ينحسر ريشه الأول وينبت له ريش جلدي أي شديد صلب. وقيل: العاتق من الطير ما لم يسن ويستحكم والجمع عتق وجمعها عواتق. والعاتقان: ما بين المنكبين. والعاتق من الزقاق: الواسع الجيد والعاتق من نعت المزادة: إذا كانت واسعة. وشرب العتيق: وهو الطلا والخمر، ويقال: هو الماء والخمر العتيقة: التي قد عتقت زمانا حتى عتقت. قال الأعشى: وسبيئة مما تعتق بابل ... كدم الذبيح سلبتها جريالها السبيئة: الخمر تنقل من بلد إلى بلد، والجريال: لونها الأحمر، يعني: شربتها حمراء وبلتها صفراء. والمعتقة: ضرب من العطر. وعتيق الطير: البازي، قال: فانتضلنا وابن سلمى قاعد ... كعتيق الطير يغضى ويجل والعتيق: اسم أبي بكر الصديق. قتع: القتع: دود أحمر تكون في الخشب تأكله، الواحدة قتعة. قال عرام: وهي القادحة أيضا، قال: غداة غادرتهم قتلى كأنهم ... خشب تقصف في أجوافها القتع 1 (وهي الأرض أيضا والطحنة والعرانة والحطيطة والبطيطة واليسروعة والهرنبصاة وقاتعه الله مثل كاتعه، وقيل: هي على البدل) 2'),
(77, 'قعظ', 'قعظ', 'قعظ', 'القعظ: إدخال المشقة تقول: أقعظني فلان. إذا أدخل عليك المشقة في أمر كنت عنه بمعزل.'),
(78, 'عذق', 'عذق', 'عذق', 'العذق: العنقود من العنب. العذق: النخلة بحملها. وقال غبره: العذق: الكباسة 1 وهي العنقود على النخلة أو عنقود العنب. والعذق من النبات: ذو الأغصان، وكل غصن له شعب، والعذق: موضع، وخبراء العذق: موضع معروف بناحية الصمان، قال رؤبة: 2 بين القرينين وخبراء العذق'),
(79, 'قذع', 'قذع', 'قذع', 'القذع: سوء القول من الفحش ونحوه، قذعته قذعا: رميته بالفحش، قال: يا أيها القائل قولا أقذعا وتقول: أقذع القول إقذاعا أي أساءه. وامرأة قذوع: تأنف من كل شيء. ذعق: الذعاق بمنزلة الزعاق. قال الخليل 3 : سمعناه فلا ندري ألغة هي أم لثغة. قال زائدة داء زعاق وذعاق أي قاتل.'),
(80, 'قعث', 'قعث', 'قعث', 'أقعثني العطية: أجزلها، قال رؤبة: أقعثني منه بسيب مقعث ... ليس بمنزور ولا بريث والقعث: الكثرة. وإنه لقعبث أي كثير واسع من المعروف ونحوه. قال مبتكر الأعرابي: اقتعث وقعث، وعذم له من ماله واعتذم، (وعثم له واعتثم) 1 ومطر قعيث أي كثير. قال زائدة: الاقتعاث 2 : الكيل الجزاف.'),
(81, 'عقر', 'عقر', 'عقر', 'العقر 3 : كالجرح. سرج معقر وكلب عقور 4 يعقر الناس. وعقرت الفرس: كشفت قوائمه بالسيف، وفرس عقير معقور وكذلك يفعل بالناقة فإذا سقطت نحرها مستمكنا منها. وكل عقير معقور، وجمعه عقرى، قال لبيد: لما رأى لبد النسور تطيرت ... رفع القوادم كالعقير الأعزل ويروى: كالفقير الأعزل، أي مكسور الفقار، شبه هذا النسر القشعم حين أراد أن يطير بالفرس المعقور المائل. وعقرت ظهر الدابة إذا أدبرته، قال امرؤ القيس: عقرت بعيري يا امرأ القيس فانزل وانعقر واعتقر ظهر الدابة بالسرج، قال 1 : وإن تحنى كل عود وانعقر والعقر مصدر العاقر، وهي التي لا تحمل، يقال: امرأة عاقر وبها عقر، ونسوة عواقر وعقر. وقد عقرت تعقر، (وعقرت) تعقر أحسن لأن ذلك شيء ينزل بها وليس من فعلها بنفسها. وفي الحديث: عجز عقر. والعقر: دية فرج المرأة إذا غصبت. وبيضة العقر: بيضة الديك تنسب إلى العقر لأن الجارية العذراء تبلى بها فيعلم شأنها فتضرب بيضة العقر مثلا لكل شيء لا يستطاع مسه رخاوة وضعفا (ويضرب ذلك مثلا للعطية القليلة التي لا يزيدها معطيها ببر يتلوها) 2 ويقال للرجل الأبتر الذي لم يبق له ولد من بعده 3 كبيضة العقر والعقر: قصر يكون معتمدا لأهل القرية يلجأون إليه. قال لبيد بن أبي ربيعة يصف ناقته: كعقر الهاجري إذا آبتناه ... بأشباه حذين على مثال يعني الجسم في عظم القصر والقوائم والأساطين. وعقر الدار محلة بين الدار والحوض كان هناك بناء أو لم يكن، قال أوس بن مغراء: أزمان سقناهم عن عقر دارهم ... حتى استقروا وأدناهم بحوارنا ويقال: وعقر الدار وعقر الدار بالرفع والنصب. وعقر الحوض: موقف الإبل إذا وردت. قال امرؤ القيس واصفا صائدا حاذقا بالرمي يصيب المقاتل: فرماها في فرائصها ... من إزاء الحوض أو عقره وقال 4 : بأعقاره القردان هزلى كأنها ... بوادر صيصاء الهبيد المحطم يعني أعقار الحوض. قال الخليل: سمعت أعرابيا فصيحا من أهل الصمان يقول: كل فرجة تكون بين شيئين فهو عقر وعقر لغتان، ووضع يديه على قائمتي المائدة 1 ونحن نتغدى فقال: ما بينهما عقر. والعقر: غيم ينشأ من قبل العين فيغشي عين الشمس وما حواليها، ويقال: بل ينشأ في عرض السماء ثم يقصد على حاله من غير أن تبصره إذا مر بك ولم تسمع رعده من بعيد. قال حميد: 2 وإذا احزألت في المناخ رأيتها ... كالعقر أفردها الغمام الممطر يصف الإبل. والنخلة تعقر: تقطع رءوسها فلا يخرج من ساقها شيء حتى تيبس فذلك العقر، والنخلة عقرة 3 وكذلك يكون في الطير فقد تضعف 4 قوادمها فتصيبها آفة فلا ينبت ريشها أبدا. يقال: طائر عقر وعاقر. والعقار: ضيعة الرجل، يجمع عقارات والعقار: الخمر التي لا تلبث أن تسكر. والعقار والمعاقرة: إدمان شربها، يقال: ما زال فلان يعاقرها حتى صرعته، قال العجاج: صهباء خرطوما عقارا قرقفا وعقر الرجل: بقي متحيرا دهشا من غم أو شدة. وعقيرة الرجل: صوته إذا غنى أو قرأ أو بكى. وعقيرته، ناقته. وعقيرته: ما عقر من صيد. ويقال امرأة عقرى حلقى: توصف بالخلاف والشؤم ويقال: عقرها الله: أي عقر جسدها وأصابها بوجع في حلقها واشتقاقه من أنها تحلق قومها وتعقرهم: أي تستأصلهم من شؤمها عليهم. ويقال في الشتيمة: عقرا له وجدعا 1'),
(82, 'عرق', 'عرق', 'عرق', 'العرق: ماء الجسد يجري من أصول الشعر وإن جمع فقياسه أعراق مثل حدث وأحداث وسبب وأسباب. وقد عرق يعرق عرقا. واللبن عرق يتحلب في العروق ثم ينتهي إلى الضروع، قال الشماخ: 2 تمسي وقد ضمنت ضراتها عرقا ... من طيب الطعم صاف غير مجهود ولبن عرق: فاسد الطعم، وهو الذي يجعل في سقاء ثم يشد على بعير ليس بينه وبين جنبه شيء فإذا أصابه العرق فسد طعمه وتغير لونه. وعرقت الفرس تعريقا: أي أجريته حتى عرق، قال الأعشى: يعالى عليه الجل كل عشية ... ويرفع نقلا بالضحى ويعرق وعرق الشجرة وعروق كل شيء أطنابه تنبت من أصوله ويقال: استأصل الله عرقاتهم 3 ، بنصب التاء أي شأفتهم، لا يجعلونه كالتاء الزائدة في التأنيث. وقال بعضهم: العرقاة إنما هي أرومة الأصل التي تتشعب منها العروق على تقدير سعلاة، وهي عرق يذهب في الأرض سفلا. ويقال: العرقات جمع العرق، الواحدة عرقة، وهي الأرومة التي تذهب سفلا في الأرض من عروق الشجر في الوسط، وتأؤه كتاء جمع التأنيث، ولكنهم ينصبونه كقولهم: رأيت بناتك لخفته على اللسان لأنه مبني على فعال والعرق: نبات أصفر يصبغ به وجمعه عروق. والعرب تقول: إنه لمعرق له في الحسب والكرم، وفي اللؤم والقرم 1 ويجوز في الشعر إنه لمعروق. وعرقة أعمامه وأخواله تعريقا، وأعرقوا فيه إعراقا، وعرق فيه اللئام، وأعرق فيه إعراق العبيد والإماء إذا خالطه ذلك وتخلق بأخلاقهم. وتداركه أعراق خير وأعراق شر. قال 2 : جرى طلقا حتى إذا قيل سابق ... تداركه أعراق سوء فبلدا وجرت الخيل عرقا أي طلقا وأعرق الفرس: صار عريقا كريما. وأعرق الشجر والنبات: امتدت عروقه والعريق من الناس والخيل: الذي فيه عرق من الكرم. والعراق: شاطىء البحر على طوله. وبه سمي العراق لأنه على شاطىء دجلة والفرات. وتقول: رفعت من الحائط عرقا وجمعه أعراق. وفي الحديث: ليس لعرق ظالم حق ، وهو الذي يغرس في أرض غيره، وذلك أن الرجل يجيء إلى أرض قد أحياها رجل قبله فيغرس فيها غرسا أو يحدث فيها حدثا يستوجب به الأرض. وعراق المزادة والرواية: الخرز المثنى الذي في أسفله، ويجمع على عرق، وثلاثة أعرقة، وهو من أوثق خرزها، قال ابن أحمر: من ذي عراق نيط في خرز ... فهو لطيف طيه مضطمر والعرقوة: خشبة معروضة على الدلو، ورب دلو ذات عرقوتين. للقتب عرقوتان وهما خشبتان 3 على جانبيه. والعرقوة: كل أكمة كأنها جثوة قبر فهي مستطيلة. والعرقوة من الجبال: الغليظ المنقاد في الأرض ليس يرتقى لصعوبته وليس بطويل. والعرق: جبل صغير. قال الشماخ: ما إن يزال لها شأو يقومها ... مجرب مثل طوط العرق مجدول 1 وقال يصف الغرب 2 : رحب الفروع مكرب العراقي والعراق: العظم الذي قد أخذ عنه اللحم. قال: فألق لكلبك منها عراقا وتقول: عرقت العظم أعرقه عرقا واتعرقه إذا أكلت لحمه، فإذا كان العظم بلحمه فهو عرق. ورجل معروق ومعترق: إذا لم يكن على قصبه لحم، وكذلك المهزول، قال رؤبة يصف صيادا وامرأته: غول تصدى 3 لسبنتى معترق ... كلحية الأصيد من طول الأرق وفرس معترق: معروق أي مهزول قليل اللحم. قال امرؤ القيس: قد أشهد الغارة الشعواء تحملني ... جرداء معروقة اللحين سرحوب (ويروى: معروقة الجنبين وإذا عري لحياها من اللحم فهو من علامات عتقها،) (يصفه بقلة لحم وجهها وذلك أكرم لها 4 ) . والعرق والعرقات: كل شيء مصطف أو مضفور. والعرق: الطير المصطفة في السماء، الواحدة عرقة. والعرقة: السفيفة 5 المنسوجة من الخوص قبل أن يجعل زبيلا ويسمى الزبيل 6 عرقا وعرقة واشتقاقه منه، قال أبو كبير: نغدو فنترك في المزاحف من ثوى ... ونقر في العرقات من لم يقتل يعني نأسرهم فنشدهم في العرقات وهي النسوع'),
(83, 'قعر', 'قعر', 'قعر', 'قعر كل شيء: أقصاه ومبلغ أسفله. يقال: بئر قعرة وقصعة قعيرة: قد قعرت قعارة واقعرتها إقعارا. وامرأة قعر ويقال قعرة نعت سوء لها في الجماع. وقعرت الشجرة فانقعرت: قلعتها فانقلعت من أرومتها. والرجل يقعر في كلامه إذا تشدق وتكلم بأقصى قعر فمه، وهو يقعر تقعيرا أي يبلغ قعر الأشياء من الأمور ونحوها.'),
(84, 'قرع', 'قرع', 'قرع', 'القرع: ذهاب شعر الرأس من داء. رجل أقرع وامرأة قرعاء ونساء قرع ورجال قرعان ويجوز قرع إلا أن فعلان في جماعة أفعل في النعوت أصوب. ونعام قرع، ويقال: (ما تسن إلا قرعت) 1 وفي المثل: استنت الفصال حتى القرعى أي سمنت، يضرب مثلا لمن تعدى طوره وادعى ما ليس له. ودواء القرع الملح وجباب ألبان الإبل، فإذا لم يجدوا ملحا نتفوا أوباره ونضحوا جلده بالماء ثم جروه على السبخة. وتقرع جلده: تقوب عن القرع. وقرع الفصيل تقريعا: فعل به ما يفعل به إذا لم يوجد الملح، قال أوس بن حجر يذكر الخيل 2 : لدى كل أخدود يغادرن دارعا ... يجر كما جر الفصيل المقرع وهذا على السلب لأنه ينزع قرعه بذلك كما يقال: قذيت العين أي نزعت قذاها، وقردت البعير. والقرع: حمل اليقطين الواحدة قرعة. ويقال: أقرع القوم وتقارعوا بينهم والاسم القرعة. وقارعته فقرعته اصابتني القرعة دونه. واقرعت بين القوم: أمرتهم أن يقترعوا على الشيء، وقارعت بينهم ايضا، وفلان قريع فلان أي يقارعه، والجمع قرعاء. والقريع من الإبل: الفحل، ويسمي قريعا لانه يقرع الناقة أي يضربها، (وثلاثة أقرعة) ، 1 قال الفرزدق: وجاء قريع الشول قبل إفالها ... يزف وجاءت خلفه وهي زفف وقال ذو الرمة: 2 : وقد لاح للساري سهيل كأنه ... قريع هجان عارض الشول جافر ويروى: وقد عارض الشعرى سهيل'),
(85, 'عقل', 'عقل', 'عقل', 'العقل: نقيض الجهل. عقل يعقل عقلا فهو عاقل. والمعقول: ما تعقله في فؤادك. ويقال: هو ما يفهم من العقل، وهو العقل واحد، كما تقول: عدمت معقولا أي ما يفهم منك من ذهن أو عقل 1 . قال دغفل: فقد أفادت لهم حلما وموعظة ... لمن يكون له إرب ومعقول وقلب عاقل عقول، قال دغفل: بلسان سؤول، وقلب عقول وعقل بطن المريض بعد ما استطلق: استمسك. وعقل المعتوه ونحوه والصبي: إذا ادرك وزكا. وعقلت البعير عقلا شددت يده بالعقال أي الرباط، والعقال: صدقة عام من الإبل ويجمع على عقل، قال عمرو بن العداء الكلبي: سعى عقالا فلم يترك لنا سبدا ... فكيف لو قد سعى عمرو عقالين والعقلية: المرأة المخدرة، المحبوسة في بيتها وجمعها عقائل، وقال عبيد الله بن قيس الرقيات: 2 درة من عقائل البحر بكرء ... لم تخنها مثاقب اللآل يعني بالعقائل الدر، واحدتها عقيلة، وقال امرؤ القيس في العقلية وهو يريد المرأة المخدرة: عقيلة أخدان لها لا دميمة ... ولا ذات خلق ان تأملت جأنب 1 وفلانة عقلية قومها وهو العالي من كلام العرب. ويوصف به السيد. وعقيلة كل شيء: أكرمه. وعقلت القتيل عقلا: أي وديت ديته من القرابة لا من القائل، قال: 2 إني وقتلي سليكا ثم أعقله ... كالثور يضرب لما عافت البقر والعقل في الرجل اصطكاك الركبتين، وقيل: التواء في الرجل، وقيل: هو أن يفرط الروح في الرجلين حتى يصطك العرقوبان وهو مذموم، قال: أخا الحرب لباسا إليها جلالها ... وليس بولاج الخوالف أعقلا وبعير أعقل وناقة عقلاء: بينا العقل وهو التواء في رجل البعير واتساع، وقد عقل عقلا. والعقال- ويخفف أيضا-: داء يأخذ الدواب في الرجلين، يقال: دابة معقولة، وبها عقال: اذا مشت كأنها تقلع رجليها من صخرة 3 وأكثر ما يعتريه في الشتاء. والعقل: ثوب تتخذه نساء الأعراب، قال علقمة بن عبدة: عقلا ورقما تظل الطير تتبعه 4 ... كأنه من دم الأجواف مدموم ويقال: هي ضربان من البرود. والعقل: الحصن وجمعه العقول. وهو المعقل ايضأ وجمعه معاقل، قال النابغة: وقد اعددت للحدثان حصنأ ... لو أن المرء تنفعه العقول. وقال: ولاذ بأطراف المعاقل معصما ... وأنسي أن الله فوق المعاقل والعاقل من كل شيء: ما تحصن في المعاقل المتمنعة، قال حفص الأموي: تظل خوف الرماة عاقلة ... الى شظايا فيهن أرجاء وفلان معقل قومه: أي يلجئون إليه اذا حزبهم أمر، قال الفرزدق: كان المهلب للعراق سكينة ... وحيا الربيع ومعقل الفرار والعاقول: المعرج والملتوي من النهر والوادي، ومن الأمور الملتبس المعوج. (وأرض عاقول: لا يهدى لها) 1 . والعقنقل من الرمال والتلال: ما ارتكم واتسع، ومن الأودية: ما عرض واتسع بين حافتيه، والجمع عقاقل وعقاقيل، قال العجاج: إذا تلقته الدهاس خطرفا ... وإن تلقته العقاقيل طفا يصف الثور الوحشي وظفره. والخطرفة: مشية كالتخطي. ويقال في الصرعة: عقلته عقلة شغزبية فصرعته. ومعقلة: موضع بالبادية. وعاقل: اسم جبل، قال: لمن الديار برامتين فعاقل');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(86, 'علق', 'علق', 'علق', 'العلق: الدم الجامد قبل أن ييبس، والقطعة علقة. والعلقة: دويبة حمراء تكون في الماء، تجمع على علق. والمعلوق: الذي أخذ العلق بحلقه إذا شرب. والعلوق: المرأة التي لا تحب غير زوجها. ومن النوق: التي تألف الفحل ولا ترام البو، ويقال: هي التي يعلق عليها ولد غيرها، قال: أفنون التغلبي: وكيف ينفع ما تعطي العلوق به ... رئمان أنف اذا ما ضن باللبن 1 والمرأة اذا أرضعت ولد غيرها يقال لها علوق ويجمع على علائق، قال: وبدلت من أم علي شفيقة ... علوقا وشر الامهات علوقها والعلق: ما يعلق به البكرة من القامة، قال رؤبة: قعقعة المحور خطاف العلق 2 والعلق: المال الذي يكرم عليك، تضن به، تقول: هذا علق مضنة. وما عليه علقة اذا لم يكن عليه ثياب فيها خير والعلاقة: ما تعلقت به في صناعة أو ضيعة أو معيشة معتمدا عليه، أو ما ضربت عليه يدك من الأمور والخصومات ونحوها التي تحاولها. وفلان ذو معلاق: أي شديد الخصومة والخلاف، ويقال: مغلاق وإنما عاقبوا (على حذف المضاف) 3 ، وقال: 4 إن تحت الأحجار 5 حزما وعزما ... وخصيما ألد ذا معلاق ومعلاق الرجل: لسانه اذا كان بليغا. وعلقت بفلان: أي خاصمته. وعلق بالشيء: نشب به، قال جرير: اذا علقت مخالبه بقرن ... أصاب القلب أو هتك الحجابا وعلقت فلانة: أي أحببتها. وعلق فلان يفعل كذا: أي طنق وصار. وتقول: علقت بقلبي علاقة جني، قال جرير: أو ليتني لم تعلقني علائقها ... ولم يكن داخل الحب الذي كانا وقال جميل: ألا أيها الحب المبرح هل ترى ... أخا علق يفري بحب كما أفري 1 والمعلاق: ما علق من العنب ونحوه. وأهل اليمن يقولون: معلوق، أدخلوا الضمة والمدة، كأنهم أرادوا حذو بناء المدهن والمنخل ثم مدوا. وتمامه ان يكون ممدودا لأنه على حذو المنطيق والمحضير. وكل شيء علق عليه فهو معلاقه. ومعلاق الباب: مزلاجه يفتح بغير المفتاح. والمغلاق يفتح بالمفتاح. يقال: علق الباب وأزلجه، وتعليق الباب: نصبه وتركيبه. وعلاقة السوط: سير في مقبضه. والعلقة: شجرة تبقى في الشتاء. وكل شيء كانت علقة فهو بلغة والإبل تعلق منه فتستغني به حتى تدرك الربيع وقد علقت به تعلق علقا اذا اكلت منه فتبلغت به. والعليقي: شجر معروف. والعلقة من النبات لا تلبث أن تذهب. والعلقى: شجر، واحدته علقاة، قال العجاج: فكر في علقى وفي مكور 2 ... بين ثواري الشمس والذرور والعولق: الغول، والكلبة الحريصة على الكلاب. قال الطرماح: عولق الحرص اذا أمشرت ... سادرت فيه سؤور المسامي 3 يعني أنهم يودعون ركابهم ويركبونها ويزيدون في حملها. والعليق: القضيم اذا علق في عنق الدابة والعليق: الشراب، قال لبيد: 1 اسق هذا وذا وذاك وعلق ... لا تسم الشراب إلا عليقا وكل شيء يتبلغ به فهو علقة وفي الحديث: وتجتزىء بالعلقة أي تكتفي بالبلغة من الطعام. وفي حديث الإفك: وإنما يأكلن العلقة من الطعام. وقولهم: ارض من الركب بالتعليق، يضرب مثلا للرجل يؤمر بأن يقنع ببعض حاجته دون إتمامها كالراكب عليقة من الإبل ساعة بعد ساعة) 2 . ويقال: العليق ضرب من النبيذ يتخذ من التمر. ومعاليق العقد: الشنوف يجعل فيها من كل ما يحسن فيه. والعلاق: ما تتعلق به الإبل فتجتزىء به وتتبلغ، قال الأعشى: وفلاة كأنها ظهر ترس ... ليس إلا الرجيع فيها علاق (والعليق: نبات أخضر يتعلق بالشجر ويلتوي عليه فيثنيه) 3 . والعلوق: التي قد علقت لقاحا. والعلوق أيضا: ما تعلقه الإبل أي ترعاه، وقيل: نبت، قال الأعشى: هو الواهب المائة المصطفاة ... لاق العلوق بهن احمرارا 4 (أي حسن النبت ألوانها. وقيل: إنه يقول: رعين العلوق حين لاط بهن الاحمرار من السمن والخصب. ويقال: أراد بالعلوق الولد في بطنها، وأراد بالاحمرار حسن لونها عند اللقح) 5 . والعلوق: الناقة السيئة الخلق القليلة الحلب، لا ترأم البو، ويعلق عليها فصيل غيرها، وتزبن ولدها أيضا لأنها تتأذى بمصه إياها لقلة لبنها، قال الكميت والرؤوم الرفود ذا السر ... منهن علوقا يسقينها وزجورا قعل: القعال: ما تناثر عن نور العنب وعن فاغية الحناء وشبهه، الواحدة: قعالة. وأقعل النور: اذا انشق عن قعالته. والاقتعال: أخذك ذلك عن الشجر في يدك إذا استنفضته. والمقتعل: السهم الذي لم يبربريا جيدا، قال لبيد: فرشقت القوم رشقا صائبا ... ليس بالعصل ولا بالمقتعل 1 (والاقعيلال: الانتصاب في الركوب) 2 .'),
(87, 'قلع', 'قلع', 'قلع', 'قلعت الشجرة واقتلعتها فانقلعت. ورجل قلع: لا يثبت على السرج. وقد قلع قلعا وقلعة. والقالع: دائرة بمنسج الدابة يتشاءم به. ويجمع قوالع. والمقلوع: الأمير المعزول. قلع قلعا وقلعة، قال خلف بن خليفة: 3 تبدل بآذنك المرتشي ... وأهون تعزيره القلعة أي أهون أدبه أن تقلعه. والقلعة: الرجل الضعيف الذي اذا بطش به لم يثبت، قال: يا قلعة ما أتت قوما بمرزئة ... كانوا شرارا وما كانوا بأخيار والقلعة من الحصون: ما يبنى منها على شعف الجبال الممتنعة. وقد أقلعوا بهذه البلاد قلاعا: أي بنوها. والمقلعة من السفن: العظيمة تشبه بالقلع من الجبال، وقال يصف السفن: مواخر في سماء اليم مقلعة ... اذا علوا ظهر موج ثمت انحدروا شبه السفن العظام بالقلعة 1 لعظمها وارتفاعها، وقال: 2 ) تكسر فوقه القلع السواري ... وجن الخاز باز بها جنونا يصف السحاب. والقلعة: القطعة من السحاب. واقلعت السماء: كفت عن المطر. وأقلعت الحمى: فترت فانقطعت. والقلعة: صخرة ضخمة تنقلع عن جبل، منفردة صعبة المرتقى. والقلعي: الرصاص الجيد. والسيف القلعي: ينسب الى القلعة العتيقة. والقلعة: موضع بالبادية تنسب اليه السيوف، قال الراجز: محارف بالشاء والأباعر ... مبارك بالقلعي الباتر والقلاع: الطين الذي يتشقق اذا نضب عنه الماء. والقطعة منه قلاعة. واقلع فلان عن فلان أي كف عنه. وفي الحديث: بئس الماء القلعة لا تدوم لصاحبها لأنه متى شاء ارتجعه.'),
(88, 'لعق', 'لعق', 'لعق', 'اللعوق: اسم كل شيء يلعق، من حلاوة أو دواء. لعقته ألعقه لعقا، لا تحرك مصدره لأنه فعل واقع، ومثل هذا لا يحرك مصدره، وأما عجل عجلا وندم ندما فيحرك، لأنك لا تقول: عجلت الشيء ولا ندمته لأن هذا فعل غير واقع. والملعقة: خشبة معترضة الطرف يؤخذ بها ما يلعق. واللعقة: اسم ما تأخذه بالملعقة. واللعقة: المرة الواحدة فالمضموم اسم. والمفتوح فعل مثل اللقمة واللقمة والأكلة والأكلة. واللعاق: بقية ما بقي في فمك مما ابتلعت، تقول: ما في فمي لعاق من طعام كما تقول: أكال ومصاص. وفي الحديث: إن للشيطان لعوقا ونشوقا يستميل 1 بهما العبد إلى هواه. فاللعوق اسم ما يلعقه. والنشوق: اسم ما يستنشقه لقع: لقعت الشيء: رميت به، القعه لقعا. واللقاعة على بناء شداخة 2 : الرجل الداهية الذي يتلقع بالكلام يرمي به رميا، قال: باتت تمنيها الربيع وصوبه ... وتنظر من لقاعة ذي تكاذب لقعه بعينه: أصابه بها. ولقعه ببعرة: رماه بها. واللقاع: الكساء الغليظ. وقال بعضهم: هو اللفاع لأنه يتلفع به وهذا أعرف.'),
(89, 'عنق', 'عنق', 'عنق', 'العنق: من سير الدواب. والنعت معناق ومعنق وعنيق. وسير عنيق. وبرذون عنق. ولم أسمع عنقه، قال رؤبة: لما رأتني عنقي دبيب ... وقد أرى وعنقي سرحوب ويجوز للشاعر أن يجعل العنق من السير عنيقا. والمعنق من جلد الأرض: ما صلب وارتفع وما حواليه سهل، وهو منقاد في طول نحو ميل أو أقل، وجمعه معانيق. والعنق معروف، يخفف ويثقل ويؤنث. وقول الله تعالى: فظلت أعناقهم لها خاضعين 1 أي جماعاتهم، ولو كانت الأعناق خاصة لكانت خاضعة وخاضعات. ومن قال: هي الأعناق، والمعني على الرجال، رد نون خاضعين على أسمائهم المضمرة. وتقول: جاء القوم رسلا رسلا وعنقا عنقا إذا جاءوا فرقا 2 ، ويجمع على الأعناق. واعتنقت الدابة: إذا وقعت في الوحل فأخرجت أعناقها، قال رؤبة: خارجة أعناقها من معتنق أي من موضع أخرجت أعناقها منه. والمعتنق: مخرج أعناق الجبال من السراب، أي اعتنقت فأخرجت أعناقها. والاعتناق من المعانقة، ويجوز الافتعال في موضع المفاعلة، غير أن المعانقة في حال المودة، والاعتناق في الحرب ونحوها، تقول: اعتنقوا في الحرب ولا تقول: تعانقوا والقياس واحد، قال زهير: يطعنهم ما ارتموا حتى اذا اطعنوا ... ضارب حتى ما ضاربوا اعتنقا وتعنقت الأرنب في العانقاء (وتعنقتها، كلاهما مستعمل: دست عنقها فيه وربما غابت تحته، وكذلك البربوع والعانقاء) 1 . وهو جحر مملوء ترابا رخوا يكون للأرنب واليربوع إذا خافا. وربما دخل ذلك التراب فيقال: تعنق اليربوع لأنه يدس عنقه فيه ويمضي حتى يصير تحته. والعنقاء: طائر لم يبق في أيدي الناس من صفتها غير اسمها. ويقال بل سميت به لبياض في عنقها كالطوق وقال: إذا ما ابن عبد الله خلى مكانه ... فقد حلقت بالجود عنقاء مغرب والعنقاء: الداهية. والعنقاء: اسم ملك، قال: 2 ولدنا بني العنقاء وابني محرق ... فأكرم بنا خالا وأكرم بنا ابنما والأعنق: الطويل العنق. والأعنق: الكلب الذي في عنقه بياض كالطوق. والعناق: الأنثى من أولاد المعز. ويجمع العنوق. وقولهم: العنوق بعد النوق، أي صرت راعيا للغنم بعد النوق، يقال ذلك لمن تحول من رفعة إلى دناءة، قال إذا مرضت منها عناق رأيته ... بسكينه 3 من حولها يتصرف 4 وعناق الأرض: حيوان أسود الرأس طويل الظهر أصغر من الفهد ويجمع على عنوق . قعن: اشتق منه اسم قعين وهو في أسد وفي قيس أيضا. ويقال: أفصح العرب نصر قعين أو قعين نصر. والقيعون من العشب: نبت على فيعول مثل قيصوم، وهو ما طال منه. يقال: اشتقاقه من القعن كاشتقاق القيصوم من القصم. ونحو هذه الأشياء اشتقت من الأسماء وأميتت أصولها، ولكن يعرف ذلك في تقدير الفعل. قيل: يكون القيعون من القيع كالزيتون من الزيت'),
(90, 'قنع', 'قنع', 'قنع', 'قنع يقنع قناعة: أي رضي بالقسم فهو قنع وهم قنعون، وقوله تعالى: القانع والمعتر فالقانع: السائل، والمعتر: المعترض له من غير طلب، قال: 1 ومنهم شقي بالمعيشة قانع وقنع يقنع قنوعا: تذلل للمسألة فهو قانع، قال الشماخ: لمال المرء يصلحه فيغني ... مفاقره أعف من القنوع 2 ويروى من الكنوع بمنزلة القنوع ورجل قنع أي كثير المال والقنوع بمنزلة الهبوط- بلغة هذيل- من سفح الجبل، وهو الارتفاع أيضا. قال: بحيث استفاض 3 القنع غربي واسط ... نهارا ومجت في الكثيب الأباطح والقناع: طبق من عسيب النخل وخوصه. والإقناع: مد البعير رأسه إلى الماء ليشرب، قال يصف ناقة: تقنع للجدول منها جدولا شبه حلق الناقة وفاها بالجدول تستقبل به جدولا في الشرب. والرجل يقنع الإناء للماء الذي يسيل من جدول أو شعب. والرجل يقنع يده في القنوت أي يمدها فيسترحم ربه. والقناع أوسع من المقنعة. وتقول: ألقى فلان عن وجهه قناع الحياء وفلان مقنع: أي يرضى بقوله. وتقول: قنعت رأسه بالعصا أو بالسوط: أي علوته به ضربا.؟ والقنعة وجمعها القنع وجمع القنع القنعان: وهو ما جرى بين القف والسهل من التراب الكثير، فإذا نضب عنه الماء صار فراشا يابسا، قال: 1 وايقن أن القنع صارت نطافه ... فراشا وأن البقل ذاو ويابس المقنعة من الشاء: المرتفعة الضرع، ليس في ضرعها تصوب، قنعت بضرعها، وأقنعت فهي مقنع. واشتقاقه من اقناع الماء ونحوه كما ذكرنا . نعق: نعق الراعي بالغنم نعيقا: صاح بها زجرا. ونعق الغراب ينعق نعاقا ونعيقا. وبالغين أحسن. والناعقان: كوكبان أحدهما رجل الجوزاء اليسرى والآخر منكبها الأيمن. وهو الذي يسمى الهقعة، وهما أضوأ كوكبين في الجوزاء نقع: نقع الماء في منقعة السيل ينقع نقعا ونقوعا: اجتمع فيها وطال مكثه. وتجمع المنقعة 2 على المناقع. وهو المستنقع: أي المجتمع. واستنقعت في الماء: أي لبثت فيه متبردا. وأنقعت الدواء في الماء إنقاعا. والنقوع: شيء ينقع فيه زبيب وأشياء ثم يصفى ماؤه ويشرب. واسم ذلك نقوع. ونقع السم في ناب الحية: في أنيابها السم ناقع اجتمع فيه كقوله 3 . وانتقع لون الرجل وامتقع أصوب: تغير. والرجل إذا شرب من الماء فتغير لونه، يقال: نقع ينقع نقوعا. قال: 1 لو شئت قد نقع الفؤاد بشربة ... تدع الصوادي لا يجدن غليلا والماء ينقع العطش نقعا ونقوعا، قال حفص الأموي: أكرع عند الورود في سدم ... تنقع من غلتي وأجزؤها والنقيع: شراب يتخذ من الزبيب ينقع في الماء من غير طبخ. والنقيعة هي العبيطة من الإبل. وهي جزور توفر أعضاؤها فتنقع في أشياء علاجا لها، قال: كل الطعام تشتهي ربيعه ... الخرس والإعذار والنقيعه وقال المهلهل: إنا لنضرب بالصوارم هامهم ... ضرب القدار نقيعة القدام 2 القدام: القادمون من سفر، جمع قادم. وقيل القدام بفتح القاف وعن غير الخليل: والقدام: الجزار. يقال: نقعوا النقيعة، ولا يقال: أنقعوا لأنه لا يريد إنقاعها في الماء. والنقع: الغبار. قال الشويعر واسمه عبد العزى: فهن بهم ضوامر في عجاج ... يثرن النقع أمثال السراحي 3 قال ليث: قلت للخليل: ما السراحي، قال: أراد الذئاب، ولكنه حذف من السرحان الألف والنون فجمعه على سراحي، والعرب تقول ذلك كثيرا كما قال: 4 درس المنا بمتالع فأبان أراد المنازل فحذف الزاء واللام. ونقع الصوت: إذا ارتفع. ونقع بصوته، وأنقع صوته: إذا تابعه ومنه قول عمر (في نسوة اجتمعن يبكين على خالد بن الوليد: وما على نساء بني المغيرة أن يهرقن من دموعهن على أبي سليمان) ما لم يكن نقع أو لقلقة. يعني بالنقع أصوات الخدود إذا ضربت، قال لبيد: 1 فمتى ينقع صراخ صادق ... يحلبوها ذات جرس وزجل ونقع الموت يعني كثر. وما نقعت بخبره نقوعا: أي ما عجت به ولا صدقت ما عجت به أي ما أخذته ولا قبلته. والنقع: ما اجتمع من الماء في القليب. والنقيع: البئر الكثيرة الماء، تذكره العرب، وجمعه أنقعة. والمنقع والمنقعة: إناء ينقع فيه الشيء. والأنقوعة: وقبة الثريد التي فيها الودك. وكل شيء سال إليه الماء من مثعب ونحوه فهو أنقوعة.'),
(91, 'عقف', 'عقف', 'عقف', 'عقفت الشيء أعقفه عقفا: أي عطفته. والعقافة: خشبة في رأسها حجنة يمد بها الشيء كالمحجن. وهو أعقف وعقفاء: إذا كان فيه انحناء. والأعقف: الفقير المحتاج، ويجمع على عقفان، قال يزيد بن معاوية 1 يا أيها الأعقف المزجي مطيته ... لا نعمة تبتغي عندي ولا نشبا والعقفاء 2 من النبات. والعقاف: داء يأخذ في قوائم الشاة حتى تعوج شاة عاقف ومعقوفة 3 أيضا. وربما اعترى كل الدواب. قال أبو سعيد: هو القفاع لأنه يقفعها. والعقف: العطف'),
(92, 'عفق', 'عفق', 'عفق', 'عفق يعفق عفقا: إذا مضى راكبا رأسه، ومن الإبل. تقول: ما يزال يعفق عفقا ثم يرجع: أي يغيب غيبة. والإبل تعفق عفقا وعفوقا: إذا أرسلت في مراعيها فمرت على وجهها. وربما عفقت عن المرعى إلى الماء ترجع إليه بين كل يومين. وكل وارد صادر: عافق. وهو شبه الخنوس إلا أنه يرجع، قال الراجز: ترعى الغضا من جانبي مشفق ... غبا ومن يرع الحموض يعفق 4 أي من يرع المحض تعطش ماشيته سريعا فلا يجد بدا من العفق (لأن المحض يعطش فيبعث على شرب الماء 1 . وقال رؤبة: 2 صاحب عادات من الورد العفق ... يرمي ذراعيه بجثجاث السوق عفاق: اسم رجل، قال: إن عفاقا أكلته باهله ... تمششوا عظامه وكاهله'),
(93, 'قعف', 'قعف', 'قعف', 'القعف: شدة الوطء واجتراف التراب بالقوائم، قال: يقعفن باعا كفراش الغضرم ... مظلومة، وضاحيا لم يظلم قال زائدة: هو القعث. والقاعف: المطر الشديد يقعف بالحجاره أي يجرفها من وجه الأرض.'),
(94, 'قفع', 'قفع', 'قفع', 'القفع: 3 ضرب من الخشب يمشي الرجال تحته إلى الحصون في الحرب. والقفعاء: حشيشة خوارة خشناء الورق من نبات الربيع لها نور أحمر مثل الشرار، صغار ورقها 4 مستعليات من فوق وثمرتها متقفعة من تحت، قال: بالسي ما تنبت القفعاء والحسك 5 وأذن قفعاء: كأنما أصابتها نار فتزوت من أعلاها إلى أسفلها. ورجل قفعاء: أي ارتدت أصابعها أي القدم. تقول: قفعت قفعا. وربما قفعها البرد فتقفعت. ونظر أعرابي إلى قنفذة قد تقبضت فقال: أترى البرد قفعها أي قبضها. والفقاعي: الرجل الأحمر الذي يتقسر أنفه من شدة حمرته. والمقفعة: خشبة تضرب بها الأصابع. والقفاع: نبات متقفع كأنه قرون صلابة إذا يبس، يقال له كف الكلب. والقفعة: هنة تتخذ من خوص مستديرة يجنى فيها الرطب. وذكر الجراد عند عمر فقال: ليت عندنا قفعة أو قفعتين. وتسمى هذه الدوارات التي يجعل فيها الدهانون السمسم المطحون قفعات. وهي هنات يوضع بعضها على بعض حتى يسيل منها الدهن. وشهد عند بعض القضاة قوم عليهم خفاف لها قفع أي هنات مستديرة تتذبذب.'),
(95, 'فقع', 'فقع', 'فقع', 'الفقع 1 ضرب من الكمأة، واحدتها فقعة، قال النابغة: 2 حدثوني الشقيقة ما يمنع ... فقعا بقرقر أن يزولا يهجو النعمان، شبهه بالفقع لذلتها وأنها لا أصل لها. والفقع يخرج في أصل الأجرد. وهي هنات صغار، وربما خرج في النفض الواحد منه الكثير، والظباء تأكله. وهي أردأ الكمأة طعما وأسرعها فسادا، فإذا يبس آض له جوف أحمر إذا مس تفتت. ويقال: إنك لأذل من فقع في قاع. والفقاع: شراب يتخذ من الشعير سمي به للزبد الذي يعلوه. والفقاقيع: هنات كالقوارير تتفقع فوق الماء والشراب، الواحدة فقاعة قال عدي بن زيد يصف الخمر: 3 وطفا فوقها فقاقيع كالياقوت ... حمر يثيرها التصفيق أي التمزيج. والتفقيع: أخذك ورقة من الورد ثم تديرها بإصبعك ثم تغمزها فتسمع لها صوتا إذا انشقت. والتفقيع: صوت الأصابع. والفقع: الضراط. وإنه ليفقع بمفقاع: وهو المقلاع إذا رميت به سمعت له فقعا أي صوتا. وأصفر فاقع: وهو أنصعه وأخلصه. وقد فقع يفقع فقوعا. وأفقع، الرجل فهو مفقع: أي فقير مجهود، أصابته فاقعة من فواقع الدهر فاقعة من فواقع الدهر أي بائقة من البوائق يعني الشدة. فقير مفقع مدقع، فالمفقع: أسوأ ما يكون من حالات. والمدقع: الذي يبحث في الدقعاء من الفقر.'),
(96, 'عقب', 'عقب', 'عقب', 'العقب: العصب الذي تعمل منه الأوتار، الواحدة عقبة، وخلاف ما بينه وبين العصب أن العصب يضرب إلى صفرة والعقب يضرب إلى بياض وهو أصلبها 1 وأمتنها. والعقب: مؤخر القدم، تؤنثه العرب، وتميم تخففه. وتجمع على أعقاب، وثلاث أعقبة 2 وعقب الرجل: ولده وولد ولده الباقون من بعده وقولهم: لا عقب له: أي لم يبق له ولد ذكر. وتقول: ولى فلان على عقبه وعقبيه: أي أخذ في وجه 3 ثم انثنى راجعا. والتعقيب: انصرافك راجعا من أمر أردته أو وجه. والمعقب: الذي يتتبع عقب إنسان في طلب حق أو نحوه، قال لبيد 4 : حتى تهجر في الرواح وهاجه ... طلب المعقب حقه المظلوم وقوله عز وجل-: ولم يعقب 5 * أي لم ينتظر والتعقيب: غزوة بعد غزوة وسير بعد سير. وقوله عز وجل-: لا معقب لحكمه 6 ) أي لا راد لقضائه. والخيل تعقب في حضرها إذا لم تزدد إلا جودة. ويقال للفرس الجواد: إنه لذو عقو وذو عقب، فعفوه أول عدوه، وعقبه ان يعقب بحضر أشد من الأول، قال: لا جرى عندك في عقب وفي حضر وكل شيء يعقب شيئا فهو عقيبه كقولك: خلف يخلف بمنزلة الليل والنهار إذا قضى أحدهما عقب الآخر فهما عقيبان كل واحد منهما عقيب صاحبه، ويعتقبان ويتعاقبان: إذا جاء أحدهما ذهب الآخر. وعقب الليل النهار والنهار الليل: أي خلفه. وأتى فلان إلى فلان خبرا فعقب بخير منه أي أردف. ويقال: عقب أيضا مشددا. قال: 1 فعقبتم بذنوب غير مر وقال أبو ذؤيب: أودى بني وأعقبوني حسرة ... بعد الرقاد وعبرة ما تقلع قوله: فأعقبوني مخالف للألفاظ المتقدمة وموافق لها في معنى. ولعلهما لغتان. فمن قال عقب لا يقول أعقب كمن قال: بدأت به لا يقول: أبدأت، قال جرير: عقب الرذاذ خلافهم فكأنما ... بسط الشواطب بينهن حصيرا وعقب الأمر: آخره. قال: محذور عقب الأمر في التنادي ويجمع أعقاب الأمور. وعاقبة كل شيء: آخره، وعاقب أيضا بلا هاء ويجمع عواقب وعقبا. ويقال: عاقبة وعواقب وعاقب وعقب (مشدد ومخفف) تقول لي ميالة الذوائب ... كيف أخي في عقب النوائب 2 وأعقب هذا الأمر يعقب عقبانا وعقبى، قال ذو الرمة: 3 أعاذل قد جربت في الدهر ما مضى ... وروأت في أعقاب حق وباطل يعني أواخره. وأعقبه الله خيرا منه والاسم العقبى شبه العوض والبدل. وأعقب هذا ذاك: أي صار مكانه. وأعقب عزه ذلا: أي ابدل منه، قال: كم من عزيز أعقب الذل عزه ... فأصبح مرحوما وقد كان يحسد والبئر تطوى فتعقب الحوافي بالحجارة من خلفها، تقول: أعقبت الطي. وكل طرائق 1 يكون بعضها خلف بعض فهي أعقاب، كأنها منضودة، عقبا على عقب، قال الشماخ: 2 أعقاب طي على الأثباج منضود. يصف طرائق شحم ظهر الناقة. وقد استعقبت من كذا خيرا وشرا. واستعقب من أمره الندامة وتعقب بمعناه. وتعقبت ما صنع فلان: أي تتبعت أثره. والرجلان يتعاقبان الركوب بينهما والأمر، يركب هذا عقبة وهذا عقبة. والعقبة فيما قدروا بينهما فرسخان. والعقوبة: اسم المعاقبة، وهو أن يجزيه بعاقبة ما فعل من السوء، قال النابغة: 3 ومن عصاك فعاقبه معاقبة ... تنهى الظلوم ولا تقعد على ضهد والعقبة: مرقة تبقى في القدر المعارة إذا ردوها إلى صاحبها. وفلان وفلان يعقبان فلانا: إذا تعاونا عليه، وقوله تعالى: له معقبات من بين يديه ومن خلفه يحفظونه من أمر الله 4 أي يحفظونه بأمر الله. والعقبة: طريق في الجبل وعر يرتقى بمشقة وجمعه عقب وعقاب. والعقاب: طائر، تؤنثها العرب إذا رأته لأنها لا تعرف إناثها من ذكورها، فإذا عرفت قيل: عقاب ذكر. ومثله العقرب، ويجمع على عقبان وثلاث 1 أعقب. والعقاب: العلم الضخم تشبيها بالعقاب الطائر، قال الراجز: ولحق تلحق من أقرابها ... تحت لواء الموت أو عقابها 2 والعقاب: مرقى في عرض جبل، وهي صخرة نائتة ناشزة، وفي البئر من حولها، وربما كانت من قبل الطي، وذلك أن تزول الصخرة من موضعها. والمعقب: الذي ينزل في البئر فيرفعها ويسويها. وكل ما مر من العقاب نجمعه عقبان. واليعقوب: الذكر من الحجل والقطا، وجمعه يعاقيب. ويعقوب: اسم اسرائيل، سمي به لأنه ولد مع عيصو أبي الروم في بطن واحد. ولد عيصو قبله، ويعقوب متعلق بعقبه خرجا معا. واشتقاقه من العقب. وتسمى الخيل يعاقيب لسرعتها. ويقال: بل سميت بها تشبيها بيعاقيب الحجل. ومن أنكر هذا احتج بأن الطير لا تركض ولكن شبه بها الخيل، قال سلامة بن جندل: 3 ولى حثيثا وهذا الشيب يتبعه ... لو كان يدركه ركض اليعاقيب. ويقال: أراد بالتعاقيب الخيل نفسها اشتقاقا من تعقيب السير والغزو بعد الغزو. وامرأة معقاب: من عادتها أن تلد ذكرا بعد أنثى. ومفعال في نعت الإناث لا تدخله الهاء. وفي الحديث: قدم رسول الله صلى الله عليه وسلم نصارى نجران: السيد والعاقب ، فالعاقب من يخلف السيد بعده.'),
(97, 'عبق', 'عبق', 'عبق', 'العباقية على تقدير علانية: الرجل ذو شر ونكر، قال: أطف لها عباقية سرندى ... جريء الصدر منسط اليمين 1 والعبق: لزوق الشيء بالشيء. وامرأة عبقة ورجل عبق: إذا تطيب بأدنى طيب فبقي ريحه أياما، قال 2 : عبق العنبر والمسك بها ... فهي صفراء كعرجون القمر. أي لزق. قعب: القعب: القدح الغليظ، ويجمع على قعاب قال: تلك المكارم لا قعبان من لبن ... شيبا بماء فعادا بعد أبوالا والقعبة: شبه حقة مطبقة يكون فيه سويق المرء. والتقعيب في الحافر 3 : إذا كان مقعبا 4 كالقعبة في استدارتها، وهكذا خلقته، قال العجاج 5 : ورسغا وحافرا مقعبا وأنشد ابن الأعرابي: يترك خوار الصفا ركوبا ... بمكربات قعبت تقعيبا'),
(98, 'قبع', 'قبع', 'قبع', 'قبع الخنزير بصوته قبعا وقباعا. وقبع الإنسان قبوعا: أي تخلف عن أصحابه. والقوابع: الخيل المسبوقة قد بقيت خلف السابق، قال: يثابر حتى يترك الخيل خلفه ... قوابع في غمى عجاج وعثير والقباع: الأحمق. وقباع بن ضبة كان من أحمق أهل زمانه، يضرب مثلا لكل أحمق. ويقال: يا ابن قابعاء. ويا ابن قبعة، يوصف بالحمق. ومن النساء القبعة الطلعة: تطلع مرة وتقبع أخرى فترجع. وقبيعة السيف: التي على رأس القائم، وربما اتخذت القبيعة من الفضة على رأس السكين. وقبع: دويبة، يقال من دواب البحر، قال: 1 مأبالي أن تشذرت لنا ... عاديا أم بال في البحر قبع وقبعت السقاء: إذا جعلت رأسه فيه وجعلت بشرته الداخلة.'),
(99, 'بعق', 'بعق', 'بعق', 'البعاق: شدة الصوت. بعقت الإبل بعاقا. والمطر الباعق: الذي يفاجئك بشدة، قال: تبعق فيه الوابل المتهطل والإنبعاق: أن ينبعق الشيء عليك مفاجأة، قال أبو دؤاد: بينما المرء آمنا راعه رائع ... حتف لم يخش منه انبعاقه وقال: تيممت بالكديون كيلا يفوتني ... من المقلة البيضاء تفريط 1 باعق الباعق: المؤذن إذا انبعق بصوته. والكديون 2 يقال الثقيل من الدواب. وبعقت الإبل: نحرتها.'),
(100, 'بقع', 'بقع', 'بقع', 'البقع: لون يخالف بعضه بعضا مثل الغراب الأسود في صدره بياض، غراب أبقع، وكلب أبقع. والبقعة: قطعة من أرض على غير هيئة التي على جنبها. كل واحدة منها بقعة، وجمعها بقاع وبقع. والبقيع: موضع من الأرض فيه أروم شجر من ضروب شتى، وبه سمي بقيع الغرقد بالمدينة والغرقد: شجر كان ينبت. هناك، فبقي الاسم ملازما للموضع وذهب الشجر. والباقعة: الداهية من الرجال. وبقعتهم باقعة من البواقع: أي داهية من الدواهي. وفي الحديث: يوشك أن يعمل عليكم بقعان أهل الشام يريد خدمهم 3 لبياضهم، وشبههم بالشيء الأبقع الذي فيه بياض، يعني بذلك الروم والسودان.'),
(101, 'عقم', 'عقم', 'عقم', '1 حرب عقام وعقام، لغتان، أي شديدة مفنتة لا يلوي فيها أحد على أحد، قال: حفافاه موت ناقع وعقام والعقم: المرط، ويقال: بل هو ثوب يلبس في الجاهلية، ويقال،: كل ثوب أحمر عقم. وعقمت الرحم عقما. وذلك هزمة تقع فيها فلا تقبل الولد. وكذلك عقمت المرأة فهي معقومة وعقيم. ورجل عقيم ورجال عقماء. ونسوة معقومات وعقائم وعقم. قال الاصمعي: يقال: عقم الله رحمها عقما ولا يقال: أعقمها. ويقال: عقمت المرأة تعقم عقما. وفي الحديث: تعقم أصلاب المشركين أي تيبس وتسد. والريح العقيم: التي لا تلقح شجرا ولا تنشىء سحابا ولا مطرا. وفي الحديث: العقل عقلان: فأما عقل صاحب الدنيا فعقيم، وأما عقل صاحب الآخرة فمثمر والملك عقيم أي لا ينفع فيه النسب لأن الابن يقتل على الملك أباه، والأب ابنه. والدنيا عقيم أي لا ترد على صاحبها خيرا. ويقال: ناقة معقومة أي لا تقبل رحمها الولد، قال: معقومة أو عازر جدود والاعتقام: الدخول في الأمر، قال رؤبة 1 : بذي دهاء يفهم التفهيما ... ويعتفي بالعقم التعقيما وقال: ولقد دريت بالاعتفاء ... والاعتقام فنلت نجحا 2 يقول: إذا لم يأت الأمر سهلا عقم فيه وعفا حتى ينجح. والمعاقم: المفاصل. ويقال للفرس إذا كان شديد الرسغ: إنه لشديد المعاقم، قال النابغة: يخطو على معج عوج معاقمها ... يحسبن أن تراب الأرض منتهب والتعقيم: إبهام الشيء حتى لا يهتدى له.'),
(102, 'عمق', 'عمق', 'عمق', 'بئر عميقة وقد عمقت عمقا. وأعمقها حافرها. (والعمقى 3 : نبت. وبعير عامق، وإبل عامقة: تأكل العمقى، وهو أمر من الحنطل، قال الشاعر: فأقسم أن العيش حلو إذا دنت ... وهو إن نأت عني أمر من العمقى والعمقى أيضا: موضع في الحجاز يكثر فيه هذا الشجر، قال أبو ذؤيب: لما ذكرت أخا العمقى تأدبني ... هم وأفرد ظهري الأغلب الشيح والعمق كزفر: موضع بمكة، وقول ساعدة بن جؤية: لما رأى عمقا ورجع عرضه ... هدرا كما هدر الفنيق المصعب أراد: العمق فغير. وما في النحي عمقة، كقولك: ما به عبقة أي لطخ ولا وضر من رب ولا تمن. وعمق النظر في الأمور تعميقا وتعمق في كلامه: تنطع. وتعمق في الأمر: تشدق فيه فهو متعمق. وفي الحديث: لو تمادى الشهر لواصلت وصالا يدع المتعمقون تعمقهم. والمتعمق: المبالغ في الأمر المنشود فيه، (الذي يطلب أقصى غايته) والعمق والعمق: ما بعد من أطراف المفاور. والأعماق، أطراف المفاوز البعيدة، وقيل: الأطراف ولم تقيد، ومنه قول رؤبة: وقاتم الأعماق خاوي المخترق ... مشتبه الأعلام لماع الخفق وأعامق: موضع، قال الشاعر. وقد كان منا منزلا نستلذه ... أعامق، برقاواته فأجادله'),
(103, 'معق', 'معق', 'معق', 'المعق: البعد في الأرض سفلا. بئر معيقة، ومعقت معاقة. وبئر معقة أيضا والعمق والمعق لغتان، يختارون العمق أحيانا في بئر ونحوها إذا كانت ذاهبة في الأرض، ويختارون المعق أحيانا في الأشياء الأخر مثل الأودية والشعاب البعيدة في الأرض، إلا أنهم لا يكادون يقولون: فج معيق، بل عميق. والمعنى كله يرجع إلى البعد والقعر الذاهب في الأرض. والفج العميق. المصر البعيد. ويصفون أطراف الأرض بالمعق والعمق، قال رؤبة: كأنها وهي تهادى في الرفق ... من جذبها شبراق شد ذي معق 1 أي ذي بعد في الأرض، وقال أيضا: وقاتم الأعماق خاوي المخترق يريد الأطراف البعيدة. والأمعاق 1 كذلك، والأماعق: أطراف المفاوز البعيدة. (والمعق: الشرب الشديد) 2 ، ومنه قول رؤبة: وإن همى من بعد معق معقا 3 ... عرفت من ضرب الحرير عتقا أي من بعد بعد بعدا، وقد تحرك مثل نهر ونهر . قعم: قعم وأقعم الرجل: إذا أصابه الطاعون فمات من ساعته. وأقعمته الحية: لدغته فمات من ساعته. والقعم: ردة في الأنف أي ميل، قال الراجز: علي ضفان 4 مهدمان ... مشتبها الأنف مقعمان والمقعمة: مسمار في طرف الخشبة معقف الرأس'),
(104, 'قمع', 'قمع', 'قمع', 'قمعت فلانا فانقمع: أي ذللته فذل واختبأ فرقا والقمع ما فوق السناسن من سنام البعير من أعلاه، قال علينا قرى الأضياف من قمع البزل والقمع: شيء يصب به الشراب في القربة ونحوها، وجمعه أقماع 1 ويكون الواحد قمع وقمع جميعا، ويكون لأشياء كثيرة مثل ذلك. والمقمعة: خشبة يضرب بها الإنسان على رأسه والجميع المقامع. والمقمعة: مسمار يكون في طرف الخشبة معقف الرأس قال عرام: المقمعة: المقطرة وهي الأعمدة والحوزة أيضا. قال: ويمشي معد حوله بالمقامع والأذنان: قمعان مقع: المقع: شدة الشرب. والفصيل يمقع: إذا رضع أمه. وامتقع لونا وانتقع 2 : أي تغير. والميقع: داء يأخذ البعير مثل الحصبة فيقع فلا يقوم فينحر، قال جرير: جرت فتاة مجاشع في مقفر ... غير المراء كما يجر الميقع 3'),
(105, 'عكش', 'عكش', 'عكش', 'عكش على القوم: حمل عليهم 1 . عكاشة: اسم. قلت للخليل: من أين قلت (عكش) مهمل، وقد سمت العرب بعكاشة؟ قال: ليس على الأسماء قياس. وقلنا لأبي الدقيش. ما الدقيش؟ قال: لا أدري، ولم 2 أسمع له تفسيرا. قلنا: فتكنيت بما لا تدري؟ قال: الأسماء والكنى علامات، من شاء تسمى بما شاء، لا قياس ولا حتم.'),
(106, 'شكع', 'شكع', 'شكع', 'شكع الرجل شكعا فهو شاكع إذا كثر أنينه وضجره من شدة المرض. وشكع الغضبان أي: طال غضبه. والشكاعى نبات دقيق 3 العود رخو. ويقال للمهزول: كأنه عود شكاعى، وكأنه شكاعى. قال ابن أحمر 4 : شربت الشكاعى والتددت ألدة ... وأقبلت أفواه العروق المكاويا'),
(107, 'عكس', 'عكس', 'عكس', 'العكس: ردك آخر الشيء على أوله. قال: 2 وهن لدى الأكوار 3 يعكسن بالبرى ... على عجل منها ومنهن نزع 4 ويقال: عكست أي عطفت على معني النسق. ويعكس: يطرد. والعكيس من اللبن: الحليب يصب عليه الإهالة ثم يشرب، ويقال: بل هو مرق يصب على اللبن. قال: 5 فلما سقيناها العكيس تملأت ... مذاخرها وارفض رشحا وريدها مذاخرها: حوايا بطنها. والتعكس: مشي كمشي الأفعى، كأنه قد يبست عروقه. والسكران يتعكس 6 في مشيه إذا مشى كذلك.'),
(108, 'كعس', 'كعس', 'كعس', 'الكعس: عظام السلامى، وجمعه: كعاس، وهو أيضا عظام البراجم من الأصابع، ومن الشاء أيضا وغيرها،'),
(109, 'كسع', 'كسع', 'كسع', 'الكسع: ضرب يد أو رجل على دبر شيء وكسعهم، وكسع أدبارهم إذا تبع أدبارهم فضربهم بالسيف. وكسعته بما ساءه إذا تكلم فرميته على إثر قوله بكلمة تسوؤه بها. وكسعت الناقة بغبرها 1 إذا تركت بقية اللبن في ضرعها 2 وهو أشد لها، قال: 3 لا تكسع الشول بأغبارها ... إنك لا تدري من الناتج هذا مثل. يقول: إذا نالت يدك ممن بينك 4 [وبينه] 5 إحنة فلا تبق على شيء، لأنك لا تدري ما يكون في غد، وقال الليث: لا تدع في خلفها لبنا تريد قوة ولدها، فإنك لا تدري من ينتجها، أي لمن يصير ذلك الولد. وقال أبو سعيد: الكسع كسعان، فكسع للدرة، وهو أن ينهز الحالب ضرعها فتدر، أو ينهزه الولد. والكسع 6 لآخر: أن تدع ما اجتمع في ضرعها، ولا تحلبه حتى يتراد اللبن في مجاريه ويغزر. وقوله: لا تكسع الشول بأغبارها أي: احلب وافضل. والكسع 7 حي من اليمن رماة. قال: 8 ندمت ندامة الكسعي لما ... رأت عيناه ما عملت يداه والكسعة: ريش أبيض يجتمع تحت ذنب العقاب ونحوها من الطير. وجمعه: كسع. والكسعة الحمير والدواب كلها، سميت كسعة لأنها تكسع من خلفها.'),
(110, 'سكع', 'سكع', 'سكع', 'سكع فلان إذا مشى متعسفا، لا يدري أين يسكع من أرض الله، أي أين يأخذ. قال 1 : ألا إنه في غمرة يتسكع'),
(111, 'عسك', 'عسك', 'عسك', '[تقول:] 2 عسكت بالرجل أعسك عسكا إذا لزمته ولم تفارقه'),
(112, 'عكز', 'عكز', 'عكز', 'العكازة: عصا في أسفلها زج يتوكأ عليها، ويجمع عكازات وعكاكيز 3'),
(113, 'عكد', 'عكد', 'عكد', 'العكدة: أصل اللسان وعقدته. وعكد الضب عكدا. أي: سمن وصلب لحمه فهو عكد. واستعكد الضب اذا لاذ بحجر أو جحر. واستعكد الطائر إلى كذا: انضم إليه مخافة. البازي ونحوه. قال: 1 اذا استعكدت 2 منه بكل كداية ... من الصخر وافاها لدى كل مسرح 3 هذه ضباب استعصمت من الذئب فهو لا يقدر أن يحفر الكدية وهو ما صلب من الأرض وكذلك الكداية. دعك الأديم ونحوه 4 والثوب والخصم دعكا إذا لينه ومعكه. قال: 5 قرم قروم صلهبا ضباركا ... من آل مر جخدبا 6 مداعكا'),
(114, 'دكع', 'دكع', 'دكع', 'الدكاع داء يأخذ الخيل والإبل في صدورها، وهو كالخبطة في الناس. دكع فهو مدكوع. قال القطامي: 7 ترى منه صدور الخيل زورا ... كأن بها نحازا أو دكاعا'),
(115, 'عتك', 'عتك', 'عتك', 'عتك فلان عليه يضربه: لا ينهنهه عنه شيء. وعتك فلان يعتك عتوكا: ذهب في الأرض وحده. وعتك الشيء: إذا قدم وعتق. وعاتكة: اسم امرأة. عتيك 1 : قبيلة من اليمن، والنسبة إليه: عتكي.'),
(116, 'كتع', 'كتع', 'كتع', 'الكتع: من أولاد الثعالب وهو أردؤها 2 . ويجمع: كتعان. ورجل كتع: لئيم. وقوم كتعون وأكتع: حرف يوصل به أجمع تقوية له (ليست له عربية) 3 ومؤنثه كتعاء. تقول: جمعاء كتعاء، وجمع كتع وأجمعون أكتعون، كل هذا توكيد.'),
(117, 'عكظ', 'عكظ', 'عكظ', 'عكاظ اسم سوق كان العرب يجتمعون فيها كل سنة شهرا ويتناشدون ويتفاخرون ثم يفترقون، فهدمه الإسلام، وكانت فيها وقائع. يقول فيها دريد بن الصمة: 4 تغيبت عن يومى عكاظ كليهما ... وإن يك يوم ثالث أتغيب وهو من مكة على مرحلتين أو ثلاث، قريب من ركبة والركبة من السي 5 يقال: أديم عكاظي، منسوب إلى عكاظ، وسمي به لأن العرب كانت تجتمع كل سنة فيعكظ بعضها بعضا بالمفاخرة والتناشد، أي يدعك ويعرك. وفلان يعكظ خصمه بالخصومة: يمعكه.'),
(118, 'كعظ', 'كعظ', 'كعظ', 'الكعيظ المكعظ: القصير الضخم من الناس'),
(119, 'كثع', 'كثع', 'كثع', 'يقال: شفة ولثة كاتعة، أي: كادت تنقلب من كثرة 2 دمها، وامرأة مكثعة، والفعل كثعت تكثع كثوعا. قال أبو أحمد: مكثعة 3 على غير قياس وعسى أن 4 تكلمت به العرب. وعن غير الخليل: لبن مكثع، أي: قد ظهر زبده فوقه.'),
(120, 'عكر', 'عكر', 'عكر', 'عكر على الشيء يعكر عكورا وعكرا، وهو انصرافه عليه بعد مضيه [عنه] 6 واعتكر الليل إذا اختلط سواده والتبس. قال: 7 تطاول الليل علينا واعتكر واعتكرت الريح إذا جاءت بالغبار. قال: 1 وبارح معتكر الأشواط يصف بلدا. أي: من ساره يحتاج إلى أن يعيد شوطا بعد شوط في السير. واعتكر العسكر: أي رجع بعضه على بعض فلا يقدر على عده. قال رؤبة: 2 إذا أرادوا أن يعدوه اعتكر والعكر: رديء النبيذ والزيت. يقال: عكرته تعكيرا. والعكر: القطيع الضخم من الإبل فوق خمسمائة 3 قال: 4 فيه الصواهل والرايات والعكر قال حماس: 5 رجال معتكرون، أي كثير.'),
(121, 'عرك', 'عرك', 'عرك', 'عركت الأديم عركا: دلكته. وعركت القوم في الحرب عركا. قال جرير: 6 قد جربت عركي في كل معترك 7 واعترك القوم للقتال والخصومة، والموضع: المعترك، والمعركة. وعريكة البعير: سنامه إذا عركه الحمل. قال سلامة بن جندل: 8 نهضنا إلى أكوار عيس تعركت ... عرائكها شد القوى بالمحازم أي: انكسرت أسنمتها من الحمل. وقال: 1 خفاف الخطى مطلنفئات العرائك أي: قد هزلت فلصقت أسنمتها بأصلابها. وفلان لبن العريكة: أي: ليس ذا إباء فهو سلس. وأرض معروكة عركتها السائمة بالرعي فصارت جدبة. وعركت الشاة عركا: جسستها وغبطتها، لأنظر سمنها، الغبط أحسن الجس، وأما العرك فكثرة الجس. وناقة عروك: لا يعرف سمنها من هزالها إلا بجس اليد لكثرة وبرها. ولقيته عركة بعد عركة: أي مرة بعد مرة، وعركات: مرات. وامرأة عارك، أي: طامث. وقد عركت تعرك عراكا، قال: 2 لن تغسلوا أبدا عارا أظلكم ... غسل العوارك حيضا بعد أطهار ويروى: لن ترحضوا، ورحض العوارك. ورجل عرك، وقوم عركون، وهم الأشداء الصراع. والعرك عرك [مرفق البعير جنبه] 3 قال [الطرماح] : 4 قليل العرك يهجر 5 مرفقاها ... خليف رحى كقرزوم القيون أي: (كعلاة) 6 القيون. والخليف: 7 ما بين العضد والكركرة. ويهجر: يتنحى عن. والرحى: [الكركرة] 8 . والعركرك: الركب الضخم من اركاب النساء. وأصله من الثلاثي ولفظه خماسي، إنما هو من العرك فأردف بحرفين 1 . وعركت القوم في الحرب عركا. قال [زهير] : وتعرككم عرك الرحى بثفالها 2'),
(122, 'كعر', 'كعر', 'كعر', 'كعر الصبي كعرا فهو كعر: إذا امتلأ بطنه من كثرة الأكل. وكعر البطن، وكل شيء يشبه هذا المعنى فهو الكعر. وأكعر البعير اكتنز سنامه وكبر، فهو مكعر. قال الضرير: إذا حمل [الحوار] 3 أول الشحم فهو مكعر.'),
(123, 'كرع', 'كرع', 'كرع', 'كرع في الماء يكرع كرعا وكروعا: إذا تناوله بفيه. وكرع في الإناء: أمال عنقه نحوه فشرب. قال [النابغة] : وتسقي إذا ما شئت غير مصرد ... بزوراء في أكنافها المسك كارع 4 قوله: بزوراء، أي: بسقاية يشرب بها. سميت زوراء لا زورار البصر فيها من شدة ما صقلت. ورجل كرع: غلم، وامرأة كرعة: غلمة وكرعت المرأة إلى الفحل تكرع كرعا. والكراع من الإنسان ما دون الركبة، ومن الدواب ما دون الكعب. تقول: هذه 5 كراع، وهو الوظيف نفسه. قال: 1 يا نفس لا تراعي ... إن قطعت كراعي إن معي ذراعي ... رعاك خير راعي وثلاثة أكرع. قال سيبويه: الكراع: الماء الذي يكرع فيه. الأكرع من الدواب: الدقيق القوائم. وقد كرع كرعا. وكراع كل شيء طرفه، مثل كراع الأرض، أي: ناحيتها. والكراع: اسم الخيل، إذا قال الكراع والسلاح فإنه الخيل نفسها. ورجلا الجندب كراعاه قال أبو زيد: 2 ونفى الجندب الحصى بكراعيه ... وأذكت نيرانها المعزاء [والكراع أنف سائل من جبل أو حرة] 3 ويقال [الكراع] 4 من الحرة ما استطال منها. قال الشماخ: 5 وهمت بورد القنتين فصدها ... مضيق الكراع والقنان اللواهز'),
(124, 'ركع', 'ركع', 'ركع', 'كل قومة من الصلاة ركعة، وركع ركوعا. وكل شيء ينكب لوجهه فتمس ركبته الأرض أولا تمس [ها] 6 بعد أن يطأطىء رأسه فهو راكع. قال لبيد: 7 أخبر أخبار القرون التي مضت ... أدب كأني، كلما قمت، راكع وقال: ولكني أنص العيس تدمى ... أظلاها وتركع بالحزون 1'),
(125, 'عكل', 'عكل', 'عكل', 'عكل يعكل السائق الخيل والإبل عكلا إذا حازها وضم قواصيها 2 وساقها قال [الفرزدق] 3 وهم على صدف الأميل تداركوا ... نعما تشل إلى الرئيس وتعكل والعكل لغة في العكر. وعكل قبيلة فيهم غفلة وغباوة يقال لكل من به غفلة: عكلي. قال: 4 [جاءت به عجز مقابلة] 5 ... ما هن من جرم ولا عكل والعوكل ظهر الكثيب، الواو إشباع، وبناؤه ثلاثي. قال: 6 بكل عقنقل [أو رأس] برث ... وعوكل كل قوز [مستطير] 7'),
(126, 'علك', 'علك', 'علك', 'علكت الدابة اللجام علكا [حركته في فيها] 8 قال [النابغة] [خيل صيام وخيل غير صائمة] 1 ... تحت العجاج وأخرى تعلك اللجما والعلكة: الشقشقة عند الهدير. قال رؤبة: يجمعن زارا وهديرا محضا 2 ... في علكات يعتلين النهضا أي: إن ناهضت فحولا غلبتها. وسمي العلك لأنه يعلك، أي: يمضغ.'),
(127, 'كلع', 'كلع', 'كلع', 'الكلع: شقاق أو وسخ يكون بالقدم. كلعت رجله كلعا، وكلع البعير كلعا وكلاعا: انشق فرسنه والنعت: كلع [والأنثى كلعة] 3 ويقال لليد أيضا. وإناء كلع مكلع إذا التبد عليه الوسخ. قال حميد بن ثور: 4 وجاءت بمعيوف الشريعة مكلع ... أرشت عليه بالأكف السواعد السواعد: مجاري اللبن في الضرع. والكلعة: داء يأخذ البعير (فيجرد شعره عن مؤخره ويسود) 5 ورجل كلع، أي أسود، سواده كالوسخ. وأبو الكلاع: ملك من ملوك اليمن.'),
(128, 'لكع', 'لكع', 'لكع', 'لكع الرجل يلكع لكعا ولكاعة فهو ألكع ولكع ولكيع ولكاع وملكعان ولكوع.. وامرأة لكاع ولكيعة وملكعانة، كل ذلك يوصف به [من به] الحمق والموق واللؤم. ويقال اللكع اللئيم من الرجال 1 . ويقال: ملكعان إلا في النداء، يا ملكعان ويا مخبثان ويا محمقان ويا مرقعان. وقال: 2 عليك بأمر نفسك يا لكاع ... فما من كان مرعيا كراعي ويقال: اللكع العبد.'),
(129, 'عكن', 'عكن', 'عكن', 'العكن: الأطواء في بطن الجارية السمينة، ويجوز جارية عكناء، ولم يجزه الضرير، قال: ولكنهم يقولون: معكنة. وواحدة العكن: عكنة. قال [الأعشي:] 3 إليها وإن حسرت أكلة ... يوافي لأخرى عظيم العكن وتعكن الشيء تعكنا، أي: آرتكم بعضه على بعض، وانثني.'),
(130, 'عنك', 'عنك', 'عنك', 'العانك: لون من الحمرة. دم عانك، وعرق عانك: في لونه صفرة. والعانك من الرمل: الذي في لونه حمرة. قال ذو الرمة: 4 على أقحوان في حناديج حرة ... يناصي حشاها عانك متكاوس والعنك: سدفة من الليل. يقال مضى من الليل عنك. والعنك: الباب بلغة اليمن'),
(131, 'كنع', 'كنع', 'كنع', 'الكنع: تشنج في الأصابع وتقبض. وقد كنع كنعا فهو كنع، [أي] 1 شنج. قال: 2 أنحى أبو لقط حزا بشفرته ... فأصبحت كفه اليمنى بها كنع وقال ابن أحمر: ترى كعبه قد كان كعبين مرة ... وتحسسبه قد عاش دهرا مكنعا وتكنع فلان بفلان، أي تضبث به وتعلق. وكنع الموت يكنع كنوعا، أي: اقترب قال الأحوص: يلوذ حذاء الموت والموت كانع 3 وكنعت العقاب إذا ضمت جناحيها للانقضاض، فهي كانعة جانحة. قال: 4 قعودا على أبوابهم يثمدونهم ... رمى الله في تلك الأكف الكوانع وأكنع الشيء: لان وخضع. قال: 5 من نفثه والرفق حتى أكنعا والاكتناع: العطف. اكتنع عليه، أي: عطف. والاكتناع: الاجتماع. قال: 6 ساروا جميعا حذار الكهل فاكتنعوا ... بين الإياد وبين الهجفة الغدقة وكنعان بن سام بن نوح إليه ينسب الكنعانيون وكانوا يتكلمون بلغة تقارب العربية 1');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(132, 'نكع', 'نكع', 'نكع', 'الأنكع: المتقشر الأنف مع حمرة لون شديدة. وقد نكع ينكع. ونكعة الطرثوث: نبت من أعلاه إلى أسفله قدر إصبع، وعليه قشر أحمر كأنه نقط. ونكعه مثل كسعه إذا ضرب بظهر قدمه على دبره. قال: 2 بني ثعل لا تنكوا. العنز إنه ... بني ثعل من ينكع العنز ظالم يقول: العنز سمحة الدرة، تحتاج إلى أن تنكع كما تنكع النعجة، يقول: أحسنوا الحلب. ويقال: أنكعه الله، أي: أبغضه.'),
(133, 'عكف', 'عكف', 'عكف', 'عكف يعكف ويعكف عكفا وعكوفا وهو إقبالك على الشيء لا تصرف عنه وجهك. قال العجاج يصف حميرا وفحلا: 3 فهن يعكفن به إذا حجا ... عكف النبيط يلعبون الفنزجا أي: وقفن وثبتن. وقرىء 4 يعكفون على أصنام لهم 5 ويعكفون. ولو قيل: عكف في المسجد لكان صوابا، ولكن يقولون: اعتكف. قال الله عز وجل: والعاكفين 1 وعكفت الطير بالقتيل. ويقال للنظم إذا نضد فيه الجوهر: عكف تعكيفا. قال الأعشى: 2 وكأن السموط عكفها السلك ... بعطفي جيداء أم غزال'),
(134, 'عفك', 'عفك', 'عفك', 'الأعفك: الأحمق. وقال أبو ليلى: الأعفك: الذي لا يحسن عملا، ولا خير عنده. قال: 3 صاح ألم تعجب لقول الضيطر ... الأعفك الأحدل ثم الأعسر'),
(135, 'عكب', 'عكب', 'عكب', 'العكب: غلظ في لحي الإنسان. وأمة عكباء: علجة جافية الخلق من آم عكب. وفي لغة الخفجيين: عكبت حولهم الطير فهي طير عكوب أي: عكوف. قال شاعرهم: 4 تظل نسور من شمام [عليهم] 5 ... عكوبا من العقبان عقبان يذبل'),
(136, 'عبك', 'عبك', 'عبك', 'يقال: ما ذقت عبكة ولا لبكة. العبكة: قطعة من شيء أو كسرة. واللبكة: لقمة من ثريدة ونحوها. قال عرام: العبكة ما ثردته من خبز، وعبكت بعضه فوق بعض، واللبك سمن تصبه على الدقيق، أو السويق ثم ترويه.'),
(137, 'كعب', 'كعب', 'كعب', 'الكعب: العظيم لكل ذي أربع، وكعب الإنسان: ما أشرف فوق رسغه عند قدمه، وكعب الفرس: عظم الوظيف، وعظم ناتىء من الساق من خلف. والكعبة: البيت الحرام، وكعبته تربيع أعلاه. وأهل العراق يسمون البيت المربع: كعبة. وإنما قيل: كعبة البيت فاضيف إليه، لأن كعبته تربع أعلاه. وبيت لربيعة كانوا يطوفون به يسمونه: ذا الكعبات. قال [الأسود بن يعفر] 1 أهل الخورنق والسدير وبارق ... والبيت ذي الكعبات من سنداد وكعبت الجارية تكعب كعوبة وكعابة فهي كعاب، وكاعب. وتكعب ثدياها. وثدي كاعب ومتكعب. وقد كعب تكعيبا. كل ذلك قد قيل. والثوب المكعب المطوي الشديد الإدراج كعبته تكعيبا. والكعبة: الغرفة. والكعب من القصب ونحوه معروف. ويجمع على كعوب. والكعب من السمن قدر صبة أو كيلة. قال عرام: إذا كان جامدا ذائبا لا يسمى كعبا. ويقال: كعبت الشيء إذا ملأته تكعيبا. وكعاب الزرع عقد قصبة وكعابره.'),
(138, 'كبع', 'كبع', 'كبع', 'الكبع: نقد الدراهم ووزنها. قال الراجز: 1 قالوا لي اكبع قلت: لست كابعا أي: الغرام 2 قالوا له: انقد لنا، وزن لنا.'),
(139, 'بكع', 'بكع', 'بكع', 'البكع: شدة الضرب المتتابع، تقول: بكعناه بالعصا والسيف بكعا وبكعته بالكلام إذا وبخته، بكعة يبكعه بكعا.'),
(140, 'عكم', 'عكم', 'عكم', 'يقال: عكمت المتاع أعكمه عكما إذا بسطت ثوبا وجمعت فيه متاعا فشددته فيكون حينئذ عكمة. والعكمان عدلان يشدان من جانبي الهودج. قال أبو ليلى: هما شبه الحقيبتين تكون فيهما ثياب النساء [و] 3 تكون على البعير والهودج فوقهما، وأنشد: أيا رب 4 زوجني عجوزا كبيرة ... فلا جد لي يا رب في الفتيات تحدثني عما مضى من شبابها ... وتطعمني من عكمها تمرات وعكم فلان عنا 5 عكاما، أي: رد عن زيارتنا. قال: 6 ولاحته من بعد الحرور ظماءة ... ولم يك عن ورد المياه عكوم أي: منصرف، وتقول: ما عن هذا الأمر عكوم، أي: لا بد من مواقعته. ويقال للدابة إذا شربت فامتلأ بطنها: ما بقيت في جوفها هزمة ولا عكمة 1 إلا امتلأت. قال: 2 حتى إذا ما بلت العكوما ... من قصب الأجواف والهزوما يقال: الهزم: داخل الخاصرة، والعكم داخل الجنب.'),
(141, 'كعم', 'كعم', 'كعم', 'كعم يكعم الرجل المرأة كعما وكعوما: إذا قبلها فاعتكم فاها، والكعام: شيء يجعل 3 في فم البعير، ويجمع: أكعمة، كعمته أكعمه كعما. قال ذو الرمة: 4 يهماء خابطها بالخوف مكعوم 5 وتقول: كعمه الخوف فلا ينبس 6 بكلمة. والكعم: شيء من الأوعية يوعى فيه السلاح، وجمعه: كعام.'),
(142, 'كمع', 'كمع', 'كمع', 'كامعتها: ضممتها إلى [أصونها] 7 . والمكامع: المضاجع، واشتقاقه من ذلك. والكميع الضجيع. قال ذو الرمة: 8 ليل التمام إذا المكامع ضمها ... بعد الهدو من الخرائد تسطع'),
(143, 'معك', 'معك', 'معك', 'المعك: دلكك الشيء في التراب. والتمعك: الفعل اللازم، والتمعيك متعد 1 وهو التقلب في التراب، كما تتمعك الدابة. ومعكته بالقتال والخصومة [لويته] 2 ومعكني ديني، أي لواني. وقال: 3 لزاز خصم ممعك 4 مهون ورجل معك: شديد الخصومة قال زهير: 5'),
(144, 'جشع', 'جشع', 'جشع', 'الجشع: الحرص الشديد على الأكل وغيره. وقوم جشعون. وجشع يجشع.'),
(145, 'شجع', 'شجع', 'شجع', 'الشجع في الإبل: سرعة نقل القوائم. جمل شجع، وناقة شجعة. ويقال: شجعاء. ويقال: هو الذي يعتريه جنون من الإبل، وهو خطأ، إذ لو كان جنونا لما وصف به قوائمها في قوله: 1 على شجعات لا شخات 2 ولا عصل يعني بالشجعات: قوائم الإبل، وقال سويد 3 يصف النوق: بصلاب الأرض فيهن شجع والشجعة من النساء: الجريئة الجسورة على الرجال في كلامها وسلاطتها واللبؤة الشجعاء الجسورة الجريئة، وكذلك الأشجع من الأسد، والأشجع من الرجال الذي كأن به جنونا. قال الأعشى: 4 بأشجع أخاذ على الدهر حكمه'),
(146, 'ضجع', 'ضجع', 'ضجع', 'ضجع فلان ضجوعا، أي نام، فهو ضاجع، وكذلك اضطجع. وأصل هذه الطاء تاء، ولكنهم استقبحوا أن يقولوا: اضتجع. وأضجعته: وضعت جنبه بالأرض. وضجع هو ضجعا. وكل شيء خفضته فقد أضجعته. وضجيعك الذي يضاجعك في فراشك. والإضجاع في القوافي: أن تميلها: قال 2 يصف الشعر: والأعوج الضاجع من إكفائها يعني إكفاء القوافي. وتقول: أضجع رأيه لغيره'),
(147, 'عجس', 'عجس', 'عجس', '1 العجس: شدة القبض على الشيء. ومعجس القوس: مقبضها، قال: 2 انتضوا معجس القسي وأبرقنا ... كما توعد الفحول الفحولا وقيل: عجس القوس عجزها. وعجس القوم: اخرهم وعجزهم. وعجاساء الليلة: ظلمتها. قال العجاج: 3 منها عجاساء إذا ما التجت. والعجاساء المسان من الإبل. قال: 4 وإن بركت منها عجاساء جلة ... بمحنية أشلى العفاس وبروعا'),
(148, 'عسج', 'عسج', 'عسج', 'العسج: مد العنق في المشي. والعوسج: شجر كبير الشوك، وهو ضروب شتى، وقال في العسج: 5 والعيس من عاسج أو واسج خببا وقال: 1 عسجن بأعناق الظباء وأعين الجآذر ... وارتجت لهن الروادف'),
(149, 'جعس', 'جعس', 'جعس', 'الجعس: العذرة. جعس يجعس جعسا. والجعسوس: اللئيم القبيح الخلقة والخلق، والجمع: الجعاسيس. قال العجاج: 2 ليس بجعسوس ولا بجعشم 3'),
(150, 'سجع', 'سجع', 'سجع', 'سجع الرجل إذا نطق بكلام له فواصل كقوافي الشعر من غير وزن كما قيل: لصها بطل، وتمرها دقل، إن كثر الجيش بها جاعوا، وإن قلوا ضاعوا 4 يسجع سجعا فهو ساجع وسجاع وسجاعة. والحمامة تسجع سجعا إذا دعت، وهي سجوع ساجعة، وحمام سجع سواجع. قال: 5 إذا سجعت حمامة بطن وج وقال: 6 وإن سجعت هاجت لك الشوق سجعها ... وإن قرقرت هاج الهوى قرقريرها أي: قرقرتها.'),
(151, 'عجز', 'عجز', 'عجز', 'أعجزني فلان إذا عجزت عن طلبه وإدراكه. والعجز نقيض الحزم. وعجز يعجز عجزا فهو عاجز ضعيف. قال الأعشي: 2 فذاك ولم يعجز من الموت ربه والعجوز: المرأة الشيخة. ويجمع عجائز، والفعل: عجزت. وعجزت تعجز عجزا، وعجزت تعجيزا، والتخفيف أحسن. ويقال للمرأة: اتقي 3 الله في شيبتك، وعجزك، أي: حين تصيرين عجوزا. وعاجز فلان: حين ذهب فلم يقدر عليه. وبهذا التفسير: وما أنتم بمعجزين في الأرض 4 * والعجز: مؤخر الشيء، وجمعه أعجاز. والعجوز: الخمر. والعجوز: نصل السيف. قال أبو المقدام: وعجوزا رأيت في بطن كلب ... جعل الكلب للأمير حمالا 5 يريد: ما فوق النصل من جانبيه حديدا أو فضة. والعجيزة عجيزة المرأة إذا كانت ضخمة، وامرأة عجزاء وقد عجزت عجزا قال: من كل عجزاء سقوط البرقع بلهاء لم تحفظ، ولم تضيع وتجمع العجيزة عجيزات، ولا يقولون: عجائز مخافة الالتباس. والعجزاء من الرمل خاصة رملة مرتفعة كأنها جبل ليس بركام رمل، وهي مكرمة المنبت وجمعه: عجز، لأنه نعت لتلك الرملة. والعجز داء يأخذ الدابة في عجزها فتثقل. والنعت: أعجز وعجزاء. والعجزة وابن العجزة آخر ولد الشيخ ... 1 ويقال: ولد لعجزة، أي: ولد بعد ما كبر أبواه. قال: 2 واستبصرت في الحي أحوى أمردا ... عجزة شيخين يسمى معبدا'),
(152, 'جزع', 'جزع', 'جزع', 'الجزع: الواحدة: جزعة من الخرز. قال امرؤ القيس: 3 كأن عيون الوحش حول خبائنا ... وأرحلنا الجزع الذي لم يثقب والجزع: قطعك المفازة عرضا. قال: جازعات بطن [العقيق] 4 كما تمضي ... رفاق أمامهن رفاق وجزعنا الأرض: سلكناها عرضا خلاف طولها. وناحيتا الوادي: جزعاه، ويقال: لا يسمى جزع الوادي جزعا حتى تكون له سعة تنبت الشجر وغيره، واحتج بقول لبيد: كأنها ... أجزاع ببشة أثلها ورضامها 5 قال: ألا ترى أنه ذكر الأثل! ويقال: بل يكون جزعا بغير نبات وربما كان رملا. ومعه: أجزاع. والجازع: الخشبة التي توضع بين الخشبتين منصوبتين عرضا 1 لتوضع عليها عروش الكرم وقضبانها، ليرفعها عن الأرض، فإن نعتها قلت: خشبة جازعة، وكذلك كل خشبة بين شيئين ليحمل عليها (شيء فهي) 2 جازعة. والمجزع من البسر ما قد تجزع فأرطب بعضه وبعضه بسر بعد. وفلان يسبح بالنوى المجزع أي: الذي يصير على هيئة الجزع من الخرز. والجزعة من الماء واللبن: ما كان أقل من نصف السقاء [أو] 3 نصف. الإناء والحوض. والجزع: نقيض الصبر. جزع على كذا جزعا فهو [جزع و] 4 جازع وجزوع. وفي الحديث: أتتنا جزيعة 5 من الغنم.'),
(153, 'زعج', 'زعج', 'زعج', 'الإزعاج: نقيض القرار، أزعجته من بلاده فشخص، ولا يقال: فزعج. ولو قيل: انزعج وازدعج لكان صوابا وقياسا. قال الضرير: لا أقوله، ولكن يقال: أزعجته فزعج زعجا.'),
(154, 'عجد', 'عجد', 'عجد', 'العجد: الزبيب، وهو حب العنب أيضا، ويقال: بل هو ثمرة غير الزبيب شبيهة به، ويقال: بل هي العنجد. لا يعرف عرام إلا العنجد 1 .'),
(155, 'جعد', 'جعد', 'جعد', 'رجل جعد الشعر، وشعر جعد، وقد جعد يجعد جعودة. وجعدها صاحبها تجعيدا. ويجمع الجعد جعادا. وقال: 2 قد تيمتني طفلة أملود ... بفاحم زينه التجعيد ورجل جعد اليدين: بخيل بملك يده. قال: 3 ما قابض الكفين إلا جعد ويقال للقصير الأصابع: جعد الأصابع. وزبد جعد إذا صار على خطم البعير بعضه فوق بعض. قال: واعتم بالزبد الجعد الخراطيم 4 والجعودة في الخدين أيضا. وثرى جعد يعني التراب الندي. (يقال: ثرى جعد ثعد: ند) 1 . والذئب يكنى أبا جعدة من بخله. قال: 2 هي الخمر تكنى [بأم] 3 الطلا ... كما الذئب يكنى أبا جعده يعني: هذه كنية باطلة ككنية الذئب. وبنو جعدة: حي من قيس. وبعير جعد: كثير الوبر. والجعدة: حشيشة تنبت على شاطىء الأنهار لها رعثة مثل رعثة الديك طيبة الريح تنبت بالربيع وتيبس في الشتاء، وهي من البقول تحشي بها المرافق 4 . قال أبو ليلى: هي من الأصول التي تشبه البقول. لها أصل مجتمع وعروق كثيرة، والبقلة: التي لها عرق واحد.'),
(156, 'جدع', 'جدع', 'جدع', 'الجدع: قطع الأنف والأذن والشفة، جدعته أجدعه جدعا وهو مجدوع وأنا جادع. واذا لزمت النعت فهو أجدع والأنثي جدعاء. وبه جدع، ولا يقال: قطع. ولا يقال: قد جدع ولكن جدع، ألا ترى أنك تقول: رجل أقطع وبه قطع، ولا يقال قطع. والجدعة: موضع الجدع من المجدوع [قال سيبويه، يقال: جدعته، أي: قلت له: جدعا] 5 والجداع: 6 السنة التي تذهب بكل شيء وجديع: اسم الكرماني الأزدي. والجدع: السيء الغذاء، وقد أجدعته.'),
(157, 'دعج', 'دعج', 'دعج', 'الدعج: شدة سواد العين وشدة بياضه. رجل أدعج، وامرأة دعجاء، وعين دعجاء. ويقال: الدعج: شدة سواد سواد العين، وشدة بياض بياضها. والدليل على ذلك بيت جميل حيث يقول: سوى دعج العينين والنعج الذي ... به قتلتني حين أمكنها قتلي وقال العجاج: 1 تسور في أعجاز ليل أدعجا جعله أدعج لشدة سواده وبياض الصبح.'),
(158, 'جعظ', 'جعظ', 'جعظ', 'يقال الجعظ للسيء الخلق الذي يتسخط عند الطعام.'),
(159, 'جذع', 'جذع', 'جذع', 'الجذع من الدواب قبل أن يثني بسنة، ومن الأنعام هو أول ما يستطاع ركوبه. والأنثي جذعة، ويجمع على جذاع وجذعان وأجذاع أيضا. والدهر يسمى جذعا لأنه جديد. قال: 2 يا بشر لو لم أكن منكم بمنزلة ... ألقى علي يديه الأزلم الجذع صير الدهر أزلم لأن أحدا لا يقدر أن يكدح فيه. يقال: قدح مزلم، أي: مسوى، وفرس مزلم إذا كان مصنعا وقال بعضهم: الأزلم الجذع في هذا البيت هو الأسد، وهذا خطأ أنما هو الدهر، يقول: لولا أنتم لأهلكني الدهر. وإذا طفئت الحرب من القوم يقال: إن شئتم أعدناها جذعة، أي أول ما يبتدأ بها. وفلان في هذا الأمر جذع، أي: أخذ فيه حديثا. والجذع النخلة، وهو غصنها 1'),
(160, 'عثج', 'عثج', 'عثج', 'العثج والثعج والأول أنسب: 2 جماعة من الناس في السفر. قال: 3 ثعج: لا هم لولا أن بكرا دونكا ... يبرك الناس ويفجرونكا ما زال منا عثج يأتونكا يريدون بيتك، والعثوجج: البعير السريع الضخم، المجتمع الخلق، يقال: اعثوثج اعثيثاجا، لم يعرفه عرام.'),
(161, 'عجر', 'عجر', 'عجر', 'الأعجر: الضخم الوسط من الناس، وقد عجر يعجر عجرا. والعجرة: موضع العجر منه. والأعجز: كل شيء ترى فيه عقدا. كيس أعجز، وبطن أعجز إذا امتلأ جدا. قال: عنترة: أبني زبيبة ما لمهركم ... متخددا وبطونكم عجر 1 وأنشد أبو ليلى: حسن الثياب يبيت أعجر طاعما ... والضيف من حب الطعام قد التوى والعجرة: خروج السرة. وفي الحديث: أذكر عجره وبجره 2 والخليج 3 ذو عجر. والعجر [جمع عجرة] 4 كل عقدة في خشبة أو غيرها. وكذلك المعجر حتى يقال: هذا سيف أعجر، وفي وسطه عجرة، ومعجر. وحافر عجر، أي: صلب شديد. قال: 5 سائل شمراخه ذي جبب ... سلط السنبك في رسغ عجر والاعتجار: لف العمامة على الرأس من غير إدارة تحت الحنك، وأنشد أبو ليلى: 6 جاءت به معتجرا ببرده ... سفواء تخدي بنسيج وحده والمعجر: ثوب تعتجر به المرأة، أصغر من الرداء، وأكبر من المقنعة. قال زائدة: معجر من المعاجر ثياب تكون باليمن. العجير من الخيل كالعنين من الرجال.'),
(162, 'عرج', 'عرج', 'عرج', 'عرج الأعرج يعرج عرجا. والأنثي عرجاء. وأعرج الله الأعرج فعرج هو، وفلان يتعارج إذا مشى يحكى الأعرج. والعرجة: موضع العرج من الرجل. وجمع الأعرج عرجان. والعرجاء: الضبع، خلقه فيها. وجمعه: عرج.. أعيرج: حية صماء لا تقبل الرقية، وتطفر كما تطفر الأفعى وجمعه: أعيرجات. قال أبو ليلى: العرج من الإبل ثمانون إلى تسعين فإذا بلغت مائة فهي هنيدة، وجمعه: أعرج وعروج. قال طرفة بن العبد البكري: 1 يوم تبدي البيض عن أسوقها ... وتلف الخيل أعراج النعم ويقال: العرج: القطيع الضخم من الإبل نحو خمسمائة 2 ، وجمعه: أعراج. قال: 3 فقسم عرجا كأسه فوق كفه ... وجاء بنهب كالفسيل المكمم والعرج من الإبل كالحقب وهو الذي لا يستقيم بوله [لفصده من ذكره] 4 يقال: عرج الجمل وحقب. وعرج يعرج عروجا، أي: صعد. والمعرج: المصعد. والمعرج: الطريق الذي تصعد فيه الملائكة. والمعراج شبه سلم أو درجة تعرج الأرواح فيه إذا قبضت. يقال ليس شيء أحسن منه، إذا رآه الروح لم يتمالك أن يخرج، ولو جمع على المعاريج لكان صوابا. والمعارج في قول الله عز وجل: من الله ذي المعارج تعرج الملائكة والروح إليه 5 جماعة المعرج. ولغة هذيل: يعرج ويعكف، هم مولعون بالكسر. والتعريج: حبسك مطيتك ورفقتك مقيما على رفقتك أو لحاجة. وما لنا عرجة بموضع كذا، أي: مقام. قال: يا حاديي أم فضاض أما لكما ... حتى نكلمها هم بتعريج وانعرج الطريق والبئر والوادي إذا مال، ومنعرجه حيث يميل يمنة ويسرة. وانعرج القوم عن الطريق، أي: مالوا عنه. وعرجنا النهر، أي: أملناه يمنة ويسرة. والعرنجج: اسم حمير، واشتقاقه من العرج.'),
(163, 'رعج', 'رعج', 'رعج', 'الإرعاج: تلألؤ البرق وتفرقه في السماء. قال العجاج: 1 سحا أهاضيب وبرقا مرعجا'),
(164, 'جعر', 'جعر', 'جعر', 'الجعر ما يبس في الدبر من العذرة، أو خرج يابسا. ولا يقال للكلب إلا جعر يجعر. والجعراء حي يعيرون بذلك. قال: 2 دعت كندة الجعراء بالحي مالكا ... وتدعو بعوف تحت ظل القواصل والضبع تسمى جعار لكثرة جعرها، والأنثي أم جعار. والجاعرتان حيث يكوى الحمار من مؤخره على كاذتي فخذيه 3 والجعار: الحبل الذي يشد به المستقي من البئر وسطه لئلا يقع في البئر. قال: الراجز 4 ليس الجعار مانعي من القدر'),
(165, 'جرع', 'جرع', 'جرع', 'جرعت الماء أجرعه جرعا، واجترعته. وكل شيء يبلعه الحلق فهو اجتراع. والاسم الجرعة وإذا جرعه بمرة قيل: اجترعه. والاجتراع، بالماء كالابتلاع بالطعام. والتجرع: تتابع [الجرع] 1 مرة بعد مرة. والجرعاء من الأرض: ذات حزونة تسفي عليها الرياح فتغشيها، وإذا كانت صغيرة فاسمها الجرعة وجمعها جراع. وإذا كانت واسعة جدا [فهي] 2 أجرع كله، ويجمع أجارع. وجمع الجرعاء: جرعاوات. قال: أتنسي بلائي 3 غداة الحروب ... وكري على القوم بالأجرع وقال ذو الرمة: 4 بجرعائك البيض الحسان الخرائد'),
(166, 'رجع', 'رجع', 'رجع', 'رجعت رجوعا ورجعته يستوي فيه اللازم والمجاوز. والرجعة المرة الواحدة. والترجيع: تقارب ضروب الحركات في الصوت. هو يرجع في قراءته، وهي قراءة أصحاب الألحان. والقينة والمغنية ترجعان في غنائهما. وترجيع وشي النقش والوشم والكتابة خطوطها. والرجع: ترجيع الدابة يدها في السير. قال: 5 يعدو به نهش المشاش كأنه ... صدع سليم رجعه لا يظلع شبه الفرس في عدوه بصدع. وهو الفتي من الأوعال. ورجع الجواب: رده. ورجع الرشق من الرمي: ما يرد عليه. والمرجوعة: جواب الرسالة. قال: 1 لم تدر ما مرجوعة السائل يصف الدار، تقول: ليس في هذا البيع مرجوع، أي: لا يرجع فيه. ويقال: يريد: ليس فيه فضل ولا ربح، والارتجاع 2 أن ترتجع شيئا بعد أن تعطي. وارتجع الكلب في قيئه. قال: أن الحباب عاد في عطائه ... كما يعود الكلب في تقيائه والرجعة: مراجعة الرجل أهله بعد الطلاق. وقوم يؤمنون بالرجعة إلى الدنيا قبل يوم القيامة. والاسترجاع أن تقول: إنا لله وإنا إليه راجعون 3 قال الضرير: أقول: رجع، ولا أقول استرجع. وكلام رجيع: مردود إلى صاحبه. يقال: هذا الكلام رجيع فيما بيننا. والرجيع من الدواب ما رجعته من السفر إلى السفر، والأنثى رجيعة. قال: ذو الرمة: 4 رجيعة أسفار كأن زمامها ... شجاع لدى يسرى الذراعين مطرق والرجيع: الروث. قال الأعشي: 5 ليس فيها إلا الرجيع علاق ويقال: الرجيع: الجرة. قال حميد: 6 رددن رجيع الفرث حتى [كأنه] ... حصي إثم بين الصلاء سحيق يصف إبلا تردد جرتها. قال الضرير: يصف الرماد فأما الجرة ففي البيت الأول. والرجع: المطر نفسه. والرجع: نبات الربيع. قال: 1 وجاءت سلتم لا رجع فيها ... ولا صدع [فتحتلب] الرعاء السلتم: السنة الشديدة، وهي الداهية أيضا. والرجعان من الأرض ما ارتد فيه من السيل ثم نفذ.'),
(167, 'عجل', 'عجل', 'عجل', 'العجل: العجلة وربما قيل [رجل] 2 عجل وعجل، لغتان. واستعجلته، أي: حثثته وأمرته أن يعجل في الأمر. وأعجلته وتعجلت خراجه، أي: كلفته أن يعجله. وعجل يا فلان، أي: عجل أمرك. ورجل عجلان، وامرأة عجلى، وقوم عجال، ونساء عجالى. والعجل عجل الثيران، ويجمع على أعجال. والعجلة: المنجنون يستقى عليها، وجمعه: عجل وعجلات. والعجلة: المزادة، والإداوة الصغيرة، ويجمع على عجال وعجل. قال: 3 على أن مكتوب العجال وكيع وقال الأعشى: 1 والرافلات على أعجازها العجل قال أبو ليلى: العجلة: المطهرة والمزادة. والعجلة ضرب من الجنبة من نبات الصيف والاعجالة: ما يعجله الراعي من اللبن إلى أهله. قال الكميت: 2 أتتكم بإعجالاتها وهي حفل ... تمج لكم قبل احتلاب ثمالها والعجول من الإبل الواله التي فقدت ولدها، ويجمع على عجل. قالت الخنساء: 3 فما عجول على بو تطيف به ... قد ساعدتها على التحنان أظار والعاجلة: الدنيا، والآجلة: الاخرة. والعاجل: نقيض الآجل. عام في كل شيء، يقال: عجل وأجل. وبعضهم يفسر قول الله خلق الإنسان من عجل 4 أنه الطين والله أعلم. والعجول لغة في عجل البقرة. والأنثي: عجولة، وجمعها: عجاجيل. وقد تجيء في الشعر نعتا للإبل السراع، والقوائم الخفاف. والعجول: قطعة من أقط. والعجالة من اللبن ويجمع على عجال. والعجالة: ما استعجل به من طعام، فقدم قبل إدراك الغداء، وهو العجل أيضا. قال: 5 أن لم تغثني أكن يا ذا الندى عجلا ... كلقمة وقعت في شدق غرثان'),
(168, 'علج', 'علج', 'علج', 'العلج من معلوجاء العجم، وجمعه: علوج. والعلج: حمار الوحش لاستعلاج خلقه، أي: غلظه. والرجل إذا خرج وجهه وغلظ فهو علج. وقيل: قد استعلج. والعلاج مزاولة كل شيء ومعالجته. وعالجت فلانا فعلجته إذا غلبته، والعلج من الرجال الشديد القتال، والنطاح. قال العجاج: 1 منا [خراطيم] 2 ورأسا علجا واعتلج القوم: اتخذوا صراعا وقتالا، واعتلاج الأمواج: التطامها. والعلجان: شجر أخضر لا تأكله [الإبل والغنم إلا مضطرة] 3 رمل عالج: موضع بالبادية. قال: 4 أو حيث رمل عالج تعلجا 5 تعلجه: اجتماعه. وبنو علاج قبيلة.'),
(169, 'جعل', 'جعل', 'جعل', 'جعل جعلا: صنع صنعا، وجعل أعم، لأنك تقول: جعل يأكل، وجعل يصنع كذا، ولا تقول: صنع يأكل. والجعل: ما جعلت لإنسان أجرا له على عمل يعمله، والجعالة أيضا. والجعالات: ما يتجاعل الناس بينهم عند بعث أو أمر يحزبهم من السلطان. والجعل: دابة من هوام الأرض. والجعل، واحدها جعلة: وهي النخل الصغار. والجعال والجعالة: خرقة تنزل بها القدر عن رأس النار يتقى بها من الحر. قال: 1 كمنزل قدرا بلا جعالها وأجعلت الكلبة 2 إذا أرادت السفاد. وماء مجعل وجعل، أي: ماتت فيه الجعلان والخنافس. ورجل جعل يشبه بالجعل لسواده، وفطس أنفه وانتشاره.'),
(170, 'جلع', 'جلع', 'جلع', 'المجالعة: التنازع عند شرب أو قمار أو قسمة. قال: 3 ولا فاحش عند الشراب مجالع وروى عرام: مجالح أي مكابر. وقال عرام: المجالعة: أن يستقبلك بما لم تفعله ويبهتك به. والجلعلع من الإبل: الحديدة النفس الشديدة.'),
(171, 'لعج', 'لعج', 'لعج', 'لعج الحزن يلعج لعجا وهو حرارته في الفؤاد. لعجه الحزن أبلغ إليه. قال: 4 بمكتمن من لاعج الحزن واتن أي: دائم قد دخل الوتين. ويقال: الحب يلعج. قال: فوا كبدا من لاعج الحب والهوى ... إذا اعتاد نفسي من أميمة عيدها 5'),
(172, 'عجن', 'عجن', 'عجن', 'عجن يعجن عجنا [فهو عجين] 1 إذا عجن الخمير وناقة عجناء: كثيرة لحم الضرع مع قلة لبن [وكذا الشاة والبقرة] 2 [يقال] 3 عجنت تعجن عجنا وهي حسنة 4 المرآة 5 قليلة اللبن. والمتعجن من الإبل: المكتنز سمنا كأنه لحم بلا عظم. والعجان اخر الذكر ممدود في الجلد الذي يستبرئه البائل، وهو القضيب الممدود من الخصية إلى الدبر. وثلاثة أعجنة ويجمع على عجن. والعجان: الأحمق. ويقال: إن فلانا ليعجن 6 بمرفقيه حمقا.'),
(173, 'عنج', 'عنج', 'عنج', 'العناج: خيط أو سير يشد في أسفل الدلو ثم يشد في عروته فإذا انقطع الحبل أمسك العناج الدلو من أن تقع في البئر، وكل شيء يجعل له ذلك فهو عناج. وثلاثة أعنجة، وجمعه عنج. وكل شيء تجذبه إليك فقد عنجته. عنج رأس البعير، أي: جذبه إليه بخطامه. قال الحطيئة: شدوا العناج وشدوا فوقه الكربا 7 و [عنجة] 1 الهودج: عضادة عند بابه [يشد بها] 2 الباب. والعنج بلغة هذيل هو الرجل، ويقال بالغين، وهذيل تقول: عنج على شنج، أي: رجل على جمل. والعنجوج: الرائع من الخيل، ومن النجائب، ويجمع عناجيج. قال: نحن صبحنا عامرا وعبسا ... جردا عناجيج سبقن الشمسا أي: طلوعها'),
(174, 'جعن', 'جعن', 'جعن', 'جعونة: اسم رجل من البادية. قال مبتكر 3 : بنو جعونة بطن من بني تميم.'),
(175, 'نعج', 'نعج', 'نعج', 'نعج اللون نعجا إذا ابيض، ونعوجا أيضا وهو البياض الخالص. وامرأة ناعجة اللون، أي: حسنته. وجمل ناعج، وناقة ناعجة: حسنة اللون مكرمة. والناعجة من الأرض: السهلة المستوية مكرمة للنبات تنبت الرمث. قال أبو ليلى: تنبت أطايب العشب والبقل. والنعجة من الإناث، من الضأن والبقر الوحشي والشاء الجبلي، وجمعه: نعاج. وكني عن المرأة فسميت نعجة. قال الله عز وجل: ولي نعجة واحدة 4 ومنعج: موضع بالبادية، ويقال منعج: واد لبني كلاب من ضرية، قال: منا فوارس منعج وفوارس ... شدوا وثاق الحوفزان (تأودا) 5 وإذا أكل القوم لحم ضأن فثقل عليهم فهم نعجون ورجل نعج قال: 1 كأن القوم عشوا لحم ضأن ... فهم نعجون قد مالت طلاهم'),
(176, 'نجع', 'نجع', 'نجع', 'النجعة: طلب الكلأ والخير. وانتجعت أرض كذا في طلب الريف. وانتجعت فلانا لطلب معروفه. ونجع في الإنسان طعام ينجع نجوعا أي: هنأه واستمرأه. ونجع فيه قولك أي: أخذ فيه. والنجيع: دم الجوف. قال ذو الرمة في الانتجاع: رأيت الناس ينتجعون غيثا ... فقلت لصيدح: انتجعي بلالا 2 والناجعة القوم ينتجعون.'),
(177, 'عجف', 'عجف', 'عجف', 'عجفت نفسي عن الطعام أعجفها عجفا وعجوفا، أي: حبست وأنا أشتهيه لأوثر به جائعا، ولا يكون العجف إلا على الجوع. وعجفت نفسي على المريض أعجفها عجفا، أي: صبرت فأقمت عليه أعينه وأمرضه. قال: 3 إني وإن عيرتني نحولي ... أو ازدريت عظمي وطولي لأعجف النفس على خليلي ... أعرض بالود وبالتنويل أي أعرض له بالمودة والنوال. وعجفت له نفسي، أي: حملت عنه، ولم أؤاخذه. والعجف: ذهاب السمن. رجل أعجف وامرأة عجفاء، وتجمع على عجاف، ولا يجمع أفعل على فعال غير هذا، رواية شاذة عن العرب حملوها على لفظ سمان. والعجاف من أسماء التمر. قال: 1 نعاف وإن كانت خماصا بطوننا ... لباب المصفى والعجاف المجردا'),
(178, 'عفج', 'عفج', 'عفج', 'العفجة: من أمعاء البطن، وهي لكل ما لا يجتر كالممرغة من الشاء وهي كالكيس من الإنسان كأنها حوصلة الطائر فيما يقال. وقد يجمعون الأمعاء بالأعفاج، الواحد: عفج وعفج. وعفجه بالعصا: ضربه بها. والعفنجج: كل ضخم اللهازم من الرجال ذي وجنات وألواح أكول فسل 2 ، بوزن فعنلل، ويقال: هو الأخرق الجافي الذي لا يتجه لعمل، قال: 3 منهم وذا الخنابة 4 العفنججا والعفج معروف'),
(179, 'جعف', 'جعف', 'جعف', 'الجعف: شدة الصرع. جعفته فانجعف، قال: إذا دخل الناس الظلال فإنه ... على الحوض حتى يصدر الناس منجعف 5 أي قد رمى بنفسه. وجعفي: حي 6 . والنسبة إليه: جعفي على لفظه.'),
(180, 'فجع', 'فجع', 'فجع', 'الفجع: أن يفجع الإنسان بشيء يكرم عليه فيعدمه. فجع بماله وولده، ونزلت به فاجعة من فواجع الدهر. قال: أن تبق تفجع بالأحبة كلها ... وفناء نفسك لا أبا لك أفجع 1 ويقال لغراب البين: فاجع، لأنه يفجع الناس بالبين. قال: بشير صدق أعان دعوته ... بصعقه مثل فاجع شجب 2 وموت فاجع. ودهر فاجع يفجع الناس بالأحداث. والرجل يتفجع، وهو توجعه للمصيبة. والفجيعة الاسم كالرزية. أنشد عرام: كأنها نائحة تفجع ... تبكي لميت وسواها الموجع'),
(181, 'عجب', 'عجب', 'عجب', 'عجب عجبا، وأمر عجيب عجب عجاب. قال الخليل: بينهما فرق. أما العجيب فالعجب، وأما العجاب فالذي جاوز حد العجب، مثل الطويل والطوال. وتقول: هذا العجب العاجب، أي: العجيب. والاستعجاب: شدة التعجب، وهو مستعجب ومتعجب مما يرى. وشيء معجب، أي: حسن. وأعجبني وأعجبت به. وفلان معجب بنفسه إذا دخله العجب. وعجبته بكذا تعجيبا فعجب منه. والعجب من كل دابة: ما ضمت عليه الوركان من أصل الذنب المغروز في مؤخر العجز. تقول: لشد ما عجبت وذلك إذا دق مؤخرها، وأشرفت جاعرتاها، وهي خلقة قبيحة فيمن كانت. وناقة عجباء بينة العجب والعجبة. وعجوب الكثبان أواخرها المستدقة. قال لبيد: بعجوب كثبان يميل هيامها 1'),
(182, 'جعب', 'جعب', 'جعب', 'جعبت جعبة، أي: اتخذت كنانة. والجعابة صنعة الجعاب. والجعبى: ضرب من النمل أحمر، ويجمع جعبيات. والجعبوب: الدنيء من الرجال. قال: تأمل للملاح مخضبات ... إذا انجعب البعيث ببطن وادي أي: مات البعيث الذي عجز عن المرأة. والجعباء: الدبر قال: بشار: سهيل بن عمار يجود ببره ... كما جاد بالجعبا سهيل بن سالم 2 ويروى: بالوجعاء.'),
(183, 'بعج', 'بعج', 'بعج', 'بعج فلان بطن فلان بالسكين، أي: شقه وخضخضه فيه، وتبعج السحاب إذا انفرج عن الودق. قال: 3 حيث استهل المزن [أو] 1 تبعجا وبعج المطر في الأرض تبعيجا من شدة فحصه الحجارة. وبعجه [حب] 2 فلان إذا اشتد وجده وحزن له. ورجل بعج كأنه مبعوج البطن من ضعف مشيه 3 . قال: ليلة أمشي على مخاطرة ... مشيا رويدا كمشية البعج باعجة [الوادي حيث ينبعج أي: يتسع] 4 . و [بنو بعجة] 5 بطن.'),
(184, 'عجم', 'عجم', 'عجم', 'العجم: ضد العرب. ورجل أعجمي: ليس بعربي وقوم عجم وعرب والأعجم: الذي لا يفصح. وامرأة عجماء بينة العجمة. والعجماء: كل دابة أو بهيمة. وفي الحديث: جرح العجماء جبار 6 يقول: إذا أفلتت الدابة فقتلت إنسانا فليس على صاحبها دية وجبار، أي: باطل، هدر دمه. والعجماء كل صلاة لا يقرأ فيها. والأعجم: كل كلام ليس [بلغة] 7 عربية إذا لم ترد بها النسبة. قال أبو النجم: صوتا مخوفا عندها مليحا ... أعجم في آذانها فصيحا يصف حمار الوحش. وتقول: اسعجمت الدار عن جواب السائل. والمعجم حروف الهجاء المقطعة، لأنها أعجمية. وتعجيم الكتاب: تنقيطه كي تستبين عجمته ويصح. وعجمة الرمل أكثره واضخمه وأكثره تراكما في وسط الرمل. قال ذو الرمة: من عجمة الرمل أنقاء لها حبب 1 وعجم التمر نواه 2 والإنسان يعجم التمرة إذا لاكها بنواتها في فمه. وعجيم النوى: الذي قد قشر لحاؤه من التمر. وعجمت العود: عضضت عليه بأسناني أيها أصلب. قال عبد الله بن سبرة الجرشي: وكم عاجم عودى أضر بنابه ... مذاقي ففي نابيه فرض فلول وقال الحجاج بن يوسف: إن أمير المؤمنين نكب كنانته فعجم عيدانها فوجدني أصلبها 3 . قوله: عجم، أي: عض عليها بأسنانه لينظر أيها أصلب، وهذا مثل، أي: جرب الرجال فاختارني منهم. والثور يعجم قرنه يدلكه بشجرة لينظفه. وما عجمتك عيني مذ كذا، أي: ما أخذتك. وتقول للرجل العزيز النفس: أنه لصلب المعجم. أي: إذا عجمته الأمور وجدته متينا. وقال سعد بن مسمع: ذا سبحة لو كان حلو المعجم أي: ذا جمال. وهذا من سبحات الوجه، وهو محاسنه، ولأنك إذا رأيته قلت: سبحان الله. وقوله: لو كان حلو المعجم، أي: لو كان محمود الخبر كان قد تم أمره ولكنه جمال دون خبر. قال أبو ليلى: المعجم: هاهنا المذاق. عجمته: ذقنه. قال الأخطل: يا صاح هل تبلغنها ذات معجمة ... بدايتيها ومجرى نسعها بقع 1'),
(185, 'عمج', 'عمج', 'عمج', 'التعمج: الاعوجاج في السير، والمشي لليدين والأعضاء لاعوجاج الطريق كتعمج السيل إذا انقلب بعضه على بعض. قال: 2 تدافع السيل إذا تعمجا'),
(186, 'جعم', 'جعم', 'جعم', 'امرأة جعماء: أنكر عقلها هرما، ولا يقال رجل أجعم. وناقة جعماء: مسنة. ورجل جعم وامرأة جعمة، وبها جعم، أي: غلظ كلام في سعة حلق. وجعم الرجل جعما، أي: قرم إلى اللحم، وهو في ذاك أكول. قال: العجاج 3 إذ جعم الذهلان كل مجعم أي: جعموا إلى الشر، كما يقرم إلى اللحم.'),
(187, 'جمع', 'جمع', 'جمع', 'الجمع مصدر جمعت الشيء. والجمع أيضا: اسم لجماعة الناس، والجموع: اسم لجماعة الناس. والمجمع حيث يجمع الناس، وهو أيضا اسم للناس والجماعة: عدد كل شيء وكثرته. والجماع: ما جمع عددا، فهو جماعه، كما تقول لجماع الخباء: أخبية قال الحسن: اتقوا هذه الأهواء التي 1 جماعها الضلالة ومعادها إلى النار. وكذلك الجميع إلا أنه اسم لازم. يقال: رجل جميع، أي: مجتمع في خلقه. وأما المجتمع فالذي استوت لحيته، وبلغ غاية شبابه، ولا يقال للنساء. والمسجد الجامع نعت به، لأنه يجمع أهله، ومسجد الجامع خطأ بغير الألف واللام، لأن الاسم لا يضاف إلى النعت. لا يقال: هذا زيد الفقيه. وتقول: جمع الناس، أي: شهدوا الجمعة، وقضوا الصلاة. وجماع كل شيء: مجتمع خلقه، فمن ذلك: جماع جسد الإنسان رأسه، وجماع الثمرة ونحوها إذا اجتمعت براعيمها في موضع واحد. قال ذو الرمة: ورأس كجماع الثريا ومشفر ... كسبت اليماني قده لم يحرد 2 وتقول: ضربته بجمع كفي، ومنهم من يكسر الجيم. وأعطيته من الدراهم جمع الكف كما تقول: ملء الكف. وماتت المرأة بجمع، أي: مع ما في بطنها 3 [وكذلك 4 ] يقال إذا ماتت عذراء. وترك فلان امرأته بجمع وسار، أي: تركها وقد أثقلت. واستجمع للمرء أموره إذا استجمع وهيء له ما يسر به من أمره. قال: 5 إذا استجمعت للمرء فيها أموره ... كبا كبوة للوجه لا يستقيلها واستجمع السيل: أي: اجتمع، واستجمع الفرس جريا. قال: 1 ومستجمع جريا وليس ببارح ... تباريه في ضاحي المتان سواعده وسمي جمع 2 جمعا، لأن الناس يجتمعون إليها من المزدلفة بين الصلاتين، المغرب والعشاء الاخرة. والمجامعة والجماع: كناية عن الفعل، والله يكني عن الأفعال، قال الله عز وجل: أو لامستم النساء* 3 كنى عن النكاح'),
(188, 'معج', 'معج', 'معج', 'المعج: التقليب في الجري. معج الحمار يمعج معجا، أي: جرى في كل وجه جريا سريعا. قال العجاج: 4 حني منه غير ما أن يفحجا ... غمر الأجاري مسحا ممعجا وحمار معاج: يسبق في عدوه يمينا وشمالا. والريح تمعج في النبات، أي 5 : تفليه وتقلبه. قال ذو الرمة: أو نفحة من أعالي حنوة معجت ... فيها الصبا موهنا والروض مرهوم 6 والفصيل يمعج ضرع أمه إذا لهزه، وقلب فاه في نواحيه 7 ليستمكن. وتقول: جاءنا الوادي يمعج بسيوله، أي: يسرع. قال: 8 ضافت تمعج أعناق السيول به'),
(189, 'مجع', 'مجع', 'مجع', 'مجع الرجل مجعا، وتمجع تمجعا 1 إذا أكل التمر باللبن. والمجاعة: فضالة ما يمجع. والاسم: المجيع. قال: 2 إن في دارنا ثلاث حبالى ... فوددنا لو قد وضعن جميعا جارتي ثم هرتي ثم شاتي ... فإذا ما وضعن كن ربيعا جارتي للخبيص والهر للفأر ... وشاتي إذا اشتهيت مجيعا ورجل مجاععة، أي: كثير التمجع، مثل: علامة ونساببة. قال الخليل: يدخلون هذه الهاءات في نعوت الرجال للتوكيد.'),
(190, 'شسع', 'شسع', 'شسع', 'يقال: شسعت النعل تشسيعا، وأشسعته إشساعا، أي: جعلت [لها] 3 شسعا. واشسع: السير نفسه، وجمعه: شسع. قال: 4 أحدو بها منقطعا شسعني أراد: شسعي، فأدخل النون على البناء حتى استقامت قافيته. والشاسع: المكان البعيد. وشسع يشسع شسوعا. قال: 5 لقد علمت أفناء بكر بن وائل ... بأنا نزور الشاسع المتزحزحا'),
(191, 'عشز', 'عشز', 'عشز', 'العشوز من الأرض والمواضع: ما صلب مسلكه، وخشن من [طريق] 1 أو أرض، ويجمع على عشاوز. قال الشماخ: 2'),
(192, 'عطش', 'عطش', 'عطش', 'رجل عطشان، وامرأة عطشى، وفي لغة، عطشانة، وهو عاطش غدا، ويجمع على: عطاش. والفعل: عطش يعطش عطشا. والمعاطش: مواقيت الظمء. قال: 3 لا تشتكى سقطة منها وقد رقصت ... بها المعاطش حتى ظهرها حدب والمعاطش: الأرضون التي لا ماء بها. الواحدة: معطشة. وعطشت الإبل تعطيشا إذا ازددت على ظمئها في حبسها عن الماء تكون نوبتها [اليوم] 4 الثالث أو الرابع فتسقيها فوق ذلك بيوم. وإذا حبستها دون ذلك قلت: أعطشتها، كما قال الأعرابي: أعطشناها لأقرب الوقتين، والمعطش: المحبوس عن الورد عمدا، وزرع معطش: قد عطش عطشا.'),
(193, 'شعذ', 'شعذ', 'شعذ', 'الشعوذة: خفة في اليد، وأخذ كالسحر يري غير ما عليه الأصل من عجائب يفعلها كالسحر في رأي العين. والشعوذي أظن اشتقاقه منه لسرعته وهو الرسول على البريد لأمير. ورجل مشعوذ، وفعله: الشعوذة، ويقال: مشعبذ والشعوذي: كلمة ليست من كلام العرب وهي كلمة عالية.'),
(194, 'شعث', 'شعث', 'شعث', 'يقال: رجل أشعث شعث شعثان الرأس، وقد شعث شعثا وشعاثا وشعوثة وشعثته أنا تشعيثا، وهو المغبر الرأس، المتلبد الشعر جافا غير دهين. والتشعث كتشعث رأس السواك. وأشعث: اسم الوتد لتشعث رأسه. قال ذو الرمة: 1 وأشعث عاري الضرتين مشجج'),
(195, 'عشر', 'عشر', 'عشر', 'العشر: عدد المؤنث، والعشرة 2 : عدد المذكر، فإذا جاوزت ذلك أنثت المؤنث وذكرت المذكر. وتقول: عشر نسوة، وإحدى عشرة امرأة، وعشرة رجال، وأحد عشر رجلا وثلاثة عشر رجلا تلحق الهاء في ثلاثة وتنزعها من عشرة، ثم تقول: ثلاث عشرة امرأة تنزع الهاء من ثلاثة وتلحقها بالعشرة. وعشرت القوم: صرت عاشرهم، وكنت عاشر عشرة: أي: كانوا تسعة فتموا بي عشرة. وعشرتهم تعشيرا: أخذت العشر من أموالهم، وبالتخفيف أيضا، وبه سمي العشار عشارا والعشر: جزء من عشرة أجزاء، وهو العشير والمعشار. والعشر: ورد الإبل [ال] يوم العاشر. وفي حسابهم: العشر: التاسع. وإبل عواشر: وردت الماء عشرا. ويجمع [العشر] 3 ويثنى، فيقال: عشران وعشرون، وكل عشر من ذلك: تسعة أيام. ومثله: الثوامن والخوامس. قال ذو الرمة: 1 أقمت لهم أعناق هيم كأنها ... قطا نش عنها ذو جلاميد خامس يعني بالخامس: القطا التي وردت الماء خمسا. والعرب تقول: سقينا الإبل رفها أي: في كل يوم، وغبا إذا أوردوا يوما، وأقاموا في الرعي يوما، وإذا أوردوا يوما، وأقاموا في الرعي يومين ثم أوردوا [ال] يوم 2 الثالث قالوا: أوردنا ربعا، ولا يقولون ثلثا أبدا، لأنهم يحسبون يوم الورد الأول والآخر، ويحسبون يومي المقام بينهما، فيجعلون ذلك أربعة. فإذا زادوا على العشرة قالوا: أوردناها رفها بعد عشر. قال الليث: قلت للخليل: زعمت أن عشرين جمع عشر، والعشر تسعة أيام، فكان ينبغي أن يكون العشرون سبعة وعشرين يوما، حتى تستكمل ثلاثة أتساع. فقال الخليل: ثماني عشر يوما عشران [ولما كان اليومان من العشر الثالث مع الثمانية عشر يوما] 3 سميته بالجمع. قلت: من أين جاز لك ذلك، ولم تستكمل الأجزاء الثلاثة؟ هل يجوز أن تقول للدرهمين ودانقين: ثلاثة دراهم؟ قال: لا أقيس على هذا ولكن أقيسه على قول أبي حنيفة، ألا ترى أنه قال: [إذا] 4 طلقتها تطليقتين وعشر تطليقة [ف] هي ثلاث تطليقات، وليس من التطليقة الثالثة في الطلاق ألا عشر تطليقة، فكما جاز لأبي حنيفة أن يعتد بالعشر جاز لي أن أعتد باليومين. وتقول: جاء القوم عشار عشار ومعشر معشر، أي: عشرة عشرة و [أحاد أحاد] 5 ومثنى مثنى وثلاث ثلاث، إلى عشرة، نصب بغير تنوين. وعشرت [هم] 1 تعشيرا، أي: كانوا تسعة فزدت واحدا [حتى تم عشرة، وعشرت، خفيفة، أخذت واحدا] 2 من عشرة فصار [وا] 3 تسعة، فالعشور نقصان والتعشير تمام. والمعشر [الحمار] 4 الشديد النهاق المتتابع، سمي به، لأنه لا يكف حتى يبلغ بع عشر نهقات وترجيعات. قال: 5 [لعمري لئن] عشرت من خشية الردى ... نهاق [الحمير] إني لجزوع وناقة عشراء، أي: أقربت، وسميت به لتمام عشرة أشهر لحملها. عشرت تعشيرا، فهي بعد ذلك عشراء حتى تضع، والعدد: عشراوات، والجميع: العشار، ويقال: بل سميت عشراء لأنها حديثة العهد بالتعشير، والتعشير: حمل الولد في البطن، يقال: عشراء بينة التعشير. يقال: بل العشار اسم النوق التي قد نتج بعضها وبعضها قد أقرب ينتظر نتاجها. قال الفرزدق: 6 كم خالة لك يا جرير وعمة ... فدعاء قد حلبث علي عشاري قال بعضهم: ليس للعشار لبن، وإنما سماها عشارا لأنها حديثة العهد بالتعشير وهي المطافيل. والعاشرة: حلقة من عواشر المصحف. ويقال للحلقة: التعشير. [والعشر] 1 : قطعة تنكسر من البرمة أو القدح، فهو أعشار. قال: 2 وقد يقطع السيف اليماني وجفنه ... شباريق أعشار عثمن على كسر وقدور أعشار لا يكاد يفرد العشر من ذلك. قدور أعاشير، أي: مكسرة على عشر قطع. تعشار موضع معروف، يقال: بنجد ويقال: لبني تميم. والعشر: شجر له صمغ. يقال له: سكر العشر. والعشرة: المعاشرة. يقال: أنت أطول به عشرة، وأبطن به خبرة. قال زهير: 3 لعمرك، والخطوب مغيرات ... وفي طول المعاشرة التقالي وعشيرك: الذي يعاشرك، أمركما واحد، ولم أسمع له جمعا، لا يقولون: هم عشراؤك، فإذا جمعوا قالوا: هم معاشروك وسميت عشيرة الرجل لمعاشرة بعضهم بعضا، [و] 4 الزوج [عشير] 5 المرأة، [والمرأة عشيرة الرجل] 6 والمعشر: كل جماعة أمرهم واحد. المسلمون معشر، والمشركون معشر، والإنس معشر، والجن معشر وجمعه: معاشر. والعشاري من النبات: ما بلغ طوله أربعة أذرع. وعاشوراء: اليوم العاشر من المحرم 1 ، ويقال: بل التاسع، وكان المسلمون يصومونه قبل فرض شهر رمضان.'),
(196, 'عرش', 'عرش', 'عرش', 'العرش: السرير للملك. والعريش: ما يستظل به، وإن جمع قيل: عروش في الاضطرار. وعرش الرجل: قوام أمره، وإذا زال عنه ذلك قيل: ثل عرشه. قال زهير: 2 تداركتما عبسا وقد ثل عرشه ... وذبيان إذ زلت بأقدامها النعل وجمع العرش: عرشة وأعراش. ويقال: العرش: ما عرش من بناء يستظل به. قالت الخنساء: 3 كان أبو حسان عرشا خوى ... مما بناه الدهر دان ظليل وعرشت الكرم بالعوش تعريشا إذا عطفت ما ترسل عليه قضبان الكرم. الواحد: عرش. وجمعه: عروش، وعرش. والعريش: شبه الهودج، وليس به، يتخذ للمرأة على بعيرها. وعرش البيت سقفه، وعرش البئر: طيها بالخشب. قال ابو ليلى: تكون بئر رخو الأسفل والأعلى فلا تمسك الطي، لأنها رملة فيعرش أعلاها بالخشب بعد ما يطوى موضع الماء بالحجارة، ثم تقوم السقاة عليه فيستقون، قال: 4 وما لمثابات العروش بقية ... إذا استل من تحت العروش الدعائم وعرش الحمار بعانته تعريشا إذا حمل عليها رافعا رأسه شاحيا فاه. قال [رؤبة] 1 كأن حيث عرش القنابلا ... من الصبيين وحنوا ناصلا وللعنق عرشان بينهما الفقار، وفيهما الأخدعان وهما لحمتان مستطيلتان عداء العنق، أي: طواره. قال: 2 [وعبد] يغوث تحجل الطير حوله ... وقد هذ عرشيه الحسام المذكر والعرش في القدم ما بين الحمار والأصابع من ظهر القدم، والحمار: ما ارتفع من ظهر القدم، وجمعه: عرشة، وأعراش. والعرش: مكة: 3');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(197, 'شعر', 'شعر', 'شعر', 'رجل أشعر: طويل شعر الرأس والجسد كثيره. وجمع الشعر: شعور وشعر وأشعار. والشعار: ما استشعرت به من اللباس تحت الثياب. سمي به لأنه يلي الجسد دون ما سواه من اللباس، وجمعه: شعر وجل الأعشى الجل الشعار فقال: 4 وكل طويل كأن السليط ... في حيث وارى الأديم الشعارا معناه بحيث وارى الشعار الأديم، ولكنهم يقولون هذا وأشباهه لسعة العربية، كما يقولون: ناصح الجيب، أي: ناصح الصدر. والشعار ما ينادي به [القوم] 5 في الحرب، ليعرف بعضهم بعضا. والأشعر: ما استدار بالحافر من منتهى الجلد حيث تنبت الشعيرات حوالي الحافر، ويجمع: أشاعر. وتقول: أنت الشعار دون الدثار، تصفه بالقرب والمودة. وأشعر فلان قلبي هما، أي: ألبسه بالهم حتى جعله شعارا للقلب. وشعرت بكذا أشعر شعرا لا يريدونه به من الشعر المبيت، أنما معناه: فطنت له، وعلمت به. ومنه: ليت شعري، أي: علمي. وما يشعرك أي: ما يدريك. ومنهم من يقول: شعرته، أي: عقلته وفهمته. والشعر: القريض المحدد بعلامات لا يجاوزها، وسمي شعرا، لأن الشاعر يفطن له بما لا يفطن له غيره من معانيه. ويقولون: شعر شاعر أي: جيد، كما تقول: سبي ساب، وطريق سالك، وإنما هو شعر مشعور. والمشعر: موضع المنسك من مشاعر الحج من قول الله: فاذكروا الله عند المشعر الحرام 1 وكذلك الشعارة من شعائر الحج، وشعائر الله مناسك الحج، أي: علاماته، والشعيرة من شعائر الحج، وهو أعمال الحج من السعي والطواف والذبائح، كل ذلك شعائر الحج. والشعيرة أيضا: البدنة التي تهدى إلى بيت الله، وجمعت على الشعائر. تقول: قد أشعرت هذه البدنة لله نسكا، أي: جعلتها شعيرة تهدى. ويقال: إشعارها أن يجأ أصل سنامها بسكين. فيسيل الدم على جنبها، فيعرف أنها بدنة هدي. وكره قوم من الفقهاء ذلك وقالوا: إذا قلدت فقد أشعرت. والشعيرة حديدة أو فضة تجعل مساكا لنصل السكين في النصاب حيث يركب. والشعارير: صغار القثاء، الواحدة، شعرورة وشعرور. والشعارير: لعبة للصبيان، لا يفرد. يقولون: لعبنا الشعارير، ولعب الشعارير. والشعراء من الفواكه واحده وجمعه سواء. تقول: هذه شعراء واحدة، وأكلنا شعراء كثيرة. والشعيراء ذباب من ذباب الدواب، ويقال: ذباب الكلب. والشعيرة من الحلي تتخذ من فضة أو ذهب أمثال الشعير. بنو الشعيراء: قبيلة من العرب. الشعرى: كوكب وراء الجوزاء. ويسمي اللحم الذي يبدو إذا قلم الظفر: أشعر. شعر جبل لبني سليم، ويقال: لبني كلاب بأعلى الحمى خلف ضربة. والشعران: ضرب من الرمث أخضر يضرب إلى الغبرة مثل قعدة الإنسان ذو ورق، ويقال: هو ضرب من الحمض. والشعرة: الشعر النابت على عانة الرجل. قال الشاعر: 1 يحط العفر من أفناء شعر ... ولم يترك بذي سلع حمارا يعني به اسم جبل يصف المطر في أول السنة.'),
(198, 'شرع', 'شرع', 'شرع', 'شرع الوارد الماء وشرعا فهو شارع، والماء مشروع فيه إذا تناوله بفيه. والشريعة والمشرعة: موضع على شاطىء البحر أو في البحر يهيأ لشرب الدواب، والجميع: الشرائع، والمشارع، قال ذو الرمة: 2 وفي الشرائع من. جلان مقتنص ... رث الثياب خفي الشخص منزرب والشريعة والشرائع: ما شرع الله للعباد من أمر الدين، وأمرهم بالتمسك به من الصلاة والصوم والحج وشبهه، وهي الشرعة والجمع: الشرع. ويقال: هذه شرعة ذاك، أي: مثله. قال الخليل بن أحمد رضي الله عنه: 1 كفاك لم تخلقا للندى ... ولم يك بخلهما بدعه فكف عن الخير مقبوضة ... كما حط من مائة سبعه وأخرى ثلاثة آلافها ... وتسع مئيها لها شرعه أي: مثلها:.. وأشرعت الرماح نحوهم إشراعا. وشرعت هي نفسها فهي شوارع. قال: 2 وق خيرونا بين ثنتين منهما ... صدور القنا قد أشرعت والسلاسل ولغة شرعناها نحوهم فهي مشروعة قال: 3 أناخوا من رماح الخط لما ... رأونا قد شرعناها نهالا وكذلك في السيوف. يقال: شرعناها نحوهم. قال النابغة: 4 غداة تعاورتهم ثم بيض ... شرعن إليه في الرهج المكن أي: المغطي. قال أبو ليلى: أشرعت الرماح فهي مشرعة. وإبل شروع إذا كانت تشرب. ودار شارعة، ومنزل شارع إذا كان قد شرع على طريق نافذ، والجميع: الشوارع. ويجيء في الشعر الشارع اسما لمشرعة الماء. والشراع: الوتر نفسه ما دام 1 مشدودا على القوس. والشرعه الوتر، ويجمع على شرع، قال: 2 ترنم صوت ذي شرع عتيق وقال: 3 ضرب الشراع نواحي الشريان يعني: ضرب الوتر سيتي 4 القوس. وشراع السفينة. يقال: ثلاثة أشرعة. وجمعه: شرع 5 وشرعت السفينة تشريعا: جعلت لها شراعا، وهو شيء يكون فوق خشبة كالملاءة الواسعة، تصفقه الرياح فتمضي السفينة. ورفع البعير شراعه، أي: عنقه. ونحن في هذا الأمر شرع، أي: سواء. وتقول: شرعك هذا، أي: حسبك. وأشرعني، أي: أحسبني وأكفاني، والمعني واحد. وشرعت الشيء إذا رفعته جدا. وحيتان شرع: رافعة رءوسها، كما قال الله عز وجل إذ تأتيهم حيتانهم يوم سبتهم شرعا 6 أي: رافعة 7 رءوسها. قال أبو ليلى: شرعا: خافضة رءوسها للشرب. وأنكره عرام. وشرعت اللحمة تشريعا إذا قددتها طولا، واحدتها: شريعة، وجمعها: شرائع. ويقال: هذا أشرع من السهم، أي: أنفذ وأسرع.'),
(199, 'رعش', 'رعش', 'رعش', 'الرعش: رعدة تعترى الإنسان. ارتعش الرجل. وارتعشت يده. ورعش يرعش رعشا. ورجل رعشيش، وقد أخذته الرعشيشة عند الحرب ضعفا وجبنا. قال: 1 . لجت به غير صياش ولا رعش قال: 2 وليس برعشيش تطيش سهامه والرعشاء: النعامة الأنثي السريعة. وظليم رعش على تقدير فعل بدلا من أفعل. وناقة رعشاء وجمل أرعش إذا رأيت له اهتزازا من سرعته في السير. ويقال: جمل رعشن وناقة رعشنة، قال: 3 من كل رعشاء وناج رعشن ... يركبن أعضاد عتاق الأجفن جفن كل شيء بدنه. ويقال: أدخل النون في رعشن بدلا من الألف التي أخرجها من أرعش. وكذلك الأصيد من الملوك يقال له: الصيدن، ويقال: بل الصيدن الثعلب. والرعشن بناء على حدة بوزن فعلل. والرعاش: رعشة تغشى الإنسان من داء يصيبه لا يسكن عنه. وارتعش رأس الشيخ من الكبر كالمفلوج.'),
(200, 'علش', 'علش', 'علش', 'العلوش: الذئب بلغة حمير، وهي مخالفة لكلام العرب، لأن الشينات كلها قبل اللام 1 . قال زائدة: لا أشك إلا أنه الذئب، لأن العلوش الخفيف الحريص. وأنشد عرام: أيا جحمتي بكي على أم واهب ... أكيلة علوش بإحدى الذنائب 2'),
(201, 'شعل', 'شعل', 'شعل', 'اشعل: بياض في الناصية وفي الذنب. والفعل: شعل يشعل شعلا. والنعت: أشعل وشعلاء للمؤنث. والشعلة من النار ما أشعلت من الحطب. والشعيلة: الفتيلة المشتعلة في الذبال. قال لبيد: 3 كمصباح الشعيلة في الذبال وأشعلته فاشتعل غضبا، وأشعلت الخيل في الغارة، أي: بثثتها. قال: والخيل مشعلة في ساطع ضرم ... كأنهن جراد أو يعاسيب 1 وجراد مشعل: متفرق كثير. ويقال شعل يشعل شعلا. قال زائدة: قد شعل شعلا وأشعل الرأس الشيب.'),
(202, 'شنع', 'شنع', 'شنع', 'الشنع والشنوع كله من قبح الشيء الذي يستشنع. شنع الشيء وهو شنيع. وقصة شنعاء ورجل أشنع الخلق، وأمور شنع، أي: قبيحة. قال: 2 تأتي أمورا شنعا شنائرا أي فظيعة وقال: 3 وفي الهام منها نظرة وشنوع أي: قبح واختلاف يتعجب من قبحه. وقال أبو النجم: 4 باعد أم العمر من أسيرها ... حراس أقوام على قصورها وغيرة شنعاء من أميرها وقال القطامي: 1 ونحن رعية وهم رعاة ... ولولا رعيهم شنع الشنار وتقول رأيت أمرا شنعت به، أي: استشنعته. وشنعت عليه تشنيعا، واستشنع به جهله 2 [خف] 3 قال مروان بن الحكم: 4 فوض إلى الله الأمور فإنه ... سيكفيك لا يشنع برأيك شانع'),
(203, 'نشع', 'نشع', 'نشع', 'النشوع: الوجور. والنشع: إيجارك الصبي. قال: 5 فألأم مرضع نشع المحارا والنشع: جعل الكاهن يقول: أنشعنا الجارية إنشاعا. قال: 6 قال الحوازي واستحت أن تنشعا أي: استحت أن تأخذ أجر الكهانة.'),
(204, 'نعش', 'نعش', 'نعش', 'النعش: سرير الميت عند العرب. قال: 7 أمحمول على النعش الهمام وعند العامة: النعش للمرأة والسرير للرجل. بنات نعش سبعة كواكب، أربعة نعش وثلاثة بنات والواحد: ابن نعش، لأن الكوكب مذكر فيذكرونه على تذكيره، فإذا قالوا: ثلاث وأربع ذهبوا به مذهب التأنيث، لأن البنين لا يقال إلا للآدميين. وعلى هذا: ابن اوى فإذا جمعوا قالوا: بنات اوى. وابن عرس وبنات عرس. قال الخليل: [هذا شيء لم نسمع بالابن لحال الأب والأم كما يقولون بنين وبنات فإذا ذكروا ابن لبون وابن مخاض قالوا] 1 ولكنهم يقولون: بنات لبون ذكور وبنات مخاض ذكور هكذا كلام العرب، ولو حمله النحوي على القياس فذكر المذكر وأنث المؤنث كان صوابا. وتقول: نعشه الله فانتعش. إذا سد فقره، وأنعشته فانتعش، أي جبرته فانجبر بعد فقر. قال زائدة: لا يقال نعشه الله فانتعش، والربيع ينعش الناس، أي، يخصبهم. قال رؤبة: 2 أنعشني منه بسيب مفعم وقال: 3 وأنك غيث أنعش الناس سببه ... وسيف، أعيرته المنية، قاطع عنش: العرب تقول: رجل عنشنش، وامرأة (عنشنشة) 4 بالهاء. قال عرام: يروي بالهاء مكان العين، فيقال: هنشنش، أي: خفيف. وقال الراجز: 5 عنشنش تعدو به عنشنشه'),
(205, 'شعف', 'شعف', 'شعف', 'الشعف: مثل رءوس الكمأة، ورءوس الأثافي المستديرة في أعاليها، قال العجاج: 1 دواخسا في الأرض إلا شعفا يعني دواخل في الأرض إلا رءوس الأثافي. وشعفة القلب: رأسه عند معلق نياطه. شعفني حبه، وشعفت به وبحبه، أي: غشي الحب القلب من فوق. ويقرأ شعفها حبا 2 . وشعف الجبال والأبنية: رءوسها. قال: 3 وكعبا قد حميناهم فحلوا ... محل العصم في شعف الجبال'),
(206, 'شفع', 'شفع', 'شفع', 'الشفع: ما كان من العدد أزواجا. تقول: كان وترا فشفعته بالآخر حتى صار شفعا. وفي القرآن والشفع والوتر 4 . الشفع يوم النحر والوتر يوم عرفة. ويقال: الشفع الحصا يعني كثرة الخلق، والوتر الله قال العجاج: 5 شفع تميم بالحصى المتمم يريد به الكثرة. والشافع: الطالب لغيره: وتقول استشفعت بفلان فتشفع لي إليه فشفعه في. والاسم: الشفاعة. واسم الطالب: الشفيع. قال: 1 زعمت معاشر أنني مستشفع ... لما خرجت أزوره أقلامها أي: زعموا أني أستشفع (بأقلامهم) 2 أي: بكتبهم إلى الممدوح. لا: بل إني أستغني عن كتب المعاشر بنفسي عند الملك. والشفعة في الدار ونحوها معروفة يقضى لصاحبها. والشافع: المعين. يقال: فلان يشفع لي بالعداوة، أي: يعين علي ويضادني. قال النابغة: 3 أتاك امرؤ مستعلن شنآنه ... له من عدو مثل ذلك شافع أي: معين. وقال الأحوص: 4 كأن من لامني لأصرمها ... كانوا علينا بلومهم شفعوا أي: أعانوا.'),
(207, 'عشب', 'عشب', 'عشب', 'رجل عشب وامرأة عشبة، أي: قصير في دمامة وذلة، تقول: عشب يعشب عشبا وعشوبة. والعشب: الكلأ الطب. وهو سرعان الكلأ، أي: أوله في البيع ثم يهيج فلا بقاء له. وأرض عشبة معشبة قد أعشبت واعشوشبت، أي: كثر عشبها وطال والتف. وأعشب القوم واعشوشبوا أصابوا عشبا. وأرض عشبة بينة العشابة. ولا يقال: عشبت الأرض، ولكن أعشبت وهو القياس. قال أبو النجم: 1 يقلن للرائد أعشبت إنزل وعشب الموضع يعشب عشبا وعشوبة.'),
(208, 'شعب', 'شعب', 'شعب', 'الشعب: الصدع الذي يشعبه الشعاب، وصنعته: الشعابة، قال: 2 وقالت لي النفس اشعب الصدع واهتبل ... لإحدى الهنات المعضلات اهتبالها والمشعب: المثقب. والشعبة: القطعة يصل بها الشعاب قدحا مكسورا ونحوه. تقول: شعبه فما ينشعب، أي: ما يقبل الشعب، والعالي من الكلام شعبه فما يلتئم. والشعب: ما تشعب من قبائل العرب، وجمعه: شعوب. ويقال: العرب شعب والموالي شعب والترك شعب وجمعه شعوب. والشعوبي: الذي يصغر شأن العرب فلا يرى لهم فضلا. وشعبت بينهم، أي: فرقتهم. وشعبت بينهم بالتخفيف: أصلحت. والتأم شعبهم، أي: اجتمعوا بعد تفرقهم وتفرق شعبهم، قال الطرماح 1 شت شعب الحي بعد التئام وقال ذو الرمة: 2 ولا تقسم شعبا واحدا شعب وشعب الرجل أمره: فرقه. قال الخليل: هذا من عجائب الكلام ووسع اللغة والعربية أن يكون الشعب تفرقا، ويكون اجتماعا وقد نطق به الشعر. ومشعب الحق: طريق الحق. قال الكميت: 3 وما لي إلا آل أحمد شيعة ... وما لي ألا مشعب الحق مشعب وانشعبت أغصان الشجرة، والشعبة: غصنها في أعلى ساقها. وعصا في رأسها شعبتان. وشعب الجبال: ما تفرق من رءوسها. وانشعبت الطريق إذا تفرق، وانشعبت منه أنهار. وأقطار الفرس وأطرافه شعبه، يعني: عنقه ومنسجه وما أشرف منه. قال: 1 أشم خنذيذ منيف شعبه ... يقتحم الفارس لولا قيقبه قال أبو ليلى: نواحي الفرس كلها شعبه، أطرافه: يداه ورجلاه. يقال: فرس أشعب الرجلين أي: فيهما فجوة، وظبي أشعب: متفرق قرناه متباين [ان] 2 بينونة شديدة. قال أبو دواد: 3 وقصرى شنج الأنساء نباج من الشعب يصف الفرس. يعني من الظباء الشعب. وكان قياسه تسكين العين على قياس أشعب وشعب مثل أحمر وحمر، ولحاجته حرك العين، وهذا يحتمل في الشعر. ويقال: في يد فلان شعبة من هذا الأمر، أي: طائفة. وكذلك الشعبة من شعب الدهر وحالاته. والزرع يكون على ورقة ثم ينشعب، أي: يصير ذا شعب وقد شعب. ويقال للمنبة: شعبته شعوب أي أماته الموت فمات. وقال بعضهم: شعوب اسم المنية لا ينصرف، ولا تدخل فيه ألف ولام، لا يقال: هذه الشعوب. وقال بعضهم: بل يكون نكرة. قال الفرزدق: يا ذئب إنك إن نجوت فبعد ما ... شر وقد نظرت إليك شعوب ويقال للميت: انشعب إذا مات، وتمثل يزيد بن معاوية ببيت سهم الغنوي: 1 حتى يصادف مالا أو يقال فتى ... لاقى الذي يشعب الفتيان فانشعبا والشعب: سمة لبني منقر كهيئة المحجن. وكأس شعوب هو الموت. والشعبة: صدع في الجبل تأوي إليه الطير 2 . والشعيب: السقاء البالي، ويقال: بل هي المزادة الضخمة. قال امرؤ القيس: 3 فسحت دموعي في الرداء كأنها ... (كلى) 4 من شعيب بين سح وتهتان [و] 5 شعبعب: موضع. وشعبان اسم شهر. وشعبان حي، نسبة عامر الشعبي إليهم وشعب: حي من همدان.'),
(209, 'شبع', 'شبع', 'شبع', 'الشبع: اسم ما يشبع من طعام 6 وغيره. والشبع مصدر شبع شبعا فهو شبعان، وأشبعته فشبع. قال: 7 وكلكم قد نال شبعا لبطنه ... وشبع الفتى لؤم إذا جاع صاحبه وامرأة شبعى وشبعانة. وأشبعت الثوب صبغا، [أي: رويته] 1 وأشبعت القراءة والكتابة، أي: وفرت حروفها.'),
(210, 'بشع', 'بشع', 'بشع', 'البشع: طعام (كريه) 2 فيه جفوف ومرارة كطعم الإهليلجة البشعة 3 . ورجل بشع وامرأة بشعة، 4 أي: كريهة ريح الفم، لا تتخلل ولا تستاك. وقد بشع يبشع بشعا وبشاعة.'),
(211, 'عشم', 'عشم', 'عشم', 'العيشوم: ما هاج من الحماض ويبس، الواحدة بالهاء. قال أبو ليلى: هي عندنا نبت دقيق طوال: يشبه الأسل، محدد الرأس كأنها شوك تتخذ منه الحصر الدقاق المصبغة 5 قال ذو الرمة: 6'),
(212, 'عضد', 'عضد', 'عضد', 'العضد فيه ثلاث لغات: عضد، وعضد، وعضد. وعضدان وأعضاد، وهو من المرفق إلى الكتف 2 . وفلان يعضد فلانا: يعينه. وعضدني عليه، أي: أعانني. والعضد: داء يأخذ في أعضاد الإبل خاصة. قال: 3'),
(213, 'ضرع', 'ضرع', 'ضرع', 'ضرع الرجل يضرع فهو ضرع، أي: غمر ضعيف. قال طرفة بن العبد: 5'),
(214, 'عضل', 'عضل', 'عضل', 'العضلة: موضع اللحم من الساقين والعضدين. وإنه لعضل الساقين إذا كثر لحمهما. ويد عضلة، وساق عضلة: ضخمة. وداء عضال، إذا أعيى الأطباء، وأعضلهم فلم يقوموا به. وأمر معضل يغلب الناس أن يقوموا به 1 . قال ذو الإصبع 2 : واحدة أعضلكم أمرها ... فكيف لو درت على أربع بلغنا أن ذا الإصبع تزوج فأتي حيه يسألهم مهرها فلم يعطوه، فهجاهم يقول: عجزتم عن مهر واحدة فكيف لو تزوجت بأربع نسوة. وقوله: فكيف لو درت، أي: فكيف لو قامت الحرب على ساق. ولو قيل للحم الساق عضيلة وعضائل جاز. وتقول: عضلت عليه، أي: ضيقت عليه في أمره وحلت بينه وبين ما يريد ظلما. وعضلت المرأة، بالتخفيف إذا لم تطلق، ولم تترك، ولا يكون العضل ألا بعد التزويج. وعضلت المرأة بولدها، إذا عسر عليها ولادها، وأعضلت مثله، وأعسرت فهي معضل [ومعضل] 3 . والعضل مواضع 1 بالبادية كثيرة الغياض 2 . بنو عضل من أسد. واعضلت 3 الشجرة إذا كثرت 4 أغصانها، واشتد التفافها، قال: 5'),
(215, 'نعض', 'نعض', 'نعض', 'النعض: اسم شجر 1 معروف عندهم. قال عرام: لا ينبت النعض إلا بالحجارة، وهي شجرة خضراء تشبه المرخ 2 ، ليس لها ورق، ولكنها خيطان. والخيطان: التي لا شوك لها ولا ورق.'),
(216, 'ضعف', 'ضعف', 'ضعف', 'ضعف يضعف ضعفا وضعفا. والضعف: خلاف القوة. ويقال: الضعف في العقل والرأي، والضعف في الجسد. ويقال: هما لغتان جائزتان في كل وجه. ويقال: كلما فتحت بالكلام فتحت بالضعف. تقول: رأيت به 3 ضعفا. وأن به ضعفا، فإذا رفعت أو خفضت فالضم أحسن، تقول: به ضعف شديد. وفعل ذاك من ضعف شديد. رجل ضعيف، وقوم ضعفاء ونسوة ضعيفات، وضعائف. أنشد عرام: 1 أيا نفس قد فرطت وهي قريبة ... وأبليت ما تبلى النفوس الضعائف ويجمع الرجال أيضا على ضعفى، كما يقال حمقى. ويقال: رجال ضعاف، كما يقال خفاف. وتقول أضعفته إضعافا، أي: صيرته ضعيفا. واستضعفته: وجدته ضعيفا فركبته بسوء. وفي معنى آخر 2 : أضعفت الشيء إضعافا، وضاعفته مضاعفة، وضعفته تضعيفا، وهو إذا زاد على أصله فجعله مثلين أو أكثر. وضعفت القوم أضعفهم ضعفا إذا كثرتهم، فصار لك ولأصحابك الضعف عليهم. ضفع- فضع: 3 ضفع الإنسان يضفع ضفعا، إذا جعس. وفضع ... لغتان، مثل جذب وجبذ مقلوبا.'),
(217, 'عضب', 'عضب', 'عضب', 'العضب: السيف القاطع. عضبه يعضبه عضبا، أي قطعه. وشاة عضباء: مكسورة القرن. وقد عضبت عضبا، وأعضبتها إعضابا، وعضبت قرنها فانعضب، أي: انكسر. ويقال العضب يكون في أحد القرنين. وناقة عضباء، أي: مشقوقة الأذن. ويقال: هي التي في أحد أذنيها شق وسميت ناقة رسول الله صلى الله عليه وسلم العضباء.'),
(218, 'بعض', 'بعض', 'بعض', 'بعض كل شيء: طائفة منه. وبعضته تبعيضا، إذا فرقته 1 أجزاء. وبعض مذكر في الوجوه كلها، كقولك: هذه الدار متصل بعضها ببعض. وبعض العرب يصل ب (بعض) كما يصل ب (ما) ، كقول الله عز وجل: فبما رحمة من الله 2 . وكذلك ببعض في هذه الآية: وإن يك صادقا يصبكم بعض الذي يعدكم 3 . والبعوض: جمع البعوضة، وهي المؤذية العاضة في الصيف.'),
(219, 'ضبع', 'ضبع', 'ضبع', 'ضبعت الناقة ضبعا وضبعة فهي ضبعة، وأضبعت فهي مضبعة إذا أرادت الفحل وفي معنى آخر: ضبعت تضبع ضبعا، وضبعت تضبيعا، وهو شدة سيرها. وضبعانها اهتزازها، واشتقاقها من أنها تمد ضبعيها في السير والضبع وسط العضد بلحمه، قال العجاج: 1 وبلدة تمطو العناق الضبعا قال عرام: الضبعة: اللحم [الذي] 2 تحت العضد مما يلي الإبط. والمضبعة اللحم الذي تحت الإبط من قدم. قال موسى 3 : فرس ضابع إذا كان يتبع أحد شقيه، فيثني عنقه، وهو أن يركض فيقدم إحدى رجليه. ويجمع: ضوابع. والرجل يضطبع بالثوب أو بالشيء إذا تأبطه. ضباعة اسم امرأة. ضبيعة: قبيلة، والنسبة إليها: ضبعي 4 والضبعان: الذكر من الضباع، ويجمع على ضبعانات، لم يرد بالتاء التأنيث، إنما هو مثل قولك: فلان من رجالات الدنيا. قال الخليل: كلما اضطروا إلى جماعة فصعب عليهم واستقبح ذهبوا به إلى هذه الجماعة، تقول: حمام وحمامات، كما يقولون: فلان من رجالات الدنيا. قال: 1 وبهلولا وشيعته تركنا ... لضبعانات معقلة منابا قال زائدة: هو منى مناب، أي هو منى على بعد ليس كل البعد. والضباع: جمع للذكر والأنثى، ولغة للعرب: ضبع جزم. والضبع: السنة المجدبة. قال: 2 أبا خراشة إما كنت ذا نفر ... فإن قومي لم 3 تأكلهم الضبع بضع: بضعت اللحم أبضعه بضعا، وبضعته تبضيعا، أي: جعلته قطعا. والبضعة: القطعة، وهي الهبرة. وفلان شديد البضع والبضعة، أي: حسنها إذا كان ذا جسم وسمن. قال: 4 خاظي البضيع لحمه كالمرمر وبضعت من صاحبي بضوعا إذا أمرته بشيء فلم يفعله فدخلك منه شيء 5 وبضعت من الماء بضوعا، أي: رويت. والبضع اسم باضعتها، أي: باشرتها. وبضعتها بضعا، أو بضعا، وهو 6 الجماع والبضاعة: ما أبضعت للبيع كائنا ما كان. ومنه الإبضاع والإبتضاع. والباضعة: شجة تقطع اللحم. والباضعة: قطعة من الغنم انقطعت عن 1 الغنم. يقال: فرق بواضع. والبضيع: البحر. قال 2 : ساد تجرم في البضيع ثمانيا ... يلوى (بفيفاء) 3 البحور ويجنب ويروي بعيقات البحور. قال الهذلي يصف حمار الوحش 4 : فظل يراعي الشمس حتى كأنها ... فويق البضيع في الشعاع جميل 5 الجميل هاهنا: الشحم المذاب، شبه شعاع الشمس في البحر بدسم الشحم المذاب. والبضع من العدد ما بين الثلاثة إلى العشرة، ويقال: هو سبعة. قال عرام: ما زاد على عقد فهو بضع، تقول: بضعة 6 عشر وبضع وعشرون وثلاثون 7 ونحوه. وأبضعته بالكلام إبضاعا، وهو أن تبين له ما تنازعه حتى تشتفي منه كائنا ما كان. وبضعته فانبضع، أي قطعته فانقطع. وبضع الشيء، أي: فهم.'),
(220, 'عضم', 'عضم', 'عضم', 'العضم: معجس 1 القوس والجميع العضام، وهو ما وقعت عليه أصابع الرامي. قال 2 : رب عضم رأيت في جوف ضهر الضهر: موضع في الجبل. والعضام: عسيب البعير وهو عظم الذنب لا الهلب، و [أدنى] 3 العدد: أعضمة، والجميع: العضم. والعضم: خشبة ذات أصابع يذرى بها الحنطة فينقى من التبن. وعضم الفدان: لوحه العريض الذي في رأسه الحديدة التي تشق بها الأرض، لم يعرفه أبو ليلى. معض: معض الرجل من شيء يسمعه، وامتعض منه إذا شق عليه وأوجعه فامتعض منه، أي: توجع منه. وفي الحديث: فأشفق 4 عليه امتعاضه أي: موجدته. والمجاوز 1 أمعضته إمعاضا، ومعضته تمعيضا إذا أزلت به ذلك. قال رؤبة 2 : فهي ترى ذا حاجة مؤتضا ... ذا معض لولا يرد المعضا'),
(221, 'عصد', 'عصد', 'عصد', 'قلت لأبي الدقيش: ما العصد؟ قال: تقليبك العصيدة في الطنجير بالمعصدة. تقول: عصد يعصد عصدا. قلت: هل تعرفه العرب العاربة ببواديها؟ قال: نعم! أما سمعت قول غيلان 3 : على الرحل مما منه السير 4 عاصد أي: يذبذب رأسه ويضطرب شبه الناعس الذي يعصد لخفة رأسه. وقال بعضهم: العاصد في هذا البيت هو الميت وهو خطأ. والعصواد: جلبة في بلية. تقول: عصدتهم العصاويد، وهم في عصواد من أمرهم، وفي عصواد بينهم، يعني البلايا والخصومات. وجاءت الإبل عصاويد: يركب بعضها بعضا. قال زائدة: (أقول) 5 جاءت الإبل عصاويد، أي: متفرقة وكذلك عصاويد الظلام لتراكبه. وعصد البعير إذا مات 1 قال غيلان:'),
(222, 'صتع', 'صتع', 'صتع', 'العرب تقول: جاء فلان يتصتع إلينا، أي: يذهب بلا زاد، ولا نفقة، ولا حق واجب. وقال أبو ليلى: بل هو التردد، أي: يذهب مرة، ويعود أخرى.'),
(223, 'عصر', 'عصر', 'عصر', 'العصر: الدهر، فإذا احتاجوا إلى تثقيله قالوا: عصر، وإذا سكنوا الصاد لم يقولوا إلا بالفتح، كما قال 1'),
(224, 'عصل', 'عصل', 'عصل', 'العصل: إعوجاج الناب، قال 1 : على شناح نابه لم يعصل شناح، أي: طويل. والأعصل من الرجال: الذي عصلت ساقه فاعوجت اعوجاجا شديدا. ولا يقال العصل إلا لكل معوج فيه صلابة وكزازة. والعصلة: الشجرة العوجاء التي لا يقدر على إقامتها بعد ما صلبت. وكذلك السهم إذا اعوج متنه. والعصلة شجرة إذا أكل البعير منها سلحته تسليحا، ويجمع على عصل قال لبيد 2 : وقبيل من عقيل صادق ... كليوث بين غاب وعصل'),
(225, 'علص', 'علص', 'علص', 'العلوص: من التخمة والبشم. ويقال: هو اللوى 3 الذي ييبس في المعدة. علصت التخمة في معدته تعليصا، وإن به لعلوصا. وإنه لمعلوص وعلوص، أي: متخم.'),
(226, 'صعل', 'صعل', 'صعل', 'الصعل من النعام ما صغر رأسه، وكذلك الرجل الصعل إذا صغر رأسه، كأنه يستوي مع عنقه من غير قصر في العنق. قال 1 يصف دقلا، وهي الخشبة التي ينصب في وسطها الشراع: ودقل أجر شوذبي 2 ... صعل من السام ورباني الشوذبي: الطويل، وأراد بالصعل هاهنا الطويل. وإنما يصف مع طوله استواء أعلاه بأسفله، ولم يصفه بدقة الرأس، لأنه أراد جودة النعت. قال الضرير: الصعل: الدقيق، والسام: شجر، والرباني الذي يقعد فوق الدقل فيتمخر الرياح لأصحاب السفن. صعل من السام وزنبري وهو الملاح، ويروى: رباني. وقد يقال: رجل أصعل، وامرأة صعلاء، وقد صعل صعلا. صلع: الصلع: ذهاب شعر الرأس من مقدمه إلى مؤخره، وإن ذهب وسطه فكذلك 3 والنعت: أصلع وصلعاء، والجميع: صلع وصلعان. والصلعة: موضع الصلع من الرأس حيث يرى، وكذلك النزعة والجلحة ونحوه رأيتهم يخففونه، ويجوز تثقيله في الشعر على قياس الكشفة والقزعة فإنها يثقلان هكذا جاءت الرواية. الصلاع: الصفاح وهو العريض من الصخر. الواحدة: صلاعة وصفاحة. والتصليع: السلاح. يقال للمجعسس: صلع تصليعا، إذا وضع مستويا مبسوطا على الأرض. قال شجاع: أقول: لا أعرف: صلع المجعسس، ولكن أقول: (سلخ أي: وضعه مطولا مثل سليخة الغزل، ويصل به، وهو السليخ أيضا التي تنزع المرأة مما على مغزلها إذا وفرته وفرع) 1 . وزرق به وذرق به إذا وضعه بخراءة 2 مستويا. وصلعت العرفطة تصليعا إذا سقطت رءوس أغصانها، وأكلتها الإبل. قال الشماخ 3 إن تمس في عرفط صلع جماجمه ... من الأسالق عاري الشوك مجرود والأصلع من الحيات الدقيق العنق كأن رأسه بندقة مدحرجة. والأصيلع: رأس الذكر مكنى عنه 4'),
(227, 'عنص', 'عنص', 'عنص', 'العنصوة: الخصلة من الشعر على تقدير ثندوة 1 . وما لم يكن ثانية نونا لا تضم العرب صدره، مثل عرقوة وترقوة وقرنوة 2 ، وهي شجرة طيبة الريح يدبغ بها الأدم، وهي جنس من الجنبة. وتجمع عناصي. قال 3 : فقد عيرتني الشيب عرسي ومسحت ... عناصي رأسي فهي من ذاك تعجب'),
(228, 'نعص', 'نعص', 'نعص', 'وأما نعص فليس [ت] 4 بعربية، إلا ما جاء من اسم ناعصة المشبب بخنساء، وكان جيد الشعر، وقلما يروى شعره لصعوبته 5'),
(229, 'صنع', 'صنع', 'صنع', 'صنع يصنع صنعا. وما أحسن صنع الله عنده وصنيعه. والصناع: الذين يعملون بأيديهم. تقول: صنعته فهو صناعتي. وامرأة صناع، وهي الصناعة الرقيقة بعمل يديها، ويجمع صوانع. ورجل صنع اليدين وصنع اليدين. والصنيعة: ما اصطنعت من خير إلى غيرك. قال: 1 . إن الصنيعة لا تكون صنيعة ... حتى يصاب بها طريق المصنع وفلان صنيعتي، أي: اصطنعته وخرجته. والتصنع: حسن السمت والرأي سره يخالف جهره. وفرس صنيع، أي: قد صنعه أهله بحسن القيام عليه. تقول: صنع 2 الفرس، وصنع الجارية تصنيعا، لأنه لا يكون إلا بأشياء كثيرة وعلاج. والمصنعة: شبه صهريج عميق تتخذ للماء، وتجمع مصانع. والمصانع: ما يصنعه العباد من الأبنية والآبار والأشياء. قال لبيد: 3 بلينا وما تبلى النجوم الطوالع ... وتبقى الجبال بعدنا والمصانع وقال الله عز وجل: وتتخذون مصانع لعلكم تخلدون 4 . والصناع والصناعة أيضا: خشب يتخذ في الماء ليحبس به الماء، أو يسوى به، ليمسكه حينا، لم يعرفه أبو ليلى ولا عرام. والأصناع: جمع الصنع [وهو مثل الصناع أيضا: خشب] 5 يتخذ لمستنقع الماء. نصع: النصع: ضرب من الثياب شديد البياض. قال العجاج: 6 تخال نصعا فوقها مقطعا والناصع: الشديد البياض، الحسن اللون. نصع لونه نصاعة ونصوعا. ويقال للإنسان إذا تصدى للشر: قد أنصع للشر إنصاعا. والنصيع: البحر، قال: 1 أدليت دلوي في النصيع الزاخر لم يعرفه عرام، ولم ينكره. قال أبو عبد الله: هو بالضاد والباء، وكذلك البيت 2 ، ولم يشك فيه، وقال: هو مأخوذ من البضع، وهو الشق، كأن هذا البحر شقة شقت من البحر الأعظم. ومما يشبه: الخليج، لأنه خلج من النهر الأعظم. قال عرام: هذا صحيح لا شك فيه. قال عرام: ويكون الأبيض ناصعا كما قال النابغة: 3'),
(230, 'عصف', 'عصف', 'عصف', 'العصف: ما على ساق الزرع من الورق الذي يبس فتفتت. قال أبو ليلى: هو عندنا دقاق التبن الذي إذا ذري البيدر صار مع الريح كأنه غبار. وقال عرام: هو أن تؤخذ رءوس الزرع قبل أن تسنبل فتعلفه الدواب، ويترك الزرع حتى ينشو، أو يكتنز، فيكون أقوى له وأكثر لنزله، وأنكر ما سواه. والريح تعصف بما مرت عليه من جولان التراب، أي: تمضي به. وناقة عصوف: تعصف براكبها، أي: تمضي به كسرعة الريح. والعصف: السرعة في كل شيء. قال: 1 ومن كل مسحاج إذا ابتل ليتها ... تحلب منها ثائب متعصف 2 ونعامة عصوف: سريعة. والحرب تعصف بالقوم، أي: تذهب بهم، قال: 3 في فيلق جأواء ملمومة ... تعصف [بالدارع والحاسر] 4 جأواء: التي فيها من كل لون. والمعصفات التي تثير 5 السحاب والتراب ونحوهما الواحد [ة] 6 معصفة قال العجاج: 7 والمعصفات لا يزلن هدجا'),
(231, 'عفص', 'عفص', 'عفص', 'العفص: حمل شجرة تحمل سنة عفصا وسنة بلوطا. والعفاص: صمام القارورة. [و] 8 عفصتها: جعلت العفاص في رأسها.'),
(232, 'صفع', 'صفع', 'صفع', 'الصفع: ضرب بجمع اليد على القفا، ليس بالشديد. والسين لغة فيه. ويقال: الصفع بالكف كلها. ورجل صفعان. فصع: الفصع من 1 قولك: فصع تفصيعا: يكنى به 2 عن ريح [سوء] 3 وفسوة لا غير.'),
(233, 'عصب', 'عصب', 'عصب', 'العصب: أطناب المفاصل الذي يلائم بينها، وليس بالعقب. ولحم عصب: صلب كثير العصب. والعصب: الطي الشديد. ورجل معصوصب الخلق كأنما لوي ليا. قال: 4 ذروا [التخاجؤ] 5 وامشوا مشية سجحا ... إن الرجال ذوو عصب وتشمير التخاجؤ 6 : مشية فيها نفخ. وسجحا: مستوية. وروى عرام: سرحا. والمعصوب: الجائع، في لغة هذيل، الذي كادت أمعاؤه تيبس وهو يعصب عصوبا فهو عاصب أيضا، يقال، لأنه عصب بطنه بحجر من الجوع. وعصبتهم تعصيبا، أي: جوعتهم، قال 1 : لقد عصبت أهل العرج منهم ... بأهل صوالق إذ عصبوني والعصب من البرود: ما يعصب غزله ثم يصبغ ثم يحاك، ليس من برود الرقم. وتقول: برد عصب، مضاف [إليه] 2 لا يجمع، وربما اكتفوا فقالوا: عليه العصب، لأن البرد عرف بذلك الاسم. وسمي العصيب من أمعاء الشاة، لأنه مطوي. ويقال في سنة المحل إذا احمر 3 لأفق، واغبر العمق: عصب الأفق يعصب فهو عاصب، أي: محمر. قال أبو ليلى: عصبت أفواه القوم عصوبا، إذا لصق على أسنانهم غبار مع الريق وجفت أرياقهم. ويقال: عصب القوم يعصب عصوبا إذا اجتمع الوسخ على أسنانهم من غبار أو شدة عطش، فإذا غسل أو مسح ذهب. والعصبة: ورثة الرجل عن كلالة من غير ولد ولا والد. فأما في الفرائض فكل من لم يكن له فريضة مسماة فهو عصبة، يأخذ ما بقي من الفرائض، ومنه اشتقت العصبية. والعصبة من الرجال: عشرة، لا يقال لأقل منه. وإخوة يوسف عليه السلام عشرة، قالوا: ونحن عصبة* 4 ، ويقال هو ما بين العشرة إلى الأربعين من الرجال. وقوله تبارك وتعالى: لتنوأ بالعصبة 5 . يقال أربعون، ويقال: عشرة. وأما في كلام العرب فكل رجال أو خيل بفرسانها إذا صاروا قطعة فهم عصبة، وكذلك العصابة من الناس والطير. قال النابغة: 1 إذا ما التقي الجمعان حلق فوقهم ... عصائب طير تهتدي بعصائب واعصوصب القوم: صاروا عصابة. قال: 2 يعصوصب الحشر إذا اقتدى بها أي: يجتمع. واعصوصب القوم إذا جدوا في السير، واشتقاقه من اليوم العصيب، أي: الشديد. وأمر عصيب، أي: شديد. قال العجاج: ومبرك الجائل حيث اعصوصبا أي: تفرقت عصبا. وقال: 3 يعصوصب السفر إذا علاها ... رهبتهم أو ينزلوا ذراها يعصوصب السفر، أي: يجدون في السير حين رهبوا تلك المفازة. واعصوصب السفر، أي اشتد. ويوم عصبصب بوزن فعلعل بناء مردف بحرفين، قال: 4'),
(234, 'عصم', 'عصم', 'عصم', 'العصمة: أن يعصمك الله من الشر، أي: يدفع عنك. واعتصمت بالله، أي: امتنعت به من الشر. واستعصمت، أي: أبيت. وأعصمت، أي: لجأت إلى شيء اعتصمت به. قال: 3 قل لذي المعصم الممسك بالأطناب ... يا ابن الفجار يا ابن ضريبه وأعصمت فلانا: هيأت له ما يعتصم به. والغريق يعتصم بما تناله يده، أي: يلجأ إليه. قال: 1'),
(235, 'عطس', 'عطس', 'عطس', 'المعطس: الأنف من يعطس. والمعطس من يعطس. قال 1 : يا قوم ما الحيلة في العرندس ... المخلف الوعد المطول المفلس وهو على ذاك كريم المعطس أي: كريم الأنف. أخبر أنه حمي الأنف منيع. وهذا رجل كان له عليه دين فجحد 2 إياه. يقال: عطس يعطس عطاسا وعطس يعطس عطسا. ويقال: كان سبب عطسة آدم عليه السلام أن الروح جرى في جسده، فتنفس فخرج من خياشيمه فصارت عطسة فقال: الحمد لله إلهاما من الله فقال له ربه: يرحمك الله، فسبقت رحمته غضبه، فصارت سنة التسميت للعاطس. وعطس الصبح: انفلق، ولذلك سمي الصبح عطاسا. قال أبو ليلى: هو قبل أن ينتبه أحد فيعطس، وذلك بليل. قال امرؤ القيس 3 : وقد أغتدي قبل العطاس بسابح ... [أقب كيعفور الفلاة محنب] وقال عرام السلمي: لأن الإنسان يعطس قرب الصباح، والعطاس للإنسان مثل الكداس للبهائم.'),
(236, 'سعط', 'سعط', 'سعط', 'أسعطته دواء فاستعطه. والسعوط: اسم ذلك الدواء. وطعنته فأسعطته الرمح، أي: جعلته في أنفه. والمسعط: الذي يجعل فيه الدواء، على مفعل، لأنه أداة. والمسعط أصل بنائه، وقال غيره بالكسر وليس بشيء. أسعطته سعطة واحدة وإسعاطة واحدة، فهو مسعط وسعيط.'),
(237, 'سطع', 'سطع', 'سطع', 'كل شيء ينتشر فينبسط نحو البرق والغبار والريح الطيبة يقال: سطع سطوعا. قال 1 : مشمولة غلثت بنابت عرفج ... كدخان نار ساطع أسنامها وسطع الظليم، أي: رفع رأسه، ومد عنقه. وظليم أسطع: طويل العنق، وقياس فعله: سطع سطعا، والأنثى: سطعاء مثل حمراء هذا من النعت. ومن رفع العنق فقد سطع يسطع سطعا. وسطاع الخباء: خشبة تنصب في وسطه ووسط الرواق ونحوهما. وثلاثة أسطعة وجمعه [لأكثر العدد 2 ] سطع. قال 3 : أليسوا بالألى قسطوا قديما ... على النعمان وابتدروا السطاعا وذلك أنهم دخلوا عليه قبته والسطع أن تسطع شيئا براحتك أو أصابعك ضربا. وتقول: سمعت لوقعه سطعا شديدا، تعني صوت ضربة أو رمية، وإنما ثقلت سطعا، لأنه حكاية، وليس بنعت ولا مصدر وتقول: أسطعته إسطاعة. قال عرام: إذا قويت عليه، والاستطاعة تجري مجرى القدرة.'),
(238, 'طسع', 'طسع', 'طسع', 'الطسع: الرجل الذي لا غيرة له. طسع طسعا، أي: ذهبت غيرته. وطزع لغة.'),
(239, 'عسد', 'عسد', 'عسد', 'العسد لغة في العزد، كالأسد والأزد. والعسودة: دويبة بيضاء كأنها شحمة يقال لها: بنت نقا، تكون في الرمل يشبه بها بنان الجواري، ويجمع على عسودات وعساود. قال زائدة: هي على خلق العظاء إلا أنها أكثر شحما من العظاء وإلى السواد أقرب.'),
(240, 'عدس', 'عدس', 'عدس', 'العدس: حبوب. الواحدة عدسة. والعدس: بثرة من جنس الطاعون قلما يسلم منها، وبها مات أبو لهب. عدس فهو معدوس، كما تقول: طعن فهو مطعون. عدس: زجر للبغال، وناس يقولون: حدس. ويقال: إن حدسا كانوا بغالين على عهد سليمان بن داود عليه السلام يعنفون على البغال عنفا شديدا، والبغل إذا سمع باسم حدس طار فرقا مما يلقى منهم، فلهج الناس بذلك. والمعروف عدس. وعدس: قبيلة من تميم.'),
(241, 'سعد', 'سعد', 'سعد', 'السعد: نقيض النحس في الأشياء يوم سعد ويوم نحس، وسعد الذابح، وسعد بلع، وسعد السعود، وسعد الأخبية، نجوم من منازل القمر وهي بروج الجدي والدلو. وسعد فلان يسعد سعدا وسعادة فهو سعيد ويجمع سعداء، نقيض أشقياء 1 وتقول: أسعده الله وأسعد جده. وإذا كان اسما لا نعتا 2 فجمعه 3 سعيدون لا سعداء. وسعيد الأرض النهر الذي يسقيها. والساعد: إحليل خلف الناقة يخرج منه اللبن، ويجمع سواعد، ويقال: هي عروق يجري فيها اللبن إلى الضرع والإحليل. قال حميد 4 : وجاءت بمعيوف الشريعة مكلع ... أرست 5 عليه بالأكف السواعد قال 6 : لا أشك أن سعيد النهر اشتق منه. والساعد: عظم الذراع ملتقي الزندين من لدن المرفق إلى الرسغ، وجمعه سواعد. قال 7 : هو الساعد الأعلى الذي يتقى به ... وما خير كف لا تنوء بساعد ويقال للأسد خاصة: ساعدة. وساعدة قبيلة. والمساعدة: المعاونة على كل أمر يعمله عامل. والمسعود: السعيد. وساعدته فسعدته فهو مسعود، أي: صرت في المساعدة أسعد منه وأعون. والسعدان: نبات له شوك كحسك القطب غير أنه غليظ مفرطح كالفلكة، ونباته سمي الحلمة، وهو من أفضل المراعي وهو من أحرار البقول. ويقال: الحلمة نبت حسن غير السعدان. وتقول العرب إذا قاست رجلا برجل لا يشبهه: مرعى ولا كالسعدان، وماء ولا كصداء 1 . وسعدانة الثندوة: التي في رأس الثدي، شبهت بحسكة تلك الشجرة وهو ما استدار من السواد حول حلمة الثدي من المرأة، ومن ثندوة الرجل. والسعادى نبات السعد والسعد أصله الأسود. والسعدانة: الحمامة الأنثى، وإن جمع قيل: سعدانات. والإسعاد لا يستعمل إلا في البكاء والنوح. قال عمران بن حطان: ألا يا عين ويحك أسعديني ... على تقوى وبر عاونيني'),
(242, 'دعس', 'دعس', 'دعس', 'الدعس: الطعن بالرمح. قال 2 : اذا دعسوها بالنضي المعلب وطريق مدعاس: دعسته القوائم حتى لان، والدعس: شدة الوطء. قال رؤبة: في رسم آثار ومدعاس دعق أراد بالدعق: الدقع على القلب، وهو التراب.'),
(243, 'سدع', 'سدع', 'سدع', 'رجل مسدع: ماض لوجهه نحو الدليل. المسدع: الهادي. قال زائدة: وشجاع يصدع بالصاد.'),
(244, 'دسع', 'دسع', 'دسع', 'الدسع: خروج جرة البعير بمرة إذا دسعها وأخرجها إلى فيه. والمدسع: مضيق مولج المريء في عظم ثغرة النحر، واسم ذلك العظم الدسيع، وهو العظم الذي فيه الترقوتان مشدود [ا] 1 بعظم الكاهل. قال: 2 يرقى الدسيع إلى هاد له تلع ... في جؤجؤ كمداك الطيب مجيوب أي: متسع، وهو من الجيب. والدسيعة: مائدة الرجل إذا كانت كريمة. قال أبو ليلى: الدسيعة: كل مكرمة يفعلها الرجل. قال 3 : ضخم الدسيعة حمال لأثقال ورجل ذو دسيعة، أي: ذو مكرمة. ودسعت الحجر 4 إذا أخذت دساما، وهو شيء على قدر الجحر فسددت بمرة، فدسمته بدسام دسما 5 .'),
(245, 'ستع', 'ستع', 'ستع', 'رجل مستع، لغة في مسدع، وهو الماضي في أمره. ورأيته مستعا، أي: سريعا، لم يعرفه عرام ولا أبو ليلى.'),
(246, 'تعس', 'تعس', 'تعس', 'التعس: ألا ينتعش 1 من صرعته وعثرته، وأن ينكس في السفال. تعس الرجل يتعس تعسا فهو تعس. أتعسه الله [فهو] 2 متعس 3 إذا أنزل الله به ذلك.'),
(247, 'تسع', 'تسع', 'تسع', 'يقال: تسعت القوم، أي: صرت تاسعهم. وأتسعت الشيء إذا كان ثمانية وأتممته تسعة. والتسع والتسعة من 4 العدد يجري على وجوه [التذكير والتأنيث 5 ] ، تسعة رجال، وتسع نسوة.'),
(248, 'عسر', 'عسر', 'عسر', 'العسر: قلة ذات اليد. والعسر نقيض اليسر، والعسر خلاف والتواء. أمر عسير وعسر، ويوم عسير وعسر، ولم أسمع: رجل عسر. وعسر الأمر يعسر عسرا، ويجوز عسارة، ونعته عسير. وعسر الأمر يعسر علينا عسرا، وهو شاذ، لاختلاف تصريفه في الفعل والنعت. قال: 1 عليك بالميسور 2 واترك ما عسر ... وإن أداروك لشرب فاستدر ورجل أعسر بين العسر. وأعسر يسر وامرأة عسراء يسرة [إذا كان 3 ] يعمل 4 بيديه معا فإذا عمل بيده الشملى وكانت غالبة على اليمنى فهو أعسر. وأعسر الرجل إذا صار من ميسرة إلى عسرة. وعسرته أعسره عسرا إذا لم ترفق به إلى ميسرة. والمعسور: المضيق عليه. وبلغت معسوره [إذا لم ترفق به 5 ] ، وعسرت عليه تعسيرا، أو عسرت عليه عسرا إذا خالفته. ومن العرب من يقول: عسر الأمر وعسر الرجل فرقا بينهما. والعسرى ذهاب اليسرى. ويقال: يسره الله للعسرى، ولا وفقه لليسرى وما كان أعسر ولقد كان عمل بعسارة 1 واستعسرته: طلبت معسوره. واستعسر الأمر وتعسر، أي: التوى. وتغسر الغزل بالغين [المعجمة 2 ] إذا التبس فلا يقدر على تخليصه، ولا يقال بالعين [المهملة 3 ] إلا تجشما. وأعسرت المرأة: عسر عليها ولادها. وقيل: أعسرت وأنثت إذا دعي عليها، وأيسرت وأذكرت إذا دعي لها. والعسير: الناقة التي اعتاصت فلم تحمل سنتها. قال 4 : وعسير أدماء حادرة العين ... خنوف عيرانة شملال ويقال: عسر الناقة، وناقة عاسرة تعسر إذا عدت، أي: ترفع ذنبها. قال 5 : تراني إذا ما الركب جدوا تنوفة ... تكسر أذناب القلاص العواسر وناقة عوسرانية، وهي التي تركب قبل أن تراض. والذكر عيسراني كالمنسوب، وإن شئت طرحت الياء، وضممت السين كما تضم الخيزران، فتقول: عيسران، وتفتح السين أيضا كما تفتح الغيدقان، فتقول: عيسران.'),
(249, 'عرس', 'عرس', 'عرس', 'العرس: امرأة الرجل. ولبوءة الأسد عرسه والعروس نعت للرجل والمرأة، استويا فيه ما داما في تعريسهما إذا عرس أحدهما بالآخر. وأحسن ذلك أن يقال للرجل: معرس، لأنه أعرس، أي: اتخذ عرسا. والعرس: اسم الطعام الذي يعرس للعروس. والعرب تؤنث العرس. قال: 1 يمشي إذا أخذ الوليد برأسه ... مشيا كما يمشي الهجين المعرس هذا هو الذي يعرس العرس، وهو اسم الطعام الذي يعرس للعروس. قال عرام: عرس الرجل يعرس عرسا، أي: بطر. ويقال: عرس به، أي: لزمه، واعترسوا عنه، أي: تفرقوا. والعرسي: ضرب من الصبغ يشبه لون ابن عرس. والعريس 2 : مأوى الأسد في خيس من الشجر والغياض في أشدها التفافا. وقول جرير: 3'),
(250, 'عسل', 'عسل', 'عسل', 'العسل: لعاب النحل. وعسل اللبنى: شيء يتخذ من شجر اللبنى يشبه العسل، لا حلاوة له. والعسالة: شورة النحل يتخذ فيها العسل. والعاسل: الذي يشتار العسل من موضعه فيستخرجه. قال عرام: العسال والعاسل واحد. قال لبيد: 1 بأشهب من أبكار مزن سحابة ... وأري دبور شاره النحل عاسل الأري: العسل، والدبور: النحل. وعسل النحل تعسيلا. وطعام معسل معسول: مجعول فيه العسل، ومعقد به وناقة عسول، وجمل عسال، إذا كان (باقي السير سريعه) 2 وناقة عسالة أيضا والعاسل والعسال والمعسل والمتعسل من يطلب العسل. والعسل: الرجل الشديد الضرب السريع رجع اليدين بالضرب 3 . قال: 4 تمشي موائله والنفس تنذرها ... مع الوبيل بكف الأهوج العسل 1 وكلام معسول: حلو. والعسلان: شدة اهتزاز، إذا هززته. عسل يعسل عسلانا كما يعسل الذئب إذا مشي مسرعا، وهز رأسه فالذئب عاسل، ويجمع على عسل وعواسل، والرمح عسال. قال: 2 بكل عسال إذا هز عسل وقال: عسلان الذئب أمسي طاويا ... برد الليل عليه فنسل والدليل يعسل في المفازة، أي يسرع.'),
(251, 'علس', 'علس', 'علس', 'العلس: الشرب. علس يعلس علسا، أي: شرب. قال أبو ليلى: العلس لما يؤكل ويشرب جميعا. والعلس الشواء السمين. وقال غير الخليل: العليس الذي ليس بالسمين ولا [ال] 3 مهزول، بين ذلك. والمسيب بن علس شاعر. غير الخليل: العلس: القراد.'),
(252, 'سعل', 'سعل', 'سعل', 'السعال: معروف. تقول: سعل يسعل سعالا وسعلة شديدة. وإنه لذو سعال ساعل، كما تقول: شغل شاغل، وشعر شاعر. قال: 4 ذو ساعل كسعلة المزفور والسعلاة من أخبث الغيلان، ويجمع على سعالى. ويقال للمرأة الصخابة: استسعلت، أي: صارت كالسعلاة، كما قالوا: استكلب، واستأسد وثلاث سعليات، وتصغر: سعيلية، وثلاث سعالى صواب أيضا. قال حميد: 1 فأضحت تعالى بالرجال كأنها ... سعالى بجنبي نخلة وسلوق'),
(253, 'لعس', 'لعس', 'لعس', 'اللعس: لعسة، وهو سواد يعلو الشفة للمرأة البيضاء. وجعلها رؤبة في الجسد كله إذا كان بياضا ناصعا يعلوه أدمة خفية. قال الراجز: 2 وبشر 3 مع البياض ألعسا يريد بالبشر: جلدها. وامرأة لعساء. قال ذو الرمة 4 : لمياء في شفتيها حوة لعس ... وفي اللثات وفي أنيابها شنب ورجل متلعس: شديد الأكل. ورجل لعوس لحوس، أي: أكول حريص. والجمع: لعاوس 5 . قال 6 : وماء هتكت الليل عنه ولم يرد ... روايا الفراخ والذئاب اللعاوس ويروى بالغين. والبيت لذي الرمة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(254, 'سلع', 'سلع', 'سلع', 'السلع: نبات، يقال: هو سم. قال العجاج: 1 فظل يسقيها السمام الأسلعا أي: السم الأشد. وقال في موعظة يصف الدنيا: أسبابها رمام وقطافها سلع. والسلع: شق في الجبل كهيئة الصدع. وبكسر السين أيضا، والجميع: السلوع، وهو أيضا الشيء الذي يكون في العقب. يقال: به سلع وزلع، وسلعت يده وزلعت. ويقال للدليل الهادي: مسلع، أي يشق بالقوم أجواز الفلا: قالت الخنساء: 2 سباق عادية ورأس سرية ... ومقاتل بطل وهاد مسلع والسلعة تجمع على سلع وما كان متجورا به من رقيق وغيره. والسلعة يخفف ويثقل: خراج، ويخرج كهيئة الغدة في العنق أو غيره، يمور بين الجلد واللحم، تراه يديص ديصانا إذا حركته. يديص: يتقلب. وسلع: موضع بالحجاز. قال: 3 أرقت لتوماض البروق اللوامع ... ونحن نشادي بين سلع وفارع'),
(255, 'لسع', 'لسع', 'لسع', 'اللسع للعقرب تلسع بالحمة. والحية تلسع أيضا، ويقال: إن من الحيات ما تلسع بلسانها كلسع الحمة وليس لها أسنان. ولسع فلان فلانا بلسانه، أي: قرصه. وإنه للسعة للناس، أي: قراصة لهم بلسانه. والملسعة: المقيم الذي لا يبرح. قال: 1 ملسعة وسط أرباعه ... به عسم يبتغي أرنبا ليجعل في رجله كعبها ... حذار المنية أن يعطبا وذلك أن العرب كانوا يعلقون في أرجلهم كعاب الأرانب كالمعاذة لئلا يموتوا، وهو باطل. والملسعة مثل علامة وداهية.'),
(256, 'عسن', 'عسن', 'عسن', 'العسن: نجوع العلف والرعي في الدواب. عسنت الإبل عسنا إذا نجع فيها الكلأ وسمنت. ودابة عسن، أي: شكور. وعسن: موضع. قال: 2 كأن عليهم بجنوب عسن ... غماما يستهل ويستطير'),
(257, 'عنس', 'عنس', 'عنس', 'العنس من أسماء الناقة سميت به لتمام سنها وشدة قوتها. ووفور عظامها وأعضائها واعنيناس ذنبها، أي: وفور هلبه وطوله. قال: 3 وكم قطعنا من علاة عنس وقال الطرماح: 1 يمسح الأرض بمعنونس ... مثل مئلاة النياح الفئام وعنست المرأة تعنس عنوسا، إذا صارت نصفا وهي بعد بكر لم تزوج. وعنسها أهلها تعنيسا إذا حبسوها عن الإزواج حتى تجاوزت فتاء السن، ولما تعجز بعد فهي معنسة، ويجمع على معانس ومعنسات، ويجمع العانس بالعوانس. قال: 2 وعيط كأسراب القطا قد تشوفت ... معاصيرها والعاتقات العوانس قال عرام: والقاعدات. وقال ابو ليلى: جماعة العانس: عنس، وأنشد: 3 تجمع العون على العنس من كل فخجاء لبود البرنس وعنس: قبيلة من مذحج.'),
(258, 'سعن', 'سعن', 'سعن', 'السعن يتخذ من الأدم شبه الدلو إلا أنه مستطيل مستدير، ربما جعلت له قوائم وينتبذ فيه. وقد يكون على تلك الخلقة من الدلاء صغيرا [فتسميه] 4 العرب السعن، وجمعه: سعنة وأسعان. قال: سعن وسعن كلاهما. وقال عرام: السعن عندنا قربة بالية قد تخرق عنقها يبرد فيها الماء، ولا يسمى الدلو سعنا، وأنشد لعنترة 5 : كذب العتيق وماء سعن بارد ... إن كنت سائلة غبوقا فاذهبي ويروي: وماء شن. والمسعن من الغروب يتخذ كل واحد من أديمين يقابل بينهما فيعرقان عراقين، وله خصمان من جانبين لو وضع لقام قائما من استواء أعلاه وأسفله. والسعن: ظلة يتخذها أهل عمان فوق سطوحهم من أجل ندى الومدة 1 والجميع: السعون.'),
(259, 'نعس', 'نعس', 'نعس', 'نعس ينعس نعاسا ونعسة شديدة فهو ناعس. وقد سمعناهم يقولون: نعسان ونعسى، حملوه على وسنان ووسنى، وربما حملوا الشيء على نظائره، وأحسن ما يكون ذلك في الشعر.'),
(260, 'سنع', 'سنع', 'سنع', 'امرأة سنيعة قد سنعت سناعة، وهي الجميلة اللينة المفاصل اللطيفة العظام في كمال. والسنيع: التام الضليع من كل شيء. والسنع: السلامى التي تصل ما بين الأصابع والرسغ في جوف الكف. الواحدة: سنعة ويجمع على أسناع.'),
(261, 'نسع', 'نسع', 'نسع', 'النسع: سير يضفر كهيئة أعنة البغال يشد به الرحال. والقطعة منها: نسعة تشد على طرفي البطان، ويجمع على نسوع وأنساع. والمرأة الناسعة هي الطويلة المتك. ونسوعه: طوله.'),
(262, 'عسف', 'عسف', 'عسف', 'العسف: السير على غير هدى، وركوب الأمر من غير تدبير، وركوب مفازة بغير قصد، ومنه التعسف. قال: 1 قد أعسف النازح المجهول معسفه ... في ظل أخضر يدعو هامه البوم والعسيف: الأجير. قال: 2 كالعسيف المربوع شل جمالا ... ما له دون منزل من بيات وعسف البعير يعسف عسفا (وعسوفا) 3 إذا كان في حشرجة الموت، وهو مثل النزع للإنسان وهو أهون من كرير الحشرجة. وعسفان: موضع بالحجاز.'),
(263, 'عفس', 'عفس', 'عفس', 'العفس: شدة سوق الإبل. قال: 4 يعفسها السواق كل معفس والرجل يعفس المرأة برجله إذا ضربها على عجيزتها، يعافسها وتعافسه. قال غيره: المعافسة: المعاركة في جد أو لعب، وأصله اللعب. والعفاس: اسم ناقة. قال 1 : أشلى العفاس وبروعا والعفس. أن ترد رأس الدابة إلى صدرها.'),
(264, 'سعف', 'سعف', 'سعف', 'السعف: أغصان النخلة. الواحدة: سعفة. وأكثر ما يقال ذلك إذا يبست، فإذا كانت رطبة فهي شطبة. وشبه امرؤ القيس ناصية الفرس بسعف النخل حيث يقول: 2 وأركب في الروع خيفانة ... كسا وجهها سعف منتشر والسعفة قروح تخرج على رأس الصبي وفي وجهه، سعف الصبي إذا ظهر به ذلك فهو مسعوف. والإسعاف: قضاء الحاجة. والمساعفة: المواتاة على الأمر في حسن معاونة. قال: 3'),
(265, 'عسب', 'عسب', 'عسب', 'العسب: طرق الفرس، وربما استعمله الشاعر في الناس. قال زهير: 1 فلولا 2 عسبه لرددتموه ... وشر منيحة أير معار قال أبو ليلى: العسب: ماء الفحل فرسا كان أو بعيرا. يقال: قطع الله عسبه، أي: ماءه وولده. وقال 3 يصف نجائب قد رمت بأولادها من التعب: يغادرن عسب الوالقي وناصح 4 ... تخص به أم الطريق عيالها أم الطريق: معظمه. يقول: هذه الإبل ترمي بأجنتها فتأكلها الطير والسباع. وعسيب الذنب: عظمه الذي فيه منابت الشعر. والعسيب من النخل: جريدة مستقيمة دقيقة يكشط خوصها. وجمعه عسبان، وثلاثة أعسبة. واليعسوب: أمير النحل وفحلها، ويقال: هي دبرة عظيمة مطاعة [فيها] إذا أقبلت أقبلت، وإذا أدبرت أدبرت. واليعسوب: ضرب من الحجلان من أعظمها. قال أبو ليلى: هو اليعقوب من الحجلان لا اليعسوب. واليعسوب: دائرة عند مركض الفرس حيث يصيب رجل الفارس. واليعسوب أيضا طائر يشبه به الخيل والكلاب لضمرها.'),
(266, 'عبس', 'عبس', 'عبس', 'عبس يعبس عبوسا فهو عابس الوجه غضبان. فإن أبدى عن أسنانه في عبوسه قلت كلح. وإن أهتم لذلك وفكر فيه، قلت: بسر، وهكذا قول الله عز وجل عبس وبسر 1 . وبلغنا أن النبي صلى الله عليه وآله كان مقبلا على رجل يعرض عليه الإسلام فأتاه ابن أم مكتوم، فسأله عن بعض ما كان يسأل فشغله عن ذلك الرجل فعبس رسول الله صلى الله عليه وآله وجهه، وليس من التهاون به، ولكن لما كان يرجو من إسلام ذلك الرجل، فأنزل الله: عبس وتولى أن جاءه الأعمى 2 وإن رأيته مع ذلك مغضبا قلت: بسل. وإن رأيته مع ذلك وقد زوى بين عينيه قلت: قطب وقطب أيضا فهو عابس وقاطب. والعبس: ما يبس على هلب الذنب من البعر والبول، وهو من الإبل كالوذح من الشاء الذي يتعلق بأذنابها وألياتها وخصاها، ويكون ذلك من السمن. وفي الحديث: مر رسول الله بإبل قد عبست في أبوالها فتقنع بثوبه 3 . وقد عبست فهي عبسة. قال: 4 كأن في أذنابهن الشول ... من عبس الصيف قرون الأيل ويوم عبوس: شديد.'),
(267, 'سبع', 'سبع', 'سبع', 'السبع: واحد السباع. والأنثي سبعة. وسبعت فلانا عند فلان إذا وقعت فيه وقيعة مضرة. وعبد مسبع في لغة هذيل عبد مترف. ويقال: ترك حتى صار كالسبع لجرأته على الناس. وهو في لغة الدعي. قال العجاج: 1 إن تميما لم يراضع مسبعا ... ولم تلده أمه مقنعا أي: لم يكن ملففا خوف الفضيحة، أي: لم يولد زنى. قال أبو ليلى: والمسبع: الراعي الذي أغارت السباع على غنمه فهو يصيح بالسباع وبكلابه. قال 2 : قد أسبع الراعي وضوضى أكلبه ... واندفع الذئب (وشاه يسحبه) وقال أبو ليلى وعرام: المسبع ولد الزنى. وقال أبو ذؤيب: 3'),
(268, 'عسم', 'عسم', 'عسم', 'العسم: يبس في المرفق تعوج منه اليد. عسم الرجل فهو أعسم، والأنثي عسماء. والعسوم: كسر الخبز القاحل اليابس. الواحد: عسم، وإن أنثت قلت: عسمة. قال 1 : ولا أقوات أهلهم العسوم والعسم: الطمع. قال 2 : استسلموا كرها ولم يسالموا ... كالبحر لا يعسم فيه عاسم أي: لا يطمع فيه طامع أن يغالبه ويقهره، وقد قيل: لا يمشي فيه ماش. وأقول: يد عسمة وعسماء. والأرض من العضاه وما شابهه عسوم وأعسام وعسون وأعسان. وأقول: رأيت بعيرا حسن الأعسان والأعسام، أي: حسن الخلق والجسم والألواح. وتقول: ظل العبد يعسم عسمانا، وهو الزميل وما شاكله. ومثل يعسم: يرسم من الرسيم. والعسمان الحفدان، وهو خبب الدابة. ويد عسمة وعسماء، أي: معوجة. وعسم بنفسه إذا ركب رأسه ورمى بنفسه وسط جماعة في حرب. وعسم واعتسم، أي اقتحم غير مكترث.'),
(269, 'عمس', 'عمس', 'عمس', 'العماس: الحرب الشديد وكل أمر لا يقام له ولا يهتدى لوجهه. ويوم عماس من أيام عمس. وعمس يومنا عماسة وعموسا. قال 1 : ونزلوا بالسهل بعد الشأس ... [من مر أيام] 2 مضين عمس ويقال: عمس يومنا عماسة عموسة 3 . قال: 4 إذ لقح اليوم العماس واقمطر والليلة العماس: الشديدة الظلمة عن شجاع. وتعامست عن كذا: إذا أريت كأنك لا تعرفه، وأنت عارف بمكانه. وتقول: اعمس الأمر، أي: اخفه ولا تبينه حتى يشتبه. والعماس من أسماء الداهية.'),
(270, 'سعم', 'سعم', 'سعم', 'السعم: سرعة السير والتمادي. قال 1 وقلت إذ لم أدر ما أسماؤه ... سعم المهاري والسرى دواؤه'),
(271, 'سمع', 'سمع', 'سمع', 'السمع: الأذن، وهي المسمعة، والمسمعة خرقها، والسمع ما وقر فيها من شيء يسمعه. يقال: أساء سمعا فأساء جابة، أي: لم يسمع حسنا فاساء الجواب. وتقول: سمعت أذني زيدا يقول كذا وكذا، أي: سمعته، كما تقول: أبصرت عيني زيدا يفعل كذا وكذا، أي: أبصرت بعيني زيدا 2 . والسماع ما سمعت به فشاع. وفي الحديث: من سمع بعبد سمع الله به ، أي: من أذاع في الناس عيبا على أخيه المسلم أظهر الله عيوبه. ويقال: هذا قبيح في السماع، وحسن في السماع، أي إذا تكلم به. والسماع الغناء. والمسمعة: القينة المغنية. والسمعة: ما سمعت به من طعام على ختان وغيره من الأشياء كلها، تقول: فعل ذاك رياء وسمعة، أي: كي يرى ذلك، ويسمع. وسمع به تسميعا إذا نوه به في الناس. والمسمع من المزادة ما جاوز خرت العروة إلى الظرف. والجميع: المسامع. ومسمع الدلو والغرب: عروة في وسطه يجعل فيه حبل ليعتدل. قال أوس بن حجر 1 : ونعدل ذا الميل إن رامنا ... كما يعدل الغرب بالمسمع أي: بأذنه. والسامعة في قول طرفة: الأذن، حيث يقول: 2 كسامعتي شاة بحومل مفرد ويجمع على سوامع. والسمع: سبع بين الذئب والضبع. قال 3 فإما تأتني أتركك صيدا ... لذئب القاع والسمع الأزل الأزل: الصغير المؤخر الضخم المقدم. والسمعمع من الرجال: المنكمش الماضي، وهو الغول أيضا. يقال: غول سمعمع، وأمرأة سمعمعة، كأنها غول أو ذئبة. ويقال: السمعمع من الرجال: الصغير الرأس والجثة، وهو في ذلك منكر داهية. قال 1 هولول إذا دنا القوم نزل ... سمعمع كأنه سمع أزل هولول، أي خفيف خدوم. وقال: سمعمع كأنني من جن 2 ويقال للشيطان: سمعمع لجنته. ويقال: النساء أربع: جامعة تجمع، ورابعة تربع، وشيطان سمعمع (ورابعتهن القرثع) 3 فالجامعة الكاملة في الخصال تجمع الجمال والعقل والخير كله. والرابعة التي تربع على نفسها إذا غضب زوجها. والسمعمع: الصخابة السليطة شبهت بشيطان سمعمع. والقرثع: البذيئة الفاحشة، ويقال: هي التي تكحل إحدى عينيها وتدع الأخرى 4 لحمقها 5'),
(272, 'طزع', 'طزع', 'طزع', 'رجل طزع: لا غيره له. وقد طزع يطزع طزعا إذا لم يغر.'),
(273, 'عزد', 'عزد', 'عزد', 'العزد: الجماع'),
(274, 'عزر', 'عزر', 'عزر', 'العزير: ثمن الكلأ، ويجمع على عزائر. إذا حصدت الحصائد بيعت مراعيها. وعزائرها 1 والتعزير: ضرب دون الحد. قال 2 : وليس بتعزير الأمير خزاية ... علي إذا ما كنت غير مريب والتعزير: النصرة. عزير: اسم. عيزار اسم.'),
(275, 'عرز', 'عرز', 'عرز', 'العارز: العاتب. قال الشماخ 1 : وكل خليل غير هاضم نفسه ... لوصل خليل صارم أو معارز وتقول: استعرز علي، أي: استصعب. والعرز واحدتها بالهاء، من الشجر من أصاغر الثمام وأدقه، ذات ورق صغار متفرق، وما كان من شجر الثمام من ضروبه فهو ذو أماصيخ، أمصوخة في أمصوخة إذا امتصخت انقلعت العليا من جوف السفلى انقلاع العفاص من رأس المكحلة. والتعريز كالتعريض في الخصومة. ويقال: العرز: اللوم. قال مزاحم: التعريز: التوذير 2 ، وإفساد وإفساد الشيء وتعييبه. أعرز الله منه، أي: أعوز منه وأفقده وعيب شخصه. وعرز منه بمعناه ويقال: التعريز: الخسف والإعواز، أعرز الله به، أي: خسف به.'),
(276, 'زعر', 'زعر', 'زعر', 'الزعر: قلة شعر الرأس، وقلة ريش الطائر وتفرقه، إذا ذهب أطوله وبقي أقصره وأردؤه، قال علقمة 3 : كأنها خاضب زعر قوادمها يقال: زعر يزعر زعرا، وازعار ازعيرارا. والزعارة، الراء شديدة، شراسة في خلق الرجل، لا يكاد ينقاد، ولا يلين، ولا يعرف منه فعل وليس لها نظائر إلا حمارة القيظ، وصبارة الشتاء، وعبالة البقل، ولم أسمع منه فاعلا ولا مفعولا، ولا مصروفا في وجوه. والزعرور: شجر، الواحدة بالهاء تكون حمراء ثمرتها، وربما كانت صفراء نواتها كنواة النبق في الصلابة والاستدارة، إلا أنها مطبقة تكون اثنتين 1 في ثمرة واحدة، ونواة النبق واحدة أبدا.'),
(277, 'زرع', 'زرع', 'زرع', 'زرعة من أسماء الرجال، وكذلك زريع. والزرع: نبات البر والشعير. الناس يحرثونه والله يزرعه، أي: ينميه حتى يبلغ غايته وتمامه. ويقال للصبي: زرعه الله أي: بلغه تمام شبابه. والمزدرع: الذي يزرع، أو يأمر بحرث زرع لنفسه خصوصا. دخلته الدال بدل تاء مفتعل، كما يقال: اجدمعوا واجتمعوا. قال شجاع: المزدرع: الأرض التي يزرع فيها. قال 2 : فاطلب لنا منهم نخلا ومزدرعا ... كما لجيراننا نخل ومزدرع والمزارع: الزارع. والمزارع الذي يزرع أرضه.'),
(278, 'عزل', 'عزل', 'عزل', 'عزلت الشيء نحيته، ورأيته في معزل، أي في ناحية عن القوم معتزلا وأنا بمعزل منه، أي: قد اعتزلته. والعزلة: الاعتزال نفسه. وعزل الرجل عن المرأة عزلا إذا لم يرد ولدها. والأعزل: الذي لا رمح له، فيعتزل عن الحرب. وعزلت الوالي: صرفته عن ولايته. والأعزل من السماكين: الذي [ينزل به القمر، والسماك الآخر هو السماك المرزم الذي لا ينزل به القمر، لأنه ليس على مجراه، وهو السماك الرامح] 1 ، وقال 2 : لا معازيل في الحروب تنابيل ... ولا رائمون بو اهتضامي وواحد المعازيل: معز [ا] ل 3 والأعزل من الدواب الذي يميل ذيله عن دبره. والعزلاء: مصب الماء من الرواية حيث يستفرغ ما فيها، ويجمع عزالي وسميت عزالي السحاب تشبيها بها. يقال: أرسلت السماء عزاليها إذا جاءت بمطر منهمر. قال 4 : يهمرها الكف على انطوائها ... همر شعيب العرف من عزلائها ويروي: مثل فنيق الغرب. ورجل معزال: لا ينزل مع القوم في السفر، ينزل وحده في ناحية. قال الأعشى 5 :'),
(279, 'عنز', 'عنز', 'عنز', 'العنز: الأنثى من المعز ومن الأوعال والظباء. والعنز: ضرب من السمك، يقال له: عنز الماء. والعنزة كهيئة عصا في طرفها الأعلى زج يتوكأ عليها الشيخ. وضرب من الطير يقال له: عنزل الماء. والعنزة والجمع العنز: دويبة، دقيق 3 الخطم يكون بالبادية، وهو من السباع يأخذ البعير من قبل دبره، قلما يرى، يزعمون أنه شيطان، يقال في قد 4 ابن عرس يدنو من الناقة الباركة فيدخل حياءها فيندس فيه حتى يصل إلى الرحم فيجد به وتسقط الناقة فتموت مكانها. والعنز: دابة تكون في الماء. قال رؤبة 5 : وإرم أحرس فوق عنز أحرس، أي: أتي عليه الدهر. والعنز: النسر الأنثي، وجمعه: عنوز، ويقال: العنز: العقاب. قال 1 : إذا ما العنز من ملق تدلت ... ضحيا وهي طاوية تحوم 2 تناولت النسوس بلهذميها ... كما يتطوح الحبل الجذيم قوله: بلهذميها، أي: بمنقاريها الأعلى والأسفل. يتطوح يأخذ الحية. والعنز من الأرض ما فيه حزونة، وأكمة، وتل فيه حجارة. قال الضرير: العنز: أكمة سوداء غليظة.'),
(280, 'نزع', 'نزع', 'نزع', 'نزعت الشيء: قلعته، أنزعه نزعا، وانتزعته أسرع وأخف. ونزع الأمير عاملا عن عمله. قال 3 : نزع الأمير للأمير المبدل ونزعت في القوس نزعا. والسياق النزع هو في النزع ينزع نزعا، أي: يسوق سوقا. والنفس إذا هويت شيئا، ونازعتك إليه فإنها تنزع إليه نزاعا. ونزعت عن كذا نزوعا، أي: كففت. والنزوع: الجمل الذي ينزع عليه الماء من البئر وحده. وبئر نزوع إذا نزعت دلاؤها بالأيدي. والنزائع التي تجلب إلى غير بلادها. الواحدة نزيعة. وكذلك النزائع من النساء يزوجن في غير عشائرهن، فينقلن 1 وفلانة تنزع إلى ولدها، أي: تحن. والنزوع: الذي يحن إلى الشيء. ونزع الرجل أخواله وأعمامه ونزعوه ونزع إليهم، أي: أشبهوه وأشبههم. قال الفرزدق: أشبهت أمك يا جرير فإنها ... نزعتك والأم اللئيمة تنزع أي اجترت شبهك إليها. ونزعت وانتزعت له آية من القرآن، ونحو ذلك. ونزعت وانتزعت له بسهم. والمنزع: السهم الذي يرمي به أبعد ما يقدر به الغلوة. قال: 2 فهو كالمنزع المريش من الشوحط ... مالت به يمين المغالي يصف فرسا شبهه بقدح حين يرسله. والمنزعة: إذا نزعت يدك عن فيك بالإناء فنحيته. تقول: إن هذا الشراب لطيب المنزعة. وتكون تعني 3 به الشرب. قال الضرير: المنزعة: الاجتذاب وهو أن يجرع جرعا شديدا. ويقال للخيل إذا جرت طلقا: لقد نزعت سننا، أي بعضها خلف بعض. قال النابغة 4 : والخيل تنزع غربا في أعنتها ... كالطير تنجو من الشؤبوب ذي البرد والتنازع: المنازعة في الخصومات ونحوها، وهي المجاذبة ايضا، كما ينازع 1 الفرس فارسه العنان. والنزعة: الموضع من رأس الأنزع، وهما نزعتان ترتفعان في جانبي الناصية، فتحاص الشعر عن موضعها. نزع ينزع نزعا فهو أنزع، والأنثى نزعاء، وقوم نزع، وغنم نزع، أي: حرامى.'),
(281, 'عزف', 'عزف', 'عزف', 'العزف: من اللعب بالدف والطنابير ونحوه. والمعازف: الملاعب التي يضرب بها. الواحد: عزف والجميع: معازف، رواية عن العرب. فإذا أفرد المعزف فهو ضرب من الطنابير يتخذه أهل اليمن. والعزف: صرف النفس عن الشيء فتدعه. والعزوف: الذي لا يكاد يثبت على خلة خليل واحد. قال 2 : عزفت بأعشاش وما كدت تعزف وقال: 3 ألم تعلمي أني عزوف عن الهوى ... إذا صاحبي من غير شيء تعصبا 4 والعزيف: أصوات الجن ولعبهم، وكل لعب عزف. وعزف الرياح: أصواتها ودويها. قال 1 عوازف جنان وهام صواخد والعزيف والعزاف رمل لبني سعد. تسمى هذه الرملة: أبرق العزاف، وفيها الجن، قريب من زرود، يسرة عن طريق الكوفة.'),
(282, 'فزع', 'فزع', 'فزع', 'فزع فزعا، أي فرق. وهو لنا مفزع، وهي لنا مفزع، وقوم لنا مفزع 2 سواء، أي: فزعنا إليهم إذا دهمنا أمر، وهو لنا مفزعة، وهي لنا مفزعة [وهم لنا مفزعة] 3 الواحد والجمع والتأنيث سواء، أي: فزعنا منه، ومن أجله فرقوا بينهما، لأن المفزع يفزع إليه، والمفزعة يفزع منه. ورجل فزاعة: يفزع الناس كثيرا.'),
(283, 'عزب', 'عزب', 'عزب', 'عزب يعزب عزوبة فهو عزب. والمعزابة: الذي طالت عزوبته حتى ما له في الأهل من حاجة 1 والمعزابة: الذي يعزب بعيره، ينقطع به عن الناس إلى الفلوات. وليس في التصريف مفعالة غير هذه الكلمة. وقالوا: معزابة توكيد النعت، وكذلك الهاء توكيد في النسابة ونحوها. ويقال: أدخلت الهاء في هذا الضرب من نعوت الرجال، لأن النساء لا يوصفن بهذه النعوت. وأعزب فلان حلمه وعقله، أي: أذهبه. وعزب عنه حلمه، أي: ذهب. عزب يعزب عزوبا. وكل شيء يفوتك حتى لا تقدر عليه فقد عزب عنك، ولا يعزب عن الله شيء. والعازب من الكلأ: البعيد المطلب. قال ابو النجم: 2 وعازب نور في خلائه ... في مقفر الكمأة من جنائه وأعزب القوم: أصابوا عازبا من الكلأ. ويقال: العازب: ما لم يرع قط.'),
(284, 'زعب', 'زعب', 'زعب', 'الزاعبية: الرماح المنسوبة، ولا يعلم الزاعب أرجل هو أم بلد. قال 1 : والزاعبية ينهلون صدورها والأزعب: ضرب من الأوتار جيد: قال قيس بن الإطنابة: كما طنت الأزعب المحصد 2 أنث (طنت) ، لأنه رده على طنة واحدة. والتزعب: من النشاط والسرعة. والزاعب: الهادي السياح في الأرض. قال ابن هرمة: يكاد يهلك فيها الزاعب الهادي 3 وزعبت الإناء والقربة زعبا إذا ملأته، ويقال: إذا احتملتها وهي مملوءة. والرجل يزعب المرأة إذا ملأ [فرجها بفرجه] 4 من ضخمه. وزعبت له من مالي زعبة، أي: قطعت له قليلا من كثير.'),
(285, 'زبع', 'زبع', 'زبع', 'الزوبعة: اسم شيطان، ويكنى الإعصار أبا زوبعة حين يدوم ثم يرتفع إلى السماء ساطعا، يقال فيه شيطان مارد. وتزبع فلان: تهيأ للشر. قال متمم بن نويرة 5 : وإن تلقه في الشرب لا تلق فاحشا ... على القوم ذا قاذورة 6 متزبعا'),
(286, 'بزع', 'بزع', 'بزع', 'بزع الغلام بزاعة فهو بزيع، وجارية بزيعة يوصف بالظرافة والملاحة (و) 1 ذكاء القلب، لا يقال إلا للأحداث. وتبزع الشر أي: هاج وأرعد 2 ولما يقع. قال 3 : إنا إذا أمر العدى تبزعا ... وأجمعت بالشر أن تلفعا وبوزع رملة لبني سعد. قال 4 : برمل يرنا 5 وبرمل بوزعا وبوزع: من أسماء النساء.'),
(287, 'عزم', 'عزم', 'عزم', 'العزم: ما عقد عليه القلب أنك فاعله، أو من أمر تيقنته. وما لفلان عزيمة، أي: ما يثبت على أمر يعزم عليه، وما وجدنا له عزما، وإن رأيه لذو عزم. والعزيمة: الرقى ونحوها يعزم على الجن ونحوها من الأرواح، ويجمع: عزائم. وعزائم القرآن: الآيات التي يقرأ بها على ذوي الآفات لما يرجى من البرء بها. والاعتزام: لزوم القصد في الحضر والمشي وغير ذلك. قال رؤبة: إذا اعتزمن الرهو في انتهاض ... جاذبن 1 بالأصلاب والأنواض يريد بالأنواض: الأنواط، لأن الضاد والطاء تتعاقبان. والرهو: الطريق هاهنا. والرجل يعتزم الطريق فيمضي فيه [و] لا ينثني. قال حميد: 2 معتزما للطرق النواشط النواشط: التي تنشط من بلد إلى بلد.'),
(288, 'زعم', 'زعم', 'زعم', 'زعم يزعم زعما وزعما إذا شك في قوله، فإذا قلت ذكر فهو أحرى إلى الصواب، وكذا تفسير هذه الآية هذا لله بزعمهم 3 ويقرأ بزعمهم، أي: بقولهم الكذب. وزعيم القوم: سيدهم ورأسهم الذي يتكلم عنهم. زعم يزعم زعامة، أي: صار لهم زعيما سيدا. قالت ليلى 4 : حتى إذا رفع اللواء رأيته ... تحت اللواء على الخميس زعيما والتزعم: التكذب. قال 1 : يا أيها الزاعم ما تزعما والزعيم: الكفيل بالشيء، ومنه قوله تعالى: وأنا به زعيم 2 أي: كفيل. وزعم فلان في غير مزعم، أي: طمع في غير مطمع. وأزعمته: أطمعته. وزعامة المال: أكثره وأفضله من الميراث. قال لبيد 3 : تطير عدائد الأشراك شفعا ... ووترا والزعامة للغلام وقال عنترة 4 : علقتها عرضا وأقتل قومها ... زعما لعمر أبيك ليس بمزعم أي: طعما ليس بمطمع. والزعوم من الجزر التي يشك في سمنها حتى تضبث بالأيدي فتغبط، وتلمس بها، وهي الضبوث 5 والغبوط. قال 6 : مخلصة الأنقاء أو زعوما والزعيم: الدعي. وتقول زعمت أني لا أحبها، ويجوز في الشعر: زعمتني لا أحبها. قال 7 فإن تزعميني كنت أجهل فيكم ... فإني شريت الحلم بعدك بالجهل وأما في الكلام فأحسن ذلك أن توقع الزعم على أن، دون الاسم. وتقول: زعمتني فعلت كذا. قال: زعمتني شيخا ولست بشيخ ... إنما الشيخ من يدب دبيبا 1'),
(289, 'معز', 'معز', 'معز', 'المعز اسم جامع لذوات الشعر من الغنم. قال الضرير: المعيز والمعز والماعز واحد، والمعنى جماعة. ويقال: معيز مثل الضئين في جماعة الضأن، والواحد: الماعز والأنثى ماعزة. قال 2 : ويمنحها بنو أشجى بن جرم ... معيزهم حنانك ذا الحنان والأمعوزة 3 : جماعة الثياتل من الأوعال. ورجل ماعز: شديد عصب الخلق. ما أمعزه، أي: ما أصلبه وأشده. ورجل ممعز، أي: شديد الخلق والجلد. والأمعز والمعزاء من الأرض: الحزنة الغليظة، ذات حجارة كثيرة، ويجمع على معز وأماعز ومعزاوات. فمن جعله نعتا قال للجميع معز، نطق الشاعر بكل هذا. قال 4 : جماد بها البسباس ترهص معزها ... بنات اللبون والصلاقمة الحمرا جماد: بلاد ينبت البسباس. والصلقامة: الجمل المسن. يقول: إذا وطئت هذه الصلاقمة المعزاء رهصتها أخفافها فورمت، لأنه غليظ.'),
(290, 'زمع', 'زمع', 'زمع', 'الزمع: هنات شبه أظفار الغنم في الرسغ، في كل قائمة زمعتان كأنهما خلقتا من القرون، تكون لكل ذي ظلف ويقال: للأرانب زمعات خلف قوائمها، ولذلك يقال لها: زموع. قال الشماخ 1 : وما تنفك بين عويرضات ... تجر برأس عكرشة زموع قال حماس: زموع: فردة من الأرانب تكون وحدها. والزمعة: النهر الصغير، ويسمى التلعة الزمعة. والزمعة من الكلأ: الفردة من صغار الحشيش مما تأكل الشاء والأماعز. ويقال: بل الزموع من الأرانب السريعة النشيطة التي تزمع زمعانا يعني سرعتها وخفتها. ويقال لرذالة الناس إنما هم زمع. وأزماع عند الرجال بمنزلة الزمع من الظلف. قال 2 : ولا الجدا من مشعب حباض ... ولا قماش الزمع الأحراض يقول: لا ينقمشون من قلة الخير فيهم. ويروى من متعب. وقوله: من مشعب، أي في مفرد من الناس. والحابض: الفشل من الرجال، وهو السفلة. وقوله: أحراض، أي: قصار لا خير فيهم. ويقال: رجل زمع، أي خفيف للحادث. والزماعة التي تتحرك من رأس الصبي من يافوخه، وهي اللماعة. والزميع: الشجاع الذي يزمع بالأمر ثم لا ينثني، وهم الزمعاء، والمصدر منه: الزماع. قال 1 : وصله بالزماع وكل أمر ... سما لك أو سموت له ولوع أي: هو عزم. وأزمعوا على كذا إذا ثبت عليه عزيمة القوم أن يمضوا فيه لا محالة. وأزمعوا بالابتكار، وأزمعوا ابتكارا قال 2 : أأزمعت من آل ليلى ابتكارا وأزمع النبت إزماعا إذا لم يستو النبت كله، وكان قطعة قطعة متفرقا بعضه أفضل من بعض.'),
(291, 'مزع', 'مزع', 'مزع', 'مزع الظبي في عدوه يمزع مزعا، أي: أسرع. قال: 3 فأقبلن يمزعن مزع الظباء وامرأة تمزع القطن بيديها إذا زبدته كأنما تقطعه ثم تؤلفه فتجوده بذلك. ومزعة: بقية من دسم. يقال: ما له جزعة ولا مزعة، فالجزعة: ما يبقى في الإناء، والمزعة: شيء من شحم متمزع. ويقال: إنه يكاد يتمزع من الغضب، أي يتطاير شققا. والمزعة من الريش والقطن ونحوه كالمزقة من الخرق. وقال يصف ظليما: مزع يطير به أسف خذوم 4 وقال في المزعة، أي: قطعة الشحم: 1 فلما تخلل طرف الخلال ... لم يبق في عينه مزعه يصف أعور. قوله تخلل، أي أخطأ الخلال وتحركت يده فأصاب الخلال عينه فأوجعها. ج 2'),
(292, 'عطد', 'عطد', 'عطد', 'العطود الشديد الشاق من كل شيء. وبعض يقول: عطوط. قال الراجز: 1 فقد لقينا سفرا عطودا ... يترك ذا اللون البصيص أسودا'),
(293, 'عذط', 'عذط', 'عذط', 'العذيوط: الذي إذا أتى أهله أبدى، ويجمع عذاييط وعذاويط، وإن شئت عذيوطون. وقد عذيط عذيطة.'),
(294, 'ذعط', 'ذعط', 'ذعط', 'الذعط: الذبح نفسه، وذعطته المنية قتلته. قال 1 : إذا بلغوا مصرهم عوجلوا ... من الموت بالهميع الذاعط'),
(295, 'ثعط', 'ثعط', 'ثعط', 'الثعيط: دقاق رمل يسير على وجه الأرض تنقله الريح.'),
(296, 'ثطع', 'ثطع', 'ثطع', 'الثطع من الزكام. ثطع فهو مثطوع 1 ، أي: مزكوم.'),
(297, 'عطر', 'عطر', 'عطر', 'العطر: اسم جامع الأشياء 2 الطيب. وحرفة العطار: عطارة. ورجل عطر وامرأة عطرة، إذا تعاهد نفسه بالطيب. قال أبو ليلى امرأة معطير، وأنشد 3 : يتبعن جأبا كمدق المعطير ... ينتشف البول انتشاف المعذور يصف حمار وحش.'),
(298, 'عطل', 'عطل', 'عطل', 'العطل: فقدان القلادة. عطلت تعطل عطلا وعطولا فهي عاطل، وهن عواطل. قال 1 : يرضن صعاب الدر في كل حجة ... وإن لم تكن أعناقهن عواطلا وتعطلت فهي متعطلة، وهن عطل. [وهي عطل أيضا] 2 قال الشماخ 3 : يا ظبية عطلا حسانة الجيد وقوس عطل: لا وتر عليها. والأعطال من الخيل التي لا قلائد ولا أرسان في أعناقها. والتعطيل: الفراغ، ودار معطلة. وبئر معطلة، أي: لا تورد ولا يستقى منها. وكل شيء ترك ضائعا فهو معطل. والعطيل: الطويل من النساء والنوق في حسن جسم. قال ذو الرمة 4 : رواع الفؤاد حرة الوجه عيطل ويقال للناقة الصفية الكريمة: إنها لعطلة، وما أحسن عطلها. وشاة عطلة تعرف أنها من الغزار.'),
(299, 'علط', 'علط', 'علط', 'العلط من العذار في قول الشاعر 5 : واعرورت العلط العرضي تركضه ... أم الفوارس بالدئداء والربعة ويقال اعرورت العلط من اعلواط البعير، وهو ركوب العنق، والتقحم على الشيء من فوق. والعلاطان: صفقا العنق من الجانبين من كل شيء. قال حميد 6 : من الورق سفعاء العلاطين باكرت ... فروع أشاء مطلع الشمس أسحما والعلاط: كي وسمة في العنق عرضا. وثلاثة أعلطة، ويجمع على علط. علطت البعير أعلطه علطا. قال أبو عبد الله هو أن تسمه في بعض عنقه في مقدمه، واسم تلك السمة العلاط، وبه سمي المعلوط الشاعر. والأعلواط: ركوب العنق، والتقحم على الشيء من فوق. وعلاط الإبرة خيطها. وعلاط الشمس [الذي] 7 كأنه خيط إذا رأيت. ويجمع على أعلاط، وكذلك يقال للنجوم [علاط النجم] 8 : المعلق به. قال 9 : وأعلاط النجوم معلقات ... كحبل الفرق ليس له انتصاب قال: لأن النجوم أول ما تطلع مصعدة فإذا ولت للمغيب ذهب انتصابها. وأعلاط النجوم وأفرادها، التي ليست لها أسماء كخيل القرق جعلها حجارة، لأن تلك الحجارة أفراد لا أسماء لها فكذلك هذه النجوم لا أسماء لها. والقرق لعبة لهم. جعلها خيلا، لأنهم يلعبون هذه اللعبة بالحجارة 10 . طلع: المطلع: الموضع الذي تطلع عليه الشمس. والمطلع: مصدر من طلع، ويقرأ مطلع الفجر 11 وليس بقياس. والطلعة: الرؤية. ما أحسن طلعته، أي: رؤيته. ويقال: حيا الله طلعتك. وطلع علينا فلان يطلع طلوعا إذا هجم. وأطلع فلان رأسه: [أظهره] 12 وأطلع: أشرف على الشيء، وأطلع غيره إطلاعا، ويقرأ، فهل أنتم مطلعون فأطلع 13 ، أي: تطلعونني على قريني فأنظر إليه. والاسم: الطلع. تقول: أطلعني طلع هذا الأمر حتى علمته كله. وطالعت فلانا: أتيته ونظرت ما عنده. والطليعة: قوم يبعثون ليطلعوا طلع العدو. ويقال للواحد: طليعة. والطلائع: الجماعات في السرية، يوجهون ليطالعوا العدو ويأتون بالخبز. والطلاع: ما طلعت عليه الشمس. وطلاع الأرض: ملء الأرض. وفي الحديث: لو كان لي طلاع الأرض ذهبا لافتديت به من هول المطلع 14 . والطلاع: الاطلاع نفسه في قول حميد: 15 وكان طلاعا من خصاص ورقبة ... بأعين أعداء، وطرفا مقسما أي: ينظر مرة هاهنا ومرة هاهنا. وتقول: إن نفسك لطلعة إلى هذا الأمر، أي: تتطلع 16 إليه، أي: تنازع إليه. وامرأة طلعة قبعة: تنظر ساعة وتتنحى أخرى. والطلع: طلع النخلة، الواحدة: طلعة ما دامت في جوفها الكافورة. وأطلعت النخلة، أي: أخرجت طلعة. وطلع الزرع: بدا. واستطلعت رأيه، أي: نظرت ما هو. وقوس طلاع: إذا كان عجسها يملأ الكف قال 17 : كتوم طلاع الكف لا دون ملئها ... ولا عجسها عن موضع الكف أفضلا'),
(300, 'لطع', 'لطع', 'لطع', 'لطعت عينه: لطمته. ولطعت الغرض: أصبته. ومثله: لقعته ولمعته ورقعته. ولطع الشيء: ذهب. ولطعت الشيء إذا لحسته بلسانك لطعا. ورجل لطاع: يمص أصابعه ويلحس إذا أكل. ورجل لطاع قطاع: يأكل نصف اللقمة ويرد الباقي إلى القصعة. والألطع: الذي قد ذهبت أسنانه وبقيت أسناخها في الدردر. يقال لطع لطعا. ويقال: بل هو الذي في شفته رقة [وامرأة لطعاء] 18 . واللطعاء أيضا: اليابسة الهتة منها، ويقال: هي المرأة المهزولة.'),
(301, 'عطن', 'عطن', 'عطن', 'العطن: ماء حول الحوض والبئر من مبارك الإبل ومناخ القوم، ويجمع على أعطان. عطنت الإبل تعطن عطونا و [إ] عطانها حبسها على الماء بعد الورد. قال لبيد بن ربيعة العامري: 1 عافتا الماء فلم يعطنهما ... إنما يعطن من يرجو العلل ويقال: كل مبرك يكون إلفا للإبل فهو عطن بمنزلة الوطن للناس. وقيل: أعطان الإبل لا تكون إلا على الماء، فأما مباركها في البرية فهي المأوى والمراح أيضا، وأحدهما: مأوة ومعطن مثل الموطن. قال 2 : ولا تكلفني نفسي ولا هلعي ... حرصا أقيم به في معطن الهون وعطن الجلد في الدباغ والماء إذا وضع فيه حتى فسد فهو عطن. ويقال: انعطن مثل عفن وانعفن، ونحو ذلك كذلك. وفي الحديث: وفي البيت أهب عطنة 3 .'),
(302, 'عنط', 'عنط', 'عنط', 'العنطنط اشتق من عنط، أردف بحرفين في عجزه، وامرأة عنطنطة: طويلة العنق، مع حسن قوامها، لا يجعل مصدره إلا العنط، ولو قيل عنطنطتها طول عنقها كان صوابا في الشعر، ولكن يقبح في الكلام لطول الكلمة. وكذلك يوم عصبصب بين العصابة، وفرس غشمشم بين الغشم وبين الغشمشمة، ويقال بل يقال: عصيب بين العصابة، ولا يقال عصبصب بين العصابة، ولكن بين العصبصبة. والغشمشم: الحمول الذي لا يبالي ما وطىء وكيف ركض وهو شبه الطموح. قال رؤبة: يمطو السرى بعنق عنطنط 4'),
(303, 'طعن', 'طعن', 'طعن', 'طعن فلان على فلان طعنانا في أمره وقوله إذا أدخل عليه العيب. وطعن فيه وقع فيه عند غيره. قال 5 : وأبى الكاشحون يا هند إلا ... طعنانا وقول ما لا يقال وطعنه بالرمح يطعن بضمة العين طعنا، ويقال: يطعن بالرمح ويطعن بالقول. قال: كلاهما مضموم. والإنسان يطعن في مفازة ونحوها، أي: مضى وأمعن.. وفي الليل إذا سار فيه. وطعن فهو مطعون من الطاعون، وطعين. قال النابغة 6 : فبت كأنني حرج لعين ... نفاه الناس، أو دنس طعين والأطعان: التطاعن من مطاعنة الفرسان في الحرب، تطاعنوا واطعنوا، وكل شيء نحو ذلك مما يشترك الفاعلان فيه يجوز فيه التفاعل والافتعال، نحو: تخاصموا واختصموا إلا أن السمع آنس فإذا كثر سمعك الشيء استأنست 7 به، وإذا قل سمعك استوحشت منه. ويقال: طاعنت الفرسان. قال دريد بن الصمة 8 : وطاعنت عنه الخيل حتى تبددت ... وحتى علاني حالك اللون أسود وطعن في السن: دخل فيه دخولا شديدا.'),
(304, 'نعط', 'نعط', 'نعط', 'ناعط: اسم جبل.'),
(305, 'نطع', 'نطع', 'نطع', 'النطع ما يتخذ من الأدم، وتصحيحه: كسر النون وفتح الطاء، يجمع على أنطاع. والنطع مثل فخذ وفخذ: ما ظهر من الغار الأعلى، وهي الجلدة الملتصقة بعظم الخليقاء، وفيها آثار كالتحزيز، ويجمع على نطوع، ومنهم من يقول للأسفل والأعلى: نطعان. والتنطع في الكلام تعمق واشتقاق.'),
(306, 'عطف', 'عطف', 'عطف', 'عطفت الشيء: أملته. وانعطف الشيء انعاج. وعطفت عليه: انصرفت. وعطفت رأس الخشبة، أي: لويت. وقوله: ثاني عطفه 1 أي: لاوي عنقه، وهن عواطف: أي: ثواني الأعناق. وثنى فلان على عطفه إذا أعرض عنك وجفاك. وتعطف على ذي رحم، في الصلة والبر. وعطف الله فلانا على فلان عطفا. والعطاف: الرجل العطيف على غيره بفضله، الحسن الخلق، البار اللين الجانب. وعطفا كل شيء جانباه [وعطفا الإنسان] 2 من لدن رأسه إلى وركه. قال 3 : فبينا الفتى يعجب الناظرين ... مال على عطفه قانعفر وعطفت الوسادة، أي: ثنيتها وارتفقتها. قال: عاطف النمرق صدق المبتذل 4 ورجل عطوف إذا عطف على القوم في الحرب فحمى دبرهم إذا انهزموا. وظبي عاطف: تعطف عنقها إذا ربضت، وربما كان الذئب عاطفا في عدوه وختله. وعطفت دابتي، وبرأس الدابة إلى وجه آخر. وهي لينة العطف، والعطف متن العنق. وفلان يتعاطف في مشيه إذا حرك رأسه. وناقة عطوف تعطف على بو فترأمه، ويجمع على عطف. وفلان يتعطف، بثوبه شبه التوسخ. والعطوف: مصيدة سميت به لأنها خشبة معطوفة، ويقال: عاطوف.'),
(307, 'عفط', 'عفط', 'عفط', 'العفط والعفيط: نثرة الضأن بأنوفها كنثر الحمار، وفي المثل: ما لفلان عافطة ولا نافطة، العافطة: النعجة، والنافطة: العنز والناقة، لأنها تنفط نفيطا. وهذا كقولهم: ما له ثاغية ولا راغية، أي: لا شاة تثغو ولا ناقة ترغو. والعافطة: الأمة، لأنها تعفط في كلامها، كما يعفط الرجل الألكن، والنافطة: الشاة. والرجل العفاطي هو الألكن الذي لا يفصح، وهو العفاط. ويقال: يعفط في كلامه عفطا، ويعفت كلامه عفتا، وهو عفات عفاط، ولا يقال على وجه النسبة: الأعفطي. والعفطة: ريح الجوف المصوت. قال موسى: العافط كلام الراعي للإبل، والنفيط للشاء ضائنها وماعزها.'),
(308, 'عطب', 'عطب', 'عطب', 'عطب الشيء يعطب عطبا، أي: هلك، وأعطبه معطبة. ويقال: أجد ريح عطبة، أي ريح خرقة، أو قطنة محترقة. قال 1 : كأنما في ذرى عمائمهم ... موضع من منادف العطب وكل شيء من ثياب القطن أخذت فيه النار فهو عطبة خلقا أو جديدا.'),
(309, 'عبط', 'عبط', 'عبط', 'عبطت الناقة عبطا، واعتبطتها اعتباطا إذا نحرتها من غير داء وهي سمينة فتية. واعتبط فلان: مات فجأة من غير علة ولا مرض. وقولهم: الرجل يعبط بسيفه في الحرب عبطا، اشتق من ذلك. ويعبط نفسه في الحرب إذا ألقاها فيها، غير مكره. قال أبو ذؤيب 2 : بنوافذ ... كنوافذ العبط التي لا ترقع 3 واحد العبط: عبيط. والرجل يعبط الأرض عبطا، ويعتبطها إذا حفر موضعا لم يحفره قبل ذلك، وكل مبتدأ من حفر أو نحر أو ذبح أو جرح فهو عبيط. قال مرار بن منقذ 4 : ظل في أعلى يفاع جاذلا ... يعبط الأرض اعتباط المحتفر ومات فلان عبطة، أي: شابا صحيحا. قال أمية بن أبي الصلت 5 : من لم يمت عبطة يمت هرما ... الموت كأس والمرء 6 ذائقها واعتبطه الموت. ولحم عبيط: طري، وكذلك دم عبيط. وزعفران عبيط شبيه بالدم بين العبط. وعبطته الدواهي، أي: نالته من غير استحقاق لذلك. قال حميد الأريقط 7 : (مدنسات الريب العوابط) والعبيطة: الشاة أو الناقة المعتبطة، ويجمع عبائط قال 8 : وله، لا يني، عبائط من كوم ... إذا كان من دقاق وبزل'),
(310, 'بعط', 'بعط', 'بعط', 'البعط منه الإبعاط، وهو الغلو في الجهل والأمر القبيح. يقال: منه إبعاط وإفراط إذا لم يقل قولا على وجهه، وقد أبعط إبعاطا. قال رؤبة 9 : وقلت أقوال امرىء لم يبعط ... أعرض عن الناس ولا تسخط ويقال للرجل إذا استام بسلعته فتباعد عن الحق في السوم: قد أبعط وتشحى. أو شط وأشط.'),
(311, 'طبع', 'طبع', 'طبع', 'الطبع: الوسخ الشديد على السيف. والرجل إذا لم يكن له نفاذ في مكارم الأمور، كما يطبع السيف إذا كثر عليه الصدأ. قال 10 : بيض صوارم نجلوها إذا طبعت ... تخالهن على الأبطال كتانا أي بيض كأنهن ثياب كتان، قال 11 : وإذا هززت قطعت كل ضريبة ... فخرجت لا طبعا ولا مبهورا وفلان طبع طمع إذا كان ذا خلق دنيء. قال المغيرة بن حبناء يهجو أخاه صخرا 12 : وأمك حين تذكر، أم صدق ... ولكن ابنها طبع سخيف وفلان مطبوع على خلق سيء، وعلى خلق كريم. والطباع: الذي يأخذ فيطبعها، يقرضها أو يسويها، فيطبع منها سيفا أو سكينا، ونحوه. طبعت السيف طبعا. وصنعته: الطباعة. وما جعل في الإنسان من طباع المأكل والمشرب وغيره من الأطبعة التي طبع عليها. والطبيعة الاسم بمنزلة السجية والخليقة ونحوه. والطبع: الختم على الشيء. وقال الحسن: إن بين الله وبين العبد حدا إذا بلغه طبع على قلبه، فوفق بعده للخير. والطابع: الخاتم. وطبع الله الخلق: خلقهم. وطبع على القلوب: ختم عليها. والطبع ملء المكيال. طبعته تطبيعا، أي: ملأته حتى ليس فيه مزيد. وطبعت الإناء تطبيعا. وتطبع النهر حتى إنه ليتدفق. والطبع: ملؤك سقاء حتى لا يتسع فيه شيء من شدة ملئه، والطبع كالملء، والتطبيع مصدر كالتمليء، ولا يقال للمصدر: طبع، لأن فعله لا يخفف كما يخفف فعل ملأت، لأنك تقول: طبعته [تطبيعا] 13 ولا تقول طبعته طبعا. وقول لبيد 14 : كروايا الطبع ضحت بالوحل فالطبع هاهنا الماء الذي ملىء به الراوية. يعني الربيع بن زياد ومن نازعه عند الملك. يقول: أوقرتهم 15 وأثقلت أكتافهم للذي سمعوا من كلامي وحجتي فصاروا كأنهم روايا قد أثقلت وأوقرت ماء حتى همت أن توحل حول الماء. ويقال: من طباعه السخاء، ومن طباعه الجفاء. والأطباع مغايض الماء. ويقال: هي الأنهار. الواحد: طبع. قال 16 : ولم تثنه الأطباع دوني ولا الجدر'),
(312, 'طعم', 'طعم', 'طعم', 'الطعم، طعم كل شيء وهو ذوقه. والطعم: الأكل. إنه ليطعم طعما حسنا. وهو حسن المطعم، كما تقول: حسن الملبس، أي: طعامه طيب، ولباسه جميل. وفلان حسن الطعمة كسرت كالجلسة، لأنه ضرب من الفعل، وليس بفعلة واحدة. وكل فعل واقع 1 لا يحرك مصدره نحو الطعم، لأنك تقول: طعمت الطعام، وما لم يقع يحرك مصدره مثل ندم، لأنك لا تقول: ندمت الشيء. والطعام اسم جامع لكل ما يؤكل، وكذلك الشراب لكل ما يشرب. والعالي في كلام العرب: أن الطعام هو البر خاصة. ويقال: اسم له وللخبز المخبوز، ثم يسمى بالطعام ما قرب منه، وصار في حده، وكل 2 ما يسد جوعا فهو طعام. قال [تعالى: أحل لكم صيد البحر] وطعامه متاعا لكم 3 فسمى الصيد طعاما، لأنه يسد الجوع، ويجمع: أطعمة وأطعمات. ورجل طاعم: حسن الحال في المطعم. قال: 4 فاقعد فإنك أنت الطاعم الكاسي وطعم يطعم طعاما، هكذا قياسه. وقول العرب: مر الطعم وحلو الطعم معناه الذوق، لأنك تقول: اطعمه، أي: ذقه، ولا تريد به امضغه كما يمضغ الخبز، وهكذا في القرآن: ومن لم يطعمه فإنه مني 5 فجعل ذوق الشراب طعما. نهاهم أن يأخذوا منه إلا غرفة وكان فيها ري الرجل وري دابته. رجل مطعام: يطعم الناس، ويقري الضيف 6 في الشتاء والصيف. وامرأة مطعام بغير الهاء، ورجل مطعم شديد الأكل، والمرأة بالهاء. وطعم المسافر: زاده. والطعم: الحب الذي يلقى للطير. والطعمة: المأكلة. والمطعم: القوس، لأنها تطعم الصيد. قال ذو الرمة 7 : وفي الشمال من الشريان مطعمة ... كبداء في عجسها عطف وتقويم وطعمة: من أسماء الرجال. والمطعمة: الإصبع الغليظة المتقدمة من الجوارح، لأن الجارحة به تحفظ اللحم، فاطرد هذا الإسم في الطير كلها. والمطعم من الإبل الذي تجد في مخه طعم الشحم من سمنه. وكل شيء إذا وجد طعمه فقد أطعم واطعمت الشجرة أدركت ثمرتها على بناء (افتعلت) ، يعني أخذت طعمها وطابت. قال أبو ليلى: أطعم النخل بالتخفيف. ومن طعوم يوجد فيه طعم السمن. وطعمت أطعم طعما، أي: أكلت. وجزور طعوم: بين السمين والمهزول. والمطعمتان: من رجل كل طائر: المتقدمتان المتقابلتان.'),
(313, 'طمع', 'طمع', 'طمع', 'طمع طمعا فهو طامع، وأطعمه غيره، وإنه لطمع: حريص. والأطماع: أرزاق الجند. وما أطمع فلانا، وإنه لطمع [الرجل] بضم الميم على معنى التعجب، وكذلك التعجب في كل شيء كقولك لخرجت المرأة، أي: كثيرة الخروج، ولقضو القاضي، مضموم أجمع إلا ما قالوا في نعم بئس، رواية تروى عنهم. غير لازم لقياس التعجب، لأنهم لا يقولون: نعم ولا بؤس والباقية كذلك. وامرأة مطماع: تطمع ولا تمكن. والمطمع: ما طمعت فيه، ويقال: إن قول المخاضعة لمطمعة، ونحوه في كل شيء. والمطمعة هو الطمع نفسه، طمعت فيه مطمعة.'),
(314, 'مطع', 'مطع', 'مطع', 'المطع: ضرب من الأكل بأدنى الفم، والتناول في الأكل بالثنايا وما يليها 8 من مقدمة الأسنان.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(315, 'معط', 'معط', 'معط', 'المعط: مد الشيء. وامتعطت السيف من غمده، [سللته] ، ولو قلت: معطته لاستقام، وإنه لطويل ممعط بتشديد الميم وكسر العين، أي: كأنه قد مد مدا. ومعط يمعط معطا فهو أمعط، معط. (وامعط شعره امعاطا) 9 إذا تمرط فذهب. ومعطت الشعر من رأس الشاة ونحوه إذا مددته فنتفته 10 . والأمعط: الذي لا شعر على جسده كالذئب الأمعط الذي قد تمعط شعره. ومعط الذئب، ولا يقال معط 11 شعره. ذئب أمعط يفسرونه بالخبث. والأصل ما فسرت لك، لأنه أخبث من غيره، وإذا تمرط شعره يتأذى بالذباب والبعوض، فيخرج على أذى شديد وجوع فلا يكاد يسلم منه ما اعترض له. ولص أمعط، ولصوص معط، تشبيها بالذئاب لخبثهم وهو الذي مع خبثه لا شيء معه. والمعط: ضرب من النكاح. وبنو معيط حي من قريش.'),
(316, 'عتد', 'عتد', 'عتد', 'عتد الشيء يعتد عتادا فهو عتيد: حاضر. ومنه سميت العتيدة التي يكون فيها الطيب، والأدهان. قال النابغة 1 : عتاد امرىء لا ينقض البعد همه ... طلوب الأعادي، واضح غير خامل والعتيد: الشيء المعد. أعتدناه، أي: أعددناه لأمر إن حزب. وجمعه: عتد، وأعتدة. والعتود: الجدي الذي قد استكرش. وثلاثة أعتدة، والجميع عدات: فعلان، أصله: عتدان، فأدغمت التاء في الدال. ويقال: العتود: الذي بلغ السفاد، قال 2 : واذكر غدانة عدانا مزنمة ... من الحبلق تبنى حوله الصير وتقول: هذا الفرس عتد، أي معد متى ما شئت ركبت، الذكر والأنثى فيه سواء. قال سلامة 3 : وكل طوالة عتد نزاق أي: شديد الجري.'),
(317, 'عدر', 'عدر', 'عدر', 'العدر: المطر الكثير. وأرض معدورة: ممطورة. وعدر المكان عدرا واعتدر: [كثر ماؤه] 1 . عرد: العرد: الشديد الصلب من كل شيء، المنتصب. يقال: أنه لعرد العنق، ويقال: عارد مغرز 2 العنق. قال رؤبة يصف حمار وحش 3 : عرد التراقي حشورا معقربا وعرد الناب يعرد عرودا إذا خرج كله واشتد وانتصب، وكذلك نحوه. قال ذو الرمة 4 : يصعدن رقشا بين عوج كأنها ... زجاج القنا منها نجيم وعارد والتعريد: ترك القصد، وسرعة الذهاب، والإنهزام. قال الراجز 5 : وهمت الجوزاء بالتعريد وقال لبيد 6 : فمضى وقدمها وكانت عادة ... منه إذا هي عردت إقدامها والعرد الذكر، والعرادة الجرادة الأنثى. والعرادة: ضرب من نبات الربيع حشيشه طيبة الريح. ويقال: العرادة: الحمض تأكله الإبل. والعرادة: شبه منجنيق صغيرة، ويجمع على عرادات.'),
(318, 'دعر', 'دعر', 'دعر', 'الدعر: ما احترق من حطب، أو غيره فطفىء من غير أن يشتد احتراقه. الواحدة دعرة. هو أيضا من الزناد ما قدح به مرارا حتى احترق فصار دعرا لا يوري. ويقال: هو الذي يدخن ولا يتقد. قال 7 : أقبلن من بطن فلاة بسحر ... يحملن فحما جيدا غير دعر والداعر: الخبيث الفاجر، ومصدره الدعارة. ورجل دعار، وقوم داعرون.'),
(319, 'رعد', 'رعد', 'رعد', 'الرعد: اسم ملك يسوق السحاب، وتسبيحه صوته الذي يسمع (ومن صوته اشتق رعد يرعد، ومنه الرعدة والإرتعاد) 8 . ارتعد رعدة وارتعادا. والرعدة: رجرجة تأخذ الإنسان من فزع أو داء. تقول: يرعد الإنسان، فإذا جعلت الفعل منه قلت: يرتعد. وأرعده الداء. والرعديد والرعديدة: الرجل الفروقة. وسمعت من يقول: ترعيد، كما يقولون: تعبيد. وأرعده الخوف ورجل رعديد: جبان يدع القتال من رعدة تأخذه. قال الهذلي 9 : ثأرت بأبناء الكرام ولم أكن ... لدى الروع رعديدا جبانا ولا غمرا وكل شيء يترجرج من نحو القريس فهو يترعدد، كما تترعدد الألية والفالوذج ونحوهما. قال العجاج 10 : فهي كرعديد الكثيب الأهيم وتقول: رعدت السماء وبرقت، ويقال: أرعدت وأبرقت، وسحاب رواعد وبوارق، أي ذات رعد وبرق. والرواعد: سحابات فيها ارتجاس رعد. ويقال: أرعد لي فلان وأبرق إذا هدد وأوعد (من بعيد يريني علامات بأنه يأتي إلي شرا) . قال 11 : أبرق وأرعد يا يزيد ... فما وعيدك لي بضائر وقال 12 : وهبته بأطيب الهبات ... من بعد ما قد كثرت بناتي فأرعدوا وأبرقوا عداتي هذا في بني له. ويقال: يرعد ويبرق لغتان. رعد يرعد فهو راعد. قال: فابرق هنالك ما بدا لك وارعد ويقال: الرعديد: الفالوذج، فما أدري مولد أم تليد'),
(320, 'درع', 'درع', 'درع', 'درع المرأة يذكر، ودرع الحديد تؤنث، وقال بعضهم: يذكر أيضا، والجميع: الدروع. وتصغيره: دريع بلا هاء، رواية عن العرب. والدرع اللبوس، وهو حلق الحديد. وادرع الرجل، لبس الدرع. وادرع القوم سرابيل الدم، أي: تسربلوا فجرحوا وجرحوا. قال العجاج 13 : وادرع القوم سرابيل الدم والدراع الرجل ذو الدرع إذا كانت عليه. والدراعة: ضرب من الثياب، وهو جبة مشقوقة المقدم. والمدرعة ضرب آخر، لا يكون إلا من الصوف. قال الراجز 14 : يوم لخلاني ويوم للمال ... مشمر يوما ويوما ذيال مدرعة يوما ويوما سربال يقول: أتنعم مع إخواني يوما، ويوما أصلح مالي، فأتشمر وألبس المدرعة. قال الخليل: فرقوا بينهما لاختلافهما في الصنعة إرادة الإيجاز في المنطق، وكذلك يفعلون بنحو ذلك. وصفة الرحل إذا بدا منها رءوس الواسطة والآخرة تسمى: مدرعة. ادرع الرجل، أي: لبس هذه الغواشي. والدرع مصدر الأدرع [والدرعاء] 15 وهو في ألوان الشاء: بياض في الصدر والنحر، وسواد في الفخذ، شاة درعاء.. وإذا كانت سوداء الجسد، بيضاء الرأس فهي أيضا درعاء. والليالي الدرع هي التي يطلع فيها القمر عند وجه الصبح، وسائرها أسود مظلم، شبه بالشاة التي وصفت. ويقال: الدرع: ثلاث ليال'),
(321, 'ردع', 'ردع', 'ردع', 'الردع: مقاديم الإنسان إذا كانت فيه منيته. يقال: طعنته فركب ردعه، أي: خر صريعا لوجهه. ويقال: خر في بئر فركب ردعه، وهوى فيها، فلذلك يقال: ركب ردع المنية. ويقال للفرس إذا وقع على وجهه فعطب: ركب ردعه فمات. قال 16 : أقول له والمرء يركب ردعه ... وقد شكه لدن المهزة ناجم وردعته ردعا فارتدع، أي: كففته فكف. وارتدع الرجل إذا رآك وأراد أن يعمل عملا فكف، أو سمع كلامك. وأنا ردعته عن ذلك، كأنه شبه الدفع وهو مستقبلك فردعته ردعا لا باليد بل بنظرة. قال 17 : أهل الأمانة إن مالوا ومسهم ... طيف العدو إذا ما ذكروا ارتدعوا والرادعة والمردعة: قميص قد لمع بالزعفران أو بالطيب في مواضع، وليس مصبوغا كله، إنما هو مبلق كما تردع الجارية صدر جيبها بالزعفران بملء كفها، والفعل: الردع. قال 18 : رادعة بالمسك أردانها وقال 19 : ورادعة بالطيب صفراء عندها ... لجس الندامى في يد الدرع مفتق يعني جارية قد جعلت ردعا 20 على ثيابها في مواضع. وقال رؤبة 21 : وقد فشا فيهن صبغا مردعا'),
(322, 'عدل', 'عدل', 'عدل', 'العدل: المرضي من الناس قوله وحكمه. هذا عدل، وهم عدل، وهم عدل، فإذا قلت: فهم عدول على العدة قلت: هما عدلان، وهو عدل بين العدل. والعدولة والعدل: الحكم بالحق. قال زهير 1 : متى يشتجر قوم يقل سرواتهم ... هم بيننا فهم رضى وهم عدل وتقول: هو يعدل، أي: يحكم بالحق والعدل. وهو حكم عدل ذو معدلة في حكمه. وعدل الشيء: نظيره، هو عدل فلان. وعدلت فلانا بفلان أعدله به. وفلان يعادل فلانا، وإن قلت: يعدله فحسن. والعادل: المشرك الذي يعدل بربه. والعدلان: الحملان على الدابة، من جانبين، وجمعه: أعدال، عدل أحدهما بالآخر في الإستواء كي لا يرجح أحدهما بصاحبه. والعدل أن تعدل الشيء عن وجهه فتميله. عدلته عن كذا، وعدلت أنا عن الطريق. ورجل عدل، وامرأة عدل سواء. والعدل أحد حملي الجمل، لا يقال إلا للحمل، وسمي عدلا، لأنه يسوى بالآخر بالكيل والوزن. والعديل الذي يعادلك في المحمل. وتقول: اللهم لا عدل لك، أي: لا مثل لك. ويقول في الكفارة أو عدل ذلك 2 ، أي: ما يكون مثله، وليس بالنظير بعينه. ويقال: العدل: الفداء. قال الله [تعالى] لا يقبل منها عدل 3 ويقال: هو هاهنا الفريضة. والعدل: نقيض الجور. يقال عدل على الرعية. ويقال لما يؤكل إذا لم يكن حارا ولا باردا يضر: هو معتدل. وجعلت فلانا عدلا لفلان وعدلا، كل يتكلم به على معناه. وعدلت فلانا بنظيره، أعدله. ومنه: يقال: ما يعدلك عندنا شيء، أي: ما يقع عندنا شيء موقعك. وعدلت الشيء أقمته حتى اعتدل. قال 4 : صبحت بها القوم حتى امتسكت ... بالأرض أعدلها أن تميلا أي: لئلا تميل. وعدلت الدابة إلى كذا: أي: عطفتها فانعدلت. والعدل: الطريق. ويقال: الطريق يعدل إلى مكان كذا، فإذا قالوا ينعدل في مكان كذا أرادوا الاعوجاج. وفي حديث عمر: الحمد لله الذي جعلني في قوم إذا ملت عدلوني، كما يعدل السهم في الثقاف 5 . والمعتدلة من النوق: الحسنة المتفقة الأعضاء (بعضها ببعض) 6 . والعدولية: ضرب من السفن نسب إلى موضع يقال له: عدولاة، أميت اسمه. قال حماس: وأرويه أيضا: عدولية من الاستواء والإعتدال. وغصن معتدل: مستو. وو جارية حسنة الاعتدال، أي: حسنة القامة. والانعدال: الانعراج. قال ذو الرمة 7 : وإني لأنحي الطرف من نحو غيرها ... حياء ولو طاوعته لم يعادل أي: لم ينعدل. وقال طرفة في العدولية 8 : عدولية، أو من سفين ابن يامن ... يجور بها الملاح طورا ويهتدي'),
(323, 'علد', 'علد', 'علد', 'العلد: الصلب الشديد من كل شيء كأن فيه يبسا من صلابته. وهو الراسي الذي لا ينقاد ولا ينعطف. وسيد علود: رزين ثخين، قد اعلود اعلودا. واعلود الشيء إذا لزم مكانه فلم يقدر على تحريكه. قال رؤبة 9 : وعزنا عز إذا توحدا ... تثاقلت أركانه واعلودا والعلندى: البعير الضخم، وهو على تقدير فعنلى، فما زاد على العين واللام والدال فهو فضل، والأنثى: علنداة، ويجمع علاندة وعلادى وعلنديات وعلاند، على تقرير قلانس. والعلنداة: شجرة طويلة من العضاه لا شوك لها. قال 10 : دخان العلندى دون بيتي مذود'),
(324, 'دلع', 'دلع', 'دلع', 'دلع لسانه يدلع دلعا ودلوعا، أي: خرج من الفم، واسترخى وسقط على عنفقته، كلهثان الكلب، وأدلعه العطش ونحوه، واندلع لسانه. قال أبو العتريف الغنوي 11 يصف ذئبا طرده حتى أعيا ودلع لسانه 12 : وقلص المشفر عن أسنانه ... ودلع الدالع من لسانه وفي الحديث 13 : إن الله أدلع لسان بلعم، فسقطت أسلته على صدره. ويقال للرجل المندلث البطن أمامه: مندلع البطن. والدليع: الطريق السهل في مكان حزن لا صعود فيه ولا هبوط، ويجمع: دلائع.'),
(325, 'عدن', 'عدن', 'عدن', 'عدن: موضع ينسب إليه الثياب العدنية. والمعدن: مكان كل شيء، أصله ومبتدؤه، نحو الذهب، والفضة والجوهر والأشياء، ومنه: جنات عدن. وفلان معدن الخير ومعدن الشر. عدان: موضع على ساحل من السواحل. قال لبيد 1 : ولقد يعلم صبحي أنني ... بعدان السيف صبري ونقل والعدن: إقامة الإبل على الحمض خاصة. عدنت الإبل تعدن عدونا. عدنية: من أسماء النساء والثياب. عدنان: اسم أبي معد.'),
(326, 'عند', 'عند', 'عند', 'عند الرجل يعند عندا وعنودا فهو عاند وعنيد، إذا طغى وعتا، وجاوز قدره، ومنه: المعاندة، وهو أن يعرف [الرجل] الشيء ويأبى أن يقبله أو يقر به. والعنود من الإبل: الذي لا يخالط الإبل، إنما هو في ناحية. ورجل عنود: يحل وحده، لا يخالط الناس. قال 2 : وصاحب ذي ريبة عنود ... بلد عني أسوأ التبليد وأما العنيد فهو من التجبر، لذلك خالفوا بين العنود والعاند والعنيد. ويقال للجبار العنيد: لقد عند عندا وعنودا. عند: حرف الصفة، فيكون موضعا لغيره، ولفظه نصب، لأنه ظرف لغيره، [وهو] في التقريب شبه اللزق، لا يكاد يجيء إلا منصوبا، لأنه لا يكون إلا صفة معمولا فيها، أو مضمرا فيها فعل إلا في حرف واحد، وذلك قول القائل لشيء، بلا علم: هو عندي كذا وكذا، فيقال له: أولك عند؟ فيرفع. وزعموا أنه في هذا الموضع يراد به القلب وما فيه من معقول اللب. والعرق العاند: الذي ينفجر منه الدم فلا يكاد يرقأ، وأنشد 3 : وطعنة عاندها يفور'),
(327, 'دنع', 'دنع', 'دنع', 'رجل دنع من قوم دنائع، وهو الغسل الذي لا لب له ولا عقل. والدانع: الذي يأتي مداق الأمور والمخازي ولا يكرم نفسه'),
(328, 'عدف', 'عدف', 'عدف', 'العدوف: الذواق. والعدف: اليسير من العلف. ما ذاقت الخيل عدوفا، أي: لم 1 يلكن عودا. قال 2 : إلى قلص تظل مقلدات ... أزمتهن ما يعدفن عودا والعدف: نول قليل، أصبنا عدفا من ماله. والعدفة كالصنفة من قطعة ثوب ونحو ذلك. ويقال: بل العدف اشتقاقه من العدفة، أي: يلم ما تفرق منه. قال 3 : حمال أثقال ديات الثأي ... عن عدف الأصل وجرامها ويقال: عدفة من الناس وحذفة، أي: قطعة.'),
(329, 'دفع', 'دفع', 'دفع', 'دفعت عنه كذا وكذا دفعا ومدفعا، أي: منعت. ودافع الله عنك المكروه دفاعا، وهو أحسن من دفع. والدفعة: انتهاء جماعة قوم إلى موضع بمرة. قال خلف 4 : فندعى جميعا مع الراشدين ... فندخل في آخر الدفعة وكذلك نحو ذلك. وأما الدفعة فما دفع من إناء أو سقاء فانصب بمرة. قال 5 : كقطران الشام سالت دفعه وكذلك دفع المطر نحوه. قال الأعشى 6 : وسافت من دم دفعا يصف بقرة أكل السباع ولدها. والدفاع: طحمة الموج والسيل. قال 7 : جواد يفيض على المجتدين ... كما فاض يم بدفاعه والدفاع: الشيء العظيم الذي يدفع بعضه بعضا. والدافعة: التلعة تدفع في تلعة أخرى من مسايل الماء إذا جرى في صبب وحدور فتراه يتردد في مواضع فانبسط شيئا، أو استدار، ثم دفع في أخرى أسفل من ذلك، فكل واحد من ذلك دافعة، وجمعه: دوافع، وما بين الدافعتين مذنب. والاندفاع: المضي في الأمر كائنا ما كان. وأما قول الشاعر 8 : أيها الصلصل المغذ إلى المدفع ... من نهر معقل فالمذار فيقال: أراد بالمدفع موضعا 9 وأشعث يزهاه النبوح مدفع ... عن الزاد ممن حرف الدهر محثل وإذا مات أبو الصبي فهو يتيم، وهو مدفع، أي: يدفع ويحقر. وفلان سيد قومه غير مدافع، أي: غير مزاحم فيه، ولا مدفوع عنه. وهذا طريق يدفع إلى مكان كذا. [أي: ينتهي إليه] 11 . ودفع فلان إلى فلان: انتهى إليه. وقولهم: غشيتنا سحابة فدفعناها إلى بني فلان، أي: انصرفت إليهم عنا. والدافع: الناقة التي تدفع اللبن على رأس ولدها، إنما يكثر اللبن في ضرعها حين تريد أن تضع، وكذلك الشاة المدفاع. والمصدر: الدفعة. ورأيت عليه دفعا، أي: دفعة دفعة.'),
(330, 'فدع', 'فدع', 'فدع', 'الفدع: عوج في المفاصل، [كأنها] 12 ، قد زالت عن مواضعها، وأكثر ما يكون في الأرساغ خلقة أو داء، كأنه لا يستطيع بسطه. وكل ظليم أفدع لاعوجاج في مفاصله. فدع فدعا. قال الفرزدق 13 : كم خالة لك يا جرير وعمة ... فدعاء قد حلبت علي عشاري وقال 14 : عكباء عكبرة في بطنها ثجل ... وفي المفاصل من أوصالها فدع وقال 15 : عن ضعف أطناب وسمك أفدعا جعل السمك المائل أفدع'),
(331, 'عبد', 'عبد', 'عبد', 'العبد: الإنسان حرا أو رقيقا. هو عبد الله، ويجمع على عباد وعبدين. والعبد: المملوك، وجمعه: عبيد، وثلاثة أعبد، وهم العباد أيضا. إن العامة اجتمعوا على تفرقة ما بين عباد الله، والعبيد المملوكين. وعبد بين العبودة، وأقر بالعبودية، ولم أسمعهم يشتقون منه فعلا، ولو اشتق لقيل: عبد، أي: صار عبدا، ولكن أميت منه الفعل. وعبد تعبيدة، أي: لم يزل فيه من قبل هو وآباؤه. وأما عبد يعبد عبادة فلا يقال إلا لمن يعبد الله. وتعبد تعبدا، أي: تفرد بالعبادة. وأما عبد خدم مولاه، فلا يقال: عبده ولا يعبد مولاه. واستعبدت فلانا، أي اتخذته عبدا. وتعبد فلان فلانا، أي: صيره كالعبد له وإن كان حرا. قال 1 : تعبدني نمر بن سعد، وقد أرى ... ونمر بن سعد لي مطيع ومهطع وقالوا: إذا طردك الطارد وأبى (أن) 2 ينجم عنك، [أي] 3 لا يقلع فقد تعبدك تعبدا. وأعبد فلان فلانا: جعله عبدا. وتقرأ هذه الآية على سبعة أوجه: فالعامة تقرأ: وعبد الطاغوت، أي: عبد الطاغوت من دون الله. وعبد الطاغوت، كما تقول: ضرب عبد الله. وعبد الطاغوت، أي: صار الطاغوت يعبد، كما تقول: فقه الرجل، وظرف. وعبد الطاغوت، معناه عباد الطاغوت. جمع، كما تقول: ركع وسجد. وعبد الطاغوت، أرادوا: عبدة الطاغوت مثل فجرة وكفرة، فطرح الهاء والمعنى في الهاء. وعابد الطاغوت، كما تقول: ضارب الرجل. وعبد الطاغوت، جماعة، لا يقال: عابد وعبد، إنما يقال عبود وعبد. ويقال للمشركين: عبدة الطاغوت والأوثان، وللمسلمين: عباد يعبدون الله. والمسمى بعبدة. والجزم فيها ة خطأ، إنما هو عبدة على بناء سلمة. وتقول: استعبدته وهو قريب المعنى من تعبد إلا أن تعبدته أخص، وهم العبدى، يعني: جماعة العبيد الذين ولدوا في العبودة، تعبيدة ابن تعبيدة، أي: في العبودة إلى آبائه. وأعبدني فلانا، أي: ملكني إياه. وبعير معبد: مهنوء 4 بالقطران، وخلي عنه فلا يدنو منه أحد. قال 5 : وأفردت إفراد البعير المعبد وهو الذلول أيضا، يوصف به البعير. والمعبد: كل طريق يكثر فيه المختلفة، المسلوك. والعبد: الأنفة والحمية من قول يستحي منه، ويستنكف. ومنه: فأنا أول العابدين 6 أي: الأنفين من هذا القول، ويقرأ العبدين، مقصورة، على عبد يعبد. ويقال: فأنا أول العابدين أي: كما أنه ليس للرحمن ولد فلست بأول من عبد الله من أهل مكة. ويروى عن أمير المؤمنين أنه قال: عبدت فصمت أي: أنفت فسكت. قال 7 : ويعبد الجاهل الجافي بحقهم ... بعد القضاء عليه حين لا عبد والعباديد: الخيل إذا تفرقت في ذهابها ومجيئها. ولا تقع إلا على جماعة، لا يقال للواحد: عبديد. ألا ترى أنك تقول: تفرقت فهي كلها متفرقة، ولا يقال للواحد متفرق، ونحو ذلك كذلك مما يقع على الجماعات فافهم. تقول: ذهبت الخيل عباديد، وفي بعض الكلام عبابيد. قال الشماخ 8 : والقوم أتوك بهز دون إخوتهم ... كالسيل يركب أطراف العبابيد 9 والعباديد: الأطراف البعيدة والأشياء المتفرقة، وكذا 10 العبابيد.'),
(332, 'دعب', 'دعب', 'دعب', 'الدعابة من المزاح والمضاحكة. يداعب الرجل أخاه شبه المزاح. تقول: يدعب دعبا إذا قال قولا يستملح. قال 11 : واستطربت ظعنهم لما احزأل بهم ... مع الضحى ناشط من داعبات دد رواه الخليل بالباء [وقد روي] بالياء، يعني اللواتي يدعبن بالمزاح ويدأددن بأصابعهن، ويروى: داعب ددد، يجعله نعتا للداعب، ويكسعه بدال أخرى ثالثة ليتم النعت، لأن النعت لا يتمكن حتى يصير ثلاثة أحرف، فإذا اشتقوا من ذلك فعلا أدخلوا بين الدالين همزة لتستمر طريقة الفعل، ولئلا تثقل الدالات إذا اجتمعن، فيقولون: دأدد يدأدد دأددة، وعلى ذلك القياس: قال رؤبة: يعد دأدا وهديرا زعدبا ... بعبعة مرا ومرا بأببا 12 أخبر أنه يقرقر فيقول: بب بب، وإنما حكى جرسا شبه ببب فلم يستقم في التصريف إلا كذلك، قال الراجز 13 : يسوقها أعيس هدار ببب ... إذا دعاها أقبلت لا تتئب أي: لا تستحي، ونحو ذلك كذلك من الحكايات المتكاوسة الحروف بعضها على بعض، وقلما هي تستعمل في الكلام. والداعب: اللاعب أيضا. والدعبوب: الطريق المذلل يسلكه الناس. والدعبوب: النشيط. قال 14 : يا رب مهر حسن دعبوب ... رحب اللبان حسن التقريب'),
(333, 'بعد', 'بعد', 'بعد', 'بعد: خلاف شيء وضد قبل، فإذا أفردوا قالوا: هو من بعد ومن قبل رفع، لأنهما غايتان مقصود إليهما، فإذا لم يكن قبل وبعد غاية فهما نصب لأنهما صفة. وما خلف بعقبه فهو من بعده. تقول: أقمت خلاف زيد، أي: بعد زيد. قال الخليل: هو بغير تنوين على الغاية مثل قولك: ما رأيته قط، فإذا أضفته نصبت إذا وقع موقع الصفة، كقولك: هو بعد زيد قادم، فإذا ألقيت عليه من صار في حد الأسماء، كقولك: من بعد زيد، فصار من صفة، وخفض بعد لأن من حرف من حروف الخفض، وإنما صار بعد 15 منقادا لمن، وتحول من وصفيته إلى الاسمية، لأنه لا تجتمع صفتان، وغلبه من لأن من صار في صدر الكلام فغلب. وتقول العرب: بعدا وسحقا، مصروفا عن وجهه، ووجهه: أبعده الله وأسحقه، والمصروف ينصب، ليعلم أنه منقول من حال إلى حال، ألا ترى أنهم يقولون: مرحبا وأهلا وسهلا، ووجهه: أرحب الله منزلك، وأهلك له، وسهله لك. ومن رفع فقال: بعد له وسحق يقول: هو موصوف وصفته قوله [له] 16 مثل: غلام له، وفرس له، وإذا أدخلوا الألف واللام لم يقولوا إلا بالضم، البعد له، والسحق له، والنصب في القياس جائز على معنى أنزل الله البعد له، والسحق له. والبعد على معنيين: أحدهما: ضد القرب، بعد يبعد بعدا فهو بعيد. وباعدته مباعدة، وأبعده الله: نحاه عن الخير، وباعد الله بينهما وبعد، كما تقرأ هذه الآية ربنا باعد بين أسفارنا 17 وبعد، قال الطرماح 18 : تباعد منا من نحب اقترابه ... وتجمع منا بين أهل الظنائن والمباعدة: تباعد الشيء عن الشيء. والأبعد ضد الأقرب، والجمع: أقربون وأبعدون، وأباعد وأقارب. قال 19 : من الناس من يغشى الأباعد نفعه ... ويشقى به حتى الممات أقاربه وإن يك خيرا فالبعيد يناله ... وإن يك شرا فابن عمك صاحبه ويقرأ: بعدت ثمود 20 وبعدت ثمود. إلا أنهم يقولون: بعد الرجل، وأبعده الله. والبعد والبعاد أيضا من اللعن، كقولك: أبعده الله، أي: لا يرثى له مما نزل به. قال 21 : وقلنا أبعدوا كبعاد عاد وهذا من قولك: بعدا وسحقا، والفعل منه: بعد يبعد بعدا. وإذا أهلته لما نزل به من سوء قلت: بعدا له، كما قال: بعدت ثمود، ونصبه فقال: بعدا له لأنه جعله مصدرا، ولم يجعله اسما. وفي لغة تميم يرفعون، وفي لغة أهل الحجاز أيضا.'),
(334, 'بدع', 'بدع', 'بدع', 'البدع: إحداث شيء لم يكن له من قبل خلق ولا ذكر ولا معرفة. والله بديع السموات والأرض ابتدعهما، ولم 22 يكونا قبل ذلك شيئا يتوهمهما متوهم، وبدع الخلق. والبدع: الشيء الذي يكون أولا في كل أمر، كما قال الله عز وجل: قل ما كنت بدعا من الرسل 23 ، أي: لست بأول مرسل. وقال الشاعر 24 : فلست ببدع من النائبات ... ونقض الخطوب وإمرارها والبدعة: اسم ما ابتدع من الدين وغيره. ونقول: لقد جئت بأمر بديع، أي: مبتدع عجيب. وابتدعت: جئت بأمر مختلف لم يعرف ذلك قال 25 : إن (نبا) 26 ومطيعا ... خلقا خلقا بديعا جمعة تتبع سبتا ... وجمادى وربيعا ويقرأ: بديع السماوات والأرض 27 بالنصب على جهة التعجب لما قال المشركون، بدعا ما قلتم وبديعا ما اخترقتم، أي: عجيبا، فنصبه على التعجب، والله أعلم بالصواب. ويقال: هو اسم من أسماء الله، وهو البديع لا أحد قبله. وقراءة العامة الرفع [وهو] أولى بالصواب. والبدعة: ما استحدثت بعد رسول الله ص من أهواء وأعمال، ويجمع على البدع. قال الشاعر 28 : ما زال طعن الأعادي والوشاة بنا ... والطعن أمر من الواشين لا بدع وأبدع البعير فهو مبدع، وهو من داء ونحوه، ويقال هو داء بعينه، وأبدعت الإبل إذا تركت في الطريق من الهزال وأبدع بالرجل إذا حسر عليه ظهره.'),
(335, 'عدم', 'عدم', 'عدم', 'العدم: فقدان الشيء وذهابه، والعدم لغة. إذا أرادوا التثقيل فتحوا العين، وإذا أرادوا التخفيف ضموها. عدمت فلانا أعدمه عدما، أي: فقدته أفقده فقدا وفقدانا، أي: غاب عنك بموت أو فقد لا يقدر عليه. وأعدمه الله مني كذا، أي: أفاته. ورجل عديم لا مال له، وقد عدم ماله وفقده وذهب عنه. والعديم: الفقير، لأنه فقد الغنى، وأيس منه، ويجوز جمعه على: عدماء، كما يجمع الفقير فقراء. قال 1 : فعديمنا متعفف متكرم ... وعلى الغني ضمان حق المعدم وأعدم فهو معدم، وأفقر فهو مفقر، أي: نزل به العدم والفقر فهو صاحبه. قال حسان بن ثابت 2 : رب حلم أضاعه عدم المال ... وجهل غطى عليه النعيم لأنه إذا كان فقيرا لم ير الناس له قيمة، ولا ينتفعون بحلمه، ولا يهابونه، وإذا كان غنيا هيب واحتمل له، وإن كان جهولا طمعا فيما عنده. قال 3 : أما تريني اليوم لا أعدو غنم ... أعين ما اسطعت وعوني كالعدم قال حماس: قوله: لا أعدو غنم، أي: ليس لي فضل على الغنم. أي: على حفظها، ويكون المعنى ليس عندي منفعة، ولا كفاية إلا مثل كفاية شاة من الغنم.'),
(336, 'عمد', 'عمد', 'عمد', 'عمدت فلانا أعمده عمدا، أي: قصدته وتعمدته مثله. والعمد: نقيض الخطأ. والعمدان: تعمد الشيء بعماد يمسكه ويعتمد عليه. والعمد: جمع عماد، والأعمدة جمع العمود من حديد أو خشب. وعمود الخباء من خشب قائم في الوسط. وأهل عمود وعماد: أصحاب الأخبية، لا ينزلون غيرها. وقوله: في عمد ممددة 4 أي: في شبه أخبية من نار ممدودة، ويقرأ في عمد، لغة، وهما جماعة عمود، وعمد بمنزلة أديم وأدم، وعمد بمنزلة رسول ورسل. ويقال: هي أوتاد أطباق تطبق على أهل النار، ولا يدخل جهنم بعد ذلك ريح ولا يخرج منها تنفس. والعمد: الشاب الشديد الممتلىء شبابا. يقال: عمد وعمداني وعمدانيون، والمرأة: عمدانية، أي: ذات جسم وعبالة، وهو أملأ الشباب وأردؤه. الدال شديدة في كله. عمدان: اسم جبل. والعمود عرق الكبد الذي يسقيها. ويقال للوتين: عمود السحر. وعمود البطن شبه عرق ممدود من لدن الرهابة إلى دوين السرة في وسطه يشق من بطن الشاة. وعمود السنان ما توسط شفرتيه من أصله، وهو الذي فيه خيط العير. ورجلا الظبي عموداه. وعمود الأمر: قوامه الذي يستقيم به. وعمود الأذن: معظمها وقوامها الذي تثبت عليه الأذن. وعميد القوم: سيدهم الذي يعتمدون عليه في الأمور، إذا حزبهم أمر فزعوا إليه وإلى رأيه. والعميد: المعمود الذي لا يستطيع الجلوس من مرضه حتى يعمد بالوسائد. ومنه اشتق القلب العميد وهو المعمود المشغوف الذي قد هده العشق وكسره فصار كشيء عمد بشيء. قال امرؤ القيس 5 : أأذكرت نفسك ما لن يعودا ... فهاج التذكر قلبا عميدا يقال: قلب عميد معمود معمد. قال جميل 6 : فقلت لها يا بثن أوصيت كافيا ... وكل امرىء لم يرعه الله معمود والعمد: ارتكابك أمرا بجد ويقين. تقول: فعلته عمدا على [عين] وعمد عين، وتعمدت له وأتيت ذلك الأمر متعمدا ومعتمدا بمعناه. قال 7 : فزادك الله غما إذا كلفت بها ... وإذا أتيت الذي أبلاك معتمدا وعمد السنام يعمد عمدا فهو عمد إذا كان ضخما واريا فحمل عليه ثقل فكسره ومات فيه شحمه فلا يستوي فيه أبدا كما يعمد الجرح إذا عسر قبل أن ينضج بيضته فيرم. وبعير عمد، وسنام عمد، وناقة عمدة. وثرى عمد، أي: بلته الأمطار، وأنشد أبو ليلى 8 : وهل أحطبن القوم بعد نزولهم ... أصول ألاء في ثرى عمد جعد وبعير معمود، وهو داء يأخذه في السنام. وقوله خلق السماوات بغير عمد ترونها 9 . يقال: إن الله عجب الخلق من خلق السماوات في الهواء من غير أساس وأعمدة، وبناؤهم لا يثبت إلا بهما، فقال: خلقتهما من غير حاجة إلى الأعمدة ليعتبر الخلق ويعرفوا قدرته. وقال آخر: بغير عمد ترونها، أي: لها عمد لا ترونها. ويقال: عمدها جبل قاف، وهي مثل القبة أطرافها على ذلك الجبل والجبل محيط بالدنيا من زبرجدة خضراء وخضرة السماء منه، فإذا كان يوم القيامة صيره الله نارا تحشر الناس من كل أوب إلى بيت المقدس. وأما قول ابن ميادة 10 : وأعمد من قوم كفاهم أخوهم فإنه يقول: هل زدنا على أن كفينا إخواننا. قال عرام: يقول: إني أجد من ذلك ألما ووجعا، أي: لا أعمد من ذاك. ويعني بقول أبي جهل حين صرع: أعمد من سيد قتله قومه، أي: هل زاد على سيد قتله قومه، والعرب تقول: أعمد من كيل محق، أي: هل زاد على هذا؟'),
(337, 'دعم', 'دعم', 'دعم', 'الدعم 11 : أن يميل الشيء فتدعمه بدعام، كما تدعم عروش الكرم ونحوه فتدعمه بشيء يصير له مساكا. وجمعه: دعائم. قال: لما رأيت أنه لا قامه ... وأنه النزع على السآمة جذبت جذبا زعزع الدعامة وقال: لأدعمن العيس دعما أيما ... دعم يثني العاشق المتيما وقال: لا دعم بي لكن بليلى دعم ... جارية في وركيها شحم 12 قوله: لا دعم بي، أي: لا سمن بي يدعمني، أي: يقويني. والدعامتان: خشبتا البكرة، بمنزلة القائمتين من الطين. والدعامة: 13 اسم الخشبة التي يدعم بها. والمدعوم الذي يميل فتدعمه ليستمسك. والمدعوم الذي يحمل عليه الثقل من فوق كالسقف يعمد بالأساطين المنصوبة. دعمي: اسم أبي حي من ربيعة، ومن ثقيف. ويقال للشيء الشديد الدعام: إنه لدعمي. قال رؤبة 14 : حاول منه العرض طولا سلهبا ... أكتد دعمي الحوامي جسزبا ودعمي كل شيء أشده وأكثره. والدعم: تقوية الشيء الواهن، نحو: الحائط المائل فتدعمه بدعامة من خلفه، وبه يشبه الرجل السيد يقال: دعامة العشيرة، أي: به يتقوون. ودعائم الأمور: ما كان قوامها.'),
(338, 'معد', 'معد', 'معد', 'المعدة: [ما] 15 يستوعب الطعام من الإنسان، والمعدة لغة. قال: 16 معدا وقل لجارتيك تمعدا ... إني أرى المعد عليها أجودا قال هذا ساق يسقي إبله فاستعان بجاريته إذ لا أعوان له يقول: امعد وناد جاريتك. والمعد: أن تأخذ الشيء من الرجل ويأخذه منك. والمعد: نزع الماء من البئر. ومعد الرجل فهو [ممعود 17 ] ، أي: دويت معدته فلم يستمرىء ما يأكل واشتكاها. ويجوز جمعه على المعد. معد: اسم أبي نزار. والتمعدد: الصبر على عيشهم في سفر وحضر. تمعدد فلان. وكذلك إذا عاد إليهم بعد التحول عنهم إلى غيرهم. والمعد مشددة الدال: اللحم الذي تحت الكتف، أو أسفل منه قليلا، من أطيب لحم الجنب 18 . ويقال: المعدان من الفرس ما بين كتفيه إلى مؤخر متنيه. قال ابن أحمر 19 : وإما زال سرج عن معد ... وأجدر بالحوادث أن تكونا وقال 20 : وكأنما تحت المعد ضئيلة ... ينفي رقادك لدغها وسمامها ومثل تضربه العرب: قد يأكل المعدي أكل السوء، وهو في الإشتقاق يخرج على مفعل، وعلى تقدير فعل على مثال علد ونحوه، ولم يشتق منه فعل. معدان: اسم رجل، ولو اشتق منه من سعة المعدة فقيل: معدان واسع المعدة لكان صوابا. والمعيدي: رجل من كنانة صغير الجثة عظيم الهيبة قال له النعمان: أن تسمع بالمعيدي خير من أن تراه فذهب مثلا. والمعد: الجذب. معدته معدا. ويقال: امعد دلوك، أي: انزعها وأخرجها من البئر. قال الراجز 21 : يا سعد يا ابن عمل يا سعد ... هل يروين ذودك نزع معد والمعد: الغض من الثمار. والتمعدد: التردد في اللصوصية.'),
(339, 'دمع', 'دمع', 'دمع', 'دمعت العين تدمع دمعا ودمعا ودموعا. من قال: دمعت قال: دمعا، ومن قال: دمعت قال: دمعا. وعين دامعة، والدمع: ماؤها. والدمعة القطرة. والمدمع: مجتمع الدمع في نواحيها. يقال: فاضت مدامعي ومدامع عيني. والماقيان من المدامع، وكذلك المؤخران. وامرأة دمعة: سريعة الدمعة والبكاء، وإذا قلت: ما أكثر دمعتها خففت، لأن ذلك تأنيث الدمع. قال 22 : قد بليت مهجتي وقد قرح المد ... مع ... ويقال للماء الصافي: كأنه دمعة. والدماع من الثرى ما تراه يتحلب عنه الندى، أو يكاد. قال 23 : من كل دماع الثرى مطلل ... يثرن صيفي الظباء الغفل ودماع الكرم ما يسيل منه أيام الربيع. والدماع: ما تحرك من رأس الصبي إذا ولد ما لم 24 يشتد، وهي اللماعة والغاذية أيضا. وشجة دامعة: تسيل دما.'),
(340, 'ذعت', 'ذعت', 'ذعت', 'ذعت فلانا أذعته ذعتا إذا أخذت برأسه ووجهه فمعكته في التراب معكا كأنك تغطه في الماء، ولا يكون الذعت إلا كذلك. ويقال: الذعت: الخنق. ذعته: خنقته، حتى قتلته.'),
(341, 'عتر', 'عتر', 'عتر', 'عتر الرمح يعتر عترا وعترانا، أي: اضطرب وتراءد في اهتزاز. قال 1 : من كل خطي إذا هز عتر والعتيرة: شاة تذبح ويصب دمها [على رأ] 2 س الصنم. والعاتر: الذي يعتر شاة، يفعلونه في الجاهلية، وهي المعتورة. قال 3 : فخر صريعا مثل عاترة النسك أراد الشاة المعتورة. وربما أدخلوا الفاعل على المفعول إذا جعلوه صاحب واحد ذلك الوصف. كقولهم: أمر عارف، أي: معروف، ولكن أرادوا أمرا ذا معرفة، كما تقول: رجل كاس، أي: ذو كسوة، ونحوه وقوله: في عيشة راضية 4 *، أي: مرضية. وجمعه عتائر وعتيرات. قال 5 : عتائر مظلوم الهدي المذبح وأما العتر فاختلف فيه. قالوا: العتر مثل الذبح، ويقال: هو الصنم الذي كان تعتر له العتائر في رجب. قال زهير 6 : كناصب العتر دمى رأسه النسك يصف صقرا وقطاة، ويروى: كمنصب العتر، يقول: كمنصب ذلك الصنم أو الحجر الذي يدمى بدم العتيرة. ومن روى: كناصب العتر يقول: إن العاتر إذا عتر عتيرته دمى نفسه ونصبه إلى جنب الصنم فوق شرف من الأرض ليعلم أنه ذبح لذلك. وعترة الرجل: أصله. وعترة الرجل أقرباؤه من ولده وولد ولده وبني عمه دنيا. وعترة الثغر إذا رقت غروب الأسنان ونقيت وجرى عليها الماء فتلك العترة. ويقال: إن ثغرها لذو أشرة وعترة. وعترة المسحاة: خشبتها التي تسمى يد المسحاة. عتوارة: اسم رجل من بني كنانة. والعترة أيضا: بقلة إذا طالت قطع أصلها، فيخرج منه لبن. قال 7 : فما كنت أخشى أن أقيم خلافهم ... لستة أبيات كما ينبت العتر لأنه إذا قطع أصله نبتتت من حواليه شعب ست أو ثلاث، ولأن أصل العتر أقل من فرعه، وقال: لا تكون العترة أبدا كثيرة إنما هن شجرات بمكان، وشجرات بمكان لا تملأ الوادي، ولها جراء شبه جراء العلقة. والعلقة شجرة يدبغ بها الأهب. والعترة [نبتة 8 ] طيبة يأكلها الناس ويأكلون جراءها.'),
(342, 'ترع', 'ترع', 'ترع', 'الترع: امتلاء الإناء. ترع يترع ترعا، وأترعته. قال جرير 9 : فهنا كم ببابه رادحات ... من ذرى الكوم مترعات ركود وقال 10 : فافترش الأرض بسيل أترعا أي: ملأ الأرض ملء شديدا. وقال بعضهم: لا أقول ترع الإناء في موضع الإمتلاء، ولكن أترع. ويقولون: ترع الرجل، أي: اقتحم الأمور مرحا ونشاطا، يترع ترعا. قال 11 : الباغي الحرب يسعى نحوها ترعا ... حتى إذا ذاق منها جاحما بردا ترعا، أي: ممتلئا نشيطا، جاحما، أي: لهبا ووقودا. وإنه لمتترع إلى كذا، أي: متسرع. وقول رسول الله ص: إن منبري على ترعة من ترع الجنة 12 . يقال: هي الدرجة، ويقال: هي الباب، كأنه قال: إن منبري على باب من أبواب الجنة. والترعة، والجماعة الترع: أفواه الجداول تفجر من الأنهار فيها وتسكر إذا ساقوا الماء.'),
(343, 'رتع', 'رتع', 'رتع', 'الرتع: الأكل والشرب في الربيع رغدا. رتعت الإبل رتعا، وأرتعتها: ألقيتها في الخصب. قال العجاج 13 : يرتاد من أربا لهن الرتعا فأما إذا قلت: ارتعت الإبل ترتعي فإنما هو تفتعل من الرعي نالت خصبا أو لم تنل، والرتع لا يكون إلا في الخصب، وقال الفرزدق 14 : ارعي فزارة، لا هناك المرتع وقال الحجاج للغضبان: سمنت قال: أسمنني القيد والرتعة، كما يقال: العز والمنعة والنجاة والأمنة. وقال 15 : أبا جعفر لما توليت أرتعوا ... وقالوا لدنياهم أفيقي فدرت وقوم مرتعون وراتعون. ورتع فلان في المال إذا تقلب فيه أكلا وشربا. وإبل رتاع.'),
(344, 'عتل', 'عتل', 'عتل', 'العتلة: حديدة كحد فأس عريضة ليست بمتعقفة الرأس كالفأس، ولكنها مستقيمة مع الخشبة، في أصلها خشبة يحفر بها الأرض والحيطان. ورجل عتل أي: أكول منوع. والعتل: أن تأخذ بتلبيب رجل فتعتله، أي: تجره إليك، وتذهب به إلى حبس أو عذاب. وتقول: لا أنعتل 1 معك، أي: لا أنقاد معك. وأخذ فلان بزمام الناقة فعتلها، وذلك إذا قبض على أصل الزمام عند الرأس فقادها قودا عنيفا. وقال بعضهم: العتلة عصا من حديد ضخمة طويلة لها رأس مفلطح مثل قبيعة السيف مع البناة يهدمون بها الحيطان. والعتلة: الهراوة الغليظة من الخشب، والجميع عتل. قال الراجز 16 : وأينما كنت من البلاد ... فاجتنبن عرم الذواد وضربهم بالعتل الشداد يعني عرامهم وشرتهم.'),
(345, 'تلع', 'تلع', 'تلع', 'التلع: ارتفاع الضحى. وتلع النهار ارتفع. قال 17 : وكأنهم في الآل إذ تلع الضحى وتلع فلان إذا أخرج رأسه من كل شيء كأن فيه وهو شبه طلع، غير أن طلع أعم. وتلع الشاة يعني الثور، أي: أخرج رأسه من الكناس. وأتلع رأسه، فنظر إتلاعا، لأن فعله يجاوز، كما تقول: أطلع رأسه إطلاعا. قال ذو الرمة 18 : كما أتلعت من تحت أرطى صريمة ... ألى نبأة الصوت الظباء الكوانس والأتلع من كل شيء: الطويل العنق. والأنثى: تلعاء. والتلع والترع هو الأتلع، لأن الفعل يدخل على الأفعل. قال 19 : وعلقوا في تلع الرأس خدب يعني بعيرا طويل العنق. وسيد تلع، ورجل تلع، أي كثير التلفت حوله. ولزم فلان مكانه فما يتتلع، أي ما يرفع رأسه للنهوض ولا يريد البراح. قال أبو ذؤيب 20 : فوردن والعيوق مقعد رابىء ... الضرباء فوق النظم لا يتتلع ويقال: إنه ليتتالع في مشيه إذا مد عنقه ورفع رأسه. ومتالع: اسم جبل بالحمى. ومتالع اسم موضع بالبادية. قال لبيد 21 : درس المنا بمتالع فأبان ... فتقادمت بالحبس فالسوبان والتلعة: أرض مرتفعة غليظة، وربما كانت مع غلظها عريضة يتردد فيها السيل ثم يدفع منها إلى تلعة أسفل منها. قال النابغة 22 : فالتلاع الدوافع ويقال: التلعة مقدار قفيز من الأرض، والذي يكون طويلا ولا يكون عريضا. والقرارة أصغر من 23 التلعة، والدمعة أصغر من ذلك. ورجل تليع، وجيد تليع، أي: طويل. قال: جيد تليع تزينه الأطواق'),
(346, 'عنت', 'عنت', 'عنت', 'العنت: إدخال المشقة على إنسان. عنت فلان، أي: لقي مشقة. وتعنته تعنتا، أي: سألته عن شيء أردت به اللبس عليه والمشقة. والعظم المجبور يصيبه شيء فيعنته إعناتا، قال 1 : فأرغم الله الأنوف الرغما ... مجدوعها والعنت المخشما المخشم: الذي قد كسرت خياشيمه مرة بعد مرة. والعنت: الإثم أيضا. والعنتوت: ما طال من الآكام كلها.'),
(347, 'نعت', 'نعت', 'نعت', 'النعت: وصفك الشيء بما فيه. ويقال: النعت وصف الشيء بما فيه إلى الحسن مذهبه، إلا أن يتكلف متكلف، فيقول: هذا نعت سوء. فأما العرب العاربة فإنما تقول لشيء إذا كان على استكمال النعت: هو نعت كما ترى، يريد التتمة. قال: أما القطاة فإني سوف أنعتها ... نعتا يوافق نعتي بعض ما فيها سكاء مخطومة في ريشها طرق ... حمر قوادمها سود خوافيها 2 البيتان لامرىء القيس 3 . ويقال: صلماء 4 أصح من سكاء، لأن السكك قصر في الأذن. فلو قال: صلماء لأصاب. و [النعت] 5 : كل شيء كان بالغا. تقول: هو نعت، أي: جيد بالغ. والنعت: الفرس 6 الذي هو غاية في العتق والروع إنه لنعت ونعيت. وفرس نعتة، بينة النعاتة وما كان نعتا، ولقد نعت، أي: تكلف فعله. يقال: نعت نعاتة. واستنعته، أي استوصفته. والنعوت: جماعة النعت، كقولك: نعت كذا ونعت كذا. وأهل النحو يقولون: النعت خلف من الاسم يقوم مقامه. نعته أنعته نعتا، فهو منعوت.'),
(348, 'نتع', 'نتع', 'نتع', 'نتع العرق نتوعا، وهو مثل نبع، إلا أن نتع في العرق أحسن.'),
(349, 'عفت', 'عفت', 'عفت', 'العفت في الكلام كاللكنة. عفت الكلام يعفته عفتا. وهو أن يكسره، وهي عربية كعربية الأعجمي أو الحبشي أو السندي ونحوه إذا تكلف العربية. وقال ابن القرية: لا يعرف العربية هؤلاء الجراجمة الطمطمانيون الذين يلفتونها لفتا ويعفتونها عفتا.'),
(350, 'عتب', 'عتب', 'عتب', 'العتبة: أسكفة الباب. وجعلها ابراهيم ع كناية عن امرأة إسماعيل إذ أمره بإبدال عتبته. وعتبات الدرجة وما يشبهها من عتبات الجبال وأشراف الأرض وكل مرقاة من الدرج عتبة، والجميع العتب. وتقول: عتب لنا عتبة، أي: اتخذ عتبات: أي: مرقيات. والعتب ما دخل في أمر يفسده ويغيره عن الخلوص. قال خلف بن خليفة 1 : فما في حسن طاعتنا ... ولا في سمعنا عتب وحمل فلان على عتبة كريهة، وعلى 2 عتب كريه من البلاء والشر. والعتب: التواء عند الضريبة. قال امرؤ القيس 3 : مجرب الوقع غير ذي عتب يصف السيف، وقال المتلمس 4 : يعلى على العتب الكريه ويوبس أي: يكره ويرد عليه. والفحل المعقول، أو الظالع إذا مشى على ثلاث قوائم كأنه يقفز يقال: يعتب عتبانا، وكذلك الأقطع إذا مشى على خشبة، وهذا تشبيه كأنه ينزو من عتبة إلى عتبة. والعتب: الموجدة. عتبت على فلان عتبا ومعتبة، أي: وجدت [عليه] . قال 5 : عتبت على جمل ولست بشامت ... بجمل وإن كانت بها النعل زلت وأعتبني، أي ترك ما كنت أجد [عليه] 6 ورجع إلى [مرضاتي] 7 والاسم: العتبى. تقول: لك العتبى. والتعاتب إذا وصفا موجدتها، وكذلك المعاتبة إذا لامك واستزادك، قال 8 : إذا ذهب العتاب فليس حب ... ويبقى الحب ما بقي العتاب وأعطاني فلان العتبى، أي أعتبني. قال 9 : لك العتبى وحبايا خليلي واستعتب، أي: طلب أن يعتب. وما وجدت في قوله وفعله عتبانا، إذا ذكر أنه قد أعتبك، ولم ير لذلك بيان. قال أبو الأسود في الإستعتاب 10 : فعاتبته ثم راجعته ... عتابا رفيقا وقولا أصيلا فألفيته غير مستعتب ... ولا ذاكر الله إلا قليلا نصب ذكر الله على توهم التنوين، أي: ذاكر الله. وعتيبة وعتابة من أسماء النساء، وعتبة وعتاب ومعتب من أسماء الرجال 11 وعتيب اسم قبيلة.'),
(351, 'تعب', 'تعب', 'تعب', 'التعب: شدة العناء. والإعجال في السير والسوق والعمل. تعب يتعب تعبا. فهو تعب. وأتعبته إتعابا [فهو] 12 متعب، ولا يقال: متعوب. وإذا أعتب العظم المجبور، وهو أول برئه قيل أتعب ما أعتب. قال ذو الرمة 13 : إذا ما رآها رأية هيض قلبه ... بها كانهياض في المتعب المتتمم يعني أنه تتمم جبره بعد الكسر.'),
(352, 'تبع', 'تبع', 'تبع', 'التابع: التالي 14 ، ومنه التتبع والمتابعة، والإتباع، يتبعه: يتلوه. تبعه يتبعه تبعا. والتتبع: فعلك شيئا بعد شيء. تقول: تتبعت علمه، أي: اتبعت آثاره. والتابعة: جنية تكون مع الإنسان تتبعه حيثما ذهب. وفلان يتابع الإماء، أي: يزانيهن. والمتابعة أن تتبعه هواك وقلبك. تقول: هؤلاء تبع وأتباع، أي: متبعوك ومتابعوك على هواك. والقوائم يقال لها تبع. قال أبو دؤاد 15 : وقوائم تبع لها ... من خلفها زمع معلق يصف الظبية. وقال 16 : يسحب الليل نجوما طلعا ... وتواليها بطيئات التبع والتبيع: العجل المدرك من ولد البقر الذكر، لأنه يتبع أمه بعدو. والعدد: أتبعة، والجميع: أتابيع. وبقر متبع، أي: خلفها تبيع. وتبعت شيئا، واتبعت سواء. وأتبع فلان فلانا إذا تبعه يريد شرا. قال الله عز ذكره: فأتبعه الشيطان فكان من الغاوين 17 والتتابع ما بين الأشياء إذا فعل هذا على إثر هذا لا مهلة بينهما كتتابع الأمطار والأمور واحدا خلف آخر، كما تقول: تابع بين الصلاة والقراءة، وكما تقول: رميته بسهمين تباعا وولاء ونحوه. قال 18 : متابعة تذب عن الجواري ... تتابع بينها عاما فعاما والتبيع: النصير 19 . والتبعة هي التباعة، وهو اسم الشيء الذي لك فيه بغية شبه ظلامة ونحوها. والتبع والتبع: الظل، لأنه متبع حيثما زال. قال الفرزدق 20 : نرد المياه قديمة وحديثة ... ورد القطاة إذا اسمأل التبع والتبع ضرب من اليعاسيب، أحسنها وأعظمها، وجمعها: تبابيع. تبع: اسم ملك من ملوك اليمن، وكان مؤمنا، ويقال: تبت اشتق لهم هذا الاسم من تبع ولكن فيه عجمة، ويقال: هم من اليمن وهم من وضائع تبع بتلك البلاد. والتبيع الذي له عليك مال يتابعك به، أي: يطالبك. وأتبعت فلانا على فلان، أي: أحلته عليه، ونحو ذلك.'),
(353, 'بتع', 'بتع', 'بتع', 'البتع والبتع معا: نبيذ يتخذ من العسل كأنه الخمر صلابة. وأما البتع فالشديد المفاصل والمواصل من الجسد. قال سلامة بن جندل 21 : يرقى الدسيع إلى هاد له بتع ... في جؤجؤ كمداك الطيب مخضوب أي: شديد موصول. وقال رؤبة: 22 وقصبا فعما وعنقا أبتعا أي: صلبا، ويروى: أرسعا.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(354, 'عتم', 'عتم', 'عتم', 'عتم الرجل تعتميا إذا كف عن الشيء بعد ما مضى فيه. قال حميد 23 : عصاه منقار شديد يلطم ... مجامع الهام ولا يعتم يصف الفيل. عصا الفيل منقاره، لأنه يضرب به كل شيء. وقوله: لا يعتم، أي: لا يكف ولا يهمل. وحملت على فلان فما عتمت، أي: ضربته فما تنهنهت وما نكلت ولا أبطأت. وعتمت فأنا عاتم، أي: كففت. قال 24 : ولست بوقاف إذا الخيل أحجمت ... ولست عن القرن الكمي بعاتم والعاتم: البطيء. قال 25 ظعائن أما نيلهن فعاتم وفي الحديث 26 : أن رسول الله صلى الله عليه وآله ناول سلمان كذا وكذا ودية فغرسها فما عتمت منها ودية، أي، ما أبطأت حتى علقت. والعتمة: الثلث الأول من الليل بعد غيبوبة الشفق. أعتم القوم إذا صاروا في ذلك الوقت، وعتموا تعتيما ساروا في ذلك الوقت، وأوردوا أو أصدروا في تلك الساعة. قال 27 يبني العلى ويبتني المكارما ... أقراه 28 للضيف يثوب عاتما والعتم: الزيتون يشبه البري لا يحمل شيئا.'),
(355, 'عمت', 'عمت', 'عمت', 'العمت: أن تعمت الصوف فتلف بعضه على بعض مستطيلا أو مستديرا، كما يفعله الذي يغزل الصوف فيلقيه في يده أو نحو ذلك، والاسم: العميت، وثلاثة أعمتة، وجمعه: عمت. قال 29 : يظل في الشاء يرعاها ويحلبها ... ويعمت الدهر إلا ريث يهتبد ورجل عمات وامرأة عماتة إذا كانت جيدة العمت. وعمت الصوف تعميتا. وعمت الصوف أن تعمته عمائت. والعميتة: [ما] 30 ينفش [من] 31 الصوف، ثم يمد، ثم يجعل حبالا، يلقى بعضه على بعض، ثم يغزل 32 . قال: حتى تطير ساطعا سختيتا ... وقطعا من وبر عميتا وقيل: العمت: أن تضرب ولا تبالي من أصاب ضربك.'),
(356, 'متع', 'متع', 'متع', 'متع النهار متوعا. وذلك قبل الزوال. ومتع الضحى. إذا بلغ غايته عند 33 الضحى الأكبر. قال 34 : وأدركنا بها حكم بن عمرو ... وقد متع النهار بنا فزالا والمتاع: ما يستمتع به الإنسان في حوائجه من أمتعة البيت ونحوه من كل شيء. والدنيا متاع الغرور، وكل شيء تمتعت به فهو متاع، تقول: إنما العيش متاع أيام ثم يزول [أي بقاء أيام] 35 ومتعك الله به وأمتعك واحد، أي: أبقاك لتستمتع به فيما تحب من السرور والمنافع. وكل من متعته شيئا فهو له متاع ينتفع به. ومتعة المرأة المطلقة إذا طلقها زوجها. متعها متعة يعطيها شيئا، وليس ذلك بواجب، ولكنه سنة. قال الأعشى 36 يصف صيادا: حتى إذا ذر قرن الشمس صبحها ... من آل نبهان يبغي أهله متعا أي: يبغيهم صيدا يتمتعون به، ومنهم من يكسر في هذا خاصة، فيقول: المتعة. والمتعة في الحج: أن تضم عمرة إلى الحج فذلك التمتع. ويلزم لذلك 37 دم لا يجزيه غيره.'),
(357, 'رعظ', 'رعظ', 'رعظ', 'الرعظ من السهم: الموضع الذي يدخل فيه سنخ النصل. وفوقه الذي عليه لفائف العقب. ورعظ السهم فهو مرعوظ إذا انكسر رعظه. قال 1 : ناضلني وسهمه مرعوظ ويقال: أرعظ فهو مرعظ. يعني: مرعوظ. ويقال: إن فلانا ليكسر عليك أرعاظ النبل غضبا. أبو خيرة: المرعوظ الموصوف بالضعف.'),
(358, 'عظل', 'عظل', 'عظل', 'عظل يعظل الجراد والكلاب وكل ما [يلازم] 2 في السفاد. والاسم العظال. قال 3 : يا أم عمرو أبشري بالبشرى ... موت ذريع وجراد عظلى أي: يسفد 4 بعضها بعضا. وعاظلها فعظلها، أي: غلبها. قال جرير 5 : كلاب تعاظل سود الفقاح'),
(359, 'عنظ', 'عنظ', 'عنظ', 'العنظوان نبات إذا استكثر منه البعير وجع بطنه. عظي البعير عظى فهو عظ 1 . النون زائدة، وأصل الكلام: العين والظاء والواو، ولكن الواو إذا بنيت منه فعل 2 قلت: عظي مثل رضي، فالياء هو الواو وكسرته الضاد المكسورة، والدليل عليه الرضوان. قال 3 : حرقها وارس عنظوان ... فاليوم منها يوم أرونان وارس ثمره. والمورس [الذي] 4 خرج وارسه. وقال 5 : ماذا تقول نبتها تلمس ... وقد دعاها العنظوان المخلس والعنظوانة: الجرادة الأنثى، والجمع 6 العنظوانات.'),
(360, 'ظعن', 'ظعن', 'ظعن', 'ظعن يظعن ظعنا وظعونا وظعنا وهو الشخوص. والظعينة: المرأة، سميت به لأنها تظعن إذا ظعن زوجها، وتقيم إذا أقام. ويقال: لا بل الظعينة الجمل الذي يعتمل ويركب، وسميت ظعينة لأنها راكبته، كما سميت المزادة راوية وإنما الرواية البعير. قال 7 : تبين خليلي هل ترى من ظعائن ... لمية أمثال النخيل المخارف والنساء لا يشبهن بالنخيل، وإنما تشبه بها الإبل التي عليها الأحمال فهذا يبين لك أن الظعينة قد تكون البعير الذي يعتمل. والظعن: رجال ونساء جماعة.'),
(361, 'نعظ', 'نعظ', 'نعظ', 'نعظ ذكر الرجل ينعظ نعظا ونعوظا. وأنعظه [ينعظه] 8 . وهو أن ينتشر ما عند الرجل، ومن المرأة الاهتياج إذا علاها الشبق. يقال: أنعظت المرأة.'),
(362, 'فظع', 'فظع', 'فظع', 'فظع الأمر يفظع فظاعة. وأفظع إفظاعا. وأمر فظيع، أي: عظيم. وأفظعني هذا الأمر وفظعت به: واستفظعته رأيته فظيعا. وأفظعته أيضا.'),
(363, 'عظب', 'عظب', 'عظب', 'عظب الطائر يعظب عظبا وهو سرعة تحريك الزمكى.'),
(364, 'عظم', 'عظم', 'عظم', 'العظام: جمع العظم، وهو قصب المفاصل. والعظم: مصدر الشيء العظيم. عظم الشيء عظما فهو عظيم. والعظامة: مصدر الأمر العظيم. عظم الأمر عظامة. وعظمه يعظمه تعظيما، أي: كبره. وسمعت خبرا فأعظمته، أي: عظم في عيني. ورأيت شيئا فاستعظمته. واستعظمت الشيء: أخذت أعظمه. واستعظمته: أنكرته. وعظم الشيء: أعظمه وأكبره ومعظم 1 الشيء أكثره. مثل معظم الماء وهو تبلده. والعظم: جل الشيء وأكثره. والعظمة من [التعظم] 2 والزهو والنخوة. وعظم الرجل عظامة فهو عظيم في الرأي والمجد. والعظيمة: الملمة النازلة الفظيعة. قال 3 : فإن تنج منها تنج من ذي عظيمة'),
(365, 'عذر', 'عذر', 'عذر', 'عذرته عذرا ومعذرة. والعذر اسم، عذرته بما صنع عذرا ومعذرة وعذرته من فلان، أي: لمت فلانا ولم ألمه. قال 1 : يا قوم من يعذر من عجرد ... القاتل النفس على الدانق وعذير الرجل ما يروم ويحاول مما يعذر عليه إذا فعله. قال العجاج 2 : جاري لا تستنكري عذيري ثم فسره فقال: سعيي وإشفاقي على بعيري وعذيري من فلان، أي من يعذرني منه. قال 3 : عذيرك من سعيد كل يوم ... يفجعنا بفرقته سعيد أي: أعذر من سعيد. واعتذر فلان اعتذارا وعذرة. قال 4 : ها إن تا عذرة. واعتذر من ذنبه فعذرته. وأعذر فلان، أي: أبلى عذرا فلا يلام. واعتذر إذا بالغ فيه. وعذر الرجل تعذيرا إذا لم يبالغ في الأمر وهو يريك أنه يبالغ فيه. وأهل العربية يقولون: المعذرون الذين لهم عذر بالتخفيف، وبالتثقيل 5 الذين لا عذر لهم فتكلفوا عذرا. وتعذر الأمر إذا لم يستقم. قال 6 :'),
(366, 'عذل', 'عذل', 'عذل', 'عذل يعذل عذلا وعذلا، وهو اللوم، والعذال الرجال، والعذل النساء. قال 1 : يا صاحبي أقلا اللوم والعذلا ... ولا تقولا لشيء فات ما فعلا والعاذل: اسم العرق الذي يخرج منه دم الاستحاضة.'),
(367, 'لذع', 'لذع', 'لذع', 'لذع يلذع لذعا كلذع النار أي: كحرقتها، ولذعته بلساني، والقرحة تلتذع إذا قيحت، ويلذعها القيح. قال 2 : وفي الجمر لذع كجمر الغضى والطائر يلذع الجناح إذا رفرف به ثم حرك جناحيه ومشى مشيا قليلا.'),
(368, 'ذعن', 'ذعن', 'ذعن', 'يقال: أذعن إذعانا، وذعن يذعن أيضا، أي: انقاد وسلس. ناقة مذعان سلسة الرأس منقادة لقائدها. وفي القرآن: مذعنين أي: طائعين. قال 1'),
(369, 'ذعف', 'ذعف', 'ذعف', 'الذعاف سم ساعة. وطعام مذعوف جعل فيه الذعاف. قال رزاح: وكنا نمنع الأقوام طرا ... ونسقيهم ذعافا لا كميتا'),
(370, 'عذب', 'عذب', 'عذب', 'عذب الماء عذوبة فهو عذب طيب، وأعذبته إعذابا، واستعذبته، أي: أسقيته وشربته عذبا. وعذب الحمار يعذب عذبا وعذوبا فهو عاذب عذوب لا يأكل من شدة العطش. ويقال للفرس وغيره: عذوب إذا بات لا يأكل ولا يشرب، لأنه ممتنع من ذلك. ويعذب الرجل فهو عاذب عن الأكل، لا صائم ولا مفطر. قال عبيد 1 : وتبدلوا اليعبوب بعد إلههم ... صنما فقروا يا جديل وأعذبوا وقال حميد 2 : إلى شجر ألمى الظلال كأنه ... رواهب أحرمن الشراب عذوب وتقول: أعذبته إعذابا، وعذبته تعذيبا، كقولك: فطمته عن هذا الأمر، وكل من منعته شيئا فقد أعذبته. قال 3 : يسب قومك سبا غير تعذيب أي: غير تفطيم. والعذوب والعاذب الذي ليس بينه وبين السماء ستر. قال النابغة الجعدي 4 : فبات عذوبا للسماء كأنه ... سهيل إذا ما أفردته الكواكب والمعذب قد يجيء اسما ونعتا للعاشق. وعذبة السوط: طرفه. قال 5 : مثل السراحين في أعناقها العذب يعني أطراف السيور التي قد قلدت بها الكلاب. والعذبة في قضيب البعير أسلته. أي: المستدق من مقدمه، ويجمع على عذب. وعذبة شراك النعل: المرسلة من الشراك. والعذيب: ماء لبني تميم.'),
(371, 'بذع', 'بذع', 'بذع', 'البذع: شبه الفزع. والمبذوع كالمفزوع. قال الأعرابي: بذعوا فأبذعروا. أي: فزعوا فتفرقوا.'),
(372, 'عذم', 'عذم', 'عذم', 'عذم يعذم عذما، والاسم العذيمة وهو الأخذ باللسان، واللوم. قال الراجز 1 : يظل من جاراه في عذائم ... من عنفوان جريه العفاهم أي: في ملامات. وفرس عذوم، وعذم، أي: عضوض. والعذام: شجر من الحمض ينتمىء، وانتماؤه انشداخه إذا مسسته. له ورق كورق القاقل، الواحدة عذامة. مذع 2 : مذع لي فلان مذعة من الخبر إذا أخبرك عن الشيء ببعض خبره ثم قطعه، وأخذ في غيره، ولم يتممه. والمذاع: الكذاب يكذب لا وفاء له. ولا يحفظ أحدا بالغيب.'),
(373, 'عثر', 'عثر', 'عثر', 'عثر الرجل يعثر [ويعثر] عثورا، وعثر الفرس عثارا إذا أصاب قوائمه شيء، فيصرع أو يتتعتع. دابة عثور: كثيرة العثار. وعثر الرجل يعثر عثرا إذا اطلع على شيء لم يطلع عليه غيره. وأعثرت فلانا على فلان أي: أطلعته عليه، وأعثرته على كذا. وقوله عز وجل 1 : فإن عثر 2 أي: اطلع. والعثير: الغبار الساطع. والعثير الأثر الخفي، وما رأيت له أثرا ولا عثيرا. والعثير: ما قلبت من تراب أو مدر أو طين بأطراف أصابع رجليك إذا مشيت لا يرى من القدم غيره. قال 3 :'),
(374, 'علث', 'علث', 'علث', 'العلث: الخلط. يقال: علث يعلث علثا، واعتلث. ويقال للزند إذا لم يور واعتاص: علاثة، ويقال: إنما هو علث والعلاث اسمه. قال 1 : وإني غير معتلث الزناد أي: غير صلد الزند. أي: أنا صافي النسب. واعتلث زندا أخذه من شجر لا يدري أيوري أم لا. واعتلث سهما أتخذه بغير حذاقة. علاثة: اسم رجل، ويقال: بل هو الشيء الذي يجمع من هنا وهناك.'),
(375, 'ثعل', 'ثعل', 'ثعل', 'الثعل: زيادة السن أو دخول سن تحت سن في اختلاف من المنبت. ثعل ثعلا فهو أثعل والأنثى ثعلاء، وربما كان الثعل في أطباء الناقة، والبقرة، وهي زيادة في طبيها فهي ثعلاء. والأثعل: السيد الذي له فضول. والثعلول: الرجل الغضبان. قال 2 : وليس بثعلول إذا سيل واجتدي ... ولا برما يوما إذا الضيف أوهما والأنثى من الثعالب ثعالة، ويقال للذكر أيضا ثعالة. قال رافع 3 : الثعل دويبة صغيرة تكون في السقاء إذا خبث ريحه. ويقال للرجل إذا سب: هذا الثعل والكعل، أي: لئيم ليس بشيء، والكعل: كسرة تمر يابس لا يكاد أحد يكسره ولا يأكله وأصله تشبيه بتلك الدويبة فاعلم. عثل 4 : يقال: رجل عثول، أي: طويل اللحية، ولحية عثولة 5 : [ضخمة 6 ] .'),
(376, 'عثن', 'عثن', 'عثن', 'العثان: الدخان. عثن النار يعثن عثنا، وعثن يعثن تعثينا، أي: دخن تدخينا. وعثن البيت يعثن عثنا إذا عبق به ريح الدخنة، وعثنت البيت والثوب بريح الدخنة والطيب تعثينا، أي: دخنته. وعثنون اللحية طولها وما تحتها من الشعر. والعثنون: شعيرات عند مذبح البعير. وجمعه: عثانين. وعثنون السحاب: [ما تدلى من هيدبها] 1 . و [عثنون] 2 الريح: هيدبها في أوائلها إذا أقبلت تجر الغبار جرا، ويقال: هو أول هبوبها. ويقال: العثن: يبيس الكلأ.'),
(377, 'عنث', 'عنث', 'عنث', 'العنث أصل تأسيس العنثوة وهي يبيس الحلي خاصة إذا اسود وبلي. ويقال: عنثة، وشبه الشاعر شعرات اللمة به فقال 3 : عليه من لمته عناث ويروى عناثي مثل عناصي في جماعة عنثوة.'),
(378, 'عبث', 'عبث', 'عبث', 'عبث يعبث عبثا فهو عابث بما لا يعنيه، وليس من باله، أي: لاعب. وعبثت الأقط أعبثه عبثا فأنا عابث، أي: جففته في الشمس. والاسم: العبيث. والعبيثة والعبيث: الخلط 1 .'),
(379, 'ثعب', 'ثعب', 'ثعب', 'ثعبت الماء أثعبه ثعبا، أي فجرته فانثعب، ومنه اشتق المثعب وهو المرزاب. وانثعب الدم من الأنف. والثعبان: الحية الطويل الضخم، ويقال: أثعبان. قال 2 : على نهج كثعبان العرين والأثعبان الوجه الضخم الفخم في حسن وبياض. قال الراجز 3 : إني رأيت أثعبانا جعدا ... قد خرجت بعدي وقالت نكدا والثعبة: ضرب من الوزغ لا تلقى أبدا إلا فاتحة فاها شبه سام أبرص، غير أنها خضراء الرأس والحلق جاحظة العينين، والجميع: الثعب. والثعب: الذي يجتمع في مسيل المطر من الغثاء. وربما قالوا: هذا ماء ثعب، أي: جار، للواحد، ويجمع على ثعبان.'),
(380, 'بثع', 'بثع', 'بثع', 'البثع: ظهور الدم في الشفتين خاصة. شفة باثعة كاثعة، أي: يتبثع فيها الدم، [و] 4 كادت تنفطر من شدة الحمرة، فإذا كان بالغين 5 فهو في الشفتين وغيرهما من الجسد كله، وهو التبثغ.'),
(381, 'بعث', 'بعث', 'بعث', 'البعث: الإرسال، كبعث الله من في القبور. وبعثت البعير أرسلته وحللت عقاله، أو كان باركا فهجته. قال 6 : أنيخها ما بدا لي ثم أبعثها ... كأنها كاسر في الجو فتخاء وبعثته من نومه فانبعث، أي: نبهته. ويوم البعث: يوم القيامة. وضرب البعث على الجند إذا بعثوا، وكل قوم بعثوا في أمر أو في وجه فهم بعث. وقيل لآدم: ابعث بعث النار فصار البعث بعثا للقوم جماعة. هؤلاء بعث مثل هؤلاء سفر وركب.'),
(382, 'عثم', 'عثم', 'عثم', 'عثمت عظمه أعثمه عثما إذا أسأت جبره وبقي فيه ورم أو عوج، [وعثم عثما 1 ] فهو عثم، وبه عثم كهيئة المشمش. قال 2 : وقد يقطع السيف اليماني وجفنه ... شباريق أعشار عثمن على كسر والعيثام: شجرة بيضاء طويلة جدا، الواحدة عيثامة 3 . والعيثوم الضخم من كل شيء الشديد. ويقال للفيلة الأنثى عيثوم، ويقال للذكر أيضا عيثوم، ويجمع عياثيم. قال 4 : وقد أسير أمام الحي تحملني ... والفضلتين كناز اللحم عيثوم أي: قوية ضخمة شديدة. والعثمثم: الطويل من الإبل في غلظ، ويجمع على عثمثمات، ويوصف به الأسد والبغل لشدة وطئهما.'),
(383, 'ثعم', 'ثعم', 'ثعم', 'الثعم: النزع والجر. ثعمته: نزعته. وتثعمت فلانا أرض بني فلان إذا أعجبته وجرته إليها ونزعته.'),
(384, 'رعل', 'رعل', 'رعل', 'الرعل: شدة الطعن 1 . رعله بالرمح، وأرعل الطعن. قال الأعراب: الرعل الطعن ليس بصحيح إنما هو الإرعال، وهو السرعة في الطعن. وضرب أرعل، وطعن أرعل أي: سريع. قال 2 : يحمي إذا اخترط السيوف نساءنا ... ضرب تطير له السواعد أرعل ورعلة الخيل: القطعة 3 التي تكون في أوائلها غير كثير. والرعال: جماعة. قال 4 : كأن رعال الخيل لما تبددت ... بوادي جراد الهبوة المتصوب والرعيل: القطيع أيضا منها. والرعلة النعامة، سميت بها لأنها لا تكاد ترى إلا سابقة للظليم. والرعلة: أول كل جماعة ليست بكثيرة. وأراعيل في كلام رؤبة: أوائل الرياح، حيث يقول 5 : تزجي أراعيل الجهام الخور وقال 6 : جاءت أراعيل وجئت هدجا ... في مدرع لي من كساء أنهجا والرعلة: القلفة وهي الجلدة من أذن الشاة تشتق فتترك معلقة في مؤخر الأذن.'),
(385, 'عرن', 'عرن', 'عرن', 'عرنت الدابة عرنا فهي عرون، وبها عرن وعرنة وعران، على لفظ العضاض والخراط، وهي داء يأخذ في رجل الدابة فوق الرسغ من آخره مثل سحج في الجلد يذهب الشعر. والعران: خشبة في أنف البعير. قال 1 : وإن يظهر حديثك يؤت عدوا ... برأسك في زناق أو عران والعرن 2 قروح تأخذ في أعناق الإبل وأعجازها. والعرنين: الأنف. قال ذو الرمة 3 : تثني النقاب على عرنين أرنبة ... شماء مارنها بالمسك مرثوم عرينة: اسم حي من اليمن، وعرين: حي من تميم. قال جرير 4 : برئت إلى عرينة من عرين والعرين: مأوى الأسد. قال 5 : أحم سراة أعلى اللون منه ... كلون سراة ثعبان العرين قال: هذا زمام وإنما حممته الشمس ولوحت لونه، والثعبان على هذه الصفة.'),
(386, 'رعن', 'رعن', 'رعن', 'رعن الرجل يرعن رعنا فهو أرعن، أي: أهوج، والمرأة رعناء، إذا عرف الموق والهوج في منطقها. والرعن من الجبال ليس بطويل، ويجمع على رعون ورعان، قال 6 : يعدل عنه رعن كل ضد ... عن جانبي أجرد مجرهد أي عريان مستقيم، وقال 7 : يرمين بالأبصار أن رعن بدا ويقال هو الطويل. وجيش أرعن: كثير. قال 8 : أرعن جرار إذا جر الأثر ورعن الرجل إذا غثي عليه كثير. قال 9 : كأنه من أوار الشمس مرعون أي: مغشي عليه من حر الشمس. رعين: جبل باليمن، وفيه حصن يقال لملكه: ذو رعين ينسب إليه. وكان المسلمون يقولون للنبي صلى الله عليه وآله: أرعنا سمعك، أي: اجعل إلينا سمعك. فاستغنمت اليهود ذلك، فقالوا ينحون نحو المسلمين: يا محمد راعنا، وهو عندهم شتم، ثم قالوا فيما بينهم: إنا نشتم 10 محمدا في وجهه، فأنزل الله: لا تقولوا راعنا وقولوا انظرنا 11 ، فقال سعد لليهود: لو قالها رجل منكم لأضربن عنقه.'),
(387, 'نعر', 'نعر', 'نعر', 'نعر الرجل ينعر نعيرا، وهو صوت في الخيشوم. والنعرة: الخيشوم. نعر الناعر، أي: صاح الصائح. قال 12 : وبج كل عاند نعور بج أي: صب فأكثر، يعني: خروج الدماء من عرق عاند لا يرقأ دمه. نعر عذرقه نعورا وهو خروج الدم. والناعور: ضرب من الدلاء. والنعرة: ذباب الحمير، أزرق يقع في أنوف الخيل والحمير. قال امرؤ القيس 13 : فظل يرنح في غيطل ... كما يستدير الحمار النعر قال 14 : وأحذريات يعييها النعر والنعرة: ما أجنت حمر الوحش في أرحامها قبل أن يتم خلقه. قال رؤبة 15 : والشدنيات يساقطن النعر ... حوص العيون مجهضات ما استطر يصف ركابا ترمي بأجنتها من شدة السير. ورجل نعور: شديد الصوت. ورجل نعر: غضبان. وو امرأة غيرى نعرى، يعني بالنعرى: الغضبى 16 . وأما نغرة بالغين فمحمارة الوجه متغيرة متربدة اللون. ويقال للمرأة الفحاشة: نعارة.'),
(388, 'عرف', 'عرف', 'عرف', 'عرفت الشىء معرفة وعرفانا. وأمر عارف، معروف، عريف. والعرف: المعروف. قال النابغة 17 : أبى الله إلا عدله وقضاءه ... فلا النكر معروف ولا العرف ضائع والعريف: القيم بأمر قوم عرف عليهم، سمي به لأنه عرف بذلك الاسم. ويوم عرفة: موقف الناس بعرفات، وعرفات جبل، والتعريف: وقوفهم بها وتعظيمهم يوم عرفة. والتعريف: أن تصيب شيئا فتعرفه إذا ناديت من يعرف هذا. والاعتراف: الإقرار بالذنب، والذل، والمهانة، والرضى به. والنفس عروف إذا حملت على أمر بسأت به، أي: اطمأنت. قال 18 : فآبوا بالنساء مردفات ... عوارف بعد كن وائتجاح الائتجاح من الوجاح وهو الستر، أي: معترفات بالذل والهون 19 . والعرف: ريح طيب، تقول: ما أطيب عرفه، قال الله عز وجل: عرفها لهم 20 ، أي: طيبها، وقال 21 : ألا رب يوم قد لهوت وليلة ... بواضحة الخدين طيبة العرف ويقال: طار القطا عرفا فعرفا، أي: أولا فأولا، وجماعة بعد جماعة. والعرف: عرف الفرس، ويجمع على أعراف. ومعرفة الفرس: أصل عرفه. والعرف: نبات ليس بحمض ولا عضاة، وهو من الثمام. قال شجاع: لا أعرفه ولكن أعرف العرف وهو قرحة الأكلة، يقال: أصابته عرفة.'),
(389, 'عفر', 'عفر', 'عفر', 'عفرته في التراب أعفره عفرا، وهو متعفر الوجه في التراب. والعفر: التراب. وعفرته تعفيرا، واعتفرته اعتفارا إذا ضربت به الأرض فمغثته فانعفر، قال 22 : تهلك المدراة في أكنافه ... وإذا ما أرسلته ينعفر أي: يسقط على الأرض. يعفر: اسم رجل. والعفرة في اللون: أن يضرب إلى غيره في حمرة، كلون الظبي الأعفر، وكذلك الرمل الأعفر. قال الفرزدق 22 : يقول لي الأنباط إذ أنا ساقط ... به لا بظبي بالصريمة أعفرا واليعفور: الخشف، لكثرة لزوقه بالأرض. ورجل عفر وعفرية. وعفارية وعفريت: بين العفارة، يوصف بالشيطنة. وشيطان عفرية وعفريت وهم العفارية والعفاريت، وهو الظريف الكيس، ويقال للخبيث: عفري، أي: عفر وهم العفريون وأسد عفرنى ولبوءة عفرناة وهي الشديدة قال الأعشى 23 : بذات لوث 24 عفرناة إذا عثرت وعفرية الرأس: الشعر الذي عليه. وعفرية الديك مثله. وأما ليث عفرين فدويبة مأواها التراب السهل في أصول الحيطان. تدور دوارة ثم تندس في جوفها، فإذا هيج رمى بالتراب صعدا. ويسمى الرجل الكامل من أبناء خمسين: ليث عفرين. قال: وابن العشر لعاب بالقلين، وابن العشرين باغي نسين، أي: طالب نساء، وابن الثلاثين أسعى الساعين، وابن الأربعين أبطش الباطشين، وابن الخمسين ليث عفرين. وابن الستين مؤنس الجليسين، وابن السبعين أحكم الحاكمين، وابن الثمانين أسرع الحاسبين، وابن التسعين واحد الأرذلين، وابن المائة لاجا ولاسا، أي: لا رجل ولا امرأة. والعفارة: شجرة من المرخ يتخذ منها الزند، ويجمع: عفارا. ومعافر: العرفط يخرج منه شبه صمغ حلو يضيع بالماء فيشرب. ومعافر: قبيلة من اليمن. ولقيته عن عفر، أي بعد حين. وأنشد 25 : أعكرم أنت الأصل والفرع والذي ... أتاك ابن عم زائرا لك عن عفر قال أبو عبد الله: يقال: إن المعفر المفطوم شيئا بعد شيء يحبس عنه اللبن للوقت الذي كان يرضع شيئا، ثم يعاد بالرضاع، ثم يزاد تأخيرا عن الوقت، فلا تزال أمه به حتى يصبر عن الرضاع، فتفطمه فطاما باتا.'),
(390, 'رعف', 'رعف', 'رعف', 'رعف يرعف رعافا فهو راعف. قال 26 : تضمخن بالجادي حتى كأنما الأنوف إذا استعرضتهن رواعف والراعف: أنف الجبل 27 ، ويجمع رواعف. والراعف: طرف الأرنبة. والراعف: المتقدم. وراعوفة البئر وأرعوفتها، لغتان،: حجر ناتىء [على رأسها 28 ] لا يستطاع قلعه، ويقال: هو حجر على رأس البئر يقوم عليه المستقي.'),
(391, 'رفع', 'رفع', 'رفع', 'رفعته رفعا فارتفع. وبرق رافع، أي: ساطع، قال 29 : أصاح ألم يحزنك ريح مريضة ... وبرق تلالا بالعقيقين رافع والمرفوع من حضر الفرس والبرذون دون الحضر وفوق الموضوع. يقال: ارفع من دابتك، هكذا كلام العرب. ورفع الرجل يرفع رفاعة فهو رفيع [إذا شرف] 30 وامرأة رفيعة. والحمار يرفع في عدوه ترفيعا: [أي: عدا] 31 عدوا بعضه أرفع من بعض. كذلك لو أخذت شيئا فرفعت الأول فالأول قلت: رفعته ترفيعا. والرفع: نقيض الخفض. قال 32 : فاخضع ولا تنكر لربك قدرة ... فالله يخفض من يشاء ويرفع والرفعة نقيض الذلة. والرفاعة والعظامة و [الزنجبة] 33 : شيء تعظم به المرأة عجيزتها.'),
(392, 'فرع', 'فرع', 'فرع', 'فرعت رأس الجبل، وفرعت فلانا: علوته. قال لبيد 34 : لم أبت إلا عليه أو على ... مرقب يفرع أطراف الجبل والفرع: أول نتاج الغنم أو الإبل. وأفرع القوم إذا نتجوا في أول النتاج. ويقال: الفرع: أول نتاج الإبل يسلخ جلده فيلبس فصيلا آخر ثم تعطف عليه [ناقة] 35 سوى أمه فتحلب عليه. قال أوس بن حجر 36 : وشبه الهيدب العبام من الأقوام ... سقبا مجللا فرعا والفرع: أعلى كل شيء، وجمعه: فروع. والفروع: الصعود من الأرض. وواد مفرع: أفرع أهله، أي: كفاهم فلا يحتاجون إلى نجعة. والفرع: المال المعد. ويقال: فرع يفرع فرعا، ورجل أفرع: كثير الشعر. والفارع والفارعة والأفرع والفرعاء يوصف به كثرة الشعر وطوله على الرأس. ورجل مفرع الكتف: أي: عريض. قال مرار 37 : جعدة فرعاء في جمجمة ... ضخمة نمرق عنها كالضفر وأفرع فلان إذا طال طولا. وأفرعت 38 بفلان فما أحمدته، أي: نزلت. وأفرع فلان في فرع قومه، قال النابغة 39 : ورعابيب كأمثال الدمى ... مفرعات في ذرى عز الكرم وقول الشاعر 40 : وفروع سابغ أطرافها ... عللتها ريح مسك ذي فنع يعني بالفروع: الشعور. وافترعت المرأة: افتضضتها. وفرعت أرض كذا: أي جولت فيها، وعلمت علمها وخبرها. وفرعة الطريق وفارعته: حواشيه. وتفرعت بني فلان: أي: تزوجت سيدة نسائهم. قال 41 : وتفرعنا من ابني وائل ... هامة العز وخرطوم الكرم فوارع: موضع. والإفراع: التصويب. والمفرع: الطويل من كل شيء. والفارع: ما ارتفع من الأرض من تل أو علم. أو نحو ذلك. فارع: اسم حصن كان في المدينة. والفرعة: القملة الصغيرة.'),
(393, 'عرب', 'عرب', 'عرب', 'العرب العاربة: الصريح منهم. والأعاريب: جماعة الأعراب. ورجل عربي. وما بها عريب، أي: ما بها عربي. وأعرب الرجل: أفصح القول والكلام، وهو عرباني اللسان، أي: فصيح. وأعرب الفرس إذا خلصت عربيته وفاتته القرافة. والإبل العراب: هي العربية والعرب المستعربة الذين دخلوا فيهم فاستعربوا وتعربوا. والمرأة العروب: الضحاكة الطيبة النفس، وهن العرب. والعروبة: يوم الجمعة. قال 1 : يا حسنه عبد العزيز إذا بدا ... يوم العروبة واستقر المنير كنى عن عبد العزيز قبل أن يظهره، ثم أظهره. والعرب: النشاط والأرن. وعرب الرجل يعرب عربا فهو عرب، وكذلك الفرس عرب، أي: نشيط. وعرب الرجل يعرب عربا فهو عرب، أي: متخم. وعربت معدته وهو أن يدوي جوفه من العلف. والعرب: يبيس البهمى. الواحدة: عربة. والتعريب: أن تعرب الدابة فتكوى على أشاعراها في مواضع، ثم يبزغ بمبزغ ليشتد أشعره. والعرابة والتعريب والإعراب: أسام من قولك: أعربت، وهو ما قبح من الكلام، وكره الإعراب للمحرم. وعربت عن فلان، أي تكلمت عنه بحجة.'),
(394, 'عبر', 'عبر', 'عبر', 'عبر يعبر الرؤيا تعبيرا. وعبرها يعبرها عبرا وعبارة. إذا فسرها. وعبرت النهر عبورا. وعبر النهر شطه. وناقة عبر أسفار. أي: لا تزال يسافر عليها. قال [الطرماح] 2 : قد تبطنت بهلواعة ... عبر أسفار كتوم البغام والمعبر: شط النهر الذي هيىء للعبور. والمعبر: مركب يعبر بك، أي: يقطع بلدا إلى بلد. والمعبرة: سفينة يعبر عليها النهر. وعبرت عنه تعبيرا إذا عي من حجته فتكلمت بها عنه. والشعرى العبور: نجم خلف الجوزاء. وعبرت الدنانير تعبيرا: وزنتها دينارا دينارا. ورجل عابر سبيل، أي مار طريق. والعبرة: الإعتبار لما مضى. والعبير: ضرب من الطيب. وعبرة الدمع: جريه، ونفسه أيضا. عبر فلان يعبر عبرا من الحزن، وهو عبران عبر، وامرأة عبرى عبرة. واستعبر، أي: جرت عبرته. والعبري: ضرب من السدر. ويقال: العبري: الطويل من السدر الذي له سوق. والضال: ما صغر منه. قال العجاج 3 : لاث بها الأشاء والعبري وقال 4 :'),
(395, 'عرم', 'عرم', 'عرم', 'عرم الإنسان يعرم عرامة فهو عارم. وعرم يعرم. قال صقر بن حكيم 1 : إني امرؤ يذب عن محارمي ... بسطة كف ولسان عارم وعرام الجيش: حدهم وشرتهم وكثرتهم. قال سلامة بن جندل 2 : وإنا كالحصى عددا وإنا ... بنو الحرب التي فيها عرام وقال 3 : وليلة هول قد سريت وفتية ... هديت وجمع ذي عرام ملادس والعرم: الجرذ الذكر. والعرمة: بياض بمرمة الشاة، عنقها بيضاء وسائرها أسود. والعرمة الكدس المدوس الذي لم يذر بعد كهيئة الأزج. قال شجاع: لا أقول: نعجة عرماء، ولكن ماعزة عرماء ببطنها بياض. والعرمرم: الجيش الكثير. وجبل عرمرم، أي: ضخم. قال 4 : أدارا بأجماد النعام عهدتها ... بها نعما حوما وعزا عرمرما والعرمرم الشديد العجمة الذي لا يفصح.'),
(396, 'عمر', 'عمر', 'عمر', 'العمر: ضرب من النخل وهو السحوق الطويل. والعمر: ما بدا من اللثة، ومنه اشتق اسم عمرو. والعمر عمر الحياة. وقول العرب: لعمرك، تحلف بعمره، وتقول: عمرك الله أن تفعل كذا. هذا إن تحلفه بالله، أو تسأله طول عمره. عمر الناس وعمرهم الله تعميرا. وتقول: إنك عمري لظريف. وعمر الناس الأرض يعمرونها عمارة، وهي عامرة معمورة ومنها العمران. واستعمر الله الناس ليعمروها. والله أعمر الدنيا عمرانا فجعلها تعمر ثم يخربها. والعمارة: القبيلة العظيمة. والعمور: [حي من عبد القيس] 5 . قال 6 : فلولا كان أسعد عبد قيس 7 ... أعاديها لعادتني العمور والحاج يعتمر عمرة. والعمرة: خرزة حمراء كثيرة الماء طويلة تكون في القرط. والإفلاس يكنى أبا عمرة 8 .'),
(397, 'رعم', 'رعم', 'رعم', 'رعمت الشاة ترعم فهي رعوم، وهو داء يأخذ في أنفها فيسيل منه شيء، فيقال لذلك الشيء: رعام رعوم: اسم امرأة تشبيها بالشاة الرعوم. قال الأخطل 9 : صرمت أمامة حبلنا ورعوم ... وبدا المجمجم منهما، المكتوم'),
(398, 'معر', 'معر', 'معر', 'معر الظفر معرا. إذا أصابه شيء فنصل. قال 11 : بوقاح مجمر غير معر وقال 12 : تتقي الأرض بمرثوم معر وتمعر لونه إذا تغير، وعرته صفرة من غضب. ورجل أمعر، وبه معرة، وهو لون يضرب إلى الحمرة والصفرة، وهو أقبح الألوان. ومعر رأس الرجل إذا ذهب شعره، وأمعر أيضا بالألف. قال 13 : والرأس منك مبين الإمعار ويقال: رجل أمعر، أي: قليل الشعر، مثل أزعر. وأمعرت الأرض إذا لم يكن فيها نبات، وأرض معرة مثل زعرة: قليلة النبات غليظة. ومعرت الأرض وأمعرت لغتان. قال الكميت 14 : أصبحت ذا تلعة خضراء إذ معرت ... تلك التلاع من المعروف والرحب وأمعرنا في هذا البلد، أي: وقعنا في أرض معرة.'),
(399, 'رمع', 'رمع', 'رمع', 'رمع يرمع رمعا ورمعانا وهو التحرك 15 . وتقول: مر بي يرمع رمعا ورمعانا مثل: رسم يرسم رسما 16 ورسمانا. والرماعة: الاست، لترمعها، أي: تحركها. والرماعة التي تتحرك من رأس الصبي المولود [من يافوخه من رقته] 17 . واليرمع: الحصى البيض التي تتلألأ في الشمس، الواحدة بالهاء. قال رؤبة 18 : حتى إذا أحمى النهار اليرمعا'),
(400, 'مرع', 'مرع', 'مرع', 'مرع يمرع مرعا والمرع الاسم، وهو الكلأ. ويقال: أرض مرعة ممرعة. مثل خصبة مخصبة. وأمرع القوم: أصابوا مرعا. قال 19 : فلما هبطناه وأمرع سربنا ... أسال علينا البطن بالعدد الدثر وأمرع المكان والوادي، أي: أكلآ.'),
(401, 'علن', 'علن', 'علن', 'علن الأمر يعلن علونا وعلانية، أي: شاع وظهر. وأعلنته إعلانا. قال 1 : قد كنت وعزت إلى علاء ... في السر والإعلان والنجاء ويقال للرجل: استسر ثم استعلن. لا يقال: أعلن إلا للأمر والكلام، وأما استعلن فقد يجوز في كل ذلك. واعتلن الأمر، أي: اشتهر. ويقولون: استعلن يا رجل، أي: أظهر. والعلان: المعالنة، يعلن كل واحد لصاحبه ما في نفسه. قال 2 : وإعلاني لمن يبغي علاني'),
(402, 'لعن', 'لعن', 'لعن', 'اللعن: التعذيب، والملعن: المعذب، واللعين المشتوم المسبوب 3 . لعنته: سببته. ولعنه الله: باعده. واللعين: ما يتخذ في المزارع كهيئة رجل. واللعنة في القرآن: العذاب. وقولهم: أبيت اللعن، أي: لا تأتي أمرا تلحى عليه وتلعن. واللعنة: الدعاء عليه. واللعنة: الكثير اللعن، واللعنة: الذي يلعنه الناس. والتعن الرجل، أي: أنصف في الدعاء على نفسه وخصمه، فيقول: على الكاذب مني ومنك اللعنة. وتلاعنوا: لعن بعضهم بعضا، واشتقاق ملاعنة الرجل امرأته منه في الحكم. والحاكم يلاعن بينهما ثم يفرق. قال جميل 4 : إذا ما ابن ملعون تحدر رشحه ... عليك فموتي بعد ذلك أوذري والتلاعن كالتشاتم في اللفظ، وكل فعل على [تفاعل] 5 فإن الفعل يكون منها، غير أن التلاعن ربما استعمل في فعل أحدهما، والتلاعن يقع فعل كل واحد منهما بنفسه ويجوز أن يقع كل واحد بصاحبه فهو على معنيين.'),
(403, 'نعل', 'نعل', 'نعل', 'النعل: ما جعلت وقاية من الأرض. نعل ينعل نعلا، وانتعل بكذا: [إذا لبس النعل] 6 . والتنعيل: أن ينعل حافر البرذون بطبق من حديد يقيه الحجارة، [وكذلك خف البعير بالجلد] 7 لئلا يحفى. ويقال: لا يقال إلا أنعلت. ويوصف حمار الوحش فيقال: ناعل، لصلابته. قال 8 : يركب قيناه وقيعا ناعلا يقول: صلب من توقيع الحجارة حتى كأنه منتعل من وقاحته. ورجل ناعل: ذو خف ونعل، وكذلك منعل. وكذلك يقال: أنعلت الفرس. ونعل السيف: الحديدة التي في أسفل جفنه. قال 9 : إلى ملك لا ينصف الساق نعله والنعل من الأرض: شبه أكمة صلب يبرق حصاه، لا ينبت شيئا، ويجمع النعال، ونعلها غلظها. قال 10 : كأنهم حرشف مبثوث ... بالجو إذ تبرق النعال يعني: نعال الحرة.'),
(404, 'علف', 'علف', 'علف', 'علفت الدابة أعلفها علفا، أي: أطعمتها العلف. والمعلف: موضع العلف. والدابة تعتلف، أي: تأكل، وتستعلف، أي: تطلب العلف بالحمحمة. والشاة المعلفة هي التي تسمن. علفتها تعليفا [إذا أكثرت تعهدها بإلقاء العلف لها] 1 . (وعلوفة الدواب كأنه جمع وهو شبيه بالمصدر وبالجمع أخرى) 2 . والعلف: ثمر الطلح، مشددة اللام، الواحدة بالهاء. والعلافي، منسوب، وهو أعظم الرحال آخرة وواسطا 3 . وجمعه: علافيات. قال ذو الرمة 4 : أحم علافي وأبيض صارم ... وأعيس مهري وأروع ماجد وقال 5 : شعب العلافيات بين فروجهم ... والمحصنات عوازب الأطهار قوله بين فروجهم، أي قد ركبوها ونساؤهم عوازب منهن إذا طهرن لا يغشونهن، لأنهم أبدا على الأسفار. وشيخ علفوف: كثير الشعر واللحم، ويقال: هو الكبير السن.'),
(405, 'عفل', 'عفل', 'عفل', 'عفلت المرأة عفلا فهي عفلاء. وعفلت الناقة. والعفل والعفلة الاسم، وهو شيء يخرج في حياء الناقة شبه أدرة.'),
(406, 'فعل', 'فعل', 'فعل', 'فعل يفعل فعلا وفعلا، فالفعل: المصدر، والفعل: الاسم، والفعال اسم للفعل الحسن، مثل الجود والكرم ونحوه. ويقرأ وأوحينا إليهم فعل الخيرات 6 بالنصب. والفعلة: العملة، وهم قوم يستعملون الطين والحفر وما يشبه ذلك من العمل.'),
(407, 'لفع', 'لفع', 'لفع', 'لفع الشيب الرأس يلفع لفعا، أي: شمل المشيب الرأس. قال سويد 7 : كيف يرجون سقاطي بعد ما ... لفع الرأس مشيب وصلع وتلفع الرجل، إذا شمله الشيب، كأنه غطى على سواد رأسه ولحيته. قال رؤبة بن العجاج 8 : إنا إذا أمر العدى تترعا ... وأجمعت بالشر أن تلفعا أي: تلبس بالشر، يقول: يشمل شرهم الناس. وقال 9 : وقد تلفع بالقور العساقيل يعني: تلفع السراب على القارة. وإذا اخضر الرعي واليبيس، وانتفع المال بما يأكل. قيل: قد تلفع المال. ولفعت 10 فهي ملفعة. واللفاع: خمار للمرأة يستر رأسها وصدرها، والمرأة تتلفع به. وتقول: لفعت المزادة فهي ملفعة، أي: ثنيتها فجعلت أطبتها في وسطها، فذلك تلفيعها.'),
(408, 'فلع', 'فلع', 'فلع', 'فلع رأسه بحجر يفلع فلعا فهو مفلوع، أي مشقوق، فانفلع، أي: انشق. قال طفيل 11 : نشق العهاد الحو لم ترع قبلنا ... كما شق بالموسى السنام المفلع وتفلعت البطيخة، وتفلعت العقب ونحوه. ويقال في الشتم: لعن الله فلعتها. ويقال للمرأة: يا فلعاء، ويا فلحاء، أي: يا منشقة.'),
(409, 'علب', 'علب', 'علب', 'علب النبات يعلب علبا فهو علب. وهو الجاسي. واللحم يعلب ويستعلب إذا لم يكن رخصا. واستعلبت البقل، أي: وجدته علبا. والعلبة الشيخ الكبير المهزول. والعلب: الضب الضخم المسن. والعلباء: عصب العنق، وهما علباوان، وهن علابي. ورمح معلب، أي: مجلوز بعصب العلباء. والعلبة من خشب كالقدح يحلب فيها. ويقال: علبت السيف بالعلابي تعليبا، وهو سيف معلب ومعلوب. قال 1 : وسيف الحارث المعلوب أردى ... حصينا في الجبابرة الردينا وبعير أعلب، وقد علب علبا، وهو داء يأخذ في جانبي عنقه ترم منه الرقبة وتنحني، تقول: قد حز علباويه، وعلبابيه وبالواو أجود. والعلاب سمة في طول العنق، ربما كان شبرا، وربما كان أقصر. وعلبت الشيء أعلبه علبا وعلوبا إذا أثرت فيه. قال ابن الرقاع 2 : يتبعن ناجية كأن بدفها ... من غرض نسعتها علوب مواسم'),
(410, 'عبل', 'عبل', 'عبل', 'العبل: الضخم، عبل يعبل عبالة. قال 3 : خبطناهم بكل أزج لام ... كمرضاخ النوى عبل وقاح وحبل أعبل، وصخرة عبلاء، أي: بيضاء. وقد عبل عبلا فهو أعبل. قال أبو كبير الهذلي 4 : أخرجت منها سلقة مهزولة ... عجفاء يبرق نابها كالأعبل أي: كحجر أبيض صلب من حجارة المرو. والعبل: ثمر الأرطى، الواحدة بالهاء.'),
(411, 'لعب', 'لعب', 'لعب', 'لعب يلعب لعبا ولعبا، فهو لاعب لعبة، ومنه التلعب. ورجل تلعابة- مشددة العين- أي: ذو تلعب. ورجل لعبة، أي: كثير اللعب، ولعبة، أي: يلعب به كلعبة الشطرنج ونحوها. قال الراجز 5 : العب بها أو اعطني ألعب بها ... إنك لا تحسن تلعابا بها والملعب حيث يلعب. والملعبة: ثوب لا كم له، يلعب فيها الصبي. واللعاب من يكون حرفته اللعب.. ولعاب الصبي: ما سال من فيه، لعب يلعب لعبا، ولعاب الشمس: السراب. قال 6 : في صحن يهماء يهتف السهام بها ... في قرقر بلعاب الشمس مضروج قال شجاع: المضروج من نعت القرقر، يقول: هذا القرقر قد اكتسى السراب، وأعانه ذائب من شعاع الشمس، فقوى السراب. ولعاب الشمس أيضا: شعاعها. قال 7 : حتى إذا ذاب لعاب الشمس ... واعترف الراعي ليوم نجس وملاعب ظله: طائر بالبادية. وملاعبا ظليهما، والثلاثة: ملاعبات ظلالهن. وتقول: رأيت ثلاثة ملاعبات أظلال لهن، ولا تقل أظلالهن، لأنه يصير معرفة. قال شجاع: ملاعب ظله عندنا: الخطاف.'),
(412, 'بعل', 'بعل', 'بعل', 'البعل: الزوج. يقال: بعل يبعل بعلا وبعولة فهو بعل مستبعل، وامرأة مستبعل، إذا كانت تحظى عند زوجها، والرجل يتعرس لامرأته يطلب الحظوة عندها: والمرأة تتبعل لزوجها إذا كانت مطيعة له. والبعل: أرض مرتفعة لا يصيبها مطر إلا مرة في السنة. قال سلامة بن جندل 8 : إذا ما علونا ظهر بعل عريضة ... تخال علينا قيض بيض مفلق ويقال: البعل من الأرض التي لا يبلغها الماء إن سيق إليها لارتفاعها. ورجل بعل، وقد بعل يبعل بعلا إذا كان يصير عند الحرب كالمبهوت من الفرق والدهش. قال أعشى همدان: فجاهد في فرسانه ورجاله ... وناهض لم يبعل ولم يتهيب وامرأة بعلة: لا تحسن لبس الثياب. والبعل من النخل: ما شرب بعروقه من غير سقي سماء ولا غيرها. قال عبد الله بن رواحة 9 : هنالك لا أبالي سقي نخل ... ولا بعل وإن عظم الإتاء الإتاء: الثمرة. والبعل: الذكر من النخل، والناس يسمونه: الفحل. قال النابغة 10 : من الواردات الماء بالقاع تستقي ... بأذنابها قبل استقاء الحناجر أراد بأذنابها: العروق. والبعل: صنم كان لقوم إلياس. قال الله عز وجل: أتدعون بعلا والتباعل والمباعلة والبعال: ملاعبة الرجل أهله، تقول: باعلها مباعلة، وفي الحديث: أيام شرب وبعال 11 .'),
(413, 'بلع', 'بلع', 'بلع', 'بلع الماء يبلع بلعا، أي شرب. وابتلع الطعام، أي: لم يمضغه. والبلعة من قامة البكرة سمها وثقبها، ويجمع على بلع. والبالوعة والبلوعة: بئر يضيق رأسها لماء المطر. والمبلع: موضع الابتلاع من الحلق. قال 12 : تأملوا خيشومه والمبلعا والبلعة والزردة: الإنسان الأكول. ورجل متبلع إذا كان أكولا. وسعد بلع: نجم يجعلونه معرفة. ورجل بلع، أي: كأنه يبتلع الكلام. قال رؤبة 13 : بلع إذا استنطقتني صموت'),
(414, 'علم', 'علم', 'علم', 'علم يعلم علما، نقيض جهل. ورجل علامة، وعلام، وعليم، فإن أنكروا العليم فإن الله يحكي عن يوسف إني حفيظ عليم 1 ، وأدخلت الهاء في علامة للتوكيد. وما علمت بخبرك، أي: ما شعرت به. وأعلمته بكذا، أي: أشعرته وعلمته تعليما. والله العالم العليم العلام. والأعلم: الذي انشقت شفته العليا. وقوم علم وقد علم علما. قال عنترة 2 : تمكو فريصته كشدق الأعلم والعلم: الجبل الطويل، والجميع: الأعلام. قال 3 : قال ابن صانعة الزروب لقومه ... لا أستطيع رواسي الأعلام ومنه قوله [تعالى] : في البحر كالأعلام 4 *، شبه السفن البحرية بالجبال. والعلم: الراية، إليها مجمع الجند. والعلم: علم الثوب ورقمه. والعلم: ما ينصب في الطريق، ليكون علامة يهتدى بها، شبه الميل والعلامة والمعلم. والعلم: ما جعلته علما للشيء. ويقرأ: وإنه لعلم للساعة 5 ، يعني: خروج عيسى ع، ومن قرأ لعلم يقول: يعلم بخروجه اقتراب الساعة. والعالم: الطمش، أي الأنام، يعني: الخلق كله، والجمع: عالمون. والمعلم: موضع العلامة. والعيلم: البحر، والماء الذي عليه الأرض، قال 6 : في حوض جياش بعيد عيلمه ويقال: العيلم: البئر الكثيرة الماء، قال 7 : يا جمة العيلم لن نراعي ... أورد من كل خليف راعي الخليف: الطريق. والعلام: الباشق. عليم: اسم رجل.'),
(415, 'عمل', 'عمل', 'عمل', 'عمل عملا فهو عامل. واعتمل: عمل لنفسه. قال 8 : إن الكريم وأبيك يعتمل ... إن لم يجد يوما على من يتكل والعمالة: أجر ما عمل لك. والمعاملة: مصدر عاملته معاملة. والعملة: الذين يعملون بأيديهم ضروبا من العمل حفرا وطينا ونحوه. وعامل الرمح: دون الثعلب قليلا مما يلي السنان وهو صدره. قال 9 : أطعن النجلاء يعوي كلمها ... عامل الثعلب فيها مرجحن وتقول: أعطه أجر عملته وعمله. ويقال: كان كذا في عملة فلان علينا، أي: في عمارته. ورجل عميل: قوي على العمل. والعمول: القوي على العمل، الصابر عليه، وجمعه: عمل. وأعملت إليك المطي: أتعبتها. وفلان يعمل رأيه ورمحه وكلامه ونحوه [عمل به] 10 . والبناء يستعمل اللبن إذا بنى. واليعملة من الإبل: اسم مشتق من العمل، ويجمع: يعملات، ولا يقال إلا للأنثى، وقد يجمع باليعامل، قال 11 : واليعملات على الونى ... يقطعن بيدا بعد بيد'),
(416, 'معل', 'معل', 'معل', 'معلت الخصية إذا استخرجتها من أرومتها وصفنها.'),
(417, 'لمع', 'لمع', 'لمع', 'لمع بثوبه يلمع لمعا، للإنذار، أي: للتحذير. وألمعت الناقة بذنبها فهي ملمعة، و [هي] 12 ملمع أيضا: قد لحقت. قال لبيد بن ربيعة 13 : أو ملمع وسقت لأحقب لاحه ... طرد الفحول وزرها وكدامها ويقال: ألمعت إذا حملت، ويقال: ألمعت إذا تحرك ولدها في بطنها. وتلمع ضرعها إذا تلون ألوانا عند الإنزال. قال أبو ليلى: يقال: لمع ضرعها إذا ظهر. واللمع: التلميع في الحجر، أو الثوب ونحوه من ألوان شتى، تقول: إنه لحجر ملمع، الواحدة: لمعة. قال لبيد 14 : مهلا أبيت اللعن لا تأكل معه ... إن استه من برص ملمعه يقول: هو منقط بسواد وبياض. ويقال: لمعة سواد أو بياض أو حمرة. يلمع: اسم البرق الخلب. واليلمع: السراب. واليلمع: الملاذ الكذاب، ويقال: ألمعي، لغة فيه، وهو مأخوذ من السراب قال أبو ليلى: اليلمعي من القوم: الداعي الذي يتظنى الأمور ولا يكاد يخطىء ظنه، قال أوس بن حجر 15 : اليلمعي الذي يظن بك الظن كأن قد رأى وقد سمعا واللماع جمع اللمعة من الكلأ. والتمعت الشيء ذهبت به، وأما قول الشاعر 16 : أبرنا من فصيلتهم لماعا أي: السيد اللامع، وإن شئت فمعناه. التمعناهم، أي: استأصلناهم.'),
(418, 'عنف', 'عنف', 'عنف', 'العنف: ضد الرفق. عنف يعنف عنفا فهو عنيف. وعنفته تعنيفا، ووجدت له عليك عنفا ومشقة. وعنفوان الشباب: أول بهجته، وكذلك النبات. قال 1 : تلوم امرأ في عنفوان شبابه ... وتترك أشياع الضلالة حيرا وقال 2 : وقد دعاها العنفوان المخلس واعتنفت الشيء كرهته.'),
(419, 'عفن', 'عفن', 'عفن', 'عفن الشيء يعفن عفنا فهو عفن، وهو الشيء الذي فيه ندوة يحبس في موضع فيفسد فإذا مسسته تفتت. وعفن الخبز أيضا إذا فسد وعشش.'),
(420, 'نعف', 'نعف', 'نعف', 'النعف من الأرض: المكان المرتفع في اعتراض، ويقال: ناحية من الجبل، وناحية من رأسه. والرجل ينتعف إذا ارتقى نعفا. قال العجاج 3 : والنعف بين الأسحمان الأطول وقال رؤبة 4 : بادرن ريح مطر وبرقا ... وظلمة الليل نعافا بلقا والنعف: ذؤابة النعل. والنعفة: أدمة تضطرب خلف مؤخر الرحل.'),
(421, 'نفع', 'نفع', 'نفع', 'النفع: ضد الضر. نفعه نفعا، وانتفعت بكذا. والنفعة في جانبي المزادة، يشق الأديم فيجعل في كل جانب نفعة. نفيع: اسم رجل.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(422, 'فنع', 'فنع', 'فنع', 'الفنع: نشر المسك ونفحته، ونشر الثناء الحسن. يقال: له 5 فنع في الجود، قال 6 : وفروع سابغ أطرافها ... عللتها ريح مسك ذي فنع أي: ذي نشر. ومال ذو فنع، وذو فنأ 7 ، أي: ذو كثرة. والفنع أكثر وأعرف.'),
(423, 'عنب', 'عنب', 'عنب', 'رجل عانب: ذو عنب كثير، كما يقال: لابن وتامر، أي كثير اللبن والتمر، الواحدة: عنبة ويجمع أعنابا. والعناب: ثمر، والعناب الجبل الصغير الأسود. وظبي عنبان: نشيط، ولم أسمع للعنبان فعلا. قال 1 : يشتد شد العنبان البارح والعنبة: قرحة تعرف بهذا الاسم. والعناب: المطر، ويجمع أعنبة.'),
(424, 'عبن', 'عبن', 'عبن', 'العبن [والعبنى] 2 : الجمل الشديد الجسيم. وناقة عبنة وعبناة، ويجمع: عبنيات. ورجل عبن الخلق: أي ضخمه وجسيمه. قال حميد بن ثور 3 : وفيها عبن الخلق مختلف الشبا ... يقول المماري طال ما كان مقرما'),
(425, 'نعب', 'نعب', 'نعب', 'نعب الغراب ينعب نعيبا ونعبانا، وهو صوته. وفرس منعب: جواد. وناقة نعابة، أي: سريعة.'),
(426, 'نبع', 'نبع', 'نبع', 'نبع الماء نبعا ونبوعا: خرج من العين، ولذلك سميت العين ينبوعا. والنبع: شجر يتخذ منها القسي. ينابعى: اسم مكان ويجمع: ينابعات. قال 4 : سقى الرحمن حزن ينابعات ... من الجوزاء أنواء غزارا'),
(427, 'عنم', 'عنم', 'عنم', 'العنم: شجر من شجر السواك، لين الأغصان لطيفها، كأنها بنان جارية. الواحدة: عنمة. ويقال: العنم: شوك الطلح. والعنمة: ضرب من الوزغ مثل العظاية إلا أنها أحسن منها وأشد بياضا. قال رؤبة 1 : يبدين أطرافا لطافا عنمه'),
(428, 'نعم', 'نعم', 'نعم', 'نعم ينعم نعمة فهو نعم ناعم بين المنعم. قال 2 : هذا أواني وأوانكنه ... ليس النعيم دائما لكنه والنعماء اسم النعمة. والنعيم: الخفض والدعة. والنعمة: اليد الصالحة، وأنعم الله عليه. وجارية ناعمة منعمة، وأنعم الله بك عينا، ونعم بك عينا، أي: أقر بك عين من تحب. وتقول: نعمة عين، ونعماء عين، ونعام عين. والنعمة: المسرة. ونعم الرجل فلان، وإنه لنعما وإنه لنعيم. نعم: كقولك: بلى، إلا أن نعم في جواب الواجب. والنعامى: اسم ريح الجنوب. قال 3 : مرته الجنوب فلم يعترف ... خلاف النعامى من الشام ريحا والنعام الذكر وهو الظليم. والنعامة: الخشبة المعترضة على الرجامين تتعلق عليها البكرة، وهما نعامتان. وزعموا أن ابن النعامة من الطرق كأنه مركب النعامة. قال 4 : ويكون مركبك القعود ورحله ... وابن النعامة عند ذلك مركبي ويقال: ليس ابن النعامة هاهنا الطريق، ولكنه صدر القدم. وهو الطريق أيضا. ويقال: قد خفت نعامتهم، أي: استمر بهم السير. والنعم: الإبل إذا كثرت. وزعم المفسرون أن النعم الشاء والإبل، في قول الله عز وجل: ومن الأنعام حمولة وفرشا 5 . والنعائم: من منازل القمر.. والأنعمان: واديان. وتقول: دققته دقا نعما، أي زدته على الدق. وأحسن وأنعم، أي زاد على الإحسان. ينعم: حي من اليمن. نعمان: أرض بالحجاز أو بالعراق. وفلان من عيشه في نعم. نعيم ونعمان: اسمان.'),
(429, 'معن', 'معن', 'معن', 'أمعن الفرس ونحوه إمعانا، إذا تباعد يعدو. ومعن يمعن معنا أيضا. والماعون يفسر بالزكاة والصدقة. ويقال: هو أسقاط البيت، نحو الفأس، والقدر، والدلو.. معن: اسم رجل.'),
(430, 'منع', 'منع', 'منع', 'منعته أمنعه منعا فامتنع، أي: حلت بينه وبين إرادته. ورجل منيع: لا يخلص إليه، وهو في عز ومنعة، ومنعة- يخفف ويثقل، وامرأة منيعة: متمنعة لا تؤاتى على فاحشة، قد منعت مناعة، وكذلك الحصن ونحوه. ومنع مناعة 6 إذا لم يرم. [ومناع بمعنى امنع] 7 قال 8 : مناعها من إبل مناعها'),
(431, 'فعم', 'فعم', 'فعم', 'يقال: فعم فعامة وفعومة، فهو فعم، أي: ملآن. قال كعب بن زهير 1 : فعم مقلدها عبل مقيدها ... في خلقها عن بنات الفحل تفضيل وامرأة فعمة الساق، فعمت فعامة وفعومة، أي: مستوية الكعب، غليظة الساق. قال 2 : فعم [مخلخلها] 3 وعث مؤزرها ... عذب مقبلها طعم السدا فوها وأفعمت البيت بريح العود. وافعوعم النهر والبحر، أي: امتلأ. قال 4 : مفعوعم صخب الآذي منبعق ... كأن فيه أكف القوم تصطفق يعني النهر. وأفعمته فهو مفعم. وأفعم المسك البيت. وقوله في البيت الأول: طعم السدا: السدا: البلح.'),
(432, 'عبم', 'عبم', 'عبم', 'العبام: الرجل الغليظ الخلق. في حمق عبم يعبم عبامة [فهو عبام] 1 . قال 2 : فأنكرت إنكار الكريم ولم أكن ... كفدم عبام سيل نسيا فجمجما'),
(433, 'عرو', 'عرو', 'عرو', 'عري: عراه أمر يعروه عروا إذا غشيه وأصابه، يقال: عراه البرد، وعرته الحمى، وهي تعروه إذا جاءته بنافض، وأخذته الحمى بعروائها. وعري الرجل فهو معرو، واعتراه الهم. عام في كل شيء، حتى يقال: الدلف يعتري الملاحة. ويقال: ما من مؤمن إلا وله ذنب يعتريه قال أعرابي إذا طلع السماك فعند ذلك يعروك ما عداك من البرد الذي يغشاك. وعري فلان عروة وعرية شديدة وعريا فهو عريان والمرأة عريانة، ورجل عار وامرأة عارية. والعريان من الخيل: فرس مقلص طويل القوائم. والعريان من الرمل ما ليس عليه شجر. وفرس عري: ليس على ظهره شيء، وأفراس أعراء، ولا يقال: رجل عري، واعروريت الفرس: ركبته عريا، ولم يجىء افعوعل مجاوز غير هذا. والعراء: الأرض الفضاء التي لا يستتر فيها بشيء، ويجمع: أعراء، وثلاثة أعرية والعرب تذكره فتقول: انتهينا إلى عراء من الأرض واسع بارد، ولا يجعل نعتا للأرض. وأعراء الأرض: ما ظهر من متونها. قال 1 : وبلد عارية أعراؤه وقال 2 : أو مجن عنه عريت أعراؤه واعرورى السراب ظهور الآكام إذا ماج عنها فأعراها. ماج عنها: ذهب عنها، ويقال: بل إذا علا ظهورها. والعراء: كل شيء أعريته من سترته، تقول: استره من العراء، ويقال: لا يعرى فلان من هذا الأمر أي: لا يخلص، ولا يعرى من الموت أحد، أي: لا يخلص. قال 3 : وأحداث دهر ما يعرى بلاؤها والعرى: الريح الباردة. [يقال] : ريح عرية، ومساء عري، وليلة عرية ذات ريح باردة قال ذو الرمة 4 : وهل أحطبن القوم وهي عرية ... أصول ألاء في ثرى عمد جعد والعروة: عروة الدلو وعروة المزادة وعروة الكوز. والجمع: عرى. والنخلة العرية: التي عزلت عن المساومة لحرمة أو لهبة إذا أينع ثمر النخل، ويجمع: عرايا. وفي الحديث: أن رسول الله صلى الله عليه وآله رخص في العرايا 5 . وعريت الشيء: اتخذت له عروة كالدلو ونحوه. وجارية حسنة المعرى، أي: [حسنة عند تجريدها من ثيابها] 6 والجميع: المعاري: والمعاري مبادىء رءوس العظام حيث تعرى العظام عن اللحم. ويقال: المعاري: اليدان والرجلان والوجه لأنه باد أبدا. قال أبو كبير الهذلي يصف قوما ضربوا على أيديهم وأرجلهم حتى سقطوا 7 : متكورين على المعاري بينهم ... ضرب كتعطاط المزاد الأنجل والعروة من النبات: ما تبقى له خضرة في الشتاء تتعلق بها الإبل حتى تدرك الربيع. وهي العلقة. قال 8 : خلع الملوك وآب تحت لوائه ... شجر العرى وعراعر الأقوام ويقال: العروة: الشجر الملتف الذي تشتو فيه الإبل فتأكل منه، وتبرك في أذرائه.'),
(434, 'عور', 'عور', 'عور', 'عير: عارت العين تعار عوارا، وعورت أيضا، واعورت. يعني ذهاب البصر [منها] . قال 9 : وربة سائل عني حفي ... أعارت عينه أم لم تعارا والعوار: ضرب من الخطاطيف، أسود طويل الجناحين. والعوار: الرجل الجبان السريع الفرار، وجمعه عواوير. قال 10 : غير ميل ولا عواوير في الهيجا ... ولا عزل ولا أكفال والعرب تسمي الغراب أعور، وتصيح به فتقول: عوير عوير. قال 11 : يطير عوير أن أنوه باسمه ... عوير'),
(435, 'حق', 'حق', 'حق', 'الحق نقيض الباطل. حق الشيء يحق حقا أي وجب وجوبا. وتقول: يحق عليك أن تفعل كذا، وأنت حقيق على أن تفعله. وحقيق فعيل في موضع مفعول. وقول الله عز وجل 1 - حقيق على أن لا أقول 2 معناه محقوق كما تقول: واجب. وكل مفعول رد إلى فعيل فمذكره ومؤنثه بغير الهاء، وتقول للمرأة: أنت حقيقة لذلك، وأنت محقوقة أن تفعلي ذلك، قال الأعشى: لمحقوقة أن تستجيبي لصوته ... وأن تعلمي أن المعان موفق 3 والحقة من الحق كأنها أوجب وأخص. تقول: هذه حقتي أي حقي. قال: وحقه ليست بقول الترهة. والحقيقة: ما يصير إليه حق الأمر ووجوبه. وبلغت حقيقة هذا: أي يقين شأنه. وفي الحديث: لا يبلغ أحدكم حقيقة الإيمان حتى لا يعيب على مسلم 4 بعيب هو فيه. وحقيقة الرجل: ما لزمه الدفاع عنه من أهل بيته، والجميع حقائق. وتقول: أحق الرجل إذا قال حقا وادعى حقا فوجب له وحقق، كقولك: صدق وقال هذا هو الحق. وتقول: ما كان يحقك أن تفعل كذا أي ما حق لك. والحاقة: النازلة التي حقت فلا كاذبة لها. وتقول للرجل إذا خاصم في صغار الأشياء: إنه لنزق الحقاق. وفي الحديث: متى ما يغلوا يحتقوا أي يدعي كل واحد أن الحق في يديه، ويغلوا أي يسرفوا في دينهم ويختصموا ويتجادلوا. والحق: دون الجذع من الإبل بسنة، وذلك حين يستحق للركوب، والأنثى حقة: إذا استحقت الفحل، وجمعه حقاق وحقائق، قال عدي: لا حقة هن ولا ينوب 1 وقال الأعشى 2 أي قوم قومي إذا عزت الخمر ... وقامت زقاقهم والحقاق والرواية: قامت حقاقهم والزقاق فمن رواه: قامت زقاقهم والحقاق يقول: استوت في الثمن فلم يفضل زق حقا، ولا حق زقا. ومثله: قامت زقاقهم بالحقاق فالباء والواو بمنزلة واحدة، كقولهم: قد قام القفيز ودرهم، وقام القفيز بدرهم. وأنت بخير يا هذا، وأنت وخير يا هذا، وقال 3 : ولا ضعاف مخهن زاهق ... لسن بأنياب ولا حقائق وقال 1 : أفانين مكتوب لها دون حقها ... إذا حملها راش الحجاجين بالثكل جعل الحق وقتا. وجمع الحقة من الخشب حقق، قال رؤبة: سوى مساحيهن تقطيط الحقق 2 والحقحقة: سير أول الليل، وقد نهي عنه، ويقال: هو إتعاب ساعة. وفي الحديث: إياكم والحقحقة في الأعمال، فإن أحب الأعمال إلى الله ما داوم عليه العبد وإن قل. ونبات الحقيق 3 : ضرب من التمر وهو الشيص.'),
(436, 'قح', 'قح', 'قح', 'والقح الجافي من الناس والأشياء، يقال للبطيخة التي لم تنضج: إنها لقح 4 . والفعل: قح يقح قحوحة، قال: لا أبتغي سيب اللئيم القح ... يكاد من نحنحة وأح يحكي سعال الشرق الأبح 5 والقح: الشيخ الفاني. والقح: الخالص من كل شيء. والقحقح: فوق القب شيئا. والقب: العظم الناتىء من الظهر بين الأليتين.'),
(437, 'حك', 'حك', 'حك', 'الحكيك: الكعب المحكوك. والحكيك: الحافر النحيت. والحككة: حجر رخو أبيض أرخى من الرخام وأصلب من الجص. والحاكة: السن، تقول: ما فيه حاكة. ويقال: إنه ليتحكك بك: أي يتعرض لشرك. وحك في صدري واحتك: وهو ما يقع في خلدك من وساوس الشيطان. وفي الحديث: إياكم والحكاكات فإنها المآتم. وحككت رأسي أحكه حكا. واحتك رأسه احتكاكا. وقوله 2 : أنا جذيلها المحكك أي عمادها وملجأها.'),
(438, 'كح', 'كح', 'كح', 'الأكح: الذي لا سن له. والكحكح: المسن من الشاء والبقر.'),
(439, 'حج', 'حج', 'حج', 'قد تكسر الحجة والحج فيقال: حج وحجة. ويقال للرجل الكثير الحج حجاج من غير إمالة. وكل نعت على فعال فإنه مفتوح الألف، فإذا صيرته اسما يتحول عن حال النعت فتدخله الإمالة كما دخلت في الحجاج والعجاج. وحج علينا فلان أي قدم. والحج: كثرة القصد إلى من يعظم، قال: كانت تحج بنو سعد عمامته ... إذا أهلوا على أنصابهم رجبا 3 حجوا عمامته: أي عظموه. والحجة: شحمة الأذن، قال لبيد: يرضن صعاب الدر في كل حجة ... وإن لم تكن أعناقهن عواطلا 1 ويقال: الحجة هيهنا الموسم. والحجحجة: النكوص، تقول: حملوا ثم حجحجوا أي نكصوا، قال 2 : حتى رأى رايتهم فحجحجا والمحجة: قارعة الطريق الواضح. والحجة: وجه الظفر عند الخصومة. والفعل حاججته فحججته. واحتججت عليه بكذا. وجمع الحجة: حجج. والحجاج المصدر. والحجاج: العظم المستدير حول العين، ويقال: بل هو الأعلى الذي تحت الحاجب، وقال: 3 إذا حجاجا مقلتيها هججا والحجيج: ما قد عولج من الشجة، وهو اختلاط الدم بالدماغ فيصب عليه السمن المغلي حتى يظهر الدم فيؤخذ بقطنة، يقال: حججته أحجه حجا. الجحجاح: السيد السمح الكريم، ويجمع: جحاجحة، ويجوز بغير الهاء، قال أمية 4 : ماذا ببدر فالعقنقل ... من مرازبة جحاجح وأجحت الكلبة: أي حملت فهي مجح.'),
(440, 'حش', 'حش', 'حش', 'حششت النار بالحطب أحشها حشا: أي ضممت ما تفرق من الحطب إلى النار. والنابل إذا راش السهم فألزق القذذ به من نواحيه يقال: حش سهمه بالقذذ، قال: أو كمريخ على شريانة ... حشه الرامي بظهران حشر 1 والبعير والفرس إذا كان مجفر الجنبين يقال: حش ظهره بجنبين واسعين، قال أبو داود في الفرس: من الحارك محشوش ... بجنب جرشع رحب 2 والحشاشة: روح القلب. والحشاشة: رمق بقية من حياة النفس، قال يصف القردان 3 : إذا سمعت وطء الركاب تنغشت ... حشاشتها في غير لحم ولا دم والحشيش الكلأ، والطاقة منه حشيشة، والفعل الاحتشاش. والمحشة: الدبر. وفي الحديث: محاش النساء حرام ويروى: محاسن بالسين أيضا. والحش والحش: جماعة النخل، والجميع الحشان. ويقال لليد الشلاء: قد حشت ويبست. وإذا جاوزت المرأة وقت الولاد 1 وهي حامل ويبقى الولد في بطنها يقال: قد حش ولدها في بطنها أي يبس. وأحشت المرأة فهي محش. والحش: المخرج.'),
(441, 'شح', 'شح', 'شح', 'يقال: زند شحاح: أي لا يوري. والشحشح: المواظب على الشيء الماضي فيه. والشحشح: الرجل الغيور وهو الشحشاح، قال 2 : فيقدمها شحشح عالم ويقال: شحشح البعير في الهدر وهو الذي ليس بالخالص من الهدر، قال: فردد الهدر وما إن شحشحا 3 ويقال للخطيب الماهر في خطبته الماضي فيها: شحشح. والشح: البخل وهو الحرص. وهما يتشاحان على الأمر: لا يريد كل واحد منهما أن يفوته. والنعت شحيح وشحاح والعدد أشحة. وقد شح يشح شحا.'),
(442, 'حض', 'حض', 'حض', 'حض: الحضيضى والحثيثى من الحض والحث. وقد حض يحض حضا. والحضض: دواء يتخذ من أبوال الإبل. والحضيض: قرار الأرض عند سفح الجبل.'),
(443, 'ضح', 'ضح', 'ضح', 'الضح والضيح: ضوء الشمس إذا استمكن من الأرض. والضحضاح: الماء إلى الكعبين، أو إلى أنصاف السوق. والضحضحة والتضحضح 1 : جري السراب وتلعلعه:'),
(444, 'حص', 'حص', 'حص', 'الحصحصة: الحركة في الشيء حتى يستقر فيه ويستمكن منه. وتحاص القوم تحاصا: يعني الاقتسام من الحصة. والحصحصة: بيان الحق بعد كتمانه. حصحص الحق، ولا يقال: حصحص الحق. والحصاص: سرعة العدو في شدة. ويقال: الحصاص: الضراط. والحص: الورس، وإن جمع فحصوص، يصبغ به، وهو الزعفران أيضا. والحص: إذهابك الشعر كما تحص البيضة رأس صاحبها، قال 1 : قد حصت البيضة رأسي فما ... أطعم ونوما غير تهجاع وقال: 2 بميزان قسط لا يحص شعيرة ... له شاهد من نفسه غير فاضل 3 لا يحص: أي لا ينقص. ويقال: رجل أحص وامرأة حصاء. وقال في السنة الجرداء الجدبة: علوا على شارف صعب مراكبها ... حصاء ليس بها هلب ولا وبر 4 علوا: حملوا على ذلك'),
(445, 'صح', 'صح', 'صح', 'الصحة: ذهاب السقم والبراءة من كل عيب وريب. صح يصح صحة. (والصوم مصحة 5 ) ومصحة، ونصب الصاد أعلى من الكسر. يعني يصح عليه. والصحصان والصحصح: ما استوى وجرد من الأرض، ويجمع صحاصح، قال: وصحصحان قذف كالترس 1'),
(446, 'حس', 'حس', 'حس', 'الحس: القتل الذريع. والحس: إضرار البرد الأشياء، تقول: أصابتهم حاسة من البرد، وبات فلان بحسة سوء 2 : أي بحال سيئة وشدة. والحس: نفضك التراب عن الدابة بالمحسة وهي الفرجون. ويقال: ما سمعت له حسا ولا جرسا، فالحس من الحركة، والجرس من الصوت. والحس: داء يأخذ النفساء في رحمها. وأحسست من فلان أمرا: أي رأيت. وعلى الرؤية يفسر (قوله عز وجل) : فلما أحس عيسى منهم الكفر 3 أي رأى. ويقال: محسة المرأة: دبرها. ويقال: ضرب فلان فما قال حس ولا بس، ومنهم من لا ينون ويجر فيقول: حس، ومنهم من يكسر الحاء 4 . والعرب تقول عند لذعة نار أو وجع: حس حس 5 . والحس: مس الحمى أول ما تبدو 1 . والحس: الحسيس تسمعه يمر بك ولا تراه، قال: ترى الطير العتاق يظلن منه 2 ... جنوحا إن سمعن له حسيسا وتحسست خبرا: أي سألت وطلبت.'),
(447, 'سح', 'سح', 'سح', 'السحسحة: عرصة المحلة وهي الساحة. وسحت الشاه تسح سحا وسحوحا أي حنت. وشاة سمينة ساح، ولا يقال: ساحة. قال الخليل: هذا مما يحتج به، إنه قول العرب فلا نبتدع شيئا فيه. وسح المطر والدمع يسح سحا وهو شدة انصبابه. وفرس مسح: أي سريع، قال 3 : مسح إذا ما السابحات على الونى ... أثرن الغبار بالكديد المركل'),
(448, 'حز', 'حز', 'حز', 'الحز: قطع في اللحم غير بائن. والفرض في العظم والعود غير طائل حز أيضا. يقال: حززته حزا، واحتززته احتزازا، قال الشاعر: 4 وعبد يغوت تحجل الطير حوله ... قد احتز عرشيه الحسام المذكر فجعل الاحتزاز هيهنا قطع العنق. والحزازة: هبرية في الرأس 1 ، وتجمع على حزاز. والحزازة أيضا: وجع في القلب من غيظ ونحوه. والحزاز يقال في القلب أيضا، قال الشماخ: فلما شراها فاضت العين عبرة ... وفي الصدر حزاز من اللوم حامز 2 وقال 3 : وقد ينبت المرعى على دمن الثرى ... وتبقى حزازات النفوس كما هيا وتقول: أعطيته حزة من لحم 4 . والحزاز من الرجال: الشديد على 5 السوق والقتال، قال: فهي تفادى من حزاز ذي حزق 6 وفي الحديث: أخذ بحزته يقال: أخذ بعنقه، وهو من السراويل حزة وحجزة، والعنق عندي تشبيه به. وحزاز 7 القلوب: ما حز وحك في قلبه. والحزيز: موضع من الأرض كثرت حجارته وغلظت كأنها سكاكين، ويجمع على حزان وثلاثة أحزة 8 . وإذا أصاب المرفق طرف كركرة البعير فقطعه قيل به حاز.'),
(449, 'زح', 'زح', 'زح', 'الزح: جذب الشيء في العجلة. زحه يزحه زحا. والزحزحة: التنحية عن الشيء [يقال] زحزحته فتزحزح.'),
(450, 'حط', 'حط', 'حط', 'الحط: وضع الأحمال عن الدواب. والحط: الحدر من العلو. وحطت النجيبة وانحطت في سيرها من السرعة، قال النابغة يمدح النعمان: فما وخدت بمثلك ذات غرب ... حطوط في الزمام ولا لجون 1 وقال: 2 مكر مفر مقبل مدبر معا ... كجلمود صخر حطه السيل من عل وحط عنه ذنوبه، قال: واحطط إلهي بفضل منك أوزاري 3 والحطاطة: بثرة تخرج في الوجه صغيرة تقبح 4 اللون ولا تقرح، قال: 5 ووجه قد جلوت أقيم صاف ... كقرن الشمس ليس بذي حطاط وبلغنا أن بني إسرائيل حيث قيل لهم: وقولوا حطة 1 * إنما قيل لهم ذلك حتى يستحطوا بها أوزارهم فتحط عنهم. ويقال للجارية الصغيرة: يا حطاطة. وجارية محطوطة المتنين أي ممدودة حسنة، قال النابغة: محطوطة المتنين غير مفاضة 2'),
(451, 'طح', 'طح', 'طح', 'الطح: أن يضع الرجل عقبه على شيء ثم يسحجه بها. والمطحة من الشاة مؤخر ظلفها وتحت الظلف في موضع المطحة عظيم كالفلكة. والطحطحة: تفريق الشيء هلاكا، وقال في خالد بن عبد الله القسري: فيمسي نابذا سلطان قسر ... كضوء الشمس طحطحه الغروب 3'),
(452, 'حد', 'حد', 'حد', 'فصل ما بين كل شيئين حد بينهما. ومنتهى كل شيء حده. وحد السيف واحتد. وهو جلد حديد. وأحددته. واستحد الرجل واحتد حدة [فهو] 4 حديد. وحدود الله: هي الأشياء التي بينها وأمر أن لا يتعدى فيها. والحد: حد القاذف ونحوه مما يقام عليه من الجزاء بما أتاه. والحديد معروف، وصاحبه الحداد. ورجل محدود: محارف في جده. وحد كل شيء: طرف شباته كحد السنان والسيف ونحوه. والحد: الرجل المحدود عن الخير. والحد: بأس الرجل ونفاذه في نجدته، قال العجاج: أم كيف حد مضر القطيم 1 وأحدت المرأة على زوجها فهي محد 2 وحدت بغير الألف أيضا، وهو التسليب بعد موته. وحاددته: عاصيته، من يحادد الله ، أي يعاصيه. وما عن هذا الأمر حدد: أي معدل 3 ولا محتد، مثله، قال الكميت: حددا أن يكون سيبك فينا ... رزما أو مجبنا ممصورا 4 وحدان: حي من اليمن. والحد: الصرف عن الشيء من الخير والشر. وتقول للرامي: اللهم احدده، أي لا توفقه للإصابة. وحددته عن كذا: منعته والاستحداء: حلق الشيء بالحديد، وحد الشراب: صلابته، قال الأعشى 5 : وكأس كعين الديك باكرت حدها ... بفتيان صدق والنواقيس تضرب'),
(453, 'دح', 'دح', 'دح', 'الدح: شبه الدس، وهو أن تضع شيئا على الأرض ثم تدقه وتدسه حتى يلزق، قال أبو النجم: بيتا خفيا في الثرى مدحوحا والدح أن ترمي بالشيء قدما 1 . والدحداح والدحداحة من الرجال والنساء: المستدير الململم، قال: أغرك أنني رجل قصير ... دحيدحة وأنك علطميس 2'),
(454, 'حت', 'حت', 'حت', 'الحت: فركك شيئا عن ثوب ونحوه، قال الشاعر: تحت بقرنيها برير أراكة ... وتعطو بظلفيها إذا الغصن طالها 3 وحتات كل شيء: ما تحات منه. والحت لا يبلغ النحت. وفي حديث النبي صلى الله عليه وسلم: احتتهم يا سعد فداك أبي وأمي يعني ارددهم. والفرس الكريم العتيق: الحت.'),
(455, 'تح', 'تح', 'تح', 'وتحت: نقيض فوق. والتحوت: الذين كانوا تحت أقدام الناس لا يشعر بهم. وفي حديث: لا تقوم الساعة حتى يظهر التحوت 4'),
(456, 'حظ', 'حظ', 'حظ', 'والحظ: النصيب من الفضل والخير، والجميع: الحظوظ. وفلان حظيظ، ولم نسمع فيه فعلا. وناس من أهل حمص يقولون: حنظ، فإذا جمعوا رجعوا إلى الحظوظ، وتلك النون عندهم غنة ليست بأصلية 1 . وإنما يجري على ألسنتهم في المشدد نحو الرز يقولون: رنز، ونحو أترجة يقولون أترنجة، ونحو اجار يقولون انجار فإذا جمعوا تركوا الغنة ورجعوا إلى الصحة فقالوا: أجاجير وحظوظ.'),
(457, 'حذ', 'حذ', 'حذ', 'الحذ: القطع المستأصل. والحذذ: مصدر الأحذ من غير فعل. والأحذ يسمى به الشيء الذي لا يتعلق به شيء. والقلب يسمى أحذ. والدنيا ولت حذاء مدبرة: لا يتعلق بها شيء. والأحذ من عروض الكامل: ما حذف من آخره وتد تام وهو متفاعلن حذف منه علن فصار متفا فجعل فعلن مثل قوله: وحرمت 2 منا صاحبا ومؤازرا ... وأخا على السراء والضر وقصيدة حذاء: أي سائرة لا عيب فيها. ويقال للحمار القصير الذنب: أحذ. ويقال للقطاة: حذاء لقصر ذنبها مع خفتها، قال الشاعر: 3 حذاء مقبلة سكاء مدبرة ... للماء في النحر منها نوطة عجب'),
(458, 'حث', 'حث', 'حث', 'حثيث فلانا فهو حثيث محثوث، وقد احتث. وامرأة حثيثة في موضع حاثة، وامرأ حثيث في موضع محثوثة. والحثيثى من الحث، قال: اقبلوا دليلى ربكم وحثيثاه إياكم 1 يعني ما يدلكم ويحثكم. والحثحثة: اضطراب البرق في السحاب وانتخال 2 ، المطر والثلج. والحثوث والحثحوث: السريع. قال زائدة: الحثحثة طلب الشيء وحركته، يقال: حثحث الأمر ليتحرك. وحثحث القوم: أي سلهم عن الأمور.'),
(459, 'ثح', 'ثح', 'ثح', 'الثحثحة: صوت فيه بحة عند اللهاة. قال: أبح مثحثح صحل 3 الشحيح 4'),
(460, 'حر', 'حر', 'حر', 'حر النهار يحر حرا. والحرور: حر الشمس. وحرت كبده حرة، ومصدره: الحرر، وهو يبس الكبد. والكبد تحر من العطش أو الحزن. وو الحريرة: دقيق يطبخ بلبن. والحرة: أرض ذات حجارة سود نخرة كأنما أحرقت بالنار، وجمعه حرار وإحرين وحرات، قال: لا خمس إلا جندل الإحرين ... والخمس قد جشمك الأمرين والحران: العطشان، وامرأة حرى. والحر: ولد الحية اللطيف في شعر الطرماح: كانطواء الحر بين السلام 2 والحر: نقيض العبد، حر بين الحرورية والحرية والحرار 3 . والحرارة: سحابة حرة من كثرة المطر. والمحرر في بني إسرائيل: النذيرة. كانوا يجعلون الولد نذيرة لخدمة الكنيسة ما عاش لا يسعه تركه في دينهم. والحر: فعل حسن في قول طرفة: لا يكن حبك داء قاتلا ... ليس هذا منك ماوي بحر 4 والحرية من الناس: خيارهم. والحر من كل شيء اعتقه. وحرة الوجه: ما بدا من الوجنة. والحر: فرخ الحمام، قال حميد [بن ثور] : وما هاج هذا الشوق إلا حمامة ... دعت ساق حر في حمام ترنما 5 وحرة النفرى: موضع مجال القرط. والحر والحرة: الرمل والرملة الطيبة، قال: واقبل كالشعرى وضوحا ونزهة ... يواعس من حر الصريمة معظما يصف الثور. وقول العجاج: في خشاوى حرة التحرير أي حرة الحرار 1 ، أي هي حرة. وتحرير الكتاب: إقامة حروفه وإصلاح السقط. وحروراء 2 : موضع، كان أول مجتمع الحرورية بها وتحكيمهم منها. وطائر يسمى ساق حر. والحر في قول طرفة ولد الظبي حيث يقول 3 : بين أكناف خفاف فاللوى ... مخرف يحنو لرخص الظلف حر وحران: موضع. وسحابة حرة تصفها بكثرة المطر. ويقال لليلة التي تزف فيها العروس إلى زوجها فلا يقدر على افتضاضها ليلة حرة، فإذا افتضها فهي ليلة شيباء، قال 4 : شمس موانع كل ليلة حرة'),
(461, 'رح', 'رح', 'رح', 'الرحح: انبساط الحافر وعرض القدم، وكل شيء كذلك فهو أرح، قال الأعشى: فلو أن عز الناس في رأس صخرة ... ململمة تعيي الأرح المخدما 5 يعني الوعل يصفه بانبساط أظلافه. ويستعمل أيضا في الخفين وترحرحت الفرس إذا فحجت قوائمها لتبول. رحرحان: موضع.'),
(462, 'حل', 'حل', 'حل', 'المحل: نقيض المرتحل، قال الأعشى: إن محلا وإن مرتحلا ... وإن في السفر ما مضى مهلا 1 قلت للخليل: أليس تزعم أن العرب العاربة لا تقول: إن رجلا في الدار، لا تبدأ بالنكرة ولكنها تقول: إن في الدار رجلا، قال: ليس هذا على قياس ما تقول، هذا من حكاية سمعها رجل من رجل: إن محلا وإن مرتحلا. ويصف بعد ذلك حيث يقول: هل تذكر العهد في تنمص إذ ... تضرب لي قاعدا بها مثلا والمحل الآخرة، والمرتحل: الدنيا، وقال بعضهم: أراد أن فيه محلا وأن فيه مرتحلا فأضمر الصفة. والمحل مصدر كالحلول. والحل والحلال والحلول والحلل: جماعة الحال النازل، قال رؤبة: وقد أرى بالجو حيا حللا ... حلا 2 حلالا يرتعون القنبلا والمحلة: منزل القوم. وأرض محلال: إذا أكثر القوم الحلول بها. والحلة: قوم نزول، قال الأعشى: لقد كان في شيبان لو كنت عالما ... قباب وحتى حلة وقبائل وتقول: حللت العقدة أحلها حلا إذا فتحتها فانحلت. ومن قرأ: يحلل عليه غضبي 1 [ف] معناه ينزل. ومن قرأ: يحلل يفسر: يحب من حل عليه الحق يحل محلا. وكانت العرب في الجاهلية الجهلاء إذا نظرت إلى الهلال قالت: لا مرحبا بمحل الدين مقرب الأجل. والمحل: الذي يحل لنا قتله 2 ، والمحرم الذي يحرم علينا قتله، وقال: 3 وكم بالقنان من محل ومحرم ويقال: المحل الذي ليس له عهد ولا حرمة، والمحرم: الذي له حرمة. والتحليل والتحلة من اليمين. حللت اليمين تحليلا وتحلة، وضربته ضربا تحليلا يعني شبه التعزير غير مبالغ فيه، اشتق من تحليل اليمين ثم أجري في سائر الكلام حتى يقال في وصف الإبل إذا بركت: نجائب وقعها في الأرض تحليل 4 أي: هين. والحليل والحليلة: الزوج والمرأة لأنهما يحلان في موضع واحد، والجميع حلائل. وحلحلت بالإبل إذا قلت: حل بالتخفيف، وهو زجر، قال: قد جعلت ناب دكين ترحل 5 ... أخرى وإن صاحوا بها وحلحلوا وحلحلت القوم: أزلتهم عن موضعهم. ويقال: الحلة إزار ورداء برد أو غيره. ولا يقال لها حلة حتى تكون ثوبين. وفي الحديث تصديقه وهو ثوب يماني. ويقولون للماء والشيء اليسير محلل، كقوله: 1 نمير الماء غير محلل أي غير يسير. ويحتمل هذا المعنى أن تقول: غذاها غذاء ليس بمحلل، أي ليس بيسير ولكن بمبالغة. ويقال: غير محلل أي غير منزول عليه فيكدر ويفسد. قال الضرير: غير محلل أي ليس بقدر تحلة اليمين ولكن فوق ذلك رياء. وحلت العقوبة عليه تحل: وجبت. والحل: الحلال نفسه، لا هن حل. وشاة محل: قد أحلت إذا نزل اللبن في ضرعها من غير نتاج ولا ولاد. وغنم محال. والإحليل: مخرج البول من الذكر ومخرج اللبن من الضرع. والحل: الرجل الحلال الذي خرج من إصراحه، والفعل أحل إحلالا. والحل: ما جاور الحرم. والحلان 2 : الجدي ويجمع حلالين، ويقال هذا للذي يشق عنه بطن أمه، قال عمرو بن أحمر: تهدى إليه ذراع الجفر تكرمة ... إما ذبيحا وإما كان حلانا ويروى: ذراع البكر والجدي. والحلاحل: السيد الشجاع. والمحل: مبلغ المسافر حيث يريد. والمحل: الموضع الذي يحل نحره يوم النحر بعد رمي جمار العقبة. وفي الحديث: أحل بمن أحل بك 1 . يقول: من ترك الإحرام وأحل بك فقاتلك فاحلل أنت به فقاتله.'),
(463, 'لح', 'لح', 'لح', 'الإلحاح: الإلحاف في المسألة، ألح يلح فهو ملح. وألح المطر بالمكان: أي دام به. والإلحاح: الإقبال على الشيء لا يفتر عنه. وتقول: هو ابن عم لح في النكرة، وابن عمي لحا في المعرفة، وكذلك المؤنث والأثنان والجماعة بمنزلة الواحد.'),
(464, 'حن', 'حن', 'حن', 'الحن: حي من الجن، [يقال: منهم الكلاب السود] 2 البهم [يقال:] كلب حني. والحنان: الرحمة، والفعل: التحنن. والله الحنان المنان الرحيم بعباده. وحنانا من لدنا 3 . أي رحمة من عندنا. وحنانيك يا فلان افعل كذا ولا تفعل كذا تذكره الرحمة والبر. ويقال: كانت أم مريم تسمى حنة. والاستحنان: الاستطراب. وعود حنان: مطرب يحن. وحنين الناقة: صوتها إذا اشتاقت، ونزاعها إلى ولدها من غير صوت، قال رؤبة: حنت قلوصي أمس بالأردن ... حني فما ظلمت أن تحني 4 والحنة: خرقة تلبسها المرأة فتغطي بها رأسها.'),
(465, 'نح', 'نح', 'نح', 'النحنحة: أسهل من السعال. وهو علة البخيل، قال: والتغلبي إذا تنحنح للقرى ... حك استه وتمثل الأمثالا وقال: يكاد من نحنحة وأح ... يحكي سعال الشرق الأبح 1'),
(466, 'حف', 'حف', 'حف', 'حف الشعر يحف حفوفا: إذا يبس. واحتفت المرأة: أمرت من تحف شعر وجهها بخيطين. والحفوف: اليبوسة من غير دسم، قال رؤبة: قالت سليمى أن رأت حفوفي مع اضطراب اللحم والشفوف 2 وحفت المرأة وجهها تحفه حفا وحفوفا. وسويق حاف: غير ملتوت. والحفيف: صوت الشيء تحسه كالرمية أو طيران طائر أو غيره، حف يحف حفيفا. وحفان الإبل: صغارها. والحفان: الخدم. والمحفة: رحل يحف بثوب تركبه المرأة. وحفافا كل شيء: جانباه. وحف الحائك: خشبته العريضة [ينسق] 3 بها اللحمة بين السدى. وحف القوم بسيدهم: أي أطافوا به وعكفوا، ومنه قوله: حافين من حول العرش 4 . والحف: نتف الشعر بخيط ونحوه.'),
(467, 'فح', 'فح', 'فح', 'فحيح الحية شبيه بالنفخ في نضنضة، أي بضرب أسنانها. [وقيل] : فحيح الأفعى دلك بعض جلدها ببعض، وهي خشناء الجلد. والفحفاح: الأبح من الرجال.'),
(468, 'حب', 'حب', 'حب', 'أحببته نقيض أبغضته. والحب والحبة بمنزلة الحبيب والحبيبة. والحب: الجرة الضخمة ويجمع على: حببة وحباب، وقالوا: الحبة إذا كانت حبوب مختلفة من كل شيء [شيء] . وفي الحديث: كما تنبت الحبة في حميل السيل. ويقال لحب الرياحين حبة، وللواحدة حبة. وحبة القلب: ثمرته، قال الأعشى: فرميت غفلة عينه عن شاته ... فأصبت حبة قلبها وطحالها 1 ويقال: حب إلينا فلان يحب حبا، قال: وحب إلينا أن نكون المقدما 2 وحبابك أن يكون ذاك 3 ، معناه: غاية محبتك. والحب: القرط من حبة واحدة، قال: 4 تبيت الحية النضناض منه ... مكان الحب يستمع السرارا وحباب الماء: فقاقيعه الطافية كالقوارير، ويقال: بل معظم الماء، قال طرفة: يشق حباب الماء حيزومها بها ... كما قسم الترب المفايل باليد فهذا يدل على أنه معظم الماء، وقال الشاعر: كأن صلا جهيزة حين تمشي 1 ... حباب الماء يتبع الحبابا ويروي: حين قامت. لم يشبه صلاها ومآكمها بالفقاقيع وإنما شبهها بالحباب الذي كأنه درج في حدبة 2 . وحبب الأسنان: تنضدها، قال طرفة: وإذا تضحك تبدي حببا ... كأقاحي الرمل عذبا ذا أشر وحبان وحبان: اسم من الحب. والحبحاب: الصغير: ونار الحباحب: ذباب يطير بالليل له شعاع كالسراج. ويقال: بل نار الحباحب ما اقتدحت من شرار 3 النار في الهواء من تصادم الحجارة. وحبحبتها: اتقادها. وقيل في تفسير الحب والكرامة: إن الحب الخشبات الأربع التي توضع عليها الجرة ذات العروتين، والكرامة: الغطاء الذي يوضع فوق الجرة من خشب كان أو من خزف. قال الليث: سمعت هاتين بخراسان. حبذا: حرفان حب وذا، فإذا وصلت رفعت بهما، تقول: حبذا زيد.'),
(469, 'بح', 'بح', 'بح', 'عود أبح: إذا كان في صوته غلظ. والبحح مصدر الأبح. والبح إذا كان من داء فهو البحاح. والتبحبح: التمكن في الحلول والمقام، والمرأة إذا ضربها الطلق، قال أعرابي: تركتها تبحبح على أيدي القوابل. وقال في البحح أي مصدر الأبح: ولقد بححت من النداء ... لجمعكم هل من مبارز والبحبوحة: وسط محلة القوم، قال جرير: ينفون تغلب عن بحبوحة الدار 1'),
(470, 'حم', 'حم', 'حم', 'حم الأمر: قضي. وقدروا احتممت الأمر اهتممت، قال: كأنه من اهتمام بحميم وقريب. والحمام: قضاء الموت. والحميم: الماء الحار وتقول: أحمني الأمر. والحامة: خاصة الرجل من أهله وولده وذوي قرابته. والحمام: أخذ من الحميم، تذكره العرب. والحميم: الماء الحار. وأحمت الأرض: أي صارت ذات حمى كثيرة. وحم الرجل فهو محموم، وأحمه الله. والحمة: عين فيها ماء حار يستشفى فيه بالغسل. والحم: ما اصطهرت إهالته من الألية والشحم، الواحدة: حمة، قال: كأنما أصواتها في المعزاء ... صوت نشيش الحم عند القلاء 2 والحمم: المنايا، واحدتها حمة. والحمم أيضا: الفحم البارد، الواحدة حممة. والمحمة: أرض ذات حمى. وجارية حمة: أي سوداء كأنها حممة. والأحم من كل شيء: الأسود، والجميع الحم. والحمة: الاسم. والحمة: ما رسب في أسفل النحي من سواد ما احترق من السمن، قال: لا تحسبن أن يدي في غمه ... في قعر نحي أستثير حمه وقوله تعالى: وظل من يحموم 1 هو الدخان. والحمام: حمى الإبل والدواب وتقول: حم هذا لذاك أي قضي وقدر وقصد، قال الأعشى: هو اليوم حم لميعادها 2 أي قصد لميعادها، يقول: واعدتها أن لا أحط عنها حتى القى سلامة ذا فائش. وأحمني فاحتممت، قال زهير: [وكنت إذا ما جئت يوما] لحاجة ... مضت وأحمت حاجة الغد ما تخلو 3 أي حانت ولزمت. والحميم: الذي يودك وتوده. والحمام: طائر، والعرب تقول: حمامة ذكر وحمامة أنثى، والجميع حمام. والحميم: العرق. والحماء 4 الدبر لأنه محمم بالشعر، وهو من قولك: حم الفرخ إذا نبت ريشه. واليحموم: من أسماء الفرس، على يفعول، يحتمل أن يكون بناؤه من الأحم الأسود ومن الحميم العرق. والحمحم: نبات، قال عنترة: تسف حب الحمحم 5 ويروى بالخاء. واستحم الفرس: إذا عرق. والرجل يطلق المرأة فيحممها: أي يمتعها تحميما، قال: أنت الذي وهبت زيدا بعد ما ... هممت بالعجوز أن تحمما والحمحمة: صوت الفرس دون الصوت العالي.'),
(471, 'مح', 'مح', 'مح', 'المح: الثوب البالي. والمحاح: الذي يرى الناس بلا فعل من الرجال. والمح: صفرة البيض، قال 1 : كانت قريش بيضة فتفلقت ... فالمح خالصة لعبد مناف وأمح الثوب يمح: إذا خلق، ولو استعمل في أثر الدار إذا عفت كان جائزا، قال: 2 ألا يا قتل قد خلق الجديد ... وحبك ما يمح وما يبيد'),
(472, 'شقح', 'شقح', 'شقح', 'الشقح، العرب تقول: قبحا له وشقحا. وإنه لقبيح شقيح. ولا يكاد يعزل الشقح من القبح. والشقيح 3 : تلوين البسر إذا اصفر أو احمر، قيل: قد شقح. وفي الحديث: 1 لا بأس ببيع تمر النخل إذا شقحت ، ويقال: أشقحت أيضا.'),
(473, 'قسح', 'قسح', 'قسح', 'القسح: صلابة الانعاظ، إنه لقساح مقسوح. قال زائدة: القسح الفتل الشديد في الحبل. قسحته قسحا.'),
(474, 'سحق', 'سحق', 'سحق', 'السحق: دون الدق، وفي العدو دون الحضر وفوق السحج، قال العجاج: سحقا من الجد وسحجا باطلا 2 ويقال للثوب البالي: سحقه البلى ودعكه اللبس، قال: وليس عليك إلا طيلسان ... نصيبي وإلا سحق نيم 3 وقال: 4 سحق البلى جدته فانسحقا وهو يسحقه سحقا: ويقال: سحقه وسحجه إذا طرده طردا شديدا، قال: كانت لنا جارة فأزعجها ... قاذورة تسحق النوى قدما والسحق: البعد. ولغة أهل الحجاز: بعد له وسحق، يجعلونه اسما، والنصب على الدعاء عليه، أي أبعده الله وأسحقه. وأتان سحوق، وحمار سحوق، وهي طوال المسان ويجمع [على] سحق، قال: يمنيني النسيب قبيل شهر ... وقد أعيتني السحق الطوال 1 والعين تسحق الدمع سحقا، ودمع منسحق، ودموع مساحيق كما تقول: منكسر ومكاسير، قال الراعي: ظلى طرف عينيه مساحيق ذرف 2 والاسحاق: ارتفاع الضرع ولزوقه بالبطن، قال لبيد: حتى إذا يئست وأسحق 3 حالق ... لم يبله إرضاعها وفطامها ويروى: لم يبله أي لم يجربه. ومكان سحيق: أي بعيد. والسوحق: الطويل.'),
(475, 'قحز', 'قحز', 'قحز', 'القحز: الوثبان والقلق، قال 4 : إذا تنزى قاحزات القحز يعني به شدائد الدهر، ويقال: قاحزات القحز نازيات النزو.'),
(476, 'حزق', 'حزق', 'حزق', 'الحزق: شدة جذب الرباط والوتر. والرجل المتحزق: المتشدد على ما في يديه ضنكا، وكذلك الحزقة والحزق، قال امرؤ القيس: وأعجبني مشي الحزقة خالد ... كمشي أتان حلئت عن مناهل ويقال الحزق أيضا وقال في الحزق: فهي تفادى 1 من حزاز ذي حزق والحزيقة: الجماعة من حمر الوحش، قال ذو الرمة: 2 كأنه كلما ارفضت حزيقتها ... بالقاع من نهشه أكفالها كلب'),
(477, 'قزح', 'قزح', 'قزح', 'القزح: ابزار القدر. وقدر مقزحة. وقوس قزح: طريقة متقوسة تبدو في السماء 3 أيام الربيع. قال أبو الدقيش: القزح الطرائف التي فيها، الواحدة: قزحة. وقزح: اسم شيطان. والتقزيح في رأس شجرة أو نبت: إذا انشعب شعبا مثل برثن الكلب. ونهي عن الصلاة خلف شجرة مقزحة، وقول الأعشى: في محيل القد من صحب قزح 4 يعني لقبا له وليس باسم.'),
(478, 'قحط', 'قحط', 'قحط', 'القحط: احتباس المطر. قحط القوم وأقحطوا. وقحطت الأرض فهي مقحوطة. أو قحط المطر: احتبس، قال الأعشى: وهم يطعمون إن قحط القطر ... وهبت بشمأل وضريب 1 ورجل قحطي: أكول لا يبقي على شيء من الطعام من كلام أهل العراق دون أهل البادية، أي كأنه نجا من القحط. قحطان: ابن هود، ويقال: ابن أرفخشذ بن سام بن نوح.'),
(479, 'قحد', 'قحد', 'قحد', 'القحدة: 2 ما بين المأنتين من شحم السنام. ناقة مقحاد: ضخمة القحدة، قال: المطعم القوم الخفاف الأزواد ... من كل كوماء شطوط مقحاد 3'),
(480, 'حقد', 'حقد', 'حقد', 'الحقد: الاسم، والحقد: الفعل، حقد يحقد حقدا، وهو إمساك العداوة في القلب والتربص بفرصتها.'),
(481, 'قدح', 'قدح', 'قدح', 'القداح: متخذ الأقداح، وصنعته القداحة. والقداح: أراد رخصة من الفسفسة، والواحدة قداحة. وأراد بالأرآد جمع رؤد وهو نعمة الشباب وغضارته وأوليته ورونقه. والمقدح: الحديدة التي يقدح بها. والقداح: الحجر الذي تورى منه النار، قال رؤبة: والمرو ذا القداح مضبوح الفلق 1 والقدح: فعل القادح بالزند وبالقداح ليوري. والقدح: أكال يقع في الشجر وفي الأسنان. والقادحة: الدودة التي تأكل الشجرة والسن، قال الطرماح: بريء من العيب والقادحه 2 وقال جميل: رمى الله في عيني بثينة بالقذى ... وفي الغر من أنيابها بالقوادح 3 القدحة: اسم مشتق من الاقتداح بالزند. وفي الحديث: لو شاء الله لجعل للناس قدحة ظلمة كما جعل لهم قدحة نور 4 . والإنسان يقتدح الأمر إذا نظر فيه ودبر، قال عمرو بن العاص: يا قاتل الله وردانا وقدحته ... أبدى لعمرك ما في النفس وردان والقديح: ما يبقى في أسفل القدر فيعرف بجهد، قال النابغة: يظل 1 الإماء يبتدرن قديحها ... كما ابتدرت كلب مياه قراقر والمقدحة: المغرفة. والقدح: السهم قبل أن يراش وينصل، وجمعه قداح.'),
(482, 'حدق', 'حدق', 'حدق', 'حدقة العين في الظاهر هي سواد العين، وفي الباطن خرزتها، وتجمع [على] حدق وحداق أيضا، قال أبو ذؤيب: فالعين بعدهم كأن حداقها سملت ... بشوك فهي عور تدمع والحديقة: أرض ذات شجر مثمر، والجميع: الحدائق. والحديقة من الرياض: ما أحدق بها حاجز أو أرض مرتفعة، قال عنترة: فتركن كل حديقة كالدرهم 2 يعني في بياضه واستدارته. والتحديق: شدة النظر. وكل شيء استدار شيء فقد أحدق به.'),
(483, 'دحق', 'دحق', 'دحق', 'الدحق: أن تقصر يد الرجل وتناوله عن الشيء، تقول: أدحقه الله: أي باعده عن كل خير. ورجل دحيق مدحق: منحى عن الناس والخير، قال يصف العير المغلوب: والدحيق العاملا 3 يعني الذي قد أخرج عن الحمير. وتقول: [دحقت الرحم: إذا] 1 رمت بالماء ولم تقبله، قال النابغة: لم يحرموا حسن الغذاء وأمهم ... دحقت عليك بناتق مذكار يعني بامرأة بناتق مذكار. وقوله: دحقت عليك: فضلت عليك بأولاد، أي على الذي يفاخره 2 .'),
(484, 'حذق', 'حذق', 'حذق', 'الحذق والحذاقة: مهارة في كل شيء. والحذق مصدر حذق وحذق معا في عمله فهو حاذق. وحذق القرآن حذقا وحذاقا، والاسم الحذاقة. وحذقك الشيء: مدكه، تقطعه بمنجل ونحوه حتى لا يبقى منه شيء. وانحذق الشيء: انقطع، قال: يكاد منه نياط القلب ينحذق 3'),
(485, 'رقح', 'رقح', 'رقح', 'الرقاحي: التاجر. وإنه ليرقح معيشته: أي يصلحها.'),
(486, 'حقر', 'حقر', 'حقر', 'الحقر في كل المعاني: الذلة. حقر يحقر حقرا وحقرية. وتحقير الكلمة: تصغيرها.'),
(487, 'قحر', 'قحر', 'قحر', 'القحر: المسن وفيه بقية وجلد.'),
(488, 'قرح', 'قرح', 'قرح', 'القرح: في عض السلاح ونحوه مما يجرح من الجسد. إنه لقرح قريح، وبه قرحة دامية. وقرح قلبه من الحزن. والقرح: جرب يأخذ الفصلان لا تكاد تنجو منه، يقال: فصيل مقروح. والناقة تقرح قروحا: إذا لم يظنوها حاملا ولم تبشره بذنبها فيستبين الحمل في بطنها. واقترحت الجمل: ركبته قبل أن يركب. واقترحت الشيء: ابتدعته. ويقال للصبح أقرح لأنه بياض في سواد، قال ذو الرمة: وسوج إذا الليل الخداري شقه ... عن الركب معروف السماوة أقرح 1 يعني الصبح. والقرحة: الغرة في وسط الجبهة، والنعت أقرح وقرحاء. وروضة قرحاء: في وسطها نور أبيض، قال ذو الرمة: حواء قرحاء أشراطية وكفت ... فيها الذهاب وحفتها البراعيم 2 وقرح الفرس قروحا، وقرح نابه فهو قارح، والأنثى قارح أيضا. والقارح: السن التي بها صار قارحا. ويقال للرجل والمرأة: قرحان إذا لم يصبهما الجدري ونحوه، والجميع قرحانون. والقرحان: ضرب من الكمأة بيض صغار ذات رءوس، كرءوس الفطر، الواحدة بالهاء. وجمع القارح من الفرس قرح وقرح وقوارح، قال: 1 نحن سبقنا الحلبات الأربعا ... الربع والقرح في شوط معا والقراح: الماء الذي لا يخالطه ثفل من سويق وغيره. والقراح من الأرض: كل قطعة على حيالها من منابت [النخل] 2 وغير ذلك. والقرواح: الأرض المستوية، قال عبيد: فمن بعقوته كمن بنجوته 3 ... والمستكن كمن يمشي بقرواح'),
(489, 'حرق', 'حرق', 'حرق', 'حريق الناب: صريفه إذا حرق أحدهما بالآخر. والرجل يحرق نابه، قال زهير: أبى الضيم والنعمان يحرق نابه ... عليه وأفضى والسيوف معاقله أفضى: أي صار في فضاء ولم يتحرز بشيء. وأحرقني فلان: إذا برح بي وآذاني: قال: 4 أحرقني الناس بتكليفهم ... ما لقي الناس من الناس وأحرقت النار الشيء فاحترق. وحرق الثوب: ما يصيبه من دق القصار. والحرقات: سفن فيها مرامي نيران يرمي بها العدو في البحر بالبصرة، وهي أيضا بلغتهم: [مواضع] القلائين والفحامين 5 . والحروق والحراق: ما يورى به النار. والمحارقة: المباضعة على الجنب. والحرقة: حي من اليمن. والحريقاء: من الأسماء. والحارقة: عصبة بين وابلة الفخذ التي تدور في صدفة الورك والكتف، فإذا انفصلت لم تلتئم أبدا. ويقال: إنما هي عصبة بين خربة الورك ورأس الفخذ يقال عند انفصالها: حرق الرجل فهو محروق. والحرقة: ما يوجد من رمد عين أو وجع قلب أو طعم شيء محرق. والحارقة من السبع: اسم له. والحرقة: احتراق يقع في أصول الشعر فينحص. والحرقتان تيم وسعد وهما رهط الأعشى، قال الأعشى: عجبت لآل الحرقتين كأنما ... رأوني نفيا من إياد وترخم 1');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(490, 'رحق', 'رحق', 'رحق', 'الرحيق: من أسماء الخمر، قال حسان: يسقون من ورد البريص عليهم ... كأسا تصفق بالرحيق السلسل 2'),
(491, 'حقل', 'حقل', 'حقل', 'الحقل: الزرع إذا تشعب ورقه قبل أن يغلظ. وأحقلت الأرض إحقالا. والحقيلة: ماء الرطب في الأمعاء، وربما صيره الشاعر حقلا، قال: 3 إذا الفروض اضطمت الحقائلا والحقلة 1 حسافة التمر، وهو ما بقي من نفاياته. وحقيل: اسم جبل بالبادية. والحوقل: الشيخ إذا فتر عن الجماع، قال: أصبحت قد حوقلت أو دنوت ... وفي حواقيل الرجال الموت 2 والحوقلة: الغرمول اللين، وهي الدوقلة أيضا. والمحاقلة: بيع الزرع قبل بدو صلاحه. قال غيره: هو أن يدفع الأرض بالثلث والربع أو أقل أو أكثر.'),
(492, 'قحل', 'قحل', 'قحل', 'القاحل: اليابس من الجلود ونحوه. وشيخ قاحل. قحل يقحل قحولا، قال (رجل من أصحاب الجمل) : ردوا علينا شيخنا ثم بجل ... عثمان ردوه بأطراف الأسل (فأجابه رجل من أصحاب علي) : كيف نرد نعثلا وقد قحل 3 أي مات وذهب.'),
(493, 'قلح', 'قلح', 'قلح', 'القلح: صفرة الأسنان. رجل أقلح وامرأة قلحاء قلحة. ويسمى الجعل أقلح لأنه لا يرى أبدا إلا متلطخا بعذرة 4 .'),
(494, 'لقح', 'لقح', 'لقح', 'اللقاح: اسم ماء الفحل. واللقاح: مصدر لقحت الناقة تلقح لقاحا، وذلك إذا استبان لقاحها يعني حملها، فهي لاقح، قال أبو النجم: وقد أجنت علقا ملقوحا ... ضمنه الأرحام والكشوحا يعني لقحته من الفحل أي أخذته. وأولاد الملاقيح والمضامين نهي عن بيعها، كانوا يتبايعون ما في بطون الأمهات وأصلاب الآباء، فالملاقيح هن الأمهات والمضامين هم الآباء، الواحد ملقوح ومضمون. واللقحة: الناقة الحلوب، فإذا جعل نعتا قيل: ناقة لقوح، ولا يقال: ناقة لقحة. و [يقال] هذه لقحة بني فلان. واللقاح: جمع اللقحة. واللقح: جماعة اللقوح. وإذا نتجت الإبل فبعضها وضع وبعضها لم يضع فهي عشار، فإذا وضعن كلهن فهن لقاح، فإذا أرسل فيهن الفحل بعد ذلك فهن الشول. واللقاح: ما تلقح به النخلة من النخلة الفحالة. ألقحوا نخلهم القاحا ولقحوها تلقيحا في المبالغة. واستلقحت النخلة أنى لها أن تلقح. وحي لقاح 1 : لم يملكوا قط. والواقح من الرياح: التي تحمل الندى ثم تمجه في السحاب وفي كل شيء، فإذا اجتمع في السحاب صار مطرا. والملقح كاللقاح وهما مصدران، قال: يشهد منا ملقحا ومنتحا 2 وحرب لاقح تشبيها لها بالأنثى الحامل، قال: 3 إذا شمرت بالناس شهباء لاقح ... عوان شديد همزها وأظلت أي دنت، وهمزها: عضها ومكروهها.'),
(495, 'لحق', 'لحق', 'لحق', 'اللحق: كل شيء لحق شيئا أو ألحقته به، من النبات ومن حمل النخل، وذلك أن يرطب ويتمر 1 ثم يخرج في بعضه 2 شيء أخضر قل ما يرطب حتى يدركه الشتاء، ويكون نحو ذلك في الكرم يسمى لحقا. واللحق من الناس: قوم يلحقون بقوم بعد مضيهم، قال: ولحق يلحق من أعرابها 3 واللحق: الدعي الموصل بغير أبيه. وناقة ملحاق: لا تكاد الإبل تفوتها 4 في السير، قال رؤبة: فهي ضروح الركض ملحاق اللحق 5 ولاحق: اسم فرس 6 . وقوله: إن عذابك بالكفار ملحق بالكسر. ويقال: إنه من القرآن لم يجدوا عليها إلا شاهدا واحدا فوضعت في القنوت. وهذه لغة موافقة لقوله تعالى: سبحان الذي أسرى بعبده 7'),
(496, 'حلق', 'حلق', 'حلق', 'الحلق: مساغ الطعام والشراب. ومخرج النفس من الحلقوم. وموضع المذبح من الحلق أيضا، ويجمع على حلوق. وحلق فلان فلانا: ضربه فأصاب حلقه. والحلق: نبات لورقه حموضة يخلط بالوسمة للخضاب، الواحدة بالهاء. والحلقة من القوم وتجمع على حلق. ومنهم من يثقل فيقول حلقة لا يبالي. والحلق: الخاتم من فضة بلا فص، قال المخبل في رجل أعطاه النعمان خاتمه: وناول منا الحلق أبيض ماجدا 1 ... رديف ملوك ما تغب نوافله أي لا يبطىء ولا يجيء غبا. والحالق: الجبل المنيف المشرف، قال: فخر من وجأته ميتا ... كأنما دهده من حالق والحالق من الكرم والشري ونحوهما ما التوى منه وتعلق بالقضبان، لم يعرفوه. والمحالق: من تعريش الكرم. وحلق الضرع يحلق حلوقا فهو حالق: [يريد: ارتفاعه إلى البطن وانضمامه] . وفي قول آخر: كثرة لبنه. وتحلق القمر: صارت حوله دوارة 3 . والمحلق: موضع حلق الرأس بمنى، قال: كلا ورب البيت والمحلق 4 . وحلق الطائر تحليقا: إذا ارتفع. والحالق: المشئوم يحلق أهله ويقشرهم. وفي شتم المرأة: حلقى عقرى، يريد مشئومة مؤذية. والمحلق: اسم رجل ذكره الأعشى: وبات على النار الندى والمحلق 5'),
(497, 'حقن', 'حقن', 'حقن', 'الحقين: اللبن المحقون في محقن. وفي مثل: أبى الحقين العذرة. وأصله أن أعرابيا أتى حيا فسألهم اللبن، فقيل له: ما عندنا لبن، فالتفت إلى سقاء فيه لبن فقال: يأبى الحقين العذرة، أي يأبى الحقين أن أقبل عذركم. وحقنته: جمعته في سقاء ونحوه. وحقنت دمه: إذا انقذته من قتل أحل به. واحتقن الدم في جوفه: إذا اجتمع من طعنة جائفة. والحقنة: اسم دواء يحقن به المريض المحتقن. وبعير محقان يحقن البول، فإذا بال أكثر. والحاقنتان: نقرتا الترقوتين، والجميع: الحواقن . نقح: النقح: تشذيبك عن العصا أبنها. وكل شيء نحيته عن شيء فقد نقحته من أذى. والمنقح للكلام: الذي يفتشه ويحسن النظر فيه، [وقد] نقحت الكلام.'),
(498, 'قنح', 'قنح', 'قنح', 'القنح: اتخاذك قناحة تشد بها عضادة الباب ونحوه، تسميه الفرس قانه. قال غير الخليل: لا أعرف القنح إلا في الشرب، وهو شرب في أفاويق، ويروى في الحديث. وأشرب فأتقنح 1 وأتقمح، يرويان جميعا.'),
(499, 'حنق', 'حنق', 'حنق', 'الحنق: شدة الاغتياظ، حنق حنقا فهو حنق. والاحناق: لزوق البطن بالصلب، قال: 1 فأحنق صلبها وسنامها'),
(500, 'حقف', 'حقف', 'حقف', 'الحقف: الرمل ويجمع [على] أحقاف وحقوف. واحقوقف. واحقوقف الرمل، واحقوقف ظهر البعير: أي طال واعوج، قال العجاج: سماوة الهلال حتى احقوقفا 2 والأحقاف في القرآن يقال: جبل محيط بالدنيا من زبرجدة خضراء يلتهب يوم القيامة فيحشر الناس من كل أفق.'),
(501, 'قحف', 'قحف', 'قحف', 'القحف: العظم فوق الدماغ من الجمجمة، والجميع: القحفة والأقحاف. والقحف: قطعه وكسره فهو مقحوف أي مقطوع القحف، قال: يدعن هام الجمجم المقحوف ... صم الصدى كالحنظل المنقوف 3 والقحف: شدة الشرب، وقيل لامرىء القيس: قتل أبوك، وهو على الشراب، فقال: اليوم قحاف وغدا نقاف، ومثله اليوم خمر وغدا أمر. وقحف الإناء: شرب ما فيه. ومطر قاحف مثل قاعف: إذا جاء مفاجأة فأقحف كل شيء. ويقال: سيل قحاف وجحاف وقعاف [بمعنى واحد] 1 .'),
(502, 'فقح', 'فقح', 'فقح', 'فقح الجرو: أي أبصر وفتح عينيه. والفقاح: من العطر، وقد يجعل في الدواء فيقال: فقاح الاذخر، الواحدة بالهاء وهو من الحشيش. والفقحة: الراحة بلغة اليمن. والفقحة: معروفة وهي الدبر بجمعها. والتفقح: التفتح بالكلام.'),
(503, 'حبق', 'حبق', 'حبق', 'الحبق: دواء من أدوية الصيدلاني. والحبق: ضراط المعز، حبقت تحبق حبقا.'),
(504, 'حقب', 'حقب', 'حقب', 'الحقب: حبل يشد به الرحل إلى بطن البعير كي لا يجتذبه التصدير: وحقب البعير حقبا فهو حقب أي تعسر عليه البول. والأحقب: حمار الوحش لبياض حقويه، ويقال: بل سمي لدقة حقويه، والأنثى حقباء، قال رؤبة: كأنها حقباء بلقاء الزلق 2 الزلق: العجز وقارة حقباء: دقيقة مستطيلة، قال: 1 ترى القارة الحقباء منها كأنها ... كميت يباري رعلة الخيل فارد. ويقال: لا يقال ذلك حتى يلتوي السراب بحقويها. والحقاب: شيء تتخذه المرأة تعلق به معاليق الحلي تشده على وسطها، ويجمع [على] حقب. واحتقب واستحقب: أي شد الحقيبة من خلفه، وكذلك ما حمل من شيء من خلفه، قال النابغة: حلق الماذي خلفهم ... شم العرانين ضرابون للهام 2 وقال: 3 فاليوم فاشرب غير مستحقب ... إثما من الله ولا واغل والمحقب كالمردف. والحقبة: زمان من الدهر لا وقت له. والحقب: ثمانون سنة والجميع: أحقاب'),
(505, 'قحب', 'قحب', 'قحب', 'القحاب: سعال الشيخ والكلب. قحب يقحب قحابا وقحبا. وأخذه سعال قاحب. والقحبة: 4 المرأة بلغة اليمن.'),
(506, 'قبح', 'قبح', 'قبح', 'القبح والقباحة: نقيض الحسن، عام في كل شيء. وقبحه الله: نحاه عن كل خير وقوله تعالى: هم من المقبوحين 5 أي المنحين عن كل خير. قال زائدة: المقبوح الممقوت. والقبيح: طرف عظم المرفق ويجمع: قبائح، قال: 1 حيث تحك الإبرة القبيحا 2'),
(507, 'قحم', 'قحم', 'قحم', 'قحم الرجل يقحم قحوما في الشعر، ويقال في الكلام العام: اقتحم وهو رميه بنفسه في نهر أو وهدة أو في أمر من غير روية 3 . ويقال: قحم قحوما: إذا كبر. قال زائدة: قحم وأقحم تجاوز، واقتحم هو. والقحم: الشيخ الخرف، والقحمة: الشيخة، قال الراجز: إني وإن قالوا كبير قحم ... عندي حداء 4 زجل ونهم والقحمة: الأمر العظيم. لا يركبها كل أحد، والجمع: قحم. وقحم الطريق: ما صعب، قال: يركبن من فلج طريقا ذا قحم 5 وبعير مقحام: يقتحم الشول من غير إرسال فيها. والمقحم: البعير الذي يربع ويثنى في سنة واحدة فتقتحم سن. وبعير مقحم: يقحم في مفازة من غير مسيم ولا سائق، قال ذو الرمة: أو مقحم أضعف الإبطان حادجه ... بالأمس فاستأخر العدلان والقتب 1 شبه به جناحي الظليم. وأعرابي مقحم: أي نشأ في المفازة لم يخرج منها. والتقحيم: رمي الفرس فارسه على وجهه. وفي الحديث: إن للخصومة قحما 2 أي إنها تتقحم على المهالك وقحمة الأعراب: سنة جدبة تتقحم عليهم، أو تقحم الأعراب بلاد الريف.'),
(508, 'قمح', 'قمح', 'قمح', 'القمح: البر. وأقمح البر: جرى الدقيق في السنبل. والاقتماح: ما تقتمحه من راحتك في فيك. والاسم: القمحة كاللقمة والأكلة. والقميحة: اسم الحوارش. والقمحان: ورس، ويقال: زعفران. وقال زائدة: هو الزبد وقال النابغة: إذا فضت خواتمه علاه ... يبيس القمحان من المدام 3 والقامح والمقامح من الإبل: الذي اشتد عطشه ففتر فتورا شديدا. وبعير مقمح، وقمح يقمح قموحا وأقمحه العطش والذليل مقمح: لا يكاد يرفع بصره. وقول الله- عز وجل- فهم مقمحون 4 أي خاشعون لا يرفعون أبصارهم، وقال الشاعر: ونحن على جوانبه عكوف 5 ... نغض الطرف كالإبل القماح وفي المثل: الظمأ القامح خير من الري الفاضح يضرب هذا لما كان أوله منفعة وآخره ندامة. ويقال: القامح الذي يرد الحوض فلا يشرب. ويقال: رويت حتى انقمحت: أي حتى تركت الشراب. وابل قماح.'),
(509, 'محق', 'محق', 'محق', 'محقه الله فانمحق وامتحق: أي ذهب خيره وبركته ونقص، قال الشاعر: يزداد حتى إذا ما تم أعقبه ... كر الجديدين نقصا ثم ينمحق 1 والمحاق: آخر الشهر إذا انمحق الهلال فلم ير، قال: بلال يا ابن الأنجم الأطلاق ... لسن بنحسات ولا محاق 2 ويروي: ولا أمحاق.'),
(510, 'حمق', 'حمق', 'حمق', 'استحمق الرجل: فعل فعل الحمقى. وامرأة محمق: تلد الحمقى. وفرس محمق: لا يسبق نتاجها. وحمق حماقة وحمقا: صار أحمق. والحماق: الجدري 3 . يقال منه رجل محموق. وانحمق في معنى استحمق، قال: والشيخ يوما إذا ما خيف ينحمق 4'),
(511, 'حشك', 'حشك', 'حشك', 'الحشك: تركك الناقة لا تحلبها حتى يجتمع لبنها، وهي محشوكة. والحشك: اسم للدرة المجتمعة، قال: غدت وهي محشوكة حافل ... فراح الذئار عليها صحيحا 1'),
(512, 'كشح', 'كشح', 'كشح', 'الكشح: من لدن السرة إلى المتن ما بين الخاصرة إلى الضلع الخلف، وهو موضع موقع السيف إلى المتقلد. وطوى فلان كشحه على أمر: إذا استمر عليه وكذلك الذاهب القاطع. والكاشح: العدو، قال: فذرني ولكن ما ترى رأي كاشح ... يرى بيننا من جهله دق منشم ويقال: طوى كشحه عني: إذا قطعك وعاداك. وكاشحني فلان بالعداوة.'),
(513, 'شحك', 'شحك', 'شحك', 'الشحك: من الشحاك، تقول: شحكت الجدي: وهو عود يعرض في فمه يمنعه من الرضاع.'),
(514, 'ضحك', 'ضحك', 'ضحك', 'ضحك يضحك ضحكا وضحكا، ولو قال: ضحكا لكان قياسا لأن مصدر فعل فعل. والضحكة: ما يضحك منه. والضحكة: الكثير الضحك يعاب به. والضحاك في النعت أحسن من الضحكة. والضاحكة: كل سن من مقدم الأضراس ما يبدو عند الضحك. والضحاك بن عدنان: الذي يقال ملك الأرض، ويقال له: المذهب، كانت أمه جنية فلحق بالجن وتلبد بالفراء 1 . تقول العجم إنه عمل بالسحر وأظهر الفساد أخذ فشد في جبل دنباوند. وقوله فضحكت فبشرناها 2 يعني طمثت. والضحك: الثلج، ويقال: جوف الطلع، وهي من لغة بني الحارث، يقال: ضحكت النخلة إذا انشق كافورها. وقال آخرون: هو الشهد، ويقال: الزبد، ويقال: العسل. وهو بهذين أشبه في قوله: 3 فجاء بمزج لم ير الناس مثله ... هو الضحك إلا أنه عمل النخل والضحوك من الطرق: ما وضح فاستبان، قال: على ضحوك النقب مجرهد 4'),
(515, 'حسك', 'حسك', 'حسك', 'الحسك: نبات له ثمرة خشنة تتعلق بأصواف الغنم، الواحدة حسكة. والحسك: من أدوات الحرب ربما يتخذ من حديد فيلقى حول العسكر، وربما اتخذ من خشب فنصب حول العسكر. وحسك الصدر: حقد العداوة، تقول: إنه والحسك الصدر علي. والحسكيك 1 : القنفذ الضخم.'),
(516, 'كسح', 'كسح', 'كسح', 'الكساحة: تراب مجموع. وكسح بالمكسحة كسحا أي كنسا. والمكاسحة: المشارة الشديدة. والكسح: شلل 2 في إحدى الرجلين إذا مشى جرها جرا. ورجل كسحان. وكسح يكسح كسحا فهو أكسح، قال: 3 . كل ما يقطع من داء الكسح قال زائدة: أعرف الكسح العجز، يقال: فلان كسح: أي عاجز ضعيف. والأكسح: الأعرج.'),
(517, 'كدح', 'كدح', 'كدح', 'الكدح: عمل الإنسان من الخير والشر. ويكدح لنفسه: أي يسعى. وقوله تعالى: إنك كادح إلى ربك كدحا 1 أي ناصب، وكدحا أي نصبا. قال زائدة: إلى ربك في معنى نحو ربك. والكدح: دون الكدم بالأسنان. والكدح بالحجر والحافر.'),
(518, 'كتح', 'كتح', 'كتح', 'الكتح: دون الكدح من الحصى والشيء يصيب الجلد فيؤثر فيه، قال: 2 يلتحن وجها بالحصى ملتوحا ... ومرة بحافر مكتوحا أي تضربه الريح بالحصى، قال: فأهون بذئب يكتح الريح باسته 3 أي تضربه الريح بالحصى. ومن يروي: تكثح، أي: تكشف.'),
(519, 'حتك', 'حتك', 'حتك', 'الحتك والحتكان: شبه الرتكان في المشي إلا أن الرتك للإبل خاصة، والحتك من المشي للإنسان وغيره. والحوتك: القصير 4'),
(520, 'كثح', 'كثح', 'كثح', 'الكثح: كشف الريح الشيء عن الشيء. ويكثح بالتراب وبالحصى: يضرب به.'),
(521, 'حرك', 'حرك', 'حرك', 'حرك الشيء يحرك حركا وحركة وكذلك يتحرك. تقول: حركت بالسيف محركه حركا أي ضربته. والمحرك: منتهى العنق وعند مفصل الرأس. والحارك: أعلى الكاهل، قال: 2 مغبط الحارك محبوك 3 الكفل والحراكيك: الحراقف، واحدها: حرككة.'),
(522, 'حكر', 'حكر', 'حكر', 'الحكر: الظلم في النقص 4 وسوء المعاشرة. وفلان يحكر فلانا: أدخل عليه مشقة ومضرة في معاشرته ومعايشته. وفلان يحكر فلانا حكرا. والنعت حكر، قال الشاعر: ناعمتها أم صدق برة ... وأب يكرمها غير حكر 1 والحكر: ما احتكرت من طعام ونحوه مما يؤكل، ومعناه: الجمع، والفعل: احتكر وصاحبه محتكر ينتظر باحتباسه، الغلاء.'),
(523, 'ركح', 'ركح', 'ركح', 'الركح: ركن منيف من الجبل صعب، قال: كأن فاه واللجام شاحي ... شرخا 2 غبيط سلس مركاح أي كأنه ركح جبل. والركح: ناحية البيت من ورائه، وربما كان فضاء لا بناء فيه.'),
(524, 'كحل', 'كحل', 'كحل', 'الكحل: ما يكتحل [به] والمكحال: الميل تكحل به العين من المكحلة، والكحل: مصدره. والأكحل الذي يعلو منابت أشفاره سواد خلقة. والأكحل: عرق الحياة في اليد وفي كل عضو منه شعبة على حدة. والكحل: شدة المحل. والكحيل: ضرب من القطران.'),
(525, 'لحك', 'لحك', 'لحك', 'اللحك: شدة لأم الشيء بالشيء، تقول: قد لوحكت فقار هذه الناقة، أي دخل بعضها في بعض. والملاحكة في البنيان ونحوه، قال الأعشى: 3 ودأبا تلاحك مثل الفئوس ... لاحم فيه السليل 1 الفقارا'),
(526, 'حلك', 'حلك', 'حلك', 'الحلك: شدة السواد، حالك حلكوك، وحلك يحلك [حلوكا] 2 . والحلك: شدة السواد كلون الغراب، يقال: إنه لأشد سوادا من حلك الغراب.'),
(527, 'كلح', 'كلح', 'كلح', 'الكلوح: بدو الأسنان عند العبوس. وكلح كلوحا. وأكلحه كذا. قال لبيد: تكلح الأروق منهم والأيل 3'),
(528, 'حكل', 'حكل', 'حكل', 'تقول: في لسانه حكلة أي عجمة.'),
(529, 'نكح', 'نكح', 'نكح', 'نكح ينكح نكحا: وهو البضع. ويجرى نكح أيضا مجرى التزويج. وامرأة ناكح: أي ذات زوج، ويجوز في الشعر ناكحة بالهاء، قال: 4 ومثلك ناحت عليه النساء ... من بين بكر إلى ناكحه وقال: أحاطت بخطاب الأيامى وطلقت ... غداتئذ منهن من كان ناكحا 1 وكان الرجل يأتي الحي خاطبا فيقوم في ناديهم فيقول: خطب، أي جئت خاطبا، فيقال 2 له: نكح، أي أنكحناك.'),
(530, 'حنك', 'حنك', 'حنك', 'رجل محنك: لا يستقل منه شيء مما عضه الدهر. والمحتنك: الذي تم عقله وسنه، يقال: حنكته السن حنكا وحنكا. وحنكته تحنيكا: إذا نبتت أسنانه التي تسمى أسنان العقل، قال العجاج: محنتك ضخم شئون الراس ويقال: هم أهل الحنك، ومنهم من يكسر الحاء، ومنهم من يثقل فيقول: أهل الحنك والحنكة يعني أهل الشرف 3 والتجارب. والتحنيك: إن تغرز عودا في الحنك الأعلى من الدابة أو في طرف قرن حتى يدميه لحدث يحدث فيه. واستحنك الرجل: اشتد أكله بعد قلة. وحنكت الصبي بالتمر: دلكته في حنكه. والحنكان: الأعلى والأسفل، فإذا فصلوهما لم يكادوا يقولون للأعلى حنك، قال حميد: 4 [فالحنك الأعلى طوال سرطم] ... والحنك الأسفل منه أفقم] وفي الحديث: أن النبي صلى الله عليه وسلم- كان يحنك أولاد الأنصار. واحتنكت الرجل: أخذت ماله ومنه قوله تعالى: لأحتنكن ذريته إلا قليلا 1 .'),
(531, 'كفح', 'كفح', 'كفح', 'المكافحة: مصادفة الوجه بالوجه عن مفاجأة، قال عدي: 2 أعاذل من تكتب له النار يلقها ... كفاحا ومن يكتب له الخلد يسعد وكافحها: قبلها عن غفلة وجاها. والمكافحة في الحرب: المضاربة تلقاء الوجوه.'),
(532, 'كحب', 'كحب', 'كحب', 'الكحب: [البروق] 3 بلغة اليمن، والحبة منه كحبة..'),
(533, 'كبح', 'كبح', 'كبح', 'الكبح: كبحك الدابة باللجام، وهو قرعك إياها.'),
(534, 'حبك', 'حبك', 'حبك', 'حبكته بالسيف حبكا: وهو ضرب في اللحم دون العظم، ويقال: هو محبوك العجز والمتن إذا كان فيه استواء مع إرتفاع، قال الأعشى: 1 على كل محبوك السراة كأنه ... عقاب هوت من مرقب وتعلت أي: ارتفعت. وهوت انخفضت.. والحباك: رباط الحضيرة بقصبات تعرض ثم تشد كما تحبك عروش الكرم بالحبال. واحتبكت إزاري: شددته. والحبيكة: كل طريقة في الشعر وكل طريقة في الرمل تحبكه الرياح إذا جرت عليه، ويرى نحو ذلك في البيض من الحديد، قال الشاعر: والضاربون حبيك البيض إذ لحقوا ... لا ينكصون إذا ما استلحموا 2 وحموا أي اشتد قتالهم. والحبك: جماعة الحبيك، ويقال: كذلك خلقة وجه السماء. ويقال: ما طعمنا عنده حبكة ولا لبكة، ويقال: عبكة، فالعبكة والحبكة معا: الحبة من السويق، واللبكة: اللقمة من الثريد ونحوه.'),
(535, 'حكم', 'حكم', 'حكم', 'الحكمة: مرجعها إلى العدل والعلم والحلم. ويقال: أحكمته التجارب إذا كان حكيما. وأحكم فلان عني 3 كذا، أي: منعه، قال: ألما يحكم الشعراء عني 1 واستحكم الأمر: وثق. واحتكم في ماله: إذا جاز فيه حكمه. والأسم: الأحكومة والحكومة، قال الأعشى: ولمثل الذي جمعت لريب ... الدهر يأبى حكومة المقتال أي لا تنفذ حكومة من يحتكم عليك من الأعداء. والمقتال: المفتعل من القول حاجة منه إلى القافية. والتحكيم: قول الحرورية: لا حكم إلا لله 2 . وحكمنا فلانا أمرنا: أي: يحكم بيننا. وحاكمناه إلى الله: دعوناه إلى حكم الله. ويقال: نهي أن يسمى رجل حكما. وحكمة اللجام: ما أحاط بحنكيه سمي به لأنها تمنعه من الجري. وكل شيء منعته من الفساد فقد [حكمته] وحكمته وأحكمته، قال: 3 أبني حنيفة أحكموا سفهاءكم ... إني أخاف عليكم أن أغضبا وفرس محكومة: في رأسها حكمة. قال زائدة: محكمة وأنكر محكومة، قال: محكومة حكمات القد والأبقا 4 وهو القتب 5 . وسمى الأعشى القصيدة المحكمة حكيمة في قوله: وغريبة تأتي الملوك حكيمة 6 .'),
(536, 'محك', 'محك', 'محك', 'المحك: التمادي في اللجاجة عند المساومة والغضب ونحوه. وتماحك البيعان.'),
(537, 'حمك', 'حمك', 'حمك', 'الحمك: من نعت الأدلاء، [تقول] : حمك يحمك.'),
(538, 'كمح', 'كمح', 'كمح', 'الكمح: رد الفرس باللجام.'),
(539, 'شحج', 'شحج', 'شحج', 'الشحيج: صوت البغل وبعض أصوات الحمار. شحج يشحج شحيجا. وشحج الغراب شحجانا: وهو ترجيع الصوت فإذا مد [قيل] : نعب 1 . ويقال للبغال: بنات شاحج وشحاج. ويقال للحمار الوحشي 2 ، قال لبيد: فهو شحاج مدل سنق ... لاحق البطن إذا يعدو زمل 3'),
(540, 'جحش', 'جحش', 'جحش', 'الجحش: ولد الحمار، والعدد: جحشة، والجميع جحاش. والجحشة [يتخذها الراعي] كالحلقة من الصوف يلقيها في يده ليغزلها 4 . والجحاش: الدفاع [تجاحش] 5 : تدافع عن نفسك. والجحش: دون الخدش. جحش فهو مجحوش.'),
(541, 'سحج', 'سحج', 'سحج', 'سحجت الشعر سحجا: وهو تسريح لين على فروة الرأس. وسحج الشيء يسحجه: أي يقشر منه شيئا قليلا كما يصيب الحافر من قبل الحفا. والسحج أيضا: 4 جري الدواب دون الشديد. وحمار مسحج، قال النابغة: رباعية أضر بها رباع ... بذات الجزع مسحاج شنون 5 والمسحج: من التسحيج وهو الكدم.'),
(542, 'سجح', 'سجح', 'سجح', 'الإسجاح: حسن العفو كقولهم: ملكت فأسجح. ويقال: مشى مشيا سجيحا وسجحا، قال الشاعر: 1 ذروا التخاجي وامشوا مشية سجحا ... إن الرجال ذوو عصب وتذكير ويقال: سجحت [الحمامة] 2 وسجعت. وربما قالوا: مزجح في مسجح كالأسد والأزد. والسجح: لين الخد، والنعت: أسجح وسجحاء، قال ذو الرمة: وخد كمرآة الغريبة أسجح 3'),
(543, 'حجز', 'حجز', 'حجز', 'الحجز: أن تحجز بين مقاتلين. والحجاز والحاجز اسم، وقوله تعالى: وجعل بين البحرين حاجزا 4 أي حجازا فذلك الحجاز أمر الله بين ماء ملح وعذب لا يختلطان. وسمي الحجاز لأنه يفصل بين الغور والشام وبين البادية. والحجاز: حبل يلقى للبعير من قبل رجليه، ثم يناخ عليه، يشد به رسغا رجليه إلى حقويه وعجزه. حجزته فهو محجوز، قال ذو الرمة: حتى إذا كان محجوزا بنافذة ... وقائظا وكلا روقيه مختضب 1 وتقول: كان بينهم رميا ثم حجزت بينهم حجيزى. أي رمي، ثم صاروا إلى المحاجزة. والحجزة: حيث يثنى طرف الأزار في لوث الازار، قال النابغة: رقاق النعال طيب حجزاتهم ... يحيون بالريحان يوم السباسب والرجل يحتجز بإزاره على وسطه. وحجز الرجل: أصله ومنبته. وحجز الرجل أيضا: فصل ما بين فخذه والفخذ الأخرى من عشيرته، قال: 2 فامدح كريم المنتمى 3 والحجز'),
(544, 'جزح', 'جزح', 'جزح', 'جزح لنا من ماله [جزحا 4 أو جزحة: أي قطع قطعة. وجزح الشجر: حت ورقه.'),
(545, 'جطح', 'جطح', 'جطح', 'جطح: يقال للعنز عند الحليب: جطح، أي: قري فتقر. قال زائدة: جطح السخلة إذا زجرت ولا يقال للعنز.'),
(546, 'جحد', 'جحد', 'جحد', 'الجحود: ضد الاقرار كالانكار والمعرفة. والجحد: من الضيق والشح. ورجل جحد: قليل الخير، قال: لا جحدا ابتغينه ولا جدا ... يعدن من هازلنه غدا غدا 1'),
(547, 'حدج', 'حدج', 'حدج', 'الحدج: حمل البطيخ والحنظل ما دام صغارا خضرا. ويقال ذلك لحسك القطب ما دام رطبا، الواحدة بالهاء. والحدج لغة فيه. والتحديج: شدة النظر بعد روعة وفزعة، حدجت ببصرى، قال العجاج: 2 إذا آثبجرا 3 من سواد حدجا وحدجت ببصري: رميت به. والحدج: مركب غير رحل ولا هودج لنساء العرب، حدجت الناقة أحدجها حدجا، والجميع: أحداج وحدائج وحدوج، قال: أصاح ترى حدائج باكرات ... عليها العبقرية والنجود 4 وأحدجتها: إذا شددت الحدج عليها.'),
(548, 'جدح', 'جدح', 'جدح', 'الجدح: خوض السويق واللبن ونحوه بالمجدح ليختلط. والمجدح: خشبة في رأسها خشبتان معترضتان. والمجداح: تردد ريق الماء في السحاب 1 ، يقال: أرسلت السماء مجاديح الغيث.'),
(549, 'جحظ', 'جحظ', 'جحظ', 'الجحاظان: حدقتا العين إذا كانتا خارجتين. وعين جاحظة جحظت جحوظا.'),
(550, 'ذحج', 'ذحج', 'ذحج', 'ذحجت المرأة بولدها، إذا رمت به عند الولادة. ومذحج: اسم رجل.'),
(551, 'حجر', 'حجر', 'حجر', 'الأحجار: جمع الحجر. والحجارة: جمع الحجر أيضا على غير قياس، ولكن يجوز الاستحسان في العربية [كما أنه يجوز في الفقه، وترك القياس له] 1 كما قال: 2 . لا ناقصي حسب ولا ... أيد إذا مدت قصاره ومثله المهارة والبكارة والواحدة مهر وبكر. والحجر: حطيم مكة، وهو المدار بالبيت كأنه حجرة. مما يلي المثعب. وحجر: موضع كان لثمود ينزلونه. [وقصبة اليمامة] : حجر، قال الأعشى: وإن امرأ قد زرته قبل هذه ... بحجر لخير منك نفسا ووالدا 3 والحجر والحجر لغتان: وهو الحرام، وكان الرجل يلقى غيره في الأشهر الحرم فيقول: حجرا محجورا أي حرام محرم عليك في هذا الشهر فلا يبدؤه بشر، فيقول المشركون يوم القيامة للملائكة: حجرا محجورا، ويظنون أن ذلك ينفعهم كفعلهم في الدنيا، قال: حتى دعونا بأرحام لهم سلفت ... وقال قائلهم إني بحاجور 4 وهو فاعول من المنع، يعني بمعاذ. يقول: إني متمسك بما يعيذني منك ويحجبك 5 عني، وعلى قياسه العاثور وهو المتلف. والمحجر: المحرم. والمحجر: حيث يقع عليه النقاب من الوجه، قال النابغة: وتخالها في البيت إذ فاجأتها ... وكأن محجرها سراج الموقد 6 وما بدا من النقاب فهو محجر. وأحجار الخيل 7 : ما اتخذ منها للنسل 1 لا يكاد يفرد. ويقال: بل يقال هذا حجر من أحجار خيلي، يعني الفرس الواحد، وهذا اسم خاص للإناث دون الذكور، جعلها كالمحرم بيعها وركوبها. والحجر: أن تحجر على إنسان ماله فتمنعه أن يفسده. والحجر: قد يكون مصدرا للحجرة التي يحتجرها الرجل، وحجارها: حائطها المحيط بها. والحاجر من مسيل الماء ومنابت العشب: ما استدار به سند أو نهر مرتفع، وجمعه حجران، وقول العجاج: وجارة البيت لها حجري 2 أي حرمة. والحجرة: ناحية كل موضع قريبا منه. وفي المثل: يأكل خضرة ويربض حجرة 3 أي يأكل من الروضة ويربض ناحية. وحجرتا العسكر: جانباه من الميمنة والميسرة، قال: إذا اجتمعوا فضضنا حجرتيهم ... ونجمعهم إذا كانوا بداد 4 وقال النابغة: أسائل عن سعدى وقد مر بعدنا ... على حجرات الدار سبع كوامل وحجر المرأة وحجرها، لغتان،: للحضنين.'),
(552, 'جحر', 'جحر', 'جحر', 'جمع الجحر: جحرة. أجحرته فانجحر: أي أدخلته في جحر، ويجوز في الشعر: جحرته في معنى أجحرته بغير الألف. واجتحر لنفسه جحرا. وجحر عنا الربيع: تأخر، وقول امرىء القيس: جواحرها في صرة لم تزيل 1 أي أواخرها. وقالوا: الجحرة السنة الشديدة، وإنما سميت بذلك لأنها جحرت الناس، قال زهير: ونال كرام الناس في الجحرة الأكل 2'),
(553, 'حرج', 'حرج', 'حرج', 'الحرج: المأثم. والحارج: الآثم، قال: يا ليتني قد زرت غير حارج 3 ورجل حرج وحرج كما تقول: دنف ودنف: في معنى الضيق الصدر، قال الراجز: لا حرج الصدر، ولا عنيف 4 ويقرأ يجعل صدره ضيقا حرجا 5 وحرجا. وقد حرج صدره: أي ضاق ولا ينشرح لخير ورجل متحرج: كاف عن الإثم وتقول: أحرجني إلى كذا: أي ألجأني فخرجت إليه أي انضممت إليه، قال الشاعر: 6 تزداد للعين إبهاجا إذا سفرت ... وتحرج العين فيها حين تنتقب والحرجة من الشجر: الملتف قدر رمية حجر، وجمعها حراج، قال: ظل وظلت كالحراج قبلا ... وظل راعيها بأخرى مبتلى 7 والحرج: قلادة كلب ويجمع [على] أحرجة ثم أحراج، قال الأعشى: بنواشط غضف يقلدها ... الأحراج فوق متونها لمع 1 والحرج: ودعة، وكلاب محرجة: أي مقلدة، قال الراجز: 2 والشد يدني لاحقا والهبلعا ... وصاحب الحرج ويدني ميلعا 3 والحرجوج: الناقة الوقادة القلب، قال: قطعت بحرجوج إذا الليل أظلما 4 والحرج من الإبل: التي لا تركب ولا يضربها الفحل معدة للسمن، كقوله: 5 حرج في مرفقيها كالفتل 6 ويقال: قد حرج الغبار غير الساطع المنضم إلى حائط أو سند، قال: وغارة يحرج القتام لها ... يهلك فيها المناجد البطل 7'),
(554, 'جرح', 'جرح', 'جرح', 'جرحته أجرحه جرحا، واسمه الجرح. والجراحة: الواحدة من ضربة أو طعنة. وجوارح الإنسان: عوامل جسده من يديه ورجليه، الواحدة: جارحة. واجترح عملا: أي اكتسب، قال: وكل فتى بما عملت يداه ... وما اجترحت عوامله رهين 1 والجوارح: ذوات الصيد من السباع والطير، الواحدة جارحة، قال الله تعالى: وما علمتم من الجوارح مكلبين 2 .'),
(555, 'رجح', 'رجح', 'رجح', 'رجحت بيدي شيئا: وزنته ونظرت ما ثقله. وأرجحت الميزان: أثقلته حتى مال. ورجح الشيء رجحانا ورجوحا. وأرجحت الرجل: أعطيته راجحا. وحلم راجح: يرجح بصاحبه. وقوم مراجيح في الحلم، الواحد مرجاح ومرجح، قال الأعشى: من شباب تراهم غير ميل ... وكهولا مراجحا أحلاما 3 وأراجيح البعير: اهتزازه في رتكانه إذا مشى، قال: على ربذ سهل الأراجيح مرجم 4 والفعل من الأرجوحة: الارتجاح. والترجح: التذبذب بين شيئين.'),
(556, 'حجل', 'حجل', 'حجل', 'الحجل: القبج، الواحدة حجلة. وحجلة العروس تجمع على حجال وحجل، قال: يا رب بيضاء ألوف للحجل والحجل، مجزوم، مشي المقيد. وحجلا القيد: حلقتاه. قال عدي بن زيد: أعاذل قد لاقيت ما يزع الفتى ... وطابقت في الحجلين مشي المقيد 1 وفلان يحجل: إذا رفع رجلا ويثب في مشيه على رجل، يقال: حجل. ونزوان الغراب: حجله. والحجل: الخلخال، ويقال: الحجل أيضا، قال النابغة: على أن حجليها وإن قلت أوسعا ... صموتان من ملء وقلة منطق 2 والتحجيل: بياض في قوائم الفرس، فرس محجل، وفرس باد حجوله، قال: 3 تعالوا فإن العلم عند ذوي النهى ... من الناس كالبلقاء باد حجولها والحوجلة: من صغار القوارير ما وسع رأسها، قال العجاج: كأن عينيه من الغئور ... قلتان أو حوجلتا قارور 4 وحجل الإبل: أولادها وحشوها. وحجلت عينه: غارت، قال: 5 فتصبح حاجلة عينه ... بحنو استه وصلاه عيوب'),
(557, 'جحل', 'جحل', 'جحل', 'الجحل: ضرب من اليعسوب، والجمع جحلان. غير الخليل: ضب جحول إذا كان ضخما كبيرا.'),
(558, 'لحج', 'لحج', 'لحج', 'اللحج: كسر العين مثل اللخص إلا أنه من تحت ومن فوق. واللحج: الغمص نفسه. واللحج، مجزوم، الميلولة 1 التحجوا إلى كذا. وألحجهم فيه كذا: أمالهم فيه، قال: ويلتحجوا بكرا لدى كل مذنب 2 قال العجاج: أو تلحج الألسن فينا ملحجا 3 أي تقول فينا فتميل إلى القبيح عن الحسن.'),
(559, 'جلح', 'جلح', 'جلح', 'الجلح: ذهاب شعر مقدم الرأس، والنعت أجلح. والتجليح: التعميم في الأمر. وناقة مجلاح: وهي المجلحة على السنة الشديدة في بقاء لبنها، والجميع: المجاليح، قال: شد الفناء بمصباح مجالحه ... شيحانة خلقت خلق المصاعيب 4 والجالحة والجوالح: ما تطاير من رءوس النبات كالقطن من الريح ونحوه من نسج العنكبوت. وكالثلج إذا تهافت. والجلحاء: البقرة الذاهب قرناها بأخرة 1 . جلاح: اسم أبي أحيحة، وكان سيد بني النجار وهو جد عبد المطلب، كانت أمه سلمى بنت عمرو بن أحيحة. والمجلح: الكثير الأكل، ومنه قول ابن مقبل: إذا اغبر العضاه المجلح 2 وهو الذي أكل فلم يترك منه شيء.'),
(560, 'حلج', 'حلج', 'حلج', 'والحلج: حلج القطن بالمحلاج. والحلج في السير كقولك: بيننا وبينهم حلجة صالحة وحلجة بعيدة 3 ، قال أبو النجم: منه بعجز كصفاة الحيجل 4 وفي الأصل: الحيلج.'),
(561, 'حجن', 'حجن', 'حجن', 'المحجنة والمحجن 5 : عصا في طرفها عقافة. واحتجن الرجل: إذا اختص بشيء 1 لنفسه دون أصحابه. والاحتجان أيضا بالمحجن. حجنته عنه: أي صددته، قال: ولا بد للمشعوف من تبع الهوى ... إذا لم يزعه من هوى النفس حاجن 2 وغزوة حجون: وهي التي تظهر غيرها ثم تخالف إلى غير ذلك الموضع، [ويقصد إليها] . يقال: غزاهم غزوة حجونا، ويقال: هي البعيدة، قال الأعشى: فتلك إذا الحجون ثنى عليها ... عطاف الهم واختلط المريد 3 والحجون: موضع بمكة قال: 4 فما أنت من أهل الحجون ولا الصفا والحجنة: موضع أصابه اعوجاج. والحجن: اعوجاج الشيء الأحجن. والصقر وما يشبهه من الطير أحجن المنقار. ومن الأنوف أحجن وهو ما أقبلت روثته نحو الفم فاستأخرت ناشزتاه قبحا. وتكون الحجنة من الشعر: الذي جعودته في أطرافه.'),
(562, 'نجح', 'نجح', 'نجح', 'النجح والنجاح: من الظفر [بالحوائج] . نجحت حاجتك وأنجحتها لك. وسرت سيرا نجحا وناجحا ونجيحا: أي وشيكا، قال: يشلهن قربا نجيحا 5 يصف قربا على طريق المصدر. ورأي نجيح: صواب. وتناجحت أحلامه: إذ تتابعت عليه رؤيا صدق. ونجح أمره: سهل ويسر.'),
(563, 'جحن', 'جحن', 'جحن', 'جيحون وجيحان: اسم نهر بالشام 1 . والجحن: السيىء الغذاء، قال الشماخ يذكر ناقة: وقد عرقت مغابنها وجادت ... بدرتها قرى جحن قتين 2 أي قليل الطعم.'),
(564, 'جنح', 'جنح', 'جنح', 'جنح الطائر جنوحا: أي كسر من جناحيه ثم أقبل كالواقع اللاجىء إلى موضع. والرجل يجنح: إذا أقبل على الشيء يعمله بيديه وقد حنى إليه صدره، قال: 3 جنوح الهالكي على يديه ... مكبا يجتلي نقب النصال وقال في جنوح الطائر: ترى الطير العتاق يطلن منه ... جنوحا'),
(565, 'حجف', 'حجف', 'حجف', 'الحجف: [ضرب من الترسة] 1 مقورة من جلود الإبل، الواحدة حجفة. والحجاف: داء يعتري [الإنسان] من كثرة الآكل أو من شيء لا يلائمه فيأخذ البطن استطلاقا. وقيل: رجل محجوف، قال: 2 . والمشتكي من مغلة المحجوف'),
(566, 'جحف', 'جحف', 'جحف', 'الجحف: شبه الجرف إلا أن الجرف للشيء الكثير والجحف للماء والكرة ونحوهما، تقول: اجتحفنا ماء البئر إلا جحفة واحدة بالكف أو بالإناء. وتجاحفنا الكرة بيننا بالصوالجة. وتجاحفنا بالقتال: تناول بعضنا [بعضا] بالعصي والسيوف، قال العجاج: وكان ما اهتض الجحاف بهرجا 3 اهتض: أي كسر، بهرجا: أي باطلا، والجحاف: مزاحمة الحرب. وسنة مجحفة: تجحف بالقوم وتجتحف أموالهم. ويقال: من آثر الدنيا أجحفت بآخرته. والجحفة: 4 ميقات للإحرام.'),
(567, 'فحج', 'فحج', 'فحج', 'الفحج: تباعد ما بين الساقين في الإنسان والدابة، والنعت: أفحج وفحجاء، ويقال 5 : لا فجح فيها ولا صكك.'),
(568, 'حجب', 'حجب', 'حجب', 'الحجب: كل شيء منع شيئا من شيء فقد حجبه حجبا. والحجابة: ولاية الحاجب. والحجاب، اسم،: ما حجبت به شيئا عن شيء، ويجمع [على] : حجب. وجمع حاجب: حجبة. وحجاب الجوف: جلدة تحجب بين الفؤاد وسائر البطن. والحاجب: عظم العين من فوق يستره بشعره ولحمه. وحاجب الفيل: اسم شاعر. ويسمى رءوس عظم الوركين وما يلي الحرقفتين حجبتين وثلاث حجبات، وجمعه حجب، قال 1 : ولم يوقع بركوب حجبه'),
(569, 'حبج', 'حبج', 'حبج', 'أحبجت لنا نار وعلم: أي بدا بغتة، قال: 2 علوت أقصاه إذا ما أحبجا'),
(570, 'بجح', 'بجح', 'بجح', 'فلان يتبجح بفلان ويتمجح به: أي يهذي به اعجابا، وكذلك إذا [تمزح] 3 به. وبجحني فبجحت: أي فرحني ففرحت. وبجحت وبجحت لغتان، قال: 4 ولكنا بقرباك نبجح 5'),
(571, 'جبح', 'جبح', 'جبح', 'جبحوا بكعابهم: رموا بها لينظر أيها يخرج فائزا. والأجبح 1 : مواضع النحل في الجبل، الواحد جبح، ويقال: هو الجبل، قال الطرماح: 2 جنى النحل أضحى واتنا بين أجبح'),
(572, 'حجم', 'حجم', 'حجم', 'الحجامة: حرفة الحاجم وهو الحجام، والحجم فعله. والمحجمة: قارورة. والمحجم: موضعة من العنق. والحجوم: اسم للقبل. والإحجام: النكوص عن الشيء هيبة. والحجام: شيء يجعل في خطم البعير كي لا يعض، بعير محجوم. والحجم: كفك إنسانا عن أمر يريده. والحجم: وجدانك شيئا تحت ثوب، تقول: مسست الحبلى فوجدت حجم الصبي في بطنها. وأحجم الثدي أي: نهد، قال: 3 قد أحجم الثدي على نحرها ... في مشرق ذي بهجة نائر'),
(573, 'جحم', 'جحم', 'جحم', 'الجحيم: النار الشديدة التأجج والالتهاب، جحمت تجحم جحوما. وجاحم الحرب: شدة القتل في معركتها، قال: حتى إذا ذات منها جاحما بردا 1 والحجمة: العين بلغة حمير. قال: 2 أيا جحمتي بكي على أم واهب وجحمتا الأسد: عيناه بكل لغة 3 . والأجحم: الشديد حمرة العين مع سعتها. والمرأة جحماء ونساء جحم وجحماوات.'),
(574, 'جمح', 'جمح', 'جمح', 'جمحت السفينة جموحا: تركت قصدها فلم يضبطها الملاحون. وجمح الفرس بصاحبه جماحا: إذا ذهب جريا غالبا. وكل شيء مضى لوجهه على أمر فقد جمح، قال: إذا عزمت على أمر جمحت به ... لا كالذي صد عنه ثم لم يثب 4 وفرس جموح: جامح، الذكر والأنثى في النعتين سواء. والجماح 5 و [الجميع] : الجماميح: شبه سنبل في رءوس الحلي والصليان. وجمحموا بكعابهم مثل جبحوا. والجماح 6 : شيء يلعب به الصبيان، يأخذون ثلاث ريشات فيربطونها ويجعلون في وسطها تمرة أو عجينا أو قطعة طين فيرمونه فذلك الجماح، قال: 1 عبدا كأن رأسه جماح وقال الحطيئة: أخو المرء يؤتي دونه ثم يتقى ... بزب اللحى جرد الخصى كالجمامح والجماحة والجماميح: رءوس الحلي والصليان ونحو ذلك مما يخرج على أطرافه شبه سنبل غير أنه كأذناب الثعالب. والجماح: موضع، قال الأعشى: فكم بين رحبى وبين الجماح ... أرضا إذا قيس أميالها 2'),
(575, 'حمج', 'حمج', 'حمج', 'وتحميج العينين: إذا غارتا، قال: لقد تقود الخيل لم تحمج أي لم تغر أعينها. والتحميج: النظر بخوف. ويقال: تحميجها هزالها. والتحميج: تغير الوجه من [الغضب] 3 . وفي الحديث: ما لي أراك محمجا.'),
(576, 'محج', 'محج', 'محج', 'المحج: مسح شيء عن شيء. والريح تمحج الأرض: أي تذهب بالتراب حتى يتناول من أدمة الأرض ترابها 4 ، قال العجاج: ومحج أرواح يبارين الصبا ويروى: وسحج أرواح 1'),
(577, 'مجح', 'مجح', 'مجح', 'التمجح: 2 الاعجاب بالشيء.'),
(578, 'شحص', 'شحص', 'شحص', 'الشحصاء: الشاة التي لا لبن لها.'),
(579, 'شحط', 'شحط', 'شحط', 'الشحط: البعد في الحالات كلها يخفف ويثقل. شحطت داره تشحط شحوطا وشحطا. والشحطة: داء يأخذ في صدور الإبل لا تكاد تنجو منه. ويقال لأثر سحج يصيب جنبا أو فخذا ونحوه: أصابته شحطة. والشوحط: ضرب من النبع. والمشحط: عويد يوضع عند القضيب من قضبان الكرم يقيه من الأرض. والتشحط: الاضطراب في الدم. والولد يتشحط في السلى: أي يضطرب فيه، قال النابغة: ويقذفن بالأولاد في كل منزل ... تشحط في أسلائها كالوصائل 1 يعني بالوصائل البرود الحمر.'),
(580, 'حشد', 'حشد', 'حشد', 'يقال: حشدوا أي خفوا في التعاون، وكذلك إذا دعوا فأسرعوا الإجابة، يستعمل في الجميع، قلما يقال: حشد، إلا أنهم يقولون للإبل: لها حالب حاشد أي لا يفتر عن حلبها والقيام بذلك. شحد 2 : الشوحد: الطويل من النوق، قال الطرماح: بفتلاء أمرار الذراعين شودح 3 وهذا مقلوب من شوحد.'),
(581, 'شحذ', 'شحذ', 'شحذ', 'الشحذ: التحديد، شحذت السكين أشحذه شحذا فهو شحيذ ومشحوذ، قال رؤبة: يشحذ لحييه بناب أعصل 1 والشحذان: الجائع'),
(582, 'حشر', 'حشر', 'حشر', 'الحشر: حشر يوم القيامة [وقوله تعالى] : ثم إلى ربهم يحشرون 2 ، قيل: هو الموت. والمحشر: المجمع الذي يحشر إليه القوم. ويقال: حشرتهم السنة: وذلك أنها تضمهم من النواحي [إلى الأمصار] ، قال: 3 وما نجا من حشرها المحشوش ... وحش ولا طمش من الطموش قال غير الخليل: الحش والمحشوش واحد. والحشرة: ما كان من صغار دواب الأرض مثل اليرابيع والقنافذ والضباب ونحوها. وهو اسم جامع لا يفرد منه الواحد إلا أن يقولوا هذا من الحشرة. قال الضرير: الجراد والأرانب والكماة من الحشرة قد يكون دواب وغير ذلك. والحشور: كل ملزز الخلق. شديدة. والحشر من الآذان ومن قذذ السهام ما لطف كأنما بري بريا، قال: 4 لها أذن حشر وذفرى أسيلة ... وخذ كمرآة الغريبة أسجح وحشرت السنان فهو محشور: أي رققته 1 وألطفته.'),
(583, 'شحر', 'شحر', 'شحر', 'الشحر: ساحل اليمن في أقصاها، قال العجاج: رحلت من أقصى بلاد الرحل ... من قلل الشحر فجنبي موكل 2 ويقال: الشحر موضع بعمان.'),
(584, 'شرح', 'شرح', 'شرح', 'الشرح: السعة، قال الله- عز وجل-: أفمن شرح الله صدره للإسلام 3 أي وسعه فاتسع لقول الخير. والشرح: البيان، اشرح: أي بين. والشرح والتشريح: قطع اللحم على العظام قطعا، والقطعة منه شرحة.'),
(585, 'رشح', 'رشح', 'رشح', 'رشح فلان رشحا: أي عرق. والرشح: اسم للعرق. والمرشحة: بطانة تحت لبد السرج لنشفها العرق. والأم ترشح ولدها ترشيحا باللبن القليل: أي تجعله في فمه شيئا بعد شيء حتى يقوى للمص. والترشيح أيضا: لحس الأم ما على طفلها من الندوة، قال: أدم 4 الظباء ترشح الأطفالا والراشح والرواشح: جبال تندى فربما اجتمع في أصولها ماء قليل وإن كثر سمي واشلا. وإن رأيته كالعرق يجري خلال الحجارة سمي راشحا.'),
(586, 'حرش', 'حرش', 'حرش', 'الحرش والتحريش: إغراؤك إنسانا بغيره. والأحرش من الدنانير ما فيه خشونة لجدته، قال: دنانير حرش كلها ضرب واحد 1 والضب أحرش: خشن الجلد كأنه محزز. واحترشت الضب وهو أن تحرشه في جحره فتهيجه فإذا خرج قريبا منك هدمت عليه بقية الجحر. وربما حارش الضب الأفعى: إذا أرادت أن تدخل عليه قاتلها. والحريش: دابة لها مخالب كمخالب الأسد ولها قرن واحد في وسط هامتها، قال: بها الحريش وضغز مائل ضبر ... يأوي إلى رشف منها وتقليص 2 والحرش: ضرب من البضع وهي مستلقية.'),
(587, 'حشن', 'حشن', 'حشن', 'حشن السقاء حشنا وأحشنته أنا: إذا أكثرت استعماله بحقن اللبن ولم يغسل ففسدت ريحه.'),
(588, 'شحن', 'شحن', 'شحن', 'شحنت السفينة: ملأتها فهي مشحونة. والشحناء: العداوة، عدو مشاحن: يشحن لك بالعداوة 1 .'),
(589, 'شنح', 'شنح', 'شنح', 'الشناحي: نعت للجمل في تمام خلقه: قال 2 : أعدوا كل يعملة ذمول ... وأعيس بازل قطم شناحي'),
(590, 'نشح', 'نشح', 'نشح', 'نشح الشارب: أي شرب حتى امتلأ، ويقال للذي يشرب قليلا قليلا، قال: 3 وقد نشحن فلا ري ولا هيم وسقاء نشاح، أي: نضاح.'),
(591, 'حنش', 'حنش', 'حنش', 'الحنش: من الحرابي وسوام أبرص ونحوه، تشبه رءوسه رءوس الحيات، وجمعه أحناش، قال الشماخ: ترى قطعا من الأحناش فيه ... جماجمهن كالخشل النزيع 4 يصفها في الوكر. قال زائدة: الخشل ما يكسر من الحلي، ونزيع ومنزوع واحد.'),
(592, 'حشف', 'حشف', 'حشف', 'الحشف: ما لم ينو 1 من التمر، فإذا يبس صلب وفسد، لا طعم له ولا حلاوة 2 . وقد أحشف ضرع الناقة: إذا يبس وتقبض. والحشيف: الثوب الخلق. والحشفة: ما فوق الختان. والحشف: الضرع اليابس، قال طرفة: فطورا به خلف الزميل وتارة ... على حشف كالشن ذاو مجدد 3'),
(593, 'فحش', 'فحش', 'فحش', 'الفحش: معروف، والفحشاء: اسم للفاحشة. وأفحش في القول والعمل وكل أمر: لم يوافق الحق فهو فاحشة. وقوله تعالى: إلا أن يأتين بفاحشة مبينة* 4 ، يعني خروجها من بيتها بغير إذن زوجها المطلقها.'),
(594, 'حفش', 'حفش', 'حفش', 'الحفش: ما كان من الآنية مما يكون أوعية في البيت للطيب ونحوه، وقوارير الطيب أحفاش. والسيل يحفش الماء حفشا من كل جانب إلى مستنقع واحد فتلك المسايل التي [تنصب 5 ] إلى المسيل الأعظم من الحوافش، الواحدة حافشة، قال: عشية رحنا وراحوا إلينا ... كما ملأ الحافشات المسيلا 1 وقال مرار بن منقذ: يرجع الشد على الشد كما ... حفش الوابل غيث مسبكر 2 وحفش: أي طرد فأسرع، يصف الفرس. والحفش: البيت الصغير أيضا. والحفش: الجري. وهم يحفشون عليك ويجلبون: أي يجتمعون. والفرس يحفش الجري: أي يعقب جريا بعد جري فلا يزداد إلا جودة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(595, 'حشب', 'حشب', 'حشب', 'الحوشب: عظم في باطن الحافر بين العصب والوظيف. والحوشب: العظيم البطن، قال الأعلم الهذلي: وتجر مجرية لها ... لحمي إلى أجر حواشب 3 وقال العجاج في الوظيف: في رسغ لا يتشكى الحوشبا 4 الحوشب: من أسماء الرجال.'),
(596, 'شحب', 'شحب', 'شحب', 'شحب يشحب شحوبا: أي تغير من سفر أو هزال أو عمل، قال: فإن كرام الناس باد شحوبها 1'),
(597, 'حبش', 'حبش', 'حبش', 'الحبش: جنس من السودان، وهم الحبشان والحبش، و [في] لغة يقولون: الحبشة على بناء سفرة، وهذا خطأ في القياس لأنك لا تقول حابش كما تقول: فاسق وفسقة، ولكنه سار في اللغات وهو في اضطرار الشعر جائز. والأحبوش كالحبش، قال: 2 كأن صيران المها الأخلاط ... بالرمل أحبوش من الأنباط وأما الأحابيش فكانوا أحياء من القارة انضموا إلى بني ليث في الحرب التي وقعت بينهم وبين قريش قبل الإسلام فيها يقول إبليس لقريش: إني جار لكم من بني كبت فواقعوا محمدا، أتاهم في صورة سراقة بن مالك بن جعثم، وذلك حيث يقول الشاعر: ليث وديل وكعب والتي ظأرت ... جمع الأحابيش لما احمرت الحدق سموا بذلك لتجمعهم فلما صار لهم ذلك الاسم صار التحبيش في الكلام كالتجميع، قال رؤبة 3 : أولاك حبشت لهم تجبيشي ... فرضي وما جمعت من خروشي والحبشية: ضرب من النمل سود عظام، لما جعلوا ذلك اسما غيروا اللفظ ليكون فرقا بين النسبة والاسم. النسبة: حبشية، والاسم: حبشية. وعلى هذا أيضا الحبشية: ناقة شديدة السواد.'),
(598, 'شبح', 'شبح', 'شبح', 'الشبح: ما بدا لك شخصه من الخلق، يقال: شبح لنا أي مثل، وجمعه: أشباح، قال: رمقت بعيني كل شبح وحائل 1 وقال: كأنما الرحل منها فوق ذي جدد ... ذب الرياد إلى الأشباح نظار 2 أي كثير الرياد وهو الاقبال والادبار في الرعي. ويقال في التصريف أسماء الأشباح وهو ما [أدركته] 3 الرؤية والحس، وأسماء الأعمال: ما لا تدركه الرؤية ولا الحس. والشبح: مدك الشيء بين أوتاد ليجف. والمضروب يشبح إذا مد للجلد. ورجل مشبوح الذراعين: أي طويلهما، قال أبو ذؤيب: فذلك مشبوح الذراعين خلجم ... خشوف إذا ما الحرب طال مرارها 4'),
(599, 'حشم', 'حشم', 'حشم', 'الحشم: خدم الرجل ومن دون أهله من ولده وعياله. والحشمة: الانقباض عن أخيك في المطعم وطلب الحاجة، تقول: احتشمت، وما الذي حشمك وأحشمك أيضا. والحشوم: الإقبال بعد الهزال، حشم يحشم، ورجل حاشم، وقد حشمت الدواب في أول الربيع وذلك إذا أصابت شيئا فحسنت بطونها وعظمت.'),
(600, 'شحم', 'شحم', 'شحم', 'رجل شاحم لاحم: إذا أطعم الناس الشحم واللحم. وقد شحمهم يشحمهم شحما. وشحمة الرمانة: هنة في جوفها تفصل بين حبها، وإذا غلظت قلت رمانة شحمة. وعنب شحم: قليل الماء صلب اللحاء. وشحمة الأذن: لحمة متعلق القرط من أسفل.'),
(601, 'حمش', 'حمش', 'حمش', 'الحمش: الدقيق القوائم. وساق حمشة، جزم، وتجمع [على] : حمش وحماش، قال الطرماح يصف الديكة: حماش الشوى يصدحن من كل مصدح 1 . أي: من كل وجه. والاستحماش في الوتر أحسن، يقال: أوتار حمشة، ووتر حمش: مستحمش، قال: 2 كأنما ضربت قدام أعينها ... قطن بمستحمش الأوتار محلوج واستحمش الرجل: اشتد غضبه.'),
(602, 'محش', 'محش', 'محش', 'المحش: تناول من لهب يحرق الجلد ويبدي العظم، يقال محشته النار محشا.'),
(603, 'دحض', 'دحض', 'دحض', 'الدحض: الزلق، يقال: مزلقة مدحاض. والدحض: الماء الذي تكون منه المزلقة. ودحضت الشمس عن بطن السماء، أي: زالت. ودحضت حجته: أي: بطلت. ودحيضة: موضع، قال: 1 أتنسين أياما لنا بدحيضة ... وأيامنا بين البدي فثهمد البدي: بئر لحمى ضرية لبني جعفر بن كلاب. ودحضت رجل البعير: زلقت.'),
(604, 'حضر', 'حضر', 'حضر', 'الحضر: خلاف البدو، والحاضرة خلاف البادية لأن أهل الحاضرة حضروا الأمصار والديار. والبادية يشبه أن يكون اشتقاق اسمه من: بدا يبدو أى برز وظهر، ولكنه اسم لزم ذلك الموضع خاصة دون ما سواه، [والحضرة: قرب الشيء] 1 . تقول: كنت بحضرة الدار، قال: فشلت يداه يوم يحمل رأسه 2 ... إلى نهشل 3 والقوم حضرة نهشل وضربته بحضرة فلان، وبمحضره أحسن في هذا. والحاضر: هم الحي إذا حضروا الدار التي بها مجتمعهم فصار الحاضر اسما جامعا كالحاج والسامر ونحوهما، قال: في حاضر لجب بالليل سامره ... فيه الصواهل والرايات والعكر 4 والحضر والحضار: من عدو الدابة، والفعل: الإحضار. وفرس محضير بمعنى محضار غير أنه لا يقال إلا بالياء وهو من نوادر كلام العرب، قال امرؤ القيس: استلحم الوحش على أحشائها ... أهوج محضير إذا النقع دخن 5 والحضير: ما اجتمع من [جائية] 6 المدة 7 في الجرح، وما اجتمع من السخد في السلا ونحوه. والمحاضرة: أن يحاضرك إنسان بحقك فيذهب به مغالبة ومكابرة. والحضار: اسم جامع للإبل البيض كالهجان، الواحدة والجميع في الحضار سواء. وتقول: حضار. أي: احضر مثل نزال بمعنى انزل. وتقول: حضرت الصلاة، لغة أهل المدينة، بمعنى حضرت، وكلهم يقولون: تحضر. وحضار: اسم كوكب معروف، مجرور أبدا. وحضرموت: اسمان جعلا اسما واحدا ثم سميت به تلك البلدة، ونظيره: أحمرجون 1 .'),
(605, 'رحض', 'رحض', 'رحض', 'ثوب رحيض ومرحوض: أي: مغسول. والرحض: الغسل. وقالت عائشة في عثمان: استتابوه حتى إذا تركوه كالثوب الرحيض أحالوا عليه فقتلوه 2 . والمرحضة: شيء يتوضأ فيه مثل كنيف وكذلك المرحاض وهو المغتسل. والرحضاء: عرق الحمى، رحض الرجل أخذته الرحضاء.'),
(606, 'حرض', 'حرض', 'حرض', 'التحريض: التحضيض. والحرض، (مثقل) ، الأشنان، والمحرضة: وعاؤه. وقوله تعالى: حتى تكون حرضا 3 أي محرضا يذيبك الهم، وهو المشرف حتى يكاد يهلك. رجل حرض ورجال أحراض. والحرض: الذي لا خير فيه لؤما ودقة من كل شيء. [والفعل منه 4 : حرض يحرض حروضا. وناقة حرض وإبل أحراض: وهو الضاوي الرديء.'),
(607, 'ضرح', 'ضرح', 'ضرح', 'الضرح: حفرك الضريح للميت وهو قبر بلا لحد، ضرحت له. والضرح: الرمي بالشيء. واضطرحوا فلانا: إذا رموا به، والعامة تقول: اطرحوه، يظنون أنه من الطرح وإنما هو من الضرح، قال: ضرحا بصليات النسور نحتبي 5 ويقال: الضرح الرمح. والضراح بيت في السماء. والمضرحي من الصقور: ما طال جناحاه، قال طرفة: كأن جناحي مضرحي تكنفا 1 ويقال للرجل السيد السري: مضرحي. ويقال المضرحي. ويقال المضرحي: الأبيض من كل شيء.'),
(608, 'رضح', 'رضح', 'رضح', 'الرضح: رضحك النوي بالمرضاح أي: بالحجر، والخاء لغة قليلة.'),
(609, 'ضحل', 'ضحل', 'ضحل', 'الضحل: الماء القريب القعر. والضحضاح: أعم منه قل أو كثر. وأتان الضحل: الصخرة بعضها غامر وبعضها ظاهر. والمضحل: مكان يقل فيه الماء من الضحل، وبه يشبه السراب، قال: 2 حسبت يوما غير قر شاملا ... ينسج غدرانا على مضاحلا'),
(610, 'حضل', 'حضل', 'حضل', 'حضلت النخلة: أي فسد أصول سعفها، و [حظلت] 3 أيضا. وصلاحها: إشعال نار فيها حتى يحترق ما فسد من ليفها وسعفها ثم تجود بعد ذلك.'),
(611, 'حضن', 'حضن', 'حضن', 'الحضن: ما دون الإبط إلى الكشح، ومنه احتضانك الشيء وهو احتمالكه وحملكه في حضنك كما تحتضن المرأة ولدها فتحمله في أحد شقيها. والمحتضن: الحضن، قال: 1 هضيم الحشا شختة المحتضن 2 والحضانة: مصدر الحاضنة والحاضن وهما اللذان يربيان الصبي. وناحيتا المفازة: حضناها، قال: أجزت حضنيه هبلا وعثا 3 وعنز حضون: أي أحد طبييها أطول. والحمامة تحتضن بيضها حضونا للتفريخ فهي حاضن. وسقع حواضن: أي جواثم، قال النابغة: رماد محتة الريح من كل وجهة ... وسفع على ما بينهن حواضن 4 أي أثافي [جواثم] على الرماد. وحضنت الرجل عن الشيء: اختزلته ومنعته، قال ابن مسعود: لا تحضن زينب امرأة عبد الله 5 أي لا تحجب عنه ولا يقطع أمر دونها. وفلان احتجن بأمر دوني وأحضنني: أي أخرجني منه في ناحية. وقالت الأنصار لأبي بكر: تريدون أن تحضنونا 6 من هذا الأمر. والمحضنة: المعمولة من الطين للحمامة كالقصعة الروحاء. والمحاضن: المواضع التي تحضن فيها الحمامة على بيضها، واحدها محضن. والأعنز الحضينات: ضرب منها شديدة الحمرة، وأسود منها شديد السواد. والحضن: جبل، قال الأعشى: كخلقاء من هضبات الحضن 1'),
(612, 'نضح', 'نضح', 'نضح', 'النضح: كالنضح ربما اختلفا وربما اتفقا. ويقال: النضخ ما بقي له أثر، يقال: على ثوبه نضخ دم. والعين تنضح بالماء نضحا: أي تفور [وتنضخ] أيضا. والرجل يعترف بأمر فينتضح منه: إذا أظهر البراءة وبرا نفسه منه جهده. والنضيح من الحياض: ما قرب من البئر حتى يكون الافراغ فيه من الدلو ويكون عظيما، قال: 2 فغدونا عليهم بكرة الورد ... كما تورد النضيح الهياما والناضح: جمل يستقى عليه الماء للقرى في الحوض، أو سقي أرض وجمعه النواضح. والفرس ينضح: أي يعرق، قال: 3 كأن عطفيه من التنضاح ... بالماء ثوبا منهل مياح أي مستق بيده. والجرة تنضح بالماء: يخرج الماء من الخزف لرقتها. والجبل ينضح: إذا تحلب الماء من بين صخوره. ويقال في القتال: نضحوهم بالنشاب ورضحوهم بالحجارة. واستنضح الرجل: أي رش شيئا من الماء على فرجه بعد الوضوء. وإذا ابتدأ الدقيق في حب السنبل وهو رطب قيل: قد أنضح ونضح 1 ، لغتان. والنضوح: الطيب.'),
(613, 'نحض', 'نحض', 'نحض', 'النحض: اللحم نفسه، والقطعة الضخمة تسمى نحضة. ورجل نحيض، وامرأة نحيضة: كثيرة اللحم. وقد نحض نحاضة، فإذا قلت: نحضت فقد ذهب لحمها فهي منحوضة ونحيض. ونحضت السنان رققته، قال حميد: كموقف الأشقر إن تقدما ... باشر منحوض السنان لهذما والموت من ورائه ان أحجما 2'),
(614, 'ضحن', 'ضحن', 'ضحن', 'الضحن: اسم بلد.'),
(615, 'فضح', 'فضح', 'فضح', 'والاسم: الفضيحة: ويجمع الفضائح. والفضح فعل مجاوز من الفاضح إلى المفضوح، قال في الفضائح: قوم إذا ما رهبوا الفضائحا ... على النساء لبسوا الصفائحا 3 وقال الأعشى: لأمك بالهجاء أحق منا ... لما أولتك من شوط الفضاح 1 الشوط: المجازاة. يقال للمفتضح: يا فضوح. وأفضح البسر: إذا بدت فيه الحمرة. والفضحة: غبرة في طحلة 2 يخالطها لون قبيح يكون في ألوان الإبل والحمام، والنعت أفضح. قد فضح فضحا.'),
(616, 'حفض', 'حفض', 'حفض', 'الحفض: القعود نفسه بما عليه، ويقال: بل الحفض كل جوالق فيه متاع القوم ويحتج بقوله: 3 على الأحفاض نمنع من يلينا ويقال: الأحفاض في هذا البيت صغار الإبل أول ما تركب، وكانوا يكنونها في البيت من البرد، قال: بملقى بيوت عطلت بحفاضها ... وإن سواد الليل شد على مهر 4 ويقال: الأحفاض عند الأخبية. ومثل من الأمثال: يوم بيوم الحفض المجور 5 .'),
(617, 'حضب', 'حضب', 'حضب', 'الحضب والحصب واحد، وقرىء: حضب جهنم، قال الأعشى: فلا تك في حربنا محضبا ... لتجعل قومك شتى شعوبا 1 أي موقدا.'),
(618, 'ضبح', 'ضبح', 'ضبح', 'ضبحت العود بالنار: إذا أحرقت من أعاليه شيئا، وكذلك حجارة القداحة إذا طلعت كأنها محترقة: مضبوحة، قال طرفة: واصفر مضبوح نظرت حواره ... إلى النار واستودعته كف مجمد 2 أي بخيل يريد المضبوح بالنار. يقال: كل شيء مسته النار فقد ضبحته. والضباح: صوت الثعلب. والهام يضبح، قال الشاعر: من ضابح الهام وبوم نوم 3 الأرجوزة للعجاج، وقال ذو الرمة: سباريت يخلو سمع مجتاز ركبها 4 ... من الصوت إلا من ضباح الثعالب والخيل تضبح في عدوها ضبحا: تسمع من أفواهها صوتا ليس بصهيل ولا حمحمة.'),
(619, 'حبض', 'حبض', 'حبض', 'حبض القلب يحبض حبضا: أي ضربانا شديدا. والعرق يحبض ثم يسكن، وهو أشد من النبض. والوتر يحبض إذا مددته ثم أرسلته. وحبض السهم: إذا لم يقع بالرمية وقصر دونها فوقع وقعا [غير شديد 1 ] ، قال الراجز: والنبل يهوي خطأ وحبضا ويقال: أصاب القوم داهية من حبض الدهر: أي من ضرباته. ويقال: حبض الدهر وحبضه أي حركاته. والحبض والنبض: الحركة، يقال: ما يحبض ولا ينبض.'),
(620, 'حمض', 'حمض', 'حمض', 'الحمض: كل نبات يبقى على القيظ فلا يهيج في الربيع، وفيه ملوحة، تشرب الإبل الماء على أكله، وإذا لم تجده دقت 2 وضعفت. حمضت تحمض حموضا: إذا رعتها، وهي حوامض، وأحمضناها، قال: 3 قريبة ندوته من محمضه وقد يسمى كل ما فيه ملوحة حمضا. ويقال للشيء الحامض: حمض حموضة، إلا أنهم يقولون للبن خاصة حمض حمضا، وهو شديد الحمض. واللحم حمض الرجال، وإذا حولت رجلا عن أمر فقد أحمضته، قال الطرماح: لا يني يحمض العدو وذو الخلة ... يشفى صداه بالإحماض 1 والحمضة: الشهوة للشيء: وحمضة اسم حي بلعاء بن قيس الليثي. والحماض: بقلة من ذكور البقل لها زهرة حمراء، قال: 2 كثمر الحماض من هفت العلق ويقال للذي يكون في جوف الأترج: حماضة ويجمع الحماض: قال 3 : كأنما في فيه حماض نزا'),
(621, 'محض', 'محض', 'محض', 'المحض: اللبن الخالص بلا رغوة. وكل شيء خلص حتى لا يشوبه شيء فهو محض. ورجل ممحوض الضريبة: أي مخلص. وفضة محضة: لا شوب فيها، فإذا قلت هذه الفضة محضا جعلت المحض [نصبا] اعتمادا على المصدر أي قصدا له. ورجل عربي محض، وامرأة محضة ومحض.'),
(622, 'مضح', 'مضح', 'مضح', 'مضح الرجل عرض فلان: 4 إذا شأنه وعابه، قال 5 . لا تمضحن عرضي فإني ماضح ... عرضك إن شاتمتني وقادح'),
(623, 'حصد', 'حصد', 'حصد', 'الحصد: جز البر ونحوه. وقتل الناس أيضا حصد. وقول الله تعالى: جعلناهم حصيدا 1 أي كالحصيد المحصود. والحصيدة: المزرعة إذا حصدت كلها. والجميع الحصائد، قال الأعشى: قالوا البقية والهندي يحصدهم ... ولا بقية إلا الثأر 2 فانكشفوا نصب البقية بفعل مضمر أي ألقوا. وقوله تعالى: وحب الحصيد 3 أي وحب البر المحصود. وأحصد البر: إذا أنى حصاده أي: حان وقت جزازه. والحصاد: اسم البر المحصود وبعد ما يحصد، قال ذو الرمة: عليهن رفضا من حصاد القلاقل 4 وقوله تعالى: يوم حصاده وحصاده، يريد: الوقت للجزاز. والأحصد: المحصد: [وهو المحكم فتله] 5 وصنعته من حبل ودرع ونحوه. ويقال للخلق الشديد أحصد فهو محصد ومستحصد، وتر أحصد، قال: 6 . من نزع أحصد مستأرب أي محكم الأرب ومثله مؤرب الخلق أي محكمة، ومستأرب مستفعل، والدرع الحصداء: المحكمة.'),
(624, 'صدح', 'صدح', 'صدح', 'الصدح: من شدة صوت الديك والغراب ونحوهما، قال أبو النجم يصف الحمار: محشرجا ومرة صدوحا والصادحة: المغنية. وصيدح: اسم ناقة ذي الرمة، لا ينصرف، ولو كان اسما عاملا لانصرف، قال: فقلت لصيدح انتجعي بلالا 1'),
(625, 'حصر', 'حصر', 'حصر', 'حصر حصرا: أي عي فلم يقدر على الكلام. وحصر صدر المرء: أي ضاق عن أمر حصرا. والحصر: اعتقال البطن حصر، وبه حصر، وهو محصور. والحصار: موضع يحصر فيه المرء، حصروه حصرا، وحاصروه، قال رؤبة: مدحة محصور تشكى الحصرا ... دجران لم يشرب هناك الخمرا 2 دجران: أي سكران: والإحصار: أن يحصر الحاج عن بلوغ المناسك مرض أو عدو. والحصور: من لا إربة له في النساء. والحصور كالهيوب المحجم عن الشيء، قال الأخطل: لا بالحصور ولا فيها بسوار 1 والحصير: سفيفة من بردي ونحوه. وحصير الأرض: وجهها، وجمعه حصر. والعدد: أحصرة. والحصير: فرند السيف. والحصير: الجنب، قال تعالى: وجعلنا جهنم للكافرين حصيرا 2 أي يحصرون فيها.'),
(626, 'صحر', 'صحر', 'صحر', 'أصحر القوم: أي برزوا إلى الصحراء، وهو فضاء من الأرض واسع لا يواريهم شيء، والجمع الصحارى ولا يجمع على الصحر لأنه ليس بنعت. والصحر مصدر الأصحر وهو لون غبرة في حمرة خفيفة 3 إلى بياض قليل، والجميع الصحر. والصحرة: اسم اللون، يقال حمار أصحر، قال ذو الرمة: صحر السرابيل في أحشائها فبب 4 وأصحار النبات: أي أخذت فيه صفرة غير خالصة ثم يهيج فيصفر. ويقول: أبرز له ما في نفسه صحارا: أي جاهره به جهارا. والصحير: النهيق الشديد، صحر يصحر صحيرا، أي: نهق.'),
(627, 'صرح', 'صرح', 'صرح', 'الصرح: بيت منفرد يبنى ضخما طويلا في السماء، ويجمع الصروح، قال: 5 بهن نعام بنته الرجال ... تحسب أعلامهن الصروحا يريد بالنعام: [خشبات] قائمات على أرجاء الآباد. والصريح: اللبن المحض الخالص. ومن كل شيء. ومن البول: إذا لم يكن عليه رغوة، قال أبو النجم: يسوف من أبوالها الصريحا ... حسو المريض الخردل المجدوحا 1 والصريح من الخيل والرجال: المحض الحسب، وجمعه: صرحاء، وجمع الخيل: الصرائح. وصريح النصح: محضه، قال الشاعر: أمرت أبا ثور بنصح كأنما ... يرى بصريح النصح وكع العقارب 2 وقول عبيد: 3 فتخاء لاح لها بالصرحة الذيب فالصرحة: موضع، ويقال: متن 4 من الأرض مستو. وكرم ماء صريحا قال زائدة: بالصخرة الذيب. وقال في السحاب: 5 أي: خالصا، كرم 6 : كثر بلغة هذيل وصرح ما في نفسه تصريحا أي أبداه 7 . وخمر وكأس صراحية وصراح: أي لم تشب بمزاج، وصرحت الخمر تصريحا: ذهب عنها الزبد، قال الأعشى: كميتا تكشف عن حمرة ... إذا صرحت بعد إزبادها ويقال: جاء بالكفر صراحا: أي جهارا.'),
(628, 'حرص', 'حرص', 'حرص', 'حرص يحرص حرصا فهو حريص عليك: أي على نفعك، وقوم حرصاء وحراص. والحرصة: مستقر وسط كل شيء كالعرصة للدار 1 . والحارصة: شجة تشق الجلد قليلا كما يحرص القصار الثوب عند الدق، ويقال منه قول الله- عز وجل-: ولو حرصت بمؤمنين 2 . والمطر يحرص الأرض: يخرقها.'),
(629, 'حصل', 'حصل', 'حصل', 'حصل يحصل حصولا: أي بقي وثبت وذهب ما سواه من حساب أو عمل ونحوه فهو حاصل. والتحصيل: تمييز ما يحصل. والاسم: الحصيلة، قال لبيد: وكل امرىء يوما سيعلم سعيه ... إذا حصلت عند الإله الحصائل 3 ويروى: إذا كشفت عند الإله. وحوصلة الطائر: معروف. والحوصلة: طير أعظم من طير الماء طويل العنق، بحرية جلودها بيض تلبس، ويجمع حواصل. والحوصل: الشاة التي عظم ما فوق سرتها من بطنها. ويقال: احونصل الطير: إذا ثنى عنقه وأخرج [حوصلته] 1 .'),
(630, 'صحل', 'صحل', 'صحل', 'الصحل: صوت فيه بحة، صحل صوته فهو أصحل الصوت 2'),
(631, 'صلح', 'صلح', 'صلح', 'الصلاح: نقيض الطلاح 3 . ورجل صالح في نفسه ومصلح في أعماله وأموره. والصلح: تصالح القوم بينهم. وأصلحت إلى الدابة: أحسنت إليها. والصلح: نهر بميسان.'),
(632, 'لحص', 'لحص', 'لحص', 'اللحص والتلحيص: استقصاء خبر الشيء وبيانه، لحص لي فلان خبرك وأمرك أي بينه شيئا شيئا. وقال 4 في بعض الوصف: أمر مناقع النز ومواقع الرز، حبها لا يجز، وقصبها يهتز، وكتبت كتابي هذا وقد حصلته ولحصته وفصلته ووصلته وترصته 6 وفصصته محصلا ملحصا مفصلا موصلا مترصا مفصصا، وبعض يقول ملخصا بالخاء.'),
(633, 'حصن', 'حصن', 'حصن', 'الحصن: كل موضع حصين لا يوصل إلى ما في جوفه، يقال: حصن الموضع حصانة وحصنته وأحصنته. وحصن حصين: أي لا يوصل إلى ما في جوفه. والحصان: الفرس الفحل، وقد تحصن أي تكلف ذلك، ويجمع [على] حصن. وامرأة محصنة: أحصنها زوجها. ومحصنة: أحصنت زوجها. ويقال: فرجها. وامرأة حاصن: بينة الحصن والحصانة أي العفافة عن الريبة. وامرأة حصان الفرج، قال: 1 وبيني حصان الفرج غير ذميمة ... وموموقة فينا كذاك ووامقه وجماعة الحاصن حواصن وحاصنات، قال: وابناء الحواصن من نزار 2 وقال العجاج: وحاصن من حاصنات ملس 3 وأحسن ما يجمع عليه الحصان حصانات. والمحصن: المكتل 4 . والحصينة: اسم للدرع المحكمة النسج، قال: وكل دلاص كالأضاة حصينة 1'),
(634, 'صحن', 'صحن', 'صحن', 'الصحن: شبه العس الضخم إلا أن فيه عرضا وقرب قعر. والسائل يتصحن الناس: أي يسأل في قصعة ونحوها. والصحناة 2 بوزن فعلاة إذا ذهب عنها الهاء دخلها التنوين، ويجمع على الصحنى بحذف الهاء.'),
(635, 'نصح', 'نصح', 'نصح', 'فلان ناصح الجيب: أي ناصح القلب مثل طاهر الثياب أي الصدر. ونصحته ونصحت له نصحا ونصيحة، قال: النصح مجان فمن شاء قبل ... ومن أبى لا شك يخسر ويضل 3 والناصح: الخياط، وقميص منصوح: أي مخيط. نصحته أنصحه نصحا [من النصاحة] . والنصاحة: السلوك التي يخاط بها وتصغيرها نصيحة، قال: 4 وسلبناه برده المنصوحا والتنصح: كثرة النصيحة، قال أكتم بن صيفي: إياكم وكثرة التنصح فإنه يورث التهمة. والتوبة النصوح: أن لا يعود إلى ما تاب عنه. والنصاحات: الجلود، قال الأعشى: فترى القوم نشاوى كلهم ... مثل ما مدت نصاحات الربح 5'),
(636, 'نحص', 'نحص', 'نحص', 'النحوص: الأتان الوحشية الحائل. ونحص الجبل: أصله.'),
(637, 'حنص', 'حنص', 'حنص', 'الحنصأوة من الرجال: الضئيل الضعيف، قال: حتى ترى الحنصأوة الفروقا ... متكئا [يقتمح] 1 السويقا'),
(638, 'صحف', 'صحف', 'صحف', 'الصحف: جمع الصحيفة، يخفف ويثقل، مثل سفينة وسفن، نادرتان، وقياسه صحائف وسفائن. وصحيفة الوجه: بشرة جلده، قال: إذا بدا من وجهك الصحيف 2 وسمي المصحف مصحفا لأنه أصحف، أي جعل جامعا للصحف المكتوبة بين الدفتين. والصحفة شبه القصعة المسلنطحة العريضة وجمعه صحاف. والصحفي: المصحف، وهو الذي يروي الخطأ عن قراءة الصحف بأشباه الحروف.'),
(639, 'حصف', 'حصف', 'حصف', 'الحصف: بثر صغار يقيح ولا يعظم 3 ، وربما خرج في مراق البطن أيام الحر. حصف جلده حصفا. والحصافة: ثخانة العقل. رجل حصيف حصف، قال حديثك في الشتاء حديث صيف ... وشتوي الحديث إذا تصيف فتخلط فيه من هذا بهذا ... فما أدري أأحمق أم حصيف 1 ويقال: أحصف نسجه: أحكمه. وأحصف الفرس: عدا عدوا شديدا، [ويقال: استحصف القوم واستحصدوا إذا اجتمعوا] . قال الأعشى: تأوي طوائفها إلى محصوفة ... مكروهة يخشى الكماة نزالها 2'),
(640, 'فصح', 'فصح', 'فصح', 'الفصح: فطر النصارى، قال الأعشى: بهم تقرب يوم الفصح ضاحية 3 وتفصيح اللبن: ذهاب اللبأ عنه وكثرة محضة وذهاب رغوته، فصح اللبن تفصيحا. ورجل فصيح فصح فصاحة، وأفصح الرجل القول. فلما كثر وعرف أضمروا القول واكتفوا بالفعل كقولهم: أحسن وأسرع وأبطأ. ويقال في الشعر في وصف العجم: أفصح وإن كان بغير العربية كقول أبي النجم: أعجم في آذانها فصيحا 4 يعني صوت الحمار. والفصيح في كلام العامة: المعرب.'),
(641, 'صفح', 'صفح', 'صفح', 'الصفح: الجنب: من كل شيء. وصفحا السيف: وجههاه. وصفحة الرجل: عرض صدره 1 وسيف مصفح [ومصفح] وصدر مصفح: أي عريض، قال: وصدري مصفح للموت نهد ... إذا ضاقت عن الموت الصدور 2 وقال الأعشى: ألسنا نحن أكرم إن نسبنا ... وأضرب بالمهندة الصفاح 3 وقال لبيد: 4 كأن مصفحات في ذراه ... وأنواحا عليهن المآلي شبه السحاب وظلمته وبرقه بسيوف مصفحة، والمآلي جمع المئلاة وهي خرقة سوداء بيد النواحة. وكل حجر عريض أو خشبة أو لوح أو حديدة أو سيف له طول وعرض فهو صفيحة، وجمعه صفائح. والصفاح من الحجارة خاصة: ما عرض وطال، الواحدة صفاحة، قال: 5 ويوقدن بالصفاح نار الحباحب وصفحت عنه: أي عفوت عنه. وصفحت ورق المصحف صفحا. وصفحت القوم: عرضتهم واحدا واحدا 6 وتصفحتهم: نظرت في خلالهم هل أرى فلانا، أو ما حالهم. وقوله تعالى: أفنضرب عنكم الذكر صفحا 7 هو الاعراض. والصفاح من الإبل: التي عرضت أسنامها 1 ، ويجمع صفاحات وصفافيح. والمصافحة معروفة.'),
(642, 'فحص', 'فحص', 'فحص', 'الفحص: شدة الطلب خلال كل شيء [تقول] : فحصت عنه وعن أمره لأعلم كنه حاله. ومفحص القطا: موضع تفرخ فيه. والدجاجة تفحص برجليها وجناحيها في التراب: تتخذ أفحوصة تبيض أو تربض 2 فيها. وفي الحديث: 3 فحصوا عن أوساط الرءوس أي عملوها مثل أفاحيص القطا. والمطر يفحص [الحصى] 4 : يقلبه وينحي بعضه عن بعض.'),
(643, 'حفص', 'حفص', 'حفص', 'أم حفصة: تكنى به الدجاجة. وولد الأسد يسمى [حفصا] 5 .'),
(644, 'حصب', 'حصب', 'حصب', 'الحصب: رميك بالحصباء أي صغار الحصى أو كبارها. وفي فتنة عثمان: تحاصبوا حتى ما أبصر أديم السماء. والحصبة معروفة تخرج بالجنب، حصب فهو محصوب. والحصب: الحطب للتنور أو في وقود [أما] 6 ما دام غير مستعمل للسجور فلا يسمى حصبا. والحاصب: الريح تحمل التراب وكذلك ما تناثر من دقاق البرد والثلج، قال الأعشى: لنا حاصب مثل رجل الدبى ... وجأواء تبرق عنها الهيوبا 1 يصف جيشا جعله بمنزلة الريح الحاصب يثير الأرض. والمحصب: موضع الجمار. والتحصيب: النوم بالشعب الذي مخرجه إلى الأبطح ساعة من الليل ثم يخرج إلى 2 مكة.'),
(645, 'صحب', 'صحب', 'صحب', 'الصاحب: يجمع بالصحب، والصحبان والصحبة والصحاب. والأصحاب: جماعة الصحب. والصحابة مصدر قولك صاحبك الله وأحسن صحابتك. ويقال عند الوداع: مصاحبا معافى. ويقال: صحبك الله [أي: حفظك] ، ولا يقال: مصحوب. والصاحب يكون في حال نعتا، ولكنه عم في الكلام فجرى مجرى الاسم، كقولك: صاحب مال، أي: ذو مال، وصاحب زيد، أي: أخو زيد ألا ترى أن الألف واللام لا تدخلان، على قياس الضارب زيدا، لأنه لم يشتق من قولك: صحب زيدا، فإذا أردت ذلك المعنى قلت: هو الصاحب زيدا. وأصحب الرجل: إذا كان ذا صاحب. وتقول: إنك لمصحاب لنا بما تحب، قال: 3 فقد أراك لنا بالود مصحابا وكل شيء لاءم شيئا فقد استصحبه، قال: إن لك الفضل على صاحبي 4 ... والمسك قد يستصحب الرامكا ويقال: جلد مصحب: إذا كان عليه شعره وصوفه.'),
(646, 'صبح', 'صبح', 'صبح', '[تقول] : صبحني فلان: إذا أتاك صباحا. وناولك الصبوح صباحا، قال طرفة بن العبد: متى تأتني أصبحك كأسا روية ... وإن كنت عنها ذا غنى فاغن وازدد 1 وتقول في الحرب: صبحناهم. أي غاديناهم بالخيل ونادوا: يا صباحاه، إذا استغاثوا. ويوم الصباح: يوم الغارة، قال الأعشى: ويمنعه يوم الصباح مصونة ... سراعا إلى الداعي تثوب وتركب 2 (يعني أن الخيل تمنع هذا المصطبح يوم الصباح، المصونة: الخيل، تثوب: ترجع) 3 . وكان ينبغي أن يقول: تركب وتثوب، فاضطر إلى ما قاله. وهذا مثل قوله تعالى: اقتربت الساعة وانشق القمر 4 إنما معناه: انشق القمر واقتربت الساعة. وكما قال ابن أحمر: فاستعرفا ثم قولا في مقامكما ... هذا بعير لنا قد قام فانعقرا 5 معناه: قد انعقر فقام. والصبح: سقيك من أتاك صبوحا من لبن وغيره. والصبوح: ما يشرب بالغداة فما دون القائلة، وفعلك الاصطباح. والصبوح: الخمر، قال الأعشى: ولقد غدوت على الصبوح معي ... شرب كرام من بني رهم 6 واستصبح القوم بالغدوات. والمصبح: الموضع الذي يصبح فيه، قال: بعيدة المصبح من ممساها 1 والمصباح: السراج بالمسرجة، والمصباح: نفس السراج وهو قرطه الذي تراه في القنديل وغيره، والقراطة 2 لغة. والمصباح من الإبل: ما يبرك في معرسه فلا ينهض وإن أثير حتى يصبح، قال: أعيس في مبركه مصباحا 3 والمصابيح من النجوم: أعلام الكواكب، الواحد مصباح، وقول الله- عز وجل-: فأخذتهم الصيحة مصبحين 4 أي بعد طلوع الفجر وقبل طلوع الشمس. وصبحت القوم ماء كذا، وصبحتهم أيضا: أتيتهم مع الصباح، قال: وصبحتهم ماء بفيفاء قفرة ... وقد حلق النجم اليماني فاستوى 5 والصبح والصباح: هما أول النهار. والصبح: شدة حمرة في الشعر، وهو أصبح. والأصبحية والأصبحي: غلاظ السياط وجيادها، وتقول: أصبح الصبح صباحا وصباحة. وصبح الرجل صباحة وصبحة، قال ذو الرمة: وتجلو بفرع من أراك كأنه ... من العنبر الهندي والمسك أصبح 6 أراد به أذكى ريحا. ونزل رجل بقوم فعشوه فجعل يقول: إذا كان غد وأصبت من الصبوح مضيت في حاجة كذا (أراد أن يوجب) 7 الصبوح عليهم ففطنوا له فقالوا: أعن صبوح ترقق. أي: تحسن كلامك فذهبت مثلا.'),
(647, 'حمص', 'حمص', 'حمص', 'الحمصيص: بقلة دون الحماض في الحموضة، طيبة الطعم من أحرار البقل تنبت في رمل عالج. والحمص: ترجح الغلام على أرجوحة من غير أن يرجح، يقال: حمص. وانحمص الورم: أي سكن. وحمصه الدواء 1 . وحمصت القذاة بيدي: إذا رفقت بإخراجها من العين مسحا مسحا. حمص: كورة بالشام أهلها يمانون. والحمص: جمع الحمصة، وهو حبة القدر، قال: ولا تعدون سبيل الصواب ... فأرزن من كذب حمصه 2'),
(648, 'محص', 'محص', 'محص', 'المحص: خلوص الشيء، محصته محصا: خلصته من كل عيب، قال: يعتاد كل طمرة ... ممحوصة ومقلص 3 والمحص: العدو، يقال: خرج يمحص كأنه ظبي. والتمحيص: التطهير من الذنوب.'),
(649, 'صحم', 'صحم', 'صحم', 'الصحمة: لون من الغبرة إلى سواد قليل. واصحامت البقلة فهي مصحامة: إذا أخذت ريها واشتدت خضرتها. والصحماء: اسم بقلة ليست بشديدة الخضرة. وبلدة صحماء: ذات اغبرار، قال الطرماح: وصحماء مغبر الحزابي كأنها 1'),
(650, 'مصح', 'مصح', 'مصح', 'مصح الشيء 2 يمصح مصوحا: إذا رسخ، من الثرى وغيره. والدار تمصح: أي تدرس فتذهب، قال الطرماح: قفا نسأل الدمن الماصحه 3 وقال: عبل الشوى ماصحة أشاعره 4 أي رسخت أصول الأشاعر حتى أمنت الانتتاف والانحصاص.'),
(651, 'صمح', 'صمح', 'صمح', 'صمحه الصيف: أي: كاد يذيب دماغه من شدة الحر 5 . قال أبو زبيد الطائي: 6 من سموم كأنها لفح نار ... صمحتها ظهيرة غراء وقال ذو الرمة: إذا صمحتنا الشمس كان مقيلنا ... سماوة بيت لم يروق له ستر 1 وفي حديث مقتل حجر بن عدي عن أبي عبيد في ذكر سمية أم زياد: إنها لوطباء 2 شديدة الصماح تحب النكاح أي شديدة الحر. ورجل صمحمح وصمحمحي: أي مجتمع ذو ألواح، وفي السن: ما بين الثلاثين إلى الأربعين.'),
(652, 'حصم', 'حصم', 'حصم', 'حصم الفرس وخبج الحمار: إذا ضرط. والحصوم: الضروط.'),
(653, 'سطح', 'سطح', 'سطح', 'السطح: البسط، يقال في الحرب سطحوهم أي أضجعوهم على الأرض. والسطيح: المسطوح، وهو القتيل، قال: حتى تراه وسطنا سطيحا 3 وسطيح: اسم رجل من بني ذئب في الجاهلية الجهلاء، كان يتكهن، سمي سطيحا لأنه لم يكن بين مفاصله قصب يعمده، كان لا يقدر على قعود ولا قيام، وكان مسطحا على ألأرض وفيه يقول الأعشى: ما نظرت ذات أشفار كنظرتها ... يوما كما صدق الذئبي إذ سجعا 1 والسطح: ظهر البيت إذا كان مستويا، والفعل التسطيح 2 . والمسطح: شبه مطهرة ليست بمربعة. والمسطحة: الكوز ذو الجنب الواحد يتخذ للأسفار، قال 3 : فلم يلهنا استنجاء وطب ومسطح . الاستنجاء: التشمم هاهنا. والمسطح: عود من عيدان الخباء والفسطاط ونحوه، قال مالك بن عوف النضري: 4 تعرض ضيطار وخزاعة دوننا ... وما خير ضيطار يقلب مسطحا'),
(654, 'سحط', 'سحط', 'سحط', 'سحطت الشاة سحطا، وهو ذبح وحي.'),
(655, 'حسد', 'حسد', 'حسد', 'الحسد: معروف، والفعل: حسد يحسد حسدا، ويقال: فلان يحسد على كذا فهو محسود.'),
(656, 'سدح', 'سدح', 'سدح', 'السدح: ذبحك الحيوان وبسطكه على وجه الأرض، ويكون إضجاعك الشيء على الأرض سدحا، نحو القربة المملوءة المسدوحة إلى جنبك. قال أبو النجم: 1 يأخذ فيه الحية النبوحا ... ثم يبيت عنده مذبوحا مشدخ، الهامة أو مسدوحا'),
(657, 'حدس', 'حدس', 'حدس', 'الحدس: التوهم في معاني الكلام والأمور. تقول: بلغني عنه أمر فأنا أحدس فيه، أي: أقول فيه بالظن. والحدس: سرعة في السير، ومضي على طريقة مستمرة. قال 2 : كأنها من بعد سير حدس وحدس: حي من اليمن بالشام. والعرب تختلف في زجر البغل، فيقول: عدس، وبعض يقول: حدس، والحاء أصوب. ويقال: إن حدسا قوم كانوا بغالين على عهد سليمان بن داود عليهما السلام، وكانوا يعنفون على البغال، فإذا ذكروا نفرت البغال خوفا مما كانت تلقى منهم.'),
(658, 'دحس', 'دحس', 'دحس', 'الدحس: التدسيس للأمر تستبطنه وتطلبه أخفى ما تقدر عليه، ولذلك سميت دودة تحت التراب دحاسة. وهي صفراء صلبة داهية، لها رأس مشعب يشده الصبيان في الفخاخ لصيد العصافير، لا تؤذي. قال: [في الدحس بمعنى] 1 الاستيطان: 2 ويعتلون من مأى في الدحس من مأى: أي: من نم. والمأي النميمة. مأت بين القوم: نممت.'),
(659, 'سحت', 'سحت', 'سحت', 'السحت: كل حرام قبيح الذكر يلزم منه العار- نحو ثمن الكلب والخمر والخنزير. وأسحت الرجل: وقع فيه. والسحت: جهد العذاب. وسحتناهم- وأسحتنا بهم لغة- أي: بلغنا مجهودهم في المشقة عليهم. [قال] الله عز وجل: فيسحتكم بعذاب 3 . قال الفرزدق: 4 وعض زمان يا ابن مروان لم يدع ... من المال إلا مسحت أو مجلف أي: مقشر، ورجل مسحوت الجوف، أي: لا يشبع. قال: 5 يدفع عنه جوفه المسحوت أي: سحت جوفه، فنحى جوانبه عن أذى يونس عليه السلام.'),
(660, 'حسر', 'حسر', 'حسر', 'الحسر: كشطك الشيء عن الشيء. (يقال) : 1 حسر عن ذراعيه، وحسر البيضة عن رأسه، (وحسرت الريح السحاب حسرا) 2 . وانحسر الشيء إذا طاوع. ويجيء في الشعر حسر لازما مثل انحسر. والحسر والحسور: الإعياء، (تقول) 3 : حسرت الدابة وحسرها بعد السير فهي حسير ومحسورة 4 وهن حسرى، قال الأعشى: فالخيل شعث ما تزال جيادها ... حسرى تغادر بالطريق سخالها 5 وحسرت العين أي: كلت، وحسرها بعد الشيء الذي حدقت نحوه 6 ، قال: 7 يحسر طرف عينه فضاؤه وحسر حسرة وحسرا أي ندم على أمر فاته، قال مرار بن منقذ: 1 ما أنا اليوم على شيء خلا ... يا ابنه القين تولى بحسر أي بنادم. ويقال: حسر البحر عن القرار 2 وعن الساحل اذا نضب عنه الماء ولا يقال: انحسر. وانحسر الطير: خرج من الريش العتيق إلى الحديث، وحسرها إبان التحسير: ثقله لأنه فعل في مهلة وشيء بعد شيء. والجارية تنحسر 3 إذا صار لحمها في مواضعه. ورجل حاسر: خلاف الدارع، قال الأعشى: وفيلق شهباء ملمومة ... تقذف بالدارع والحاسر 4 وامرأة حاسر: حسرت عنها درعها. والحسار: ضرب من النبات يسلح 5 الإبل. ورجل محسر أي محقر مؤذى. ويقال: يخرج في آخر الزمان رجل أصحابه محسرون أي مقصون عن أبواب السلطان ومجالس الملوك يأتونه من كل أوب كأنهم قزع الخريف يورثهم الله مشارق الأرض ومغاربها.'),
(661, 'سحر', 'سحر', 'سحر', 'السحر: كل ما كان من الشيطان فيه معونة 1 . والسحر: الأخذة التي تأخذ العين. والسحر: البيان في الفطنة. والسحر: فعل السحر. والسحارة: شيء يلعب به الصبيان إذا مد خرج على لون، وإذا مد من جانب آخر خرج على لون آخر مخالف (للأول) 2 ، وما أشبهها فهو سحارة. والسحر: الغذو، كقول امرىء القيس: ونسحر بالطعام وبالشراب 3 وقال لبيد بن ربيعة العامري: فإن تسألينا: فيم نحن فإننا ... عصافير من هذا الأنام المسحر 4 وقول الله- عز وجل-: إنما أنت من المسحرين* 5 ، أي من المخلوقين. وفي تمييز العربية: هو المخلوق الذي يطعم ويسقى. والسحر: آخر الليل وتقول: لقيته سحرا وسحر، بلا تنوين، تجعله اسما مقصودا إليه، ولقيته بالسحر الأعلى، ولقيته سحرة وسحرة بالتنوين، ولقيته بأعلى سحرين، ويقال: بأعلى السحرين، وقول العجاج: غدا بأعلى سحر و [أجرسا] 1 هو خطأ، كان ينبغي أن يقول: بأعلى سحرين لأنه أول تنفس الصبح ثم الصبح، كما قال الراجز: مرت بأعلى سحرين تدأل 2 أي تسرع، وتقول: سحري هذه الليلة، ويقال: سحرية هذه الليلة، قال: في ليلة لا نحس في ... سحريها وعشائها 3 وتقول: أسحرنا كما تقول: أصبحنا. وتسحرنا: أكلنا سحورا على فعول وضع اسما لما يؤكل في ذلك الوقت. والإسحارة: بقلة يسمن عليها المال. والسحر والسحر: الرئة في البطن بما اشتملت، وما تعلق بالحلقوم، وإذا نزت بالرجل البطنة يقال: انتفخ سحره إذا عدا طوره وجاوز قدره، وأكثر ما يقال للجبان إذا جبن عن أمر 4 . والسحر: أعلى الصدر، ومنه حديث عائشة: توفي رسول الله صلى الله عليه و [على] آله وسلم- بين سحري ونحري [ 5 .'),
(662, 'حرس', 'حرس', 'حرس', 'الحرس: وقت من الدهر دون الحقب، قال: 1 أتقنه الكاتب واختاره ... من سائر الأمثال في حرسه والحرس هم الحراس والأحراس، (والفعل) 2 حرس يحرس، ويحترس أي: يحترز: فعل لازم. والأحرس هو الأصم من البنيان. وفي الحديث: أن الحريسة السرقة 3 . وحريسة الجبل: ما يسرق من الراعي في الجبال وأدركها الليل قبل أن يؤويها المأوى.'),
(663, 'سرح', 'سرح', 'سرح', 'سرحنا الإبل، وسرحت الإبل سرحا. والمسرح: مرعى السرح، والسرح من المال: ما يغدى به ويراح، والجميع: سروح، والسارح اسم للراعي، ويكون اسما للقوم الذين هم السرح نحو الحاضر والسامر وهم الجميع، قال: 4 سواء فلا جدب فيعرف جدبها ... ولا سارح فيها على الرعي يشبع والسرح: شجر له حمل وهي [الآء] 5 ، والواحدة سرحة. والسرح: انفجار البول بعد احتباسه. ورجل منسرح الثياب أي: قليلها خفيف فيها، قال رؤبة: منسرحا إلا ذغاليب الخرق 1 والسريحة: كل قطعة من خرقة متمزقة، أو دم سائل مستطيل يابس وما يشبهها، والجميع السرائح، قال: 2 بلبته سرائح كالعصيم يريد به ضربا من القطران. والسريح: سير تشد به الخدمة فوق الرسغ، قال حميد: 3'),
(664, 'حسل', 'حسل', 'حسل', 'الضب يكنى أبا حسل، والحسل: ولده، ويقال: إنه قاضي الدواب والطير، ويقال: وصف له آدم وصورته- عليه السلام-، فقال الضب: وصفتم طيرا ينزل الطير من السماء والحوت [في] الماء، فمن كان ذا جناح فليطر، ومن كان ذا حافر فليحفر. وجمعة حسلة 3 .'),
(665, 'سحل', 'سحل', 'سحل', 'السحيل: ثوب لا يبرم غزلة أي لا يفتل طاقين طاقين، تقول: سحلوه أي: لم يفتلوا سداه 1 ، والجمع السحل، قال 2 : على كل حال من سحيل ومبرم والمسحل: الحمار الوحشي، والسحيل: أشد نهيق الحمار. والسحل: نحتك الخشبة بالمسحل، أي: المبرد، ويقال له ومبرد الخشب، إذا شتمه. والمسحل: من أسماء الرجال الخطباء، واللسان، قال الأعشى: وما كنت شاحردا ولكن حسبتني ... إذا مسحل سدى لي القول أنطق 3 ومسحل يقال، اسم جني الأعشى في هذا البيت، ويريد بالمسحل المقول. والريح تسحل الأرض سحلا تكشط أدمتها. والسحالة: ما تحات من الحديد إذا برد، ومن الموازين إذا [تحاتت] 4 ، ومن الذرة والأرز إذا دق شبه النخالة. والسحل: الضرب بالسياط مما يكشط من الجلد. والمسحلان: حلقتان إحداهما مدخلة في الأخرى على طرفي شكيم الدابة، وتجمع مساحل، قال: 5 لولا شباة المسحلين اندقا وقال: 1 صدود المذاكي أفلتتها المساحل والساحل: شاطىء البحر. والإسحل: من شجر السواك. ومسحلان: اسم واد، قال النابغة: سأربط كلبي أن يريبك نبحه ... وإن كنت أرعى مسحلان وحامرا 2 وشاب مسحلان 3 : طويل حسن القامة.'),
(666, 'سلح', 'سلح', 'سلح', 'السلح: السلاح، ويقال: هذه الحشيشة تسلح الإبل تسليحا. والسلاح من عداد الحرب ما كان من حديد، حتى السيف وحده يدعى سلاحا، قال: طليح سفار كالسلاح المفرد يعني السيف وحده. والسلحة: رب خاثر يصب في النحي. والمسلحة: قوم في عدة قد وكلوا بإزاء ثغر، والجميع المسالح، والمسلحي: الواحد الموكل به. والاسليح: شجرة تغرز عليه الإبل. وسيلحين وسيلحون ونصيبين ونصيبون، كذا تسميه العرب بلغتين.'),
(667, 'حلس', 'حلس', 'حلس', 'الحلس: ما ولي البعير تحت الرحل 1 ، ويقال: فلان من أحلاس الخيل، أي في الفروسية أي كالحلس اللازم لظهر الفرس. والحلس للبيت: ما يبسط تحت حر المتاع من مسح وغيره. وحلست البعير حلسا: غشيته بحلس. وفي الحديث في الفتنة كن حلس بيتك حتى تأتيك يد خاطية أو منية قاضية 2 . وحلست السماء: أمطرت مطرا رقيقا دائما. وعشب مستحلس: ترى له طرائق بعضها فوق بعض لتراكمه وسواده. واستحلس الليل بالظلام، أي: تراكم. واستحلس السنام إذا ركبته روادف الشحم ورواكبه. والحلس (بكسر اللام) : [الشجاع الذي يلازم قرنه] 3 والحلس: أن ياخذ المصدق مكان الإبل دراهم 4 . والحلس: الرابع من القداح. والمستحلس: الذي يلزم المكان.'),
(668, 'لحس', 'لحس', 'لحس', 'اللحس: أكل الدواب 1 الصوف، وأكل الجراد الخضر والشجر ونحوه. واللاحوس: المشئوم يلحس قومه. واللحوس: الذي يتتبع الحلاوة كالذباب. والملحس: الشجاع الذي يأكل كل شيء يرتفع إليه.'),
(669, 'حسن', 'حسن', 'حسن', 'حسن الشيء فهو حسن. والمحسن: الموضع الحسن في البدن، وجمعه محاسن. وامرأة حسناء، ورجل حسان، وقد يجيء فعال نعتا، رجل كرام، قال الله- جل وعز-: مكرا كبارا 2 . والحسان: الحسن جدا، ولا يقال: رجل أحسن. وجارية حسانة. والمحاسن من الأعمال ضد المساوىء، قال الله- عز وجل-: للذين أحسنوا الحسنى وزيادة 3 أي الجنة وهي 4 ضد السوءى. وحسن: اسم رملة لبني سعد 1 . وفي أشعارهم يوم الحسن، وكتاب التحاسين، وهو الغليظ ونحوه من المصادر، يجعل اسما ثم يجمع كقولك: تقاضيب الشعر وتكاليف الأشياء.'),
(670, 'سحن', 'سحن', 'سحن', 'السحنة: لين البشرة، والناعم له سحنة. والمساحنة: الملاقاة. والسحن: دلكك خشبة بمسحن حتى تلين من غير أن يأخذ من الخشبة شيئا.'),
(671, 'نحس', 'نحس', 'نحس', 'النحس: خلاف السعد، وجمعه النحوس، من النجوم وغيرها. يوم نحس وأيام نحسات، من جعله نعتا ثقله، ومن أضاف اليوم إلى النحس خفف النحس. والنحاس: ضرب من الصفر شديد الحمرة، قال النابغة: كأن شواظهن بجانبيه ... نحاس الصفر تضربه القيون 2 والنحاس: الدخان الذي لا لهب فيه، قال: 3 يضيء كضوء سراج السليط ... لم يجعل الله فيه نحاسا والنحاس: مبلغ طبع وأصله، قال: 4 يا أيها السائل عن نحاسي ... عني ولما تبلغن أشطاسي'),
(672, 'سنح', 'سنح', 'سنح', 'سنح لي طائر وظبي سنوحا، فهو سانح إذا أتاك عن يمينك، يتيمن به، قال الشاعر: 1 أبالسنح الأيامن أم بنحس ... تمر به البوارح حين تجري وسنح لي رأي أو قريض أي: عرض. وكان في الجاهلية امرأة تقوم في سوق عكاظ فتنشد الأقوال وتضرب الأمثال وتخجل الرجال، فانتدب لها رجل، فقالت ما قالت، فأجابها فقال: أسيكتاك جامح ورامح ... كالظبيتين سانح وبارح 2 فخجلت وهربت.'),
(673, 'نسح', 'نسح', 'نسح', 'النسح والنساح: ما تحات عن التمر من قشره، وفتات أقماعه ونحوه مما يبقى في أسفل الوعاء. والمنساح: شيء يدفع به التراب ويذرى به.'),
(674, 'حسف', 'حسف', 'حسف', 'حسافة التمر: قشوره ورديئة، (تقول) 2 : حسفت التمر أحسفه حسفا: نقيته 3 .'),
(675, 'حفس', 'حفس', 'حفس', 'رجل حيفس، وامرأة حيفساء، والحيفساء إلى القصر ولؤم الخلقة.'),
(676, 'سحف', 'سحف', 'سحف', 'السحف: كشطك الشعر عن الجلد حتى لا يبقى منه شيء تقول: 4 سحفته سحفا. والسحائف، الواحدة سحيفة: طرائق الشحم التي بين طرائق الطفاطف ونحوها مما يرى من شحمة عريضة ملزقة 5 بالجلد. وناقة سحوف: كثيرة السحائف، وجمل سحوف كذلك، قال: 6 بجلهة عليان سحوف المعقب 7 والقطعة منه سحيفة وتكون سحفة. والسحاف: السل. والسحوف من الغنم: الرقيقة صوف البطن. والسيحف: النصل العريض، والجميع: السياحف.'),
(677, 'سفح', 'سفح', 'سفح', 'سفح الجبل: عرضه المضطجع، وجمعه سفوح. وسفحت العين دمعها تسفح سفحا. وسفح الدمع يسفح سفحا وسفوحا وسفحانا، قال الطرماح: سوى سفحان الدمع من كل [مسفح] 1 وسفح الدم كالصب. ورجل سفاح: سفاك للدماء. والمسافحة: الإقامة مع امرأة على فجور من غير تزويج صحيح، ويقال لابن البغي: ابن المسافحة. وقال جبريل: يا محمد ما بينك وبين آدم نكاح لا سفاح فيه. والسفيحان: جوالقان يجعلان كالخرج 2 ، قال: تنجو إذا ما اضطرب السفيحان ... نجاء هقل جافل بفيحان 3 والسفيح: من أسماء القداح.'),
(678, 'فسح', 'فسح', 'فسح', 'الفساحة: السعة في الأرض، بلد فسيح وأمر فسيح، فيه فسحة أي: سعة. والرجل يفسح لأخيه في المجلس: يوسع عليه. والقوم يتفسحون إذا مكنوا. وانفسح طرفه إذا لم يردده شيء عن بعد النظر. والفساح: من نعت الذكر الصلب 2 .'),
(679, 'فحس', 'فحس', 'فحس', 'الفحس: أخذك الشيء بلسانك وفمك من الماء ونحوه، فحسه فحسا.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(680, 'حسب', 'حسب', 'حسب', 'الحسب: الشرف الثابت في الآباء. رجل كريم الحسب حسيب، وقوم حسباء، وفي الحديث: الحسب المال، والكرم التقوى 4 . وتقول: الأجر على حسب ذلك أي على قدره، قال خالد بن جعفر للحارث بن ظالم: أما تشكر لي إذ جعلتك سيد قومك؟ قال: حسب ذلك أشكرك. وأما حسب (مجزوما) فمعناه كما تقول: حسبك هذا، أي: كفاك، وأحسبني ما أعطاني أي: كفاني. والحساب: عدك الأشياء. والحسابة مصدر قولك: حسبت حسابة، وأنا أحسبه حسابا. وحسبة أيضا 1 ، قال النابغة: وأسرعت حسبة في ذلك العدد 2 وقوله- عز وجل-: يرزق من يشاء بغير حساب* 3 اختلف فيه، يقال: بغير تقدير على أجر بالنقصان، ويقال: بغير محاسبة، ما إن يخاف أحدا يحاسبه 4 ، ويقال: بغير أن حسب المعطى أنه يعطيه: أعطاه من حيث لم يحتسب. واحتسبت أيضا من الحساب والحسبة مصدر احتسابك الأجر عند الله. ورجل حاسب وقوم حساب. والحسبان من الظن، حسب يحسب، لغتان، حسبانا، وقوله- عز وجل-: الشمس والقمر بحسبان 5 ، أي قدر لهما حساب معلوم في مواقيتهما لا يعدوانه ولا يجاوزانه. وقوله تعالى: ويرسل عليها حسبانا من السماء 6 أي نارا تحرقها. والحسبان: سهام قصار يرمى بها عن القسي الفارسية، الواحدة بالهاء. والأحسب: الذي ابيضت جلدته من داء ففسدت شعرته فصار أحمر وأبيض، من الناس والإبل وهو الأبرص، قال: 1 عليه عقيقته أحسبا عابه بذلك، أي لم يعق له في صغره حتى كبر فشابت عقيقته، يعني شعره الذي ولد معه 2 . والحسب والتحسيب: دفن الميت في الحجارة، قال: غداة ثوى في الرمل غير محسب 3 أي غير مكفن.'),
(681, 'حبس', 'حبس', 'حبس', 'الحبس والمحبس: موضعان للمحبوس، فالمحبس يكون سجنا ويكون فعلا كالحبس. والحبيس: الفرس: يجعل في سبيل الله. والحباس: شيء يحبس به نحو الحباس في [المزرفة] 4 يحبس به فضول الماء. والحباسة في كلام العجم: (المكلا) 1 ، وهي التي تسمى المزرفة، وهي الحباسات في الأرض قد أحاطت بالدبرة يحبس فيها الماء حتى يمتلىء ثم يساق إلى غيرها. واحتبست الشيء أي خصصته لنفسي خاصة. واحتبست الفراش بالمحبس أي بالمقرمة 2 .'),
(682, 'سحب', 'سحب', 'سحب', 'السحب: جرك الشيء، كسحب المرأة ذيلها، وكسحب الريح التراب. وسمي السحاب لانسحابه في الهواء. والسحب: شدة الأكل والشرب، رجل أسحوب 3 : أكول شروب. ورجل متسحب: حريص على أكل ما يوضع بين يديه.'),
(683, 'سبح', 'سبح', 'سبح', 'قوله- عز وجل- إن لك في النهار سبحا طويلا 4 ، أي: فراغا للنوم عن أبي الدقيش، ويكون السبح فراغا بالليل أيضا. سبحان الله: تنزيه لله عن كل ما لا ينبغي أن يوصف به، ونصبه في موضع فعل على معنى: تسبيحا لله، تريد: سبحت تسبيحا لله [أي: نزهته تنزيها] 5 . ويقال: نصب سبحان الله على الصرف، وليس بذاك، والأول أجود. والسبوح: القدوس، هو الله، وليس في الكلام فعول غير هذين. والسبحة: خرزات يسبح بعددها. وفي الحديث أن جبريل؟ قال للنبي صلى الله عليه وآله وسلم-: إن لله دون العرش سبعين حجابا لو دنونا من أحدها لأحرقتنا سبحات وجه ربنا يعني بالسبحة جلاله وعظمته ونوره. والتسبيح يكون في معنى الصلاة وبه يفسر قوله- عز وجل- فسبحان الله حين تمسون وحين تصبحون 1 ، الآية تأمر بالصلاة في أوقاتها، قال الأعشى: وسبح على حين العشيات والضحى ... ولا تعبد الشيطان والله فاعبدا 2 يعني الصلاة. وقوله تعالى: فلولا أنه كان من المسبحين 3 يعني المصلين. والسبح مصدر كالسباحة، سبح السابح في الماء. والسابح من الخيل: الحسن مد اليدين في الجري. والنجوم تسبح في الفلك: تجري في دورانه. والسبحة من الصلاة: التطوع.'),
(684, 'حسم', 'حسم', 'حسم', 'الحسم: أن تحسم عرقا فتكويه لئلا يسيل دمه. والحسم: المنع، والمحسوم: الذي حسم رضاعه وغذاؤه. وحسمت الأمر أي: قطعته حتى لم يظفر منه بشيء، ومنه سمي السيف حساما لأنه يحسم العدو عما يريد، أي يمنعه. والحسوم: الشؤم، تقول: هذه ليالي الحسوم تحسم الخير عن أهلها، كما حسم عن قوم عاد في قوله تعالى: ثمانية أيام حسوما 2 أي شؤما عليهم ونحسا 3 . حسم: موضع، قال: 4 وأدنى منازلها ذو حسم وحاسم: موضع. وحيسمان: اسم رجل 5 .'),
(685, 'حمس', 'حمس', 'حمس', 'رجل أحمس أي شجاع. وعام أحمس، وسنة حمساء أي شديدة، ونجدة حمساء يريد بها الشجاعة، قال 1 : بنجدة حمساء تعدي الذمرا ويقال: أصابتهم سنون أحامس لم يرد به محض النعت، ولو أراده لقال: سنون حمس، وأريد بتذكيره الأعوام. والتنور: هو الوطيس والحميس. والحمس: قريش. وأحماس العرب: أمهاتهم من قريش، وكانوا متشددين في دينهم، وكانوا شجعاء العرب لا يطاقون، وفي قيس حمس أيضا، قال: والحمس: قد تعلم يوم مأزق 2 والحمس: الجرس، قال: كأن صوت وهسها تحت الدجى ... وقد مضى ليل عليها وبغى 3 حمس رجال سمعوا صوت وحا 4 والوحى مثل الوغى.'),
(686, 'سحم', 'سحم', 'سحم', 'السحمة: سواد كلون الغراب الأسحم، أي: الأسود. والأسحم: الليل في شعر الأعشى: بأسحم داج عوض لا نتفرق 1 وفي قول النابغة: السحاب الأسود: وأسحم دان مزنه متصوب 2'),
(687, 'سمح', 'سمح', 'سمح', 'رجل سمح، ورجال سمحاء، وقد سمح سماحة وجاد بماله 3 ، ورجل مسماح مساميح، قال: 4 غلب المساميح الوليد سماحة ... وكفى قريش المعضلات وسادها وسمح لي بذلك يسمح سماحة وهو الموافقة فيما طلب. والتسميح: السرعة 5 ، والمسامحة في الطعان والضراب والعدو إذا كانت على مساهلة، قال: 6 وسامحت طعنا بالوشيج المقوم ورمح 7 مسمح: تقف حتى لان. وكذلك بعير [مسمح] 8 . ورجل مسماح أي: جواد عند السنة.'),
(688, 'مسح', 'مسح', 'مسح', 'يقال للمريض: مسح الله ما بك، ومصح أجود. ورجل ممسوح الوجه ومسيح إذا لم يبق على أحد شقي وجهه عين ولا حاجب إلا استوى. والمسيح الدجال على هذه الصفة. والمسيح عيسى بن مريم عليه السلام- أعرب اسمه في القرآن، وهو في التوراة مشيحا 1 ، قال: إذا المسيح يقتل المسيحا يعني عيسى يقتل الدجال بنيزكه. والأمسح من المفاوز كالأملس، والجميع الأماسح. والمساحة: ذرع الأرض، يقال: مسح يمسح مسحا ومساحة. والمسح: ضرب العنق تمسحه بالسيف مسحا ومنه قوله- عز وجل-: فطفق مسحا بالسوق والأعناق 2 . والتمسح والتمساح: خلق في الماء شبيه بالسلحفاة، إلا أنه ضخم طويل قوي. والماسحة: الماشطة. والمماسحة: الملاينة في المعاشرة من غير صفاء القلب. وعلى فلان مسحة من جمال، وكانت مية تتمنى لقاء 3 ذي الرمة فلما رأته استقبحته فقالت: أن تسمع بالمعيدي خير من أن تراه، فسمع ذو الرمة فهجاها فقال: على وجه مي مسحة من ملاحة ... وتحت الثياب الشين لو كان باديا 4 والمسيحة، قطعة من الفضة. والمسيحة والمسايح: ما ترك من الشعر فلم يعالج بشيء وفلان يتمسح به لفضله وعبادته.'),
(689, 'دحز', 'دحز', 'دحز', 'الدحز: الجماع.'),
(690, 'حزر', 'حزر', 'حزر', 'الحزر: حزرك الشيء بالحدس تحزره حزرا. والحازر والحزر: اللبن الحامض. والحزرة: خيار المال 2 ، قال: الحزرات حزرات النفس 3'),
(691, 'حرز', 'حرز', 'حرز', 'مكان حريز: قد حرز حرازة، والحرز: الخطر، وهو الجوز المحكوك يلعب به 4 ، وجمعه أحراز. وأخطار. والحرز: ما أحرزت في موضع من شيء، تقول: هو في حرزي. واحترزت من فلان.'),
(692, 'زحر', 'زحر', 'زحر', 'زحر يزحر زحيرا وهو إخراج النفس بأنين عند شدة ونحوها، والتزحر مثله. وزحرت المرأة بولدها، وتزحرت عنه إذا ولدت، قال: 1 إني زعيم لك أن تزحري ... عن وارم الجبهة ضخم المنخر وفلان يتزحر بماله شحا.'),
(693, 'رزح', 'رزح', 'رزح', 'رزح البعير رزوحا أي: أعيا، وبعير مرزاح ورازح وهو المعيي القائم، وإبل رزحى ومرازيح. والمرزيح: الصوت.'),
(694, 'حزل', 'حزل', 'حزل', 'الإحزئلال: الارتفاع، احزأل يحزئل في السير وفي الأرض صعدا كما يحزئل السحاب إذا ارتفع نحو بطن السماء. واحزألت الإبل: اجتمعت ثم ارتفعت على متن من الأرض في ذهابها، قال: 3 بنو جندع فاحزوزأت واحزألت والاحتزال: الاحتزام بالثوب. واحزوزأت الدجاجة على بيضها: 1 تجافت، وهذا من المضاعف.'),
(695, 'حلز', 'حلز', 'حلز', 'القلب يتحلز عند الحزن كالاعتصار فيه والتوجع. وقلب حالز، وإنسان حالز: ذو 2 حلز، ويقال: كبد [حلزة وحلزة، أي: قريحة] 3 . ورجل حلز (أي بخيل) 4 . وامرأة حلزة بخيلة.'),
(696, 'زلح', 'زلح', 'زلح', '(الزلح من قولك) : 5 قصعة زلحلحة: لا قعر لها.'),
(697, 'زحل', 'زحل', 'زحل', 'زحل الشيء: زال عن مقامه. والناقة تزحل زحلا إذا تأخرت في سيرها، قال: 6 فإن لا تغيرها قريش بملكها ... يكن عن قريش مستماز ومزحل وقال: 7 قد جعلت ناب دكين تزحل والمزحل: الموضع الذي يزحل إليه. والزحول من الإبل: التي إذا غشيت الحوض ضرب الذائد وجهها فولته عجزها (ولم تزل تزحل حتى ترد الحوض) 1 ، وربما ثبتت مقبلة، قال لبيد في زحل الشيء إذا زال عن مقامه 2 : لو يقوم الفيل أو فياله ... زل عن مثل مقامي وزحل'),
(698, 'لحز', 'لحز', 'لحز', 'رجل لحز أي شحيح النفس، وأنشد: ترى اللحز الشحيح إذا أمرت ... عليه لما له فيها مهينا) 3 والتلحز: تحلب فيك من أكل رمانة ونحوها 4 . شهوة.'),
(699, 'حزن', 'حزن', 'حزن', 'الحزن والحزن، لغتان [إذا ثقلوا فتحوا، وإذا ضحوا خففوا، يقال: أصابه حزن شديد، وحزن شديد] 5 ، ويقال: حزنني الأمر [يحزنني فأنا محزون] وأحزنني [فأنا محزن، وهو محزن] ، لغتان أيضا، ولا يقال: حازن. وروي عن أبي عمرو 6 : إذا جاء الحزن منصوبا فتحوه، وإذا جاء مكسورا مرفوعا ضموه، قال الله عز وجل-: وابيضت عيناه من الحزن 1 وقال- عز اسمه-: وأعينهم تفيض من الدمع حزنا 2 . وقوله- عز وجل-: نما أشكوا بثي وحزني إلى الله 3 . ضموا الحاء هنا لكسرة النون، كأنه مجرور في استعمال الفعل. وإذا أفردوا الصوت والأمر قالوا: أمر محزن وصوت محزن ولا يقال: حازن. والحزن من الأرض والدواب: ما فيه خشونة، والأنثى حزنة، وقد حزن حزونة. وحزانة الرجل: من يتحزن بأمره. ويسمي سفنجقانية العرب على العجم في أول قدومهم الذي استحقوا به ما استحقوا من الدور والضياع 4 حزانة 5 .'),
(700, 'زحن', 'زحن', 'زحن', 'زحن الرجل يزحن زحنا، وتزحن تزحنا أي: أبطأ عن أمره وعمله. وإذا أراد رحيلا فعرض له شغل فبطأ به قلت: له زحنة بعد. والرجل الزيحنة 6 : المتباطىء عند الحاجة تطلب إليه، قال: إذا ما التوى الزيحنة المتآزف 1'),
(701, 'نزح', 'نزح', 'نزح', 'نزحت الدار تنزح نزوحا أي بعدت. ووصل نازح أي بعيد، قال: 2 أم نازح الوصل مخلاف لشيمته ونزحت البئر، ونزحت ماءها، وبئر نزوح ونزح أي قليلة الماء، [ونزحت البئر، أي: قل ماؤها] 3 والصواب عندي: نزحت البئر أي: استقي ما فيها.'),
(702, 'نحز', 'نحز', 'نحز', 'النحز كالنخس. والنحز شبه الدق. والراكب ينحز بصدره واسط الرحل، قال ذو الرمة: إذا نحز الإدلاج ثغرة نحره ... به أن مسترخي العمامة ناعس 4 قال: والنحاز داء 5 يأخذ الإبل والدواب في رئاتها 6 ، وناقة ناحز: بها نحاز، قال القطامي: ترى منه صدور الخيل زورا ... كأن بها نحازا أو دكاعا 7 والناحز أيضا: أن يصيب المرفق كركرة البعير، فيقال: به ناحز 1 ، وإذا أصاب حرف الكركرة المرفق فحزة قيل: بها حاز، مضاعف، فإذا كان من اضطغاط عند الأبط قيل بها ضاغط. والمنحاز ما يدق به. ونحيزة الرجل: طبيعته، وتجمع: نحائز. ونحيزة الأرض كالطبة ممدودة في بطن الأرض تقود الفراسخ وأقل (من ذلك) 2 ، ويجيء في الشعر نحائز يعنى بها طبب من الخرق والأدم إذا قطعت شركا طوالا.'),
(703, 'زحف', 'زحف', 'زحف', 'الزحف جماعة يزحفون إلى عدوهم بمرة، فهم الزحف والجميع زحوف. والصبي يتزحف على الأرض قبل أن يمشي. وزحف البعير يزحف زحفا فهو زاحف إذا جر فرسنه من الاعياء، ويجمع زواحف، قال: 3 . على زواحف تزجى مخهارير وأزحفها طول السفر والازدحاف كالتزاحف.'),
(704, 'حفز', 'حفز', 'حفز', 'الحفز: [حثك] الشيء حثيثا من حلفه، سوقا أو غير سوق 1 ، قال: 2 وقد سيقت من الرجلين نفسي ... ومن جنبي يحفزها وتين أي يحثها الوتين، وهو نياط القلب، بالخروج. والرجل يحتفز في جلوسه: يريد القيام أو البطش بالشيء. والليل يحفز النهار: يسوقه، قال رؤبة: حفز الليالي أمد التدليف 3 والحوفزان من الأسماء.'),
(705, 'حزب', 'حزب', 'حزب', 'حزب الأمر يحزب حزبا إذا نابك، قال: 4 فنعم أخا فيما ينوب ويحزب وتحزب القوم: تجمعوا. وحزبت أحزابا: جمعتهم. والحزب: أصحاب الرجل على رأيه وأمره، قال العجاج 5 : لقد وجدنا مصعبا مستصعبا ... حتى رمى الأحزاب والمحزبا) 6 والمؤمنون حزب الله، والكافرون حزب الشيطان. وكل طائفة تكون أهواؤهم واحدة فهم حزب. والحيزبون: العجوز، النون زائدة كنون الزيتون. والحزباءة، ممدودة،: أرض حزنة غليظة، وتجمع حزابي، قال: 1 تحن إلى الدهنا قلوصي وقد علت ... حزابي من شأز 2 المناخ جديبا وعير حزابية في استداره خلقه، قال النابغة: أقب ككر الأندري معقرب ... حزابية قد كدمته المساحل 3 وركب حزابية، قال: 4 إن حري حزنبل حزابيه ... إذا قعدت فوقه نبابيه كالقدح المكبوب فوق الرابيه ويقال: أرادت: حزابي أي: رفع بي عن الأرض.'),
(706, 'حزم', 'حزم', 'حزم', 'المحزم: حزامة البقل، وهو الذي تشد به الحزمة، حزمه يحزمه حزما. والحزام للدابة والصبي في مهده. والمحزم: الذي يقع عليه الحزام من الصدر. والحزيم: موضع الحزام من الصدر والظهر كله ما استدار به، يقال: شد حزيمه وشمر، قال: 1 شيخ إذا حمل مكروهة ... شد الحيازيم لها والحزيم والحيزوم: وسط الصدر حيث يلتقي فيه رءوس الجوانح فوق الرهابة بحيال الكاهل، قال ذو الرمة: تكاد تنقض منهن الحيازيم 2 والحيزوم: اسم فرس جبريل 3 ع-. والحزم أيضا: ضبطك أمرك وأخذك فيه بالثقة، حزم الرجل حزامة فهو حازم ذو حزمة 4 . والحزم: ما احتزم السيل من نجوات الأرض والظهور، وجمعه حزوم.'),
(707, 'زحم', 'زحم', 'زحم', 'زحم القوم بعضهم بعضا من شدة الزحام إذا ازدحموا. والأمواج تزدحم، قال: 5 تزاحم الموج إذا الموج التطم جعل مصدر ازدحم تزاحما. والفيل والثور يكنيان أبا مزاحم. ومزاحم أو أبو مزاحم: أول خاقان ولي الترك وقاتل العرب، فقتل زمن أسد بن عبد الله القسري.'),
(708, 'مزح', 'مزح', 'مزح', 'المزاح مصدر كالممازحة، والمزاح الاسم، قال: 1 ولا تمزح فإن المزح جهل ... وبعض الشر يبدؤه المزاح مزح يمزح مزحا ومزاحا ومزاحة.'),
(709, 'زمح', 'زمح', 'زمح', 'الزومح [والزمح] : الأسود القبيح من الرجال، ويقال: الزمح الضيق الخلق 2 ، قال بعض قريش: 3 لازمحيين إذا جئتهم ... وفي هياج الحرب كالأشبل [والزماح: طائر عظيم] 4 .'),
(710, 'حمز', 'حمز', 'حمز', 'حمز اللوم فؤاده وقلبه أي: أوجعه، قال الشماخ بن ضرار: فلما شراها فاضت العين عبرة ... وفي الصدر حزاز من اللوم حامز 5 الحامز: الشديد من كل شيء. ورجل حامز الفؤاد: شديده. وقال ابن عباس: أفضل الأشياء أحمزها أي: أشدها وأمتنها 1'),
(711, 'محز', 'محز', 'محز', 'المحز: النكاح، تقول: محزها، قال جرير: محز الفرزدق أمه من شاعر 2'),
(712, 'طحر', 'طحر', 'طحر', 'الطحر: قذف العين قذاها 3 ، وطحرت العين الغمص أي رمت به، قال: 4 وناظرتين تطحران قذاهما وقال في عين الماء: 5 ترى الشريريغ يطفو فوق طاحرة ... مسحنطرا ناظرا نحو الشناغيب (يصف عين ماء تفور بالماء، والشريريغ: الضفدع الصغير، والطاحرة: العين التي ترمي ما يطرح فيها لشدة حموة مائها من منبعها وقوة فورانه، والشناغيب والشغانيب: الأغصان الرطبة، واحدها شغنوب وشنغوب، والمسحنطر: المشرف المنتصب) 1 . وقوس مطحرة: ترمي بسهمها صعدا لا تقصد إلى الرمية. والقناة إذا التوت في الثقاف فوثبت فهي مطحرة، وأما قول النابغة: مطحرة زبون 2 فإنه نعت للحرب. والطحير: شبه الزحير.'),
(713, 'طرح', 'طرح', 'طرح', 'طرحت الشيء فأنا أطرحه طرحا، والطرح: الشيء المطروح لا حاجة لأحد فيه. والطروح: البعيد نحو البلدة وما أشبهها.'),
(714, 'طلح', 'طلح', 'طلح', 'شجر أم غيلان، شوكه أحجن، من أعظم العظاه شوكا، وأصلبه عودا واجوده 3 صمغا، الواحدة طلحة. والطلح في القرآن الموز. والطلاح نقيض الصلاح، والفعل طلح يطلح طلاحا. وذو طلح: موضع: قال: 1 ورأيت المرء عمرا بطلح قال بعضهم: رأيته ينعم بنعمة، وهو غلط، إنما عمرو هذا بموضع يقال له: ذو طلح، وكان ملكا. والطلاحة: الإعياء وبعير طليح، وناقة طليح، وطلح أيضا، قال: 2 فقد لوى أنفه بمشفرها ... طلح قراشيم شاحب جسده والقرشوم: شجرة تزعم العرب أنها تنبت القردان، والقرشوم: القراد الضخم.'),
(715, 'طحل', 'طحل', 'طحل', 'الطحلة: لون بين الغبرة والبياض في سواد قليل كسواد الرماد. وشراب طاحل: ليس بصافي اللون، والفعل طحل يطحل طحلا. وذئب أطحل، ورماد أطحل. والطحال معروف. ورجل مطحول إذا ديء 3 طحاله.'),
(716, 'لطح', 'لطح', 'لطح', 'اللطح كاللطخ إذا جف ويحك لم يبق له أثر. واللطح كالضرب باليد.'),
(717, 'حلط', 'حلط', 'حلط', 'حلط فلان إذا نزل بحال مهلكة. والاحتلاط: الاجتهاد في محك ولجاجة. وأحلط الرجل بالمكان إذا أقام به، قال ابن أحمر: وأحلط هذا: لا أريم مكانيا 1'),
(718, 'طحن', 'طحن', 'طحن', 'الطحن: الطحين المطحون، والطحن الفعل، والطحانة: فعل الطحان. والطاحونة: الطحانة التي تدور بالماء. وكل سن من الأضراس طاحنة. والطحنة: دويبة كالجعل، ويجمع [على] طحن. والطحون: الكتيبة [من الخيل] تطحن كل شيء بحوافرها.'),
(719, 'حنط', 'حنط', 'حنط', 'الحنطة: البر. والحناطة: حرفة الحناط، وهو بياع البر. والحنوط: يخلط (من الطيب) 2 للميت خاصة، وفي الحديث: أن ثمودا لما أيقنوا بالعذاب تكفنوا بالأنطاع وتحنطوا بالصبر 3 .'),
(720, 'نحط', 'نحط', 'نحط', 'النحطة: داء يصيب (الخيل) 1 والإبل في صدورها، فلا تكاد تسلم منه. والنحط شبه الزفير، والقصار ينحط إذا ضرب بثوبه على الحجر، ليكون أروح له، قال الراجز: 2 ما لك لا تنحط يا فلاح ... إن النحيط للسقاة راح أي راحة. والنحاط: الرجل المتكبر، وقال النابغة: وتنحط حصان آخر الليل نحطة ... تقضب منها أو تكاد ضلوعها 3'),
(721, 'نطح', 'نطح', 'نطح', 'النطح للكباش ونحوها، وتناطحت الأمواج والسيول والرجال في الحروب. والنطيح: ما يأتيك من أمامك من الظباء والطير وما يزجر. والنطيحة: ما تناطحا فماتا، كان أهل الجاهلية يأكلونها فنهي عنها.'),
(722, 'فطح', 'فطح', 'فطح', 'الفطح: عرض في وسط الرأس، وفي الأرنبة حتى تلتزق بالوجه كالثور الأفطح، قال أبو النجم: قبصاء لم تفطح ولم تكتل 1'),
(723, 'طحف', 'طحف', 'طحف', 'الطحف: حب يكون باليمن يطبخ 2 .'),
(724, 'طفح', 'طفح', 'طفح', 'طفح النهر إذا امتلأ. والشارب طافح 3 أي ممتلىء سكرا. والريح تطفح القطنة إذا سطعت بها، قال أبو النجم: ممزقا في الريح أو مطفوحا 4 وما طفح فوق شيء فهو طفاحة كطفاح القدر.'),
(725, 'حطب', 'حطب', 'حطب', 'الحطب معروف، حطب يحطب حطبا وحطبا، المخفف مصدر، والمثقل اسم. وحطبت القوم إذا احتطبت لهم، قال: 5 وهل أحطبن القوم وهي عرية (ويقال) 1 للمخلط في كلامه وأمره: حاطب ليل، مثلا له لأنه لا يتفقد كلامه كحاطب الليل لا يبصر ما يجمع في حبله من رديء وجيد. وحطب فلان بفلان إذا سعى به. والحطب في القرآن 2 النميمة، ويقال: هو الشوك كانت تحمله فتلقيه على طريق رسول الله صلى الله عليه وآله وسلم-. ويقال للشديد الهزال حطب 3 .'),
(726, 'حبط', 'حبط', 'حبط', 'الحبط: وجع يأخذ البعير في بطنه 4 من كلأ يستوبله، (يقال) 5 : حبطت الإبل تحبط حبطا. وحبط عمله: فسد، وأحبطه صاحبه، والله محبط عمل من أشرك. و [الحبطات] 6 : حي من تميم.'),
(727, 'بطح', 'بطح', 'بطح', 'بطحته فانبطح. والبطحاء: مسيل فيه دقاق الحصى، فإن عرض واتسع سمي أبطح. والبطيحة: ماء مستنقع بين واسط والبصرة، لا يرى طرفاه من سعته، وهو مغيض دجلة والفرات، وكذلك مغايض ما بين البصرة والأهواز، والطف: ساحل البطيحة. وتبطح السيل أي: سال سيلا عريضا، قال ذو الرمة: ولا زال من نوء السماك عليكما ... ونوء الثريا، وابل متبطح وقال الراجز: إذا تبطحن على المحامل ... تبطح البط بشط الساحل 2 والبطحاء والأبطح ومنى من الأبطح 3 . ويقال: بين قرية كذا وقرية كذا بطحة 4 بعيدة.'),
(728, 'حطم', 'حطم', 'حطم', 'الحطم: كسرك الشيء اليابس كالعظام ونحوها، حطمته فانحطم، والحطام: ما تحطم منه، وقشر البيض حطام، قال الطرماح: كأن حطام قيض الصيف فيه ... فراش صميم أقحاف الشئون 5 والحطمة: السنة الشديدة. وحطمة الأسد في المال: عيثه وفرسه. [والحطمة: النار] 6 . وقيل: الحطمة: باب من جهنم. والحطيم: حجر مكة.'),
(729, 'طحم', 'طحم', 'طحم', 'طحمة السيل: دفاعه ومعظمه. وطحمة الفتنة: جولة الناس عندها، قال: 1 ترمي بنا خندف يوم الايساد ... طحمة إبليس ومرداة الراد 2'),
(730, 'محط', 'محط', 'محط', 'محطت الوتر: أمررت الأصابع عليه لتصلحه، وكذلك تمحط العقب فتخلصه، والبازي يمحط ريشه: يذهبه 3 ، وتقول: امتحط البازي 4 .'),
(731, 'طمح', 'طمح', 'طمح', 'طمح الفرس رأسه أي رفعه، وكذلك طمح يديه 5 . وطمحات الدهر: شدائده، [وربما خفف] 6 قال: 7 باتت همومي في الصدر تحضؤها ... طمحات دهر ما كنت أدرؤها وطمحت الشيء وغيره في الهواء أي رميت به تطميحا. وطمح ببصره إذا رمى به إلى الشيء. وفرس طامح البصر والطرف، قال: 8 طمحت رءوسكم لتبلغ عزنا ... إن الذليل بأن يضام جدير'),
(732, 'حمط', 'حمط', 'حمط', 'الحمطيط و [جمعه] الحماطيط، والحماط: نبت. والحماطة: حرقة يجدها الرجل في حلقه، تقول. أجد في حلقي حماطة.'),
(733, 'حدث', 'حدث', 'حدث', 'يقال: صار فلان أحدوثة أي كثروا فيه الأحاديث. وشاب حدث، وشابة حدثة: [فتية] في السن. والحدث من أحداث الدهر شبه النازلة، والأحدوثة: الحديث نفسه. والحديث: الجديد من الأشياء. ورجل حدث: كثير الحديث. والحدث: الإبداء.'),
(734, 'دحر', 'دحر', 'دحر', 'دحرته أدحره دحرا أي بعدته ونحيته. وملوما مدحورا 1 أي: مطرودا.'),
(735, 'حدر', 'حدر', 'حدر', 'الحدر: ما تحدره من علو إلى سفل، والمطاوعة منه الأنحدار، وحدرت السفينة في الماء حدورا. والحدور اسم منحدر الماء في انحطاط صببه، وكذلك الحدور في سفح جبل. وحدرت القراءة حدرا، وحدرت عيني الدمع، وانحدر الدمع. وناقة حادرة العينين أي ممتلئتهما 1 نقيا قد ارتوتا وحسنتا 2 . وكل ريان حسن الخلق حادر، وقد حدر حدارة، قال: 3 وعسير 4 أدماء حادرة العين ... خنوف عيرانة شمالال وقال: 5 أحب صبي 6 السوء من أجل أمه ... وأبغضه من بغضها وهو حادر وامرأة حدراء، ورجل أحدر. والحدرة (جزم) 7 : قرحة تخرج بباطن جفن العين (وقد) 8 حدرت عينه حدرا. ويقال: الحدر في نعت العين في حسنها خاصة مثل الحادرة، قال: 9 وأنكرت من حدراء ما كنت تعرف وحيدرة: اسم علي بن أبي طالب عليه السلام- في التوراة، وارتجز فقال: أنا الذي سمتني أمي حيدره 1 وحدر جلده يحدر حدورا أي تورم، قال: 2 لو دب ذر فوق ضاحي جلدها ... لأبان من آثارهن حدور ومنه يقال: حدرت جلده بضرب، وأحدرت لغة.'),
(736, 'ردح', 'ردح', 'ردح', 'الردح: بسطك الشيء فتسوي ظهره بالأرض، قال أبو النجم: بيت حتوف مكفأ مردوحا 3 ... شختا خفيا في الثرى مدحوحا 4 يصف القترة. ويجيء في الشعر مردح مثل مبسوط ومبسط. وناقة رداح: ضخمة العجيزة والمآكم 5 ، تقول: ردحت رداحة فهي ردوح ورداح. وكبش رداح: ضخم الألية، قال: 6 ومشى الكمأة إلى الكماة ... وقرب الكبش الرداح وكتيبة رداح: ململمة كثيرة الفرسان 7 .'),
(737, 'حرد', 'حرد', 'حرد', 'الحرد مصدر الأحرد الذي إذا مشى رفع قوائمه رفعا شديدا ويضعها مكانها من شدة قطافته في الدواب وغيرها. وحرد الرجل فهو أحرد إذا ثقلت 1 عليه درعه فلم يستطع الانبساط في المشي، قال: إذا ما مشى في درعه غير أحرد والحرد والحرد لغتان، يقال: حرد فهو حرد إذا اغتاظ فتحرش بالذي غاظه وهم به فهو حارد، قال: 3 أسود شرى لاقت أسود خفية ... تساقين سما، كلهن حوارد وقطا حرد أي سراع، قال: 4 بادرت حردا من قطاها النامي وقول الله جل ذكره: وغدوا على حرد قادرين 5 ، أي على جد من أمرهم. وحرد السير إذا لم يستو قطعه. والحردية: حياصة الحظيرة التي تشد على حائط من قصب عرضا (تقول) 6 : حردناه تحريدا، ويجمع على حرادي. وحي حريد: (الذي) 1 ينزل منزلا من جماعة القبيلة لا يخالطهم في ارتحاله وحلوله. والحرد: قطعة من سنام 2 . والمحاردة: انقطاع اللبن من المواشي والإبل، وناقة محارد: شديدة الحراد. والحرد: القصد، قال: 3 أقبل سيل جاء من أمر الله ... يحرد حرد الجنة المغلة'),
(738, 'حدل', 'حدل', 'حدل', 'الأحدل: ذو الخصية الواحدة من كل شيء، ويقال لمائل الشقين أيضا. والحودل: المذكر من القردان. وبنو حدال: حي نسبوا إلى محلة [كانوا ينزلونها] 4 . والتحادل: الانحناء على القوس.'),
(739, 'دحل', 'دحل', 'دحل', 'الدحل: مدخل تحت الجرف أو في عرض جنب 1 البئر في أسفلها، أو نحوه من المناهل والموارد، ورب بيت من بيوت الأعراب يجعل له دحل تدخل المرأة فيه إذا دخل عليهم داخل، وجمعه دحلان وأدحال، قال: 2 دحل أبي المرقال خير الأدحال والداحول وجمعه دواحيل: خشبات على رءوسها خرق كأنها طرادات قصار، تركز في الأرض لصيد الحمر 3 . والدحل: [ال] عظيم البطن، ويقال: الخداع.'),
(740, 'لحد', 'لحد', 'لحد', 'اللحد: ما حفر في عرض القبر، وقبر ملحد، ويقال: ملحود، ولحدوا لحدا، قال ذو الرمة: أناسي ملحود لها في الحواجب 4 شبه إنسان العين تحت الحاجب باللحد، حين غارت عيون الإبل من تعب السير. والرجل يلتحد إلى الشيء: يلجأ إليه ويميل، يقال: ألحد إليه ولحد إليه بلسانه أي: مال، ويقرأ: لسان الذي يلحدون ويلحدون 5 . وألحد في الحرم، (ولا يقال: لحد) 1 إذا ترك القصد ومال إلى الظلم، ومنه قوله تعالى: من يرد فيه بإلحاد 2 يعني في الحرم، قال حميد الأرقط: 3 لما رأى الملحد حين ألحما ... صواعق الحجاج يمطرن دما 4'),
(741, 'دلح', 'دلح', 'دلح', 'دلح البعير فهو دالح إذا تثاقل في مشيه من ثقل الحمل. والسحابة تدلح في سيرها من كثرة مائها، كأنما 5 تنخزل انخزالا، قال: 6 بينما نحن مرتعون بفلج ... قالت الدلح الرواء أنيه 7 . أي صبي وافعلي.'),
(742, 'ندح', 'ندح', 'ندح', 'الندح: السعة والفسحة، [تقول] 1 : إنه لفي ندحة من الأمر ومندوحة منه. وأرض مندوحة: بعيدة واسعة، قال 2 : إذا علا دويه المندوحا ويقال لعظيم البطن: انداح بطنه واندحى. والندح في قول العجاج الكثرة حيث يقول: صيدا تسامي ورما رقابها ... بندح وهم قطم قبقابها 3'),
(743, 'دحن', 'دحن', 'دحن', 'الدحن: العظيم البطن، والدحنة: الكثير اللحم، وقد دحن دحنا. وقيل لابنة الخس: أي الإبل خير؟ قالت: خير الإبل الدحنة الطويل الذراع القصير الكراع وقلما تجدنه.'),
(744, 'حفد', 'حفد', 'حفد', 'الحفد: الخفة في العمل والخدمة 1 ، قال: حفد الولائد بينهن وأسلمت ... بأكفهن أزمة الأجمال 2 وسمعت في شعر محدث حفدا أقدامها 3 أي سراعا خفافا. وفي سورة القنوت: وإليك نسعى ونحفد 4 أي نخف في مرضاتك. والاحتفاد: السرعة في كل شيء، قال الأعشى: ومحتفد الوقع ذو هبة ... أجاد جلاه يد الصيقل وقول الله- عز وجل-: بنين وحفدة 5 يعني البنات [و] هن خدم الأبوين في البيت، ويقال: الحفدة: 6 وعند العرب الحفدة الخدم. والمحفد: شيء يعلف فيه، قال: 7 وسقيي وإطعامي الشعير بمحفد 8 والحفدان فوق المشي كالخبب. والمحافد: وشي الثوب، الواحد محفد.'),
(745, 'فدح', 'فدح', 'فدح', 'الفدح: إثقال الأمر والحمل، وصاحبه مفدوح، تقول: نزل بهم أمر فادح، قال الطرماح: فمثلك ناحت عليه النساء ... لعظم مصيبتك الفادحه 1'),
(746, 'حدب', 'حدب', 'حدب', 'الحدبة: موضع الحدب من ظهر الأحدب، والاسم: الحدبة، وقد حدب حدبا واحدودب ظهره. وحدب فلان على فلان حدبا أي عطف عليه وحنا، وإنه كالوالد. والحدب: حدور في صبب 2 ، ومن ذلك (حدب الريح) 3 وحدب الرمل، وجمعه حداب، ومنه قوله تعالى: وهم من كل حدب ينسلون 4 . ويقال للدابة إذا بدت حراقيفه 5 وعظم ظهره حدباء وحدبير وحدبار. والحداب: ما ارتفع من الأرض، الواحدة حدبة وحدبة وحدبة، قال ذو الرمة: ويوم يظل الفرخ في بيت غيره ... له كوكب فوق الحداب الظواهر 1'),
(747, 'دبح', 'دبح', 'دبح', 'التدبيح: تنكيس الرأس في المشي، قال: 2 كمثل ظباء دبحت في مغارة ... وألجأها فيها قطار وراضب 3 أي قاطر، ويروى: ناطف.'),
(748, 'بدح', 'بدح', 'بدح', 'البدح: ضربك شيئا 4 بشيء فيه رخاوة كما تأخذ بطيخة فتبدح بها إنسانا. وتقول: ورأيتهم يتبادحون بالكرين والرمان ونحوها عبثا يعني رميا. وبدحت المرأة وتبدحت، وهو جنس من مشيها.'),
(749, 'حدم', 'حدم', 'حدم', 'الحدم: شدة إحماء الشيء بحر 5 الشمس والنار، تقول: حدمه كذا فاحتدم. والحدم: التزيد في الجري، وتقول إذا [أوزعتها] 1 بتحريك الساق: واحتدمت جريا) ، قال الأعشى: وإدلاج ليل على غرة ... وهاجرة حرها محتدم 2'),
(750, 'دحم', 'دحم', 'دحم', 'دحم ودحمان من اسمان 3 ، والدحم: النكاح، دحمها يدحمها دحما.'),
(751, 'مدح', 'مدح', 'مدح', 'المدح: نقيض الهجاء و [هو] حسن الثناء. والمدحة اسم المديح، وجمعه مدائح ومدح، يقال: مدحته وامتدحته.'),
(752, 'حمد', 'حمد', 'حمد', 'الحمد: نقيض الذم، يقال: بلوته فأحمدته أي وجدته حميدا محمود الفعال. وحمدته على ذلك، ومنه المحمدة. وحماداك أن تفعل كذا أي: [حمدك] 4 ، وحماداك أن تنجو من فلان رأسا برأس. والتحميد: كثرة حمد الله بحسن المحامد. وأحمد الرجل: أي: فعل فعلا يحمد عليه، قال الأعشى: وأحمدت إذ نجيت بالأمس صرمة ... لها غددات واللواحق تلحق 5 والحمد: الثناء. وخمسة من الأنبياء ذوو 1 اسمين: أحمد ومحمد صلى الله عليه وعلى آله وسلم- وعيسى والمسيح، وذو الكفل وإلياس، وإسرائيل ويعقوب، ويونس وذو النون عليهم السلام وعلى غيرهم من أنبيائه- 2 . وقولهم: أحمد إليك الله أي: معك، ويقال: إنما هو كقولك: أشكو إليك. وقوله: إني أحمد إليكم غسل الإحليل، أي أرضى لكم ذلك.'),
(753, 'حتر', 'حتر', 'حتر', 'الحتر: الذكر من الثعالب 3 ، والحتار: ما استدار بالعين من الجفن 4 من باطن. وما يحيط بالظفر حتار، و [كذلك] ما يحيط بالخباء، وكذلك حلقة الدبر. وأراد أعرابي مجامعة أهله، فقالت: إني حائض، فقال: أين الهنة الأخرى؟ قالت: اتق الله 5 ، فقال: بلى 1 ورب البيت والأستار ... لأهتكن حلق الحتار قد يؤخذ الجار بظلم الجار والمحتر من الرجال: الذي لا يعطي خيرا ولا يفضل على أحد، [إنما هو كفاف بكفاف لا ينفلت منه شيء] 2 ، ويقال: قد أحتر على نفسه وأهله أي: ضيق عليهم ومنعهم خيره.'),
(754, 'حرت', 'حرت', 'حرت', 'حرت [الشيء] 3 حرتا أي: قطعه مستديرا كله كالفلكة 4 . والمحروت: أصول الأنجذان.'),
(755, 'ترح', 'ترح', 'ترح', 'الترح: ضد الفرح 5 ، قال سليمان 6 : وما فرحة إلا ستعقب ترحة ... وما عامر إلا وشيكا سيخرب والمتراح: الناقة التي يسرع انقطاع لبنها، وتجمع: متاريح.'),
(756, 'لتح', 'لتح', 'لتح', 'اللتح: ضرب الوجه والجسد بالحصى (حتى) 1 تؤثر فيه من غير جرح شديد، قال أبو النجم يصف العانة حين يطردها الفحل: يلتحن وجها بالحصى ملتوحا ... ومرة بحافر مكتوحا 2'),
(757, 'حلت', 'حلت', 'حلت', 'الحلتيت: [الأنجذان] 3 ، قال: 4 عليك بقنأة وبسندروس ... وحلتيت وشيء من كنعد'),
(758, 'نحت', 'نحت', 'نحت', 'النحت نحت النجار الخشب، يقال: نحت ينحت، وينحت لغة 5 . وجمل نحيت: قد انتحتت 1 مناسمه، قال: 2 وهو من الأين حف نحيت 3 والنحاته: ما انتحتت من الشيء من الخشب ونحوه 4 . وتقول في النكاح: نحتها نحتا.'),
(759, 'حتن', 'حتن', 'حتن', '(الحتن من قولك) 5 : تحاتنت دموعه إذا تتابعت، وعبرة متحاتنة، قال الطرماح: كأن العيون المرسلات عشية ... شآبيب دمع العبرة المتحاتن 6 وتحاتنت الخصال في النصال إذا وقعت خصلات في أصل القرطاس، والخصلة: كل رمية لزقت بالقرطاس من غير أن تصيبه. وإذا تصارع رجلان فصرع أحدهما وثب ثم قال: 7 الحتنى 8 لا خير في سهم زلج قوله: الحتنى أي: عاود الصراع، والزلج: الباطل، وهو الذي يقع بالأرض ثم يصيب القرطاس. والتحاتن: التباري، قال النابغة: شمال تجاريها 1 الجنوب بقرضها ... وريح الصبامور الدبور تحاتن'),
(760, 'نتح', 'نتح', 'نتح', 'النتح: خروج العرق من أصول الشعر، وقد نتحه الجلد، ومناتح العرق: مخارجه من الجلد، قال أبو النجم: جون كأن العرق المنتوحا ... لبسه القطران والمسوحا 2'),
(761, 'حتف', 'حتف', 'حتف', 'الحتف: الموت وقضاؤه، (ويقال) : مات فلان حتف أنفه أي: بلا ضرب ولا قتل، ويجمع على حتوف. ولا يقال: حتف فلان، ولا حتف نفسه 3 .'),
(762, 'تحف', 'تحف', 'تحف', 'التحفة [أبدلت التاء فيها من الواو] 4 إلا أن هذه التاء تلزم في التصريف كله، إلا في يتفعل كقولهم 5 : يتوحف، ويقولون: أتحفته تحفة يعني طرف الفواكه.'),
(763, 'فتح', 'فتح', 'فتح', 'الفتح: نقيض الإغلاق. والفتح: افتتاح دار الحرب. والفتح: أن تفتح على من يستقرئك. والفتح: أن تحكم بين قوم يختصمون إليك، قال تعالى: ربنا افتح بيننا وبين قومنا بالحق 1 . والفتح: النصرة، قال تعالى: إن تستفتحوا فقد جاءكم الفتح 2 . واستفتحت الله على فلان أي: سألته النصر عليه ونحو ذلك. والمفتح: الخزانة، ولكل شيء مفتح، ومفتح بالفتح والكسر، من صنوف الأشياء. والفتاح: الحاكم. وقوله تعالى: ما إن مفاتحه لتنوأ بالعصبة 3 يعني الكنوز وصنوف أمواله، فأما المفاتيح فجمع المفتاح الذي يفتح به المغلاق. والفتحة: تفتح الإنسان بما عنده من أموال أو أدب يتطاول به، يقال: ما هذه الفتحة التي أظهرتها، وتفتحت بها علينا. وفواتح القرآن: أوائل السور. وافتتاح الصلاة: التكبيرة الأولى. وباب فتح أي: واسع.'),
(764, 'حفت', 'حفت', 'حفت', 'الحفت: الهلاك، تقول: حفته الله ولفته أي أهلكه ودق عنقه 4 . ورجل [حفيتأ] 1 ، مهموز غير ممدود، إلى القصر ولؤم الخلقة.'),
(765, 'تفح', 'تفح', 'تفح', 'التفاح: فاكهة، الواحدة تفاحة.'),
(766, 'بحت', 'بحت', 'بحت', 'خمر بحت، وخمور بحتة، وللتذكير بحت لا يثنى ولا يجمع ولا يصغر. (والبحت: الشيء الخالص معهما'),
(767, 'حتم', 'حتم', 'حتم', 'الحتم: إيجاب القضاء، والحاتم: القاضي، قال أمية: 2 حناني ربنا، وله عنونا ... بكفيه المنايا والحتوم. والحاتم: الغراب الأسود، ويقال: بل غراب البين، أحمر المنقار والرجلين. والحتامة: ما يبقى على الخوان من سقاط الطعام. والتحتم: أن تأكل شيئا فكان في فيك هشا.'),
(768, 'تحم', 'تحم', 'تحم', 'الأتحمي: ضرب من البرود، قال: 1 أمسى كسحق الأتحمي أرسمه'),
(769, 'متح', 'متح', 'متح', 'المتح: جذبك الرشاء تمد بيد وتأخذ بيد على رأس البئر. والإبل تمتح في سيرها، أي: تراوح بأيديها وتتمتح، قال: 2 ماتح سجل مدفق غروف وقال ذو الرمة: لأيدي المهارى خلفها متمتح 3 وفرس متاح أي مداد. وبينهم وبيننا كذا فرسخا متحا أي مدا.'),
(770, 'حمت', 'حمت', 'حمت', 'الحميت: وعاء السمن كالعكة، وجمعه: حمت، ويقال: هو الزق.'),
(771, 'حظر', 'حظر', 'حظر', 'الحظار: حائط الحظيرة، والحظيرة تتخذ من خشب أو قصب، والمحتظر: [ال] متخذها لنفسه، فإذا لم تخصه بها فهو محظر، ويقال: حاظر من حظر، خفيف. وكل من حظر بينك وبين شيء فقد حظره عليك، قال الله تعالى: وما كان عطاء ربك محظورا 1 أي ممنوعا، وكل شيء حجز بين شيئين فهو حجاز وحظار 2 .'),
(772, 'حظل', 'حظل', 'حظل', 'الحظل: المقتر، قال: 3 فما يخطئك لا يخطئك منه ... طبانية فيحظل أو يغار وبعير حظل إذا كان يأكل الحنظل، يحذفون النون، ويقال: هي زائدة، ويقال: هي أصلية، والبناء رباعي ولكنها أحق بالطرح، لأنها أخف الحروف، وهم الذين يقولون: قد أسبل الزرع، بطرح النون، من السنبل، ولغة أخرى: سنبل الزرع. والحاظل: الذي يمشي في شقة 4 من شكاة، [تقول: مر بنا يحظل ظالعا.'),
(773, 'لحظ', 'لحظ', 'لحظ', 'اللحاظ: مؤخر العين، واللحظة: النظرة من جانب الأذن، [ومنه قول الشاعر: فلما تلته الخيل وهو مثابر ... على الركض يخفي لحظة ويعيدها] 1'),
(774, 'حفظ', 'حفظ', 'حفظ', 'الحفظ: نقيض النسيان، وهو التعاهد وقلة الغفلة، والحفيظ: الموكل بالشيء يحفظه. والحفظة جمع الحافظ، وهم الذين يحصون أعمال بني آدم من الملائكة 2 . والاحتفاظ: خصوص الحفظ، تقول: احتفظت به لنفسي، واستحفظته كذا، أي: سألته أن يحفظه عليك 3 . والتحفظ: قلة الغفلة حذرا من السقطة في الكلام والأمور. والمحافظة: المواظبة على الأمور من الصلوات 4 والعلم ونحوه. والحفاظ: المحافظة على المحارم ومنعها عند الحروب، والاسم منه الحفيظة، يقال: هو ذو حفيظة. وأهل الحفائظ: المحامون من وراء إخوانهم، متعاهدون لأمورهم، مانعون لعوراتهم، قال: 5 إنا أناس نلزم الحفائظا ... إذ كرهت ربيعة الكظائظا والحفظة مصدر الاحتفاظ عند ما يرى من حفيظة الرجل، تقول: أحفظته فاحتفظ حفظة أي أغضبته، قال العجاج: وحفظة أكنها ضميري 1 يفسرونه: على غضبة أجنها ضميري. وتقول: احفاظت الجيفة أي: انتفخت 2 .'),
(775, 'حذر', 'حذر', 'حذر', 'الحذر مصدر قولك: حذرت أحذر حذرا فأنا حاذر وحذر. وتقرأ الآية وإنا لجميع حاذرون 3 أي مستعدون، ومن قرأ: حذرون فمعناه: إنا نخاف شرهم. وأنا حذيرك منه أي أحذركه 4 . وحذار يا فلان أي: احذر، قال: 5 حذار من أرماحنا حذار جرت للجزم الذي في الأمر، وأنثت لأنها كلمة، يقال: سمعت حذار في عسكرهم ودعيت نزال بينهم. وحذار: اسم أبي ربيعة قاضي العرب في الجاهلية، وكان من بني أسد بن خزيمة.'),
(776, 'ذرح', 'ذرح', 'ذرح', 'الذرحرحة: واحدة من الذراريح، ويقال: ذريحة لواحدة، ويقال: طعام مذروح، وهو شيء أعظم من الذباب قليلا، مجزع مبرقش بحمرة وسواد وصفرة، لها جناحان تطير بهما، وهو سم قاتل، فإذا أرادوا كسر (حد) سمه خلطوه بالعدس فيصير دواء لمن عضه الكلب [الكلب] 1 . وبنو ذريح: حي من العرب. والذرح: شجرة يتخذ منها الرحالة.'),
(777, 'حذل', 'حذل', 'حذل', 'الحذل (مثقل) : حمرة في العين، تقول: حذلت عينه حذلا، وعيون حذل في قوله: 2 ما بال دمع عينك المهلل ... والشوق شاج للعيون الحذل يصفها كأن تلك الحمرة تعتريها من شدة النظر إلى ما أعجبت به'),
(778, 'ذحل', 'ذحل', 'ذحل', 'الذحل: طلب مكافأة بجناية [جنيت عليك] 3 ، أو عداوة أتيت إليك.'),
(779, 'حنذ', 'حنذ', 'حنذ', 'الحنذ: اشتواء اللحم المحنوذ بالحجارة المسخنة، تقول: أنا أحنذه حنذا، قال العجاج: 1 ورهبا من حنذه أن يهرجا يعني الحمران يحنذها حر الشمس على الحجارة. قال أبو أحمد: 2 الحنذ مصدر، والحنيذ والحنذ 3 اسمان للحم، وقد يسمى الشيء بالمصدر، إلا أن هذا لم يرد به المصدر، وقوله تعالى: فما لبث أن جاء بعجل حنيذ 4 أي: مشوي. [حذن: الحذنتان: الأذنان] 5'),
(780, 'حذف', 'حذف', 'حذف', 'الحذف: قطف الشيء من الطرف كما يحذف طرف ذنب الشاة والمحذوف: الزق، قال الأعشى: قاعدا حوله الندامى فما ينفك ... يؤتى بموكر محذوف 1 والحذف: الرمي عن جانب والضرب عن جانب. وتقول: حذفني فلان بجائزة أي: وصلني. وحذفه بالسيف: على ما فسرته من الضرب عن جانب. والحذف: ضرب من الغنم السود الصغار، واحدها حذفة. وفي الحديث: لا يتخللكم الشيطان كأولاد الحذف 2 قال الشاعر: 3 فأضحت الدار قفرا لا أنيس بها ... إلا القهاد مع القهبي والحذف'),
(781, 'ذبح', 'ذبح', 'ذبح', 'الذبح: قطع الحلقوم من باطن عند النصيل، وموضعه المذبح. والذبيحة: الشاة [المذبوحة. والذبح: ما أعد للذبح وهو بمنزلة الذبيح والمذبوح] 4 . والمذبح: السكين الذي يذبح به. والذابح: شعر ينبت بين النصيل والمذبح. والذبحة: داء يأخذ في الحلق وربما قتل. والذبح، والذباح، لغة: نبات من السم بالفارسية: سعن، قال العجاج: يسقيهم من خلل الصفاح ... كأسا من الذيفان والذباح 1 والذبح: نبات له أصل يقشر عنه قشر أسود فيخرج أبيض كأنه جزرة، حلو (طيب) 2 يؤكل، والواحدة ذبحة. ويقال: أخذه الذباح، وهو تشقف بين أصابع الصبيان من التراب. والذابح: كوكب، يقال له: سعد الذابح من منازل القمر فإذا طلع الذابح انجحر النابح.'),
(782, 'حبذ', 'حبذ', 'حبذ', 'حبذا، أي: أحبب بهذا. قال أبو أحمد: أصلها حبب ذا فأدغمت الباء الأولى في الثانية ورمي بضمتها.'),
(783, 'حذم', 'حذم', 'حذم', 'الحذم: القطع الوحي، تقول: حذم يحذم. وسيف حذيم أي: حاذم قاطع. وحذام: اسم امرأة، قال: 1 [إذا قالت حذام فصدقوها] ... فإن القول ما قالت حذام جرتها العرب في موضع الرفع والنصب، وكذلك فجار وفساق وخباث، ولم يلقوا عليها صرف الكلام لأنه نعت مؤنث معدول عن جهته، وهي حاذمة وفاجرة وفاسقة وخبيثة، فلما صرف إلى فعال كسرت أواخر الحروف، لأنهم وجدوا أكثر حالات المؤنث الكسر، كقولهم: أنت، عليك، إليك. وفيه قول آخر، يقال: لما صرف عن جهته حمل على إعراب الأصوات والحكايات والزجر ونحوه مجرورا كما تقول في زجر البعير: ياه ياه، إنما هو تضاعف ياه مرتين، قال: 2 ينادي بيهياه وياه كأنه ... صويت الرويعي ضل بالليل صاحبه يقول: لما سكن الحرف الذي قبل الحرف الأخير حركت آخره بكسرة، وإذا تحرك الحرف قبل الحرف الآخر وسكن الأخير جزمت كقولك: بجل وأجل. وأما حسب وجير فكسرت الآخر وحركت لسكون السين والياء: 3'),
(784, 'مذح', 'مذح', 'مذح', 'مذح الرجل، ومذحت فخذاه، [مذحا] 4 وهو التواء فيهما إذا مشى انسحجت إحداهما بالأخرى، قال حسان: 1 . إنك لو صاحبتنا مذحت ... وحكك الحنوان فانفشحت'),
(785, 'حرث', 'حرث', 'حرث', 'الاحتراث من الزرع، ومن كسب المال، قال: ومن يحترث حرثي وحرثك يهزل 2 والإحراث: هزل الخيل، يقال: أحرثنا الخيل، وحرثناها لغة. والمحراث من الحديد كهيئة المسحاة تحرك بها النار، ومحراث الحرب: ما يهيجها، قال رؤبة: ولوا ومحراث الوغى عنيف 3 والحرث: قذفك الحب في الأرض.'),
(786, 'حثل', 'حثل', 'حثل', 'الإحثال: سوء الرضاع، تقول: أحثلته أمه. ويكون يحثله الدهر بسوء الحال، قال العجاج: ولم تنبت في الجراء المحثل 1 وقال:'),
(787, 'حنث', 'حنث', 'حنث', 'الحنث: الذنب العظيم، ويقال: بلغ [الغلام] 3 الحنث أي بلغ مبلغا جرى عليه القلم في المعصية والطاعة. والحنث إذا لم يبر بيمينه، وقد حنث يحنث.'),
(788, 'حفث', 'حفث', 'حفث', 'الحفثة: ذات الطرائق 4 من الكرش كأنها أطباق، وفيها الفرث، قال: 5 لا تكرين بعدها خرسيا ... إنا وجدنا لحمه رديا الكرش والحفثة والمريا والحفاث: ضرب من الحيات يأكل الحشيش لا يضر شيئا. ويقال للغضبان إذا انتفخت أوداجه غضبا قد احرنفش حفاثه.'),
(789, 'بحث', 'بحث', 'بحث', 'البحث: طلبك شيئا في التراب، وسؤالك مستخبرا، تقول: أستبحث عنه وأبحث 1 ، وهو يبحث بحثا. والبحوث من الإبل التي إذا سارت بحثت التراب بأيديها أخرا ترمي به إلى خلفها.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(790, 'رحل', 'رحل', 'رحل', 'الراحلة: المركب من الإبل ذكرا كان أو أنثى. ورحلت بعيري أرحله رحلا، وارتحل البعير رحلة 2 أي سار فمضى. ثم جرى في المنطق حتى يقال: ارتحل القوم. والرحيل: اسم الارتحال للمسير، [والمرتحل: نقيض المحل، قال الأعشى: إن محلا وإن مرتحلا يريد: إن ارتحالا وإن حلولا. وقد يكون المرتحل اسم الموضع الذي تحل فيه] 2 . وترحل القوم: وهو ارتحال في مهلة. ورحل الرجل: منزله ومسكنه، يقال: إنه لخصيب الرحل. ورحلته بمكروه أرحله أي: ركبته بها. والمرحل: ضرب من برود اليمن، سمي به لأن عليه تصاوير رحل وما يشبهه 3 . وقال في المرحل 4 : على أثرينا ذيل مرط مرحل والعرب تقذف أحدهم وتكنى فتقول: يا ابن ملقى أرحل الركبان. (وراحيل 5 : اسم أم يوسف- عليه السلام) 6 .'),
(791, 'حرن', 'حرن', 'حرن', 'حرنت الدابة، وحرنت لغة، فهي تحرن حرانا، وهي حرون. وفي الحديث: ما خلأت ولا حرنت (ولكن حبسها حابس الفيل) 1 . [ويقال: فرس حرون من خيل حرن. والحرون: اسم فرس كان لباهلة، إليه تنسب الخيل الحرونية] 2 .'),
(792, 'رنح', 'رنح', 'رنح', 'رنح فلان ترنيحا إذا اعتراه وهن في عظامه وضعف في جسده عند ضرب أو فزع يغشاه كالميد 3 ، قال: 4 تميد إذا استعبرت ميد المرنح والمرنح: ضرب من العود من أجوده يستجمر 5 به.'),
(793, 'حنر', 'حنر', 'حنر', 'الحنورة: دويبة دميمة 6 يشبه بها الإنسان فيقال: يا حنورة. وفي الحديث: لو صليتم حتى تكونوا كالأوتاد 1 أو صمتم حتى تكونوا كالحنائر ما نفعكم إلا بنية صادقة وورع صادق. والحنيرة: العقد المضروب وليس بذاك العريض، تقول: حنرت حنيرة إذا بنيتها. والحنيرة: مندفة النساء للقطن.'),
(794, 'نحر', 'نحر', 'نحر', 'إذا تشاح القوم على أمر قيل: انتحروا وتناحروا من شدة حرصهم. وهذه الدار تنحر تلك الدار إذا استقبلتها. وإذا انتصب الانسان في صلاته فنهد قيل: قد نحر. (واختلفوا في تفسير قوله تعالى: فصل لربك وانحر 2 ، قال بعضهم: انحر البدن، ويقال: هو وضع اليمين على الشمال في الصلاة) 3 . ويوم النحر: يوم الأضحى. والنحر: ذبحك البعير بطعنة في النحر، حيث يبدو الحلقوم من أعلى الصدر، ونحرته أنحره نحرا.'),
(795, 'حرف', 'حرف', 'حرف', 'الحرف من حروف الهجاء. وكل كلمة بنيت أداة عارية في الكلام لتفرقة المعاني تسمى حرفا، وإن كان بناؤها بحرفين أو أكثر مثل حتى 1 وهل وبل ولعل. وكل كلمة تقرأ على وجوه من القرآن تسمى حرفا، يقال: يقرأ هذا الحرف في حرف ابن مسعود أي في قراءته. (والتحريف في القرآن تغيير الكلمة عن معناها وهي قريبة الشبه، كما كانت اليهود تغير معاني التوراة بالأشباه، فوصفهم الله بفعلهم فقال: يحرفون الكلم عن مواضعه* 2 ) 3 . وتحرف فلان عن فلان وانحرف، واحرورف واحد، أي: مال. والانسان يكون على حرف من أمره كأنه ينتظر ويتوقع فإن رأى من ناحية ما يحب؟ 4 وإلا مال إلى غيرها. وحرف السفينة: جانب شقها. والحرف: الناقة الصلبة تشبه بحرف الجبل، قال الشاعر: 5 جمالية حرف سناد يشلها ... وظيف أزج الخطو ريان سهوق وهذا نقض على من قال: ناقة حرق، أي:] 6 مهزولة كحرف كتابة لدقتها ولو كان [معنى] الحرف مهزولا لم يصفها بأنها جمالية سناد، ولا وظيفها ريان. والحرف: حب كالخردل، والحبة منه حرفة. والمحارفة: المقايسة بالمحراف، وهو الميل تسبر به الجراحات. والمحارف: المحروم المدبر.'),
(796, 'حفر', 'حفر', 'حفر', 'الحفيرة: الحفرة في الأرض، والحفر اسم المكان الذي حفر كخندق أو بئر، قال: 1 قالوا انتهينا وهذا الخندق الحفر والبئر إذا كانت فوق قدرها سميت حفرا (وحفيرا وحفيرة) 2 . وحفير وحفيرة اسما موضعين جاءا 3 في الشعر. والحافر: الدابة. وقول العرب: النقد عند الحافر 4 ، تقول: إذا اشتريته لا تبرح حتى تنقد. وإذا أعموا اسم الدواب قالوا: الحافر خير من الظلف أي ذوات الحوافر خير من ذوات الظوالف 5 . والحافرة: العودة في الشيء حتى يرد آخره على أوله، وفي الحديث: إن هذا الأمر لا يترك على حاله حتى يرد على حافرته أي على أول تأسيسه. وقوله تعالى: إنا لمردودون في الحافرة 6 أي في الخلق الأول بعد ما نموت كما كنا. والحفر، والحفر لغة،: ما يلزق بالأسنان من ظاهر وباطن، تقول: حفرت أسنانه حفرا، ولغة أخرى: حفرت تحفر حفرا. والحفراة: نبت من نبات الربيع. والحفراة: خشبة ذات أصابع تذرى بها الكدوس المدوسة، وينقى بها البر بلغة ناس من أهل اليمن.'),
(797, 'فرح', 'فرح', 'فرح', 'رجل مفرح: أثقله الدين، قال: 1 إذا أنت لم تبرح تؤدي أمانة ... وتحمل أخرى أفرحتك الودائع ورجل فرحان وفرح من الفرح، وامرأة فرحة وفرحى مثل عطشى، وتقول: ما يسرني به مفرح ومفروح. فالمفروح: الشيء أنا أفرح به، والمفرح: الشيء الذي يفرحني.'),
(798, 'حرب', 'حرب', 'حرب', 'الحرب: نقيض السلم، تؤنث، وتصغيرها حريب رواية عن العرب، ومثلها ذريع 2 وفريس وقريس أنثى، ونييب يعني الناقة وذويد وقدير وخليق، يقال: ملحفة خليق، كل ذلك تأنيث يصغر بغير الهاء. ورجل محرب 3 : شجاع. وفلان حرب فلان أي يحاربه. ودار الحرب: بلاد المشركين الذين لا صلح بينهم وبين المسلمين. وحربته تحريبا أي حرشته على إنسان فأولع به وبعداوته. وحرب فلان حربا: أخذ ماله فهو حرب محروب حريب. وحريبة الرجل: ماله الذي يعيش به، (والحريب الذي سلبت حريبته) 1 . وقوله تعالى: يحاربون الله ورسوله 2 يعني المعصية. وقوله تعالى: فأذنوا بحرب من الله ورسوله يقال: هو القتل. وشيوخ حربى والواحد حرب شبيه (بالكلبى) 4 والكلب، قال: 5 وشيوخ حربى بجنبي أريك والحراب جمع الحربة (دون الرمح) 6 والمحراب عند العامة اليوم: مقام الإمام في المسجد. وكانت محاريب بني إسرائيل مساجدهم التي يجتمعون فيها للصلاة. والمحراب: الغرفة [قال امرؤ القيس: كغزلان رمل في محاريب أقيال] 7 والمحراب: عنق الدابة. والحرباء: دويبة على خلقة سام أبرص مخططة، وجمعه: الحرابي 8 والحرباء والقتير: رأسا المسمار في الحلقة في الدرع، قال لبيد: 9 كل حرباء إذا أكره صل والحربة: الوعاء مثل الجوالق.'),
(799, 'رحب', 'رحب', 'رحب', 'رحب 1 الشيء رحبا ورحابة. ورجل رحيب الجوف أي: أكول 2 . وقال نصر بن سيار: أرحبكم الدخول في طاعة الكرماني؟، أي: أوسعكم؟. هذه كلمة شاذة على فعل مجاوز، وفعل لا يجاوز 3 أبدا. وأرحب: حي أو موضع تنسب إليه النجائب الأرحبية. وقوله: مرحبا، أي: انزل في الرحب والسعة، قال الليث: وسئل الخليل عن نصبه فقال: فيه كمين الفعل، أراد: انزل أو أقم فنصب بفعل مضمر، فلما عرف معناه المراد 4 أميت الفعل. والرحبى: سمة للعرب على جنب البعير. والرجى: سمة العرب على جنب البعير.'),
(800, 'برح', 'برح', 'برح', 'برح الرجل يبرح براحا إذا رام من موضعه. وأبرحته: [رمته] 5 وقول الأعشى: أبرحت ربا وأبرحت جارا 1 أي: أعظمت واتخذته عظيما. وما برحت أفعل كذا أي: ما زلت. وقولهم: برح الخفاء أي: ذهب، قال: 2 برح الخفاء وما لدي تجلد. وأرض براح: لا بناء فيها ولا عمران. والبرحاء: الحمى الشديدة. (وتقول) 3 : برح بنا 4 فلان تبريحا إذا آذاك بإلحاح المشقة، قال ذو الرمة: لنا والهوى برح على من يغالبه 5 والتباريح: كلف المعيشة في مشقة، والاسم التبرح، وتقول: ضربته ضربا مبرحا ولا تقول: مبرحا. وهذا الأمر أبرح علي من ذاك أي: أشق (وأشد، قال ذو الرمة: أنينا وشكوى بالنهار كثيرة ... علي وما يأتي به الليل أبرح) 6 والبراح: البيان، تقول: جاء الكفر براحا، وعلى هذا المعنى يجوز برح الخفاء أي ظهر ما كنت أخفي. والبروح: مصدر البارح وهو خلاف السانح من الظباء والطير وما يتيمن به أو يتشاءم به، قال: 1 فهن يبرحن 2 به بروحا ... وتارة يأتينه سنوحا والبارح من الرياح: ما تحمل التراب في شدة الهبوب 3 قال: 4'),
(801, 'حرم', 'حرم', 'حرم', 'الحرم: حرم مكة وما أحاط بها إلى قريب من المواقيت التي يحرمون منها، مفصول بين الحل والحرم بمنى. والمحرم في شعر الأعشى هو الحرم حيث يقول: بأجياد غربي الصفا والمحرم 1 وقال النبي- صلى الله عليه وآله وسلم-: مكة حرم إبراهيم، والمدينة حرمي. (والمحرم هو الحرم) 2 ، ورجل حرمي: منسوب إلى الحرم، قال: 3 لا تأوين لحرمي مررت به ... يوما وإن ألقي الحرمي في النار [وإذا نسبوا غير الناس (فتحوا وحركوا) فقالوا] 4 : منسوب إلى الحرم. أي: محرمون. وتقول: أحرم الرجل فهو محرم وحرام، ويقال: إنه حرام على من 5 يرومه بمكروه، وقوم حرم أي: محرمون. والأشهر الحرم ذو القعدة وذو الحجة والمحرم ورجب، ثلاثة سرد وواحد فرد 1 . والمحرم سمي به لأنهم [لا] يستحلون فيه القتال. وأحرمت: دخلت في الشهر الحرام. والحرمة: ما لا يحل لك انتهاكه. وتقول: فلان له حرمة أي تحرم منا بصحبة وبحق. وحرم الرجل: نساؤه وما يحمي. والمحارم: ما لا يحل استحلاله. والمحرم: ذو الرحم في القرابة [وذات الرحم في القرابة] أي: لا يحل تزويجها، يقال: هو ذو رحم محرم [وهي ذات رحم محرم] 2 قال: 3 . وجارة البيت أراها محرما وحريم الدار: ما أضيف إليها من حقوقها ومرافقها (وحريم البئر: ملقى النبيثة والممشى على جانبيها ونحو ذلك. وحريم النهر: ملقى طينه والممشى على حافتيه) 4 . والحريم: الذي حرم مسه فلا يدنى منه. وكانت العرب إذا حجوا ألقوا الثياب التي دخلوا بها الحرم 5 ، فلا يلبسونها ما داموا في الحرم، قال 6 كفى حزنا كري عليه كأنه ... لقى بين أيدي الطائفين حريم والحرام ضد الحلال، والجميع حرم، قال: 1 وبالليل هن عليه حرم والمحروم: الذي حرم الخير حرمانا، ويقرأ (قوله تعالى) : وحرام على قرية 2 ، أي واجب، عليهم، حتم 3 لا يرجعون إلى الدنيا بعد ما هلكوا. ومن قرأ: وحرام على قرية يقول: حرم ذلك عليها فلا يبعث دون يوم القيامة. وحرم الرجل إذا لج في شيء ومحك 4 . والحرمى من الشاء والبقر هي المستحرمة، تقول: استحرمت حرمة إذا أرادت السفاد وهن حرامى 5 أي مستحرمات. والقطيع المحرم: السوط الذي لم يمرن، قال الأعشى: ترى عينها صغواء في جنب مأقها ... تراقب كفي والقطيع المحرما 6'),
(802, 'رحم', 'رحم', 'رحم', 'الرحمن الرحيم: اسمان مشتقان من الرحمة، ورحمة الله وسعت كل شيء، (وهو أرحم الراحمين) 1 ، ويقال: ما أقرب رحم فلان إذا كان ذا مرحمة وبر، وقوله- جل وعز- وأقرب رحما ، أي أبر بالوالدين من القتيل الذي قتله الخضر- عليه السلام-، [وكان الأبوان مسلمين والابن كان كافرا فولد لهما بعد بنت فولدت نبيا، وأنشد: أحنى وأرحم من أم بواحدها ... رحما وأشجع من ذي لبدة ضاري) 2 والمرحمة: الرحمة، [تقول: رحمته أرحمه رحمة ومرحمة، وترحمت عليه، أي قلت: رحمة الله عليه، وقال الله- جل وعز- وتواصوا بالصبر وتواصوا بالمرحمة 3 أي أوصى بعضهم بعضا برحمة الضعيف والتعطف عليه) 4 . والرحم: بيت منبت الولد ووعاؤه في البطن. وبينهما رحم أي قرابة قريبة، قال الأعشى: نجفى وتقطع منا الرحم 5 [وجمعه الأرحام. وأما الرحم الذي جاء في الحديث: الرحم معلقة بالعرش، تقول: اللهم صل من وصلني واقطع من قطعني فالرحم القرابة تجمع بني أب. وناقة رحوم: أصابها داء في رحمها فلا تلقح، تقول: قد رحمت رحما، وكذلك المرأة رحمت ورحمت إذا اشتكت رحمها] .'),
(803, 'مرح', 'مرح', 'مرح', 'المرح: شدة الفرح حتى يجاوز قدره. وفرس (مرح) 2 ممراح مروح، وناقة ممراح مروح، وقال: 3 نطوي الفلا بمروح لحمها زيم ومرحى: كلمة تقولها العرب عند الإصابة. والتمريح: أن تملأ المزادة أول ما تخرز حتى تكتم خروزها 4 ، تقول: ذهب مرح المزادة إذا لم يسل ماؤها، وقد مرحت [العين] مرحانا: [اشتد سيلانها] 5 ، [قال] 6 : [كأن قذى في العين قد مرحت به ... وما حاجة الأخرى إلى المرحان] ويقال: مرح جلدك أي: ادهنه، قال الطرماح: مدبوغة لم تمرح 7'),
(804, 'رمح', 'رمح', 'رمح', 'الرمح [واحد] 1 الرماح. والرماحة: صنعة الرماح. والرامح: نجم يقال له السماك المرزم. و [ذو] الرميح 2 : ضرب من اليرابيع، طويل الرجلين في أوساط أوظفته، في كل وظيف فضل ظفر. وأخذت البهمى رماحها: إذا امتنعت من المراعي. ورمحت الدابة برجلها ترمح بها رمحا، [وكل ذي حافر يرمح رمحا إذا ضرب برجليه، وربما استعير الرمح لذي الخف، قال الهذلي: بطعن كرمح الشول أمست غوارزا ... حواذبها تأبى على المتغبر] 3 ويقال: برئت إليك من الجماح والرماح، [وهذا من العيوب التي يرد المبيع بها] 4 ويقال: رمح الجندب أي: ضرب الحصى برجله، قال: 5 والجندب الجون يرمح'),
(805, 'حمر', 'حمر', 'حمر', 'الحمرة: لون الأحمر، تقول: قد احمر الشيء [احمرارا] 6 إذا لزم لونه فلم يتغير من حال إلى حال، واحمار يحمار احميرارا إذا كان عرضا حادثا لا يثبت، كقولك: جعل يحمار مرة ويصفار مرة. والحمر: داء يعتري (الدابة) 1 من كثرة الشعير، تقول: حمر يحمر حمرا، وبرذون حمر، [وقال امرؤ القيس: لعمري لسعد بن الضباب إذا غدا ... أحب إلينا منك، فا فرس حمر أراد: يا فا فرس حمره، لقبه بفي فرس حمر لنتن فيه] 2 . والحمرة 3 : داء يعتري الناس فتحمر مواضعها، يعالج بالرقية. والحمار: [العير الأهلي والوحشي] 4 ، والعدد 5 : أحمرة، والجميع: الحمير والحمر والحمرات، والأنثى حمارة وأتان. والحميرة: الأشكز 6 : [معرب وليس بعربي، وسميت حميرة لأنها تحمر أي: تقشر، وكل شيء قشرته فقد حمرته فهو محمور وحمير] 7 . والخشبة التي يعمل عليها الصيقل يقال لها: الحمار: وحمارة 8 القدم: هي المشرفة بين مفصلها وأصابعها من فوق. والحمار: خشبة في مقدم الرحل تقبض عليها المرأة، وهي في مقدم الإكاف أيضا، قال الأعشى: كما قيد الآسرات الحمارا 1 وحمار قبان: دويبة صغيرة 2 لازقة بالأرض ذات قوائم كثيرة. وفي الحديث 3 : غلبتنا عليك هذه الحمراء يعني العجم والموالي، لسمرة ألوان العرب وحمرة ألوان العجم. وفرس محمر وجمعه محامر ومحامير أي: يجري جري الحمار من بطئه، [قال: يدب إذ نكس الفحج المحامير] 4 . والحمرة: ضرب من الطير كالعصافير، وبعض يجعل العصافير الحمرة، قال: 5 يا لك من حمرة بالجنفر وحمارة الصيف: شدة وقت الحر، ولم اسمع على فعالة غير هذه والزعارة. ثم سمعت بخراسان صبارة 6 الشتاء، وسمعت: إن وراءك لقرا حمرا. والأحمران: الزعفران والذهب. وموت أحمر، وميتة حمراء، أي: شديدة، قال: 1 نسقى بأيدينا منايا حمرا وسنة حمراء أي: شديدة، قال: 2 إليك أشكو سنوات حمرا أخرج على نعت الأعوام فلم يقل حمراوات 3 .'),
(806, 'محر', 'محر', 'محر', 'المحارة: دابة 4 في الصدفين. والمحارة: باطن الأذن 5 . والمحارة: ما يوجر به الصبي ويلد، وربما سقي فيها باللبن لعله .'),
(807, 'لحن', 'لحن', 'لحن', 'اللحن: ما تلحن إليه بلسانك، أي: تميل إليه بقولك. ومنه قول الله- جل وعز-: ولتعرفنهم في لحن القول 1 فكان رسول الله- صلى الله عليه و [على] آله وسلم- بعد نزول هذه الآية يعرف المنافقين إذا سمع كلامهم، يستدل بذلك على ما يرى من لحنه، (أي من مثله في كلامه في اللحن 2 . واللحن والألحان: الضروب من الأصوات الموضوعة. واللحن: ترك الصواب في القراءة والنشيد، يخفف ويثقل، واللحان واللحانة: الرجل الكثير اللحن، وقال: 3 فزت بقدحي معرب لم يلحن ولحن يلحن لحنا ولحنا. واللحن (بفتح الحاء) : الفطنة، ورجل لحن إذا كان فطنا.'),
(808, 'نحل', 'نحل', 'نحل', 'واحدة النحل: نحلة. والنحل: إعطاؤك إنسانا شيئا بلا [استعاضة] 4 . ونحل المرأة: مهرها 5 ، ويقال: أعطيتها مهرها نحلة إذا لم ترد عوضا. وانتحل فلان شعر فلان إذا ادعاه [أنه قائله] 6 . ونحل الشاعر قصيدة إذا رويت عنه وهي لغيره. وسيف ناحل أي: دقيق. ونحل الجسم ينحل نحولا فهو ناحل، وأنحله الهم أي: هزله. [ونحل فلان فلانا أي: سابه فهو ينحله أي: يسابه، وقال طرفة: فذر ذا وانحل النعمان قولا ... كنحت الفأس ينجد أو يغور 1 والنحل: دبر العسل، الواحدة نحلة) 2 .'),
(809, 'حلف', 'حلف', 'حلف', 'الحلف والحلف [لغتان] ، 3 في القسم، الواحدة حلفة، ويقال: محلوفة بالله ما قال ذاك، ينصب على ضمير يحلف بالله محلوفة أي قسما فالمحلوفة هي القسم، قال النابغة: فاصبحت لا ذو الضغن عني مكذب ... ولا حلفي على البراءة 4 نافع 5 ورجل حلاف وحلافة كثير الحلف. واستحلفته بالله ما فعل ذاك. وحالف فلان فلانا، فهو حليفه، وبينهما حلف لأنهما تحالفا بالأيمان أن يفي كل لكل، فلما لزم ذلك عندهم في الأحلاف التي في العشائر والقبائل صار كل شيء لزم شيئا لم يفارقه حليفه، حتى يقال: فلان حليف الجود وحليف الإكثار وحليف الإقلال، [وأنشد: وشريكين في كثير من المال ... وكانا محالفي إقلال] 1 وأحلف الغلام: جاوز رهاق الحلم، فهو محلف 2 ، وقال بعضهم: أخلف بالخاء. والحلفاء: نبات حمله قصب النشاب، الواحدة حلفة والجميع الحلف 3 ، وقياسه: قصباء وقصبة وقصب، وطرفاء وطرفة وطرف، وشجراء وشجرة وشجر سواء.'),
(810, 'لحف', 'لحف', 'لحف', 'اللحف: تغطيتك الشيء باللحاف، لحفت فلانا لحافا: ألبسته إياه. واللحاف: اللباس الذي فوق سائر اللباس، ولحفت لحافا وهو جعلكه، وتلحفت لحافا: اتخذته لنفسي والتحفت مثله، [وقال طرفة: يلحفون الأرض هداب الأزر 4 أي يجرونها على الأرض] 5 . والملحفة: الملاءة التحفت بها. والإلحاف في المسألة: الإلحاح وقال؟ 1 : نسأل الناس إلحافا ونأكله إسرافا.'),
(811, 'فلح', 'فلح', 'فلح', 'الفلاح، والفلح لغة، البقاء في الخير، وفلاح الدهر: بقاؤه. وحي على الفلاح أي: [هلم] 2 على بقاء الخير، وفي الشعر فلح، قال: 3 أخبر المخبر عنكم أنكم ... يوم فيف الريح أبتم بالفلح أريد به الفلاح فقصر، وقد يطرحون الألف من الفلاح والواو من الكفوف 4 فيقولون: كفف احتياجا إلى القوافي، ولا يتغير المعنى. والفلح: الشق في الشفة في وسطها، رجل أفلح وامرأة فلحاء دون العلم. وقولهم: 5 إن الحديد بالحديد يفلح أي يفرج لأحدهما بالآخر حتى يخرج من مضيق موضعه، أو يقطع به أي: يشق أحدهما. والفلاحون: الزراعون. والفلاح: السحور، أي من تسحر بقيت له قوة يومه. والفلاح: المكاري [وإنما قيل له فلاح تشبيها بالأكار] 1 ، قال: 2 وفلاح يسوق له حمارا'),
(812, 'لفح', 'لفح', 'لفح', 'لفحته النار أي أصابت وجهه وأعالي جسده فأحرقت، [والسموم تلفح الإنسان] 3 . واللفاح: شيء أصفر مثل الباذنجان طيب الريح.'),
(813, 'فحل', 'فحل', 'فحل', 'الفحول والفحولة جمع الفحل، والفحلة: افتحال الإنسان فحلا لدوابه، قال: 4 نحن افتحلنا جهدنا لم نأتله والاستفحال خطأ، وإنما الاستفحال على ما بلغني من أهل كابل عن علوجها أنهم إذا وجدوا رجلا من العرب جسيما جميلا خلوا بينه وبين نسائهم رجاء أن يولد فيهم مثله. وفحل فحيل: كريم المنتجب. والفحل: الحصير، سمي به لأنه يعمل من سعف النخل من الفحل، ويقال للنخلة الذكر [الذي يلقح به حوائل] 1 النخل فحالة، والجميع فحال. واستفحل الأمر: عظم واشتد.'),
(814, 'حفل', 'حفل', 'حفل', 'حفل الماء حفولا وحفلا أي: اجتمع في محفله أي مجتمعه، والمحفل: المجلس، وقد حفلوا أي اجتمعوا، وهو المجتمع في غير مجلس أيضا، واحتفلوا أي: اجتمعوا، ويقال: تعالوا بأجمعكم الأحفلى 2 يريد الجماعة، قال: 3 نحن في المشتاة ندعو الأحفلى ... لا ترى الآدب فينا ينتقر ومن روى بالجيم فانه يريد الجفالة من الناس أي الجماعة. وشاة حافل قد حفلت حفولا إذا اجتمع لبنها في ضرعها وكثر، ويجمع حفل وحوافل. والحفل: المبالاة، وما أحفل: ما أبالي، قال لبيد: 4 فمتى أهلك فلا أحفله ... بجلي الآن من العيش بجل والتحفيل: التزيين، والتحفل: التزين، وتحفلي أي: تزيني.'),
(815, 'حبل', 'حبل', 'حبل', 'الحبل: الرسن، [والحبل: العهد والأمان] 1 والحبل: التواصل، والحبل: الرمل الطويل الضخم. والحبل: موضع بالبصرة على شاطىء النهر. والحبل: مصدر حبلت الصيد واحتبلته أي: أخذته، والجميع من هذه الأسماء كلها: الحبال. والحبالة: المصيدة، وحبائل الموت: أسبابه، واحتبله الموت. وحبل العاتق: وصلة ما بين العاتق والمنكب. [وحبل الوريد: عرق يدر في الحلق. والوريد: عرق ينبض من الحيوان لا دم فيه] 2 وفلان الحبلي: منسوب إلى حي من اليمن. والمحبل في قول رؤبة: كل جلال يملأ المحبلا حبل، وحبلت المرأة حبلا فهي حبلى. وشاة حبلى، [وسنورة حبلى، وجمع الحبلى حبالى] 4 والحبلة: طاقة من قضبان الكرم. والحبل: نوع من الشجر مثل السمر. وحبل الحبلة: ولد الولد الذي في البطن 1 ، وكانت العرب ربما تبايعوا على حبل الحبلة فنهى رسول الله- صلى الله عليه وسلم- عن بيع المضامين والملاقيح وحبل الحبلة.'),
(816, 'حلب', 'حلب', 'حلب', 'عناق تحلبة 2 أي: بكر تحلب قبل أن يفسد [لبنها] 3 . والحلب: اللبن الحليب، والحلاب: المحلب الذي يحلب فيه، [قال: صاح هل ريت أو سمعت براع ... رد في الضرع ما قرى في الحلاب] 4 والإحلاب من اللبن يجتمع عند الراعي نحو من الوسق فيحمل إلى الحي، يقال: جاءوا باحلابين وثلاثة أحاليب، فأما في الشاء والبقر فيقال: جاءوا بإمخاض وإمخاضين وثلاثة أماخيض، لأنه يمخض فيخرج زبده، ولا تمخض ألبان الإبل. والحلب من الجباية مثل الصدقة ونحوها مما لا يكون وظيفة معلومة. وناقة حلوب: ذات لبن، فإذا صيرتها اسما قلت: هذه الحلوبة لفلان، وقد يخرجون الهاء من الحلوبة وهم يعنونها، قال الأعشى: تذهل الشيخ عن بنيه وتودي ... بحلوب المعزابة المعزال 1 ويروى بلبون، وكذلك الركوبة والركوب. وناقة حلباة ركباة أي ذات لبن تحلب وتركب، قال: 2 ليست بحلباة ولا ركباة وحلبانة وركبانة أيضا، ولا يقال للذكور شيء من ذلك، وتصغير حلباة حليبية. والمحلب: شجر يجعل حبه في العطر. والحلب: نبات من أفضل المراعي. والحلباب: نبات غير الحلب 3 . والحلبة: خيل تجتمع للسباق من كل أوب، ولا تخرج من موضع واحد، ولكن من كل حي، قال 4 : نحن سبقنا الحلبات الأربعا ... الفحل والقرح في شوط معا وإذا جاء القوم من كل وجه فاجتمعوا لحرب ونحوه قيل: قد أحلبوا، والاحلاب يراد به الإغاثة. وربما جمعوا الحلبة بالحلائب، ولا يقال للواحد منها حليبة ولا حلابة. وتحلب فوه وتحلب الندى أو الشيء إذا سال. والحلب: حب الواحدة حلبة، وهي الفريقة. والحلبوب: اللون الأسود 1 ، قال رؤبة: واللون في حوته حلبوب 2 والحلب: الجلوس على الركبة وأنت تأكل، يقال: احلب فكل.'),
(817, 'لحب', 'لحب', 'لحب', 'قطعك الشيء 3 طولا، ولحبه ولحبه بالشفرة إذا قطع لحمه. ولحب متن الفرس وعجزه إذا املس في حدور، قال: 4 والمتن ملحوب وطريق لاحب ولحب (وملحوب) 5 وقد لحب يلحب لحوبا أي وضح، قال: 6 تدع الجنوب إذا انتحت ... فيه طريقا لاحبا'),
(818, 'بلح', 'بلح', 'بلح', 'البلح: الخلال، وهو حمل النخل ما دام أخضر صغارا كحصرم العنب. البلح: طائر أعظم من النسر محترق الريش، يقال: لا تقع ريشة من ريشه وسط ريش سائر الطير إلا أحرقته، ويقال: هو النسر القديم إذا هرم، وجمعه: بلحان 7 . والبلوح: تبلد الحامل تحت الحمل من ثقله، يقال: حمل على البعير حتى بلح، قال أبو النجم: وبلح النمل به بلوحا 1 أي حين ينقل الحب في الحر.'),
(819, 'حمل', 'حمل', 'حمل', 'الحمل: الخروف، والجميع الحملان 2 . والحمل: برج من البروج الاثني عشر. والفعل حمل يحمل حملا وحملانا. ويكون الحملان أجرا لما يحمل. والحملان: ما يحمل عليه من الدواب في الهبة خاصة. وتقول: إني لأحمله على أمر فما يتحمل، وأحمله أمرا فما يتحمل، وإنه ليتحمل الصنيعة والإحسان، وحملت فلانا فلانا، وتحملت به عليه في الشفاعة والحاجة 3 . وتحاملت في الشيء إذا تكلفته على مشقة. واستحملت فلانا نفسي أي حملته أموري وحوائجي، قال: 4 ومن لم يزل يستحمل الناس نفسه وحملت عنه أي حلمت عنه. والحمل: ما في البطن، والحمل ما على الظهر، وأما حمل الشجر فيقال: ما ظهر فهو حمل، وما بطن فهو حمل. وبعض يقول: حمل الشجر ويحتجون فيقولون: ما كان لازما فهو حمل، وما كان بائنا فهو حمل 1 . والحميل: المنبوذ يحمل فيربى. وحميل السيل: ما يحمل من الغثاء، وفي الحديث: فيخرجون من النار فينبتون كما تنبت الحبة في حميل السيل 2 . والحميل: الولد في بطن الأم إذا أخذت من أرض الشرك. والحمالة والمحمل: علاقة السيف، قال: 3'),
(820, 'حنف', 'حنف', 'حنف', 'الحنف: ميل في صدر القدم، ورجل أحنف، ورجل حنفاء، [ويقال: سمي الأحنف بن قيس به لحنف كان في رجله] 1 ، وقالت حاضنة الأحنف: والله لولا حنف برجله ... ما كان في فتيانكم كمثله 2 والسيوف الحنفية تنسب إليه لأنه أول من عملها، أي: أمر باتخاذها، وهو في القياس: سيف أحنفي. [وبنو حنيفة حي من ربيعة. ويقال: تحنف فلان إلى الشيء تحنفا إذا مال إليه. وحسب حنيف أي: حديث إسلامي لا قديم له، وقال ابن حبناء التميمي: وماذا غير أنك ذو سبال ... تمسحها وذو حسب حنيف] 3 والحنيف في قول: المسلم الذي يستقبل قبلة البيت الحرام على ملة إبراهيم حنيفا مسلما. والقول الآخر: الحنيف كل من أسلم في أمر الله فلم يلتو في شيء منه. وأحب الأديان إلى الله الحنيفية السمحة وهي ملة النبي- صلى الله عليه و [على] آله وسلم- لا ضيق فيها ولا حرج.'),
(821, 'نحف', 'نحف', 'نحف', 'نحف 1 الرجل ينحف نحافة فهو نحيف قضيف، ضرب الجسم قليل اللحم، قال: ترى الرجل النحيف فتزدريه ... وفي أثوابه أسد مزير 2'),
(822, 'نفح', 'نفح', 'نفح', 'نفح الطيب ينفح نفحا ونفوحا، وله نفحة طيبة ونفحة خبيثة ونفحت الدابة [إذا رمحت برجلها] 3 ورمت بحد حافرها. ونفحه 4 بالسيف أي: تناوله من بعيد شزرا. ونفحه بالمال نفحا، ولا تزال له نفحات من المعروف، والله النفاح 5 المنعم على عباده. والإنفحة لا تكون إلا لكل ذي كرش، وهو شيء يستخرج من بطن (ذيه) أصفر يعصر في صوفة 7 مبتلة في اللبن فيغلظ كالجبن.'),
(823, 'حفن', 'حفن', 'حفن', 'الحفن: أخذك الشيء براحة كفك، والأصابع مضمومة، وملء كل كف حفنة. واحتفنت: أخذت لنفسي. والمحفن: الرجل ذو الحفن الكثير، وكان محفن أبو بطحاء تنسب إليه الدواب البطحاوية. والحفنة: الحفرة 1 ، وجمعها حفن.'),
(824, 'حبن', 'حبن', 'حبن', 'الحبن: ما يعتري الجسد فيقيح ويرم، وجمعه: حبون. والحبن: أن يكثر السقي في شحم البطن فيعظم البطن جدا. وأم حبين: دويبة على خلقة الحرباء عريضة البطن جدا، [قال: أم حبين آبسطي برديك ... إن الأمير داخل عليك وضارب بالسيف منكبيك 2 والحبن: عظم البطن، ولذلك قيل لمن سقي بطنه قد حبن. وأم حبين: هي الأنثى من الحرابي] 3 .'),
(825, 'حنب', 'حنب', 'حنب', 'الحنب: اعوجاج في الساقين، والتحنيب في الخيل مما يوصف صاحبه بالشدة، وليس ذلك من اعوجاج شديد. ورجل محنب أي: شيخ منحن، قال: 1 قذف المحنب بالعاهات والسقم'),
(826, 'نحب', 'نحب', 'نحب', 'النحب: النذر، وقوله- جل وعز-: فمنهم من قضى نحبه 2 أي قتلوا في سبيل الله فأدركوا ما تمنوا فذلك قضاء نحبهم، كأن المعنى: ظفروا بحاجتهم. والانتحاب: صوت البكاء، والنحيب: البكاء. وناحبته: حاكمته أو قاضيته إلى رجل. والنحب: السير السريع.'),
(827, 'نبح', 'نبح', 'نبح', 'النبح: صوت الكلب، والتيس عند السفاد ينبح. والحية تنبح في بعض أصواتها، قال: 3 يأخذ فيه الحية النبوحا والظبي ينبح في بعض الأصوات، قال: 4'),
(828, 'نحم', 'نحم', 'نحم', 'نحم الفهد ينحم نحيما، ونحوه من السباع. وكذلك النئيم وهو صوت شديد. والنحام: طائر 3 أحمر على خلقة الاوز 4 ، الواحدة نحامة. والرجل نحام: بخيل إذا طلب إليه كثر سعاله، قال: 5 أرى قبر نحام بخيل بماله ... كقبر غوي في البطالة مفسد'),
(829, 'منح', 'منح', 'منح', 'المنحة: منفعتك أخاك بما تمنحه. وكل شيء يقصد به قصد شيء فقد منحته إياه كما تمنح المرأة وجهها المرآة، قال: 1 تمنح المرآة وجها واضحا ... مثل قرن الشمس في الصحو ارتفع ومنحت فلانا شيئا ناقة أو شاة، فتلك المنيحة، ولا تكون المنيحة إلا للبن خاصة. والمنيح فيما زعم: الثامن من القداح.'),
(830, 'حمن', 'حمن', 'حمن', 'الحمنان، الواحدة حمنانة: صغار القردان، وانتهينا إلى محمنة، أي: أرض كثيرة الحمنان. وتكون حمنانا ثم قمقاما ثم قردانا ثم حلما.'),
(831, 'محن', 'محن', 'محن', 'المحنة: معنى الكلام الذي يمتحن به، فيعرف بكلامه ضمير قلبه. وامتحنته وامتحنت الكلمة أي: نظرت إلى ما يصير صيرها 2 . وفي صفة الحرورية: (إن) 3 لهم محنة من أخطأها قتلته، ومن أصابها أضلته.'),
(832, 'فحم', 'فحم', 'فحم', 'الفحم: الجمر الطافي. الواحدة: فحمة. وفحم الصبي يفحم إذا طال بكاؤه حتى ينقطع نفسه، فلا يطيق البكاء، وأفحمت فلانا إذا لم يطق جوابك. وشعر فاحم قد فحم فحوما أيضا، وهو الحسن الأسود. قال: لها مقلتا ريم وأسود فاحم وفحمة العشاء: شدة سواد الليل وظلمته.'),
(833, 'الحاء', 'الحاء', 'حا', 'الحاء: حرف هجاء مقصور موقوف، فإذا جعلته اسما مددته. تقول: هذه حاء مكتوبة. ومدتها ياءان. وكل حرف على خلقتها من حروف المعجم فألفها إذا مدت صارت في التصريف ياءين. وتصغيرها: حيية [وإنما يجوز تصغيرها] إذا كانت صغيرة في الخط أو خفية وإلا فلا. وحاء- ممدودة- قبيلة. قال: 1 طلبت الثأر في حكم وحاء ويقال لابن مائة: لا حاء ولا ساء، أي: لا محسن ولا مسيء، ويقال: لا رجل ولا امرأة. ويقال: تفسيره أنه لا يستطيع أن يقول: حا وهو أمر للكبش عند السفاد، يقال: حأحأت به وحاحيت به. قال أبو خيرة: حأحأ. وقال أبو الدقيش: أحوأحو. ولا يستطيع أن يقول: سأ، وهو للحمار، ويقول: سأسأت بالحمار إذا قلت: سأسأ. قال: 2 قوم يحاحون بالبهام ونسوان ... قصار كهيئة الحجل الوحوحة: الوحوحة: الصوت. والأحاح: الغيظ، قال: 3 طعنا شفى سرائر الأحاح حي: حي- مثقلة-: يندب بها، وينعى 4 بها. يقال: حي على الفداء، حي على الخير، ولم يشتق منه فعل. حو: وحو: زجر للمعز دون الضأن. حوحيت به حوحاة. حيو: والحيوة كتبت بالواو ليعلم أن الواو بعد الياء، ويقال: بل كتبت على لغة من يفخم الألف التي مرجعها إلى الواو نحو: الصلوة والزكوة. ويقال: حيي يحيا فهو حي، ويقال للجميع: حيوا. ولغة أخرى: حي يحي، والجميع: حيوا خفيفة مثل: بقوا. والحيوان: كل ذي روح. الواحد والجميع فيه سواء. والحيوان: ماء في الجنة لا يصيب شيئا إلا حي بإذن الله. والحية اشتقاقها من الحياة، ويقال: هي في أصل البناء: حيوة. ولكن الياء والواو إذا التقتا وسكنت الأولى منهما جعلتا ياء شديدة ومن قال لصاحب الحيات: حاي فهو فاعل من هذا البناء. صارت الواو كسرة كواو الغازي.. ومن قال: حواء على فعال فإنه يقول: اشتقاق الحية من حويت، لأنها تتحوى في التوائها وكذلك 1 تقول العرب. والحيا- مقصور-: حيا الربيع، وهو ما تحيا به الأرض من الغيث. قال: 2 وغيث حيا تحيا به الأرض واسع وأرض محواة: كثيرة الحيات، اجتمعوا على ذلك. والحياء- ممدود: من الاستحياء. رجل حيي بوزن فعيل، وامرأة حيية بوزن فعيلة. قالت ليلى: 1 وأحيى حياء من فتاة حيية ... وأشجع من ليث بخفان خادر والمحاياة: الغذاء للصبي بما به حياته. والمحاياة: تحيه القوم بعضهم بعضا. والحي: الواحد من أحياء العرب. وحيا الشاة: مقصور وممدود- لغتان. والمحيا: الوجه. وقول العرب: حياك الله: يعني: الإستقبال بالمحيا، ويحتمل أن يكون اشتقاقه من الحياة. وتقول: حياك الله وبياك، أي: أفرحك وأضحكك، ويقال: بياك تقوية لحياك. وقول المصلي في التشهد: التحيات لله، معناه: البقاء لله، ويقال: الملك لله. حوي: حوى فلان مالا حيا وحواية، أي: جمعه وأحرزه، واحتوى عليه، كحوي الحية. والحوية: مركب يهيأ للمرأة. والحوي: استدارة كل شيء، كحوي الحية، وكحوي بعض النجوم إذا رأيتها على نسق واحد مستديرة، والحوية والحاوية والجميع الحوايا: الأمعاء قال علي عليه السلام: 2 أقتلهم ولا أرى معاوية ... الأخزر العين العظيم الحاوية وقال: 1 فهن من واطىء ثنيي حويته ... وناشج وعواصي الجوف تنشخب والحواء: أخبية تدانى بعضها من بعض. تقول: هم أهل حواء واحد، والجماعة: أحوية. والحواء: نبت معروف، الواحدة: حوأة. والحوة في الشفاه: شبه اللمى واللمس. قال ذو الرمة: 2 لمياء في شفتيها حوة لعس ... وفي اللثات وفي أنيابها شنب ويح: أما الويح ونحوه مما في صدره واو فلم يسمع في كلام العرب إلا ويح، وويس، وويل، وويه. فأما ويح فيقال إنه رحمة لمن تنزل به بلية. [وربما] جعل مع (ما) كلمة واحدة فقيل: ويحما. قال حميد: وويح لمن لم يدر ما هن ويحما فجعل (ويحما) كلمة واحدة فأضاف (ويح) إلى (ما) 4 . ونصب (ويحما) لأنه فعل معكوس على الأول كما قال: ويل له ويل له ويلا وحي: يقال: وحي يحي وحيا، أي: كتب يكتب كتبا. قال العجاج: 1 لقدر كان وحاه الواحي وقال: في سورة من ربنا موحيه وأوحى الله إليه، أي: بعثه. وأوحى إليه: ألهمه. وقوله عز وجل: وأوحى ربك إلى النحل 2 ، أي: ألهمها. وأوحى لها معناه: وأوحى إليها في معنى الأمر. قال الله عز وجل: بأن ربك أوحى لها 3 . قال العجاج: 4 وحى لها القرار فاستقرت أراد: أوحى إليها، إلا أن لغته: وحى، فإذا لم يذكر (لها) قال: أوحى. وزكريا أوحى إلى قومه، أي: أشار إليهم. والإيحاء: الإشارة. قال: 5 فأوحت إليها والأنامل رسلها وقوله 6 : واستحيوا نساءهم 7 . أي: استفعلوا من الحياة، أي: اتركوهن أحياء. وفي الحديث: إن الرجل ليسأل عن كل شيء حتى عن حية أهله 1 ، أي: عن كل شيء حي في منزله مثل الهرة، فأنث الحي فقال: حية. والحوايا: المساطح، وهو أن يعمدوا إلى الصفا فيحوون له ترابا يحبس عليهم الماء. الواحدة: حوية. والحي: نقيض الميت. والوحى: السرعة.'),
(834, 'قه', 'قه', 'قه', 'قه: حكاية ضرب من الضحك، ثم يضاعف بتصريف الحكاية. يقال: قهقه الضاحك يقهقه قهقهة، إذا مد ورجع. وإذا خفف قيل: قه الضاحك، قال الراجز: 1 فهن في تهانف وفي قه وإن اضطر إلى تثقيلها جاز، كقوله: 2 ظللن في هزرقة وقه والقهقهة في قرب الورد مشتق من آصطدام الأحمال لعجلة 3 السير، كأنهم توهموا لحس ذلك جرس نغمة فضاعفوه، وقال رؤبة: 4 يطلقن قبل القرب المقهقه'),
(835, 'كه', 'كه', 'كه', 'الكهكهة: حكاية صوت الزمر، والكهكهة في الزمر أعرف منها في الضحك قال: 1 يا حبذا كهكهة الغواني وكه: حكاية المكهكه. والأسد يكهكه في زئيره. قال: 2 سام على الزءارة المكهكه وناقة كهة وكهاة- أي: ضخمة مسنة ثقيلة. قال: 3 فمرت كهاة ذات خيف جلالة'),
(836, 'هج', 'هج', 'هج', 'هجج البعير يهجج تهجيجا إذا غارت عينه في رأسه من جوع أو عطش أو إعياء غير خلقة. قال: 4 إذا حجاجا مقلتيها هججا والهجهجة، حكاية صوت الرجل إذا صاح بالأسد. قال: أو ذو زوائد لا يطاف بأرضه ... يغشى المهجهج كالذنوب المرسل وفحل هجهاج في حكاية شدة هديره. والهجهاج: النفور. وهجهجت بالناقة وبالجمل إذا زجرته، فقلت: هيج هيج. قال: 2 أمرقت من جوزه أعناق ناجية ... تنجو إذا قال لها هيجي وإذا حكوا ضاعفوا هجهج، كما يضاعفون الولولة من الويل، فيقولون: ولولت المرأة، إذا أكثرت من قولها: الويل. والهجاجة: الأحمق. والهجاجة: الهبوة التي تدفن كل شيء بالتراب.'),
(837, 'جه', 'جه', 'جه', 'جه: حكاية المجهجه. والجهجهة من صياح الأبطال في الحرب. يقال: جهجهوا فحملوا. قال: 3 فجاء دون الزجر والمجهجه'),
(838, 'هش', 'هش', 'هش', 'الهش: كل شيء فيه رخاوة. هش يهش هشاشة فهو هش هشيش. والهش: جذبك غصن الشجرة إليك، وكذلك إن نثرت ورقها بعصا، ومنه قوله عز وجل: وأهش بها على غنمي 1 . ورجل هش إذا هش إلى إخوانه، والهشاش والأشاش بمنزلة هرقت وأرقت 2 .'),
(839, 'هض', 'هض', 'هض', 'الهض: كسر دون الدق 3 وفوق الرض. والهضهاض: الفحل الذي يهض أعناق الفحول. يقال: هو يهضهض الأعناق. والهضهضة كذلك إلا أنه في عجلة والهض في مهلة جعلوا ذلك كالمد والترجيع في الأصوات.'),
(840, 'هص', 'هص', 'هص', 'الهص: شدة القبض والغمز. تقول: هصه وهصهصه في المد والترجيع. هصيص: اسم أبي حي من قريش.'),
(841, 'صه', 'صه', 'صه', 'صه: كلمة زجر للسكوت. قال: 1 صه! لا تكلم لحماد بداهية ... عليك عين من الأجذاع والقصب وقال: 2 إذا قال حادينا لتشبيه نبأة ... صه! لم تكن إلا دوي المسامع يقول: حين أنصت لم يسمع شيئا إلا دوي سمعه. وكل شيء من موقوف الرجز فإن العرب تنونه مخفوضا، وما كان غير موقوف فعلى حركة صرفه في الوجوه كلها. ويضاعف (صه) . فيقال: صهصهت بالقوم.'),
(842, 'هس', 'هس', 'هس', 'الهساهس: الكلام الخفي المجمجم. وسمعت هسيسا وهو الهمس. والهساهس: حديث النفس ووسوستها. قال: 3 فلهن منك هساهس وهموم'),
(843, 'سه', 'سه', 'سه', 'السه: حلقة الدبر. قال الراجز: 1 ادع فعيلا باسمها لا تنسه ... إن فعيلا هي صئبان السه وقال: 2 شأتك قعين غثها وسمينها ... وأنت السه السفلى إذا دعيت نصر'),
(844, 'هز', 'هز', 'هز', 'هززت الرمح ونحوه فاهتز. وهززت فلانا للخير فاهتز للخير. واهتزت الأرض: نبتت والهزهزة والهزاهز: تحريك البلايا والحروب للناس. وهزيز الريح: تحريكها. قال: 3 تقول هزيز الريح مرت بأثأب'),
(845, 'طه', 'طه', 'طه', 'الطهطاه: الفرس الفتي الرائع. قال: 4 سليم الرجع طهطاه قبوص وبلغنا في تفسير (طه) مجزومة أنه بالحبشية: يا رجل. ومن قرأ (طاها) فهما حرفان من الهجاء. وبلغنا أن موسى بن عمران لما سمع كلام الرب استفزه الخوف حتى قام على أصابع قدميه خوفا، فقال الله: طه، أي: آطمئن يا رجل.'),
(846, 'هد', 'هد', 'هد', 'الهد: الهدم الشديد، كحائط يهد بمرة فينهدم، والهدة، صوت تسمعه من سقوط ركن أو ناحية جبل. والهاد: صوت شديد يسمعه أهل السواحل، يأتيهم من قبل البحر له دوي في الأرض وربما كانت منه الزلزلة، ودوية هديره. قال: 1 يتبعن ذا هداهد عجنسا ... إذا الغربان به تمرسا وهدهدة الهدهد: صوته. والهداهد: طائر يشبه الحمام. قال الراعي: 2 كهداهد كسر الرماة جناحه ... يدعو بقارعة الطريق هديلا والتهدد، والتهدد والتهديد من الوعيد. والهدهدة: تحريك الأم ولدها لينام. والهد من الرجال: الضعيف. يقال: هذا هد حي. ويقال للرجل: مهلا هداديك. وهداد، حي من العرب.'),
(847, 'ده', 'ده', 'ده', 'ده: كلمة كانت العرب تتكلم بها. يرى الرجل ثأره. فتقول له: يا فلان إلا ده فلا ده، أي: أنك إن لم تثأر بفلان الآن لم تثأر به أبدا. وأما قول رؤبة: 1 وقول إلا ده فلا ده فيقال: إنها فارسية حكى قول ظئره. والدهدهة: قذفك الحجارة من أعلى إلى أسفل دحرجة. قال عمرو 2 يصف السيوف: يدهدهن الرءوس كما تدهدي ... حزاورة بأيديها الكرينا حول الهاء الآخرة ياء، لأن الياء أقرب الحروف شبها بالهاء، ألا ترى أن الياء مدة والهاء نفس، ومن هنالك صار مجرى الياء والواو والألف والهاء في روي الشعر واحدا نحو قوله 3 : لمن طلل كالوحي عاف منازله فاللام هو الروي، والهاء وصل للروي، كما أنها لو لم تكن لمدت اللام حتى تخرج من مدتها واو أو ياء، أو ألف للوصل نحو: منازلو، منازلي، منازلا.'),
(848, 'هت', 'هت', 'هت', 'الهت شبه العصر للصوت، يقال للبكر: يهت هتيتا، ثم يكش كشيشا، ثم يهدر إذا بزل هديرا. ويقال: الهمز صوت مهتوت في أقصى الحلق، فإذا رفه عن الهمز صار نفسا، تحول إلى مخرج الهاء، ولذلك استخفت العرب إدخال الهاء على الألف المقطوعة، يقال: أراق وهراق، وأيهات وهيهات. وتقول: يهت الإنسان الهمزة هتا إذا تكلم بها. والهتهتة أيضا تقال في معنى الهتيت.'),
(849, 'ته', 'ته', 'ته', 'والهتهتة والتهتهة [تقال] في التواء اللسان.'),
(850, 'هذ', 'هذ', 'هذ', '[يقال: هذه بالسيف هذا إذا قطعه] 1 والهذ: سرعة القطع، وسرعة القراءة. قال: 2 كهذ الأشاءة بالمخلب وقال: 3 وعبد يغوث تحجل الطير حوله ... قد اهتذ عرشيه الحسام المذكر ويروى: احتز، في بعض اللغات.'),
(851, 'هث', 'هث', 'هث', 'الهثهثة: انتخال الثلج والبرد وعظام القطر في سرعة. يقال: هثهث السحاب بمطره. قال: 1 من كل جون مسبل مهثهث والهثهثة: بعض كلام الألثغ. ويقال للوالي إذا جار وظلم: قد هثهث. قال العجاج: 2 وأمراء أفسدوا فعاثوا ... وهثهثوا فكثر الهثهاث'),
(852, 'هر', 'هر', 'هر', 'الهرة: السنورة، والهر: الذكر. ويجمع الهر: هررة، وتجمع الهرة: هررا. والهرير: دون النباح. تقول: هر الكلاب إليه. وبه يشبه نظر الكماة بعضهم إلى بعض، يقال: هر الكماة. وفلان هره الناس، إذا كرهوا ناحيته. قال: 1 أرى الناس هروني وشهر مدخلي ... وفي كل ممشى أرصد الناس عقربا وهر الشوك هرا إذا اشتد يبسه. قال: 2 إذا ما هر وآمتنع المذاق أي: صار كأنه أظفار هر. والهرهور: الكثير من الماء واللبن، إذا حلبت سمعت له هرهرة. قال: 3 سلم ترى الدالح منه أزورا ... إذا يعب في الطوي هرهرا والهرهرة والغرغرة يحكى بها بعض أصوات الهند والميذ 4 عند الحرب.'),
(853, 'ره', 'ره', 'ره', 'الرهرهة: حسن بصيص لون البشرة، وأشباه ذلك.'),
(854, 'هل', 'هل', 'هل', 'هل- خفيفة- استفهام، تقول: هل كان كذا وكذا؟ وهل لك في كذا وكذا؟ وقول زهير: 1 وذي نسب ناء بعيد وصلته ... بمالك لا يدري أهل أنت واصله اضطرار، لأن (هل) حرف استفهام وكذلك الألف، ولا يستفهم بحرفي استفهام. [قال الخليل لأبي الدقيش: هل لك في الرطب؟ قال: أشد (هل) وأوحاه فخفف، وبعض يقول: أشد الهل وأوحاه] وكل حرف أداة إذا جعلت فيه ألفا ولا ما صار اسما فقوي وثقل. وإذا جاءت الحروف اللينة في كلمة، نحو لو وأشباهها ثقلت، لأن الحرف اللين خوار أجوف لا بد له من حشو يقوى به إذا جعل اسما كقوله: 2 ليت شعري وأين مني ليت ... إن ليتا وإن لوا عناء والحروف الصحاح مستغنية بجروسها لا تحتاج إلى حشو فتترك على حالها. وتقول: هل السحاب بالمطر هلا، وآنهل بالمر انهلالا، وهو شدة آنصبابه، ويتهلل السحاب ببرقه أي: يتلألأ. ويتهلل الرجل فرحا. قال: 3 تراه إذا ما جئته متهللا ... كأنك تعطيه الذي أنت سائله والهليلة: أرض يستهل بها المطر، وما حواليها غير ممطور. والهلال: غرة القمر حين يهله الناس في غرة الشهر. يقال: أهل 1 الهلال ولا يقال: هل. والمحرم يهل بالإحرام إذا أوجب بالإحرام إذا أوجب الحرم على نفسه. وإنما قيل ذلك، لأنهم أكثر ما يحرمون إذا أهلوا الهلال فجرى ذلك على ألسنتهم. وهلل البعير تهليلا إذا استقوس وانحنى ظهره وآلتزق بطنه هزالا وإضاقا. قال: 2 إذا ارفض أطراف السياط وهللت ... جدوم المهاري عذبتهن صيدح والهلل: الفزع، يقال: حمل فلان فما هلل [عن] قرنه. وتقول: أحجم عنا هللا. قال كعب: 4 لا يقع الطعن إلا في نحورهم ... وما بهم عن حياض الموت تهليل والتهليل: قول لا إله إلا الله. والاستهلال: الصوت. وكل متهلل رافع الصوت أو خافضه فهو مهل ومستهل. وأنشد: 5 وألفيت الخصوم فهم لديه ... مبرشمة أهلوا ينظرونا والهلال: الحية الذكر. والهلهل: السم القاتل. والهلهلة: سخافة النسج. ثوب مهلهل. والمهلهلة من الروع: أردؤها. والهلاهل من وصف الماء: الكثير الصافي. ويقال: أنهج الثوب هلهالا.'),
(855, 'له', 'له', 'له', 'اللهلهة: مثل الهلهلة في النسج. قال: 1 أتاك بقول لهله النسج كاذب واللهلهة: المكان الذي يضطرب فيه السراب قال: 2 ومخفق من لهله ولهله');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(856, 'هن', 'هن', 'هن', 'الهن: كلمة يكنى بها عن اسم الإنسان. تقول: أتاني هن، والإنثى: هنه بفتح النون إذا وقفت عندها لظهور الهاء، فإذا مررت سكنت النون، لأنها بنيت في الأصل على التسكين، وصيرت الهاء تاء، كقولك: رأيت هنة 3 مقبلة [لم] 4 تصرف، لأنها اسم معرفة للمؤنث. وهاء التأنيث إذا سكن ما قبلها صارت تاء مع ألف الفتح الذي قبلها، كقولك: القناة والحياة. وهاء التأنيث أصل بنائها من التاء، ولكنهم فرقوا بين تأنيث الفعل وتأنيث الاسم، فقالوا في الفعل: فعلت. وفي الاسم: فعلة. وإنما وقفوا عند هذه التاء بالهاء من بين سائر الحروف، لأن الهاء ألين الحروف الصحاح، فجعلوا البدل صحيحا مثلها، ولم يكن في الحروف 1 حرف أهش من الهاء، لأن الهاء نفس. وأما هن فمن العرب من يسكن يجعلها مثل من فيجريها مجراها، والتنوين فيها أحسن. كقول الراجز: 2 إذ من هن قول وقول من هن'),
(857, 'نه', 'نه', 'نه', 'النهنهة: الكف. تقول: نهنهت فلانا إذا زجرته ونهيته. قال: 3 نهنه دموعك إن من ... يغتر بالحدثان عاجز'),
(858, 'هف', 'هف', 'هف', 'الهفيف: سرعة السير. هف يهف هفيفا. قال ذو الرمة: 4 إذا ما نعسنا نعسة قلت: غننا ... بخرقاء وارفع من هفيف الرواحل وزقاق الهفة: موضع من البطيحة، كثير القصباء، فيه مخترق للسفن. وجارية مهفهفة، ومهففة- لغة-: إذا كانت هيفاء، خميصة البطن، دقيقة الخصر.'),
(859, 'فه', 'فه', 'فه', 'رجل فه وفهيه: إذا جاءت منه سقطة أو جهلة من العي. ورجل فه: عي عن حجته. وامرأة فهة ... وقد فه يفه فهاهة وفها وفهة، وفههت يا رجل. ويقال: جئت لحاجة فأفهني عنها فلان إذا أنساكها.'),
(860, 'هب', 'هب', 'هب', 'هبت الريح تهب هبوبا، والنائم يهب هبا، والسيف يهب، إذا هز، هبة. والتيس يهب هبيبا للسفاد. والناقة تهب هبابا. قال: 1 فلها هباب في الزمام كأنها ... صهباء راح مع الجنوب جهامها وهبهب السراب إذا ترقرق، والهبهاب من أسماء السراب، والهبهاب لعبة لصبيان العراق والهبهبي: تيس الغنم، ويقال: بل راعيها. قال: 2 كأنه هبهبي نام عن غنم ... مستأور في سواد الليل مذؤوب'),
(861, 'به', 'به', 'به', 'البهبهي: الجسيم الجريء. قال: 3 لا تراه في حادث الدهر إلا ... وهو يغدو ببهبهي جريم والبهبهة: من هدير الفحل. والأبه: الأبح.'),
(862, 'هم', 'هم', 'هم', 'الهم: ما هممت به في نفسك. تقول: أهمني هذا الأمر. والهم: الحزن. والهمة: ما هممت به من أمر لتفعله. يقال: إنه لعظيم الهمة، وإنه لصغير الهمة. ويقال: أهمني الشيء، أي: أحزنني. وهمني، أذابني 1 . والمهمات من الأمور: الشدائد. والهمام: الملك لعظم همته. وتقول: لا يكاد ولا يهم كودا ولا هما ولا مهمة ولا مكادة. والهميم: دبيب هوام الأرض. والهوام: ما كان من خشاش الأرض، نحو العقارب وشبهها، الواحدة: هامة، لأنها تهم، أي: تدب. والانهمام في ذوبان الشيء واسترخائه بعد جموده وصلابته، مثل الثلج إذا ذاب. تقول: قد انهم. وآنهمت البقول إذا طبخت في القدر. والهاموم من الشحم كثير الإهالة. قال: 1 وآنهم هاموم السديف الواري والهمهمة: نحو أصوات البقر والفيلة وأشباه ذلك. والهمهمة: تردد الزئير في الصدر من الهم والحزن. ويقال للقصب إذا هزته الريح: إنه لهمهوم، ويقال للحمار إذا ردد نهيقه في صدره، إنه لهمهيم. قال: 2 خلى لها سرب أولاها وهيجها ... ومن خلفها لاحق الصقلين همهيم وأحب الأسماء إلى الله: عبد الله وهمام [لأنه ما من أحد إلا ويهم بأمر من الأمور، رشد أو غوى] 3 . ويقال: هو يتهمم رأسه، أي: يفليه. وسحابة هموم، أي: صبابة للمطر. والهم: الشيخ الفاني.'),
(863, 'مه', 'مه', 'مه', 'مه: زجر ونهي. ومهمهت قلت له: مه مه. والمهمه: الخرق الواسع الأملس. [وأما مهما فإن أصلها: ما ما، ولكن أبدلوا من الألف الأولى هاء ليختلف اللفظ. ف (ما) الأولى هي (ما) الجزاء، و (ما) الثانية هي التي تزاد تأكيدا لحروف الجزاء مثل أينما ومتى ما وكيفما. والدليل على ذلك أنه ليس شيء من حروف الجزاء إلا و (ما) تزاد فيه. قال الله [تعالى] : فإما تثقفنهم في الحرب الأصل: إن تثقفهم ... ] 4 .'),
(864, 'هبخ', 'هبخ', 'هبخ', '[أهملت الهاء مع الخاء في الثلاثي الصحيح إلا قولهم:] 1 . الهبيخة: الجارية التارة. وبالحميرية: كل جارية هبيخة. والهبيخى: مشية في تبختر، وقد اهبيخت اهبياخا، وهي تهبيخ. قال: 2 جر العروس ذيلها الهبيخا'),
(865, 'هنغ', 'هنغ', 'هنغ', '[لا توجد الهاء مع الغين إلا في هذه الحروف، وهي: الأهيغ والغيهق، والهينغ، والغيهب، والهلياغ. فأما الأهيغ فإنك ترى تفسيره في أول معتل الهاء. وأما الغيهق فهو النشاط ويوصف به العظم والترارة] 1 . الهينغة: المرأة المهانغة المضاحكة الملاعبة. قال: 2 قولا كتحديث الهلوك الهينغ وهانغت المرأة مهانغة، إذا غازلتها. [والهلياغ: شيء من صغار السباع. قال: وهلياغها فيها معا والغناجل] 3'),
(866, 'هبغ', 'هبغ', 'هبغ', 'الهبوغ: النوم. هبغ فلان يهبغ هبغا إذا نام قال: 4 هبغنا بين أرجلهن حتى ... تبخبخ حرذي رمضاء حامي'),
(867, 'غهب', 'غهب', 'غهب', 'الغيهب: شدة سواد الليل والجمل ونحوه. يقال: جمل غيهب: مظلم السواد. قال: 1 تلاقيتها والبوم يدعو بها الصدى ... وقد ألبست أفراطها ثني غيهب وغيهب عن هذا الشيء غهبا إذا غفلت عنه ونسيته. وأصبت هذا الصيد غهبا، أي: غفلة من غير تعمد.'),
(868, 'همغ', 'همغ', 'همغ', 'الهميغ: الموت الوحي، ويقال: إنما هو بالعين [المهملة] . قال الشاعر: 2 إذا بلغوا مصرهم عوجلوا ... من الموت بالهميغ الذاعط'),
(869, 'شهق', 'شهق', 'شهق', 'الشهيق ضد الزفير، فالشهيق رد النفس، والزفير إخراجه. شهق يشهق ويشهق شهيقا- لغتان- وجبل شاهق: ممتنع طولا، ويجمع: شواهق، وهو يشهق شهوقا.'),
(870, 'سهق', 'سهق', 'سهق', 'السهوق: كل شيء تر وآرتوى من سوق الشجر ونحوه، والسهوق: الطويل من الرجال. قال الشاعر 1 وظيف أزج الخطو ريان سهوق والسهوق: الكذاب. والسهوق من الرياح: التي تنسج العجاج.'),
(871, 'هزق', 'هزق', 'هزق', 'امرأة هزقة ومهزاق: لا تستقر في موضع. وحمار هزق: كثير الاستنار 2 . قال: 3 وشج ظهر الأرض رقاص الهزق'),
(872, 'قهز', 'قهز', 'قهز', 'القهز والقهز- لغتان: ضرب من الثياب تتخذ من صوف كالمرعزي، وربما خالطه الحرير يشبه به الشعر اللين. قال رؤبة يصف حمر الوحش: 4 وآدرعت من قهزها سرابلا ... أطار عنها الخرق الرعابلا يقول: سقط عنها العفاء، ونبت تحته شعر لين. قال: 1 كأن لون القهز في خصورها ... والقبطري البيض في تأزيزها'),
(873, 'زهق', 'زهق', 'زهق', 'زهقت نفسه، وهي تزهق زهوقا، أي: ذهبت. [وكل شيء هلك وبطل فقد زهق] ويقال للبئر البعيدة المهواة: زاهقة وزهوق. قال أبو ذؤيب: 3 وأشعث كسبه فضلات ثرل ... على أرجاء متلفة زهوق والزاهق: السمين من الدواب. قال زهير: 4 منها الشنون ومنها الزاهق الزهم ويقال: الزاهق: الشديد الهزال حتى تجد زهومة غثوثة لحمه. والزهم: السمين. والشنون: الذي بدا فيه الهزال، ويقال: بل هو الغاية في السمن. والزهم: الكثير الشحم. والزهق: الوهدة، وآنزهقت أيدي الدابة، إذا وقعت في وهدة ونحوها. قال: 5 كأن أيديهن تهوي في الزهق والزهزقة: ترقيص الأم الصبي. والزهزاق: آسم ذلك الفعل. والزهزقة في سوء الضحك كالقهقهة.'),
(874, 'قهد', 'قهد', 'قهد', 'القهد: من أولاد الضأن يضرب إلى بياض. والجمع: قهاد. وكذلك ولد البقرة الوحشية. قال: 1 نقود جيادهن ونفتليها ... ولا نعدو التيوس ولا القهادا'),
(875, 'دهق', 'دهق', 'دهق', 'الدهق: خشبتان يغمز بهما الساق، وآدهقت الحجارة ادهاقا، وهو شدة تلازمها، ودخول بعضها في بعض. قال: 2 ينصاح من جبلة رضم مدهق وكأس دهاق: ملأى. وأدقتها: شددت ملأها. والدهدقة: دوران البضع الكثير في القدر إذا غلت، تراها تعلو مرة وتسفل أخرى. قال حاتم طيء: 3 يقمص دهداق البضيع كأنه ... رءوس قطا كدر دقاق الحناجر'),
(876, 'هرق', 'هرق', 'هرق', 'هراقت السحابة ماءها تهريق فهي مهريقة، والماء مهراق. الهاء مفتوحة في كله، لأنها بدل من همزة أراق، وهرقت مثل أرقت. ومن قال: أهراق فقد أخطأ في القياس 1 . ويقال: مطر مهرورق، ودمع مهرورق. ويقال للغضبان: هرق على جمرك، أي: آصبب على غضبك ما تطفئه به. قال رؤبة: 2 هرق على جمرك أو تبين أي: تثبت. والمهرق: الصحيفة البيضاء يكتب فيها، ويجمع مهاريق. والمهرق: الصحراء الملساء، وجمعه: مهاريق.'),
(877, 'قهر', 'قهر', 'قهر', 'الله القاهر القهار. يقال: أخذهم قهرا، أي: من غير رضاهم، والقهر: الغلبة، والأخذ من فوق. والقهقر: الحجر. قال: 1 جئنا على كل كميت هيكل ... أخضر كالقهقر أو كالأحيل'),
(878, 'رهق', 'رهق', 'رهق', 'الرهق: جهل في الإنسان، وخفة في عقله. يقال: به رهق، ولم أسمع منه فعلا. ورجل مرهق: موصوف بالرهق. قال: 2 إن في شكر صالحينا لما يدحض ... قول المرهق الموصوم ورهق فلان فلانا إذا تبعه فقرب أن يلحقه. ورهق أيضا: غشي. قال الله عز وجل: ولا يرهق وجوههم قتر ولا ذلة 3 . والرهق: غشيان الشيء. تقول: رهقه ما يكره، أي: غشيه ذلك. والرهق: الكذب. قال: الكميت: 4 حلفت يمينا غير ما رهق ... بالله رب محمد وبلال والرهق: العظمة، وهو قوله: فزادوهم رهقا 5 والرهق: الظلم، وهو قوله: فلا يخاف بخسا ولا رهقا 6 والرهق: العيب. قال كعب بن زهير: 1 ما فيه قول ولا عيب يقال له ... عند الرهان سليم جنب الرهقا وتقول: أرهقناهم 2 الخيل فهم مرهقون. وأرهقتهم أمرا صعبا إذا حملتهم عليه. وقول الله عز وجل: سأرهقه صعودا 3 ، يقال: جبل في النار يكلف الله الكفار صعوده. والمراهق: الغلام الذي قارب الحلم. ورجل مرهق: إذا كان يظن به السوء. ورجل مرهق أيضا، أي: ينزل به الضيفان، يأتونه وقد أرهق الليل. وأرهقنا الصلاة، أي: استأخرنا عنها.'),
(879, 'قره', 'قره', 'قره', 'القره في الجسد كالقلح في الأسنان، وهو الوسخ. والنعت: أقره وقرهاء ومتقره.'),
(880, 'هقل', 'هقل', 'هقل', 'الهقل والهقلة: الفتيان من النعام.'),
(881, 'قهل', 'قهل', 'قهل', 'القهل كالقره في قشف الإنسان وقذر جلده. ورجل متقهل لا يتعاهد جسده بالماء والنظافة. قال: 1 مترهب متبتل متقهل ... طاوي النهار وليله ما يرقد وأقهل الرجل إذا تكلف ما يعيبه ويدنس نفسه. قال: 2 خليفة الله بلا إقهال وقهل الرجل قهلا، أي: استقل العطية وكفر النعمة.'),
(882, 'لهق', 'لهق', 'لهق', 'اللهق: الأبيض ليس بذي بريق ولا موهة كاليقف. إنما هو نعت للثور، والثوب والشيب. ورجل لهوق وهو يتلهوق، أي: يبدي من سخائه، ويفتخر على غير ما عليه سجيته. وفي الحديث: كان خلق النبي صلى الله عليه وعلى آله وسلم سجيه. ولم يكن تلهوقا 3 . أي: تخلقا. وبعير لهق. والأنثى: لهق. وقال في الشيب: 4 بان الشاب ولاح الواضح اللهق ... ولا أرى باطلا والشيب يتفق'),
(883, 'قله', 'قله', 'قله', 'القله لغة في القرة.'),
(884, 'نهق', 'نهق', 'نهق', 'النهق- جزم-: نبات يشبه الجرجير من أحرار البقول، يؤكل. والنهيق: صوت الحمار. وأخذه النهاق: إذا كثر نهيقه واشتد. ونواهق الدابة: عروق اكتنفت خياشيمها. الواحدة: ناهقة. وقد نهق ينهق وينهق معا 1 .'),
(885, 'نقه', 'نقه', 'نقه', 'نقه ينقه، معناه: فهم يفهم، فهو نقه: سريع الفطنة. ونقه من المرض ينقه نقوها فهو ناقه.'),
(886, 'فهق', 'فهق', 'فهق', 'الفهقة: عظم عند فائق الرأس، مشرف على اللهاة، وهو العظم الذي يسقط على اللهاة فيقال: فهق الصبي. قال: 2 قد يجأ الفهقة حتى تندلق أي: يجأ القفا حتى تسقط الفهقة من باطن. والفهق: اتساع كل شيء ينبع منه ماء أو دم. نقول: انفهقت الطعنة وانفهقت العين، وأرض تنفهق مياها عذابا. قال رؤبة: 1 صفقن أيديهن في الحوم الفهق ويروى: المهق. والفهق: الامتلاء. وقال: 2 وأطعن الطعنة النجلاء عن عرض ... تنقي المسابير بالإزباد والفهق والفيهق: الواسع من كل شيء، حتى قيل: مفازة فيهق. ورجل متفيهق، أي: متفتح بالبذخ، يقال: هو يتفيهق علينا بمال غيره.'),
(887, 'فقه', 'فقه', 'فقه', 'الفقه: العلم في الدين. يقال: فقه الرجل يفقه فقها فهو فقيه. وفقه يفقه فقها إذا فهم. وأفقهته: بينت له. والتفقه: تعلم الفقه.'),
(888, 'هقب', 'هقب', 'هقب', 'الهقب: الضخم الطويل من النعام. قال: 3 [شخت الجزارة مثل البيت سائره ... من المسوح] هقب شوقب خشب'),
(889, 'قهب', 'قهب', 'قهب', 'القهب: الأبيض من أولاد البقر والمعز ونحوه. يقال: إنه لقهب الإهاب، وإنه لقهاب قهابي، والأنثى: قهبة. والقهب: المسن في قول رؤبة: 1 إن تميما كان قهبا قهقبا وقوله: 2 إن تميما كان قهبا من عاد والقهبي: اليعقوب وهو الذكر من الحجل. قال: 3 فأضحت الدار قفرا لا أنيس بها ... إلا القهاب مع القهبي والحذف والقهوبة: من نصال السهام، ذات شعب ثلاث، وربما كانت حديدتين تنضمان أحيانا وتنفرجان. والجميع: القهوبات. والقهقب: الطويل العظيم الرغيب.'),
(890, 'بهق', 'بهق', 'بهق', 'البهق: بياض دون البرص. [قال رؤبة: كأنه في الجلد توليع البهق] 4'),
(891, 'هقم', 'هقم', 'هقم', 'رجل هقم: شديد الجوع، كثير الأكل. وهو يتهقم الطعام، أي: يتلقمه لقما عظاما متتابعة. وبحر هيقم: واسع بعيد القعر. قال: 1 ولم يزل عز تميم مدعما ... للناس يدعو هيقما وهيقما كالبحر ما لقمته تلقما'),
(892, 'همق', 'همق', 'همق', 'الهمقاق، واحدتها: همقاقة بوزن فعلالة ولا أظنه إلا دخيلا من كلام العجم، أو كلام بلعم خاصة، لأنها تكون بجبال بلعم. وهي حبة تشبه حب القطن في جماحة مثل الخشخاش، إلا أنها صلبة ذات شعب، يقلى حبه ويؤكل، يزيد في الجماع.'),
(893, 'قهم', 'قهم', 'قهم', 'القهقم: الفحل الضخم.'),
(894, 'مهق', 'مهق', 'مهق', 'مقه: المهق والمقه: بياض في زرقة، ويقال: المقه: أشدهما بياضا. وامرأة مهقاء ومقهاء، وسراب أمقه، أي: أبيض.'),
(895, 'قمه', 'قمه', 'قمه', 'قمه الشيء في الماء يقمهه إذا قمسه فارتفع رأسه أحيانا وآنغمر أحيانا، فهو قامه قال: تعدل أنضاد القفاف القمه القمه: من نعت القفاف.'),
(896, 'سهك', 'سهك', 'سهك', 'السهك: ريح كريهة تجدها من الإنسان إذا عرق. تقول: إنه لسهك الريح. قال: 2 سهكين من صدإ الحديد كأنهم ... تحت السنور جنة البقار وسهكت الريح، وسهكت سهوكا، وهو جري خفيف في لين. وفرس مسهك: سريع، ويقال: سهوكها: آستنانها يمينا وشمالا. قال ذو الرمة: 3 نضا البرد عنه وهو ذو من جنونه ... أجاري تسهاك وصوت صلاصل والساهكة من الرياح: التي تسهك التراب عن وجه الأرض. قال: 1 بساهكات دقق وجلجال وتقول: سهكت العطر ثم سحقته، فالسهك: كسرك إياه بالفهر. ويقال: بعينك ساهك مثل العائر، وهما من الرمد.'),
(897, 'كهد', 'كهد', 'كهد', 'اكوهد الشيخ والفرخ إذا ارتعد.'),
(898, 'كده', 'كده', 'كده', 'الكده: صكة بحجر ونحوه يؤثر أثرا شديدا. قال: 2 وخاف صقع القارعات الكده ... وخبط صهميم اليدين عيده'),
(899, 'هتك', 'هتك', 'هتك', 'الهتك: أن تجذب سترا فتشق منه طائفة، أو تقطعه، فيبدو ما وراءه منه. يقال: هتك الله ستر الفاجر. ورجل مهتوك الستر متهتكه. ورجل مستهتك، لا يبالي أن يهتك ستره عن عورته. وكل شيء آنشق فقد تهتك وآنهتك، قال يصف الكلأ: 1 : منهتك الشعران نضاح العذب والهتكة: ساعة من الليل للقوم إذا ساروا. يقال: سرنا هتكة من آخر الليل، وقد هاتكناه إذا سرنا في دجاه. قال: 2 هاتكته حتى آنجلت أكراؤه يصف الليل والبعير.'),
(900, 'كهر', 'كهر', 'كهر', 'كهرت الرجل أكهره كهرا، إذا إستقبلته بوجه عابس تهاونا به، وبه تفسير قراءة ابن مسعود: فأما اليتيم فلا تكهر 1 . وكهر النهار: ارتفاعه في شدة الحر.'),
(901, 'كره', 'كره', 'كره', 'يقال فعلته على كره وفعلته كرها، إذا ضموا وخففوا قالوا: كره وإذا فتحوا قالوا: كره. والكره: المكروه. ورجل كره متكره. وأمر كريه مستكره، مكروه. وامرأة مستكرهة: غصبت نفسها فأكرهت على ذلك. وأكرهته: حملته على أمر وهو كاره. والكريهة: الشدة في الحرب، وكذلك الكرائه [وهي] نوازل الدهر. وتقول: كرهته كراهة وكراهية ومكرهة. وكره إلي كذا تكريها: صيره عندي بحال كراهة. وجمل كره، شديد الرأس. قال: 2 كره الحجاجين شديد الأراد والكرهاء: أعلى النقرة بلغة هذيل 3 .'),
(902, 'هكل', 'هكل', 'هكل', 'الهيكل: الفرس الطويل علوا وعدوا. قال: 1 بمنجرد قيد الأوابد هيكل والهيكل: بيت للنصارى فيه صنم على خلقة مريم عليها السلام فيما يذكر، قال: 2 مشي النصارى حول بيت الهيكل'),
(903, 'هلك', 'هلك', 'هلك', 'الهلك: الهلاك. والاهتلاك: رمي الإنسان نفسه في تهلكة. والتهلكة: كل شيء يصير عاقبته إلى الهلاك. والقطاة تهتلك من خوف البازي، أي: ترمي نفسها في المهالك. وقوم هلكى وهالكون. والهلاك: الصعاليك الذين ينتابون الناس طلبا لمعروفهم من سوء الحال. قال جميل: 3 أبيت مع الهلاك ضيفا لأهلها ... وأهلي قريب موسعون ذوو فضل وهالك أهل: الذي يهلك في أهله، وكذلك الذي يهلك أهله، قال: 4 وهالك أهل يجنونه ... كآخر في أهله لم يجن ومفازة هالكة من سلكها، أي: هالكة السالكين. قال العجاج: 1 ومهمه هالك من تعرجا أي: يهلك من تعرج به عن الطريق. والهلكة: مشرفة المهواة في جو السكاك، قال ذو الرمة: 2 ترى قرطها في واضح الليت مشرفا ... على هلك في نفنف يتطوح والهلوك: المرأة الفاجرة. والهالكي: الحداد.'),
(904, 'كهل', 'كهل', 'كهل', '[الكهل: الذي وخطه الشيب ورأيت له بجالة] 3 . ورجل كهل، وامرأة كهلة. وقل ما يقال للمرأة: كهلة، إلا أن يقولوا: شهلة كهلة. واكتهلت الروضة إذا عمها نورها، قال: 4 [يضاحك الشمس منها كوكب شرق] ... مؤزر بعميم النبت مكتهل ونعجة مكتهلة: مختمرة الرأس بالبياض. والكاهل: مقدم الظهر، مما يلي العنق، وهو الثلث الأعلى، فيه ست فقرات.'),
(905, 'كهن', 'كهن', 'كهن', 'كهن الرجل يكهن كهانة، وقلما يقال إلا تكهن الرجل. وتقول: لم يكن كاهنا، ولقد كهن، [ويقال] : كهن لهم إذا قال لهم قول الكهنة. وفي الحديث: وليس منا من تكهن أو تكهن له.'),
(906, 'نهك', 'نهك', 'نهك', 'النهك: التنقص. نهكته الحمى إذا رئي أثر الهزال فيه من المرض، فهو منهوك، وبدت فيه نهكة المرض، أي: أثر الهزال. وانتهكت حرمة فلان، إذا تناولتها بما لا يحل. وفي الحديث: انهكوا وجوه القوم 1 ... أي: آبلغوا جهدهم. ورجل نهيك، وقد نهك نهاكة، وهو الجريء الشجاع كالأسد. والنهيك: البئيس. وسيف نهيك: قاطع، ماض. وتقول: ما ينهك فلان يصنع كذا، 2 أي: ما ينفك. قال: 3 لن ينهكوا صفعا إذا أرموا أي: ضربا إذا سكتوا.'),
(907, 'كنه', 'كنه', 'كنه', 'كنه كل شيء: غايته، وفي بعض المعاني: وقته ووجهه. تقول: بلغت كنه الأمر، أي: غايته. وفعلته في غير كنهه، أي: وجهه.'),
(908, 'نكه', 'نكه', 'نكه', 'نكهت فلانا وآستنكهته، أي: تشممت ريح فمه. والاسم: النكهة. واستنكهت فلانا فنكه علي، أي: أوجدني ريح نكهته، ونكهت على فلان. أي: أشممته نكهتي. قال: 1 نكهت مجالدا فوجدت منه ... كريح الكلب مات حديث عهد'),
(909, 'كهف', 'كهف', 'كهف', 'الكهف: كالمغارة في الجبل إلا أنه واسع، فإذا صغر فهو غار، وجمعه: كهوف. قال: 2 وكنت لهم كهفا حصينا وجنة ... يؤول إليها كهلها ووليدها'),
(910, 'فكه', 'فكه', 'فكه', 'الفاكهة قد اختلف فيها، فقال بعض العلماء: كل شيء قد سمي في القرآن من الثمار، نحو العنب، والرمان فإنا لا نسميه فاكهة، ولو حلف أن لا يأكل فاكهة فأكل عنبا ورمانا لم يكن حانثا. وقال آخرون: كل الثمار فاكهة، وإنما كرر في القرآن فقال عز وجل: فيهما فاكهة ونخل ورمان 1 ، لتفضيل النخل والرمان على سائر الفواكه. وذلك [أسلوب] 2 اللغة العربية، كما قال تعالى: وإذ أخذنا من النبيين ميثاقهم ومنك ومن نوح وإبراهيم وموسى وعيسى ابن مريم 3 وكرر هؤلاء للتفضيل على النبيين، ولم يخرجوا منهم وقال من خالف: لو كانا فاكهة ما كررا. وفكهت القوم بالفاكهة تفكيها، وفاكهتهم مفاكهة بملح الكلام والمزاح، والاسم: الفكيهة والفكاهة. وتفكهنا من كذا، أي: تعجبنا، ومنه قوله [تعالى] : فظلتم تفكهون 4 ، أي: تعجبون. وقوله عز وجل: فاكهين بما آتاهم ربهم 5 أي: ناعمين معجبين بما هم فيه، ومن قرأ (فكهين) فمعناه: فرحين، ويختار ما كان لأهل الجنة: فاكهين، وما كان لأهل النار: فكهين، أي: أشرين بطرين. والفكاهة: المزاح، والفاكه: المازح. ويقال في قوله تعالى: فظلتم تفكهون : تندمون. وأفكهت الناقة إذا رأيت في لبنها خثورة قبل أن تضع فهي: مفكه. والفكه: الطيب النفس.'),
(911, 'كهب', 'كهب', 'كهب', 'الكهبة: غبرة مشربة سوادا في ألوان الإبل خاصة. يقال: جمل أكهب، وناقة كهباء.'),
(912, 'هكم', 'هكم', 'هكم', 'الهكم: المقتحم على ما لا يعنيه، المعترض للناس بالشر. قال: 1 تهكم حرب على جارنا ... وألقى عليه له كلكلا'),
(913, 'همك', 'همك', 'همك', 'انهمك فلان في كذا، إذا لج وتمادى فيه. يقال: ما الذي همكه فيه؟'),
(914, 'مهك', 'مهك', 'مهك', 'مهكة الشباب: نفحته، وامتلاؤه وارتواؤه، وماؤه. يقال شاب ممهك بوزن مفتعل.'),
(915, 'كهم', 'كهم', 'كهم', 'كهم الرجل يكهم كهاما إذا كان بطيئا عن النصرة والحرب. وفرس كهام: بطيء عن الغاية. وسيف كهام: كليل عن الضريبة. ولسان كهام: بطيء عن البلاغة. وكهمته الشدائد، أي: نكصته عن الإقدام. والكهامة: المتهيب، وكذلك الكهكامة. قال: ولا كهكامة برم ... إذا ما اشتدت الحقب'),
(916, 'كمه', 'كمه', 'كمه', 'الكمه: العمى الذي يولد عليه ابن آدم. وقد جاء في الشعر من عرض حادث. قال: 2 كمهت عيناه حتى آبيضتا ... فهو يلحى نفسه لما نزع'),
(917, 'جهش', 'جهش', 'جهش', 'جهشت نفسي وأجهشت إذا نهضت إليك وهمت بالبكاء. قال لبيد: 3 باتت تشكى إلي الموت مجهشة ... وقد حملتك سبعا بعد سبعينا'),
(918, 'جهض', 'جهض', 'جهض', 'الجهيض: السقط الذي تم خلقه، ونفخ فيه روحه من غير أن يعيش، قال: 1 يطرحن بالمهامه الأغفال ... كل جهيض لثق السربال ويقال للناقة خاصة إذا ألقت ولدها: أجهضت فهي مجهض، ويجمع مجاهيض، والاسم: الجهاض، قال: 2 في حراجيج كالحني مجاهيض ... يخدن الوجيف وخد النعام والجاهض: الحديد النفس، وفيه جهوضة وجهاضة، أي: حدة.'),
(919, 'هجس', 'هجس', 'هجس', 'الهجس: ما وقع في خلدك. [تقول] : هجس في قلبي هم وأمر. قال الشاعر في فرسه: 3 فطأطأت النعامة من بعيد ... وقد وقرت هاجسها وهجسي أي: همها وهمي. وقوله: وقرت، أي: قلت لها: قري فلن يدركك إلا ما قضى الله وقدره.'),
(920, 'هزج', 'هزج', 'هزج', 'الهزج: صوت مطرب، ورعد هزج بالصوت، وعود هزج، ومغن هزج، يهزج الصوت تهزيجا. والهزج: ضرب من أعاريض الشعر وهو: مفاعيلن مفاعيلن مفاعيلن مفاعيلن، أربعة أجزاء على هذا البناء كله.'),
(921, 'جهز', 'جهز', 'جهز', 'جهزت القوم تجهيزا، إذا تكلفت لهم جهازهم للسفر، وكذلك جهاز العروس والميت، وهو ما يحتاج إليه في وجهه. وتجهزوا جهازا. وسمعت أهل البصرة يخطئون من يقول الجهاز [بالكسر] 1 . وأجهزت على الجريح: أثبت قتله. وموت مجهز، أي: وحي. وجهيزة: اسم امرأة، خليقة في جسمها رعناء يضرب بها المثل في الحمق. قال: 2 كأن صلا جهيزة حين قامت ... حباب الماء حالا بعد حال'),
(922, 'هجد', 'هجد', 'هجد', 'هجد القوم هجودا، أي: ناموا، وتهجدوا، أي: استيقظوا لصلاة أو لأمر. وقوله [تعالى] : ومن الليل فتهجد به نافلة لك [ 3 ] ، أي: بالقرآن في الصلاة، أي: انتبه بعد النوم نافلة، أي: فضيلة.'),
(923, 'هدج', 'هدج', 'هدج', 'الهدجان: مشية الشيخ، ونحوه. هدج الشيخ، وهدجت الريح، أي: حنت وصوتت. والتهدج: تقطع الصوت. وهدج الظليم وهو مشي وسعي وعدو. كل ذلك في آرتعاش، قال: 1 أصك نغضا لا يني مستهدجا والهودج: مركب لنساء الأعراب، وليس بفودج، ويجمع: الهوادج.'),
(924, 'جهد', 'جهد', 'جهد', 'الجهد: ما جهد الإنسان من مرض، أو أمر شاق فهو مجهود [والجهد لغة بهذا المعنى] 2 والجهد: شيء قليل يعيش به المقل على جهد العيش. والجهد: بلوغك غاية الأمر الذي [لا] 3 تألو عن الجهد فيه. تقول: جهدت جهدي، واجتهدت رأيي ونفسي حتى بلغت مجهودي. وجهدت فلانا: بلغت مشقته، وأجهدته على أن يفعل كذا. وأجهد القوم علينا في العداوة. وجاهدت العدو مجاهدة، وهو قتالك إياه.'),
(925, 'هرج', 'هرج', 'هرج', 'الهرج: القتال والاختلاط. تقول: رأيتهم يتهارجون، أي: يتسافدون. وبات فلان يهرجها، من ذلك.'),
(926, 'جهر', 'جهر', 'جهر', 'جهر بكلامه وصلاته وقراءته يجهر جهارا، وأجهر بقراءته- لغة. وجاهرتهم بالأمر، أي: عالنتهم. وآجتهر القوم فلانا، أي: نظروا إليه عيانا جهارا. وكل شيء بدا فقد جهر. ورجل جهير إذا كان في الجسم والمنظر مجتهرا. وكلام جهير، وصوت جهير، أي: عال، والفعل: جهر جهارة. قال: 2 ويقصر دونه الصوت الجهير وجهرت البئر: أخرجت ما فيها من الحمأة والماء فهي مجهورة، قال: 3 وإن وردنا آجنا جهرناه والجهور: الجريء المقدم الماضي. والجهور: الصوت العالي. ونعجة جهراء، وكبش أجهر، أي: لا يبصران في الشمس، ويقال في كل شيء. والجوهر: كل حجر يستخرج منه شيء ينتفع به. وجوهر كل شيء: ما خلقت عليه جبلته. وآجتهرت الجيش، أي: كثروا في عيني حين رأيتهم، وجهر لغة. قال العجاج: 1 كأنما زهاؤه لمن جهر'),
(927, 'جره', 'جره', 'جره', 'سمعت جراهية القوم، وهو كلامهم وعلانيتهم دون سرهم.'),
(928, 'رهج', 'رهج', 'رهج', 'الرهج: الغبار.'),
(929, 'هجل', 'هجل', 'هجل', 'الهجل: كالغائط مطمئن موطئه صلب، منفرج بين الجبال. قال: 2 يدع الرمال دكادكا وهجالا والهوجل: المفازة البعيدة، وقول الشاعر: 1 الهوجل المتعسف من جعل المتعسف فاعلا فهو الدليل، ومن جعله مفعولا فهو المفازة.'),
(930, 'هلج', 'هلج', 'هلج', 'الهليلج: من الأدوية، الواحدة بالهاء.'),
(931, 'جهل', 'جهل', 'جهل', 'الجهل: نقيض العلم 2 . تقول: جهل فلان حقه، وجهل علي، وجهل بهذا الأمر. والجهالة: أن تفعل فعلا بغير علم. والجاهلية الجهلاء: زمان الفترة قبل الإسلام.'),
(932, 'لهج', 'لهج', 'لهج', 'لهج فلان بكذا وكذا: أي: أولع به. ولهج الفصيل بأمه يلهج، إذا تناول ضرعها يمتص، [وهو فصيل لاهج] 3 . وألهجت الفصيل إذا جعلت في فيه خلالا كي لا يصل إلى الرضاع. قال أبو النجم: يضرب لحي لاهج مخلل وقال: 4 يرى بسفا البهمى أخلة ملهج واللهجة: طرف اللسان، ويقال: جرس الكلام، ويقال: فصيح اللهجة [واللهجة. وهي لغته التي جبل عليها فاعتادها، ونشأ عليها] 1 ورجل ملهج بكذا، أي: مولع به، قال العجاج: 2 رأسا بتهضاض الرءوس ملهجا ولهوجت اللحم، إذا لم تنعم شيه، قال: 3 ولحم بلا نار أكلت ملهوجا'),
(933, 'جله', 'جله', 'جله', 'الجله: أشد من الجلح، وهو ذهاب الشعر من الجبين. قال: 4 براق أصلاد الجبين الأجله والجلهتان: جانبا الوادي إذا كان فيه صلابة. قال: بالجلهتين ظباؤها ونعامها'),
(934, 'هجن', 'هجن', 'هجن', 'الهاجن: العناق التي تحمل قبل وقت السفاد، والجميع: الهواجن، ولم أسمع له فعلا. والهجان من الأبل: البيض الكرام. ناقة هجان وبعير هجان، ويجمع على الهجائن. وأرض هجان إذا كانت تربتها بيضاء. قال: 1 بأرض هجان الترب وسمية الثرى ... عذاة نأت عنها المؤوجة والبحر ويقال للقوم الكرام: 2 إنهم لمن سراة الهجان. قال: 3 ومثل سراة قومك لم يجاروا ... إلى الربع الهجان ولا الثمين والهجين: ابن العربي من الأمة الراعية التي لا تحصن، فإذا حصنت فليس ولدها بهجين، والجميع: الهجناء. والاسم من الهجين: هجانة وهجنة، وقد هجن هجانة وهجنة. والهجنة في الكلام: ما يلزمك منه عيب. تقول: لا تفعله فيكون عليك هجنة.'),
(935, 'نهج', 'نهج', 'نهج', 'طريق نهج: واسع واضح، وطرق نهجة. ونهج الأمر وأنهج- لغتان- أي: وضح. ومنهج الطريق: وضحه. والمنهاج: الطريق الواضح. قال: 4 وأن أفوز بنور أستضيء به ... أمضي على سنة منه ومنهاج والنهجة: الربو يعلو الإنسان والدابة، ولم أسمع منه فعلا. ويقال للثوب إذا بلي ولما يتشقق: قد نهج ونهج وأنهج. وأنهجه البلى، قال: 1 وكيف رجائي جدة الناهج البالي وقال: 2 من طلل كالأتحمي أنهجا وقال: 3 إذا ما أديم القوم أنهجه البلى ... قديما فلو كتبته لتخرما'),
(936, 'جهن', 'جهن', 'جهن', 'جارية جهانة، أي: تارة ناعمة.'),
(937, 'نجه', 'نجه', 'نجه', 'نجهت الرجل نجها، إذا استقبلته بما ينهنهه عنك، فينقدع. وتنجهته أيضا بمعنى نجهته، قال: 4 كعكعته بالرجم والتنجه وفي الحديث بعد ما نجهها عمر 5 ، أي: بعد ما ردها وانتهرها'),
(938, 'هجف', 'هجف', 'هجف', 'الهجف: الظليم المسن. قال: 1 هجفا كأن به أولقا ... إذا حاول الشد من حملته'),
(939, 'هبج', 'هبج', 'هبج', 'الهبج: الضرب بالخشب، كما يهبج الكلب إذا قتل. والتهبيج: شبه الورم.'),
(940, 'بهج', 'بهج', 'بهج', 'البهجة: حسن لون الشيء، ونضارته. ورجل بهج. أي: مبتهج بأمر يسره، والمرأة بالهاء، وقد بهجت بهجة وهي مبهاج قد غلبت عليها البهجة، [وقد تباهج الروض إذا كثر النور] قال: 2 نوارها متباهج يتوهج يصف الروضة.'),
(941, 'جبه', 'جبه', 'جبه', 'الجبهة: مستوى ما بين الحاجبين إلى الناصية. والأجبه: العريض الجبهة. والجبه: مصدره. قال رؤبة: 1 من عصلات الضيغمي الأجبه وجبهته: استقبلته بكلام فيه غلظ. والجبهة: اسم يقع على الخيل لا يفرد. والجبهة: النجم الذي يقال له: جبهة الأسد.'),
(942, 'هجم', 'هجم', 'هجم', 'الهجمة من الإبل: ما بين التسعين إلى المائة، فإذا بلغت مائة فهي: هنيدة. وهجمنا على القوم هجوما، أي: انتهينا إليهم بغتة، وهجمنا عليهم الخيل، ولا يقال: أهجمنا. وبيت مهجوم، إذا حلت أطنابه فانضمت سقابه، أي: أعمدته، وكذلك إذا وقع ... قال علقمة: 2 صعل كأن جناحيه وجؤجؤه ... بيت أطافت به خرقاء، مهجوم والهجم: الحلب، وقوله: 1 فاهتجم العبدان من أخصامها أي: احتلب، والهجيمة من اللبن: الثخين. والهيجمانة: اسم امرأة. وآنهجمت عينه: دمعت. وهجمت العين، أي: غارت [تهجم] هجما وهجوما. وفي حديث النبي (صلى الله عليه وسلم) أنه قال لعبد الله بن عمر حين ذكر قيامه بالليل، وصيامه بالنهار: إنك إذا فعلت ذلك هجمت عيناك، ونفهت نفسك 2 . والهجم: السوق. والهجم: القدح الضخم. قال: 3 نتملأ الهجم عفوا وهي وادعة ... حتى تكاد شفاه الهجم تنثلم'),
(943, 'همج', 'همج', 'همج', 'الهمج: كل دود ينفقىء عن ذباب أو بعوض. وهمج الناس: رذالتهم والهميج: الخميص البطن. وآهتمجت نفسه إذا ضعفت من حر أو جهد. والهمج: الجوع أيضا.'),
(944, 'جهم', 'جهم', 'جهم', 'رجل جهم الوجه، أي: غليظه، وفيه جهومة، أي: غلظ، وقد جهم الوجه جهومة. وتجهمت له، أي: استقبلته بوجه كريه. وربما قيل: جهم الركب، يعني: متاع المرأة. ورجل جهوم، أي: عاجز ضعيف. قال: 1 وبلدة تجهم الجهوما أي: بلدة تستقبل السائر بما يكره. والجهام: الغيم الخفيف الذي هراق ماءه مع الريح. وجيهم: موضع بالغور كثير الجن. قال: 2 أحاديث جن زرن جنا بجيهما'),
(945, 'مهج', 'مهج', 'مهج', 'المهجة: دم القلب، ولا بقاء للنفس بعد ما تراق مهجتها، والأمهجان: الرقيق من اللبن ما لم يتغير طعمه.'),
(946, 'شهد', 'شهد', 'شهد', 'الشهد: العسل ما لم يعصر من شمعه، شهاد، والواحدة: شهدة وشهدة. والشهادة أن تقول: آستشهد فلان فهو شهيد، وقد شهد علي فلان بكذا شهادة، وهو: شاهد وشهيد. والتشهد في الصلاة من قولك: أشهد أن لا إله إلا الله، وأشهد أن محمدا عبده ورسوله. وفلان يشهد بالخطبة. منه. والمشهد: مجمع الناس، والجمع: مشاهد. ومشاهد مكة: مواضع المناسك، وقول الله عز وجل وشاهد ومشهود 1 قيل في تفسيره: الشاهد هو النبي صلى الله عليه وعلى آله. والمشهود هو يوم القيامة. ولغة تميم: شهيد بكسر الشين، يكسرون فعيلا في كل شيء كان ثانيه أحد حروف الحلق، وكذلك: سفلى مضر. ولغة شنعاء، يكسرون كل فعيل، والنصب: اللغة العالية. والشهود: ما يخرج على رأس الصبي، واحدها: شاهد، وهي الأغراس، والواحدة: غرس، قال: 2 فجاءت بمثل السابري تعجبوا ... له والثرى ما جف عنها شهودها وهي: الأغراس.'),
(947, 'دهش', 'دهش', 'دهش', 'شده: الدهش: قهاب العقل، من الذهل والوله ونحوه. دهش الرجل فهو دهش وشده فهو مشدوه شدها، وأدهشه الأمر، وأشدهه.'),
(948, 'هدش', 'هدش', 'هدش', 'هدش الكلب فانهدش، وهتش فاهتتش، أي: حرش فاحترش، ولا يقال إلا للسباع. وفي هذا المعنى: حتش الرجل، أي: هيج للنشاط.'),
(949, 'هشر', 'هشر', 'هشر', 'الهيشر: نبات رخو فيه طول، على رأسه برعومة كأنه عنق الرأل، قال: 1 كأن أعناقها كراث سائفة ... طارت لفائفه، أو هيشر سلب أي: مسلوب الورق. ورجل هيشر، أي: رخو ضعيف. والمهشار من الإبل: التي تضع قبل الإبل، وتلقح في أول ضربة، ولا تماجن.'),
(950, 'هرش', 'هرش', 'هرش', 'رجل هرش، أي: مائق جاف. والمهارشة في الكلاب ونحوها كالمخارشة، ويقال: هارش بين الكلاب. قال: 2 كأن طبييها إذا ما درا ... جروا ربيض هورشا فهرا'),
(951, 'شهر', 'شهر', 'شهر', 'الشهر والأشهر عدد، والشهور جماعة. والمشاهرة: المعاملة شهرا بشهر. والشهرية: ضرب من البراذين، وهو بين المقرف من الخيل والبرذون. والشهرة: ظهور الشيء في شنعة حتى يشهره الناس، ورجل مشهور ومشهر. وشهر سيفه، إذا انتضاه فرفعه على الناس. وفي الحديث: ليس منا من شهر علينا السلاح 1 . وقال: 2 وقد لاح للساري الذي أكمل السرى ... على أخريات الليل فتق مشهر أي: صبح مشهور وامرأة شهيرة، وهي العريضة الضخمة، وأتان شهيرة مثلها.'),
(952, 'رهش', 'رهش', 'رهش', 'الرهش: ارتهاش في الدابة، وهو أن تصطك يداه في مشيه، فيعقر رواهشه، أي: عصب يديه، والواحدة: راهشة. وكذلك في يد الإنسان رواهشها، [وهي] عصبها من باطن الذراع. والارتهاش: ضرب من الطعن في عرض، قال: 3 أبا خالد لولا انتظاري نصركم ... أخذت سناني فارتهشت به عرضا وارتهاشه: تحريك يديه. ورجل رهشوش: حيي سخي رقيق الوجه. ولقد ترهشش، وهو بين الرهشة والرهشوشية، قال: 1 أنت الجواد رقة الرهشوش أي: ترق رقة الرهشوش.'),
(953, 'شره', 'شره', 'شره', 'رجل شره: شرهان النفس، حريص. هيا شراهيا، بالعبرانية: يا حي يا قيوم.'),
(954, 'شهل', 'شهل', 'شهل', 'الشهل: شهلة في العين ويقال للمرأة النصف العاقلة: شهلة كهلة، نعت لها خاصة، لا يوصف الرجل بالشهل والكهل. [والشهلة: العجوز] 2 قال: 3 باتت تنزى دلوها تنزيا ... كما تنزي شهلة صبيا والمشاهلة: المشارة 1 ، يقال: كانت بينهم مشاهلة، أي: لحاء ومقارصة.'),
(955, 'نهش', 'نهش', 'نهش', 'النهش بالفم كالنهس، إلا أن النهش تناول من بعيد، كنهش الحية، والنهس: القبض على اللحم ونتفه.'),
(956, 'شفه', 'شفه', 'شفه', 'الشفة، حذفت منها الهاء، وتصغيرها: شفيهة، والجميع: الشفاه، وإذا ثلثوا قالوا: شفهات وشفوات، الهاء أقيس، والواو أعم، لأنهم شبهوها بالسنوات، ونقصانها حذف هائها. والمشافهة بالكلام: المواجهة من فيك إلى فيه. وماء مشفوه، أي: مطلوب مسئول، وهو الذي كثر عليه الناس، وأنفدوه إلا أقله، وإذا جمعوا قالوا: مياه مشفوهة. وطعام مشفوه، أي: قليل.'),
(957, 'هبش', 'هبش', 'هبش', 'يقال: تهبشوا، وتحبشوا، أي: اجتمعوا، والاسم: الهباشة والحباشة، أي: الجماعة.'),
(958, 'شهب', 'شهب', 'شهب', 'الشهب والشهبة: لون بياض يصدعه سواد في خلاله. والعنبر الجيد لونه أشهب. وآشهاب رأسه، إذا غلب بياضه سواده، واشتهب كذلك. ويوم أشهب، أي: ذو ريح باردة، وليلة شهباء كذلك، وكتيبة شهباء لما فيها من بياض السلاح في خلال السواد. وآشهاب الزرع، إذا هاج وفي خلاله خضرة قليلة. والشهاب: شعلة من نار، والجميع: الشهب والشهبان، ويقال للرجل الماضي في الحرب: شهاب حدب.'),
(959, 'بهش', 'بهش', 'بهش', 'رجل بهش: هش لين. وبهشت إلى فلان: حننت إليه. والبهش: رديء المقل، ويقال: ما قد أكل قرفه، قال: 1 يثورن ما تحت الحصى من لبانه ... كما يحتفي البهش الدقيق الثعالب'),
(960, 'شبه', 'شبه', 'شبه', 'الشبه: ضرب من النحاس يلقى عليه دواء فيصفر، وسمي شبها، لأنه شبه بالذهب. وفي فلان شبه من فلان وهو شبهه وشبهه، أي: شبيهه. وتقول: شبهت هذا بهذا [وأشبه فلان فلانا] 1 ، وقال الله عز وجل: آيات محكمات هن أم الكتاب، وأخر متشابهات ، أي: يشبه بعضها بعضا. والمشبهات من الأمور: المشكلات، قال: 3 واعلم بأنك في زمان ... مشبهات هن هنه وشبه فلان علي، إذا خلط. واشتبه الأمر، أي: اختلط. ورأيتك مثله في الشبه والشبه، وفيه مشابه من فلان، ولم أسمع: فيه مشبهة من فلان. وتقول: إني لفي شبهة منه. وحروف الشين يقال لها: أشباه، وكل شيء يكون سواء فإنها أشباه، قال: 4 [كعقر الهاجري إذا آبتناه] ... بأشباه حذين على مثال والشباه: حب على لون الحرف يشرب للدواء. والشبهان: الثمام، قال: 5 وأسفله بالمرخ والشبهان'),
(961, 'هشم', 'هشم', 'هشم', 'الهشم: كسر الشيء الأجوف والشيء اليابس. هشمت أنفه، أي: كسرت قصبته. والهاشمة: شجة تكسر العظم. والريح إذا كسرت اليبيس، يقال: هشمته. وتهشم الشجر إذا يبس وتكسر، قال: 1 إذا همرنا رأسه تهشما أي: تكسر. وهاشم أبو عبد المطلب جد النبي صلى الله عليه وعلى آله، أول من ثرد الثريد وهشمه فسمي به. قالت ابنته: 2 عمرو العلا هشم الثريد لقومه ... ورجال مكة مسنتون عجاف'),
(962, 'همش', 'همش', 'همش', 'الهمش: السريع العمل بأصابعه. والهمشة: الكلام والحركة، وقد همش القوم يهمشون.'),
(963, 'شهم', 'شهم', 'شهم', 'الشهم، وجمعه الشهوم: السادة الأنجاد النافذون في الأمور. وفرس شهم: سريع نشيط قوي. وشهمت الفرس أشهمه شهما. والمشهوم: كالمذعور سواء. والشيهم: الدلدل، وما عظم [شوكه] 1 من ذكران القنافذ. والمشهوم: الحديد الفؤاد. قال ذو الرمة: 2 [طاوى الحشا قصرت عنه محرجة] ... مستوفض من نبات القفر مشهوم'),
(964, 'ضهد', 'ضهد', 'ضهد', 'ضهد فلان فلانا واضطهده، إذا قهره وأذله. [وهو مضطهد: مقهور وذليل] 3 .'),
(965, 'ضهر', 'ضهر', 'ضهر', 'الضهر: خلقة في الجبل من صخر يخالف جبلته 4 .'),
(966, 'هضل', 'هضل', 'هضل', 'الهيضل: جماعة متسلحة في الحرب أمرهم واحد، فإذا جعل اسما قيل: هيضلة. قال: 1 أزهير إن يشب القذال فإنني ... كم هيضل مصع لففت بهيضل والهيضلة: الضخمة من النساء النصف، ومن النوق الغزيرة. [والهيضلة] : 2 أيضا أصوات الناس.'),
(967, 'ضهل', 'ضهل', 'ضهل', 'ضهلت الناقة، إذا قل لبنها، فهي: ضهول. ويقال: إنها لضهل بهل: ما يشد لها صرار، ولا يروى لها حوار. قال ذو الرمة: 3 بها كل خوار إلى كل صعلة ... ضهول ورفض المذرعات القراهب ويقال: أعطيته ضهلة من مال، أي: عطية [قليلة] 4 . وضهل السراب: قل ورق. وضهل: صار كالضحضاح. وحمة ضاهلة، وعين ضاهلة، أي: نزرة الماء. والحمة: البئر نفسها.'),
(968, 'نهض', 'نهض', 'نهض', 'النهوض: البراح من الموضع. والناهض: الفرخ الذي وفر جناحاه، ونهض للطيران، قال لبيد: 1 رقميات عليها ناهض ... تكلح الأروق منهم والأيل ونهض البعير: ما بين المنكب والكتف. قال [هميان بن قحافة:] 2 أبقى السناف أثرا بأنهضه'),
(969, 'هضب', 'هضب', 'هضب', 'الهضبة: المطرة الدائمة. العظيمة القطر [وجمعها: هضب] 3 . يقال: أصابتهم الهضوبة من المطر، ويجمع: أهاضيب. وهضبتهم السماء، أي: بلتهم بلا شديدا. والهضبة: كل جبل من صخرة واحدة. وكل صخرة راسية ضخمة تسمى: هضبة. والجميع الهضاب. والهضب: الشديد الصلب.'),
(970, 'ضهب', 'ضهب', 'ضهب', 'كل قف أو حزن أو موضع [من الجبل] 1 تحمى عليه الشمس حتى ينشوي اللحم عليه. فهو: الضيهب، قال: 2 وغر تجيش قدوره بضياهب وضهبت اللحم فهو مضهب، أي: شويته على حجر محمى.'),
(971, 'هضم', 'هضم', 'هضم', 'الهاضم: الشادخ لما فيه [من] رخاوة ولين، تقول: هضمته فانهضم، كالقصبة المهضومة التي يزمر بها. يقال: مزمار مهضم، قال لبيد: 3 يرجع في الصوى بمهضمات ... يجبن الصدر من قصب العوالي شبه مخارج صوت حلقه بمهضمات المزامير. والهاضوم: [كل دواء هضم طعاما كا] 4 لجوارش. وبطن هضيم مهضوم وأهضم. قال: 5 لفاء عجزاء وفي الكشح هضم ونخل طلعها هضيم 1 : مهضوم في جوف الجف منهضم فيه. وهضمت من حقي طائفة، أي: تركته. والمهضومة: ضرب من الطيب يخلط بالمسك والبان. والأهضام: ضرب من البخور، واحدها: هضمة، قال النمر: 2 كأن ريح خزاماها وحنوتها ... بالليل ريح يلنجوج وأهضام وقال العجاج: 3 كأن ريح جوفه المزبور ... في الخشب تحت الهدب اليخضور مثواه عطارين بالعطور ... أهضامها والمسك والقفور والأهضام: الأرض المطمئنة. والأهضام: ملاجىء الغبوب، قال ذو الرمة: 4 حتى إذا الوحش في أهضام موردها ... تغيبت رابها من خيفة ريب وقرى تبالة تدعى أهضاما لكثرة خيرها قال: 5 هبطا تبالة مخصبا أهضامها'),
(972, 'صهد', 'صهد', 'صهد', 'الصيهد: الطويل، والصيهود، الجسيم.'),
(973, 'هصر', 'هصر', 'هصر', 'الهصر: أن تأخذ برأس الشيء ثم تكسره إليك من غير بينونة، قال: 1 [فلما تنازعنا الحديث وأسمحت] ... هصرت بغصن ذي شماريخ ميال وأسد هيصير [هصور] 2 هصار. والمهاصري: ضرب من برود اليمن.'),
(974, 'صهر', 'صهر', 'صهر', 'الصهر: حرمة الختونة. وختن القوم: صهرهم، والمتزوج فيهم: أصهار، ولا يقال لأهل بيت الختن إلا أختان، ولأهل بيت المرأة إلا أصهار. ومن العرب من يجعلهم 3 كلهم أصهارا، وصهراء، والفعل: المصاهرة. قال أبو الدقيش: أصهر بهم الختن، أي: صار فيهم صهرا. والصهر: الإذابة، والصهارة: ما ذاب منه، وكذلك: الإصهار في إذابته، وأكل صهارته، قال العجاج: 1 شك السفافيد الشواء المصطهر والصهير: المشوي. ويقال للحرباء إذا تلألأ ظهره من شدة الحر: صهره الحر، واصطهر الحرباء. وقوله [عز وجل] . يصهر به ما في بطونهم 2 أي: يذاب. والصيهور: ما يوضع عليه متاع البيت، من صفر أو شبه أو نحوه.'),
(975, 'رهص', 'رهص', 'رهص', 'الرهص: أن يصيب حجر حافرا أو منسما فيدوى باطنه. يقال: رهصه الحجر، ودابة رهيص، ومرهوص. والمرهص: موضع الرهصة، ويجمع مراهص، قال: على جمال تهص المراهصا والرهص: شدة العصر. وللفرس عرقان في خيشومه، وهما الناهقان، إذا رهصا مرض لهما الفرس. والرهص: أسفل عرق في الحائط، ويرهص الحائط بما يقيمه إذا مال. والرواهص: بواطن الأخفاف التي ترهص فيها المرهوصة. الواحدة [راهصة] 1 .'),
(976, 'صهل', 'صهل', 'صهل', 'الصهيل: صوت الخيل. صهل يصهل صهيلا. وفرس صهال: كثير الصهيل.'),
(977, 'صهب', 'صهب', 'صهب', 'الصهب والصهبة: لون حمرة في شعر الرأس واللحية إذا كان في الظاهر حمرة وفي الباطن سواد. وبعير أصهب وصهابي، وناقة صهباء وصهابية. والصهابية أيضا نعت للجراد، قال: 2 صهابية زرق بعيد مسيرها ومن الظلمان: أصهب البلد، أي: جلده.'),
(978, 'هبص', 'هبص', 'هبص', 'الهبص: من النشاط والعجلة. يقال: هبص الكلب هبصا، إذا حرص على الصيد، أو الشيء يأكله فتراه قلقا لذلك، وكذلك الإنسان الهبص.'),
(979, 'هصم', 'هصم', 'هصم', 'الهيصم: الأسد، وهو الهصمصم لشدته وصولته.'),
(980, 'صهم', 'صهم', 'صهم', 'الصهميم من الرجال: الذي يركب رأسه، لا يثنيه شيء عما يريد ويهوى. ج 4'),
(981, 'سهد', 'سهد', 'سهد', 'السهد والسهاد- لغتان ... : نقيض الرقاد. وما رأيت من فلان سهدة، أي أمرا أعتمد عليه، من بركة أو خير أو كلام مطمع. وسهدد: اسم جبل لا ينصرف.'),
(982, 'دهس', 'دهس', 'دهس', 'الدهسة: لون كلون الرمال، يعلوه أدنى سواد يكون في ألوان الرمال والمعز. قال العجاج: 1 . مواصلا قفا بلون أدهسا والدهاس: ما كان من الرمل كذلك، لا ينبت شجرا، وتغيب فيه القوائم. قال: 2 : وفي الدهاس مضبر مواثم');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(983, 'سته', 'سته', 'سته', 'السته: مصدر الأسته، وهو الضخم الاست. ويقال للواسعة الدبر: ستهاء وستهم. وتصغير الاست: ستيهة، والجميع: أستاه.'),
(984, 'هرس', 'هرس', 'هرس', 'الهرس: دق الشيء بالشيء عريضا، كما تهرس الهريسة بالمهراس. والفحل يهرس القرن بكلكله. والهرس من الأسود: الشديد المراس، قال: 1 : شديد الساعدين أخا وثاب ... شديدا أسره هرسا هموسا والمهاريس من الإبل: الجسام الثقال ومن شدة وطئها سميت: مهاريس، وكذلك الكثيرات الأكل من الإبل (تسمى مهاريس) . وقال: 2 : وكلكلا ذا حاميات أهرسا والمهراس: حجر مستطيل منقور يتوضأ به. والهراس: شجر كثير الشوك، قال النابغة: 3 : فبت كأن العائدات فرشنني ... هراسا به يعلي فراشي ويقشب'),
(985, 'سهر', 'سهر', 'سهر', 'السهر: امتناع النوم بالليل. (تقول) : أسهرني (هم) 4 فسهرت (له) 1 سهرا، أي: امتنعت من النوم. والساهور: من أسماء القمر، وقال القتيبي: بل هو في ليل تمامه. والساهرة: وجه الأرض العريضة البسيطة، قال 2 يرتدن ساهرة كأن جميمها ... وعميمها أسداف ليل مظلم وقال الله (عز وجل) فإذا هم بالساهرة 3 ، أي: على وجه الأرض. والأسهران: عرقان في الأنف من باطن إذا اغتلم الحمار سالا دما أو ماء.'),
(986, 'هلس', 'هلس', 'هلس', 'الهلاس: شبه السلال من الهزال. وامرأة مهلوسة: مهزولة . سهل: السهل: كل شيء إلى اللين، وذهاب الخشونة، وقد سهل سهولة. والسهلة: تراب كالرمل يجيء به الماء. وأرض سهلة، فإذا قلت: سهلة فهي نقيض حزنة وأسهل القوم: نزلوا عن الجبل إلى السهل. وإسهال البطن: أن يسهله دواء. وسهيل: اسم كوكب يرى بالعراق، ولا يرى بخراسان. ويقال إن سهيلا كان عشارا على طريق اليمن ظلوما فمسخه الله كوكبا.'),
(987, 'لهس', 'لهس', 'لهس', 'الملاهس: المزاحم على الطعام من الحرص.'),
(988, 'نهس', 'نهس', 'نهس', 'النهس: القبض على اللحم ونتره. قال العجاج: 1 : مضبر اللحيين نسرا منهسا والنهس: طائر . سنه: السنة: نقصانها حذف الهاء وتصغيرها: سنيهة. والمسانهة: المعاملة سنة بسنة. وثلاث سنوات، وقال الله عز وجل: لم يتسنه 2 . ومن جعل حذف السنة واوا قرأ: لم يتسن، ومنه: سانيته مساناة، وإثبات الهاء أصوب 3 .'),
(989, 'سهف', 'سهف', 'سهف', 'السهف: تشحط القتيل، يسهف في نزعه واضطرابه، قال: 4 ماذا هنالك من أسوان مكتئب ... وساهف ثمل في صعدة قصم والسهف: حرشف السمك خاصة.'),
(990, 'سفه', 'سفه', 'سفه', 'السفه والسفاه والسفاهة: نقيض الحلم. وسفهت أحلامهم. وسفه الرجل: صار سفيها. وسفه حلمه، ورأيه ونفسه، إذا حملها على أمر خطأ. وقول الله عز وجل: إلا من سفه نفسه 1 مثل [قولهم] : صبر نفسه، ولا يقال: سفهت زيدا ولا صبرته.'),
(991, 'سهب', 'سهب', 'سهب', 'فرس سهب: شديد الجري، بطيء العرق، قال 2 : وقد أغدو بطرف هيكل ... ذي ميعة سهب وبئر سهبة: بعيدة القعر يخرج منها الريح. وإذا حفر القوم فهجموا على الريح، وأخلفهم الماء قيل: أسهبوا، ويقال: بل حفروا فأسهبوا معناه: حتى بلغوا رملا. وقال 3 في بئر كثيرة الماء: حوض طوي نيل من إسهابها ... يعتلج الآذي من حبابها وهي المسهبة، حفرت حتى بلغ بها عيلم الماء، ألا ترى أنه قيل: نيل من أعمق قعرها 4 . والسهباء: بئر لبني سعد، وروضة بالصمان. وسهوب الفلاة: نواحيها التي لا مسلك فيها قال: 5 : سهوب مهامه ولها سهوب والمسهب: الكثير الكلام، قال الجعدي 1 غير عيي ولا مسهب والمسهب: المتغير الوجه. والمسهب: الغالب المكثر [في عطائه] 2 .'),
(992, 'بهس', 'بهس', 'بهس', 'بيهس: من اسماء الأسد، وأخذ [فلان] يتبيهس، وتبيهس في مشيه، إذا تبختر، فهو يتبيهس تبيهسا . سبه: السبه: ذهاب العقل من هرم. قال رؤبة 3 : قالت أبيلى لي ولم أسبه: ... ما السن إلا غفلة المدله'),
(993, 'همس', 'همس', 'همس', 'الهمس: حس الصوت في الفم مما لا إشراب له من صوت الصدر، ولا جهارة في المنطق، ولكنه كلام مهموس في الفم كالسر. وهمس الأقدام: أخفى ما يكون من صوت الوطء. وعن ابن عباس رضي الله عنه: وهن يهوين بنا هميسا 4 والشيطان يهمس بوسواسه في الصدور. وروي عن النبي صلى الله عليه وسلم أنه كان يتعوذ بالله من همز الشيطان وهمسه ولمزه ، فالهمز كلام من وراء القفا كالاستهزاء، واللمز مواجهة. وقوله عز وجل: فلا تسمع إلا همسا 1 يعني: خفق الأقدام على الأرض والهماس: الشديد الغمز بضرسه، قال 2 : عادته خبط وعض هماس ... يعدو باشبال أبوها الهرماس'),
(994, 'سهم', 'سهم', 'سهم', 'استهم الرجلان، أي: اقترعا، لقوله [عز وجل] : فساهم فكان من المدحضين 3 ، وآستهم القوم فسهمهم فلان، أي: قرعهم. والسهم: النصيب، والسهم: واحد من النبل. والسهم: القدح الذي يقارع به، والسهم: مقدار ست أذرع في معاملة الناس ومساحاتهم. وبرد مسهم: مخطط، قال 4 : كأنها بعد أحوال مضين لها ... بالأشيمين، يمان فيه تسهيم والسهوم: عبوس الوجه من الهم، ويقال للفرس إذا حمل على كريهة الجري: ساهم الوجه. وكذلك الرجل في الحرب ساهم الوجه. قال عنترة 5 : والخيل ساهمة الوجوه كأنما ... تسقى فوارسها نقيع الحنظل والسهام من وهج الصيف وغبرته، [يقال] : سهم فلان إذا أصابه السهام. والسهمة: النصيب، تقول: لي في هذا الأمر سهمة، أي: نصيب. والسهمة: القرابة، قال عبيد بن الأبرص 1 : [قد يوصل النازح النائي وقد] ... يقطع ذو السهمة القريب'),
(995, 'سمه', 'سمه', 'سمه', 'سمه البعير، أو الفرس في شوطه يسمه سموها فهو سامه لا يعرف الإعياء، قال 2 : يا ليتنا والدهر جري السمه والسمهى: الباطل .'),
(996, 'زهد', 'زهد', 'زهد', 'الزهد في الدين خاصة، والزهادة في الأشياء كلها. ورجل زهيد. وإمرأة زهيدة وهما القليل طعمهما. وأزهد الرجل إزهادا فهو مزهد، لا يرغب في ماله لقلته.'),
(997, 'هزر', 'هزر', 'هزر', 'الهزر والبزر: شدة الضرب بالخسب، [يقال] : هزره هزرا كما يقال: هطره وهبجه. الهزر: قبيلة من اليمن بيتوا فقتلوا ليلا [فلم يبق منهم أحد] 1 . ورجل ذو هزرات وكسرات، وإنه لمهزر، وهذا كله: الذي يغبن في كل شيء، قال 2 : إلا تدع هزرات لست تاركها ... تخلع ثيابك، لا ضأن ولا إبل'),
(998, 'زهر', 'زهر', 'زهر', 'الزهرة: نور كل نبات. وزهرة الدنيا: حسنها وبهجتها. وشجرة مزهرة، ونبات مزهر. والزهور: تلألؤ السراج الزاهر. وزهر السراب زهورا، أي: تلألؤا. والزهرة: اسم كوكب. والأزدهار: الحفظ، قال جرير: 3 : فإنك قين وابن قينين فازدهر ... بكيرك إن الكير للقين نافع والأزهر: القمر، زهر يزهر زهرا، وإذا نعته بالفعل اللازم قلت: زهر يزهر زهرا والأزهر: لكل لون أبيض كالدرة الزهراء، والحوار الأزهر.'),
(999, 'رهز', 'رهز', 'رهز', 'الرهز من قولك: رهزها فارتهزت وهو تحركهما معا عند الإيلاج. من الرجل والمرأة.'),
(1000, 'هزل', 'هزل', 'هزل', 'الهزل: نقيض الجد. فلان يهزل في كلامه، إذا لم يكن جادا. ويقال: أجاد أنت أم هازل. والهزال: نقيض السمن. [تقول] : هزلت الدابة، وأهزل الرجل، إذا هزلت دابته. وتقول: هزلتها فعجفت. والهزيلة: اسم مشتق من الهزال. كالشتيمة من الشتم، [ثم] 1 فشت الهزيلة في الإبل، قال 2 : حتى إذا نور الجرجار وارتفعت ... عنها هزيلتها والفحل قد ضربا'),
(1001, 'زهل', 'زهل', 'زهل', 'تقول: أصبح الفرس زهلولا، أي: أملس.'),
(1002, 'لهز', 'لهز', 'لهز', 'اللهز: الضرب بجمع اليد في الصدر والحنك. ولهزه القتير فهو ملهوز. ولهزه بالرمح، أي: طعنه في صدره. والفصيل يلهز أمه، أي: يضرب ضرعها بفمه ليرضع'),
(1003, 'زله', 'زله', 'زله', 'الزلة: ما يصل إلى النفس من غم الحاجة، أو هم من غيرها، قال 3 وقد زلهت نفسي من الجهد والذي ... أطالبه شقن ولكنه نذل'),
(1004, 'هزن', 'هزن', 'هزن', 'هوازن: قبيلة ضخمة من مضر. هزان أيضا قبيلة.'),
(1005, 'نهز', 'نهز', 'نهز', 'النهز: التناول [باليد] والنهوض للتناول جميعا. والنهزة: اسم الشيء الذي هو لك معرض كالغنيمة، تقول: انتهزها فقد أمكنتك قبل الفوت. والناقة تنهز بصدرها، أي: تنهض لتمضي، قال 1 : نهوز بأولاها زجول برجلها والدابة تنهز برأسها إذا ذبت عن نفسها. ونهز الصبي للفطام، أي: دنا فهو ناهز، والجارية ناهزة، قال 2 ترضع شبلين في مغارهما ... قد ناهزا للفطام أو فطما'),
(1006, 'نزه', 'نزه', 'نزه', 'مكان نزه، وقد نزه نزاهة، وتنزهت، أي: خرجت إلى نزهة. وتنزهت عن كذا، أي: رفعت نفسي عنه تكرما، ورغبة عنه. وتنزيه الله: [تسبيحه، وهو تبرئته عما يصف المشركون] 3'),
(1007, 'هزف', 'هزف', 'هزف', 'ظليم هزف. لغة في هجف.'),
(1008, 'زهف', 'زهف', 'زهف', 'استعمل منه الازدهاف، وهو الصدود، قال 1 فيه ازدهاف أيما ازدهاف'),
(1009, 'هزب', 'هزب', 'هزب', 'الهوزب: المسن الجريء [من الإبل] 2 ، قال الأعشى 3 : والهوزب العود أمتطيه بها ... والعنتريس الوجناء والجملا'),
(1010, 'بهز', 'بهز', 'بهز', 'البهز: الدفع العنيف، بهزته عني بهزا، قال 4 : دعني فقد يقرع للأضز ... صكي حجاجي رأسه وبهزي'),
(1011, 'هزم', 'هزم', 'هزم', 'الهزم: غمزك الشيء تهزمه بيدك فينهزم في جوفه، كما تغمز الفتاة [فتنهزم، وكذلك القربة تنهزم في جوفها] والاسم: الهزمة، وجمعه: هزوم، قال 5 : حتى إذا ما بلت العكوما ... من قصب الأجواف والهزوما وقال 1 : ولكنه خانت كعوب قناته ... وما هزمت أنبوبه كف أخرقا وغيث هزم متهزم لا يستمسك، كأنه منهزم عن مائه، وكذلك: هزم السحاب أو هزيمه ويقال: هزم: القوم، والاسم: الهزيمة والهزمى. وأصابتهم هازمة من هوازم الدهر، أي: داهية كاسرة. والهزمة: ما تطامن من الأرض. والهزائم: العجاف من الدواب، الواحدة: هزيمة، والمهزام: عود يجعل في رأسه نار، لعبة لصبيان العرب.'),
(1012, 'همز', 'همز', 'همز', 'الهمز: العصر، تقول: همزت رأسه، [وهمزت] الجوزة بكفي. وإنما سميت الهمزة في الحروف، لأنها تهمز، فتهت فتهمز عن مخرجها. تقول: يهت [فلان] هتأ، إذا تكلم بالهمز. والهماز والهمزة: من يهمز أخاه في قفاه من خلفه بعيب. واللمزة: في الاستقبال. قال 2 . وإن تغيبت كنت الهامز اللمزه'),
(1013, 'زهم', 'زهم', 'زهم', 'لحم زهم، أي: منتن، والزهومة: ريحه. والزهم: لحم الوحش من غير أن يكون فيه زهومة، ولكنه اسم له خاص.'),
(1014, 'ذهط', 'ذهط', 'ذهط', 'الذهيوط: مكان.'),
(1015, 'هطر', 'هطر', 'هطر', 'هطرة يهطره هطرا، كما يهبج الكلب بالخشبة.'),
(1016, 'هرط', 'هرط', 'هرط', 'نعجة هرطة، أي: مهزولة، لا ينتفع بلحمها غثوثة. وفلان يهرط في كلامه، إذا سفسف وخلط. والهرط لغة في الهرت. وهو المزق، ويقال: بل الهرط في الشدقين، والهرط في الأشياء: المزق العنيف.'),
(1017, 'طهر', 'طهر', 'طهر', 'الطهر: نقيض الحيض. [يقال] : طهرت المرأة وطهرت- لغتان، فهي طاهر. إذا انقطع، وهي ذات طهر. وتطهرت، أي: اغتسلت [وأطهرت] 1 . والاطهار: الاغتسال في قوله [تعالى] : وإن كنتم جنبا فاطهروا 2 ، وقوله [عز وجل] : رجال يحبون أن يتطهروا 1 يعني: الاستنجاء بالماء. والتطهر أيضا: التنزه والكف عن الإثم. وفلان طاهر الثياب، أي: ليس بصاحب دنس في الأخلاق، قال 2 : ثياب بني عوف طهارى نقية ... وأوجههم بيض المسافر غران أخرجه على سودان وحمران. والطهور: اسم للماء [الذي يتطهر به] ، كالوضوء [للماء الذي يتوضأ به] 3 . وكل ماء نظيف اسمه طهور. والتوبة [التي تكون] بإقامة الحدود: طهور للمذنب تطهره تطهيرا. والمطهرة [إناء من] الأدم [يتخذ] 4 للماء. والطهارة: فضل ما تطهرت به. والعرب تجمع طهر النساء: أطهارا، وهي أيامها التي لا تحيض [فيها] 5 ، قال 6 قوم إذا حاربوا شدوا ماذرهم ... دون النساء ولو بانت بأطهار وقوله [تعالى] : لا يمسه إلا المطهرون 7 ، أي: الملائكة، يعني الكتاب.'),
(1018, 'رهط', 'رهط', 'رهط', 'الرهط: عدد يجمع من ثلاثة إلى عشرة، ويقال: من سبعة إلى عشرة، وما دون السبعة إلى الثلاثة: نفر. وتخفيف الرهط أحسن من تثقيله. والترهيط: عظم اللقم، وشدة الأكل، قال 1 يا أيها الآكل ذو الترهيط وهو الدهورة أيضا. والراهطاء: جحر اليربوع، بين القاصعاء والنافقاء، يخبأ فيه أولاده. والرهاط، وواحدها رهط: أدم تقطع كقدر ما بين الحجزة إلى الركبه. ثم تشق كأمثال الشرك تلبسه 2 الجارية، قال 3 : [بضرب في الجماجم ذي فروغ] ... وطعن مثل تعطيط الرهاط وقال 4 : متى ما أشأ غير زهو الملوك ... أجعلك رهطا على حيض والعدد: أرهطة، ويجوز أن تقول: هؤلاء رهطك وأرهطك، كل ذلك جميع، وهم رجال عشيرتك والأراهط الجمع أيضا. قال 5 : يا بؤس للحرب التي ... وضعت أراهط فاستراحوا أي: أراحتهم من الدنيا بالقتل.'),
(1019, 'هطل', 'هطل', 'هطل', 'الهطلان: تتابع القطر المتفرق العظام. والسحاب يهطل. والعين تهطل [بالدموع] ودمع هاطل. والهيطل والهياطلة جنس من الترك والسند، قال 1 : حملتهم فيها مع الهياطله ... أثقل بهم من تسعة في قافله'),
(1020, 'طهل', 'طهل', 'طهل', 'الطهلية: الطين في الحوض، وهو ما انحت فيه من الحوض بعد ما ليط. والطهلية: الأحمق الذي لا خير فيه.'),
(1021, 'طهف', 'طهف', 'طهف', 'الطهف: طعام يتخذ من الذرة، يختبز.'),
(1022, 'هبط', 'هبط', 'هبط', '[هبط الإنسان يهبط إذا انحدر في هبوط من صعود] والهبطة: ما تطامن من الأرض، [وقد هبطنا أرض كذا وكذا، أي نزلناها] 3 ، ويقال للقوم إذا كانوا في سفال: قد هبطوا يهبطون، وهو نقيض ارتفعوا. قال 4 : كل بني حرة مصيرهم ... قل وإن أكثرت من العدد إن يغبطوا يهبطوا وإن أمروا ... يوما فهم للفناء والفند وفرق ما بين الهبوط والهبوط: أن الهبوط اسم للحدور، وهو الموضع الذي يهبطك من أعلى إلى أسفل. والهبوط: المصدر. والمهبوط: الذي هبطه المرض إلى أن اضطرب لحمه.'),
(1023, 'بهط', 'بهط', 'بهط', 'البهط: سندية، وهو الأرز يطبخ باللبن والسمن بلا ماء. وعربته العرب فقالوا: بهطة طيبة، قال 1 : من أكلها الأرز بالبهط.'),
(1024, 'همط', 'همط', 'همط', 'الهمط: الخلط من الأباطيل والظلم، تقول: يهمط ويخلط همطا وخلطا.'),
(1025, 'طهم', 'طهم', 'طهم', 'المطهم: الفرس التام الخلق، الجهير الجمال.'),
(1026, 'هدر', 'هدر', 'هدر', 'الهدر: ما يبطل. هدر دمه يهدر هدرا، وأهدرته أنا إهدارا. وهدر البعير يهدر هديرا وهدرا. والحمامة تهدر، وجرة النبيذ تهدر. والأرض الهادرة. والعشب الهادر: الكثير. وبنو فلان هدرة، أي: ساقطون ليسوا بشيء.'),
(1027, 'هرد', 'هرد', 'هرد', 'الهردية قصبات ملوية مطوية تضم بطاقات الكرم [يرسل عليها قضبان الكرم] 1 . وهردت اللحم فهو مهرد، أي شويته [فهو مشوي] . وقد هرد اللحم. [نفج] 2 .'),
(1028, 'دهر', 'دهر', 'دهر', 'الدهر: الأبد الممدود. ورجل دهري: قديم، والدهري [الذي يقول ببقاء الدهر و] لا يؤمن بالآخرة. ودهوري الصوت. أي: صلب الصوت. والدهارير: أول الدهر من الزمان الماضي [يقال: كان ذلك في دهر الدهارير] 3 ، ولا يفرد منه دهرير. والدهر: النازلة. دهرهم أمر، أي: نزل بهم مكروه. وما دهري كذا وكذا، أي: ما همتي. والدهورة: جمع الشيء ثم قذفه 4 في مهواة. وقوله: لا تسبوا الدهر فإن الله هو الدهر 5 . يعني: ما أصابك من الدهر فالله فاعله، ليس الدهر، فإذا سببت 1 الدهر أردت به الله عز وجل.'),
(1029, 'رهد', 'رهد', 'رهد', 'الرهيد: الناعم، والمصدر: الرهادة. وفتاة رهيدة، أي: رخصة.'),
(1030, 'دره', 'دره', 'دره', 'أميت فعله، إلا [قولهم: رجل] مدره حرب، و [هو] مدره القوم، أي: الدافع عنهم.'),
(1031, 'رده', 'رده', 'رده', 'الرده: شبه أكمة خشنة، كثيرة الحجارة. والواحدة: ردهة، والجميع: رده. وربما جاءت الردهة في وصف بئر تحفر في القف، أو تكون خلقة فيه. ويقال للبيت العظيم الذي لا أعظم منه: الردهة، وجمعه: الرداه، وقد ردهت المرأة بيتها تردهه ردها.'),
(1032, 'هدل', 'هدل', 'هدل', 'هدلت الحمامة تهدل هديلا. [ويقال] 2 : هديلها فرخها. والهدل 3 : استرخاء في المشفر الأسفل. مشفر هادل، وأهدل، وشفة هدلاء: منقلبة على الذقن. والتهدل: استرخاء جلدة الخصية ونحوها. قال 4 كأن خصييه من التهدل ... ظرف عجوز فيه ثنتا حنظل والهدال: ضرب من الشجر، ويقال: كل غصن ينبت في أراكة أو طلحة مستقيما فهو هدالة. كأنه مخالف لغيره من الأغصان، وربما يداوى به من السحر والجنون.'),
(1033, 'دهل', 'دهل', 'دهل', 'لا دهل بالنبطية: لا تخف، قال بشار يهجو الطرماح 1 : فقلت له: لا دهل ما لكمل 2 بعد ما ... ملا نيفق التبان منه بعاذر'),
(1034, 'لهد', 'لهد', 'لهد', 'اللهد: الصدم الشديد في الصدر. والبعير اللهيد: الذي أصاب جنبه ضغطة من حمل ثقيل، فأورثه داء أفسد عليه رئته، فهو ملهود. قال الكميت 3 : نطعم الجيأل اللهيد من الكوم ... ولم ندع من يشيط الجزورا ورجل ملهد، أي: مدفع من الذل. ولهدت الرجل ألهده لهدا، إذا دفعته فهو ملهود.'),
(1035, 'دله', 'دله', 'دله', 'الدله: ذهاب الفؤاد من هم، كما تدله المرأة على ولدها إذا فقدته، وكما يدله العقل من عشق أو غيره، يقال: دله الرجل تدليها.'),
(1036, 'هدن', 'هدن', 'هدن', 'المهدنة من الهدنة، وهو السكون. تقول، هدنت أهدن هدونا إذا سكنت فلم تتحرك. ورجل مهدون وهو البليد الذي يرضيه الكلام، تقول: هدنوه بالقول دون الفعل، قال 1 : ولم يعود نومة المهدون [ورجل هدان وهو الأحمق الجافي] 2 قال 3 : قد يجمع المال الهدان الجافي ... من غير ما عقل ولا اصطراف والهداء لغة في الهدان. والهودنات: النوق: وقوله: يكون بعدها هدنة على دخن، وجماعة على أقذاء 4 أي: صلح واستقرار على أمور كريهة.'),
(1037, 'هند', 'هند', 'هند', 'هنيدة: مائة من الإبل، معرفة [لا تنصرف، ولا يدخلها (أل) ] ولا تجمع [ولا واحد لها من جنسها] 5 . هندت المرأة فلانا، أي: أورثته عشقا بالمغازلة والملاطفة، قال 6 : غرك من هنادة التهنيد ... موعودها والباطل الموعود والتهنيد: شحذ السيف، قال 1 : كل حسام محكم التهنيد ... يقضب عند الهز والتجريد سالفة الهامة واللديد'),
(1038, 'دهن', 'دهن', 'دهن', 'الدهن: الاسم. والدهن: الفعل المجاوز، والادهان: الفعل اللازم. وناقة دهين: قليلة اللبن حدا يمرى ضرعها فلا يدر قطرة. قال 2 : لسانك مبرد لا عيب فيه ... ودرك در حادبة دهين والدهن من المطر: قدر ما يبل وجه الأرض. والإدهان: اللين والمصانعة. قال الله تعالى: ودوا لو تدهن فيدهنون 3 . أي: تلين لهم فيلينون. والمداهن: المصانع الموارب، قال زهير 4 : وفي الحلم إدهان وفي العفو دربة ... وفي الصدق منجاة من الشر فاصدق وأصل المدهن: مدهن، فلما كثر على الألسن ضموه، مثل المنخل. وكل موضع حفره سيل، أو ماء واكف في حجر فهو: مدهن. والدهناء: موضع كله رمل، والنسبة إليها: دهناوي. قال 5 : بوعساء دهناوية الترب مشرف'),
(1039, 'نهد', 'نهد', 'نهد', 'النهد من الخيل: الجسيم المشرف، تقول: [فرس] نهد القذال، نهد القصيري. والنهد: إخراج الرفقة نفقاتهم على قدرهم. تقول: تناهدوا. وناهد بعضهم بعضا. والمناهدة: أن ينهد بعضهم إلى بعض في الحروب. وهو في معنى نهضوا إلا أن النهوض قيام عن قعود ومضي، والنهود: مضي على كل حال. والنهيدة: الزبدة الضخمة، وتسمى أيضا: نهدة. والنهداء من الرمال كالرابية المثلبدة: مكرمة تنبت الشجر، ولا ينعت الذكر على أنهد. ونهد الثدي نهودا، أي: انتبر 1 وكعب فهو ناهد.'),
(1040, 'نده', 'نده', 'نده', 'النده: الزجر عن الحوض، وعن كل شيء إذا طردت الإبل عنه بالصياح، قال 2 : لو دق وردي حوضه لم ينده وقال 3 : لمن الديار بقنة الرده ... [قفرا] 4 من التأييه والنده'),
(1041, 'هدف', 'هدف', 'هدف', 'الهدف: الغرض. والهدف من الرجال: الجسيم الطويل العنق، العريض الألواح. والهدف: كل شيء عريض مرتفع. وأهدف الشيء، إذا انتصب. وفي الحديث أن النبي (صلى الله عليه وسلم) كان إذا مر بهدف مائل أو صدف مائل أسرع المشي .'),
(1042, 'فهد', 'فهد', 'فهد', 'الفهد: معروف، وجمعه: فهود وثلاثة أفهد. وأنثاه: فهدة. وفهد الرجل فهدا، إذا نام وتغافل عما يجب عليه تعهده.'),
(1043, 'هدب', 'هدب', 'هدب', 'الهدب: أغصان الأرطى، ونحوه مما لا ورق له، وجمعه أهداب، والواحدة هدبة والهدب: مصدر الأهدب والهدباء، يقال: شجرة هدباء، وقد هدبت هدبا. وهدبها: تدلي أغصانها من حواليها. ورجل أهدب: طويل أشفار العينين كثيرهما. والهداب: اسم يجمع هدب الثوب، وهدب الأرطى. الواحدة: هدابة. قال 2 : وشجر الهداب عنه فجفا ... بسلهبين فوق أنف أذلفا والهدب: ضرب من الحلب، هدب الحالب الناقة يهدبها هدبا. وهيدب السحاب: إذا رأيت السحابة تسلسل في وجهها للودق، فانصب كأنه خيوط متصلة، وكذلك: هيدب الدمع ويقال للبد ونحوه إذا طال زئبره: أهدب، قال 1 : عن ذي درانيك ولبد أهدبا الدرنوك: المنديل المخمل. والهدبة: الواحدة من هدب الثوب. والهيدب من الرجال: العيي الثقيل.'),
(1044, 'هبد', 'هبد', 'هبد', 'الهبد: كسر الهبيد. أي: الحنظل. وتهبد الرجل والظليم إذا أخذه من شجره.'),
(1045, 'بده', 'بده', 'بده', 'البده: استقبالك إنسانا بأمر مفاجأة [والاسم البديهة] 2 و [البديهة أول الرأي] 3 وبادهني مبادهة، أي: باغتني مباغتة. والبداهة والبديهة: أول جري الفرس. تقول: هو ذو بديهة وبداهة.'),
(1046, 'هدم', 'هدم', 'هدم', 'الهدم: قلع المدر، أي: البيوت. والهدم: الخلق البالي. والجمع: أهدام والهدمة: الناقة الضبعة الشديدة الضبعة إلى الفحل. تقول: هدمت تهدم هدما. وقد هدمت هدمة شديدة. وناب متهدمة، وعجوز متهدمة، أي: فانية هرمة.'),
(1047, 'همد', 'همد', 'همد', 'الهمود: الموت. كما همدت ثمود. ورماد هامد إذا تغير وتلبد. وثمرة هامدة، إذا اسودت وعفنت. وأرض هامدة: مقشعرة لا نبات فيها إلا يبيس متحطم. والهامد من الشجر: اليابس، ويقال للهامد: هميد. [والإهماد: السرعة. والإهماد: الإقامة بالمكان] 1 .'),
(1048, 'دهم', 'دهم', 'دهم', 'الأدهم: الأسود، وبه دهمة شديدة. وادهام الزرع، إذا علاه السواد ريا. والدهم: الجماعة الكثيرة، ودهمونا، أي: جاءونا بمرة جماعة. ودهمهم أمر، أي: غشيهم فاشيا، قال 2 : جاءوا بدهم يدهم الدهوما ... فجر كأن فوقه النجوما والدهماء: سحنة الرجل. والدهماء: القدر. والدهماء: بقلة، والدهماء: الجماعة من الناس. والدهيم 3 : الداهية.'),
(1049, 'مهد', 'مهد', 'مهد', 'المهد: الموضع يهيأ لينام فيه الصبي. والمهاد اسم أجمع من المهد، كالأرض جعلها الله مهادا للعباد، وجمع المهاد: مهد، وثلاثة أمهدة. ومهدت لنفسي خيرا، أي: هيأته ووطأته، قال 1 : وامتهد الغارب فعل الدمل'),
(1050, 'دمه', 'دمه', 'دمه', 'الدمه: شدة حر الرمل، قال 2 : ظلت على شزن في دامه دمه ... كأنه من أوار الشمس مرعون أي: مغشي عليها. وتقول: ادمومه الرمل.'),
(1051, 'مده', 'مده', 'مده', 'المده يضارع المدح، إلا أن المده في نعت الجمال والهيئة، والمدح في كل شيء، قال رؤبة 3 : لله در الغانيات المده ... سبحن واسترجعن من تألهي'),
(1052, 'هتر', 'هتر', 'هتر', 'الهتر: مزق العرض. رجل مستهتر لا يبالي ما قيل فيه. وما شتم به. وأهتر الرجل: فقد عقله من الكبر فهو المهتر. والتهتار من الحمق والجهل، كما قال 1 : إن الفزاري لا ينفك مغتلما ... من النواكة تهتارأ بتهتار ولغة للعرب في هذا خاصة: دهداد بدهدار، وذلك أن منهم من يقلب بعض التاءات في الصدور دالا نحو: الدرياق، لغة في الترياق. والدخريص والتخريص. والهتر [السقط] 2 من الكلام مثل الهذيان.'),
(1053, 'هرت', 'هرت', 'هرت', 'الهرت: هرتك الشدق نحو الأذن، والهرت: مصدر الأهرت. تقول: أسد هريت الشدق، أي: مهروت ومنهرت. والهرت: شقك شيئا توسعه بذلك.'),
(1054, 'تره', 'تره', 'تره', 'الترهات: البواطل من الأمور، قال 3 : وحقة ليست بقول التره والواحدة: ترهة.'),
(1055, 'هتل', 'هتل', 'هتل', 'الهتل والتهتال: تتابع المطر، واستعمل الهتل استبدالا، بدلوا النون لاما، فقالوا في (التهتان) : تهتال، في لغة من يقول في بل: بن، قال العجاج 4 : وبعد تهتال السحاب الهتل'),
(1056, 'تله', 'تله', 'تله', 'فلاة متلهة، أي: مثلفة، والتله لغة في التلف. قال 1 : به تمطت غول كل متله'),
(1057, 'هتن', 'هتن', 'هتن', '[هتن المطر هتونا، وكذلك الدمع، وتهاتن أيضا] 2 . وهتن لغة في هتل.'),
(1058, 'نهت', 'نهت', 'نهت', 'النهيت: صوت الأسد [وهو] دون الزئير. وقد نهت ينهت'),
(1059, 'هتف', 'هتف', 'هتف', 'الهتف: الصوت الشديد. هتف يهتف هتفا، وهتفت الحمامة: [ناحت] ، قال 3 : أإن هتفت ورقاء ظلت سفاهة ... تبكي على جمل لورقاء تهتف'),
(1060, 'هفت', 'هفت', 'هفت', 'الهفت: تساقط الشيء قطعة بعد قطعة، كما يهفت الثلج ونحوه. قال: 4 كأن هفت القطقط المنثور بعد رذاذ الديمة المحدور وتهافت القوم إذا تساقطوا موتا، وتهافت الثوب إذا تساقط بلى، وتهافت الفراش في النار [إذا تساقط] . وقال في وصف الفحل 1 : بهفت عنه زبدا وبلغما'),
(1061, 'تفه', 'تفه', 'تفه', 'تفه الشيء يتفه تفها فهو تافه، أي: قليل خسيس. وتفه الرجل يتفه تفوها فهو تافه، ورجل تافه العقل: أحمق.'),
(1062, 'بهت', 'بهت', 'بهت', 'بهته فلان، أي: استقبله بأمر قذفه به وهو بريء منه، لا يعلمه، والاسم: البهتان. وبهت الرجل يبهت بهتا إذا حار. يقال: رأى شيئا فبهت: ينظر نظر المتعجب، قال 1 : أأن رأيت هامتي، كالطست ... ظللت ترميني بقول بهت'),
(1063, 'هتم', 'هتم', 'هتم', 'الهتم: كسر الثنية أو الثنايا من الأصل، والنعت: أهتم وهتماء. [والهتامة: ما تكسر من الشيء] 2 .'),
(1064, 'تهم', 'تهم', 'تهم', '[تهم اللحم إذا تغير] 3 . والتهم: النائم. وتهامة: اسم مكة، والنازل فيها: متهم.'),
(1065, 'تمه', 'تمه', 'تمه', 'تمه اللبن يتمه تمها فهو تمه، إذا تغير. وشاة متماه: يتمه لبنها ريث 4 يحلب.. والتمه في اللبن كالنمس في الدسم وغيره، والطيب ونحوه. نمس اللحم وغيره: تغير.'),
(1066, 'مته', 'مته', 'مته', 'المته والتمته: [الأخذ] في البطالة والغواية. قال رؤبة: 1 بالحق والباطل والتمته ... أيام تعطيني المنى ما أشتهي'),
(1067, 'ظهر', 'ظهر', 'ظهر', 'الظهر: خلاف البطن من كل شيء. والظهر من الأرض: ما غلظ وارتفع، والبطن ما رق منها واطمأن. والظهر: الركاب تحمل الأثقال في السفر. ويقال لطريق البر، حيث يكون فيه مسلك في البر، ومسلك في البحر: طريق الظهر. والظهر: ساعة الزوال، ومنه يقال: صلاة الظهر. والظهيرة: حد انتصاف النهار. والظهير من الإبل: القوي الظهر، الصحيحه، وقد ظهر ظهارة. والظهير: العون، والمظاهر: المعاون، وهما يتظاهران، أي: يتعاونان. والظهور: بدو الشيء الخفي. والظهور: الظفر بالشيء، والاطلاع عليه، ظهرنا على العدو، والله أظهرنا عليه، أي: أطلعنا. والظهر فيما غاب عنك، تقول: تكلمت بذلك عن ظهر غيب. وظهر القلب: حفظ من غير كتاب، تقول: قرأته ظاهرا واستظهرته. والظاهرة: كل أرض غليظة مشرفة كأنها على جبل. والظاهرة: العين الجاحظة، وهي خلاف الغائرة. والظاهرة والظهارة: خلاف الباطن والبطانة من الأقبية ونحوها. وظهرته تظهيرا: جعلت له ظاهرة. والظهارة: مظاهرة الرجل امرأته إذا قال: هي علي كظهر أمي، أو كظهر ذات رحم محرم. والظهار من الريش: الذي يظهر من ريش الطائر وهو في الجناح، ويقال: الظهار جماعة، الواحد: ظهر، ويجمع أيضا على الظهران، وهو أفضل ما يراش به السهم، فإذا ريش بالبطنان كان عيبا. والظهري: الشيء تنساه وتغفل عنه. ورجل ظهري: من أهل الظهر. ولو نسبت رجلا إلى ظهر الكوفة لقلت: ظهري وكذلك لو نسبت جلدا إلى ظهر قلت: جلد ظهري. والظهران من قولك: أنا بين ظهرانيهم وظهريهم. وكذلك الشيء في وسط الشيء: هو بين ظهريه وظهرانيه، قال 1 : ألبس دعصا بين ظهري أو عسا ويقال للمدبر للأمر: قلبت الأمر ظهرا لبطن.'),
(1068, 'بهظ', 'بهظ', 'بهظ', 'بهظني هذا الأمر، أي: ثقل علي، وبلغ مني مشقته.'),
(1069, 'هذر', 'هذر', 'هذر', 'الهذر: الكلام الذي لا يعبأ به. هذر في منطقه يهذر هذرا. ورجل هذار ومهذار.'),
(1070, 'هذل', 'هذل', 'هذل', 'الهذلول من الأرض: ما ارتفع من تلال صغار. وجمعه: هذاليل قال 1 : يعلو الهذاليل ويعلو القرددا والهوذلة: القذف بالبول، هوذل ببوله: قذفه. والهوذلة: اضطراب في العدو. وهوذل السقاء يهوذل، إذا تمخض] 2 .'),
(1071, 'ذهل', 'ذهل', 'ذهل', 'الذهلول: الفرس الدقيق الجواد. والذهل: تركك الشيء تناساه على عمد، أو يشغلك عنه شاغل. ذهلت عنه، وذهلت، لغتان، [تركته] ، وأذهلني كذا عنه كذا وكذا. والذهلان: حيان من ربيعة، بنو ذهل بن شيبان، وبنو ذهل بن ثعلبة.'),
(1072, 'ذهن', 'ذهن', 'ذهن', 'الذهن: حفظ القلب، نقول: اجعل ذهنك إلى كذا وكذا.'),
(1073, 'هذب', 'هذب', 'هذب', 'الإهذاب: السرعة في العدو والطيران، والمهذب: المخلص من العيوب.'),
(1074, 'هبذ', 'هبذ', 'هبذ', 'المهابذة: الإسراع 1 ، قال 2 : مهابذة لم تترك حين لم يكن ... لها مشرب إلا بناء منصب'),
(1075, 'ذهب', 'ذهب', 'ذهب', 'الذهب: التبر. وأهل الحجاز يقولون: هي الذهب، وبلغتهم نزلت: والذين يكنزون الذهب والفضة، ولا ينفقونها في سبيل الله 3 ، ولولا ذلك لغلب المذكر المؤنث. والقطعة منها: ذهبة، وغيرهم يقول: هو الذهب. والمذهب: الشيء المطلي بماء الذهب، قال : أو مذهب جدد على ألواحه ... الناطق المبروز والمختوم والمذهب: اسم شيطان من ولد إبليس عليه لعنة الله، يبدو للقراء فيفتنهم في الوضوء أو غيره. والذهاب والذهوب، لغتان، مصدر (ذهبت) . والمذهب: يكون مصدرا كالذهاب، ويكون اسما للموضع، ويكون وقتا من الزمان. والمذهب: المتوضأ، بلغة أهل الحجاز. والذهبة: المطرة الجودة، والجميع: الذهاب، قال ذو الرمة 1 : حواء قرحاء أشراطية وكفت ... فيها الذهاب وحفتها البراعيم والذهبة: الواحدة من الذهاب. والذهب: مكيال لأهل اليمن: ويجمع على [ذهاب] وأذهاب، ثم على الأذاهب جمع الجمع.'),
(1076, 'هذم', 'هذم', 'هذم', 'الهذم: الأكل، والهذم: القطع، كل ذلك في سرعة [وقال رؤبة يصف الليل والنهار 2 : كلاهما في فلك يستلحمه ... واللهب لهب الخافقين يهذمه كلاهما: يعني الليل والنهار، في فلك يستلحمه: أي: يأخذ قصده ويركبه. واللهب: المهواة بين الشيئين، يعني به: ما بين الخافقين وهما المغربان، وأراد بقوله: يهذمه: نقصان القمر] 3 . والهيذام: الشجاع من الرجال، وهو الأكول أيضا. سيف مهذم مخذم، وسكين هذام، وموسى هذام. وشفرة هذامة، قال 1 : ويل لبعران بني نعامه ... منك ومن شفرتك الهذامة'),
(1077, 'همذ', 'همذ', 'همذ', 'الهماذي: السرعة في الجري، يقال: إنه لذو هماذي في جريه.'),
(1078, 'هلث', 'هلث', 'هلث', 'الهلثاء، ممدودة: جماعة من الناس علت أصواتهم، يقال: جاء فلان في هلثاء من أصحابه.'),
(1079, 'ثهل', 'ثهل', 'ثهل', 'ثهلان: اسم جبل بالبادية [معروف، ومنه المثل السائر يضرب للرجل الرزين الوقور فيقال (ثهلان ذو الهضبات ما يتحلحل] ) 3 .'),
(1080, 'لهث', 'لهث', 'لهث', 'اللهث: لهث الكلب، عند الإعياء، وعند شدة الحر، وهو إدلاع اللسان من العطش. [واللهاث: حر العطش] 4 .'),
(1081, 'بهث', 'بهث', 'بهث', 'البهثة: ولد البغي 1 وبهثة: اسم أبي حي من سليم.'),
(1082, 'هثم', 'هثم', 'هثم', 'الهيثم: فرخ العقاب.'),
(1083, 'هرل', 'هرل', 'هرل', 'الهرولة: بين المشي والعدو. هرول الرجل هرولة.'),
(1084, 'رهل', 'رهل', 'رهل', 'الرهل: شبه ورم ليس من داء، ولكن رخاوة من سمن، وهو إلى الضعف. تقول: فرس رهل الصدر.'),
(1085, 'هرن', 'هرن', 'هرن', '1 الهرنوي: نبت.'),
(1086, 'هنر', 'هنر', 'هنر', 'الهنرة: وقبة الأذن.'),
(1087, 'رهن', 'رهن', 'رهن', 'الرهن معروف، تقول: رهنت الشيء فلانا رهنا. فالشيء مرهون. وأرهنت فلانا ثوبا إذا دفعته إليه ليرهنه. وارتهنه فلان، إذا أخذه رهنا. والرهون، والرهان والرهن: جمع الرهن. والمراهنة والرهان: أن يراهن القوم على سباق الخيل وغيره. وأرهنت الميت قبرا: ضمنته إياه. وكل أمر يحتبس به شيء فهو رهنه، ومرتهنه، كما أن الإنسان رهين عمله.'),
(1088, 'نهر', 'نهر', 'نهر', 'النهر لغة في النهر، والجميع: نهر وأنهار. واستنهر النهر، أي: أخذ لمجراه موضعا مكينا. والمنهر: موضع النهر يحتفره الماء. والنهار: ضياء ما بين طلوع الفجر إلى غروب الشمس، لا يجمع. ورجل نهر: صاحب نهار، قال 2 : لست بليلي ولكني نهر ... لا أدلج الليل ولكن أبتكر والنهار: فرخ القطا والغطاط والعقاب ونحوه. ثلاثة أنهرة. ونهرت الرجل نهرا وانتهرته انتهارا: زجرته بكلام عن شر.'),
(1089, 'هرف', 'هرف', 'هرف', 'الهرف: شبه الهذيان من الإعجاب بالشيء. فلان يهرف بفلان نهاره كله، هرفا. وبعض السباع يهرف لكثرة صوته. وفي مثل: لا تهرف حتى تعرف 1 .'),
(1090, 'رهف', 'رهف', 'رهف', 'الرهف: مصدر الرهيف، وهو اللطيف الدقيق. رهف الشيء [يرهف] ، رهافة، وقلما يستعمل إلا مرهفا، وقلما يقال: رهيف. وأرهفت السيف إذا رققته. ورجل مرهف الجسم: رقيقه.'),
(1091, 'فهر', 'فهر', 'فهر', 'الفهر: الحجر قدر ما يكسر به جوز، أو يدق به شيء، وعامة العرب تؤنثه وتصغيره: فهيرة. وقريش كلهم ينسبون إلى فهر بن غالب بن النضر بن كنانة. وفي الحديث: كأنكم اليهود خرجوا من فهرهم 2 أي: من موضع مدراسهم الذي يجتمعون فيه كالعيد يصلون فيه.'),
(1092, 'رفه', 'رفه', 'رفه', 'رفه عيشه رفاهة ورفاهية فهو رفيه العيش، وهو أرغد الخصب. والرفه: ورد كل يوم، يقال: أوردتها رفها. قال لبيد 1 : يشربن رفها عراكا غير صادرة ... [فكلها كارع في الماء مغتمر] وأرفه القوم فهم مرفهون [إذا فعلت إبلهم كذلك] ولا يقولون: أرفهت الإبل، والاسم: الإرفاه. والإرفاه: الادهان كل يوم وقد نهى رسول الله ص عن الإرفاه. ورفهت عن فلان شدته وخناقه إذا نفست عنه ترفيها. والرفه: التبن.'),
(1093, 'فره', 'فره', 'فره', 'فره الشيء يفره فراهة فهو فاره بين الفراهة والفراهية. وقوله عز اسمه وتنحتون من الجبال بيوتا فارهين 2 أي: حاذقين، ومن قرأها فرهين فمعناه: أشرين بطرين. وناقة مفرهة: تلد فرها، قال النابغة 3 : أعطى لفارهة حلو ترابعها ... من المواهب لا تعطى على [حسد] يعني بالفارهة: القينة، وما يتبعها من المواهب. والجمع: الفواره والفره.'),
(1094, 'هرب', 'هرب', 'هرب', 'الهرب: الفرار. والمهرب: موضع الهرب تقول: فلان لنا مهرب. والمهرب: الفزع الهارب. تقول: جاء فلان مهربا، إذا أتاك هاربا فزعا.'),
(1095, 'هبر', 'هبر', 'هبر', 'الهبر: القطع في اللحم، قال 1 : تجد مهرة مثل القناة قويمة ... وعضبا إذا ما هز لم يرض بالهبر والهبرة: نحضة من اللحم لا عظم فيها. والهبير، والهبيرة واحدها،: ما اطمأن من الأرض وما حوله أشد ارتفاعا منه. والهبرية والإبرية: نخالة الرأس. وهو [ما تعلق بأسفل شعر الرأس كالنخالة] 2 . والهبور: الشعر النابت بالنبطية وهوبر: اسم رجل. وبنو هبار: فخذ من قريش من أسد بن عبد العزي.'),
(1096, 'رهب', 'رهب', 'رهب', 'رهبت الشيء أرهبه رهبا ورهبة، أي: خفته. وأرهبت فلانا. والرهبانية: مصدر الراهب، والترهب: التعبد في صومعة، والجميع: الرهبان والرهابنة خطأ 3 . والرهب- جزم- لغة في الرهب، والرهباء: اسم من الرهب، تقول: الرهباء من الله، والرغباء إليه، والنعماء منه. ورهبوت خير من رحموت، أي: أن ترهب خير من أن ترحم. والرهابة: عظيم في الصدر يشرف على [البطن] 4 كأنه ظرف لسان الكلب وناقة رهب: مهزولة جدا. والرهاب: الرقاق من النصال. رهبي: موضع'),
(1097, 'بهر', 'بهر', 'بهر', 'بهرته: عالجته حتى انبهر، والاسم: البهر. وإذا عجز الشيء عن الشيء قيل: بهره. وامرأة بهيرة: قصيرة ذليلة الخلقة، ويقال: هي الضعيفة المشي. وبهرها بكذا: قذفها ببهتان. والأبهران: عرقان، ويقال: هما الأكحلان، ويقال: بل هما عرقان مكتنفا الصلب من الجانبين. والأبهر: عرق في القلب يقال إن الصلب متصل به. قال 1 : وللفؤاد وجيب تحت أبهره ... لدم الغلام وراء الغيب بالحجر وقال رسول الله ص [وعلى] آله: ما زالت أكلة خيبر تعاودني فهذا أوان قطعت أبهري 2 . والأباهر من الريش: ما يلي الخوافي، وهي [الجوانب القصار] 3 . والأبهر من القوس: ما دون الطائف. والبهار- قبطية-: ثلاث مائة رطل. والبهار: من الآنية كالإبريق، قال في نعت الفرس 4 : على العلياء كوب أو بهار وابهار الليل: أي: انتصف، وبهرة الشيء: وسطه. والبهار: نوع من نبات الربيع. وبهراء: حي من اليمن.'),
(1098, 'بره', 'بره', 'بره', 'البرهان: بيان الحجة وإيضاحها. والبرهرهة: الجارية البيضاء، وبرهها: ترارتها وبضاضتها، وتصغير [البرهرهة] : بريهة، ومن أتمها قال: بريرهة، وأما بريهرهة فقبيحة [قلما يتكلم بها] 1 . وأبرهة: اسم أبي يكسوم الحبشي ملك اليمن، الذي ساق الفيل إلى البيت [فأهلكه الله] 2 ، قال 3 : منعت من أبرهة الحطيما ... وكنت فيما ساءه زعيما ومعنى (فيما) : بما.'),
(1099, 'هرم', 'هرم', 'هرم', 'هرم يهرم هرما ومهرما، وهي: هرمة، وهن هرمى وهرمات. والهرم: ضرب من النبات فيه ملوحة، وهو من أذل الحمض، وأشده استبطاحا على وجه الأرض، الواحدة: هرمة، وهو الذي يقال له: حيهلة، ويقال في مثل: أذل من هرمة قال زهير 1 : ووطئتنا وطء على حنق ... وطء المقيد يابس الهرم وابن هرمة، وابن عجزة آخر ولد الشيخ والشيخة، ويقال: ولد لهرمة. [وهرمة وهرم اسما رجلين] 2 .'),
(1100, 'همر', 'همر', 'همر', 'الهمر: صب الدمع والماء والمطر، وهمر الماء، وأنهمر فهو هامر منهمر. والفرس يهمر الأرض همرا، وهو شدة حفره الأرض بحوافره، قال 3 : يهامر السهل ويولي الأخشبا والهمار: النمام. والمهمار: الذي يهمر عليك الكلام همرا، أي: يكثر عليك.'),
(1101, 'رهم', 'رهم', 'رهم', 'الرهمة: مطرة ضعيفة القطر، دائمة، والجميع: رهم ورهام. وروضة مرهومة. والرهام من الطير: كل شيء لا يصطاد.'),
(1102, 'مهر', 'مهر', 'مهر', 'مهرت المرأة: قطعت لها مهرا فهي ممهورة. قال 4 : أمكم ناكحة ضريسا ... مهرها عنيزا وتيسا فإذا زوجتها رجلا على مهر قلت: أمهرتها. وامرأة مهيرة: غالية المهر. [والمهائر: الحرائر، وهن ضد السراري] 5 . والمهر: ولد الرمكة والفرس، والأنثى: مهرة، والجميع: مهار ومهارة. والماهر: الحاذق بكل عمل، وأكثر ما ينعت به: السابح المجيد قال: مثل الفراتي إذا ما طما ... يقذف بالبوصي والماهر ومهرت به أمهر به مهارة، إذا صرت به حاذقا.'),
(1103, 'مره', 'مره', 'مره', 'المره: خلاف الكحل. وامرأة مرهاء: لا تتعهد عينها بالكحل. وشراب أمره: ليس فيه من السواد شيء.'),
(1104, 'لهن', 'لهن', 'لهن', 'اللهنة: ما يتعلل به قبل الغداء، وقد لهنت للقوم.'),
(1105, 'نهل', 'نهل', 'نهل', 'أنهلت الإبل. وهو أول سقيكها، و [قد] نهلت، إذا شربت في أول الورود، والأسم: النهل ... والمنهل: المورد حتى صارت منازل السفار على المياه مناهل. والمنهال: الرجل الكثير الإنهال. والناهلة: المختلفة إلى المنهل 2 . لم تراقب هناك ناهلة الواشين ... حتى أجرهد ناهلها أي: أسرع. وقال في النهل 3 : نهلنا من دماء بني لؤي ... وأروينا القنا حتى روينا ويقال: نهل الرجل: عطش أشد العطش، ونهل إذا شرب حتى روي، وهذا من الأضداد. وإبل نهلة ونهول. وأنهلت الرجل: أغضبته. [ومنهال: اسم رجل] 1 .'),
(1106, 'هلف', 'هلف', 'هلف', 'الهلوف: الرجل الكذوب، ويقال: الشيخ القديم. والهلوف: اللحية الضخمة. قال 2 : هلوفة كأنها جوالق ... نكداء لا بارك فيها الخالق'),
(1107, 'لهف', 'لهف', 'لهف', 'التلهف على الشيء: التحسر عليه يفوتك وقد كنت أشرفت عليه. ولهف نفسه وأمه إذا قال: وا نفساه، وا أمياه، ويقال: ووا لهفتاه ووا لهفتياه. ورجل لهفان: شديد اللهف. وامرأة لهفي والجميع: لهاف ولهافي. والملهوف: المظلوم ينادي ويستغيث. وفي الحديث: أجب الملهوف 3 . واللهوف: الطويل.'),
(1108, 'هلب', 'هلب', 'هلب', 'الهلب: ما غلظ من الشعر كشعر ذنب الناقة. ورجل أهلب: غليظ شعر ذراعيه وجسده وفرس مهلوب: هلب ذنبه، أي: استوصل جزا. وهلبتنا السماء، أي: بلتنا بشيء من ندى أو نحوه.'),
(1109, 'هبل', 'هبل', 'هبل', 'الهبل: الشيخ الكبير، والمسن من الإبل، قال 1 : أنا أبو نعامة الشيخ الهبل ... أنا الذي ولدت في أخرى الإبل وهبلته أمه، أي: ثكلته، والهبل كالثكل. والمهبل: موضع الولد في الرحم، قال 2 : وقد طوت ماء الفنيق المهبل ... بين الكلى منها وبين المهبل في حلق ذات رتاج مقفل والمهبل: الذي قيل له: هبلتك أمك. والهبال: المحتال والصياد يهتبل الصيد، أي: يغتنمه. قال ذو الرمة: 3 ومطعم الصيد هبال لبغيته ... [ألفى أباه، بذاك الكسب، يكتسب] وسمعت كلمة فاهتبلتها، أي: اغتنمتها. وهبل: صنم كان لقريش. قال أبو سفيان يوم أحد: أعل هبل، فقال رسول الله صلى الله عليه وسلم وعلى آله: الله أعلى وأجل. والمهبل: الكثير اللحم. قال 1 . ريان لا عش ولا مهبل وأصبح فلان مهبلا، أي: مورما مهيجا.'),
(1110, 'لهب', 'لهب', 'لهب', 'اللهب: اشتعال النار الذي قد خلص من الدخان. واللهبان: توقد الجمر 2 بغير ضرام وكذلك لهبان الحر في الرمضاء. ونحوها. قال 3 : لهبان وقدت حزانه ... يرمض الجندب منه فيصر وألهبت النار فالتهبت، وتلهبت. واللهبة: العطش، وقد لهب يلهب لهبا، فهو لهبان، أي: عطشان جدا، وهي لهبى، أي: عطشى جدا، وهم لهاب، أي: عطاش جدا. واللهب: وجه من الجبل كالحائط لا يستطاع ارتقاؤه، وكذلك لهب أفق السماء. والجميع: اللهوب. واللهب: الغبار الساطع. وفرس ملهب: شديد الجري ملهب الغبار. قال 4 : يقطعهن بأنفاسه ... ويلوي إلى حضر ملهب'),
(1111, 'بهل', 'بهل', 'بهل', 'باهلت فلانا، أي: دعونا على الظالم منا. وبهلته: لعنته.. وابتهل إلى الله في الدعاء، أي: جد واجتهد. وامرأة بهيلة، لغة في البهيرة. والأبهل: شجر يقال له: الأيرس، وليس بعربية محضة، ويسمى بالعربية عرعرا. والباهل: المتردد بلا عمل، [وهو أيضا] : الراعي بلا عصا. وأبهل الراعي إبله: تركها. والباهل: الناقة التي ليست بمصرورة، لبنها مباح لمن حل ورحل، وإبل بهل. ورجل بهلول: حيي كريم، وامرأة بهلول. والبهل: الشيء اليسير الحقير، يقال: أعطاه قليلا بهلا، قال 1 : وأعطاك بهلا منهما فرضيته ... وذو اللب للبهل الحقير عيوف والبهل: واحد لا يجمع. وامرأة باهلة: لا زوج لها. وباهلة: حي من العرب.'),
(1112, 'بله', 'بله', 'بله', 'البله: الغفلة عن الشر. رجل أبله، والبله: جماعته. وفي الحديث: أكثر أهل الجنة البله 2 قال: 3 أبله صداف عن التفحش والتبله: تطلب الضالة. بله: كلمة بمعنى أجل، قال 4 : بله أني لم أخن عهدا ولم ... أقترف ذنبا فتجزيني النقم وبله: بمعنى كيف، ويكون في معنى دع، بكله نطق الشعر.'),
(1113, 'هلم', 'هلم', 'هلم', 'الهلام: طعام يتخذ من لحم العجل بجلده. [والهلمان: الشيء الكثير] 1 . وهلم: كلمة دعوة إلى شيء. التثنية والجمع والوحدان، والتأنيث والتذكير فيه سواء، إلا في لغة بني سعد فإنهم يحملونه على تصريف الفعل، فيقولون: هلما وهلموا ونحو ذلك.'),
(1114, 'همل', 'همل', 'همل', 'الهمل: السدى، وما ترك الله الناس هملا، أي: سدى بلا ثواب وبلا عقاب. وإبل هوامل [مسيبة] 2 لا ترعى. وأمر مهمل، أي: متروك.'),
(1115, 'لهم', 'لهم', 'لهم', 'لهمت الشيء. وقلما يقال إلا التهمت، وهو ابتلا عكه بمرة، قال 3 : ما يلق في أشداقه تلهما وقال: 4 كذاك الليث يلتهم الذبابا وأم اللهيم: الحمى، ويقال: بل هو الموت، لأنه يلتهم كل أحد. وفرس لهم: سابق يجري أمام الخيل، لالتهامه الأرض، والجميع: لهاميم. ورجل لهوم، أي: أكول. ألهمه الله خيرا، أي: لقنه خيرا. ونستلهم الله الرشاد. وجيش لهام أي: يغتمر من يدخله، أي: يغيبه في وسطه.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1116, 'مهل', 'مهل', 'مهل', 'المهل- مجزوم-: السكينة والوقار، تقول: مهلا يا فلان، أي: رفقا وسكونا، لا تعجل ويجوز التثقيل، كما قال 1 : فيا بن آدم ما أعددت في مهل ... لله درك ما تأتي وما تذر وقال جميل 2 [في تخفيف مهل] 3 : يقولون: مهلا يا جميل، وإنني ... لأقسم مالي عن بثينة من مهل وأمهلته: أنظرته، ولم أعجله. ومهلته: أجلته. والمهل: خثارة الزيت، ويقال: النحاس الذائب، ويقال: الصديد والقيح. والمهل: الفلز، وهو جواهر الأرض من الذهب والفضة. والمهل: ما يتحات من الخبزة من رماد أو غيره إذا أخرجت من الملة. والمهل: ضرب من القطران، إلا أنه ماء رقيق يشبه الزيت، وهو يضرب إلى الصفرة من مهاوته، وهو دسم تدهن به الإبل في الشتاء، وسائر القطران لا يدهن به، لأنه يقتل.'),
(1117, 'هنف', 'هنف', 'هنف', 'الهناف: مهانفة الجواري بالضحك، وهو فوق التبسم [قال: تغض الجفون على رسلها ... بحسن الهناف وخون النظر] 1 وقال: 2 إذا هن فصلن الحديث لأهله ... حديث الزنى فصلنه بالتهانف وهذا نعت لا يوصف به الرجال.'),
(1118, 'نفه', 'نفه', 'نفه', 'نفهت نفسي: أعيت. والنافه المنفه: الكال المعيي [من الدواب] 3 وجمع النافه: نفه قال 4 : بنا حراجيج المهارى النفه والنافهة: الأنثى.'),
(1119, 'هنب', 'هنب', 'هنب', 'هنب، وبنو هنب: حيان من ربيعة.'),
(1120, 'نهب', 'نهب', 'نهب', 'النهب: الغنيمة، والانتهاب: أخذه 1 من شاء. والإنهاب: إباحته لمن شاء. والنهبي: أسم لما انتهبته. والنهاب: جمع النهب. والمناهبة: المباراة في الحضر والجري، فرس يناهب فرسا. قال العجاج: 2 وإن تناهبه تجده منهبا ويقال الفرس الجواد: أنه لينهب الغاية والشوط قال 3 : [تبري له صعلة خرجاء خاضعة] ... والخرق دون بنات البيض منتهب يعني: في التباري بين النعامة والظليم.'),
(1121, 'بهن', 'بهن', 'بهن', 'البهوني من الإبل: ما يكون بين العربية والكرمانية 4 ، دخيل في الكلام. وجارية بهنانة وهنانة، أي: لينة في منطقها وعملها. [والبهنانة أيضا: الطيبة الريح]'),
(1122, 'نبه', 'نبه', 'نبه', 'النبه: الضالة توجد عن غير طلب غفلة، تقول: وجدتها نبها عن غير طلب، وأضللتها نبها، لم تعلم متى ضل. قال 6 : كأنه دملج من فضة نبه ... في ملعب من جواري الحي مفصوم يصف الخشف. والنبه: الانتباه من النوم. تقول: نبهته وأنبهته من النوم، ونبهته من الغفلة. قال 1 : لعمري لقد نبهت من كان نائما ... وأسمعت من كانت له أذنان ورجل نبيه، أي: شريف، نبه نباهة. ونبهت باسم فلان، أي: جعلته مذكورا.'),
(1123, 'هنم', 'هنم', 'هنم', 'الهينمة: الصوت الخفي، وهو شبه قراءة غير بينة. قال رؤبة: 2 لم يسمع الركب بها رجع الكلم ... إلا وساويس هيانيم الهنم وليهود تهنيم في بيعتها، قال: 3 ألا يا قيل ويحك قم فهينم ... لعل الله يصبحنا غماما'),
(1124, 'نهم', 'نهم', 'نهم', '[النهيم: شبه الأنين والطحير والنحيم] 4 . نهم ينهم نهيما. قال 5 : ما لك لا تنهم يا فلاح ... إن النهيم للسقاة راح والنهم: الحذف بالحصى ونحوه. نهم ينهم نهما. قال 6 : ينهمن بالدار الحصى المنهوما والنهم: زجرك الإبل، تصيح بها لتمضي. نهم الإبل ينهمها وينهمها نهما ونهيما. والنهمة: بلوغ الهمة والشهرة في الشيء. هو منهوم بكذا، أي: مولع به، وفي الحديث: منهومان لا يشبعان منهوم بالعلم ومنهوم بالمال 1 . والنهامي: الحداد، قال 2 : [وفاقد مولاه أعارت رماحنا ... سنانا كنبراس النهامي منجلا والنهام: ضرب من الطير كالهام. والنهام: الأسد، لصوته. والفعل: نهم ينهم نهيما والنهيم: صوت فوق الزئير، قال 3 : إذا أعاد الزار أو تنهما'),
(1125, 'مهن', 'مهن', 'مهن', 'المهنة: الخدمة، مهنهم: خدمهم، والمهنة: الحذاقة في العمل ونحوه، وقد مهن يمهن مهنا، [ومهنة، ومهنة] 4 . ويقال: خرقاء لا تحسن المهنة، أي: الخدمة. والماهن: العبد، ورجل مهين، أي: حقير ضعيف، وقد مهن مهانة. ومهنت الإبل أمهنها إذا جلبتها عند الصدر.'),
(1126, 'فهم', 'فهم', 'فهم', 'فهمت الشيء [فهما وفهما] : عرفته وعقلته، وفهمت فلانا وأفهمته: عرفته، وقرأ ابن مسعود: فأفهمناها سليمان 5 . ورجل فهم: سريع الفهم.'),
(1127, 'بهم', 'بهم', 'بهم', 'البهمة: أسم للذكر والأنثى من أولاد بقر الوحش وضروب الغنم، والجميع: البهم والبهام. والبهم أيضا: صغار الغنم. والبهمي: نبات تجد به الغنم وجدا شديدا ما دام أخضر. فإذا يبس هر شوكه وامتنع. الواحد: بهمي أيضا، ويقال للواحدة بهماة أيضا. والإبهام: الإصبع الكبرى [التي تلي المسبحة] ، والجميع: الأباهيم. [ولها مفصلان] 1 وأبهم الأمر، أي: اشتبه، لا يعرف وجهه. واستبهم علي هذا الأمر. وكان ابن عباس سئل [عن قوله عز وجل] : وحلائل أبنائكم الذين من أصلابكم 2 فلم يبين أدخل بها أم لا، فقال، أبهموا ما أبهم الله 3 . وباب مبهم: لا يهتدي لفتحه، قال الشاعر 4 : وكم من شجاع مارس الحرب دهره ... فغاص عليه الموت والباب مبهم والبهيم: ما كان من الألوان لونا واحدا لا شية فيه من الدهمة والكمتة. وصوت بهيم، أي: لا ترجيع فيه.. وليل بهيم: لا ضوء فيه إلى الصباح. والبهيمة: ذات أربع قوائم من دواب البر والبحر. ويحشر الناس يوم القيامة [غرلا] بهما 1 ، أي: ليس بهم شيء مما كان في الدنيا، نحو العمى والعرج، والجذام والبرص. ويقال: بل عراة ليس معهم شيء من متاع الدنيا. والبهمة: الأبطال، قال متمم بن نويرة 2 : وللشرب فابكي مالكا ولبهمة ... شديد نواحيها على من تشجعا'),
(1128, 'خق', 'خق', 'خق', 'قال الخليل: يقال لقنب الدابة إذا زعق: خق. فإذا ضوعف مخففا قيل: خقخق، والخقخقة: صوت القنب والفرج إذا ضوعف. وإخقاق الأحراح: صوتها عند النحج، وهو شدة المجامعة. والأتان تخق خقيقا وقد خقت، وهو صوت حيائها من الهزال والاسترخاء عند المجامعة. وأتان خقوق: واسعة الدبر. وأخقت البكرة إذا اتسع خرقها عن المحور. واتسعت النعامة عن موضع طرفها من الزرنوق 1 . والأخقوق: نقر في الأرض أي: حفر طوال، وهي كسور فيها في منفرج الجبل وفي الأرض المتفقرة. والأخقوق: قدر ما يختفي فيه الرجل أو الدابة، ومن قال: اللخقوق فهو غلط من قبل لام المعرفة 2 .'),
(1129, 'خج', 'خج', 'خج', 'الريح الخجوج: التي تخج في هبوبها، أي تلتوي، هي التي تصوت. ولو ضوعف فقيل: خجخجت الريح لكان صوابا. والخجخجة: الانقباض في موضع يختفي فيه. واختج الجمل والناشط في سيره وعدوه إذا لم يستقم. ورجل خجاجة، أي خفيف أحمق لا يعقل، والخجخاج من الرجال: الذي يهمر الكلام، ليس لكلامه جهة.'),
(1130, 'جخ', 'جخ', 'جخ', 'جخ الرجل يجخ جخا، أي: تحول من مكان إلي مكان، وفي الحديث: كان رسول الله ص إذا صلى جخ 1 أي: تحول من مكان إلي مكان، ويقال: جخى، أي: مد ضبعيه، وتجافى في الركوع والسجود. وفي الحديث: إن أردت العز فجخجخ في جشم 2 ، أي: صح وناد فيهم، ويمكن أن يكون بمعنى: تحول إليهم. والجخجخة: الصياح والنداء.'),
(1131, 'خش', 'خش', 'خش', 'خششت البعير: جعلت الخشاش في أنفه، وجمعه: أخشة. قال ذو الرمة 3 : تشكو الخشاش ومجرى النسعتين كما ... أن المريض إلى عواده، الوصب والخشاش من الطير: صغارها، وخشاش الأرض: صغار دوابها. ورجل خشاش لطيف الرأس، ضرب الجسم، خفيف. قال أنا الرجل الضرب الذي تعرفونه ... خشاش كرأس الحية المتوقد والخشخاش: شر الحيات وأخبثها، وهو الذي لا يطني، أي: لا يفلت لديغه. والخششاوان: عظمان ناتئتان خلف الأذنين. والخشخشة: صوت السلاح، وصوت ثمر الينبوت، والشخشخة لغة. والخشخاش: [نبت منه] الأبيض والأسود، فالأبيض منه دواء معروف، والأسود من السموم. والخشخاش: الجماعة. ورجل مخش ومخشف وهو الجريء على العمل'),
(1132, 'شخ', 'شخ', 'شخ', 'يقال: شخ الصبي ببوله، إذا أسمعك صوته، وكذلك إذا امتد كالقضيب. والشخشخة لغة في الخشخشة.'),
(1133, 'خض', 'خض', 'خض', 'الخضخاض: ضرب من القطران، وكل شيء يتحرك ولا يصوت خثورة، يقال: إنه يتخضخض. ويقال: وجأه بالخنجر فخضخض بطنه. وخضخضت الأرض، لترخو مواضعها وتثور. وفي الحديث: نكاح الإماء خير من الخضخضة، والخضخضة خير من الزنا يعني: جلد عميرة. والخضاض: الشيء اليسير من الحلي. قال 1 : ولو أشرفت من كفة الستر عاطلا ... لقلت: غزال ما عليه خضاض والخضاض: الرجل الأحمق. والخضيض: المكان المنبوث تبله الأمطار.'),
(1134, 'ضخ', 'ضخ', 'ضخ', 'الضخ: امتداد البول. والمضخة: قصبة في جوفها خشبة 2 يرمي بها من الفم.'),
(1135, 'خص', 'خص', 'خص', 'الخص: بيت يسقف بخشبة على هيئة الأزج، وجمعه: خصاص. وخصصت الشيء خصوصا، واختصصته. والخاصة، الذي اختصصته لنفسك. والخصاصة: سوء الحال. والخصاص: شبه كوة في قبة ونحوها إذا كان واسعا قدر الوجه، قال 3 : وإن خصاص ليلهن استدا ... ركبن من ظلمائه ما اشتدا أخبر أنهن لا يهبن الليل، وشبه القمر بالخصاص، وبعض يجعل الخصاص للضيق والواسع، حتى قالوا لخروق المصفاة: خصاص. وخصاص المنخل: خروقه، وجمعه: أخصة، ويسمى الغيم: خصاصة. وكل خرق أو خلل في سحاب أو منخل يسمى: خصاصة والجميع: خصاص. والخصاص: فرج ما بين الأثافي.'),
(1136, 'صخ', 'صخ', 'صخ', 'الصاخة: صيحة تصخ الآذان فتصمها، ويقال: هي الأمر العظيم، يقال: رماه الله بصاخة، أي: بداهية وأمر عظيم. والغراب يصخ بمنقاره في دبر البعير، أي: يطعن فيه.'),
(1137, 'خس', 'خس', 'خس', 'الخس: بقلة من أحرار البقول حارة لينة تزيد في الدم. والخساسة: مصدر الخسيس، يقال: خسست نصيبه خسا فهو مخسوس، وامرأة مستخسة، أي: قبيحة الوجه محقورة، اشتقت من الخسيس، أي: القليل. وخس الرجل يخس خسوسة: صار خسيسا، وخس حظه خسا. وبنت الخس الأيادية معروفة. سخ 1 : السخاخ: الأرض الحرة اللينة. وأرض سخاء 2 .'),
(1138, 'خز', 'خز', 'خز', 'الخز: معروف، والجميع: الخزوز. والخزز: الذكر من الأرانب وثلاثة خززة والجميع: خزان.'),
(1139, 'زخ', 'زخ', 'زخ', 'زخخت في قفاه زخا، أي: دفعت. والزخيخ: شدة بريق الجمر والحر، وقد زخ يزخ زخيخا، قال: 1 فعند ذاك يطلع المريخ ... في الصبح يحكي لونه زخيخ من شعلة ساعدها النفيخ وزخة الرجل، ومزخته: امرأته [وقد زخها زوجها يزخها زخا إذا جامعها] . وزخ ببوله مثل ضخ. وزخ بنفسه: وثب، وربما وضع الرجل مسحاته في وسط نهر، ثم يزخ بنفسه، أي: يثب.'),
(1140, 'خط', 'خط', 'خط', 'الخط أرض تنسب إليها الرماح، يقال: رماح خطية، فإذا جعلت النسبة اسما لازما قلت: خطية. والخطة من الخط كالنقطة من النقط. والخطوط: من بقر الوحش الذي يخط الأرض بأظلافه، وكل دابة تخط الأرض بأظلافها فكذاك. والتخطيط كالتسطير، وتقول: خططت عليه ذنوبه، أي: سطرتها. وخط وجهه واختط: [صارت فيه خطوط] 1 . وخططت بالسيف وسطه. والخطة: شبه القصة، يقال: إن فلانا ليكلفني خطة من الخسف. والخطيطة: الأرض التي لم تمطر بين أرضين ممطورتين، وتجمع: خطائط، قال 2 : على قلاص تختطي الخطائطا والخط: ضرب من البضع، تقول: خط بها، أي: نكحها، [ويقال: خط بها قساحا] 3 . والخط: الكتابة ونحوها مما يخط. والخطة: ارض يختطها الرجل إذا لم تكن لأحد قبله. وإنما كسرت الخاء، لأنها أخرجت على مصدر [بني على فعلة] 4 .'),
(1141, 'طخ', 'طخ', 'طخ', 'الطخوخ: الشرس الخلق، السيء العشرة. والطخطخة: تسوية الشيء، كنحو السحاب يكون فيه فرج، ثم يتطخطخ، أي: ينضم بعضه إلى بعض، وهو الطخطاخ. والمتطخطخ: الرجل الضعيف البصر، والجميع: متطخطخون، وهو المطرخم ايضا، واطرخمامه: كلالة بصره. وطخطخ فلان إذا ضحك،. أي: إذا قال: طيخ طيخ، وهو أقبح القهقهة. والطخطاخ: اسم رجل. وربما حكي به صوت الحلي ونحوه.'),
(1142, 'خد', 'خد', 'خد', 'المخدة: المصدغة، واشتقاقهما من الخد والصدغ، وهو [أي الخد] من لدن المحجر إلى اللحي من الجانبين. والخد: جعلك أخدودا في الأرض، تحفره مستطيلا، يقال: خده خدا، قال 1 : ضاحي الأخاديد إذا الليل ادلهم ومثله أخاديد السياط، في الظهر، وهي طرائقها. والتخديد: تخديد اللحم عند الهزال. ورجل متخدد، وامرأة متخددة، أي: مهزول قليل اللحم. وإذا شق [الجمل] بنابه شيئا قيل: خده. قال 2 : قدا بخداد وهذا شرعبا أي قطعا طويلا.'),
(1143, 'دخ', 'دخ', 'دخ', 'الدخ: الدخان. والدخ مثل الدوخ. ودخدخته ودوخته، أي: ذللته ووطئته، ودخدخت البلاد ودوختها، أي: وطئتها.'),
(1144, 'تخ', 'تخ', 'تخ', 'التختخة: في حكاية بعض الأصوات كأصوات الجنان وبه سمي التختاخ. والتخ: العجين الحامض، تخ يتخ تخا وتخوخا، وأتخه إتخاخا'),
(1145, 'خر', 'خر', 'خر', 'الخرير: صوت الماء وصوت الريح، وخرير العقاب: حفيفها. وقد يضاعف إذا توهم سرعة الخرير في القصب فيحمل على الخرخرة، وأما في الماء فلا يقال إلا خرخرة. والهرة تخر في نومها فهي خرور، وخر النمر خريرا، وخرخر يخرخر خرخرة، ويقال لصوته أيضا: خرير، وهدير وغطيط.'),
(1146, 'رخ', 'رخ', 'رخ', 'الرخاخ: لين العيش. والرخ: نبات هش والرخ: من أدوات الشطرنج، والجميع: رخخة من كلام العجم.'),
(1147, 'خل', 'خل', 'خل', 'الاختلال من الخل الذي يتخذ من عصير العنب والتمر. والخل: طريق نافذ بين رمال متراكمة، سمي به، لأنه يتخلل، أي: ينفذ. والخل في العنق: عرق متصل بالرأس. قال منظور 1 . ثم إلى هاد شديد الخل ... وعنق كالجذع متمهل أي طويل. والخل: الثوب البالي إذا رأيت فيه طرقا. وخللت الثوب ونحوه أخله بخلال، أي، شككته بخلال، والخلال: اسم خشبة أو حديدة يخل بها، والخل: خلول الجسم، أي: تغيره وهزاله. ورجل خل، وجمعه: خلون، أي: مهزولون، قال 2 . واستهزأت بي ابنة السعدي حين رأت ... شيبي وما خل من جسمي وتحنيبي والخلل منفرج ما بين كل شيئين. وخلل السحاب: ثقبه، وهي مخارج مصب القطر، والجمع: الخلال، قال الله جل ذكره: فترى الودق يخرج من خلاله* 3 . وخلال الدار: ما حوالي جدرها، وما بين بيوتها، ومنه قوله [جل وعز] : فجاسوا خلال الديار 4 . وتقول: رأيته خلل الدناس، وخلل كل شيء: ما بدا لك من بين كل شيء من نقبه أي من جوبه. والخلل في الحرب وفي الأمر كالوهن. والخلل: الرقة في الناس. والخلل: ما يبقى [من الطعام] بين الأسنان، جماعته كالواحد. وأخل بهم فلان، إذا غاب عنهم. وأخل الوالي بالثغور إذا قلل الجند بها. ونزلت به خلة، أي: حاجة وخصاصة. واختل إلى فلان، أي احتيج إليه، من الخلة، وهي الحاجة. وأخل بك فلان، إذا أدخل عليك الضرورة. والخليل: الفقير الذي أصابته ضارورة في ماله، وغير ذلك، قال زهير 1 : وإن أتاه خليل يوم مسألة ... يقول: لا غائب مالي ولا حرم والخليل في هذا البيت: الذي أصابته ضارورة [فهو] مفعول رد إلى فعيل. واختللت: افتقرت. واختللت إلى رؤيتك. أي: اشتقت. والخلة من النبات: ما ليس بحمض. قال 2 : كانوا مخلين فلاقوا حمضا أي: كانوا في خلة فصاروا في حمض، يعني: الجيش. والخلة: العرفج، وكل شجر يبقى في الشتاء وهو مثل العلقى. وخللته بالرمح [واختللته] 3 : طعنته به. والخلة: الخصلة، والجميع: الخلال، والخلات. والخلة: المرأة يخالها الرجل. والخلة والخلان: جماعة الخليل. وخاللته مخالة وخلالا والخلة: الاسم. وفلان خلي، وفلانة: خلتي. بمنزلة: حبي وحبتي. والخل: الرجل الخليل. والخلال: البلح، بلغة أهل البصرة، وهو الأخضر من البسر قبل أن يشقح 4 . الواحدة: خلالة. الواحدة: خلالة. والخلة: جفن السيف المغشي بالأدم، والجميع: الخلل. والمخلخل: موضع الخلخال. ولسان الرجل وسيفه خليلاه في كلام العرب، قال عمرو بن معدي كرب: خليلي لم أخنه ولم يخني ... على الصمصامة السيف السلام والخلخال من الحلي: ما تتخلخل به الجارية.'),
(1148, 'لخ', 'لخ', 'لخ', 'اللخلخة من الطيب: ضرب منه. واللخلخانية: العجمة، [يقال] رجل لخلخاني، والمرأة بالهاء، أي: لا يفصحان، قال الأخطل 1 يصف وده: أذود اللخلخانيات عنه ... وأمنحه المصرحة العرابا يعني: أنه ببذله للعربيات، ويمنعه من اللخلخانيات. والمصرحة: الصريحة الأنساب.'),
(1149, 'خن', 'خن', 'خن', 'خنت المرأة تخن خنينا، وهو دون الانتحاب من البكاء، والخنخنة: ألا يبين الكلام فيخنخن في خياشيمه، قال 2 : خنخن لي في قوله ساعة ... وقال لي شيئا فلم أسمع والخنان: داء يأخذ الطير في حلوقها، فيقال: طير مخنون. والخنان في الإبل كالزكام في الناس فيقال: خن [البعير] فهو مخنون. والخنة كالغنة كأن الكلام يرجع إلى الخياشيم، يقال: امرأة خناء وغناء، وفيها مخنة، أي: خنة. والمخن: الرجل الطويل في اعتدال. والخنين: الضحك، إذا اظهرته فخرج جافيا، يقال: خن يخن خنينا، فإذا خرج رقيقا، فهو الرنين فإذا أخفاه فهو الهنين.'),
(1150, 'نخ', 'نخ', 'نخ', 'النخة والنخة، لغتان: اسم جامع للحمر. وفي الحديث ليس في النخة صدقة 1 . والنخ: أن تناخ النعم قريبة من المصدق حتى يصدقها، قال: 2 أكرم أمير المؤمنين النخا والنخ: الزجر، كقولك للبعير: إخ إخ، وقد نخها ينخها، قال 3 إن لها لسائقا مزخا ... أعجم إلا أن ينخ نخا والنخ لم يترك لهن مخا وهو التأنيخ أيضا. والنخنخة من الإناخة، تقول: أنختها فاستناخت، أي: بركت، ونخنختها فتنخنخت، من الزجر [أي: أبركتها فبركت] . قال 4 : ولو أنخنا جمعهم تنخنخوا'),
(1151, 'خف', 'خف', 'خف', 'الخف: مجمع فرسن البعير، والجمع: أخفاف. والخف: ما يلبسه الإنسان، وتخففت بالخف، أي: لبسته. والخف: كل شيء خف محمله. والخفة: خفة الوزن، وخفة الحال. وخفة الرجل: طيشه، وخفته في عمله. [والفعل من ذلك كله] : خف يخف خفة فهو خفيف، فإذا كان خفيف القلب في توقده، فهو خفاف، ينعت به الرجل، كالطويل والطوال، والعجيب والعجاب، وكأن الخفاف أخف من الخفيف. وكذلك بعير خفاف، قال أبو النجم: 1 جوز خفاف قلبه مثقل وأخف فلان إذا خفت حاله، أي: رقت. وأخف الرجل: قل ثقله في سفر أو حضر، كما قال مالك بن دينار: فاز المخفون 2 فهو مخف. وخفان: موضع كثير الأسد. والخفانة: النعامة السريعة. والخفوف: سرعة السير من المحلة، تقول: حان الخفوف. وخف القوم، إذا ارتحلوا مسرعين، قال 3 : خف القطين فراحوا منك وابتكروا ... [فما تواصله سلمى وما تذر] والخف: كل شيء خف حمله، كما قال 4 : يطير الغلام الخف عن صهواته ... [ويلوي بأثواب العنيف المثقل]'),
(1152, 'فخ', 'فخ', 'فخ', 'الفخيخ دون الغطيط في النوم، وللأفعى فخيخ يعرف به مكانها. والفخ: مصيدة من كلام العجم، وجمعه: فخاخ.'),
(1153, 'خب', 'خب', 'خب', 'الخبب: ضرب من العدو، تقول: جاءوا مخبين تخب بهم دوابهم، قال يخب بي الكميت قليل وفر ... أفكر في الأمور واستعين والخب: الجربزة 2 ، والنعت: خب وخبة، والفعل: خب يخب خبا. والتخبيب: إفساد الرجل عبد رجل أو أمته. والخب: هيج البحر، يقال: أصابهم الخب إذا اضطربت أمواج البحر، والتوت الرياح في وقت معلوم، ومن يكون في البحر يلجأ إلى الشط، ويلقي الأنجر، يقال: خب بهم البحر يخب. والخبة: من المراعي، قال الراعي: 3 حتى ينال خبة من الخبب والخبة: مكان يستنقع فيه الماء، فتنبت حوله البقول. والخبة، وجمعها: خبات: شبه الطية من الثوب، مستطيلة كأنها طرة، وبها يشبه طرائق الرمل، وهي الخبيبة أيضا. وخب النبات والسفى، أي: أرتفع وطال. والمخبة والخبيبة: بطن الوادي. والخبخاب: رخاوة الشيء المضطرب. وتخبخب لحمه إذا اضطرب.'),
(1154, 'بخ', 'بخ', 'بخ', 'تبخبخ الحر: سكن بعض فورته، وتبخبخت الغنم: سكنت حيث كانت، وتبخبخ لحمه. إذا صوت من الهزال. وبخ: كلمة تقال عند الإعجاب بالشيء، يخفف ويثقل، نقول: بخبخ الرجل إذا قال: بخ وقال الراجز: 1 بخ بخ لهذا كرما فوق الكرم ودرهم بخي: كتب عليه: بخ، ودرهم معمعي: كتب عليه مع مضاعفا، لأنه منقوص وإنما يضاعف إذا كان في حال إفراده مخففا، لأنه لا يتمكن في التصريف في حال تخفيفه، فيحتمل طول التضاعف، ومن ذلك ما يثقل فيكتفي بتثقيله، وإنما حمل ذلك على ما يجري على ألسنتهم، فوجدوا (بخ) مثقلا في مستعمل الكلام. ووجدوا (مع) مخففا، وجرس الخاء امتن من جرس العين، فكرهوا تثقيل العين، فإفهم ذلك. وبخباخ الجمل أول هديره. وبخبخة البعير وبخباخه: هدير يملأ الفم شقشقته قال 2 : بخ وبخباخ الهدير الزغد [وبخبخ الرجل: قال: بخ بخ] 3 ، قال العجاج: 4 إذا الأعادي حسبونا بخبخوا أي قالوا: بخ بخ، كما قال الشاعر 5 في عبد الرحمن بن الأشعث: بين الأشبج وبين قيس باذخ ... بخبخ لوالده وللمولود فأخذه الحجاج وقتله، وقال: والله لا تبخبخ بعد هذا أبدا.'),
(1155, 'خم', 'خم', 'خم', 'اللحم المخم: الذي تغيرت ريحه. ولما يفسد فساد الجيف. وخم مثله، وقد خم يخم خموما. قال 1 وشمة من شارف مزكوم ... قد خم أو قد هم بالخموم وإذا خبث ريح السقاء، فأفسد اللبن، قيل: أخم اللبن فهو مخم. فإذا انتن فهو الذفر من البان الإبل. والخمخمة: ضرب من الأكل قبيح، وبه سمي الخمخام، ومنه: التخمخم. والخمخم: نبت، قال: 2 [ما راعني إلا حمولة أهلها] ... وسط الديار تسف حب الخخم والخمامة: القمامة والكناسة من خممت البيت، أي: كنسته. والخمامة: ريشة فاسدة رديئة تحت الريش. ورجل مخموم القلب كأنه قد نقي من الغش والغل.'),
(1156, 'مخ', 'مخ', 'مخ', 'المخ: نقي العظم، وجمعه: مخخة، فإذا قلت: مخة فجمعها: مخ. وتمخخت العظم تمصصته. وقد يجيء (المخ) في الشعر ويراد به شحم العين. يقال: آخر مخ يبقى في الجسد: مخ العين، ومخ السلامي، قال 3 : لا يشتكين عملا ما أبقين ... ما دام مخ في سلامي أو عين وامتخخت [العظم] : انتزعت مخه. وأمخ العظم، وأمخت الشاة، إذا اكتنزت سمنا.'),
(1157, 'خسق', 'خسق', 'خسق', 'خسق [السهم] يخسق خسقا وخسوقا 1 ، وناقة خسوق: [سيئة الخلق] 2 تخسق الأرض بمناسمها، إذا مشت انقلب منسمها فخد في الأرض.'),
(1158, 'خزق', 'خزق', 'خزق', 'كل شيء حاد رززته في الأرض أو غيرها فارتز فقد خزقته. والخزق، ما ينفذ. خزق يخزق، وخسق لغة فيه. والمخزق: عويد في طرفه مسمار محدد، ويكون عند بياع البسر بالنوى، فإذا أخذ ما معهم من النوى اشترط له بكذا وكذا ضربة بالمخزق فما انتظم فيه من البسر فهو له، قل أو كثر، وإن أخطأ فلا شيء له وذهب نواه.'),
(1159, 'خذق', 'خذق', 'خذق', 'الخذق للبازي إذا أسبح. ولسائر الطير الذرق. خذق خذقا'),
(1160, 'خرق', 'خرق', 'خرق', 'خرقت الثوب إذا شققته. وخرقت الأرض إذا قطعتها حتى بلغت أقصاها. وبه سمي الثور مخراقا. والإختراق: المرور 1 في الأرض غير طريق عرضا. واخترقت دار فلان: جعلتها طريقا لحاجتك. والخرق: الشق في حائط، أو ثوب ونحوه فهو مخروق. والخرق: المفازة البعيدة، اخترقته الريح فهو خرق أملس. والخريق: الريح الباردة الشديدة الهبوب، كأنها خرقت، أماتوا الفاعل منه والمفعول. وانخرقت الريح الخريق: منخريق: اشتد هبوبها، وتخللها المواضع. ويقال للرجل المتمزق الثياب: منخرق السربال. والاختراق كالاختلاق، وتخرق الكذب كتخلقه، وقوله [جل وعز] ، وخرقوا له بنين وبنات 1 بالتخفيف أحسن. والمخارق: الأكاذيب. وريح خرقاء: لا تدوم على جهتها، قال 2 : [صعل كأن جناحيه وجؤجؤه] ... بيت أطافت به خرقاء مهجوم ومفازة خرقاء: بعيدة، وناقة خرقاء: لا تتعاهد مواضع قوائمها، وبعير أخرق: [يقع منسمه بالأرض قبل خفه يعتريه ذلك من النجابة] 3 . والخرق: شبه النظر من الفزع، كما يخرق الخشف إذا صيد، وهو الدهش. وخرق الرجل، بقي متحيرا من هم أو شدة. وخرق في البيت خرقا، فلم يبرح. وخرق يخرق فهو أخرق، إذا حمق. وخرق بالشيء: جهله ولم يحسن عمله. والخرقاء من الغنم: المثقوبة الأذن. والمخراق: منديل أو نحوه، يلوي ويلعب به [وهو من لعب الصبيان] 4 يقال: لعب بالمخاريق. وأخرقه الخوف [فخرق، أي: فزع] 5 قال 6 : والطير في حافاتها خرقه أي: فزعة.'),
(1161, 'خلق', 'خلق', 'خلق', 'الخليقة: الخلق، والخليقة: الطبيعة. والجميع: الخلائق، والخلائق: نقر في الصفا. والخليقة: الخلق [والخالق: الصانع] 1 ، وخلقت الأديم: قدرته. وإن هذا لمخلقة للخير، أي: جدير به، وقد خلق لهذا الأمر فهو خليق له، أي: جدير به. وإنه لخليق لذاك، أي: شبيه، وما أخلقه، أي: ما أشبهه. وامرأة خليقة: ذات جسم وخلق، وقد يقال: رجل خليق، أي: تم خلقه، وخلقت المرأة خلاقة. أي: تم خلقها وحسن. والمختلق من كل شيء ما اعتدل وتر. والخلاق: النصيب من الحظ الصالح. وهذا رجل ليس له خلاق، أي: ليس له رغبة في الخير، ولا في الآخرة: ولا صلاح في الدين. والخلق: الكذب في قراءة من قرأ: إن هذا إلا خلق الأولين 2 وخلق الثوب يخلق خلوقة، أي: بلي، وأخلق إخلاقا. ويقال للسائل: أخلقت وجهك. واخلقني فلان ثوبه، أي: أعطاني خلقا من الثياب. وثوب أخلاق: ممزق من جوانبه. والأخلق: الأملس. وهضبة أو صخرة خلقاء، أي: مصمتة. وخليقاء الجبهة: مستواها، وهي الخلقاء أيضا، ويقال في الكلام: سحبوهم على خلقاوات جباههم. وخليقاء الغار الأعلى: باطنه، وخلقاء الغار أيضا. واخلولق السحاب، أي: استوى، كأنه ملس تمليسا، وقد خلق يخلق خلقا. والخلق: السحاب، قال 1 : بريق تلألأ في خلق ناصب والخلوق: من الطيب. وفعله: التخليق والتخلق. وامرأة خلقاء: رتقاء، لأنها مصمتة كالصفاة الخلقاء. يقال منه: خلق يخلق خلقا.'),
(1162, 'قلخ', 'قلخ', 'قلخ', 'القلخ والقليخ: شدة الهدير، ويقال للفحل عند الضراب: قلخ قلخ، مجزوم. ويقال للحمار المسن: قلخ وقلح بالخاء والحاء. قال: 2 أيحكم في أموالنا ودمائنا ... قدامة قلخ العير عير ابن جحجب ويروى بالحاء أيضا. والقلخ: ضرب من النبات.'),
(1163, 'لخق', 'لخق', 'لخق', 'اللخق، واللخقوق: الشق، وهو آثار جخ الماء حيث يجخ.'),
(1164, 'خقن', 'خقن', 'خقن', 'خاقان: [اسم لكل ملك من ملوك الترك] 3 . وخقنت الترك فلانا: رأسته،'),
(1165, 'خنق', 'خنق', 'خنق', 'خنقه فاختنق، واختنق، وانخنق، فأما الانخناق فهو انعصار الخناق في عنقه، والإختناق: فعله بنفسه. والخناق: الحبل الذي يخنق به، ويقال: رجل خنق، مخنوق، ورجل خانق، قال رؤبة: 1 وخانق ذي غصة جراض والخناق: نعت لمن يكون ذلك شأنه وفعله بالناس. وأخذ بمخنقة، أي: بموضع الخناق، ومنه اشتقت المخنقة. [أي] 2 : القلادة. وفرس مخنوق، من الخناقية، والخناقية: داء يأخذ الطير في رءوسها وحلوقها، ويعتري الفرس أيضا، فيقال: خنق الفرس فهو مخنوق، وأكثر ما يظهر في الحمام. والخانق: اسم موضع ذكره جرير 3 .'),
(1166, 'نقخ', 'نقخ', 'نقخ', 'النقخ: نقف الرأس عن الدماغ. والنقاخ: الماء البارد العذب الذي ينقخ الفؤاد لبرودته.'),
(1167, 'خفق', 'خفق', 'خفق', 'الخفق: ضربك الشيء بالدرة، أو بشيء عريض. والخفق: صوت النعل وما اشبهه من الأصوات. ورجل خفاق القدم: عريض باطنها، قال 1 : خدلج الساقين خفاق القدم والخفق: اضطراب الشيء العريض. يقال: راياتهم وأعلامهم تخفق وتختفق. وهن الخوافق والخافقات. والمخفق، والمخفقة، والخفقة، جزم،: هو الشيء الذي يضرب به نحو: درة، أو سير، أو سوط من خشب. والخفقان: اضطراب القلب، من خفة تأخذ القلب، تقول: رجل مخفوق. والخفقان: اضطراب الجناح. وأخفق الرجل، إذا ذهب راجي شيء فرجع خائبا. وأخفق القوم في زادهم، إذا نفد. وسراب خفوق خافق: كثير الأضطراب. والخفقة: المفازة ذات السراب، قال 2 : وخفقة ليس بها طوئي وناقة خيفق: سريعة جدا ومثله خنفقيق، وهو مشي في اضطراب، وخنفقيق وخيفقيق: حكاية جرى الخيل. وكذلك يقال: فرس خيفق، وظليم خيفق إذا كان سريعا.'),
(1168, 'قفخ', 'قفخ', 'قفخ', 'القفخ: كسر الرأس شدخا، وكذلك إذا كسرت العرمض 3 عن وجه الماء قلت: قفخته قفخا قال 4 : قفخا على الهام وبجا وخضا والقفيخة: طعام من تمر وإهالة يصب على جشيشة . والقفخة: من أسماء البقرة المستحرمة، يقال: أقفخت أرخهم، أي: استحرمت بقرتهم، وكذلك يقال للذئبة إذا ارادت السفاد.'),
(1169, 'بخق', 'بخق', 'بخق', 'البخق: أقبح ما يكون من العور، وأكثره، وأكثره غمصا. قال 2 : وما بعينيه عواوير البخق وتقول: [بخقت عينه أبخقها بخقا، إذا أعميتها، وهو بخيق العين] 3 .'),
(1170, 'كشخ', 'كشخ', 'كشخ', 'الكشخان: الديوث، وهو دخيل، لأنه ليس في كلام العرب رباعية مختلفة الحروف على فعلال ولا يكون إلا بكسر الصدر غير كشخان فإنه يفتح. [فإن أعرب قيل: كشخان على فعلال] 4 ، ويقال [للشاتم] 5 : لا تكشخ فلانا.'),
(1171, 'كرخ', 'كرخ', 'كرخ', 'الكراخة: الشقة من البواري- بغدادية. والكارخ: الذي يسوق الماء [إلى الأرض] 1 - سوادية. والكرخ: اسم سوق ببغداذ [نبطية] 2 [وأكيراخ: موضع آخر في السواد] 3'),
(1172, 'كفخ', 'كفخ', 'كفخ', 'الكفخة: الزبدة المجتمعة البيضاء الجيدة، قال 4 : لها كفخة بيضا تلوح كأنها ... تريكة قفر أهديت لأمير'),
(1173, 'كخم', 'كخم', 'كخم', 'الكيخم: يوصف به الملك والسلطان، قال: قبة إسلام وملكا كيخما'),
(1174, 'كمخ', 'كمخ', 'كمخ', 'أكمخ الرجل إكماخا، إذا جلس جلوس المتعظم في نفسه. حكاه لنا أبو الدقيش، فلبس كساء له، ثم جلس جلوس العروس على المنصة، وقال: هكذا يكمخ من البأو والعظمة. قال 1 : إذا أزدهاهم يوم هيجا أكمخوا ... بأوا ومدتهم جبال شمخ والكواميخ: دخيل، وهو [من الأدم] 2 ، الواحد: كامخ.'),
(1175, 'خدج', 'خدج', 'خدج', 'خدجت الناقة فهي خادج، وأخدجت فهي: مخدج، إذا ألقت ولدها وقد أستبان خلفه. والولد: خديج، ومخدج، ومخدوج، وأخدجت الزندة إذا لم تور. والخداج: الأسم. وكل ذات منسم أو ظلف تخدج. وذات الحافر تزلق.'),
(1176, 'خجر', 'خجر', 'خجر', 'رجل خجر، [والجميع: خجرون] 1 ، وهو الشديد الأكل الجبان الصداد عن الحرب، وامرأة خجرة.'),
(1177, 'خرج', 'خرج', 'خرج', 'الخروج: نقيض الدخول، خرج يخرج خروجا فهو خارج. واخترجت الرجل، واستخرجته سواء. وناقة مخترجة: خرجت على خلقة الجمل. والخروج: السحاب أول ما يبدأ. والخرج والخراج: ما يخرج من المال في السنة بقدر معلوم. والخراج: ورم وقرح يخرج من ذاته. قال الخليل: والخروج: الألف التي بعد الصلة في القافية، كقول لبيد: عفت الديار محلها فمقامها فالروي هو الميم، والهاء بعد الميم هي الصلة، لأنها اتصلت بالروى، والألف التي بعدها هي الخروج. والخراج والخريج: مخارجة لعبة لفتيان العرب. والخروج: خروج الأديب، والسائق ونحوهما، يخرج فيخرج فهو خريج. والخارجية: خيل [ليس] 1 لها عرق في الجودة فتخرج سوابق. والخارجي: الذي لم يكن له شرف في آبائه فيخرج ويشرف بنفسه. والسحاب يخرج السحاب. كما يخرج الليل ظلما. والأخرج: المكاء. والأخرج: لون سواده أكثر من بياضه، كلون الرماد. والأخرج من المعز والنعام والجبال [ما كان] على هذه الصفة. وقارة خرجاء: ذات لونين. والخرج، والخرجة جمعه: جوالق ذو أونين 2 وللعرب بئر احتفرت في أصل جيل أخرج يسمونها: أخرجة، وبئر احتفرت في أصل جبل أسود، يسمونها أسودة، اشتقوا لهما اسمين من نعت الجبلين. واخترجوه من السجن، أي: استخرجوه. وأرض مخرجة، وتخريجها أن يكون نبتها في مكان دون مكان، فترى بياض الأرض في خضرة النبات. جخر 3 : الجخراء: المنتنة الريح.'),
(1178, 'رخج', 'رخج', 'رخج', 'رخج: اسم كورة 4 معروف.'),
(1179, 'خجل', 'خجل', 'خجل', 'الخجل: أن يفعل الإنسان فعلا يتشور منه فيستحيي، وقد خجلته أنا تخجيلا، وأخجله فعله. وخجل البعير إذا سار في الطين فبقي كالمتحير. وخجل الحمض خجلا: طال والتف. والخجل: البطر، قال النبي صلى الله عليه وعلى آله وسلم: إنكن إذا جعتن دقعتن، وإذا شبعتن خجلتن 1 . أي: أشرتن وبطرتن.'),
(1180, 'خلج', 'خلج', 'خلج', 'خلج الرجل حاجبيه عن عينيه، واختلج حاجباه وعيناه، إذا تحركتا. قال: 2 يكلمني ويخلج حاجبيه ... لأحسب عنده علما قديما والخلج: جذبك شيئا أخرجته من شيء، ويقال للميت: اختلج من بينهم فذهب به. وإذا مد الطاعن رمحه عن جانب، قيل: خلجه. قال 3 : ينوء بصدره والرمح فيه ... ويخلجه خدب كالبعير ويقال: إن الخلج: الانتزاع، قال 4 : نطعنهم سلكى ومخلوجة ... كرك لامين على نابل والفحل إذا أخرج من الشوك قبل أن يقدر 1 فقد خلج، أي: يزع وأخرج، وإذا أخرج بعد الفدور قيل: عدل فانعدل. قال: 2 فحل هجان تولى غير مخلوج واختلج في صدره هم أو أمر، وتخالجتني الهموم، أي، تنازعتني. وتقول: بيننا وبينهم خلجة، وهي بقدر ما يمشي حتى يعيي مرة واحدة. وناقة خلوج إذا اختلجت عن ولدها فقل لبنها. وخلج البعير خلجا فهو أخلج: تقبض عصب عضده حتى يعالج بعد ذلك فيستطلق، ويعود، وإنما قيل له: خلج، لأن جذبه يخلج عضده. وسحابة خلوج: متفرقة بلغة هذيل. والخلوج: من السحاب: الكثير الماء، الشديد البرق. وجفنة خلوج: كثيرة الأخذ، قعيرة. وناقة خلوج: كثيرة اللبن. ويقال: هي التي تخلج السير من سرعتها. ويقال: التي تحن إلى ولدها. وخلجته الخوالج، أي: شغلته الشواغل. والخليج: النهر الذي يختلج في شق من النهر الأعظم. وجناحا النهر: خليجاه، قال أبو النجم: 3 [إلى فتى فاض أكف الفتيان] ... فيض الخليج مده خليجان والمجنون يتخلج في مشيته، أي: يتمايل، كالمجتذب يمنة ويسرة، قال: 4 أقبلت تنفض الخلاء بعينيها ... وتمشي تخلج المجنون والخليج: ما اعوج من البيت 1 ، وخلج، أي: فسد في نواحيه، وقوله: 2 فإن يكن هذا الزمان خلجا أي: نحى شيئا عن شيء.'),
(1181, 'جلخ', 'جلخ', 'جلخ', 'الجلخ في النكاح: الأخراج، والدعس: الإدخال.'),
(1182, 'لخج', 'لخج', 'لخج', 'اللخج: أسوأ الغمص. وعين لخجة: لزقة بالغمص.'),
(1183, 'نخج', 'نخج', 'نخج', 'نخج السيل ينخج نخجا في سند الوادي إذا صدمه. ونخج المرأة: نكحها. والنخاجة: الرشاحة.'),
(1184, 'نجخ', 'نجخ', 'نجخ', 'النجخ: نجخ السيل في سند الوادي وفي وسط البحر حين يجرف، قال 3 : ذو ناجخ يضرب صوحي مخرم وقال آخر: 4 مفعوعم ينجخ في أمواجه ونخيجه: صوته وصدمه. وامرأة نجاخة: وهي الرشاحة التي تمسح الابتلال.'),
(1185, 'خجف', 'خجف', 'خجف', 'الخجيف: لغة في الجخيف، وهو الخفة والطيش والكبر.'),
(1186, 'خفج', 'خفج', 'خفج', 'الخفج: الاعوجاج، والأخفج: الأعوج. والخفج: نبات ينبت في الربيع، الواحدة بالهاء، وهي بقلة شهباء لها ورق عراض. والخفج: ضرب من المباضعة.. وخفاجة: حي من قيس.'),
(1187, 'جخف', 'جخف', 'جخف', 'الجخفة المرأة: المرأة القضيفة القصيرة، وهن الجخاف، ورجل جخيف وقوم جخف. والجخيف: الكبر. والجخيف: الغطيط.'),
(1188, 'جفخ', 'جفخ', 'جفخ', 'الجفخ: العظمة والفخر والتطاول. قال 1 أتوعدني بجفخ بني فلان ... وقد افحمت شاعر كل حي والفعل منه: جفخ يجفخ.'),
(1189, 'خبج', 'خبج', 'خبج', 'الخباجاء: الفحل الكثير الضراب. والخبج: لون من الضرب بسيف أو عصا، ليس بشديد. ويقال: للضراط الشديد: خبج لصوته.'),
(1190, 'جخب', 'جخب', 'جخب', 'الجخابة: الأحمق. والجخابة: الثقيل الكثير اللحم.'),
(1191, 'جبخ', 'جبخ', 'جبخ', 'الجبخ: إجالتك الكعاب والقداح. وصوته: جبخة وجمخة.'),
(1192, 'خجم', 'خجم', 'خجم', 'الخجام: المرأة الواسعة الفرج. يقولون في السب: يا ابن الخجام.'),
(1193, 'مخج', 'مخج', 'مخج', 'مخجت الدلو أمخجها مخجا: خضضتها.'),
(1194, 'جمخ', 'جمخ', 'جمخ', 'الجمخ مثل الحبخ في الكعاب إذا اجيلت، قال 1 : [وإذا ما مررت في مسبطر] ... فاجمخ الخيل مثل جمخ الكعاب'),
(1195, 'شخص', 'شخص', 'شخص', 'الشخص: سواد الإنسان إذا رأيته من بعيد، وكل شيء رأيت جسمانه فقد رأيت شخصه، وجمعه: الشخوص والأشخاص. والشخوص: السير من بلد، إلى بلد وقد شخص يشخص شخوصا، وأشخصته أنا. وشخص الجرح: ورم. وشخص ببصره إلى السماء: ارتفع. وشخصت الكلمة في الفم. إذا لم يقدر على خفض صوته بها. والشخيص: العظيم الشخص، بين الشخاصة. وأشخصت هذا على هذا إذا أعليته عليه.'),
(1196, 'شخس', 'شخس', 'شخس', 'الشخس: فتح الحمار فمه عند التثاؤب والكرف، قال: 2 وشاخس فاه الدهر [حتى كأنه ... منمس ثيران الكريص الضوائن] أي: خالف بين أسنانه فشخص بعضها، ومال بعضها، وقال تراه في آثارهن خائفا ... مشاخسا طورا وطورا كارفا وتشاخس ما بين القوم، أي: اختلف.'),
(1197, 'شخز', 'شخز', 'شخز', 'الشخز: المشقة والعناء، قال: 2 إذا الأمور أولعت بالشخز والشخز: [العوج في الأمر] 3 .'),
(1198, 'خدش', 'خدش', 'خدش', 'الخدش مزق الجلد قل أو كثر. وخادشة السفا: أطرافه. وكان أهل الجاهلية يسمون كاهل البعير: مخدشا، لأنه يخدش الفم لقلة لحمه.'),
(1199, 'شدخ', 'شدخ', 'شدخ', 'الشدخ: كسر الشيء الأجوف كالرأس ونحوه، وكذلك كل شيء رخص كالعرفج وما أشبهه. والغرة الشادخة: التي تغشى الوجه من أصل الناصية إلى الأنف، فإذا غشي العينين فهو: الإغراب. قال مرار: 4 شادخ غرتها من نسوة ... هن يفضلن نساء الناس، غر والشداخة: الشديدة الشدخ. والشداخ: رجل من الليث يكنى أبا الملوح، واسمه: يعمر بن الملوح، وكان حكم بين خزاعة وقصي حين أقتتلوا في أمر البيت، وكثر القتل، فشدخ دماء خزاعة تحت قدمه، أي: أبطلها، وقضى بالبيت لقصي، وفيه يقول الشاعر: 1 إذا خطرت بنو الشداخ حولي ... ومد البحر من ليث بن بكر والمشدخ: بسر يغمز حتى ينشدخ، ثم ييبس في الشتاء.'),
(1200, 'شخت', 'شخت', 'شخت', 'الشخت، الدقيق من كل شيء، ويقال للدقيق العنق والقوائم: شخت، وقد شخت شخوتة، وجمع الشخت: الشخات. والشخيت مثل الشخت، وقد أشخته، أي: أدقه قال 2 : شخت الجزارة، مثل البيت سائره ... [من المسوح خدب شوقب خشب]'),
(1201, 'خشر', 'خشر', 'خشر', 'الخشارة من الشعير ما لم يكتنز، إنما هو كالسحالة والنخالة، [مما] لا لب فيه، قال 3 : أنتم خشار خشار ... وليس خز كخيش'),
(1202, 'خرش', 'خرش', 'خرش', 'الخرش بالأظفار في الجسد كله. وتخارش الكلاب والسنانير: مزق بعضها بعضا. والخراش: سمة مستطيلة كاللذعة الخفية، وثلاثة أخرشة، وبعير مخروش. والخرشاء: قشر البيضة الداخل، وجمعه الخراشي، وهو الغرقيء. والخرشاء جليدة تعلو اللبن. وبين القوم خراشة، أي: تبعة يطلب بها بعضهم بعضا. وخرشت البعير بالمحجنة، أي: نخسته. وقد خرشته واخترشته وخرشته.'),
(1203, 'شخر', 'شخر', 'شخر', 'شخر الحمار يشخر شخيرا، وهو صوته من الحلق، ويقال: هو من منخره، والنخير في الأنف. والشخير: ما تحات من الجبل 1 بالأقدام والقوائم، قال 2 : بنطفة بارق في رأس نيق ... منيف دونها منه شخير والشخير: رفع الصوت بالنفير ورجل شخير نفير. والشخير: هو الكثير الشخير.'),
(1204, 'شرخ', 'شرخ', 'شرخ', 'شرخا الرحل: آخرته وواسطته، ويقال: قادمته وآخرته، قال: كأنه بين شرخي رحل ساهمة ... [حرف إذا ما استرق الليل مأموم] وشرخا السهم: زنمتا فوقه، وهما اللذان الوتر بينهما. والشرخ: نتاج كل سنة من أولاد الإبل. قال ذو الرمة 1 : سبحلا أبا شرخين أحيا بناته ... مقاليتها فهي اللباب الحبائس والشارخ: الحدث من الناس، قال الأعشى: 2 [وما إن أرى الدهر في صرفه] ... يغادر من شارخ أو يفن وشرخ الشباب: أوله. شرخ ناب البعير، إذا شق البضعة وخرج. شرخ الناب يشرخ شروخا، قال 3 : على بازل لم يخنها الضراب ... وقد شرخ الناب منها شروخا'),
(1205, 'خشل', 'خشل', 'خشل', 'الخشل: من المقل كالحشف من التمر. والخشل: رءوس الأسورة والخلاخيل، ولا أعرف له جمعا ولا واحدا. ويقال: الخشل: رأس الخلخال.'),
(1206, 'شخل', 'شخل', 'شخل', 'الشخل: الغلام الحدث يصادق رجلا. والشخل: [بزل] 4 الشراب بالمشخلة، وهي: المصفاة.'),
(1207, 'شلخ', 'شلخ', 'شلخ', 'شالخ: جد إبراهيم ع.'),
(1208, 'خشن', 'خشن', 'خشن', 'خشن الشيء يخشن خشونة، فهو خشن أخشن. والمخاشنة: في الكلام والعمل. وأخشوشن الرجل إذا لبس خشنا، أو قال قولا فيه خشونة. وكتيبة خشناء: كثيرة السلاح. والخشناء: بقلة خضراء ورقها قصير مثل ورق الرمرام. غير أنها أشد اجتماعا، ولها حب يكون في الروض والقيعان. والخشناء: الأرض الغليظة. وأخشن: جبل. وخشينة: حي من العرب، والنسبة إليهم: خشني. ومخاشن: أسم رجل.'),
(1209, 'خنش', 'خنش', 'خنش', 'امرأة مخنشة: فيها بقية شباب، ونساء مخنشات، وتخنشها: بعض رقة بقية شبابها. والتخنش: التحرك.'),
(1210, 'نخش', 'نخش', 'نخش', 'نخش الرجل فهو منخوش، أي: مهزول [وامرأة منخوشة: لا لحم عليها] 1 .'),
(1211, 'خشف', 'خشف', 'خشف', 'الخشف: ولد الظبي. والأخشف: الذي عمه الجرب، فهو يمشي مشي الشيخ، وقد خشف يخشف خشفا، أي: يبس جلده عليه من الجرب. والخشفان: الجولان بالليل والسرعة فيه، وبه سمي الخشاف لخشفانه، وهو أحسن من الخفاش، ومن قال: خفاش فاشتقاقه من صغر عينيه. ودليل مخشف: يخشف بالقوم، أي: يسير أمامهم، قال 2 : تنح سعار الحرب لا تصطلي بها ... فإن لها من القبيلين مخشفا والمخشف: اليخدان. والخشيف: الثلج الخشن، وكذلك الجمد الرخو، وليس له فعل، يقال: أصبح الماء خشيفا. والخشف: الذباب الأخضر، وجمعه: أخشاف. وخشف يخشف [خشوفا] إذا ذهب في الأرض. ويقال: سمعت خشفته، أي: حسا منه حركة، أو صوتا خفيا والخشوف: الذي لا يهاب الليل.'),
(1212, 'خفش', 'خفش', 'خفش', 'الخفش: فساد في الجفون تضيق له العيون من غير وجع ولا قرح. رجل أخفش.'),
(1213, 'فشخ', 'فشخ', 'فشخ', 'الفشخ: الظلم والصفع في لعب الصبيان والكذب فيه.'),
(1214, 'شخف', 'شخف', 'شخف', 'الشخاف: اللبن بالحميرية.'),
(1215, 'خشب', 'خشب', 'خشب', '[الخشب معروف] 1 والخشابة: قوم معهم خشب، وحرفتهم: الخشابة. والخشب- جزم-: الشحذ، وسيف خشيب مخشوب، أي: شحيد. وجبهة خشباء: كريهة يابسة صلبة، بادية العظام والعروق، غير مستوية ورجل خشب: عاري العظام والعصب، له شدة وصلابة، وكذلك اليد ونحوها. وأخشوشب الرجل. وكل شيء خشن من أرض وقت ونحوهما فهو أخشب. والأخشب مكان من القف غليظ. وقد يكون سفح الجبل أخشب. وأخاشب الصمان: جبال اجتمعن بها في محلة بني تميم. وأخشبا مكة: جبلاها. والخشب: خلطك الشيء بالشيء غير متأنق فيه. وطعام مخشوب 1 .'),
(1216, 'خبش', 'خبش', 'خبش', 'خباشات العيش: ما يتناول من طعام ونحوه، تقول: يخبش من ههنا وههنا'),
(1217, 'شخب', 'شخب', 'شخب', 'الشخب: ما امتد من اللبن متصلا بين الإناء والطبي. وشخبت اللين فانشخب، وقد شخبت أوداج المقتول دما.'),
(1218, 'خشم', 'خشم', 'خشم', 'الخشم: كسر الخيشوم، والخشام: داء يأخذ فيه، وسدة، وصاحبه: مخشوم. وخشم هو فهو أخشم [وفلان ظاهر الخيشوم، أي: واسع الأنف] 2 ، قال 3 : أخشم بادي النعو والخيشوم والخيشوم: سلائل سود، ونغف في العظم. والسليلة: هنة رقيقة، كاللحم لينة [وفي الأنف ثلاثة أعظم، فإذا انكسر منها عظم تخشم الخيشوم فصار مخشوما] 1 . والأخشم: الذي لا يجد ريح طيب، ولا نتن. والتخشم: من السكر، وذلك أن ريح الشراب تسور في خيشوم الشارب ثم تخالط الدماغ، فيذهب العقل فيقال: قد تخشم، وخشمه الشراب. وخياشيم الجبال: أنوفها.'),
(1219, 'خمش', 'خمش', 'خمش', 'الخامشة، وجمعها: الخوامش، صغار مسايل الماء والدوافع. والخموش: البعوض بلغة هذيل، الواحدة بالهاء، قال: 2 كأن وغى الخموش بجانبيه ... مآتم يلتدمن على قتيل والخمش: في الوجه، وقد يستعمل في الجسد. والخماشة 3 : الجناية والجراحة والكدمة.'),
(1220, 'شخم', 'شخم', 'شخم', 'شخم اللحم شخوما: [تغيرت رائحته] . وطعام شاخم: فاسد قد كرج وتغير.'),
(1221, 'شمخ', 'شمخ', 'شمخ', 'جبل شامخ: طويل في السماء، ويجمع: شوامخ، وقد شمخ شموخا. وشمخ فلان بأنفه. وشمخ أنفه، إذا رفعه عزا.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1222, 'خضد', 'خضد', 'خضد', 'الخضد: نزع الشوك عن الشجر. وقال الله جل وعز في سدر مخضود 1 ، أي: نزع شوكة. وخضدت العود فانخضد، أي: انكسر من غير بينونة. والبعير يخضد عنق البعير، إذا قاتله. والخضاد: من شجر الجنبة، وهو مثل النصي، ولورقه حروف كحروف الحلفاء يجز باليد كما تجز الحلفاء. وخضد يخضد خضدا إذا أكل شيئا رطبا، نحو القثاء وغيرها.'),
(1223, 'دخض', 'دخض', 'دخض', 'الدخض: سلاح السباع، وأكثر ما يوصف به [سلاح] الأسد. دخض يدخض دخضا، فهو داخض.'),
(1224, 'خضر', 'خضر', 'خضر', 'الخضر: نبي معمر، محجوب عن الأبصار [وهو نبي من بني إسرائيل، وهو صاحب موسى الذي التقى معه بمجمع البحرين] 2 . والخضر في القرآن: 3 الزرع الأخضر، وفي الكلام: كل نبات من الخضر. والاخضرار مصدر من قولك: اخضر. والخضر والمخضور 1 : للرخص من الشجر. والخضاري: طائر يسمى الأخيل، يتشاءم به إذا سقط على ظهر البعير، وهو أخضر في حنكه حمرة، وهو أعظم من القطا. وقول النبي صلى الله عليه وعلى آله وسلم: إياكم وخضراء الدمن 2 . يعني: المرأة الحسناء في منبت السوء، يشبهها بالشجرة الناضرة في دمنة البعر. والمخاضرة: بيع الثمار قبل بدو صلاحها، وهي خضر بعد. وخضر الزرع خضرا [نعم] ، وأخضره الري. والخضير: الزرع الأخضر، وقد اختضر فلان إذا مات شابا، وجعل شاب يقول لشيخ: أجززت، فقال: وتختضرون، أي: تموتون شبابا. وذهب دمه خضرا مضرا، وخضرا مضرا، إذا ذهب هدرا باطلا ولم يطلب. ويقال: خذ الشيء خضرا مضرا، أي: غضا حسنا.'),
(1225, 'خرض', 'خرض', 'خرض', 'الخريضة: الجارية الحديثة السن، التارة البيضاء. والجميع: الخرائض.'),
(1226, 'رضخ', 'رضخ', 'رضخ', 'الرضخ: كسر رأس الحية، والنوى وما يشبه ذلك. وترضخت الخبز، أي: كسرته وتناولته. ورضخت له من مالي رضخة [وهو القليل] 3 والتراضخ: ترامي القوم بينهم بالنشاب. والحاء في كل هذا جائز إلا في الأكل والعطاء. تقول: كنا نترضخ، أي: نأكل، وراضخ فلان شيئا، أي: أعطاه وهو كاره. وراضخنا منه شيئا، أي: أصبنا.'),
(1227, 'خضل', 'خضل', 'خضل', 'الخضل: كل شيء ند يترشش من نداه. وأخضل فلان لحيته بالدمع. واخضلت لحيته. واخضل الليل: وقع نداه. ويسمى اللؤلؤ: خضلا، ولم أسمعهم يقولون: خضل الشيء. ودرة خضلة: أي: صافية نقية. وأخضلتنا السماء: بلتنا بلا شديدا. ونبات خضل بالندى.'),
(1228, 'خضن', 'خضن', 'خضن', 'المخاضنة: الترامي بقول فحش أو غزل، قال الطرماح: 1 [وأدت إلى القول عنهن زولة] ... تخاضن أو ترنو لقول المخاضن'),
(1229, 'نضخ', 'نضخ', 'نضخ', 'النضخ: [من فور الماء من العين والجيشان] 2 ، قال الله عز وجل: يهما عينان نضاختان 3 . والنضخ كاللطخ: مما يبقى له أثر. نفخ ثوبه بالطيب.'),
(1230, 'خضف', 'خضف', 'خضف', 'البطيخ، أول ما يخرج يكون قعسرا، ثم خضفا أكبر منه. ثم فجا، والحدج يجمعها.. وهو طبيخ لغة فيه.. والخضف: الضرط..'),
(1231, 'خفض', 'خفض', 'خفض', 'الخفض: نقيض الرفع. وعيش خفض: [ذو دعة وخصب] 1 ، وخفضت الشيء فانخفض واختفض. وخفضت الجارية وختن الغلام. والتخفيض: مدك رأس البعير إلى الأرض [لتركبه] ، قال: 3 يكاد يستعصي على مخفضه'),
(1232, 'فضخ', 'فضخ', 'فضخ', 'الفضخ: كسر الشيء الأجوف، كالرأس والبطيخ. والفضيخ: شراب يتخذ من البسر المفضوخ، وهو المشدوخ.'),
(1233, 'خضب', 'خضب', 'خضب', 'خضب الرجل شيبه، والخضاب: الأسم، وكل شيء غير لونه بحمرة كالدم ونحوه فهو مخضوب. والخاضب: من النعام، وهو نعت للذكر، إذا اغتلم في الربيع إحمرت ساقاه. والمخضب: شبه [إجانة] 1 يغسل فيها الثياب. واختضب الرجل، [واختضبت المرأة] 2 ، من غير ذكر الشعر.'),
(1234, 'خضم', 'خضم', 'خضم', 'الخضم: الأكل والمضغ بأقصى الأضراس. والخضم: شدة الأكل في رغد. والخضم: نحو أكل القثاء ونحوه، وهو الأكل بجميع الفم. وقولهم: قد يبلغ الخضم بالقضم، أي: قد يبلغ المبلغ الكبير بالشيء الصغير. وخضمت أخضم خضما، والخضمة 3 : ما خضم. والمخضم: الشديد الخضم. وخضمة الذراع: [مستغلظها] 4 . والمخضم: مصدر من خضمت. والخضم: نعت للشريف المعطاء، أي: السيد الضخم، وجمعه: الخضمون: قال رؤبة 5 : كم لك يا سفاح من خال وعم ... من هاشم في السودد الضخم الخضم والخضم: المسن، والخضم: الفرس الجواد الضخم. قال 1 : خضمات الأباهر والعروق'),
(1235, 'ضخم', 'ضخم', 'ضخم', '[الضخم: العظيم من كل شيء] 2 ، وضخم الشيء ضخامة فهو ضخم، وجمعه: ضخام، والإناث: الضخمات، لأنه من الصفات، وإذا كان اسما فهو: فعلات، مثقل، مثل شربة وشربات وقرية وقريات.. وبنات الواو من الأسماء، نحو: جوزة وجوزات، خفيفة، لأنها إن ثقلت صارت الواو ألفا، فتركت على حالها مخافة الالتباس.'),
(1236, 'مخض', 'مخض', 'مخض', 'المخيض: ما قد أخذ زبده، والمخض: تحريكك المخض، وهو الذي فيه اللبن. ويستعمل المخض في أشياء كثيرة [نحو] البعير يمخض شقشقته. قال رؤبة: يجمعن زأرا وهديرا مخضا والسحاب يتمخض بمائه. والدهر يتمخض بفتنه. والتمخض: التحرك. والإمخاض: ما اجتمع من الألبان حتى صار وقر بعير، ويجمع على الأماخيض، وبهذا المعنى [يقال] إحلاب من لبن، وأحاليب. وكل حامل ضربها الطلق فهي: ماخض. والمخاض: أسم يجمع النوق الحوامل، وهن شول ما دام الفحل فيها، فإذا نتج بعضها وانتظر بعضها فهن عشار، فإذا نتجت فهن لقاح حتى قعدن شولا. وابن المخاض: الذي حملت أمه. والمستمخض من اللبن: البطيء الروب، وإذا راب ثم مخضته فعاد مخضا فهو المستمخض، وذلك أطيب الألبان. ويقال: إذا أرتكض الولد في بطن [الناقة] قيل لها: ملمع، ثم يقال لها: خلفة، والاثنتان: خلفتان، والثلاث: خلفات، فإذا جمعت الخلفات قلت لهن: مخاض، فكن مخاضا إلى مطلع سهيل.. فهن متليات.'),
(1237, 'ضمخ', 'ضمخ', 'ضمخ', 'الضمخ: لطخ الجسد بالطيب حتى كأنه يقطر. قال 1 : تضمخن بالجادي حتى كأنما الأنوف ... إذا استعرضتهن رواعف ضمختها، وضمختها، فاضطمخت وتضمخت.'),
(1238, 'مضخ', 'مضخ', 'مضخ', 'المضخ: لغة شنعاء في الضمخ.'),
(1239, 'صخد', 'صخد', 'صخد', 'الصخد: صوت الهام والصرد. صخد يصخد صخدا وصخيدا. قال 2 : وصاح من الأفراط هام صواخد وهي: الآكام، واحدها: فرط [وقيل: الأفراط تباشير الصبح] . يعني: من أوائل الصبح. والصيخد: عين الشمس، لشدة حرها. والحرباء يصطخد إذا تصلى بحر الشمس واستقبلها. والصيخود: الصخرة الملساء الصلبة، لا تحرك من مكانها، ولا يعمل فيها الحديد، قال 1 : حمراء مثل الصخرة الصيخود وهي: [الصلود] 2 . وأصخدنا، أي: أظهرنا. وحر صاخد: شديد.'),
(1240, 'دخص', 'دخص', 'دخص', 'الدخوص: نعت للجارية التارة، وبالحاء [المهملة] والسين أيضا، لغة.'),
(1241, 'خصر', 'خصر', 'خصر', 'الخصر: وسط الإنسان. والخاصرتان: ما بين الحرقفة والقصيري. وخصر القدم: أخمصها. وقدم مخصرة ومخصورة، ويد مخصرة، إذا كان في رسغها تخصير. كأنه مربوط، وفيه منز 3 مستدير. ورجل مخصر: مخصور البطن أو القدم. وخصر الرمل: طريق أعلاه وأسفله في الرمل خاصة. والخصر من بيوت الأعراب: موضعها. والإختصار في الكلام: ترك الفضول، واستيجاز ما يأتي على المعنى. و [كذلك الإختصار] في الطريق. وفي الجز: ألا تستأصله. والمخاصرة في البضع: [أن يضرب بيده إلى خصرها] 1 والخصر: البرد الذي يجده الإنسان في أطرافه، قال 2 : رأت رجلا أما إذا الشمس عارضت ... فيضحي وأدما بالعشي فيخصر وثغر خصر: بارد المقبل. وفلان مخاصر فلان، إذا أخذ بيده في المشي وهو بجنبه، قال: 3 ثم خاصرتها إلى القبة الحمراء ... تمشي في مرمر مسنون والمخصرة: عصا أو نحوها بيد صاحبها. ونهي عن التخصر في الصلاة، وهو وضع اليدين على الخاصرة.'),
(1242, 'خرص', 'خرص', 'خرص', 'الخرص: الكذب، والخراصون في قوله جل وعز: قتل الخراصون 4 : الكذابون، ويخرصون: يكذبون. والخرص: الحزر في العدد والكيل، والخارص: يخرص ما على النخلة، ثم يقسم الخراج على ذلك. والخريص: شبه حوض واسع ينبثق فيه الماء من نهر، ثم يعود إلى النهر، والخريص ممتلىء. قال عدي: 1 والمشرف المشمول يسقي به ... أخضر مطموثا كماء الخريص المطموث: الذي شرب به مرة بعد مرة. والخرص: القرط بحبة واحدة في حلقة واحدة، والجميع: خرصة. والخرص من الرماح: رمح قصير يتخذ من خشب منحوت، وقد يقال لدقاق القناة وقصارها: خرصان، والواحد: خرص، قال 2 : وفي خيزومه خرص طرير أي: دقيق لطيف. والخرص: العود 3 . والخرص: الذي به جوع وبرد'),
(1243, 'صخر', 'صخر', 'صخر', 'الصخر: عظام الحجارة وصلابها. والصاخر: إناء من خزف. والصخير: نبات.'),
(1244, 'رخص', 'رخص', 'رخص', 'الرخص: الناعم من كل شيء. ومن المرأة بشرتها ورقتها، ورخاصة أناملها: لينها. وقد رخص رخاصة ورخوصة أيضا. وثوب رخيص: ناعم. والرخص في الأشياء: بيع رخيص. رخص رخصا. وارتخصته: اشتريته رخيصا، وأرخصته: جعلته رخيصا. والموت الرخيص: الذريع. والرخصة: ترخيص الله للعبد في أشياء خففها عليه. ورخصت له [في كذا] 1 : أذنت له بعد النهي عنه.'),
(1245, 'صرخ', 'صرخ', 'صرخ', 'الصرخة: صيحة شديدة عند فزعة أو مصيبة. والصريخ: [الذي] 2 يأتي قوما يستغيث بهم عند غارة، أو ينعي لهم ميتا. والمستصرخ: المستغيث. والمصرخ: المغيث. والاصطراخ 3 : التصارخ 4 . والصريخ: المفزع والمعين، أصرختهم: أعنتهم.'),
(1246, 'خصل', 'خصل', 'خصل', 'الخصلة: لفيفة من شعر، وجمعها: خصل: خصل، ومنه قول لبيد 5 : [وتأييت عليه ثانيا] ... يتقيني بتليل ذي خصل والخصل: الرمي في النضال، إذا وقع السهم بلزق القرطاس فهي: خصلة، والمقرطس: الذي يصيب القرطاس. فإذا تناضلوا على سبق حسبوا خصلتين بمقرطسة، ويقال: رمى فأخصل، ومن قال: الخصل: الإصابة فقد أخطأ. والخصال: حالات الأمور، الواحدة: خصلة، تقول: في فلان خصلة حسنة. وخصلة قبيحة وخصلات كريمات. والخصيلة: كل لحمة على حيزها في الفخذين والعضدين، ويقال: في الساقين والساعدين أيضا، قال 1 ، عاري القرا مضطرب الخصائل أخبر أنه واسع الجلد، ويكون أقوى على الجري.'),
(1247, 'خلص', 'خلص', 'خلص', 'خلص الشيء خلوصا، إذا كان قد نشب، ثم نجا وسلم. وخلصت إليه: وصلت إليه. والخلاص يكون مصدرا كالخلوص، للناجي، ويكون مصدرا للشيء الخالص، وتقول: هو خالصتي وخلصاني، وهؤلاء خلصاني وخلصائي، أي: أخلائي، قال: منا النبي الذي قد عاش مؤتمنا ... ومات صافية لله خلصانا وهذا الشيء خالصة لك، أي: خالص لك خاصة، وفلان لي صافية وخالصة. والإخلاص: التوحيد لله خالصا، ولذلك قبل السورة قل هو الله أحد: سورة الإخلاص. وأخلصت لله ديني: [أمحضته] ، وخلص له ديني. إنه من عبادنا* المخلصين* 1 ، المخلصون: المختارون. والمخلصون: الموحدون. وخلصته: نحيته من كل شيء ينشب تخليصا، وتخلصته كما يتخلص الغزل إذا التبس. والخلاص: زبد اللبن يستخلص منه، أي: يستخرج. وبعير مخلص: سمين المخ، قال: زجرت فيها عيهلا رسوما ... مخلصة الأنقاء أو زعوما والخلاص: رب يتخذ من التمر والسمن يطبخ فإذا أرادوا أن يخلصوه ألقوا فيه نحو التمر والسويق ليخلص السمن من اللبن، فالذي يلقى فيه هو: الخلاص. والخلاصة: ما بقي من الخلاص وغيره. والخلصاء: ماء بالبادية. وذو الخلصة: موضع بالبادية كان به صنم.'),
(1248, 'لخص', 'لخص', 'لخص', 'اللخص: أن يكون الجفن الأعلى لحيما والنعت: اللخص. وضرع لخص: كثير اللحم. ولخصت البعير، إذا شققت جلدة عينه فنظرت لترى فيه شحما أم لا، ولا يكون إلا في المنحور. ولخصت الشيء إذا استقصيت في بيانه، يقال: لخص لي خبرك، أي: بينه شيئا بعد شيء. صلخ 1 : الأصلخ: الأصم.'),
(1249, 'خصن', 'خصن', 'خصن', 'الخصين: فأس ذات خلف واحد، تذكر وتؤنث، وهو الناجخ أيضا. وثلاث أخصن، قال: 2 يقطع الغاف بالخصين ويشلي ... قد علمنا بمن يدير الربابا'),
(1250, 'خنص', 'خنص', 'خنص', 'الخنوص: ولد الخنزير، وجمعه: خنانيص.'),
(1251, 'خصف', 'خصف', 'خصف', 'الخصف نياب غلاظ جدا، ويقال إن تبعا كسا البيت المسوح، فانتفض البيت ومزقها، ثم كساه الخصف فلم يقبلها، ثم كساه الأنطاع فقبلها، وهو أول من كسا البيت. والخصف لغة في الخزف. والخصفة: القطعة مما يخصف به النعل، والمخصف: مثقبه. والخصفة، وجمعها: الخصاف: جلة التمر. وكتيبة خصيف، أي: خصفت من ورائها بخيل، أي: أردفت. والأخصف: لون كلون الرماد، فيه سواد وبياض، وهو الخصيف أيضا. والخصيف من الجبال: ما كان أبرق، سوداء، وقوة بيضاء، وهو الأخصف أيضا، قال 1 : من الصباح عن بريم أخصفا والأخصف: الظليم لسواد فيه وبياض. والأنثى: خصفاء. والإخصاف: شدة العدو، وبالحاء أيضا. والاختصاف، أن يأخذ العريان ورقا عراضا، فيخصف بعضها على بعض، ويستتر بها. خصف على نفسه بكذا، واختصف بكذا.'),
(1252, 'خصب', 'خصب', 'خصب', 'الخصب: نقيض الجدب، وهو كثرة العشب، ورفاهة العيش، والإخصاب والاختصاب منه. ويقال: أخصبت الأرض إخصابا. وفلان خصيب الرحل: كثير خير المنزل. والخصبة: الطلعة في لغة، وهي النخلة الكثيرة الحمل في لغة، وجمعها: خصاب. والخصب: حية بيضاء في الجبل، والجميع: الأخصاب. وأخصبت العضاه، أي: جرى الماء في عودها حتى يتصل بالعرق، وهو الإختصاب.'),
(1253, 'خبص', 'خبص', 'خبص', 'الخبص: فعلك الخبيص. والمخبصة: ما يقلب به الخبيص في الطنجير. خبص. يخبص خبصا، وخبص يخبص. تخبيصا، فهو خبيص مخبوص مخبص. ورجل خبص إذا كان يحب الخبيص.'),
(1254, 'صخب', 'صخب', 'صخب', 'الصخب معروف، وقد صخب يصخب صخبا. وعين صخبة، إذا اصطفقت عند الجيشان. وماء صخب الآذي [إذا تلاطمت أمواجه] 1 ، قال مغعوعم صخب الآذي منبعق ... كأن فيه أكف القوم تصطفق'),
(1255, 'بخص', 'بخص', 'بخص', 'البخص: ما ولي الأرض من تحت أصابع الرجلين، وتحت مناسم البعير والنعام. وربما أصاب الناقة داء في بخصها فهي مبخوصة تظلع منه. وبخص اليد: لحم أصول الأصابع مما يلي الراحة. [والبخص في العين] 3 : لحم عند الجفن الأسفل، كاللخص عند الجفن الأعلى. والبخص: لحم الذراع أيضا، وبالسين لغة. قال الكميت: جمعت نزارا وهي شتى فأصبحت ... كما جمعت كف إليها الأباخسا'),
(1256, 'خصم', 'خصم', 'خصم', 'الخصم: واحد وجميع، قال الله عز وجل: وهل أتاك نبأ الخصم إذ تسوروا المحراب فجعله جمعا لأنه سمي بالمصدر. وخصيمك: الذي يخاصمك، وجمعه: خصماء. والخصومة: الأسم من التخاصم والإختصام. يقال: أختصم القوم وتخاصموا، وخاصم فلان فلانا، مخاصمة وخصاما. والخصم: طرف الراوية الذي بحيال العزلاء في مؤخرها. والطرف الأعلى هو العصم، وهي: الأخصام وزوايا الوسائد والجواليق والفرش كلها أخصام، واحدها: خصم.'),
(1257, 'خمص', 'خمص', 'خمص', 'الخمص: خماصة البطن، وهو دقة خلقته. والخمص: الخمص والمخمصة. أيضا: خلاء البطن من الطعام. وامرأة خميصة البطن خمصانة. وهن خمصانات، وفلان خميص البطن من أموال الناس، أي: عفيف عنها، وهم خماص البطون. والطير تغدو خماصا وتروح بطانا. والخميصة: كساء أسود معلم من المرعزي والصوف ونحوها. والأخمص: خصر القدم. والأخمص: باطن القدم. قال 1 : كأن أخمصهما بالشوك منتعل والجميع: الأخامص. والخمصة: بطن من الأرض صغير، لين الموطيء.'),
(1258, 'صمخ', 'صمخ', 'صمخ', 'الصماخ: خرق الأذن [إلى الدماغ] 1 ، والسماخ: لغة فيه. والصاد تميمية، وصمخني الصوت. وصمخت فلانا: عقرت صماخ أذنه بعود أو نحوه. ويقال للعطشان: إنه لصادي الصماخ.'),
(1259, 'مصخ', 'مصخ', 'مصخ', 'المصخ: أجتذابك الشيء عن الشيء. وضرب من الثمام من أصغره يسمى الغرز. الواحدة: غرزة ينبت على شطوط الأنهار، لا ورق له، إنما هو أنابيب مركب بعضها في بعض، كل أنبوبة منها أمصوخة، إذا اجتذبتها خرجت من جوف أخرى خروج العفاص من المكحلة. وإجتذابه: المصخ والامتصاخ. والمصوخة من الغنم: ما كان ضرعها مسترخي الأصل، كأنما امتصخت ضرتها وامصخت عن البطن، أي: انفصلت.'),
(1260, 'سخط', 'سخط', 'سخط', 'السخط والسخط: نقيض الرضا، والفعل: سخط يسخط. وتسخطه: لم يرض به. وأسخطه غيره إسخاطا، والمسخط: مصدر من سخط، تقول: هذا مسخطة، أي: من تعرض له سخط عليه. والسخط والسخط مثل: السقم والسقم، والعدم والعدم.'),
(1261, 'سخد', 'سخد', 'سخد', 'السخد: ما فيه الولد في المشيمة من المرأة، وهو ماء السلى، والسلى: لباس الولد، وإذا أسخدت الرحم سكن الولد، وهي الحولاء من الإبل وغيرها، ومنه ماء غليظ. وأصبح فلان مسخدا، أي: ثقيلا [من مرض أو غيره] كأنهم يريدون من معنى السخد.'),
(1262, 'دخس', 'دخس', 'دخس', 'الدخس: الإنسان التار المكتنز. غير جد جسيم. والدخس: الفتي من الدببة. والدخس: الرجل الكثير اللحم، والجميع: الأدخاس. والدخس: اندساس الشيء تحت التراب [كما تدخس الأثفية في الرماد] ، ويقال للأثافي: دواخس لاندساسها في الرماد، قال العجاج 1 : دواخسا في الأرض، إلا شعفا أي: إلا رءوسها. قال 2 : فأطرفت إلا ثلاثا دخسا والدخس: دابة تندخس في الرمل. والدخس: داء يأخذ في قوائم الدابة.. فرس دخس. والدخس: امتلاء العظم من السمن. جمل مدخس. والجميع: مدخسات. وامرأة مدخسة، أي سمنت حتى صارت دخسا. والدخيس: لحم باطن الكف. والدخيس: عظم الحوشب. والدخيس من الناس: العدد المجتمع. قال العجاج: 1 جم الدخيس بالثغور أحوسا ودخيس اللحم: مكتنزه.'),
(1263, 'سخت', 'سخت', 'سخت', '[اسخات الورم إذا سكن. والسختيت: السويق غير الملتوت] 3 . والسنختيت: كلمة يقال: هي فارسية اشتقها رؤبة من (سخت) . فقال: 4 هل ينجيني حلف سختيت ... أو فضة أو ذهب كبريت'),
(1264, 'خسر', 'خسر', 'خسر', 'الخسر: النقصان، والخسران كذلك، والفعل: خسر يخسر خسرانا. والخاسر: الذي وضع في تجارته، ومصدره: الخسارة والخسر. كلته ووزنته فأخسرته، أي: نقصته. وقوله [جل وعز] : وكان عاقبة أمرها خسرا 1 ، أي: نقصا. وصفقة خاسرة، أي: غير مربحة'),
(1265, 'خرس', 'خرس', 'خرس', 'خرس خرسا. والخرس: ذهاب الكلام خلقة، أو عيا. وكتيبة خرساء: لا يسمع لها صوت ولا جلبة، وفيهم نجدة. وصوة خرساء، وعلم أخرس، أي: لا يسمع فيه صوت صدى. يعني الأعلام التي يهتدي بها. والخرس: طعام الولادة، والعقيقة، وخرستها: أطعمتها عند ولادها. وناقة خرساء: لا يسمع لها صوت. والخرسي: منسوب إلى خراسان، ومثله: الخراسي والخراساني، ويجمع الخرسي على الخرسين، بتخفيف ياء النسبة كالأشعرين. قال 2 : لا تكرين بعدها خرسيا والخرساء: الداهية.'),
(1266, 'سخر', 'سخر', 'سخر', 'سخر منه وبه، أي: استهزأ. والسخرية: مصدر في المعنيين جميعا، وهو السخري أيضا ويكون نعتا كقولك: هم لك سخري وسخرية، مذكر ومؤنث [من ذكر قال: سخري، ومن أنث قال: سخرية] 1 . والسخرة: الضحكة، وأما السخرة فما تسخرت من خادم ودابة بلا أجر ولا ثمن. تقول: هم لك سخرة وسخريا. قال الله جل وعز: فاتخذتموهم سخريا حتى أنسوكم ذكري 2 ، أي: سخرية، من تسخر الخول وما سواه، وسخريا في الاستهزاء. سخرت السفن: أطاعت وطاب لها السير. قال 3 : سواخر في سواء اليم تحتفز وقد سخرها الله لخلقه تسخيرا، وتسخرت دابة لفلان: ركبتها بغير أجر.'),
(1267, 'رسخ', 'رسخ', 'رسخ', 'رسخ الشيء رسوخا، إذا ثبت في موضعه. وأرسخته إرساخا، كالحبر يرسخ في الصحيفة، والعلم يرسخ في القلب، وهو راسخ في العلم: داخل فيه مدخلا ثابتا، والراسخون في العلم 4 * يقال: هم المدارسون. والدمنة الراسخة: الثابتة. قال لبيد 5 : راسخ الغدير رسوخا: نش ماؤه فذهب.'),
(1268, 'خلس', 'خلس', 'خلس', 'الخلس والاختلاس: أخذ الشيء مكابرة، تقول: اختلسته اختلاسا واجتذابا. والخلس والاختلاس: النهزة، والاختلاس أوحاهما وأخصهما. والخلسة: النهزة. والقرنان يتخالسان، أيهما يقدر على صاحبه [ويناهز كل واحد منهما قتل صاحبه] 2 . والخلس في القتال والصراع. والرجل المخالس: الشجاع والحذر. والخليس: النبات الهائج، بعضه أصفر، وبعضه أخضر. وأخلست لحيته، أي: اختلط فيها البياض بالسواد نصفين، وأخلس الرجل كذلك. والخلاسي: الولد من أبيض وسوداء، أو أسود وبيضاء. والخلاسي من الديكة: بين الدجاج الهندية والفارسية.'),
(1269, 'سخل', 'سخل', 'سخل', 'السخل: ولد الشاة، ذكرا كان أو أنثى، والسخلة: الواحدة، والجميع: السخل والسخال. ويقال للأوغاد من الرجال: سخل وسخال، لا يفرد منه واحد.'),
(1270, 'سلخ', 'سلخ', 'سلخ', 'السلخ: كشط الإهاب عن [ذيه] 1 ، الإهاب نفسه. ومسلاخ الحية: قشرها الذي ينسلخ منها. والإنسان إذا محشه الحر، قيل: قد سلخ الحر جلده فانسلخ، وقد تسلخ جلده من داء. وسلخت المرأة درعها: نزعته. قال 2 : إذا سلخت عنها أمامة درعها ... وأعجبها رابي المجسة مشرف وسلخت الشهر: خرجت منه، فصرت في آخر يوم منه، وانسلخ الشهر. والسالخ: جرب يكون بالجمل، سلخ فهو مسلوخ، وكذلك الظليم إذا أصاب ريشة داء. والمسلوخة: اسم للشاة المسلوخة نفسها، بلا بطون ولا جزارة. وانسلخ النهار من الليل: خرج منه خروجا لا يبقى معه شيء من ضوئه، لأن النهار مكور على الليل فإذا انسلخ منه [ضوؤه] 3 بقي الليل غاسقا قد غشي الناس، قال الله عز ذكره: وآية لهم الليل نسلخ منه النهار 4 .. والسليخة: شيء من العطر كأنه قشر منسلخ ذو شعب. والسالخ من الحيات: الشديد السواد.. والنبات إذا سلخ، ثم عاد فاخضر كله فهو سالخ، من الحمض وغيره.'),
(1271, 'خنس', 'خنس', 'خنس', 'الخنس: انقباض قصبة الأنف، وعرض الأرنبة كأنف البقرة الخنساء، قال 1 : خنساء ضيعت الفرير فلم يرم ... عرض الشقائق طوفها وبغامها والترك: خنس. والخنوس: الانقباض والاستخفاء. والشيطان يوسوس في القلب، فإذا ذكر الله خنس 2 ، أي: أنقبض. الخنس: الكواكب الخمسة التي تجري وتخنس في مجراها حتى يخفى ضوء الشمس، وخنوسها: اختفاؤها بالنهار.'),
(1272, 'سخن', 'سخن', 'سخن', 'السخن: نقيض البارد، سخن الماء سخونة، وأسخنته إسخانا، وسخنته تسخينا، فهو سخن وسخين ومسخن. وسخنت عينه: نقيض قرت، وهي تسخن سخنة وسخونة، وهو سخين العين. وليلة [سخنانة] 3 : حارة، وطعام سخاخين، أي: قدم إليك حارا، ومطر سخاخين: جاء في حر القيظ. والسخين: المر الذي يعمل به في الطين.'),
(1273, 'نخس', 'نخس', 'نخس', 'النخس: تغريزك مؤخر الدابة بعود أو غيره. وسمي النخاس لنخسه الدابة حتى تنبسط. وفعله: النخاسة. ويقال لابن زنية: ابن نخسة، قال الشماخ 1 : أنا الجحاشي شماخ وليس أبي ... بنخسة- لدعي غير موجود أي: متروك وحده، ولا يقال: منه وحده. ونخسوا بفلان: هيجوه وأزعجوه، وكذلك إذا نخسوا دابته وطردوه، قال 2 : الناخسين بمروان بذي خشب ... والمقحمين على عثمان في الدار أي: نخسوا به من خلفه حتى سيروه من البلاد. والنخيسة: الزبدة ... والنخاسان: دائرتان في دائرة الفخذين كدائرة كتف 3 الإنسان. والدابة منخوسة: يتطير منها. كما يتطير من المهقوع والمقلوع والمكشوف، وغير ذلك. والناخس: جرب يكون عند ذنب البعير [فهو منخوس] 4 . والنخاسة: رقعة تدخل في ثقب البكرة لئلا يأكلها المحور، ويقال: أنخسوا البكرة، أي: سدوا ما أتسع منها بخشبة، أو غير ذلك.'),
(1274, 'سنخ', 'سنخ', 'سنخ', 'السنخ: أصل كل شيء. وسنخ السكين: طرف سيلانه الداخل في النصاب. ورجع فلان إلى سنخه الكريم أو الخبيث. وأسناخ الثنايا: أصولها. وسنخ الكلمة: أصل بنائها. والسناخة: الرائحة المكروهة.'),
(1275, 'نسخ', 'نسخ', 'نسخ', 'النسخ والانتساخ: اكتتابك في كتاب عن معارضه. والنسخ: إزالتك أمرا كان يعمل به، ثم تنسخه بحادث غيره، كالآية تنزل في أمر، ثم يخفف فتنسخ بأخرى، فالأولى منسوخة [والثانية ناسخة] 1 . وتناسخ الورثة، وهو موت ورثة بعد ورثة، والميراث لم يقسم، وكذلك تناسخ الأزمنة، والقرن بعد القرن.'),
(1276, 'خسف', 'خسف', 'خسف', 'الخسف: سؤوخ الأرض بما عليها من الأشياء.. انخسفت به الأرض، وخسفها الله به. وعين خاسفة: فقئت، وغابت حدقتها. وبئر خسيف مخسوفة، أي: نقب جبلها 2 عن عيلم الماء فلا تنزف أبدا، وهن الأخسفة. وناقة خسيف: غزيرة سريعة الإنقطاع من اللبن في الشتاء. والخسيف من السحاب: ما نشأ من قبل العين، أي: من قبل المغرب الأقصى عن يمين القبلة، وفيه ماء كثير.. وخسفناها خسفا. وخسوف الشمس: يوم القيامة: دخولها في السماء، كأنها تكورت في جحر. والخسف: تحميلك إنسانا ما يكره. والخسف: الجور، بلغة الشحر،'),
(1277, 'خفس', 'خفس', 'خفس', '[يقال للرجل: خفست يا هذا، وأخفست] وهو من سوء القول- إذا قلت لصاحبك: أقبح ما تقدر عليه. وشراب مخفس: سريع الإسكار، وهو من القبح، لأنك تخرج منه إلى قبح القول والفعل.'),
(1278, 'سخف', 'سخف', 'سخف', 'السخف: رقة العقل. وفي حديث أبي ذر: أنه لبث أياما فما وجد سخفة الجوع 2 ، أي: رقته وهزاله. ورجل سخيف، بين السخف. وهذا من سخفة عقله، وسخافة عقله. وثوب سخيف: رقيق النسج، بين السخافة، ولا يكادون يقولون: السخف، إلا في العقل خاصة، والسخافة عام في كل شيء.'),
(1279, 'فسخ', 'فسخ', 'فسخ', 'الفسخ: زوال المفصل عن موضعه.. وقع فانفسخت قدمه، وفسخته أنا. وفسخت البيع بينهما فانفسخ، أي: نقضته فانتقض. والفسيخ: الضعيف المتفسخ عند الشدة. والفسخ: حل العمامة، تقول: أفسخ عمامتك، أي: حلها. وانفسخ اللحم، أي: أصل وتفسخ عن العظم. وانفسخ الشعر عن الجلد، ولا يقال إلا لشعر الميت وجلده ورجل فسيخ: لا يظفر بحاجته.'),
(1280, 'خبس', 'خبس', 'خبس', 'أسد خابس وخباس وخبوس وخنابس، وخبسه: أخذه بكفه. والخباسة: ما يخبس، أي: يؤخذ. قال 1 : خباسات الفوارس كل يوم ... يواري شمسه رهج الغبار والخباسة: الغنيمة، قال أبو زبيد 2 : ولكني ضبارمة جموح ... على الأقران مجترء خبوس'),
(1281, 'سخب', 'سخب', 'سخب', 'السخاب: قلادة تتخذ من قرنفل وسك ومحلب، ليس فيها من الجوهر شيء، وجمعه: سخب. والسخب: الصخب بلغة ربيعة.'),
(1282, 'بخس', 'بخس', 'بخس', 'البخس: أرض تنبت من غير سقي، وجمعه: بخوس. والبخس: فقء العين بالإصبع وغيرها. والبخس: الظلم، تبخس أخاك حقه فتنقصه، كما ينقص الكيال مكياله فينقصه. وقوله عز وجل: بثمن بخس 3 . أي: ناقص، وقوله عز وجل: ولا تبخسوا الناس أشياءهم 4 * أي: لا تنقصوا. وعن أبي عمرو: الأباخس: الأصابع. واحدها: أبخس.'),
(1283, 'سبخ', 'سبخ', 'سبخ', 'أرض سبخة: أي: ذات ملح ونز، وانتهينا إلى سبخه، أي: إلى موضعه، والنعت: أرض سبخة. وأسبخت الأرض وسبخت. ويقال: قد علت الماء سبخة شديدة كالطحلب من طول الترك. والسبيخة: قطنة تعرض ليوضع عليها دواء، وتوضع فوق جرح، وما أشبهها من عرمض وغيره، وجمعها: سبائخ، قال 1 : سبائخ من برس وطوط وبيلم ... وقنفعة فيها أليل وحيحها البرس: القطن، والطوط: قطن البردي، والبيلم: قطن القصب. والقنفعة: القنفذة، والأليل: التوجع. والوحيح: صوت، من الوحوحة. والتسبيخ: نحو السل والتخفيف. وقوله [صلى الله عليه وعلى آله وسلم] لعائشة: لا تسبخي عليه بدعائك ، أي: لا تخففي. ويقال لريش الطائر [الذي يسقط] : 2 سبيخ، لأنه ينسل فيسقط. والسبائخ: قطع القطن إذا ندف. قال الأخطل 3 : فأرسلوهن يدزين التراب كما ... يذري سبائخ قطن ندف أوتار'),
(1284, 'خمس', 'خمس', 'خمس', 'الخماسي والخماسية من الوصائف: ما كان طوله خمسة أشبار، ولا يقال: سداسي ولا سباعي في هذا، وفي غير ذلك: الخماسي: ما بلغ خمسة، وكذلك السداسي والعشاري. والخميسي والمخموس من الثوب: الذي طوله خمس أذرع، ويقال: بل الخميسي: ثوب منسوب إلى ملك من ملوك اليمن كان أمر بعمل هذه الثياب، فنسبت إليه. والخمس: تأنيث الخمسة. والخمس: أخذك واحدا من خمسة، تقول: خمست مال فلان، وتقول: هذا خامس خمسة، أي: واحد من خمسة، والخمس: جزء من خمسة، وخمست القوم، أي: تموا بي خمسة. والخمس: شرب الإبل يوم الرابع من يوم صدرت، لأنهم يحسبون يوم الصدر فيه. والخميس: الجيش. والخميس: الخمس، كالعشير من العشر. والأخماس: برود من برود اليمن. والمخامس: الذي يقاسمك الخمس وتقاسمه.'),
(1285, 'سخم', 'سخم', 'سخم', 'السخام: [دخان القدر] 1 معروف. والسخام: الشيء اللين. والسخيمة: الموجدة في النفس والسخم: مصدره. وقد سخمت بصدره، أي: أغضبته، وسللت 2 سخيمته بقول طيب، وجمعها: سخائم. وشعر سخام، أسود لين. وخمر سخامية: لون يضرب إلى السواد، قال: 3 [فبت كأني شارب بعد هجعة] ... سخامية حمراء تحسب عندما وسخمت وجهه: سودته. والسخام: الريش اللين يكون تحت ريش الطائر، الواحدة بالهاء.'),
(1286, 'سمخ', 'سمخ', 'سمخ', 'السماخ: لغة في الصماخ، وهو والج الأذن عند الدماغ. وسمخته أسمخه، إذا أصبت سماخه فعقرته. وسمخني لشدة صوته وكثرة كلامه. ولغة تميم: الصمخ والصماخ . مسخ: المسخ: تحويل خلق عن صورته، وكذلك المشوه الخلق. والمسيخ من الناس: الذي لا ملاحة له، ومن الطعام: الذي لا ملح فيه. ومن الفواكه: الذي لا طعم له. وقد مسخ مساخة. قال 1 : وأنت مسيخ كلحم الحوار ... فلا أنت حلو ولا أنت مر والماسخي: القواس، ويقال: بل القسي تنسب إلى ماسخة، وهو حي 2 من الأزد، 3 ويقال: بل نسبت إلى الذي مسخها.'),
(1287, 'خزر', 'خزر', 'خزر', 'الخزر: جيل خزر العيون. والخزرة: انقلاب الحدقة نحو اللحاظ. وهو أقبح الحول، قال: 4 إذا تخازرت وما بي من خزر ... ثم كسرت العين من غير عور والخزرة: وجع في الصلب. وخزرت فلانا خزرا: نظرت إليه بلحاظ عيني. قال 5 : لا تخزر القوم شزرا عن معارضة وعدو أخزر العين، إذا نظر عن معارضة، والخزيرة: مرقة، تطبخ بماء يصفى من بلالة النخالة، قال: 1 مباسيم عن غب الخزير كأنما ... تصوت في أعفاجهن الضفادع [والخنزير: مأخوذ من الخزر، لأن ذلك لازم له] 2 ، قال: 3 لا تفخرن فإن الله أنزلكم ... باخزر ثعلب دار الذل والعار يعني: يا خنازير وكل خنزير أخزر. والخيزران: نبات لين القضبان، أملس العيدان، ويقال: بل كل خشبة مستوية: خيزرانة. والخيزرانة: سكان السفينة. والخزرة: داء في مستدق الظهر عند فقره، قال: 4 داو بها ظهرك من توجاعه ... من خزرات فيه وانقطاعه'),
(1288, 'خرز', 'خرز', 'خرز', 'الخرز: فصوص من جيد الجوهر، ورديئه من الحجارة ونحوها. والخرز: خياطة الأدم، وكل خرزة: كتبة-، يعني: ثقبة. والمخرز من الحمام والطير: الذي على جناحيه نمنمة [وتحبير] شبيه بالخرز.'),
(1289, 'زخر', 'زخر', 'زخر', '[زخر البحر يزخر زخرا وزخورا] 5 ، إذا جاش ماؤه وارتفعت أمواجه، فهو زاخر. وكذلك الخيل إذا جاشت للنفير، [وإذا جاش القوم للنفير قيل: زخروا] 1 .'),
(1290, 'خزل', 'خزل', 'خزل', 'الخزل من الانخزال في المشي، كأن الشوك شاك قدمه. والخزل: القطع. قال الأعشى 2 : [صفر الوشاح وملء الدرع بهكنة] ... إذا تأتى يكاد الخصر ينخزل والسحاب يتخزل، إذا رأيته متثاقلا كأنه يتراجع. والأخزل: الذي في وسط ظهره كسر، فهو مخزول الظهر، وفي ظهره خزلة، أي: هو مثل سرج. وقد خزل خزلا. والأخزل: البعير الذي قد ذهب سنامه كله. والمخزول من الشعر، والخزلة في الشعر: سقوط تاء متفاعلن ومفاعلتن، كقوله: 3 وأعطى قومه الأنصار فضلا ... وإخوتهم من المهاجرينا كأن تمامه من (المتهاجرينا) ، ويكون هذا في الوافر والكامل. ومثله قوله: 4 لقد بححت من الندا ... ء بجمعكم هل من مبارز وتمامه: ولقد، ويسمى هذا أخزل ومخزولا، وهو الجزء الذي فيه الخزلة.'),
(1291, 'زلخ', 'زلخ', 'زلخ', 'الزلخ: رفعك يدك في رمي السهم إلى أقصى ما تقدر عليه، تريد بعد الغلوة، قال 5 : من مائة زلخ بمريخ غال وسألت أبا الدقيش عن هذا البيت بعينه. فقال: الزلخ أقصى غاية المغالي.'),
(1292, 'خزن', 'خزن', 'خزن', 'خزن الشيء فلان يخزنه خزنا إذا أحرزه في خزانة، واختزنته لنفسي. وخزانتي قلبي، وخازني لساني، قال لقمان لابنه: إذا كان خازنك حفيظا، وخزانتك أمينة سدت في دنياك وآخرتك 1 يعني اللسان والقلب. والخزانة: الموضع الذي يخزن فيه الشيء. والخزانة عمل الخازن. وخزن اللحم أي تغير، قال: 2 ثم لا يخزن فينا لحمها ... إنما يخزن لحم المدخر 3 قال الخليل: النصب خزانة النحو، والبصرة خزانة العرب 4 أي معولهم عليه أكثر من سائره. النصب في الحال والقطع والوقف وإضمار الصفات.'),
(1293, 'خنز', 'خنز', 'خنز', 'خنزت الجوزة خنوزا: عفنت. وكذا ما يشبهها كالتمر ونحوه. وخزن لغة في خنز، وخنزت تخنز وخنز يخنز وخزن يخزن وخزن يخزن (ويخزن) 5 .'),
(1294, 'فخز', 'فخز', 'فخز', 'الفخز: العظمة، وهو يتفخز علينا.'),
(1295, 'خزف', 'خزف', 'خزف', 'الخزف: الجر، والخصف لغة فيه.'),
(1296, 'خزب', 'خزب', 'خزب', 'الخزب: ورم أو كهيئته في الجلد من غير ألم، وفي الضرع خزب شبه الرهل، خزب فهو خزب. والخزب: النوق اليابسة الضروع، الواحدة خزباء، وقال: . وفي حياضك من جود ومكرمة ... ثر الأحاليل لا كمش ولا خزب وفي أي: ملأها، وهذا مثل 2 . والخازباز: ذباب في العشب، ويقال: هو مجرور، وقال: 3 تفقع فوقه القلع السواري ... وجن الخازباز به جنونا والخازباز: ضرب من البقل. والخازباز: داء يأخذ في اللهازم. قال: 4 يا خازباز أرسل اللهازما ... إني خشيت أن تكون لازما'),
(1297, 'بزخ', 'بزخ', 'بزخ', 'البزخ: الجرف بلغة عمان. والبزخ: تقاعس الظهر عن البطن، ورجل أبزخ وأبزى. وأما البزي فكأن العجز خرجت حتى أشرفت على الفخذين، والأبزخ ما به وصف وربما مشى الإنسان متبازخا كمشية العجوز إذا تكلفت إقامة صلبها فتقاعس كاهلها وانحنى ثبجها. وتبازخت عن كذا أي تقاعست عنه. وبزخت ظهره بالعصا بزخا إذا ضربت ذلك الموضع. وبزاخة: موضع، (ويوم بزاخة من أيام العرب معروف) 1 .'),
(1298, 'خبز', 'خبز', 'خبز', 'الخبز: الضرب باليد، والخبز: السوق الشديد، قال 2 لا تخبزا خبزا ونسا نسا النس: السوق اللطيف، ومن روى بسا فقد غلط، 3 لأن البس من البسيس، وهو دقيق يلت بالسمن أو الزيت ثم يستف. والخبزة: اسم لما يعالج في الملة وهي الطلمة، يقال: أكلت خبز ملة لأن الملة الخبز نفسه والرماد. واختبز فلان إذا عالج دقيقا فعجنه ثم خبزه. والخبازة صنعته.. والخبيز: الخبز المخبوز من أي حب كان. يقال: عندهم طبيخ وخبيز أي مرق مطبوخ وخبز مخبوز.'),
(1299, 'زخب', 'زخب', 'زخب', 'الزخزب: 1 الذي اشتد لحمه وغلظ جسمه من الفصلان وغيرها.'),
(1300, 'خمز', 'خمز', 'خمز', 'الخاميز عجمي إعرابه: عامص وآمص.'),
(1301, 'زمخ', 'زمخ', 'زمخ', 'الزامخ: الشامخ بأنفه.'),
(1302, 'خزم', 'خزم', 'خزم', 'الخزم: الشد، 2 ، (تقول) : شراك مخزوم. والخزامة: برة في أنف الناقة يشد فيها الزمام. والخزامة من قلب (كذا) 3 ، فإن كانت من صفر 4 فهي برة وإن كانت من عقب فهي ضانة، والجميع الخزائم. وكمرة خزماء: قصيرة وترتها، وذكر أخزم، قال قائل لبني له أعجبه: شنشنة أعرفها من أعرفها من أخزم 1 أي قطران الماء من ذكر أخزم، قال: هذا خطأ، بل أخزم جد حاتم الطائي، وإنما أراد أن حاتما فيه مشابه من أخزم. وقالوا: الأخزم قطعة من جبل. والأخزم الحية الذكر. والخزمة: خوص المقل يعمل منه أحفاش النساء والخزم: شجر..'),
(1303, 'خطر', 'خطر', 'خطر', 'الخطر: القطيع الضخم من الإبل ألف أو زيادة. والخطر: ارتفاع المكانة والمنزلة والمال والشرف. والخطر: السبق الذي يتراهن عليه، يقال: وضعوا لهم خطرا أي ثوبا ونحوه، قال: وعنده يحرز الأخطار والقصبا 2 والسابق يتناول قصبة فيعلم أنه قد أحرز الخطر. ويقال: هذا خطر لهذا أي: مثل في القدر، ولا يكون إلا في الشيء المزير. ولا يقال في الدون إلا للشيء السري 3 ، ويقال: ليس له خطر أي: نظير ومثل، وخطيره: نظيره. وأخطرت بفلان أي صيرت نظيره في الخطر، ويقال للرجل الشريف: هو عظيم الخطر. وأخطرني فلان وهو مخطري، بالياء، إذا كان مثلك في الخطر. والجند يخطرون حول قائدهم: يرونه منهم الجد. وخطر يخطر الشيطان من الرجل وقلبه أي أوصل وسوسة إلى قلبه 1 . والإخطار: الإحراز في اللعب بالجوز. والخطير: الخطران عند الصولة والنشاط، وهو التطاول والوعيد، قال الطرماح: بالوا مخافتها على نيرانهم ... واستسلموا بعد الخطير وأخمدوا 2 ورجل خطار بالرمح: طعان به، قال: مصاليت خطارون بالرمح في الوغي 3 ورمح خطار: ذو اهتزاز شديد، يخطر خطرانا. وخطر فلان بيده يخطر كبرا في المشي، والناقة تخطر بذنبها لنشاطها أي: تحرك. وخطر على بالي وببالي، كله يخطر 4 خطرانا وخطورا إذا وقع ذلك في بالك وهمك. وخطر الدهر من خطرانه كقولك ضرب الدهر من ضربانه. والخطر: مكيال لأهل الشام ضخم. والخطار: دهن يتخذ من زيت بأفاويه الطيب والعطر. والخطر: نبات يجعل ورقه في الخضاب الأسود. ويقال: ما لقيته إلا خطرة بعد خطرة معناه الأحيان بعد الأحيان. وخاطر بنفسه أي أشفاها على خطر هلك أو نيل ملك. والمخاطر: المرامي.'),
(1304, 'طخر', 'طخر', 'طخر', 'الطخارير: سحابات 1 متفرقة، الواحدة طخرورة، وفي المطر مثله. والناس طخارير أي متفرقون.'),
(1305, 'خرط', 'خرط', 'خرط', 'الخرط: قشرك الورق عن الشجرة اجتذابا بكفك، ومنه خرط القتاد، وقال مرار ابن منقذ: 2 ويرى دوني فما يسطيعني 3 ... خرط شوك من قتاد مسمهر أي شديد. والخروط من الدواب: الذي يجتذب رسنه من يد ممسكه ثم يمضي عائرا خارطا. ويقول البائع (للدابة) : 4 برئت إليك من الخراط. واستخرط فلان: أشتد بكاؤه 5 ولج فيه. واخترطت السيف: سللته. ويكون قوم في أمر فيقبل عليهم رجل بما يكرهون فتقول: 6 انخرط عليهم، وهو الخروط يقع في الأمر بجهل. والخروط: الفاجرة من النساء. والإخريط نبات من المرعى. والخراط 1 والواحدة خراطة: شحمة تمتصخ من أصل البردي، ويقال: هو الخراطي والخريطي، ياؤه مثل حبلى. وخرط الضرع: وقع فيه الخرط، وهو لبن يشوبه دم، وأخرطت الناقة أي صار بها ذاك، فهي مخرط، فإذا كان ذلك عادة فهي مخراط. والخريطة مثل الكيس مشرج من أدم أو خرق لكتب العمال. وإذا أذن المولى للعبد بأذى الناس قيل: خرط عليهم عبده. وإذا طال الطريق وامتد يقال: قد اخروط، قال: 2 عن حافتي أبلق مخروط ووجه مخروط، أي: فيه طول. وإذا انقلبت الشركة 3 على الصيد فاعتلقت رجله قيل: اخروطت في رجله، وهو امتداد انشوطتها. وخرطها يخرطها خرطا، أي: نكحها. وناقة مخروطة: سريعة. وإذا أخذ الطائر الدهن بزمكائه من مدهنة قلت: تخرط تخرطا، ونضد تنضيدا مثله.'),
(1306, 'طرخ', 'طرخ', 'طرخ', 'الطرخة: ماء 4 يجتمع كالحوض الواسع عند مخرج القناة يجتمع فيها ماء كثير ثم يفتح منها إلى المزارع، دخيل، ليس بعربية محضة. وطرخان اسم رجل بلغة خراسان.'),
(1307, 'خطل', 'خطل', 'خطل', 'الخطل: خفة وسرعة، يقال للأحمق العجل وللمقاتل السريع الطعن: خطل، قال: أحوس في الظلماء بالرمح خطل 1 والخطل من السهام الذي يذهب يمينا وشمالا لا يقصد قصد الهدف، قال الكميت: هذا لذاك وقول المرء اسهمه ... منها المصيب زمنها الطائش الخطل ويقال للجواد: خطل اليدين بالمعروف أي: عجل. والخطل من الثياب: 2 ما غلظ وخشن وجفا، 3 قال: أعد أخطالا له ونرمقا 4 يعني الصياد. والخطلاء من الشاء: العريضة الأذنين جدا، وأذناه خطلاوان كنعلين. والخيطل: السنور، ويجمع خياطل وامرأة خطالة فحاشة، وخطلها فحشها من العيب والزينة.'),
(1308, 'طلخ', 'طلخ', 'طلخ', 'الطلخ: اللطخ بالقذر وإفساد الكتاب ونحوه. واطلخ دمع عينه: تفرق، قال: لا خير في الشيخ إذا ما أجلخا ... وسال غرب عينه فاطلخا 2'),
(1309, 'لطخ', 'لطخ', 'لطخ', 'اللطخ أعم من الطلخ، واللطاخة: بقية الطلخ وأثره. ورجل لطخ: قذر الأكل، ولطخت فلانا بأمر قبيح ونحوه'),
(1310, 'خلط', 'خلط', 'خلط', 'اختلط الشيء بالشيء وخلطته خلطا. والخلط: اسم كل نوع من الأخلاط كالدواء ونحوه، قال: شريجان من لونين خلطين منهما ... سواد ومنه واضح اللون مغرب 3 قال: أحسبه الليل والفجر. والخليط أيضا من السمن فيه لحم وشحم. والخليط: تبن وقت مختلطان. والخليطي: تخليط الأمر، إنه لفي خليطي من أمره. والخلاط: مخالطة الذئب بالغنم، قال: يضمن أهل الشاء بالخلاط 1 وخليط الرجل: مخالطه. والخليط: القوم الذين أمرهم واحد، قال: بان الخليط بسحرة فتبددوا 2 والخلاط: مخالطة الفحل الناقة أيضا، إذا خالط ثيله حياها. وأخلط الرجل للفحل إذا أدخل قضيبه وسدده. وخولط في عقله خلاطا فهو خلط 3 . وخلط مختلط بالناس متحبب، وامرأة بالهاء. ونهي عن الخليطين في الأنبذة، وهو أن يجمع بين صنفين تمر وزبيب أو عنب ورطب. وقوله: لا خلاط ولا وراط أي لا يجمع بين متفرق ولا يفرق بين مجتمع، والوراط: الخديعة. وإذا حلبت على الحامض محضا فهو الخليط. والخلاط: مخالطة الداء الجوف. وأخلط الفحل إذا خالط، وأخلطه الرجل.'),
(1311, 'نخط', 'نخط', 'نخط', 'النخط: الأنام، يقال: ما في النخط مثلك. وقال الضرير: إنما هو: ما في النخط مثله.'),
(1312, 'خطف', 'خطف', 'خطف', 'الخطف: الأخذ في الاستلاب. وسيف يخطف الرأس، ونار مخطف الضريبة 1 قال: يخطف خزان الشربة بالضحى 2 وبرق خاطف: يخطف نور الأبصار. والشياطين تخطف السمع أي تسترق. والخطاف: اللص. وخطف يخطف، وخطف يخطف 3 . والخطفة مثل الخلسة: هو كل ما اختطفت. وبه خطف أي شبه جنون. والمخطف 4 : الذي يرفع الشراع في البحر. والخيطف: سرعة انجذاب السير، وجمل خيطف، وجمل ذو عنق خيطف، قال: أعناق جنان وهاما رجفا 1 ... وعنقا بعد الرسيم خيطفا أي كأنه يختطف في مشيه عنقه، أي يجتذب. والخطفى: سيرته. وهو أخطف الحشي، وبعير مخطف، وحمار مخطف البطن. والخطاف: طائر، يجمع: خطاطيف. والخطاف: حديدة حجناء في جانبي البكرة فيهما المحور، قال النابغة: خطاطيف حجن في حبال متينة ... تمد بها أيد إليك نوازع 2 وكل شيء يشبه به سمي خطافا، يقال: بعير به سمة خطاف أو كالخطاف، وهي سمة أناس من تيم. وكان الحسن يقرأ: إلا من خطف الخطفة 3 على تأويل: اختطف اختطافة، جعل المصدر على بناء خطف يخطف خطفة كما تقول من الاختطاف اختطافة. والخاطف: الذئب لأنه يخطف.'),
(1313, 'طخف', 'طخف', 'طخف', 'طخفة: جبل من جبال الحمى، وموضع أيضا.'),
(1314, 'خطب', 'خطب', 'خطب', 'الخطب: سبب الأمر. وفلان يخطب امرأة ويختطبها خطبة، ولو قيل خطيبي جاز، والخطيبى مرخمة الياء 1 على بناء خليفى، الياء مرخمة، اسم امرأة، قال: 2 لخطيبى التي غدرت وخانت ... وهن ذوات غائلة دهينا والخطاب: مراجعة الكلام. والخطبة: مصدر الخطيب. وكان الرجل في الجاهلية إذا أراد الخطبة قام في النادي فقال: خطب، ومن أراده قال: نكح. وجمع الخطيب خطباء، وجمع الخاطب خطاب. والأخطب: طائر، وهو الشقراق. والأخطب: لون إلى الكدرة مشرب حمرة في صفرة كلون الحنظلة الخطباء قبل أن تيبس، وكلون بعض حمر الوحش، والجميع: خطبان، وقال علقمة بن عبدة: يظل في الحنظل الخطبان ينقفه 3 ويقال: بل الواحدة خطبانة كقولك كتفان كتفانة، ويرويان بالكسر. وقد خطب لونه خطبا، قال ذو الرمة: قود سماحيج في ألوانها خطب 1 والخطب: المرأة، وهو الزوج، والمخطبة الخطبة، إن شئت في النكاح، وإن شئت في الموعظة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1315, 'خبط', 'خبط', 'خبط', 'الخبط: خبط ورق العضاه، وهو أن تضرب بالعصا حتى يتناثر ثم تعلفه الإبل، وخبطت له خبطا. والخبط: الهش، وهو اسم مثل النفض والنسل، وهو ما خبطته أي كسرته. والخبطة: شيء من ماء ولبن قليل، والرفض مثله. وخبطة من مس، والشيطان يخبط الإنسان إذا مسه بأذى وأجنه وخبله. والخبط: شدة الوطء بأيدي الدواب. وتخبطت الشيء: توطأته. والخبطة كالزكمة في قبل الشتاء، وقد خبط فهو مخبوط. ويقال للذي فيه وعوثة في لبسه وعمله: يا خباطة. والخبيط: حوض خبطته الإبل حتى هدمته، وجمعه خبط، ويقال: بل سمي لأن طينه خبط بالأرجل عند بنائه، قال: 2 ونؤي كأعضاذ الخبيط المهدم والخبيط: لبن رائب أو مخيض، يصب الحليب من اللبن ثم تضربه حتى يختلط، قال: أو قبضة من حازر خبيط 1 ... تصبه في العقب ذي التخليط والإختباط: طلب المعروف، واختبطت فلانا معروفه فخبطني، قال: 2 وفي كل حي قد خبطت بنعمة ... وحق لشأس من نداك ذنوب وقال لبيد: ليبك على النعمان شرب وقينة ... ومختبطات كالسعالي أرامل 3 ويقال: بل هو الطالب بلا وسيلة ولا معرفة، والأول أجود. والخباط: سمة في الفخذ طويلة عرضا وهي لبني سعد. وخبوط: يخبط بيديه أي يضرب.'),
(1316, 'طبخ', 'طبخ', 'طبخ', 'الطبخ: إنضاج اللحم والمرق، والطبيخ كالقدير إلا أن القدير فيه توابل، والطبيخ دونه. والطباخة: ما تأخذ مما تحتاج إليه مما يطبخ نحو البقم تأخذ طباخته للصبغ وتطرح سائره. والمطبخ: بيت الطباخ: وأطبخناه: عالجناه. وقول العجاج: تالله لولا أن تحش الطبخ 4 يعني بالطبخ: الملائكة الموكلين بعذاب أهل النار. وطبائخ الحر: سمائمه في الهواجر، الواحدة طبيخة، قال الطرماح: طبائخ شمس حرهن سفوع 1 أي شديد محرق للجلد. والطبيخ: ضرب من المنصف. والطبيخ: لغة في البطيخ، حجازية. وامرأة طباخية: شابة مكتنزة، قال الأعشى: عبهرة الخلق طباخية ... تزينه بالخلق الطاهر 2 وشاب مطبخ: أملأ ما يكون شابا وأرواه. والمطبخ: من أولاد الضباب 3 حتى يكاد يلحق بأبيه. وطبخ الغلام تطبيخا أي ترعرع وعمل. ويقال: ليس به طباخ أي لا قوة ولا سمن. وطابخة بن إلياس بن مضر.'),
(1317, 'بطخ', 'بطخ', 'بطخ', 'المبطخة: مجتنى البطيخ ومنبته.'),
(1318, 'طخم', 'طخم', 'طخم', 'الطخمة: سواد في مقدم الأنف ومقدم الخطم، قال 1 : وما أنتم إلا ظرابي قصة ... تفاسى وتستنشي بآنفها الطخم أي: لطخ من قذر. والظربان: شيء على خلقة الكلب صغير، والقصة: ناحية من الأرض، وهي أيضا وطن للجرذان. وكبش أطخم: رأسه أسود وسائره أكدر. والأطخم: مقدم الخرطوم في الإنسان والدابة.'),
(1319, 'خطم', 'خطم', 'خطم', 'الخطم: منقار كل طائر، ومن كل دابة مقدم أنفه وفمه نحو الكلب والبعير. والخطام: حبل يجعل في شفار من حديد، ليس في خشاش ولا برة ولا عران، وربما كان الشفار من حبل، وليس بمثقوب في الأنف. والأخطم: الأسود. والخطمي: نبات يتخذ منه غسل. والمخطم: الأنف. وخطمة: حي من الأنصار.'),
(1320, 'مطخ', 'مطخ', 'مطخ', 'المطخ: الباطل، ويقال للرجل الكذاب مطخ مطخ 2 أي باطل باطل.'),
(1321, 'خمط', 'خمط', 'خمط', 'الخمط: ضرب من الأراك يؤكل، وفي القرآن 1 يريد بالخمط هذا المعنى. والخمط: سلخك الحمل الخميط، تشويه، ويقال للحمل خاصة إذا نزع جلده: خمط، فإذا نزع شعره فهو سميط، ويقال: الخمط والسمط واحد. والخمطة: ريح نور الكرم وما أشبهه مما له ريح طيبة وليست بالشديدة الذكاء طيبا. ولبن خمط يجعل في سقاء ثم يوضع على حشيش حتى يأخذ من ريحه فيكون خمطا طيب الريح والطعم. ورجل متخمط وخمط: شديد الغضب له فورة 2 وجلبة من شدة غضبه، قال: إذا تخمط جبار ثنوه إلى ... ما يشتهون ولا يثنون إن خمطوا 3 ويقال للبحر إذا التطمت أمواجه: إنه لخمط الأمواج، قال: خمط التيار يرمي بالقلع 4 كأن وجهه القلاع فقصره، يعني الصخرة العظيمة.'),
(1322, 'مخط', 'مخط', 'مخط', 'امتخط الصبي ومخطته، وهو المخاط. ورجل مخط: سيد كريم، قال رؤبة: وإن أدواء الرجال المخط 1 ... مكانها من شامت وغبط أي: حد.'),
(1323, 'خدر', 'خدر', 'خدر', 'الخدر: ستر يمد للجارية في ناحية البيت، وكذلك ينصب لها خشبات فوق قتب البعير، مستور بثوب، وهو الهودج المخدور، والجميع: أخدار وأخادير، 3 قال: حتى تغامز ربات الأخادير وخدرت الجارية فتخدرت، وأخدرت لها كأخدار الظبية خشفها في هبطة من الأرض. وأسد خادر مخدر كثير الخدور، خدر في عرينه، وأخدره عرينه. والخادر: المتحير، وكل شيء منع بصرا فقد أخدره، والليل مخدر، قال العجاج: ومخدر الأبصار أخدري 4 والأخدري من نعت حمار الوحش. وليل خداري: شديد الظلمة. والخداري: الأسود الشعر حتى العقاب، والخداري: الشعر، وكذلك الجارية الخدارية، بالهاء. والخدر: امذلال يغشى اليد والرجل والجسد، والفعل خدرت. والخدر من الشراب والدواء: ما يضعف صاحبه. وقوله: بيعفور خدر 1 أي كأنه ناعس من سجو طرفه وضعفه. ويوم خدر أي: ماطر، ويوم خدر: شديد الحر أيضا، قال طرفة. ومكان زعل ظلمانه ... كالمخاض الجرب في اليوم الخدر 2 وخدر النهار: إذا لم يتحرك فيه الريح، ولا يوجد فيه روح.'),
(1324, 'دخر', 'دخر', 'دخر', 'الداخر: الصاغر، دخر يدخر دخورا أي صغر يصغر صغارا، وهو أن يفعل ما تأمره كرها على صغر ودخور.'),
(1325, 'خرد', 'خرد', 'خرد', 'جارية خريدة أي: بكر لم تمسس، والجميع: خرائد وخرد. وجارية خرودة: خفرة حيية، جاوزت الإعصار ولم تبلغ التعنيس.'),
(1326, 'ردخ', 'ردخ', 'ردخ', 'الردخ: الشدخ، والردخ يقال له: الردغ 3 .'),
(1327, 'خدل', 'خدل', 'خدل', 'مرأة خدلة الساق، وساق خدلة، وقد خدلت خدالة وخدلت خدولة، وجمعه خدلات وخدال. وخدالتها استدارتها كأنما طوي طيا.'),
(1328, 'دخل', 'دخل', 'دخل', 'الدخل: عيب في الحسب، والدخل، مثقل: شبيه بهذا، يقال في هذا الأمر دخل ودغل، قال: رفدت ذوي الأحساب منهم مرافدي ... وذا الدخل حتى عاد حرا سنيدها 1 والدخل: ما دخل ضيعة الإنسان من المنالة. ودخل فلان فهو مدخول، ودخل حسبه أو عقله، وامرأة مدخولة، ورجل مدخول أي مهزول، وفيه دخل من الهزال. والدخلة: بطانة من الأمر، يقال: إنه لعفيف الدخلة، وإنه لخبيث الدخلة أي: باطن أمره ويقال: إنه لعالم دخلة أمرهم وبدخل أمرهم. والدخلة في اللون: تخليط من ألوان في لون. وادخل في غار وتدخل فيه يصف شدة دخوله. ودخيلك 2 : الذي تدخله في أمورك، ودخلل أيضا، قال: وموطأ الأكناف أحصن سره ... من دون كل مضاحك أو دخلل 3 ودخول: موضع. والمتدخل في الأمور: المتكلف فيها 4 ، ليس بعالم. وسقيت الإبل دخالا إذا حملتها على الحوض ثانية لتستوفي بعد ما سقيتها قطيعا قطيعا. والدخال في وجه آخر: إن تحملها على الحوض بمرة واحدة عراكا، قال لبيد: فأوردها العراك ولم يذدها ... ولم يشفق على نغص الدخال 1 والدخال: مداخلة المفاصل بعضها في بعض، قال: وطرفة شدت دخالا مدرجا 2 والطرفة: الفرس الأنثى. والدوخلة: سفيفة من خوص صغيرة يجعل فيها الرطب. والدخل: صغار الطير، أمثال العصافير، مأواها في الصيف: الغيران وبطون الأودية تحت شجر ملتف، والجميع الدخاخيل، والواحدة دخلة للأنثى، قال: ألا أيها الربع الذي بان أهله ... فساكن واديه حمام ودخل 3 وإذا اؤتكل 4 الطعام سمي مدخولا ومسروفا. ودخل الطعام واماس فهو طعام مسيس 5 .'),
(1329, 'دلخ', 'دلخ', 'دلخ', 'الدالخ: المخصب من الرجال.'),
(1330, 'خلد', 'خلد', 'خلد', 'الخلد: من أسماء الجنان، والخلود: البقاء فيها، وهم فيها خالدون ومخلدون. وتفسير ولدان مخلدون* 6 مقرطون. وأخلد فلان إلى كذا أي ركن إليه ورضي به. والخلد: البال، تقول: ما يقع ذلك في خلدي. والخلد: ضرب من الجرذان عمي، لم يخلق لها عيون، واحدتها خلدة، والجميع خلدان. والخوالد: الأثافي، وتسمى الجبال والحجارة خوالد، قال: فتأتيك حذاء محمولة ... تفض خوالدها الجندلا 1 الخوالد هاهنا الحجارة ومعناها القوافي.'),
(1331, 'خدن', 'خدن', 'خدن', 'خدن الجارية: محدثها، وكانوا لا يمتنعون من خدن يحدثها فهدمه الإسلام، قال: ولا متخذات أخدان 2 . والخدان والخدين: مخادنك يكون معك في ظاهر أمرك وباطنه.'),
(1332, 'دخن', 'دخن', 'دخن', 'دخن الدخان دخونا: سطع. والداخنة: كوى فيها إردبات تتخذ على المقالي والأتونات، قال: كمثل الدواخن فوق الإرينا 3 ودخن الغبار أي سطع، قال 4 : أهوج محضير إذا النقع دخن والدخنة: بخور يدخن به. والدخن: الجاورس، والحبة منه دخنة. والدخنة من لون الأدخن، وهو كدرة في سواد كالدخان. وشاة دخناء، وكبش أدخن، قال: مرت كظهر الصرصران الأدخن 1 ومرت أي مستو، والصرصران: سمك بحري. وفي الحديث: هدنة على دخن أي صلح واستقرار على أمور مكروهة. وليلة دخنانة: كأنما يغشاها دخان من شدة حرها وغمها. ويوم دخنان سخنان. والدخان يقال له الدخ. وطعام دخن: فاسد.'),
(1333, 'ندخ', 'ندخ', 'ندخ', 'رجل مندخ أي: لا يبالي ما قال وما قيل له من الفحش.'),
(1334, 'دنخ', 'دنخ', 'دنخ', 'التدنيخ: خضوع وذلة وتنكيس الرأس، ويقال: لما رآني دنخ. والتدنيخ في البطيخة والقرعة أن يكون قد انهزم بعضها. وخرج بعضها. ورجل مدنخ الرأس إذا كان فيه ارتفاع وانخفاض في رأسه. ودنخت ذفراه أي أشرفت قمحدوته عليها، ودخلت الذفرى خلف الخششاوين فهو مدنح.'),
(1335, 'خفد', 'خفد', 'خفد', 'الخفيدد من الظلمان: الطويل الساقين، والجميع الخفيددات، ويقال: الخفادد. وإذا جاء على بناء فعالل في آخره حرفان مثلان فإنهم يمدونه نحو قردد وقراديد، وخفيدد وخفاديد، قال: وإن شئت سامي واسط الكور رأسها ... وعامت بضبعيها نجاء الخفيدد 1'),
(1336, 'خدب', 'خدب', 'خدب', 'الخدب: ضرب في الرأس ونحوه. والخدب: ضرب بالسيف يقطع اللحم دون العظم، قال العجاج: خوادبا أهونهن الأم 2 والخدب بالناب: شق الجلد مع اللحم، قال: للهام خدب وللأعناق تطبيق أي قطع مستو، والتطبيق: قطع يمضي في فقر العنق، وبين كل مفصلين. وأصابته خادبة أي: شجة شديدة وخيدب: موضع من رمال بني سعد. وبعير خدب أي: قوي ضخم شديد، وشيخ خدب أي: قوي'),
(1337, 'بدخ', 'بدخ', 'بدخ', 'امرأة بيدخة: تارة، لغة حمير. وبيدخ: اسم امرأة، قال: هل تعرف الدار لآل بيدخا ... جرت عليه الريح ذيلا أنبخا 1'),
(1338, 'خمد', 'خمد', 'خمد', 'خمد القوم إذا لم تسمع لهم حسا، وقوم خمود. وخمدت النار خمودا: سكن لهبها، وإذا طفئت قيل همدت.'),
(1339, 'خدم', 'خدم', 'خدم', 'الخدم: الخدام، الواحد خادم غلاما كان أو جارية، قال: مخدمون ثقال في مجالسهم ... وفي الرحال، إذا صاحبتهم، خدم 2 وهذه خادمنا لوجوبه، وهذه خادمتنا غدا. والخدمة: سير غليظ محكم، كالحلقة، يشد في رسغ البعير، ثم يشد [إليها 3 ] سرائح نعلها، وبه سمي الخلخال خدمة، وشاة خدماء في ساقها عند رسغها بياض كالخدمة في السواد، وسواد في بياض، والاسم الخدمة. والمخدم: موضع الخلخال، قال: ولو أن عز الناس في رأس هضبة ... ململمة تعيي الأرح المخدما 4 الأرخ: العظيم الظلف، ورباط السراويل عند أسفل الرجلين يقال له: خدمة. والمخدم من البعير: ما فوق الكعب.'),
(1340, 'دمخ', 'دمخ', 'دمخ', 'دمخ: اسم جبل.'),
(1341, 'مدخ', 'مدخ', 'مدخ', 'المدخ: العظمة، ورجل مديخ أي: عظيم عزيز، قال: مدخاء كلهمو إذا ما نوكروا ... يتقى كما يتقى الطلي الأجرب 1 وميدخة: تارة ناعمة بمنزلة بيدخة في الباب قبله، قال: لمن خيال زارنا من ميدخا ... طاف بنا والليل قد تجخجخا 2'),
(1342, 'ختر', 'ختر', 'ختر', 'الختر: شبه الغدر، ورجل ختار: غدار. والختر كالخدر، وهو ضعف يأخذك من شرب دواء أو سم أو سكر، تقول: انخترت يدي.'),
(1343, 'خرت', 'خرت', 'خرت', 'الخرت: ثقبة الإبرة والحلقة والفأس ونحوه، وجمعه خروت. وجمل مخروت الأنف: خرته الخشاش. والخريت: الدليل وجمعه الخرارت 1 ، قال: يعيا على الدلامز الخرارت 2 وبه سمي لسعة المفازة، ويجمع خراريت أيضا، والدلامز: المواضي، وقال: وبلدة ليس بها الخريت 3 وأخرات المزادة: عراها بينها القصبة التي تحمل بها، والواحدة خرتة، هذلية.'),
(1344, 'رتخ', 'رتخ', 'رتخ', 'الرتخ: قطع صغار في الجلد خاصة. وإذا لم يبالغ الحجام في الشرط، قالوا: أرتخ إرتاخا، وهو شق أعلى الجلد. وأراد أبو علقمة أن يحتجم فقال للحجأم: انظر ما آمرك به فاصنعه لا كمن أمر فضيعه: اتق غسل المحاجم، واشدد قصب الملازم وارهف ظبات المباضع ، وشرشر الوضع، وأخف القطع، واتئد ولا ترتخ، وليكن مصك لينا، وشرطك نهسا، ولا تردن آتيا، ولا تكرهن آبيا، حتى إذا الدم آل إلى غاية، وصرت من سكبه إلى نهاية فأحسن المسح، وقم عني فتنح. فقال الحجام: هذه صفة الحروب، ولم أقاتل قط، فحمل جونته وانصرف. وقراد رتخ 5 أي يابس.'),
(1345, 'ختل', 'ختل', 'ختل', 'الختل: تخادع عن غفلة، وقد ختل ختلا.'),
(1346, 'ختن', 'ختن', 'ختن', 'ختن يختن ختنا فهو مختون، والختانة صنعته، والختان ذلك الأمر كله وعلاجه، وطعامه: العذار. والختان أيضا، موضع القطع من الذكر. والختن: الصهر، والختن أيضا، وخاتنت فلانا مخاتنة، وهو الرجل المتزوج في القوم، والأبوان أيضا ختنا ذلك الزوج. والرجل ختن، والمرأة ختنة: والختن: زوج فتاة القوم، ومن كان قبله من رجل وامرأة، كلهم أختان لأهل المرأة. وأم الزوج حماة للمرأة، وأبوه حموها.'),
(1347, 'تنخ', 'تنخ', 'تنخ', 'تنخ فلان في العلم: رسخ فيه. وأتنخه: أثبته في الشيء حتى تنخ وثبت فيه 1 .'),
(1348, 'نتخ', 'نتخ', 'نتخ', 'نتخ البازي ينتخ اللحم بمنسره، والغراب ينتخ الدبرة عن ظهر البعير. والنتخ: إخراجك الشوك من الرجل بالمنتاخين، يقال: نتخت الشوك من رجلي. والمنتاخ: المنتاش.'),
(1349, 'خفت', 'خفت', 'خفت', 'صوت خفيت، وخفت خفوتا أي خفض خفوضا. ويقال للرجل إذا مات: قد خفت أي انقطع كلامه. وزرع خافت كأنه بقي فلم يبلغ غاية الطول. ومات خفاتا أي لم يشعر بموته، وأخفته الله. والرجل تخافت بقولته إذا لم يبينها برفع الصوت، وهم يتخافتون إذا تشاوروا سرا. وامرأة خفوت لفوت: وهي التي تأخذها العين ما دامت وحدها أي تستحسنها، فإذا صارت بين النساء غمرنها، ولفوت: فيها التواء وانقباض. ويقال: اللفوت: الكثيرة الالتفات إلى الرجال، والخفوت: التي تخفت في جنب من كان أحسن منها.'),
(1350, 'فخت', 'فخت', 'فخت', '1 إذا مشت المرأة مجنحة 2 قيل: تفختت، وأظن اشتقاق مشيها من مشي فاختة، وهي طائر.'),
(1351, 'فتخ', 'فتخ', 'فتخ', 'الفتخ: فتوخ الأسد مفاصل مخالبه، وإذا كان عريض الكف قيل له: أفتخ. وسميت العقاب فتخاء لعرض جناحيها. والفتوخ: خواتيم لا فصوص فيها، كأنها حلق، الواحدة فتخة. وكل جلجل لا يجرس فهو فتخ. والفتخ: لين وطول في الجناحين في قصبهما، 3 وفي الرجلين طول العظم وقلة اللحم. وقال بعضهم: لا أعرف الفتخ إلا عرض الكف والقدم، قال: على فتخاء تعلم حيث تنجو ... وما إن حيث تنجو من طريق 4 والفتخاء أيضا شيء مرتفع يجلس عليه الرجل [المشتار] فيمد ويجر، وهو شيء من خشب 5 .'),
(1352, 'خبت', 'خبت', 'خبت', 'الخبت: ما اتسع من بطون الأرض، وجمعه خبوت. والمخبت: الخاشع المتضرع، يخبت إلى الله ويخبت قلبه لله. والخبيت من الأشياء: الحقير الرديء، 1 قال: ينفع الطيب القليل من الرزق ... ولا ينفع الكثير الخبيت 2 وهو الخبيث بالثاء أيضا.'),
(1353, 'بخت', 'بخت', 'بخت', 'البخت والبختي، أعجميان دخيلان،: الإبل الخراسانية [تنتج] 3 من إبل عربية وفالج. ورجل مبخوت أي ذو بخت وجد.'),
(1354, 'ختم', 'ختم', 'ختم', 'ختم يختم ختما أي: طبع فهو خاتم. والخاتم: ما يوضع على الطينة، أسم مثل العالم، والختام: الطين الذي يختم به على كتاب 4 . ويقال: هو الختم يعني: الطين الذي يختم به. وختام الوادي: أقصاه. ويقرأ: خاتمه مسك 1 أي ختامه، يعني عاقبته ريح المسك، ويقال: بل أراد به خاتمه يعني ختامه المختوم، ويقال: بل الختام والخاتم ها هنا ما ختم عليه. وخاتمة السورة: آخرها. وخاتم العمل وكل شيء: آخره. وختمت زرعي إذا سقيته أول سقية، فهو الختم، والختام اسم لأنه إذا سقي فقد ختم بالرجاء. وختموا على زرعهم ختما أي سقوه وهو كراب بعد.'),
(1355, 'تخم', 'تخم', 'تخم', 'تخوم الأرض اسم على فعول، وبعض يقول: تخوم الأرض، كأنه جميع ولا يفرد منه واحد. وهو مفصل ما بين الكورتين أو القريتين. ومنتهى أرض كل قرية وكورة تخومها. قال الضرير: التخوم واحدها تخم. والتخمة فاؤها واو في أصل التأسيس ولكنها استعملت 2 فقيل: اتخم واتخمه كذا، ويخفف فيقال: تخم ويتخم، بحذف التثقيل من التاء. وبعض يقول: تخم متروك على ما كان عليه في قولك: اتخم، وكذلك قياس التهمة والتؤدة والتكأة (كأنهم حملوه على تقي يتقي مخففا. وهذا أمر متوخم ومستوخم إذا كان دميما.'),
(1356, 'خمت', 'خمت', 'خمت', 'الخميت: اسم السمين بالحميرية.'),
(1357, 'ذخر', 'ذخر', 'ذخر', 'ذخرته أذخره 1 ذخرا. وأدخرت ادخارا، وتاء الافتعال إذا جاءت بعد الذال تحولت إلى مخرج الدال فتدغم فيها الذال، وكذلك الادكار من الذكر. ومنعهم أن يدعوا تاء افتعل على حالها استقباحهم 2 لتأليف الذال مع التاء، وكذلك يجعل التاء مع الزاي 3 دالا [لازمة في نحو ازدرد، لأنه لا يوجد في بناء كلام العرب] 4 ذال 5 بعدها تاء، فلذلك جعلت تاء افتعل مع الذال دالا، لأن انتظامها من موضع واحد أيسر. وتقول من الدخان ادخن على ذلك التفسير. فإذا فرقت بين هذه الدال التي أصلها تاء وبين الحروف التي قبلها رجعت إلى أصلها كقولك من الدوخ والذوق أداخ وأذاق فهو مذاق، فإذا صغرت قلت مذيتيق. ومن الزيت مفتعل مزدات وتصغيره مزيتيت، ونحوه مثله، ولم يقل: مزديت على تقدير مفتعل، لأن الياء خوارة فاعتمدت على فتحة الدال، وكذلك الواو تعتمد على الفتحة. والإذخر: حشيشه طيبة الريح أطول من الثيل، وهو كهيئة الكولان، له 6 أصل مندفن. وهي شجرة صغيرة ذفرة الريح. قال الضرير: الكولان ضرب من النبات، وهو الذي يلقى في المساجد 1 .'),
(1358, 'رخذ', 'رخذ', 'رخذ', 'رخذ: اسم مدينة ويعرب فيقال: رخج.'),
(1359, 'خذل', 'خذل', 'خذل', 'خذل يخذل خذلا وخذلانا، وهو تركك نصرة أخيك. وخذلان الله للعبد: ألا يعصمه من السوء. والخاذل والخذول من الظباء والبقر الوحشية: التي تخذل صواحبها في المرعى وتنفرد 3 مع ولدها، وقد أخذلها ولدها.'),
(1360, 'خنذ', 'خنذ', 'خنذ', 'الخنذيذ: الخصي من الخيل، ويقال هو الطويل، قال النابغة: وبراذين كابيات وأتنا ... وخناذيد خصية وفحولا 4 وخناذيد الجبل: شعب طوال دقاق في اطرافها. والخنذيذ: البذيء اللسان. والخنذيذ: الخطيب الماهر، الفائق في كل شيء، وأنشد أبو عبيدة يصف الشاعر الخنذيد: عنا صدود البكر عن قرم هجان 1 والخناذي أيضا مثل الخناذيذ من الخيل.'),
(1361, 'خذف', 'خذف', 'خذف', 'الخذف: رميك بحصاة أو نواة تأخذها بين سبابتيك وتخذف بها أي ترمي. والمخذفة من خشب ترمي بها بين إبهامك والسبابة. وناقة خذوف: سريعة. والخذفان: ضرب من السير للإبل.'),
(1362, 'فخذ', 'فخذ', 'فخذ', 'الفخذ: وصل ما بين الورك والساق، ويخفف فيقال: فخذ في لغة سفلى مضر، وهي مؤنثة، وكسرت الفاء على أعقاب كسرة الخاء حيث اسكنت، ومن فتحها مع سكون الخاء تركها على ما كانت، كما قالوا في العقب عقب فلزموا الفتحة، وفي الكتف كتف فلزموا الكسرة. وفخذ الرجل فهو مفخوذ أي كسرت فخذه. وفخذ الرجل: نفره من حيه الذين هم أقرب عشيرته إليه. وهي أفخاذ العرب يذكر، وإذا أفرد قيل: هذا فخذ أي: هذا حي.'),
(1363, 'بذخ', 'بذخ', 'بذخ', 'البذخ: التطاول والافتخار، بذخ يبذخ بذخا وبذوخا. ورجل باذخ وبذاخ، قال: أشم بذاخ نمتني البذخ 1 وجبل باذخ: طويل، وجمعه بواذخ وباذخات، وقد بذخ بذوخا. وأنا أبذخ منه أي: أفخر وأعز.'),
(1364, 'خذم', 'خذم', 'خذم', 'الخذم: سرعة القطع والسير. وفرس خذم: سريع، اسم له لازم لا يشتق منه فعل. وقد خذم يخذم خذما 2 وأما الإجذام بالجيم فله فعل، والإجذام: السرعة. وسيف خذوم مخذم أي قاطع، والقطعة خذامة. ورجل خذم: طيب النفس. والخذمة: سمة الناس إبلهم، والخذمة: سمة الشاة، وتشق من عرض الأذن. ورجل خذم العطاء، أي: جواد سمح.'),
(1365, 'خرث', 'خرث', 'خرث', 'الخرثي من المتاع والغنائم: أردؤها، وهو اسقاط البيت وشبهه، وجمعه خراثي. والخرثاء: النمل الذي فيه حمرة، والواحدة خرثاءة.'),
(1366, 'خثر', 'خثر', 'خثر', 'خثر 1 الشيء يخثر خثورة، وخثارته: بقيته. وأخثرته وخثرته. ويقال: خاثر النفس، وخثرت نفسه.'),
(1367, 'ثلخ', 'ثلخ', 'ثلخ', 'ثلخ البقر ثلخا، وهو خراؤه إذا خالطه الرطب أيام الربيع.'),
(1368, 'ثخن', 'ثخن', 'ثخن', 'ثخن الشيء ثخانة والرجل الحليم الرزين: ثخين. والثوب المكتنز اللحمة والسدى- من جودة نسجه-: ثخين. وقد أثخنته أي: أثقلته. وأثخن الرجل إذا اتخذ شيئا ثخينا، أو ما به ثخانة وثخن.'),
(1369, 'خنث', 'خنث', 'خنث', 'الخنثى: وهو الذي ليس بذكر ولا أنثى، ومنه أخذ المخنث. ويقال: بل سمي لتكسره كما يخنث السقاء والجوالق إذا عطفته. وخنثت فم القربة فانخنثت هي. ويقال للمخنث: يا خناثة ويا خنيثة. ويقال للرجل: يا خنث، وللمرأة: يا خناث، على بناء: لكع ولكاع. وتخنث: فعل فعلهم. والخنث: باطن الشدق عند الأضراس من فوق وأسفل. ونهي عن اختناث الأسقية، وهو كسر أفواهها.'),
(1370, 'خبث', 'خبث', 'خبث', 'خبث الشيء خباثة وخبثا فهو خبيث. وأخبث فهو مخبث: صار ذا خبث وشر. والخابث: الرديء. وأخبث القول ونحوه. والخبيث: نعت كل شيء فاسد، خبيث الطعم، وخبيث اللون. والخبثة: الزنية 1 من الفجور، ويقال: هذا ولد الخبثة وولد لخبثة. وخبث الحديد وغيره: مما يذاب بالنار، وهو ما يبقى من رداءته إذا أخلص جيده. ويقولون للرجل: يا خبث، وللمرأة: يا خباث. وهو من أخابث الناس، واحدها أخبث. ويقولون للرجل والمرأة: يا مخبثان، وهو من الخبث والأخابث والخبائث والتخبث. وغلام خباثي (برفع الخاء) أي خبيث. ويقال: به الأخبثان وهما البخر والسهر.'),
(1371, 'خثم', 'خثم', 'خثم', 'الخثمة في أنف الثور، وثور أخثم وبقرة خثماء. والخثمة: غلظ وقصر 2 وتفرطح، قال النابغة: وإذا لمست لمست أخثم جاثما ... [متحيزا بمكانه ملء اليد] 3 يصف الركب، وقد خثم خثما. وناقة خثماء، وخثمها: استدارة خفها وانبساطه وقصر مناسمه، وبه شبه الركب لاكتنازه. ومثله الأخث، وهو من الخثم إلا أنه مستو. وخيثمة وخيثم من أسماء الرجال.'),
(1372, 'رخل', 'رخل', 'رخل', 'الرخل لغة في الرخل، وجمعه رخلان والرخال بالضم لا غير، هو الأنثى من أولاد الضأن.'),
(1373, 'خنر', 'خنر', 'خنر', 'الخنور: قصب النشاب، قال: يرمون بالنشاب ذي الآذان ... في القصب الخنور 1 ويقال: الخنور كل شجرة رخوة خوارة، ويقال: إنما هو الخوار فزيد النون فيه، والنون من الحروف العسرة.'),
(1374, 'نخر', 'نخر', 'نخر', 'نخر الحمار بأنفه نخيرا أي: مد نفسه في الخياشيم كأنه نغمة خاء 1 مضطربة. ونخرتا الأنف خرقاه. والمنخر لجميع الأنف، والقياس منخر بفتحة الخاء، ولكن أراد منخير، وفي منتن منتين، قال: إني زعيم لك أن تزهري ... عن وارم الجبهة ضخم المنخر وقال: صياما تذب البق عن نخراتها ... بنهز كإيماء الرءوس الموانع 3 ونخرت الخشبة أي: بليت فاسترخت حتى تفتتت إذا مست، (وكذلك العظم الناخر) 4 . والنخور: الناقة التي لا تدر حتى تدخل إصبعك في أنفها. وقوله تعالى: عظاما نخرة 5 من نخر العظم أي بلي ورم.'),
(1375, 'خرف', 'خرف', 'خرف', 'خرف الشيخ 6 خرفا، وأخرفه الهرم، (فهو خرف) 7 . وخرف الرجل يخرف أي: أخذ من طرف الفواكه، والأسم الخرفة. وأخرفته نخلة: جعلتها خرفة له يخترفها. والمخرف كالزبيل يخترف فيه من أطايب الترطب، واسم تلك النخلة التي تعزل للخرفة الخريفة، وتجمع خرائف. وأخرف النخل وهو مخرف مثل أجز البر. والخروف: الحمل الذكر، وجمعه الخرفان، والعدد 1 أخرفة، واشتقاقه أنه يخرف من هنا وهنا وبه سمي الخريف، لأنه يخرف فيه كل شيء أي يؤخذ ويجتني في حينه، فهو ثلاثة أشهر بين آخر القيظ وأول الشتاء. وإذا مطر القوم في الخريف قيل: خرفوا. ومطر الخريف هو الخزفي، قال: وجوازل مخروفة وبراغز ... محبورة ومكللان وعوهج 2 والخرافة: حديث مستملح كذب. وخرفت فلانا: حدثته بالخرافات. ومخرفة النعم، قال الهذلي: 3 فاجزته بأفل تحسب أثره ... نهجا أبان بذي فريغ مخرف'),
(1376, 'رخف', 'رخف', 'رخف', 'الرخفة: الزبدة، أسم لها، قال: تضرب دراتها إذا شكرت ... تأقطها والرخاف تسلؤها 4 وسميت رخفة لرقتها. وأرخفت العجين وأورخته إذا أكثرت ماءه حتى يسترخي، وقد رخف يرخف رخفا وورخ ورخا، وأسم ذلك العجين الرخف.'),
(1377, 'فرخ', 'فرخ', 'فرخ', 'فرخت الحمامة تفريخا، واستفرخناها أي اتخذناها للفرخ. وأفرخ الطائر: صار ذا فرخ، وأفرخ البيض: خرج فرخه. وأفرخ الأمر وفرخ أي: استبان عاقبته بعد اشتباه. وأفرخ الروع إذا أمن. ويقال للفرق (الرعديد) 1 : فرخ تفريخا، وكذاك الشيخ إذا رعب، قال: [و] ما رأينا معشرا فينتخوا ... من شنأ الأقوام إلا فرخوا 2 قوله: فينتخوا من النخوة. وفروخ من ولد إبراهيم- ع- كثر نسله ونمى 3 عدده، وهو الذي ولد العجم الذين هم في وسط البلاد يعني: العراق. والفرخ: الزرع إذا تهيأ للانشقاق، والزرع ما دام في البذر فهو الحب ثم الفرخ فإذا طلع رأسه فهو الحقل، وقد أحقل الزرع. وإذا صارت الحقلة حقلتين سمي مشعبا، وقد شعب الزرع تشعيبا.'),
(1378, 'خفر', 'خفر', 'خفر', 'الخفر: شدة الحياء، وامرأة خفرة: حيية متخفرة. وخفير 4 القوم: مجيرهم الذي هم في ضمانه ما داموا في بلاده، قال: لا يجوزن أرضنا مضري بخفير ولا بغير خفير 5 . قال الضرير: الخفرة الضمان، وخفرت الرجل أي: أجرته، قال يخفرني سيفي إذا لم أخفر 1 يقول: يمنعني. وهو يخفر القوم خفارة، قال: شمر تشمره وأخفر خفارته ... فإن من منع الجيران خفار 2 . وقال: كل له جارة يحمي خفارتها ... والماء سيان ممجوج ومشروب 3 وممجوج: تمجه فتصبه من فيك. والخفارة: الذمة، وانتهاكها: إخفارها، وأخفر الذمة أي: لم يف لمن يجير. والخفور: الإخفار نفسه من نفسه من قبل المخفر، ومن غير فعل على خفر يخفر، قال: فواعدني وأخلف ثم ظني ... وبئس خليقة المرء الخفور 4'),
(1379, 'فخر', 'فخر', 'فخر', 'فخيرك: مفاخرك كالخصيم، تقول: فاخرته ففخرته، وهو نشر المناقب وذكر الكريم بالكرم. ورجل فخير: كثير الافتخار، قال: يمشي كمشي الفرح الفخير 5 والفخير: المفخور. والفاخر: الجيد. والفاخور: ضرب من الريحان، له مرو، وما عرض ورقه، وخرجت جماميحه، يعني رءوسه، في وسطه كأطراف أذناب الثعالب، نورها أحمر، طيب الريح، يسميه أهل البصرة ريحان الشيوخ ويزعم أطباؤهم أنه يقطع السبات 1 . وناقة فخور أي غزيرة، تعطيك ما عندها من اللبن، ولا بقاء للبنها، بل يقال: هي العظيمة الضرع وليس بما يظن من لبن. واستفخرت الثوب: اشتريته فاخرا، وكذلك في التزويج. وأفخرت المرأة: ولدت فاخرا فقد يكون في الفخر من الفعل ما يكون في المجد إلا أنك لا تقول: فخير مكان مجيد ولكن فخور، ولا أفخرته مكان أمجدته.'),
(1380, 'خرب', 'خرب', 'خرب', 'يقال: خراب، وثلاثة أخربة، والجميع: خرب كالكلمة والكلم، ولغة تميم: خرب وكلم الواحدة: خربة (وكلمة) 2 . وخرب خرابا وخربته تخريبا. وفي الدعاء: اللهم مخرب الدنيا ومعمر الآخرة أي خلقتها للخراب. والخروبة: شجرة الينبوت. والخرب: الذكر من الحباري، ويجمع على خربان والخربة: سعة خرت الأذن، (وأهل السند خرب) 3 . وامرأة خرباء وعبد أخرب، والخرب مصدر الخربة. والخربة أيضا: شرمة أي: شق في ناحية، ويقال: ربما كانت في ثغر الدابة. والخربة أيضا: عروة المزادة، وكل ثقبة مستديرة فهي خربة، وكذلك من الدلو الذي فيه عروة العرقوة. والخارب: اللص. وما رأينا من فلان خربا وخربة أي: فسادا في دينه أو شينا. وخريبة: موضع بالبصرة يسمى بصيرة الصغرى. والخارب من شدائد الدهر، قال: إن بها أكتل أو رزاما ... خويربان ينقفان الهاما 1 والأكتل والكتال هما شدة العيش، والرزام: الهزال، ويقال: أكتل ورزام أسما 2 لصين، واللص: من شدائد الدهر، لأنه يستأصل أموال الناس. والخرابة: جبل من ليف ونحوه. وخرابة الإبرة: خرتها. والخرخوب: الناقة الخوارة الكثيرة اللبن في سرعة انقطاع 3 .'),
(1381, 'برخ', 'برخ', 'برخ', 'البرخ: ضرب بالسيف يقطع بعض اللحم. والبرخ: الرخيص بلغة عمان. والبرخ: الحرب، وأهل عمان يقولون: كيف اسعاركم؟، فيقول المجيب: برخ، هكذا، أي: رخيص. وقول رؤبة: ولو أقول برخوا لبرخوا ... لمار سرجيس وقد تدخدخوا 1 قوله: برخوا أي بركوا، أخذها من النبطية.'),
(1382, 'ربخ', 'ربخ', 'ربخ', 'الربوخ: المرأة يغشى عليها عند الملامسة، يقال: ربخت تربخ ربوخا وربخا، وأربخت إرباخا فهي ربوخ. ومربخ: رمل بالبادية، وربخت الإبل في المربخ أي فترت في ذلك الرمل من الكلال، قال: أمن حبال مربخ تمطين 2 ... لا بد منه فانحدرن وأرقين 3 أو يقضي الله صبابات الدين 4 ... وقد قطعت الرمل إلا حبلين 5 حبلي زرود والذي بالغربين وعن الضرير: مربخ: أحد حبال الشقيق وهي خمسة أحبل: حبلا زرود وحبل الغرب ومربخ وحبل الطريدة. قال الضرير: وأوعرها مربخ، وهذه الحبال تحبلت من عالج. ورجل ربيخ أي ضخم، قال الشاعر: فلما اعترت طارقات الهموم ... فعت الولي وكورا ربيخا 1'),
(1383, 'خبر', 'خبر', 'خبر', 'أخبرته وخبرته، والخبر: النبأ، ويجمع على أخبار. والخبير: العالم بالأمر. والخبر: مخبرة الإنسان إذا خبر أي جرب فبدت أخباره أي أخلاقه. والخبرة: الاختبار، تقول: أنت أبطن به خبرة، وأطول به عشرة. والخابر: المختبر المجرب، والخبر: علمك بالشيء، تقول: (ليس لي به خبر) 2 . والخبار: أرض رخوة يتتعتع فيها الدواب، قال: يتعتع بالخبار إذا علاه ... ويعثر في الطريق المستقيم 3 والخبر والمخابرة: أن تزرع على النصف أو الثلث ونحوه، والأكار: الخبير، والمخابرة: المؤاكرة. الخبراء: شجر في بطن روضة يبقى الماء فيها إلى القيظ، وفيها ينبت الخبر وهو شجر السدر والأراك، وحواليها عشب كثير. ويقال: الخبرة أيضا، والجميع خبر، وخبر الخبرة: شجرها، قال: فجادتك أنواء الربيع وهللت ... عليك رياض من سلام ومن خبر والخبر من مناقع الماء: ما خبر المسيل في الرءوس، فيخوض الناس فيه.'),
(1384, 'بخر', 'بخر', 'بخر', 'البخر: ريح كريهة من الفم، بخر الرجل فهو أبخر وامرأة بخراء. والبخر- مجزوم- فعل البخار، بخرت القدر تبخر بخارا وبخرا. وكل شيء يسطع من ماء حار فهو بخار. وكذلك من الندى. والبخور: دخنة يتبخر بها. وبنات بخر وبنات مخر سحابات بيض، الواحدة بنت بخر وبنت مخر اشتق من بخار البحر لأن هذه السحاب تعلو في البحر ولا تجوز إلى البر.'),
(1385, 'خرم', 'خرم', 'خرم', 'خرم الرجل، (فهو مخروم) 1 . وخرم أنفه يخرم خرما فهو أخرم، وهو قطع من الوترة أو الناشرتين أو في طرف الأرنبة لا يبلغ الجدع. والفعل: خرمته خرما وشرمته شرما، وخرم من قبله وشرم. وإن أصاب ذلك أو نحوه في الشفة وفي أعلى الأذن فهو خرم. والناشرتان هما المنخران. والخرم أيضا ما خرم سيل، أو طريق في خف أو راس جبل. واسم ذلك الموضع- إذا اتسع-: مخرم كمخرم العقبة ومخرم المسيل. والخرم: أنف الجبل، وهي الخروم، ومنه اشتق المخرم. وأخرم الكتف: محز في طرف عيرها مما يلي الصدفة، وجمعه: أخارم. واخترم فلان أي ذهب فمات، واخترمته المنية من بين أصحابه. والأخرم من الشعر: ما كان في صدره وتد مجموع الحركتين فخرم أحدهما وطرح، كقوله: إن امرأ قد عاش تسعين حجة ... إلى مثلها يرجو الخلود لجاهل وتمامه: وإن امرأ.'),
(1386, 'رخم', 'رخم', 'رخم', 'أرخمت النعامة والدجاجة على بيضها إذا حضنت على بيضها فهي مرخم. ورخمها أهلها: الزموها بيضها. والرخمة: شبه النسر في الخلقة إلا أنها مبقعة ببياض وسواد، وجمعه: رخم. والرخام: حجر أبيض رخو. والرخامى: نبات أغبر يضرب إلى البياض (وهي بقلة) 1 حلوة أصلها أبيض كأنه العنقر إذا انتزعته حلب لبنا تجد به السوام. والرخام: جبل بعينه. والرخامة: لين حسن في منطق النساء. وقد رخمت رخامة فهي رخيمة الصوت، وقد رخم كلامها وصوتها، ويقال ذلك للمرأة والخشف 2 . وشاة رخماء: في رأسها أو وجهها بياض وسائرها لون آخر. ورجل رخيم وأبح وأصحل أي: ضعيف الصوت.'),
(1387, 'مرخ', 'مرخ', 'مرخ', 'المرخ: مرخك إنسانا بالدهن. ورجل مرخ: كثير الإدهان. والمرخ: شجر سريع الورى. والمريخ: والمريخ سهم طويل يقتدر 1 به الغلاء، قال: أو كمريخ على شريانة ... حشه الرامي بظهران حشر 2 والمريخ من الكواكب بهرام 3 . والمريخ: المرتك 4 ، وإذا انكسر القرن وبلغ إلى العظم الأبيض فذلك العظم المريخ، وجمعه: أمرخة.'),
(1388, 'رمخ', 'رمخ', 'رمخ', 'الرمخ: من أسماء الشجر 5 المجتمع.'),
(1389, 'مخر', 'مخر', 'مخر', 'مخرت السفينة مخرا ومخورا، فهي ماخرة، وهن مواخر إذا استقبلت بها الريح. وفي بعض [وجوه] 6 التفسير مواخر 7 [أي] 8 مقبلة ومدبرة بريح واحدة. والفرس يستمخر الريح ويمتخرها ليكون أروح له أي: يستقبلها. وفي الحديث: استمخروا الريح وأعدوا النبل 9 يعني في الاستنجاء واجعلوا القبلة عن اليمين أو عن الشمال. ومخرت الأرض مخرا فهي ممخورة أي: أرسلت فيها الماء في الصيف ليطيبها. ومخرت الأرض فهي مخورة أي طابت من ذلك الماء. وامتخرت القوم: انتقيت خيارهم ونخبتهم، قال العجاج: من نخبة القوم الذي كان امتخر 1 أي: اختار. وبنات مخر وبنات بخر: سحابات تنشأ بالبادية من قبل البحر، بيض، بعضها أكبر من بعض، والقطعة بنت مخر، بالميم أكثر. والماخور: مجلس الريبة ومجتمعه، وربما قيل للرجل: ماخور، قال زياد بن أبيه حين قدم البصرة عاملا بها: ما هذه المواخير المنصوبة؟ الشراب عليها حرام حتى تسوى بالأرض هدما و [إحراقا] 2 . وجمل يمخور العنق أي: طويل، قال: في شعشعان عنف يمخور 3 أي: كأنه يعوم في الماء.'),
(1390, 'خمر', 'خمر', 'خمر', 'اختمر الخمر أي: أدرك، ومخمرها 4 متخذها، وخمرتها: ما غشي المخمور من الخمار والسكر، قال: فلم تكد تنجلي عن قلبه الخمر 5 واختمر الطيب والعجين خمرة ووجدت منه خمرة طيبة إذا اختمر الطيب أي: وجد طيبه. والشارب يصيبه خمرة، وقد خمر وخمر. وخمرت العجين والطيب: تركته حتى يجود. واختمرت المرأة بالخمار، والخمرة: الاختمار، وهما مصدران. والمختمرة من الضأن: السوداء ورأسها أبيض، ومن المعز أيضا. وأخمره البيت: ستره، وخمرت البيت أي: سترته. والخميرة فتاق الخمير. وخامرة الداء: خالط جوفه، قال: هنيئا مريئا غير داء مخامر ... لعزة من أعراضنا ما استحلت 1 وخمرت الإناء: غطيته، قال رسول الله- ص-: خمروا شرابكم ولو بعود 2 . وفي الحديث: لا تجد المؤمن إلا من إحدى ثلاث: في مسجد يعمره، أو بيت يستره أو معيشة يدبرها. والمستخمر: الشريب، هذلية. ودخل في غمار الناس وخمارهم، ودخل في خمار الناس وخمرهم أي: جماعتهم فخفي فيهم. والخمر: وهدة يختفي فيها الذئب، قال: فقد جاوزتما خمر الطريق والخمرة: شيء منسوج مثل السعف أصغر من المصلى. واستخمرت فلانا: استعبدته. وخمرت الدابة أخمرها: أسقيتها خمرا. والخمر أن تخرز ناحيتا أديم المزادة، ثم يعلى بخرز آخر فذاك الخمر.'),
(1391, 'لخن', 'لخن', 'لخن', 'لخن السقاء أي: أديم فيه صب اللبن ولم يغسل، وصار فيه تحبيب أبيض- قطع صغار مثل السمسم وأكبر منه- متغير الريح والطعم. ويقال: لخنت الجوزة تلخن لخنا فهي لخناء أي فسدت. ولخن الأديم في دباغه أي: فسد. والألخن واللخناء هما اللذان لم يختنا، ويقال: هما اللذان يرى في قلفتيهما قبل الختان بياض عند انقلاب الجلدة شبه الكرج 1 .'),
(1392, 'نخل', 'نخل', 'نخل', '[النخلة: شجرة التمر، والجماعة: نخل] ونخيل.. وثلاث نخلات. ونخيلة: موضع بالبادية. وذات نخل: موضع بالعراق، وبطن نخلة بالحجاز. والنخل: تنخيل الثلج والودق. وانتخلت ليلتنا الثلج، أو مطرا غير جود. وإذا نخلت اشياء 2 لتستقصي أفضلها قلت: نخلت وانتخلت. فالنخل: التصفية، والانتخال: الاختيار لنفسك، أفضله وهو التنخل أيضا، قال: تنخلتها مدحا لقوم ولم أكن ... لغيرهم فيما مضى أتنخل 1'),
(1393, 'لخف', 'لخف', 'لخف', 'اللخاف واحدتها لخفة، وهي حجارة بيض دقاق، قال زيد بن ثابت: كنت أجمع القرآن من اللخاف وصدور الرجال.'),
(1394, 'خلف', 'خلف', 'خلف', 'الخلف: حد الفأس- تقول: فأس ذات خلفين، وذات خلف، وجمعه خلوف. وكذلك المنقار الذي يقطع به الحجر. والخلف: أصغر ضلع يلي البطن، وجمعه خلوف، وهو القصيري، قال طرفة: وطي محال كالحني خلوفه 2 ... [وأجرنة لزب بدأي منضد] والخلف من الأطباء: المؤخر، والقادم هو المقدم، ويقال: الخلف: الضرع نفسه، والقادمان والآخران المتقدمان والمتأخران، والجميع: الأخلاف، قال: كأن خلفيها إذا ما درا 3 وخلوف فم الصائم نكهته في غبه. وخلاف رسول الله- ص-: مخالفته في القرآن. ورجل خالف 4 وخالفة أي: يخالف، ذو خلاف، وخلفة. واختلفت اختلافة واحدة. والخلاف بمنزلة بعد، ومنه قوله تعالى: لا يلبثون خلافك 1 أي بعدك [ويقرأ] 2 : خلفك، وقال الحارث بن خالد المخزومي: خلت الديار خلافهم فكأنما ... بسط الشواطب بينهن حصيرا 3 . الشواطب: اللواتي يعملن 4 الحصر، الواحدة: شاطبة. والخلاف شجر، والواحدة: خلافة 5 . ويقال: جاء الماء ببزره فنبت مخالفا لأصله فسمي خلافا. والخلف: الخليفة بمنزلة مال يذهب فيخلف الله خلفا، ووالد يموت فيكون ابنه خلفا له، أي خليفة فيقوم مقامة. والخلف: القرن 6 من الناس، ويجمع على خلوف. والخلف: خلف سوء بعد أبيه، قال لبيد: ذهب الذين يعاش في أكنافهم ... وبقيت في خلف كجلد الأجرب 7 والخلف: من الصالحين، ولا يجوز [أن يقال] : من الأشرار خلف، ولا من الأخيار خلف. وفي الحديث: في الصالحين كل خلف عدوله. قال الضرير: يقول: يحمل هذا العلم من كل خلف عدوله. يعني من كل قوم يحمله العدول من كل خلف من الناس. والخلف: مصدر قولك: أخلفت وعدي، وأخلف ظني. ولحم خالف: به رويحة، ولا يأس بمضغه، وقد خلف يخلف، ومنه اشتق خلوف الفم يقال: خلف ريح فمه، أي: تغير. وقوله تعالى: رضوا بأن يكونوا مع الخوالف* 1 يعني النساء. والخلف: قوم يذهبون من الحي يستقون وخلفوا أثقالهم، يقال: أبيناهم وهم خلوف أي غيب، قال أبو زبيد: أصبح البيت بيت آل إياس ... مقشعرا والحي حي خلوف 2 ويقال: بعتنا فلانا يخلف لنا أي يستقي فهو مخلف. والخلفة والإخلاف: الاستقاء، يقال: من أين خلفتكم؟ ويقال للقطا مخلفات لأنها تستخلف لأولادها الماء وتخلف، قال ذو الرمة: [كأني ورحلي فوق أحقب] لاحه ... من الصيف شل المخلفات الرواجع 3 والمخلاف: الكورة، بلغة أهل اليمن، ومخاليفها: كورها. والخليفة: من استخلف مكان من قبله، ويقوم مقامه، والجن كانت عمار الدنيا فجعل الله آدم وذريته خليفة منهم، يعمرونها، وذلك قوله- عز أسمه-: إني جاعل في الأرض خليفة 4 . وقال تعالى: هو الذي جعلكم خلائف* 5 أي: مستخلفين في الأرض. والخالفة: الأمة الباقية بعد السالفة، قال: كذلك يلقاه القرون السوالف 6 يعني الموت. والمخلف: الغلام إذا راهق الحلم. وخلف فلان بعقب فلان إذا خالفه إلى أهله. وخلفك الله بأحسن الخلافة، وفلان يخلف فلانا في عياله بخلافة حسنة. وإذا تمت للإبل بعد البزول سنة قيل: مخلف عام، ومخلف عامين، ومخلف ثلاثة أعوام، فإذا جاوز ذلك أخذ في الانتقاص. والمتوشح يخالف بين طرفي ثوبه. والخلفة: ما أنبت الصيف من العشب بعد ما يبس من الربعي، ومنه سمي زرع الحبوب خلفة لأنه يستخلف من البر والشعير. والخلفة: مصدر الاختلاف، ومنه قوله تعالى: جعل الليل والنهار خلفة لمن أراد 1 يقول: إن فاته أمر بالنهار من العبادة تداركه بالليل، وإن فاته بالليل تداركه بالنهار. والخليفان من الإبل كالابطين من الناس. والخلفة من النوق: الحامل، والخلفات جماعة، فإذا جمعت الخلفات قلت لهن: مخاض إلى مطلع سهيل، ثم قيل: لهن متلئة، وإتلاؤها: أن تعظم بطونها وتثقل. والخليف: فرج بين قنتين أو بين حبلين- متدان قليل العرض والطول، وسد 2 القارة والقنة ونحوهما، وليس بشعب، لان الشعب يكون بين الجبال الطوال، وليس في الرمل شعب ولا خليف، وربما كثر نبته. والخليفي على بناء هجيري: الخلافة، ومثله جاءت أحرف [نحو] 1 : رديدي من الرد، ودليلى من الدلالة، وخطيبى من الخطبة، وحجيزي من حجزت 2 ، وهزيمي من الهزيمة. والخليف: مدافع الأودية، ومن الطريق افضلها لأنك لا تضل فيه، وهو جدد، وإنما ينتهي المدفع إلى خليف يفضي إلى سعة. والبوانان 3 هما الخالفتان، وهما عمودا البيت، وأحدهما خالفة. ورجل خالفة: كثير الخلاف، وقوم خالفون كقولك: رجل راوية ولحانة ونسابة إذا كان النعت واحدا فإذا جمعت قلت: خالفون وراوون. وأدخلت الهاء لانه نعت واجب لازم له، وكذلك المرأة، وهذا في مكان له فعل يفعله. وإذا كان النعت فاعلا ولا فعل له [كان] 4 بغير الهاء، الذكر والأنثى سواء كقولك: رجل رامح ورجل كاس وامرأة رامح وامرأة كاس أي: معهما رماح وأكسية ونحوه. والواجب في نعت النساء ربما ألقيت منه الهاء للوجوب.'),
(1395, 'خلب', 'خلب', 'خلب', 'الخلب: مزق الجلد بالناب. والسبع يخلب الفريسة إذا شق جلدها بناب أو مخلب. ولكل طائر من الجوارح مخلب، ولكل سبع مخلب ... وهو أظافيره. والمخلب: المنجل، ويقال: هو المنجل الذي لا أسنان له لقطع سعف النخل وشبهه، قال النابغة الجعدي: قد أفناهم القتل بعد الوفاة ... كهذ الإشاءة بالمخلب 1 والخلب: ورق الكرم والعرمض ونحوه. والخلب: حبل دقيق صلب الفتل من ليف أو قنب أو شيء صلب، قال: كالمسد اللدن أمر خلبه 2 والخلب: الطين والحمأة، ويقال: الطين الصلب نحو: طين لازب خلب. وفي بعض الشعر: في ماء مخلب 3 أي صار طينه خلبا، قال تبع يصف ذا القرنين 4 . فرأى مغيب الشمس عند مآبها ... في عين ذي خلب وثاط حرمد والثأط: الطين الرخو. والخلابة: المخادعة، وفي الحديث: إذا تبايعتم فقولوا: لا خلابة 5 . والخلابة: أن تخلب المرأة قلب الرجل بألطف القول وأخلبه. وامرأة خلابة أي: مذهبة للفؤاد، وكذلك خلوب. ورجل خلبوت أي ذو خديعة اختلاب للشيء، قال: ملكتم فلما أن ملكتم خلبتمو ... وشر الملوك: الخالب الخلبوت 1 وبرق خلب: يومض ويرجع ويرجى أن يمطر ثم يعدل عنك، وكذلك اليلمع. وخلبت المرأة خلبا فهي خلباء وخرقاء في عملها بيديها، وكذلك الخلبن. ويقال للمرأة المهزولة: خلبن أيضا، ويجمع خلابن، قال رؤبة: وخلطت كل دلاث علجن ... تخليط خرقاء اليدين خلبن 2 والمخلب من الثياب: الكثير الوشي، قال لبيد 3 : [وغيث بدكداك يزين وهاده ... نبات] كوشي العبقري المخلب'),
(1396, 'بلخ', 'بلخ', 'بلخ', 'البلخ مصدر الأبلخ، وهو العظيم في نفسه، الجريء على ما أتى من الفجور. وامرأة بلخاء، وقال: تعقل مرات ومرا تبلخ 4 وقال: فقال: سما للجرح [جلد، و] أبلخ ... أخو نكرات كان للبغي جانيا 5 والبلخاء: التي دخلها الزهو من كرمها 6 .');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1397, 'لبخ', 'لبخ', 'لبخ', 'اللبخ: احتيال لأخذ شيء. واللبخ من الضرب والقتل، يقال: لبخه الله بشر، ولبخه [فلان] بالعصا. واللبوخ: كثرة لحم الجنب 1 . واللبيخ: النعت. وامرأة لباخية أي: ضخمة الربلة كثيرة اللحم، قال عبهرة الخلق لباخية ... تزينه بالخلق الظاهر 2'),
(1398, 'بخل', 'بخل', 'بخل', 'بخل بخلا وبخلا فهو بخيل، بخال، مبخل. والبخلة: بخل مرة واحدة، قال عدي بن زيد: وللبخلة الأولى لمن كان باخلا ... أعف ومن يبخل يلم ويلهد 3'),
(1399, 'خبل', 'خبل', 'خبل', 'الخبل: جنون أو شبهه في القلب، ورجل مخبول: به خبل، وهو مخبل أي: لا فؤاد له، وقد خبله الدهر والحزن والشيطان 4 والحب والداء خبلا. وقد خبل: خبالا، ورجل أخبل. ودهر خبل: ملتو على أهله، لا يرون فيه سرورا. والخبل: فساد في القوائم حتى لا يدري كيف يمشي، فهو متخبل خبل. ومختبل الدابة فعله، ومختبلها: قوائمها، واختبالها: ألا تثبت في مواطئها، قال أبو النجم: لما رأيت الدهر جما خبله 1 وبه خبال أي: مس وشر، قال الله تعالى: لا يألونكم خبالا 2 أي شرا. وهو خبال على أهله أي: عناء. وطين الخبال: ما ذاب من أجساد أهل النار 3 . والرجل تصيبه السنة فيأتي أخاه فيستخبله غنما وإبلا ينتفع بها 4 ، قال: هنالك أن يستخبلوا المال يخبلوا ... وإن يسألوا يعطوا، وإن ييسروا يغلوا 5'),
(1400, 'خمل', 'خمل', 'خمل', 'الخامل: الخفي، وخمل يخمل خمولا، وقول خامل: خفي. ويقال: هو خامل الذكر والأمر أي: لا يعرف. وفي الحديث: اذكروا الله ذكرا خاملا أي ذكرا بقول خفيض. والخميلة: مفرج بين الرمل في هبطة وصلابة (وهي) 6 مكرمة للنبات، وجمعها خمائل، قال لبيد: باتت وأسبل واكف من ديمة ... يروي الخمائل دائما تسجامها 7 والخمل- مجزوم خمل الطنفسة ونحوه. ولريش النعام خمل، ويجمع على خميل. والخمال: داء يأخذ الفرس فلا يبرح حتى يقطع منه عرق أو يهلك، قال الأعشى: لم تعطف على حوار ولم يقطع ... عبيد عروقها من خمال 1 وخميلة ريش النعام تجمع على خميل. والخملة: ثوب مخمل من صوف كالكساء له خمل. وربما أخذ الخمال في قائمة الشاة، ثم يتحول في القوائم يدور بينهن 2 . يقال: خملت الشاة فهي مخمولة. والخمل: ضرب من السمك مثل اللخم.'),
(1401, 'لخم', 'لخم', 'لخم', 'اللخم من سمك البحر، قال: كثيرة حيتانه ولخمه 3'),
(1402, 'خلم', 'خلم', 'خلم', 'الخلم: مربض الظبية أو كناسها 4 ، تتخذه مألفا وتأوي إليه. وسمي الصديق خلما لألفته، وفلان خلم فلان. والخلم: العظيم.'),
(1403, 'ملخ', 'ملخ', 'ملخ', 'الملخ: قبضك على عضلة عضا وجذبا. ويقال: امتلخ الكلب عضلته، وامتلخ فلان يده من يد القابض. (وملخت العقاب عينه وامتلختها) 1 أي أخرجتها. وامتلخت اللجام من رأس الدابة. والملاخ: الملاق. ويقال: تملخ بالباطل أي: تلهى به. ومالختها: مالقتها ولاعبتها. والمليخ: لحم لا طعم له كلحم الحوار، قال: وأنت مليخ كلحم الحوار ... لا أنت حلو ولا أنت مر 2 والفحل المليخ، وجمعه أملخه، وهو الذي ينعدل عن الشول قدورا 3 . وملخت المرأة ملخا وهو شدة الرطم.'),
(1404, 'لمخ', 'لمخ', 'لمخ', 'اللماخ: اللطام، قال: فأورخته أيما إيراخ ... قبل لماخ أيما لماخ 4'),
(1405, 'خفن', 'خفن', 'خفن', 'الخفان: رأل النعام، الواحدة بالهاء من الذكر والأنثى 5 . والخيفان: الجراد أول ما يطير، وجرادة خيفانة: أشب ما تكون، وكذلك الناقة السريعة. وخفان: أسم أرض.'),
(1406, 'خنف', 'خنف', 'خنف', 'صدر أخنف، ظهر أخنف، وخنفه: انهضام أحد جانبيه، فذلك الخنف. وخنفت الدابة تخنف بيدها في السير أي تضرب بها نشاطا، وفيه بعض الميل. يقال: ناقة خنوف ... مخناف. وجمل مخناف: لا يلقح من ضرابه، كالعقيم من الرجال 1 . والخنيف: ضرب من النبات أبيض غليظ، [جنس 2 ] من الكتان، وجمعه خنف. والخناف: لين في الأرساغ. ويقال: الخنيف الفدام، قال أبو زبيد: وأباريق شبه أعناق طير الماء ... قد جيب فوقهن خنيف 3'),
(1407, 'فنخ', 'فنخ', 'فنخ', 'الفنيخ: الرخو والضعيف. ويقال للشيخ: حوقل فنيخ، قالت أعرابية: ما لي وللشيوخ ... يمشونن كالفروخ والحوقل الفنيخ 4 وفنخته تفنيخا أي: ذللته. وفنخت رأسه فنخا: فتت العظم من غير شق ولا إدماء، قال: لعلم الجهال أني مفنخ 1'),
(1408, 'نفخ', 'نفخ', 'نفخ', '[النفخ: معروف. تقول نفخته فانتفخ] . المنفاخ: ما ينفخ به الإنسان في النار وغيرها. والنفيخ: الموكل بنفخ النار، قال: في الصبح يحكي لونه زخيخ ... من شعلة ساعدها النفيخ 2 صار النفيخ مثل الجليس والشريب ونحوهما. ويقال: هو النفيخ مثل الجليس والشريب، مخفف، ونحوهما. والنفاخ: نفخة الورم من داء يأخذ حيث أخذ. والنفخة: انتفاخ البطن من طعام ونحوه. والمنفاخ: كير الحداد. وشاب نفخ، وشابة نفخ، بغير الهاء، إذا ملأتهما نفخة الشباب. ورجل أنفخان 3 وامرأة، بالهاء، ورجل منفوخ، وقوم منفوخون أي: سمنوا في رخاوة. وفرس أنفخ، وهو انتفاخ الخصيتين من النفخ وهو داء يأخذ في الفرس. والنفاخة: هنة منتفخة في بطن السمكة، وهي نصابها، وبها تستقل السمكة في الماء وتتردد به فيما زعم. والنفاخة: الحجاة، وهي فقاعة ترتفع فوق الماء. والنفخاء من الأرض: ما ارتفع، وهي مكرمة تنبت قليلا من الشجر، ومثلها النهداء غير أنها أشد استواء. والنفاخة: ثمرة العشر، وهي كثيرة ليس لها حشو إلا الريح.'),
(1409, 'خنب', 'خنب', 'خنب', 'جارية خنبة 1 : رخيمة غنجة. ورجل خنأب، مكسور الخاء، مشدد النون، مهموز: هو الضخم في عبالة، وجمعه خنانب. ويقال: الخنأب من الرجال: الأحمق المتصرف، يختلج 2 هكذا مرة، وهكذا مرة أي: يذهب، وقال: أكوي ذوي الأضغان كيا منضجا ... منهم وذا الخنابة العفنججا والخنابة، الخاء رفع والنون شديدة، وبعد النون همزة، وهي طرف الأنف، وهما الخنأبتان. والأرنبة: هي ما تحت الخنأبة.'),
(1410, 'نخب', 'نخب', 'نخب', 'النخب: ضرب من البضع، يقال: نخبها به. والنخبة: خوق 1 الثفر. ورجل نخب: لا فؤاد له، ومثله منخوب ونخب أي: شديد الجبن، والمنخوب: الذاهب العقل. ورجل نخب في معنى منخوب من الجبن، الخاء مكسورة. ويقال للمنخوب النخب، النون مجرورة والخاء منصوبة والباء شديدة، والجميع: منخوبون، ويقال في الشعر على مناخب. والنخبة: خيار الناس، يقال: انتخبت أفضلهم (نخبة) 2 وانتخبت نخبتهم. والمنخوب: الذاهب لحمه، والمنخوب 3 بالهزال.'),
(1411, 'خبن', 'خبن', 'خبن', 'خبنت الثوب إذا رفعت ذلذلة فخطته أرفع من موضعه كي يقلص 4 كما يفعل بثوب الصبي، والفعل خبن يخبن خبنا. والخبن في المزادة: ما بين الخرب والفم، وهو ما دون المسمع، والمسمع طرف، وهو ما بينه وبين الخرب، ولكل مسمع خبنان. والمخبون من أجزاء الشعر: ما قبض من حروف مشوه مما يجوز في الزحاف فيلزم قبضه كقولك في فاعلن فعلن في القافية، أو في النصف فيلزم ذلك القبض، وذلك الشعر مخبون، والجزء مخبون. والخبنة: اسم موضع. والخبنة: تبان الرجل، وهو ذلذل ثوبه المرفوع، ويقال: رفع في خبنيه شيئا، وقد خبنت أخبن خبنا.'),
(1412, 'نبخ', 'نبخ', 'نبخ', 'النبخ: ما نفط من اليد فخرج عليه شبه قرح ممتليء ماء من العمل. فإذا اتفقأ أو يبس مجلت اليد على العمل. وكذلك من الجدري، قال زهير: 1 تحطم عنها قيضها عن خراطم ... وعن حدق كالنبخ لم تتفتق 2 يصف حدق الرال، ويقال: فراخ القطا. وقيل: النبخ الجدري نفسه وتراب أنبخ: أكدر اللون كثير، قال: جرت عليه الريح ذيلا أنبخا 3 والنبخة كالنكتة 4 . والأنبخان: العجين النباخ، يعني الفاسد الحامض، وقد نبخ العجين ينبخ نبوخا.'),
(1413, 'خمن', 'خمن', 'خمن', 'الخمن: تخمينك الشيء بالوهم والظن، وخمن يخمن خمنا، تقول: قل فيه (قولا) 5 بالتخمين، أي: بالوهم.'),
(1414, 'مخن', 'مخن', 'مخن', 'رجل مخن وامرأة مخنة: إلى القصر ما هو، وفيه زهو وخفة.'),
(1415, 'نخم', 'نخم', 'نخم', 'النخامة: ما يخرج من الخيشوم عند التنخع: نخم ينخم نخما، وهو نخم. والنخم: اللعب والغناء.'),
(1416, 'فخم', 'فخم', 'فخم', 'فخم يفخم فخامة فهو فخم أي: عبل. وفلان يفخم فلانا أي: يبجله ويجله. وتفخيم الكلام: تعظيمه. والرفع في الكلام تفخيم. وألف مفخم يضارع الواو، وقد فخم فخامة. وسيد فخم أي نبيل، وامرأة فخمة أي: نبيلة جميلة، قال: أحمد مولانا الأعز الأفخما 1'),
(1417, 'غق', 'غق', 'غق', 'تقول: غق الفار يغق غقيقا. والغراب يغق، والصقر يغق أيضا في ضرب من أصواتهما. وفي الحديث: تغق بطون الناس يوم القيامة لقرب الشمس منهم. والصقر يغقغق أيضا.'),
(1418, 'غش', 'غش', 'غش', 'غش فلان فلانا يغش غشا أي: لم يمحضه النصيحة. وتقول: لقيته غشاشا وغشاشا أي: عند مغيربان الشمس، أي: في آخر غشيشيان النهار 1 . وشرب غشاش: قليل. قال الضرير: ولقيته غشاشا أي: على عجلة. يقال منه: غاشة مغاشة، قال القطامي: على مكان غشاش ما ينيخ به ... إلا مغيرنا والمستقي العجل 2'),
(1419, 'شغ', 'شغ', 'شغ', 'الشغشغة في الشرب: التصريد، أي: التقليل، قال رؤبة: لو كنت أسطيعك لم يشغشغ 3'),
(1420, 'غض', 'غض', 'غض', 'الغض والغضيض: الطري. والغض والغضاضة: الفتور في الطرف، وغض غضا، وأغضى إغضاء أي: دانى بين جفنيه ولم يلاق. والغض: وزع الملامة 1 ، قال: غض الملامة إني عنك مشغول 2 وقال جرير: فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا 3 والغضغضة: الغيض، قال جرير: وجاش بتيار يدافع مزبدا ... أواذي من بحر له لا يغضغض 4 وهذا مثل يقول: جاش بشعر كأنه تيار يدافع موجا آخر وهو الماء.'),
(1421, 'ضغ', 'ضغ', 'ضغ', 'الضغضغة: لوك الدرداء. وتقول: أقمت عنده في ضغيغ دهره أي قدر تمامه.'),
(1422, 'غص', 'غص', 'غص', 'الغصة: شجا يغص به في الحرقدة، قال عدي بن زيد: كنت كالغصان بالماء اعتصاري 1'),
(1423, 'غس', 'غس', 'غس', 'الغس: زجر القط. والغس: الفسل من الرجال، وهم الأغساس.'),
(1424, 'سغ', 'سغ', 'سغ', 'سغسغت شيئا في التراب إذا دحدحته فيه وسغسغت الدهن باليد على الرأس، قال رؤبة: ولم يعقني عائق التسغسغ 2'),
(1425, 'غز', 'غز', 'غز', 'غزة: أرض بمشارف الشام مات بها بعض بني عبد المطلب. وأغزت البقرة فهي مغز إذا عسر حملها.'),
(1426, 'زغ', 'زغ', 'زغ', 'زغزغت به أي: سخرت به. زغزع: موضع بالشام. قال الضرير: الزغزغ والزغازغ: الأولاد الصغار.'),
(1427, 'غط', 'غط', 'غط', 'غطه في الماء يغطه غطا. والنائم 1 يغط غطيطا. والغطغطة: حكاية ضرب من الصوت. والغطاغط: السخال الإناث. والغطاط: طير أمثال القطا، ويقال: الغطاط.'),
(1428, 'غد', 'غد', 'غد', 'أغدت الإبل أي صار لها غدد بين الجلد واللحم من داء، الواحدة غدة. ويكون في الشحم وغيره، قال: لا برئت من أغدا 2'),
(1429, 'دغ', 'دغ', 'دغ', 'الدغدغة في البضع، قال الشاعر: علي إني لست بالمدغدغ 3'),
(1430, 'غت', 'غت', 'غت', 'الغت كالغط في الماء. وفي الحديث: يغتهم الله غتا بالعذاب يصف المنافقين في الفتنة. والغت: أن تتبع القول القول، والشرب الشرب.'),
(1431, 'تغ', 'تغ', 'تغ', 'والتغتغة في حكاية الحلي 1 . وفي نسخة الحاتمي: حكاية الحبلى.'),
(1432, 'غذ', 'غذ', 'غذ', 'غذ الجرح يغذ غذا إذا ورم. والإغذاذ: الإسراع في السير.'),
(1433, 'غث', 'غث', 'غث', 'أغث الرجل إذا اشترى لحما غثا وغثيثا، وفيه غثوثة. وأغث الجرح إذا أمد إغثاثا. وغثيثته: مدته، وتجمع غثاثا. وهو بين الغثوثة والغثاثة.'),
(1434, 'ثغ', 'ثغ', 'ثغ', 'الثغثغة: عض الصبي قبل أن يشقأ ويثغر، 1 قال رؤبة: وعض عض الأدرد المثغثغ 2'),
(1435, 'غر', 'غر', 'غر', 'الغر: الكسر في الثوب وفي الجلد. وغروره أي: كسوره، قال رؤبة: أطوه على غره لثوب خز نشر عنده 3 والغرة في الجبهة: بياض يغر والأغر: الأبيض. والغر: طير سود في الماء، الواحدة غراء، ذكرا كانت أو أنثى. وفلان غرة من غرر قومه. وهذا غرة من غرر المتاع. وغرة النبات رأسه، وغرة كل شيء أوله. وسرع 1 الكرم إلى بسوقه: غرته. وغرة الهلال ليلة يرى الهلال، والغرر ثلاثة أيام من أول الشهر. والغر: الذي لم يجرب الأمور مع حداثة السن، وهو كالغمر، ومصدره الغرارة، قال: أيام نحسب ليلى في غرارتها ... بعد الرقاد غزالا هب وسنانا 2 والجارية غرة غريرة. والمؤمن غر كريم، يؤاتيك مسرعا، ينخدع للينه وانقياده. وأنا غريرك منه أي: أحذركه. وأنا غريرك أي كفيلك. والطائر يغر فرخه إذا زقه. والغرر كالخطر، وغرر بماله أي: حمله على الخطر. والغرور من غر يغر فيغتر به المغرور. والغرور: الشيطان. والغار: الغافل. والغرارة: وعاء. والغرغرة: التغرغر في الحلق. والغرة: خالص من مال الرجل. وحديث عمر: لا يعجل الرجل بالبيعة تغرة أن يقتل أي لا يغرن نفسه تغرة بدخوله في البيعة قبل اجتماع الناس في الأمر. والغرغرة: كسر قصب الأنف ورأس القارورة، قال: وخضراء في وكرين غرغرت رأسها 1 قال الضرير: هو بالعين، وهو تحريك سمامها لاستحراجه، وقال: بالغين خطأ. وتغرة على تحلة، قال: كل قتيل في كليب غره ... حتى ينال القتل آل مره 2 والغرار: نقصان لبن الناقة فهي مغار، ومنه: الحديث: لا تغاتر التحية، ولا غرار في الصلاة أي لا نقصان في ركوعها وسجودها لا تغار التحية، ولا غرار في الصلاة أي لا نقصان في ركوعها وسجودها. والغرار: النوم القليل. والغرار: حد الشفرة والسيف وغير ذلك. والغرار: المثال الذي تطبع عليه نصال السهام. والغرغر: دجاج الحبش، الواحدة غرغرة.'),
(1436, 'غل', 'غل', 'غل', 'أغللت في الإهاب غللا أي أبقيت عليه شحما بعد السلخ. والغليل: حر الجوف لوحا وامتعاضا، قال: إلى الغليل ولم يقصعنه نغب 3 وغل البعير يغل غللا إذا لم يقض ريه، قال: أنقع من غلتي وأجزؤها 4 والغلان: أودية، الواحد غليل، ويقال: غال. والغل: الحقد الكامن. ورجل مغل مضب: على غل. والمغل: الخائن. والغل: جامعة يشد في العنق واليد. وفي الحديث: من النساء غل قمل، يقذفه الله في عنق من يشاء ثم لا يخرجه إلا هو ، وذلك أن العرب كانوا إذا أسروا أسيرا غلوه بالقد فربما قمل في عنقه. والغلة: الدخل. وأغلت الضيعة أي: أعطت الغلة. والغلول: خيانة الفيء، وفي الحديث. لا إسلال ولا إغلال أي: لا خيانة ولا سرقة. والغلغلة: سرعة السير، يقال: تغلغلوا فمضوا. ورسالة مغلغلة أي محمولة من بلد إلى بلد. والغلالة: شعار تحت الثوب للبدن خاصة. وغللته وغليته أيضا: من الغالية، وكلام العامة: غليته. والغلغلة كالغرغرة. والغلل: الماء بين الشجر.'),
(1437, 'غن', 'غن', 'غن', 'الغنة: صوت فيه ترخيم نحو الخياشيم يغور من نحو الأنف بعون من نفس الأنف. قال الخليل: النون أشد الحروف غنة. وقرية غناء أي: جمة الأهل والبنيان. ويجمع الأغن والغناء على غن. وهو بين الغنة أو الغنن.'),
(1438, 'نغ', 'نغ', 'نغ', 'النغنغ: موضع بين اللهاة وشوارب الحنجور. ونغنغ فلان: عرض له في نغنغه داء، قال جرير: غمز ابن مرة يا فرزدق كينها ... غمز الطبيب نغانغ المعذور 1'),
(1439, 'غف', 'غف', 'غف', 'الغفة: البلغة من كل شيء. والفأر بلغة السنور وغفته. واغتفت الخيل غفة أي: سمنت بعض السمن. والاغتفاف: تناول العلف. والغفة: شيء قليل من العلف، قال: وكنا إذا ما اغتفت الخيل غفة ... تجرد طلاب الترات مطلب 2'),
(1440, 'غب', 'غب', 'غب', 'غبت الأمور أي: صارت إلى أواخرها، قال: غب الصباح تحمد القوم السرى 3 والغب: ورد يوم وظمء يوم. وقال: زر غبا تزدد حبا. ويقال: ما يغبهم لطفي. ولهذا العطر مغبة طيبة أي: عافية. واللحم يغب غبوبا إذا تغير فهو غاب، والثمار مثله. والغبب للشاة والبقرة: ما تدلى عند النصيل. والغبغب للديك والثور. والغبب: نصب ذبح عليه في الجاهلية. قال زائدة: الغبيبة شراب يضرب بمجدح ثم يجعل في سقاء ضار يوما وليلة، فيخرج منه الزبد. وقال عرام: هو بالعين، وصحت معرفته.'),
(1441, 'بغ', 'بغ', 'بغ', 'البغبغة: حكاية صوت من الهدير، قال: برجس بغباغ الهدير البهبة 1 البغيبغة: 2 ضيعة جعفر ذي الجناحين بالمدينة.'),
(1442, 'مغ', 'مغ', 'مغ', 'المغمغة: الاختلاط، قال رؤبة: ما منك خلط الخلق الممغمغ 1'),
(1443, 'غسق', 'غسق', 'غسق', 'الغاسق: الليل إذا غاب الشفق. وغسقت عينه تغسق غسوقا وغسقا وغسقانا، قال: فالعين مطروفة لبينهم ... تغسق ما في دموعها سرع 1 أخبر أنه فاسد العين. وقوله تعالى: إلا حميما وغساقا 2 أي منتنا.'),
(1444, 'غدق', 'غدق', 'غدق', 'عين غدقة، وقد غدقت. وقوله تعالى: لأسقيناهم ماء غدقا 3 أي فتحنا عليهم أبواب المعيشة لنختبرهم بالشكر. ومطر مغدودق أي: كثير. والغيدق والغيدقان: عم. قال: جعد العناصي غبدقانا أغيدا 4 وقال: بعد التصابي والشباب الغيدق 1'),
(1445, 'غرق', 'غرق', 'غرق', 'رجل غرق وغريق: رسب في الماء، وابتلي بالدين والبلوى تشبيها به. وأغرقت النبل وغرقته: بلغت به غاية المد في القوس. والفرس إذا خالط الخيل ثم سبقها يقال: اغترقها، قال: يغرق الثعلب في شرته ... صائب الخدبة في غير فشل 2 والغرقىء: قشرة البيض الداخلة. والغرقة: القليل من اللبن، قدر قدح أو أقل. والتغريق: القتل، وكان إذا اشتد الزمان فولدت المرأة ولدا غرقته القابلة في ماء السلا، ثم تخرجه ميتا، ذكرا كان أو أنثى، فأنزل الله تعالى: ولا تقتلوا أولادكم خشية إملاق 3 . وقال: أطورين في عام غزاة ورحلة ... ألا ليت قيسا غرقته القوابل 4'),
(1446, 'غلق', 'غلق', 'غلق', 'احتد فلان فنشب في حدته فغلق أي: غضب. وغلق الرهن في يد المرتهن إذا لم يفتك. وغلق ظهر البعير لكثرة الدبر غلقا لا يبرأ. ونخلة منغلقة، قد غلقت أي: دودت أصول سعفها، وانقطع حملها. والمغلاق: المرتاج. والغلاق والغلق: ما يفتح به ويغلق. والمغلق: السهم السابع في مضعف الميسر، سمي به لأنه يستغلق ما يبقى من آخر الميسر. وفي الميسر الآخر كل سهم مغلق، قال لبيد: بمغالق متشابه أجسامها 1 والغلقة: نبات يدبغ به الأدم.'),
(1447, 'نغق', 'نغق', 'نغق', 'نغق الغراب ينغق نغيقا، صاح 2 : غيق غيق. وقيل: نغق بخير ونعب بشر وإذا قال: غاق غاق فهو النعبان يتشاءم به. ونغق ببين أيضا، قال زهير: أمسى بذاك غراب البين قد نغقا 3'),
(1448, 'غفق', 'غفق', 'غفق', 'الغفق: الهجوم على الشيء والإياب من الغيب فجأة.'),
(1449, 'غبق', 'غبق', 'غبق', 'الغبق: شراب الغبوق، والفعل الاغتباق.'),
(1450, 'غمق', 'غمق', 'غمق', 'غمق النبات غمقا إذا وجدت لريحه خمة وفسادا من كثرة الأنداء عليه.'),
(1451, 'غنج', 'غنج', 'غنج', 'الغنج: شكل الجارية الغنجة. وغنجة، بلا ألف ولام، معرفة لا تنصرف: القنفذة. وتقول هذيل: غنج على شنج أي رجل على جمل.'),
(1452, 'غلج', 'غلج', 'غلج', 'عير مغلج شلال للعانة يعني: فحل الحمر يغلج في جريه.'),
(1453, 'جغب', 'جغب', 'جغب', 'رجل جغب متجغب أي: شغب متشغب.'),
(1454, 'غمج', 'غمج', 'غمج', 'فصيل غمج: يتغامج بين أرفاغ أمه.'),
(1455, 'غطش', 'غطش', 'غطش', 'غطش الليل، وليل غاطش مطلخم. والله أغطشها. ورجل أغطش: في عينه شبه العمش.'),
(1456, 'شغر', 'شغر', 'شغر', 'شغر الكلب: رفع إحدى رجليه ليبول. وبلدة شاغرة برجليها إذا لم تمتنع من الغارة. وقول النبي- صلى الله عليه وعلى آله وسلم-: لا شغار في الإسلام ، وهو أن يزوج الرجل أخته من رجل، على أن يزوجه أخته ونحو ذلك، ولا مهر بينهما. يقال: شاغرني فلان. واشتغر المنهل أي: تباعد وصار في ناحية. ورفقة مشتغرة أي: منفردة عن السابلة. وشغار على الغارة.'),
(1457, 'شرغ', 'شرغ', 'شرغ', 'الشرغ، يخفف ويثقل،: الضفدع الصغير، ويجمع على شرغان، قال: ترى الشريريغ يطفو فوق طاحرة ... مسحنطرا ناظرا نحو الشناغيب 1'),
(1458, 'شغل', 'شغل', 'شغل', 'شغلته وشغلت به، وشغل شاغل.'),
(1459, 'شلغ', 'شلغ', 'شلغ', 'وشلغ رأسه وثلغه أي: شدخه.'),
(1460, 'نشغ', 'نشغ', 'نشغ', 'نشغت الصبي وجورا فانتشغه أي: جرعه جرعة بعد جرعة. والأسم النشوغ. ونشغ نشغا أي شهق شهقة، قال رؤبة يذكر شدة شوقه إلى رجل: عرفت أني ناشغ في النشغ ... إليك أرجو من نداك الأسبغ 1 والنشغة: تنفسة من تنفس الصعداء، نشغ ينشغ نشغا. وفي الحديث: فإذا أنابه ينشغ بفيه أي يمتص بفيه.'),
(1461, 'نغش', 'نغش', 'نغش', 'النغش والنغشان تحرك الشيء في مكانه. تقول: دار تنتغش صبيانا ورأس ينبغش صئبانا، قال الشاعر: إذا سمعت وطء الركاب تنغشت ... حشاشاتها في غير لحم ولا دم 1'),
(1462, 'شغف', 'شغف', 'شغف', 'شغف: موضع بعمان ينبت الغاف العظام، قال: حتى أناخ بذات الغاف من شغف 2 والشغاف: مولج البلغم، ويقال: غشاء القلب. وقد شغفها حبا أي: غشي القلب حبها، قال النابغة: وقد حال هم دون ذلك داخل ... دخول الشغاف تبتغيه الأصابع 3'),
(1463, 'فشغ', 'فشغ', 'فشغ', 'الفشغة: قطنة في جوف القصبة. والفشغة: ما تطاير من جوف الصوصلاة برسا، وهو نبت يقال له: صاصلى يأكل جوفه صبيان العراق. ورجل مفشغ: قليل الخير كذاب. وقد أفشغ الرجل. ورجل أفشغ الثنية أي: ناتئها. والفشاغ: نبات يتفشغ على الشجر ويلتوي ويختلط قال الشاعر: له قصة فشغت حاجبيه، ... والعين تبصر ما في الظلم 1 وتفشغ الشيب فيه: انتشر وكثر. والمفشاغ: الدرجة التي تجعل في حياء الناقة، والجمع المفاشغ.'),
(1464, 'شغب', 'شغب', 'شغب', 'الشغب: تهييج الشر. ويقال للأتان: ذات شغب وضغن 2 إذا وحمت فاستعصت 3 على الفحل.'),
(1465, 'غبش', 'غبش', 'غبش', 'الغبش: شدة الظلمة. والتغبش: الظلم.'),
(1466, 'بغش', 'بغش', 'بغش', 'تقول: أصابتهم بغشة من المطر أي: قليل.'),
(1467, 'غشم', 'غشم', 'غشم', 'الغشم: الغضب. وإنه لذو غشمشمة وغشمشمية.'),
(1468, 'شغم', 'شغم', 'شغم', 'الشغموم والشغميم: الشاب الطويل، الجلد، قال: [هيهات خرقاء إلا أن يقربها ... ذو العرش] والشعشعانات الشغاميم 1 والشغموم من الإبل: التام، الحسن المنظر، قال: واسترجفت هامها الهيم الشغاميم 2'),
(1469, 'مشغ', 'مشغ', 'مشغ', 'المشغ: ضرب من الأكل ليس بشديد.'),
(1470, 'ضغز', 'ضغز', 'ضغز', 'الضغز من السباع السيء الخلق، قال: فيها الجريش وضغز ماثل ضئز 3'),
(1471, 'ضغط', 'ضغط', 'ضغط', 'الضغط: عصر شيء إلى شيء. والضغاط: تضاغط الناس في الزحام ونحوه. والضاغط: أن يسحج المرفق أو الكركرة جنب البعير، تقول: به ضاغط، وهن ضواغط. والضغطة: غلاء الأسعار وشدة الحال، تقول: فعل ذلك ضغطة أي: أضطرارا.'),
(1472, 'ضغت', 'ضغت', 'ضغت', 'الضغت: اللوك بالأنياب والنواجذ، والثاء لغة. وقد ضغته ضغتا.'),
(1473, 'ضغث', 'ضغث', 'ضغث', 'الضغث: التباس الشيء بعضه ببعض والضغث: اللوك بالأنياب والنواجذ 1 . والأضغاث: أحلام ملتبسة. ويقال للحالم: أضغثت الرؤيا. والضغث: قبضة قضبان يجمعها أصل واحد، قال: كأنه إذ تدلى ضغث كراث 2 وضغث رأسه أي: دلكه. وناقة ضغوث: لا يدري سمنها حتى تضغث.'),
(1474, 'غرض', 'غرض', 'غرض', 'الغرض: البطان، وهو الغرضة. والمغرض للبعير كالمحزم للدابة. والإغريض: البرد، ويقال: هو الطلع، قال: وأبيض كالإغريض لم يتثلم 3 ولحم مغروض وغريض عبيط ساعته 4 . والمغروض: ماء المطر الطري، وقال لبيد: مشعشعة بمغروض زلال والغرض: الهدف. وغرضت منه غرضا أي: مللت ملالة. والمغارض واحدها مغرض أي: جوانب البطن أسفل الأضلاع.'),
(1475, 'غضر', 'غضر', 'غضر', 'وغضر الرجل بالمال والسعة أي: أخصب بعد إقتار وهو مغضور أي: مبارك. وهو في غضارة عيش وغضرائه أي: سعته. والغضارة: القطاة. والغضار: الطين اللازب. وغواضر حي من قيس، يقال: هم بنو غاضرة من بني أسد. وغاضرة سعد: بنو صعصعة. والغضور: نبات لا يعقد منه شحم. ويقال في مثل: هو يأكل غضرة ويربض حجرة 1 . ويقال: إذا بلغ في استوائه هو كمجز غضورة، لأنها إذا جزت جاء جزها مستويا 2 . والغضراء: أرض لا ينبت فيها النخل حتى تحفر، وأعلاها كذان أبيض.'),
(1476, 'ضغل', 'ضغل', 'ضغل', 'الضغيل: صوت فم الحجام إذا امتص، ضغل يضغل ضغيلا.'),
(1477, 'ضغن', 'ضغن', 'ضغن', 'الضغن والضغينة: الحقد، ضغن عليه أي: حقد. وسللت ضغينته وضغنه أي: طلبت مرضاته، قال: وأحمل في ليلي لقوم ضغينة 1 والضغن: التواء وعسر في الدابة. ودابة ضغنة إذا نزعت إلى وطنها، قال الشماخ: تسائل أسماء الرفاق عشية ... تسائل عن ضغن النساء النواكح 2 (وقال الشاعر) 3 والضغن من تتابع الأشواط والضغن: العوج، وقناة ضغنة، قال الشاعر: إن قناتي من صليبات القنا ... ما زادها التثقيف إلا ضغنا 4 وضغن إلى الدنيا أي: ركن. والاضطغان: الدوك بالكلكل. والاضطغان كالشيء تأخذه تحت حضنك، قال: كأنه مضطغن صبيا 5'),
(1478, 'غضن', 'غضن', 'غضن', 'الغضن والغضون: مكاسر جلد الجبين والنصيل والكم والدرع، قال: ترى فوق النطاق لها غضونا 1 والأغضن: الكاسر العينين خلقة، قال رؤبة: يا أيها الكاسر عين الأغضن 2 والمغاضنة: المكاسرة بالعينين. وغضنت الناقة: ألقت ولدها قبل أن ينبت الشعر، وهي الغضان. والمغضن: شيء يتخذ من عجين طبقا على طبق.'),
(1479, 'نغض', 'نغض', 'نغض', 'النغض: غرضوف الكتف. والنغضان: تنغض الرأس والأسنان في ارتجاف، نغضت أي رجفت. وفلان ينغض رأسه نحو صاحبه أي يحركه، ومنه قوله تعالى: فسينغضون إليك رؤسهم 3 . ونغض الغيم إذا كثف ثم مخض حيث تراه يتحرك بعضه في بعض متحيرا ولا يسير، قال: برق سرى في عارض نغاض 4 والنغض: الظليم الجوال. ويقال: بل هو الذي ينغض رأسه كثيرا.'),
(1480, 'غضف', 'غضف', 'غضف', 'الغضف: شجر بالهند كهيئة النخل سواء من أسفله إلى أعلاه، له سعف أخضر مغشى عليه ونواه مقشر بغير لحاء. ويقال: هو خوص المقل يجلب إلى البحرين، تتخذ منه جلال التمر. ونخلة مغضف: كثر سعفها وساء ثمرها. والأغضف من السباع: ما قد انكسر أعلا أذنيه واسترخى. وانغضفت أذنه أي استرخت من غير خلقة. وغضفت إذا كانت خلقة. وكلاب غضف: مسترخية الآذان. يقال: أذن غضفاء، وأنا أغضفها. وانغضف القوم في الغبار: دخلوا فيه، قال العجاج: وانغضفت من مرجحن أغضفا 1 وليل أغضف: تشبه ظلمته بالغبار. والغاضف: الناعم البال، ويقال: غضف يغضف غضوفا. والمغضف: المتدلي من ثمر النخل. وأغضفت النخلة، وكل شيء: تدلى ثمرها. وانغضفت البئر: تهدمت. والأغضف: الليل نفسه في قول ذي الرمة: قد أعسف النازخ المجهول معسفه ... في ظل أغضف يدعو هامه البوم 2'),
(1481, 'غضب', 'غضب', 'غضب', 'رجل غضوب وغضب وغضبة وغضب أي كثير الغضب شديده. وناقة غضوب: عبوس. والغضب: بخصة في الجفن الأعلى خلقة. والغضبة: الصخرة الصلبة المتراكمة في الجبل، المخالفة له، قال: وغضبة في هضبة ما أمنعا 1 والغضبة: جلد المسن من الوعول حين يسلخ.'),
(1482, 'ضغب', 'ضغب', 'ضغب', 'والضغيب: تضور الأرنب عند الأخذ. والسنور يضغب، وهو أن يصيح فيمد صوته.'),
(1483, 'غبض', 'غبض', 'غبض', 'التغبيض: أن يريد الإنسان البكاء فلا يجيبه.'),
(1484, 'بغض', 'بغض', 'بغض', 'البغضة والبغضاء: شدة البغض. وقد بغض بغاضة فهو بغيض. وبغض إلي بغضة وبغاضة. ونعم بك الله عينا وأبغض بعدوك عينا.'),
(1485, 'مضغ', 'مضغ', 'مضغ', 'المضاغ: كل ما يمضغ. والمضاغة: ما يبقى في الفم مما تمضغه. والمضغة: قطعة لحم. وقلب الإنسان مضغة من جسده. والمضغة: كل لحم يخلق من علقة، وكل لحمة يفصل بينها وبين غيرها عرق فهي مضيغة. وعقبة القوس الممضوغة: مضيغة. واللهزمة: مضيغة. والماضغان: أصلا اللحيين عند منبت الأضراس بحياله. والعضلة: مضيغة. والمضاغة: الأحمق. والمضغ من الأمور: صغارها.'),
(1486, 'ضغم', 'ضغم', 'ضغم', 'الضغم: عض من غير نهش. والضيغم: الأسد.'),
(1487, 'غمض', 'غمض', 'غمض', 'الغمض: ما تطامن من الأرض، وجمعه: غموض، قال رؤبة: إذا اعتسفنا رهوة أو غمضا 1 والغماض: النوم، يقال: ما ذقت غمضا ولا غماضا وما غمضت ولا أغمضت ولا اغتمضت، لغات. والغمضة: التغافل عن الأشياء. ودار غامضة: غير شارعة. وغمضت تغمض غموضا. وأمر غامض، غمض غموضا. والغامض من الرجال: الفاتر عن الحملة، قال: لا يستطيع دفعة الغوامض 1 وحسب غامض غير معروف. وخلخال غامض: غمض في الساق غموضا. وكعب غامض أيضا. ويكون التغميض في البياعة، وأغمض أي زدني لمكان الرداءة وحط عني. والغموض: بطون الأودية.'),
(1488, 'صدغ', 'صدغ', 'صدغ', 'الصداغ: سمة في الصدغ، ما بين لحاظ العين إلى أصل الأذن. والصديغ: الضعيف من الرجال. يقال: ما يصدغ نملة من ضعفه. والصديغ: الولد إلى سبعة أيام، والتين لغة. والمصدغة لغة في المزدغة، تتوسد تحت الصدغ.'),
(1489, 'دغص', 'دغص', 'دغص', 'الداغصة عظم يديص ويموج فوق رضف الركبة.'),
(1490, 'صغر', 'صغر', 'صغر', 'الصاغر: الراضي بالضيم، وصغر يصغر صغرا وصغارا. والصغر: مصدر الصغير في القدر. واصغرت الناقة وأكبرت، والإصغار حنينها الخفيض، والإكبار حنينها [الرفيع] 1 ، قالت الخنساء: حنين والهة ضلت أليفتها ... لها حنينان إصغار وإكبار 2 وتصاغرت إليه نفسه ذلا ومهانة.'),
(1491, 'رصغ', 'رصغ', 'رصغ', 'الرصغ لغة في الرسغ، وهو عظم الحافر. وقد حفر حتى رسغ أي بلغ إلى الرسغ.'),
(1492, 'صغل', 'صغل', 'صغل', 'الصغل: لغة في السغل وهو الدقيق القوائم، الصغير الجثة.'),
(1493, 'لصغ', 'لصغ', 'لصغ', 'لصغ الجلد لصوغا: يبس على العظم عجفا.'),
(1494, 'صلغ', 'صلغ', 'صلغ', 'صلغت الشاة صلوغا لغة في السلوغ.'),
(1495, 'غلص', 'غلص', 'غلص', 'الغلص: قطع الغلصمة.'),
(1496, 'غصن', 'غصن', 'غصن', 'الغصن: ما تشعب من ساق الشجرة دقها وغلاظها، وجمعه: غصون. ويجمع الغصن غصنة وأغصانا، غصنة واحدة والجميع غصن.'),
(1497, 'نغص', 'نغص', 'نغص', 'نغص الرجل نغصا إذا لم تتم له هناءته، وبالتشديد أكثر. ونغص عليه عيشه بأذى ومكروه.'),
(1498, 'غفص', 'غفص', 'غفص', 'غافصته مغافصة أي: أخذته على غرة، فركبته بمساءة، والإسم الغفصة مثل الخلسة. والغافصة من أوازم الدهر، قال: إذا نزلت إحدى الأمور الغوافص 1 وهو غفيصي إذا كان يغافصك في الأشياء.'),
(1499, 'غصب', 'غصب', 'غصب', 'الغصب: أخذ الشيء ظلما وقهرا.'),
(1500, 'صبغ', 'صبغ', 'صبغ', 'الصبغ والصباغ ما يلون به الثياب. والصبغ مصدره، والصباغة حرفة الصباغ. والصبغ والصباغ: ما يصطبغ في الأطعمة ونحوها أي يؤتدم، قال تعالى: وصبغ للآكلين 2 . وصبغة الله: الملة التي يمل بها المسلمون أي يدينون بها. والأصبغ من الطير: ما أبيض ذنبه، والأسم الصبغة. وصبغت الناقة لغة في سبغت، يعني: جاءت بولدها تاما والمصبغ: المكان الذي يصبغ فيه، والمصدر المصبغ أيضا، يقال: صبغته مصبغا.'),
(1501, 'غمص', 'غمص', 'غمص', 'الغمص في العين، والقطعة غمصة. وفلان غمص الناس، وغمط النعمة إذا تهاون بها وبحقوقهم ويقال للرجل إذا كان مطعونا عليه في دينه: إنه لمغموص عليه أي مطعون في دينه. وغمصت عليه قوله: عبته. ولا تغمص علي أي: لا تغضب.'),
(1502, 'مغص', 'مغص', 'مغص', 'المغص: غلظ في المعي 1 وتقطيع. ورجل ممغوص. والمغص: تلاد الإبل، وقيل: البيض الكرام، والواحدة مغصة.'),
(1503, 'صمغ', 'صمغ', 'صمغ', 'الصمغ: ما يسيل من الشجرة إذا جمد، وهي صمغة. والصمغان: ملتقى الشفتين مما يلي الشدقين 2 . والصمغ: شيء في أحاليل ضرع الشاة، يابس، الواحدة صمغة. وأصمغ شدقه أي: كثر بصاقه.'),
(1504, 'غطس', 'غطس', 'غطس', 'غطس الإناء في الماء أي غطه. وليل غاطس أي: مظلم.'),
(1505, 'غسر', 'غسر', 'غسر', 'تغسر الغزل: التبس. والفحل غسر الناقة إذا ضربها على غير ضبعة.'),
(1506, 'غرس', 'غرس', 'غرس', 'الغراس: وقت الغرس، والمغرس موضعه. والغراس: فسيل النخل. والغرس: الشجر الذي يغرس، وجمعه: أغراس. والغرس: جليدة رقيقة تخرج على رأس الولد إذا حست افثاثت 1 .'),
(1507, 'رغس', 'رغس', 'رغس', 'الرغس: البركة والنماء. وامرأة مروسة: ولود، ورجل مرغوس: كثير الخير. وعيش مرغس: واسع. وهم في مرغوس من أمرهم أي: في أخلاط.'),
(1508, 'رسغ', 'رسغ', 'رسغ', 'الرسغ: مفصل ما بين الساعد والكف، والساق والقدم. والرساغ: حبل يشد في رسغ البعير وهو المرسغ 1 وجمعه مراسغ. وإنه لمرسغ عليه أي موسع. وعيش رسيغ. وارتسغ على عيالك.'),
(1509, 'سرغ', 'سرغ', 'سرغ', 'سرغ: موضع.'),
(1510, 'غسل', 'غسل', 'غسل', 'الغسل معروف، والغسل: الماء. والغسل: الخطمي. وغسلين فعلين من غسلت، يقال: إنه الحار الشديد. والغسول من الحمض نحو الرمث. والمغسل: الذي لا يكاد يلقح من كثرة ضرابه.'),
(1511, 'سغل', 'سغل', 'سغل', 'السغل: الدقيق القوائم، الصغير الجثة، وقيل: الدقيق الصلب.'),
(1512, 'سلغ', 'سلغ', 'سلغ', 'سلغت الشاة والبقرة إذا خرج نابها، فهي سالغ. والأسلغ: النيء من اللحم وكل لئيم أسلغ.'),
(1513, 'غلس', 'غلس', 'غلس', 'الغلس: ظلام آخر الليل. وغلسنا: سرنا بغلس. وسقط في تغلس أي: الداهية، كأنما يراد أنها تباكر، والأصل: أن الغارات تكثر في آخر الليل. وغليس من ألقاب الحمار لأنه أغلس اللون.'),
(1514, 'لغس', 'لغس', 'لغس', 'ذئب لغوس أي: خبيث، وجمعه لغاوس، وكذلك اللص. والغواس: السريع الأكل، الخفيف. واللغس: سرعة الأكل. وطعام ملغوس: مثل ملهوج. واللغوس: ما رق من النبات.'),
(1515, 'غسن', 'غسن', 'غسن', 'الغسن: شعر العرف والناصية، الواحدة غسنة. وفرس ذو غسن. والرجل الجميل جدا يقال له: غساني. وغسان: ماء بالمشلل، من شرب منه من الأزد قيل: غساني. وكان ذلك في غسان 1 شبابه أي في نعمته. وفلان على أغسان أبيه أي على أخلاقه. وأغسان الرجال لئامهم. والغسن: الضعيف من الرجال 1 . والغسان 2 : رهط الصبي. وغسن الشيء: مضغ 3 .'),
(1516, 'نسغ', 'نسغ', 'نسغ', 'النسغ: تغريز الإبرة. والمنسغة: إضبارة من ذنب طائر ونحوه مما ينسغ بها الخبز. والغسيلة إذا غرست فخرجت قلبتها فقد أنسغت إنساغا.'),
(1517, 'غبس', 'غبس', 'غبس', 'الغبس: لون الرماد والذئب. وأغبس الليل وأغبش واحد.'),
(1518, 'سبغ', 'سبغ', 'سبغ', 'سبغ الشعر سبوغا، وسبغت الدزع، وكل شيء طال إلى الأرض فهو سابغ. وسبغت الناقة تسبيغا إذا كانت كلما نبت الشعر على ولدها أجهضته. وإسباغ الوضوء: المبالغة فيه. والتسبغة: شيء من حلق الدرع توصل به البيضة فيستر العنق، والبيضة يقال لها: سابغ. ويقال: تسبغ وتسبغة، الباء نصب.'),
(1519, 'سغب', 'سغب', 'سغب', 'الساغب: الجائع. وسغب يسغب سغوبا ومسغبة.'),
(1520, 'سغم', 'سغم', 'سغم', 'فلان يسغم فلانا أي: يبلغ الأذى إلى قلبه. وسغمت الفصيل إذا سمنته. والمسغم: الحسن الغذاء، وقد أسغم إسغاما.'),
(1521, 'غمس', 'غمس', 'غمس', 'الغمس: إرسال 1 الشيء في الماء أو غيره. والغماسة من طير الماء غطاط يغتمس كثيرا. والمغامسة: أن يرمي الرجل بنفسه في سطة الخطب. وهي أرضا الطعنة النافذة 2 . والغميس: الغمير تحت اليبيس. واليمين الغموس: التي لا استثناء فيها، وقيل التي يقتطع فيها الحق. والغموس: الشاة التي أنفدت شهرا أو أكثر ولم يتبين إيلادها. وقيل: هي مثل الغدوية، يتبايع بها، وهي في بطن الأم. والغميس: العالي من الأودية، والجميع: الغمسان. وقيل: هو مجرى الماء. والأجمة من القصب غميسة. وغمس النجم أي: غاب.'),
(1522, 'مغس', 'مغس', 'مغس', 'المغس لغة في المغص. والمغس: الطعن، وطعنة مغوس أي موجعة.'),
(1523, 'غسم', 'غسم', 'غسم', 'الغسم: اختلاط الظلمة، وأول طلوع النجم. وأغسم الليل. والغسم: الغبرة.'),
(1524, 'غزد', 'غزد', 'غزد', 'الغزيد: الصوت الشديد. والغزيد: الناعم من النبات.'),
(1525, 'زغد', 'زغد', 'زغد', 'الزغد: الهدير الشديد. والزغد: تزغد الشقشقة وهو الزغدب. والزغد: ملء الإناء والسقاء. والإزغاد: الإرضاع. وعاش عيشا زغدا أي: رغدا.'),
(1526, 'زدغ', 'زدغ', 'زدغ', 'المزدغة: لغة في المصدغة.'),
(1527, 'غزر', 'غزر', 'غزر', 'غزرت الناقة والشاة تغزر غزارة فهي غزيرة، كثيرة اللبن. وعين غزيرة الماء (ومطر غزير) 1 ومعروف غزير. وأغزر القوم، وغزرت إبلهم.'),
(1528, 'غرز', 'غرز', 'غرز', 'الغرز غرزك إبرة في شيء 2 . والغرز: ركاب الرحل، وكل ما كان مساكا للرجلين في المركب يسمى غرزا. وسمي به لأنك تقول: غرزت رجلي في الركاب. وجرادة غارزة وغارز أي: رزت ذنبها في الأرض لتسرأ 3 ومغزر الرأس والأضلاع مركب أصولها ونحوه. والغريزة: الطبيعة من خلق صالح أو رديء. وغرزت الناقة غرازا فهي غارز قليلة اللبن. وغرزتها: تركت حلبها ليذهب لبنها. والغرز: ضرب من اصغر الثمام، الواحدة بالهاء، تنبت على شطوط الأنهار، لا ورق لها، وهي أنابيب مركب بعضها في بعض، فإذا اجتذبتها خرجت من جوف آخر، كأنها عفاص أخرج من مكحلة.'),
(1529, 'رزغ', 'رزغ', 'رزغ', 'الرزغة أقل من الردغة. وأرزغها المطر: إذا كان ما يبل الأرض. والرزغ: المرتطم فيه. وأرزغت فلانا إذا لطخته بعيب.'),
(1530, 'زغر', 'زغر', 'زغر', 'زغر: بحيرة بناحية البصرة، ويقال لها: عيينة.'),
(1531, 'غزل', 'غزل', 'غزل', 'غزلت المرأة تغزل غزلا بالمغزل، والمغزل لغة. والغزل: حديث الفتيان مع الجواري، يقال: غازلها مغازلة. والتغزل: تكلف ذاك. والغزال: الشادن حين يتحرك ويمشي قبل الإثناء. والغزالة: عين الشمس. والغزالة: الضحى.'),
(1532, 'زغل', 'زغل', 'زغل', 'زغلت المزادة من عزاليها 1 أي صبت. وأزغلت القطاة فرخها، والاسم الزغلة.'),
(1533, 'لغز', 'لغز', 'لغز', 'اللغز، واللغز لغة،: ما ألغزت العرب من كلام فشبهت معناه. واللغز والألغاز: حفرة 2 يلغزها اليربوع في جحره يمنة ويسرة يلوذ بها.'),
(1534, 'زلغ', 'زلغ', 'زلغ', 'تزلغت يدي أي تشققت، وتزلعت بالعين أيضا.'),
(1535, 'نزغ', 'نزغ', 'نزغ', 'نزغ فلان بينهم نزغا أي: حمل بعضهم على بعض بفساد ذات بينهم، كما نزغ الشيطان من يوسف وإخواته، قال رؤبة: واحذر أقاويل العداة النزغ 1'),
(1536, 'زغف', 'زغف', 'زغف', 'درع زغف من دروع زغف، الواحد والجميع فيه سواء، أي محكم، قال: تحتي الأغر وفوق جلدي نثرة ... زغف ترد السيف وهو مثلم 2 ورجل مزغف: مفهوم جراف يزدغف كل شيء أي يأكله ويلفه. والزغف: دقاق الحطب.'),
(1537, 'زغب', 'زغب', 'زغب', 'الزغب: صغار الريش لا يجود ولا يطول. ورجل زغب، ورقبة زغباء. والزغب: ما يعلو ريش الفرخ. والزغابة: أصغر الزغب. وزغب الفرخ تزغيبا. والزغب: شعر المهر أول ما ينبت.'),
(1538, 'بزغ', 'بزغ', 'بزغ', 'بزغت الشمس بزوغا أي: بدا طلوعها. ونجوم بوازغ: طوالع. والبزغ والتبزيغ: تشريط شعر الدابة بمبزغ من حديد.'),
(1539, 'بغز', 'بغز', 'بغز', 'البغز: ضرب بالرجل والعصا، قال: واستحمل السير مني عرمسا أجدا ... تخال باغزها بالليل مجنونا 1'),
(1540, 'زغم', 'زغم', 'زغم', 'التزغم: التغضب وترمرم الشفة في برطمة. وتزغمت الناقة: تبرطم ولا ترضح الهدير.'),
(1541, 'غمز', 'غمز', 'غمز', 'الغمز: الإشارة بالجفن والحاجب. والغمز: العصر باليد. والغمازة: الجارية الحسنة الغمز للأعضاء. والغميزة: ضعفة في العمل وجهلة في العقل. وتقول: سمعت كلمة فاغتمزتها في عقله أي: علمت أنه أحمق. والمغامز: المعايب، ويعيب [بها] على غيره. وتقول: ما في هذا الأمر من مغمز أي مطمع، ويقال: معاب ومأكل 1 . قال الضرير: الغميزة العيب، يقال: ما فيه غميزة أي: ليس فيه ما يعاب به. والغمز في الدابة من قبل الرجل، والفعل يغمز.'),
(1542, 'غطل', 'غطل', 'غطل', 'الغيطل والغيطلة: شجر ملتف أو عشب. والغيطلة اسم البقرة، قال زهير: كما استغاث بسيء فز غيطلة 2 والغيطلة: جلبة القوم، وأصواتهم غيطلاتهم. والغيطلة: اسم الظلام وتراكمه، قال: وقد كسانا ليلة غياطلا 1'),
(1543, 'لغط', 'لغط', 'لغط', 'اللغط: أصوات مبهمة لا تفهم. واللغاط يلغط بصوته لغطا ولغيطا، ويلغط الغاطا، قال رؤبة: باكرته قبل الغطاط اللغط 2 والغطوا: أكثروا اللغط. ولغاط: اسم جبل.'),
(1544, 'غلط', 'غلط', 'غلط', 'الغلاط 3 : كل ما غالطت به، والغلطة المرة الواحدة. وغلطني وأغلطني فغلطت غلطا.'),
(1545, 'غطف', 'غطف', 'غطف', 'غطفان: حي من قيس عيلان.'),
(1546, 'غبط', 'غبط', 'غبط', 'الغبط: الجس باليد [للحيوان] ليعرف سمنه من هزاله. وناقة غبوط: لا يعرف طرقها حتى تغبط (أي تجس باليد) 1 . والغبطة: حسن الحال. ورجل مغبوط ومغتبط أي في غبطة. والغبيط: رحل قتبه وأحناؤه واحد وفرس مغبط الكاثبة إذا كان مرتفع المنسج، قال لبيد: مغبط الحارك محبوك الكفل 2 وفي الدعاء اللهم غبطا لا هبطا أي اجعلنا نغبط ولا نهبط. وهبطوا بمعنى وضعوا. وغبطت فلانا أي: أحببت أن أكون مثله. وأغبطت عليه الحمى أي: دامت، قال: كأن به توصيم حمى تصيبه ... بست وإغباط من الورد واعك 3'),
(1547, 'غطم', 'غطم', 'غطم', 'الغطمطة: التطام الأمواج. وبحر غطم، أي: شديد الالتطام قال: بذي عباب بحره غطيم وعدد غطيم أي: كثير.'),
(1548, 'طغم', 'طغم', 'طغم', 'الطغام: أوغاد الناس، الواحد والجميع سواء [قال: وكنت إذا هممت بفعل أمر ... يخالفني الطغامة والطغام] 1 ويقال: إن ذاك الطير والسباع.'),
(1549, 'مغط', 'مغط', 'مغط', 'المغط: مدك الشيء (اللين) 2 نحو المصران، يقال: مغطته فامتغط 3 وانمغط. وقولهم: ليس بالطويل الممغط (ولا بالقصير المتردد) 4 أي ليس بالبائن الطول.'),
(1550, 'غمط', 'غمط', 'غمط', 'غمط النعمة والعافية أي لم يشكرهما 5 . والغمط كالغمج، والفعل يغامط. والغمطاط: كثرة الماء. وماء غطماط: كثير 6'),
(1551, 'غدر', 'غدر', 'غدر', 'غدر غدرا أي: نقض العهد ونحوه. ويقال: غدر أي يا غدار، وللمرأة غدار أي يا غدارة. ويا ابن مغدر ويا مغدر. ولا يقال: رجل غدر، لأن غدر عندهم في حد المعرفة، وإذا كان في حد النكرة صرف فتقول: رأيت غدرا من الناس. ورجل مغدران: كثير الغدر. والغدير: مستنقع ماء المطر صغيرا كان أو كبيرا ولا يبقى إلى القيظ إلا ما يتخذه الناس من عد 1 أو حائر أو وجذ أو وقط أو صهريج. وكل عقيصة غديرة، قال: غدائره مستشزرات إلى العلى 2 والمغادرة: الترك، وهو ترك شيء مسلما. وقوله تعالى: لا يغادر صغيرة ولا كبيرة 3 ، أي لا يترك الكتاب شيئا إلا أحصاه. وكل متروك في مكان فقد غودر، وكذلك أغدرت الشيء أي تركته. ورجل ثبت الغدر أي ثابت في قتال أو كلام. وأصل الغدر الموضع الكثير الحجارة والصعب المسلك، لا تكاد الدابة تتخلص منه، فكأن قولك: غادره أي تركه في الغدر، فاستعمل ذلك حتى يقال: غادرته أي خلفته، قال العجاج: وإن تلقى غدرا تخطرفا 1 وأغدرت الليلة فهي مغدرة أي مظلمة 2 .'),
(1552, 'دغر', 'دغر', 'دغر', 'الدغر: الإقتحام من غير تثبت. يقال: أدغروا عليهم في الحملة. وفي الحديث: ليس في الدغرة قطع 3 ، وهو اسم ما دغرت أي استلبت. ولغة الأزد لصبيانهم: دغرى لا صفى 4 أي احملوا ولا تصافوا. وفي خلقه دغر، أي: تخلف 5 . ودغرت الغلام أي غمزت حلقه من العذرة.'),
(1553, 'ردغ', 'ردغ', 'ردغ', 'الردغة: وحل كثير سواخي الطين. ومكان ردغ. وارتدغ الرجل: وقع في الرداغ أي: الوحل. والمرادع: ما بين الترقوة إلى العنق، الواحدة مردغة.'),
(1554, 'غرد', 'غرد', 'غرد', 'كل صائت طرب الصوت فهو غرد. وقد غرد تغريدا، قال: إذا غرد المكاء في غير روضة ... فويل لأهل الشاء والحمرات 6 والغراد: الكمأة الرديئة، الواحدة: غردة 7 .'),
(1555, 'رغد', 'رغد', 'رغد', 'عيش رغيد أي: رغد، رفيه. والرغد: سعة العيش وقوم رغد ونساء رغد. وارغاد المريض إذا عرفت فيه ضعضعة من غير هزال 1 . والمرغاد: المتغير اللون غضبا ونحوه'),
(1556, 'دغل', 'دغل', 'دغل', 'الدغل: دخل مفسد في الأمور. وعن الحسن: اتخذوا دين الله دغلا أي أدغلوا في التفسير، يعني الحدود، أو حرفوا. وأدغلت في هذا الأمر أي أدخلت فيه ما يخالفه. وكل موضع يخاف فيه الإغتيال: دغل. وإذا دخل الرجل مدخل المريب، قيل: دغل فيه مثل دخول القانص في المكان الخفي لختل قنص، قال: أوطن في الشجراء بيتا داغلا 2 والدغاول: الريب..'),
(1557, 'لغد', 'لغد', 'لغد', 'اللغدود: باطن النصيل بين الحنك وصفق الغنق، وهو اللغد والألغاد'),
(1558, 'لدغ', 'لدغ', 'لدغ', 'اللدغ لغة، واللسب أعلى وأكثر، لدغ يلدغ لدغا فهو لديغ بمعنى ملدوغ.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1559, 'غدن', 'غدن', 'غدن', 'المغدودن: الناعم. وشاب غداني إذا ارتوى وامتلأ شبابا.'),
(1560, 'دغن', 'دغن', 'دغن', 'يقال للأحمق دغينة ودغة، ويقال: إنها كانت امرأة حمقاء. ويقال: هو أحمق من دغة، ولها حديث.'),
(1561, 'ندغ', 'ندغ', 'ندغ', 'الندغ والمنادغة شبه النخسة بالمغازلة، قال رؤبة: لذت أحاديث الغوي المندغ 1'),
(1562, 'غدف', 'غدف', 'غدف', 'الغدفة: لباس الملك والغول والدجى 2 وشبهه. والإغداف: إرسال القناع، قال عنترة: إن تغدفي دوني القناع فإنني ... طب بأخذ الفارس المستلئم 1 وأغدف الليل وأغدودف أي: أرخى سدفته. والغداف: غراب القيظ، ضخم وافر الجناحين. والغداف: الشعر الطويل الأسود، قال: ركب في جناحك الغداف 2'),
(1563, 'فدغ', 'فدغ', 'فدغ', 'الفدغ كسر كل أجوف مثل حبة العنب. ويقال في الذبح بحجر: إن لم يفدغ الحلقوم فكل (أراد إن لم يثرده) 3 . والفدغ: التواء في القدم، ورجر أفدغ: مائل القدمين.'),
(1564, 'دغم', 'دغم', 'دغم', 'الدغم: كسر الأنف إلى باطنه هشما، تقول: دغمته دغما. والأدغم: الأسود الأنف. والدغمة: اسم من إدغامك حرفا في حرف. وأدغمت الفرس اللجام: أدخلته في فيه. والأدغم: الديزج.'),
(1565, 'مغد', 'مغد', 'مغد', 'المغد: اللفاح. والفصيل يمغد الضرع مغدا أي: يتناول. وبعير مغد الجسم أي: تار لحيم. والمغد: نتف موضع الغرة ليبيض. والمغد: شيء ينشئه الله في العضاه، يؤكل، حلوا.'),
(1566, 'غمد', 'غمد', 'غمد', 'أغمدت السيف: أدخلته في غمده، أي في غلافه وغماده ومغمده وتغمدت فلانا: أخذته بختل حتى تغطيه. وتغمده الله وبرحمته: عمره فيها وغطاه. وغمدان: اسم حصن باليمن. وغامد: حي من اليمن.'),
(1567, 'دمغ', 'دمغ', 'دمغ', 'الدمغ: كسر الصاقورة عن الدماغ. والقهر والأخذ من فوق دمغ أيضا كما يدمغ الحق الباطل. والدامغة: طلعة تخرج من بين شظيات قلب النخلة، طويلة صلبة، إن تركت أفسدت النخلة، فإذا علم بها امتصخت أي قلعت ونزعت. والدامغة: حديدة يشد بها أعلى أخرة الرحل.'),
(1568, 'تغر', 'تغر', 'تغر', 'تغرت القدر تغرا، وتغرانها غليانها وأتغرتها: أغليتها، قال: وصهباء ميسانية لم يقم بها ... حنيف ولم تتغر بها ساعة قدر 1'),
(1569, 'غلت', 'غلت', 'غلت', 'الغلت في الحساب بمعنى الغلط، وهو في الحساب خاصة.'),
(1570, 'نتغ', 'نتغ', 'نتغ', 'أنتغ الرجل إنتاغا أي ضحك مستهزئا خفيا، قال: لما رأيت المنتغين أنتغوا 1 والمنتغة: ما أنتغك فأضحكك، ومثله: النتغة. والنتغة 2 : قرية حاتم طيء، وبها قبره.'),
(1571, 'نغت', 'نغت', 'نغت', 'النغت: جذب الشعر ونتفه عن الجلد، ونغته نغتا.'),
(1572, 'بغت', 'بغت', 'بغت', 'البغت: البغتة، قال: وأفظع شيء حين يفجؤك البغت 3 وباغته مباغتة: أي فاجأه. بغتة.'),
(1573, 'تغب', 'تغب', 'تغب', 'التغب: الوتغ أي: الهلاك، وتغب تغبا.'),
(1574, 'غتم', 'غتم', 'غتم', 'الغتمة: عجمة في المنطق. ورجل اغتم وغتمي، أي لا يفصح شيئا.'),
(1575, 'غلظ', 'غلظ', 'غلظ', 'غلظ الشيء غلظا فهو غليظ. واستغلظ النبات والشجر. وأغلظت الثوب: وجدته غليظا، واستغلظته: تركت شراءه لغلظه. والتغليظ: الشدة في اليمين. وغلظت عليه، وأغلظت له في المنطق. وأمر غليظ 1 .'),
(1576, 'غنظ', 'غنظ', 'غنظ', 'الغنظ: الهم اللازم. تقول: إنه لمغنوظ أي: مهموم. وقد غنظه الأمر يغنظه، ويغنظه وهو أشد الكرب، وهو إشراف على الموت. وغنظته غنظا: بلغت منه ذلك. وهذا غناظ له أي: مغمة.'),
(1577, 'غذم', 'غذم', 'غذم', 'غذم غذما أي: أكل بجفاء وشدة نهم. واغتذم الحوار ما في ضرغ أمه أي: استوعبه كله. والغذم من اللبن شيء ثخين، الواحدة غذمة، قال: مما غذته غذما فغذما 1 وأصابوا من معروفه غذما أي شيئا بعد شيء. وأغذمته: أطعمته ما يغذم. وذو غذم: موضع.'),
(1578, 'غثر', 'غثر', 'غثر', 'الأغثر والغثراء من الأكسية: ما كثر زئبره، وبه يشبه الغلفق فوق الماء. والأغثر من طير الماء ملتبس الريش، طويل العنق. والغثراء: سفلة الناس وجمهورهم. والغيثرة: الجماعة من الناس. والأغثر: الأغبر، وهو بين الغثر.'),
(1579, 'ثغر', 'ثغر', 'ثغر', 'ثغر الصبي: سقطت أسنانه، واثغرت أي نبتت بعد السقوط. ويقال: أتغر (بالتاء) . والثغرة: اسم له ما دام في منابته. وانثغر الصبي: سقط بعض ثغره. وانثغر الثغر أي انثلم. ومثغور اسم رجل من ضبة. وثغر العدو: ما يلي دار الحرب. والثغرة: نقرة النحر 1 . والثغرة: الناحية من الأرض، يقال: ما في تلك الثغرة مثل فلان والثغرة: الناحية من الأرض، يقال: ما في تلك الثغرة مثل فلان'),
(1580, 'غرث', 'غرث', 'غرث', 'الغرثان الجائع، وامرأة غرثى، وجمعه غراث، ونسوة غراثى. وجارية غرثى الوشاح، ووشاحها غرثان.'),
(1581, 'رغث', 'رغث', 'رغث', 'كل مرضعة رغوث ترغث ولدها أي ترضعه. والرغثاوان: بضعتان بين السندوة والمنكب بجانبي الصدر.'),
(1582, 'رثغ', 'رثغ', 'رثغ', 'الرثغ في الثلغ، وهو هشم الرأس.'),
(1583, 'ثلغ', 'ثلغ', 'ثلغ', 'الثلغ: هشم الرأس، وثلغت رأسه ثلغا شدخته.'),
(1584, 'لثغ', 'لثغ', 'لثغ', 'الألثغ: الذي يتحول لسانه من السين إلى الثاء.'),
(1585, 'غلث', 'غلث', 'غلث', 'الغلث: الخلط، وطعام مغلوث أي مخلوط بر وشعير ونحوه، قال لبيد: مشمولة غلثت بنابت عرفج ... كدخان نار ساطع أسنامها وسمعت من يقول: غلث الطائر أي عاج ورمى من حوصلته بشيء كان قد استرطه 2 . والغلثى: شجر يطسم ما أكله من المواشي والطير. ورجل غليث شديد القتال اللزوم لمن طالب. وغلث به لونه 3 .'),
(1586, 'غنث', 'غنث', 'غنث', 'غنثت: شربت من اللبن. وغنث غنثا وهو أن يشرب ثم يتنفس فهو يغنث.'),
(1587, 'غثن', 'غثن', 'غثن', 'الغثان: الدخان.'),
(1588, 'بغث', 'بغث', 'بغث', 'الأبغث من طير الماء كلون الرماد، طويل العنق، وجمعه بغث وأباغث. والبغاث: طير كالبواشيق 1 لا تصيد شيئا من الطير، الواحدة بغاثة، ويجمع على البغثان. قال أبو عبد الله: هو الرخم وشبهه. ويوم بغاث: وقعة كانت بين الأوس والخزرج 2 . ويقال: هو بغاث على ميل من المدينة، قريب من صريا 3 ، وهو موضع أتخذه موسى بن جعفر أبو الرضا. وصريا معمورة بهم اليوم. تقول: دخلنا في البغثاء والبرشاء يعني جماعة الناس.'),
(1589, 'ثغب', 'ثغب', 'ثغب', 'الثغب: ماء صار في مستنقع في صخرة أو جلهة، قليل، وجمعه ثغبان. وذوب الجمد ثغب، وقال: ولقد تحل بها كأن مجاجها ... ثغب يصفق صفوه بمدام 1'),
(1590, 'مغث', 'مغث', 'مغث', 'المغث: العرك في المصارعة والخصومات. ومغثت الرجل: أقبلت عليه فأسمعته. والمغث: التباس الشجعاء في المعركة. ومغثت الدواء في الماء إذا مرثته.'),
(1591, 'ثمغ', 'ثمغ', 'ثمغ', 'الثمغ: خلط البياض بالسواد، وثمغ لحيته ثمغا: خضبها، قال: إن لاح شيب الشمط المثمغ 2 وثمغ: ضيعة لعمر بن الخطاب، صدقة موقوفة بالمدينة.'),
(1592, 'ثغم', 'ثغم', 'ثغم', 'الثغامة 3 : نبات ذو ساق، وجمعه 4 ثغام مثل هامة الشيخ، قال: إن يك أمسى الرأس كالثغام 5'),
(1593, 'غرل', 'غرل', 'غرل', 'الغرل: القلف، والغرلة: القلفة. والأغرل: الأقلف، ويجمع على غرل. ويقال للمسترخي الخلق غرل، وجمعه غرلان، قال: لا غرل الطول ولا قصير 1 وعيش أغرل وأرغل أي: سائغ رغد. ورمح أغرل: طويل. وعام أغرل وأرغل: متتابع الخصب.'),
(1594, 'رغل', 'رغل', 'رغل', 'الرغل: نبات يسمى السرمق 2 وأرغلت الأرض: أنبتت الرغل والرضاع في عجلة، والاختلاس في غفلة رغل، يقال: رغلها يرغلها رغلا'),
(1595, 'رغن', 'رغن', 'رغن', 'أرغن فلان لفلان أي: أصغى قابلا راضيا، وفي لغة رغن، قال: وأخرى تصفقها كل ريح ... سريع لدى الحور إرغانها 1'),
(1596, 'نغر', 'نغر', 'نغر', 'نغرت القدر: غلت. ونغرت الناقة: قد ضيمت مؤخرها فمضت، قال: وعجز تنغر للتنغير 2 ونغرت بها: صحت بها. والنغر: فراخ العصافير، الواحدة بالهاء، ويجمع على نغران. وهو ضرب من الحمر حمر المناقير. واصول الأحناك: نغر 3 . والنغر: أولاد الحوامل إذا صوتت ووزغت 4 ، أي يتبين في بطنها كالوزغ في خلقته في الصغر.'),
(1597, 'رغف', 'رغف', 'رغف', 'الرغفان جمع الرغيف، والرغف أيضا، والعدد أرغفة.'),
(1598, 'غرف', 'غرف', 'غرف', 'الغرف: غرفك الماء باليد وبالمغرفة. والغرفة: قدر اغترافك، مثل الكف. والغرفة: مرة واحدة. والغرفة: بيت فوق بيت. وغرب غروف أي كثيرة الأخذ. ومزادة غرفية: مدبوغة بالغرف. والغرف: شجر يجلب من يبرين، وهو لا يوكع الأديم أي يغلظ والغرف: شجر إذا يبس فهو الثمام. والغرف: سرعة في العدو، وفرس غراف. والغريف: ماء في الأجمة. ويقال للسماء السابعة غرفة، قال لبيد: سوى فأغلق دون غرفة عرشه ... سبعا شدادا دون فرع المنقل 1'),
(1599, 'فغر', 'فغر', 'فغر', 'فغر المرء فاه يفغر فغرا إذا شحاه، وهو واسع فغر الفم. والفغر: الورد فغر وتفتج. وولد فلان بالفغرة، وأول طلوع الثريا. وأفغر النجم أي توقعه الناظرون إليه.'),
(1600, 'غفر', 'غفر', 'غفر', 'المغفر: وقاية للراس. وغفر الثوب إذا ثار زئبره غفرا. والغفارة: المغفر، ومغفر البيضة: رفرفها من حلق الحديد، قال الأعشى: والشطبة القوداء تط ... فر بالمدجج ذي الغفار 1 والغفارة: خرقة تضعها المرأة للدهن على هامتها. والغفارة: خرقة تلف على سية القوس لتلف فوقها إطنابة القوس، وهو سيره الذي يشد به، وحبل يسمى رأسه غفارة. واصل الغفر التغطية. والمغفور: دود يخرج من العرفط حلو يضيح بالماء فيشرب. وصمغ الإجاصة مغفور. وخرجوا يتمغفرون أي يطلبون المغافير. والغفارة: الربابة التي تغفر الغمام عليك أي تغطيه لأنها تحت الغيث، فهي تستره عنك. وجاء القوم جماء الغفير أي بلفهم ولفيفهم. والغفر: ولد الأروية، قال ذو الرمة: وفج أبى أن يسلك الغفر بينه ... سلكت قرانى من قراسية سمرا 2 والمغفر: الأروية، ويقال لها: أم غفر. والغفر من منازل القمر. والله الغفور الغفار يغفر الذنوب مغفرة وغفرانا وغفرا.'),
(1601, 'رفغ', 'رفغ', 'رفغ', 'الرفغ والرفغ لغتان، وهو من باطن الفخذ عند الأربية. واقة رفغاء: واسعة الرفغ. والرفغ: وسخ الظفر. وعيش رفيغ: خصيب، وإنه لفي رفاغة من عيشه ورفاغية. ورفغ العيش: سعته وخصبه. قال: تحت دجنات النعيم الأرفغ 1'),
(1602, 'فرغ', 'فرغ', 'فرغ', 'فرغ يفرغ وفرغ يفرغ فراغا. وقريء: حتى إذا فرغ عن قلوبهم 2 أي: ذهب بالخوف. وقوله تعالى: وأصبح فؤاد أم موسى فارغا 3 أي: خاليا من الصبر. وقريء: فرغا أي مفرغا، يكون فعل موضع مفعل مثل عطل ومعطل. والفرغ: مفرغ الدلو، وهو خرقه الذي يأخذ الماء، والفراغ ناحيته التي يصب الماء منها، قال: يسقى به ذات فراغ عثجلا 4 وقال كأن شدقيه إذا تهكما ... فرغان من دلوين قد تخرما 5 يريد بالفرغ مفرغ الدلو أي: خرقه، وفرغه: سعة جوفه. والإفراغ: الصب، قال الله تعالى: أفرغ علينا صبرا* 6 ، أي: اصبب. وافترغت: صببت على نفسي ماء. ودرهم مضرغ أي مصبوب في قالب ليس بمضروب وفرس فريغ المشي: هملاج وساع قد فرغ فراغة، ووسع وساعة ويقال للدم الذي فيه قود ولادية، قال: فإن تك أذواد أصين ونسوة ... فلن تذهبوا فرغا بقتل حبال 1'),
(1603, 'غرب', 'غرب', 'غرب', 'الغرب: التمادي، وهو اللجاجة في الشيء، قال: قد كف من غربي عن الإنشاد 2 وكف من غربك أي: من حدتك. واستغرب الرجل إذا لج في الضحك خاصة، واستغرب عليه في الضحك أي لج فيه. والغرب أعظم من الدلو، وهو دلو تام، وعدده أغرب، وجمعه غروب. واستحالت الدلو غربا أي عظمت بعدها ما كانت دلية. وفي حديث لعمر: استحالت الدلو في يدي عمر غربا أي تحولت فعظمت، أراد أن عمر ستفتح على يديه فتوح وتظهر معالم الدين وتنشر. وكل فيضة من الدمع غرب، يقال: فاضت غروب العين، قال: ألا لعينيك غروب تجري 3 قال: والغروب هاهنا الدمع. والغرب في قول لبيد الراوية التي يحمل عليها الماء وهو قوله: فصرفت قصرا والشؤون كأنها ... غرب تحت بها القلوص هزيم 4 (وغروب الأسنان: الماء الذي يجري عليها، أي على الأسنان) 1 واحدها غرب. والغربان: مؤخر العين ومقدمها. والغرب: ما يقطر من الدلاء عند البئر من الماء فيتغير سريعا ريحه. وأغرب الساقي أي أكثر الغرب. وإذا انقلبت الدلو فانصبت 2 يقال: أغرب الساقي. وإذا أفاض جوانب الحوض قيل: أغرب الحوض. وغروب الأسنان: أطرافها. والغرب: خراج يخرج في العين. والغرب: المغرب. والغروب: غيبوبة الشمس. ويقال: لقيته عند مغيربان الشمس. وقوله تعالى: رب المشرقين ورب المغربين ، 3 الأول أقصى ما تنتهي إليه الشمس في الصيف، والآخر أقصى ما تنتهي إليه في الشتاء، وبين الأقصى ما تنتهي إليه الشمس في الصيف، والآخر أقصى ما تنتهي إليه في الشتاء، وبين الأقصى والأدنى مائة وثمانون مغربا. قال الله: رب المشرقين. وقال: فلا أقسم برب المشارق والمغارب 4 . والغربة: الاغتراب من الوطن. وغرب فلان عنا يغرب غربا أي تنحى، أغربته وغربته أي نحيته. والغربة: النوى البعيد، يقال: شقت بهم غربة النوى. وأغرب القوم: أنتووا. وغاية مغربة أي بعيدة الشأو. وغربت الكلاب أي أمعنت في طلب الصيد. ويقال: نحن غربان أي غريبان، قال:'),
(1604, 'مرغ', 'مرغ', 'مرغ', 'المرغ: الأشباع بالدهن، ورجل أمرغ. ومرغ عرضه: (دنس) 2 . والأمراغ مجاوز من فعله 3 . ومرغته في التراب فتمرغ. وبلغني قوله: فلم أرغ منه ولم أتمرغ أي: لم أبال. ومراغ الإبل: متمرغها. والمراغة: الأتان التي لا تمتنع من الفحول، قال يا ابن المراغة أين خالك إنني ... خالي حبيش ذو الفعال الأجزل 4'),
(1605, 'مغر', 'مغر', 'مغر', 'ثوب ممغر: مصبوغ بالمغرة، وهو طين أحمر، ويجمع مغر، نحو بدرة وبذر. والأمغر: الأحمر الشعر والجلد، والأمغر الذي في وجهه حمرة مع بياض صاف. وقول عبد الملك: مغر يا جرير أي: أنشد لابن مغراء. وشاة ممغار: شائب لبنها بدم، وأمغرت: شابت لبنها بدم. والمغر: لعاب الدواب 1 .'),
(1606, 'غمر', 'غمر', 'غمر', 'الغمر: الماء الكثير المغرق. والغمار: جماعة الغمر، وهي مجتمع ماء البحر والنهر. والغمر: قديح صغير يكايل به في المهامه. تؤخذ حصاة فتلقى في القدح فيصب عليها الماء حتى يغمرها، ثم يأخذها رجل، فتلك الحصاة تسمى الدو قلة، قال: من الشواء ويروي شربه الغمر 2 وتغمرت: شربت ما دون الري. وتغمر: السيد المعطاء. والغمر: الفرس الكثير الجري. والاغتمار: الاغتماس. والغمر: منهمك الباطل. ومرتكم الهول 3 : غمرة الحرب وفلان غمر فلانا أي: علاه بفضله. ودخل في غمار الناس أي: مجتمعهم. والمغامر: الذي يرمي بنفسه في غمرة من الأمر. والغمر: من لم يجرب الأمور، وجمعه أغمار. ودار غامرة: خراب. والغمرة: ما تطلى به العروس. والغمر: الخفد، والغمر: ريح اللحم. والغمر: موضع. وغمرة الموت: شدته. والمغمر: الغمر، قال: قطعته لاعس ولا بمغمر! 1'),
(1607, 'رغم', 'رغم', 'رغم', 'الرغم: محنة أن يفعل ما يكره على كره وذل. والرغام: الثرى، ورغم الله أنفه أي: لوثه في التراب. وأرغمته: حملته على ما لا يمتنع منه. ورغمته: قلت له: رغما ودغما وهو راغم داغم. والرغام: سيلان الأنف من داء 2 . ورغم فلان إذا لم يقدر على الانتصاف، يرغم رغما. وفي الحديث: إذا صلى أحدكم فليلزم جبهته وأنفه الأرض حتى يخرج منه الرغم أي حتى يخضع ويذل ويخرج منه كبر الشيطان 3 . والرغام ليس بتراب خالص ولا برمل خالص. والرغامى لغة في الرخامى. وما أرغم منه شيئا أي ما أكره. والمراغمة: الهجران، هو يراغم أهله أياما ثم يرجع. وقوله تعالى: مراغما كثيرا 1 أي متسعا لهجرته، قال الجعدي: عزيز المراغم والمهرب 2 قال الضرير: الرغامى الرئة، والرغام: الزيادة.'),
(1608, 'غرم', 'غرم', 'غرم', 'الغرم: أداء شيء لزم من قبل كفالة أو لزوم نائبة في ماله من غير جناية، غرمته أغرمه. والتغريم: مجاوز. والغريم: الملزوم ذلك. والغريمان سواء الغارم والمغرم. والغرام: العذاب أو العشق أو الشر، وحب غرام أي لازم. وقوله تعالى: إن عذابها كان غراما 3 أي لازما. والمغرم: الغرم، قال تعالى: فهم من مغرم مثقلون* 4 ، أي من غرم.'),
(1609, 'نغل', 'نغل', 'نغل', 'النغل: الجلد الفاسد في دباغه، ونغل نغلا. وجوزة نغلة. والنغل: ولد زنية، والجارية نغلة، والمصدر النغلة.'),
(1610, 'لغن', 'لغن', 'لغن', 'اللغنون واللغانين من نواحي اللهاة، مشرف على الحلق. وإلغان النبات إذا التف، وبالعين أيضا.'),
(1611, 'غلف', 'غلف', 'غلف', 'الأغلف: الأقلف. وقلب أغلف كأنما غشي غلافا فلا يعي شيئا. والغلاف: الصوان. وغلفت لحيته. وتغلف الرجل واغتلف. وغلفت القارورة وأغلقتها في الغلاف. وغلفت السرج والرحل.'),
(1612, 'غفل', 'غفل', 'غفل', 'غفل يغفل غفلة وغفولا. والتغافل: التعمد: والتغفل: ختل عن غفلة. وأغفلت الشيء: تركته غفلا وأنت له ذاكر. والمغفل: من لا فطنة له. والغفل: المقيد لا يرجى خيره ولا يخشى شره، وقد اغتفل، والجميع الأغفال. ورجل غفل: ليس يعرف ما عنده ويقال: لا يعرف له حسب، وجمعه أغفال. والغفل: سبسب متيه 1 بعيد، لا علامة فيها، قال: يتركن بالمهامه الأغفال 2 وطريق غفل: لا علامة فيه. ودابة غفل: لا سمة عليها. وغفل فلان نفسه أي كتمها في الناس ولم يشهرها. وبنو غفيلة: حي.'),
(1613, 'غلب', 'غلب', 'غلب', 'غلب يغلب غلبا وغلبة. والغلاب: النزاع. والمغلب: الذي يغلبه أقرانه فيما يمارس. والمغلب قد يكون المفضل على غيره. والأغلب: الغليظ الشديد القصرة، واسد أغلب. وقد غلب غلبا، يكون من داء أيضا. وهضبة غلباء، وعزة غلباء، وتغلب كانت تسمى الغلباء. واغلولب العشب [في] الأرض إذا بلغ كل مبلغ 1'),
(1614, 'لغب', 'لغب', 'لغب', 'لغب يلغب لغوبا، ولغب، وهو شدة الاعياء. واللغاب من الريش: البطن، الواحدة بالهاء. واللغاب: ريش السهم إذا لم يعتدل، والمعتدل لؤام، قال: بسهم لم يكن يكسى لغاما 2'),
(1615, 'بغل', 'بغل', 'بغل', 'البغلة والبغل معروفان. والبغل بغل وهو لذلك أهل 3 . والتبغيل: مشية الإبل في سعة.'),
(1616, 'بلغ', 'بلغ', 'بلغ', 'رجل بلغ: بليغ، وقد بلغ بلاغة. وبلغ الشيء يبلغ بلوغا، وأبلغته إبلاغا. وبلغته تبليغا في الرسالة ونحوها. وفي كذا بلاغ وتبليغ أي كفاية. وشيء بالغ أي جيد. والمبالغة: أن تبلغ من العمل جهدك. قال الضرير: سمعت أبا عمرو يقول: البلغ ما يبلغك من الخبر الذي لا يعجبك، القول: اللهم سمع لا بلغ أي اللهم نسمع بمثل هذا فلا تنزله بنا'),
(1617, 'غلم', 'غلم', 'غلم', 'غلم يغلم غلما وغلمة أي غلب شهوة. والمغليم يستوي فيه الذكر والأنثى، يقال: جارية مغليم. واغتلم الشراب: صلب واشتد. وغلام بين الغلوم والغلامية، وهو الطار الشارب. والغلامة: الجارية قال: فلم أر عاما كان أكثر باكيا ... ووجه غلام ... 1'),
(1618, 'غنف', 'غنف', 'غنف', 'الغنيف: غيلم الماء في منبع الآبار والعيون. وبحر ذو غينف، قال: نغرف من ذي غينف ونؤزي 1 قال الضرير: هو خطأ، إنما هو: نغرف من ذي غيث ونؤزي ... إلى تميم وتميم حرزي'),
(1619, 'نغف', 'نغف', 'نغف', 'النغف: دود عقف 2 ينسلخ عن الخنافس ونحوها. قال القاسم: النغف دود في عظمي الوجنتين، لكل رأس نغفتان أي عظمان، ويقال: من تحركهما يكون العطاس. وربما انغف البعير فكثر نغفه. وقد نغف إذا رمى بالنغف، وأنغف إذا وقع فيه النغف.'),
(1620, 'نغب', 'نغب', 'نغب', 'نغب الإنسان ينغب وينغب نغبا أي: ابتلع ريقه أو الماء نغبة بعد نغبة 1 وقوله: لم يقصعنه نغب 2 أي يجرع.'),
(1621, 'نبغ', 'نبغ', 'نبغ', 'نبغ الرجل إذا لم يكن في إرث الشعر ثم قال فأجاد فيقال: نبغ منه شعر شاعر. (وبلغنا أن زيادا قال الشعر على كبر سنه، ولم يكن نشأ في بيت الشعر فسمي النابغة) 3 ، وقيل: بل سمي لقوله: وقد نبغت لنا منهم شؤون 4 أي: ظهرت أمور. والدقيق ينبغ من خصاصر المنخل وأنبغته أنا.'),
(1622, 'غبن', 'غبن', 'غبن', 'الغبن في الرأي القائل، والغبن في البيع، وغبنته فهو مغبون في تجارته والفاتر عن العمل غابن. والمغابن: الأرفاغ والآباط، الواحد مغبن. واغتبنت الشيء: أخذته في المغبن. والغبينة من الغبن كالشتيمة من الشتم. ويقال: أرى هذا الأمر عليك غبنا، قال: أجول في الدار لا أراك وفي الدار ... أناس جوارهم غبن 1 ويوم التغابن في الآخرة بالأعمال.'),
(1623, 'غنم', 'غنم', 'غنم', 'هذه غنم لفظ للجماعة، فإذا أفردت قلت: شاة. والغنم: الفوز بالشيء في غير مشقة. والاغتنام: انتهاب 2 الغنم والغنيمة: الفيء. وبنو غنم: حي من العرب.'),
(1624, 'نغم', 'نغم', 'نغم', 'النغمة: جرس الكلام وحسن الصوت من القراءة ونحوها. وتقول: ما نغم بكلمة.'),
(1625, 'غمن', 'غمن', 'غمن', 'غمنت الجلد ليلين ويحتمل الدباغ. ويقال: غمنته وغملته. وغمنت المرأة بالغمنة أي غمرتها بالغمرة ليحسن لونها ويرق جلدها.'),
(1626, 'نمغ', 'نمغ', 'نمغ', 'التنميغ: مجمجة بسواد وحمرة وبياض، ورجل منمغ الخلق. والنمغة: ما تحرك من الرماعة.'),
(1627, 'فغم', 'فغم', 'فغم', 'فغم الورد: انفتح، قال: كأنه الورد إذا ما فغما 1 والريح الطيبة تفغم المزكوم، والسدة بعد انسداد، قال: نفحة مسك تفغم المزكوما 2 وفي الحديث: لو أن امرأة من الحور العين أشرفت لأفغمت ما بين السماء والأرض ريح المسك أي: لملأت خياشيم من يشم الريح. يقال: فغم فهو مفغوم. وفغمت السدة: فتقتها.'),
(1628, 'بغم', 'بغم', 'بغم', 'بغم الظبي يبغم بغوما وهو أرخم صوته، قال ذو الرمة: داع يناديه باسم الماء مبغوم 1 أي: المجاب بالبغام، والمبغوم: الولد لأن أمه تبغمه أي تصيح به. والناقة والبقرة تبغمان. وامرأة بغوم أي رخيم الصوت، قال: حبذا أنت يا بغوم إلينا 2 أي: ما أحبك إلينا.'),
(1629, 'قش', 'قش', 'قش', 'القش والتقشيش: تطلب الأكل من هاهنا وهاهنا، ولف ما قدر عليه. والقشيش والقشاش الاسم. والنعت قشاش وقشوش. والقشة: الصبية الصغيرة الجثة 1 لا تكاد تنبت. ويقال: القشة: دويبة شبه الجعلان والخنافس. والقشقشة: يحكى بها الصوت قبل الهدير في مخض الشقشقة قبل أن يزغد 2 . بالهدير، أي يفصح به، والتزغد: هدير لين. وتقشقشت القروح أي تقشرت للبرء 3 . والقشة: الصوفة التي تلقى بعد ما يهنأ بها البعير، وهي قبل الإلقاء ربذة. وانقش القوم: تفرقوا وذهبوا مسرعين.'),
(1630, 'شق', 'شق', 'شق', 'الشقشقة: لهاة البعير، وتجمع شقاشق، ولا يكون ذلك إلا للعربي من الإبل. والشق: مصدر قولك: شققت، والشق الاسم، ويجمع على شقوق. والشق غير بائن ولا نافذ، والصدع ربما يكون من وجه. والشقاق: تشقق جلد اليد والرجل من برد ونحوه. وتقول: ما بلغت كذا إلا بشق النفس أي بمشقة. وجانبا كل شيء شقاه. والشقيق من قولك: هذا أخي وشقيقي، وشق نفسي. وأخت الرجل شقيقته. والشقة: شظية تشق من لوح أو خشبة. ويقال لمن غضب: احتدم فطارت منه شقة في الأرض وشقة في السماء. وشقة شاقة، وأمر شاق. والشقة من الثياب، والشقة: بعد مسير إلى أرض بعيدة. والشقاق: الخلاف. والخارجي يشق عصا المسلمين ويشاقهم خلافا، قال: رضوا بالشقاق الأكل خضما فقد رضوا ... أخيرا بأكل الخضم أن يأكل القضما 1 . وانشقت عصا المسلمين بعد التئام، أي تفرق أمرهم. والاشتقاق: الأخذ في الكلام. [والاشتقاق في] الخصومات مع ترك القصد. وفرس أشق، وقد اشتق في عدوه يمينا وشمالا. والشقق: مصدر الأشق، قال: وتباريت كما يمشي الأشق 1 التباري: سعة الخطو. والشقيقة: وجع نصف الرأس. والشقيقة: فرجة بين الرمال تنبت العشب والشجر. وشقائق النعمان: نور أحمر. الواحدة شقيقة. وفرس أشق، يقال: واسع المنخرين'),
(1631, 'قض', 'قض', 'قض', 'تقول: قضضنا عليهم الخيل فانقضت أي أرسلنا، قال: قضوا غضابا عليك الخيل من كثب 2 وانقض الحائط أي وقع. وانقض الطائر: هوى في طيرانه ليسقط على شيء. والقض 1 : التراب يعلو الفراش، تقول: أقض علي المضجع، واستقضه فلان، قال أبو ذؤيب: أم ما لجنبك لا يلائم مضجعا ... إلا أقض عليك ذاك المضجع 2 وأقض الرجل أي تبلغ دقاق المطامع. قال: ما كنت من تكرم الأعراض ... والخلق العف عن الإقضاض 3 ولحم قض وطعام قض: أي وقع في التراب أو أصابه التراب فوجد ذاك في طعمه، قال: وأنتم أكلتم لحمه متربا قضا 4 . وجاءوا بقضهم وقضيضهم أي بجماعتهم، لم يخلفوا أحدا ولا شيئا. والقضقضة: كسر العظام عند الفرس والأخذ. وأسد قضقاض: يقضقض فريسته، قال: كم جاوزت من حية نضناض ... وأسد في غيله قضقاض 5 والقضة: أرض منخفضة ترابها رمل والى جنبها متن مرتفع، والجميع قضون. والقضقاض: من أشنان الشام. والقضيض: أن تسمع من الوتر والنسع صوتا كأنه قطع، والفعل: قض يقض قضيضا. وقضضت الجارية: ذهبت بقضتها. وقضضت اللؤلؤة قضا: خرقتها. ودرع قضاء أي خشنة المس لم تنسحق، قال النابغة: وكل صموت نثلة تبعية ... ونسج سليم كل قضاء ذائل 1'),
(1632, 'قص', 'قص', 'قص', 'والقص قص الشاة وهو مشاش صدرها المغروزة فيه شراسيف الأضلاع، وهو القصص أيضا. وقصصت الشعر بالمقص أي بالمقراض قصا. والقصة تتخذها المرأة في مقدم رأسها تقص ناصيتها 2 عدا جبينها. وقصاص الشعر نهاية منبته من مقدم الرأس، ويقال: بل ما استدار به كله من خلف وأمام وما حواليه. والقاص يقص القصص قصا، والقصة معروفة. ويقال: في رأسه قصة أي جملة 3 من الكلام ونحوه. والقصاص: التقاص في الجراحات والحقوق، شيء بعد شيء، ومنه الاقتصاص والاستقصاص والإقصاص لكل معنى، اقتص منه أي أخذ منه. واستقص منه أي طلب أن يقص منه، وأقصه به. وأحسن القصص القرآن. القصيص: نبات ينبت في أصول الكمأة، وقد يجعل منه غسلا للرأس كالخطمي، قال: جنيته من مجتنى عويص ... من منبت الإذخر والقصيص 1 وأقصت الشاة أي استبان ولدها فهي مقص 2 . والقصقاص: نعت من صوت الأسد في لغة، والقصقاص نعت للحية الخبيثة، ولم يجيء في بناء المضاعف على وزن فعلال غيره، وإنما حد أبنية المضاعف على زنة فعلل أو فعلول أو فعلل أو فعليل مع كل ممدود ومقصور مثله. وجاءت كلمات شواذ منها: ضلضلة، وزلزل، وقصقاص، وأبو القلنقل، والزلزال، وهو أعمها لأن مصدر الرباعي يحتمل أن يبنى كله على فعلال، وليس بمطرد. وكل نعت رباعي فان الشعراء يبنونه على فعالل مثل قصاقص كقول الشاعر: فيه الغواة مصورون ... فحاجل منهم وراقص والفيل يرتكب الرداف ... عليه والأسد القصاص يصف بيتا مصورا بأنواع التصاوير. ورجل قصقصة وقصقاص أي غليظ قصير. وزاملة قصيصة أي ضعيفة. والقص لغة في الجص. وقصاقصة: موضع. ويقال: جمعت قصيصته مع بني فلان أي بعيرا يقص أثر الركاب، ويجمع قصائص. ويقال: ضربه فأقصه أي أدناه من الموت.'),
(1633, 'قس', 'قس', 'قس', 'قس يقس فلان قسا من النميمة وذكر الناس بالغيبة، قال: يصبحن عن قس الأذى غوافلا 1 والقسة: القرية الصغيرة بلغة السواد. والقسقس: الدليل الهادي المتفقد الذي لا يغفل إنما هو تلفتا ونظرا 2 . والقس: رأس من رءوس النصارى، وكذلك القسيس، ومصدره القسوسة والقسيسة. ويجمع على قسيسين، ويقال: يجمع على قساوسة، قال أمية: لو كان منفلت كانت قساوسة ... ينجيهم الله في أيديهم الزبر 3 وليلة قسقاسة: شديدة الظلمة، قال رؤبة: كم جبن من بيد وليل قسقاس 1 وقس: موضع'),
(1634, 'قز', 'قز', 'قز', 'قز الإنسان يقز إذا قعد كالمستوفز ثم انقبض ووثب. وفي الحديث: إن إبليس ليقز القزة من المشرق فيبلغ المغرب. والتقزز: التنطس. والقاقزة: مشربة، وهي فيالجة دون القرقارة. ويقال: هي أعجمية، وليس في كلام العرب مثلها مما يفصل بين حرفين مثلين مما يرجع إلى بناء ققز ونحوه، وأما بابل فانه اسم خاص لا يجرى مجرى الأسماء العوام. ويقال: قاقوزة بمعنى قاقزة، قال: بقواقيز في الأكف علينا موزعه 2'),
(1635, 'زق', 'زق', 'زق', 'الزق: وعاء للشراب، وهو الجلد يجز شعره ولا ينتف نتف الأديم. وزق الطائر الفرخ يزقه زقا أي يغره غرا. والزقاق: طريق دون السكة، ضيق نافذ أو غير نافذ. والزقة: طائر صغير في الماء يمكن حتى يكاد يقبض عليه ثم يغوص فيخرج بعيدا. والزقزاق والزقزقة: ترقيص الأم ولدها.'),
(1636, 'قط', 'قط', 'قط', 'قط، خفيفة، هي بمنزلة حسب، يقال: قطك هذا الشيء أي حسبكه، قال: امتلأ الحوض وقال قطني 1 وقد وقط لغتان في حسب، لم يتمكنا في التصريف، فإذا أضفتهما إلى نفسك قويتا بالنون فقلت: قدني وقطني كما قووا عني ومني ولدني بنون أخرى. قال أهل الكوفة: معنى قطني كفاني، النون في موضع النصب مثل نون كفاني لأنك تقول: قط عبد الله درهم. وقال أهل البصرة: الصواب فيه الخفض على معنى: حسب زيد وكفي زيد، وهذه النون عماد. ومنعهم أن يقولوا: حسبني لأن الباء متحركة، والطاء هناك ساكنة فكرهوا تغييرها عن الإسكان، وجعلوا النون الثانية من لدني عمادا للياء. وأما قط فإنه الأبد الماضي، تقول: ما رأيته قط، وهو رفع لأنه غاية مثل قولك: قبل وبعد. وأما القط الذي في موضع: ما أعطيته إلا عشرين درهما قط، فإنه مجرور فرقا بين الزمان والعدد. والقط: قطع الشيء الصلب كالحقة على حذو مسبور 1 كما تقط القصبة على عظم. والمقطة: عظيم تقط عليه رءوس الأقلام. ويقال: ناولني قطا من البطيخ أي قطعة. والقطاط: حرف من الجبل أو من صخرة كأنما قط قطا، والجميع الأقطة. والقط: كتاب المحاسبة، وجمعه قطوط. والقط: النصيب لقوله تعالى: ربنا عجل لنا قطنا قبل يوم الحساب 2 . ورجل قطط، وشعر قطط، وامرأة قطط، والجميع قططون وقططات. والقطة: السنور، والجميع القطاط، وهو نعت للأنثى، قال الأخطل: أكلت القطاط فأفنيتها ... فهل في الخنانيص من مغمز 3 . والقطقط: المطر المتفرق المتحاتن 4 المتتابع العظيم القطر، والقطقطة فعله. والقطقط: القصير، قال أعرابي: إنه لقطقط من الرجال لو سقطت بيضة من استه ما أنكرت.'),
(1637, 'طق', 'طق', 'طق', 'طق: حكاية حجر على حجر، والطقطقة فعله.'),
(1638, 'قد', 'قد', 'قد', 'قد مثل قط على معنى حسب، تقول: قدي أي حسبي، قال النابغة: إلى حمامتنا ونصفه فقد 1 وأما قد فحرف يوجب الشيء كقولك قد كان كذا وكذا، والخبر أن تقول: كان كذا وكذا فأدخل قد توكيدا لتصديق ذلك. وتكون قد في موضع تشبه ربما، وعندها تميل قد إلى الشك إذا كانت مع العوامل كقولك: قد يكون ذلك 2 . والقد: قطع الجلد وشق الثوب ونحوه. وتقول: قددت وسطه بالسيف، وقددت القميص فانقد، قال ذو الرمة: تكاد تنقد منهن الحيازيم 3 وفلان حسن القد أي في قدر خلقه، وشيء حسن القد أي التقطيع. والقد: سير يقد من جلد غير مدبوغ، والقديد اشتقاقه منه. ولا يقال القدة إلا لكل شيء كالوعاء. وصار القوم قددا أي تفرقت حالاتهم وأهواؤهم، قال الله- عز ذكره-: كنا طرائق قددا 1 . والقدة: الطريقة والفرقة من الناس. وهم 2 القدد إذا كان هوى كل فرد على حدة. وقديد: موضع بالحجاز. وفلان يقتد الأمور أي يدبرها ويميزها بعلم واتفاق، قال رؤبة 3 : يقتد من كون الأمور الكون ... حقائقا ليست بقول الكهن ورجل قداد: يقد الكلام، وهو تشقيقه إياه وكثرته. وتقدد البعير: سمن بعد الهزال فرأيت أثر السمن يأخذ فيه، وكذلك إذا كان سمينا فيأخذ فيه الهزال. والمسافر يقد المفازة أي يشق وسطها، قال: قد الفلاة كالحصان الخابط والقديد: مسيح صغير. وهذا على قد هذا أي على قدره. والقداد: أظنه من أسماء القنافذ واليرابيع. والقيدود: الناقة الطويلة الظهر، ويقال: أخذ من القود بمنزلة الكينونة من الكون . دق: دققت الشيء دقا، وكل شيء كسرته قطعة قطعة، إلا أنهم يقولون: كسرته 1 . الحمى لأنها لم تكسره قطعة قطعة، ولكنها دهمته من فوق. والدقاق: فتات كل شيء دق. والمدق: حجر يدق به الطيب، وضم الميم لأنه جعله اسما، وكذلك المنخل، فإذا جعلته نعتا رددته إلى مفعل، كقوله: يرمي الجلاميد بجلمود مدق 2 يريد بالجلمود هاهنا حافر الحمار. والدق ضد الجل، والدقة مصدر الدقيق. وتقول: دق الشيء يدق دقة وهو على أربعة أنحاء: الدقيق الطحين، والدقيق الأمر الغامض، والدقيق الرجل الدقيق الخير والقليله، والدقيق الشيء الذي لا غلظ فيه. والدقة: الملح المدقوق حتى إنهم يقولون: ما لفلان دقة، وإن فلانة لقليلة الدقة أي ليست بمليحة. وفلان يداق فلانا في الحساب أي ينظر معه في الحساب اليسير الدقيق. والدقاقة: التي يدق بها الأرز ونحوه. ومستدق الساعد: كل ما دق منه. والدقدقة حكاية حوافر الدواب في سرعة ترددها. والدقة والدقق: ما تسهكه 1 الريح من الأرض، قال: بساهكات دقق وجلجال 2'),
(1639, 'قت', 'قت', 'قت', 'القت: الفسفسة اليابسة. والقت: الكذب المهيأ والنميمة، وهو يقت الكذب أي يهيئه. والقتات: النمام، قال: قلت وقولي عندهم مقتوت 3 . أي مهيأ كذبا. وهو مقتت أي مطيب مطبوخ بالرياحين. والقت: اتباعك الرجل سرا لتعلم ما يريد.'),
(1640, 'قذ', 'قذ', 'قذ', 'القذ: قطع أطراف الريش على مثال الحذف والتحذيف، وكذلك كل قطع نحو قذة الريش. ويقال: أذن مقذوذة، ورجل مقذذ أي مقصص شعره حوالي قصاصه كله. والقذة: الريش يراش السهم بها. والقذة: كلمة يقولها صبيان العرب يقولون: لعبنا شعارير قذة. والقذان: البراغيث واحدتها قذة، قال: يؤرقني قذانها وبعوضها 1 والقذاذات: قطع صغار تقطع من أطراف الذهب، والجذاذات من الفضة.'),
(1641, 'قث', 'قث', 'قث', 'القثاث: المتاع ونحوه. وجاء فلان يقث مالا ويقث معه دنيا عريضة أي يجر معه. والمقثة والمطثة لغتان، وهي خشبة مستديرة عريضة يلعب بها الصبيان، ينصبون شيئا ثم يجتثونه عن موضعه. ويقولون: قثثناه وطثثناه عن موضعه قثا وطثا. والقت: حشيش ينبت يتيما يحصد ويطحن ويخبز منه الخبز.'),
(1642, 'قر', 'قر', 'قر', 'القر: البرد، وليلة قرة ويوم قر وطعام قار. وفي الحديث: 1 ول حارها من تولي قارها. والقرة: ما تصيبه من القر. ورجل مقرور، وهو أقر من القر أي أبرد من الكافور ويكون باردا، قال امرؤ القيس: على حرج كالقر تخفق أكفاني 2 والقرة كل شيء قرت به عينك، وقرت العين تقر قرة نقيض سخنت. والقرار: المستقر من الأرض. وأقررته في مقره ليقر، وفلان قار أي ساكن. وما يتقار في مكانه ويقر أي ما يستقر. والإقرار: الاعتراف بالشيء. والقرارة: القاع المستدير. والقرقرة: الأرض الملساء ليست بجد واسعة، فإذا اتسعت غلب عليها اسم التذكير فقالوا: قرقر، قال ابن الأبرص: تزجي يرابيعها في قرقر ضاحي 1 ويجوز في الشعر قرق بحذف الراء، قال: كأن ايديهن بالقاع القرق 2 وقرة وقران من أسماء الرجال. وقول الله: فمستقر ومستودع ، 3 أي ما ولد من الخلق على ظهر الأرض والمستودع: ما في الأرحام. والقرقرة في الضحك، ومن أصوات الحمام، قال: وما ذات طوق فوق خوط أراكة ... إذا قرقرت هاج الهوى قرقريرها 4 والعرب تخرج من آخر حروف الكلمة حرفا مثله، كما قالوا: رماد رمدد، ورجل رعش رعشيش، وفلان دخيل فلان ودخلله، (والياء في رعشيش مدة، فإن جعلت مكانها ألفا أو واوا، جاز وأنشد: كأن صوت جرعهن المنحدر ... صوت شقراق إذا قال قرر 1 يصف إبلا وشربها. فأظهر حرفي التضعيف، فإذا صرفوا ذلك في الفعل، قالوا: قرقر فيظهرون حروف المضاعف لظهور الراءين في قرقر، ولو حكى صوته وقال: قر، ومد الراء لكان تصريفه: قر يقر قريرا، كما يقال: صر يصر صريرا، وإذا خفف واظهر الحرفين جميعا، تحول الصوت من المد إلى الترجيع فضوعف لأن الترجيع يضاعف كله في تصريف الفعل إذا رجع الصائت، قالوا: صرصر وصلصل، على توهم المد في حال، والترجيع في حال. والقرقارة سميت لقرقرتها، والقرقور: من أطول السفن، وجمعه قراقير، قال النابغة: قراقير النبيط على التلال 2 وقراقر وقرقرى وقرورى وقران. وقراقري: مواضع كلها بأعيانها، وقران: قرية باليمامة ذات نخل وسيوح جارية، وقال علقمة بن عبدة يصف فرسا: سلاءة لعصا النهري غل لها ... ذو فيئة من نوى قران معجوم 3 وفي حديث ابن مسعود: قاروا الصلاة) 1 . ويوم القر اليوم الثاني من يوم النحر. قر الناس فيه بمنى. وفسر: أنهم قروا بعد التعب أي سكنوا. والقرقور: ودع للنساء.'),
(1643, 'رق', 'رق', 'رق', 'الرق: الصحيفة البيضاء، لقوله تعالى: في رق منشور 2 . والرق: العبودة 3 . ورق فلان: صار عبدا، وعن علي أنه قال: يحط عنه بقدر ما عتق ويسعى في ما رق منه 4 . والرق: من دواب الماء شبه التمساح، والتمسح أعرف. والرقة: مصدر الرقيق في كل شيء، يقال: فلان رقيق في الدين. والرقاق: أرض لينة يشبه ترابها الرمل اللينة، قال: ذاري الرقاق واثب الجراثم 5 . والرقة: كل أرض إلى جنب واد ينبسط عليها الماء أيام المد ثم ينحسر عنها فتكون مكرمة للنبات، والجميع الرقاق. والرقاق: الخبز الرقيق. والرقق: ضعف العظام، ورقت عظامه إذا كبر، قال: لم تلق في عظمها وهنا ولا رققا 1 وأرق فلان، في رقة المال والحال. والرقراق والرقرقة والترقرق: بصيص الشراب وتلألؤه، وما أشبه ذلك. وجارية رقراقة البشر. ورقرقت الثوب بالطيب، ورقرقت الثريد بالسمن والدسم'),
(1644, 'قل', 'قل', 'قل', 'قل الشيء فهو قليل، ورجل قليل: صغير الجثة، والقل: القليل، قال لبيد: كل بني حرة مصيرهم ... قل وإن أكثرت من العدد 2 . والقلال: القليل أيضا. والقلة والقلة لغتان، والقلة رأس كل شيء. والرجل يقل الشيء فيحمله، وكذلك يستقله. واستقل الطائر ارتفع من الأرض. واستقل النبات إذا أناف، والقوم إذا أمعنوا في مسيرهم. والقلقلة والتقلقل: قلة الثبوت في المكان. ويقال: مقلاق وقلق، المسمار السلس يتقلقل في موضعه إذا قلق. وفرس قلقل: جواد سريع. والقلقلة: شدة الصياح والإكثار في الكلام. والقلقل: شجر له حب أسود عظيم، يؤكل. والقلقلاني: طائر كالفاختة. والقلاقل: ضرب من النبات، وكذلك القلقلان، قال: كأن صوت حليها إذا انجفل ... هز رياح قلقلانا قد ذبل 1'),
(1645, 'لق', 'لق', 'لق', 'واللقلقة: شدة الصياح، واللقلاق: الصوت. واللقلاق: طائر أعجمي. واللقلقة: شدة اضطراب الشيء في تحركه، يقال: يتلقلق ويتقلقل، لغتان، قال: شبه الأفاعي خيفة تلقلق 2'),
(1646, 'قن', 'قن', 'قن', 'القن: العبد المتعبد، ويجمع على الأقنان، وهو الذي في العبودة الى آباء. والقنة: الجبل المنفرد المستطيل في السماء والجميع القنان. وقنان بن قنان اسم ملك كان يأخذ كل سفينة غصبا، كان من أشراف اليمن (بني) جلندى بن قنان. والقنينة: وعاء يتخذ من خيزران أو قضبان قد فصل داخله بحواجز بين مواضع الآنية على صيغة القشوة، والقشوة شيء يتخذ من مشارب يوضع فيه الزجاج. والقنان: أشد ما يكون من ريح الإبط. والقنقن: الدليل الهادي البصير بالماء تحت الأرض وحفر القني، ويجمع قناقن، قال الطرماح: يخافتن بعض المضغ من خشية الردى ... وينصتن للسمع انتصات القناقن 1 وقن القميص: كمه، وقنانه. والقنة: قوة (من قوى) حبل الليف ويجمع على قنن، قال: يصفح للقنة وجها جابا ... صفح ذراعيه لعظم كلبا 2 .'),
(1647, 'نق', 'نق', 'نق', 'النقيق والنقنقة من أصوات الضفادع، يفصل بينهما المد والترجيع. والنقنق: الظليم. والدجاجة تنقنق للبيض، ولا تنق لأنها ترجع في أصواتها، يقال: نقت ونقنقت. ونقنقت عينه إذا غارت، قال: خوص ذوات أعين نقانق 1'),
(1648, 'قف', 'قف', 'قف', 'القفة كهيئة القرعة تتخذ من خوص، قال: كل عجوز رأسها كالقفه 2 ويقال: شيخ كالقفة، واستقف الشيخ إذا انضم وتشنج فصار كالقفة وقف شعري أي قام إذا اقشعر من أمر. والقف: ما ارتفع من متون الأرض وصلبت حجارته، والجميع قفاف. والقف: قب الفأس 3 . وأقفت الدجاجة: كفت عن البيض للترخيم. والقفات: الجماعة. والقفقفة: اضطراب الحنكين والأسنان من برد ونحوه . فق: والفق والانفقاق: الانفراج، تقول: قد انفقت عوة 1 الكلب أي انفرجت. والفقفقة: حكاية بعض ذلك في تحرك عوائها.'),
(1649, 'قب', 'قب', 'قب', 'القب: ضرب من اللجم، أصعبها وأعظمها. ويقال لشيخ القوم هو قبهم. وقب الدبر: ما بين الأليتين ويعني ذلك المفرج، تقول: الزق قبك بالأرض. وقب اللحم يقب قبيبا أي ذهبت ندوته. وما أصابتنا قابة العام أي شيء من المطروق، قال خالد بن صفوان لابنه: إنك لا تفلح العام ولا قابل ولا قاب ولا قباقب ولا مقبقب كل كلمة من ذلك اسم للسنة بعد السنة. والقبقبة: حكاية صوت أنياب الفحل، وقبقب الفحل قبقابا، وقب أيضا. والقبب: دقة الخصر، والفعل: قبه يقبه قبا، وهو شدة الدمج للاستدارة، والنعت أقب، والجميع قب. ويقال للبصرة قبة الإسلام وخزانة العرب، وفعل القبة قببت قبة. والقبقب: البطن.'),
(1650, 'بق', 'بق', 'بق', 'البق: عظام البعوض، الواحدة بقة. والبقاق: أسقاط متاع البيت. ووضع حبر في بني إسرائيل سبعين كتابا من صنوف العلم فأوحى إلى نبي من أنبيائهم: أن قل لفلان إنك قد ملأت الأرض بقاقا، وإن الله لا يقبل من بقاقكم شيئا. ويقال لكثير الكلام: بقباق. والبقبقة: حكاية الصوت كما يبقبق الكوز في الماء.'),
(1651, 'قم', 'قم', 'قم', 'القم: ما يقم من القمامات والقماشات تجمعه بيدك. والمقمة: مرمة الشاة أي فمها، وتقمم في فيها ما أصابت على وجه الأرض. والقمة: رأس الإنسان، قال عبد الله بن الحر: صخم الفريسة لو أبصرت قمته ... بين الرجال إذن شبهته الجملا 1 والقمقام: صغار القرون، الواحدة بالهاء. والقمقام: العدد الكثير، قال [رؤبة] 1 : من خر في قمقامنا تقمقما أي غمر. وسيد قمقام وقماقم لكثرة خيره. والقمقام: البحر، قال: ولقد نزت بك من سفاهك بطنة ... أردتك حتى طحت في القمقام والقمقم والقمقمة معروفان.'),
(1652, 'مق', 'مق', 'مق', 'المق: الطول الفاحش في دقة. ورجل أمق وامرأة مقاء. والمقمقة: حكاية صوت من يتكلم بأقصى حلقه، تقول: فيه مقمقة.'),
(1653, 'شقص', 'شقص', 'شقص', 'الشقص: طائفة من الشيء، تقول: أعطيته شقصا من ماله. والمشقص: سهم له نصل عريض لرمي الوحش. والتشقيص في نعت الفرس: فراهية وجودة. ويجوز في الشعر. وهذه القطعة شقص من هذه الدار. والشنقاص ينسب إليه قوم من الجند يقال لهم: الشناقصة، الواحد شنقاصي. وفي الحديث: من لعب بالنرد فليشقص الخنازير وهو كالغامس يده في لحمانها يقسمها أجزاء.'),
(1654, 'شقد', 'شقد', 'شقد', 'الشقدة: حشيشة كثيرة الإهالة واللبن تطبخ بدقيق ولبن وأشياء، تؤكل، وهي القشدة أيضا.'),
(1655, 'شدق', 'شدق', 'شدق', 'الشدق: طفطفة 1 الفم من باطن الخدين، والأشدق: العريض الشدقين وما يليه. وتشدق في الكلام إذا فتح فاه. واللجام الشادق الداخل الفم، وشدقه يشدقه شدقا وأشدقته أنا إياه إشداقا.'),
(1656, 'دقش', 'دقش', 'دقش', 'قلت لأبي الدقيش: ما الدقش والدقيش؟ قال: لا أدري. قلت: فاكتنيت بكنية لا تدري؟ قال: إنما الكنى والأسماء علامات من شاء تسمى بما شاء لا قياس ولا حتم.'),
(1657, 'شقذ', 'شقذ', 'شقذ', 'الشقذ: فرخ القطا. والشقذان: الحرباء، وجمعه شقاذى، قال: فرعت بها حتى إذا ... رأت الشقاذى تصطلي 2 وقال بعضهم: هو الفراش في هذا الموضع، وهو خطأ. والشقذان من العقاب: الشديدة الجوع والطلب. وقد يقال للحشرات كلها الشقذان، الواحدة شقذة وشقذ 1 . وشقذ هو أي ذهب، وهو الشقذان، وأنشد: إذا غضبوا علي وأشقذوني 2'),
(1658, 'قشذ', 'قشذ', 'قشذ', 'قال أبو الدقيش. القشذة هي الزبدة الرقيقة، قال: ويقال: اقتشذنا شيئا جمعناه لنأكله. والقشذة شيء يتخذ من الزبد واللبن والسمن يعالج بالنار تسمن به الجواري، قال أبو خيرة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1659, 'قشر', 'قشر', 'قشر', 'القشر: سحفك القشر عن ذيه أي عن صاحبه. والأقشر: الذي اشتدت حمرته كأن بشرته متغيرة. وحية قشراء، وشجرة قشراء أيضا إذا كان بعضها قشر وبعضها لم يقشر. والقشرة والقشرة: مطرة تقشر الحصى عن وجه الأرض. ومطرة قاشرة: ذات قشرة. والقاشور: المشؤوم. ويقال: قشرهم أي شأمهم قال: اصبب عليهم سنة قاشوره 1 والقشارة: ما يقشر من شجرة أو غيرها من شيء دقيق. والقشور: اسم دواء. والقشرة: اسم للثوب، وكل ملبوس قشر وقشر الرجل لباسه. ولعنت القاشرة والمقشورة، وهي التي تقشر عن وجهها ليصفو اللون. والأقشر من اللحاء: ما قد انقشرت عنه سجاءته العليا، قال: حتى تلوى باللحاء الأقشر ... تلوية الخاتن زب المعذر 2 وبنو قشير بن كعب من قيس، وبنو قشر من عكل.'),
(1660, 'شقر', 'شقر', 'شقر', 'شقر شقرا وشقرة فهو أشقر أي أحمر، ودم أشقر أي صار علقا لم يعله غبار. ورجل أشقري: منسوب إلى الأشاقر، وهم حي من اليمن. والشقرة: هو السنجرف أي السخرنج، قال: عليه دماء البدن كالشقرات 3 . وبنو شقرة: قبيلة. والشقارى: نبات. والشقران: (داء يأخذ الزرع، وهو مثل الورس يعلو الأذنة ثم يصعد في الحب والثمر) 1 . والشقرقان: طائر بأرض الحرم في منابت النخل كقدر الهدهد مرقط بحمرة وخضرة وسواد وبياض. والشقراق: طائر فيه حمرة مخالطها خضرة.'),
(1661, 'رشق', 'رشق', 'رشق', 'الرشق والخزق بالرمي، ورشقناهم بالسهام رشقا. وإذا رمى أهل النضال ما معهم من السهام ثم عادوا، فكل شوط من ذلك رشق. والرشق والرشق لغتان، وهما صوت القلم إذا كتب به، قال موسى- عليه السلام-: كأني برشق القلم في مسامعي حين جرى على الألواح بكتبه التوراة. ويقال للغلام والجارية إذا كانا في اعتدال: إنه لرشيق، وإنها لرشيقة، ومرشق ومرشقة، ورشق رشاقة. ورشقت القوم ببصري، وأرشقت فنظرت أي طمحت ببصري فنظرت، قال ذو الرمة: كما أرشقت من تحت أرطى صريمة 2'),
(1662, 'شرق', 'شرق', 'شرق', 'شرق فلان بريقه، والشرق بالماء كالغص بالطعام، وهو أن يقع في غير مساغه، يقال: أخذته شرقة فكاد يموت. وشرق شرقا إذا اشتدت حمرته بدم أو بحسن لون أحمر، قال: وتشرق بالقول الذي قد أذعته 1 وصريح شرق بدمه. والشرق خلاف الغرب، والشروق كالطلوع، وشرق يشرق شروقا، ويقال لكل شيء طلع من قبل المشرق. وأما المستعمل فللشمس والقمر، ويجيء في الأشعار حتى الكواكب. والشرقي: الأحمر من الصبغ. والشرقي من الأرض والشجر ما تطلع عليه الشمس من لدن شروقها إلى نصف النهار، فإذا تجاوز فهو الغربي. والجانب الشرقي: الصقع الذي يلي المشرق. واشتقاق أيام التشريق من تشريقهم اللحم في الشمس بمنى. ويقال: أخذ من شروق الشمس وذلك وقت صلاته. والمشرق: المنير، وأشرقت الأرض بنور ربها 2 أضاءت بنور يسطع فيها، قال الشاعر: أشرقت دارنا وطاب فنانا ... واسترحنا من الثقيل الفراش 3 والفناء ممدود فقصر هاهنا. وأشرق وجه فلان أي تلألأ حسنا من الفرح والجمال. وشرق فلان أي صار لونه كالدم حياء وخجلا. والمشرقة: متشرق القوم في الشمس. وفي الحديث: لا تشريق ولا جمعة إلا في مصر جامع. وأشرق القوم: صاروا في وقت شروق الشمس. وقوله تعالى: فأخذتهم الصيحة مشرقين 1 . أي حيث طلعت عليهم الشمس، والشرق طائر بين الصقر والشاهين، يصيد، قال رؤبة: أجدل أو شرق من الشروق 2 وشرق الموتى إذا ارتفعت الشمس عن الطلوع، وتقول: تلك ساعة شرق الموتى. وشاة شرقاء: مشقوقة الأذنين نصفين.'),
(1663, 'قرش', 'قرش', 'قرش', 'القرش: الجمع من هاهنا وهاهنا، يضم بعضه إلى بعض، وسميت قريش لتجمعها إلى مكة حيث غلب عليها قصي بن كلاب، والنسبة إليهم قرشي وقريشي، قال: بكل قريشي عليه مهابة 3 والمقرشة: السنة الشديدة لاجتماع الناس وانضمام حواشيهم وقواصيهم، ويجمع مقرشات، قال: مقرشات الزمن المحذور 1 وقرشت واقترشت مثل كسبت واكتسبت. والقرش: سمك بالحجاز يقال له: كلب الماء.'),
(1664, 'رقش', 'رقش', 'رقش', 'الأرقش: لون فيه كدورة وسواد كلون الأفعى الرقشاء، والجندب الأرقش الظهر. وشقشقة رقشاء. والترقيش: الكتابة، ورقشت الكتاب: كتبته، قال مرقش: رقش، في ظهر الأديم، قلم 2 وبه سمي مرقشا والترقيش: التسطير أيضا. والجلاد يرقش في ظهر المجلود إذا سطر فيه. والترقيش: الصخب والمعاتبة، قال رؤبة: عاذل قد أولعت بالترقيش 3 . والخباز يرقش الخبز بالمرقش، وهو أصول الريش. ورقاش: حي من ربيعة'),
(1665, 'شقل', 'شقل', 'شقل', 'الشاقول: خشبة قدر ذراعين في الحبل، ثم يرزها الذراع في الأرض، وفي رأسها زج ويضبطها حتى يمد الحبل، واشتقوا منه أسماء للذكر فقالوا: شقلها بشاقوله. وشقلت الدنانير: عيرتها، وهي كلمة عبادية حيرية ليست بعربية محضة.'),
(1666, 'شلق', 'شلق', 'شلق', 'الشلق: شبه سمكة صغيرة، له رجلان عند ذنبه كرجل الضفدع، لا يدان له، يكون في أنهار البصرة، ليست بعربية. والشلق أيضا من الضرب والبضع ليست بعربية محضة. والشولقي الذي يبيع الحلاوة، وهو بالفارسية الرس.'),
(1667, 'قلش', 'قلش', 'قلش', 'الأقلش اسم أعجمي. وليس في كلام العرب شين بعد لام مع القاف إلا دخيل.'),
(1668, 'نقش', 'نقش', 'نقش', 'النقاشة: حرفة النقاش، نقول: نقش ينقش نقشا. والنقش: نتفك شيئا بالمنقاش بعد شيء. والمناقشة في الحساب: ألا يدع قليلا ولا كثيرا. وفي الحديث: من نوقش في الحساب فقد هلك ، وقال: إن تناقش يكن نقاشك يا رب ... عذابا لا طوق لي بالعذاب 1 والمنقشة: العجوز المتقبضة. والانتقاش: أن تنتقش على فصك، أي تأمر به. وإذا تخير الإنسان شيئا لنفسه يقال: جاد ما انتقشه لنفسه، قال الشاعر: وما اتخذت صداما للمكوث بها ... وما انتقشتك إلا للوصرات 2 قال: الوصرة: القبالة، وصدام اسم فرس.'),
(1669, 'شنق', 'شنق', 'شنق', 'الشنق: طول الرأس كأنما يمد صعدا. ويقال للفرس الطويل: شناق ومشنوق، قال: يممته بأسيل الخد منتقب ... خاظي البضيع كمثل الجذع مشنوق 3 والأنثى: شناق، وكل فعال في النعوت يستوي فيه الذكر والأنثى، يقال: شنق شنقا فهو مشنوق. وقلب شنق مشناق: طامح إلى كل شيء، وقد شنق قلبه شنقا إذا هوي شيئا فصار كالمتعلق به. وكل شيء يشد به شيء فهو شناق. وبعير شناق: طويل القرى، والجميع الشنق. والشناق في الحديث: ما بين الفريضتين فما زاد على العشرة لا يؤخذ منه شيء حتى تتم الفريضة الثانية، قال الشاعر: قرم تعلق أشناق الديات به ... إذا المئون أمرت فوقه جملا 1 وشنقت رأس الدابة إذا شددته إلى أعلى شجرة أو وتد مرتفع. وأشناق الديات أن تكون دون الحمالة بسوق دية كاملة، وهي مائة من الإبل، فإذا كان معها جراحات دون التمام فتلك أشناق لأنها أبعرة قلائل على قدر أرش الجراحة، وكأنما اشتقاق أشناقها من تعلقها بالدية العظمى، ثم عم ذلك الاسم حتى سميت بالأشناق من غير الدية العظمى.'),
(1670, 'نشق', 'نشق', 'نشق', 'النشق: صب سعوط في الأنف، وأنشقته الدواء. وأنشقته قطنة محرقة أي أدنيتها من أنفه ليدخل ريحها في أنفه وخياشيمه. والنشوق اسم كل دواء ينشق، واستنشقته أي تشممته، وقال المتلمس: فلو أن محموما بخيبر مدنفا ... تنشق رياها لأقلع صالبه 2 . ويقال: استنشق الريح فإنك لا تجد ما ترجو إذا أراد شيئا فخيبته. وريح مكروهة النشق أي الشم، قال رؤبة: حرا من الخردل مكروه النشق 3 . واستنشقت الماء: مددته بريح الأنف. ويقال: نشقت الدواء وانتشقته.'),
(1671, 'قشف', 'قشف', 'قشف', 'القشف: القذر على الجلد، ورجل متقشف: لا يتعاهد الغسل والنظافة، فهو قشف، ويخفف أيضا فيسكن الشين. وقشف قشافة وقشف قشفا فيمن ثعل أي لا يبالي ما تلطخ بجسده.'),
(1672, 'فشق', 'فشق', 'فشق', 'الفشق: المباغتة، ويقال: هو انتشار الحرص. والفشق: ضرب من الأكل في شدة.'),
(1673, 'شفق', 'شفق', 'شفق', 'الشفق: الرديء من الأشياء وقلما يجمع. وأشفقت أي جئت به شفقا. وأشفقت العطاء وشفقته تشفيقا: جعلته شفقا. وملحفة شفق، وثوب شفق سواء. والشفق: الخوف، وهو مشفق أي خائف. والشفق والشفقة: أن يكون الناصح من النصح خائفا على المنصوح، وأشفقت عليه أن يناله مكروه. والشفيق: الناصح الحريص على صلاح المنصوح. وقوله تعالى: إنا كنا قبل في أهلنا مشفقين 1 أي خائفين من هذا اليوم. والشفق: الحمرة من غروب الشمس إلى وقت العشاء (الأخيرة) 2'),
(1674, 'قفش', 'قفش', 'قفش', 'القفش، ساكن الفاء، ضرب من الأكل في شدة) . والقفش لا يستعمل إلا في الافتعال كالعنكبوت ونحوها إذا انجحر وضم إليه جراميزه وقوائمه، قال: كالعنكبوت اقتفشت في الجحر 3 ويقال: اقفنششت مكان اقتفشت.'),
(1675, 'قشب', 'قشب', 'قشب', 'كل شيء قدرته فقد قشبته فهو قشب. والقشب: خلط السم بالطعام. والقشب اسم السم، وكذلك كل شيء يخلط به شيء يفسده فقد قشبته. ورجل مقشب أي ممزوج الحسب. وقشب الشيء فهو قشب أي خولط بالقذر. والقشب: كل شيء حسن طري ناعم. والقشيب: الجديد، وقد قشب قشابة. وسيف قشيب: حديث الجلاء . شقب: الشقب، والجمع الشقبة: مواضع دون الغيران في لهوب الجبال ولصوب الأودية توكر فيها الطير، قال: فصبحت والطير في شقابها ... جمة تيار إذا طما بها 1 والشوقب: الطويل جدا من النعام والرجال والإبل، قال ذو الرمة: [شخت الجزارة مثل البيت سائره ... من المسوح] خدب شوقب خشب 2 . شبق: الشبق: شدة الغلمة، ورجل شبق، وامرأة بالهاء، وقد شبق شبقا، قال رؤبة: لا يترك الغيرة من عهد الشبق 3 . يصف الحمار.'),
(1676, 'بشق', 'بشق', 'بشق', '4 ولو اشتق من فعل الباشق بشق لجاز، وهي فارسية عربت للأجدل الصغير.'),
(1677, 'قشم', 'قشم', 'قشم', 'القشم: شدة الأكل وخلطه، وهو يقشم قشما. والقشم: اللحم إذا نضج واحمر فسال ودكه، الواحدة قشمة بلغة تغلب. والقشم: مسيل الماء في الروض، والجميع قشوم. وما أصابت الإبل مقشما أي ما ترعاه. والقشام: اسم ما يؤكل.'),
(1678, 'قمش', 'قمش', 'قمش', 'القمش: جمع القماش، وهو ما كان على وجه الأرض من فتات الأشياء. ويقال لرذالة الناس: قماش. ورأيته يتقمش أي يأكل ما وجد وإن كان دونا. وما أعطاني إلا قماشا أي أوتح ما قدر عليه وأردؤه. والقميشة: طعام للعرب من اللبن وحب الحنظل.'),
(1679, 'مشق', 'مشق', 'مشق', 'ثوب ممشق: مصبوغ بالمشق، وهو طين أحمر. والمشق: الضرب بالسوط، ومشقته أمشقه مشقا، قال: والعيس يحذرن السياط المشقا 1 . وقال: تنجو وأشقاهن تلقى مشقا 1 والمشق: شدة الأكل تأخذ النحضة فتمشقها بفيك مشقا أي جذبا. ومشقت الطعام مشقا أي أبقيت أكثر مما تأكل. والإبل تمشق الكلا مشقا إذا تناولت وهي تسير بأحمالها، ويقال: امشقوها أي دعوها تصيب من الكلا. والمشق: جذب الشيء ليمتد ويطول. والوتر يمشق حتى يلين ويجود كما يمشق الخياط خيطه بحزقه 2 وفرس مشيق وممشوق وممشق أي طويل. والمشق: جذب الكتان في ممشقة حتى يخلص خالصه وتبقى مشاقته، قال: [أتبدل] خزا خالصا بمشاقة 3 وكتاب مشق، مضاف مجرور، أي فرج وحد حروفه. وامشق الألف أي مدها، واكتب مشقا أي غير مقرمط. وجارية ممشوقة أي حسنة القوام قليلة اللحم.'),
(1680, 'شمق', 'شمق', 'شمق', 'الشمق: شبه مرح الجنون، وقد شمق شماقة، قال رؤبة: كأنه إذ راح مسلوس الشمق 1'),
(1681, 'قرض', 'قرض', 'قرض', 'أقرضته قرضا، وكل أمر يتجافاه الناس فيما بينهم فهو من القروض. والقرض: نطق الشعر، والقريض الاسم كالقصيد. والبعير يقرض جرته، وهو مضغها، والجرة المقروضة وهي القريض. وقولهم: حال الجريض دون القريض، يقال: الجريض الغصة، والقريض الجرة لأنه اذا غص لم يقدر على قرض جرته. ويقال في حديثه: إن رجلا نبغ له ابن شاعر فنهاه عن قرض 2 الشعر فكمد الغلام بما جاش في صدره من الشعر حتى مرض وثقل، فلما حضره 3 الموت، قال لأبيه: اكمد في القريض الممنوع، قال: فاقرض يا بني، قال: هيهات! حال الجريض دون القريض، ثم قال الغلام: عذيرك من أبيك يضيق صدرا ... فما يغني بيوت الشعر عني أتأمرني وقد فنيت حياتي ... بأبيات ترجيهن مني فأقسم لو بقيت أقول قولا ... أفوق به قوافي كل جن والقرض: القطع بالناب، والمقراض: الجلم الصغير. والقراضة: فضالة ما يقرض الفأر من خبز أو ثوب. وقراضات الثوب: ما ينفيها الجلم. وابن مقرض: ذو القوائم الأربع، طويل الظهر، قتال للحمام، بالفارسية: من نكر وتقول: قرضته يمنة ويسرة، إذا عدلت عن شيء في سيرك، أي تركته عن اليمين وعن الشمال، قال ذو الرمة: إلى ظعن يقرضن أجواز مشرف ... شمالا وعن أيمانهن الفوارس 1 والتقريض في كل شيء كتقريض عين الجعل.'),
(1682, 'نقض', 'نقض', 'نقض', 'النقض: إفساد ما أبرمت من حبل 2 أو بناء والنقض: البناء المنقوض، يعني اللبن إذا خرج منه. والنقض والنقضة هما الجمل والناقة اللذان هزلتهما الأسفار وأدبرتهما، والجميع الأنقاض، قال: إذا مطونا نقضة أو نقضا 3 والمناقضة في الأشياء، نحو الشعر، كشاعر ينقض قصيدة أخرى بغيرها، والاسم النقيضة ويجمع نقائض، ومن هذا نقائض جرير والفرزدق. والنقض: منتقض الكماة من الأرض إذا أرادت أن تخرج، ونقضتها نقضا فانتقضت منه، وجمعها أنقاض. والانتقاض: أن يعود الجرح بعد البرء، وكذلك انتقاض الأمور والثغور ونحوها. والنقيض: صوت الأصابع والمفاصل والأضلاع، وأنقضت الأضلاع والأصابع إنقاضا، ورأيته ينقض، وينقض أصابعه، قال: وحزن تنقض الأضلاع منه ... مقيم في الجوانح لن يزولا 1 . وقولك: أنقضت يعني أخذت الأصابع إنقاضا. ونقيض المحجمة: صوتها إذا شدها الحجام بمصه، قال:'),
(1683, 'قضف', 'قضف', 'قضف', 'قضف قضافة فهو قضيف أي قليل اللحم. والقضفة: أكمة كأنها حجر واحد وتجمع على قضف وقضاف، لا يخرج سيلها من بينها . ضفق: الضفق: الوضع بمرة، وضفق به: وضعه بمرة 1'),
(1684, 'قضم', 'قضم', 'قضم', 'القضم أكل كل شيء دون الخضم. والحمار يقضم الشعير، وقد اقضمته فقضم قضما. وفي الحديث: اخضموا فسوف نقضم أي كلوا فسوف نجتزيء بالقليل. والقضيم: الصحف البيض في شعر النابغة قال: كأن مجر الرامسات ذيولها ... عليه قضيم نمقته الصوانع 2'),
(1685, 'قصد', 'قصد', 'قصد', 'القصد استقامة الطريقة، وقصد يقصد قصدا فهو قاصد. والقصد في المعيشة ألا تسرف ولا تقتر. وفي الحديث: ما عال مقتصد ولا يعيل. والقصيد: ما تم شطرا أبنيته من الشعر. والقصيدة: مخة العظم إذا خرجت وانقصدت أي انفصلت من موضعها وخرجت. وانقصد الرمح أي انكسر نصفين حتى يبين، وكل قطعة منه قصدة، ويجمع على قصد، ورمح قصد أي قصم نصفين أو أكثر، بين القصد، قال: أقرو إليهم أنابيب القنا قصدا 1 أي قطعا. وانقصد الرمح، وقلما يقال: قصد إلا أن كل نعت على فعل لا يمتنع صدوره من انفعل. والقصد مشرة العضاه أيام الخريف تخرج بعد القيظ الورق في العضاه أغصان غضة رخاص تسمى كل واحدة منها قصدة. والمقتصد من الرجال الذي ليس بقصير ولا جسيم ويستعمل في غير الرجال، [وكذلك] المقصد من الرجال 2 . والإقصاد: القتل مكانه 3 ، قال: يا عين ما بالي أرى الدمع جامدا ... وقد أقصدت ريب المنية خالدا 4'),
(1686, 'صدق', 'صدق', 'صدق', 'الصدق: نقيض الكذب. ويقال للرجل الجواد والفرس الجواد: إنه لذو مصدق، أي صادق الحملة. وصدقته: قلت له صدقا، وكذلك من الوعيد إذا أوقعتهم قلت: صدقتهم. وهذا رجل صدق، مضاف، بمعنى نعم الرجل هو، وامرأة صدق، وقوم صدق. فإذا نعته قلت: هو الرجل الصدق، وهي الصدقة، وقوم صدقون، ونساء صدقات، قال: مقذوذة الأذان صدقات الحدق 1 أي نافذة الحدق. وفلان صديقي، وفلانة صديقتي، وإن قيل: هي له صديق على التكرار جاز، قال: وإذا أم عمار صديق مساعف 2 والصدق: الكامل من كل شيء. والصديق من يصدق بكل أمر الله والنبي- عليه السلام- لا يتخالجه شك في شيء. والصداقة مصدر الصديق، وقد صادقه مصادقة أي يصدقه النصيحة والمودة. والصداق والصدقة والصدقة: المهر. والمتصدق: المعطي للصدقة. وأصدق: آخذ الصدقات من الغنم، قال الأعشى: ود المصدق من بني عمرو ... أن القبائل كلها غنم 1'),
(1687, 'قصر', 'قصر', 'قصر', 'القصر: الغاية، وهو القصار والقصارى، قال العباس بن مرداس: لله درك لم تمنى موتنا ... والموت، ويحك، قصرنا والمرجع 2 والقصر: المجدل أي الفدن الضخم. وجمع المقصورة مقاصير، وهو حيث يقوم الإمام في المسجد. وهذا قصرك أي أجلك وموتك وغايتك. واقتصر على كذا أي قنع به. وقال في وصية: والشك لبني عمي قصرة أي يقصر به عليهم خاصة لا يعطى غيرهم. واقتصر على أمري أي أطاعني. والقصر: كفك نفسك عن شيء، وقصرت نفسي على كذا أقصرها قصرا. وقصرت طرفي أي لم أرفعه إلى ما لا ينبغي. وقاصر الطرف قريب من الخاشع. قاصرات الطرف* 1 في القرآن أي قصرن طرفهن على أزواجهن لا يرفعن إلى غيرهم ولا يردن بدلا. وقصرت لجام الدابة. وقصرت الصلاة قصرا وقصرتها. والقاصر: كل شيء قصر عنك، وأقصر عما كان عليه. وتقاصرت إليه نفسه ذلا. وقصرت عن هذا الأمر أقصر قصورا وقصرا، وأقصرت عنه أي كففت، قال الشاعر: لولا حبائل من نعم علقت بها ... لأقصر القلب عنها أي إقصار 2 وقصر عني الوجع قصورا أي ذهب. وقصر عني الغضب مثله إذا لم تغضب ونحو ذلك. وامرأة مقصورة الخطو، شبهت بالمقيد الذي يقصر القيد خطوه. وقصرت بفلان أي أعطيته مخسوسا، والتقصير فيما يشبه من هذا المعنى. وقصر الشيء قصرا، وهو خلاف طال طولا وقصرته أي صيرته قصيرا. والمقصورة: المحبوسة في بيتها وخدرها لا تخرج، قال: من الصيف مقصور عليها حجالها 3 والمقصور من نعت الحجال، والقصيرة: المرأة المحجوبة في الحجلة. وتقاصرت عن الشيء إذا لم أبلغه على عمد. والمقصورة: كل ناحية الدار على حيالها محصنة، قال: ومن دون ليلى مصمتات المقاصر 1 والقصيرى: الضلع التي تلي الشاكلة بين الجنب والبطن، والقصرى جائز. والقصار يقصر الثوب قصرا وقصارة، والقصارة فعله. والقوصرة: وعاء للتمر من قصب، ويخفف في لغة، قال: أفلح من كان له قوصره ... يأكل منها كل يوم مره 2 والقصر: كعابر الزرع الذي يخرج من البر وفيه بقية من الحب، وهي القصرى والقصارة. والقصرة: أصل العنق، وكذلك عنق النخلة أيضا، ويجمع القصر والقصرات. وقال أبو عبيدة: كان الحسن يقرأ إنها ترمي بشرر كالقصر، كأنه جمالات صفر 3 ويفسر أن الشرر يرتفع فوقهم كأعناق النخل ثم ينحط عليهم كالأينق السود. والقصر داء يأخذ في القصرة فتغلظ، وبعير قصر، ويجوز في الشعر أقصر، قد قصر قصرا من قصر، وهو الكزاز. وجاءت نادرة عن الأعشى [وهي] جمع قصيرة على قصارة قال: لا ناقصي حسب ولا ... أيد إذا مدت قصاره 4 والقصر معروف، وجمعه قصور والقصر: قبل اصفرار الشمس لأنك تقتصر على أمر قبل غروب الشمس سميت بهذا. وأقصرنا: صرنا في ذلك الوقت.'),
(1688, 'صقر', 'صقر', 'صقر', 'الصقر من الجوارح، وبالسين جائز. والصاقرة والصاقورة: النازلة الشديدة، لم يسمع إلا بالصاد والصاقورة: اسم السماء الدنيا. والصاقورة: باطن القحف المشرف على الدماغ فوقه كأنه قعر قصعة. والصاقورة: المطرقة. والصقر لغة في السقر، وهو شدة الوقع، قال: إذا مالت الشمس اتقى صقراتها 1 يعني شدة وقع الشمس. والصقر: ما تحلب من العنب والتمر 2 من غير عصر. وما مصل من اللبن فآنمازت خثارته، وصفت صفوته فإذا حمضت كانت صباغا طيبا، ويجوز بالسين. والصوقرير: حكاية صوت طائر يصوقر 3 ، في صياحه تسمع نحو هذه النغمة في صوته. ولا تنكر السين في كل صاد تجيء قبل القاف.'),
(1689, 'قرص', 'قرص', 'قرص', 'قرصه بلسانه وإصبعه يقرصه قرصا أي تقبض على الجلد بإصبعين غمزة توجعه. ولا تزال تقرصني منهم قرصة أي كلمة مؤذية، قال: قوارص تأتيني وتحتقرونها ... وقد يملأ القطر الإناء فيفعم 1 والقرص من الخبز وشبهه، والجميع القرصة، والواحدة الصغيرة قرصة، والتذكير أعم. والقرص: عين الشمس عند الغروب. ولبن وشراب قارص: يحذي اللسان. والقريص لغة في القريس. وقرصت العجين: قطعته قرصة. وكل ما أخذت شيئا بين شيئين وعصرت أو قطعت فقد قرصته. والقراص: نبات، قال الأخطل: كأنه من ندى القراص مختضب 2 الواحدة قراصة'),
(1690, 'رقص', 'رقص', 'رقص', 'الرقص والرقص والرقصان ثلاث لغات. ولا يقال يرقص إلا للاعب والإبل ونحوه، وما سوى ذلك ينقز ويقفز. والسراب أيضا يرقص، والحمار إذا لاعب عانته، قال: حتى إذا رقص اللوامع بالضحى ... واجتاب أردية السراب ركامها 1 والنبيذ إذا جاش [فهو يرقص] ، قال حسان: بزجاجة رقصت بما في قعرها ... رقص القلوص براكب مستعجل 2'),
(1691, 'قلص', 'قلص', 'قلص', 'قلص الشيء يقلص قلوصا أي انضم إلى أصله. وفرس مقلص: طويل القوائم منضم البطن. وقميص مقلص. وقلصت الإبل تقليصا: استمرت في مضيها. وثوب قالص، وظل قالص، وقال: يطلب في الجندل ظلا قالصا 3 وقلص الغدير تقليصا: ذهب ماؤه إلا قليلا. والقلوص: كل أنثى من الإبل من حين تركب إلى أن تبزل 1 ، وسميت لطول قوائمها ولم تجسم بعد. والقلوص: الأنثى من النعام، وهي الضخمة من الحباري أيضا.'),
(1692, 'صلق', 'صلق', 'صلق', 'الصلق: الصدمة، قال لبيد: فصلقنا في مراد صلقة والصلق: صوت أنياب البعير إذا صلقها وضرب بعضها ببعض، وأصلقت أنيابه. والصلقة: تصادم الأنياب. وتصلقت المرأة عند الطلق: ألقت نفسها مرة ومرة كذا، وكذلك كل ذي ألم إذا تصلق على جنبيه. وقاع صلق: مستديرة ملساء، فإن كان بها شجر فقليل، ويجمع أصالق، والسين لغة، قال أبو دواد: ترى فاه إذا أقبل ... مثل الصلق الجدب 2 يصف سعة فم الفرس. والصلائق: الخبز الرقيق، قال الشاعر: تكلفني معيشة آل زيد ... ومن لي بالصلائق والصناب 3'),
(1693, 'لصق', 'لصق', 'لصق', 'لصق يلصق لصوقا، لغة تميم، ولسق أحسن لقيس، ولزق لربيعة وهي أقبحها إلا في أشياء نصفها في حدودها. والملصق: الدعي.'),
(1694, 'قصل', 'قصل', 'قصل', 'القصل: قطع الشيء من وسطه أو أسفله قطعا وحيا. وسمي قصيل الدابة لسرعة اقتصاله من رخاصته. وسيف قصال أي قطاع ومقصل أيضا. وما يعزل عن البر إذا نقي ثم لين ثانية فهو قصالة.'),
(1695, 'صقل', 'صقل', 'صقل', 'الصقلان: القرنان من كل دابة، قال: من خلفها لاحق الصقلين همهيم 1 . والصقل: الجلاء، وبالسين جائز. والمصقلة: التي يصقل بها الصيقل سيفه.'),
(1696, 'لقص', 'لقص', 'لقص', 'لقص الرجل يلقص لقصا فهو لقص: كثير الكلام سريع إلى الشر.'),
(1697, 'نقص', 'نقص', 'نقص', 'النقص: الخسران في الحظ، والنقصان مصدر، ويكون قدر الشيء الذاهب، من المنقوص، اسم له. ونقص الشيء نقصا ونقصانا، مصدر، ونقصانه كذا وكذا، وهذا قدر الذي ذهب. ونقصته أنا، يستوي فيه اللازم والمجاوز. والنقيصه: الوقيعة في الناس، والانتقاص الفعل، وانتقصت حقه إذا نقصته مرة بعد مرة. وتقول: ليست عليه منقصة في عيشه.'),
(1698, 'قنص', 'قنص', 'قنص', 'القنص والقنيص: الصيد. والقانص والقناص: الصياد، وصدت وقنصت واصطدت واقتنصت يستوي تصريفها. والقانصة: هنة كحجيرة في بطن الطائر، ويجوز بالسين. والقنيص جماعة القانص كالحجيج جمع الحاج، قال الأخطل: آنس صوت قنيص أو أحس بهم ... كالجن يقفون من جرم وأنمار 1'),
(1699, 'قصف', 'قصف', 'قصف', 'القصف: كسر قناة، ونحوها نصفين. يقال: قصفتها إذا انكسرت ولم تبن، فإذا بانت قيل: انقصفت. ورجل قصف: سريع الانكسار عن النجدة. وانقصف القوم عن كذا إذا خلوا عنه فترة وخذلانا. والأقصف: الذي انكسرت ثنيته من النصف، وثنية قصفاء. والقصف: اللعب واللهو. والقاصف: الريح الشديدة تقصف الشجرة أي تكسرها. وقصف البعير أنيابه يقصفها قصفا وقصيفا، وهو صريف أنيابه.'),
(1700, 'صفق', 'صفق', 'صفق', 'وصفقا العنق جانباه، وأصل ذلك الصفق أي السقع. وانصفق القوم يمينا وشمالا، والريح تصفق الثوب في كل صفق أي يضطرب. واصطفق القوم: اضطربوا. وصفقت رأسه بيدي، وعينه صفقة أي ضربة. وصفاق البطن: الجلد الباطن الذي يلي سواد البطن، ويقال: جلد البطن كله صفاق. والصفقة: ضرب اليد على اليد في البيع والبيعة. واصطفق القوم على أمير واحد أي اجتمعوا عليه، والسين جائز في كله.'),
(1701, 'قفص', 'قفص', 'قفص', 'القفص للطير، والسين لا يجوز. ورجل قفص: منقبض بعضه إلى بعض.'),
(1702, 'فقص', 'فقص', 'فقص', 'الفقوص: الفقوص: البطيخ، بلغة مصر: الذي لم ينضج.'),
(1703, 'قصب', 'قصب', 'قصب', 'القصب: ثياب من كتان ناعمة رقاق، والواحد قصبي. وكل نبت ساقه ذو أنابيب فهو قصب، وقصب الزرع تقصيبا. والقصب: عظام اليدين والرجلين، وقصبة الأنف عظمه، وكل عظيم مستدير أجوف. وما اتخذ من فضة أو غيرها قصب. والقصباء: القصب الكثير في مقصبته. وقصب الرئة عروق غلاظ فيها، وهي مخارج النفس ومجاريه. والقصبة: جوف القصر أو جوف الحصن يبنى فيه بناء هو أوسطه. والقصبة خصلة من الشعر تلتوي فإذا أنت قصبتها كانت تقصيبة، وتجمع تقاصيب، قال بشار: وفرع زان متنيك ... وزانته التقاصيب 1 وهو أن تضمها ليا إلى أصلها وتشدها فتصبح تقاصيب. وفلان يقصب فلانا: يمزقه ويذكره بالقبيح. والقصب: القطع، والقصاب يقصب الشاة ويفصل أعضاءها تقصيبا. والقصب من الجوهر: ما كان مستطيلا أجوف. ولخديجة بيت في الجنة من قصب لا وصب فيه ولا نصب أي لا داء فيه ولا عناء. والقصب: الأمعاء كلها، وجمعه أقصاب. والقاصب: الزامر.'),
(1704, 'صقب', 'صقب', 'صقب', 'الصقب والسقب الطويل مع ترارة في كل شيء. والصقب: القرب، وبالسين لغة. ويقال للفصيل والفصيلة سقب وسقبة ويقال للغصن الطويل الريان سقب، قال ذو الرمة: سقبان لم يتقشر عنهما النجب 2'),
(1705, 'قبص', 'قبص', 'قبص', 'القبص: التناول بأطراف الأصابع. ويروى: فقبصت قبصة 1 ، أي أخذت من أثر دابة جبرئيل- ع. من التراب بأطراف أصابعي. وفرس قبوص أي إذا جرى لم يصب الأرض إلا أطراف سنابكه من قدم، ويقال: هو الرشيق الخلق، قال: سليم الرجع طهطاه قبوص 2 والقبص، والقبص أجود،: مجمع النمل الكثير. وتقول: إنهم لفي قبص من العدد، وفي قبص الحصى أي في كثرة لا يستطاع عده. والقبص: ارتفاع في الرأس وعظم، وقبص قبصا فهو رجل أقبص الرأس ضخم مدور، قال: قبصاء لم تنطح ولم تكتل 3'),
(1706, 'بصق', 'بصق', 'بصق', 'بصق لغة في بسق، وبصاق الجراد لعابه. والبصاق: هنات من الحرة تبدو منها إلى المستوى، الواحدة بصقة كأن الحر بصقها بصقا 4'),
(1707, 'قصم', 'قصم', 'قصم', 'القصم: دق الشيء، وقصم الله ظهره، قال: إذا نزلت بالمرء قاصمة الظهر 1 ورجل قصم: هار ضعيف سريع الانكسار، وفتاة قصمة: منكسرة. وأقصم أعم وأكثر من الأقصف أي الذي انقصمت ثنيته من النصف.'),
(1708, 'قمص', 'قمص', 'قمص', 'القماص: ألا يستقر في موضع، تراه يقمص فيثب من مكانه من غير صبر. يقال للقلق: أخذه القماص. والقمص: ذباب صغار فوق الماء، الواحدة قمصة. والقمص: الجراد أول ما يخرج من بيضه. والقميص مذكر وقد أنثه جرير وأراد به الدرع، قال: تدعو هوازن والقميص مفاضة ... تحت النطاق تشد بالأزرار 2'),
(1709, 'قسط', 'قسط', 'قسط', 'القسط: عود هندي يجعل في البخور والدواء. والقسوط: الميل عن الحق، وقسط يقسط فهو قاسط، قال: يشفى من الغيظ قسوط القاسط 1 ورجل قسطاء: في ساقها اعوجاج حتى تتنحى القدمان وتنضم الساقان. والقسط خلاف الفحج. والإقساط: العدل في القسمة والحكم، وتقول: أقسطت بينهم وأقسطت إليهم. والقسط: الحصة التي تنوبه، وتقسطوا بينهم الشيء أي اقتسموه بالتسوية فكل مقدار قسط في كل شيء. والقسطاس والقسطاس: أقوم الموازين، وبعضهم يفسره الشاهين.'),
(1710, 'سقط', 'سقط', 'سقط', 'السقط والسقط، لغتان: الولد المسقط، الذكر والأنثى فيه سواء. والسقط: ما سقط من النار، قال: وسقط كعين الديك عاورت صحبتي ... أباها وهيأنا لموقعها وكرا 2 وسقط البيت نحو الإبرة والفأس والقدر، ويجمع على أسقاط. والسقط من البيع نحو السكر والتوابل، وبياعه سقاط. وقال بعضهم: بل يقال: صاحب سقط. والسقط: الخطأ في الكتابة والحسابة. والسقط من الأشياء: ما تسقطه فلا تعتد به. والسقط من الجند والقوم ونحوهم. والساقطة: اللئيم في حسبه ونفسه، وهو الساقط أيضا، قال: نحن الصميم وهم السواقط 1 ويقال للمرأة الدنيئة الحمقاء: سقيطة. والسقاطات: ما لا يعتد به تهاونا من رذالة الثياب والطعام ونحوه. ويقال: سقط الولد من بطن أمه، ولا يقال: وقع، هذا حين يولد. وهو يحن إلى مسقطه أي إلى حيث ولد. والمسقط مسقط الرمل، وهو حيث ينتهي إليه طرفه، وسقطه أيضا. وسقط السحاب: طرف منه كأنه ساقط في الأرض من ناحية الأفق، وكذلك سقط الخباء، وسقط جناحي الظليم ونحوه إذا رأيتهما ينحوان على الأرض، قال: عنس مذكرة كأن عفاءها ... سقطان من كفي ظليم جافل 2 والسقاط في الفرس: ألا يزال منكوبا، وكذلك إذا جاء مسترخي المشي، والعدو، ويقال: يساقط العدو سقاطا. وإذا لم يلحق الإنسان ملحق الكرام يقال: قد تساقط، قال سويد بن أبي كاهل: كيف يرجون سقاطي بعد ما ... لفع الرأس مشيب وصلع 1'),
(1711, 'قسد', 'قسد', 'قسد', 'القسود: الغليظ الرقبة القوي، قال: ضخم الذفارى قاسيا قسودا 2'),
(1712, 'قدس', 'قدس', 'قدس', 'القدس: تنزيه 3 الله، وهو القدوس والمقدس [والمتقدس] . والقداس: الجمان من فضة.'),
(1713, 'دسق', 'دسق', 'دسق', 'الدسق: امتلاء الحوض حتى يفيض على جوانبه، وأدسقته فدسق. والديسق: الحوض الملآن، قال رؤبة: يردن تحت الأثل سياح الدسق 1 والديسق: السراب إذا اشتد جريه، قال: هابي العشيات يسمى الديسقا 2'),
(1714, 'دقس', 'دقس', 'دقس', 'الدقيوس: اسم الملك الذي بنى مسجدا على أصحاب الكهف، ويقال: دقيوس، ويقال: دقينوس، لغات.'),
(1715, 'ستق', 'ستق', 'ستق', 'المستقة: فرو طويل الكمين.'),
(1716, 'قسر', 'قسر', 'قسر', 'القسور: الصياد والراعي، والجميع قسورة. والقسر: القهر على الكره. يقال: قسرته قسرا، واقتسرته أعم. وفرت من قسورة 1 أي رماة، ويقال: أسد. والقسوري: الرامي. والقيسري: الضخم الشديد المنيع.'),
(1717, 'سقر', 'سقر', 'سقر', 'السقر لغة في الصقر. وسقر: اسم معرفة لجهنم نعوذ بالله منها.'),
(1718, 'قرس', 'قرس', 'قرس', 'القرس: أكثر الصقيع وأبرده، قال العجاج: تقذفنا بالقرس بعد القرس ... دون ظهار اللبس بعد اللبس 2 وقرس المقرور: لا يستطيع عملا بيديه من شدة الخصر، قال أبو زبيد: فقد تصليت حر حربهم ... كما تصلى المقرور من قرس 3 وأقرسه البرد، وإنما سمي القريس قريسا لأنه يجمد فيصير ليس بجامس 4 ولا ذائب. وقرسنا قريسا وتركناه حتى أقرسه البرد. وقد أقرس العود أي جمس ماؤه من البرد. والقراسية: الجمل الضخم. وناقة قراسية أيضا، وفي الفحول أعم،: ليست نسبة أيضا، إنما هي على بناء رباعية، وهذه ياءات تزاد، قال جرير: يكفي بنى سعد إذا ما حاربوا ... عز قداسية وجد مدفع 1'),
(1719, 'سرق', 'سرق', 'سرق', 'السرق: أجود الحرير، الواحدة سرقة، قال: يرفلن في سرق الحرير وخزه 2 وتقول: برئت إليك من الاباق والسرق، في بيع العبد. والسرق: مصدر، والسرقة اسم. والاستراق: الختل كالذي يسترق السمع أي يقرب من السماء فيستمع ثم يذيع واليوم يرجم 3 ، وكالكتبة يسترقون من بعض المحاسبات. والاستراق: أن يحبس إنسان نفسه من قوم ليذهب، كالمسارقة.'),
(1720, 'سلق', 'سلق', 'سلق', 'سلقته باللسان: أسمعته ما كره فأكثرت عليه. ولسان مسلق: حديد ذلق. والسلق: نبات. والسلقة: الذئبة. والسلاق: بثر يخرج على اللسان. والسليقة: مخرج النسع في دف البعير، واشتقاقه من: سلقت الشيء بالماء الحار، وهو أن يذهب الوبر والشعر ويبقى أثره، فلما أحرقته الحبال شبه بذلك فسميت سلائق، قال: تبرق في دفها سلائقها 1 والسلوقي من الكلاب والدروع: أجودها، قال: تقد السلوقي المضاعف نسجه 2 والسليقي من الكلام: ما لا يتعاهد إعرابه، وهو في ذلك فصيح بليغ في السمع عثور في النحو. والتسلق: الصعود على حائط أملس. والسليقة: الطبيعة، ويجمع سلائق. والأسلاق من الأرض: معشبة، الواحد سلق، قال الأعشى: [كخذول ترعى النواصف من تثليث ... قفرا] خلالها الأسلاق 3'),
(1721, 'لسق', 'لسق', 'لسق', 'اللسق 4 : إذا التزقت الرئة بالجنب من شدة العطش قيل: لسقت لسقا، قال رؤبة: وبل برد الماء أعضاد اللسق 1 أي نواحيه. واللسوق كاللزوق في كل التصريف.'),
(1722, 'سقل', 'سقل', 'سقل', 'السقل: الصقل، لغة فيه.'),
(1723, 'لقس', 'لقس', 'لقس', 'اللقس: الشره النفس، الحريص على كل شيء، ولقست نفسه إلى الشيء: نازعته حرصا. وفي الحديث: لا تقل خبثت نفسي، ولكن لقست.'),
(1724, 'قلس', 'قلس', 'قلس', 'القلس: حبل ضخم من ليف أو خوص. والقلس: ما خرج من الحلق ملء الفم أو دونه، وليس بقيء، فإذا غلب فهو القيء، يقال: قلس الرجل يقلس قلسا، وهو خروج القلس من حلقه. والسحابة تقلس الندى إذا رمت به من غير مطر شديد: قال ندى الرمل مجته العهاد القوالس 2 والتقلس: لبس القلنسوة، والقلاس صاحبها وصانعها، والجميع قلانس وقلاسي، ويصغر: قليسية بالياء، وقلنسية بالنون. وقلنسية، وتجمع على القلنسي، قال: أهل الرياط البيض والقلنسي 1 والتقليس: وضع اليدين على الصدر خضوعا كفعل النصراني قبل أن يكفر أي يسجد. وفي الحديث: لما رأوه قلسوا ثم كفروا أي سجدوا. والأنقلس، بنصب اللام والألف، ويكسران أيضا، وهو سمكة على خلقة حية يقال لها: مارماهي 2 .'),
(1725, 'قسن', 'قسن', 'قسن', 'القسين: الشيخ القديم، قال الراجز: وهم كمثل البازل القسين 3 وإذا اشتقوا من القسين فعلا همزوا فقالوا اقسأن، لأن الياء لا تجيء في عماد أواخر الأفعال، قال: إن تك لدنا لينا فإني ... ما شئت من أشمط مقسئن 4 وأقسأن الليل: اشتدت ظلمته، قال العجاج: بت لها يقظان واقسأنت 1'),
(1726, 'نقس', 'نقس', 'نقس', 'واحد الأنقاس نقس. والنقس: ضرب الناقوس وهو الخشبة الطويلة، والوبيل: الخشبة القصيرة. ونقس الناقوس نقسا.'),
(1727, 'قنس', 'قنس', 'قنس', 'القنس تسميه الفرس الراسن. والقنس: منبت كل شيء ومعتمده، قال العجاج: في قنس مجد فوق كل قنس 2 وقونس الفرس: ما بين أذنيه من الرأس، وكذلك قونس البيضة من السلاح.'),
(1728, 'سنق', 'سنق', 'سنق', 'سنق الحمار وكل دابة سنقا إذا أكل من الرطبة حتى يكاد يصيبه كالبشم، وهو الأجم بعينه إلا أن الأجم يستعمل في الناس. وسنق الفصيل أي كاد يموت من كثرة اللبن، فإذا مرض قيل: بشم ودفي، قال الأعشى: ويأمر لليحموم كل عشية ... بقت وتعليق فقد كاد يسنق 1'),
(1729, 'نسق', 'نسق', 'نسق', 'النسق من كل شيء: ما كان على نظام واحد عام في الأشياء. ونسقته نسقا ونسقته تنسيقا، ونقول: انتسقت هذه الأشياء بعضها إلى بعض أي تنسقت.'),
(1730, 'سقف', 'سقف', 'سقف', 'السقف: عماد البيت، والسماء سقف فوق الأرض، وبه ذكر، قال تعالى: السماء منفطر به 2 . والزقف: لغة الأزد في السقف، يقولون: ازدقف، أي: استقف والسقيفة: كل بناء سقف به صفه أو شبه صفة مما يكون بارزا، ألزم هذا الاسم لتفرقة ما بين الأسماء. والسقيفة: كل خشبة عريضة كاللوح، وحجر عريض يستطاع أن يسقف به قترة أو غيرها، والصاد لغة، قال: لناموسه من الصفيح سقائف 3 وسقائف جنب البعير: أضلاعه، الواحدة سقيفة. والأسقف: رأس من رءوس النصارى، ويجمع أساقفة.'),
(1731, 'فسق', 'فسق', 'فسق', 'الفسق: الترك لأمر الله، وفسق يفسق فسقا وفسوقا. وكذلك الميل إلى المعصية كما فسق إبليس عن أمر ربه. ورجل فسق وفسيق، قال: ائت غلاما كالفنيق ناشئا ... أبلج فسيقا كذوبا خاطئا 1 وقال سليمان: عاشوا بذلك عرسا في زمانهم ... لا يظهر الجور فيهم آمنا فسق والفويسقة: الفأرة، وقد أمر النبي- عليه السلام- بقتلها في الحرم.'),
(1732, 'سفق', 'سفق', 'سفق', 'السفق لغة في الصفق. وسفق الثوب سفاقة فهو سفيق أي ليس بسخيف. ورجل سفيق الوجه أي قليل الحياء. وسفقت الباب فأسفق. والسفيقة: خشبة عريضة، دقيقة طويلة، تلف عليها البواري فوق سطوح أهل البصرة، هكذا رأيتهم يسمونها. وكل ضريبة من الذهب والفضة والجواهر إذا ضربت دقيقة طويلة فهي سفيقة. وسفاسق السيوف، الواحدة سفسقة وهي شطبته كأنها عمود في متنه، ممدود كالخط، ويقال: بل هو ما بين الشطبتين على صفحة السيف طولا، قال امرؤ القيس: ومستلئم كشفت بالرمح ذيله ... أقمت بعضب ذي سفاسق ميله 1'),
(1733, 'فقس', 'فقس', 'فقس', 'المفقاس: عودان يشد طرفاهما بخيط كما يشد في وسط الفخ، ثم يبل أحدهما، ثم يجعل بينهما شيء، يشدهما، ثم توضع فوقهما الشركة، فإذا أصابها شيء فقست أي وثبت ثم علقت الشركة في الصيد. وإذا مات الميت يقال: فقس فقوسا، هكذا أخبرنيه أبو الدقيش.'),
(1734, 'قفس', 'قفس', 'قفس', 'القفس: جيل بكرمان، في جبالها كالأكراد، قال: زط وأكراد وقفس قفس 2 وأمة قفساء أي رديئة لئيمة، نعت للأمة خاصة.'),
(1735, 'قسب', 'قسب', 'قسب', 'القسب: تمر يابس يتفتت في الفم، والصاد خطأ. والقسب: الصلب الشديد، يقال: إنه لقسب العلباء أي صلب العقب والعصب، وقسب قسوبة. والقسيب: صوت الماء تحت الورق أو القماش، قال: للماء من تحته قسيب 1 وقال: قسب العلابي جراء الألغاد 2'),
(1736, 'سقب', 'سقب', 'سقب', 'السقب لغة في الصقب. والسقيبة: عمود الخباء، قال: كسقف خباء خر فوق السقائب والسقب: ولد الناقة. وأسقبت الناقة أي أكثرت وضعها الذكر، وهي مسقاب، قال رؤبة: غراء مسقابا لفحل أسقبا 3 يعني فعلا ماضيا على أسقب يسقب، ولم يجعله نعتا. والسقب: الغصن الطويل الريان. وسألت أبا الدقيش عن قول أبي دواد: ... كالقمر السقب 1 قال: هو الذي امتلأ وتم، عام في كل شيء من نحوه. والسقب: القرب، والجار القريب أحق بسقبه 2 .'),
(1737, 'سبق', 'سبق', 'سبق', 'السبق: القدمة، وتقول: له في الجري وفي الأمر سبق وسبقه وسابقه أي سبق الناس إليه. والسبق: الخطر يوضع بين أهل السباق، وجمعه أسباق. والسباقان: قيد أرجل الطائر الجارح بسير أو خيط.'),
(1738, 'بسق', 'بسق', 'بسق', 'بسق وبصق وبزق لغات وبساق: جبل بالحجاز مما يلي الغور. وبسقت النخلة بسوقا: طالت وكملت. وقوله تعالى: والنخل باسقات 3 أي طويلات. وأبسقت الشاة فهي مبسق وبسوق ومبساق أي انزلت اللبن قبل الولاد بشهر أو أكثر فتحلب، وربما بسقت وليس بحامل فأنزلت اللبن. وقد سمعت أن الجارية تبسق وهي بكر ويصير في ثديها لبن.'),
(1739, 'قبس', 'قبس', 'قبس', 'القبس: شعلة من نار تقبسها وتقتبسها أي تأخذ من معظم النار. وقبست النار، واقتبست رجلا نارا أو خيرا. وقبست العلم واقتبسته. وأقبست العلم فلانا. وأبو قبيس: جبل مشرف على مكة.'),
(1740, 'قسم', 'قسم', 'قسم', 'القسم مصدر قسم يقسم قسما، والقسمة مصدر الاقتسام، ويقال أيضا: قسم بينهم قسمة. والقسم 1 : الحظ من الخير ويجمع على أقسام. والقسم: اليمين، ويجمع على أقسام، والفعل: أقسم. وقوله تعالى: فلا أقسم* 2 بمعنى أقسم ولا صلة. والقسيم: الذي يقاسمك أرضا أو مالا بينك وبينه. وهذه الأرض قسيمة هذه أي عزلت منها، وهذا المكان قسيم هذا ونحوه. والقسام: من يقسم الأرضين بين الناس، وهو القاسم. والاستقسام: [أنهم] كانوا يجيلون السهام أي الأزلام عند الأصنام فما يهمون به من الأمور العظام مثل تزويج أو سفر، كتب على وجهي القدح: أخرج، لا تخرج، تزوج، لا تتزوج، ثم يقعد عند الصنم بكفره، أي الأمرين كان خيرا إلي فأذن لي فيه حتى أفعله، ثم يجيل، فأي الوجهين خرج فعل راضيا به قسما وحظا. وحصاة القسم ونواة القسم 1 أنهم إذا قل ماؤهم في المفاوز عمدوا إلى غمر فألقوا فيه تلك الحصاة أو النواة ثم صبوا عليه من الماء قدر ما يغمرها حتى يستوي بأعلاها فيعطى كل إنسان شربة من ذلك الماء بمقدار واحد على ما وصفت. والأقاسيم: الحظوظ المقسومة بين العباد واختلفوا فقالوا: الواحدة أقسومة، ويقال: بل هي جماعة الجماعة كالأظفار والأظافير. والقسيم من الرجال: الحسن الخلق، والقسمة: الوجه، قال الشاعر: كأن دنانيرا على قسماتهم ... وإن كان قد شف الوجوه لقاء 2'),
(1741, 'سقم', 'سقم', 'سقم', 'السقم والسقم والسقام لغات، وقد سقم الرجل فهو سقيم مسقام.'),
(1742, 'مقس', 'مقس', 'مقس', 'مقست نفسه وتمقست أيضا نفسه أي غثيت.'),
(1743, 'قمس', 'قمس', 'قمس', 'كل شيء ينغط في الماء ثم يرتفع فقد قمس، والقيزان كذلك، والقنان وهي أكام القفاف إذا اضطرب السراب حواليها قيل: قمست، قال رؤبة في نعت القيزان: بيدا ترى قيزانهن قسا ... بوازيا مرا ومرا قمسا 1 2 ... أي بدت بعد ما تخفى [كذا] ، يصف رؤبة قيزانا أنهن يتقمسن في السراب. وفي المثل: بلغ قوله قاموس البحر أي قعره الأقصى.'),
(1744, 'سمق', 'سمق', 'سمق', 'سمق النبات: بلغ غاية الطول. ونخلة سامقة: طويلة جدا. والسميقان: (خشبات يدخلن في الآلة) 3 التي ينقل عليها اللبن، والسميقان في النير عودان قد لوقي بين طرفيهما تحت غبغب الثور شدا بخيط، وتجمع أسمقة. والسمسق: الياسمين.'),
(1745, 'زقد', 'زقد', 'زقد', 'الزقد كلمة يمانية،'),
(1746, 'زدق', 'زدق', 'زدق', 'وزدق لغة لهم في صدق.'),
(1747, 'رزق', 'رزق', 'رزق', 'رزق الله يرزق العباد رزقا اعتمدوا عليه، وهو الاسم أخرج على المصدر وقيل: رزق. وإذا أخذ الجند أرزاقهم، قيل: ارتزقوا رزقة واحدة أي مرة.'),
(1748, 'زرق', 'زرق', 'زرق', 'زرقت عينه زرقة وزرقا، وازراقت ازريقاقا. وقول الله- عز وجل-: ونحشر المجرمين يومئذ زرقا 1 يريد عميا لا يبصرون وعيونهم في المنطق 2 [كذا] زرق لا نور لها. وثريدة زريقاء بلبن وزيت. والزرق: طائر بين البازي والباشق.'),
(1749, 'لزق', 'لزق', 'لزق', 'لزق الشيء بالشيء يلزق لزوقا، والتزق التزاقا. واللزق: هو اللوى تلتزق منه الرئة بالجنب. وهذه الدار لزيقة هذه وبلزقها. (واللزوق) 1 واللازوق: دواء للجرح يلزمه حتى يبرأ. ولصق لغة في كله.'),
(1750, 'زلق', 'زلق', 'زلق', 'الزلق: المزلقة. والمزلاق والمزلاج: الذي تغلق به الباب. والزلق: العجز من كل دابة، قال: كأنها حقباء بلقاء الزلق 2 يريد أتانا. وأزلقت الفرس: ألقت ولدها تاما كالسقط. وفرس مزلاق: كثير الإزلاق. وناقة زلوق زلوج أي سريعة. والتزلق: [صبغك] 3 البدن بالأدهان ونحوها. وزلقته: ملسته، والموضع مزلق صار كالمزلقة وإن لم يكن فيه ماء.'),
(1751, 'قلز', 'قلز', 'قلز', 'القلز: ضرب من الشرب، قال مطيع بن إياس 4 : وندامى كلهم يقلز ... والقلز عتيد'),
(1752, 'قزل', 'قزل', 'قزل', 'القزل: أسوأ العرج وهو أقزل، وقزل يقزل قزلا.'),
(1753, 'نقز', 'نقز', 'نقز', 'النقز والنقزان كالوثب والوثبان صعدا في مكان واحد. والنقاز: الصغير من العصافير. والنقز: الصغار من الناس، والرذالة منهم. والنواقز: القوائم، قال الشماخ: وإن ريغ منها أسلمته النواقز 1 .'),
(1754, 'زنق', 'زنق', 'زنق', 'الزنقة: ميل في جدار في سكة، أو في ناحية من الدار، أو عرقوب من الوادي يكون فيه كالمدخل والالتواء، اسم بلا فعل. والزناق: حلقة يجعل لها خيط يشد في راس البغل الجموح، وكل رباط تحت الحنك في الجلد فهو زناق. وما كان في الأنف مثقوبا فهو عران. وبغل مزنوق، وزنقته زنقا، قال الشاعر: فإن يظهر حديثك بؤت عدوا ... برأسك في زناق أو عران 1'),
(1755, 'نزق', 'نزق', 'نزق', 'النزق: خفة في كل أمر (وعجلة في جهل وحمق) 2 . ورجل نزق وامرأة نزقة، وقد نزق نزقا.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1756, 'قفز', 'قفز', 'قفز', 'القفز والقفزان: وثبان أكثر من النقزان. وأمة قفازة لقلة استقرارها. والقفاز: لباس للكف. ويقال للخيل السراع التي تثب في عدوها: قافزة وقوافز. والقفيز: مكيال، وهو أيضا مقدار من مساحة الأرض.'),
(1757, 'زقب', 'زقب', 'زقب', 'زقبه في جحره فانزقب [فيه] .'),
(1758, 'زبق', 'زبق', 'زبق', 'الزئبق، يهمز ويلين في لغة، وفعله: التزبق. والزابوقة: شبه دغل في بناء أو بيت تكون زاوية منه معوجة.'),
(1759, 'بزق', 'بزق', 'بزق', 'البزق: البصق وهو البزاق والبصاق. وبزقوا الأرض أي بذروها، وهي يمانية.'),
(1760, 'قزم', 'قزم', 'قزم', 'القزم: اللئيم الدنيء، الصغير الجثة، ورجل قزم، وامرأة قزم، وقوم قزم وأقزام، وهو ذو قزم. ولغة أخرى: رجل قزم وامرأة قزمة وامرأتان قزمتان، ونساء قزمات، ورجلان قزمان، ورجال قزمون، قال: لا بخل خالطه ولا قزم 1 ويقال للرذالة من الأشياء: قزم، والجميع قزم.'),
(1761, 'زقم', 'زقم', 'زقم', 'الزقم: أكل الزقوم. ويقال: الزقوم، بلغة إفريقية، الزبد بالتمر. (ولما نزلت آية الزقوم لم تعرفه قريش، فقدم رجل من إفريقية وسئل عن الزقوم، فقال الإفريقي: الزقوم بلغة إفريقية، الزبد والتمر) 1 . فقال أبو جهل: هاتي يا جارية تمرا وزبدا نزدقمه، فجعلوا يتزقمون منه ويأكلونه، وقالوا: أبهذا يخوفنا محمد، فبين الله في آية أخرى: إنا جعلناها فتنة للظالمين، إنها شجرة تخرج في أصل الجحيم 2 .'),
(1762, 'مزق', 'مزق', 'مزق', 'المزق: شق الثياب ونحوه. وصار الثوب مزقا أي قطعا ولا يكادون يقولون: مزقة للقطعة. وثوب مزيق ومتمزق وممزوق وممزق. وكذلك المزق من السحاب، وسحابة مزق. وناقة مزاق: (سريعة يكاد جلدها يتمزق من سرعتها) 3 ، قال 4 : فجاء بشوشاة مزاق ترى لها ... ندوبا من الأنساع فذا وتوأما ومزق العرض الشتم. ومزق الطائر بسلحه أي رمى به. ومزيقياء كان ملكا من ملوك اليمن.'),
(1763, 'قطر', 'قطر', 'قطر', 'القطر والقطران مصدر قطر الماء. والقطار: قطار الإبل بعضها إلى بعض على (نسق واحد) 1 . والقطار: جماعة القطر. واشتق اسم المقطرة منه لان من حبس فيها صار على قطار واحد، مضموم بعضها إلى بعض، ويقال لها: الفلق 2 ، تجعل أرجلهم في خروق، وكل خرق على قدر ساق الرجل. والقطر: النحاس الذائب. والقطر: الشق، قال ابن مسعود: لا يعجبنك ما ترى من الرجل حتى ترى على أي قطريه يقع أي على جنبيه يقع في خاتمة عمله. والأقطار: النواحي. والقطر: عود يتبخر به. وأقطار الفرس: ما أشرف منه مثل كاثبته وعجزه ورأسه. وأقطار الجبل: أعاليه. وقطور: اسم نبات، سوادية. والقطران، ويخفف في لغة،: ما يتحلب من شجر الأبهل، يطبخ فيتحلب منه. وقطرت فلانا تقطيرا: صرعته صرعة شديدة، قال: قد علمت سلمى وجاراتها ... ما قطر الفارس إلا أنا 1 وقال:'),
(1764, 'قلط', 'قلط', 'قلط', 'القلطي: القصير جدا. والقلوط: أولاد الجن والشياطين.'),
(1765, 'لقط', 'لقط', 'لقط', 'لقط يلقط لقطا: أخذ من الأرض. واللقطة: ما يوجد ملقوطا ملقى، وكذلك المنبوذ من الصبيان لقطة. واللقطة: الرجل اللقاطة وبياع اللقاطات يلتقطها. واللقاط: سنبل تخطئه المناجل يلتقطه الناس ويتلقطونه، واللقاط اسم ذلك الفعل كالحصاد والحصاد. واللقاطة: ما كان معروفا، من شاء أخذه. واللقط: قطع ذهب أو فضة أمثال الشذر وأعظم، توجد في المعادن، وهو أجوده. تقول: ذهب لقطي والتقطوا منهلا وغديرا، أي هجموا عليه بغتة لا يريدونه، قال: ومنهل وردته التقاطا 1 واللقيطة: الرجل المهين الرذل، والمرأة كذلك، وتقول: إنه لسقيط لقيط وإنها لسقيطة لقيطة، وإنه لساقط لاقط، فإذا أفردوا قالوا: إنه للقيطة. وتقول: يا ملقطان للغسل الأحمق، والأنثى بالهاء، ولا يقال إلا في الدعاء. واللقيطى: شبه حكاية إذا رأيته كثير الالتقاط للقاطات تعيبه بذلك. وإذا التقط الكلام للنميمة قلت: لقيطى خليطى حكاية لفعله.'),
(1766, 'طلق', 'طلق', 'طلق', 'طلقت المرأة فهي مطلوقة إذا ضربها الطلق عند الولادة. والطلاق: تخلية سبيلها، والمرأة تطلق طلاقا فهي طالق وطالقة غدا، قال الأعشى: أيا جارتي بيني فإنك طالقه 2 وطلقت وطلقت تطليقا. والطالق من الإبل ناقة ترسل في الحي ترعى من جنابهم أي حواليهم حيث شاءت، لا تعقل إذا راحت ولا تنحى في المسرح، وأطلقت الناقة وطلقت هي أي حللت عقالها فأرسلتها. ورجل مطلاق ومطليق أي كثير الطلاق للنساء. والطليق: الأسير يطلق عنه إساره. وإذا خلى الظبي عن قوائمه فمضى لا يلوي على شيء قيل: تطلق، قال: تمر كمر الشادن المتطلق 1 وإذا خلى الرجل عن الناقة على ما وصفت لك قيل: طلقها، وكذلك العير إذا حاز عانته وعنف عليها، ثم خلى عنها قيل: طلقها، وإذا استعصت عليه ثم انقادت قيل: طلقته، وإذا أبت أن تقرب الماء قربا ثم مضت للقرب قيل: طلقت. والانطلاق: سرعة الذهاب في المحنة. وفلان طلق الوجة وطليقه، وقد طلق طلاقة، ويوم طلق، وليلة طلقة: نقيض النحس والنحسة، قال رؤبة: أيوم نحس أو يكون طلقا 2 واستطلق البطن وأطلقه الدواء فأسهل. ورجل طليق اللسان وطلق اللسان: ذو طلاقة وذلاقة، ولسانه طلق ذلق أي مستمر. ورجل طلق اليدين: سمح بالعطاء، قال حسان في ربيعة بن مكدم: نفرت قلوصي من حجارة حرة ... بنيت على طلق اليدين وهوب 3 وما تطلق نفسي لهذا الشيء، أي ما تنشرح ولا تستمر. والطلق: الشوط في جرى الخيل، ويستعمل في أشياء. وتطلقت الخيل إذا مضت طلقا لم تحتبس إلى الغاية، قال: جرى طلقا حتى إذا قيل قد دنا ... تداركه أعراق سوء فبلدا 1 ويروى: تنازعه أعراق سوء. والطلق: الحبل القصير الشديد الفتل، حتى يقوم قياما، قال: محملج أدرج إدراج الطلق 2'),
(1767, 'قطن', 'قطن', 'قطن', 'قطن: اسم جبل لعبس. والقطن: الموضع من الثبج والعجز. والقطان: شجار الهودج، والجميع: القطن، قال لبيد: فتكنسوا قطنا تصر خيامها 3 والقطن يجوز تثقيله كما قال: قطنة من أجود القطنن 4 والقيطون: المخدع في لغة البربر ومصر. وبزر قطونا 1 لأهل العراق يستشفى بها. والقطون: الإقامة. ومجاورو مكة: قاطنوها وقطانها، ويقال أيضا لحمام مكة: قطن وقواطن، والجميع والواحد قطين سواء، قال: فلا ورب الآمنات القطن 2 والقطنة: هنة دون القبة 3 . وقطن الكرم وعطب إذا بدت زمعاته.'),
(1768, 'نطق', 'نطق', 'نطق', 'نطق الناطق ينطق نطقا، وهو منطيق بليغ. والكتاب الناطق: البين، قال لبيد: أو مذهب جدد على ألواحه ... الناطق المبروز والمختوم 4 وكلام كل شيء: منطقه. والمنطق: كل شيء شددت به وسطك، والمنطقة: اسم خاص. والنطاق: شبه إزار فيه تكة كانت المرأة تنتطق به. وإذا بلغ الماء النصف من الشجر يقال: نطقها.'),
(1769, 'قنط', 'قنط', 'قنط', 'القنوط: الإياس، وقنط يقنط وقنط يقنط 1'),
(1770, 'نقط', 'نقط', 'نقط', 'نقط ينقط نقطا، والنقطة الاسم، والنقطة مرة واحدة'),
(1771, 'قطف', 'قطف', 'قطف', 'القطف: اسم الثمار المقطوفة، والجميع القطوف. وقول الله- عز وجل-: قطوفها دانية 2 ، أي ثمارها قريبة يتناولها القاعد والقائم. والقطف: قطفك العنب وغيره. (وكل شيء تقطفه عن شيء فقد قطفته) حتى الجراد تقطف رءوسها. وأقطف الكرم: أنى قطافه، والقطاف اسم وقت القطف. وقال الحجاج: إني أرى رءوسا قد أينعت وحان قطافها. والقطيفة دثار. والقطف: نبات رخص عراض الورق، يطبخ، الواحدة قطفة. والقطاف مصدر القطوف من الدواب والإبل، وهي البطيء المتقارب لخطو، وقطفت تقطف قطافا وقطوفا. وأقطف الرجل: صار صاحب دابة قطوف، قال ذو الرمة: كأن رجليه رجلا مقطف عجل 1'),
(1772, 'طفق', 'طفق', 'طفق', 'طفق، وطفق لغة رديئة، أي جعل يفعل، وهو مثل ظل وبات وما جمعهما 2'),
(1773, 'قفط', 'قفط', 'قفط', 'واقفاطت العنز للتيس اقفيطاطا إذا حرصت على الفحل فمدت مؤخرها إليه حرصا على السفاد، والتيس يقتفط إليها ويقتفطها إذا ضم مؤخره إليها، تقافطا: تعاونا على ذلك. ورقية للعقرب إذا لسعت: شجة قرنية، ملحة بحري قفطي. تقرأ سبع مرات. وقل هو الله أحد سبع مرات. وسئل النبي- عليه السلام- عن هذه الرقية بعينها فلم ينه عنها، وقال: الرقى عزائم أخذت على الهوام.'),
(1774, 'قطب', 'قطب', 'قطب', 'القطب: نبات. والقطوب والقطب: تزوي ما بين العينين عند العبوس، وقطب يقطب قطبا وقطب يقطب تقطيبا. وقاطبة: اسم يحمل كل جيل من الناس، تقول: جاءت العرب قاطبة. والقطاب: المزاج لما يشرب وما لا يشرب. قال (أبو فروة) 1 : قدم فريغون بجارية (قد اشتراها) 2 من الطائف، فصيحة، قال: فدخلت عليها وهي تعالج شيئا: فقلت: ما هذا؟ فقالت: هذه غسلة. فقلت: وما أخلاطها؟ فقالت: آخذ الزبيب الجيد فألقي لزجه وألجنه وأعثنه 3 بالوخيف وأقطبه. والتعثن: التدخن، وقال: يشرب الطرم والصريف قطابا 4 والطرم: العسل، والصريف: اللبن الحازر الحامض، وقطابا أي مزاجا، والقاطب هو المازج، قال الكميت: ولا أعد كأني كنت شاربه ... ما صرف الشاربون الخمر أو قطبوا 5 أي مزجوا. والقطب: كوكب بين الجدي والفرقدين، صغير أبيض لا يبرح موضعه، شبه بقطب الرحى. وقطب الرحى: الحديدة التي في الطبق الأسفل من الرحيين يدور عليها الطبق الأعلى. وتدور الكواكب على هذا الكوكب. والقطبة: نصل صغير مربع في السهم ترمى به الأغراض.'),
(1775, 'طبق', 'طبق', 'طبق', 'الطبق: عظيم رقيق يفصل بين الفقارين، وطبق بالسيف عنقه أي أبانه. والطبق: كل غطاء لازم، ويقال: أطبقت الحقة وشبهها. ويقال: أطبق الرحيين أي طابق بين حجريها، ومثله إطباق الحنكين. والسماوات طباق بعضها فوق بعض، الواحدة طبقة، ويذكر فيقال: طبق واحد. والطبقة: الحال، ويقال: كان فلان على طبقات شتى من الدنيا، أي حالات. وقوله تعالى: لتركبن طبقا عن طبق 1 أي حالا عن حال يوم القيامة. والطبق: جماعة من الناس يعدلون طبقا مثل جماعة. وفي المثل: وافق شن طبقه، وشن قبيلة من عبد القيس أبروا على من حولهم فصادفوا قوما قهروهم فقيل ذلك. ومن جعل الشن من القرب استحال لأن الشن لا طبق له. وأطبق القوم على هذا الأمر أي اجتمعوا وصارت كلمتهم واحدة. وطابقت المرأة زوجها إذا واتته على كل الأمور كما قالت، فتلكم طابقت واستقرت، (شبه النوق بالنساء) 2 . والمطابقة في المشي كمشي المقيد، قال عدي: وطابقت في الحجلين مشي المقيد 1 وطابقت بين الشيئين: جعلتهما على حذو واحد وألزقتهما فيسمى هذا المطابق، والمطبق: شبه اللؤلؤ 2 إذا قشر اللؤلؤ أخذ قشره فألزق بالغراء ونحوه بعضه على بعض فيصير لؤلؤا أو شبهه. وانطبق فعل لازم. وتقول: لو تطبقت السماء على الأرض ما فعلت. وفي الحديث: لله مائة رحمة، كل رحمة منه كطباق الأرض أي تغشى الأرض كلها.'),
(1776, 'قبط', 'قبط', 'قبط', 'القبط أهل مصر وبنكها، والنسبة إليهم قبطي وقبطية، ويجمع على قباطي، وهو ثياب بيض من كتان يتخذ بمصر فلما ألزمت هذا الاسم غيروا اللفظ ليعرف، قالوا: إنسان قبطي، وثوب قبطي. والقبيطى: الناطف، وإذا ذكروا قالوا: قبيط وناطف، وإذا أنثوا قالوا قبيطى.'),
(1777, 'قطم', 'قطم', 'قطم', 'نحل قطم، وجمعه قطم. وقطم يقطم قطما، وهو شدة اغتلامه. والقطم والقطيم: الصؤول 1 الفحل، قال: أم كيف جد مضر القطيم 2 والقطامي: من أسماء الشاهين. ومقطم البازي: مخلبه. وقطام: اسم امرأة.'),
(1778, 'مقط', 'مقط', 'مقط', 'المقاط: حبل صغير قصير يكاد يقوم من شدة إغارته، وجمعه مقط، قال قال رؤبة: على لياح اللون كالفسطاط ... من البياض شد بالمقاط 3 والمقط: الضرب به. والمقاط: أجير الكري [من] الذين يكرون المراحل في طريق مكة. والماقط: مولى المولى. والمقط: ضربك الكرة على الأرض ثم تأخذها بيدك، قال الشماخ يصف الناقة: كأن أوب يديها حين أدركها ... أوب المراح وقد نادوا بترحال مقط الكرين على مكنوسة زلق ... في طرف حنانة النيرين معوال 4'),
(1779, 'قمط', 'قمط', 'قمط', 'القمط: شد كشد الصبي في المهد وغيره إذا ضمت أعضاؤه إلى جسده، ويلف عليه القماط. والقماط والقماطة: الخرقة العريضة تلف على الصبي إذا قمط. ولا يكون القمط إلا شد اليدين والرجلين معا. وسفاد الطير كله قماط، وقمطها يقمطها قمطا. والقماط في لغة: اللصوص. وتقول: وقعت على قماط فلان أي بنوده.'),
(1780, 'مطق', 'مطق', 'مطق', 'التمطق: إلصاق اللسان بالغار الأعلى فيسمع صوته لاستطابة أكل شيء.'),
(1781, 'دقط', 'دقط', 'دقط', 'الدقط: الغضبان، ودقط يدقط دقطا، قال أمية بن أبي الصلت: من كان مكتئبا من سيء دقطا ... قرأت في صدره ما عاش دقطانا 1'),
(1782, 'قتد', 'قتد', 'قتد', 'القتد: من أدوات الرحل ويجمع على أقتاد وقتود. والقتاد: شجر له شوك، والواحدة قتادة. وفي المثل: دون هذا خرط القتاد.'),
(1783, 'قثد', 'قثد', 'قثد', 'القثد: هو خيار باذرنق.'),
(1784, 'قدر', 'قدر', 'قدر', 'القدر: القضاء الموفق، يقال: قدره الله تقديرا. وإذا وافق الشيء شيئا قيل: جاء على قدره. والقدرية: قوم يكذبون بالقدر. والمقدار: اسم القدر إذا بلغ العبد المقدار مات. والأشياء مقادير أي لكل شيء مقدار وأجل. والمطر ينزل بمقدار أي بقدر وقدر (مثقل ومجزوم) ، وهما لغتان. والقدر: مبلغ الشيء. وقول الله عز وجل-: وما قدروا الله حق قدره* ، 1 أي ما وصفوه حق صفته. وقدر على الشيء قدرة أي ملك فهو قادر. واقتدرت الشيء: جعلته قدرا. والمقتدر: الوسط، ورجل مقتدر الطول. وقول الله عز وجل- عند مليك مقتدر 2 أي قادر. وقدر الله الرزق قدرا يقدره أي يجعله بقدر. وسرج قدر ونحوه أي وسط، وقدر (يخفف ويثقل) . وتصغير القدر قدير بلا هاء، ويؤنثه العرب. والقدير: ما طبخ من اللحم بتوابل، فإن لم يكن بتوابل فهو طبيخ. ومرق مقدور أي مطبوخ. والقدار: الطباخ الذي يلي جزر الجزور وطبخها. وقدرت الشيء أي هيأته.'),
(1785, 'دقر', 'دقر', 'دقر', 'والدوقرة: بقعة بين الجبال، وفي الغيطان انحسرت عنها الشجر، وهي بيضاء صلبة لا نبات فيها، وهي أيضا منازل الجن يكره النزول بها، وتجمع الدواقير. ويقال للكذب المستشنع ذي الأباطيل ما جئت إلا بالدقارير. والدقرارة: الداهية، قال الكميت: ولن أبيت من الأسرار هينمة ... على دقارير أحكيها وأفتعل 1'),
(1786, 'قرد', 'قرد', 'قرد', 'القرد، والقردة الأنثى، ويجمع على قرود وقردة وأقراد. والقراد: معروف، وثلاثة أقردة ثم الأقراد والقردان. وقردت البعير تقريدا أي ألقيت عنه القراد. وأقرد الرجل أي ذل وخنع. والقرد: لغة في الكرد أي العنق، وهو مجثم الهامة على سالفة 2 العنق قال: فجلله عضب الضريبة صارما ... فطبق ما بين الذؤابة والقرد 3 والقرد من السحاب الذي تراه في وجهه شبه انعقاد في الوهم شبه بالوبر القرد والشعر القرد الذي انعقدت أطرافه. وعلك قرد أي قد قرد أي فسدت ممضغته. وقردودة الظهر: ما ارتفع من ثبجه. والقردد من الأرض: قرنة إلى جنب وهدة، وهذه أرض قردد. وقال: بقرقرة ملساء ليست بقردد 1'),
(1787, 'رقد', 'رقد', 'رقد', 'الرقاد والرقود: النوم بالليل، والرقدة أيضا: همدة ما بين الدنيا والآخرة ويقول المشركون: من بعثنا من مرقدنا هذا 2 . إذا بعثوا، فردت الملائكة: هذا ما وعد الرحمن وصدق المرسلون 3 . والراقود: حب كهيئة الأردبة يسيع داخله بالقار، ويجمع رواقيد.'),
(1788, 'درق', 'درق', 'درق', 'الدرقة: ترس من جلود، ويجمع على درق وأدراق ودراق. والدورق: مكيال للشرب. والدردق: صغار الناس وأطفالهم، ومن الإبل، ويجمع درادق. والدرداق: دك صغير متلبد، فإذا حفرت كشفت عن رمل.'),
(1789, 'ردق', 'ردق', 'ردق', 'الردق لغة في الردج كالشيرق لغة في الشيرج. والردج عقي السخلة والصبي.'),
(1790, 'دلق', 'دلق', 'دلق', 'دلق السيف من غمده، وكل شيء خرج من مخرجه، دلقا سريعا من غير أن يسل، قال: أبيض خراج من المآزق ... كالسيف من جفن السلاح الدالق 1 وبينا هم آمنون إذ دلق عليهم السيل: قال وغردا يستن سيلا دلقا 2 واندلق الرجل كأنه أقبل من بين أصحابه فمضى. وادلقت المخة فاندلقت.'),
(1791, 'دقل', 'دقل', 'دقل', 'الدقل من أردأ التمر، وما لم يكن ألوانا. والدقل: خشبة طويلة تشد في وسط السفينة يمد عليها الشراع. والدوقل: من أسماء رأس الذكر، وكمرة دوقلة: ضخمة. والدوقلة: الأكل وأخذ الشيء اختصاصا تدوقله لنفسك.'),
(1792, 'قلد', 'قلد', 'قلد', 'القلد: إدارتك قلبا على قلب من الحلي. ولو دققت حديدة ثم لويتها على شيء فقد قلدتها. والبرة التي فيها الزمام إقليد، يثنى طرفها على الطرف الآخر ويلوى ليا شديدا حتى يستمسك. ويفعل ذلك ببعض الأسورة إذا كان برة، أو كان قلدا واحدا. وسوار مقلود: ذو قلبين ملويين. والاقليد: المفتاح، يمانية، قال تبع حيث حج: وأقمنا به من الدهر سبتا ... وجعلنا لبابه إقليدا 1 ويروى: ستا. والمقلاد: الخزانة، ويجمع مقاليد وأقلد البحر على خلق كثير أي ضم عليهم، قال: تسبحه الحيتان والبحر زاخرا ... وما ضم من شيء وما هو مقلد 2 وتقول: هي قلادة الإنسان والبدنة والكلب ونحوه. وتقليد البدنة أن يعلق في عنقها عروة مزادة ونعل خلق فيعلم أنها هدي، وإذا قلدها وجب عليه الإحرام عند بعض العلماء. وتقلدت السيف والأمر ونحوه: ألزمته نفسي، وقلدنيه فلان أي ألزمنيه وجعله في عنقي.'),
(1793, 'دنق', 'دنق', 'دنق', 'الدوانيق جمع دانق ودانق، لغتان، وجمع دانق دوانق، وجمع دانق دوانيق ودنق فلان وجهه تدنيقا إذا رأيت فيه ضمر الهزال من مرض أو نصب.'),
(1794, 'قند', 'قند', 'قند', 'القند: عصارة قصب السكر إذا جمد، ومنه يتخذ الفانيذ وسويق مقنود ومقند. والقنديد: الورس الجيد، والقنديد: الخمر) 1 ، قال: صهباء صافية في طيبها أرج ... كأنها في سياع الدن قنديد والقندأو: صحيفة للحساب وغيره، لغة أهل الشام ومصر. (والقنداو: السيء الخلق والغذاء) 2 .'),
(1795, 'نقد', 'نقد', 'نقد', 'النقد: تمييز الدراهم وإعطاؤكها إنسانا وأخذها. والانتقاد والنقد: ضرب جوزة بالإصبع لعبا، (ويقال: نقد أرنبته بإصبعه إذا ضربها) 3 ، قال خلف: وأرنبة لك محمرة ... يكاد يفطرها نقده 1 أي يشقها عن دمها. والمنقدة: خزيفة تنقد عليها الجوزة، وكل شيء ضربته بإصبعك كنقد الجوز فقد نقدته. والطائر ينقد الفخ أي ينقره بمنقاره. والإنسان ينقد بعينيه إلى الشيء وهو مداومته النظر واختلاسه حتى لا يفطن له. وتقول: ما زال بصره ينقد إلى ذلك الشيء نقودا. والإنقدان: السلحفاة الذكر. والنقد: ضرب من الغنم صغار، وجمعه النقاد.'),
(1796, 'قدف', 'قدف', 'قدف', 'القدف: غرف الماء من الحوض. أو من شيء تصبه بكفك، بلغة عمان. وقالت بنت جلندى العمانية حين ألبست السلحفاة حليها فغاصت وأقبلت تغترف من البحر وتصبه على الساحل وهي تنادي القوم: نزاف نزاف، لم يبق في البحر غير قداف، أي غير حفنة.'),
(1797, 'دفق', 'دفق', 'دفق', 'دفق الماء دفوقا ودفقا إذا انصب بمرة، والماء الدافق. والنطفة تدفق، واندفق الكوز: انصب بمرة ودفق ماؤه. ويقال في الطيرة عند انصباب الكوز ونحوه: دافق خير. وأدفقته: صببته بمرة فكدرته الكدر للصب بمرة. وجاء القوم دفقة أي بدفعة واحدة، قال: نزل الفأر ببيتي ... رفقة من بعد رفقه خلفا بعد قطار ... نزلوا بالدار دفقه 1 وناقة دفاق: اندفقت في سيرها مسرعة، ويقال: ناقة دفقاء، وجمل أدفق ودفاق، وهو شدة بينونة المرفق عن الجنبين: قال بعنتريس ترى في وردها رفقا ... وفي المرافق من حيزومها دفقا 2 ويروى: في زورها. واندفق الدمع، قال سليمان: صبا فؤادك من طيف ألم به ... حتى ترقرق ماء العين فاندفقا 3'),
(1798, 'قفد', 'قفد', 'قفد', 'القفد: صفع الرأس يبسط الكف من قبل القفا، تقول: قفدته قفدا. والقفدانة: غلاف المكحلة من مشاوب 1 أو أديم. والأقفد: من في عنقه استرخاء من الناس، والظليم.'),
(1799, 'فقد', 'فقد', 'فقد', 'الفقد: فقدان الشيء. ويقال: امرأة فاقدة: مات ولدها أو حميمها. وأفقده الله كل حميم. ومات غير فقيد ولا حميد، وغير مفقود ولا محمود أي غير مكترث لفقده. والتفقد: تطلب ما غاب. والفقد: شراب من زبيب وعسل، ويقال إن العسل ينبذ ثم يلقى فيه الفقد، وهو زبيب شبه الكشوش. ويقال: امرأة فاقد، بغير الهاء، قال الشاعر: كأنها فاقد شمطاء معولة ... ناحت وجاوبها نكد مثاكيل 2'),
(1800, 'دبق', 'دبق', 'دبق', 'الدبق: حمل شجر في جوفه كالغراء، يلزج بجناح الطائر، ودبقته دبقا، ودبقته تدبيقا.'),
(1801, 'قدم', 'قدم', 'قدم', 'القدم: ما يطأ عليه الإنسان من لدن الرسغ فما فوقه 1 . والقدمة والقدم أيضا: السابقة في الأمر، وقوله تعالى: لهم قدم صدق عند ربهم ، أي سبق لهم عند الله خير، وللكافرين قدم شر. وفي الحديث: إن جهنم لا تسكن حتى يضع الله قدمه فيها ، قال الحسن: حتى يجعل الله الذين قدمهم من شرار خلقه فيها، فهم قدم الله للنار والمسلمون قدم للجنة. والقدم مصدر القديم من كل شيء، وتقول: قدم يقدم. وقدم فلان قومه أي يكون أمامهم، يقدم قومه يوم القيامة من هاهنا. والقدم: المضي أمام أمام، وتقول: يمضي قدما أي لا ينثني. والقدوم: الرجوع من السفر، وقدم يقدم. وقديدمة تصغير قدام، وهو خلاف وراء. ورأيته قديدمة ذاك ووريئة ذاك أي قدام ووراء ذاك قريبا. والقدام: الملك، قال: جيش لهام من بني القدام. والقدوم، مخففة،: الحديدة التي ينحت بها الخشب، تؤنث. والقدم ضد الأخر بمنزلة قبل ودبر. ورجل قدم: مقتحم للأشياء يتقدم الناس، ويمضي في الحرب قدما. ومقدم نقيض مؤخر، ومقدم العين: ما يلي الأنف، والمؤخر: ما يلي الصدغ. ولم يأت في كلامهم مقدم ومؤخر بالتخفيف إلا مقدم العين ومؤخرها، وسائر الأشياء بالتشديد. والمقدمة: الناصية، ويقال للجارية: إنها اللئيمة المقدمة. والمقدمة: ما استقبلك من الجبهة والجبين، يقال: ضربته فركب مقاديمه أي وقع على وجهه، الواحد مقدم ومقدم، وقال في رجل طعنه في جبهته: تركت ابن أوس والسنان كأنما ... يوتده في مقدم الرأس واتد 1 واستقدم أي تقدم وقادمة الرحل من أمام الواسطة. والقادم من الأطباء: ما ولي السرة للناقة والبقرة، وهما قادمان وآخران. والقادمة: الريشة التي تلي منكب الجناح، وكلها قوادم وقدامى، قال: وما جعل القوادم كالخوافي 2'),
(1802, 'دقم', 'دقم', 'دقم', 'الدقم: دفعك شيئا مفاجأة، وتقول: دقمته عليهم، واندقمت عليهم الريح والخيل ونحو ذلك، قال: مرا جنوبا وشمالا تندقم 1'),
(1803, 'قمد', 'قمد', 'قمد', 'القمد: القوي الشديد. ويقال: إنه لقمد قمدد، وامرأة قمدة. والقمود شبه العسو من شدة الإباء. ويقال: قمد يقمد قمدا وقمودا: جامع في كل شيء.'),
(1804, 'مقد', 'مقد', 'مقد', 'المقدي خمر منسوبة إلى قرية بالشام، قال: مقديا أحله الله للناس ... شرابا وما تحل الشمول 2'),
(1805, 'دمق', 'دمق', 'دمق', 'الدمق: ثلج وريح تأتي من كل أوب تكاد تقتل الإنسان. والاندماق: الانخراط، ويقال: اندمق عليهم بغتة ضربا وشتما. واندمق الصياد في قترته، واندمق منها أي خرج.'),
(1806, 'قتر', 'قتر', 'قتر', 'القتر: الرمقة في النفقة، ويقال: فلان لا ينفق عليهم إلا رمقة، أي مساك رمق. وهو يقتر عليهم، فهو مقتر وقتور، واقتر الرجل، فهو مقتر إذا أقل فهو مقل. والقتار: ريح اللحم المشوي والمحرق، وريح العود الذي يحرق فيذكى به، والعظم ونحوه. والتقتير: تهييج القتار. والقترة: هي الناموس يقتتر فيها الرامي. والقترة: كثبة من بعر أو حصى تكون قترا قترا. والقترة: ما يغشى الوجه من غبرة الموت والكرب، يقال: غشيته قترة وقتر، كله واحد. وأبو قترة: كنية إبليس. وابن قترة: حية لا ينجو سليمها. والقاتر من الرحال والسروج إذا وضع على الظهر أخذ مكانه لا يتقدم ولا يتأخر ولا يميل 1 . والقتر: سهام صغار هذلية، ويقال: أغاليك إلى عشر أو أكثر فذاك القتر. وتقول: كم جعلتم قتركم. ويقال: هي القطنة التي يرمى بها الهدف، أو هي القصبة 2 . وتقول هذيل: أكل حتى اقتر، في الناس وغيرهم، والاقترار الشبع. والإبل تقتر بأبوالها قليلا قليلا. والقتير: الشيب.'),
(1807, 'تقر', 'تقر', 'تقر', 'التقرة والتقر، أحدهما الكرويا، والآخر التوابل.'),
(1808, 'قرت', 'قرت', 'قرت', 'قرت الدم يقرت قروتا. ودم قارت: يبس بين الجلد واللحم. ومسك قارت: أجوده وأخفه، قال: يعل بقرات من المسك قاتن 1 والقرات: الفعال من ذلك.'),
(1809, 'رتق', 'رتق', 'رتق', 'الرتق إلحام الفتق وإصلاحه، يقال: رتقت فتقه حتى ارتتق، وقال تعالى: والسماء ذات الرجع، والأرض ذات الصدع 2 ، أي كانت السماوات لا ينزل منها رجع، والأرض رتقاء لا يكون فيها صدع، ولا يخرج منها صدع حتى فتقهما الله بالماء والنبات 3 رزقا للعباد. وجارية رتقاء بينة الرتق أي لا خرق لها إلا المبال خاصة.'),
(1810, 'ترق', 'ترق', 'ترق', 'الترقوة: وهو وصل عظم بين ثغرة النحر والعاتق في الجانبين. والترياق لغة في الدرياق وهو دواء.'),
(1811, 'قتل', 'قتل', 'قتل', 'وقول الله- عز وجل-: قاتلهم الله* 1 أي لعنهم. وقوم أقتال أي أهل الوتر والترة، من قول الأعشى: وأسرى من معشر أقتال 2 أي أعداء ذوي ترات. وقلب مقتل أي قتل عشقا. وتقتلت الجارية للفتى: (تزينت ومشت مشية حسنة تقلبت فيها وتثنت وتكسرت) يوصف به العشق، قال: تقتلت لي، حتى إذا ما قتلتني ... تنسكت، ما هذا بفعل النواسك 3 والقتل معروف، يقال: قتله إذا أماته بضرب أو جرح 4 أو علة. والمنية قاتلة. وأقتلت فلانا: عرضته للقتل، قال مالك بن نويرة لامرأته حين رآها خالد بن الوليد: سيف الله أقتلتني أي سيقتلني من أجلك، فقتله وتزوجها. والمقتل من الدواب: ما ذل ومرن على العمل.'),
(1812, 'قلت', 'قلت', 'قلت', 'القلت: حفرة يحفرها ماء واشل يقطر من جبل على حجر فيوقب فيه على مر الأحقاب وقبة مستديرة، وكذلك إن كان في الأرض الصلبة فهو قلت كقلت العين وهو وقبتها. والقلت: نقرة تحت الإبهام. وقلت الثريدة: أنقوعتها. وناقة مقلات، وبها قلت، وقد أقلتت فهي مقلت، وهي التي تضع واحدا ثم يقلت رحمها فلا تحمل. وامرأة مقلات: ليس لها إلا ولد واحد، ونسوة مقاليت، قال: وأم الصقر مقلات نزور 1'),
(1813, 'قتن', 'قتن', 'قتن', 'القتين: القليل اللحم والطعم، والقتين: القراد. وامرأة قتين: قليلة الدم واللحم. ومسك قاتن أي يابس لا ندوة فيه وقد قتن قتونا. والاقتنان: الانتصاب في قول الأعشى: والرحل تقتن اقتنان الأعصم 1'),
(1814, 'تقن', 'تقن', 'تقن', 'التقن: رسابة الماء في الربيع، وهو الذي يجيء به الماء من الخثورة. وتقنوا أرضهم أي أرسلوا فيها الماء الخاثر لتجود. والإتقان: الإحكام، قال: ولكنه بالسهل أتقن مولد 2 أي هو بالسهل أعرف منه بالجبل.'),
(1815, 'قنت', 'قنت', 'قنت', 'وقنتوا لله أي أطاعوه، ومنه القنوت أي الطاعة، وقانتون أي مطيعون. والقنوت: الدعاء في آخر الوتر قائما، ومنه قوله تعالى: وقوموا لله قانتين 3 ، وقوله: أمن هو قانت آناء الليل 4 ، وهو الدعاء قياما هاهنا. وقنتت المرأة لزوجها أي أطاعته.'),
(1816, 'نتق', 'نتق', 'نتق', 'النتق: الجذب، ونتقت الغرب من البئر إذا اجتذبته بمرة جذبا. ونتقت الملائكة جبل الطور أي اقتلعوه من أصله حتى أطلعوه على عسكر بني إسرائيل فقال موسى- عليه السلام-: خذوا التوراة بما فيها، وإلا ألقي عليكم هذا الجبل، فأخذوها، فقال تعالى: وإذ نتقنا الجبل فوقهم 1 . والبعير إذا تزعزع حمله نتق عرى حباله، وذلك إذا جذبها فاسترخت عقدها وعراها فانتتقت، قال: ينتقن أقتاد النسوع الأطط 2 ونتقت المرأة تنتق نتوقا، والناقة ونحوها، وهو كثرة الولد في سرعة الحمل فهي ناتق.'),
(1817, 'فتق', 'فتق', 'فتق', 'الفتق: انفتاق رتق كل شيء متصل مستو وهو رتق فإذا انفصل فهو فتق. وتقول: فتقته فانفتق. والفتق يصيب الإنسان في مراق بطنه فينفتق الصفاق الداخل. والفتق: انشقاق عصا المسلمين بعد اجتماع الكلمة من حرب ونحوه بين القوم، قال: ولا أرى فتقهم في الدين يرتتق 3 والفتاق: خميرة ضخمة لا يلبث العجين إذا جعلت فيه أن يدرك، وتقول: فتقت العجين أي جعلت فيه فتاقا. والفتاق: أخلاط يابسة مدقوقة، ويفتق أي يخلط بدهن الزئبق ونحوه كي تفوح ريحه. ونصل فتيق الشفرتين إذا جعل له شعبتان فكأن إحداهما فتقت من الأخرى. والفتق: الصبح نفسه (والفتق انفلاق الصبح) 1 ، قال ذو الرمة: على أخريات الليل فتق مشهر 2'),
(1818, 'قتب', 'قتب', 'قتب', 'القتب: إكاف الجمل، والتذكير فيه أعم من التأنيث، ولذلك أنثوا المصغر فقالوا: قتيبة. والقتب قتب صغير على البعير الساني، قال لبيد: [حتى تحيرت الدبار كأنها ... زلف] ، وألقي قتبها المحزوم وأقتبت البعير: شددت عليه القتب. والمبعوج تجر أقتابه أي أمعاؤه، الواحد قتب. والقتوبة: إبل يوضع عليها أقتابها لنقل أحمال الناس، قال: إليك أشكو ثقل دين أقتبا ... ظهري بأقتاب تركن جلبا 1'),
(1819, 'قتم', 'قتم', 'قتم', 'الأقتم الذي يعلوه سواد ليس بشديد كسواد ظهر البازي، والقتمة مصدر كالقتم، وقتم يقتم قتما. والقتم: ريح ذات غبار، كريهة. والقتمة 2 : رائحة كريهة ضد الخمطة التي تستحب، والقتمة تكره. وقتم الغبار يقتم قتوما أي ضرب إلى سواد، واسمه القتام، وقال رؤبة: وقاتم الأعماق خاوي المخترق 3 يريد سواد أطراف المفازة.'),
(1820, 'مقت', 'مقت', 'مقت', 'المقت بغض من أمر قبيح ركبه، فهو مقيت، وقد مقت إلى الناس مقاتة، ومقته الناس مقتا فهو ممقوت والمقيت: الحافظ للشيء.'),
(1821, 'قرظ', 'قرظ', 'قرظ', 'القرظ: ورق السلم، يدبغ به الأدم، وتقول: قرظته أقرظه قرظا. والقارظ جامعه. وفي المثل: حتى يؤوب العنزي القارظ لأنه ذهب يقرظ ففقد فصار مثلا، قال: فرجي الخير وانتظري إيابي ... إذا ما القارظ العنزي آبا 1 وبنو قريظة هم أحد حيي اليهود من السبطين اللذين كانا بالمدينة. والتقريظ: مدحك أخاك وشدة تزيينك أمره، وقرظته تقريظا.'),
(1822, 'ذرق', 'ذرق', 'ذرق', 'الذرق: الحندقوق كالفسفسة، الواحدة ذرقة. والذرق: السلح، وذرق بسلحه ذرقا، وخذق خذقا أشد منه.'),
(1823, 'قذر', 'قذر', 'قذر', 'قيذار اسم ابن إسماعيل، وهو جد العرب، ويقال: هم بنو بنت 2 قيذر بن إسماعيل وقذرت كذا أي استقذرته، قال العجاج: وقذري ما ليس بالمقذور وتقذرت منه. وشيء قذر وقذر. وقذر يقذر قذرا، ومن يجزم قال: قذر يقذر قذارة. والقاذورة: المتقذر من الرجال من سوء الخلق. ورجل قاذورة أي غيور.'),
(1824, 'قذل', 'قذل', 'قذل', 'القذال: مؤخر الرأس فوق فأس القفا، والعدد أقذلة ثم القذل. والمقذول: المشجوج في قذاله. وقذال الفرس: موضع ملتقى العذار خلف 1 القونس، قال زهير: وملجمنا ما إن ينال قذاله ... ولا قدماه الأرض إلا أنامله 2'),
(1825, 'ذلق', 'ذلق', 'ذلق', 'حد كل شيء ذلقه، وتقول: كأنه ذلق سنان. والذلق: تحديدك إياه. وذلقته وأذلقته: حددته. ورجل ذليق اللسان ذلق، وذلق لسانه ذلاقة، وهو ذلق اللسان. والإذلاق: سرعة الرمي. وضب مذلق أي مستخرج من جحره.'),
(1826, 'ذقن', 'ذقن', 'ذقن', 'الذقن: مجتمع اللحيين وناقة ذقون: تحرك رأسها في سيرها.'),
(1827, 'نقذ', 'نقذ', 'نقذ', 'فرس نقذ إذا أخذ من قوم آخرين.'),
(1828, 'قذف', 'قذف', 'قذف', 'القذف: الرمي بالسهم والحصى والكلام. والقذف: الناحية، والقذفات النواحي من كل شيء. والقذاف: المنجنيق. وناقة مقذوفة كأنها رميت باللحم من كل جانب. وسبسب قذف وقذوف، وقذف، [أي: بعيد] . والقذفة: ما أشرف من رءوس الجبال، وثلاث قذف والجمع القذفات، وبها سميت الشرف، قال امرؤ القيس: منيف تزل الطير عن قذفاته ... تظل الضباب فوقه تتقصر 1 والقذاف: سرعة السير، وناقة متقاذفة: سريعة الركض، قال جرير: متقاذف تئق كأن عنانه ... علق بأجرد من جذوع أوال 2 وقال الكميت في القذاف أي سرعة السير: جعلت القذاف لليل التمام ... إلى ابن الوليد أبان سبارا 3'),
(1829, 'قرث', 'قرث', 'قرث', 'القريثاء: ضرب من التمر أسود سريع النقض لقشره عن لحائه إذا أرطب. وهو أطيب التمر بسرا.'),
(1830, 'ثقر', 'ثقر', 'ثقر', 'التثقر: التردد والجزع، قال: إذا بليت بقرن ... فقف ولا تتثقر 4'),
(1831, 'ثقل', 'ثقل', 'ثقل', 'ثقل ثقلا فهو ثقيل، والثقل: رجحان الثقيل. والثقل: متاع المسافر وحشمه، وجمعه أثقال. والأثقال: الآثام. وامرأة ثقال أي ذات مآكم وكفل. والمثقال وزن معلوم قدره. ومثقال الشيء: ميزانه من مثله. والثقلة: نعسة غالبة. واثقلت المرأة فهي مثقل، قال الله- عز وجل-: فلما أثقلت'),
(1832, 'نقث', 'نقث', 'نقث', 'التنقيث: الإسراع، وخرج يتنقث في سيره أي يسرع إسراعا.'),
(1833, 'ثقف', 'ثقف', 'ثقف', 'قال أعرابي: إني لثقف لقف راو رام شاعر. وثفقت فلانا في موضع كذا أي أخذناه ثقفا. وثقيف: حي من قيس. وخل ثقيف قد ثقف ثقافة. ويقال: خل ثقيف على قوله: خردل حريف، وليس بحسن. والثقاف: حديدة تسوى بها الرماح ونحوها، والعدد أثقفة، وجمعه ثقف. والثقف مصدر الثقافة، وفعله ثقف إذا لزم، وثقفت الشيء وهو سرعة تعلمه. وقلب ثقف أي سريع التعلم والتفهم.'),
(1834, 'ثقب', 'ثقب', 'ثقب', 'الثقب مصدر: ثقبت الشيء أثقبه ثقبا، والثقب اسم لما نفذ. والمثقب أداة يثقب بها. والثقوب مصدر النار الثاقبة، والكواكب ونحوه أي التلألؤ، وثقب يثقب. وحسب ثاقب مشهور مرتفع. ورجل ثقيب وامرأة ثقيبة: شديدة الحمرة، وقد ثقب يثقب ثقابة. ويثقب: موضع بالبادية، قال النابغة: عفت روضة الأجداد منها فيثقب 1'),
(1835, 'بثق', 'بثق', 'بثق', 'البثق كسر شط النهر فينبثق الماء، وقد بثقته أبثقه بثقا. والبثق اسم الموضع الذي حفره الماء، وجمعه بثوق. وانبثق عليهم إذا أقبل عليهم ولم يظنوا به.'),
(1836, 'قثم', 'قثم', 'قثم', 'القثم: لطخ الجعر ونحوه، ويقال للضبع قثام لتلطخها بجعرها. ويقال للذيخ قثم، واسم فعله القثمة، وقد قثم يقثم قثما وقثمة.'),
(1837, 'رقل', 'رقل', 'رقل', 'الإرقال: الإسراع، وأرقلت المفازة قطعتها، قال العجاج: والمرقلات كل سهب سملق 1 وأرقلت الناقة: أسرعت، وأرقل القوم في الحرب: أسرعوا فيها، قال الشاعر: إذا استنزلوا عنهن للطعن أرقلوا ... إلى الموت إرقال الجمال المصاعب 2'),
(1838, 'قرن', 'قرن', 'قرن', 'قرن الثور معروف، وموضعه من رأس الإنسان قرن أيضا، ولكل رأس قرنان. والقرن في السن: اللدة. والقرن: الأمة. وقرن بعد قرن، ويقال: عمر كل قرن ستون سنة. والقرن: عفلة الشاة والبقرة، وهو شيء تراه قد خرج من ثغرها. والقرن: جبل صغير منفرد. والقرنان: ما يبنى على رأس البئر من حجر أو طين، توضع عليهما النعامة، وهي خشبة يدور عليها المحور، قال: تبين القرنين وانظر ما هما ... امدرا أم حجرا تراهما 1 والقرن: طلق من جري الخيل. وقرنت الشيء أقرنه قرنا أي شددته إلى شيء. والقرن: الحبل يقرن به، وهو القران أيضا. وكان رجل عبد صنما فأسلم ابن له وأهله، فجهدوا عليه، فأبى فعمد إلى صنمه فقلده سيفا وركز عنده رمحا، وقال: امنع عن نفسك، وخرج مسافرا فرجع ولم يره في مكانه، فطلبه فوجده وقد قرن إلى كلب ميت في كناسة قوم فتبين له جهله، فقال: إنك لو كنت إلها لم تكن ... أنت وكلب وسط بئر في قرن أف لملقاك إلها يستدن 2 فقال هذه الأبيات وأسلم. والقران: حبل يشد به البعير كأنه يقوده، وجمعه قرن. وقرن: حي من اليمن منهم أويس القرني. والقرن: جعبة صغيرة تضم إلى الجعبة الكبيرة، وفي الحديث: الناس يوم القيامة كالنبل في القرن. والقرن في قول جرير: كالمشدود في القرن 1 يكون حبلا ويكون جعبة. والأقرن: المقرون الحاجبين. والقرن: ضدك في القوة. والقرن: حد ظبة السيف والسنان. والقرون: الناقة إذا جرت وضعت يديها ورجليها معا معا. والقرن: حرف رابية مشرفة على وهدة صغيرة. والقرانى تثنية فرادى، تقول: جاءوا فرادى وقرانى. والقران أن يقارن بين تمرتين يأكلهما معا، وفي الحديث: لا قران ولا تفتيش في أكل التمر. والقران أن تقرن حجة وعمرة معا. والقرون من النوق: المقترنة القادمين والآخرين من أطبائها. والقرون: التي إذا بعرت قارنت بعرها. وسمي ذا القرنين لأنه ضرب ضربتين على قرنيه. والقرين: صاحبك الذي يقارنك، وقوله- عز وجل: مقترنين 2 أي متقارنين. وتقول: فلان إذا جاذبته قرينته وقرينه قهرها أي إذا قرنت به الشديدة أطاقها وغلبها إذا ضم إليه أمر أطاقه، قال عمرو: متى نشدد قرينتنا بحبل ... نجد الحبل أو نقص القرينا 1 وقرينه الرجل امرأته. وأقرنت لهذا البعير أو البرذون أي أطعته، اشتق من قولك: صرت له قرينا أي مطيقا، ومنه قوله تعالى: ما كنا له مقرنين أي مطيقين. والأقرن والقرناء من الشاء ذات القرون. والقرنان: الذي لا غيرة له. وقارون ابن عم موسى- عليه السلام- وكان منافقا فلما عابته موسى استبان كفره فدعا عليه فخسف به. والقرون: النفس. والقيروان: القافلة، معربة. والقيروان: اسم مدينة.'),
(1839, 'رقن', 'رقن', 'رقن', 'ترقين الكتاب: تزيينه، وترقين الثوب بالزعفران والورس، قال: دار كرقم الكاتب المرقن 2 والرقون: النقوش.'),
(1840, 'رنق', 'رنق', 'رنق', 'الرنق: تراب في الماء من القذى ونحوه، وماء رنق ورنق. وقد أرنقته ورنقته. وفي عيشه رنق أي كدر، قال: قد أرد الماء لا طرقا ولا رنقا 1 والترنيق: كسر جناح الطائر حتى يسقط من آفة، وهو مرنق الجناح'),
(1841, 'قنر', 'قنر', 'قنر', 'القنور: الشديد الرأس، الضخم من كل شيء.'),
(1842, 'نقر', 'نقر', 'نقر', 'النقر: صوت اللسان يلزق طرفه بمخرج النون فيصوت به فينقر بالدابة لتسير، قال: وخانق ذي غصة جرياض ... راخيت يوم النقر والإنقاض 2 والنقير: نكتة في ظهر النواة منها تنبت النخلة. والنقير: أصل خشبة ينقر فينبذ فيه. والنقر: ضرب الرحى ونحوه بالمنقار، والمنقار حديدة كالفأس لها خلف مسلك مستدير تقطع به الحجارة. والنقار: الذي ينقش الركب واللجم والرحى. ورجل نقار منقر: ينقر عن الأمور والأخبار. وعن عمر (قال) : متى ما يكثر حملة القرآن ينقروا، ومتى ما ينقروا يختلفوا. والمناقرة: مراجعة الكلام بين اثنين وبثهما أمورهما. وفي الحديث: ما كان الله لينقر عن قاتل المؤمن أي ما كان ليقلع، قال: وما أنا من أعداء قومي بمنقر 1 والناقور: الصور ينقر فيه الملك أي ينفخ. والنقرة: قطعة فضة مذابة، والنقرة: حفرة غير كبيرة في الأرض. ونقرة القفا: وقبة بين العنق والرأس. والمنقر: بئر: بعيدة القعر كثيرة الماء، قال: أصدرها عن منقر السنابر ... نقر الدنانير وشرب الخازر 2 ومنقر: قبيلة. ومنقار الطير والخف: طرفه. والنقرة: ضم الإبهام إلى الوسطى، 3 ثم ينقر فيسمع صوته، وباللسان أيضا. ونقر باسم رجل أي دعاه من بين أصحابه خاصة، وانتقر أيضا. ونقرت رأسه: ضربته. وانتقرت الخيل بحوافرها أي احتفرت نقرا. وانتقر السيل نقرا: حفر يحفر فيها الماء. ونقرة: منزل بالبادية. وأنقرة: موضع بالشام ذكرتها الشعراء.'),
(1843, 'قرف', 'قرف', 'قرف', 'القرف: قشر المقل ونحوه وقشر السدر، وكل قرف قشر. وقرفته قرفا أي نحيته عنه، وكذلك تقرف الجلبة من القرحة. والقطعة منه قرفة. والقرف من الذنب، وفلان يقرف بالسوء أي يرمى به ويظن به، واقترف ذنبا أي أتاه وفعله. وهؤلاء جميعا قرفتي أي بهم وعندهم أظن بغيتي، وسل بني فلان فإنهم قرفة أي موضع خبره. وقرفت فلانا أي وقعت فيه وذكرته بسوء. واقترفت أي اكتسبت لأهلي. والقروف: الأوعية، الواحد قرف، وهي التي تتخذ من الجلود'),
(1844, 'قرب', 'قرب', 'قرب', 'القرب أن يرعى القوم بينهم وبين المورد وهم يسيرون بعض السير حتى إذا كان بينهم وبين الماء عشية أو ليلة عجلوا فقربوا، وهم يقربون قربا، واقربوا إبلهم، وقربت الإبل. وحمار قارب يطلب الماء، قال: قد قدموني لإقراب وإصدار 2 وقال: هاج الصوادي والحزان فاندلقت ... وانقض سابقها الحادي لها القرب 3 والعانة القوارب: هي التي تقرب القرب أي تعجل الورود، ويقال لطالب الماء ليلا: قارب. والقرب: طلب الماء ليلا. والقارب: سفينة صغيرة (تكون مع أصحاب السفن البحرية) 1 تستخف لحوائجهم، والجميع قوارب. والقراب للسيف والسكين: غمدهما، والفعل قربت قرابا وأقربت أيضا قرابا. والقراب: مقاربة الشيء، تقول: معه ألف درهم أو قراب ذلك، ومعه ملء قدح ماء أو قرابه. وأتيته قراب العشي، وقراب الليل. وهذا قدح قربان ماء ونصفان ماء وملآن ماء، فأما نصفان فمن النصف، وقربان أي قارب الامتلاء. وهذا قربان من قرابين الملك أي وزير، هكذا يجمعون بالنون، وهو في القياس خلف، وهم الذين يستنفع بهم إلى الملوك. والقرب ضد البعد، والاقتراب الدنو، والتقرب: التدني والتواصل بحق أو قرابة. والقربان: ما تقربت به إلى الله تبتغي به قربا ووسيلة. وما قربت هذا الأمر قربانا ولا قربا. وقرب فلان أهله أي غشيها قربانا. والقربى: حق ذوي القرابة. وفلان يقرب أمرا أي يعزوه بقول أو فعل، وقربت أمرا: ما أدري ما هو. والقرب: من لدن الشاكلة إلى مراق البطن، ومن الرفغ إلى الإبط من كل جانب. وفرس لاحق الأقراب، يجمعون القرب، وإنما للفرس قربان، ولكن لسعته، كما يقولون: شاة عظيمة الخواصر، ولها خاصرتان كما قال: لأبيض عجلي عظيم المفارق 1 جمعه لسعته. والقريب ذو القرابة، ويجمع أقارب، وقريبة جمعها قرائب، للنساء. والقريب نقيض البعيد يكون تحويلا يستوي فيه الذكر والأنثى، والفرد والجميع، هو قريب، وهي قريب، وهم قريب، وهن قريب وفرس مقرب: قرب مربطه ومعلفه لكرامته، ويجمع مقربات ومقاريب. وأقربت الشاة والأتان فهي مقرب، وأدنت الناقة فهي مدن لا غير. والقريب: السمك المملح ما دام في طراءته. وقد حيى فلان وقرب أي قال: حياك الله وقرب دارك.'),
(1845, 'رقب', 'رقب', 'رقب', 'رقبت الشيء أرقبه رقبة ورقبانا أي انتظرت. وقوله تعالى: لم ترقب قولي 2 أي لم تنتظر. والترقب: تنظر الشيء وتوقعه. والرقيب: الحارس يشرف على رقبة، يحرس القوم. ورقيب الميسر: الأمين الموكل بالضريب، ويقال: الرقيب السهم الثالث. والرقيب: الحافظ. والرقوب من الأرامل والشيوخ: الذي لا ولد له، ولا يستطيع الكسب، ويقال: هو الذي لم يقدم من ولده شيئا، وسميت الأرملة رقوبا لأنه لا كاسب لها ولا ولد فهي تترقب معروفا. والرقبة أصل مؤخر العنق، والأرقب والرقباني الغليظ الرقبة وأمة رقبانية رقباء ولا تنعت به الحرة. والرقب جمع كالرقاب، والإعطاء في الرقاب أي في المكاتبين. وأعتق الله رقبته، ولا يقال: عنقه. والرقيب: ضرب من الحيات، وجمعه رقب ورقيبات.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1846, 'برق', 'برق', 'برق', 'البرق دخيل في العربية، ويجمع على برقان. والبرق مصدر الأبرق من الحبال، وهو الحبل الذي أبرم بقوة سوداء وقوة بيضاء. ومن الجبال: ما فيه جدد بيض وجدد سود. والبرقاء من الأرض: طرائق بقعة فيها حجارة سود يخالطها رملة بيضاء، وكل قطعة على حيالها برقة، فإذا اتسع فهو الأبرق، والأبارق جمعه، ويجمع على البراق. والأبارق: الأكام يخالطها الحصى والرمال، قال: لنا المصانع من بصرى إلى هجر ... إلى اليمامة فالبرق 1 وهضب الأبارق: موضع بعينه. والبروق: بيض السحاب، وبرق يبرق بروقا وبريقا، وأبرق لغة. والبارقة: سحاب يبرق، وكل شيء يتلألأ فهو بارق، ويبرق بريقأ. ويقال للسيوف بوارق. وإذا اشتد موعد بالوعيد يقال: أبرق وأرعد، قال: أبرق وأرعد يا يزيد ... فما وعيدك لي بضائر 2 وبرق ورعد لغة، قال: فارعد هنالك ما بدا لك وابرق 3 وأبرقت الناقة: ضربت بذنبها مرة على فرجها، ومرة على عجزها. والإنسان البروق هو الفرق لا يزال، قال: يروغ لكل خوار بروق 4 كأنه من قولك: برق بصره فهو برق أي بهت، فهو فزع مبهوت. وكذلك يفسر من قرأ: فإذا برق البصر 5 . ومن قرأ: برق يقول: تراه يلمع من شدة شخوصه ولا يطرف، قال: لما أتانا ابن عمير راغيا ... أعطيته عيساء منها فبرق 6 أي رد لها على الإبل. وبرق بعينه تبريقا إذا لألأها من شدة النظر. والبراق: دابة يركبها الأنبياء. والأباريق: جمع إبريق. والبرقان: جمع برقانة، وهي جرادة تلونت بخطوط صفر وسود.'),
(1847, 'ربق', 'ربق', 'ربق', 'ربقت الشاة ربقا بالربق وهو الخيط، الواحدة ربقة، وشاة مربقة أعم، ومربوقة. وأم الربيق اسم للحرب، واسم للداهية الشديدة، قال العجاج: أم الربيق والوريق الأزنم 1 ويروى: الأزلم.'),
(1848, 'قبر', 'قبر', 'قبر', 'المقبرة والمقبرة: موضع القبور، والقبر واحد. والقبر: مصدر، والقبر موضع القبر، وقبرته أقبره قبرا ومقبرا. والاقبار: أن تهيء له قبرا وتنزله منزلة ذاك، قال الله تعالى: ثم أماته فأقبره 2 ، أي جعله بحال يقبر. والمقابر: الذي يحفر. معك القبر. والقبر: موضع متأكل مسترخى في العود الذي يتطيب به، وهو جوفه.'),
(1849, 'بقر', 'بقر', 'بقر', 'البقر: جماعة البقرة، والبقير والباقر كقولك: الحمير والضئين والجامل، قال: يكسعن أذناب البقير الدلس 1 والباقر جمع البقر مع راعيها، وكذلك الجامل، جمع الجمل مع راعيها. والبقر: شق البطن، قال الراجز: ضربا وطعنا باقرا عشنزرا 2 والبقيرة شبه قميص تلبسه نساء الهند، ضيق إلى السرة. والتبقر: التفتح والتوسع من بقرت البطن، ونهي عن التبقر في المال. والمتبقر: اللاعب بالبقيرى، وهي لعبة يلعب بها. وبقروا حولهم أي حفروا، ويقال: كم بقرتم لغسيلكم أي كم حفرتم، وقال طفيل الغنوي: وملن فما ينفك حول متالع ... بها مثل آثار المبقر ملعب 3'),
(1850, 'قرم', 'قرم', 'قرم', 'القرم: الفحل المصعب. وأقرم أي ترك حتى استقرم أي صار مقرما فهو أقرم، وهو المكرم، ويترك للفحلة لا يحمل عليه. والقرم: تناول الحمل والجدي الحشيش، وأول ما يقرم أطراف الشجر شيئا، وهو راضع بعد. والقرم: أن يقرم من أنف البعير جليدة للسمة أي تقطع قطيعة فيبقى أثرها فتلك السمة القرمة والقرمة، والقطيعة التي قطعت قرامة. والبعير مقروم، وربما قرموا من كركرته وأذنه يتبلغ بها أي يؤكل عند القحط. والقرام: ثوب من صوف، فيه ألوان من العهون، صفيق، يتخذ سترا أو يغشى به هودج وكلة، ويجمع على قرم. والمقرمة: المحبس نفسه يقرم به الفراش. والقرم: شدة شهوة اللحم، وباز قرم، وقرمت إلى اللحم أي اشتهيته، قال: يزين البيت مربوطا ... ويشفي قرم الركب 1'),
(1851, 'رقم', 'رقم', 'رقم', 'الرقم: تعجيم الكتاب، وكتاب مرقوم: بينت حروفه بالتنقيط. والتاجر يرقم ثوبه بسمته. والمرقوم من الدواب: الذي يكون على أوظفته كيات صغار، كل واحدة رقمة، وينعت بها حمار الوحش لسواد على قوائمه. والرقم: خز موشى، يقال: خز رقم كما تقول: برد وشيء مضاف. والرقمتان شبه ظفرين في قوائم الدابة متقابلتين والرقمة: نبات. والرقمة: لون الحية الأرقم، وإنما هي رقشة من سواد وبغثة، والجميع الأراقم، والأنثى رقشاء ولا يقال رقماء. والأرقم إذا جعلته نعتا قلت أرقش، والأرقم اسمه، وربما جعله نعتا كما قال الباهلي: تمرس بي من حينه وأنا الرقم 1 يريد الداهية.'),
(1852, 'مرق', 'مرق', 'مرق', 'المرق: جماعة المرقة، لا فعل له. والمروق: الخروج من شيء من غير مدخله. والمارقة: الذين مرقوا من الدين كما يمرق السهم من الرمية مروقا، وأمرقته أنا. ويقال للذي يبدي عورته: أمرق إمراقا. ومرقت البيضة مرقا، ومذرت مذرا أي فسدت فصارت ماء. والامتراق: سرعة المروق، وقد امترقت الحمامة من الوكر. والمريق: شحم العصفر 2 ، ويقال: هي عربية محضة، ويقال: ليست بعربية. ومراق البطن من العانة إلى السرة.'),
(1853, 'رمق', 'رمق', 'رمق', 'الرمق: بقية الحياة. ورمقوه ويرمقونه أي بقدر ما يمسك رمقه، ويقال: وما عيشه إلا رمقة ورماق، قال: ما زخر معروفك بالرماق 1 والرماق: المرامقة بالبصر، وما زلت أرمقه بعيني وأرامقه أي أتبعه بصري فأطيل النظر. والرامق الرامج أي الملواح الذي تصاد به البزاة ونحوها، يوكأ ببومة فيشد برجلها شيء أسود وتخاط عيناها، ويشد في ساقها خيط طويل، فإذا وقع البازي عليها أخذه الصياد من قترته.'),
(1854, 'قمر', 'قمر', 'قمر', 'القمراء ضوء القمر، وليلة مقمرة. واقمر التمر أي لم ينضج حتى أصابه البرد فذهبت حلاوته وطعمه. والقمرة: لون الحمار الأقمر، وهو لون يضرب إلى الخضرة. والقمراء: دخلة من الدخل. وقامرته فقمرته من القمار. والقمري: طائر كالفاختة مسكنه الحجاز.'),
(1855, 'مقر', 'مقر', 'مقر', 'المقر شبه الصبر، والمقر أيضا، قال: إنما الصبر ككنز بارز ... طلي المر عليه والمقر 2 والمقر: إيقاعك السمك المالح في الماء، وتقول: مقرته فهو ممقور.'),
(1856, 'لقن', 'لقن', 'لقن', 'اللقن إعراب لكن 1 ، وهو شبه طست من الصفر. ولقنني فلان تلقينا أي فهمني كلاما ولقنته وتلقنته، قال: لقن وليدك يلقن؟ ما تلقنه 2 وملقن اسم موضع.'),
(1857, 'نقل', 'نقل', 'نقل', 'النقل: ما بقي من الحجارة إذا قلع جبل ونحوه، وما نفي من صغار الحجارة. والنقل: تحويل شيء إلى موضع. والنقلة: انتقال القوم من موضع إلى موضع. والمنقل: طريق مختصر. والمنقل والمنقلة: مرحلة من منازل السفر. والنقل: سرعة نقل القوائم. وفرس منقل أي ذو نقل ونقال. والمناقلة: مراجعة الكلام في الشعر بين اثنين شبه المناقضة، والمناقرة في الصخب. وفرس نقال: خفيف سريع نقل القوائم. والنقل والمنقل: الخف الخلق والجميع النقال، قال الكميت: وكان الأباطح مثل الأرين ... وشبه بالحفوة المنقل 1 يصف شدة الحر، يقول: يصيب صاحب الخف ما يصيب الحافي من الرمضاء، والحفوة الحفا، والمنقل: النعل. والناقلة من نواقل الدهر تنقل قوما من حال إلى حال. والنواقل من الخراج: ما ينقل قوما من خراج قرية إلى قرية أو كورة إلى كورة أخرى. ونقلة الوادي: صوت السيل. والمنقلة من الشجاج: ما ينقل منها فراش العظام، صغارها. والنقل: ما يعبث به الشارب على الشراب نحو الفستق. والنقائل: رقاع نعال الإبل، الواحدة نقيلة، قال: خذم نقائلها [يطرن كأقطاع ... الفراء بصحصح شأس] 2'),
(1858, 'قلف', 'قلف', 'قلف', 'القلف: مصدر الأقلف. والقلفة: جليدة القلف. والقلف: اقتلاع الظفر من أصله، والقلفة من أصلها، قال: يقتلف الأظفار عن بنانه 1'),
(1859, 'لقف', 'لقف', 'لقف', 'اللقف: تناول شيء يرمى به إليك. ولقفني تلقيفا فلقفته وتلقفته والتقفته أعم، قال الله تعالى: فإذا هي تلقف ما يأفكون* 2 . ورجل لقف ثقف أي سريع الفهم لما يرمى إليه من كلام، أو رمي باليد. وحوض لقيف يمدر ولم يطين، والماء ينفجر من جوانبه.'),
(1860, 'فلق', 'فلق', 'فلق', 'الفلق: الفجر، وقوله تعالى: قل أعوذ برب الفلق هو الصبح، والله فلقه أي أوضحه وأبداه فانفلق. والله يفلق الحب فينفلق عن نباته. وسمعته من فلق فيه. وضربته على فلق مفرقه. وفلقت الفستقة فانفلقت. والفلقة: الكسرة من الخبز. والفلق: اسم الداهية من الحروب والكتائب وكل الدواهي. والفيلق: الكتيبة المنكرة الشديدة. وامرأة فيلق أي داهية صخابة. والفليق والفليقة كالعجيب والعجيبة، يقول العرب: يا عجبا من هذه الفليقة. وأمر مفلق أي عجب. ورجل مفلاق رذل قليل الشيء.'),
(1861, 'لفق', 'لفق', 'لفق', 'اللفق: خياطة شقتين تلفق إحداهما بالأخرى لفقا، والتلفيق أعم، وكلاهما لفقان ما داما منضمين، وإذا تباينا بعد التلفيق يقال: انفتق لفقهما فلا يلزمه اسم اللفق قبل الخياطة.'),
(1862, 'قفل', 'قفل', 'قفل', 'يقال من القفل أقفلته فاقتفل. والمقتفل من الناس الذي لا يخرج من يده خير، ورجل مقتفل وامرأة بالهاء لا يخرج من أيديهما شيء. والقفلة: إعطاؤك إنسانا الشيء بمرة، وتقول: أعطيته ألفا قفلة. والقفول: رجوع الجند بعد الغزو، قفلوا قفولا وقفلا، وهم القفل بمنزلة القعد، اسم يلزمهم. وجاءهم القفل والقفول، يعني الانصراف، ومنه اشتق اسم القافلة لرجوعهم إلى الوطن، قال: سيدنيك القفول وسير ليل ... تصله (كذا) بالنهار من الإياب 1 وقفل السقاء يقفل قفولا فهو قافل أي يابس. وشيخ قافل، وقفل الفرس: ضمر.'),
(1863, 'قبل', 'قبل', 'قبل', 'قال الخليل: من قبل ومن بعد غايتان بلا تنوين، (وهما مثل قولك: ما رأيت مثله قط) 1 فإذا أضفته إلى شيء نصبته إذا وقع موقع الصفة، تقول: جاء قبل عبد الله، وهو قبل زيد قادم. وإذا ألقيت عليه من صار في حد الأسماء نحو قولك: من قبل زيد، فصارت من صفة وخفض قبل ب من فصار قبل منقادا ب من، وتحول من وصفيته إلى الاسمية، لأنه لا تجتمع صفتان. وغلبه من لأن من صار في صدر الكلام فغلب. والقبل: خلاف الدبر، والقبل: فرج المرأة. والقبل: من إقبالك على الشيء، تقول: قد أقبلت قبلك، كأنك لا تريد غيره. وسئل الخليل عن قول العرب: كيف أنت لو أقبل قبلك، قال: أراه مرفوعا لأنه اسم وليس بمصدر كالقصد والنحو، إنما هو: كيف أنت لو استقبل وجهك بما تكره. والقبل: الطاقة، تقول: لا قبل لهم. وفي معنى آخر هو التلقاء، تقول: لقيته قبلا أي مواجهة، قال الكميت: ومرصد لك بالشحناء ليس له ... بالسجل منك إذا واضحته قبل أي طاقة. وأصيب هذا من قبله، أي من تلقائه ومن لدنه، وليس من تلقاء الملاقاة، ولكن على معنى: من عنده. وقوله تعالى: وحشرنا عليهم كل شيء قبلا 2 أي قبيلا قبيلا، ويقال: عيانا أي يستقبلون كذلك فكل جيل من الجن والإنس قبل. وقوله: إنه يراكم هو وقبيله 1 أي هو ومن كان من نسله. وأما القبيلة فمن قبائل العرب وسائر الناس. وقبيلة الرأس: كل فلقة قوبلت بالأخرى، والكرة 2 لها قبائل. والقبال: زمام النعل، ونعل مقبولة ومقبلة. والقبال: شبه فحج وتباعد بين الرجلين، وهو أفجى وأفحج، واحد لا فعل له، قال: حنكلة فيها قبال وفجا 3 والقبل: رأس الجبل والأكمة ونحوه، قال الكميت: والأخريان لما أوفى بها القبل 4 ومن الجيران مقابل ومدابر، قال: حمتك نفسي ومعي جاراتي ... مقابلاتي ومدابراتي 5 ومقابلة وقبالة: ما كان مستقبل شيء. وشاة مقابلة: قطعت من أذنها قطعة فتركت معلقة من قدم، والمدابرة من خلف. وإذا ضممت شيئا إلى شيء، تقول: قابلته به. والقابلة: الليلة المقبلة، والعام القابل: المقبل، ولا يقال منه فعل يفعل. والقابلة التي تقبل الولد عند الولاد، وتجمع قوابل. والقبول: الصبا لأنها تستدبر الدبور، وهي تهب مستقبل القبلة، قال: فإن تمنع سدوس درهميها ... فإن الريح طيبة قبول 1 والقبول: أن تقبل العفو والعافية، وهو اسم للمصدر وقد أميت الفعل منه. والقبل: إقبال سواد العين على المحجر، ويقال: بل إذا أقبل سوادها على الأنف فهو أقبل، وإذا أقبلا على الصدغين فهو أخزر. والقبل: استئناف الشيء، وتقول: أفعل هذا الشيء من ذي قبل، أي من ذي استقبال. وتقول: أقبلنا على الإبل، وذلك إذا شربت ما في الحوض فاستقيتم على رءوسها وهي تشرب، قال: قرب لها سقاتها يا ابن خدب ... لقبل بعد قراها المنتهب 2 والفعل من القبلة التقبيل. والتقبل: القبول، يقال: تقبل الله منك عملك، وتقبلت فلانا من فلان بقبول حسن. ورجل مقابل في الكرم والشرف من قبل أعمامه وأخواله. ورجل مقتبل من الشباب: لم ير فيه أثر من الكبر بعد، قال: بل ليس بعل كبير لا شباب له ... لكن أثيلة صافي اللون مقتبل 1 رفع أثيلة على طلب الهاء، كقولك: لكنه أقبل فلان أي جاء مستقبلك. وأقبلت الإبل طريق كذا أي استقبلت بها أسوقها، قال الشاعر: أقبلتها الخل من شوران مصعدة ... إني لأزوي عليها وهي تنطلق 2 وقوله: أزوي من زويت عليه أي شددت عليه في المشي وأقبلت الإناء مجرى الماء ونحو ذلك. وقبيل القوم 3 فعله القبالة. والقبيل والدبير في فتل الحبل، القبيل: الفتل الأول الذي عليه العامة، والدبير الفتل الآخر، ويقال: الفتل في قوى الحبل: كل قوة على قوة، فالوجه الداخل قبيل، والوجه الخارج دبير 4'),
(1864, 'لمق', 'لمق', 'لمق', 'اللمق: الطريق، قال رؤبة: ساوى بأيديهن من قصد اللمق 2 وهو اللقم، مقلوب.'),
(1865, 'لقم', 'لقم', 'لقم', 'لقم الطريق: مستقيمه ومنفرجه، تقول: عليك بلقم الطريق فالزمه. ولقم يلقم لقما، واللقمة الاسم، واللقمة: أكلها بمرة، وتقول: أكلت لقمة بلقمتين، وأكلت لقمتين بلقمة. وألقمته فسكت كأنه لقم حجرا.'),
(1866, 'قلم', 'قلم', 'قلم', 'الأقلام جماعة القلم. والمقلم: طرف قضيب البعير. والقلم: قطع الظفر بالقلمين، وبالقلم، وهو واحد كله. والقلامة: ما يقلم منه، قال: لما أبيتم فلم تنجوا بمظلمة ... قيس القلامة مما جزه الجلم 1 والقلم: السهم الذي يجال به بين القوم، ومع كل إنسان قلمه، وقوله تعالى: إذ يلقون أقلامهم 2 أي سهامهم حيث تساهموا أيهم يكفل مريم. ويقال: بل هي أقلامهم التي كانوا يكتبون بها التوراة.'),
(1867, 'ملق', 'ملق', 'ملق', 'الملق: الود واللطف الشديد، قال: إياك أدعو فتقبل ملقي 3 أي دعائي وتضرعي. وإنه لملاق متملق ذو ملق، ولا يقال منه فعل إلا على تملق. والإملاق: كثرة إنفاق المال والتبذير حتى يورث حاجة، وقوله تعالى: خشية إملاق 1 أي الفقر والحاجة. وأخفق وأملق وأورق واحد.'),
(1868, 'مقل', 'مقل', 'مقل', 'المقل: حمل الدوم، وهو شجر كالنخل في جميع حالاته، والواحدة مقلة. ومقلة العين: سوادها وبياضها الذي يدور في العين كله. وما مقلت عيناي مثله مقلا. والمقل: ضرب من الرضاع، قال: كثدي كعاب لم يمرث بالمقل 2 نصب يمرث على طلب النون 3 . والتماقل من التعاطي في الماء. والمقل: (الكندر) 4 الذي تدخن به اليهود ويجعل في الدواء.'),
(1869, 'قمل', 'قمل', 'قمل', 'القمل معروف. وفي الحديث: من النساء غل قمل يقذفها الله في عنق من يشاء ثم لا يخرجها إلا هو وذلك أنهم كانوا يغلون الأسير بالقد فيقمل القد في عنقه. وامرأة قملة أي قصيرة جدا والقمل: الذر الصغار، ويقال: هو شيء أصغر من الطير 1 الصغير، له جناح أكدر أحمر.'),
(1870, 'قفن', 'قفن', 'قفن', 'قفان كل شيء جماعته واستقصاء عمله. والقفينة: الشاة التي تذبح من القفا، ويقال: هي التي يبان رأسها بالذبح، وإن كان من الحلق، والمعنى يرجع إلى القفا، إلا أنه إذا أبان لم يكن له بد من أن يقطع القفا. وقد قالوا: القفن في موضع القفا، قال: وموضع الأزرار والقفن 2 فزادوا النون.'),
(1871, 'قنف', 'قنف', 'قنف', 'الأذن القنفاء إذن المعزى إذا كانت غليظة كأنها نعل مخصوفة، ومن الإنسان إذا لم يكن له أطر. وكمرة قنفاء. ورجل قناف أي ضخم الأنف، ويقال: طويل الجسم غليظه. والقنف: القنع، وهو القلاع الذي ييبس. إذا نش عنه الماء (يتطاير) 3 مثل الفراش، ويجمع قنانف.'),
(1872, 'نقف', 'نقف', 'نقف', 'النقف: كسر الهامة عن الدماغ ونحو ذلك، كما ينقف الظليم الحنظل عن حبه. والمناقفة: المضاربة بالسيوف على الرءوس. والمنقاف: عظم دويبة تكون في البحر تصقل به الصحف، له مشق في وسطه. ورجل نقاف أي صاحب تدبير للأمر ونظر في الأشياء.'),
(1873, 'فنق', 'فنق', 'فنق', 'ناقة فنق: جسيمة حسنة الخلق، وبعير فنق، والجميع أفناق، قال: [وندامى بيض الوجوه كأن ... الشرب منهم مصاعب أفناق 1 ] والفينق: الفحل المقرم الذي لا يؤذي ولا يركب. وجارية مفنقة وفنق: فنقها أهلها تفنيقا وفناقا، وهي مفناق.'),
(1874, 'نفق', 'نفق', 'نفق', 'نفقت الدابة تنفق نفوقا أي ماتت، قال: نفق البغل وأودى سرجه ... في سبيل الله سرجي وبغل 2 ونفق السعر ينفق نفاقا إذا كثر مشتروه. والنفقة: ما أنفقت واستنفقت على العيال ونفسك. والنفق: سرب في الأرض له مخلص إلى مكان. والنافقاء: موضع يرققه اليربوع في جحره، فإذا أخذ من قبل القاصعاء ضرب النافقاء برأسه فانتفق منها. وبعض يسمي النافقاء النفقة. وتقول: أنفقنا اليربوع إذا لم يرفق به حتى انتفق وذهب. والنيفق: دخيل: نيفق السراويل. والنافقة: دخيل، وهي فأرة المسك والنفاق: الخلاف والكفر، والفعل: نافق نفاقا، قال: للمؤمنين أمور غير محزنة ... وللمنافق سر دونه نفق 1 أي سر يخرج منه إلى غير الإسلام'),
(1875, 'قنب', 'قنب', 'قنب', 'القنب: جراب قضيب الدابة، وإذا كني عما يخفض من المرأة قيل: قنبها. والقنب: شراع ضخم من أعظم شرع السفينة. والمقنب زهاء ثلاث مائة من الخيل. والقنب: من الكتان. (والقنيب: الجماعة من الناس) 2'),
(1876, 'نقب', 'نقب', 'نقب', 'النقب في الحائط ونحوه يخلص فيه إلى ما وراءه، وفي الجسد يخلص فيه إلى ما تحته من قلب أو كبد. والبيطار ينقب في بطن الدابة بالمنقب في سرته حتى يسيل منه ماء أصفر، قال: كالسيد لم ينقب البيطار سرته ... ولم يسمه ولم يلمس له عصبا 1 والناقبة: قرحة تخرج بالجنب تهجم على الجوف يكون رأسها من داخل. ونقب الخف: تخرق ينقب نقبا، ونقب خف فرسن البعير، لا يقال لغيرهما. والنقبة: أول الجرب حين يبدو، والجميع نقب، قال: متبدلا تبدو محاسنه ... يضع الهناء مواضع النقب 2 ويقال للخيل والناقة. والنقب والنقب: طريق ظاهر على رءوس الجبال والأكام والروابي لا يزوغ 3 عن الأبصار، وهو المنقبة أيضا. والنقب 4 : الصدأ الذي يعلو السيف والنصال. والنقيب: شاهد القوم يكون مع عريفهم أو قبيلهم، يسمع قوله، ويصدق عليه وعليهم، ونقب ينقب نقابة، ونقب جائز. والنقباء الذين ينقبون الأخبار والأمور للقوم فيصدقون بها. والنقيبة: يمن العمل، وإنه لميمون النقيبة. والمنقبة: كرم الفعال، وأنه لكريم المناقب من النجدات وغيرها. والنقيبة من النوق: المؤتزرة بصرعها عظما وحسنا، بينة النقابة. وقول الله- عز وجل- فنقبوا في البلاد 1 ، أي سيروا فانظروا هل حاص من كان قبلكم فترجون محيصا، ولو قيل بالتخفيف لحسن. ونقبة الوجه: ما أحاط به دوائرها ونقبة الثور: وجهه، قال: ولاح أزهر مشهور بنقبته 2 والنقاب: ما انتقبت به المرأة على محجرها. والنقبة: ثوب كالإزار فيه تكة ليس بالنطاق، إنما النطاق محيط الطرفين. وانتقبت المرأة نقبة من النقاب. والنقاب: الحبر العالم.'),
(1877, 'بنق', 'بنق', 'بنق', 'البنيقة كل رقعة في الثوب نحو اللبنة وشبهها، والجميع بنائق، قال: قميص من القوهي بيض بنائقه 3 وقال: قد أغتدي والصبح ذو تبنيق 4 شبه بياض الصبح ببياض البنيقة.'),
(1878, 'نبق', 'نبق', 'نبق', 'النبق: (حمل السدر) 1 ، شجرة.'),
(1879, 'نقم', 'نقم', 'نقم', 'نقم ينقم نقما، ونقم ينقم نقما ونقيمة أي [أنكر ولم يرض] 2 . وانتقمت منه: كافأته عقوبة بما صنع. والناقم: تمر بعمان، وحي باليمن.'),
(1880, 'نمق', 'نمق', 'نمق', 'نمقت الكتاب تنميقا: حسنته وجودته، وبالتخفيف حسن. ونمقته: نقشته وصورته، قال النابغة: كأن مجر الرامسات ذيولها ... عليه قضيم نمقته الصوامع 3'),
(1881, 'قمن', 'قمن', 'قمن', 'يقال: هو قمن أي جدير، وهي وهم وهما وهن قمن أن يفعل كذا. وهذه الأرض من فلان موطن قمن أي جدير أن تكون مسكنه كثيرا، ويجوز في كله قمين، قال: فالأقحوانة منها منزل قمن 4'),
(1882, 'فقم', 'فقم', 'فقم', 'الفقم: ردة في الذقن، والنعت أفقم وفقماء. والفقم والفقم: طرف خطم الكلب ونحوه، وربما سمي ذقن الإنسان فقما. وأمر أفقم: أعوج مخالف. وفقم الأمر يفقم فقما وفقوما، ولو قيل: فقم [الأمر] لكان صوابا، قال: فإن تسمع بلأمهما ... فإن الأمر قد فقما 1 وسمعت: فقما، وليس في فعل يفعل قياس إلا بسماع واستحسان. والمفاقمة: البضع، فهو فاقم متفاقم.'),
(1883, 'بقم', 'بقم', 'بقم', 'البقم: شجرة، وهو صبغ يصبغ به، قال: كمرجل الصباغ جاش بقمه 2 وإنما علمنا أنه دخيل لأنه ليس للعرب كلمة على بناء فعل. ولو كانت عربية البناء لوجد لها نظير إلا ما يقال من (بذر) وخضم، وهو بنو العنبر بن عمرو بن تميم.'),
(1884, 'قوي', 'قوي', 'قوي', 'القوة، من تأليف قاف وواو وياء، حملت على فعلة فأدغمت الياء في الواو، كراهية تغيير الضمة. والغعالة: قواية وقواية 1 أيضا، يقال (ذلك) في الحزم، ولا يقال في البدن، قال: 2 ومال بأعناق الكرى غالباتها ... وإني على أمر القواية حازم جعل مصدر القوي على فعالة، والشعراء تتكلفه في النعت اللازم. ورجل شديد القوى، أي: شديد أسر الخلق ممره، أخذ من قوى الحبل. والقوة (طاقة من طاقات) 3 الحبل، والجميع: القوى. وفي الحديث: يذهب الدين سنة سنة، كما يذهب الحبل قوة قوة 4 ، وقال: 5 لا يصل الحبل بالصفاء ولا ... يؤوده قوة إذا انجذما والاقتواء: الاشتراء، ومنه اشتقت المقاواة والتقاوي بين الشركاء إذا اشتروا بيعا رخيصا ثم تقاووه، أي: تزاودوا هم أنفسهم حتى بلغوا به غاية ثمنه عندهم، فإذا استخلصه رجل لنفسه دونهم قيل: قد اقتواه. وأقوى القوم، إذا وقعوا في قي من الأرض. والقي: أرض مستوية ملساء، اشتق من القواء، (يقال) : أرض قواء: لا أهل فيها. والفعل: أقوت الأرض، وأقوت الدار، أي: خلت من أهلها، قال العجاج: 1 قي تناصيها بلاد قي قوقى: قوقت الدجاجة قوقاة خفيفة، وهي صوتها، تقوقي قوقاة وقيقاء فهي مقوقية. والقيقاءة: قشر الطلع، يجعل منه مشربة كالتلتلة، قال: 2 وشرب بقيقاة وأنت بغير أي: شرب فأكثر فلا يكاد يروى. والقيقاة: القاع المستديرة في صلابة من الأرض إلى جنب السهل، ويقال: قيقاء، ممدودة. قال رؤبة: 3 إذا جرى من آلها الرقراق ... ريح وضحضاح على القياقي وقد قصرها فقال: 4 وخب أعراف السفا على القيق كأنه جمع القيقة، والقياقي جماعتها في البيت الأول فكان لذلك مخرج. والقاق: [الأحمق] 1 الطائش، قال: 2 لا طائش قاق ولا عيي والقوق: الأهوج [الطويل] 3 ، قال أبو النجم: 4 أحزم لا قوق ولا حزنبل والدنانير القوقية من ضرب قيصر كان يسمى قوقا. والقوق: طائر من طير الماء، طويل العنق، قليل اللحم، قال: 5 كأنك من بنات الماء قوق والوقوقة: نباح الكلب عند الفرق، قال: 6 : حتى صفا نابحهم فوقوقا ... والكلب لا ينجح إلا فرقا وقى: وكل ما وقى شيئا فهو وقاء له ووقاية، تقول: توق الله يا هذا، ومن عصى الله لم تقه منه واقية إلا بإحداث توبة 7 . ورجل تقي وقي بمعنى. والتقوى في الأصل: وقوى، فعلى، من وقيت، فلما فتحت أبدلت تاء فتركت في تصريف الفعل، في التقى والتقوى، والتقاة والتقية، وإنما التقاة على فعلة، مثل تهمة وتكأة، ولكن خففت فلين ألفها، [والتقاة جمع، وتجمع على] تقي، كما أن الأباة [تجمع على] 1 أبي. وسرج واق، غير معقر، بين الوقاء، وما أوقاه. وفرس واق، إذا كان ظالعا وقى يقي وقيا، أي ظلع. قال: 2 تقي خيلهم تحت العجاج، ولا ترى ... نعالهم في هيكل الرحل تنقب واق: الواقة من طير الماء، عراقية. ومنهم من يهمز الألف، لأنه ليس في كلام العرب واو بعدها ألف أصلية في صدر البناء إلا مهموزة، نحو، الوألة، والوأقة، فلين الهمزة، قال: 3 أبوك نهاري وأمك واقة ويقال: قاقة. والواق: الصرد، قال: 4 ولست بهياب إذا شد رحله ... يقول: غدا بي اليوم واق وحاتم أقا: الإقاة: شجرة. قاء: القيء، مهموز، [قاء يقيء قيئا، وتقيأ واستقاء بمعنى] 1 . والاستقاء هو التكلف لذلك، والتقيؤ أبلغ. وفي الحديث: لو يعلم الشارب ما عليه قائما لاستقاء ما شرب 2 وتقيأت المرأة لزوجها تقيؤا، أي: تكسرت له، وألقت نفسها عليه، وتعرضت له، قال: 3 تقيأت ذات الدلال والخفر ... لعابس جافي الدلال مقشعر أوق: الأوقة: هبطة يجتمع فيها الماء. والجميع: الأوق، قال: 4 واغتمس الرامي لها بين الأوق والأوقية: وزن من أوزان الذهب 5 ، وهي سبعة مثاقيل. وآق [فلان] علينا، أي: أشرف، قال: 6 آق علينا وهو شر آيق والأوق: الثقل، وشدة الأمر، وعظمه، قال: 7 والجن أمسى أوقهم مجمعا وأوقته تأويقا [أي: حملته المشقة والمكدوة] ، قال: 1 عز على قومك أن تؤوقي ... أو أن تبيتي ليلة لم تغبقي أيق: الأيق: الوظيف، قال الطرماح: 2 [وقام المها يقفلن كل مكبل] ... كما رص أيقا مذهب اللون صافن'),
(1885, 'كش', 'كش', 'كش', 'كش البكر يكش كشيشا، وهو صوت بين الكتيت والهدير. والكشكشة: لغة لربيعة، يقولون عند كاف التأنيث: عليكش، إليكش، بكش بزيادة شين. كما قال: 1 ولو حرشت لكشفت عن حرش ... عن واسع يغيب فيه القنفرش وكشت الأفعى تكش كشيشا، إذا احتكت سمعت لجلدها مثل جرش الرحى وبلد تكاش أفاعيه: يوصف بالمحل والجدب.'),
(1886, 'شك', 'شك', 'شك', 'الشك: نقيض اليقين. والشكة: ما يلبس من السلاح. والشكة: ما يلبس من السلاح، وهو شاك في السلاح، شك يشك شكا، ويخفف، فيقال: شاك في السلاح، ويقال: إنما هو شاكك، فحذفت الكاف الأخيرة، وتركت الأولى على حالها مكسورة. ويقال: بل هو شائك، من الشوكة، فحمل على لغة من قال: أنا قاله، يريد: قائله، وكبش صاف، ويوم راح، أي: صائف ورائح فطرح الياء 1 ولم يحدث في الأعراب شيئا، وتركه على رفعه. وشككته بالرمح: خرقته.'),
(1887, 'ضك', 'ضك', 'ضك', 'امرأة ضكضاكة، أي: مكتنزة، صلبة اللحم.'),
(1888, 'كص', 'كص', 'كص', 'الكصيص: التحرك والالتواء من الجهد. قال امرؤ القيس: 2 [تغالبن فيه الجزء لولا هواجر] ... جنادبها صرعى لهن كصيص وفي الحديث: سمعت لأهل النار كصيصا.'),
(1889, 'صك', 'صك', 'صك', 'الصك: اصطكاك الرجلين. رجل أصك، وظليم أصك، من تقارب ركبتيه يصيب بعضها بعضا، إذا عدا. ولقيته في صكة [عمي] 1 ، أي: أشد الهاجرة حرا. وصك فلان حر وجه فلان: أي: لطمه. والصك: ضرب الشيء بالشيء شديدا'),
(1890, 'كس', 'كس', 'كس', 'الكسس: خروج الأسنان السفلى مع الحنك الأسفل، وتقاعس الحنك الأعلى. والنعت: أكس. وقوم كس، قال: 2 : إذا ما كان كس القوم روقا والتكسس: تكلف ذلك من غير خلقة.'),
(1891, 'سك', 'سك', 'سك', 'السكك: صغر قوف الأذن، وضيق الصماخ. يقال: استك سمعه. ويقال للظليم: أسك، وللقطاة: سكاء، قال: 1 سكاء مخطومة في ريشها طرق ... [سود قوادمها كدر خوافيها] والسك: طيب يتخذ من مسك ورامك. والسكة: أوسع من الزقاق. والسكة: حديدة كتب عليها، تضرب [عليها] 2 الدراهم. والسك: تصبيبك الباب والخشب بالحديد، قال: 3 [ولا بد من جار يجيز سبيلها] ... كما جوز السكي في الباب فيتق والسكاسك والسكاسكة: حي من اليمن، والنسبة إليه: سكسكي. والسكاك: الهواء. وفلان ليس على السكة، أي: ليس بطيب النفس.'),
(1892, 'كز', 'كز', 'كز', 'الكزازة: اليبس والانقباض. ورجل كز: صلب، قليل الخير والمواتاة. وخشبة كزة. (أي) فيها يبس واعوجاج. وذهب كز: صلب جدا. قال الضرير: الكز في الناس، فأما في الخشب فلا. وكززت الشيء: ضيقته فهو مكزوز، قال: 1 يا رب بيضاء تكز الدملجا ... تزوجت شيخا كبيرا كوسجا والكزاز: داء يأخذ من شدة البرد والعفز، تعتري [منه] الرعدة. يقال: رجل مكزوز.'),
(1893, 'كد', 'كد', 'كد', 'الكد: الشدة في العمل، وطلب الكسب.. يكد كدا. والكد: الإلحاح في الطلب، والإشارة بالأصابع، قال: 2 [غنيت فلم أرددكم عند بغية] ... وحجت ولم أكددكم بالأصابع والكدكدة: ضرب الصيقل المدوس على السيف إذا جلاه. والكديد: موضع بالحجاز. والكديد: التراب المدقوق المكدود المركل بالقوائم، قال: 1 [مسح إذا ما السابحات على الونى] ... أثرن غبارا بالكديد المركل'),
(1894, 'دك', 'دك', 'دك', 'الدك: شبه التل، والجميع: دككة، وأدك لأدنى العدد. والدك: كسر الحائط [والجبل] 2 ، قال الله عظم عزه: جعله دكا 3 ، ويقرأ: دكاء. ودكته الحمى دكا. وأقمت عنده حولا دكيكا، أي: تاما، قال: 4 أقمت بجرجان حولا دكيكا ... أروح وأغدو اختلافا وشيكا والدكداك: الرمل المتلبد، والدكادك جماعة، قال: 5 يدع الحزون دكادكا ورمالا والدكان: يقال: هو فعلان [من الدك] . ويقال: هو فعال 6 [من الدكن] . و (الدكاوات) 7 : تلال خلقة لا يفرد له واحد. ورجل مدك: شديد الوطء. قال الضرير: 1 الدكادك جماعة الدكدك.'),
(1895, 'كت', 'كت', 'كت', 'الكتيت من صوت البكر 2 : قيل الكشيش، يكت ثم يكش ثم يهدر.'),
(1896, 'تك', 'تك', 'تك', 'التكك: جمع التكة [وهي تكة السراويل] 3 . وفلان يستتكك بالحرير. ويستتك بالإدغام [أيضا] .'),
(1897, 'كذ', 'كذ', 'كذ', 'الكذان: حجارة فيها رخاوة كأنها المدر، وربما كانت نخرة. الواحدة بالهاء، قال العجاج: 1 كذانه أو يرأم الحري يقال: كذانة: فعلانة، ويقال: فعالة 2 .'),
(1898, 'كث', 'كث', 'كث', 'الكث والأكث: نعت للكبير اللحية، ومصدره: الكثوثة والكثث. قال أبو خيرة: رجل أكث ولحية كثاء بينة الكثث، والفعل: كث يكث كثوثة، وقوم كث. والكثكث: دقاق التراب 1 .'),
(1899, 'كر', 'كر', 'كر', 'الكر: الحبل الغليظ، وهو أيضا حبل يصعد به [على] النخل، قال أبو الوازع: فإن يك حاذقا بالكر يغنم ... بيانع معوها أثر الرقي 2 وقال أبو النجم: كالكر واتاه رفيق يفتله والكر: الرجوع عليه، ومنه التكرار. والكرير: صوت في الحلق كالحشرجة. والكرير: بحة تعتري من الغبار. والكرة: سرقين وتراب يجلى به الدروع. والكر: مكيال لأهل العراق. والكر نهر يقال إنه في أرمينية. والكركرة: رحى زور البعير، والكراكر: جمعها. والكركرة في الضحك فوق القرقرة. والكراكر: كراديس من الخيل، قال: 1 ونحن بأرض الشرق فينا كراكر ... وخيل جياد ما تجف لبودها والكركرة: تعريف الريح السحاب إذا جمعته بعد تفرق.'),
(1900, 'رك', 'رك', 'رك', 'الرك: المطر القليل، وسيل الرك أقل السيل. والركاكة: مصدر الركيك، أي: القليل. ورجل ركيك العلم: [قليله] 2 . والرك: إلزامك الشيء إنسانا، [تقول] : رككت الحق في عنقه، وركت الأغلال في أعناقهم. ورك [بالتشديد] : ماء بفيد (ولما لم يستقم الوزن لزهير) 3 جعله (ركك) .'),
(1901, 'كل', 'كل', 'كل', 'الكل: اليتيم. [والكل] : الرجل الذي لا ولد له، والفعل: كل يكل كلالة، وقلما يتكلم به، قال: 1 أكول لمال الكل قبل شبابه ... إذا كان عظم الكل غير شديد والكل [أيضا] : الذي هو عيال وثقل على صاحبه. وهذا كلي، أي: عيالي، ويجمع [على] كلول. والكليل: السيف الذي لا حد له. ولسان كليل: ذو كلالة وكلة. والكال: المعيي، يكل كلالة. والكل: النسب البعيد. هذا أكل من هذا، أي: أبعد في النسب. والكلة: غشاء من ثوب يتوقى به من البعوض. والإكليل: شبه عصابة مزينة بالجواهر. والإكليل: من منازل القمر. وروضة مكللة: حفت بالنور، قال: موطنه روضة مكللة ... حف بها الأيهقان والذرق 1 وكلل الرجل، إذا ذهب وترك عياله بمضيعة. وكلا الرجلين. اشتقاقه من كل القوم، ولكنهم فرقوا بين التثنية والجمع بالتخفيف والتثقيل. والكلكل: الصدر. والكلكل: الرجل الضرب ليس بجد طويل. والكلاكل من الجماعات، كالكراكر [من] 2 الخيل. قال [رؤبة:] 3 حتى يحلون الربى كلاكلا و [الكلاكل] 4 والجميع: الكلاكلون: المربوع [المجتمع] 5 الخلق.'),
(1902, 'لك', 'لك', 'لك', 'اللك: صبغ أحمر يصبغ به جلود البقر للخفاف، وهو معرب. واللك: ما ينحت من الجلد الملكوك يشد به السكاكين في نصبها، وهو معرب أيضا. واللكيك: المكتنز [يقال] : فرس لكيك اللحم، وعسكر لكيك [وقد] التكت جماعتهم لكاكا، أي: ازدحمت ازدحاما، قال: 1 وردا على خندقه لكاكا'),
(1903, 'كن', 'كن', 'كن', 'الكن: كل شيء وقى شيئا فهو كنه وكنانه. كننته أكنه كنا: جعلته في كن. والكنانة كالجعبة غير أنها صغيرة تتخذ للنبل. واستكن الرجل واكتن: صار في كن. واكتنت المرأة: سترت وجهها حياء من الناس. والكنة: امرأة الابن، أو الأخ، والجمع: الكنائن، والكنات. وكل فعلة أو فعلة، أو فعلة من باب التضعيف يجمع على فعائل، لأن الفعلة إذا كانت نعتا صارت بين الفاعلة والفعيل، والتصريف يضم الفعل إلى الفعيل، نحو: جلد وجليد، وصلب وصليب، فردوا المؤنث من هذا النعت إلى ذلك الأصل، كقول الراجز: 2 يخضبن بالحناء شيبا شائبا ... يقلن كنا مرة شبائبا شيب شائب، [أي] : يشوب السواد بياضه. قصر شابة فجعلها شبة، ثم جمعها على الشبائب، ردها من فاعلة إلى فعلة. والإكنان: ما أضمرت في ضميرك، قال الله عز وجل: أو أكننتم في أنفسكم 1 يعني: الضمير. والكانون: المصطلى. والكانونان: شهران في قلب الشتاء- رومية. والإكنان: إخفاء الشيء بالشيء، لا تريد به كن الوقاء. قال النابغة: 2 غداة تعاورته ثم بيض ... شرعن إليه في الرهج المكن والكنة: فصلة يخرجها الرجل من حائطه كالجناح.'),
(1904, 'كف', 'كف', 'كف', 'الكف: كف اليد، وثلاث أكف، والجميع: كفوف. وكفة اللثة: ما انحدر منها على أصول الثغر. وكفة السحاب وكفافه: نواحيه. وكفة الميزان: التي توضع فيها الدراهم. والكفة: ما يصاد به الظبي. ولقيته كفة لكفة، وكفة عن كفة، أي: مفاجأة [مواجهة] 1 . واستكف القوم بالشيء: أحدقوا [به] . واستكف السائل: بسط يده. وكف الرجل عن أمر كذا يكف كفا، وكففته كفا، [اللازم والمجاوز] 2 مستويان. والمكفوف: الذاهب البصر. والمكفوف في علل العروض: مفاعيل كان أصله: مفاعيلن، فلما ذهبت النون، قال الخليل: هو مكفوف. وكفاف الثوب: [نواحيه] 3 . والخياط يكف الدخريص [إذا كفه] 4 بعد خياطته 5 مرة. والناس كافة، كلهم داخل فيه، أي: في الكافة. والكفكفة: كفك الشيء، أي: ردك الشيء عن الشيء. وكعكفت دمع العين، وكففته أيضا.'),
(1905, 'فك', 'فك', 'فك', 'فككت الشيء فانفك. ككتاب مختوم تفك خاتمه، وكما تفك الحنكين تفصل بينهما. والفكان: ملتقى الشدقين من الجانبين. وفي فلان فكك، أي: إناثة واسترخاء. والأفك: مجمع الخطم، على تقدير أفعل، وهو مجمع الفكين. والفكة: النجوم المستديرة، التي إلى جانب بنات نعش، وهي التي يسميها الصبيان: قصعة المساكين. والفكاك: الشيء الذي تفك به رهنا أو أسيرا.. فككت الأسير فكا وفكاكا، وكما قال زهير: 1 وفارقتك برهن لا فكاك له ... يوم الوداع فأمسى الرهن قد غلقا وفككت رقبة فلان: أعتقته. والفكك: انفراج المنكب عن مفصله ضعفا أو استرخاء، والنعت: أفك، وفي فلان فكك قال: 2 أبد يمشي مشية الأفك'),
(1906, 'كب', 'كب', 'كب', 'كببته لوجهه فانكب، أي: قلبته. وأكب القوم على الشيء يعملونه. وأكب فلان على فلان [يطالبه] 3 . قال لبيد: 4 جنوح الهالكي على يديه ... مكبا يجتلي نقب النصال والفارس يكب الوحش إذا طعنها فألقاها على وجهها، قال: 1 فهو يكب العيط منها للذقن والكبكبة: جماعة من الخيل. وكببت الغزل: جعلته كبة. وقيس كبة: حي من اليمن. والكباب: الطباهج. والتكبيب: فعله. كبكب: جبل، لا ينصرف، قال: 2 [وتدفن منه الصالحات وإن يسىء ... يكن ما أساء] النار في رأس كبكبا والكبكبة: الدهورة، فكبكبوا فيها 3 . دهوروا وجمعوا، ثم رمي بهم في هوة من النار. وكببت الخيل: صدمتها.'),
(1907, 'بك', 'بك', 'بك', 'البك: دق العنق. وسميت مكة: بكة، لأن الناس يبك بعضهم بعضا في الطواف، [أي] : يدفع بعضهم بعضا بالازدحام. ويقال: بل سميت، لأنها كانت تبك أعناق الجبابرة إذا ألحدوا فيها بظلم. والبكبكة: شيء تفعله العنز بولدها.'),
(1908, 'كم', 'كم', 'كم', 'كم: حرف مسألة عن عدد، وتكون خبرا بمعنى رب، فإن عني بها رب جرت [ما بعدها] ، وإن عني بها ربما رفعت. وإن تبعها فعل [رافع ما بعدها] 1 انتصبت. ويقال: هي من تأليف كاف التشبيه ضمت إلى (ما) ، ثم قصرت (ما) فأسكنت الميم. فإن عني بذلك غير المسألة عن العدد قلت: كم هذا الذي معك؟ فيجيب المجيب: كذا وكذا. والكم: كم القميص. والكمة: من القلانس. والكمام: شيء يجعل في فم البعير أو البرذون [لئلا يعض] 2 . والكم: الطلع. لكل شجرة كم وهو برعومته. وقد كمت النخلة كما وكموما، قال الله جل وعز: والنخل ذات الأكمام 3 . وما تخرج من ثمرات من أكمامها 4 . قال لبيد: [نخل كوارع في خليج محلم ... حملت] فمنها موقر مكموم 5 وقول العجاج: 6 بل لو شهدت الناس إذ تكموا أي: اجتمعوا. وكممت الشيء: طينته. قال الأخطل: 1 كمت ثلاثة أحوال بطينتها ... [حتى إذا صرحت من بعد تهدار] وكممت النخلة إذا سمخت 2 ثمرتها، والكرم إذا ثقل حمله وسمخ، أي: تبسر العناقيد، حتى لا تنكسر القضبان.'),
(1909, 'مك', 'مك', 'مك', 'مكة: أم القرى. وامتككت المخ: مصصته، وإذا أخرجت المخ قلت: أخرجت المكاكة 3 وتمككتها. والمكوك: طاس يشرب به والمكوك: مكيال لأهل العراق، والجميع: مكاكيك، ومكاكي 4 . والمكاء 5 : طائر لا يكون إلا في الريف، وجمعه: مكاكي، قال: 6 إذا قوقأ المكاء في غير روضة ... فويل لأهل الشاء والحمرات'),
(1910, 'كسج', 'كسج', 'كسج', 'الكوسج [معروف] 1 دخيل'),
(1911, 'كرج', 'كرج', 'كرج', 'الكرج دخيل [معرب] ، وهو شيء يلعب به، وربما قالوا: كرق. قال جرير 2 : لبست سلاحي والفرزدق لعبة ... عليها وشاحا كرج وجلاجله'),
(1912, 'شكس', 'شكس', 'شكس', 'الشكس: السيء الخلق في المبايعة وغيرها، والشكس: المصدر. والليل والنهار يتشاكسان، أي: يتضادان، ولا [يتوافقان] 1 ، وكذلك الشركاء الشكسون، وفي القرآن: شركاء متشاكسون 2 ورجل شكس بين الشكس، قال: 3 إني امرؤ خلقت شكسا أشوسا'),
(1913, 'شكز', 'شكز', 'شكز', 'الأشكز كالأديم إلا أنه أبيض يؤكد به السروج.'),
(1914, 'كشط', 'كشط', 'كشط', 'الكشط: رفعك شيئا عن شيء قد غطاه [وغشيه] 4 من فوقه. والكشاط: جلد الجزور بعد ما يكشط. وربما غطي عليها به، فيقال: ارفع كشاطها لأنظر إلى لحمها، [يقال هذا] في الجزور خاصة. والكشطة: أرباب الجزور المكشوطة، وانتهى أعرابي إلى قوم قد كشطوا جزورا وقد غطوها بكشاطها. فقال: من الكشطة؟ يريد أن يستوهبهم ... ) فقيل له: وعاء المرامي، ومثابت الأقران وأدنى الجزاء من الصدقة، يعني فيما يجزى من الصدقة، فقال الأعرابي: يا كنانة ويا أسد. ويا بكر أطعموا من لحم الجزور.'),
(1915, 'كشد', 'كشد', 'كشد', 'الكشد: ضرب من الحلب بثلاثة أصابع. كشدها يكشدها كشدا. وناقة كشود، وهي التي تحلب كشدا، فتدر.'),
(1916, 'كدش', 'كدش', 'كدش', 'الكدش من الشوق. [وقد كدشت إليه] 2 .'),
(1917, 'شكد', 'شكد', 'شكد', 'الشكد كالشكر، لغة أهل اليمن، [يقال] : هو شاكر شاكد والشكد، لسائر العرب 1 : ما أعطيت من الكدس عند الكيل، ومن الحزم عند الحصد، يقال: استشكدني فلان فأشكدته.'),
(1918, 'كشث', 'كشث', 'كشث', 'الكشوث: نبات مجتث مقطوع الأصل، أصفر يتعلق بأطراف الشوك، ويجعل في النبيذ، من كلام أهل السواد، وليست بعربية محضة. يقولون: كشوثاء.'),
(1919, 'كشر', 'كشر', 'كشر', 'الكشر: بدو الأسنان عند التبسم، ويقال في غير ضحك، كشر عن أسنانه إذا أبداها. قال المتلمس 1 : إن شر الناس من يكشر لي ... حين ألقاه وإن غبت شتم وقال: 2 وإن من الإخوان إخوان كشرة ... وإخوان كيف الحال والبال كله الكشرة في هذا البيت خلف من المكاشرة، لأن الفعلة تجيء في مصدر فاعل، تقول: هاجر هجرة، وعاشر عشرة، وإنما يكون هذا التأسيس فيما يكون من الافتعال على تفاعلا جميعا. والكاشر: ضرب من البضع، يقال: باضعتها بضعا كاشرا، لا يشتق منه فعل عن أبي الدقيش.'),
(1920, 'كرش', 'كرش', 'كرش', 'يقال لكل مجتمع: كرش حتى لجماعة الناس. واستكرش الجدي: عظم بطنه. وكل سخل يستكرش حتى يعظم بطنه، ويشتد أكله. ويقال للصبي إذا عظم بطنه، وأخذ في الأكل: استكرش، وأنكر عامتهم ذلك، وقالوا للصبي: استجفر، وفي الأشياء كلها جائز، وهو اتساع البطن وخروج الجنبين. وكرش الرجل: عياله من صغار ولده. يقال: كرش منثور، أي: صبيان صغار. وتزوج فلان فلانة فنثرت له بطنها وكرشها، أي، كثر ولدها. وأتان كرشاء: ضخمة الخاصرتين والبطن. حتى يقال للدلو المنتفخة النواحي: إنها لكرشاء. وإذا تقبض جلد الوجه قيل: تكرش فلان، وفي كل جلد كذلك. والكرشاء 1 : ضرب من النبات. وكان رجل يكنى أبا كرشاء، قال: 2 وإن أبا كرشاء ليس بسارق ... ولكن مما يسرق القوم يأكل'),
(1921, 'شكر', 'شكر', 'شكر', 'الشكر: عرفان الإحسان [ونشره وحمد موليه] 3 ، وهو الشكور أيضا، قال الله عز وجل: لا نريد منكم جزاء ولا شكورا 4 . والشكور من الدواب: ما يسمن بالعلف اليسير ويكفيه. والشكرة من الحلوبات التي تصيب حظا من بقل أو مرعى، فتغزر عليه بعد قلة اللبن، فإذا نزل القوم منزلا وأصاب نعمهم شيئا من بقل فدرت قيل: أشكر القوم، وإنهم ليحتلبون شكرة (جزم) . وشكرت الحلوبة شكرا، قال: 1 نضرب دراتها إذا شكرت ... بأقطها، والرخاف نسلؤها الرخفة: الزبدة. والشكير من الشعر: ما ينبت بين الضفائر، ومن النبات ما ينبت من ساق الشجر، قضبان غضة تخرج بين القضبان القاسية، والجميع: الشكر، قال: 2 وبينا الفتي يهتز بالعيش ناضرا ... كعسلوجة يهتز منها شكيرها والشكر: الفرج في قول الأعشى: 3 [وبيضاء المعاصم إلف لهو] ... خلوت بشكرها ليلا تماما يشكر: قبيلة من ربيعة. وشاكر: قبيلة من اليمن من همدان.'),
(1922, 'شرك', 'شرك', 'شرك', 'الشرك: ظلم عظيم. والشركة: مخالطة الشريكين. واشتركنا بمعنى تشاركنا، و [جمع] شريك: شركاء وأشراك. قال لبيد: تطير عدائد الأشراك شفعا ... ووترا والزعامة للغلام 4 وتقول لأم المرأة: هذه شريكتي، وفي المصاهرة تقول: رغبنا في شرككم وصهركم. والشراك: سير النعل. شركت النعل تشريكا. والشرك: أخاديد الطريق الواضح الذي تلحبه الأقدام والقوائم، قال: 1 عمى شرك الأقطار بيني وبينه ... مراري مخشي به الموت ناضد والطريق مشترك، أي، الناس فيه شركاء، وكل شيء كان فيه القوم سواء فهو مشترك، كالفريضة المشتركة التي قضى فيها عمر فأشرك بين الإخوة للأب والأم، والإخوة للأم. والشرك: حبالة يرتبك فيها الصيد، الواحدة: شركة، والذي ينصب للحمام أيضا، قال: 2 يا قانص الحب قد ظفرت بنا ... فحل عنا الشباك والشركا'),
(1923, 'رشك', 'رشك', 'رشك', 'الرشك: اسم رجل على عهد الحسن 3 ، وكان الحسن إذا سئل عن فريضة قال: علينا بيان السهام وعلى يزيد الرشك الحساب. كان أحسب أهل زمانه. ويقال: كان معه حبالة يذرع بها الأرضين فغلب عليه الرشك، والرشك 4 : الذراع.'),
(1924, 'كشل', 'كشل', 'كشل', 'الكوشلة: الفيشلة الضخمة، وهي: الكوش والفيش أيضا.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(1925, 'شكل', 'شكل', 'شكل', 'الشكل: غنج المرأة، وحسن دلها. و [يقال] : إنها لشكلة مشكلة: حسنة الشكل. والشكل: المثل، يقال: هذا على شكل هذا، أي: على مثل هذا. وفلان شكل فلان، أي: مثله في حالاته، وقوله [جل وعز] : وآخر من شكله أزواج 1 . يعني بالشكل ضربا من العذاب على شكل الحميم، والغساق أزواج، أي: ألوان. والأشكل في ألوان الإبل والغنم: [أن] يكون مع السواد حمرة وغبرة 2 ، كأنه قد أشكل لونه، و [تقول] 3 في غير ذلك من الألوان: إن فيه لشكلة من لون كذا، كقولك: أسمر فيه [شكلة من] 4 سواد. والأشكل في سائر الأشياء: بياض وحمرة قد اختلطا، قال جرير 5 : فما زالت القتلى تمور دماؤها ... بدجلة حتى ماء دجلة أشكل وقال: 6 ينفخن أشكل مخلوطا تقمصه ... مناخر العجرفيات الملاجيج الملاجيج: اللاتي يلججن في سيرهن. والأشكال: الأمور المختلفة، وهي الشكول، وكذلك الحوائج المختلفة فيما يتكلف منها. قال العجاج: 7 وتخلج الأشكال دون الأشكال وقول أبي النجم: إذ جاوبوا ذا وتر مشكل تشكيله: دستانقه الذي ينقل الضارب أصابعه عليه، وإن شئت جعلت المشكل: البربط 1 . [وأشكل الأمر، إذا اختلف] 2 . وأمر مشكل شاكل: [مشتبه ملتبس] 3 . وشاكل هذا ذاك من الأمور، أي: وافقه وشابهه. وهذا يشكل به، أي: يشبه. وهي شكيلة، أي: شبيهة. والغراب شكل الغراب، أي: شبيهه. والشكال: حبل يشكل به قوائم الدابة. والشكال في الفرس: تحجيل ثلاث قوائم وإطلاق واحدة وهو مكروه. [وشكلت الكتاب: قيدته] 4 . والشاكلتان: ظاهر الطفطفتين من لدن مبلغ القصيرى إلى حرف الحرقفة من جانبي البطن.'),
(1926, 'نكش', 'نكش', 'نكش', 'النكش: شبه الأتي على الشيء، والفراغ منه. نكشته ونكشت منه، أي: أتيت عليه، وفرغت منه. واستنكش، أي: استنهد.'),
(1927, 'كشف', 'كشف', 'كشف', 'الكشف: رفعك شيئا عما يواريه ويغطيه، كرفع الغطاء عن الشيء. والكشفة: دائرة في قصاص الناصية، وربما كانت شعيرات نبتت صعدا، يتشاءم بها. والنعت: أكشف، والاسم: الكشفة 1 والكشوف: الناقة التي يضربها الفحل وهي حامل، وقد كشفت كشافا 2 .'),
(1928, 'كشب', 'كشب', 'كشب', 'الكشب: [شدة] 1 أكل اللحم. قال: 2 ملهوج مثل الكشى نكشبه وكشب: إحدى حرار 3 بني سليم.'),
(1929, 'كبش', 'كبش', 'كبش', 'إذا أثنى الحمل صار كبشا، [ولو لم] تخرج رباعيته. وبعضهم يقول: لا: حتى تخرج رباعيته. وكبش الكتيبة: قائدها.'),
(1930, 'شبك', 'شبك', 'شبك', 'شبكت أصابعي بعضها في بعض فاشتبكت، وشبكتها فتشبكت. ويقال لأسنان المشط: شبك. واشتبك السراب: دخل بعضه في بعض. وبينهما شبكة 4 رحم. والشباك: اسم لكل شيء كالقصبة المحبكة التي تجعل على صنعة البواري، كل طائفة شباكة. والشبكة: المصيدة في الماء وغيره. والشباك: مواضع من الأرض ليست بسبخة، ولا تنبت، كنحو شباك البصرة. وطريق شابك: مختلط بعضه في بعض. وبعير شابك الأنياب، ورجل شابك الرمح، إذا رأيته من ثقافته يطعن به في الوجوه كلها، قال: 1 كمي ترى رمحه شابكا واشتبك الظلام، أي: اختلط. واشتبكت النجوم، إذا تداخلت واتصل بعضها ببعض.'),
(1931, 'بشك', 'بشك', 'بشك', 'البشك [في السير] : خفة نقل القوائم، وهو يبشك ويبشك بشكا وبشكا. وامرأة بشكى اليدين والعمل، أي: سريعة. والبشك: الكذب، بشك يبشك بشكا، أي: كذب.'),
(1932, 'كشم', 'كشم', 'كشم', 'الكشم: الفهد. والكشم والجدع اسمان في قطع الأنف. [يقال] : ابتلاه الله بالكشم والجدع. وكشمه [يكشمه] كشما.'),
(1933, 'كمش', 'كمش', 'كمش', 'رجل كميش: عزوم ماض. كمش يكمش كماشة، وانكمش في أمره. والكمش، مجزوم، إن وصف [به] ذكر من الدواب فهو القصير الصغير الذكر. وإن وصف به الأنثى فهي الصغيرة الضرع. وهي: كمشة. وربما كان الضرع الكمش، مع كموشته درورا، قال: 1 يعس جحاشهن إلى ضروع ... كماش لم يقبضها التوادي التوادي: جمع التودية وهي خشبة تعرض ثم تشد على الطبي.'),
(1934, 'شكم', 'شكم', 'شكم', 'شكم [الفرس] يشكمه شكما، أي: أدخل الشكيمة في فمه، وهي الحديدة التي في الفم من اللجام والجميع: الشكم، والشكائم. قال القطامي: 2 لأفراسه يوما على الدرب غارة ... تصلصل في أشداقهن الشكائم وفلان شديد الشكيمة، أي: ذو عارضة وجد. والشكمى [والشكم] : النعمى، قال: 3 [أبلغ قتادة غير سائله] ... منه الثواب وعاجل الشكم يعني: النعم.'),
(1935, 'كرض', 'كرض', 'كرض', 'الكريض: ضرب من الأقط، وصنعته: الكراض. كرضوا كراضا، وهو جبن 1 يتحلب عنه ماؤه فيمصل. والكراض: ماء الفحل، قال: 2 سوف يدنيك من لميس سبنتاة ... أمارت بالبول ماء الكراض وهذه مدخلة في التشبيه، كقولهم، يأكل الطين كأنما يأكل به سكرا.'),
(1936, 'ركض', 'ركض', 'ركض', 'الركض: مشية الرجل بالرجلين معا، والمرأة تركض ذيولها برجليها إذا مشت، قال النابغة: 3 والراكضات ذيول الريط فنقها ... [برد الهواجر كالغزلان بالجرد] قال أبو الدقيش: تزوجت جارية شابة فلم يكن عندي شيء فركضت برجليها في صدري ثم قالت: يا شيخ ما أرجو بك، أي: ما أرجو منك. وفلان يركض دابته يضرب جنبيها برجليه، ثم استعملوه في الدواب لكثرته على ألسنتهم، فقالوا هي تركض، كأن الركض منها. و [المركضان] 4 : موضع عقبي الفارس من [معدي] 5 الدابة. والتركضى: مشية فيها ترقل وتبختر. والارتكاض: الاضطراب، كاضطراب الولد في البطن، والشاة إذا ذبحت، حتى جعل للطير في اضطراب طيرانها.'),
(1937, 'ضرك', 'ضرك', 'ضرك', 'الضريك: البائس الهالك بسوء حال، وقلما يقال للمرأة: ضريكة. والضريك: النسر الذكر. وضراك: اسم للأسد الشديد عصب الخلق في جسم. والفعل: ضرك يضرك ضراكة.'),
(1938, 'ضنك', 'ضنك', 'ضنك', 'الضنك: الضيق. ويفسر قوله جل وعز فإن له معيشة ضنكا 1 : كل ما لم يكن حلالا فهو ضنك وإن كان موسعا عليه. وقد ضنك عيشة. قال: 2 لقد رأيت أبا ليلى بمنزلة ... ضنك يخير بين السيف والأسد والضناك: الزكام، ضنك فهو مضنوك. [والضناك: الموثق الخلق الشديد] 3 ، ويستوي [الذكر و] 4 الأنثى فيه، رجل ضناك وامرأة ضناك. وامرأة ضناك، أي: مكتنزة تارة صلبة اللحم. ورجل ضنأك على بناء فعلل مهموز الألف، وهو الصلب المعصوب اللحم، والمرأة: ضنأكة.'),
(1939, 'صطك', 'صطك', 'صطك', 'المصطكى: العلك الرومي.'),
(1940, 'كنص', 'كنص', 'كنص', 'الكناص، والكناصة من الإبل والحمر ونحوها: الشديد القوي على العمل 1 .'),
(1941, 'نكص', 'نكص', 'نكص', 'النكوص: الإحجام. نكص هو وأنكصه غيره. والنكيصة: التأخر عن الشيء.'),
(1942, 'صكم', 'صكم', 'صكم', 'الصكمة: صدمة شديدة بحجر أو نحوه. وصكمته صواكم الدهر. والفرس يصكم، إذا عض على لجامه ثم مد رأسه يربد أن يغالب.'),
(1943, 'صمك', 'صمك', 'صمك', 'اصمأك، بوزن اقشعر، إذا عرفت فيه الغضب من الرجال والفحول، وازمأك مثله. واصماك اللبن إذا خثر، فصار كالجبن في الغلظ. مصك 1 : المصك: القوي الشديد الجسيم من الرجال.'),
(1944, 'كسد', 'كسد', 'كسد', 'الكساد خلاف النفاق. وسوق كاسدة. وتكسد الشيء: صار كاسدا. ويقال: كسد مكسدا، ومكسد: مصدر مثل مطمع.'),
(1945, 'كدس', 'كدس', 'كدس', 'الكدس من الطعام ومن الدراهم: ما يجمع. [يقال] : كدس مكدس. والتكدس: مشي للخيل كمشي الوعول، كأنه (يتكبب) 2 إذا مشى، قال: 3 وخيل تكدس مشي الوعول ... نازلت بالسيف أبطالها والكادس: القعيد من الظباء، الذي يجيء من خلف. يتشاءم به.'),
(1946, 'دكس', 'دكس', 'دكس', 'الدوكس: اسم للأسد. والديكساء: [قطعة] 1 عظيمة من الغنم والنعم.'),
(1947, 'سدك', 'سدك', 'سدك', 'السدك: المولع بالشيء، في لغة طيىء، قال: وودعت القداح وقد أراني ... بها سدكا وإن كانت حراما 2 ورجل سدك: خفيف العمل بيديه. [وإنه] سدك بالرمح، أي: رفيق به سريع.'),
(1948, 'دسك', 'دسك', 'دسك', 'الديسكاء لغة في الديكساء. والدوسك لغة في الدوكس.'),
(1949, 'سكت', 'سكت', 'سكت', 'سكت عنه الغضب سكوتا، وسكن بمعناه. ورجل ساكوت، أي: صموت، وهو ساكت، إذا رأيته لا ينطق، وساكت طويل السكوت. والسكيت، خفيفة، من الخيل: الذي يجيء في آخرها، إذا أجريت بقي 1 مسكتا. ويقال: سكت تسكيتا. وضربته حتى أسكت، أي: أطرق فلم يتكلم، وقد أسكتت حركته، أي: سكنت. أسكته الله وسكته. وبه سكات. إذا طال سكوته من شربة أو داء.. والسكت: من أصول 2 الألحان: تنفس بين نغمتين من غير تنفس، يريد بذلك فصل ما بينهما 3 . والسكتة: كل شيء أسكت به صبي أو غيره. والسكتتان في الصلاة تستحبان، أن تسكت بعد الافتتاح سكتة، ثم تفتتح القراءة، فإذا فرغت من الفاتحة سكت سكتة [ثم تفتتح ما تيسر من القرآن] 4 .'),
(1950, 'كسر', 'كسر', 'كسر', 'كسرته فانكسر. وكل شيء يفتر عن أمر يعجز عنه، يقال فيه: انكسر، حتى يقال: كسرت من برد الماء فانكسر. الكسر والكسر، لغتان: الشقة السفلى من الخباء ومن كل قبة، وغشاء يرفع أحيانا ويرخى. ويقال لناحيتي الصحراء: كسراها، قال يصف القطاة: 1 أقامت عزيزا بين كسري تنوفة وقال الأخطل: 2 وقد غبر العجلان حينا إذا بكى ... على الزاد ألقته الوليدة بالكسر والكسرة: قطعة خبز. وكسرى لغة في كسرى، ثم جمع فقالوا: أكاسرة وكساسرة، والقياس: كسرون مثل عيسون وموسون، ذهبت الياء لأنها زائدة. وأرض ذات كسور، أي: كثيرة الصعود والهبوط. وكسور الجبال والأودية: [معاطفها وجرفتها وشعابها] 3 ، لا يفرد [منه الواحد] 4 ، لا يقال: كسر الوادي. والكسر من الحساب: ما لم يكن سهما تاما، وجمعه: كسور. وكسر الطائر كسورا، فإذا ذكرت الجناحين قلت: كسر جناحيه كسرا، وذلك إذا ضم منهما شيئا للوقوع والانقضاض، الذكر والأنثى فيه سواء. [يقال] : باز كاسر، وعقاب كاسر، طرحوا الهاء، لأن الفعل غالب، قال: 5 كأنها كاسر في الجو فتخاء والكسير من الشاء: المنكسر الرجل. وفي الحديث: لا يجوز في الأضاحي كسير 1 . ويقال للعود والرجل الباقي على الشديدة: إنه لصلب المكسر. ومكسر الشجرة: أصلها حيث يكسر منه أغصانها وشعبها. ويقال للشيء الذي يكسر فيعرف بباطنه جودته: إنه لجيد المكسر، قال: 2 فمن واستبقى ولم يعتصر ... من فرعه مالا ولا المكسر يقول: لم يفسد ما اصطنع، ولم يكدره، لأن الفرع إذا عصرت ماءه فقد أفسدته 3 . والكسر: العضو من الجزور والشاء، والجميع: الكسور.'),
(1951, 'كرس', 'كرس', 'كرس', 'الكرس: كرس البناء. وكرس الحوض حيث تقف الدواب فيتلبد، ويشتد، ويكرس أس البناء فيصلب، وكذلك كرس الدمنة إذا تلبدت فلزقت بالأرض. وحوض مكرس، ورسم مكرس. والكرس من أكراس القلائد والوشح. [يقال] : قلادة ذات كرسين، وذات أكراس ثلاثة، إذا ضممت بعضها إلى بعض. ورجل كروس، أي: شديد الرأس والكاهل في جسم. قال العجاج: 4 فينا وجدت الرجل الكروسا والكرياس، والجميع: الكراييس: الكنيف يكون على السطح بقناة إلى الأرض.'),
(1952, 'سكر', 'سكر', 'سكر', 'السكر: نقيض الصحو. [والسكر ثلاثة] 1 : سكر الشراب، وسكر المال، وسكر السلطان. وسكرة الموت: غشيته. والسكر: شراب يتخذ من التمر والكشوث والآس، محرم كتحريم الخمر. والسكركة 2 : شراب من الذرة، شراب الحبشة. امرأة سكرى وقوم سكارى وسكرى. ورجل سكير لا يزال سكران. والسكر: سدك بثق الماء ومنفجره، والسكر: اسم السداد الذي يجعل سدا للبثق ونحوه. وسكرت الريح [تسكر] ، أي: سكنت. قال أوس بن حجر: 3 [تزاد ليالي في طولها] ... فليست بطلق ولا ساكره والسكرة: الواحدة من السكر [وهو من الحلوى] 4 .'),
(1953, 'ركس', 'ركس', 'ركس', 'الركس: قلب الشيء [على آخره، أو رد] 1 أوله إلى آخره. والمنافقون أركسهم الله وهو شبه نكسهم بكفرهم. وارتكس الرجل فيه إذا وقع في أمر بعد ما نجا منه. والركوسية: قوم لهم دين بين النصارى والصابئين، ويقال: هم نصارى. والراكس: الثور الذي يكون في وسط البيدر حين يداس، والثيران حواليه فهو يرتكس مكانه. وإن كانت بقرة فهي راكسة.'),
(1954, 'كسل', 'كسل', 'كسل', 'كسل [يكسل] كسلا. ورجل كسلان، وامرأة كسلى، وكسلانة، لغة رديئة: تثاقل عما لا ينبغي. وكسل الفحل، أي: فتر، قال: 2 أئن كسلت والحصان يكسل وامرأة مكسال: لا تكاد تبرح مجلسها. وفلان لا تكسله المكاسل، أي: لا تثقله وجوه الكسل. قال: 3 قد ذاد لا يستكسل المكاسلا وأكسل، بمعنى جامع، ولم ينزل، ويقال: لا يريد الولد فيعزل.'),
(1955, 'كلس', 'كلس', 'كلس', 'الكلس: ما كلست به حائطا، أو باطن قصر، شبه الجص من غير آجر. والتكليس: التمليس 1 ، فإذا طلي ثخينا فهو المقرمد.'),
(1956, 'سلك', 'سلك', 'سلك', 'السلك، والجميع السلوك: الخيوط التي يخاط بها الثياب. الواحدة: سلكة. والمسلك: الطريق، سلكته سلوكا والسلك والإسلاك واحد. والسلك: إدخال الشيء في شيء تسلكه فيه، كالطاعن يسلك الرمح فيه إذا طعنه تلقاء وجهه على سجيحته، قال: 2 نطعنهم سلكى ومخلوجة ... كرك لأمين على نابل وصفة بسرعة الطعن، وشبهه بمن يدفع الريشة إلى النبال في السرعة. والسلكى: [الأمر المستقيم] 3 . وقوله [جل وعز] : ما سلككم في سقر 4 . أي: ما أدخلكم فيها؟ والسلكان: فراخ القطا. الواحد: سلك، والأنثى: سلكة، ويقال: سلكانة. قال: 5 تضل به الكدر سلكانها'),
(1957, 'كنس', 'كنس', 'كنس', 'الكنس: كسح القمام عن وجه الأرض. والكناسة: ملقاها. والكناس: مولج للوحش [من البقر] يستكن فيه من الحر والصر، ثم يذهب إذا أمسى، فإذا صار مألفا فهو تولجه، وكنست، وتكنست: دخلته، وقوله: 1 [شاقتك ظعن الحي حين تحملوا] ... فتكنسوا قطنا [تصر خيامها] أي: دخلوا في هوادج [جللت] بثياب القطن. وقوله جل ذكره: الجوار الكنس : النجوم التي تستمر في مجاريها. وتكنس في مخاويها، أي: مغايبها ومساقطها. خوت النجوم خيا، لكل نجم خوي يقف فيه، ويستدير، ثم ينصرف راجعا، فكنوسه مقامه في خويه. وخنوسه أن يخنس بالنهار فلا يرى، ويقال: أراد بالجواري الكنس: الظباء والوحش.. وفرس مكنوسة، أي: ملساء جرداء من الشعر. والكنيس: ضرب من النبات.'),
(1958, 'سكن', 'سكن', 'سكن', 'السكون: ذهاب الحركة. سكن، أي: سكت ... سكنت الريح، وسكن المطر، وسكن الغضب. والسكن: المنزل، وهو المسكن أيضا. والسكن: سكون البيت من غير ملك إما بكراء وإما غير ذلك. والسكن: السكان. والسكنى: إنزالك إنسانا منزلا بلا كراء. والسكن، جزم: العيال، وهم أهل البيت، قال سلامة بن جندل: 1 ليس بأسفى ولا أقنى ولا سغل ... يسقى دواء قفي السكن مربوب والسكينة: الوداعة والوقار [تقول] : هو وديع وقور ساكن. وسكينة بني إسرائيل: ما في التابوت من مواريث الأنبياء، وكان فيه عصا موسى، وعمامة هارون الصفراء، ورضاض اللوحين اللذين رفعا، جعله الله لهم سكينة، لا يفرون عنه أبدا، وتطمئن قلوبهم إليه، هذا قول الحسن. وقال مقاتل: كان فيه رأس كرأس الهرة، إذا صاح كان الظفر لبني إسرائيل. والمسكنة: مصدر فعل المسكين، والمسكين: مفعيل بمنزلة المنطيق وأشباهه إلا أنهم اشتقوا [منه] فعلا فقالوا: تمسكن، ولا يقولون: مسكن. وأسكنه الله، وأسكن جوفه، أي: جعله مسكينا. والسكان: ذنب السفينة الذي به تعدل. والسكين: [المدية] ، يذكر ويؤنث، ويجمع [على] السكاكين، ومتخذه: السكان 2 .'),
(1959, 'نكس', 'نكس', 'نكس', 'نكسته أنكسه نكسا: قلبته. وولاد منكوس، [أن] تخرج رجله قبل رأسه. والنكس: العود في المرض، نكس في مرضه نكسا. والنكس من القوم: المقصر عن غاية النجدة والكرم، والجميع الأنكاس. وإذا لم يلحق الفرس بالخيل قيل: نكس. قال: 1 إذا نكس الكاذب المحمر'),
(1960, 'نسك', 'نسك', 'نسك', 'النسك: العبادة. نسك [ينسك] نسكا فهو ناسك. والنسك: الذبيحة، تقول: من فعل كذا فعليه نسك، أي: دم يهريقه، وقوله عز وجل: أو نسك 2 يعني: أو دم. واسم تلك الذبيحة: نسيكة. والمنسك: الموضع الذي فيه النسائك. والمنسك: النسك نفسه.'),
(1961, 'كسف', 'كسف', 'كسف', 'الكسف: قطع العرقوب بالسيف. كسفه يكسفه. وكسف القمر يكسف كسوفا، والشمس تكسف كذلك، وانكسف خطأ. ورجل كاسف [الوجه] 3 : عابس من سوء الحال. كسف في وجهي وعبس كسوفا. والكسفة: قطعة سحاب، أو قطعة قطن أو صوف، فإذا كان واسعا كبيرا فهو كسف، ولو سقط من السماء جانب فهو كسف.'),
(1962, 'سكف', 'سكف', 'سكف', 'الأسكفة: عتبة الباب. والسكاف: مصدر الإسكاف، ولا فعل له.'),
(1963, 'سفك', 'سفك', 'سفك', 'السفك: صب الدماء. فلان سفاك للدماء وللكلام. وسفكت العين الدم: حدرته.'),
(1964, 'كسب', 'كسب', 'كسب', '[الكسب: طلب الرزق] 1 . ورجل كسوب يكسب: يطلب الرزق. وكساب: اسم للذئب، و [ربما] يجيء في الشعر: كسب وكسيب. والكسب: الكنجارق، ويقال: الكسبج. وكساب، فعال، من كسب المال.'),
(1965, 'كبس', 'كبس', 'كبس', 'الكبس: طمك حفرة بتراب. كبس يكبس كبسا، واسم التراب: الكبس. والكبس: ما يسد من الهواء مسدا. وجبال كبس: صلاب شداد. وأرنبة كابسة: مقبلة على الشفة العليا. وناصية كابسة: مقبلة على الجبهة [تقول] : جبهة كبستها الناصية. والتكبيس: الاقتحام على الشيء، تقول: كبسوا عليهم. وكابوس: يكنى به عن البضع، [يقال] : كبسها: إذا فعل مرة. والكابوس: ما يقع على الإنسان بالليل، لا يقدر [معه] أن يتنفس. والكباسة: العذق التام بشماريخه. وعام الكبيس في حساب أهل الشام [المأخوذ] عن أهل الروم: في كل أربع سنين يزيدون في شهر شباط يوما، يجعلونه تسعة وعشرين يوما، يقومون بذلك كسور حساب السنة. يسمون العام الذي يزيدون فيه ذلك اليوم: عام الكبيس. والكبيس: تمر يكبس بالقوارير والجرار.'),
(1966, 'سكب', 'سكب', 'سكب', 'سكبت الماء فانسكب: صببته. ودمع ساكب، وأهل المدينة يقولون: اسكب على يدي، [أي] : اصبب. والسكبة: الكردة العليا التي يسقى منها كرود الطبابة 1 من الأرض والسكبة:، يقال، المكان الذي يسكب فيه. والسكب: ضرب من الثياب رقيق كأنه سكب ماء من الرقة، واشتقت السكبة منه، وهي خرقة تقوب للرأس كالشبكة، [يسميها الفرس: الشستقة] 1 .'),
(1967, 'سبك', 'سبك', 'سبك', 'السبك تسبيكك السبيكة من الذهب والفضة، تذاب فتفرغ في مسبكة من حديد كأنها شق قصبة.'),
(1968, 'مكس', 'مكس', 'مكس', 'المكس: انتقاص الثمن 2 في البياعة، ومنه اشتقاق [المكاس] 3 ، لأنه يستنقصه. قال: 4 [وفي كل أسواق العراق إتاوة] ... وفي كل ما باع امرؤ مكس درهم أي: نقصان درهم بعد وجوب الثمن. ورجل مكاس يمكس الناس.'),
(1969, 'سمك', 'سمك', 'سمك', 'السمك في الماء، الواحدة، سمكة. والسمكة: برج في السماء [يقال له: الحوت] 5 . والسماكان: كوكبان ينزل بأحدهما القمر من برج السنبلة. والسماك: ما سمكت به حائطا أو سقفا. والسمك يجيء في موضع السقف 1 . والسماء مسموكة، أي: مرفوعة كالسمك. وعن علي: اللهم رب المسمكات السبع 2'),
(1970, 'كرز', 'كرز', 'كرز', 'الكرز: ضرب من الجوالق. والكراز: كبش يحمل عليه الراعي طعامه ومتاعه أمام الغنم. والكرز [من الناس] : العيي اللئيم، الذي يسميه الفرس: كرزيا، قال رؤبة: 1 وكرز يمشي بطين الكرز والطائر يكرز، دخيل، قال رؤبة: 2 رأيته كما رأيت النسرا ... كرز يلقي قادمات زعرا'),
(1971, 'زكر', 'زكر', 'زكر', 'الزكرة: وعاء من أدم، لشراب أو خل. وتزكر بطن الصبي إذا عظم وحسنت حاله وفي زكريا أربع لغات: زكريا بالمد، وفي التثنية: زكرياءان، وزكرياوان، وفي الجمع: زكرياءون. وزكريا، بطرح الهمزة، وفي التثنية: زكرييان، وفي الجمع: زكرييون. وزكري، وفي التثنية: زكريان، والجميع: زكريون، مثل: مدني، ومدنيان [ومدنيون] . وزكري، بطرح الألف، وتخفيف الياء، وفي التثنية: زكريان، وفي الجمع: زكرون بطرح الياء. و [عنز] 1 حمراء زكرية: شديدة الحمرة، وزكرية، لغتان.'),
(1972, 'ركز', 'ركز', 'ركز', 'الركز: صوت خفي من بعيد كركز الصائد إذا ناجى كلابه، قال ذو الرمة: 2 وقد توجس ركزا مقفر ندس ... بنبأة الصوت ما في سمعه كذب والركز: [غرزك شيئا منتصبا كالرمح] 3 . ركزت الرمح وغيره أركزه ركزا، إذا غرزته منتصبا في مركزه. والمرتكز من يابس الحشيش: [أن] ترى ساقا [وقد] تطاير ورقها وأغصانها عنها. ومركز الجند: موضع أمروا ألا يبرحوه. والركاز: قطع من ذهب وفضة تخرج من المعدن، وفيه الخمس 4 ، وهو الركيز أيضا. وأركز المعدن إذا انقطع ما كان يخرج منه، فإذا وجد بغتة فقد أنال. والركائز: ما غرس من الأشجار وركز، الواحدة: ركيزة.'),
(1973, 'كلز', 'كلز', 'كلز', 'اكلأز الرجل [اكلئزازا] وهو انقباض في جفاء ليس بمطمئن. بمنزلة الراكب إذا لم يتمكن من السرج.'),
(1974, 'لكز', 'لكز', 'لكز', 'اللكز: الوجء في الصدر بجمع اليد، وفي الحنك.. رجل ملكز مدفع. لكيز: حي من عبد القيس.'),
(1975, 'لزك', 'لزك', 'لزك', 'لزك الجرح لزكا، إذا استوى نبات لحمه، ولما يبرأ بعد.'),
(1976, 'كنز', 'كنز', 'كنز', '[يقال: كنز الإنسان مالا يكنزه] 1 . والكنز: اسم للمال الذي يكنزه، ولما يحرز به المال. وكنزت البر في الجراب فاكتنز. وشددت كنز القربة، أي: ملأتها جدا، عن أبي الدقيش. ورجل مكتنز اللحم، وكنيز اللحم، ولا يكاد يقال الكناز إلا للناقة، ويعنى به المكتنزة اللحم. والكنيز: التمر الذي يكتنز للشتاء في قواصر وأوعية، والفعل: الاكتناز. كناز: من أسماء الرجال.'),
(1977, 'نكز', 'نكز', 'نكز', 'الحية تنكز بأنفها. والنكز كالغرز بشيء محدد الطرف. والنكاز: ضرب من الحيات لا يعض بفيه، إنما ينكز بأنفه، لا يكاد يعرف ذنبه من أنفه لدقة رأسه. ونكز البحر نكوزا، أي: غاض. والبئر أيضا، ونكزته أنا. قال: 1 فلا ناكز بحري ولا هو غائض والنكز: [طعن] 2 بطرف سنان الرمح.'),
(1978, 'زكن', 'زكن', 'زكن', 'الإزكان: أن تزكن شيئا بالظن فتصيب. تقول: أزكنته إزكانا. وزكنت منه إذا حسبت منه، [يقال: زكنت منه مثل الذي زكنه مني] 3 .'),
(1979, 'زنك', 'زنك', 'زنك', 'الزونك و [الزونزك] 1 : القصير الدميم. قال: 2 ليس بوزواز ولا [زونك]'),
(1980, 'نزك', 'نزك', 'نزك', 'النزك: سوء القول، تقول: نزكه بغير ما رأى فيه. والنزك: الطعن بالنيزك، وهو رمح قصير. والنزك: ذكر الضب. وللضب نزكان، أي: ذكران، ونزك [الضب] ضبته، أي: نزاها ففعل بها.'),
(1981, 'كزب', 'كزب', 'كزب', 'الكزب: لغة في الكسب. كالكسبرة في الكزبرة.'),
(1982, 'زكب', 'زكب', 'زكب', 'زكبت به أمه زكبا: رمت به. وانزكب الرجل: انقحم في وهدة، أو سرب. وزكب الطائر: ذرق، والزكاب: سلاحه.'),
(1983, 'كزم', 'كزم', 'كزم', 'الكزم: قصر في الأنف قبيح، وقصر في الأصابع شديد. [تقول] : أنف أكزم، ويد كزماء، قال: 1 ليست مصلمة كزماء مقلمة ... عن الأعادي ولا معروفها عاري والكزوم: الناب التي لم يبق في فمها سن من الهرم، نعت لها خاصة دون البعير، قال: 2 دعوا المجد إلا أن تسوقوا كزومكم ... وقينا عراقيا وقينا يمانيا يعني: البعيث والفرزدق.'),
(1984, 'كمز', 'كمز', 'كمز', 'الكمزة والجمزة: الكتلة من التمر ونحوه.'),
(1985, 'زكم', 'زكم', 'زكم', 'زكم الرجل فهو مزكوم. والزكمة منه، قال رؤبة: 3 [والكبح شاف] من زكام يزكمه'),
(1986, 'زمك', 'زمك', 'زمك', 'الزمكاء: أصل الذنب، [يمد ويقصر] 1 والذنب نفسه أيضا إذا قصر 2 . وازمأك 3 ، لغة، في اصمأك الغضبان.'),
(1987, 'كتد', 'كتد', 'كتد', 'الكتد: ما بين الثبج إلى منصف الكاهل من الظهر، فإذا أشرف ذلك الموضع من الظهر فهو أكتد، قال: 4 جبهته أو الخراة والكتد'),
(1988, 'كدر', 'كدر', 'كدر', '[الكدر: نقيض الصفاء] 5 . وكدر عيشه كدرا فهو كدر أكدر. وماء أكدر: كدر. والكدرة في اللون، والكدورة في العيش والماء. والكدر في كل شيء. والكدرة: القلاعة الضخمة من مدر الأرض المثارة. والكدرية من القطا: ضرب منه، فهي كدراء اللون، فإذا نسبوا نعت الكدراء، قالوا: كدرية، وللجونية: جونية. وانكدر القوم: جاءوا أرسالا حتى انصبوا عليهم. والمنكدر: طريق بين طريقي مكة من البصرة إلى مكة. كدير: رجل من بني ضبة. والمنكدر: اسم والد محمد بن المنكدر.'),
(1989, 'كرد', 'كرد', 'كرد', 'الكرد: سوق العدو في الحملة.. يكردهم كردا، ويزرهم 1 زرا. والكرد: لغة في القرد، وهو مجثم الرأس على العنق. والكرد: العنق. قال الفرزدق: 2 وكنا إذا القيسي نب عتوده ... ضربناه [فوق] الأنثيين على الكرد وقال: 3 [فطار بمشحوذ الحديدة صارم] ... فطبق ما بين الذؤابة والكرد والكرد: جيل من الناس، قال: 4 لعمرك ما كرد من أبناء فارس ... ولكنه كرد بن عمرو بن عامر'),
(1990, 'دكر', 'دكر', 'دكر', 'الدكر ليس في كلام العرب، وربيعة تغلط فتقول: الدكر للذكر، ويقال: هو اسم موضوع من الذكر، قال جرير: 1 هاج الهوى وضمير الحاجة الدكر ... [واستعجم اليوم من سلومة الخبر]'),
(1991, 'ركد', 'ركد', 'ركد', 'ركد الماء والريح ركودا، أي: سكن. والميزان إذا استوى فقد ركد، وهو راكد، قال: 2 وقوم الميزان حين يركد ... هذا سميري وذا مولد يعني: الدرهمين. وركد القوم: هدءوا وسكنوا. ركودا. والجفنة الركود: المملوءة الثقيلة، قال: 3 المطعمين الجفنة الركودا'),
(1992, 'درك', 'درك', 'درك', 'الدرك: إدراك الحاجة والطلبة، تقول: بكر ففيه درك. والدرك: أسفل قعر الشيء. والدرك: واحد من أدراك جهنم من السبع. والدرك: لغة في الدرك الذي هو من القعر. والدرك: اللحق من التبعة والدراك: إتباع الشيء بعضه على بعض في كل شيء، يطعنه طعنا دراكا متداركا، أي: تباعا 1 واحدا إثر واحد، وكذلك في جري الفرس، ولحاقه الوحش قال الله تعالى: حتى إذا اداركوا فيها جميعا 2 ، أي: تداركوا، أدرك آخرهم أولهم فاجتمعوا فيها. والدركة: حلقة الوتر التي تقع في الفرضة، وهي أيضا ما يوصل به وتر القوس العربية. والمتدارك من القوافي والحروف المختلفة: ما اتفق [فيه] متحركان بعدهما ساكن مثل: فعو وأشباه ذلك. والإدراك: فناء الشيء.. أدرك هذا الشيء، أي: فني، وقوله عز وجل، عن الحسن: بل ادارك علمهم في الآخرة 3 أي: جهلوا علم الآخرة، أي: لا علم عندهم في أمرها. وأدرك علمي فيه، مثله، قال الأخطل: 4 وأدرك علمي في سواءة أنها ... تقيم على الأوتار، والمشرب الكدر والدرك: حبل من ليف يعقد على عراقي الدلو، ثم يعقد طرف الرشاء به.'),
(1993, 'كلد', 'كلد', 'كلد', 'أبو كلدة: من كنى الضبعان. ذيخ كالد، أي: قديم. كلدة: اسم رجل. دكل 1 : الدكلة: الذين لا يجيبون السلطان من عزهم. وهم يتدكلون على السلطان. والدكل: لزوق الشيء بالشيء.'),
(1994, 'لكد', 'لكد', 'لكد', 'لكد الشيء بفيه لكدا. إذا أكل لكدا، أي: لزج ولزق لزوقا شديدا. ولكد فوه لكدا. والألكد: اللئيم الملصق في قومه. قال: 2 يناسب أقواما ليحسب فيهم ... ويترك أصلا كان من جذم ألكدا'),
(1995, 'دلك', 'دلك', 'دلك', 'دلكت السنبل حتى انفرك قشره عن حبه. والدليك: طعام يتخذ من زبد ولبن، شبه الثريد. ودلكت الشمس دلوكا: غربت، ويقال [إن] الدلوك زوالها عن كبد السماء أيضا. والدليك: نبيذ التمر. يطبخ التمر، ثم يدلك بالماء فيسمى دليكا. والمدلك: الشديد الدلك. والدلوك: اسم الشيء يتدلك به [من طيب أو غيره] 1 .'),
(1996, 'كدن', 'كدن', 'كدن', 'الكودن والكودني أيضا: البغل والفيل، قال: 2 خليلي عوجا من صدور الكوادن ... إلى قصعة فيها عيون الضياون شبه الثريدة الزريقاء بعيون السنانير [لما فيها من الزيت] 3 . والكديون: دقاق التراب على وجه الأرض ودقاق السرجين يجلى به الدروع ونحوها. ويقال: يخلط به الزيت فيسمى كديون. قال الضرير: الكديون: دردي الزيت. [وكدنت مشافر الإبل] 4 تكدن كدنا فهي كدنة وهو لغة في الكتن، وكتنت أصوب. وامرأة ذات كدنة، أي: كثيرة اللحم، وإنها لحسنة الكدنة، أي: ذات لحم. ويقال: الكدنة: السنام. وبعير ذو كدنة، أي: ضخم السنام، قال الكميت: 5 لم تغن كدنتها الإيقار زاملة ... ولا وطاب لبون الحي والعلب يصف ناقة لم يحمل عليها الإيقار وهي زاملة فيمحق شحمها ولحمها.'),
(1997, 'كند', 'كند', 'كند', 'الكنود: الكفور للنعمة، وقوله عز وجل: إن الإنسان لربه لكنود 1 يفسر بأنه يأكل وحده، ويضرب عبده، ويمنع رفده.'),
(1998, 'دكن', 'دكن', 'دكن', 'الدكنة والدكن مصدران للأدكن، وهو لون يضرب إلى الغبرة والسواد، دكن يدكن دكنا. والدكان [فعال] 2 ، وجمعه: دكاكين. ودكنت دكانا، أي: اتخذته.'),
(1999, 'نكد', 'نكد', 'نكد', 'النكد: اللؤم والشؤم، وكل شيء جر على صاحبه شرا فهو نكد، وصاحبه: أنكد نكد. ورجال نكدى ونكد. والنكد: قلة العطاء، [وألا يهنأه من يعطاه] 3 ، قال: 4 وأعط ما أعطيته طيبا ... لا خير في المنكود والناكد'),
(2000, 'فدك', 'فدك', 'فدك', 'فدك: موضع بالحجاز، مما أفاءه الله تعالى على رسوله محمد ص.'),
(2001, 'كبد', 'كبد', 'كبد', 'الأكباد جمع كبد، وهي اللحمة السوداء في البطن. والكبد، يذكر ويؤنث، قال: 4 لها كبد ملساء ذات أسرة'),
(2002, 'كدم', 'كدم', 'كدم', 'الكدم: العض بأدنى الفم، ككدم الحمار. والدواب تكادم الحشيش، إذا لم تستمكن منه. والكدم: اسم أثره، وجمعه: كدوم.'),
(2003, 'كمد', 'كمد', 'كمد', 'الكمدة: تغير لون [يبقى أثره] 2 ويذهب ماؤه وصفاؤه. وأكمد القصار الثوب، أي: لم ينق غسله. والكمد: هم وحزن لا يستطاع إمضاؤه. أكمده الحزن إكمادا. والكمادة: خرقة تسخن فيستشفى بها من رياح، أو وجع بوضعها على موضع الوجع. والكميد والمكمود واحد.'),
(2004, 'دكم', 'دكم', 'دكم', 'الدكم: دق شيء بعضه على بعض، وكسر بعضه على بعض.. دكم يدكم دكما. ودكم فاه، إذا دقه. ودقمه، مثله.'),
(2005, 'دمك', 'دمك', 'دمك', 'دمكت الأرنب تدمك دموكا، أي: أسرعت في العدو. والدموك: أعظم من البكرة يستقى عليها بالسانية، قال: 1 على دموك أمرها للأعجل'),
(2006, 'مكد', 'مكد', 'مكد', 'مكدت الناقة: نقص لبنها من طول العهد، قال: قد حارد الخور وما تحارد ... حتى الجلاد درهن ماكد 2 ومكدت الناقة: دام لبنها فلم ينقطع، فلا أدري أمن الأضداد [هي] أم لا. وقال [بعض العرب] في صفة عجوز: ما ثديها بناهد ولا درها بماكد [ولا فوها ببارد] 3 .'),
(2007, 'كتر', 'كتر', 'كتر', 'الكتر: جوز كل شيء. [أي: أوسطه] 1 . ويقال للجمل الجسيم: عظيم الكتر، وللرجل الشريف: إنه لرفيع الكتر في الحسب ونحوه. والكتر: مشية فيها تخلج كمشية السكران 2 .'),
(2008, 'تكر', 'تكر', 'تكر', 'التكرى: القائد من قواد السند، وجمعه تكاكرة، قال: 3 لقد علمت تكاكرة ابن تيري ... غداة البد أني هبرزي'),
(2009, 'ترك', 'ترك', 'ترك', 'الترك: ودعك 4 الشيء تتركه، والإتراك: الافتعال. والترك: الجعل في بعض الكلام. [تقول] : تركت الحبل شديدا، أي: جعلته. والترك: ضرب من البيض مستدير شبيه بالتركة والتريكة وهي بيض النعام، وتجمع [على] ترك وترائك، لأن الظليم أقيم عنها فتركها، قال لبيد: 1 [فخمة ذفراء ترتى بالعرى] ... قردمانيا وتركا كالبصل والتريكة: ماء يمضى عنه السيل، ويتركه ناقعا. وسمي الغدير، لأن السيل غادره. والترك: جيل من الناس.'),
(2010, 'رتك', 'رتك', 'رتك', 'رتك البعير رتكانا، أي: مشى في اهتزاز، وأرتكه صاحبه- يقال للإبل-: [إذا حمله على السير السريع] 2 .'),
(2011, 'كتل', 'كتل', 'كتل', 'الكتلة: أعظم من الجمزة، وهي قطعة من التمر قال الراجز 3 المطعمون اللحم بالعشج ... وبالغداة كتل البرنج يريد العشج: العشي، وبالبرنج: البرني، لغة ربيعة يجعلون الياء الثقيلة جيما أعجمية. والأكتل: من أسماء الشديدة من شدائد الدهر، اشتق من الكتال، وهو سوء العيش، وضيقه. قال الضرير: الكتال: السمن وحسن الحال، قال: 1 ولست براحل أبدا إليهم ... ولو عالجت من وبد كتالا وقال: 2 إن بها أكتل أو رزاما ... خويربان ينقفان الهاما رزام: اسم سنة شديدة. والوبد: الضيق في العيش. والمكتل: المجتمع المدور، قال أبو النجم: 3 قبصاء لم تفطح ولم تكتل والمكتل: الزبيل.'),
(2012, 'كتن', 'كتن', 'كتن', 'الكتن: لطخ الدخان بالبيت، والسواد بالشفة ونحوه. وكتنت جحافل الدواب. أي: اسودت من أكل الدرين الأسود. والكتن في قول الأعشى: 4 [هو الواهب المسمعات الشروب] ... بين الحرير وبين الكتن هو: الكتان.'),
(2013, 'نكت', 'نكت', 'نكت', 'النكت: أن تنكت بقضيب في الأرض، فتؤثر فيها بطرفه. والنكتة: شبه وقرة في العين. وشبه وسخ في المرآة. وكل شيء مثله، سواد في بياض أو بياض في سواد فهو نكتة. والظلفة المنتكتة: هي طرف الحنو من القتب والإكاف، إذا كانت قصيرة فنكتت جنب البعير، والمرفق إذا عقرته. والناكت بالبعير: شبه الناحز، وهو أن ينكت مرفقه حرف كركرته، يقال: بعير به ناكت.'),
(2014, 'نتك', 'نتك', 'نتك', 'النتك: كسر الشيء تقبض عليه ثم تجذبه إليك بجفوة.'),
(2015, 'كتف', 'كتف', 'كتف', 'الكتف: عظم عريض خلف المنكب تؤنث، وتجمع [على] أكتاف. والكتف: شد اليدين من خلف، والفعل: التكتيف. والكتف: مصدر الأكتف، وهو الذي انضمت كتفاه على وسط كاهله، وهي خلقة قبيحة. والكتاف: مصدر المكتاف من الدواب، وهو الذي يعقر السرج كتفه. والكتاف: وثاق في الرحل والقتب، وهو أسر عودين أو حنوين يشد أحدهما [إلى] 1 الآخر. والكتيفة: حديدة طويلة عريضة كأنها صفيحة، قال حسان: 2 سيوف الهند لم تضرب كتيفا أي: لم تطبع طبع الكتائف. والكتفان: ضرب من الطيران. كأنه يضم جناحيه من خلف شيئا. والكتفان من الجراد: أول ما يطير وتستوي أجنحته، الواحدة بالهاء.'),
(2016, 'فتك', 'فتك', 'فتك', 'الفتك: أن تهم بالشيء فتركبه، وإن كان قتلا، قال: 3 وما الفتك إلا أن تهم فتفعلا والفاتك: الذي يرتكب ما تدعوه إليه نفسه من الجنايات، والجميع الفتاك، قال: 4 وإذ فتك النعمان بالناس محرما ... فملىء من عوف بن كعب سلاسله أي: فتك بهم فأسرهم.'),
(2017, 'كفت', 'كفت', 'كفت', 'الكفت: صرفك الشيء عن وجهه، تكفته فينكفت، أي: يرجع راجعا. كفت يكفت كفاتا وكفتانا. والكفات من العدو والطيران كالحيدان في شدة. وكفات الأرض: ظهرها للأحياء وبطنها للأموات. والمكفت: الذي يلبس درعين بينهما ثوب. والكفت: تقليب الشيء ظهرا لبطن، وبطنا لظهر. وانكفتوا 1 إلى منازلهم، أي: انقلبوا. وكفت إليك ولدك، أي: ضمهم إليك.. وهو يكفت في مشيه، أي: يقصر. وشد كفيت: أي: سريع.'),
(2018, 'كتب', 'كتب', 'كتب', 'الكتب: خرز الشيء بسير، والكتبة: الخرزة التي ضم السير كلا وجهيها. والناقة إذا ظئرت [على ولد غيرها] 2 كتب منخراها بخيط لئلا تشم البو والرأم. قال ذو الرمة: 3 [وفراء غرفية أثأى خوارزها] ... مشلشل ضيعته بينها الكتب والكتب: الخرز بسيرين، قال: 4 لا تأمنن فزاريا خلوت به ... على قلوصك واكتبها بأسيار والكتاب والكتابة: مصدر كتبت. والمكتب: المعلم. والكتاب: مجمع صبيانه. والكتيبة من الخيل: جماعة مستحيزة. والكتبة: الاكتتاب في الفرض والرزق، واكتتب فلان، أي: كتب اسمه في الفرض. والكتبة: اكتتابك كتابا تكتبه وتنسخه.'),
(2019, 'كبت', 'كبت', 'كبت', 'الكبت: صرع الشيء لوجهه. كبتهم الله فانكبتوا، أي: لم يظفروا بخير. وكبت الله أعداءك، أي: غاظهم وأذلهم. والاسم: الكبات.'),
(2020, 'بكت', 'بكت', 'بكت', 'التبكيت: ضرب بالعصا والسيف ونحوهما [بكته بالعصا تبكيتا، وبالسيف ونحوه] .'),
(2021, 'تبك', 'تبك', 'تبك', 'تبوك: اسم أرض 1 وبين تبوك والمدينة اثنتا عشرة مرحلة.'),
(2022, 'بتك', 'بتك', 'بتك', 'البتك: قبضك على الشيء، على شعر أو ريش، أو نحو ذلك، ثم تجذبه إليك فينبتك من أصله. أي: ينقطع، وينتتف، وكل طاقة من ذلك في كفك: بتكة، قال زهير: 2 [حتى إذا ما هوت كف الغلام لها] ... طارت وفي كفه من ريشها بتك والبتك: قطع الأذن من أصلها. قال الله تعالى: فليبتكن آذان الأنعام 3 .'),
(2023, 'كتم', 'كتم', 'كتم', 'الكتم: نبات يخلط مع الوسمة للخضاب الأسود، قال: 1 وأصبح الأفق كمسود الكتم والكتمان: نقيض الإعلان. وناقة كتوم، أي: لا ترغو إذا ركبت، قال: 2 كتوم الهواجر ما تنبس والكاتم من القسي: التي لا ترن إذا أنبضت، وربما جاءت في الشعر: كاتمة وكتوم. [وقيل: هي التي لا شق فيها] 3 . وأكثر القول: هي التي لا صدع في نبعها.'),
(2024, 'كمت', 'كمت', 'كمت', 'الكميت: لون ليس بأشقر، ولا أدهم. والكميت: من أسماء الخمر فيها حمرة وسواد. وقد كمت كماتة وكمتة، وكمتته: جودته. وآكمات أكميتاتا.'),
(2025, 'تكم', 'تكم', 'تكم', 'التكمة: مشي الأعمى بلا قائد. وتكمة بنت مر أم سليم.'),
(2026, 'متك', 'متك', 'متك', 'المتك: أنف الذباب. والمتك: الوترة أمام الإحليل، وعرق بظر المرأة، يقال [في السب] 1 يا ابن المتكاء، أي: عظيمة ذلك. والمتكة: أترجة واحدة، ومنه قوله [جل وعز] : وأعتدت لهن متكأ 2 بلا همز، ومنهم من قرأ. متكأ أراد المرافق.'),
(2027, 'تمك', 'تمك', 'تمك', 'تمك السنام يمتك تموكا فهو تامك، إذا تر واكتنز.'),
(2028, 'كظر', 'كظر', 'كظر', 'الكظر: محز الفرضة في سية القوس التي فيها حلقة الوتر، والجميع الكظار. كظرتها أكظرها كظرا. والكظرة: الشحمة التي قد أقامت الكلية، فإذا انتزعت الكلية كان موضعها كظرا، وجمعه: كظار.'),
(2029, 'كنظ', 'كنظ', 'كنظ', 'الكنظ: بلوغ المشقة من الإنسان [يقال] : إنه لمكنوظ مغنوظ، ويكنظني هذا الأمر.'),
(2030, 'نكظ', 'نكظ', 'نكظ', 'النكظ: يكون بمعنى الكنظ، قال الأعشى: 1 قد تعللتها على نكظ الميط ... [وقد خب لامعات الآل] أي: على شدة البعد. ونكظ ينكظ نكظا من العجلة. [والنكظة: العجلة] 2 .'),
(2031, 'كظم', 'كظم', 'كظم', 'كظم الرجل غيظه: اجترعه. وكظم البعير جرته إذا ازدردها وكف عنها. ويقال للإبل: كظوم، وناقة كظوم أيضا، إذا لم تجتر. والكظم: مخرج النفس. [يقال] : قد غمه وأخذ بكظمه فما يقدر أن يتنفس، أي: كربه، وهو مكظوم كظيم، أي: مكروب. والكظامة: سير نوصله بوتر القوس العربية، ثم يدار بطرف السية العليا، وربما كانت حبلا يكظم به خطم 3 البعير، ويتخذ له درجة يجعلونها في القد، ويشد ذلك الحبل عليه. والدرجة خرقة تلف لفا شديدا شبه الصمامة عظمت أو صغرت. والكظامة: القناة.. كظمت القناة: سددتها. والكظيمة: واحدة الكظائم، وهي خروق تحفر فيجرى فيها الماء من بئر إلى بئر. والمكظوم: الذي يلتقمه الحوت. وكاظمة: موضع بالبادية.'),
(2032, 'ذكر', 'ذكر', 'ذكر', 'الذكر: الحفظ للشيء تذكره، وهو مني على ذكر. والذكر: جري الشيء على لسانك، تقول جرى منه ذكر. والذكر: الشرف والصوت، قال الله عز وجل: وإنه لذكر لك ولقومك 1 والذكر: الكتاب الذي فيه تفصيل الدين. وكل كتاب للأنبياء: ذكر. والذكر: الصلاة، والدعاء، والثناء. والأنبياء إذا حزبهم أمر فزعوا إلى ذكر الله، أي: الصلاة. وذكر الحق: الصك وجمعه: ذكور حقوق، ويقال: ذكور حق. والذكرى: اسم للتذكير، والتذكير مجاوز. والذكر معروف، وجمعه: الذكرة، ومن أجله سمي ما إليه 2 : المذاكير. والمذاكير: سرة الرجل، لا يفرد، وإن أفرد فمذكر مثل مقدم ومقاديم. والذكورة، والذكور، والذكران، جمع الذكر، وهو خلاف الأنثى. ومن الدواب: الذكورة. والذكر [من] الحديد: أيبسه وأشده، وبه سمي السيف مذكرا، وبه يذكر القدوم، والفأس ونحوه. وامرأة مذكرة، وناقة مذكرة، [إذا كانت] في خلقة الذكر، أو شبهه في شمائلها. وأذكرت الناقة والمرأة، [إذا] ولدت ذكرا. وامرأة مذكار، [إذا] أكثرت من ولاد الذكور. ويقال للحبلى في الدعاء: أيسرت وأذكرت، أي: يسر عليها وولدت ذكرا. والاستذكار: الدراسة للحفظ. والتذكر: طلب ما قد فات.'),
(2033, 'كذب', 'كذب', 'كذب', 'الكذاب لغة في الكذب. ويقرأ: لا يسمعون فيها لغوا ولا كذابا 1 بالتخفيف، والكذاب، بالتشديد لغة. تقول: كذبك كذبا، أي: لم يصدقك، فهو كاذب، وكذوب، أي: كثير الكذب. وكذبته: جعلته كاذبا. وأكذبته: وجدته كاذبا. وقوله [جل وعز] : لا يسمعون فيها لغوا ولا كذابا أي: تكذيبا، وذلك أن العرب تقول: كذبته تكذيبا، ثم تجعل بدل التكذيب: كذابا. والكذابة: ثوب يصبغ بألوان الصبغ كأنه موشي. وقول عمر: كذب عليكم الحج، كذب عليكم الجهاد، أي: وجب عليكم، ودونكم الحج، ولا يقال: يكذب ولا كاذب، ولا يصرف في وجوه الفعل.'),
(2034, 'كثر', 'كثر', 'كثر', '[الكثرة: نماء العدد] 1 ، كثر الشيء كثرة فهو كثير. و [تقول] : كاثرناهم [فكثرناهم] 2 . وكثر الشيء: أكثره، وقله: أقله. ورجل مكثر: كثير المال. ورجل مكثور عليه، أي: كثر من يطلب إليه معروفه. ورجل مكثار، وامرأة مكثار، وهما الكثيرا الكلام. وأكثرت الشيء، وكثرته: جعلته كثيرا. والكوثر: نهر في الجنة يتشعب منه أكثر أنهار الجنة. وعن عائشة: من أراد أن يسمع خرير الكوثر فليدخل إصبعه في أذنه. ويقال: بل الكوثر: الخير الكثير الذي أعطاه النبي ص. والكثر [والكثر] 3 : جمار النخل، ويقال: الكثر: الجذب وهو الجمار أيضا. قال الضرير: الجذب: نخل ينبت في جذوع النخل، فيجذب، ويؤكل جماره، أي: يقلع.'),
(2035, 'كرث', 'كرث', 'كرث', 'اكترث: فعل لازم من قولك: ما كرثني هذا الأمر، أي: ما بلغ مني المشقة. كرثته أكرثه كرثا، جزم. والكراث: بقلة ممدودة، إذا تركت خرج من وسطها طاقة طويلة تبزر 1 . والكراث: الهليون، وهو ذو الباءة. والكريث هو المكروث.'),
(2036, 'كثل', 'كثل', 'كثل', 'الكوثل: فوعل من الكثل، وهو مؤخر السفينة، يكون فيه الملاح ومتاعه.'),
(2037, 'لكث', 'لكث', 'لكث', 'لكثه لكثا: ضربه بيده أو برجله، وهو اللكاث، قال: 2 مدل يعض إذا نالهن ... مرارا، ويدنين فاه لكاثا'),
(2038, 'ثكل', 'ثكل', 'ثكل', 'الثكل: فقدان الحبيب، وأكثر ما يستعمل في فقدان المرأة ولدها. [يقال] : ثكلته أمه فهي به ثكلى. وأثكلت المرأة فهي مثكل، لازم لها الثكل، من غير أن يقال: أثكلت ولدها، وأثكلها الله فهي مثكلة بولدها، والجميع: مثاكيل. والأثكول: العرجون بشماريخه.'),
(2039, 'كنث', 'كنث', 'كنث', 'الكنثة: نوردجة 1 تتخذ من آس وأغصان خلاف، تبسط 2 وتنضد عليها الرياحين [ثم] 3 تطوى طيا. وكنثة أيضا. وبالنبطية: كنثى.'),
(2040, 'ثكن', 'ثكن', 'ثكن', 'الثكنة: مركز الجند على رايتهم، ومجتمعهم على لواء صاحبهم، وإن لم يكن هناك لواء فإن انحيازهم إلى رئيسهم يقال: هم على ثكنهم وثكنتهم. والثكنة: الواحدة، والجميع: الثكن، وهي الجماعات، قال الأعشى: 4 يطارد ورقاء جونية ... ليدركها في حمام ثكن والأثكون: العرجون، مثل: الأثكول.'),
(2041, 'نكث', 'نكث', 'نكث', 'نكث العهد ينكثه نكثا، أي: نقضه بعد إحكامه، ونكث البيعة، والنكيثة: اسمها. ونكثت السواك. والساف عن أصول الأظفار وشبهه إذا قشرته وشعثته، وأنا ناكث، وهو منكوث. وما أشد ما انتكث هذا السواك، وهو تشعث رأسه. والنكاثة: ما كان في فيك من تشعيث السواك ونحوه.'),
(2042, 'كثف', 'كثف', 'كثف', 'كثف كثافة، أي: كثر والتف. والكثيف: اسم يوصف به كثرة العسكر والسحاب والماء. وقد استكثف الشيء، أي: اشتد. وكذلك في الأمور.'),
(2043, 'كثب', 'كثب', 'كثب', 'كثبت التراب ونحوه كثبا فانكثب، أي: نثرته. وسمي الكثيب لدقة ترابه، كأنه منثور بعضه فوق بعض رخاوة. وكل طائفة من التمر والبر مصبوب فهو كثبة، وجمعه: كثب. والكثب: غاية قريبة، تقول: رماه من كثب. والكاثبة: ما ارتفع من منسج الفرس. والجميع: كواثب وأكثاب والكثبة: القليل من اللبن ونحوه من طعام وغيره. وكثبته، أكثبه كثبا، أي: جمعته، فأنا كاثب من قوله 1 [ميلاء من معدن الصيران قاصية ... أبعارهن] على أهدافها كثب والكاثب: جبل حوله رواب، يقال لها النبي، الواحد: ناب، قال اوس بن حجر 2 لأصبح رتما دقاق الحصى ... مكان النبي من الكاثب'),
(2044, 'كبث', 'كبث', 'كبث', 'الكباث: حمل الأراك المتفرق. ويقال: بل هو ما لم ينضج، ونضيجه: المرد. واسم ذلك كله: برير، قال: كأدم الظباء ترف الكباثا'),
(2045, 'كثم', 'كثم', 'كثم', 'أكثمك الأمر، أي: أمكنك. وأكثم: اسم 3 .'),
(2046, 'مكث', 'مكث', 'مكث', 'المكث: الانتظار. والماكث: المنتظر. وقد مكث مكاثة فهو مكيث، أي: رزين لا يعجل. وقوم مكيثون ومكثاء.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2047, 'ركل', 'ركل', 'ركل', 'الركل: الضرب برجل واحدة، ومركلا الدابة: موضع القصريين من الجنبين. والمركل: الجيد الركل، و [المركل] : الرجل [من الراكب] 1 . والتركل: كفعل الحافر بالمسحاة حين يتركل عليها برجله. قال الأخطل 2 : ربت وربا في كرمها ابن مدينة ... يظل على مسحاته يتركل'),
(2048, 'كرن', 'كرن', 'كرن', 'الكران: الصنج. والكرينة: الضاربة [بالصنج] . ويقال: الكران هو العود، قال: لولا الكران وهذا الناي يطربني 1'),
(2049, 'كنر', 'كنر', 'كنر', 'الكنارة: الشقة من ثياب الكتان. والكنار: السدر بالفارسية.'),
(2050, 'ركن', 'ركن', 'ركن', 'ركن إلى الدنيا: مال إليها واطمأن.. يركن ركنا.. وركن يركن ركونا، لغة سفلى مضر. وناس أخذوا من اللغتين فقالوا: ركن يركن. والركن: ناحية قوية من جبل 2 أو دار، والجمع: أركان 3 . وأركنت 4 لحاجتي: نزلت. وركن الرجل: قومه وعدده الذين يعتز بهم. قال عز اسمه حكاية عن لوط: أو آوي إلى ركن شديد 5 . وأركان [الجمل] 6 : قواه في أعضائه، ويقال: قوائمه. ورجل ركين: أي: شديد، ذو أركان. وأركان الجبل: نواحيه الناتئة منه. ويسمى الجرذ: ركينا. والمركن: شبه تور من أدم [يتخذ] للماء. قال الضرير: المركن: إجانة من خزف أو صفر. وناقة مركنة الضرع. و [يقال] : ضرع مركن، أي: انتفخ في موضعه حتى ملأ الأرفاغ، وليس بجد طويل.'),
(2051, 'رنك', 'رنك', 'رنك', 'الرانكية نسبة إلى الرانك، وهو حي.'),
(2052, 'نكر', 'نكر', 'نكر', 'والنكر: الدهاء. و [النكر] : نعت للأمر الشديد، والرجل الداهي. يقال: فعله من نكره، ونكارته. والنكرة: نقيض المعرفة. وأنكرته إنكارا، ونكرته لغة، لا يستعمل في الغابر، ولا في أمر ولا نهي، ولا مصدر. والاستنكار: استفهامك أمرا تنكره، واللازم من فعل النكر المنكر: نكر نكارة. ورجل نكر، ورجل منكر: داه ورجال منكرون، ويجمع بالمناكير أيضا، ولا يقال في هذا المعنى: [رجل] أنكر. قال: 1 مستحقبا صحفا تدمى طوابعه ... وفي الصحائف حيات مناكير والتنكر: التغير عن حال تسرك إلى حال تكرهها. والنكير اسم للإنكار الذي يعنى به التغير. والنكرة: اسم لما يخرج من الحولاء وهو الخراج من قيح أو دم كالصديد، وكذلك من الزحير. [يقال] : أسهل فلان نكرة ودماء، وليس له فعل مشتق. ومنكر ونكير: ملكان يأتيان الميت في قبره يسألانه عن دينه. والنكر: المنكر.'),
(2053, 'كرف', 'كرف', 'كرف', 'كرف يكرف ويكرف، لغتان، الحمار، وكل دابة كذلك، كرفا، وهو شمه البول ورفعه رأسه، حتى يقلص شفتيه، وربما قالوا: كرفها، أي: تشمم بولها، قال 1 : مشاخسا طورا وطورا كارفا'),
(2054, 'كفر', 'كفر', 'كفر', 'الكفر: نقيض الإيمان. ويقال لأهل دار الحرب: قد كفروا، أي: عصوا وامتنعوا. والكفر: نقيض الشكر. كفر النعمة، أي: لم يشكرها. والكفر أربعة أنحاء: كفر الجحود مع معرفة القلب، كقوله [عز وجل] : وجحدوا بها واستيقنتها أنفسهم 2 وكفر المعاندة: وهو أن يعرف بقلبه، ويأبى بلسانه. وكفر النفاق: [وهو أن] يؤمن بلسانه والقلب كافر. و [كفر الإنكار] : وهو كفر القلب واللسان. وإذا ألجأت مطيعك إلى أن يعصيك 3 فقد أكفرته. والتكفير: إيماء الذمي برأسه، [لا] 1 يقال: سجد له، وإنما [يقال] : كفر [له] والتكفير: تتويج الملك بتاج، قال: ملك يلاث برأسه تكفير 2 يصف ثورا، فالتكفير هاهنا التاج نفسه. والرجل يكفر درعه بثوب كفرا، إذا لبسه فوقه، فذلك الثوب كافر الدرع. والكافر: الليل والبحر، ومغيب الشمس. وكل شيء غطى شيئا فقد كفره. والكافر من الأرض: ما بعد عن الناس، لا يكاد ينزله أحد، ولا يمر به أحد، ومن حلها يقال: هم أهل الكفور. قال الضرير: هي القرى، واحدها: كفر. ويقال: أهل الكفور عند أهل المدائن كالأموات عند الأحياء. والكافر في لغة العامة: ما استوى من الأرض واتسع. والكافر: النهر العظيم، قال 3 : فألقيتها في الثني من جنب كافر ... [كذلك أقنو كل قط مضلل] يعني: النهر الكثير الماء. والكفر: الثنايا من الجبال، قال أمية 4 : وليس يبقى لوجه الله مختلق ... إلا السماء وإلا الأرض والكفر والكفارة: ما يكفر به من الخطيئة واليمين فيمحى به. والكافور: كم العنب قبل أن ينور، قال 1 : كالكرم إذ نادى من الكافور وكافوره: ورقة الذي يستره. والكافور: شيء من أخلاط الطيب. والكافور: عين ماء في الجنة. والكافور: نبات نوره كنور الأقحوان. والكافور: الطلع. وإذا أنثوا قالوا: الكفرى. والجميع: الكوافير، يخرج من النخل كأنه نعلان مطبقان، والحمل بينهما منضود، والطرف محدد. ومنهم من يقول: هذه كفراة واحدة، وهذه كفرى واحدة، لا ينون. والكفر: عصا قصيرة. ورجل كفرين عفرين: عفريت خبيث. ورجل مكفر: محسان لا تشكر نعمه. ويقال: مكفور بك يا فلان عنيت وآذيت، يقال للرجل تأمره فيعمل [على] غير ما تأمر.'),
(2055, 'فكر', 'فكر', 'فكر', 'الفكر: اسم التفكر. فكر في أمره وتفكر. ورجل فكير: كثير التفكر. والفكرة والفكر واحد.'),
(2056, 'فرك', 'فرك', 'فرك', 'الفرك: دلكك شيئا حتى ينقشر عن لبه كالجوز. والفرك: المتفرك قشره. وأفرك البر، أي: اشتد في سنبله، قال 1 : أمكنك الفرك ولا يبيس وبر فريك [وهو الذي فرك ونقي] 2 . وامرأة فارك، وجمعها فوارك: تبغض زوجها، فركته وفركته، لغتان. وفركه: بغضه ورجل مفرك: تبغضه النساء [ويقال للرجل أيضا: فركها فركا، أي: أبغضها] 3 قال رؤبة: 4 ولم يضعها بين فرك وعشق وإذا زالت الوابلة عن صدفة الكتف فاسترخى المنكب قيل: قد انفرك منكبه، وانفركت وابلته، وإن كان مثله في الفخذ قيل: حرق الرجل فهو محروق، وحرقت حارقته، وذلك إذا أصابه انخلاع في وابلته. والوابلة: العظم المفلك الرأس، وهو المدخل في حق الورك، والحارقة: العصبة 5 التي تمسك الوابلة في الصدفة.'),
(2057, 'كرب', 'كرب', 'كرب', 'الكرب، مجزوم، [هو] الغم الذي يأخذ بالنفس. [يقال] : كربه أمر، وإنه لمكروب النفس. والكربة: الاسم، والكريب: المكروب. وأمر كارب. والكروب: مصدر كرب يكرب. وكل شيء داني أمرا فقد كرب، [يقال] : كربت الشمس أن تغيب، و [كربت] الجارية أن تدرك، وكرب الأمر أن يقطع. والكرب: الكرناف، وهو أصل السعفة، قال جرير 1 : [أقول ولم أملك سوابق عبرة] ... متى كان حكم الله في كرب النخل والكرب: عقد غليظ في رشاء الدلو إذا جعل طرفه في عروة العرقرة، ثني ثم لف على ثنائه رباط وثيق، فاسم ذلك الموضع: الكرب. والإكراب: الفعل من ذلك، قال 2 : يملأ الدلو إلى عقد الكرب ويقال ذلك في كل عقد. ويقال: خذ رجلك بإكراب، أي: اعجل بالذهاب، وأسرع. وقد يقال: أكرب الرجل فهو مكرب، أي: أخذ رجليه بإكراب، وقلما يقال والكراب: كربك الأرض حتى تقلبها فهي مكروبة مثارة. ومثل: الكراب على البقر، لأنها تكرب الأرض. ويقال: الكلاب على البقر، نصب، مأخوذ من صيدهم البقر الوحشية بالكلاب، معناه: ينبغي لصاحب الأمر أن يقوم به.'),
(2058, 'كبر', 'كبر', 'كبر', 'الكبر: طبل له وجه بلغة أهل الكوفة. والكبر: الإثم الكبير من الكبيرة، كالخطء من الخطيئة. والكبر: أكبر ولد الرجل، ويجمع: أكابر. وكبر كل شيء: عظمه. وقوله عز وجل: والذي تولى كبره 1 . يعني عظم هذا القذف. ومن قرأ 2 : كبره يعني: إثمه وخطأه. قال علقمة 3 : بدت سوابق من أولاه نعرفها ... وكبره في سواد الليل مستور والكبار: الكبير، قال الله تعالى: ومكروا مكرا كبارا 4 . والكبرة: السن، يقال: علته كبرة. والكبر: رفعه في الشرف، قال المدار بن منقذ 5 : ولي الأعظم من سلافها ... ولي الهامة فيها والكبر يعني سلاف عشيرته. والكبرياء: اسم للتكبر والعظمة. والكبر: مصدر الكبير في السن من الناس والدواب. فإذا أردت الأمر العظيم قلت: كبر علينا كبارة. والكبار في معنى الكبير، قال 1 : إذا ركب الناس أمرا كبارا وتقول: ورثوا المجد كابرا عن كابر، أي: كبيرا عن كبير في الشرف والعز. وكابرني فكبرته، أي: غلبته. والملوك الأكابر جمع الأكبر. لا يجوز النكرة، لأنه ليس بنعت إنما هو تعجب، ولأنك لا تقول: رجل أكبر حتى تقول: من فلان. وكبيرة من الكبائر، يعني الذنوب التي توجب لأهلها النار. ويقال للسهم والنصل العتيق الذي أفسده الوسخ: قد علته كبرة، قال الطرماح 2 : سلاجم يثرب اللاتي علتها ... بيثرب كبرة بعد الجرون أي: بعد اللين.. يصف السهام.'),
(2059, 'ركب', 'ركب', 'ركب', 'ركب (فلان فلانا) يركبه ركبا، إذا قبض على فودي شعره، ثم ضربه على جبهته بركبتيه. وركبة البعير في يده، وقد يقال لذوات الأربع كلها من الدواب: ركب. وركبتا يدي 3 البعير: المفصلان اللذان يليان البطن إذا برك. وأما المفصلان الناتئان من خلف فهما العرقوبان. والركبة: ضرب من الركوب، وإنه لحسن الركبة، وركب فلان فلانا بأمر، وارتكبه، وكل شيء علا شيئا فقد ركبه، وركبه الدين ونحوه. ورواكب الشحم: طرائق بعضها فوق بعض في مقدم السنام، فأما الذي في المؤخر فهو الروادف، الواحدة: راكبة ورادفة. والركابة: شبه فسيلة يخرج في أعلى النخلة عند قمتها ربما حملت مع أمها، وإذا قلعت كان أفضل للأم، ويقال: إنما هو راكوبة. والراكوب: ما ينبت في جذوع النخل، ليس له في الأرض عروق، والجميع: الرواكيب. وركاب السفينة: الذين يركبونها. وأما الركبان والأركوب، والركب فراكبو الدابة. وارتكبت الناقة البو، أي: رئمته، ونوق مرتكبات. والركوب: الذلول من المراكب. والركيب: ما بين نهري الكرم، وهو الظهر الذي بين النهرين. والركيب: اسم للمركب في الشيء، مثل: الفص ونحوه، لأن المفعل والمفعل، والمفعول كله يرد إلى فعيل، يقال: ثوب مجدد جديد، ورجل مطلق طليق، ومقتول قتيل. والمركب: الدابة، وهو المصدر وموضع الركوب أيضا. والمركب: الذي يغزو على فرس غيره. والمركب: المثبت في الشيء، كتركيب الفصوص. رجل كريم المركب، أي: كريم أصل منصبه في قومه. والركوب والركوبة: اسم ما يركب، كالحمول والحمولة، ويكون كالحلوبة اسما للواحد والجميع، وقول رؤبة في مطالع النجوم 1 : وراكب المقدار والرديف يعني بالراكب: الطالع، وبالرديف: الناظر من النجوم. يريد: راكب لما أمامه من النجوم. والدبران وركاب للثريا، لأنه رديفها. وركاب السرج، والجميع: الركب. والركاب: الإبل التي تحمل القوم، أو أريد الحمل عليها ... جماعة، لا يفرد. والرياح ركاب السحاب في قول أمية 1 : تردد والرياح لها ركاب والأركاب للنساء خاصة.'),
(2060, 'بكر', 'بكر', 'بكر', 'البكر من الإبل: ما لم يبزل بعد، والأنثى بكرة، فإذا بزلا جميعا فجمل وناقة. والبكرة والبكرة، لغتان: التي يسقى عليها، وهي خشبة مستديرة في وسطها محز للحبل، وفي جوفها محور تدور عليه. والقعو: الخشبة التي تعلق عليها البكرة. والبكرات: الحلق التي في حلية السيف كأنها فتوخ النساء. والبكر: التي لم تمس من النساء بعد. والبكر: أول ولد الرجل غلاما كان أو جارية. و (يقال) : أشد الناس بكر ابن بكرين، والثني: ما يكون بعد البكر، (يقال) : ما هذا الأمر منك بكرا ولا ثنيا، أي: ما هو بأول ولا ثان. والبكر من كل شيء: أوله. وبقرة بكر 2 ، أي: فتية لم تحمل. وابتكر الرجل المرأة، أي: أخذ قضتها. وبكر في حاجته، وبكر وأبكر: واحد. وبنو بكر: إخوة بني ثعلب بن وائل. وبنو بكر بن عبد مناة بن كنانة، (وإذا نسب إليهما قالوا: بكري) 1 . والبكر: جمع البكرة وهي الغداة. والتبكير والبكور والابتكار: المضي في ذلك الوقت. والإبكار: السيرورة فيه. والإبكار: مصدر للبكرة، كالإصباح للصبح. وباكرت الشيء، أي: بكرت له. والباكور: المبكر في الإدراك من كل شيء، والأنثى: باكورة. وغيث باكور وهو المبكر في أول الوسمي. وهو الساري في آخر الليل وأول النهار، وجمعه: بكر، قال 2 : (جرر السيل بها عثنونه) ... وتهادتها مداليج بكر وسحابة مدلاج، أي: بكور. وأتيته باكرا، فمن جعل الباكر نعتا قال للأنثى: باكرة، جاءته باكرة. وقول الفرزدق 3 : (إذا هن ساقطن الحديث كأنه ... جنى النخل، أو] أبكار كرم تقطف واحدها: بكر، وهو الكرم الذي حمل أول حمله 4 . وأبكار كرم يعني: العنب. وعسل أبكار يعسله أبكار النحل، أي: أفتاؤها 1 ، ويقال: بل الأبكار من الجواري تلينه.'),
(2061, 'ربك', 'ربك', 'ربك', 'الربك: إصلاح الثريد. والربك: إلقاؤك إنسانا في الوحل، فيرتبك فيه، ولا يستطيع الخروج منه. والصيد يرتبك في الحبالة، [إذا نشب فيها] وارتبك الرجل في كلامه: تتعتع فيه، وصلى أعرابي خلف ابن مسعود فتتعتع في قراءته، فقال: ارتبك الشيخ، فقال حين فرغ: يا أعرابي! إنه والله ما من نسجك، ولا من نسج أبيك، ولكنه عزيز من عند عزيز نزل. والربك: أن تربك السويق، أو الدقيق بالسمن، أو بالزيت، أي: تخوضه 2 به، واسم الذي ربك: الربيكة. ومن أمثالهم: قد جاء غرثان فاربكوا له.'),
(2062, 'برك', 'برك', 'برك', 'البرك: الإبل البوارك 3 ، اسم لجماعتها. قال طرفة 4 : وبرك هجود قد أثارت مخافتي ... [نواديها أمشي بعضب مجرد] وأبركت الناقة فبركت. والبرك: كلكل البعير وصدره الذي يدوك به الشيء تحته، يقال: حكه ودكه [ببركه] 1 . قال 2 : فأقعصتهم وحكت بركها بهم ... وأعطت النهب هيان بن بيان والبركة: ما ولي الأرض من جلد البطن وما يليه من الصدر من كل دابة. اشتق من مبرك البعير، لأنه يبرك عليه. والبركة والبرك: شبه حوض يحفر في الأرض [ولا] 3 يجعل له أعضاد فوق صعيد الأرض، قال 4 : وأنت التي كلفتني البرك شاتيا ... وأوردتنيه فانظري أي مورد والبركة: حلبة الغداة، ويقال بفتح الراء، قال الكميت: ذو بركة لم تغض قيدا تشيع به ... من الأفاويق في أحيانها الوظب 5 والبركة، والبرك جمعه: من طير الماء، أبيض. وابترك الرجل في الآخر يقصبه، إذا اجتهد في ذمه. وابتركوا في الحرب: جثوا على الركب ثم اقتتلوا [ابتراكا] ، والبراكاء: الاسم منه. قال 6 : ولا ينجي من الغمرات إلا ... براكاء القتال أو الفرار وابترك السحاب: ألح بالمطر على موضع. والبركة: الزيادة والنماء 1 . والتبريك: الدعاء بالبركة. والمباركة: مصدر بورك فيه، وتبارك الله: تمجيد وتجليل. والبركان، والواحدة بركانة: من دق الشجر. وسميت الشاة الحلوب بركة. وفي الحديث: من كان عنده شاة كانت بركة، والشاتان بركتان.'),
(2063, 'كرم', 'كرم', 'كرم', 'الكرم: شرف الرجل. رجل كريم وقوم كرم وكرام، نحو أديم وأدم، [وعمود وعمد] ، وكثر ما يجيء فعل في جمع فعيل وفعول، قال الشاعر 2 : [وأن يعدين إن كسي الجواري] ... فتنبو العين عن كرم عجاف ورجل كرام، أي: كريم. وتكرم [عن الشائنات] ، أي: تنزه، وأكرم نفسه عنها ورفعها. والكرامة: طبق يوضع على رأس الحب. والكرامة: اسم للإكرام، مثل الطاعة للإطاعة ونحوه من المصادر. والمكرمان: الكريم، [نقيض] 3 الملامان. وكرم كرما، أي: صار كريما. والكرم: القلادة. والكرمة: طاقة من الكرم، قال أبو محجن الثقفي 1 : إذا مت فادفني إلى أصل كرمة ... تروي عظامي بعد موتي عروقها و [العرب] تقول: هذه البلدة إنما هي كرمة ونخلة، يعني بذلك الكثرة. والعرب تقول: هي أكثر الأرض سمنة وعسلة. وإذا جاد السحاب بغيثه قيل: كرم. وكرم فلان علينا كرامة. والكرم: أرض مثارة منقاة من الحجارة. قال الضرير: يقال: أكرمت فاربط، أي: استفدت كريما فارتبطه 2 .'),
(2064, 'كمر', 'كمر', 'كمر', 'الكمر: جماعة الكمرة.'),
(2065, 'ركم', 'ركم', 'ركم', 'الركم: جمعك شيئا فوق شيء، حتى تجعله ركاما مركوما كركام الرمل والسحاب ونحوه من الشيء المرتكم بعضه على بعض، قال الله عز وجل: فيركمه جميعا 3 وثم يجعله ركاما 4 .'),
(2066, 'مكر', 'مكر', 'مكر', 'المكر: احتيال [في خفية] 1 ، والمكر: احتيال بغير ما يضمر، والاحتيال بغير ما يبدي هو الكيد، والكيد في الحرب حلال، والمكر في كل حال حرام. والمكر: ضرب من النبات، الواحدة: مكرة، وسميت (لارتوائها) 2 وأما مكور الأغصان فهي شجرة على حدة، وضروب من الشجر تسمى المكور، مثل الرغل ونحوه. والمكر: حسن خدالة الساق، فهي مرتوية خدلة، [شبهت بالمكر من النبات] 3 ، كما قال 4 : عجزاء ممكورة خمصانة (قلق) ورجل مكورى، أي: قصير، عريض، لئيم الخلقة، يقال: يا ابن مكورى، وهو في هذا القول: قذف كأنما توصف بزنية 5 . والمكر: المغرة.'),
(2067, 'رمك', 'رمك', 'رمك', 'الرمكة: الفرس والبرذونة تتخذ للنسل، والجميع: الرمك والأرماك. والرامك: شيء أسود كالقار يخلط بالمسك فيجعل سكا، قال 6 : إن لك الفصل على صحبتي ... والمسك قد يستصحب الرامكا والرمكة: لون في ورقة وسواد، من ألوان الإبل. والنعت: أرمك ورمكاء.'),
(2068, 'لكن', 'لكن', 'لكن', 'اللكنة: عجمة الألكن، وهو الذي يؤنث المذكر، ويذكر المؤنث، ويقال: هو الذي لا يقيم عربيته، لعجمة غالبة على لسانه، وهو الألكن 1 .'),
(2069, 'نكل', 'نكل', 'نكل', 'النكل والنكل: ضرب من اللجم والقيود، وكل شيء ينكل به غيره فهو نكل، قال 2 : عهدت أبا عمران فيه نهاكة ... وفي السيف نكل للعصا غير أعزل ونكل ينكل: تميميه، ونكل حجازية. يقال: نكل الرجل عن صاحبه إذا جبن عنه، قال 3 : ضربا بكفي بطل لم ينكل أي: لم ينكل عن صاحبه. ونكل عن اليمين: حاد عنه، والنكول عن اليمين: الامتناع منها. والنكال: اسم لما جعلته نكالا لغيره، إذا بلغه، أو رآه خاف أن يعمل عمله.'),
(2070, 'نلك', 'نلك', 'نلك', 'النلك: شجرة الدب، الواحدة: نلكة، وهي شجرة حملها زعرور أصفر.'),
(2071, 'كلف', 'كلف', 'كلف', 'كلف وجهه يكلف كلفا. وبعير أكلف، وبه كلفة، كل هذا في الوجه خاصة، وهو لون يعلو الجلد فيغير بشرته. وبعير أكلف: يكون في خديه سواد خفي. والكلف: الإيلاع بالشيء، كلف بهذا الأمر، وبهذه الجارية فهو بها كلف ومكلف. وكلفت هذا الأمر وتكلفته. والكلفة: ما تكلفت من أمر في نائبه أو حق، والجميع: الكلف. وفلان يتكلف لاخوانه الكلف، والتكاليف، قال زهير 1 : سئمت تكاليف الحياة ومن يعش ... ثمانين حولا لا أبا لك يسأم والمكلف: الوقاع فيما لا يعنيه.'),
(2072, 'كفل', 'كفل', 'كفل', 'الكفل: ردف العجز، وإنها لعجزاء الكفل، والجميع: أكفال، لا يشتق منه فعل ولا نعت، لا يقال: كفلاء، كما يقال: عجزاء. والكفل: النصيب، والكفل: شيء مستدير يتخذ من خرق أو غير ذلك، يوضع على 1 سنام البعير. تقول: اكتفل الرجل بكفل من كذا، أو من ثوبه. والكفل من الأجر، ومن الإثم: الضعف، قال الله عز وجل: يؤتكم كفلين من رحمته 2 ويكن له كفل منها 3 ، ولا يقال: هذا كفل فلان حتى تكون قد هيأت مثله لغيره كالنصيب، فإذا أفردت فلا تقل: كفل ولا نصيب. والكفل: الرجل الذي يكون في مؤخر الحرب، إنما همته التأخر [والفرار] 4 ، وهو بين الكفولة. والكفيل: الضامن للشيء. كفل به يكفل به كفالة. والكافل: الذي يكفل إنسانا يعوله وينفق عليه. وفي الحديث: الربيب كافل 5 ، وهو زوج أم اليتيم. وقوله عز اسمه: وكفلها زكريا ، [أي] : هو كفل مريم لينفق عليها، حيث ساهموا على نفقتها حين مات أبواها فبقيت بلا كافل. ومن قرأ بالتثقيل فمعناه: كفلها الله زكريا. وكفل الشيطان: مركبه. أخذ من [قولهم] : اكتفل الرجل يكتفل، وفي الحديث: لا يشربن أحدكم من ثلمة الإناء ولا عروته، فإنها كفل الشيطان 1 . والمكافلة: مواصلة الصيام.'),
(2073, 'فكل', 'فكل', 'فكل', 'الأفكل: رعدة تعلو الإنسان، ولا فعل له. ويجمع: أفاكل.'),
(2074, 'فلك', 'فلك', 'فلك', 'الفلك: دوران السماء. [وهو] اسم للدوران خاصة. والمنجم يقول: الفلك سبعة أطواق دون السماء، ركبت فيها النجوم السبعة، في كل طوق نجم، وبعضها أرفع من بعض تدور فيها بإذن الله. والفلك: السفينة، يذكر ويؤنث [وهي واحدة، وتكون جمعا] 2 . قال الله عز وجل: جاءتها ريح عاصف 3 وقال: فأنجيناه ومن معه في الفلك المشحون 4 ، أي: الموقر المفروغ من جهازه. والفلك: جماعة السفن، [حتى إذا كنتم في الفلك وجرين بهم 5 ] . وفلكت الجارية، أي: تفلك ثديها [أي: صار كالفلكة] 6 فهي مفلكة، ومفلك أجود، قال 7 : لم يعد ثديا نحرها أن تفلكا وفلكت الجدي، وهو قضيب يدار على لسانه لئلا يرضع. والفلكة: أكمة من حجر واحد مستديرة كأنها فلكة مغزل، والجميع: الفلك والفلكات، وهو على تقدير النبكة في الخلقة، إلا أن النبكة أشد تحديد رأس من الفلكة، وربما كانت النبكة من طين وحجارة رخوة.'),
(2075, 'كلب', 'كلب', 'كلب', 'الكلب: [واحد الكلاب] ، والأنثى بالهاء وثلاثة أكلب وكلبات. والذئب: كلب البر، ويقال: أنست الكلاب بابن آدم فاستعان بها على الذئاب. والكليب: جمع الكلاب، كالحمير والبقير. والكلاب والمكلب: الذي يعلم الكلاب الصيد. وكلب كلب: يكلب بأكل لحوم الناس، فيأخذه شبه جنون، فلا يعض إنسانا إلا كلب، أي: أصابه داء يسمى الكلب، أن يعوي عواء الكلب، ويمزق ثيابه على نفسه، ويعقر من أصاب، ثم يصير آخر أمره إلى أن يأخذه العطاش فيموت من شدة العطش ولا يشرب. ويقال: دواؤه شيء من ذراريح يجفف في الظل، ثم يدق وينخل، ثم يجعل فيه جزء من العدس المنقى سبعة أجزاء، ثم يداف بشراب صرف، ثم يرفع في جرة خضراء، أو قارورة، فإذا أصابه ذلك سقي منه قيراطين، إن كان قويا، وإلا فقيراط بشراب صرف، ثم يقام في الشمس، ولا تدعه ينام حتى يغتم ويعرق، يفعل به مرارا فيبرأ بإذن الله. قال الفرزدق 1 : ولو تشرب الكلبى المراض دماءنا ... شفتها، وذو الداء الذي هو أدنف والواحد: كليب، يقال: رجل كليب، وقوم كلبى: أصابهم الكلب. ورجل كلب، وقد كلب كلبا، إذا اشتد حرصه على الشيء. قال الحسن: إن الدنيا لما فتحت على أهلها كلبوا عليها والله أسوأ الكلب [وعدا بعضهم على بعض بالسيف] 2 . ودهر كلب: ألح على أهله بما يسوؤهم. وشجرة كلبة هي شجرة عاردة الأغصان والشوك اليابس، مقشعرة. والكلاب والكلوب: عصا في رأسها عقافة منها أو من حديد، أو كانت كلها من حديد. والكلبتان 3 للحدادين. وكلاليب البازي: مخالبه. والكلب: المسمار الذي في قائم السيف. الذي فيه الذؤابة. وكلبة الشتاء وكلبته وكلبه، أي: شدته، وكذلك كلب الزمان. وكلب الماء: دابة. والكلب من النجوم بحذاء الدلو من أسفل، وعلى طريقته نجم أحمر يقال له: الراعي. والكلب: [سير] 1 يجعل بين طرفي الأديم إذا خرز، كلب يكلب كلبا، قال 2 . كأن غر متنه إذ نجنبه ... سير صناع في خريز تكلبه والكلب: الخرز بعينه، والكلبة: الخرزة.'),
(2076, 'كبل', 'كبل', 'كبل', 'الكبل: قيد ضخم.'),
(2077, 'بكل', 'بكل', 'بكل', 'البكيل: مسوط الأقط، لأنه يبكله، أي: يخلطه. ورجل بكيل، في بعض اللغات، أي: متنوق في لبسه ومشيه. والتبكل: الاختيال. والتبكل: التربص ببيع ما عنده.'),
(2078, 'لبك', 'لبك', 'لبك', 'اللبك: جمعك الثريد لتأكله. والتبك الأمر، أي: اختلط والتبس، وأمر لبك، أي: ملتبس، قال 3 : [رد القيان جمال الحي فاحتملوا] ... إلى الظهيرة أمر بينهم لبك ويقال: ما ذقت عنده عبكة ولا لبكة. العبكة: الحبة من السويق، واللبكة: القطعة من الثريد.'),
(2079, 'كلم', 'كلم', 'كلم', 'الكلم: الجرح، والجميع: الكلوم. كلمته أكلمه كلما، وأنا كالم، [وهو مكلوم] 1 . أي: جرحته. وكليمك: الذي يكلمك وتكلمه. والكلمة: لغة حجازية، والكلمة: تميمية، والجميع: الكلم والكلم، هكذا حكي عن رؤبة 2 : لا يسمع الركب به رجع الكلم'),
(2080, 'كمل', 'كمل', 'كمل', 'كمل الشيء يكمل كمالا، [ولغة أخرى: كمل يكمل فهو كامل في اللغتين] 3 . والكمال: التمام الذي يجزأ منه أجزاؤه، تقول: لك نصفه وبعضه وكماله. وأكملت الشيء: أجملته وأتممته. وكامل: اسم فرس سابق كان لبني امرىء القيس. و [تقول] : أعطيته المال كملا، هكذا يتكلم به، في الواحد والجمع سواء، ليس بمصدر ولا نعت، إنما هو كقولك: أعطيته كله، ويجوز للشاعر أن يجعل الكامل كميلا، قال ابن مرداس 1 : على أنني بعد ما قد مضى ... ثلاثون للهجر حولا كميلا'),
(2081, 'لكم', 'لكم', 'لكم', 'اللكم: اللكز في الصدر.. لكمته ألكمه لكما. والملكمة: القرصة المضروبة باليد. والتلكيم: شيء يفعله خولان بن عمرو بن قضاعة، ومنازلهم من مكة على ثلاث. بلغ من برهم بالضيف أن يخلوا معه البكر فتضاجعه، ويبيحون له ما دون الفضة. يسمون ذلك التلكيم، فإذا وافقها قالت لأهلها: أنا أشاؤه فيزوجونها، وقد لكمها قبل.'),
(2082, 'لمك', 'لمك', 'لمك', 'نوح بن لمك، ويقال: ابن لامك بن اخنوخ، وهو إدريس النبي ع. واللماك: الكحل.'),
(2083, 'مكل', 'مكل', 'مكل', 'مكلت البئر: كثر ماؤها، واجتمع في وسطها. وبئر مكول، أي: قد جم الماء فيها، قال 2 : سمح المؤتى أصبحت مواكلا المكلة: المجتمع من الماء. ويقال: مكلت البئر، أي: نزحتها 1 .'),
(2084, 'ملك', 'ملك', 'ملك', 'الملك لله المالك المليك. والملكوت: ملك الله، [وملكوت الله: سلطانه] 2 . والملك: ما ملكت اليد من مال وخول. والمملكة: سلطان الملك في رعيته، يقال: طالت مملكته، وعظم ملكه وكبر. والمملوك: العبد أقر بالملوكة، والعبد أقر بالعبودة. وأصوبه [أن يقال] : أقر بالملكة وبالملك. وملاك الأمر: ما يعتمد عليه. والقلب ملاك الجسد. والإملاك: التزويج.. قد أملكوه وملكوه، أي: زوجوه، شبه العروس بالملك، قال 3 : كاد العروس أن يكون ملكا والملك [واحد] 4 الملائكة، إنما هو تخفيف الملأك 5 ، والأصل مألك، فقدموا اللام وأخروا الهمزة، فقالوا: ملأك، وهو مفعل من الألوك وهو الرسالة، واجتمعوا على حذف همزته كهمزة يرى وقد يتمونه في الشعر عند الحاجة، قال 1 : فلست لإنسي ولكن لملأك ... تبارك من فوق السماوات مرسله [وتمام تفسيره في معتلات حرف الكاف] .'),
(2085, 'كنف', 'كنف', 'كنف', 'الكنفان: الجناحان، قال 2 : [عنس مذكرة كأن عفاءها] ... سقطان من كنفي نعام جافل وكنفا الإنسان: جانباه، [وناحيتا كل شيء: كنفاه] 3 . ويقال: كنفه الله، أي: رعاه وحفظه. وهو في حفظ الله وكنفه، أي: حرزه [وظله، يكنفه بالكلاءة وحسن الولاية] 4 . والكنف: وعاء طويل لأسقاط التجار ونحوه. وقالوا: الكنف: الزنفليجة 5 . وقال عمر لابن مسعود: كنيف ملىء علما. وناقة كنوف: وهي التي تكتنف في [أكناف] 1 الإبل من البرد، أي: تستتر. واشتقاق الكنيف كأنه كنف في أستر النواحي. وأكناف الجبل أو الوادي: نواحيه، حيث تنضم إليه. الواحد: كنف. ويقال للإنسان المخذول: لا تكنفه من الله كانفة. [أي: لا تحجزه] 2 . وتكنفوه من كل جانب، أي: احتوشوه. والإكناف: الإعانة.. أكنفته: أعنته.'),
(2086, 'كفن', 'كفن', 'كفن', 'كفن الرجل يكفن، أي: يغزل الصوف، قال 3 : يظل في الشتاء يرعاها ويعمتها ... ويكفن الدهر إلا ريث يهتبد وخالف أبو الدقيش في هذا البيت بعينه. فقال: بل يكفن: يختلي الكفنة للمراضيع من الشاء. والكفنة: شجرة من دق الشجر، صغيرة جعدة، إذا يبست صلبت عيدانها، كأنها قطع شققت عن 4 القنا. وكفنت الميت، وكفنته، فهو مكفن مكفون.'),
(2087, 'نكف', 'نكف', 'نكف', 'النكف: تنحيتك الدموع بإصبعك عن خدك، قال 1 : فبانوا ولولا ما تذكر منهم ... من الخلف لم ينكف لعينك مدمع ودرهم منكوف، أي: بهرج رديء. والنكف: الاستنكاف. والاستنكاف عند العامة: الأنف. وإنما هو الامتناع، والانقباض عن الشيء حمية وعزة. والنكفة: ما بين اللحيين والعنق من جانبي الحلقوم من قدم من ظاهر وباطن.'),
(2088, 'نفك', 'نفك', 'نفك', 'النفك: لغة في النكف.'),
(2089, 'فكن', 'فكن', 'فكن', 'التفكن: التلهف على حاجة، أنه يظفر بها ففاتته. قال 2 : أما جزاء العارف المستيقن ... عندك إلا حاجة التفكن'),
(2090, 'فنك', 'فنك', 'فنك', 'فنك يفنك فنوكا، إذا لزم مكانه لا يبرح. والفنيكان: عظمان ملزقان في الحمامة إذا كسر لم يستمسك بيضها في بطنها حتى تخدجه. والفنيكان من لحي كل ذي لحيين: الطرفان اللذان يتحركان من الماضغ، دون الصدغين. ومن جعل الفنيك واحدا للإنسان فهو مجمع اللحيين في وسط الذقن. وفي الحديث: أمرني جبريل أن أتعاهد فنيكي بالماء عند الوضوء 1 .'),
(2091, 'كنب', 'كنب', 'كنب', 'الكنب: غلظ يعلو اليد، إذا مجلت من العمل وصلبت قيل: قد أكنبت يده، قال 2 : قد أكنبت يداك بعد لين ... وهمتا بالصبر والمرون وقال 3 : وأكنبت نسوره وأكنبا'),
(2092, 'كبن', 'كبن', 'كبن', 'الكبن: عدو لين في استرسال، كبن يكبن كبونا وكبنا فهو كابن، قال 4 : يمر وهو كابن حيي وكبنت الثوب، وخبنته مثله.'),
(2093, 'نكب', 'نكب', 'نكب', 'النكب: شبه ميل. وإنه لمنكاب عن الحق، قال 1 : ... عن الحق أنكب أي: مائل عنه. والأنكب من الإبل كأنما يمشي في شق واحد. قال 2 : أنكب زياف وما فيه نكب والنكب: اجتنابك الشيء. تنتكب عنه وتنكب عنه. وانتكبت الكنانة: ألقيتها في منكبي. والمنكب: كل ناحية من الجبال أو الأرض. ومنكب القوم: رأس العرفاء على كذا وكذا عريفا [ورتبته النكابة] 3 ، تقول: له النكابة في قومه. والنكباء: ريح تهب بين ريحين. والمنكب: مجمع عظم العضد والكتف، وحبل العاتق من الإنسان والطائر ونحوه. والنكب: أن ينكب الحجر ظفرا أو حافرا أو منسما. يقال: منسم منكوب ونكيب. قال لبيد 4 : وتصك المرو لما هجرت ... بنكيب معر دامي الأظل والمصدر: نكب، مجزوم، ونكبته حوادث الدهر، وأصابته نكبة ونكبات ونكوب كثيرة من الدهر.'),
(2094, 'نبك', 'نبك', 'نبك', 'النبكة: أكمة محددة الرأس ربما كانت حمراء لا تخلو من الحجارة.'),
(2095, 'بنك', 'بنك', 'بنك', 'يقال: رده إلى بنكه، أي: أصله. وتبنك [فلان] في عز ومنعة، [أي: تمكن] 1 .'),
(2096, 'كمن', 'كمن', 'كمن', 'كمن فلان يكمن كمونا، أي: اختفى في مكمن لا يفطن له. ولكل حرف مكمن إذا مر به الصوت أثاره. وأمر فيه كمين، أي: فيه دغل لا يفطن له. وناقة كمون، أي: كتوم للقاح، إذا لقحت لم تبشر بذنبها، أي: لم تشل، وإنما يعرف حملها بشولان ذنبها. والكمون: حب أدق 2 من السمسم يستعمل في الهواضم، ويسف مع الفانيذ 3 . والكمنة: جرب وحمرة تبقى في العين من رمد يساء علاجه. فتكمن وهي مكمونة. و [المكتمن: الخافي المضمر] 1 قال الطرماح 2 : عواسف أوساط الجفون يسقنه ... بمكتمن من لاعج الحزن واتن يعني بالعواسف: الدموع، لأنها لا تخرج من [مجاريها] ، إنما تنتشر انتشارا، وذلك [إذا] كثر [الدمع] .'),
(2097, 'مكن', 'مكن', 'مكن', 'المكن و [المكن] : بيض الضب ونحوه.. ضبة مكون، والواحدة: مكنة والمكان في أصل تقدير الفعل: مفعل، لأنه موضع للكينونة، غير أنه لما كثر أجروه في التصريف مجرى الفعال، فقالوا: مكنا له، وقد تمكن، وليس بأعجب من تمسكن من المسكين، والدليل على أن المكان مفعل: أن العرب لا تقول: هو مني مكان كذا وكذا إلا بالنصب.'),
(2098, 'بكم', 'بكم', 'بكم', 'الأبكم: الأخرس [الذي] لا يتكلم. وإذا امتنع [الرجل] من الكلام جهلا أو تعمدا فقد بكم عنه، وقد يقال للذي لا يفصح: إنه لأبكم. و [الأبكم] في التفسير هو الذي ولد أخرس.'),
(2099, 'كوي', 'كوي', 'كوي', 'كويته أكويه كيا، أي: أحرقت جلده بنار أو بحديدة محماة. والمكواة: الحديدة التي يكوى بها، ويقال في المثل: العير يضرط والمكواة في النار. والكو والكوة أيضا، التأنيث للتصغير والتذكير للتكبير: تأليفها من كاف وواوين.. فهي: فعلة، ومنهم من قال: تأليفها من كاف وواو وياء، كأن أصلها: كوي، ثم أدغمت الياء في الواو، فجعلت واوا مشددة، وإذا قلت: كويت في البيت كوة وتكوية فإن الياء لا تدل على أنها في الأصل ياء، لأن كل واو تصير في الفعل رابعة تقلب إلى الياء، كقولك: رجوته ورجيته. وأبو الكواء: من كنى العرب.'),
(2100, 'كيو', 'كيو', 'كيو', 'كيوان: نجم يقال له: زحل. وكاوان: جزيرة في بحر البصرة.'),
(2101, 'وكي', 'وكي', 'وكي', 'الوكاء: رباط القربة.. أوكى يوكي إيكاء. قال الحسن: جمعا في وعاء، وشدا في وكاء. جعل الوكاء هاهنا كالجراب.'),
(2102, 'جش', 'جش', 'جش', 'الجش طحن السويق (والبر إذا لم يجعل دقيقا 1 والجشيش. والمجشة: رحى صغيرة تجش بها الجشيشة ولا يقال للسويق: جشيشة ولكن جذيذة. والجشة والجشة، لغتان،: الجماعة من الناس يقبلون معا في ثورة 2 ، قال العجاج: بجشة جشوا بها ممن نفر 3 وبه جشة، أي: شدة صوت، ورعد أجش، قال لبيد: بأجش الصوت يعبوب، إذا ... طرق الحي من الغزو، صهل قال الخليل: الأصوات التي تصاغ منها الألحان ثلاثة: الأجش صوت من الرأس يخرج من الخياشيم، فيه غلظ وبحة فيتبع بخدر موضوع على ذلك الصوت بعينه يقال له الوشي، ثم يعاد ذلك الصوت بعينه، ثم يتبع بوشي مثل الأول فهي صياغته، فهذا الصوت الأجش. قال زائدة: جشه بالعصا أي ضربه بها. والجش: كنس البئر حتى تخرج حمأتها 1'),
(2103, 'شج', 'شج', 'شج', 'الشج: كسر الرأس، تقول: شج يشج شجا، وبينهم شجاج أي شج بعضهم بعضا. والشجج: أثر شجة في الجبين، والنعت أشج. وشج الفلاة: قطعها. وشج الشراب بالمزاج. والأشج: الطويل. وشجت السفينة البحر إذا قطعته. والعرب تسمي الوتد شجيجا، ومشجوجا. وشججت الفلاة: ركبتها وعلوتها..'),
(2104, 'ضج', 'ضج', 'ضج', 'يقال: هو ضجيج البعير، وضجاج القوم وهو لجبهم، وقد ضج يضج ضجا، قال العجاج: وأغشت الناس الضجاج الأضججا 1 أظهر التضعيف.'),
(2105, 'جض', 'جض', 'جض', 'جض عن الشيء أي حاد عنه، وجاض مثله.'),
(2106, 'جز', 'جز', 'جز', 'الجز جز الشعر والصوف وغيره. والجزز: الصوف الذي لم يستعمل بعد ما جز، وتقول: صوف جزز. والجزاز كالحصاد يقع على الحين والأوان. وأجز النخل مثل أحصد البر. وجزة: اسم أرض، يقال: إن الدجال يخرج منها. والجزاز: ما فضل من الأديم إذا قطع، الواحدة جزازة. وصوف كل شاة جزة. والجزائز: عهون تشد على الهوادج.'),
(2107, 'زج', 'زج', 'زج', 'الزجاج جمع زج الرمح والسهم. والزجاج: أنياب الفحل، قال الراجز: له زجاج وله قوارض 1 ويروى: ولهاة فارض. والزجج: دقة الحاجب واستقواسه أيضا، وزججت المرأة حاجبها بالمزج. وظليم أزج: أي فوق عينيه ريش أبيض، والجميع الزج. والمزج: رمح قصير في أسفله زج. والزج: رميك بالشيء تزج به عن نفسك. ويقال للظليم إذا عدا: زج برجليه. والزجاج والزجاج، لغات،: القوارير (وأقلها الكسر) 1 ، فأما في القرآن فهي القناديل والأزج من النعام: المحدد الزج، وهو منسمه، وسمي أزج لزجه. والزج: جماعة الأزج، وهو البعيد الخطو. والزج: طرف مرفق الإنسان.'),
(2108, 'جد', 'جد', 'جد', 'جد الرجل: بخته، وجد ربنا: عظمته، ويقال: غناه. والجد: نقيض الهزل. وجد فلان في أمره وسيره أي: انكمش عنه بالحقيقة. والجدة: مصدر الجديد، وفلان أجد ثوبا واستجده، قال: 2 يجد ويبلى والمصير إلى بلى والجديد يستوي فيه الذكر والأنثى لأنه مفعول بمعنى مجدد، ويجيء فعيل بمعنى المفعول المخالف للفظ من تصريف المفعل والمفعل. والجدة: جدة النهر أي ما قرب من الأرض. والجدد والجديد: وجه الأرض، قال: حتى إذا ما خر لم يوسد ... إلا جديد الأرض أو ظهر اليد 1 والجديدان: الليل والنهار. وجديدتا السرج: اللبد 2 الذي يلزق بالسرج أو الرحل من الباطن. ويقال: الزم الطريق الجدد. والجدود: كل أنثى يبس لبنها، والجمع الجدائد والجداد، قال: من الحقب لأخته الجداد الغوارز 3 والجداد 4 : صاحب الحانوت الذي يبيع الخمر، قال الأعشى:'),
(2109, 'جذ', 'جذ', 'جذ', 'الجذ: القطع المستأصل الوحي. والجذاذ: قطع ما كسر، الواحدة جذاذة، كما جعلت الأصنام جذاذا وقطع أطرافها فتلك القطع الجذاذ. والجذاذ: قطع الفضة الصغار. والجذيذ: السويق، والجذيدة: الجشيشة إذا اتخذت من السويق الغليظ. وجذذت الحبل فانجذ أي تقطع فهو مجذوذ. وقوله تعالى عطاء غير مجذوذ 1 ، أي غير مقطوع.'),
(2110, 'جث', 'جث', 'جث', 'الجث: قطعك الشيء من أصله، والاجتثاث أوحى منه، واللازم انجث واجتث أيضا 2 وشجرة مجتثة لا أصل لها في الأرض. والمجتث من العروض مستفعلن فاعلات مرتين. ولا يجيء من هذا النحو أنقص منه ولا أطول إلا بالزحاف. والجثجاث من نبات الربيع إذا أحس بالصيف يبس. قال زائدة: هي شجرة لا تزال خضراء في الشتاء والصيف، طيبة الريح، يستاك بعروقها، من مراتع الوحش، قال رؤبة: ترمي ذراعيه بجثجاث السوق 3 والجثة: خلق البدن الجسيم. وجثثت منه وجئثت، ورجل مجثوث ومجؤوث أي قد جث يعني أفزع.'),
(2111, 'ثج', 'ثج', 'ثج', 'الثج: شدة انصباب المطر والدم، ومطر ثجاج.'),
(2112, 'جر', 'جر', 'جر', 'الجرة وجمعها الجرار والجر، والجرارة حرفة الجرار. والجرارة: عقرب صفراء كأنها تبنة. والجارور: نهر يشقه السيل فيتخذة نهرا 1 والجارور: كل مكان ينحط إليه الماء من عل وهو في سفل كأنه يجر إليه الماء. والجرور من الحوامل: التي تجر ولدها إلى أقصى الغاية، قال: جرت تماما لم تخبط جهضا 2 وطعنت فارسا فأجررته الرمح إذا مشى به. وربما شق وسط لسان الجدي أو الفصيل ثم يشد فيه خشبة كي لا يرضع، ويسمى ذلك التقليد الإجرار، وجر الفصيل فهو مجرور، وأجر: أنزل به ذلك، قال: فلو أن جرما أنطقتني رماحهم ... نطقت ولكن الرماح أجرت 1 والمجرة: شرج السماء، قال: لمن طلل بين المجرة والقمر ... خلاء من الأصوات عاف من الأثر 2 والمجر: الجر. وكان عاما أول كذا فهلم جرا إلى اليوم. والرجل يجر على نفسه جريرة أي جناية، وتجمع على جرائر. وتقول في معنى من أجلك: من جريرك، ومن جراك، قال أبو النجم: فاضت دموع العين من جراها 3 والجرة جرة البعير حين يجترها فيقرضها ثم يكظمها. والجرجرة: تردد هدير البعير في حنجرته وشقشقته ثم يخرجه فيهدر، قال: جرجر في حنجرة كالحب 1 والجرجير: نبات من أحرار البقول. والجرجار: نبات. والجرجر: ما يداس به الكدس من حديد. والتجرجر: صبك الماء في حلقك. والجرور: الفرس الذي لا ينقاد. والجرير: حبل الزمام. والجرجور: مائة من الإبل، ويقال: مائة جرجور كما يقال: مائة كاملة، قال الكميت: ومقل أسقتموه فأثرى ... مائة من عطائكم جرجورا 2 ويقال: الجرجور الكرام كقول الأعشى: يهب الجلة الجراجر كالبستان ... تحنو لدردق أطفال 3 والجر: المكان الصلب الذي قد انحدر عن أن يكون طينا فهو يحتش (كذا) أي ينشف، قال: ونؤيا كحوض الجر لم يتثلم 1'),
(2113, 'رج', 'رج', 'رج', 'الرج: تحريكك شيئا كحائط دككته، ومنه الرجرجة. وكتيبة رجراجة: يترجرج عليها الحديد. وامرأة رجراجة: يترجرج عليها كفلها ولحمها. والارتجاج: مطاوعة الرج، وهو أن تزلزل زلزالا شديدا. وارتج الظلام: التبس. والرجرج: نعت للشيء يترجرج. والرجرج: الثريدة الملينة المكتنزة. والرجراج 2 : شيء من الأدوية. والرجرج 3 : ماء القريس. والرجرجة: بقية الماء في الحوض الكدرة المختلطة بالطين. وارتجت البقرة: كرهت الفحل. والرجاج: الضعيف من الناس والإبل ورجرجة من الناس أي سفلة. والرجاج: المهازيل، قال: فهم رجاج وعلى رجاج 1'),
(2114, 'جل', 'جل', 'جل', 'جل في عيني أي عظم، وأجللته أي أعظمته. وكل شيء يدق فجلاله خلاف دقاقه. وجل كل شيء عظمه. وتقول: ما له دق ولا جل. والجل: سوق الزرع إذا حصد عنه 2 السنبل. والجلة: وعاء التمر، من خوص. وجل الدابة معروف. وجلال كل شيء: غطاؤه. كالحجلة وشبهها، وهو واحد والجمع أجلة. والتجلجل: السؤوخ في الأرض والتحرك والجولان، وحركة الريح وتجلجلها 1 . وجل وجلان: حيان من العرب. وإبل جلالة أي تأكل العذرة، كره لحمها ولبنها حتى الانتفاع بظهرها وكذلك من الأنعام. والجلة البعر، وهو يجتله أي يلتقطه. وناقة تجل عن (الكلال أي أجل من أن تكل لصلابتها) 2 . وناقة جلالة وجمل جلال: ضخم، مخرج من فعيل. وحمل جلاجل: صافي النهيق. والجلة: العظام من الإبل والمعز ونحوه. والجلجلان: ثمر الكزبرة. والجلجلة: تحريك الجلجل، وصوت الرعد. والجليل: الكلأ وهو الثمام، وجمعه الأجلة، قال:'),
(2115, 'جن', 'جن', 'جن', 'الجن: جماعة ولد الجان، وجمعهم الجنة والجنان، سموا به لاستجنانهم من الناس فلا يرون. والجان أبو الجن خلق من نار ثم خلق نسله. والجان: حية بيضاء، قال الله عز وجل- تهتز كأنها جان ولى مدبرا 1 * والمجنة 2 : الجنون، وجن الرجل، وأجنه الله فهو مجنون وهم مجانين. ويقال به: جنة وجنون ومجنة، قال: من الدارميين الذين دماؤهم ... شفاء من الداء المجنة والخبل 3 وأرض مجنة: كثيرة الجن. والجنان: روع القلب، يقال: ما يستقر جنانه من الفزع. وأجنت الحامل الجنين 4 أي الولد في بطنها، وجمعه أجنة وقد جن الولد يجن فيه جنا، قال: حتى إذا ما جن في ماء الرحم 5 ويقال: أجنة الليل وجن عليه الليل (إذا أظلم حتى يستره بظلمته. واستجن فلان إذا استتر بشيء. والمجن: الترس. والجنجن والجناجن: أطراف الأضلاع مما يلي الصدر وعظم القلب. والجنة: الحديقة، وهي بستان ذات شجر ونزهة، وجمعه جنات. والجنة: الدرع، وكل ما وقاك فهو جنتك. والجنن: القبر، وقيل للكفن أيضا لأنه يجن فيه الميت أي يكفن.'),
(2116, 'نج', 'نج', 'نج', 'النجنجة: الجولة عند الفزعة 1 . والأنجوج: ريح طيب. ونجنج إبله: ردها عن الحوض. ونجنج أمره: أي ردد ولم ينفذه، قال العجاج: ونجنجت بالخوف من تنجنجا 2'),
(2117, 'جف', 'جف', 'جف', 'جف يجف ويجف جفوفا. والجف 3 : ضرب من الدلاء، قال: كل عجوز رأسها كالقفه ... تسعى بجف معها هرشفه 1 ويقال: هو الذي يكون بين السقائين يملؤون به المزايد. قال زائدة: الجف الشيء الخلق والشيخ الكبير، وقشر كل شيء جفه. والجف: قيقاءة الطلع، وهو الغشاء الذي يكون على الوليع، وجمعه جفوف، قال: وتبسم عن نير كالوليع ... شقق عنه الرقاة الجفوفا 2 والجفوة والجف 3 : جماعة من الناس. والتجفاف معروف، ويجمع على التجافيف. والتجفاف (بنصب التاء) : مصدر بدل التجفيف، وتقول: جففت التجفاف تجفافا أي تجفيفا. ويقال: اعزل جفافه عن نديه أي ما جف منه. والجفجف: القاع المستدير الواسع (وأنشد: يطوي الفيافي جفجفا فجفجفا) 4'),
(2118, 'فج', 'فج', 'فج', 'الفج: الطريق الواسع في قبل جبل ونحوه، ويجمع فجاجا. والفجج أقبح من الفحج، ورجل أفج. والنعامة تفج إفجاجا إذا رمت بصومها، قال ابن القربة أفج إفجاج النعامة وأجفل إجفال الظليم. وأفج إفجاجا أي أسرح وأفاج لغة. والفجفجة: الصلف'),
(2119, 'جب', 'جب', 'جب', 'الجب: استئصال السنام من أصله، وبعير أجب، قال النابغة: ونأخذ بعده بذناب عيق ... أجب الظهر ليس سنام 1 وجب الخصى: استئصال ما هناك. والجبوب: وجه الأرض الصلبة. والجباب: كهيئة الزبد من ألبان الإبل. والجب: الغلبة. والجباب: جمع الجبة التي تلبس. وتقول: هي جبة السنان أو نحوه أي مدخله. والجبة بياض تطأ فيه الدابة بحافرها 1 حتى تبلغ الأشاعر، والنعت مجبب 2 ، قال: المرار بن منقذ: ببعيد قدره ذي جبب ... سلط السنبك في رسغ عجز 3 وقال: إذا تأملها الراؤون من كثب ... لاحت لهم غرة منها وتجبيب 4 والجب: بئر غير بعيدة القعر، ويجمع على جببة وجباب وأجباب والجبجبة: شيء يتخذ من أدم كهيئة اللقن يسقى منها البعير، وينقع فيها الهبيد. والجباجب: الزبل من الجلود، الواحدة جبجبة. والجبجبة: كرش يجعل فيها اللحم المقطع ثم يطبخ أو يشوى، قال: إذا عرضت منها كهاة سمينة ... فلا تهد منها واتشق وتجبجب 1 وعرضت: ماتت من مرض يسمى عارضة. وتجبجب أي اتخذ منها قلية في قطعة من جلدها مشرج. والجبوب: الحجارة الواحدة بالهاء. والجباب: زمن صرام النخل، يقال: جبوا نخلهم أي صرموها. والتجبيب: النفار والذهاب، يقال: جبب فذهب. وفي الحديث: الممسك بطاعة الله إذا جبب عنها الكار بعد الفار.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2120, 'بج', 'بج', 'بج', 'البج: الطعن، قال رؤبة: نقخا على الهام وبجا وخضا 2 والبجبجة: شيء يفعله الإنسان عند مناغاة الصبي. قال زائدة: والبجبجة صوت البطن. وبج الجرح يبجه بجا أي شقه، ويقال: انجبت ماشيتك من الكلاء إذا فتقها البقل فأوسع خاصرتيها، قال:'),
(2121, 'جم', 'جم', 'جم', 'جم الشيء واستجم أي كثر. والجموم: مصدر الجام من الدواب وكل شيء، وجم يجم. والجمام: الكيل إلى رأس المكيال، وتقول: جممت المكيال جما. والجمة: بئر واسعة كثيرة الماء. قال زائدة: جممته تجميما لا غير. وقال أبو سعيد: الجمة البئر التي قد جم ماؤها بعد تنكيز أي قلة. وجممت المكيال أي لم أوف، تجميما. والجمة: الشعر، (والجميع الجمم) 2 والجميم: النبات إذا تخطى الأرض. والجمم: مصدر الشاة الجماء وهي التي لا قرن لها. والجماء الغفير: الجماعة من الناس. قال أبو سعيد: الجماء استواء الناس حتى لا ترى لبعضهم على بعض فضلا، ليس فيهم متقدم لصاحبه، كأنهم حزمة، والغفير الذي غفر غطى بعضهم بعضا فلست ترى من تعرفه من التفاف بعضهم ببعض، وتقول: جاء القوم جماء الغفير وجما غفيرا. والجمجمة: ألا تبين كلامك من غير عي، قال: لعمري لقد طالما جمجموا ... فما أخروه وما قدموا 1 قال زائدة: الجمام (بكسر الميم) أي الموضع الذي عليه اللحام، وهي الحديدة التي يلحم بها المكيال 2 . والجمجمة: القحف وما تعلق به من العظام. والجمام: كثرة الماء. والجمام: الراحة. والجمة: الجماعة من الناس، لا واحد لها. والأجم: الذي لا رمح له. والأجم: الذكر من الشاة الجماء. والأجم: البناء الذي لا شرف له. وأجمت الحاجة أي دنت وحاجت.'),
(2122, 'مج', 'مج', 'مج', 'المج: حب كالعدس. قال الضرير: هو الماش. والمجاج: ما تمج، والشراب مجاج العنب. ومجاج الجراد 1 ما يسيل من أفواهها، قال: وماء قديم العهد أجن كأنه ... مجاج الدبا لاقى بهاجرة دبا 2 أي ينبثق بعضه على بعض. والماج: الأحمق، الكثير ماء القلب 3 . والمجمجة: تخليط الكتب وإفسادها بالقلم. وكفل ممجمج (إذا كان يرتج من النعمة) ، 4 قال: وكفلا ريان قد تمجمجا 5 وقال آخر: ندى الرمل مجته العهاد القوالس 1 وهي التي تخرج الندى كما تخرجه من خوفك ومتمجمج ومترجرج واحد. والمجماج: الكثير اللحم، والبجباج مثله. وأمج الفرس إذا بدا في العدو قبل أن يضطرم. والمج مج الريق، واسمه المجاج، وهو أن يخرج ريقه على طرف الشفة فيمجه مجا'),
(2123, 'شجذ', 'شجذ', 'شجذ', 'يقال: أشجذت السماء إشجاذا إذا أقلعت بالمطر.'),
(2124, 'شجر', 'شجر', 'شجر', 'يقال لمجتمع الشجر: شجراء. والمشجرة: أرض تنبت الشجر الكثير، وقل ما يقال: الأرض شجيرة، وماء شجير. وهذه أشجر من هذه أي أكثر شجرا. والشجر أصناف، فأما جل الشجر فعظامه وما بقي على الشتاء، وأما دق الشجر فصنفان، أحدهما تبقى له أرومة في الأرض في الشتاء، وينبت في الربيع، وما ينبت من الحب كما ينبت من البقل، وفرق ما بين الشجر والبقل، أن الشجر يبقى له أرومة على الشتاء ولا يبقى للبقل شيء. وأهل الحجاز يقولون: هذه الشجر، وهذه البر، وهي الشعير، (وهي التمر) 1 ، وهي الذهب، لأن القطعة منه ذهبة وبلغتهم نزل: والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله 2 ، ولذلك لم يقل: ينفقونه لأن المذكر غالب للمؤنث، فإذا اجتمعا فالذهب مذكر والفضة مؤنثة. ويقال: شجرة وشجرات وشجر. والمشجر ضرب من التصاوير على صفة الشجر 3 . وقد شجر بينهم أمر وخصومة أي اختلط واختلف، واشتجر بينهم. وتشاجر القوم: تنازعوا واختلفوا. ويقال: سمي الشجر لاختلاف أغصانه ودخول بعضها في بعض، واشتق من تشاجر القوم. والشجر: مفرج الفم، قال يصف فحلا: ينحي إذا ما جاهل ترمرما ... شجرا لإعناق الدواهي محطما 1 والشجير: الغريب الذي لا قدح له. والشجور البعير. وإذا تدلت أغصان شجر أو ثوب فرفعته وأخفيته قلت: شجرته، وهو مشجور، قال العجاج: رفع من جلاله المشجور 2 والجلال واحد وهو الغطاء، وجمعه أجلة. والشجار: خشب الهودج فإذا غشي غشاوة صار هودجا. والرماح شواجر يختلف بعضها في بعض، واشتجرت الرماح في جنبه. والمشجور الممسوك، وهي خشبة فيها شراع السفينة. والسجير والشجير واحد، وهما الخليط والصديق'),
(2125, 'جشر', 'جشر', 'جشر', 'الجشر بقول الربيع. وجشروا الدواب: أرسلوها في الجشر. والجشر: ما يكون في سواحل البحر وقراره من الحصى والأصداف وأشباه ذلك، وربما اجتمع فلزق بعضه ببعض وصار حجرا تنحت منه أرحية بالبصرة لا تصلح للطحن، فيجعل لرءوس البلاليع. قال زائدة: وجدنا أرضا بها جشر من بقول أي خليط من ضروبه. وجشر الصبح: انكشط عنه الظلام، وعن عثمان: لا يغرنكم جشركم عن صلاتكم. وقال زائدة: أرض جشرة أي صفاء 1 . والجاشر: الغليظ. ومال جشر أي يأوي إلى أهله. قال أبو الدقيش: أصبح بنو فلان جشرا أي يأوون إلى مكانهم في الإبل. والجشير: الجوالق الضخم. والجاشرية: امرأة منسوبة.'),
(2126, 'شرج', 'شرج', 'شرج', 'الشرج: عرى المصحف، والعيبة والخباء ونحوه مما يشرج بعضه ببعض. وشرجت اللبن تشريجا أي نضدت بعضه ببعض. والشريجة: جديلة من قصب للحمام. والشريجان: لونان مختلفان من كل شيء، قال في وصف القطا: شرائج بين كدري وجون 1 والعود الواحد يشق منه القوسان يدعى الشريج. والشريج: العقب، يقال: أعطني شريجة منه. والشرج شرج الوادي إذا بلغ منفسحه، وربما اجتمعت أشراج أودية في موضع واحد، قال العجاج: بحيث كان الواديان شرجا 2 أي بحيث يلتقيان ويتفرقان. قال زائدة: شرج الوادي منعرجة وملتقاه. والأشرج الذي له خصية واحدة، ويقال: هو الذي خصيته في صفنها فلحقت. وقال زائدة: تشرج اللبن خالطه دم يخرج من أثر صرار الناقة. وشرجته أنا إذا خلطته بدهن أو بشيء من دسم. وشرجت الثوب وشمرجته إذا خطته خياطة سوء. والشريجة من أدوات النساء: ما تعده للندف. وانشرج القوس والقناة: أصابها انكسار غير بات.'),
(2127, 'جرش', 'جرش', 'جرش', 'الجرش: حك شيء خشن بشيء مثله كما تجرش الأفعى أثناءها إذا احتكت أطواؤها فتسمع لها صوتا وجرشا. والملح: الجريش كأنه حك بعضه بعضا حتى تفتت. والجرش: الأكل. وجرش: موضع باليمن. ومجرئش الجبيين بوزن مجرعش حيث انتفخ أوساطها من ظاهر وباطن. قال: ومن العنوق: حمراء جرشية. ومعنى جرش من الليل أي ساعة. ومن العنب جرشي منسوب إلى جرش وهو جيد بالغ. والجريش يتخذ من لباب القمح. والجرشى بوزن فعلى: النفس، قال الشاعر: بكى جزعا من أن يموت وأجهشت ... إليه الجرشي وارمعل حنينها 1'),
(2128, 'شجن', 'شجن', 'شجن', 'الشجن: الهم والحزن، وأشجنني فشجنت منه أشجن شجونا. والحمامة تشجن شجونا إذا ناحت وتحزنت. ووردت أرضا ما كانت لي شجنا أي وطنا. والحديث ذو شجون أي فنون وأعراض أي أطراف ونواح. والأشجان: الأحزان، جمع شجن، والفعل منه شجنت أي صار الشجن في 1 وأما تشجنت فكأني تذكرت وتبكيت لذلك، (وهو كقولك) 2 : فطنت فطنا، وفطنت للشيء فطنة (وفطنا) 3 ، (وأنشد: هيجن أشجانا لمن تشجنا 4 والشاجنة: ضرب من الأودية والمسايل ذو نبت حسن، والجميع الشواجن. والشجنة: شجنة الرحم معلقة بالعرش 5 ، ويعني بالشجنة قرابة مشتبكة، ويقال: هي كالغصن من الشجرة، ويقال: هي شجنة وشجنة.'),
(2129, 'نشج', 'نشج', 'نشج', 'نشج الباكي ينشج نشيجا إذا غص البكاء في حلقه عند الفزعة. والطعنة تنشج عند خروج الدم: تسمع لها صوتا في جوفها، وإذا بدا صوت كالنفخة قيل نعرت الطعنة. والقدر تنشج عند الغليان. والناشج الذي ينزع نفسه، قال: وناشج عينه منهلة تكف 1'),
(2130, 'جشن', 'جشن', 'جشن', 'الجوشن: ما عرض من وسط الصدر. ويقال: الجوشن اسم الحديد الذي يلبس من السلاح. وجوشن الجرادة صدرها.'),
(2131, 'شنج', 'شنج', 'شنج', 'الشنج: تشنج الأصابع كلها والجلد، وربما قالوا: شنج أشنج وشنج مشنج، والمشنج أشد تشنيجا، وإذا شنج نسا الدابة فهو (أقوى لها و) 2 أشد لرجليها. وتقول هذيل: (غنج على شنج أي رجل على جمل، فالغنج هو الرجل، والشنج: الجمل) 1 قالوا: والغنج تحريك العنق والبدن'),
(2132, 'نجش', 'نجش', 'نجش', 'النجش: إن يريد الإنسان أن يبيع بياعة فيساومه بثمن كثير ينظر إليه ناظر فيقع فيها. وفي التزويج أيضا والأشياء، ومنه: الحديث: لا نجش في الإسلام. ونجشها نجشا، ورجل ناجش نجوش الصيد أي يأخذ من حواليها ليصرفها إلى الحبالة. قال زائدة: ينجش الطير أي يسوقه.'),
(2133, 'فشج', 'فشج', 'فشج', 'الفشج، يقال: فشجت الناقة وتفشجت وتفرشحت لتبول أو لتحلب. والتفشج التفحج على النار.'),
(2134, 'جشب', 'جشب', 'جشب', 'طعام جشب: لا أدم فيه. ورجل جشب المأكل، وقد جشب جشوبة أي لم يبال ما أكل بغير أدم. ويقال: الجشب ما لم ينخل من الطعام مثل خبز الشعير وشبهه. والجشاب من الندى الذي لا يزال يقع على البقل، قال: روضا بجشاب الندى مأدوما 1 قال مزاحم: كل شيء وقع على شيء فقد جشبه، وجشبك الله شبابك أي أماته وذهب. وأقول: جشب الندى البقل أي رده يعني ركبه فكاد يغييه عن العين.'),
(2135, 'شجب', 'شجب', 'شجب', 'الشجب: الهم والحزن، وقد أشجبك هذا الأمر فشجبت له شجبا. وغراب شاجب يشجب شجيبا وشجوبا، أي شديد النعيق الذي يتفجج من غربان البين، قال: ذكرن أشجابا لمن تشجبا 2 ورجل شاجب أي آثم يتكلم بالخنا فيهلك نفسه وشجب يشجب شجبا وشجوبا. وشجب شجبا أجود، قال الكميت: ليلك ما ليلك الطويل كما ... عالج تبريج غلة الشجب 1 والمشجب: خشبات موثقة تنصب وتنشر عليها الثياب.'),
(2136, 'جشم', 'جشم', 'جشم', 'جشمت الأمر جشما وجشامة أي تكلفته وتجشمته. وتجشمني فلان وأجشمني أي كلفني. وجشم البعير: صدره، وما يغشى به القرن من خلقه. يقال: غته بجشمه أي ألقى صدره عليه. ويقال: جشمت جشمة غليظة. وبنو جشم قبيلة من هوازن.'),
(2137, 'جمش', 'جمش', 'جمش', 'الجمش: حلق النورة، قال: حلقا كحلق النورة الجميش 2 . . والركب الجميش: المحلوق. والجمش: ضرب من الحلب بأطراف الأصابع كلها. والجمش: المغازلة، وهو يجمشها أي يقرصها ويلاعبها.'),
(2138, 'شمج', 'شمج', 'شمج', 'شمجوا من الشعير ومن الأرز ونحوه أي اختبزوا شبه قرص غلاظ. يقال: ما أكلت خبزا ولا شماجا ولا لماجا.'),
(2139, 'مشج', 'مشج', 'مشج', 'المشج: اختلاط حمرة ببياض، والمشج منه، وكل لون من ذلك مشج، والجميع أمشاج، ولا يفرد، قال أبو ذؤيب: كأن النصل والفوقين منه ... خلال الريش، سيط به مشيج 1 والمشيج: كل لون مستنكر خلطه غيره.'),
(2140, 'ضرج', 'ضرج', 'ضرج', 'الإضريج أكسية تتخذ من أجود المرعزاء. وعدو إضريج: شديد، قال أبو دواد: ولقد أغتدي يدافع ركني ... أجولي ذو ميعة إضريج 1 والإضريج من الخيل: الجواد الكثير العرق. وكل شيء تلطخ بالدم وغيره فقد تضرج. وقد ضرجت أثوابه بدم النجيع. وإذا بدت ثمار البقول وأكمامها قيل: انضرجت عنها لفائفها وأكمامها كأنها انفتحت وبدت. والضرج والإضراج غبرة الأرض.'),
(2141, 'ضجر', 'ضجر', 'ضجر', 'الضجر: اغتمام فيه كلام (وتضجر) 2 . ورجل ضجر. وناقة ضجور: كثيرة الرغاء.'),
(2142, 'جرض', 'جرض', 'جرض', 'الجريض المنفلت بعد شر. ويقال: إنه ليجرض الريق على هم وحزن، ويجرض على الريق غيظا أي يبتلعه. وقولهم: حال الجريض دون القريض قال أبو الدقيش: الجريض الغصة، والقريض الجرة، أي حالت الغصة دون الجرة، فذهبت مثلا. ومات جريضا أي مريضا مغموما، وقد جرض يجرض جرضا شديدا (قال رؤبة: ماتوا جوى والمفلتون جرضى 1 والجرياض: الرجل الجريض الشديد الغم، قال: وخانق ذي غصة جرياض 2 والخانق نعت كالمخنوق، فاعل مثل مفعول، مثل فاتن، وسبيل سابل وشعر شاعر. والجرياض: الكبير العظيم، والفرياض مثله. وناقة جراض وهي اللطيفة بولدها، نعت لها دون الذكر، قال: والمراضيع دائبات تربي ... للمنايا سليل كل جراض 3 وجمل جرائض: أكول شديد القصل بأنيابه للشجر. وبعير جرواض: ذو عنق جرواض أي غليظ شديد، قال: به تدق القصر الجرواضا 1'),
(2143, 'ضلج', 'ضلج', 'ضلج', 'الضولج الفضة الجديدة: والضولجة بالهاء.'),
(2144, 'ضجن', 'ضجن', 'ضجن', 'ضجنان: موضع. والضوجان من الدواب والإبل: كل يابس الصلب. ونخلة ضوجانة أي يابسة كزة السعف والعصا.'),
(2145, 'نضج', 'نضج', 'نضج', 'نضج نضجا ونضجا، والنضج الاسم والنضج المصدر. يقال: جاد نضج هذا اللحم (وقد أنضجه الطاهي) 2 وأتى به وهو نضيج منضج. ورجل نضيج الرأي والأمر أي: محكمه.'),
(2146, 'فضج', 'فضج', 'فضج', 'تفضج الجسد بالشحم وهو أن يأخذ مأخذه فتنشق عروق اللحم في مداخل الشحم بين المضائغ. ويقال: قد تفضج بدنا وسمنا. وإذا عرقت أصول شعره ولما يسل قيل: قد تفضج عرقا، قال: يعدو إذا ما بدنه تفضجا 1'),
(2147, 'ضجم', 'ضجم', 'ضجم', 'الضجم: عوج في الأنف يميل إلى أحد شقيه. والضجم في خطم الظليم، وربما كان مع الأنف أيضا في الفم، وفي العنق ميل يسمى ضجما فهو أضجم والأنثى ضجماء.'),
(2148, 'صرج', 'صرج', 'صرج', 'الصاروج: النورة وأخلاطها، تصهرج بها الحياض والحمامات.'),
(2149, 'صلج', 'صلج', 'صلج', 'الصلجة: فيلجة واحدة من القز. والصولج: الفضة الجيدة، يقال: هذه فضة صولج وصولجة. والصولجة: الصنج العربي الذي يكون في الدفوف ونحوها، فأما الصنج ذو الأوتار فهو دخيل. والصولجان معرب'),
(2150, 'صنج', 'صنج', 'صنج', 'الأصنوجة: الدوالقة من العجين. قال زائدة: الصنج العبد، والصنج معروف.'),
(2151, 'نجص', 'نجص', 'نجص', 'الإنجاص والإجاص لغتان كالإنجانة والإجانة. ومكان نجاصص: أبيض مستو.'),
(2152, 'صمج', 'صمج', 'صمج', 'الصمج: القناديل، واحدتها بالهاء، قال الشماخ: تسرى إذا نام بنو السريات ... والنجم مثل الصمج الروميات 1'),
(2153, 'جدس', 'جدس', 'جدس', 'جديس حي كانوا يناسبون عادا، وهم إخوة طسم، وكانت منازلهم اليمامة، قال: بوار طسم بيدي جديس 2'),
(2154, 'جسد', 'جسد', 'جسد', 'الجسد للإنسان، ولا يقال لغير الإنسان جسد من خلق الأرض. وكل خلق لا يأكل ولا يشرب من نحو الملائكة والجن مما يعقل فهو جسد. وكان عجل بني إسرائيل جسدا لا يأكل ولا يشرب ويصيح، وقوله تعالى: وما جعلناهم جسدا لا يأكلون الطعام 1 أي ما جعلناهم خلقا مستغنين عن الطعام. ودم جسد جاسد أي قد يبس، قال:'),
(2155, 'ستج', 'ستج', 'ستج', 'الإستاج والإستيج من كلام أهل العراق، وهو الذي يلف عليه الغزل بالأصابع تسميه العجم استوجة وأسجوته أي دناجة (كذا) 1'),
(2156, 'جسر', 'جسر', 'جسر', 'الجسر والجسر القنطرة ونحوه مما يعبر عليه. ورجل جسر أي جسيم جسور شجاع. وناقة جسرة: ماضية، وقل ما يقال: جمل جسر. وقد جسر يجسر جسورا. وإن فلانا ليجسر فلانا أي يشجعه.'),
(2157, 'سجر', 'سجر', 'سجر', 'سجرت التنور أسجره سجرا، والسجور اسم للحطب. والمسجرة: الخشبة التي يساط بها السجور في التنور، والمفأد المحراث وهو المحلال. والسجور: امتلاء البحر والعين، وكثرة مائه. والبحر المسجور: المفعم الملآن، قال أبو ذؤيب: جون يردن ندى سجور منعم 2 وقوله تعالى: وإذا البحار سجرت 1 أي غيضت وبحر مسجور ومسجر، وبعضهم يفسر أنه لا يبقى فيه ماء. والسجير: خليل الرجل وصفية، وجمعه سجراء. والساجر: السيل يمر بشيء فيملؤه، وتقول: سجر السيل الآبار والأحساء. والسجرة والسجر: حمرة في بياض العين، ويقال: إذا خالطت الحمرة الزرقة. فهي سجراء أيضا.'),
(2158, 'جرس', 'جرس', 'جرس', 'الجرس: مصدر الصوت المجروس، والجرس: الصوت نفسه. وجرست الكلام: تكلمت به. وجرس الحرف: نغمة الصوت. والحروف الثلاثة الجوف لا صوت لها ولا جرس، وهي الواو والياء والألف اللينة، وسائر الحروف مجروسة. والنحل تجرس العسل جرسا، وهو لحسها إياه ثم لعسها إياه، ثم تعسيله في شورتها. وتسمى النحل الجوارس. والجرس الذي يعلق من البعير. وأجرسوا الجرس أي ضربوا، وأجرس الحلي ونحوه إذا صوت كصوت الجرس، قال العجاج: تسمع للحلي إذا ما وسوسا ... وارتج في أجيادها وأجرسا زفزفة الريج الحصاد اليبسا 1 ويقال: فلان مجروس لفلان أي أنه إنما ينشرح للكلام معه. وقال بعضهم: مجرس كثير الكلام لا يقر معه أحد.'),
(2159, 'رجس', 'رجس', 'رجس', 'كل شيء يستقذر فهو رجس كالخنزير، وقد رجس الرجل رجاسة من القذر، وأنه لرجس مرجوس. والرجس في القرآن العذاب كالرجز، وكل قذر رجس. ورجس الشيطان وسوسته وهمزه. والرجس، الصوت الشديد للرعد. والبعير مرجس ورجاس. والرجس أي صوت. والسحاب يرجس بصوته، والغمام الرواجس الرواعد.'),
(2160, 'سرج', 'سرج', 'سرج', 'وحرفة السراج السراجة، وأسرجت السرج إسراجا. والسراج: الزاهر الذي يزهر بالليل، والفعل منه: أسرجت السراج إسراجا. والمسرج: الموضع الذي توضع عليه المسرجة. والمسرجة: التي توضع فيها الفتيلة) 1 . وأسرجت الدابة. والشمس سراج النهار، والهدى سراج المؤمنين. وسرج الله وجهه وبهجه أي حسنه، قال العجاج: وفاحما ومرسنا مسرجا 2 لم يعن به أنه أفطس مسرج الوسط لكن عنى به الحسن والبهجة. قال القاسم: شبه حسن الأنف وامتداده بالسيف السريجي وهو ضرب من السيوف.'),
(2161, 'سجل', 'سجل', 'سجل', 'السجل: ملاك 3 الدلو، وأعطيته سجلا وسجلين، وأسجلته. والحرب سجال أي مرة منها سجل على هؤلاء، ومرة على هؤلاء. والمساجلة: المغالبة أيهما يغلب صاحبه. والسجل 1 من الضروع: الطويل. وخصية سجيلة أي مسترخية الصفن. والسجل: كتاب العهدة، ويجمع سجلات. والسجيل: حجارة كالمدر، وهو حجر وطين، ويفسر أنه معرب دخيل. ويقال: هذا الشيء مسجل للعامة أي مرسل من شاء أخذه أو أخذ منه. والسجنجل ثلاثي ألحق بالخماسي، وهو المرأة النقية.'),
(2162, 'سلج', 'سلج', 'سلج', 'السلج نبات رخو من دق الشجر، والسلجان ضرب منه.'),
(2163, 'جلس', 'جلس', 'جلس', 'ناقة جلس وجمل جلس أي وثيق. والجلس: ما ارتفع عن الغور من أرض نجد، وتقول: أغاروا وأجلسوا وغاروا وجلسوا. وجلس يجلس جلوسا، وهو حسن الجلسة. والجلسي: ما حول الحدقة، ويقال: ظاهر العين. والجلسان: دخيل، وهو بالفارسية كلشان، وقال: لنا جلسان عندها وبنفسج ... وسيسنبر والمرزجوش منمنما 1'),
(2164, 'نسج', 'نسج', 'نسج', 'وحرفة النساج النساجة. والريح تنسج الدار 2 إذا نسجت المور والجول على رسومها، والريح تنسج التراب والماء أي تضرب متنه فانتسجت له طرائق كالحبك، والشاعر ينسج الشعر، والكذاب ينسج (الزور) 3 . والمنسج: الخشب والأداة يمد عليها الثوب للنسج، والمنسج لغة فيه. والمنسج: المنتبر من كاتبة الدابة عند منتهى منبت العرف تحت القربوس المقدم. وناقة نسوج وسوج: تنسج وتسج في سيرها، وهو سرعة نقل القوائم.'),
(2165, 'جنس', 'جنس', 'جنس', 'الجنس: كل ضرب من الشيء والناس والطير، وحدود النحو والعروض والأشياء ويجمع على أجناس.'),
(2166, 'نجس', 'نجس', 'نجس', 'النجس: الشيء القذر حتى من الناس وكل شيء قذرته فهو نجس وامرأة نجس ورجال نجس ونسوة نجس، فإذا لم يكن على طهارة من الجنابة ولم يبال فهو نجس. والنجس: اتخاذك عوذة للصبي، والفاعل المنجس، ونجست الصبي تنجيسا، قال حسان: وجارية ملبوبة ومنجس ... وطارقة في طرقها لم تشدد 1 والناجس والنجيس: اللذان لا يبرءان من دائهما. ومصدر النجس النجاسة، وإن قيل: نجس نجاسة كان قياسا.'),
(2167, 'سجن', 'سجن', 'سجن', 'السجن المحبس، والسجن: الحبس. والسجن البيت الذي يحبس فيه السجين: من أسماء جهنم.'),
(2168, 'سنج', 'سنج', 'سنج', 'السناج: أثر دخان السراج 2 على شيء أو الجدار. قال مزاحم: سنجت الشيء إذا كهبته بلون سوى لونه، وهو كل ما لطخت شيئا بشيء فقد سنجته.'),
(2169, 'سجف', 'سجف', 'سجف', 'السجفان: سترا باب الحجلة، وكل باب يستره ستران مشقوق بينهما فكل شق سجف، وكذلك سجفا الخباء، وسمي خلف الباب سجفا. والسجف والتسجيف: إرخاء السجفين، قال الفرزدق: رقدن عليهن الحجال المسجف 1 نعت الحجال بنعت الذكر المفرد على تذكير اللفظ لأن الحجال على لفظ الحمار، فكل جماعة يشبه لفظها لفظ الواحد يجوز أن تنعتها بنعت الواحد، كما تقول: جيش مقبل ولم تقل: مقبلون، لأن لفظ جيش لفظ واحد كما تقول: غير ونحوه، قال الفرزدق: من السجف الحرى عليهم حضائر 2 يصف قوما أصابتهم سنة فهلكت نعمهم فجيفهم حسرى موتى حواليهم، وحسرى جماعة الحسير وهو المعيي، وذكر ذلك على تذكير اللفظ، لأن الجيف على لفظ العنب.'),
(2170, 'فسج', 'فسج', 'فسج', 'قلوص فاسجة: أعجلها الفحل فضربها قبل بلوغ وقت الضراب، وقد يقال في الشاء، وهي تفسج فسوجا.'),
(2171, 'جفس', 'جفس', 'جفس', 'الجفس لغة في الجبس، وهو اللئيم.'),
(2172, 'فجس', 'فجس', 'فجس', 'الفجس من التفجس وهو العظمة والتطاول، قال العجاج: خليفة ساس بغير فجس 1 والفعل على تفعل، قال الأعشى: يكاد يصرعها لولا تفجسها ... إذا تقوم إلى جاراتها، الكسل 2'),
(2173, 'جبس', 'جبس', 'جبس', 'الجبس: الجبان الرديء. ويقال: الجبس من أولاد الريبة 3'),
(2174, 'بجس', 'بجس', 'بجس', 'البجس: انشقاق في قربة أو حجر أو أرض ينبع منه الماء، فإن لم ينبع فليس بانبجاس، قال الله تعالى: فانبجست منه اثنتا عشرة عينا 4 والسحاب يتبجس بالمطر. والإنبجاس عام والنبوع للعين خاصة. ورجل منبجس: كثير خيره.'),
(2175, 'سبج', 'سبج', 'سبج', 'السبجة: ثوب من بعض ما يلبسه الطيانون، له جيب (ولا يدان) 1 ولا فرجان. وربما تسبج الإنسان بكساء أو ثوب، قال العجاج: كالحبشي التف أو تسبجا 2 والسيبجي ويجمع السيابجة: قوم جلداء من السند يكونون مع اشتيام 3 السفينة البحرية وهو رأس ملاحي السفينة، وهو بالنبطية اشتياس،'),
(2176, 'سجم', 'سجم', 'سجم', 'سجمت العين تسجم سجوما وهو قطران الدمع 4 قل أو كثر، وكذلك المطر. ودمع ساجم ومسجوم، وسجمته العين سجما، ولا يقال: أسجمته العين. والسجم: الدمع.'),
(2177, 'جسم', 'جسم', 'جسم', 'الجسم يجمع البدن وأعضاءه من الناس والإبل والدواب ونحوه مما عظم من الخلق الجسيم، والفعل: جسم جسامة. والجسام يجري مجرى الجسيم. والجسمان: جسم الرجل، ويقال: إنه لنحيف الجسمان.'),
(2178, 'سمج', 'سمج', 'سمج', 'سمج الشيء سماجة أي لا ملاحة فيه.'),
(2179, 'جمس', 'جمس', 'جمس', 'الجاموس دخيل. وتقول: جمس الماء وجمد، وجمست الإهالة 1 . وصحرة جامسة: لزمت مكانا مقشعرة، وقال:'),
(2180, 'زجر', 'زجر', 'زجر', 'زجرته فانزجر أي نهيته، وهو في الإبل، تقول: زجرته وازدجرته ما وقد ازدجر بمعنى انزجر. وقوله تعالى: وازدجر فدعا ربه 2 أي زجر وأذعن أن يدعوهم إلى الله. وزجر الطير أن يقول الإنسان إذا رأى طائرا أو ظبيا أو نحوه: ينبغي أن يكون كذا، فعند ذلك يقال: يزجر الطير فيرى في زجرها كذا. وإنما طائر الإنسان سهمه الذي يطير له وحظه الذي يقسم له. والطيرة اشتق منه. والزجر ضرب من السمك عظام صغار الحرشف، ويجمع الزجور والأزجر من الإبل الذي في فقار ظهره انخزال أو من دبر 3 . قال مزاحم: الأزجر من الإبل مثل الأفزر، والفزر في الظهر. وناقة زجراء ونوق زجر، وكذلك قوم فزر، وجمل أزجر. وناقة زجراء وهي التي في وركيها ثقل فلا تكاد تقوم.'),
(2181, 'جزر', 'جزر', 'جزر', 'الجزر: انقطاع المد، وجزر البحر، والجزر: نهر أو مد البحر والنهر في كثرة الماء. والجزيرة: أرض في البحر ينفرج عنها ماء البحر فتبدو، وكذلك الأرض لا يعلوها السيل فيحدق بها فهي الجزيرة. والجزيرة: كورة بجنب الشام، والجزيرة بالبصرة: أرض نخل بين البصرة والأبلة خصت بهذا الاسم. وجزيرة العرب محلتها لأن البحرين بحر فارس الحبش ودجلة والفرات قد أحاطت بجزيرة العرب، وهي أرضها ومعدنها. والجزر: نحر الجزار الجزور، والفعل: جزر يجزر. والجزارة: اليدان والرجلان والعنق، سميت بها لأنها لا تقسم في سهام الجزور، قال: شخت الجزارة 1'),
(2182, 'جزل', 'جزل', 'جزل', 'الجزل: أرض كثيرة الحجارة، وتجمع على أجزال، ويقال: إنما هو الجرل بالراء. والجزل: الحطب اليابس، والعطاء الكثير، وأجزل العطاء. وعطاء جزل جزيل. وامرأة جزلة: ذات أرداف وعجيزة. والجوزل: فرخ الحمام. والجزل: دبرة تخرج على كاهل البعير فلا تبرأ حتى يخرج منها عظم فينخسف مكانه وتغضف يد البعير، ويقال: بعير أجزل، قال الكميت: إذا هما ارتد فارضا قعودهما ... إلى التي غبها التوقيع والجزل وأرض جزلة أي شجراء.'),
(2183, 'زجل', 'زجل', 'زجل', 'الزجل: رميك الشيء تأخذه بيدك. والزجل، إرسال الحمام الهادي من مزجل بعيد، والفعل: يزجله، وفي الرمي: زجل به. والزجل: رفع الصوت الطري، يقال: حاد زجل، ومغن زجل، وقد زجل يزجل زجلا. والزنجيل 1 : الضعيف الجبان وكذلك الزؤاجل. والزجلة: الحمامة. والزاجل: حلقة الحزام من خشب. والزاجل من البيضة. والزجلة: الجماعة.'),
(2184, 'جلز', 'جلز', 'جلز', 'كل شيء يلوى على شيء ففعله الجلز، والاسم الجلاز. وجلائز القوس: عقب قد لوي عليها في مواضع، كل واحد منها جلاز، قال الشماخ: وصفراء من نبع عليها الجلائز 2 والجلاز أعم، ألا ترى أن العصابة اسم للشيء الذي للرأس خاصة، وكل شيء يعصب به فهو عصاب. وإذا كان معصوب الخلق واللحم قلت: إنه لمجلوز اللحم والخلق، ومنه أخذ: ناقة جلس، بالسين بدل من الزاي، وهي الوثيقة الخلق. والجلاز أيضا: العقب الذي يلف على السوط. والجلواز: الشرطي، وجلوزته: خفته في ذهابه ومجيئه بين يدي العامل. وجالزني: سبقني.'),
(2185, 'لزج', 'لزج', 'لزج', 'يقال: أكلت شيئا فلزج بإصبعي لزجا أي علق به، وزبيبة لزجة. والتلزج: تتبع البقول والرعي القليل من أوله أو في آخر ما يبقى'),
(2186, 'زلج', 'زلج', 'زلج', 'الزلج، مجزوم: سرعة ذهاب الشيء ومضيه، يقال: زلجت الناقة تزلج أي أسرعت كأنها لا تحرك قوائمها من سرعتها. والسهم يزلج على وجه الأرض ثم يمضي مضيا زلجا وزليجا، قال: فوقعتها ملسا وهزة 1 وأزلجت السهم، وإذا وقع بالأرض ولم يقصد الرمية، قيل: أزلجت السهم. والمزلج من العيش: المدافع البلغة الشديدة، قال ذو الرمة:'),
(2187, 'جنز', 'جنز', 'جنز', 'الجنازة، بنصب الجيم وجرها،: الإنسان الميت والشيء الذي ثقل على قوم واغتموا به أيضا جنازة، قال: وما كنت أخشى أن أكون جنازة ... عليك ومن يغتر بالحدثان 3 وقوم ينكرون الجنازة للميت يقولون: الجنازة بكسر الصدر، خشبة الشرجع، وإذا مات فإن العرب تقول: رمي في جنازته. وقد جرى في أفواه العامة الجنازة بنصب الجيم، والنحارير ينكرونه. وجنز الشيء إذا جمع'),
(2188, 'نجز', 'نجز', 'نجز', 'نجز الوعد والحاجة ينجز نجزا وأنجزته وأنجزت به أي عجلت ووفيت به، ونجز هو أي وفي به كما تقول: حضرت المائدة، وإنما أحضرت. وفي المثل: ناجز بناجز أي يد بيد، يعني: تعجيل بتعجيل. والمناجزة في الحرب أن يتبارز الفارسان حتى يقتل أحدهما صاحبه، قال عبيد بن الأبرص: نهنه دموعك إن من ... يغتر بالحدثان عاجز كونن فيما يعتريك ... به الزلازل والهرائز كالهندواني المهند هزه ... قرن مناجز 1 والتنجز: طلب شيء قد وعدته.'),
(2189, 'زنج', 'زنج', 'زنج', 'الزنج والزنج: جيل من السودان، أخذ منه زناج اسم امرأة، ويقال في النداء: يا زناج ونحوه.'),
(2190, 'جزف', 'جزف', 'جزف', 'الجزاف في الشراء والبيع دخيل، وهو بالحدس بلا كيل ولا وزن، تقول: بعته واشتريته بالجزافة والجزاف، والقياس: جزاف.'),
(2191, 'جبز', 'جبز', 'جبز', 'الجبز والجبز: اللئيم البخيل. قال الضرير: والجبيز أيضا.'),
(2192, 'مزج', 'مزج', 'مزج', 'المزج: مصدر مزجته: والمزاج الاسم، ومزاج الجسم ما أسس عليه البدن من المرة ونحوه. ويقال: قد مزج السنبل أي لون من خضرة إلى صفرة. والمزج: الشهد.'),
(2193, 'زمج', 'زمج', 'زمج', 'الزمج طائر دون العقاب في قمته حمرة غالبة تسميه العجم دو برادر، وترجمته أنه إذا عجز عن صيده أعانه أخوه على أخذه.'),
(2194, 'جمز', 'جمز', 'جمز', 'الجمز والجمزان والجمزي: عدو دون الحضر الشديد، قال: كأني ورحلي إذا زغتها ... على جمزي جازىء بالرحال 1 وجمز يجمز جمزا وجمزانا. والجمزان: ضرب من التمر والنخل والجميز، ومنهم من يؤنث فيقول الجميزى شجرة كالتين خلقة وكالفرصاد عظما، ورقة أصغر من التين، ويحمل تينا أصفر وأسود، صغارا يكون بالغور يسميه بعضهم التين الذكر، ويسمي بعضهم حملة الحما، فالأصفر منه حلو، والأسود يدمي. والجمزة كتلة من تمر وأقط ونحو ذلك.'),
(2195, 'جزم', 'جزم', 'جزم', 'الجزم: ضرب من الكتابة، وهو تسوية الحرف، وقلم جزم: لا حرف فيه. ومن القراءة: أن يجزم الكلام جزما، توضع الحروف في مواضعها في بيان ومهل. والجزم: الحرف إذا سكن آخره. وجزمت القربة إذا ملأتها. وجزمت له جزمة من مال أي قطعته له. والجزم: الخرص في التمر وغيره.'),
(2196, 'زجم', 'زجم', 'زجم', 'يقال: ما تكلم فلان بزجمة أي بنبسة. وزجم له زجمة أي ألقى إليه كلمة أو سببا من الأسباب. والزجوم من القسي: التي ليست بشديدة.'),
(2197, 'جدث', 'جدث', 'جدث', 'الأجداث: القبور، واحدها جدث.'),
(2198, 'جدر', 'جدر', 'جدر', 'الجدر: ضرب من النبات، الواحدة بالهاء. ومن الشجر: الدق ينبت في القفاف والصلاب، فإذا أطلعت رءوسها في أول الربيع يقال: أجدرت الشجرة وأجدرت الأرض، فهو جدر، وفي نسخة: مجدر، حتى يطول، فإذا طال تفرقت أسماؤه. والجدار جمعه جدر. والجدير: مكان بني حواليه جدار مجدور، قال: ويبنون في كل واد جديرا 1 وقال: تشييد أعضاد البناء المجتدر 2 والجدري معروف، وصاحبه مجدور ومجدر، وهو قروح تنفط عن الجلد 3 والجدر: انتبار في عنق الحمار، وربما كان من آثار الكدم، وجدرت عنقه جدرا إذا انتبرت أعراضه. وفلان جدير لذاك، وقد جدر جدارة، وأجدر به أن يفعله أي خليق. والجدر: شدة الشرب. وامرأة جيدرة: قصيرة، ورجل جيدر وجيدرة أيضا.'),
(2199, 'دجر', 'دجر', 'دجر', 'الدجر شبه الحيرة، وقد دجر فهو دجر ودجران أي حيران في عمله وأمره، ويجمع دجارى، قال: دجران لم يشرب هناك الخمرا 1 والديجور: الظلام والغبار الأسود. والدجر: اللوبياء. والدجر: الخشبة التي تشد عليها حديدة الفدان، وبالكسرة لغة، ومنهم من يجعله دجرين كأنهما أذنان، والحديدة اسمها السبة، والفدان اسم لجميع أدواته، والنير الخشبة على عنق الثور، والسميقان خشبتان قد شدتا في العنق، والخشبة التي في وسطه يشد بها عنان الويج، وهي القناحة، والويج والميل باليمانية اسم الخشبة الطويلة بين الثورين، والخشبة التي يقبض عليها الحراث هي المقوم والمملقة والمملسة النمرز 2 وهو المسفن أيضا.'),
(2200, 'جرد', 'جرد', 'جرد', 'الجرد فضاء لا نبات فيه، اسم للفضاء، فإذا نعت به قلت: أرض جرداء، ومكان أجرد، وقد جردت جردا، وجردها القحط تجريدا. ورجل أجرد: لا شعر على جسده. والأجرد من الخيل والدواب: القصير الشعر حتى يقال: إنه لأجرد القوائم أي قصير شعر القوائم أي قصير شعر القوائم، قال: كأن قتودي والفتان هوت به ... من الذرو جرداء اليدين وثيق 1 ويقال: فلان حسن الجردة وهي العرية. والمجرد: الذي أجرده الناس فتركوه في مكان واحد. والجرد: أخذك الشيء عن الشيء جرفا وسحفا، فلذلك سمي المشؤوم جارودا كما قيل في الهجاء للجارود العبدي: لقد جرد الجارود بكر بن وائل 2 وإذا جد الرجل في سيره فمطى، يقال: انجرد فذهب. وتجرد لأمر كذا أو للعبادة أي أخذ في القيام به. وإذا خرجت السنبلة من لفائفها، قيل: تجردت. وامرأة بضة المتجرد أي رخصة ناعمة تحت ثيابها. والجريدة: سعفة رطبة جرد عنها خوصها كما يقشأ 3 الورق عن القضيب وزرع مجرود: أصابه الجراد، وجرد الزرع. والجردان والمجرد: من أسماء الذكر. والجراد والجرادة اسم رمل بالبادية. والجرادة والجراد: اللحاسة، معروف. والجرد: ثوب خلق، لغة هذيل، وهذيل تقول: لبس جردة، وأرض مجرودة ومجرد وجردة أي ليس فيها سترة من شجر وغيره. والجريدة: طائفة من الجند 1 .'),
(2201, 'ردج', 'ردج', 'ردج', 'الردج: ما يخرج من بطن السخلة أول ما توضع 2 ، ويقال للصبي أيضا 3 ، قال الشاعر: والكلب يلحس عن حرف استه الردجا 4'),
(2202, 'درج', 'درج', 'درج', 'الدرج: جماعة عتب الدرجة. والدرجة في الرفعة والمنزلة، وتجمع الدرج، ودرجات الجنان: منازل ارفع من منازل. والدرجان: مشية الشيخ والصبي، ودرج يدرج درجا ودرجانا. والدراج من الطير بمنزلة الحيقطان، من طير العراق، أرقط. والدريج: شيء يضرب به ذو أوتار كالطنبور. وكل برج من بروج السماء ثلاثون درجة. والمدرجة: ممر الأشياء على مسلك الطريق ونحوه. ورجعت في أدراجي ودرجي أي طريقي الذي مررت فيه. ودرج قرن بعد قرن أي فنوا، وأدرجهم الله إدراجا. وأدرجت الكتاب، وفي درج الكتاب كذا. والدراجات شبه الدبابات تتخذ في الحروب يدخل فيها الرجال. والدرج: حفش من أحفاش النساء والجميع الدرجة. والدرجة: خرقة تدرج فتجعل في حياء الناقة إذا ظئرت يغطى رأسها ثم يسلون تلك الدرجة سلا عنيفا فيشمونها للرأم فإذا شمت ظنت أنه ولدها فانعطفت عليه، قال: ولم يجعل لها درج الظئار 1 أي لم تلد قط. والمدراج: الناقة تضمر حتى يلحق حقبها بالتصدير. والمدراج أيضا: الناقة لا تجاوز يومها الذي ضربت فيه حتى تنتج، والتي تجاوز يقال لها الجرور.'),
(2203, 'جدل', 'جدل', 'جدل', 'رجل جدل مجدال أي خصم مخصام، والفعل جادل يجادل مجادلة. وجدلته جدلا، مجزوم، فانجدل صريعا، وأكثر ما يقال: جدلته تجديلا أي صرعته، ويقال للذكر العرد: أنه لجدر جدل 1 . وجدول الإنسان: قصب اليدين والرجلين. وإنسان مجدول الخلق أي لطيف القصب. وجديل: الناقة: زمامها إذا كان مجدول الفتل. والجديلة: شريجة الحمام. وجديلة: قبيلة. والأجدل: من صفة الصقر، ورجل أجدل المنكب أي فيه تطأطؤ خلاف الأشرف من المناكب. ويقال للطائر إذا كان كذلك أجدل المنكبين، فإذا جعلته نعتا قلت: صقر أجدل، وصقور جدل. وإذا تركته اسما للصقر، قلت: هذه أجدل وهذه أجادل، لأن الأسماء التي على أفعل تجمع على أفاعل، والنعت إذا كان على أفعل يجمع على فعل. والجديل: نهر يأخذ من دجلة. والجدول: نهر الحوض ونحوه من الأنهار الصغار. والمجدل: القصر المنيف ويجمع مجادل.'),
(2204, 'دجل', 'دجل', 'دجل', 'دجيل: نهر صغير يأخذ من دجلة نهر العراق. والدجل: شدة طلي الجرب بالقطران، قال: البغض مثل الأجرب المدجل 1 والدجال: المسيح الكذاب، ودجله سحره وكذبه لأنه يدجل الحق بالباطل أي يخلطه، وهو رجل من اليهود يخرج في آخر هذه الأمة.'),
(2205, 'دلج', 'دلج', 'دلج', 'الدلج والدلجة: سير وارتحال بالليل، والفعل الإدلاج والإدلاج. ويقال: أدلج من آخر الليل، وادلج الليل كله. والمدلج اسم للقنفذ والدالج: الساقي يأخذ الدلو فيدلج بها من رأس البئر إلى الحوض قابضا عليه بيده، قال: بانت يداه عن مشاش والج ... بينونة السلم بكف الدالج 1 والدولج لغة في التولج، والدولج: البيت الصغير كالمخدع وشبهه. والدولج: كناس الوحش يتنكر فيه.'),
(2206, 'جلد', 'جلد', 'جلد', 'الجلد: غشاء جسد الحيوان، ويقال: جلدة العين ونحوها. وقوله- جلت عظمته-: وقالوا لجلودهم 2 ، يفسر: لفروجهم، فكنى بالجلود عنها. والجلد: ما صلب من الأرض واستوى متنه، والجميع أجلاد. وهذه أرض جلدة، ومكان جلد، والجميع جلدات، وناقة جلدة ونوق جلدات وهي القوية على العمل والسير، وتجمع على جلاد. وجلده بالسوط جلدا أي ضرب جلده. وجلدت البو تجليدا أي حشوته بالتبن، والقطعة من البو جلدة والجمع جلد، قال: عواكفا بجلد الحوار 3 وبعض يروي بجلد على معنى صلب وصلب، وقد قرىء: بين الصلب والترائب 1 . والجلاد بالسيوف الضراب. وجلدت به الأرض أي صرعته. والجليد: ما جمد من الماء وما وقع على الأرض من الصقيع فجمد، وقول الأخطل: يبقى لها بعدها آل ومجلود 2 قال أبو الدقيش: لها ألواحها، ومجلودها بقية جلدها. ورجل جلد: جليد، وقد جلد جلادة. والمجالد مثل المآلي، واحدها مجلد، وهي من جلود. والجلد أن يسلخ جلد البعير أو غيره فيلبسه غيره من الدواب، قال العجاج يصف الأسد: كأنه في جلد مرفل 3'),
(2207, 'جدن', 'جدن', 'جدن', 'جدن اسم رجل. ذو جدن: اسم رجل من مقاولة اليمن.'),
(2208, 'دجن', 'دجن', 'دجن', 'الدجن: ظل الغيم، ويوم مدجن: دام عليه ظل غيمه مع ندى. وكلب داجن أي ألف البيت، ودجن يدجن دجونا ونحوه لغيره. والداجن: المعتاد. والدجون: الألفان. ويقال للناقة التي قد عودت السناوة: مدجونة أي دجنت للسناوة، وهكذا القول فيها والمداجنة: حسن المخالطة. والدجنة: الظلماء، والتخفيف جائز للشاعر كقول حميد 1 : حتى إذا انجلت دجى الدجون 2 وقد ادجوجن. وإذا غربت الكلمة فكثيرا ما يخرجون فعلها على افعوعل مثل اعصوصب، واحرورف من الانحراف.'),
(2209, 'نجد', 'نجد', 'نجد', 'النجد: ما خالف الغور. وأنجد القوم صاروا ببلاد نجد. وكل شرف من الأرض استوى ظهره فهو نجد، ويجمع على أنجاد، وفي أدنى العدد: أنجد، و [والجماعة] النجاد. والنجاد في مثل هذه الصفة أرض فيها ارتفاع وصلابة، قال: قلائص إذا علون فدفدا ... رمين بالطرف النجاد الأبعدا 1 ويقال: هاهنا الطريق الواضح، والطريق الواضح يسمى نجدا، وقوله تعالى: وهديناه النجدين 2 أي طريق الخير وطريق الشر. وأمر نجد: واضح، وطريق نجد هاد، قال أمية: 3 وقد جاكم النجد النذير محمد ... دليل على طرق الهدى ليس يهمد 4 ويقال: هو ابن نجدتها للدليل الهادي الذي كأنه ولد ونشأ بها، ويقال: ابن بجدتها، بالباء. والناجد: الساكن المقيم. ونجد الأمر ينجد نجودا أي استبان ووضح فهو ناجد، وفي الحديث: أنه رأى امرأة عليها مناجد من ذهب فنهاها عن لبسها وهي حلي مكلل مزين بالجوهر. وبيت منجد، ونجوده ستور تشد على حيطانه وسقوفه يزين بها البيت، فإذا فعل ذلك كان ما يلي الأرض من الزينة داخلا في النجود. والنجاد: الذي يعالج الفرش والوسائد يحشوها ويخيطها بالأجر في الأسواق. ورجل نجد أي ماض في أمره، وشجاعته، والجميع أنجاد. والنجدة: الشجاعة، وهي البلوغ في الأمر الذي يعجز عنه. ورجل نجد ونجد ونجيد [كما] في قوله: عند المحجر النجد 1 واستنجد فلان: صار منجادا نجدا، واستنجدتهم فأنجدوني أي استعنتهم فأعانوني. وناقة نجود: تناجد الإبل فتغزر إذا غزرن، والغزيرة الكثيرة اللبن. والنجدات: قوم من الحرورية ينسبون إلى نجدة (الحروري) 2 . يقال: هؤلاء النجدات والنجدية، والواحد نجدي. وناجدت فلانا: بارزته بالقتال. والناجود: الراووق نفسه. ونجاد السيف: محملاه اللذان طرفاهما في الإبزيمين، قال: بأي نجاد تحمل السيف بعدنا ... قطعت القوى من محمل كان باقيا 3 والنجد: الكرب والغم، وهو منجود أي مكروب. والنجد: العرق، ونجد نجدا.'),
(2210, 'جند', 'جند', 'جند', 'كل صنف من الخلق يقال لهم: جند على حدة. وفي الحديث: الأرواح جنود مجندة فما تعارف منها ائتلف وما تناكر منها اختلف. ويقال: هذا جند قد أقبل، وهؤلاء جند قد اقبلوا، يخرج على الواحد والجميع، وكذلك العسكر والجيش. وجند: موضع باليمن. والجند: حجارة شبه الطين. وجناده: حي من اليمن.'),
(2211, 'جدف', 'جدف', 'جدف', 'الجدف: نبات يكون باليمن يأكله الأكل فلا يحتاج معه إلى شرب. وجدفت الصريح أي قطعته. والملاح يجدف جدفا بالمجداف، وهو خشبة في رأسها لوح عريض يدفع بها السفينة. وجدف الطائر عند الفرق من الصقر إذا كسر من جناحيه شيئا ثم مال. وفي الحديث: إن الجدف ما لا يغطى من الشراب. وجدف الرجل تجديفا كأنه يستقل ما أعطاه الله. والتجديف في بعض التفسير كفر النعمة، وهو التقصير في الشكر، وهو قريب المعنى من الأول. والأجدف: القصير. والجدف: النزع الشديد في القوس.'),
(2212, 'فدج', 'فدج', 'فدج', 'فودج العروس مركبها، وربما قالوا للناقة الواسعة الأرفاغ: واسعة الهودج والفودج.'),
(2213, 'جدب', 'جدب', 'جدب', 'جدب المكان جدوبة فهو جدب. وأجدب القوم والأرض والسنة. والجادب: الكاذب، لم أسمع له فعلا، والجادب: العاتب. وجدب عمر السمر أي ذمه وعابه، قال ذو الرمة: فيا لك من خد أسيل ومنطق ... رخيم ومن خلق تعلل جادبه 1'),
(2214, 'دجب', 'دجب', 'دجب', 'الدجوب: جويلق يكون مع المرأة في السفر خفيف.'),
(2215, 'دبج', 'دبج', 'دبج', 'الديباج أصوب من الديباج. وديباجة الوجه حسنه وماؤه. ورجل مدبج: قبيح الرأس والخلقة في موق. والمدبج: ضرب من الهام، وضرب من طير الماء يقال له: أغثر 1 مدبج الرأس قبيح الهامه ... يكون في الرأس مع النحامة 2 وديباجة الشعر أول قصيدة يقولها الشاعر.'),
(2216, 'بجد', 'بجد', 'بجد', 'البجاد كساء، ويقال للدليل الهادي الذي كأنه ولد ونشأ بها: هو ابن بجدتها، والنون لغة. وقال في البجاد: أو الشيء الملفف في البجاد 3'),
(2217, 'جدم', 'جدم', 'جدم', 'يقال للفرس: اجدم وأقدم إذا هيج ليمضي، وأقدم أجودهما.'),
(2218, 'دجم', 'دجم', 'دجم', 'يقال انقشعت دجم الأباطيل، وأنه لقي دجم العشق والهوى أي في غمراته وظلمه.'),
(2219, 'مجد', 'مجد', 'مجد', 'المجد: نيل الشرف، وقد مجد الرجل، ومجد: لغتان، وأمجده كرم فعاله. قال زائدة: أحسبنا وأمجدنا والله المجيد. وتمجد (بفعاله) ، ومجده خلقه تمجيدا أي تعظيما. ومجدت الإبل مجودا إذا نالت من الكلاء قريبا من الشبع وعرف ذلك في أجسامها، وأمجد القوم إبلهم، وذلك في أول الربيع أي أحسنوا رعيها 1 وإسمانها.'),
(2220, 'جمد', 'جمد', 'جمد', 'جمد الماء يجمد جمودا. ويقال: لك جامد هذا المال وذائبه، والذائب الظاهر والجامد الغائب الباطن. ويقال: ذاب لفلان عليك حق أي وجب وظهر. ومخة جامدة أي صلبة. ورجل جامد العين: قل دمعه. وسنة جماد: جامدة لا كلأ فيها ولا خصب. وعين جماد: لا دمع فيها. والجمد: الماء الجامد. وأجمد القوم: قل خيرهم وبخلوا. والجمد من أعلام الأرض كالنشز المرتفع، ويجمع على أجماد وجماد. والجماديان: اسمان معرفة لشهرين، فإذا أضفت 1 قلت: شهرا جمادى، وشهر جمادى'),
(2221, 'دمج', 'دمج', 'دمج', 'دمجت الأرنب تدمج في عدوها، وهو سرعة تقارب القوائم. ومتن مدمج وأعضاء مدمجة كأنها أدرجت وملست كما تدمج الماشطة مشطة المرأة إذا ضفرت ذوائبها. وكل ضفيرة منها على حيالها تسمى دمجا واحدا. ويقال: دمج في بيته أي دخل، والدموج الدخول. وقال في إدماج الأعضاء: حمراء في حاركها 2 دموج'),
(2222, 'تجر', 'تجر', 'تجر', 'والتجر والتجار جماعة التاجر، وقد تجر تجارة وأرض متجرة: يتجر إليها.'),
(2223, 'ترج', 'ترج', 'ترج', 'الترنج لغة في الأترج، والرنز لغة في الأرز.'),
(2224, 'رتج', 'رتج', 'رتج', 'الرتاج: الباب المغلق، وارتجت الباب: أغلقته إغلاقا وثيقا. وأرتج على فلان إذا أراد قولا وشعرا فلم يصل إلى تمامه. وأرتج عليه في المنطق. وفي كلامه رتج أي تتعتع وإعياء.'),
(2225, 'جتل', 'جتل', 'جتل', 'الجتل 1 القطع قال: وآخر مجتال بغير قرابة ... هنيدة لم يمنن عليك اجتيالها 2'),
(2226, 'تلج', 'تلج', 'تلج', 'التالج لغة في الدالج، والتولج لغة في الدولج.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2227, 'نتج', 'نتج', 'نتج', 'النتاج: اسم يجمع وضع الغنم والبهائم. وإذا ولي الرجل ناقة ماخضا ونتاجها حتى تضع، قيل: نتجها نتجا ونتاجا، ومنه يقال: نتجت الناقة، ولا يقال: نتجت الشاة إلا أن يكون إنسان يلي نتاجها، ولكن يقال: نتج القوم إذا وضعت إبلهم وشاؤهم. وقد يقال: أنتجت الناقة أي وضعت. وفرس نتوج وأتان نتوج أي حامل في بطنها ولد قد استبان، وبها نتاج أي حمل. وبعضهم يقول للنتوج من الدواب قد نتجت في معنى حملت ليس بعام وأنكره زائدة. والريح تنتج السحاب إذا مرت به حتى يجري قطره. وفي المثل: إن العجز والتواني تزاوجا فأنتجا الفقر.'),
(2228, 'جبت', 'جبت', 'جبت', 'الجبت 1 يفسر الكاهن، ويفسر الساحر.'),
(2229, 'تجب', 'تجب', 'تجب', 'التجاب من حجارة الفضة: ما أذيب مرة، وقد بقيت فيها فضة والواحدة تجابة.'),
(2230, 'جذر', 'جذر', 'جذر', 'الجذر أصل اللسان وأصل الذكر، وأصل كل شيء. وأصل الحساب الذي يقال: عشرة في عشرة أو كذا في كذا، نقول: ما جذره؟ أي ما مبلغ تمامه فتقول: عشرة في عشرة، مائة، (وخمسة في خمسة، خمسة وعشرون، فجذر مائة عشرة، وجذر خمسة وعشرين خمسة) 2 . ويقال لسقي الماء إذا سقيت الدبرة: قد بلغ الماء جذره. ويقال للرجل القصير الغليظ: المجذر. والغربة تسمى الجذرة، وهي شجرة يدبغ بها. والذغرة تسمى الجذرة لسوادها.'),
(2231, 'جرذ', 'جرذ', 'جرذ', 'الجرذ: داء يأخذ في قوائم الدواب، وبرذون جرذ. والجرذ: اسم الذكر من الفأر، والجميع الجرذان. قال زائدة: الجرذان: أكبر من الفأرة. والمجرذ والمجرس والمضرس والمقتل: المجرب للأمور.'),
(2232, 'جذل', 'جذل', 'جذل', 'الجذل: انتصاب الحمار الوحشي ونحوه (ناصبا) 1 عنقه، والفعل جذل يجذل جذولا، وجذلت به جذولا. والجذل: الفرح. والجذل: أصل كل شجرة حين يذهب رأسها، وصار الشيء 2 إلى جذله أي أصله. وقوله: أنا جذيلها المحكك، وعذيقها المرجب، وحجيرها المأوب، فإنه تصغير جذل، وهو عود ينصب للإبل الجربى تحتك به من الجرب، وأراد أنه يستشفى برأيه كاستشفاء الإبل الجربى بالاحتكاك بذلك العود. وقيل: المحكك الذي حككه الدهر حتى أحكمه. والجذل: إحكام الدروع 1 .'),
(2233, 'جلذ', 'جلذ', 'جلذ', 'الجلذي: الشديد من الأمر. والجلزي: الحجر، والجميع جلاذي. والجلذية: الشديدة من النوق.'),
(2234, 'نجذ', 'نجذ', 'نجذ', 'النجذ: شدة العض بالناجذ، وهو السن بين الأنياب والأضراس، وقول العرب: بدت نواجذه إذا ظهر ذلك منه ضحكا أو غضبا. ويقال: رجل منجذ أي مجرب مضرس، واشتقاقه أن ناجذة الدهر عضته.'),
(2235, 'جذب', 'جذب', 'جذب', 'الجذب مدك الشيء، ومنه التجاذب، وانجذبوا في سيرهم، وانجذب بهم سير. وإذا خطب الرجل امرأة فردته، قيل: جذبته وجبذته، كأنه من قولك: جاذبته فجذبته أي غلبته، فبان منها مغلوبا. والجذب: جمار النخل، الواحدة جذبة، وهي الشحمة تكون في رأس النخلة تكشط عنها فتؤكل. والجذبة: البعد، وفلان منا جذبة أي بعيد.'),
(2236, 'جبذ', 'جبذ', 'جبذ', 'الجبذ لغة في الجذب.'),
(2237, 'بذج', 'بذج', 'بذج', 'البذج: الحمل، ويجمع على البذجان، وهو أضعف ما يكون، قال: وإن تجع تأكل عتودا أو بذج 1'),
(2238, 'جذم', 'جذم', 'جذم', 'الجذم: سرعة القطع. والجذم: مصدر الأجذم اليد، وهو الذي ذهبت أصابع كفيه. ويقال: ما الذي جذم يديه؟ وما الذي أجذمه حتى جذم؟ 2 والجذوم: المنتصب القائم. وأجذمت المحجة: ارتفعت. والجاذم: الذي يلي القطع، ويقال: هو المجذم. والمجذوم: الذي ينزل به الجذم، والاسم الجذام. والإجذام: الإقلاع عن الشيء. وجذام اسم حي من اليمن، يقال: هم من بني أسد، من خزيمة. والجذمة: القطعة تبقى من الشيء يقطع طرفه ويبقى جذمه. وجذم القوم: أصلهم. والجذمة والجذمة: القطعة.'),
(2239, 'ثجر', 'ثجر', 'ثجر', 'الثجير: ما عصر من العنب، خرجت سلافته وبقيت بقيته، وهي الثجير. ويقال: الثجير: تفل البسر يخلط بالتمر فينتبذ. وفي الحديث: لا تثجروا. والثجرة من الوادي حيث يتفرق الماء في سعة من الأرض. وثجرة الحشا: مجتمع أعلى السحر بقصب الرئة. والثجر: سهام غلاظ الأصول عراض 1 .'),
(2240, 'جرث', 'جرث', 'جرث', 'الجريث: ضرب من السمك، قل من يأكله.'),
(2241, 'جثل', 'جثل', 'جثل', 'الجثل من الشعر: أشده سوادا وغلظا، ويقال: الجثل الكثير، وهو جثل بين الجثولة والجثالة. والجثلة: النملة السوداء. واجثال النبات إذا التف وطال وغلظ.'),
(2242, 'ثلج', 'ثلج', 'ثلج', 'الثلج، ويقال منه ثلجنا أي أصابنا ثلج. وثلج الرجل إذا برد قلبه عن شيء، وإذا فرح أيضا فقد ثلج. وحفر فأثلج إذا ظهر الندى ولم يخرج الماء 2 . وأثلج إذا شفي من خبر، وتقول: أثلجني أي اشفني مما عندك.'),
(2243, 'ثجل', 'ثجل', 'ثجل', 'رجل أثجل أي عظيم البطن. ومصدره الثجل.'),
(2244, 'جنث', 'جنث', 'جنث', 'الجنث أصل الشجرة، وهو العرق المستقيم أرومته في الأضمار، ويقال: بل هو من ساق الشجرة ما كان في الأرض فوق العروق. والجنثي: الزراد، منسوب إلى شيء قد جهل، قال لبيد: أحكم الجنثي عن عوراتها ... كل حرباء إذا أكره صل 1'),
(2245, 'نجث', 'نجث', 'نجث', 'النجيث الهدف سمي به لانتصابه واستقباله. والاستنجاث: التصدي للشيء والإقبال عليه والولوع به. والنجيث: الخبر السوء، وتقول: إن هذا لنجيث أي خبر سوء.'),
(2246, 'ثبج', 'ثبج', 'ثبج', 'الثبج أعلى الظهر من كل شيء. والتثبيج: التخليط من كل شيء، [ومنه] كتاب مثبج.'),
(2247, 'جثم', 'جثم', 'جثم', 'جثم يجثم جثوما أي لزم مكانا لا يبرح. وفي بعض الوصف إذا شرب على العسل، جثم على المعدة ثم قذف بالداء. والجاثوم: الكابوس أي الديثان. والجثامة: الرجل البليد، والسيد الحليم. والجثمان بمنزلة الجسمان، جامع لكل شيء، تريد جسمه وألواحه والجثوم للطير كالربوض للغنم. ونهي عن المجثمة، وهي المصبورة من الطير والأرانب وأشباههما مما يجثم بالأرض إذا لزمتها ولبدت عليها، فإن حبسها إنسان قيل: جثمها فهي مجثمة أي محبوسة، فإن فعلت هي، قيل: جثمت فهي جاثمة.'),
(2248, 'ثجم', 'ثجم', 'ثجم', 'الإثجام سرعة المطر. والثجم: شبه الصرف عن الشيء. قال زائدة: أثجم، واسجم واحد.'),
(2249, 'جرل', 'جرل', 'جرل', 'مكان جرل: صلب غليظ خشن، قال: فلو علوه جرلا هراسا ... لتركوه دمثا دهاسا 1 والجرول من الجبال مواضع تكون فيها الحجارة، قدر ما يقل الرجل، كبيرة خشنة، يقال: جبل كثير الجراول. والجرول: اسم لبعض السباع. وجرول بن مجاشع الذي يقول: مكره أخوك لا بطل. والجريال: اللون الأحمر.'),
(2250, 'رجل', 'رجل', 'رجل', 'هذا رجل أي ليس بأنثى، وهذا رجل أي كامل، ولغة طيء: هذه رجلة وهذا رجل، وهذا رجل أي راجل، وهي رجلة أي راجلة، وقال في الرجلة التي هي المرأة: خرقوا جيب فتاتهم ... لم يبالوا سوءة الرجله 2 وقال في الراجلة: فإن يك قولهم صادقا ... كانت إليكم نسائي رجالا 1 أي رواجلا. وهذا أرجل الرجلين أي فيه رجولية ليست في الآخر. والرجل: جماعة الراجل كالركب الراكب. وهم الرجالة والرجال، قال: وظهر تنوفة حدباء يمشي ... بها الرجال خائفة سراعا 2 وقد جاء في الشعر الرجلة يريد به الرجالة والرجلة: منبت 3 العرفج الكثير في روضة واحدة. والتراجيل: الكرفس بلغة العجم، وهو اسم سوادي من بقول البساتين. ورجل القوس سيتها السفلى، ويدها سيتها العليا. وفلان قائم على رجل إذا جد في أمر حزبه. والرجل: القطيع من الجراد ونحوه من الخلق. والرجلة: نجابة الرجيل 4 من الدواب والإبل، وهو الصبور على طول السير، ولم أسمع منه فعلا إلا في النعوت خاصة، ناقة رجيلة، وحمار رجيل، ورجل رجيل أي مشاء. وارتجل الرجل: ركب رجليه في صاحبه ومضى، ويقال: ارتجل ما ارتجلت أي اركب ما ركبت من الأمر. وارتجل الرجل زنده إذا أخذها تحت رجله. وترجل القوم: نزلوا عن دوابهم في الحرب للقتال. ويقال: حملك الله عن الرجلة ومن الرجلة. والرجلة هاهنا فعل الرجل الذي لا دابة له. والرجلة أيضا مصدر الأرجل من الدواب بإحدى رجليه بياض، ويقال به رجلة وترجيل، يتشاءم به إلا أن يكون فيه بياض في موضع غير ذلك فيقال: مطلق. وتصغير رجل: رجيل، والعامة تقول: رويجل صدق ورويجل سوء، يرجعون إلى الراجل لأن اشتقاقه منه كما أن العجل من العاجل والحذر من الحاذر. وارتجل الكلام. وترجل النهار: ارتفع. ورجل رجل بين الرجل أي شعره رجل. وحرة رجلاء أي مستوية بالأرض، كثيرة الحجارة. والأرجل [من الرجال] 1 : العظيم الرجل. وترجلت البئر أي نزلتها من غير تدل. والرجل جبار وهو أن تنفحه الدابة ليس على راكبها غرم، وهو هدر. وأرجلته: أخذت دابته فجعلته راجلا، كما قال: فقالت لك الويلات إنك مرجلي 2'),
(2251, 'جرن', 'جرن', 'جرن', 'الجران: مقدم العنق من مذبح البعير أي منحره فإذا مد عنقه، قيل: ألقى جرانه بالأرض، قال طرفة: وأجرنة لزت بدأي منضد 3 جمعه لسعته. والجرين: موضع البيدر بلغة اليمن، وعامتهم بكسر الجيم، وناس يسمون الموضع الذي يجمعون فيه التمر جرينا، والجمع الجرن. والجارن: ولد الحية وما لان من أولاد الأفاعي. وأديم جارن: غليظ مدبوغ بالسلم في قول لبيد:'),
(2252, 'جرف', 'جرف', 'جرف', 'الجرف: اجترافك الشيء عن وجه الأرض، حتى يقال: كانت (المرأة) 1 ذات لثة فاجترفها الطبيب أي استحاها عن الأسنان وقطعها. والطاعون الجارف نزل بأهل العراق وجرفهم تجريفا 2 فسمي جارفا. والجارف: شؤم أو بلية تجترف مال القوم. ورجل مجرف: جرفه الدهر أي اجتاح ماله فأفقره، قال:'),
(2253, 'جرب', 'جرب', 'جرب', 'الجرب معروف. والجرباء من السماء: الناحية التي لا يدور فيها فلك الشمس والقمر. وأرض جرباء: مقحوطة لا شيء فيها. وجرب البعير يجرب جربا، فهو جرب وأجرب. والجربياء: شمال باردة. قال أبو الدقيش: إنما جربياؤها بردها، فهمز. والجريب من الأرض نصف الفجان 2 ، والجمع أجربة. والجريب: الوادي، والجريب مكيال، وهو أربعة أقفزة. والمجرب: الذي بلي في الحروب والشدائد. والمجرب: الذي جرب الأمور وعرفها، والمصدر: التجريب والتجربة. والجورب: لفافة الرجل. والجراب: وعاء يوعى فيه 1 ، وهو من إهاب الشاء، والجميع جرب (وجراب البئر: جوفها من أولها إلى آخرها) 2 .'),
(2254, 'رجب', 'رجب', 'رجب', '(رجب شهر) 3 ، وهذا رجب، فإذا ضموا إليه شعبان فهما الرجبان. وكانت العرب ترجب، وكان ذلك لهم نسكا وذبائح في رجب. والرجب والرجبة، والجميع الرجاب، وهو شيء من وصف الأدوية، وفي نسخة: الأردية. والراجبة: ما بين البرجمتين من كل إصبع، ومن السلامى: ما بين المفصلين. وراجبة 4 الطائر: الإصبع التي تلي الدائرة من الجانبين الوحشيين من الرجلين. والرجب: الحياء والعفو، قال: فغيرك يستحيي وغيرك يرجب 1 وتقول: رجبته أي هبته مرجبا ومهابا. وترجيب النخلة: أن توضع أعذاقها على سعفها، ثم تضم بالخوص كي لا تنفضها الريح، وقد يقال أيضا: هو أن يوضع الشوك حول العذوق لئلا يدنو منها آكل. ويقال: أصل الترجيب أن تميل النخلة فتدعم بالحجارة ونحوها. وأما قوله: كأن أعناقها أنصاب ترجيب 2 فإنه شبه أعناق الخيل بحجارة تنصب فيهراق عندها دماء النسائك في رجب. وبعض يقول: شبهها بالنخيل المرجبة، والأول أعرف. والأرجاب: الأمعاء. ويقال: المرجبة المقلاع بالعبرانية.'),
(2255, 'برج', 'برج', 'برج', 'البرج واحد من بروج الفلك، وهو اثنا عشر برجا. وبرج سور المدينة والحصن: بيوت تبنى على السور، وتسمى البيوت تبنى على أركان القصر برجا. وثوب مبرج: صور تغيه تصاوير كبروج السور، قال العجاج: فقد لبسنا وشيه المبرجا 1 والبرج: سعة بياض العين مع حسن الحدقة. وإذا أبدت المرأة محاسن جيدها ووجهها، قيل: قد تبرجت، ومع ذلك تري من عينيها حسن نظر. وحساب البرجان، (وهو قولك) 2 : ما جداء كذا في كذا، وما جذر كذا وكذا، فجداؤه: مبلغه، وجذره أصله الذي يضرب بعضه في بعض، وجملته البرجان. يقال: ما جذر مائة؟ فيقال: عشرة. ويقال: ما جداء عشرة في عشرة؟ فيقال: مائة. والبارجة: سفينة من سفن البحر تتخذ للقتال.'),
(2256, 'جبر', 'جبر', 'جبر', 'الجبر: الاسم، وهو أن تجبر إنسانا على ما لا يريد وتكرهة جبرية على كذا. وأجبر القاضي على تسليم ما قضى عليه. والجبر: أن تجبر كسرا، وتقول: جبرته فجبر، قال: قد جبر الدين الإله فجبر 1 وجبرت فلانا فاجتبر أي نزلت به فاقة فأحسنت إليه. واستجبرته إذا كان ذلك منك بتعاهد حتى تبلغ غاية الجبر، كقولك: لأستنصرنك ثم لأجبرنك أي لأديننك 2 ثم لأجبرنك، كقوله: من عال منا بعدها فلا اجتبر 3 وتقول: أصابت فلانا مصيبة لا يجتبرها، أي لا مجبر لها. والجبارة: الخشبة توضع على الكسر حتى ينجبر العظم، والجميع الجبائر. والجبارة: دستيقة المرأة من الحلي، قال: فتناولت كفها ... واتقته بالجبائر 4 والجبار: اسم يوم الثلاثاء في الجاهلية الجهلاء. والجبار من الأرش: ما لا يهدر، والأرش: الدية وفي الحديث: العجماء جبار 1 أي ما أصاب الدابة فهو هدر. والله- تبارك وتعالى-: الجبار العزيز أي قهر خلقه، فلا يملكون منه أمرا، وله التجبر وهو التعظم. ولله الجبرية والجبروت. والجبروة لغة في الجبروت. وفي الحديث: ما كانت نبوة إلا تناسخها ملك جبرية، أي إلا تجبرت الملوك. والجبار: العاتي على ربه، القتال لرعيته. والجبار من الناس: العظيم في نفسه الذي لا يقبل موعظة أحد. وقد كانوا يعابثون امرأة سائلة فكانت تأبى إلا أن تستعصي عليهم، وتجيبهم بغير ما يريدون، فقال النبي- صلى الله عليه وسلم-: دعوها فإنها جبارة وقلب الجبار الذي قد دخله الكبر لا يقبل موعظة. والجبار من النخل: الذي قد بلغ غاية الطول في الفناء، وحمل عليه كله، وهو دون السحوق من طول النخلة، قال: نسيل دنا جبارها من محلم 2'),
(2257, 'بجر', 'بجر', 'بجر', 'البجرة: السرة الناتئة، وصاحبها أبجر، وقد بجر بجرا وبجرة. وقد تسمى سرة البعير بجرة عظمت أم لم تعظم. والبجر: الأمر العظيم، [ويقال] : جئت بأمر بجر وداهية نكر، وقال: عجبت من امرأة حصان رأيتها ... لها ولد من زوجها وهي عاقر فقلت لها: بجرا، فقالت: مجيبتي ... أتعجب من هذا ولي زوج آخر 1 يعني: زوجا من الحمام. والبجري، والبجاري جميعها من دواهي الدهر'),
(2258, 'جرم', 'جرم', 'جرم', 'أرض جرم، وأرض صرد دخيلان مستعملان في الحر والبرد. والجرم، ألواح الجسد وجثمانه. ورجل جريم وامرأة جريمة أي ذات جرم أي جسم. وجرم الصوت: جهارته، تقول: ما عرفته إلا بجرم صوته. وفلان له جريمة أي جرم، وهو مصدر الجارم الذي يجرم على نفسه وقومه شرا، وهو الجارم، قال الشاعر: وإن جار لهم جرمت يداه ... وحوله البلاء عن النعيم 2 والجرم: الذنب، وفعله الإجرام، والمجرم: المذنب، والجارم: الجاني، قال: ولا الجارم الجاني عليهم بمسلم 1 ولا جرم يجري مجرى لا بد، ويفسر حقا. وجرم: قبيلة من اليمن. وأقمت عنده حولا مجرما، أي حولا تاما حتى انقضى، وقال أبو طالب: شهورا وأياما علينا مجرما 2 وجرمنا هذه السنة أي خرجنا منها، وتجرمت السنة والشتاء والصيف، قال الشاعر: دمن تجرم بعد عهد أنيسها ... حجج خلون حلالها وحرامها 3'),
(2259, 'رجم', 'رجم', 'رجم', 'الرجم في القرآن القتل في شأن نوح- عليه السلام-. والرجم: اسم لما يرجم به الشيء، والجميع الرجوم، وهي الحجارة. والرجوم: التي ترمى بها الشياطين، والشيطان رجيم مرجوم ملعون. والرجم: الرمي بالحجارة، والرجم: القذف بالغيب وبالظن، ومنه قوله تعالى: لأرجمنك واهجرني مليا 1 أي لأقولن فيك ما تكره. والرجم: القبر ويجمع على أرجام. والرجمة: حجارة مجموعة كأنها قبور عاد، وتجمع رجاما، ورجمت القبر: جعلت فوقه رجمة. والرجامان: خشبتان تنصبان على رأس البئر ينصب القعر ونحوه من المساقي، وقول زهير: وما هو عنها بالحديث المرجم 2 أي قوله بالغيب والظن. ورجل مرجم: مدافع عن حسبه ونسبه في الحرب. وبعير مرجم: يرجم الأرض بأخفافه رجما، وهو الثقيل المشي من غير بطء.'),
(2260, 'مرج', 'مرج', 'مرج', 'المرج: أرض واسعة فيها نبت كثير تمرج فيها الدواب، قال العجاج: رعى بها مرج ربيع ممرجا 3 وقوله تعالى: مرج البحرين يلتقيان 4 أي لاقى بين البحر العذب والملح قد مرجا فالتقيا، لا يختلط أحدهما بالآخر. والمارج من النار: الشعلة الساطعة، ذات لهب شديد، ومنه قوله تعالى: وخلق الجان من مارج من نار 1 . وأمر مريج أي ملتبس قد مرج مرجا 2 وغصن مريج: قد التبست شناغيبه، قال: فجالت فالتمست به حشاها ... فخر كأنه خوط مريج 3 وفي الحديث: قد مرجت عهودهم وأمرجوها أي لم يفوا بها وخلطوها.'),
(2261, 'رمج', 'رمج', 'رمج', 'الرامج: الملواح الذي تصاد به الصقورة ونحوها من جوارح الطير. والترميج: إفساد السطور بعد كتابتها، وكذلك تقول: رمجه بالتراب حتى يفسده.'),
(2262, 'جمر', 'جمر', 'جمر', 'الجمر: المتقد، فإذا برد فهو فحم. والمجمر قد تؤنث، وهي التي تدخن بها الثياب. وثوب مجمر إذا دخن عليه. ورجل جامر أي يلي ذلك، من غير أن يقال: جمر، قال: وريح يلنجوج يذكيه جامره 1 والتجمير: ترك الجند في نحر العدو فلا يقفلون، وقد نهي أن يجمر غزاة المسلمين في ثغور المشركين. والجمرة: كل قوم يصيرون إلى قتال من قاتلهم لا يخالفون أحدا ولا ينضمون إلى أحد، وتكون القبيلة نفسها جمرة تصبر لمقارعة القبائل، كما صبرت عبس لقيس كلها. وبلغنا أن عمر بن الخطاب سأل الحطيئة عن ذاك، فقال: يا أمير المؤمنين كنا ألف فارس كأننا ذهبة حمراء لا تستجمر ولا تحالف. وبعض الناس يقول: كانت القبيلة إذا اجتمع فيها ثلاثمائة فارس صارت جمرة. والجمرة: المرماة الواحدة من جمار المناسك، وهي ثلاث جمرات، وكل جمرة ترمى بسبع حصبات، مع كل حصاة تكبيره. وحافر مجمر، ومنسم مجمر، وهو الذي نكبته الحجارة وصلب. وأجمر البعير إجمارا أي أسرع، قال لبيد: وإذا حركت غرزي أجمرت ... أو قرابي عدو جون قد أبل 2 والجمار: شحم النخل الذي في قمة رأسه، تقطع قمته ثم يكشط عن جمارة في جوفها بيضاء كأنها قطعة سنام ضخمة، رخصة تتفتت بالفم، تؤكل بالعسل. والكافور يخرج من جوف الجمار بين مشق السعفتين، وهو الكفرى. والاستجمار: استنجاء بالحجارة. وشعر مجمر أي ملبد. وابن جمير: الليلة التي لا يطلع فيها القمر.'),
(2263, 'مجر', 'مجر', 'مجر', 'المجر: الدهم، وهم قوم في حرب عليهم السلاح، قال: جئنا بدهم يدحر الدهوما ... مجر كأن فوقه النجوما 1 وقيل للجيش الضخم: مجر. وشاة مجار إذا حملت فقل ما تسلم أن يعظم بطنها فتهزل فترمي به. وأمجرت فهي ممجر. والمجر: بيع المضامين والملاقيح، والفعل منه المماجرة. والمجار: العقال. ويقال: أمجرت في البيع إمجارا، والملاقيح: الحوامل، والمضامين: ما في الأصلاب، والواحد ملقوح ومضمون.'),
(2264, 'جلن', 'جلن', 'جلن', 'جلن: حكاية صوت باب ذي مصراعين فيرد أحدهما فيقول: جلن، ويرد الآخر فيقول: بلق، قال: وتسمع في الحالين منه جلن بلق 1'),
(2265, 'لجن', 'لجن', 'لجن', 'اللجن: الخبط الملجون بخبط الورق من الشجر، ثم يخلط بالدقيق أو الشعير فيعلف للإبل، وكل ورق أو نحوه لجين ملجون حتى آس الغسلة. وناقة لجون: بينة اللجان، وهي كالحرون من الدواب. واللجين: الفضة.'),
(2266, 'نجل', 'نجل', 'نجل', 'النجل: النسل، وإنما ينسب إلى الفحل، والنسل ينسب إلى كل. وفحل ناجل: كريم النجل كثيره، (وأنشد: فزوجوه ماجدا أعراقها وانتجلوا ... من خير فحل ينتجل) 2 والنجل: رميك بالشيء، والناقة تنجل الحصى بمناسمها أي ترمي به. والمنجل: ما يقضب به العود من الشجر، فينجل به أي يرمى والنجيل: ضرب من ورق الشجر، من الحمض، والجميع النجل. وطعنة نجلاء: واسعة. ويقال للأرض ينز منها الماء: استنجلت. وفي الأرض أنجال أي عيون يخرج منها الماء. والنجل: الدلو. والأسد أنجل. (والنجل: سعة العين مع حسن، يقال: رجل أنجل وعين نجلاء وسنان منجل، إذا كان يوسع خرق الطعنة، وقال أبو النجم: سنانها مثل القدامى منجل 1'),
(2267, 'لنج', 'لنج', 'لنج', 'الألنجوج واليلنجوج: عود جيد، قال: ريح يلنجوج وأهضام 2'),
(2268, 'لفج', 'لفج', 'لفج', 'الملفج: المعدم، قال رؤبة: أحسابهم في العسر والإلفاج ... شيبت بعذب طيب المزاج 1'),
(2269, 'جلف', 'جلف', 'جلف', 'الجلف أخفى من الجرف وأشد استئصالا، تقول: جلفت ظفره عن إصبعه. ورجل جلف جاف في خلقته وأخلاقه. ورجل مجلف: قد جلفه الدهر إذا أتى على ماله، ومجرف أيضا. والجلائف: السنون القحطة، واحدتها جليفة. والجلف [من النخل] : الذكر الذي يلقح بطلعه ويقال له: الفحال. والجلف: كل ظرف ووعاء.'),
(2270, 'لجف', 'لجف', 'لجف', 'اللجف: الحفر في جنب الكناس ونحوه، والاسم: اللجف. واللجاف: ما أشرف على الغار من صخرة أو غيره ناتىء من الجبل، وربما جعل ذلك فوق الباب. واللجف أيضا: ملجأ السيل وهو محبسه.'),
(2271, 'فلج', 'فلج', 'فلج', 'الفلج: الماء الجاري من العين ونحوه، وعين فلج، وماء فلج، قال العجاج: تذكرا عينا رواء فلجا 1 والفلج في الأسنان: تباعد ما بين الثنايا والرباعيات، وصاحبه أفلج، فإن تكلف فهو التفليج. وأما الفرق فسعة ما بين الثنيتين خاصة. والفلج في الرجلين: تباعد ما بين القدمين آخرا. وفلاليج السواد: قراها، الواحدة فلوجة. والفالج: الجمل ذو السنامين الضخم، من المكرانية. والفالج: مكيال ضخم. وفلجت الشيء: قسمته. والفالج في القمار: القامر. والفالج: ريح تأخذ الإنسان، يرتعش منها، وصاحبه مفلوج. والفلج: الظفر بمن تخاصمه. وفلجت حجتك، وفلجت على صاحبك بحقك. وأمر مفلج: ليس بمستقيم. والأفلج: الذي في يديه اعوجاج، والأفحج: الذي في رجليه اعوجاج. والفليجة: الشقة من بيوت الأعراب، قال: تشتى غير مشتمل بثوب ... سوى خل الفليجة بالخلال 1 وفلجت الجزية على القوم: فرضتها عليهم. والفلوج: الكاتب القارىء، يفلج الكتب أي يكتبها، قال ابن مقبل 2 : توضحن في علياء قفر كأنها ... صحائف فلوج تعرضن تاليا 3'),
(2272, 'فجل', 'فجل', 'فجل', 'الفجل: أرومة نبات يكون لآكله جشاء خبيث، (وإياه عنى بقوله) 4 : وهو مجهز السفينة (يهجو رجلا) 5 : أشبه شيء بجشاء الفجل ... ثقلا على ثقل وأي ثقل 1'),
(2273, 'جفل', 'جفل', 'جفل', 'جفلت اللحم عن العظم، والشحم عن الجلد، والطين عن الأرض. والريح تجفل السحاب الخفيف من الجهام، أي تستخفه فتمضي به، واسم ذلك السحاب الجفل. وقال قائل: إني لآتي البحر فأجده قد جفل سمكا كثيرا، أي ألقاه على الساحل. والجفال من السحاب ومن الكلاء: ما جف وانطرد للريح. والجفال والجفول: سرعة عدو، وجفل الظليم، وأجفل أجود، قال: إذا الحر جفل صيرانها 2 وانجفل الليل والظل: ذهب، (وانجفل القوم انجفالا، إذا هربوا بسرعة، وانجفلت الشجرة إذا هبت بها ريح شديدة فقعرتها) 3 والجفالة من الناس: جماعة جاءوا أو ذهبوا. والجفال: الشعر الكثير، قال ذو الرمة: على المتنين منسدلا جفالا 1 والجفال من الصوف: ما طال وحسن ودق. يقال: عليه جفالة من الصوف. والإجفيل: الجبان. (وجفل الفزع الإبل تجفيلا، فجفلت جفولا، إذا شردت نادة، وجفلت النعامة) 2'),
(2274, 'جلب', 'جلب', 'جلب', 'الجلب: ما يجلب من السبي أو الغنم، والجمع أجلاب، والفعل يجلبون. وعبد جليب، وعبيد 3 جلباء، إذا كانوا جلبوا من أيامهم وسنتهم. والجلب والجلبة في جماعات الناس، والفعل: أجلبوا من الصياح ونحوه. والجلوبة: ما يجلب للبيع نحو الناب والفحل والقلوص، وأما كرام الإناث والفحولة التي تنتسل فليست من الجلوبة. ويقال لصاحب الإبل: هل في إبلك جلوبة؟ أي شيء جلبته للبيع. وفي الحديث: لا جلب في الإسلام. اختلفوا فيه فقيل: لا جلب في جري الخيل، وقيل: لا يستقبل الجلب في الشراء، وقيل: هو أن يجلب المصدق غنم القوم أي يجمعها عنده، وإنما ينبغي أن يأتي أفنيتهم فيصدقها هناك. والجلبة: القرفة التي تنتشر على اليد عند همومها بالبرء. وأجلبت القرحة، فهي مجلبة وجالبة. وقروح جوالب، قال: جأب ترى بليته كدوحا ... مجلبة في الجلد أو جروحا 1 وقروح جلب مثله، قال: عافاك ربي مل قروح الجلب 2 والجلبة: أن يجلب جلد الإنسان على عظمه في السنة الشديدة. وجلب الرحل: نقش خشب الرحل وأحناؤه، وما يؤسر به، ويشد سوى صنقه وأنساعه، قال: كأن جلب الرحل والقرطاط 3 والجلبان: الملك، الواحدة بالهاء، وهو حب أغبر أكدر على لون الماش، (إلا أنه أشد كدرة منه وأعظم جرما، يطبخ) 1 . والجالبة والجوالب من شدائد الدهر: حالات تجيء بآفات وتجلبها. والجلباب: ثوب أوسع من الخمار دون الرداء، تغطي به المرأة رأسها وصدرها، قال: والعيش داج كنفا جلبابه 2 وقال الآخر: مجلبب من سواد الليل جلبابا 3 والجلب والجلب من السحاب تراه كأنه جبل. (والجلبة: العوذة التي يخرز عليها الجلد، وجمعها: الجلب. وقال علقمة يصف فرسا: بغوج لبانه يتم بريمه ... على نفث راق خشية العين مجلب الغوج: الواسع جلد الصدر. والبريم خيط يعقد عليه عوذة، ويتم بريمه أي يطال إطالة لسعة صدره. والمجلب: الذي يجعل العوذة في جلب ثم يخاط على الفرس عن أبي عمرو. والجلبة: الحديدة يرقع بها القدح، وهي حديدة صغيرة. والجلبة في الجبل، إذا تراكم بعض الصخر على بعض، فلم يكن فيه طريق تأخذ فيه الدواب) 4'),
(2275, 'لجب', 'لجب', 'لجب', 'عسكر لجب، واللجب صوته. وسحاب لجب بالرعد، والأمواج كذلك، وبه لجب. وشاة لجبة: قد ولى لبنها، وقد لجبت لجوبة، وهن لجاب. وشياه لجبات، وبعضهم يثقل لأنها نعت لا يذكر جعلوه كالاسم المفرد.'),
(2276, 'بلج', 'بلج', 'بلج', 'البلج والبلجة مصدر الأبلج. والبلجة: اسم من الأبلج، وهو البادي البلدة. ورجل أبلج طليق الوجه بالمعروف، ورجل أبلج أي طلق. وأبلجت الشمس إبلاجا، أنارت وأضاءت. وأبلج الحق فهو مبلج أبلج، (ويقال: انبلج الصبح إذا أضاء) 2 .'),
(2277, 'لبج', 'لبج', 'لبج', 'اللبجة: حديدة ذات شعب، كأنها كف بأصابعها، تنفرج فتوضع في وسطها لحمة، ثم تشد إلى وتد، فإذا قبض عليها الذئب التبجت في خطمه فقبضت عليه وصرعته، والجميع: اللبج. ولبج به الأرض أي ضرب به.'),
(2278, 'بجل', 'بجل', 'بجل', 'بجل أي حسب، قال: ردوا علينا شيخنا ثم بجل 1 وقال لبيد: بجلي الآن من العيش بجل 2 وهو مجزوم لاعتماده على حركة الجيم، ولأنه لا يتمكن في التصريف. ورجل بجال: ذو بجالة وبجلة، وهو الكهل الذي ترى به هيبة وتبجيل وسن، (وأنشد: قامت ولا تنهز حظا واشلا ... قيس تعد السادة البجابلا) 3 فيبجل بذلك. ولا يقال: امرأة بجالة، ورجل باجل، وقد بجل يبجل بجولا، وهو الحسن الجسم، (الخصيب في جسمه) 1 ، وقال: النقد دين، والطعان عاجل ... وأنت بالباب سمين باجل 2 والبجل: البهتان العظيم، (يقال: رميته ببجل) 3 . (وقال أبو دواد الإيادي: أمرؤ القيس بن أروى موليا ... إن رآني لآبوءن بسبد قلت بجلا قلت قولا كاذبا ... إنما يمنعني سيفي ويد 4 وأمر بجل أي عجب. وهذا أمر مبجل أي كاف، قال الكميت: لها الري والصدر المبجل 5 والأبجلان في اليدين: عرقا الأكحلين من لدن المنكب إلى الكف، (وأنشد: عاري الأشاجع لم يبجل أي لم يفصد أبجله) 1 ويقال: الأكحل ما بدا منه في الذراع في المفصد. ويقال: هما الأبجلان من الدواب، والأكحلان من الناس. ويقال: جئت بأمر بجيل أي عظيم منكر. وبجيلة: قبيلة القسري.'),
(2279, 'جبل', 'جبل', 'جبل', 'الجبل: اسم لكل وتد من أوتاد) 2 الأرض إذا عظم وطال من الأعلام والأطوار والشناخيب والأنضاد. فإذا صغر فهو من الأكام والقيران. وجبلة الجبل: تأسيس خلقته التي جبل عليها. وجبلة الأرض: صلابها. وجبلة كل مخلوق: توسه الذي طبع عليه. ويقال للثوب الجيد النسج والغزل والفتل: إنه لجيد الجبلة. وجبلة الوجه: بشرته. ورجل جبل الوجه أي غليظ بشرة الوجه. ورجل جبل الرأس: غليظ جلد الرأس والعظام، قال الراجز: إذا رمينا جبلة الأشد ... بمقذف باق على المرد 1 والجبل: الخلق، جبلهم الله، فهم مجبولون، (وأنشد: بحيث شد الجابل المجابلا 2 أي حيث شد أسر خلقهم. والخلق: الجبلة، وكل أمة مضت فهي جبلة على حدة، وقال تعالى: والجبلة الأولين 3 . وأما الجبل، فمن خفف اللام جعله مثل قبيل وقبل. وجبيل وجبل، وهو الخلق أيضا. ومن قرأ: جبلا 4 فهو على ثقل الجبلة ومعناها واحد. وجبل الإنسان على هذا الأمر، أي طبع عليه. وأجبل القوم، أي صاروا في الجبال، وتجبلوا أي دخلوها. ويقال: والجبل: الشجر اليابس.'),
(2280, 'جلم', 'جلم', 'جلم', 'الجلم: اسم يقع على الجلمين، كالمقراض والمقراضين، والقلم والقلمين. وجلمت الصوف والشعر بالجلم، وقلمت الظفر بالقلم، قال: قيس القلامة مما جز بالقلم 1 وجلمة الشاة والجزور بمنزلة المسلوخة إذا ذهب عنها أكارعها وفضولها 2 .'),
(2281, 'لجم', 'لجم', 'لجم', 'اللجام لجام الدابة. واللجام: ضرب من سمات الإبل، في الخدين إلى صفقتي العنق. والجميع منهما اللجم، والعدد: ألجمة. ويقال: ألجمت الدابة، والقياس في السمة 1 ملجوم، ولم أسمع به، وأحسن منه أن تقول به سمة لجام. واللجم: دابة أصغر من العظاية، وأنشد لعدي بن زيد يصف فرسا: له سبة مثل جحر اللجم 2 وقال رؤبة: يصطحب الحيتان فيه واللجم 3 واللجمة لجمة الوادي، وهي منفرجها، (وهي ناحية منه) . والألجام: ما بين السهل والجدد، وقال الأخطل: ومرت على الألجام ألجام حامر ... يثرن قطا لولا سراهن هجدا 4 (وقال رؤبة: إذا ارتمت أصحانه ولجمه 5'),
(2282, 'ملج', 'ملج', 'ملج', 'الملج: تناول الضرع والثدي بأدنى الفم. وفي الحديث: لا بأس بالاملاجة والاملاجتين 1 وهو أن يتناول الصبي من ثدي أمه ملجة أو ملجتين، شربا يسيرا، ثم تقطع ذلك عنه، فلا يحرم به النكاح، وفيه اختلاف. قال زائدة: اللمجة واللمجتين ولم تعرف الاملاجة'),
(2283, 'لمج', 'لمج', 'لمج', 'اللمج: تناول الحشيش بأدنى الفم، قال لبيد: يلمج البارض لمجا في الندى ... من مرابيع رياض ورجل 2 وتقول: هل عندك شماج أو لماج أكله. وإنه لشمج لمج، ولا يفرد.'),
(2284, 'مجل', 'مجل', 'مجل', 'مجلت يده فهي مجلة، وأمجلها العمل إذا مرنت وصلبت. وكذلك الرهصة تصيب الدابة في حافرها فيشتد ويصلب 3 ، قال رؤبة: رهصا ماجلا 1 والمجل: غدران الماء والبرك. والمجلة: الصحيفة يكتب فيها، قال النابغة: مجلتهم ذات الإله ودينهم ... قويم فما يرجون خير العواقب 2'),
(2285, 'جمل', 'جمل', 'جمل', 'الجمل: يستحق هذا الاسم إذا بزل 3 . وناقة جمالية أي في خلق جمل. وإذا نعتوا شيئا من هذا النحو إلى نعت كثر ما يجيئون به على فعالي نحو صهابي. فأما قوله تعالى: كأنه جمالت صفر 4 فهو الأينق السود من غير أن يفرد الواحد، ولكن يقال لكل طائفة منها جمالة، والجميع جمالات وجمائل. وبعض يقول: أراد جمالا لا نوقا فيها. والجامل: قطيع من الإبل برعائها وأربابها كالبقر والباقر. وجمل البحر: ضرب من السمك. وجميل وجملانة: طائر من الدخاخيل. ومن أمثال العرب: اتخذ فلان الليل جملا إذا سرى كله، أو إذا ركبته ومضيت. (والجميل: طائر شبيه بالعصفور والقنبر والغر، وقال: وصدت غرا أو جميلا آلفا: ... وبرقشا يعلو على معالنا) 1 والجميل: الإهالة المذابة، واسم ذلك الذائب: الجمالة. (والاجتمال: الإدهان بالجميل) 2 . والاجتمال أيضا: أن تشوى لحما، فكلما وكفت إهالته استودقته على خبز 3 ثم أعدته ثانية. والجمال: مصدر الجميل، والفعل منه جمل يجمل. (وقال الله- تعالى-: ولكم فيها جمال حين تريحون وحين تسرحون 4 . أي بهاء وحسن. ويقال: جاملت فلانا مجاملة إذا لم تصف له المودة. وماسحته بالجميل. ويقال: أجملت في الطلب. (والجملة: جماعة كل شيء بكماله من الحساب وغيره) 1 : وأجملت له الحساب والكلام من الجملة. وحساب الجمل: ما قطع على حروف أبي جاد. والجمل: القلس الغليظ. قال مبتكر: الجميل اسم للحر.'),
(2286, 'جنف', 'جنف', 'جنف', 'الجنف: الميل في الكلام، وفي الأمور كلها، تقول: جنف فلان علينا، وأجنف في حكمه، وهو شبيه بالحيف، إلا أن الحيف من الحاكم خاصة، والجنف عام. ومنه قول الله- عز وجل-: فمن خاف من موص جنفا 2 . (وقوله- جل وعز-: غير متجانف لإثم 3 ، أي متمايل متعمد) 4 .'),
(2287, 'نجف', 'نجف', 'نجف', 'النجفة 5 تكون في بطن الوادي، شبه جدار ليس بعريض، له طريق 6 منقاد من بين مستقيم ومعوج، لا يعلوها الماء، وقد تكون في بطن الأرض. ويقال: النجاف أرض مستديرة مشرفة على ما حولها، الواحدة نجفة، قال: رأت هلكا بنجاف الغبيط ... فكادت تجد لذاك الهجار 1 أي العقال. قال: أراه ظل لها ولد ولم يعرف الملك. قال شريح: هلك وهلاك، والغبيط في بلاد بني يربوع، وكل موضع يكون على تلك الصفة حيث كانت فهو غبيط. وقد يقال لإبط 2 الكتيب نجفة الكتيب، وهو الموضع الذي تصفقه الرياح فتنجفه فيصير كأنه جرف منجوف. وقبر منجوف، وهو الذي يحفر في عرضه، وهو غير مضروح. (وغار منجوف: موسع، وأنشد: يفضي إلى جدث كالغار منجوف 3 وإناء منجوف: واسع الأسفل) 4 . ويقال: اللجاف: الباب، والغار: نجاف الباب. ونجاف التيس: جلد يشد بين بطنه والقضيب، فلا يقدر على السفاد، ويقال: تيس منجوف. والنجيف من السهام: العريض النصل. قال زائدة: النجاف: قضف وقور: قطع من الحزن.'),
(2288, 'نفج', 'نفج', 'نفج', 'نفج اليربوع ينفج، (وينفج) 1 نفوجا، وينتفج انتفاجا، وهو أوحى عدوه 2 . وأنفجه الصائد: أثاره من مجثمه ومكمنه. ويقال للصيد وكل شيء ارتفع فقد انتفج، حتى يقال: رجل منتفج الجنبين، وبعير منتفج إذا خرجت خواصره. ورجل نفاج: ذو نفج، يقول ما لا يفعل، ويفتخر بما ليس له ولا فيه، وهو ينفج نفجا. والنفاجة: رقعة للقميص تحت الكم، وهي تلك المرتبة. ونفجت الريح: جاءت بغتة. والنوافج: مؤخرات الضلوع، الواحد نافج ونافجة.'),
(2289, 'فجن', 'فجن', 'فجن', 'الفيجن (والفيجل) : السذاب. وقد أفجن الرجل إذا أدام على أكل السذاب. والفيجن: من نبات الربيع يقتلعها الصبيان فيأكلون أصولها. (والفجانة إناء من صفر، وجمعها: فجاجين. والفجان: مقدار لأهل الشام في أرضيهم) 1'),
(2290, 'جفن', 'جفن', 'جفن', 'الجفن: ضرب من العنب، ويقال: هو نفس الكرم بلغة اليمن. ويقال: الجفن والجفنة: قضيب من الكرم. والجفنة التي للطعام، وجمعها الجفان. والجفن للسيف والعين، وجمعهما جفون. وجفنة: قبيلة من اليمن، ملوك بالشام، قال: أولاد جفنة حول قبر أبيهم ... قبر ابن مارية الأعز الأجلل 2'),
(2291, 'جنب', 'جنب', 'جنب', 'الجنوب جمع الجنب. والجانب والجوانب معروفة. ورجل لين الجانب (والجنب) ، أي سهل القرب ويجيء الجنب في موضع الجانب، قال: الناس جنب والأمير جنب 1 كأنه عدله بجميع الناس. (وقوله- عز وجل- مخبرا عن دعاء إبراهيم إياه: واجنبني وبني أن نعبد الأصنام 2 ، أي نجني) 3 . والجنابان: الناحيتان. والجنبتان: ناحيتا كل شيء كجنبتي العسكر والنهر ونحوهما، والجميع الجنبات. والجنيبة: كل دابة تقاد. وجنبته عن كذا فاجتنب أي تجنبه، قال الله- عز وجل-: واجنبني وبني أن نعبد الأصنام وجنبته أي دفعت عنه مكروها. والجنبة: مصدر الاجتناب. والجنبة: الناحية من كل شيء، كأنه شبه الخلوة من الناس. ورجل ذو جنبة أي ذو اعتزال عن الناس، مجتنب لهم. والمجانب: الذي قاطعك، وقد اجتنب قربك. والجانب: المجتنب الضعيف المحقور، قال العجاج: لا جانب ولا مسقى بالغمر 1 والجنابى: لعبة لهم، يتجانب الغلامان فيعتصم كل واحد من الآخر. ورجل أجنبي، وقد أجنب، والذكر، والأنثى فيه سواء، وقد يجمع في لغة على الأجناب، قالت الخنساء: يا عين جودي بدمع منك تسكابا ... وأبكي أخاك إذا جاورت أجنابا 2 والجار الجنب الذي جاورك من قوم آخرين ذو جنابة لا قرابة له في الدار، ولا في النسب، قال الله- عز وجل-: والجار ذي القربى، والجار الجنب 3 والجنوب: ريح تجيء عن يمين القبلة، والجميع: الجنائب، وقد جنبت الريح تجنب جنوبا. والجنب في الدابة شبه ظلع، وليس بظلع. والجنيب: الأسير مشدود إلى جنب الدابة. وجناب الدار: ساحتها، وجناب القوم ما قرب من محلتهم. وأخصب 1 جناب القوم. والجنبة، مجزوم، اسم يقع على عامة الشجر يترك في الصيف. ويقال: لا جنب في الإسلام 2 ، وهو أن يجنب خلف الفرس الذي يسابق عليه فرس آخر عري، فإذا بلغ قريبا من الغاية يركب ذلك ليغلب الآخرين. والجنيب: الغريب، والجانب أيضا. والجنيب: المجنوب. والجنيب: الذي يشتكي جنبه. والجنيب: الذي يجتنبك فلا يختلط بك 3 . وأجنبنا منذ ثلاث، أي دخلنا في الجنوب. وجنبنا منذ أيام: أصابتنا ريح الجنوب. ويقال: أجنب فلان، إذا أخذته ذات الجنب، كأنها قرحة الجنب. وجنب فلان في حي فلان، إذا نزل فيهم غريبا، يجنب ويجنب. وجنب بنو فلان فهم مجنبون، إذا لم يكن في إبلهم لبن، قال الجميج: لما رأت إبلي قلت حلوبتها ... وكل عام عليها عام تجنيب 1 يريد عام ذهاب اللبن، ويقول: كل عام يمر بها هو عام تجنيب. ويقال: إن عند بني فلان لشرا مجنبا وخيرا مجنبا، أي كثيرا. والمجنب: الترس، قال ساعدة بن جؤية الهذلي: ضرب اللهيف لها السيوب بطغية ... تنبي العقاب كما يلط المجنب 2 ويقال: هذا رجل جنابي: منسوب لأهل جناب بأرض نجد. ويقال: لج فلان في جناب قبيح، أي في مجانفة وجنف. وأجنب الرجل، إذا أصابته الجنابة. (ويقال: اتق الله في جنب أخيك، ولا تقدح في شأنه، وأنشد: خليلي كنا واذكر الله في جنبي 3 أي في الوقيعة في. وضربه فجنبه، إذا أصاب جنبه. ويقال: مروا يسيرون جنابيه، وجنابتيه، أي ناحيتيه. وقعد فلان إلى جنب فلان، وإلى جانب فلان. والجأنب، بالهمز، الرجل القصير الجافي الخلقة، ورجل جأنب إذا كان كزا قبيحا. وقال أمرؤ القيس: ولا ذات خلق إن تأملت جأنب 1 ورجل أجنب، وهو البعيد منك في القرابة. وقال علقمة: فلا تحرمني نائلا عن جناية ... فاني امرؤ وسط القباب غريب 2 3'),
(2292, 'نجب', 'نجب', 'نجب', 'قال الخليل: النجب قشور الشجر الغلب. ولا يقال لما لان من قشر الأغصان نجب. ولا يقال: قشر العروق، ولكن نجب العروق، والقطعة: نجبة، وقد نجبته تنجيبا، وذهب فلان ينتجب، أي يجمع النجب 1 ، قال ذو الرمة: كأن رجليه مما كان من عشر ... صقبان لم يتقشر عنهما النجب 2 وانتجبته، أي استخلصته واصطفيته اختيارا على غيره. والمنجاب من السهام لما بري وأصلح، إلا أنه لم يرش، ولم ينصل بعد. وأنجبت المرأة إذا ولدت ولدا نجيبا، وقال الأعشى: أنجب أيام والداه به ... إذ نجلاه فنعم ما نجلا 3 وامرأة منجاب، أي ذات أولاد نجباء، ونساء مناجيب. والنجابة: مصدر النجيب من الرجال، وهو الكريم ذو الحسب إذا خرج خروج أبيه في الكرم، والفعل: نجب ينجب نجابة، وكذلك النجابة في نجائب الإبل، وهي عتاقها التي يسابق عليها.'),
(2293, 'نبج', 'نبج', 'نبج', 'نبجت القبجة، إذا خرجت من جحرها، دخيل. والنبج: ضرب من الضراط. ويقال لمن تكلم بما شاء نباج. والأنبج: حمل شجرة بالهند تربب بالعسل على خلقة الخوج، مجرف الرأس، يجلب إلى العراق وفي جوفه نواة 1 كنواة الخوج، ومنه اشتق الأنجبات التي تربب بالعسل من الأترج والأهليلجة 2 ونحوها.'),
(2294, 'بنج', 'بنج', 'بنج', 'البنج من الأدوية، معرب.'),
(2295, 'جبن', 'جبن', 'جبن', 'الجبن، مثقل، الذي يؤكل، وتجبن اللبن: صار كالجبن. ورجل جبان وامرأة جبانة، (ورجال جبناء) 3 ونساء جبانات. وأجبنته: حسبته جبانا. والجبين: حرف الجبهة ما بين الصدغين منفصلا 4 عن الناحية، كل ذلك جبين واحد، وبعضهم يقول: هما جبينان. والجبانة واحدة، والجبابين 5 كثيرة.'),
(2296, 'نجم', 'نجم', 'نجم', 'النجم: اسم يقع على الثريا، وكل منزل من منازل القمر سمي نجما. وكل كوكب من أعلام الكواكب يسمى نجما، والنجوم تجمع الكواكب كلها. ويقال لمن تفكر في أمره لينظر كيف يدبره: نظر النجوم. وعن الحسن فنظر نظرة في النجوم 1 أي تفكر ما الذي يصرفهم عنه إذا كلفوه الخروج معهم، فقال: إني طعنت، فنفروا عنه هربا من الطاعون وخوفا والمنجم: الذي ينظر في النجوم. والنجوم: وظائف الأشياء، وكل وظيفة نجم، قال الله- عز وجل-: فلا أقسم بمواقع النجوم 2 يعني نجوم القرآن، أنزل جملة إلى السماء الدنيا، ثم أنزل إلى النبي- صلى الله عليه وسلم نجوما في عشرين سنة آيات متفرقة. والنجم من النبات: ما لم يقم على ساق كساق الشجر. والنجوم: ما نجم من العروق أيام الربيع، ترى رءوسها أمثال المسال تشق الأرض شقا. ونجم الناب 1 إذا طلع. وأنجمت السماء: بدت نجومها.'),
(2297, 'منج', 'منج', 'منج', 'المنج إعراب المنك 2 ، دخيل، يعني الغطة'),
(2298, 'جمن', 'جمن', 'جمن', 'الجمان من الفضة يتخذ كاللؤلؤ، ويجيء في الشعر جمانة اضطرارا كقول لبيد: كجمانة البحري سل نظامها 3'),
(2299, 'مجن', 'مجن', 'مجن', 'الماجن والماجنة معروفان، والجميع مجان ومجنة، ومن النساء مواجن. والمجانة: ألا يبالي ما صنع وما قيل له، والفعل: مجن يمجن مجونا. والمجان: عطية بلا منة ولا ثمن. والمجن 4 : الترس، قال الأعشى: فثابر بالرمح حتى نحاه ... في كفل كسراة المجن 1'),
(2300, 'شص', 'شص', 'شص', 'الشص والشص، لغتان، وهو شيء يصاد به السمك. والشص: اللص الذي لا يدع شيئا قدر عليه. ويقال: شصت عليهم معيشتهم شصوصا، وهم في شصاصاء من عيشهم، أي: في شدة. والقوسى الشصاصاء: التي لا قرار معها من النصب والتعب. وشص الناقة تشص شصاصا، أي: قل لبنها جدا، فهي شصوص، وهن شصائص'),
(2301, 'شس', 'شس', 'شس', 'الشس: الأرض الصلبة، التي كأنها حجر واحد، وتجمع شساسا وشسوسا.'),
(2302, 'شز', 'شز', 'شز', 'الشزازة: اليبس الشديد، الذي لا ينقاد للتثقيف، يقال: شز شزيز.'),
(2303, 'شط', 'شط', 'شط', 'الشط: شط البحر [وهو جانبه] ، يقال: ركوب البحر شطا بعد شط. والشط: شق السنام، ولكل سنام شطان. وناقة شطوط. [وهي الضخمة الشطين 1 ] ونوق شطائط، قال: قد طلحته جلة شطائط ... فهو لهن خائل وفارط 2 وقال: من كل كوما، شطوط مفخاذ 3 والشطط: مجاوزة القدر في كل شيء يقال: أعطيته ثمنا لا وكسا ولا شططا. وأشط الرجل إشطاطا، أي: جار في قضيته. واشتط فيما يطلب من الثمن، وفيما يحتكم من حكومة، تقول: احتكم ولا تشطط، أي: لا تجر. وأشطوا في طلب فلان، أي: أمعنوا فيه.'),
(2304, 'طش', 'طش', 'طش', 'مطر طش وطشيش، أي: قليل، قال رؤبة 1 : ولا جدا وبلك بالطشيش وطشت [السماء] الماء، أي: مطرت قليلا. وطشت الدابة، أي: مشت 2 بآخر الرمق من هزال وإعياء.'),
(2305, 'شد', 'شد', 'شد', 'الشد: الحمل، تقول: شد عليه في القتال. وشددنا عليهم شدة واحدة في الحملة، قال 3 : شددنا شدة لا عيب فيها ... وقلنا بالضحى فيحي فياح والشد: العدو 4 والفعل: اشتد والشدة: الصلابة. والشدة: النجدة، وثبات القلب. والشدة: المجاعة. ورجل شديد: شجاع. والشدائد الهزاهز. [والأشد: مبلغ الرجل الحنكة والمعرفة. قال الله عز وجل: حتى يبلغ أشده 1 2 .');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2306, 'شت', 'شت', 'شت', 'الشت: مصدر الشيء الشتيت. وهو المتفرق. وتقول: شت شعبهم 3 شتاتا وشتا. أي: تفرق جمعهم. قال الطرماح: 4 : شت شعب الحي بعد التئام ... وشجاك الربع ربع المقام وثغر شتيت: مفلج حسن، قال 5 : حرة تجلو شتيتا حسنا ... كشعاع البرق في الغيم سطع ويقال: وقعوا في أمر شت وشتى. ويقال: إني أخاف عليكم الشتات، أي: الفرقة. ويقال: شتان ما هما.'),
(2307, 'شظ', 'شظ', 'شظ', 'شظظت الغرارتين بشظاظين أو شظاظ. والشظاظ: خشبة عقفاء محددة الطرف. [تجعل في عروتي الجوالقين إذا عكما على البعير، وهما شظاظان] 1 ، قال: أين الشطاظان وأين المربعه 2 وأشظ الرجل، أي: أنعظ. والشظشظة: فعل زب الغلام عند البول. والشظ: الحمل. والإشظاظ، الإطلاق.'),
(2308, 'شذ', 'شذ', 'شذ', 'شذ الرجل من أصحابه، أي: انفرد عنهم. وكل شيء منفرد فهو شاذ.. وكلمة شاذة. وشذاذ الناس: متفرقوهم. وكذلك شذان الحصى، قال: تترك شذان الحصى قنابلا 3'),
(2309, 'شث', 'شث', 'شث', 'الشث: شجر طيب الريح، مر الطعم، ينبت في جبال الغور ونجد، قاله أبو الدقيش.. قال في صفة النساء: وفيهن مثل الشث يعجب ريحه ... وفي عينه سوء المذاقة والطعم 1 قال حماس: الشث لا ينبت بنجد، وأظنه: الدفلى، أي: من النساء مثل الشث، حسن المنظر وفي مخبرتها وصحبتها ما يخالف منظرتها من سوء خلقها، وخبث غرضها، وعيوب نفسها فمثل الشاعر بها.'),
(2310, 'شر', 'شر', 'شر', 'الشر: السوء، والفعل للرجل الشرير، والمصدر: الشرارة، والفعل: شر يشر شرا وشرارة. وقوم أشرار خلاف الأخبار. والشر: بسطك الشيء في الشمس من الثياب وغيرها. ويقال: إنما يقال للذي يبسط في الشمس: الإشرار، يقال: أشررته في الشمس فهو مشر، ولا يقال: شررته. والإشرار ما يبسط عليه الأقط والبر ليجف، قال: ثوب على قامة سحل تعاوره ... أيدي الغواسل للأرواح مشرور 1 وقال بعضهم: الأشارير، والواحدة: إشرارة، هي مثل الخصفة يطرح عليها الأقط فيمصل، ويذهب ماؤه. ويقال: الشقة من شقاق البيت يشرر عليها الأقط. قال طفيل الغنوي 2 : كأن يبيس الماء فوق متونها ... أشارير ملح في وقال الجعدي 3 : كأن الجميم بها قافلا ... أشارير ملح لدى والشرارة والشرر: ما تطاير من النار، قال يصف الشراب: تنزو إذا شجها المزاج كما ... طار شرار مطير اللهب أو كشرار العلاة يضربها ... القين على كل وجهة يثب 4 والشران، فعلان، من كلام أهل السواد، وهو شيء تسميه العرب: الأذى 5 ، شبه البعوض يغشى وجه الإنسان، لا يعض. الواحدة: شرانة. ويقال: ألقى علي شراشره، أي: ألقى علي نفسه حرصا. ويقال: شرشره، أي: قطع شراشره.'),
(2311, 'رش', 'رش', 'رش', 'رششت البيت بالماء رشا فهو مرشوش. ورشتنا السماء، أي: بلتنا. وأرشت الطعنة ترش، ورشاشها: دمها، وكذلك: رشاش الدمع وشواء رشراش، أي: يقطر دسمه ويترشرش ماؤه.'),
(2312, 'شل', 'شل', 'شل', 'الشل: الطرد.. شللته فانشل. وذهبوا شلالا، أي: انشلوا مطرودين. والشلل: ذهاب اليد.. شلت يده تشل شللا. وتقول: لا شلل، في معنى: لا تشلل، لأنه وقع موقع الأمر، فشبه به فجر، فلو كان نعتا لنصب، قال: ضربا على الهامات لا شلل 1 وقال نصر بن سيار: إني أقول لمن جدت صريمته ... يوما لغانية 2 : تصرم ولا شلل 3 والشلل: لقح يصيب الثوب، فيبقى فيه أثر والشلشلة: قطران الماء، انشل الماء، وشلشل، والصبي يشلشل ببوله. والشليل: ثوب يلبس تحت الدرع. والشليل: الحلس. قال: إليك سار العيس في الأشله 1 وقال بعضهم: الشليل: الدرع القصيرة، وجمعها: أشلة، قال دريد بن الصمة: تقول هلال خارج من غمامة ... إذا جاء يعدو في شليل وقونس 2'),
(2313, 'لش', 'لش', 'لش', 'اللشلشة: كثرة التردد عند الفزع واضطراب الأحشاء في موضع بعد موضع، يقال: جبان لشلاش.'),
(2314, 'شن', 'شن', 'شن', 'الشن: السقاء البالي. والشنين: قطران الماء من الشنة. شيء بعد شيء، قال: يا من لدمع دائم الشنين ... تطربا والشوق ذو شجون 3 وكذلك التشنان والتشنين، قال: أعيني جودا بالدموع السواجم ... سجاما كتشنان الشنان الهزائم 1 والتشنن: التشنج في الجلد عند الهرم، قال: 2 بعد اقورار الجلد والتشنن والإشنان في الغارة، [يقال] : أشنوا الخيل، أي: بثوها. وشن: حي من عبد القيس، وفي المثل وافق شن طبقة 3 وافقه فاعتنقه. كانوا يكثرون الغارات فوافقهم طبق من الناس، فأبروا عليهم وقهروهم، فقيل ذلك. وشنشنة الرجل: غريزته. قال: 4 شنشنة أعرفها من أخزم والشنون: المهزول من الدواب، ويقال: هو السمين، ويقال: هو الذي ليس بسمين ولا مهزول، قال 5 : [القائد الخيل منكوبا دوابرها] ... منها الشنون ومنها الزاهق الزهم والشنون: الذئب الجائع، قال الطرماح 6 : [يظل غرابها ضرما شذاه] ... شج بخصومة الذئب الشنون . الأشنة من العطر: شيء أبيض كأنه مقشور من عرق. والأشنان: معروف، [الذي يغسل به الأيدي] 1 .'),
(2315, 'نش', 'نش', 'نش', 'النش والنشيش: صوت الماء إذا صببته في [صاخرة] 2 طال عهدها بالماء. ونشيش اللحم: صوته إذا قلي. ونش الغدير إذا أخذ ماؤه في النضوب. والخمر تنش في الغليان عند إدراكه، وفي الحديث: إذا نش فلا تشربه 3 . [والنشنشة: النفض والنثر] 4 . وسبخة نشاشة [ونشاشة] : تنش من النز إذا نبع.'),
(2316, 'شف', 'شف', 'شف', 'الشف: الستر الرقيق يري ما خلفه واستشففت ما وراءه، أي: أبصرت. والشف: الربح، وهو الزيادة والفضل. والشف: من المهنأ، تقول: شف لك يا فلان، إذا غبطته بشيء قلت له ذلك. والشفوف: نحول الجسم من الهم والوجد، قال 1 : فأرسلت إلى سلمى ... بأن النفس مشفوفه وقال 2 : وهم يشف الجسم مني مكانه ... وأحداث دهر ما تعرى بلاؤها والشفيف: برد ريح في ندوة، واسم تلك الريح: شفان. والشفشاف: الريح الطيبة البرد، والمصدر: الشفشفة.'),
(2317, 'فش', 'فش', 'فش', 'الفش: حمل الينبوت. الواحدة: فشة، والجميع: الفشاش. والفش: تتبع السرقة الدون، قال 3 : نحن وليناه فلا تفشه ... كيف يواتيه ولا يؤشه والفش: الفساء والفش: الحلب، فششت الناقة: حلبتها، وافتششتها [أيضا] والفشوش: الناقة الواسعة الإحليل. والفشاش: الكساء الغليظ. والانفشاش: الكسل عن الأمر.'),
(2318, 'شب', 'شب', 'شب', 'الشب: حجارة منها الزاج وأشباهه، وأجودها ما جلب من اليمن، وهو شب أبيض، له بصيص شديد. وشبه: اسم رجل، وكذلك شبيب، ويجوز [استعمال] شبة في موضع شابة والشبيبة: الشباب. والشباب و [الشبان] : جماعة الشاب.. شب يشب شبابا، ويشب الفرس شبوبا إذا رفع يديه معا.. والشبوب والشبب: الفتي من ثيران الوحش، قال ذو الرمة 1 : أذاك أم نمش بالوشم أكرعة ... مسفع الخد غاد ناشط شبب والنار تشبها شبا، أي: توقدها، وكذلك الحرب.'),
(2319, 'بش', 'بش', 'بش', 'البش: اللطف في المسألة، والإقبال على أخيك، تقول: بششت بشا وبشاشة. ورجل هش بش. والبشيش: الوجه، يقال: رجل مضيء البشيش، أي: مضيء الوجه.'),
(2320, 'شم', 'شم', 'شم', 'الشم من قولك: شممت الشيء أشمه، ومنه التشمم كما تشمم البهيمة إذا التمست رعيا. والمشامة: المفاعلة من الشم، في [قولك] شاممت العدو، يعني. الدنو من العدو حتى يروك وتراهم، [والشمم: الدنو، اسم منه] 1 ، تقول: شاممناهم وناوشناهم. والإشمام: أن تشم الحرف الساكن حرفا، كقولك في الضمة: هذا العمل، وتسكت، فتجد في فيك إشماما للام لم يبلغ أن يكون واوا، ولا تحريكا يعتد به، ولكن شمة من ضمة خفيفة، ويجوز ذلك في الكسر والفتح أيضا. وأشممت فلانا الطيب. وتقول للوالي: أشممني يدك، وهو أحسن من قولك: ناولني يدك أقبلها. وشمام: اسم جبل له رأسان يسميان ابني شمام. والشمم: الارتفاع في الأنف، والنعت: أشم وشماء. وجبل أشم: طويل الرأس. وتقول: شامم فلانا، أي: انظر ما عنده.'),
(2321, 'مش', 'مش', 'مش', 'مششت العظم، أي: مصصته ممضوغأ. وفلان يمش مال فلان، و [يمش] من ماله، أي: يأخذ الشيء بعد الشيء. والمشش: مشش الدابة، معروف. وتقول: أمش العظم [وهو أن يمخ حتى يتمشش] 1 . والمش: أن تمسح القدح بثوبك لتلينه، كما تمش الوتر. والمش: تنديل الغمر، قال امرؤ القيس 2 : نمش بأعراف الجياد أكفنا ... إذا نحن قمنا عن شواء مضهب والمشمش: فاكهة، وأهل الحجاز يسمون الإجاص مشمشا'),
(2322, 'شصر', 'شصر', 'شصر', 'الشصر: الخشف الذي بلغ، وهو الشوصر في لغة. [ويقال له: شاصر، إذا نجم قرنه 1 ] والشصار: خشبة تشد بين شفري الناقة.. شصرتها تشصيرا. [وشصرت الثوب شصرا: خطته] 2'),
(2323, 'شرص', 'شرص', 'شرص', 'الشرصتان: ناحيتا الناصية، وهما أرق شعرا، ومنهما تبدأ النزعتان [والشرص: شرص الزمام، وهو فقر يفقر على أنف الناقة، وهو حز فيعطف عليه ثني الزمام، ليكون أسرع وأطوع وأدوم لسيرها، قال: لولا أبو عمر حفص لما انتجعت ... مروا قلوصي ولا أزرى بها الشرص 3 ] .'),
(2324, 'شنص', 'شنص', 'شنص', 'فرس شناصي، أي: نشيط طويل الرأس'),
(2325, 'نشص', 'نشص', 'نشص', 'نشص السحاب، أي: ارتفع من قبل العين حين ينشأ والنشاص: اسم ذلك السحاب. والناشص: لغة في الناشز، نشصت المرأة على زوجها ونشزت إن أبغضته وكرهته، قال الأعشى 4 : تقمرها شيخ عشاء فأصبحت ... قضاعية تأتي الكواهن ناشصة'),
(2326, 'شصب', 'شصب', 'شصب', 'الشصيبة: شدة العيش، والبلاء، دفع الله عنا شصائب الأمور، وعيش شاصب وقد شصب شصوبا، وأشصب الله عيشه. [والشيصبان: الذكر من النمل، ويقال: هو جحر النمل 1 ]'),
(2327, 'شمص', 'شمص', 'شمص', 'شمصت الدابة: طردتها طردا عنيفا، وهو سرعة الجث. لا يقال هذا إلا بالصاد، فأما التشمس فأن تنخسه حتى يفعل فعل الشموس، ويقال: شمصت الفرس والراحلة، إذا ضربته، وحركته باللجام حتى تجتمع نفسه وحركته، قال: وحث بعيرهم حاد شموص 2 وقال: فإن الخيل شمصها الوليد 3 وقال رجل من بني عجل: فانشمصت لما أتانا مقبلا ... فهابها فانصاع ثم ولولا 1'),
(2328, 'شطس', 'شطس', 'شطس', 'الشطس: الدهاء والعلم. يقال: رجل شطسي ذو أشطاس'),
(2329, 'شرس', 'شرس', 'شرس', 'الشرس: شبه الدعك، كما يشرس الحمار ظهور العانة بلحييه، ونحو ذلك. وقيل: الشرس: النهس، وهو عضيض الحمار والفرس، الذي لا يقطع، وهو أوضع من القطع أو مثله، قال: قدا بأنياب وشرسا أشرسا 3 رجل شرس الخلق، وإنه لأشرس، وإنه لشريس، أي: عسر شديد الخلاف، قال: فظلت ولي نفسان نفس شريسة ... ونفس تعناها الفراق جزوع 1 والشراس: شدة المشارسة في معاملة الناس. رجل أشرس ذو شراس، وناقة شريسة، قال: قد علمت عمرة بالغميس ... أن أبا المسور ذو شريس وأمكنه شراس، أي: صلبة خشنة، وأرض شرساء. وشراس: نعت واجب على فعال.'),
(2330, 'شسف', 'شسف', 'شسف', 'الشاسف: القاحل الضامر ... سقاء شاسف وبعير شاسف، وقد شسف يشسف، وشسف شسوفا وشسافة، لغتان، إذا نحل ودق. واللحم الشسيف: الذي كاد ييبس، وفيه ندوة بعد. قال مزاحم: بالباء والفاء أقولهما جميعا، وبالفاء أحسن.. ناقة شسوف، قال 2 : تتقي الريح بدف شاسف ... وضلوع تحت زو قد نحل'),
(2331, 'شسب', 'شسب', 'شسب', 'الشاسب: والشازب: الضامر اليابس.. والشاسب: الغضبان، ويقال: شسب إذا تهيأ للقتال وغضب. ويقال للرجل النحيف اليابس الأعضاء: شاسب ويقال: شسيب النخل وعسيبه، والعسيب للرطب، فإذا يبس وانحت ورقه فهو شسيب.'),
(2332, 'شمس', 'شمس', 'شمس', 'الشمس: عين الضح، وقيل: الضح هو الشمس وعينها قرصها. والشموس: معاليق القلائد. [ويقال] : يوم شامس، وقد شمس يشمس شموسا، أي: ذو ضح نهاره كله. ورجل شموس: عسر، وهو في عداوته كذلك خلافا وعسرا على من نازعه، وإنه لذو شماس شديد. وشمس لي فلان، إذا أبدى لك عداوته كأنه قد هم أن يفعل. والشمس والشموس من الدواب الذي إذا نخس لم يستقر. والشماس من رؤساء النصارى الذي يحلق وسط رأسه لازما للبيعة، والجميع: الشمامسة.'),
(2333, 'شزر', 'شزر', 'شزر', 'الشزر: نظر فيه إعراض، كنظر المعادي المبغض. والحبل المشزور: أي: المفتول شزرا، أي: الذي فتل مما يلي اليسار، وهو أشد لفتله. وطعن شزر، أي: من ناحية ليست على شجيحة الطريقة، لأنه لما كان على خلاف اليمين لا يتوقعه المطعون لما قد أمنه وجنبه.'),
(2334, 'شرز', 'شرز', 'شرز', 'يقال: رماه أر بشرزة، أي: بهلكة. وأشرزة ار، أي: ألقاه في مكروه لا يخرج منه. وفلان يشارز فلانا، أي: يشاده ويماظه قال رؤبة 1 : يلقى معاديهم عذاب الشرز'),
(2335, 'شزن', 'شزن', 'شزن', 'الشزن: شدة الإعياء من الحفاء. شزنت الإبل شزنا. والشزن: الكعب الذي يلعب به، ويقال: شزن، قال: كأنه شزن بالدو محكوك 1 وتشزن في الأمر: بالغ فيه. والشزن: الغليظ من الأرض. وهو في شزن من عيشه، أي: نصب.'),
(2336, 'نشز', 'نشز', 'نشز', 'نشز الشيء، أي: ارتفع. وتل ناشز [وجمعها: نواشز. وقلب ناشز إذا ارتفع عن مكانه من الرعب 2 ] . نشز ينشز نشوزا وينشز لغة. ونشز ينشز، إذا زحف عن مجلسه فارتفع فويق ذلك. منه قول الله [جل وعز] : فانشزوا 3 وعرق ناشز: لا يزال منتبرا، من داء وغيره. والنشز: اسم لمتن من الأرض مرتفع، والجميع: النشوز. ونشزت المرأة تنشز فهي ناشز، أي: استعصت على زوجها إذا ضربها وجفاها فهي ناشز عليه. ودابة نشزة: لا يكاد يستقر السرج والراكب على ظهرها. وركب نشز وناشز: ناتيء. وأنشز الشيء ينشزه، إذا رفعه عن مكانه. وكلمني فلان كلاما فأنشزني، أي: أغضبني وأقامني. وأنشزت الإبل: شقتها من موضع إلى موضع.'),
(2337, 'شزب', 'شزب', 'شزب', 'الشزب: لغة في الشسب. والشازب: الضامر اليابس الأعضاء. والخيل الشزب: الضوامر. ويقال للرجل النحيف: [شازب] شزب يشزب شزوبا وشزوبة. والشازب: الغضبان، كما يقال للخيل: شزب، إذا ركضت للغارة، ويقال: شزبت أنا، إذا تهيأت للقتال وغضبت.'),
(2338, 'شمز', 'شمز', 'شمز', 'التشميز: ليست بعربية، يقال: شمزت الأرض تشميزا. واشمأز، إذا تقبض.'),
(2339, 'شطر', 'شطر', 'شطر', 'شطر كل شيء: قصده، وشطر كل شيء نصفه، وشطرته: جعلته نصفين. وشاة شطور، وقد شطرت شطارا، أي: أحد طبييها أطول من الآخر، فإن حلبا جميعا، والخلفة كذلك، سميت حصونا. ومنزل شطير: بعيد، من غير فعل، ولو استعمل لقيل: شطر شطارا، وكان قياسا وشطر فلان على أهله، أي: تركهم مخالفا مراغما. ورجل شاطر، وقد شطر شطورا وشطارة وشطارا، وهو الذي أعيى أهله ومؤدبه خبثا. وشطر بصره يشطره شطورا وشطرا، وهو الذي كأنه ينظر إليك وإلى آخر.'),
(2340, 'شرط', 'شرط', 'شرط', 'الشرط: معروف في البيع، والفعل: شارطه فشرط له على كذا وكذا، يشرط له. والشرط: بزغ الحجام بالمشرط، والفعل: شرط يشرط. والبزغ: الشرط الضعيف. والشريط: شبه خيوط تفتل من الخوص، والجميع: الشرط. فإذا كان مثلها من الليف فهي: دسر، والواحد: دسار. قال الله تعالى: وحملناه على ذات ألواح ودسر 1 ، ودسرها: شرطها. والشرطان: كوكبان. يقال: إنهما قرنا الحمل، وهو أول نجم من الربيع، قال العجاج 2 : من باكر الأشراط أشراطي ومن ذلك صار أوائل كل أمر أشراطه. وأشراط الساعة: علاماتها، الواحد: شرط. والشرط من الإبل: ما كان [مجلوبا 1 ] للبيع، نحو الناب والدبر ونحوه، يقال: أفي إبلك شرط فتقول: لا. ولكنها لباب كلها. وإذا أعجل إنسان رسولا إلى أمر قيل: أشرطه وأفرطه، كأنه اشتق من الأشراط التي هي أوائل الأشياء. والشرطي منسوب إلى الشرطة، والجميع: شرط، وبعض يقول: شرطي ينسبه إلى الجماعة. [والشرط سموا شرطا، لأن شرطة كل شيء خياره، وهم نخبة السلطان من جنده 2 ] ، قال: حتى أتت شرطة للموت حاردة 3 والشرواط من الإبل: الطويل، وناقة شرواط، وجمل شرواط، أي: طويل فيه دقة، وذئب شرواط، أي: طويل قليل اللحم، نحيف. وكل شيء هيأته لتنفقه، أو تبيعه فقد أشرطته، أي: أعددته وهيأته. وأشرط جمله للسقاء: جعله له. وأشرطت نفسي للقتال وغيره: بذلتها له. قال أوس 4 : فأشرط فيها نفسه وهو معصم ... وألقى بأسباب له وتوكلا طرش 1 : الطرش: الصمم.'),
(2341, 'شلط', 'شلط', 'شلط', 'شلط: السكين بلغه أهل الجوف.'),
(2342, 'شطن', 'شطن', 'شطن', 'الشطن: الحبل الطويل الشديد الفتل، يستقى به. ويقال للفرس العزيز النفس: إنه لينزو بين شطنين، يضرب مثلا للإنسان الأشر القوي، وذلك أنه إذا استعصى على صاحبه شده بحبلين من جانبين، فهو فرس مشطون. وغزوة شطون. أي: بعيدة. وشطنت الدار شطونا، إذا بعدت، وأكثر ما يقال: نوى شطون، ونية شطون. والشيطان: فيعال من شطن، أي: بعد. ويقال: شيطن الرجل، وتشيطن، إذا صار كالشيطان. وفعل فعله، قال رؤبة 1 : وفي أخاديد السياط المشن ... شاف لبغي الكلب المشيطن'),
(2343, 'نشط', 'نشط', 'نشط', 'نشط الإنسان ينشط نشاطا فهو نشيط، طيب النفس للعمل ونحوه، والنعت: ناشط. والناشط: اسم للثور الوحشي، وهو الخارج من أرض إلى أرض. وطريق ناشط ينشط من الطريق الأعظم يمنة ويسرة، كقول حميد الأرقط: معتزما للطرق النواشط 2 وكذلك النواشط من المسايل. والأنشوطة: عقدة [يسهل انحلالها] مثل عقدة السراويل، تقول: نشطته بأنشوطة وأنشوطتين. والنشط: جماعة الأنشوطة.. أي: أوثقته بذلك الوثاق.. وأنشطت البعير: [حللت أنشوطته] وأنشطت العقال، إذا مددت أنشوطته فانحلت، وكذلك الانتشاط، وهو مدك شيئا إليك حتى ينحل. ويقال للمريض يسرع برؤه، وللمغشي عليه تسرع إفاقته، وللمرسل في أمر يسرع فيه عزيمته: كأنما أنشط من عقال والناشط: الطريق في قول الطرماح 1 : واستطربت ظعنهم لما احزأل بهم ... أل الضحى ناشطا من داعيات دد والنشوط: كلمة عراقية، وهو سمك يمقر في ماء وملح. والنشيطة والفضول: مال هي إبل يسيرة ينشطها الجيش أو بعضهم فلا تسع القسمة فيجعلونها للرئيس.. ونشط الصقر الطائر، أي: خلبه بمخلبه.'),
(2344, 'نطش', 'نطش', 'نطش', 'النطش: شدة الجبلة 2 . يقال: إنه لنطيش جبلة الظهر.'),
(2345, 'طفش', 'طفش', 'طفش', 'الطفاشاة: المهزولة من الغنم وغيرها. والطفش: النكاح، قال [أبو زرعة التميمي] 3 : [قلت لها وأولعت بالنمش] : ... هل لك يا حليلتي في الطفش؟'),
(2346, 'شطب', 'شطب', 'شطب', 'الشطب، مجزوم: سعف النخل الأخضر، الواحدة: شطبة، ومنه قيل: جارية شطبة، أي: غضة تارة طويلة. وقوس شطبة. والشطبة: طريقة في متن السيف، وجمعه: شطب. وسيف مشطب مشطوب: ذو شطب. والشطبة لغة في الشطبة، وكان أبو الدقيش يفرق بينهما، ويقول: الشطبة: قطعة من سنام البعير تقطع طولا، وكل قطعة من ذلك تسمى: شطيبة، وكل قطعة من أديم تقد طولا تسمى شطيبة، تقول: شطبت الأديم، وشطبت السنام أشطبه شطبا. والشواطب من النساء: اللاتي يقددن الأديم بعد ما يخلقنه 1 ، ويشققن السعف للحصر، قال 2 : فكأنما ... بسط الشواطب بينهن حصيرا ويقال للفرس السمين الذي انتبر متناه وتباينت عروقه: مشطوب الظهر والبطن والكفل: أي تزايل بعضه من بعض من سمنه.'),
(2347, 'شبط', 'شبط', 'شبط', 'الشبوط: ضرب من السمك، طويل الذنب، دقيقه، عريض الوسط، لين الممس، صغير الرأس كأنه البربط، كلمه عراقية، وإنما يشبه البربط إذا كان ذا طول، ليس بعريض بالشبوط.'),
(2348, 'بطش', 'بطش', 'بطش', 'البطش: التناول عند الصولة. والأخذ الشديد في كل شيء: بطش به. والله ذو البطش الشديد، أي: ذو البأس والأخذ لأعدائه.'),
(2349, 'شمط', 'شمط', 'شمط', 'الشمط في الرجل: شيب اللحية، وهو في المرأة: شيب الرأس. ولا يقال: أمة شيباء، ولكن شمطاء، [ويقال للرجل: أشمط 1 ] والشميط من النبات: [الذي] بعضه هائج، وبعضه أخضر، وقد يقال لبعض الطير، إذا كان في ذنبه سواد وبياض: إنه لشميط الذنابى والشماطيط: الخيل المتفرقة [يقال: جاءت الخيل شماطيط، أي: متفرقة] ، قال الأعشى 2 : تباري الرياح مغاويرها ... شماطيط في رهج كالدخن'),
(2350, 'مشط', 'مشط', 'مشط', 'المشط والمشط، لغتان، والمشطة: ضرب من المشط، والمشطة: واحدة. والماشطة: الجارية التي تحسن المشاطة. وضرب من الإبل يسمى: المشط، يقال: بعير ممشوط، به سمة المشط. ورجل ممشوط، أي: به دقة وطول. والمشط: سلاميات ظهر القدم والمشط: نبت صغير يقال له: مشط الذئب. ومشطت يده تمشط مشطا وهو أن يمس [الرجل الشوك أو الجذع فيدخل منه في يده] 1 .'),
(2351, 'طمش', 'طمش', 'طمش', 'الطمش: الناس، وجمعه: طموش، قال 2 : وحش 3 ولا طمش من الطموش'),
(2352, 'شرد', 'شرد', 'شرد', 'شرد البعير يشرد شرادا. وفرس شرود، أي: مستعص. وقافية شرود، أي: عائرة سائرة في البلاد. ورجل مشرد شريد، أي: طريد. وشردته وطردته: جعلته طريدا شريدا. وقول الله عز وجل: فشرد بهم من خلفهم 4 ، أي: نكل بهم، قال 5 : أطوف في الأباطح كل يوم ... مخافة أن يشرد بي حكيم'),
(2353, 'رشد', 'رشد', 'رشد', 'رشد يرشد رشدا ورشادا [وهو] نقيض الغي. ورشد يرشد رشدا [وهو] نقيض الضلال. والرشدة: نقيض الغية، تقول: ولد لرشدة، ولم يهد إلى رشدة، قال 1 : وكائن ترى من رشدة في كريهة ... ومن غية تلقى عليها الشرائر وقال آخر: لذي غية من أمه ولرشدة ... فيغلبها فحل على النسل منجب 2 ويقال: يا رشدين كأنه يريد: يا راشد. ورشد فلان إذا أصاب وجه الأمر والطريق، والإرشاد: الدلالة والهداية. والرشاد: الحجر، سمي به تطيرا من الحرف وصلابة الحجر.'),
(2354, 'شدن', 'شدن', 'شدن', 'شدن الصبي والخشف يشدن شدونا، إذا صلح جسمه وترعرع. ويقال للمهر: قد شدن، فإذا أفردت الشادن فهو ولد الظبية، وظبية مشدن يتبعها شادن. وناقة شدنية منسوبة إلى موضع باليمن'),
(2355, 'دشن', 'دشن', 'دشن', 'داشن معرب من الدشن، والداجن مثله [وهو كلام عراقي ليس من كلام البادية 1 ]'),
(2356, 'نشد', 'نشد', 'نشد', 'نشد ينشد فلان فلانا، إذا قال: نشدتك بالله والرحم، أي: سألتك بالله وبالرحم. وناشدتك الله نشدة ونشدانا، أي: سألتك بالله.. ونشدت الضالة، إذا ناديت وسألت عنها. والناشدون: قوم يطلبون الضوال فيأخذونها ويحبسونها على أربابها. قال ابن عرس: عشرون ألفا هلكوا ضيعة ... وأنت منهم دعوة الناشد 2 يريد: أنت منهم في القرب بمكان دعوة الناشد، وهم: النشاد. والنشيد: الشعر المتناشد بين القوم ينشده بعضهم بعضا إنشادا. وأنشدت الضالة: عرفتها، ونشدتها: طلبتها.'),
(2357, 'شدف', 'شدف', 'شدف', 'الشدوف: الشخوص، الواحد: شدف. ويقال: شدف الفرس شدفا، إذا مرح، فهو شدف أشدف، ويقال: كل من خالف، وتمايل فقد شدف شدفا فهو شدف أشدف 1 ، قال العجاج 2 : بذات لوث أو نباج أشدفا'),
(2358, 'دبش', 'دبش', 'دبش', 'الدبش: القشر والأكل، يقال: دبشت الأرض دبشا، أي: أكل ما عليها من النبات، قال رؤبة 4 : جاءوا بأخراهم على خنشوش ... من مهوأن بالدبا مدبوش'),
(2359, 'مدش', 'مدش', 'مدش', 'المدش: استرخاء ودقة في اليد، يقال: يد مدشاء، ناقة مدشاء. [وقد مدشت] . [ويقال: ما مدشت منه مدشا ومدوشا، وما مدشني شيئا، وما أمدشني، وما مدشته شيئا. ولا مدشت شيئا، أي: ما أعطاني ولا أعطيته] 1 .'),
(2360, 'شتر', 'شتر', 'شتر', 'الشتر: انقلاب في جفن العين الأسفل قلما يكون خلقة. والشتر، بجزم التاء: فعلك بها. والنعت: أشتر وشتراء. وقد شتر يشتر شترا.'),
(2361, 'تشر', 'تشر', 'تشر', 'تشرين: اسم شهر من شهور الخريف بالرومية.'),
(2362, 'نتش', 'نتش', 'نتش', 'النتش: إخراج الشوك بالمنتاش. والمنتاش: تسمية العامة من الناس المنقاش، وهو الذي ينتف به الشعر. والنتش: جذب اللحم ونحوه قرصا ونهشا. وأنتش النبات: خرج رأسه من الأرض قبل أن يعرف وأنتش الحب، إذا ابتل فضرب نتشه في الأرض، أي: ما يبدو منه أول ما ينبت من أسفل أو من فوق، وذلك النبات اسمه: النتش.'),
(2363, 'فتش', 'فتش', 'فتش', 'الفتش والتفتيش: طلب في بحث.'),
(2364, 'شتم', 'شتم', 'شتم', 'شتم فلان فلانا شتما. وأسد شتيم وحمار شتيم، أي: كريه الوجه.'),
(2365, 'شمت', 'شمت', 'شمت', 'الشماتة: فرح العدو ببلية تنزل بمعاديه. وقد شمت به [يشمت] شماتة. وأشمته الله بكذا. وشمت العاطس تشميتا: قلت له: يرحمك الله. والتشميت: الدعاء، وكل داع لأحد بخير فهو مشمت له.'),
(2366, 'شنظ', 'شنظ', 'شنظ', 'الشناظ: من نعت المرأة، [وهو] اكتناز اللحم وكثرته. وشناظي الجبل: أطرافه وأعاليه.'),
(2367, 'نشظ', 'نشظ', 'نشظ', 'النشوظ: نبات الشيء من أرومته أول ما يبدو حين يصدع الأرض نحو ما يخرج من أصول الحاج، والفعل منه [نشظ] 1 ينشظ، قال: ليس له أصل ولا نشوظ 2 والنشظ: اللسع في سرعة واختلاس قال حماس: النشظ: لدغة الحية، نشظته: لدغته ... والنشظ والتنشظ في السقي، وهو السبوغ إذا جذب الدلو.'),
(2368, 'شظف', 'شظف', 'شظف', 'الشظف: يبس العيش، [قال: وراج لين تغلب عن شظاف ... كمتدن الضفا كيما يلينا 1 ] والشظيف من الشجر: ما لم يجد ريه، فخشن وصلب من غير أن تذهب ندوته. شظف شظافة.'),
(2369, 'شظم', 'شظم', 'شظم', 'الشيظم: الطويل الجسم من الفتيان، وهم الشياظمة، والأنثى: شيظمة، ومن الخيل كذلك، قال عنترة: 2 والخيل تقتحم الخبار عوابسا ... من بين شيظمة وآخر شيظم'),
(2370, 'مشظ', 'مشظ', 'مشظ', '[المشظ: أن يمس [الإنسان] الشوك أو الجذع، فيدخل منه في يده، يقال: مشظت يده تمشظ مشظا 3 . والمشظ: ما يتشعث من القنا. يقال: مشظت القناة، إذا رزتها بفيك.'),
(2371, 'شذر', 'شذر', 'شذر', 'الشذر: قطع من ذهب، تلقط من المعدن من غير إذابة الحجارة، ومما يصاغ من الذهب فرائد يفصل بها اللؤلؤ والجوهر. والتشذر: النشاط، والتسرع إلى الأمر. وتشذرت الناقة إذا رأت رعيا يسرها فحركت رأسها فرحا ومرحا. والتشذر: التوعد والتهدد، قال لبيد 1 : غلب تشذر بالذحول كأنها ... جن البدي رواسيا أقدامها والتشذر: الاستثفار بالثوب.'),
(2372, 'شذب', 'شذب', 'شذب', 'الشذب: قشر الشجر، والشذب: المصدر، والفعل: يشذب، أي: يقطع من الشجر، وكل شيء نحي عن شيء فقد شذب عنه، قال: نشذب عن خندف حتى ترضى 2 والشوذب: الطويل من كل شيء. وشاذب: اسم إنسان.'),
(2373, 'شرث', 'شرث', 'شرث', 'الشرث: غلظ ظهر الكف من برد الشتاء. شرث يشرث شرثا. وشرثت الكف.'),
(2374, 'شثن', 'شثن', 'شثن', '[الشثن: الرجل الذي، في أنامله غلظ.. والفعل: شثن، وشثن شثنا وشثونة] 1 . والشثن الخشونة ورجل شثن الكف، أي: غليظها'),
(2375, 'شبث', 'شبث', 'شبث', 'الشبث: دويبة تكون في الأرض، وتكون عند الندوة، والجميع: الشبثان. ويقال: هو العنكبوت الضخم، و (لا يصح) . قال حماس: الشبث: دابة كثيرة القوائم، صفراء شبيهة بالعقرب، لا تخرب الأرض، وربما لدغ لدغة شديدة. والتشبث: اللزوم، وشدة الأخذ. وتشبث به، أي: تقبض به.'),
(2376, 'شنر', 'شنر', 'شنر', 'الشنار: العيب والعار. [ورجل شرير شنير، إذا كان كثير الشر والعيوب وشنرت بالرجل تشنيرا إذا سمعت به وفضحته 2 ]'),
(2377, 'نشر', 'نشر', 'نشر', 'النشر: الريح الطيبة، وفي الحديث: خرج معاوية ونشره أمامه 3 يغني ريح المسك. ونشرت الثوب والكتاب نشرا: [بسطته] . والنشور: الحياة بعد الموت.. ينشرهم الله إنشارا. ونشرت الأرض تنشر نشورا، إذا أصابها الربيع فأنبتت، فهي ناشرة. والنشرة: رقية علاج للمجنون، ينشر بها عنه تنشيرا، وربما قيل للإنسان المهزول الهالك: كأنه نشرة. والتناشير: كتابة الغلمان في الكتاب. والنواشر: عروق باطن الذراع.'),
(2378, 'شرف', 'شرف', 'شرف', 'الشرف: مصدر الشريف من الناس. شرف يشرف وقوم أشراف، مثل شهيد وأشهاد ونصير وأنصار. والشرف: ما أشرف من الأرض. والمشرف: المكان تشرف عليه وتعلوه. ومشارف الأرض، أعاليها. ولذلك قالوا: مشارف الشام والشرفة: التي تشرف بها القصور، وجمعها: شرف. والشرف: الإشفاء على خطر من خير أو شر، و [يقال) : هو على شرف من كذا. وأشرف المريض، وأشفى على الموت وساروا حتى إذا شارفوهم، أي: أشرفوا عليهم. واستشرف فلان: رفع رأسه ينظر إلى شيء. وناقة شرافية: ضخمة الأذنين جسيمة. والشارف: الناقة المسنة، دون الناب.. شرفت تشرف شروفا، والجميع: شرف وشوارف، ولا يقال للذكر: شارف. وسهم شارف: طويل دقيق، ويقال: هو الذي طال عهده بالصيانة، فانتكث عقبه وريشه قال 1 : يقلب سهما راشه بمناكب ... ظهار لؤام فهو أعجف شارف وقصر مشرف، وكل شيء طال فهو مشرف. وأذن شرفاء: طويلة القوف. ومنكب أشرف: فيه ارتفاع حسن وهو نقيض الأهدأ. ورجل مشروف: شرف عليه غيره وشرفه. وشريف: أطول جبل في بلاد العرب. وقيل: شريف: بلد ببلاد بني تميم، وفيه جبال. وشراف: ماء أظنه لبني أسد. والشرف: شجر له صبغ أحمر، يقال له: البقم والعندم.'),
(2379, 'شفر', 'شفر', 'شفر', 'الشفر: شفر العين، والجميع: الأشفار والشفر: حد المشفر، ولا يقال المشفر إلا للبعير.. وامرأة شفيرة، وهي نقيض القعيرة. وشفير الوادي: حرفه و [كذلك] شفير جهنم. والشفاري: ضرب من اليرابيع، يقال له: ضأن اليرابيع، وهو أسمنها وأفضلها، ويقال: إنه أطولها أذنين، ولها ظفر في وسط ساقه. ويقال ذلك للرجل أيضا إذا كان طويل الأذنين، وهو شرافي أيضا. والشفرة: السكين، والجمع: الشفر والشفار.'),
(2380, 'رشف', 'رشف', 'رشف', 'الرشف: ماء قليل يبقى في الحوض، وهو وجه الماء الذي ترشفه الإبل بأفواهها. والرشيف: تناول الماء بالشفتين فوق المص. قال: سقين البشام المسك ثم رشفنه ... رشيف الغريريات ماء الوقائع 1 والرشف والرشيف: صوت مشافر الدابة، كشرب ماء قليل لا تستمكن منه جحفلته. وأصله من الشرب، رشفت كذا، أي: شربت ماء قليلا، قال جميل 2 : فلثمت فاها آخذا بقرونها ... شرب النزيف ببرد ماء الحشرج وقالوا: المص أروى والرشيف أشرب.'),
(2381, 'رفش', 'رفش', 'رفش', 'الرفش والرشف، لغتان: سوادية، وهي المجرفة يرفش بها البر رفشا، وقد تسمى المرفشة. وفي حديث سلمان الفارسي: أنه كان أرفش الأذنين 1 .'),
(2382, 'فرش', 'فرش', 'فرش', 'الفرش: مصدر فرش يفرش، فرشت الفراش: بسطته، وفرشته فلانا، بمعنى: فرشت له. وفرشته أمري: بسطته كله له. وافترش فلان ترابا أو ثوبا تحته. وافترش فلان لسانه يتكلم به ما شاء. وافترش الذئب ذراعيه: ربض عليهما. قال: ترى السرحان مفترشا يديه ... كأن بياض لبته الصديع 2 والأرض: فراش الأنام. وفراش اللسان: لحمة تحته. وفراش الرأس: طرائق من القحف. وفراش القاع والطين: ما يبس بعد نضوب الماء من الطين على وجه الأرض. وما بقي في الحوض إلا فراشة من ماء. والمفرش: [شيء يكون] مثل (شاذكونه) 3 والمفرشة: على الرحل يقعد عليها الرجل، أصغر من المفرش. والفراش: التي تطير طالبة للضوء. ويقال للخفيف من الرجال: فراشة. والفريش من الخيل: التي أتى عليها من يوم وضعت سبعة أيام، وبلغت أن يضربها الفحل. وجارية فريش: افترشها الرجل، فعيل جاء من افتعل. والفرش من الشجر والحطب: الدق الصغار، يقال: ما بها إلا فرش من الشجر. والفرش من النعم: التي لا تصلح إلا للذبح، وهي ما دون الحمولة، قال الله عز وجل: ومن الأنعام حمولة وفرشا 1 وشجة مفترشة ومفرشة: تبلغ فراش القحف. ويقال: مفرشة، أي: مسرعة في العظم وطعنة فارشة مفرشة، أي: داخلة في العظم، قال القطامي 2 : فوارش بالرماح كأن فيها ... شواطن ينتزعن بها انتزاعا وقيل: شجة مقرشة: مسرعة في العظم، بالقاف، وقارشة، وفي بيت القطامي: قوارش بالرماح.'),
(2383, 'شرب', 'شرب', 'شرب', 'شرب شربا وشربا. والشرب: وقت الشرب. والمشرب: الوجه الذي يشرب منه، ويكون موضعا ومصدرا، قال: ويدعى ابن منجوف أمامي كأنه ... خصي أتى للماء من غير مشرب 1 والمشرب: الشرب نفسه، والشراب: اسم لما يشرب، وكل شيء لا يمضغ فإنه يقال فيه: يشرب. ورجل شروب: شديد الشرب. وماء شروب: فيه ملوحة، ولا يمتنع من شربه. والشريب: كل ما يشرب. وشريبك: الذي يشرب معك. والشريب: المولع بالشراب، معروفا به. والشراب: الكثير الشرب الشديده. والمشربة: إناء يشرب به. والمشربة: الغرفة، وهي عند العامة: المشربة التي تكون في صفة. والمشربة: أرض لينة لا يزال فيها نبت أخضر ريان، قال 2 : بلاد بها عزوا معدا وغيرها ... مشاربها عذب وأعلامها ثمل يعني بالمشارب هاهنا: الماء. وبالثمل: جمع ثمال. ولكل نحيزة من الشجر شربة في بعض اللغات، والجميع: الشربات والشرائب. وكل أرض كثيرة الشجر: تسمى شربة، مشددة الباء. والشاربة: قوم مسكنهم على ضفة النهر، وهم الذين لهم ماء ذلك النهر. والشاربان: تجمعهما السبلة. والشاربان أيضا: ما طال من ناحيتي السبلة، ومنه سمي شاربا السيف، وبعض يسمي السبلة كلها شاربا واحدا، وليس بصواب. والشوارب: عروق محدقة بالحلقوم، وفيها يقع الشرق، ويقال: بل هي عروق تأخذ الماء ومنها يخرج الريق. وحمار صخب الشوارب، أي: شديد النهيق. والإشراب: لون قد أشرب من لون.. [يقال] أشرب فلان حب فلان، أي: خالط قلبه. والصبغ يتشرب في الثوب، والثوب يتشربه، أي: يتنشفه. واشرأب الرجل، إذا رفع عنقه لينظر، قال ذو الرمة 1 : ذكرتك أن مرت بنا أم شادن ... أمام المطايا تشرئب وتسنح'),
(2384, 'شبر', 'شبر', 'شبر', 'الشبر: الاسم والشبر: الفعل. شبرته شبرا بشبري. [يقال] : هذا أشبر من [هذا] ، أي: أوسع [منه] شبرا، وأنا أشبره. وأعطاها شبرها، أي: حقها في النكاح. والشبر: القربان. وهو شيء يعطيه النصارى بعضهم بعضا [يتقربون به] 2 ، قال عدي 3 : إذ أتاني خبر من منعم ... لم أخنه والذي أعطى الشبر'),
(2385, 'بشر', 'بشر', 'بشر', 'البشر: الإنسان الواحد رجلا كان أو امرأة. هو بشر وهي بشر [وهما بشر] ، وهم بشر، لا يثنى ولا يجمع، قال 1 : معاوي إننا بشر فأسجح ... فلسنا بالجبال ولا الحديدا والبشرة: أعلى جلد الوجه والجسد من الإنسان، وهو البشر إذا جمعته، وإذا عنيت به اللون والرقة، وجمع الجمع: أبشار، ومنه [اشتقت] مباشرة [الرجل] المرأة لتضام أبشارهما. ومباشرة الأمر: أن تحضره بنفسك. والبشر، بجزم الشين: قشرك البشرة عن الجلد، وقد يقال لجميع الجلود: بشرته إذا قشرت عنه قشرته التي ينبت فيها الشعر، والقطعة منه بشرة. والبشارة: ما بشرت به. والبشير: المبشر بخير أو شر. والبشارة: حق ما يعطى على ذلك، والبشرى: الاسم. والبشارة: الجمال. وامرأة بشيرة، قال الأعشى 2 : ورأت بأن الشيب جانبه ... البشاشة والبشاره والبشارة: تباشر القوم بأمر. وبشرته فأبشر وتبشر واستبشر، ولغة: بشرته أبشره. وتباشير الصبح: أوائله وأوائل كل أمر ولم أسمع له فعلا. واستبشر القوم: تباشروا. والمبشرات: الرياح تهب بالسحاب والغيث.'),
(2386, 'برش', 'برش', 'برش', 'البرش، والبرشة: لون مختلط بنقطة حمراء وأخرى سوداء، أو غبراء، أو نحو ذلك. وشاة برشاء: في وجهها نقط مختلفة، ورجل أبرش. وسمي جذيمة الأبرش الذي أصابه حرق فبقي فيه من أثر الحرق نقط سود وحمر، فقيل: جذيمة الأبرش، وهو ملك من ملوك اليمن. ربش 1 : الأربش: لغة في الأبرش. ويقال: مكان أربش: للكثير النبت المختلف.'),
(2387, 'شرم', 'شرم', 'شرم', 'الشرم: قطع من الأرنبة، وقطع من ثفر الناقة، قيل ذلك فيهما خاصة. وناقة شرماء مشرومة. ورجل مشروم الأنف أشرم. وكان أبرهة صاحب الفيل جاءه حجر فشرم أنفه، ونجا ليخبر قومه، فسمي الأشرم. وربما قيل: اشترم ثغرها. والشرم: لجة البحر'),
(2388, 'شمر', 'شمر', 'شمر', 'شمر: اسم ملك من اليمن، غزا مدينة السغد 1 فهدمها فسميت شمركند، ويقال: بل هو بناها فأعربت بسمرقند. والشمر: تشمير الثوب. [تقول] : شمرت الثوب، إذا رفعته. وكل شيء قالص فإنه متشمر، حتى يقال: لثة متشمرة، أي: لازقة بأسناخ الأسنان. ويقال: لثة وشفة شامرة. وشاة شامرة، أي: انضم ضرعها إلى بطنها من غير فعل. ورجل متشمر: ماض في الحوائج، وهو شمري أيضا، ويقال: شمري بكسر الشين، قال: ليس أخو الحاجات إلا الشمري ... والجمل البازل والطرف القوي 2 وتقول: أصابهم شر شمر، أي: شديد شامل. وقد انشمر لهذا الأمر، وشمر: إزاره. وشمر الشيء، أي: أرسله [في] السهم ونحوه، قال: 1 [أرقت له في القوم والصبح ساطع] ... كما سطع المريخ شمره الغالي المريخ: السهم.'),
(2389, 'رشم', 'رشم', 'رشم', 'الرشم: أن ترشم يد الكردي أو العلج. كما توشم يد المرأة، يجعل بالنيل، ليعرف بها وهو كالوشم.. والرشم: خاتم البر، والروشم لغة فيه، سوادية.. رشمت البر رشما، وهو وضع الخاتم على [كدس 2 ] البر فيبقى فيه أثره. والأرشم: الذي يتشمم الطعام، ويحرص عليه، قال 3 : لقى حملته أمه وهي ضيفة ... فجادت بنز للضيافة أرشما'),
(2390, 'رمش', 'رمش', 'رمش', 'الرمش: تفتل في الشفر وحمرة في الجفون مع ماء يسيل، والنعت: أرمش [والعين: رمشاء 4 ] .'),
(2391, 'مشر', 'مشر', 'مشر', 'المشرة: شبه خوصة تخرج في العضاه. وفي كثير من الشجر أيام الخريف، لها ورق وأغصان رخصة. يقال: أمشرت العضاه. ومشرت اللحم: قسمته، قال 1 : [فقلت: أشيعا مشرا القدر حولنا] ... وأي زمان قدرنا لم تمشر'),
(2392, 'مرش', 'مرش', 'مرش', 'المرش: شبه القرص من الجلد بأطراف الأظافير، يقال: قد ألطف مرشا وخرشا، والخرش أشد. والمرش: أرض إذا وقع عليها ماء المطر رأيتها كلها تسيل، يمرش الماء من وجهها في مواضع لا يبلغ أن يحفر حفر السيل، والجمع: أمراش. يقال: انتهينا إلى مرش من الأمراش، اسم للأرض مع الماء، وبعد الماء إذا أثر فيه. والإنسان يمترش 2 الشيء من هاهنا وهنا، ثم يجمعه. وسيل مارش: يمرش وجه الأرض. ومرشت الأكمة، أي: سالت. ويقال: سيل مارش وخارش، فأما الخارش فأضعف من المارش.'),
(2393, 'نشل', 'نشل', 'نشل', 'النشيل: لحم يطبخ بلا توابل، ينشل من المرق، أي: يخرج منه. والمنشل: حديدة ينشل بها اللحم من القدور، ويقال: منشال من المناشيل، قال: ولو أني أشاء نعمت بالا ... وباكرني صبوح أو نشيل 1 وفخذ ناشلة، أي: قليلة اللحم، نشل ينشل نشولا. وقال بعض الناس: إنها لمنشولة اللحم والناشلة أصوب. وقال بعضهم: فخذ منهوشة اللحم، ولا أعرف منشولة.'),
(2394, 'فشل', 'فشل', 'فشل', 'يقال: رجل فشل وفشل، وقد فشل يفشل عند الحرب والشدة ويضعف، وإنه لخشل فشل، والفشل: الجبان المرعوب، يبهت عند الروع، لا يحسن قتالا ولا شرادا، أي: هربا. والفشل: شيء من أداة الهودج تجعله المرأة تحتها. وجمعه: فشول. والفيشلة معروفة.'),
(2395, 'شبل', 'شبل', 'شبل', 'الشبل: ولد الأسد، والجميع: أشبال، وأدنى العدد: أشبل. وأشبل عليه، أي: عطف عليه.'),
(2396, 'شلم', 'شلم', 'شلم', 'الشيلم [والشالم] 1 ] ، بلغة أهل السواد: الزوان، يكون في البر.'),
(2397, 'شمل', 'شمل', 'شمل', 'شملهم أمر: أي: غشيهم، يشملهم شملا وشمولا. واللون الشامل: أن يكون لون أسود يعلوه لون آخر. والشمال: خلاف اليمين. والشمال: خليقة الإنسان. وجمعه: شمائل. قال لبيد 2 : هم قومي وقد أنكرت منهم ... شمائل بدلوها من شمالي ويقال: إنها لحسنة الشمائل، أي: شكلها وحالاتها، [ورجل كريم الشمائل، أي: في أخلاقه وعشرته 3 ] والشمأل: لغة في الشمال [وهي] ريح تهب عن يسار القبلة، وقد شملت تشمل شمولا. وغدير مشمول: شملته ريح الشمال، فبرد ماؤه، ومنه قيل للخمر مشمولة، أي: باردة، كما قال لبيد 4 : مشمولة غلثت بنابت عرفج ... كدخان نار ساطع أسنامها والشملة: كساء يشتمل به. والشملة: مصدر من اشتمل بثوب يديره على جسده كله، لا يخرج منه يده. والشملة الصماء: التي ليس تحتها قميص، ولا سراويل. وكره الصلاة فيها. وكره الصلاة ويده في جوفه. وشمل القوم: مجتمع عدهم وأمرهم، تقول: جمع الله شملهم. والمشملة: كساء له خمل متفرق يلتحف به دون القطيفة، ويذكر أيضا فيقال: مشمل: والمشمل: سيف قصير يشتمل عليه الرجل فيغطيه بثوب، يقال: جاء مشتملا على سيفه. وجاء فلان مشتملا على داهية. والرحم مشتملة على الولد إذا تضمنته. والشماليل: ما تفرق من شعب الأغصان في رءوسها كنحو شماريخ العذق. والشمال: ما لف فيه ضرع الناقة أو الشاة أو البقرة. والشمال: التي تجعل على صدر التيس فتمنعه من النزاء، وهو بلغتنا: النجاف: وناقة شملة شملال، أي: قوية سريعة. ومن أمثال العرب: ( أوردها سعد وسعد مشتمل ... يا سعد لا تروى بهذاك الإبل ) أي: أورد إبله الماء وهو مشتمل، أي: باشتمالك لا تروى. لأنك إذا أوردتها فلا بد من أن تتشمر وتحتزم وتأتمر حتى تروى الإبل.'),
(2398, 'شنف', 'شنف', 'شنف', 'الشنف: شدة البغض. شنفه: أبغضه، وشنف على فلان، أي: وجد وغضب. والشنف، مجزوم ومتحرك: معلاق في قوف الأذن، أي: في أعلى الأذن، وكذلك ما جمع في قلادة، والجميع: الشنوف'),
(2399, 'شفن', 'شفن', 'شفن', 'الشفون: الغيور الذي لا يفتر طرفه عن النظر من شدة الغيرة والحذر، قال 1 : [يسارقن الكلام إلي لما ... حسسن] حذار مرتقب شفون والشفن: شدة الجماع.. شفنها: فعلها فعلا شديدا.'),
(2400, 'نشف', 'نشف', 'نشف', 'النشف: دخول الماء في الأرض. والثوب وغيره.. نشفت الأرض الماء، ونشف الماء في الأرض، سواء. والنشف: [حجارة على قدر الأفهار ونحوها، سود كأنها محترقة، تسمى نشفة ونشفا] 2 . يحك بها وسخ الأديم وقدما الإنسان وبدنه في الحمام. سميت به لتنشفها الماء، ويقال: بل سميت به لانتشافها الوسخ عن مواضعه. والجميع: النشف.'),
(2401, 'فشن', 'فشن', 'فشن', 'فيشون: اسم نهر.'),
(2402, 'نفش', 'نفش', 'نفش', 'النفش: مدك الصوف حتى ينتفش بعضه عن بعض، وكل شيء تراه منتشرا رخو الجوف فهو منتفش. وأرنبة منتفشة، أي: انبسطت على الوجه. وقد تنفش الضبعان، أو بعض الطير، إذا نفش شعره وريشه كأنه يخاف أو يرعد. وأمة منتفشة الشعر. وإبل نوافش: ترددت بالليل في المراعي بلا راع، وهو كالهوامل بالنهار، [يقال] : هملت بالنهار ونفشت بالليل. وأنفشوا إبلهم: [أرسلوها بالليل 1 ]'),
(2403, 'شنب', 'شنب', 'شنب', 'الشنب: ماء ورقة يجري على الثغر، قال 2 : [لمياء في شفتيها حوة لعس] ... وفي اللثات وفي أنيابها شنب ويقال: الشنب: رقة الأنياب مع ماء وصفاء. ورمانه شنباء، وهي الإمليسية، ليس فيها حب، إنما هو ماء في قشر، على خلقة الحب من غير شحم'),
(2404, 'نشب', 'نشب', 'نشب', 'النشب: المال الأصيل ونشب الشيء في الشيء نشبا، كما ينشب الصيد في الحبالة. وأنشب البازي مخالبه في الأخيذة. ونشب فلان منشب سوء، أي: وقع موقعا لا يتخلص منه. والنشابة: واحدة النشاب. والناشبة: قوم يرمون بالنشاب، ومتخذه النشاب. ونشبة: من أسماء الذئب، معرفة، ولم يعرفه بعضهم.'),
(2405, 'نبش', 'نبش', 'نبش', 'النبش: نبشك عن الميت، وعن كل دفين.. نبش النباش القبر ينبشه نبشا. [وأنابيش العنصل: أصوله تحت الأرض، واحده: أنبوشة، قال: كأن سباعا فيه غرقى غدية ... بأرجائه القصوى أنابيش عنصل 1 ]'),
(2406, 'نشم', 'نشم', 'نشم', 'النشم: شجر تتخذ منها القسي، الواحدة: نشمة، قال امرؤ القيس 2 : رب رام من بني ثعل ... مخرج كفيه من ستره عارض زوراء من نشم ... غير باناة على وتره ومنشم: امرأة من حمير أو همدان عطارة إذا تطيبوا بطيبها اشتدت الحرب بينهم، فصارت مثلا في الشر. والمنشم: حب من العطر الصغار شاق المدق. وفي كلام بعضهم: لما نشم الناس في عثمان. أي: طعنوا فيه: ونالوا منه.. ومنه: نشم القوم في الأمر تنشيما، وقال 3 في المنشم: [تداركتما عبسا وذبيان بعد ما] ... تفانوا ودقوا بينهم عطر منشم وقال 4 : أراني وعمرا بيننا دق منشم ... [فلم يبق إلا أن أجن ويكلبا] ونشم اللحم، أي: تغير.'),
(2407, 'نمش', 'نمش', 'نمش', 'النمش: خطوط النقوش من الوشي ونحوه، قال ذو الرمة 1 : أذاك أم نمش بالوشم أكرعة ... مسفع الخد غاد ناشط شبب والنمش: النميمة.'),
(2408, 'مشن', 'مشن', 'مشن', 'المشن: ضرب بالسوط، يقال: مشنه ومتنه [ويقال: مشن ما في ضرع الناقة ومشقه، إذا حلبه 2 ]');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2409, 'شبم', 'شبم', 'شبم', 'الشبم: برد الماء، [يقال] : ماء شبم ومطر شبم، أي: بارد، قال 3 : مقبلها شبم بارد وقال الفرزدق: كأنها ضرب ريح تمتري شبما ... لمزنة كسواد الليل مدرار وتمتري: تحتلب، وقوله: لمزنة، يعني: من مزنة. والشبام: عود يشد في فم الجدي [لئلا يرضع] فهو مشبوم.. شبمته شبما وشبمته تشبيما. وشبام: حي من اليمن، وشبام: اسم جبل، قال الأعشى 1 : قد نال رب شبام فضل سودده ... إلى المدائن خاض الموت وادرعا'),
(2410, 'بشم', 'بشم', 'بشم', 'البشام: من شجر السواك، ترعاه الظباء. والبشم: تخمة على الدسم، وربما بشم الفصيل من كثرة [شرب] اللبن حتى يدقى سلحا فيهلك، يقال: دقي العجل، إذا كثر سلحه. قال الحسن: وأنت تتجشأ من الشبع بشما'),
(2411, 'ضز', 'ضز', 'ضز', 'الأضز الذي لا يستطيع ان يفرج بين حنكيه (إذا تكلم) 2 وهي من صلابة الرأس فيما يقال، قال رؤبة: دعني فقد 3 يقرع للأضز ... صكي حجاجي رأسه وبهزي والفعل ضز يضز ضززا.'),
(2412, 'ضد', 'ضد', 'ضد', 'الضد 4 كل شيء ضاد شيئا ليغلبه، والسواد ضد البياض والموت ضد الحياة، تقول: هذا ضده وضديده، والليل ضد النهار، اذا جاء هذا ذهب ذاك، ويجمع على الأضداد. قال الله عز وجل: ويكونون عليهم ضدا 5 .'),
(2413, 'ضر', 'ضر', 'ضر', 'الضر والضر لغتان، فاذا جمعت بين الضر والنفع فتحت الضاد، وإذا أفردت الضر ضممت الضاد إذا لم تجعله مصدرا، كقولك ضررت ضرا، هكذا يستعمله العرب. وقال الله تعالى: وإذا مس الإنسان الضر دعانا لجنبه 6 . والضرر: النقصان يدخل في الشيء، تقول: دخل عليه ضرر في ماله. ورجل ضرير: بين الضرارة، وقوم أضراء: ذاهبو البصر. ورجل ضرير وامرأة ضريرة: أضره المرض، والضرير: المريض، والمرأة بالهاء. والضرير: اسم للمضارة أكثر ما يستعمل في الغيرة، يقال: ما أشد ضريره عليها، قال رؤبة يصف حمار وحش: حتى اذا ما لان من ضريره 7 والضرورة: اسم لمصدر الاضطرار، [تقول: حملتني الضرورة على كذا، وقد اضطر فلان الى كذا وكذا، بناؤه: افتعل فجعلت التاء طاء، لان التاء لم يحسن لفظها مع الضاد] 8 . والضرتان: امرأتان لرجل واحد، وتجمع على ضرائر. وفلان مضر: أي ذو ضرائر. والمضر: الرجل الذي عليه ضرة من مال. والمضر: الداني، يقال: مر فلان فأضرني إضرارا أي دنا مني دنوا شديدا. والضرر: الزمانة، ومنه قوله تعالى: غير أولي الضرر 9 . وأضر الطريق بالقوم: ضاق بهم ودنا منهم. وضرة الابهام: لحمة تحتها. وضرة الضرع: لحمها، والضرع يذكر ويؤنث. والضرتان: الأليتان من جانبي المقعد 10 ، وهما شحمتان تهدلان من جانبيهما 11 .'),
(2414, 'رض', 'رض', 'رض', 'الرض: دقك الشيء، ورضاضه: دقاقه. والرضراض: حجارة تترضرض على وجه الأرض أي [تتحرك] 12 ولا تثبت، وسميت بها لتكسرها من غير فعل الناس بها. والرضراضة: الكثيرة اللحم.'),
(2415, 'ضل', 'ضل', 'ضل', 'ضل يضل اذا ضاع، يقال: ضل يضل ويضل 13 . ومن قال: يضل، قال في الأمر اضلل، ومن قال: يضل، قال في الأمر: اضلل. وتقول: ضللت مكاني إذا لم تهتد له: وضل اذا جار عن القصد. وأضل بعيره إذا أفلت فذهب. ويقال من ضللت: أضل، ومن ضللت أضل، والضلال والضلالة مصدران، وكل شيء نحوه من المصادر يجوز إدخال الهاء فيها وإخراجها في الشعر، وأما في الكلام فيقتصر به على ما جاءت به اللغات. ورجل مضلل أي لا يوفق لخير، صاحب غوايات وبطالات. وفلان صاحب أضاليل، الواحدة أضلولة، قال: قد تمادى في أضاليل الهوى 14 والضلضلة: كل حجر [قدر 15 ما] يقله الرجل، أو فوق ذلك (أملس) 16 يكون في بطون الأودية. وليس في باب المضاعف كلمة تشبهها. والضليل على بناء سكير: الذي لا يقلع عن الضلالة، قال رؤبة: قلت لزير لم تصله مريمه ... ضليل أهواء الصبا يندمه 17 وماء ضلل: يكون تحت الصخرة لا تصيبه الشمس. والضالة من الابل: ما يبقى بمضيعة لا يعرف ربها، الذكر والأنثى فيه سواء، ويجمع ضوال. والتضلال مصدر كالتضليل، والضل مثله.'),
(2416, 'لض', 'لض', 'لض', 'اللضلاض: الدليل، ولضلضته: التفاته وتحفظه، قال: وبلد يعيا على اللضلاض ... (أيهم مغبر الفجاج فاضي) 18'),
(2417, 'ضن', 'ضن', 'ضن', 'الضن والضنة والمضنة، كل ذلك من الإمساك والبخل، تقول: رجل ضنين. وقوله تعالى وما هو على الغيب بضنين 19 ، أي بمكتوم لما أوحي إليه من القرآن. وقرأت عائشة: بظنين، أي بمتهم. وثوب مضنة. وعلق مضنة أي [هو شيء نفيس] 20 يضن به [ويتنافس فيه] 21 . وهذا ضني من بين إخواني (أي أختص به وأضن بمودته) 22 . وفي الحديث: ولا تضطني مني أي لا تتخلي بانبساطك، وهو تفتعلي من الضن.'),
(2418, 'نض', 'نض', 'نض', 'نضيض من الماء أي نض قليل، كأنما يخرج من حجر، وتقول: نض الماء ينض. وفلان يستنض معروف فلان أي يستديمه وينال منه، قال رؤبة: إن كان خير منك مستنضا ... فاقني فشر القول ما أمضا 23 وأصابني نض من أمره أي مكروه. والنضنضة: صوت الحية، ونحوه من تحريك الحنكين. وحية نضناض، اذا أخرجت لسانها تحركه. ويقال: النض الدرهم الصامت. وتقول: هذا نضاضة ولد أبويه، ونضاضة الماء وغيره أي آخره وبقيته.'),
(2419, 'ضف', 'ضف', 'ضف', 'الضفة والضفة، لغتان،: جانبا النهر، تقع عليهما النبائت، وتجمع ضفات وضفافا. والضفف: العجلة في الأمر، وتقول: لقيته على ضفف أي على عجلة، قال: وليس في رأيه وهن ولا ضفف 24 وماء مضفوف أي مزدحم عليه. ورجل مضفوف في ماله بمعناه. ودخلت في ضفة الناس أي جماعتهم. ويقال: الضفف كثرة الأيدي على الطعام. وفي الحديث:'),
(2420, 'ضب', 'ضب', 'ضب', 'الضب يكنى أبا حسل. والعرب تقول: الضب قاضي الطير والبهائم، وإنما اجتمعت اليه أول ما خلق [الله] الانسان فوصفوه له، فقال الضب: تصفون خلقا ينزل الطير من السماء ويخرج الحوت من الماء، فمن كان ذا جناح فليطر، ومن كان ذا حافر فليحفر. والضبة: حديدة يضبب بها الخشب، [والجميع الضباب] 34 . والضب: الغل في القلب، وهو يضب إضبابا من العداوة، قال: وفي صدره ضب من الغل كامن 35 والتضبب: السمن حين يقبل. والضيبة: سمن ورب يجعل للصبي، وتقول: ضيبوا لصبيكم. وأضب القوم: تكلموا، [وأضبوا اذا سكتوا، وزعم أنه من الأضداد] 36 . وأضب على الشيء: أشرف عليه. والضب: داء يأخذ في الشفة فترم. والضب والضبوب: سيلان الدم من الشفاه. وأضبت السماء: من الضباب، وهو الذي يبدو كالغبار يغشى الأرض بالغدوات، وسماء مضبة، وأضب يومنا يضب. وامرأة ضبضب، ورجل ضباضب: فحاش جريء. (ورجل ضباضب أيضا أي قصير سمين مع غلظ) 37 . (وفي الحديث: إنما بقيت من الدنيا ضبابة كضبابة الإناء يعني في القلة وسرعة الذهاب.'),
(2421, 'بض', 'بض', 'بض', 'امرأة بضة تارة، مكتنزة اللحم في نصاعة لون. وبشرة بضة بضيضة، وامرأة بضة بضاض، قال رؤبة: لو كان خرزا في الكلى ما بضا 38 وقال: كل رداح بضة بضباض 39 وبض الحجر اذا خرج منه الماء، وما خرج منه بضاضته 40 . [وبئر بضوض: يجيء ماؤها قليلا قليلا] 41 . والبضباض: قالوا: الكمأة وليست بمحضة) 42 .'),
(2422, 'ضم', 'ضم', 'ضم', 'الضم: ضمك الشيء إلى الشيء، وضاممت فلانا أي قمت معه في أمر واحد. والضمام: كل شيء يضم به شيء الى شيء. والإضمامة: الجماعة من الناس، ليس أصلهم واحدا ولكنهم لفيف، وتجمع على أضاميم، قال: والحقب ترفض منهن الأضاميم 43 والضماضم: الأسد، والضمام أيضا 44 ، وضمضمته: صوته. وقيل: إضمامة من الكتب أي المضموم بعضها الى بعض. والضم والضمام: الداهية الشديدة. وضمضم: اسم رجل. والاضطمام: الضم، والرجل اذا ضم شيئا الى شيء فقد اضطمه، قال: مخبوءة تفضحها الدمامه ... في نفس من يضطمها الندامه 45'),
(2423, 'مض', 'مض', 'مض', 'المضمضة: تحريك الماء في الفم. وكحل يمض العين، ومضيضه: حرقته، (وأنشد: قد ذاق أكحالا من المضاض 46 وأمضني الأمر أي بلغ مني المشقة ومضضت منه، (وقال رؤبة: فاقني فشر القول ما أمضا) 47 وكذلك الهم: يمض القلب أي يحرقه. [والمضماض: النوم. يقال: ما مضمضت عيني بنوم أي ما نامت، قال رؤبة: من يتسخط فالإله راضي ... عنك ومن لم يرض في مضماض 48 أي في حرقة] 49 . وأمضني السوط، وأمضني الجرح، وقد يقول النحويون: مضني الجرح، وما كان في الجسد وسائره بألف. ومضاض: اسم ابن عمرو الجرهمي. والمض: مضيض الماء كما تمتصه (بفمك) 50 ، ويقال: لا تمض مضيض العنز، يصف الشراب اذا شرب. وفي الحديث: ولهم كلب يتمضمض عراقيب الناس 51 ، أي يمض) 52 . (والمض: أن يقول الانسان بطرف لسانه شبه لا وهو هيج بالفارسية، وأنشد: سألتها الوصل فقالت مض ... وحركت لي رأسها بالنعض) 53'),
(2424, 'ضرس', 'ضرس', 'ضرس', 'الضرس: يذكر، فاذا قلت: رحى أنثت. والضرس: العض الشديد بالضرس من ضرسته الحرب. والضرس: ذهاب حدة الأسنان من حموضة. والضرس: ما خشن من الآكام والأخاشب، ويجمع على ضروس. وبئر مضروسة: تطوى بضروس عظام من الحجارة محرفة النواحي. وناقة ضروس: تعض حالبها. والتضريس: تحزيز ونبر في ياقوتة أو لؤلؤة أو خشبة. وقدح مضرس: ليس بأملس. والضروس من الإبل: التي تقري جرتها أي تجمعها في شدقيها. والضروس: الأمطار المتفرقة، واحدها ضرس. وجرير مضرس بالعقب اذا لوي عليه 54 .'),
(2425, 'ضرز', 'ضرز', 'ضرز', 'الضرز: ما صلب من الصخور. والضرز: الرجل المتشدد، الشحيح.'),
(2426, 'ضزن', 'ضزن', 'ضزن', 'الضيزن: النخاس. ويقال للرجل اذا زاحم أباه في امرأته. وجارية ضيزن، قال أوس بن حجر: والفارسية فيكم غير منكرة ... فكلكم لأبيه ضيزن سلف 55 شبههم بالمجوس يتزوج الرجل منهم امرأة أبيه، وامرأة ابنه.'),
(2427, 'ضفز', 'ضفز', 'ضفز', 'ضفزت البعير ضفزا: لقمته لقما عظاما فاضطفز. وكل لقمة ضفيزة. وضفزت اللجام على الفرس، وضفزته لجامه: أدخلته في فيه.'),
(2428, 'ضبز', 'ضبز', 'ضبز', 'الضبز: شبه 56 اللحظ، وهو النظر من جانب العين. [والضبز: الشديد المحتال من الذئاب، وأنشد: وتسرق مال جارك باحتيال ... كحول ذؤالة شرس ضبيز] 57'),
(2429, 'ضمز', 'ضمز', 'ضمز', 'الضمز من الإكام، الواحدة ضمزة، وهي أكمة صغيرة خاشعة، (وقال: موف بها على الإكام الضمز) 58 والضامز: الساكت. وضمز البعير يضمز ضموزا أي لا يجتر. وناقة ضموز وضامز أي لا يسمع لها رغاء.'),
(2430, 'ضرط', 'ضرط', 'ضرط', 'الضراط معروف، وقد ضرط يضرط ضرطا. ورجل ضرط، من الضراط، نعت له، والضرط المصدر له، والضراط الاسم . ضطر: الضيطر: اللئيم، قال: صاح ألم تعجب لذاك الضيطر ... الأعفك الأحدل ثم الأعسر 59 وكذلك الضيطار. والضوطر: العظيم 60 .'),
(2431, 'ضفط', 'ضفط', 'ضفط', 'الضفاطة: ضعف الرأي والعقل، ورجل ضفيط. والضفاطة: الدف عن ابن سيرين، [قال] 61 : اين ضفاطتكم؟ أي أين دفكم 62 ؟ [والضفاط: الذي قد ضفط بسلحه، ورمى به] 63 .'),
(2432, 'ضبط', 'ضبط', 'ضبط', 'الضبط: لزوم شيء [لا يفارقه] 64 في كل شيء. ورجل ضابط: شديد البطش والقوة والجسم. ورجل أضبط، أي أعسر يسر، يعمل بيديه معا، وامرأة ضبطاء.'),
(2433, 'نضد', 'نضد', 'نضد', 'نضدت الشيء بعضه الى بعض أو فوق بعض، والنضد الاسم، وهو من حر متاع البيت، ينضد بعضه فوق بعض. والموضع الذي ينضد عليه: نضد أيضا كما قال النابغة: خلت سبيل أتي كان يحبسه ... ورفعته الى السجفين فالنضد 65 وأنضاد الجبال: جنادل بعضها فوق بعض، وبلزق بعض، الواحد نضد. وأنضاد القوم: جماعتهم وكثرتهم.'),
(2434, 'ضمد', 'ضمد', 'ضمد', 'ضمدت رأسه بالضماد: وهو خرقة تلف على الرأس 66 عند الادهان [والغسل ونحو ذلك] 67 . وقد يوضع على الرأس من قبل الصداع يضمد به. والضمد: حقد متضمد في القلب أي ثابت. ويقال: الضمد الغيظ، وضمد عليه أي اغتاظ، قال النابغة: تنهى الظلوم ولا تقعد على ضمد 68'),
(2435, 'مضد', 'مضد', 'مضد', 'المضد: لغة في الضمد، في بابه، يمانية، من المقلوب.'),
(2436, 'نتض', 'نتض', 'نتض', 'نتض الجلد نتوضا اذا خرج عليه داء فأثار القوباء ثم انتشر أطباقا بعضها فوق بعض، وهي قشور كلما قشر جلد بدا جلد آخر. وأنتض العرجون من الكربة، وهو ينتض عن نفسه كما تنتض الكمأة 69 .'),
(2437, 'ضبث', 'ضبث', 'ضبث', 'الضبث: قبضك بكفك على الشيء. وناقة ضبوث أي يشك في سمنها وهزالها حتى تضبث باليد، أي تجس.'),
(2438, 'ضثم', 'ضثم', 'ضثم', 'الضيثم اسم من أسماء الأسد، [فيعل من ضثم] 70 .'),
(2439, 'نضر', 'نضر', 'نضر', 'نضر الورق والشجر والوجه ينضر نضورا ونضرة ونضارة فهو ناضر: حسن. [وقد نضره] 71 الله وأنضره. والنضار: الخالص من جوهر التبر والخشب، [وجمعه أنضر] 72 . ويقال: قدح نضار، يتخذ من أثل ورسي اللون يكون بالغور. وذهب نضار، صار هنا نعتا. والنضر 73 : الذهب، [وجمعه أنضر، وأنشد: كناحلة من زينها حلي أنضر ... بغير ندى من لا يبالي اعتطالها] 74 وجارية غضة نضيرة، وغلام غض نضير. وقد أنضر الشجر اذا اخضر 75 ورقه، وربما صار النضر نعتا، تقول شيء نضر ونضير [وناضر] 76 . وتقول للأخضر: ناضر كما تقول للابيض: ناصع، تريد خلوص اللون وصفاءه. ويقال: نضر الله وجهه فنضر نضارة، وهكذا كلام العرب، وبعضهم يقول: فنضر، وبعضهم يقول: فنضر، كله من كلام العرب، إلا أن أحبها اليهم: فنضر نضارة. ومن قال: نضر، قال: ينضر وجهه فهو ناضر، من فعله، قال الله: وجوه يومئذ ناضرة 77 ، ووجهه منضور، من فعل الله.'),
(2440, 'رضن', 'رضن', 'رضن', 'المرضون شبه المنضود من حجارة ونحوها، يضم بعضها إلى بعض. قال الضرير: المنضود المتقارب في الوضع لأن بعضه على بعض، والمرضون والموضوم والمبسوط (دونه) 78 .'),
(2441, 'ضفر', 'ضفر', 'ضفر', 'الضفر: حقف من الرمل طويل عريض، وقد يثقل، قال العجاج: عوانك من ضفر مأطور 79 والضفر: نسجك الشعر بعضه في بعض. والضفير: خصلة من الشعر منسوجة على حدتها، وضفيرة بالهاء.'),
(2442, 'رضف', 'رضف', 'رضف', 'الرضف: حجارة على وجه الأرض قد حميت. وشواء مرضوف: يشوى على تلك الحجارة. وحمل مرضوف: تلقى تلك الحجارة المسخنة 80 في جوفه حتى ينشوي. والرضفة: سمة تكوى برضفة من حجارة حيثما كانت. والرضف، مجزوم، عظام 81 في الركبة، كالأصابع المضمومة قد أخذ بعضها في بعض، الواحدة بالهاء، ومنهم من يثقل فيقول: رضفة.'),
(2443, 'فرض', 'فرض', 'فرض', 'الفرض: جند يفترضون، ويجمع فروضا. والفرض: ما أعطيت من غير قرض، قال: ألا ليس فتى الفتيا ... ن بالرحض ولا البض ولكن مبتنى العرف ... بفرض كان أو قرض 82 والفرض: الترس. والفرض: الإيجاب، تفرض على نفسك فرضا، والفريضة الاسم. والفرض: الحز للفرضة في سية القوس والخشبة. والفارض في قوله تعالى: لا فارض ولا بكر 83 أي لا مسنة. ولحية فارضة أي ضخمة. وفرائض الله: حدوده. والفرضة: ما يشرب الماء من النهر 84 . ومرفأ السفينة حيث يركب، ويجمع على فرض وفراض.'),
(2444, 'رفض', 'رفض', 'رفض', 'الرفض: تركك الشيء والرفض: الشيء المتحرك المتفرق، ويجمع على أرفاض كأرفاض القوم في السفر. وارفاض الشيء حيث يجمعه الريح في مواضع وتفرقه. وارفض الدمع: سال ارفضاضا. والروافض: جند تركوا قائدهم وانصرفوا، كل طائفة منها رافضة، وهم قوم أيضا لهم رأي وجدال يسمون الروافض، والنسبة إليهم رافضي. وترفض في معنى ارفض. قال: حتى ترفض بالأكف خطامها 85 ورفضته ترفيضا ومرافض الأرض: مساقطها من نواحي الجبال، واحدها مرفض. والرفاض: الطرق المتفرقة أخاديدها 86 ، قال: بالعيس فوق الشرك الرفاض 87'),
(2445, 'ضرب', 'ضرب', 'ضرب', 'الضرب يقع على جميع الأعمال، ضرب في التجارة، وفي الأرض، وفي سبيل الله، يصف ذهابهم وأخذهم فيه. وضرب يده الى كذا، وضرب فلان على يد فلان: حبس عليه أمرا أخذ فيه وأراده، ومعناه: حجر عليه. والطير الضوارب: المخترقات الأرض، الطالبات الرزق. وضرب الدهر من ضرباته أي كان كذا وكذا. وضربت المخاض اذا شالت بأذنابها ثم ضربت بها فروجها ومشت فهي ضوارب. والفحل من الإبل يضرب الشول ضرابا، وصاحبها أضربها الفحل. وأضرب الريح والبرد النبات إضرابا هكذا تقول العرب. وضرب النبات ضربا فهو ضرب إذا أضر به البرد. وأضربت السمائم الماء اذا أنشفته حتى تسقيه الأرض 88 . وأضرب فلان عن كذا أي كف وأنشد: أصبحت عن طلب المعيشة مضربا ... لما وثقت بأن مالك مالي] 89 ورجل مضرب: شديد الضرب. وضريب 90 القداح: هو الموكل بها. والضرب: النحو والصنف، يقال: هذا ضرب ذاك وضريب ذاك أي مثله، قال: وما رأينا في الأنام ضربا ... ضربك إلا حاتما وكعبا 91 والضرب: العسل الخالص. والضرب: الرجل الخفيف اللحم، ليس بجسيم، قال طرفة: أنا الرجل الضرب الذي تعرفونه ... خشاش كرأس الحية المتوقد 92 والاضطراب: تضرب الولد في البطن. ويقال: اضطرب الحبل بين القوم اذا اختلفت كلمتهم. ورجل مضطرب الخلق: طويل، غير شديد الأسر 93 . والضريب: الصقيع. والضريب: النظير، والضريب: المضروب. والضريب من اللبن اذا خلط المخض بالحقين. والضريب: الشهد. والضريب: البطين من الناس وغيرهم. والضريبة: الطبيعة، يقال: إنه لكريم الضرائب. والضريبة: غلة تضرب على العبد. والضريبة: كل شيء ضربته بسيفك من حي أو ميت، [وأنشد لجرير: واذا هززت ضريبة قطعتها ... فمضيت لا كزما ولا مبهورا] 94 والضريبة: مضرب السيف. والضريبة: الصوف يضرب بالمطرق. (والمضرب: المقيم في البيت، يقال: أضرب فلان في بيته، أي أقام فيه. ويقال: أضرب خبز الملة فهو مضرب اذا نضج وآن له أن يضرب بالعصا وينفض عنه رماده وترابه، قال ذو الرمة يصف خبزة: ومضروبة في غير ذنب بريئة ... كسرت لأصحابي على عجل كسرا) 95 [والضارب: السابح في الماء، وقال ذو الرمة: كأنني ضارب في غمرة لجب] 96 [والضرائب: ضرائب الأرضين في وظائف الخراج عليها] 97 . (والضارب: الوادي الكثير الشجر، يقال: عليك بذلك الضارب فانزله، وأنشد: لعمرك إن البيت بالضارب الذي ... رأيت وإن لم آته لي شائق) 98'),
(2446, 'رضب', 'رضب', 'رضب', 'الرضاب: ما يرضب الإنسان من ريقه، كأنه يمتصه. واذا قبل جاريته رضب ريقها 99 . وسمي رضابا لبرده وبلله. وقيل: الرضاب فتات المسك، وليس كذلك. والرضب الفعل. والراضب: ضرب من السدر، والواحدة راضبة.'),
(2447, 'برض', 'برض', 'برض', 'برض النبات يبرض بروضا، وهو [اول] 100 ما يعرف ويتناول منه النعم. والتبرض: التبلغ بالبلغة من العيش، والتطلب له من هنا وهنا قليلا بعد قليل. وكذلك تبرض الماء من الحوض اذا قل 101 ، تصيب في القربة من هنا وهنا، قال: وقد كنت براضا لها قبل وصلها ... فكيف ولدت حبلها بحباليا 102 أي كنت أطالبها في الفينة بعد الفينة، فكيف وقد علق بعضنا ببعض، والابتراض منه. وثمد برض أي قليل من الماء، قال: في العد لم يقدح ثمادا برضا 103 والبراض بن قيس الكناني الذي فتك بعروة بن كثير الرحال، وهو الذي هاجت به حرب عكاظ. والمبرض الذي يأكل شيئا من ماله ويفسده، وكذلك البراض.'),
(2448, 'ربض', 'ربض', 'ربض', 'ربض البطن: ما ولي الأرض من البعير وغيره، ويجمع على أرباض 104 ، وقوله: أسلمتها معاقد الأرباض 105 أي معاقد الحبال على أرباض البطون. والربض: ما حول مدينة أو قصر من مساكن جند أو غيرهم، ومسكن كل قوم على حيالهم: ربض، ويجمع على أرباض. ربض، ويجمع على أرباض. والربضة: مقتل قوم قتلوا في بقعة واحدة. والربيض: شاء برعاتها اجتمعت في مربضها. وربض الرجل: امرأته. وتزوج الرجل امرأة تربضه أي تعزبه أي تذهب عزوبته. وكل شيء لا يبرك على أربعة فهو يربض ربوضا. والأرنبة رابضة أي ملتزقة بالوجه. والربض في قول بعضهم الأرطاة الضخمة، واحدها ربوض، قال: بربض الأرطى وحقف أعوجا 106 والربوض من نعت الأرطى، ويقال من نعت البقرة الرابضة. وفي الحديث: احلب من اللبن ما يربض القوم أي يسقيهم. وقربة ربوض أي ضخمة عظيمة. وشجرة ربوض، ودرع ربوض. والرويبضة: الانسان المجهول، والجمع رويبضون ورويبضات. وفي ذكر الفتنة: ويتكلم فيها الرويبضة، قيل: فما الرويبضة؟ قال: الفويسق يتكلم في أمر العامة. وفي حديث: فانبعث لها واحد من الرابضة ، والرابضة ملائكة أهبطوا مع آدم يهدون الضلال.'),
(2449, 'ضبر', 'ضبر', 'ضبر', 'ضبر الفرس يضبر ضبرا اذا وثب في عدوه. والضبر: جلدة تغشى خشبا فيها رجال، تقرب الى الحصون لقتال أهلها، والجمع الضبور. والضبر: شدة تلزيز العظام واكتناز اللحم، وجمل مضبور الخلق، قال: مضبر اللحيين بسرا منهسا 107 والضبر: الجماعة من الناس. والإضبارة: حزمة من صحف أو سهام ونحوه، والضبارة لغة فيها.'),
(2450, 'ضرم', 'ضرم', 'ضرم', 'الضرم من الحطب: ما التهب سريعا، الواحدة ضرمة. والضرم: مصدر ضرمت النار تضرم ضرما. وضرم الأسد اذا اشتد حر جوفه من الجوع، وكذلك غيره من اللواحم، قال: لا تراني والغا في مجلس ... في لحوم القوم كالسبع الضرم 108 والضرم: شدة العدو، وفرس ضرم العدو وضرم الرفاق، قال: رفاقها ضرم وجريها حذم ... ولحمها زيم والبطن مقبور يقول: اذا مشت على الرقاق اشتد جريها. والضرام: الذي تضرم به النار. والضرام: جماعة الضرم من الحطب. واضطرمت النار، وأضرمها غيرها في الحطب. والضرام: ما يرى من اشتعال اللهب. والضريم: اسم للحريق.'),
(2451, 'رضم', 'رضم', 'رضم', 'الرضم: حجارة مجتمعة غير ثابتة في الأرض، كأنها منثورة في بطون الأودية، ويجمع الرضم على رضام. وحجارة مرضومة بعضها فوق بعض. وبرذون مرضوم العصب اذا كان قد تشنج وصار فيه كالعقد [وأنشد: مبين الأمشاش مرضوم العصب] 109 ورضام: اسم موضع.'),
(2452, 'رمض', 'رمض', 'رمض', 'الرمض: حر الحجارة من شدة حر الشمس، والاسم الرمضاء. وأرض رمضة بالحجارة. ورمض الانسان رمضا اذا مشى على الرمضاء. والرمض: حرقة القيظ. وقد أرمضني هذا الأمر فرمضت، [قال رؤبة: ومن تشكى مضلة الإرماض ... أو خلة أحركت بالإحماض] 110 والرمض: مطر قبل الخريف. والرمضاء ملتهبة يعني شدة الحر. ورمضان: شهر الصوم.'),
(2453, 'مرض', 'مرض', 'مرض', 'التمريض: حسن القيام على المريض، [يقال: مرضت المريض تمريضا اذا قمت عليه] 111 . وتمريض الأمر: ان توهنه ولا تنضجه 112 . [ويقال: قلب مريض من العداوة ومن النفاق، قال الله تعالى: في قلوبهم مرض 113 *، أي نفاق] 114 . والمراضان: واديان ملتقاهما واحد 115 . وقال فلان قولا فأمرض، أي قارب الصواب ولم يبلغه، قال: اذا ما قال أمرض أو أصابا 116'),
(2454, 'مضر', 'مضر', 'مضر', 'لبن مضير: شديد الحموضة، ويقال: إن مضر كان مولعا بشربه فسمي به. والمضيرة: مريقة تطبخ بلبن وأشياء. وتماضر: اسم امرأة. وتمضر: اعتزى الى مضر. والتمضر: التعصب لمضر.'),
(2455, 'ضمر', 'ضمر', 'ضمر', 'الضمر من الهزال (ولحوق البطن) ، والفعل: ضمر يضمر ضمورا فهو ضامر. وقضيب ضامر: انضمر وذهب ماؤه. والمضمار: موضع تضمر فيه الخيل، وتضميرها أن تعلف قوتا بعد السمن. والضمير: الشيء الذي تضمره في ضمير قلبك. وتقول: أضمرت صرف الحرف اذا كان متحركا فأسكنته. والغناء مضمار الشعر أي به يختبر، قال: تغن بالشعر إما كنت ذا بصر ... إن الغناء لهذا الشعر مضمار 117 والضمر من الرجال: المهضم البطن، اللطيف الجسم، وامرأة ضمرة. والضمار من العدات: ما كان ذا تسويف، قال الراعي: حمدن مزاره ولقين منه ... عطاء لم يكن عدة ضمارا 118 ولؤلؤ مضطمر أي فيه بعض الانضمام، قال: تلألؤ لؤلؤ فيه اضطمار 119 وتضمر وجهه أي انضمت جلدته من الهزال. والضمران: من دق الشجر، وقيل: هو الحمض. والضمران: اسم كلب. والضومران والضيمران: نوع من الريحان 120 . والضمار من المال: ما لا يرجى رجوعه.'),
(2456, 'نضل', 'نضل', 'نضل', 'نضل فلان فلانا أي فضله في مراماة فغلبه. وفلان يناضل عن فلان أي تكلم عنه بعذر ودفع 121 . [وخرج القوم ينتضلون اذا استبقوا في رمي الأغراض. وفلان نضيلي: وهو الذي يراميه ويسابقه] 122 . [والمناضلة: المفاخرة، قال الطرماح: ملك تدين له الملوك ... ولا يجاثيه المناضل 123 وانتضل القوم: اذا تفاخروا، وقال لبيد: فانتضلنا وابن سلمى قاعد ... كعتيق الطير يغضى ويجل] 124'),
(2457, 'فضل', 'فضل', 'فضل', 'الفضل معروف. والفاضلة اسم الفضل. والفضالة: ما فضل من كل شيء. والفضلة: البقية من كل شيء. والفضيلة: الدرجة والرفعة في الفضل. والتفضل: التطول على غيرك، [وقال الله- جل وعز-: يريد أن يتفضل عليكم 125 معناه: يريد أن يكون له الفضل عليكم في القدر والمنزلة، وليس من التفضل الذي هو بمعنى الإفضال والتطول] 126 . والتفضل: التوشح. ورجل فضل ومتفضل، وامرأة فضل ومتفضلة. وعليها ثوب فضل، وهو أن تخالف بين طرفيه على عاتقها تتوشح به، قال: اذا تغرد فيه القينة الفضل 127 وافضل فلان على فلان: أناله من فضله وأحسن إليه. وأفضل من الأرض والطعام اذا ترك منه شيئا. ولغة أهل الحجاز فضل يفضل 128 ورجل مفضال: كثير الخير. والفضال مصدر كالمفاضلة. والفضال جمع الفضلة من الخمر وغيرها. [والفضال: الثوب الواحد يتفضل به الرجل، يلبسه في بيته، وأنشد: وألق فضال الوهن عنك بوثبة ... حوارية قد طال هذا التفضل] 129 [ويقال: فضل فلان على فلان اذا غلب عليه، وفضلت الرجل: غلبته، وأنشد: شمالك تفضل الأيمان إلا ... يمين أبيك نائلها الغزير] 130'),
(2458, 'نضف', 'نضف', 'نضف', 'النضف هو الصعتر 131 ، الواحدة نضفة [وأنشد: ظلا بأقرية التفاح يومهما ... ينبشان أصول المعد والنضفا] 132'),
(2459, 'ضفن', 'ضفن', 'ضفن', 'الضفن: ضربك بظهر قدمك است الشاة ونحوها. والاضطفان: أن تضرب به است نفسك. والضفن لغة في الضفندد. وامرأة ضفنة وضفنددة أي رخوة ضخمة. وضفنت الى القوم أضفن ضفنا اذا أتيتهم. وضفنت مع الضيف اذا جئت معه، وهو الضيفن. والضفن: الأحمق من الرجال مع عظم خلق.'),
(2460, 'نفض', 'نفض', 'نفض', 'النفض: ما تساقط من غير نفض في أصول الشجر من أنواع الثمر. ونفوض الأرض: راشانها، بمعنى التراب، وهي فارسية، إنما هي أشرافها، وقيل: تفوض الأرض التراب يلقى على شط النهر من النهر. والنفاضة: ما انتفض من التمر. والنفضة: قوم يبعثون الى عدوهم [ينفضون الارض متجسسين لينظروا هل فيها عدو أو خوف] 133 . واستنفض القوم: بعثوا النفضة. وفلان نفيضة اذا كان ينفض الطريق وحده، قال الفرزدق: ترد المياه حضيرة ونفيضة ... ورد القطاة اذا اسمأل التبع 134 وقال آخر: أقبلت تنفض الخلاء برجليها ... وتمشي تخلج المجنون 135 والحضيرة: الجماعة من القوم، والنفيضة الواحدة 136 . والنافض: الحمى ورعدتها ونفضانها، ونفضت الحمى، وأخذته الحمى بنافض وصالب. والإنفاض: ذهاب الزاد، وأنفض القوم. وأنفضت جلة التمر اذا نفضت ما فيها من التمر. والنفض من قضبان الكرم بعد ما ينضر الورق وقبل أن يتعلق حوالقه وهو أغض ما يكون وأرخصه، وقد انتفض الكرم عند ذلك، والواحدة نفضة. والنفض: ما مات من النحل في المعسل. والنفض: ما كان من الأرضين ليس بمعمور. ونفض الثوب: ذهب صبغه. وتنفض الرجل: قضى حاجته. والنفاض: إزار من أزر الصبيان، قال: جارية بيضاء في نفاض 137 (ويقال: استنفض ما عنده أي استخرجه، وقال رؤبة: صرح مدحي لك واستنفاضي) 138'),
(2461, 'نضب', 'نضب', 'نضب', 'نضب الماء ينضب نضوبا إذا ذهب في الأرض. ونضب الدبر 139 اذا اشتد أثره في الظهر. ونضبت المفازة اذا بعدت، وخرق ناضب: بعيد. وأنضبت القوس والوتر: لغة في أنبضت، قال العجاج: ترن إرنانا إذا ما أنضبا 140 وهو أن تمد الوتر ثم ترسله. وتنضب اسم شجر.'),
(2462, 'نبض', 'نبض', 'نبض', 'الإنباض في ذكر الوتر أجود، وكذلك القوس، قال مهلهل: أنبضوا معجس القسي وأبرقنا ... كما توعد الفحول الفحولا 141 والعرق ينبض نبضانا أي يتحرك، وربما أنبضته الحمى والوجع. ومنبض القلب: حيث تراه ينبض، وحيث تجد همس نبضانه. والنابض اسم للغضب 142 . والمنابض: المنادف في بعض الشعر، الواحد منبض مثل محبض، [وأنشد: لغام على الخيشوم بعد هبابه ... كمحلوج عطب طيرته المنابض] 143 والبرق ينبض أي يلمع لمعانا خفيفا.'),
(2463, 'ضبن', 'ضبن', 'ضبن', 'الضبن: ما بين الإبط والكشح. وتقول: اضطبنت شيئا أي حملته في ضبني، وربما أخذه بيد فرفعه الى فويق سرته فقال: أضطبنه أيضا، فأوله الإبط، ثم الحضن [وأنشد: لما تفلق عنه قيض بيضته ... آواه في ضبن مضبو به نصب] 144 والضبنة: أهل الرجل لانه يضطبنها في كنفه، وقيل: يعانقها. والضوبان: الجمل المسن، قال: فقربت ضوبانا قد اخضر نابه ... فلا ناضحي وان ولا الغرب شولا 145 أي قل فيه الماء فانضم، ومنهم من يرفع ضوبانا.'),
(2464, 'ضمن', 'ضمن', 'ضمن', 'الضمن والضمان واحد، والضمين: الضامن. وكل شيء أحرز فيه شيء فقد ضمنه، [وأنشد: ليس لمن ضمنه تربيت 146 أي ليس للذي يدفن في القبر تربيت أي لا يربيه القبر] 147 . وتضمنته الأرض والقبر والرحم، وضمنته القبر، قال: كأن لم يكن منها مقيلا ولم يعش ... بها ساكنا أو ضمنته المقابر 148 والمضمن من الشعر: ما لم يتم معنى قوافيه إلا في الذي قبله أو بعده كقوله: يا ذا الذي في الحب يلحى أما ... والله لو علقت منه كما علقت من حب رخيم لما 149 وهي أيضا مشطورة مضمنة، أي ألقي من كل بيت نصف وبني على نصف. وكذلك المضمن من الأصوات، تقول للانسان: قف (قلى) 150 بإشمام 151 اللام الحركة، وعلى فعل بتسكين العين وتحريك اللام، فيقال: هذا صوت مضمن لا يستطاع الوقوف عليه حتى يوصل بشمه (كذا) . والضامنة من كل بلد: ما تضمن وسطها. والضمن: الذي به زمانة من بلاء أو كسر ونحوه، وفي الحديث 152 : ومن اكتتب ضمنا بعثه الله ضمنا يوم القيامة. والضمان هو الداء نفسه، قال ابن أحمر: اليك إله الخلق أرفع رغبتي ... عياذا وخوفا أن تطيل ضمانيا 153 والمصدر الضمن. وذلك أنه قد أصابه بعض ذلك في جسده. والمضامين من الأولاد: التي ضمنتها الأرحام. ونهي عن المضامين والملاقيح وحبل الحبلة 154 ، وقال الشاعر في الضمن: ما خلتني زلت بعدكم ضمنا ... أشكو إليكم حموة الألم 155'),
(2465, 'صد', 'صد', 'صد', 'تقول: صد يصد صدا وهو شدة الضحك والجلبة، قال الله- عز وجل-: إذا قومك منه يصدون 1 اي يصدون ويضحكون. وصددته عن كذا أصده صدا أي عدلته عنه وصددت عنه بنفسي صدودا. والصديد: الدم المختلط بالقيح في الجرح، وتقول: أصد إصدادا أي صار فيه الصديد والمدة. وهو في القرآن، ما سال من أهل النار. ويقال: بل هو الحميم أغلي حتى خثر. والصداد: ضرب من الجرذان، ويقال: من دواب الأرض، [وأنشد: اذا ما رأى أشرا فهن انطوى لها ... خفي كصداد الجديرة أطلس] 2 والصدد: ما استقبلك، وهذه الدار على صدد هذه أي: قبالتها. وصدصد: اسم امرأة.'),
(2466, 'صت', 'صت', 'صت', 'الصت شبه الصدم والقهر. ورجل مصتيت: ماض 3 منكمش. والصتيت: الصوت والجلبة في العسكر ونحوه، قال: منهم ومن خيل لها صتيت 4'),
(2467, 'صر', 'صر', 'صر', 'صر الجندب صريرا، وصرصر الأخطب صرصرة. وصر الباب يمصر، وكل صوت شبه ذلك فهو صرير إذا امتد، فاذا كان فيه تخفيف وترجيع في إعادة ضوعف كقولك: صرصر الأخطب صرصرة. وريح صرصر: ذات صر، ويقال: ذات صوت، والصرصر نعت لها من البرد. والصر: البرد الذي يضرب كل شيء ويحسه 5 ، ومنه قوله تعالى: يها صر 6 . وصر الباب، وصرت الآذان اذا سمعت لها صوتا ودويا. والصرة: شدة الصياح، وتقول: جاء في صرة. وصرة الدراهم وغيرها معروفة. والصرار: خرقة تشد على أطباء الناقة لئلا يرضعها الفصيل، يقال: صررتها بصرار. وصر الحمار أذنيه أي سواهما، وأصر الحمار، من غير ذكر الأذن. والإصرار: العزم على شيء لا يهم بالقلوع عنه. وأصرى، أفعلى: اسم من الإصرار، وبعضهم يقول: هذه كلمة أخذت من أصرى أي جد، ويقال من أصري أي جد فخفف أصري أي اقطعي 7 ، والصرى على تقدير فعلى. والصرورة من الرجال والنساء الذي لم يحج ولا يريد التزوج. والصرصر: دويبة تحت الأرض تصر أيام الربيع. وقال أبو عمرو: الصرصراني [من] البخت: العظيم. والصرصور أيضا. والصرصراني: الملاح. والصرصران: ضرب من السمك البحري، أملس الجلد ضخم، قال: مرت كظهر الصرصران الأدخن 8'),
(2468, 'رص', 'رص', 'رص', 'رصصت البنيان رصا اذا ضممت بعضه الى بعض. ورجل أرص الأسنان أي ركب بعضها بعضا، ومنه التراص في الصف. والرصاصة والرصراصة: حجارة لازقة 9 بحوالي العين الجارية، قال الجعدي: حجاره غيل برصراصة ... كسين غثاء من الطحلب 10 ورصصت قتبي البعير اذا قاربت قيدهما اذا سمعت له قعقعة. والرصاص معروف، ويقال: الرصاص.'),
(2469, 'صل', 'صل', 'صل', 'صل اللجام صليلا اذا توهمت في صوته مدا، وان توهمت ترجيعا قلت: صلصل، وكل ذي صلابة يصلصل. وتصل البيض اذا نقفتها بالسيوف. والخزف صلصال لتصلصله اذا حرك، فاذا طبخ فهو فخار، وخلق آدم من طين، ومكث في الشمس أربعين يوما حتى صار صلصالا. والصلصلة والصلصلة: بقية الماء في الغدير، قال العجاج: صلاصل الزيت الى الشطور 11 والصلصل: طائر (تسميه العجم الفاختة) ، ويقال: بل يشبهها. والصلصل: ناصية الفرس. والصل: الداهية من الشدائد، وهو ايضا نعت لكل خبيث. وصل اللحم يصل صلولا إذا تغير. وقرىء: ااذا صللنا في الأرض 12 بمعناه. والصليان: شجر له جعثن ضخم، ربما جرد وسطه ونبت ما حواليه، وجعثنه: اجتماع أصوله. والصليان من أفضل المراعي، وهو خبرة البعير 13 .'),
(2470, 'لص', 'لص', 'لص', 'اللصوصية والتلصص واللصوصة مصدر اللص. والتلصيص كالترصيص في البنيان، قال رؤبة: لصص من بنيانه الملصص 14 واللصص في هذه اللغة كالرمص. وأرض ملصة: كثيرة اللصوص. واللصص: التزاق الأسنان بعضها ببعض. واللص جمع الألص، وهو مقاربة الأسنان.'),
(2471, 'صن', 'صن', 'صن', 'المصن: الرافع الرأس، ويقال: الغضبان، قال: أإبلي كلها مصنا 15 والصن: شبه سلة مطبقة [يحمل] 16 فيها الطعام، وقيل: بل هو الزبيل الكبير. والصن: بول الوبر. والصنان: ريح كالقنان من ريح الذفر. وأصن الرجل: بدا صنانه.'),
(2472, 'نص', 'نص', 'نص', 'نصصت الحديث الى فلان نصا أي رفعته، قال: ونص الحديث الى أهله ... فان الوثيقة في نصه 17 والمنصة: التي تقعد عليها العروس. ونصصت ناقتي: رفعتها في السير. والنصنصة: إثبات البعير ركبتيه في الأرض وتحركه اذا هم بالنهوض. والماشطة تنص العروس أي تقعدها على المنصة، وهي تنتص أي تقعد عليها أو تشرف لترى من بين النساء. ونصنصت الشيء: حركته. ونصصت الرجل: استقصيت مسألته عن الشيء، يقال: نص ما عنده أي استقصاه. ونص كل شيء: منتهاه، وفي الحديث: اذا بلغ النساء نص الحقاق فالعصبة أولى اي اذا بلغت غاية الصغر الى أن تدخل في الكبر فالعصبية أولى بها من الأم، يريد بذلك الادراك والغاية. وقوله: أحق بها أي يحفظونها وكينونتها عندهم 18 . وأنصته 19 : استمعت له، ومنه قوله- سبحانه وتعالى-: أنصتوا 20 *. وقوله تعالى: لات حين مناص 21 أي لا حين مطلب ولا حين مغاث، وهو مصدر ناص ينوص 22 ، وهو الملجأ.'),
(2473, 'صف', 'صف', 'صف', 'الصف معروف. والطير الصواف: التي تصف أجنحتها فلا تحركها. والبدن الصواف: التي تصفف ثم تنحر. وصففت القوم فاصطفوا. والمصف: الموقف، والجمع المصاف. وخيل صواف وصوافن: قد صفت بين أيديها 23 . والصفيف: القديد اذا شر في الشمس، وتقول: صففته أصفه في الشمس صفا، وصففته تصفيفا، قال: صفيف شواء أو قدير معجل 24 والصفة من البنيان والسرج ايضا 25 . والصفصف: الفلاة المستوية الملساء. والصفصف: شجر الخلاف 26 ، الواحدة بالهاء. والصفصفة: دويبة تسميها العجم السيسك، دخيل. وقوله تعالى: عذاب يوم الصفة 27 [وذلك أن قوما] عصوا ربهم فأرسل الله عليهم حرا وغما غشيهم من فوقهم فهلكوا.'),
(2474, 'فص', 'فص', 'فص', 'فص الأمر: أهله، وفص العين: حدقتها (وأنشد: بمقلة توقد فصا أزرقا) 28 والفصفصة: الفسفسة، وهو القت الرطب. وقال في فص الأمر: ورب امرىء خلته مائقا ... ويأتيك بالأمر من فصه 29 والفص: فص الخاتم. [والفص: السن من أسنان الثوم] 30 .'),
(2475, 'صب', 'صب', 'صب', 'الصبب: تصوب نهر أو طريق يكون في حدور. والصبابة: ما فضل في أصل إناء من شراب، قال: طربت الى نور وهيج لوعتي ... صبابات كأس روحها متوزع 31 والصبابة مصدر الرجل الصب، وامرأة صبة، وهو يصب إليها عشقا، وهو الوجد والمحبة. والصبيب: عصارة الحناء، قال: من الأجن، حناء معا وصبيب 32 والصبيب: الدم والعصفر المخلص [وأنشد: يبكون من بعد الدموع الغزر ... دما سجالا كسجال العصفر] 33 والتصبصب: شدة الخلاف والجرأة، يقال: تصبصب علينا فلان، قال: حتى إذا ما يومها تصبصبا 34 [أي اشتد علي [الحر] ذلك اليوم] 35 . وصبيت الماء صبا.'),
(2476, 'بص', 'بص', 'بص', 'بص يبص بصيصا، وفي لغة: وبص يبص وبيصا أي برق. والبصبصة: تحريك الكلب ذنبه طمعا وخوفا. والإبل تفعله اذا حدي بها، قال: بصبصن إذ حدين، بالأذناب 36'),
(2477, 'صم', 'صم', 'صم', 'الصمم: ذهاب السمع، والاكتناز في جوف القنا، والصلابة في الحجر، والشدة في الأمر. وفتنة صماء. والصمة والصم: من أسماء الأسد. ويقال: صمام صمام بمعنيين، أي تصاموا في السكوت، واحملوا في الحملة. والتصميم: المضي في كل أمر. وصمم في عضته اذا نيب 37 فلم يرسل ما عض، قال المتلمس: فأطرق إطراق الشجاع ولو يرى ... مساغا لنابيه الشجاع لصمما 38 والصمام: رأس القارورة، والفعل صممتها. والصمان: أرض الى جنب رمل عالج، وكل أرض كذلك، الى جنب رمل، صلبة الحجارة، وكذلك الصمانة. والصميم: العظم الذي هو قوام العضو مثل صميم الوظيف وصميم الرأس ونحوهما. ومنه يقال: هو من صميم قومه، أي من خالصهم وأصلهم. وأول من سمى السيف صمصامة عمرو بن معدي كرب حين وهب سيفه ثم قال: خليل لم أخنه ولم يخني ... على الصمصامة السيف السلام 39 والصمصامة: اسم للسيف القاطع، وللأسد. ومن العرب من يجعل اسمه معرفة ولا يصرفه كقوله: تصميم صمصامة حين صمما 40 وصوت مصم يصم الصماخ. وصميم الحر والشتاء: أشد حرا وبردا.'),
(2478, 'مص', 'مص', 'مص', 'مصصت الشيء وامتصصته، [والمص في مهلة] 41 ومصاصته: ما امتصصت منه. والمصاص: نبات يسمى؟ 42 اذا كان نديا رطبا، فاذا يبس قشره اتخذت منه الحبال. ومصاص القوم: أصل منبتهم وأفضل سطتهم، قال رؤبة: الاك يحمون المصاص المحضا 43 والمصيصة: ثغر من ثغور الروم. والماصة: داء يأخذ الصبي، وهو شعرات تنبت منثنية على سناسن القفا 44 ، فلا ينجع فيه طعام ولا شراب حتى تنتف من أصولها. ومصان ومصانة: [شتم للرجل يعير برضع الغنم من أخلافها بفيه] 45 . والمصمصة: غسل الفم بطرف اللسان دون المضمضة. وفرس مصامص: أي شديد تركيب [العظام] 46 والمفاصل، [وكذلك المصمص] 47 .'),
(2479, 'صدر', 'صدر', 'صدر', 'الصدر: أعلى مقدم كل شيء، وصدر القناة أعلاها، وصدر الأمر أوله. وصدرة الانسان: ما أشرف من أعلى صدره. والصدار: ثوب رأسه كالمقنعة، وأسفله يغشي الصدر والمنكبين تلبسه النساء. والتصدير: حبل يصدر به البعير اذا جر حمله الى خلف، فالحبل اسمه التصدير، والفعل التصدير. والتصدر 48 : نصب الصدر في الجلوس. ويقال: صدر فلان فلانا اذا أصاب صدره بشيء. والأصدر: الذي أشرفت صدرته. (وصدر فلان اذا وجع صدره) 49 . والصدر: الانصراف عن الورد وعن كل أمر، ويقال: صدروا وأصدرناهم. وطريق صادر في معنى يصدر عن الماء بأهله، وكذلك يرد بهم مكان كذا وكذا، فهو وارد، [وقال لبيد يذكر ناقتين: ثم أصدرناهما في وارد ... صادر وهم صواه قد مثل] 50 [أراد في طريق يورد فيه ويصدر عن الماء فيه، والوهم الضخم] 51 . والمصدر: أصل الكلمة الذي تصدر عنه الأفعال. [وتفسيره: ان المصادر كانت أول الكلام، كقولك: الذهاب والسمع والحفظ، وانما صدرت الأفعال عنها، فيقال: ذهب ذهابا، وسمع سمعا وسماعا وحفظ حفظا] 52 . والمصدر من السهام: الذي صدره غليظ، وصدر السهم: ما فوق نصفه الى المراش 53 . والمصدر: الأسد 54 .'),
(2480, 'رصد', 'رصد', 'رصد', 'المرصد: موضع الرصد. [والرصد] هم القوم الذين يرصدون كالحرس، والرصد الفعل 55 . والرصد: كلأ قليل في أرض يرجى بها حيا الربيع، وتقول: بها رصد من حيا، وأرض مرصدة: بها شيء من رصد، ومنه إرصاد الانسان في المكافأة والخير، يقال: أنا مرصد لك بإحسانك حتى أكافئك به، قال: وحية ترصد بالهواجر 56'),
(2481, 'صرد', 'صرد', 'صرد', 'الصرد: طائر يصيد العصافير، أكبر منها شيئا. ويوم صرد وليلة صردة، والاسم الصرد، قال رؤبة: بمطر ليس بثلج صرد 57 واذا انتهى القلب عن شيء، قيل: صرد عنه وقد صرد صردا، وقوم صردى، قال: أصبح قلبي صردا ... لا يشتهي أن يردا 58 (ورجل صرد ومصراد، وهو الذي يشتد عليه البرد ويقل صبره عليه) 59 . وجيش صرد، كأنه من تؤدة سيره جامد. والصراد: غيم رقيق تستخفه الريح الباردة، وقال: وهاجت الريح بصراد الفزع 60 ويقال: صريد مثل زمال وزميل، وهو الترخيم. والتصريد في السقي دون الري، قال النابغة: وتسقي إذا ما شئت غير مصرد ... بزوراء في أكنافها المسك كارع 61 وصرد له عطاءه أي أعطاه قليلا قليلا. وصرد السهم من الرمية صردا: نفذ منه شباة حده، ونصل صارد: خارج من الرمية شيئا، فاذا خرج بعضه فهو نافذ، واذا جاوز فهو مارق. ويقال: الصرد الإنفاذ، قال: ولكن خفتما صرد النبال 62 والصرد: الخطأ. والصردان: عرقان أخضران تحت اللسان، قال: له صردان منطلقا اللسان 63'),
(2482, 'درص', 'درص', 'درص', 'الدرص: ولد الفأر والقنافذ وشبهه، والجمع الدرصة والدرصان. والدرص، والدرص لغتان، [وأنشد: لعمرك لو تغدو علي بدرصها ... عشرت لها مالي اذا ما تألت] 64'),
(2483, 'صلد', 'صلد', 'صلد', 'حجر صلد، وجبين صلد أي أملس يابس. [واذا قلت: صلت، فهو مستو] 65 . ورجل صلد اي بخيل جدا، وقد صلد صلادة. ويقال: رجل صلود ايضا، وقال في الجبين: براق أصلاد الجبين الأجله 66'),
(2484, 'دلص', 'دلص', 'دلص', 'درع دلاص، ودروع دلص، ويجيء الدلاص بمعنى الجمع وهي اللينة الملساء. ودلصت [الدرع] تدلص دلاصة. وصخرة مدلصة اي دلصتها السيول فلينتها، قال ذو الرمة: صفا دلصته طحمة السيل أخلق 67 وحجر دلامص مدلص: شديد في استدارته. والاندلاص: الامتلاص، وهو سرعة خروج الشيء وسقوطه.'),
(2485, 'صدن', 'صدن', 'صدن', 'الصيدن من أسماء الثعالب، [وأنشد: بنى مكوين ثلما بعد صيدن] 68 وملك أصيد صيدن، قال رؤبة: اني اذا استغلق باب الصيدن 69 والصيدان: أرض حجارتها صغار جدا. والصيدان من حجارة الفضة، والقطعة بالهاء.'),
(2486, 'صند', 'صند', 'صند', 'وملك صنديد ضخم شريف 70 . وصنداد 71 : اسم جبل. والصيد 72 : جمع الأصيد. والصاد 73 : ضرب من النحاس، والصاد: الكبير.'),
(2487, 'ندص', 'ندص', 'ندص', 'ندصت عينه ندوصا أي جحظت 74 وكادت تخرج من قلتها (كما تندص عين الخنيق) 75 . ورجل منداص: لا يزال يندص على قوم بما يكرهون أي يطرأ عليهم، ويظهر بسوء.'),
(2488, 'صدف', 'صدف', 'صدف', 'الصدف: غشاء خلق في البحر تضمه صدفتان مفروجتان 76 عن لحم فيه روح يسمى المحارة فيه اللؤلؤ. والصدفان: جبلان متصادفان أي متلاقيان بيننا وبين يأجوج ومأجوج. وصادفت فلانا: لقيته. والصدوف: الميل عن الشيء، وأصدفني عنه كذا. والأصدف: من في يده اعوجاج، والمصدر الصدف، وناقة صدفاء.'),
(2489, 'فصد', 'فصد', 'فصد', 'الفصد: قطع العروق. وافتصد فلان: قطع عرقه ففصد. والفصيد: دم جعل في معى من فصد عروق الابل، ثم شوي فأكل.'),
(2490, 'صفد', 'صفد', 'صفد', 'الصفد (والصفد) 77 : العطاء، وتقول: أصفده إصفادا. والصفد، مجزوم، هو الظل. وصفدت يده الى عنقه صفدا أي أوثقته، والاسم الصفاد، والجمع: الصفد والأصفاد.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2491, 'صدم', 'صدم', 'صدم', 'الصدم: ضرب شيء صلب بشيء مثله، ورجلان يعدوان فتصادما، وجيشان، مثله، يتصادمان. وصدمهم أمر اي أصابتهم شدة. وصدام: اسم فرس. ورجل مصدم: مجرب. والصدام: داء يأخذ رؤوس الدواب. وهذا صدم هذا أي يصادمه.'),
(2492, 'دمص', 'دمص', 'دمص', 'كل عرق من أعراق الحائط يسمى دمصا، ما خلا العرق الأسفل فإنه دهص. والأدمص: الذي رق حاجبه من أخر، وكثف من قدم، والمصدر الدمص، وربما قالوا: أدمص الرأس اذا رق منه مواضع، وقل شعره.'),
(2493, 'مصد', 'مصد', 'مصد', 'المصد: ضرب من الرضاع، يقال: قبلها فمصدها مصدا.'),
(2494, 'صمد', 'صمد', 'صمد', 'الصمد عن الحسن: الذي أصمدت إليه الأمور، فلا يعتني فيها أحد غيره. وصمدت: قصدت. وفي العربية: الصمد السيد في قومه، ليس فوقه أحد، ولا يقضى أمر دونه، قال: خذها حذيف فأنت السيد الصمد 78 ويقال: هو المصمت الذي ليس بأجوف. والصمدة (والصمدة) : صخرة راسية في الأرض مستوية بمتن من الأرض، وربما ارتفعت شيئا. وصمدت صمد كذا أي قصدت قصده واعتمدته. والصماد: عفاص القارورة، وصمدتها صمدا، قال الشاعر في الصمدة: مخالف صمدة وقرين أخرى ... تجر عليه حاصبها الشمال 79 وقال رؤبة: وزاد ربي حسد الحساد ... غيظا وعضوا جندل الصماد 80'),
(2495, 'ترص', 'ترص', 'ترص', 'ترص الشيء تراصة فهو تريص اي محكم شديد. وأترصته إتراصا، قال: وشد يديك بالعقد التريص 81'),
(2496, 'صلت', 'صلت', 'صلت', 'الصلت: الأملس. ورجل صلت الوجه والخد والجبين اي أملس. وسيف صلت. وقيل: لا يقال للسيف: صلت الا لما كان فيه طول. وأصلت السيف أي جرده. وسيف إصليت أي مصلت ماض في الضريبة. وربما اشتق نعت إفعيل من أفعل مثل إبليس من أبلسه الله. ورجل صليت الوجه أي صافي اللون. ورجل منصلت: ماض في الحوائج، وأصلتي بمعناه. ونهر منصلت: شديد الجرية.'),
(2497, 'نصت', 'نصت', 'نصت', 'الإنصات: السكوت لاستماع شيء، قال الله- عز وجل-: وأنصتوا 82 . ونصته ونصت له مثل نصحته ونصحت له.'),
(2498, 'صفت', 'صفت', 'صفت', 'الصفتات: المجتمع من الناس الشديد. وامرأة صفتاتة، ويقال: بلا هاء. وقال بعضهم: لا تنعت المرأة بذلك.'),
(2499, 'صمت', 'صمت', 'صمت', 'الصمت: طول السكوت. وأخذه الصمات. وقفل مصمت: أبهم إغلاقه، وباب مصمت كذلك، قال: ومن دون ليلى مصمتات المقاصر 83 والصمات 84 : إشرافك على أمر، وتقول: هو منه على صمات. والصمتة: ما أصمتك من قضاء حاجتك.'),
(2500, 'مصت', 'مصت', 'مصت', 'المصت: لغة في المسط، فاذا جعلوا مكان السين صادا جعلوا مكان الطاء تاء، وهو أن يدخل يده فيقبض على الرحم، فيمسطها مسطا، ويمصت (ما فيها مصتا) .'),
(2501, 'صتم', 'صتم', 'صتم', 'الصتم من كل شيء: ما عظم وتم واشتد، نحو: حجر صتم، وبيت صتم وجمل صتم. واعطيته ألفا صتما اي تاما، [وقال زهير: صحيحات ألف بعد ألف مصتم] 85 والأصاتم جماعة الأصطمة بلغة تميم، جمعوها بالتاء على هذه اللغة لانهم كرهوا التفخيم أصاطم فردوا الطاء الى التاء. والحروف الصتم: التي ليست من الحلق.'),
(2502, 'رصن', 'رصن', 'رصن', 'رصن الشيء يرصن رصانة، وهو شدة الثبات ونحوه، وأرصنته إرصانا.'),
(2503, 'نصر', 'نصر', 'نصر', 'النصر: عون المظلوم. [وفي الحديث: انصر أخاك ظالما أو مظلوما ، وتفسيره: أن يمنعه من الظلم إن وجده ظالما، وان كان مظلوما أعانه على ظالمه] 86 . والأنصار: جماعة الناصر، وأنصار النبي- صلى الله عليه وسلم-: أعوانه. وانتصر الرجل: انتقم من ظالمه. والنصير والناصر واحد، وقال الله جل وعز-: نعم المولى ونعم النصير 87 . * والنصرة: حسن المعونة، [وقال الله- جل وعز-: من كان يظن أن لن ينصره الله في الدنيا والآخرة 88 .. الآية. المعنى: من ظن من الكفار أن الله لا يظهر محمدا على من خالفه فليختنق غيظا حتى يموت كمدا فان الله يظهره ولا ينفعه موته خنقا، والهاء في قوله: أن لن ينصره للنبي محمد- صلى الله عليه وسلم] 89 . وتنصر: دخل في النصرانية. ونصرونة 90 : قرية بالشام، ويقال: نصرى. ونصر الغيث البلاد: أرواها 91 .'),
(2504, 'صرف', 'صرف', 'صرف', 'الصرف: فضل الدرهم في القيمة، وجودة الفضة، وبيع الذهب بالفضة، ومنه الصيرفي لتصريفه أحدهما بالآخر. والتصريف: اشتقاق بعض من بعض. وصيرفيات الأمور: متصرفاتها أي تتقلب بالناس. وتصريف الرياح: تصرفها من وجه الى وجه، وحال الى حال، وكذلك تصريف الخيول والسيول والأمور. وصرف الدهر: حدثه. وصرف الكلمة: إجراؤها بالتنوين. وقال الحسن: الصرف: التطوع، والعدل: الفريضة. [والصرف: أن تصرف إنسانا على وجه يريده الى مصرف غير ذلك] 92 . (والصرفة: كوكب واحد خلف خراتى الأسد، اذا طلع أمام الفجر فذاك أول الخريف، واذا غاب مع طلوع الفجر فذاك أول الربيع، وهو من منازل القمر. والعرب تقول: الصرفة: ناب الدهر، لأنها تفتر عن البرد أو عن الحر في الحالتين) 93 . والصراف: حرمة الشاء والبقر والكلاب أي استحرامها، وصرفت الكلبة تصرف صرافا فهي صارف. والصريف: صوت ناب البعير حين يصرف اذا حرق أحدهما بالآخر. والصريف: صوت البكرة. والصريف: اللبن الحليب ساعة يحلب. [والصريف: الخمر الطيبة، وقال في قول الأعشى: صريفية طيبا طعمها ... لها زبد بين كوب ودن 94 قال بعضهم: جعلها صريفية لأنها أخذت من الدن ساعتئذ كاللبن الصريف] 95 . وشراب صرف: غير ممزوج. والصرف: كل شيء لم يخلط بشيء. والصرفان: من أجود التمر، وضرب منه من أرزنه 96 . ويقال: الصرفان الموت، قال: أجندلا يحملن أم حديدا ... أم صرفانا باردا شديدا 97 والصرف: الأديم الشديد الحمرة.'),
(2505, 'رصف', 'رصف', 'رصف', 'الرصف: حجارة مضمومة بعضها الى بعض في مسيل، وكذلك اذا جعل من آخر مسيل لماء أو لمصير 98 ، وجمعه رصاف. والرصافة والرصافة: موضع. والرصفة: عقبة تلوى على موضع الفوق من الوتر، وعلى أصل نصل السهم، وسهم مرصوف. ورصف قدميه أي صفهما، وضم إحداهما الى الأخرى.'),
(2506, 'فرص', 'فرص', 'فرص', 'الفرص: شق 99 الجلد بحديدة 100 عريضة الطرف تفرصه بها فرصا غمزا، كما يفرص الحذاء أذني النعل عند عقبهما بالمفراص ليجعل فيها الشراك. والمفراص: الحديدة التي يقطع بها. والفريصة: لحم عند نغض الكتف في وسط الجنب عند منبض القلب، وهما اللتان يفترصان عند الفزعة، يعني ارتعادهما، قال أمية: فرائصهم من شدة الخوف ترعد 101 وقال: صخم الفريصة لو أبصرت قمته ... بين الرجال إذن شبهته جملا 102 والفرصة: النهزة، ويقال: أصبت فرصتك ونوبتك 103 ونهزتك، واحد. وانتهزتها وافترصتها. والفرصة 104 : قطعة من صوف أو قطن. وفريص الرقبة: عروقها. والفرصة: الريح التي يكون منها الحدب، والسين فيه لغة.'),
(2507, 'صفر', 'صفر', 'صفر', '105 الصفر يقع في الكبد وشراسيف الأضلاع، يقال: إنه يلحس الانسان حتى يقتله. ورجل مصفور: في بطنه صفر. والانسان يصفر من الصفر جدا، وقال أعشى باهلة لا يتأرى لما في القدر يرقبه ... ولا يعض على شرسوفه الصفر 106 والصفار: صفرة تعلو اللون والبشرة من داء، وصاحبه مصفور أيضا، [وأنشد: قضب الطبيب نائط المصفور] 107 والصفرة: لون الأصفر، وفعله اللازم الاصفرار. وأما الاصفيرار فعرض يعرض للانسان، (يقال يصفار مرة ويحمار أخرى. ويقال في الأول: اصفر يصفر) 108 . والصفير من الصوت كما تصفر بالدواب اذا سقيت. والصفارة: هنة جوفاء من نحاس يصفر فيها الغلام للحمام ونحوه، وللحمار للشرب. والصفر: الشيء الخالي، يقال: صفر يصفر صفرا وصفورا فهو صفر صحر، والجميع والواحد والذكر والأنثى فيه سواء. والصفرية: نبات يكون في أول الخريف يخضر الأرض ويورق الشجر. والصفرية: زمان بين الخريف والوسمي. وما يصيب المواشي فيغير الخلقة وهزة الجنبة يسمى الصغرة كما تسمي ما يرعى من الربيع الربعة. والصفار [والصفار] 109 : ما بقي في أسنان الدابة من التبن والعلف للدواب كلها. وفي المثل: ما بها صافر أي أحد ذو صفير. وبنو الأصفر: ملوك الروم، [قال عدي بن زيد: وبنو الأصفر الكرام ملوك الروم ... لم يبق منهم مأثور] 110 وأبو صفرة: كنية أبي المهلب. والصفر: ما يتخذ من النحاس الجيد. وصفر: شهر بعد المحرم، فاذا جمعوها باسم واحد قالوا: الصفران، وكذلك اذا جمعوا رجبا وشعبان باسم واحد قالوا: رجبان، فغلب على الأول المؤخر، وعلى الثاني المقدم.'),
(2508, 'صبر', 'صبر', 'صبر', 'الصبر: نقيض الجزع. والصبر: نصب الانسان للقتل، فهو مصبور، وصبروه أي نصبوه للقتل. والصبر أخذ يمين إنسان، تقول: صبرت يمينه أي حلفته بالله جهد القسم. والصبر في الأيمان لا يكون الا عند الحكام. والصبر، بكسر الباء، عصارة شجرة ورقها كقرب السكاكين، طوال غلاظ، في 111 خضرتها غبرة وكمدة مقشعرة المنظر، يخرج من وسطها ساق عليه نور أصفر تمه الريح كريهه. والصبار: حمل شجرة طعمه أشد حموضة من المصل، له عجم أحمر عريض، يجلب من الهند، يسمى التمر الهندي وصبر الإناء: نواحيه وأصباره، ومنه يقال: شربها بأصبارها، وهو مثل. وأصبار القبر: نواحيه. والصبرة من الحجارة: ما اشتد وغلظ، ويجمع على الصبار، قال: كأن ترنم الهاجات فيها ... قبيل الصبح، أصوات الصبار 112 وأم صبار 113 : الحرب والداهية الشديدة. وصبر كل شيء: أعلاه، ويقال: ناحيته، ويقال: صبر، وبصر مقلوبه. ويقال: سدرة المنتهى صبر الجنة 114 قال: صبرها أعلاها. والصبر: سحاب مستو فوق السحاب الكثيف 115 وصبير الخوان: رقاقته العريضة تبسط تحت ما يؤكل من الطعام 116 وصبير الطعام: الذي يصبر لهم ويكون معهم في أمورهم 117 . (والصبرة من الطعام مثل الصوفه بعضه فوق بعض) 118 .'),
(2509, 'بصر', 'بصر', 'بصر', 'البصر: العين، مذكر، والبصر: نفاذ في القلب. والبصارة مصدر البصير، وقد بصر، وابصرت الشيء وتبصرت به، وتبصرته: شبه رمقته. واستبصر في أمره ودينه اذا كان ذا بصيرة. والبصيرة اسم لما اعتقد في القلب من الدين وحقيق الأمر. ويقال: رأى فلان لمحا باصرا أي أمرا مفزعا 119 ، قال: دون ذاك الأمر لمح باصر 120 وبصر الجر وتبصيرا: فتح عينه. والبصيرة: الدرع، ويقال: ما لبس من السلاح فهو بصائر السلاح. [ويقال للفراسة الصادقة: فراسة ذات بصيرة. والبصيرة: العبرة، يقال: أما لك بصيرة في هذا؟ أي عبرة تعتبر بها، وأنشد: في الذاهبين الأولين ... من القرون لنا بصائر 121 أي عبر] 122 . وبصائر الدماء: طرائقها على الجسد. والبصر: غلظ الشيء، نحو بصر الجبل، وبصر السماء والحائط ونحوه 123 . والبصرة: أرض حجارتها جص، وهكذا أرض البصرة، [فقد] نزلها المسلمون أيام عمر بن الخطاب، وكتبوا إليه: إنا نزلنا أرضا بصرة فسميت بصرة، وفيها ثلاث لغات: بصرة وبصرة وبصرة. وأعمها البصرة. والبصرة نعت، وكل قطعة بصرة. وقيل: البصرة الحجارة التي فيها بعض اللين، قال الشماخ: سواء حين جاهدها عليه ... أغشاهن سهلا أم بصارا 124 أي جرت وجرى معها يعني الحمر.'),
(2510, 'صرب', 'صرب', 'صرب', 'الصرب: حقن اللبن أياما (في السقاء) ، تقول: شربت لبنا صربا ومصروبا. ورجل صارب: حقن بوله وحبسه. وقدم اعرابي على أهله، وقد شبق لطول الغيبة فراودها فأقبلت تطيب وتمتعه، فقال: فقدت طيبا في غير كنهه أي في غير وجهه وموضعه، فقالت: فقدت صربة مستعجلا بها. أرادت: في صلبك شهوة تريد أن تصبها.'),
(2511, 'برص', 'برص', 'برص', 'البرص داء. وسام أبرص: مضاف غير مصروف، والجمع سوام أبرص. ويقال: كان بيده برص. قال تعالى تخرج بيضاء من غير سوء* 125 فخرجت بيضاء للناظرين.'),
(2512, 'ربص', 'ربص', 'ربص', 'التربص: الانتظار بالشيء يوما. والربصة الاسم، ومنه يقال: ليس في البيع ربصة أي لا يتربص به.'),
(2513, 'صرم', 'صرم', 'صرم', 'الصرم دخيل. والصرم: قطع بائن لحبل وعذق ونحوه. والصرام: وقت صرام [النخل] ، وصرم العذق عن النخلة، وأصرم النخل اذا حان 126 وقت اصطرامه. والصريمة: إحكامك أمرا والعزم عليه. وقوله تعالى: فأصبحت كالصريم 127 أي كالليل. والصريمة: الرأي النافذ. والصريمة: الرمل المتصرم من معظم الرمل، قال: (به لا بظبي بالصريمة أعفرا 128 ) والصرمة: قطيع من الابل نحو ثلاثين. والصرم: طائفة من القوم ينزلون بابلهم في ناحية الماء فهم أهل صرم، والجمع على أصرام، ثم يجمع على أصارم. وصرم الرجل صرامة فهو صارم: ماض في أمره. وناقة مصرمة، وذلك أن يصرم طبيها فيقرح عمدا حتى يفسد الإحليل فلا يخرج منه لبن، فييبس وذلك أقوى لها. والصرمة: قطعة من السحاب، قال النابغة: تزجى مع الليل، من صرادها، صرما 129 وتصرمت الأيام والسنة والأمر أي انقضى. وانصرم الأمر والشيء اذا انقطع فذهب. وأصرم الرجل: ساءت حاله وفيه تماسك بعد، والاسم الاصرام. وصرام: الحرب، قال الكميت: على حين درة من صرام 130 وسيف صارم أي قاطع ذو صرامة.'),
(2514, 'مرص', 'مرص', 'مرص', 'المرص: غمز الثدي بالأصابع، والمرس مثله، إلا أنه يمرس في الماء حتى يتميث 131 فيه، مرس ومرص واحد.'),
(2515, 'رمص', 'رمص', 'رمص', 'الرمص: غمص 132 أبيض تلفظه العين فتوجع له. وعين رمصاء [وقد رمصت رمصا اذا لزمها ذلك] 133 .'),
(2516, 'صمر', 'صمر', 'صمر', 'صمر الماء يصمر صمورا اذا جرى من حدور في مستو، فسكن فهو يجري، وذلك الموضع يسمى صمر الوادي. وصيمرة: أرض (من) مهرجان، وإليها ينسب الجبن الصيمري.'),
(2517, 'مصر', 'مصر', 'مصر', 'المصر: حلب بأطراف الأصابع، السبابة والوسطى والإبهام. وناقة مصور اذا كان لبنها بطيء الخروج، لا تحلب إلا مصرا. والتمصر: حلب بقايا اللبن في الضرع بعد الدر، وصار مستعملا في تتبع الغلة 134 ونحوها، يقال: لهم غلة يتمصرونها. ومصر عليه الشيء اذا أعطاه قليلا قليلا. والمصر: كل كورة تقام فيها الحدود وتغزى منها الثغور، ويقسم فيها الفيء والصدقات من غير مؤامرة الخليفة، وقد مصر عمر [بن الخطاب] سبعة أمصار منها: البصرة والكوفة، فالأمصار عند العرب تلك. وقوله تعالى: اهبطوا مصرا 135 من الأمصار، ولذلك نونه، ولو أراد مصر الكورة بعينها كما نون، لأن الاسم المؤنث في المعرفة لا يجرى. ومصر هي اليوم كورة معروفة بعينها لا تصرف. والمصير: المعى، وجمعه مصران كالغدير والغدران، والمصارين خطأ 136 . والممصر: ثوب مصبوغ فيه صفرة قليلة.'),
(2518, 'نصل', 'نصل', 'نصل', 'النصل للسيف حديدته، ونصل السهام. ونصل البهمى ونحوها من النبات اذا خرجت نصالها. وأنصلت السهم: أخرجت نصله. ونصلته: جعلت له نصلا. والمنصل: اسم السيف، ونصله: حديدته. والنصيل: مفصل ما بين العنق والرأس من باطن، من تحت اللحيين. ونصل الحافر نصولا: خرج من موضعه فسقط كما ينصل الخضاب وكل شيء نحوه. ونصل فلان من موضع كذا اذا خرج عليك. والتنصل شبه التبرؤ من جناية ذنب ونحوه. [ويقال للغزل اذا أخرج من المغزل: نصل. ويقال: استنصلت الريح اليبيس اذا اقتلعته من أصله] 137'),
(2519, 'لصف', 'لصف', 'لصف', 'اللصف لغة في الأصف، والواحدة لصفة، وهي ثمرة حشيشة تجعل في المرق لها عصارة يصطبغ بها تمرىء الطعام. ولصاف: أرض لبني تميم، قال النابغة. بمصطحبات من لصاف وثبرة 138'),
(2520, 'صلف', 'صلف', 'صلف', 'الصلف: مجاوزة قدر الظرف والبراعة والادعاء فوق ذلك. وآفة الظرف الصلف. وطعام صلف اي كالمسيخ الذي لا طعم له. والصلف والصليف نعت للذكر. والصليفان: صفحتا العنق. وصلفت المرأة عند زوجها تصلف صلفا فهي صلفة من نساء صلفات وصلائف اذا لم تحظ عنده وأبغضها.'),
(2521, 'فلص', 'فلص', 'فلص', 'الانفلاص: التفلت من الكف ونحوه. ورشاء فلص اذا كان فلوتا.'),
(2522, 'فصل', 'فصل', 'فصل', 'الفصل: بون ما بين الشيئين. والفصل من الجسد: موضع المفصل، وبين كل فصلين وصل. والفصل: القضاء بين الحق والباطل، واسم ذلك القضاء فيصل. وقضاء فيصلي وفاصل. وحكم فاصل. والفصيلة فخذ الرجل من قومه الذين هو منهم. والفصلان جمع الفصيل، وهو ولد الإبل. والفصيل: حائط قصير دون سور المدينة والحصن. والانفصال مطاوعة فصل. [والمفصل: اللسان. والمفصل أيضا: كل مكان في الجبل لا تطلع عليه الشمس، قال الهذلي: مطافيل أبكار حديث نتاجها ... يشاب بماء مثل ماء المفاصل] 139 [والفاصلة في العروض: ان يجمع ثلاثة أحرف متحركة والرابع ساكن مثل: فعلن. وقال: فاذا اجتمعت أربعة أحرف متحركة فهي الفاضلة- بالضاد معجمة-، مثل: فعلهن] 140 .'),
(2523, 'صلب', 'صلب', 'صلب', 'الصلب لغة في الصلب، وقد يقرأ: بين الصلب والترائب 141 . والصلب: الظهر، وهو عظم الفقار المتصل في وسط الظهر والصلب من الجري ومن الصهيل: الشديد، وقال: ذو ميعة اذا ترامى صلبه 142 وربما جاء في معنى الصلب كالحول والقول والقلب أي المحتال، والقول من القول. ورجل صلب: ذو صلابة، وقد صلب. والصلابة من الأرض: ما غلظ واشتد فهو صلب، والجميع الصلبة. والصلب: موضع بالصمان أرضه حجارة. والصلب: حجارة المسن، يقال: سنان مصلب أي قد سن على المسن. ويقال: الصلبة حجارة المسان، وهو عريض. والصليب: المصلوب. والصليب: ما يتخذه النصارى. والصليب: ودك الجيفة. والتصليب: خمرة للمرأة، ويكره للرجل أن يصلي في تصليب العمامة حتى يجعله كورا بعضه فوق بعض. وقد قيل: إنه التخاصر دون كور العمامة، ولكل وجه. وتصلب لك فلان أي تشدد. والصالب: الحمى التي لا تنفض، يذكر ويؤنث، وتقول: أخذته الحمى الصالب 143 . والصولب والصوليب: البذر الذي ينثر على الأرض ثم يكرب عليه.'),
(2524, 'لصب', 'لصب', 'لصب', 'اللصب مضيق الوادي، وجمعه: لصوب. [ويقال: لصب السيف لصبا اذا نشب في الغمد فلم يخرج، وهو سيف ملصاب اذا كان كذلك. ورجل لحز لصب: لا يعطي شيئا. وطريق ملتصب: ضيق] 144 .'),
(2525, 'بصل', 'بصل', 'بصل', 'البصل معروف، والبصلة بيضة الرأس من حديد، وهي المحددة الوسط، شبهت بالبصلة، قال لبيد: (قردمانيا) 145 وتركا كالبصل 146'),
(2526, 'صلم', 'صلم', 'صلم', 'الصلم: قطع الأنف من أصله. واصطلم القوم اذا أبيدوا من أصلهم. [والصيلم: الأكلة الواحدة كل يوم] 147 . والصيلم: الأمر المفني المستأصل، ووقعة صيلمية 148 من ذلك. والمصلم: الصغير الأذن، سمي به الظليم لصغر أذنه وقصرها. والأصلم: المصلم من الشعر. والمصلم: ضرب من السريع يجوز في قافيته فعلن وفعلن كقوله: ليس على طول الحياة ندم ... ومن وراء الموت ما لا يعلم 149 والصلامة 150 : الفرقة من الناس، وتجمع صلامات، وكل جماعة صلامة.'),
(2527, 'صمل', 'صمل', 'صمل', 'صمل الشيء يصمل صمولا أي صلب واشتد واكتنز، توصف به الخيل 151 والجمل والرجل، قال [رؤبة] : عن صامل عاس إذا ما اصلخمما 152 والصميل: (السقاء) 153 اليابس. [والصامل الخلق، وأنشد: اذا ذاد عن ماء الفرات فلن نرى ... أخا قربة يسقى أخا بصميل] 154 [ويقال: صمل بدنه وبطنه، وأصمله الصيام: أي أيبسه. والصومل: شجرة بالعالية] 155 . ورجل صمل، وامرأة صملة: شديدة البضعة والعظام، ولا يقال إلا لمجتمع الخلق. والمصمئل: الداهية.'),
(2528, 'مصل', 'مصل', 'مصل', 'المصل معروف. والمصول: تميز الماء عن اللبن، والأقط اذا علق مصل ماؤه فقطر منه. وبعضهم يقول: مصلة واحدة مثل أقطة. وشاة ممصل وممصال، وهي التي يصير لبنها في العلبة متزايلا قبل أن يحقن.'),
(2529, 'ملص', 'ملص', 'ملص', 'أملصت المرأة والناقة أي رمت بولدها. وانملص الشيء من يدي اي انفلت انسلالا، وقد قضى عمر في الإملاص وهو الإسقاط.'),
(2530, 'لمص', 'لمص', 'لمص', 'اللمص شيء يباع مثل الفالوذ لا حلاوة له، يأكله الفتيان مع الدبس.'),
(2531, 'صنف', 'صنف', 'صنف', 'الصنف: طائفة من كل شيء، فكل ضرب من الأشياء صنف على حدة. والصنفة والصنفة: قطعة من الثوب، وطائفة من القبيلة. والتصنيف: تمييز الأشياء بعضها من بعض.'),
(2532, 'نصف', 'نصف', 'نصف', 'النصف: أحد جزأي الكمال، والنصف لغة رديئة. وقدح نصفان: [بلغ الكيل نصفه، وشطران مثله] 156 ، وقربان الى تلك المواضع. ونصف الماء الشجرة: بلغ نصفها، وكل شيء مثله، قال: الى ملك لا تنصف الساق نعله ... أجل لا وإن كانت طوالا محامله 157 والناصفة: صخرة تكون في مناصف أسناد الوادي. والنصف: المرأة بين المسنة والحدثة. والنصفة: اسم الإنصاف، وتفسيره [أن تعطيه من نفسك النصف] 158 أي تعطي من نفسك ما يستحق من الحق كما تأخذه. وانتصفت منه: أخذت حقي كملا حتى صرت وهو على النصف سواء 159 . والنصيف: النصف. والنصفة: الخدام، واحدهم ناصف 160 . وغلام ناصف: ينصف الملوك أي يخدمهم. والنصيف: الخمار. والمنصف من الطريق ومن النهر 161 وكل شيء: وسطه. ومنتصف الليل والنهار: وسطه، وانتصف النهار، ونصف ينصف. والمنصف: ما طبخ من الشراب حتى ذهب منه النصف. والناصفة: مسيل عظيم يكون نصف الوادي.'),
(2533, 'صفن', 'صفن', 'صفن', 'الصفن والصفن 162 : وعاء الخصية. وكل دابة وخلق شبه زنبور ينضد حول مدخله ورقا أو حشيشا أو نحو ذلك ثم يبيت في وسطه بيتا لنفسه أو لفراخه فذلك الصفن، وفعله التصفين. والصافن: عرق باطن الصلب طولا متصل به نياط القلب، معلق به. ويسمى الأكحل من البعير: الصافن. والصفنة: دلو صغير لها حلقة على حده، فاذا عظمت فاسمها الصفن، وفعله التصفين. والصفون: أن تصفن الدابة وتقوم على ثلاث قوائم وترفع قائمة عن الأرض، أو ينال سنبكها الأرض لتستريح بذلك، وأكثر ما يصفن الخيل، والصافنات الخيل، وقال في العانة: كل صبير عانة صفونا 163 وقراءة عبد الله: فاذكروا اسم الله عليها صواف 164 ، أي معقولة إحدى يديها على ثلاث قوائم، وصواف قد صفت قدميها، وصوافي بالياء يريد خالصة لله. وكل صاف قدميه صافن. ويقال: الصافن الذي يجمع يديه ويثني طرف سنبك إحدى رجليه. وقيل: الصافن فوق اليد.'),
(2534, 'نصب', 'نصب', 'نصب', 'النصب: الإعياء والتعب، والفعل: نصب ينصب. وأنصبني هذا الأمر، وأمر ناصب أي منصب ومنه: كليني لهم يا أميمة ناصب 165 وكذلك خانق في موضع مخنوق، وكاس في موضع مكتس. والنصب ضد الرفع في الاعراب. والنصب: الشر والبلاء، قال ابن أبي خازم: نعناك نصب من أميمة منصب 166 والنصب: نصب الداء، تقول: أصابه نصب من الداء. والنصب: النصيب، لغة، قال: وليس له في مال وارثه نصب 167 والنصب: حجر كان ينصب فيعبد وتصب عليه دماء الذبائح وجمعه أنصاب. والنصب: العلم. والنصب: جماعة النصيبة، وهي علامة تنصب للقوم، اي علامة كانت لهم. والنصيبة واحدة النصائب، وهي نصائب الحوض، وهي حجارة تنصب حوالي شفيره فتجعل له عضائد. والنصب: رفعك شيئا تنصبه قائما منتصبا. [والكلمة المنصوبة يرفع صوتها الى الغار الأعلى] 168 . وناصبت فلانا [الشر والحرب] 169 والعداوة ونحوها. ونصبنا لهم حربا، وان لم تسم الحرب جاز. وكل شيء استقبلته فقد نصبته. وتيس أنصب، وعنزة نصباء، أي منتصب القرن. وناقة نصباء: منتصبة مرتفعة الصدر. والنصب جمع نصاب سكين. ونصاب الشمس مغيبها. ونصاب كل شيء: أصله ومرجعه الذي يرجع إليه. وتقول: رجع الى مركبه ومنصبه أي أصل منبته وحسبه.'),
(2535, 'صبن', 'صبن', 'صبن', 'الصبن: تسوية الكعبين في الكف ثم تضرب بهما فيقال: أجل ولا تصبن. واذا صرف الساقي الكأس عمن هو أولى بها قيل: صبن، قال عمرو بن كلثوم: صبنت الكأس عنا أم عمر ... وكان الكأس مجراها اليمينا 170 واذا خبأ الانسان في كفه شيئا كالدرهم او الخاتم [ولا يفطن له] 171 قيل: صبن.'),
(2536, 'نبص', 'نبص', 'نبص', 'نبص الغلام ينبص بالطائر نبصا: يضم شفتيه ثم يدعوه.'),
(2537, 'صنب', 'صنب', 'صنب', 'الصناب: صباغ الخردل. والصنابي من الدواب والابل: لون بين الحمرة والصفرة مع كثرة الشعر والوبر.'),
(2538, 'صنم', 'صنم', 'صنم', 'الصنم: جمعه أصنام.'),
(2539, 'نمص', 'نمص', 'نمص', 'النمص: رقة الشعر حتى تراه كالزغب. ورجل أنمص الرأس أنمص الحاجبين، وربما كان أنمص الجبين. وامرأة نمصاء، وهي تتنمص: أي تأمر نامصة فتنمص شعر وجهها نمصا، أي تأخذه عنها بخيط فتنتفه. والنميص والمنموص من النبات: ما أمكنك جذه 172 . وما أمكنك من الشعر الانتتاف فهو نميص.'),
(2540, 'فصم', 'فصم', 'فصم', 'الفصم: كسر الحلقة والخلخال. والفصم: أن ينصدع الشيء من غير أن يبين، وتقول: فصمته فانفصم اي انصدع. والانفصام: الانقطاع، واذا انصدعت ناحية من البيت قيل: فصم. والدرة تنفصم اذا انصدعت ناحية منها.'),
(2541, 'طس', 'طس', 'طس', 'الطست في الأصل طسة، ولكنهم حذفوا تثقيل السين فخففوا وسكنت فظهرت التاء التي في موضع هاء التأنيث لسكون ما قبلها، وكذلك تظهر في كل موضع سكن ما قبلها غير ألف الفتح، والجمع الطساس. والطساسة: حرفة الطساس. ومن العرب من يتم الطسة فيثقل السين ويظهر الهاء، فان قيل: التاء أصلية فانه ينتقض عليه قوله من وجهين: أحدهما أن الطاء مع التاء لا يدخلان في كلمة واحدة، والوجه الآخر: أن جمعه طساس ولا يصغرونه الا طسيسة. ومن قال في جمعه الطسات فهذه التاء مع التأنيث بمنزلة التاء التي تجيء في جماعة المؤنث المجرورة في موضع النصب 1 فمن جعل هاتين التاءين اللتين في البنت والطست أصلتين فإنه ينصبهما لأنهما يصيران كالحروف الأصلية مثل أقوات وأصوات ونحوهما. ومن نصب البنات فقال: هو على فعال ينتقض عليه مثل هنات وثبات 2 وذوات فنقول: ليس له أصل في الكلام فتجعل التاء شبيهة بالأصلية.'),
(2542, 'سد', 'سد', 'سد', 'السدود: السلال تتخذ من قضبان لها أطباق، وتجمع على السداد أيضا، والواحد سد 3 . والسداد: الشيء الذي تسد به كوة أو منفذ سدا، ومنه قيل: في هذا سداد من عوز، أي يسد من الحاجة سدا. والسد: ردم الثلمة، والشعب ونحوه. والسداد: إصابة القصد. والسداد 4 : مصدر، ومنه السديد، قال: أعلمه الرماية كل يوم ... فلما استد ساعده رماني 5 أي لما تشدد لقصد الرمي، ومن قال: اشتد يقول: قوي ساعده. والفعل اللازم من سد انسد. والسدة والسداد: داء يأخذ في الأنف، يأخذ بالكظم ويمنع نسيم الريح. والسدة: أمام باب الدار. والسدد 6 ، مقصور، من السداد، قال كعب: ماذا عليها وماذا كان ينقصها ... يوم الترحل لو قالت لنا سددا 7 أي قولا سدادا أي سديدا، يعني صوابا. وسددك الله: وفقك للقصد والرشاد. والسدي: منسوب الى قبيلة [من اليمن] 8 . والسد من السحاب: هو الذي يسد الأفق، قال: وقد كثر المخايل والسدود 9 ورأيت سدا من جراد، أي قطعة سدت الأفق. وسدوس 10 : قبيلة. والسدوس: الطيلسان 11 . وأسدس البعير: صار سديسا. والسدس من الورد: فوق الخمس. وتقول: سدستهم أي صرت سادسهم.'),
(2543, 'دس', 'دس', 'دس', 'دسست شيئا في التراب، أو تحت شيء أي أخفيت، قال الله- عز وجل-: أيمسكه على هون أم يدسه في التراب 12 ، [اي يدفنه] 13 . واندس فلان الى فلان: يأتيه بالنمائم. والدسيسى: اسم من دس يدس، يمد ويقصر. والدسيس: من تدسه ليأتيك بالأخبار. والدساسة: حية بيضاء تحت التراب 14 .'),
(2544, 'ست', 'ست', 'ست', 'ستة وست في الأصل سدسة وسدس، فأدغموا الدال في السين فالتقى عندها مخرج التاء فغلبت عليها كما غلبت الحاء على العين والهاء في سعد، يقولون: كنت محهم أي معهم. وبيانه أن تصغير ستة سديسة، وجميع تصريفها على ذلك، وكذلك الأسداس.'),
(2545, 'سر', 'سر', 'سر', 'السر: ما أسررت. والسريرة: عمل السر من خير أو شر، ويقال: سريرته خير من علانيته. وأسررت الشيء: أظهرته، وأسررته: كتمته، قال الشاعر: فلما رأى الحجاج جرد سيفه ... أسر الحروري الذي كان أضمرا 15 ومن الاظهار أيضا قوله- عز وجل-: وأسروا الندامة لما رأوا العذاب 16 *. والسرار: يوم يستسر فيه الهلال آخر يوم من الشهر أو قبله، وربما استسر ليلتين اذا تم الشهر. والأسرة: طرائق في الرحم، ويقال في المثل: داهية تفطر أسرة الأرحام الدم 17 ، قال 18 : قتلوا ثمانية بظنة واحد ... تلك المفطر من أسرتها الدم والسر والسرار بطن من الأرض تنبت فيه أحرار البقول، ويكون في بحر الأودية وأسلاق القيعان، قال: إلى سرار الأرض أو قعوده 19 والسر والسرار، والجميع الأسرار: خطوط راحة الكف، وأسارير جمع الجمع، قال: بطعنة لم تخنها الكف والسرر 20 وقال: انظر الى كف وأسرارها ... هل أنت إن أوعدتني ضائري 21 وجمع السرار أسرار وأسرة، وكذلك الخطوط في كل شيء، قال: بزجاجة صفراء ذات أسرة ... قرنت بأزهر في الشمال مفدم 22 والسرة: الوقبة في وسط البطن. والسرر: داء يأخذ في السرة، وبعير أسر وناقة سراء اذا بركت تجافت عن الأرض من السرر، قال: ان جنبي عن الفراش لنابي ... كتجافي الأسر فوق الظراب 23 ويقال: المسرة أطراف الريحان. والسرور من النبات: أنصاف سوقها العلى، قال: كبردية الغيل وسط الغريف ... اذا خالط الماء منها السرورا 24 وقيل: السرور أجواف العيدان، الواحدة سرر. وسرر الصبي: ما تعلق من سرته حين يولد. وعدد السرير أسرة، وجمعه سرر. والسرار: مصدر ساررته من السر، وجمع السر أسرار. والسرير: مستقر العيش الذي اطمأن عليه خفضه ودعته. وسرير الرأس: مستقره على محرك عنقه، قال: ضربا يزيل الهام عن سريره 25 ومن روى بيت الأعشى: خالط الماء منها السريرا عنى به جميع أصلها الذي استقرت عليه أو غاية نعيمها، وقال: وفارق منها عيشة غيدقية ... ولم يخش يوما أن يزول سريرها 26 قوله: سريرها يريد سارها. والسر: كناية عن الجماع، قال: ولا تقربن جارة إن سرها ... عليك حرام فانكحن أو تأبدا 27 وسر القوم: أوسط حسبهم. والسرار: مصدر السر في الحسب والمنبت من غير اشتقاق، قال: تخير من سرارة أثل حجر ... ولاءم بينها نحت القيون 28 وامرأة سارة سرة: تسرك. والسرية على فعلية: من تسررت، وغلط من يقول: تسريت. والسرور: الفرح، وسررت أنا، وسررت فلانا. والسرسور 29 : العالم الفطن الدخال في الأمور.'),
(2546, 'رس', 'رس', 'رس', 'الرس: بئر لبقية من قوم ثمود. والرس في قوافي الشعر: صرف الحرف الذي بعد الألف للتأسيس نحو حركة عين فاعل في القافية حيثما تحركت حركتها جازت وكانت رسا للألف أي أصلا. والرسيس: الشيء الثابت اللازم مكانه، قال: رسيس الهوى من طول ما يتذكر 30 ويقال: أجد رسيس الحمى ورسها وذلك حين يبدو، وقال: اذا غير النأي المحبين لم أجد ... رسيس الهوى من ذكر مية يبرح 31 والرس: تزوير الحديث والكلام في نفسك وترويضه. والرس: إحكام البناء مثل الرص، وبنيان مرسوس. والرس والرسيس: ماءان لبني سعد، قال زهير: عفا الرس منها فالرسيس فعاقله 32 والرسرسة: مثل الرصرصة، وهو إثبات البعير ركبتيه على الأرض للنهوض 33 . والرس: الحفر، وكل شيء أدخلته فقد رسسته.'),
(2547, 'سل', 'سل', 'سل', 'السل: إخراجك الشعر من العجين ونحوه من الأشياء. والانسلال: المضي والخروج من بين مضيق أو زحام. وسللت السيف فانسل من غمده. والسل والسلال: داء يأخذ الانسان ويقتل، وسل الرجل وأسله الله إسلالا [فهو مسلول] 34 . والإسلال: السرقة الخفية. والسل والسليل والسلان: جماعة أودية بالبادية. والسليل والسليلة: المهر [والمهرة] 35 . [والسليل: دماغ الفرس] 36 . والسليل: الولد، [سمي سليلا، لأنه خلق من السلالة] 37 . والسليلة: عقبة أو عصبة أو لحمة اذا كانت شبه طرائق ينفصل بعضها عن بعض، [وأنشد: لاءم فيه السليل الفقار 38 قال: السليل لحمة المتنين] 39 . وكذلك السلائل في الخيشوم، وهي لحمات عراض بعضها ملتزقات ببعض. والتسلل: فعل جماعة القوم اذا انسلوا، [ويتسللون وينسلون واحد] 40 . وسلة الفرس: دفعته في سباقه، تقول: قد خرجت سلة هذا الفرس على سائر الخيل، قال: ألزا اذ خرجت سلته ... وهلا تمسحه ما يستقر 41 الألز: الوثاب، والسلة: السبذة المطبقة كالجؤنة. والمسلة: المخيط، وجمعه مسال. والسلسل: الماء العذب الصافي يتسلسل في الحلق، وفي صبب أو حدور اذا جرى. وهو السلسال، وخمر سلسل قال الأخطل: أدب إليها جدولا يتسلسل 42 وقال: بردى يصفق بالرحيق السلسل 43 والسلة: الفرجة بين نصائب الحوض، [وأنشد: أسلة في حوضها أم انفجر 44 وفي حديث أبي زرع بن أبي زرع: كمسل شطبة أراد بالمسل: ما سل من شطب الجريدة، شبهه به لدقة خصره] 45 . والسلاسل جمع السلسلة. وبرق ذو سلاسل، ورمل مثله، وهو تسلسله الذي يرى في التوائه 46 . وماء سلاسل: عذب. قال زائدة: كل منتوج سليل لأنه يسل من بطن أمه لأنه يجبذ بالأيدي سلا. وفي بني فلان مسلة أي سرقة. وفيهم سلة أي سيوف حداد. والسلة حصى صغار مثل الجوز في بطون الأودية، لأن الماء سلها من بين الجبال 47 . والسليل: اسم منزل بالبادية. وذات السلاسل: أرض من أرض الشام غزاها عمرو بن العاص على عهد النبي- صلى الله عليه وآله وسلم- 48 . والمسلسل والمسنسن: طريق يسلك يتخلل البلاد كأنه حية. ودابة سلسة 49 أي منقادة. والسلس: السيف، وجمعه سلوس. والسلس: الخيط ينظم فيه الخرز، وجمعه سلوس، قال: وقلائد من حبلة وسلوس 50'),
(2548, 'لس', 'لس', 'لس', 'اللس: تناول الدابة الحشيش بجحفلتها اذا نتفته، قال زهير: قد اخضر من لس الغمير جحافله 51 والملسوس: الذاهب العقل.'),
(2549, 'سن', 'سن', 'سن', 'السن واحدة الأسنان. وكبرت سن الرجل: يعنى به الهرم 52 ، أخذ من السن التي نيبت 53 وليس من السنين، ومنه يقال: حديث السن وسنه حديث 54 . وأسن الرجل: [كبر] . وناقة مسنة والجمع مسان. وسن من ثوم أي حبة من رأسه. وأسنان المنجل ونحوه في كل شيء: أشره. وسنان الرمح سنان مسنون سنين 55 . والمسن: الحجر الذي يسن عليه السكين، أي يحدد والسن: أن تسن الطين بيدك اذا طينت أو اتخذت منه فخارا. ورجل مسنون الوجه: كان قد سن عن وجهه اللحم أي خفف. وحمأ مسنون، قيل: هو المنتن. والمسنون في كلام العرب المصور. وما أحسن سنة وجهه أي دوائره. والسنة: ما لج الفرس في عدوه وإقباله وإدباره، قال في وصف الشول: اذا اشمعلت سنن رسابها 56 أي رفق بها. والمسنون أخذ من سنة الوجه. وأراد رجل ابتياع جمل، فسأل صاحبه عن سنه فكذبه، وجاء آخر ببكر يبيعه فسأله عن سنه فصدقه فقال: صدقني سن بكره 57 فذهبت مثلا. والسنة: اسم الدبة او الفهد. والسناسن: حروف فقار الظهر العليا التي يسبق بعضها بين شطي سنام البعير، الواحد سنسن. وسنسن: اسم أعجمي يسمي به أهل السواد. والمسنن: طريق يسلك، والمسلسل مثله. ويقال: السنة والمنة، فالسنة الدبة، والمنة القردة. ويقال: السنينة من الرمل الشقيقة المنقطعة، وجمعها سنائن. والسنينة: الرمح، وجمعها سنائن، قال مالك بن خالد الخناعي: 58 : فضول رجاع رقرقتها السنائن والرجاع: الغدران. والسنن: أول القوم. والسنة: العام القحط.'),
(2550, 'نس', 'نس', 'نس', 'النس لزوم امضاء في كل أمر، وهو سرعة الذهاب لورود الماء خاصة 59 ، قال العجاج: وبلدة يسمى قطاها نسسا 60 والتنساس: التفعال منه، قال الحطيئة: طال بها حوزي وتنساسي 61 والنس: الحث السريع، والناس المصدر، ونسه ينسه نسا وأنسست بعيري: حثثته في السوق. والنسيس: جهد الإنسان، قال أبو زبيد: اذا علقت مخالبه بقرن ... فقد أودى اذا بلغ النسيس 62 أي بلغ مجهوده. [وأنشد: باقي النسيس مشرف كاللدن] 63 والنسنسة: سرعة الطيران، يقال: نسنس ونصنص. ويقال: طبخ اللحم حتى نس، والناس: الذي ذهب طعمه وبلله من شدة الطبخ، ونس ينس نسوسا، وأنسست لحمك يا فلان. والنسيس: البقية من الشيء، وأصله بقية الروح، يقال: ما بقي منه الا نسيسه، أي بقية روحه، قال الكميت: ولكن مني بر النسيس ... أحوط الحريم وأحمى الذمارا 64 أي لا ازال بهم بارا ما بقي في النسيس أي قوة وحياة ومنه قوله: فقد أودى اذا بلغ النسيس 65 والنسناس: خلق في صورة الناس، أشبهوهم في شيء وخالفوهم في شيء، وليسوا من بني آدم. ويقال فيهم: كانوا حيا من عاد عصوا رسلهم فمسخهم الله نسناسا، لكل إنسان يد ورجل من جانب، ينقزون نقز الظبي، ويرعون رعي البهائم. ويقال: إنهم انقرضوا، والذين هم على تلك الخلقة ليسوا من أصلهم ولا نسلهم، ولكن خلق على حدة. والنسانس جمع النسناس، قال: وما الناس الا نحن أم ما فعالهم ... وإن جمعوا نسناسهم والنسانسا 66'),
(2551, 'سف', 'سف', 'سف', 'سففت السويق أسفه سفا اذا اقتمحته، والاقتماح لكل شيء يابس: [سف] 67 والسفوف الاسم، والسفة: القمحة، والسفة فعل مرة وأسففت الجرح دواء، وأسففت الوشم نئورا. وإسفاف الخوص: نسجه بعضا في بعض، وكل شيء ينسج بالأصابع. والسفيفة بطان عريض يشد به الرحل والوكاف 68 . والإسفاف: الدنو من الأرض قال عبيد: دان مسف فويق الأرض هيدبه ... يكاد يدفعه من قام بالراح 69 يعني السحاب. والسف: الحية التي تطير، قال: وحتى لو أن السف ذا الريش عضني ... لما ضرني من فيه ناب ولا ثعر 70 والثعر: السم. والسفيف والإسفاف: المرور على وجه الأرض كما يسف الطير. وأسف الرجل اذا تتبع مداق الأمور والأشياء كأنما يطلب اللقط في التراب، قال: وسام جسيمات الأمور ولا تكن ... مسفا الى ما دق منهن دانيا 71 والإسناف في النظر: دقته وحدته، شبه اللزوم واللصوق، ويقال: لا تسف النظر أي لا تحد. والسفسفة: انتخال الدقيق من منخل ونحوه، قال: اذا مساحيج الرياح السفن ... سفسفن في أرجاء خاو مزمن كالطحن إذ يذرى ذرى لم يطحن 72 والسفساف من الشعر ونحوه: أردؤه.'),
(2552, 'فس', 'فس', 'فس', 'والمفسفس في شعر الكميت 73 : اللئيم العطية. والفسيفساء: ألوان من الخرز يؤلف بعضه الى بعض، ثم يركب في حيطان البيوت من داخل كأنه نقش مصور، وأكثر من يتخذه أهل الشام، قال: كصوت اليراعة في الفسفس 74 أي في البيت المصور بالفسيفساء. والفسفسة: القت الرطب.'),
(2553, 'سب', 'سب', 'سب', 'سبه فلان سبأ. والسبسب: المفازة. والسبب: الحبل. والسبب: كل ما تسببت به من رحم أو يد أو دين. وكل سبب ونسب منقطع يوم القيامة الا سبب النبي- صلى الله عليه وآله وسلم- ونسبه ، وهذا في الحديث. والإسلام أقوى سبب ونسب لأن المسلم اذا تقرب الى أخيه المسلم ليس بينهما نسب. ويقال للرجل الفاضل في الدين: ارتقى فلان في الأسباب، قال الله- عز وجل-: فليرتقوا في الأسباب 75 يقال: معناه إن كانوا يقدرون أن يصلوا بالسماء أسبابا فيرتقوا اليها فليفعلوا. والسب: الثوب الرقيق، وجمعه سبوب. وكذلك السبيبة وجمعها: سبائب. والسب: الكثير السباب. ويوم السباسب: يوم السعانين. والسبب: سبب الأمر الذي يوصل به، وكل فصل يوصل بشيء فهو سبب. والسبب: الطريق لأنك تصل به الى ما تريد. والسبابة: الإصبع بعد الإبهام. والسبة: العار.'),
(2554, 'بس', 'بس', 'بس', 'بس: زجر للحمار، تقول منه: بس بس 76 . وبسست وأبسست وهم يبسون ويبسون. والمبس: المتلطف للناقة المسكنها بكلام حتى يحلبها. وبسبس: اسم رجل 77 . وانبست الحيات اذا تفرقت في الأرض 78 . والبسبس: شجر تتخذ منها الرحال 79 . والبسابس: الكذب الذي ليس له أصل وكذلك الترهات. والبسباسة: بقلة. [وأبس بالناقة إبساسا: دعاها للحلب: وإذا درت على الإبساس قيل: ناقة بسوس] 80 . والبسوس: كانت ناقة ترعى فرماها كليب التغلبي فقتلها، ويقال: بل اسم المرآة التي كانت الناقة لها، وبذلك السبب هاجت الحروب بين بكر وتغلب حتى تفانوا فيقال: أشأم من البسوس.'),
(2555, 'سم', 'سم', 'سم', 'جمع السم 81 القاتل سمام. والسم: خرت الإبرة. وكل مشاق الرجل والدابة سموم، واحدها سم. والسموم: الثقوب كلها: المسمعان والمنخران والفم. والسمان: عرقان في خيشوم الفرس، ويجمع السوام. وسام أبرص: ضرب من كبار الوزغ، وتقول: ساما أبرص وسوام أبرص. والسام والسامة: الموت. والسامة: خاصة الرجل والفعل عمت وسمت 82 ، قال: هو الذي أنعم نعمى عمت ... على الذين أسلموا لو سمت 83 والسمة والسم والسموم: الودع وأشباهه يستخرج من البحر، ينظم للزينة، ويقال: كل خرق في ودع أو خرز، قال: يمد بعطفيه الوضين المسمما 84 أي وضين مزين بالسموم. والسمام، والسمامة واحدة،: ضرب من الطير دون القطا في الخلقة، يشبهه وليس به، قال النابغة: سمام تباري الطير 85 ويقال: هو طير يشبه الحمام الطوراني، وهو مذكر ويسمى اللواء سماما تشبيها به. والسموم: الريح الحارة. ونبات مسموم: أصابته السمائم. والسمسم: حب دهن الحل، والسمسم: ضرب من الثعالب، وقال: فارقني ذألانه وسمسمه 86 والسمسم: موضع. والسمسمة: دويبة حمراء على خلقة الأكلة. والسمامة والسماوة: الشخص من كل شيء 87 . والسم: الإصلاح، وسممت بين القوم وسملت أي أصلحت، قال الكميت: فكاسمك أنت اليوم في غير جفوة ... ولا عنف في حكمه 88 بين السم 89 والسمسم 90 والسماسم زعموا أنه شجر السير (كذا) ؟ وسم الطريق: استواؤه وقصده.'),
(2556, 'مس', 'مس', 'مس', 'مسست الشيء بيدي مسا، ومست 91 ، مخفف. ورجل ممسوس من الجنون، وبه مس. والمسوس من المياه: ما نالته الأيدي، قال: لو كنت ماء كنت لا ... عذبا يذاق ولا مسوسا 92 ومساس مصدر لا اسم، ويقال: لا مساس أي لا مماسة. والرحم المساسة والماسة: القريبة، ومسته مواس الخبل 93 . ويقال: مس المرأة ومماستها إتيانها. والمسمسة و [المسماس] : اختلاط الأمر واشتباهه، قال رؤبة: إن كنت من أمرك في مسماس ... فاسط على أمك سطو الماس 94 خفف سين الماس كما يخففون في قولهم: مست الشيء أي مسست، قال ابن مغراء: مسنا السماء فنلناهم وطاء لهم 95 والماس: الذي لا يلتفت الى موعظة. ورجل ماس: خفيف.'),
(2557, 'طرس', 'طرس', 'طرس', 'الطرس: الكتاب يمحى ثم يعاد فيه، وفعله التطريس.'),
(2558, 'سطر', 'سطر', 'سطر', 'السطر سطر من كتب، وسطر من شجر مغروس ونحوه، قال: إني، وأسطار سطرن سطرا، ... لقائل يا نصر نصرا نصرا 96 يستغيث به: يا نصر انصرني. ويقال: سطر فلان علينا تسطيرا اذا جاء بأحاديث تشبه الباطل. والواحد من الأساطير إسطارة وأسطورة، (وهي) أحاديث لا نظام لها بشيء. ويسطر معناه يؤلف ولا أصل له، [وسطر يسطر اذا كتب] 97 . [وقال الله جل وعز-: ن والقلم وما يسطرون 98 ، أي وما يكتب الملائكة] 99 . والسيطرة مصدر المسيطر، وهو كالرقيب الحافظ المتعهد للشيء، والمصيطر لغة، وتقول: قد تسيطر علينا فلان [وتقول: سوطر يسيطر في مجهول فعله، وانما صارت سوطر ولم تقل: سيطر لأن الياء ساكنة لا تثبت بعد ضمة، كما أنك تقول من آيست: أويس يؤيس. ومن اليقين أوقن يوقن فاذا جاءت ياء ساكنة بعد ضمة لم تثبت، ولكنها يجترها ما قبلها فيصيرها واوا في حال، مثل قولك: أعيش بين العيشة، وأبيض وجمعه بيض، وهي فعله وفعل، فاجترت الياء ما قبلها فكسرته وقالوا: أكيس كوسى وأطيب طوبى، وانما توخوا في ذلك أوضحه وأحسنه، وأيا ما فعلوا فهو القياس، ولذلك يقول بعضهم في قسمة ضيزى 100 انما هي فعلى، ولو قيل: بنيت على فعلى لم يكن خطأ، ألا ترى أن بعضهم يهمزها على كسرتها، فاستقبحوا أن يقولوا: سيطر لكثرة الكسرات، فلما تراوحت، الضمة والكسرة كانت الواو أحسن. وأما يسيطر فلما ذهبت منه مدة السين رجعت الياء] 101 .'),
(2559, 'سرط', 'سرط', 'سرط', 'السرط منه الاستراط وهو سرعة الابتلاع من غير مضغ. والسرطراط والسرطراط: الفالوذج. والسرطان من خلق الماء. ويقال له بالفارسية خرخبق. والسرطان: برج في السماء منه أنف الأسد. والسرطان: داء يظهر بقائمة الدابة. والسراط: القطاع.'),
(2560, 'طسل', 'طسل', 'طسل', 'يقال: طسل السراب اذا اضطرب، [وقال رؤبة: يقنع الموماة طسلا طاسلا] 102 والطيسل: الغبار الرقيق.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2561, 'سطل', 'سطل', 'سطل', 'السطل معروف. والسيطل: الطسيسة الصغيرة، على صنعة تور له عروة كعروة المرجل، [والسطل مثله، قال الطرماح: في سيطل كفئت له يتردد 103 وقال هميان بن قحافة في الطسل: بل بلد يكسى القتام الطاسلا ... أمرقت فيه ذبلا ذوابلا 104 وقالوا: الطاسل الملبس. وقال بعضهم: الطاسل والساطل من الغبار: المرتفع، وأيد قول هميان قول رؤبة الأول] 105'),
(2562, 'سلط', 'سلط', 'سلط', 'السلاطة مصدر السليط [من الرجال] 106 والسليطة من النساء، والفعل سلطت اذا طال لسانها واشتد صخبها، ورجل سليط. والسليط: الزيت، قال: ولكن ديامي آبوه وأمه ... بنجران يعصرن السليط قرائبه 107 والسلطان في معنى الحجة، قال تعالى: هلك عني سلطانيه 108 أي حجتيه. والسلطان: قدرة الملك، [مثل قفيز وقفزان وبعير وبعران] 109 ، وقدرة من جعل ذلك له وإن لم يكن ملكا، كقولك: قد جعلت له سلطانا على أخذ حقي من فلان. والنون في السلطان زائدة، وأصله من التسليط. والسلاط: الغليل، قال المتنخل: وأخشى أن ألاقي ذا سلاط 110'),
(2563, 'طلس', 'طلس', 'طلس', 'الطلس: كتاب قد محي ولم ينعم محوه. واذا محوت لتفسد خطه قلت: طلسته، فاذا انعمت محوه قلت: طرسته فيصير طلسا. ويقال لجلد فخذ البعير: طلس لتساقط شعره ووبره. والطلس والطلسة مصدر الأطلس، والأطلس من الذئاب: الذي قد تساقط شعره، وهو أخبث ما يكون. والطلس والطلسة: غبرة في غبسة. [وفي حديث ابي بكر أن مولدا أطلس سرق فقطع يده] 111 . والطيلسان، بفتح اللام وكسره، ولم يجيء فيعلان مكسورا غيره، وأكثر ما يجيء فيعلان مفتوحا أو مضموما نحو الخيزران والجيسمان، ولكن لما صارت الكسرة والضمة أختين واشتركتا في مواضع [كثيرة] 112 دخلت الكسرة مدخل الضمة.'),
(2564, 'لطس', 'لطس', 'لطس', 'اللطس: ضربك الشيء بشيء عريض، ويقال: لطسه البعير بخفه. والملطاس: حجر عريض فيه طول، وربما سمي خف البعير وحافر الدابة ملطاسا، وقيل: جمع ملطاس ملاطيس، وهو معول تكسر به الصخرة، تقول: قد ركبت في قوائمها حوافر أمثال الملاطيس، قال: وأبا كملطاس الصفا مقعبا 113'),
(2565, 'نطس', 'نطس', 'نطس', 'النطس ومنه التنطس وهو التقزز 114 والنطاسي والنطيس العالم بالطب، وهو بالرومية النسطاس، وما أنطسه.'),
(2566, 'سنط', 'سنط', 'سنط', 'السناط: الكوسج [من الرجال] 115 ، وفعله سنط، وكذلك عامة ما جاء على بناء فعال، [وكذلك ما جاء على بناء المجهول ثلاثيا] 116 .'),
(2567, 'سطن', 'سطن', 'سطن', 'الأسطوانة معروفة. ويقال للرجل الطويل الرجلين والظهر: أسطوان 117 . ونون الأسطوانة من أصل بناء الكلمة على تقدير أفعوالة، وبيانه قولهم أساطين مسطنة.'),
(2568, 'فطس', 'فطس', 'فطس', 'الفطس حب الآس، والواحدة فطسة. والفطس: انخفاض قصبة الأنف، والنعت أفطس، وفطس فطسا. ويقال لخطم الخنزير: فطسة. والفطيس: المطرقة للحدادين. والفطوس: مصدر الفاطس، وهو الذي يموت من غير داء ظاهر، وفطس وفقس.'),
(2569, 'فسط', 'فسط', 'فسط', 'الفسطاط والفسطاط: ضرب من الأبنية. والفسطاط: مجتمع أهل الكورة حوالي مسجدهم، وهم الجماعة، ويقال: هؤلاء أهل الفسطاط. والفسيط: علاقة 118 ما بين القمع 119 والنواة، وهو الثفروق 120 ، والواحدة فسيطة.'),
(2570, 'سفط', 'سفط', 'سفط', 'جمع السفط أسفاط. ويقال: نفسي سفيطة أي قوية. ويقال: انه لين سفاطة النفس.'),
(2571, 'طفس', 'طفس', 'طفس', 'الطفس: قذر الانسان اذا لم يتعاهد نفسه ولا يتنظف، وإنه لطفس، وانها لطفسة.'),
(2572, 'بسط', 'بسط', 'بسط', 'البسط نقيض القبض. والبسيطة من الأرض كالبساط من المتاع، وجمعه بسط. والبسطة: الفضيلة على غيرك، [قال الله- جل وعز-: وزاده بسطة في العلم والجسم 121 ] 122 . والبسيط: الرجل المنبسط اللسان، والمرأة بسيطة، وقد بسط بساطة، والصاد لغة. وبسط الينا فلان يده بما نحب ونكره. وانه ليبسطني ما بسطك ويقبضني ما قبضك أي [يسرني ما سرك ويسوءني ما ساءك] 123 . والأبساط من النوق: التي معها أولادها، والواحد بسط 124 والبسيط: نحو من العروض.'),
(2573, 'سبط', 'سبط', 'سبط', 'السبط: نبات كالثيل ينبت في الرمال، له طول، الواحدة سبطة، ويجمع على أسباط 125 . والساباط: سقيفة بين دارين من تحتها طريق نافذ. والسبط من أسباط اليهود بمنزلة القبيلة من قبائل العرب، وكان بنو اسرائيل اثني عشر سبطا، عدة بني اسرائيل وهم بنو يعقوب بن اسحاق، لكل ابن منهم سبط من ولده. قال تبع في يهود المدينة، بني قريظة وبني النضير: حنقا على سبطين حلا يثربا ... أولى لهم بعقاب يوم سرمد 125 والسبط: الشعر الذي لا جعودة فيه، ولغة أهل الحجاز: رجل سبط الشعر، وامرأة سبطة، وقد سبط شعره سبوطة 126 وسبطا 127 . وانه لسبط الأصابع أي طويلها، وسبط اليدين أي سمح الكفين، [وقال حسان: رب خال لي لو أبصرته ... سبط الكفين في اليوم الخصر] 128 وسباط: اسم شهر بالرومية، وهو فصل بين الربيع والشتاء، وفيه يكون كما يزعمون تمام اليوم الذي تدور كسوره في السنين، فاذا تم ذلك اليوم في ذلك الشهر سمى أهل الشام تلك السنة عام الكبيس، يتيمن به اذا ولد في تلك السنة، أو قدم فيه إنسان. والسبطانة: قناة جوفاء مضروبة بالعقب يرمى فيها بسهام صغار تنفخ نفخا فلا تكاد تخطىء. وسباط: الحمى النافض، قال المتنخل: كأنهم تملهم سباط 129'),
(2574, 'طبس', 'طبس', 'طبس', 'التطبيس والتطبين واحد. والطبسان: كورتان من كور خراسان 130 .'),
(2575, 'مسط', 'مسط', 'مسط', 'ومسط يمسط مسطا، وهو خرطك ما في المعى باصبعك ونحوه لتخرج ما فيه. واذا نزا على الفرس الكريمة فحل لئيم أدخل رجل يده فخرط ماءه من رحمها، يقال: مسطها ومصتها ومساها (يمسي ويمسو) ، وكأنهم عاقبوا بين التاء والطاء في هذه الكلمة. والماسطة 131 : ضرب من شجر الصيف اذا رعته الابل مسط بطونها فخرطها، [وقال جرير: يا ثلط حامضة تربع ماسطا ... من واسط وتربع القلاما] 132'),
(2576, 'سطم', 'سطم', 'سطم', 'يقال: أسطمة البحر لغة في أصطمه، وهي مجتمعه ووسطه، قال: له نواح وله أسطم 133 وأسطمة الحسب كذلك، والسين لغة فيهما جميعا، وقد مر في الصاد.'),
(2577, 'طسم', 'طسم', 'طسم', 'طسم حي ناصبوا عادا، انقرضوا وصاروا أحاديث. وطسم الشيء طسوما أي درس، قال: أحاديث طسم إنما أنت حالم 134'),
(2578, 'طمس', 'طمس', 'طمس', 'طمس: لغة في [طسم، أي:] درس الا أنه أعم. وطمس النجم: ذهب ضوؤه، والقمر مثله. وخرق طامس، وجبل طامس: لا نبات فيه ولا مسلك. والطمس الآية التاسعة من آيات موسى- عليه السلام- حين طمس الله- تعالى- بدعوته على أموال فرعون فصارت حجارة. وقيل: الآيات التسع: يده وعصاه والجراد والقمل والضفادع والدم والسنون ونقص الثمرات. وقوله- عز وجل-: ربنا اطمس على أموالهم 135 اي امسخها.'),
(2579, 'مطس', 'مطس', 'مطس', 'مطس العذرة يمطسها: رمى بها بمرة واحدة.'),
(2580, 'سمط', 'سمط', 'سمط', 'حمل مسموط: نتف منه الصوف وشوي، وسمط يسمط سمطا. ويقال: بل هو الخمط. والسمط: السلخ، وسمط يسمط. والسمط يجمع على سموط، وهو المعاليق من السيور في السرج. وسموط القلادة يكون لها معاليق على الصدر. والسمط: الرجل الخفيف في جسمه، الداهية في أمره، وأكثر ما يوصف به الصياد، [وأنشد لرؤبة: سمطا يربي ولدة زعابلا] 136 والسامط: لبن ذهبت حلاوة الحلب منه ولم يتغير طعمه، وفعله سمط يسمط. ويقال: نعل سمط وسمط اذا لم يكن فيها رقاع، ويقال: نعل أسماط. [والشعر المسمط: الذي يكون في صدر البيت أبيات مشطورة أو منهوكة مقفاة تجمعها قافية مخالفة لازمة للقصيدة حتى تنقضي. وقال امرؤ القيس قصيدتين على هذا المثال يسميان السمطين فصدر كل قصيدة مصراعان في بيت، ثم سائره في سموط، فقال في إحداهما: ومستلئم كشفت بالرمح ذيله ... أقمت بعضب ذي سفاسق ميله فجعت به في ملتقى الخيل خيله ... تركت عتاق الطير يحجلن حوله 137 وقال: كأن على سرباله نضح جريال 138 وناقة سمط وأسماط: لا وسم عليها، كما يقال: ناقة غفل. وقال العجاج يصف ثورا وحشيا وصيادا وكلابه فقال: عاين سمط قفرة مهفهفا ... وسرمطيات يجبن السوفا] 139'),
(2581, 'سدر', 'سدر', 'سدر', 'السدر شجر حمله النبق، والواحدة بالهاء، وورقه غسول. وسدرة المنتهى في السماء السابعة لا يجاوزها ملك ولا نبي، قد أظلت السماوات والجنة. والسدر: اسمدرار البصر، وسدر بصره سدرا اذا لم يكد يبصر الشيء حسنا، فهو سدر وعينه سدرة. وفي عينة سمادير أي غشوة. وسدر شعره يسدره سدرا اذا أرسله، قال: أثيث شعر على المتنين مسدور 140 وهو كالسدل للثوب. والأسدران: المنكبان. وقال الحسن في الأثر: يضرب أسدريه ويخطر في مذرويه 141 . والسادر: الذي لا يقلع ولا ينزع عما هو فيه من غيه وضلاله وتكلم فلان سادرا: غير متثبت في كلامه، ولم أسمع له فعلا، قال: ولا تنطق العوراء في القول سادرا ... فإن له فاعلم من الله واعيا 142 والسدير: اسم نهر [بالحيرة، وقال عدي: سره حالة وكثرة ما يملك ... والبحر معرضا والسدير] 143 وسيف منسدر أي ماض، وانسدر عليهم الخير والشر أي انسدل 144 . والسدر: الثوب بلغة قوم.'),
(2582, 'دسر', 'دسر', 'دسر', 'الدسر: الدفع الشديد والطعن، ودسره بالرمح. والدسار خيط من ليف تشد به ألواح السفينة، والمسامير أيضا تسمى دسرا في أمر السفينة، واحدها دسار، قال العجاج في الدسر: عن ذي قداميس لهام لو دسر 144 والبضع أيضا يستعمل فيه الدسر. وجمل دوسر ودوسري ودوسراني: ضخم الهامة والمنكب 145 .'),
(2583, 'سرد', 'سرد', 'سرد', 'سرد القراءة والحديث يسرده سردا أي يتابع بعضه بعضا. والسرد: اسم جامع للدروع ونحوها من عمل الحلق، وسمي سردا لأنه يسرد فيثقب طرفا 146 كل حلقة بمسمار فذلك الحلق المسرد، قال الله- عز وجل: وقدر في السرد 147 اي اجعل المسامير على قدر خروق الحلق، لا تغلظ فتنخرم ولا تدق فتقلق. والسراد والزراد والمسرد: المثقب، قال: كما خرج السراد من النقال 148 وسميت النعل المخصوفة اللسان مسردا. وسمي الزراد سرادا لأن السين قريبة من الزاي كما قالوا للأسد: أزد، فاذا صغر أزد رجعوا الى السين فقالوا: أسيد.'),
(2584, 'ردس', 'ردس', 'ردس', 'الردس: دكك أرضا أو حائطا أو مدرا بشيء صلب عريض يسمى مردسا، والفعل يردس، قال العجاج: يغمد الأعداء جوزا مردسا 149'),
(2585, 'درس', 'درس', 'درس', 'الدرس: ضرب من الجرب يبقى له أثر متفش في الجلد، قال العجاج: من عرق النضح عصيم الدرس 150 والدرس: بقية أثر الشيء الدارس، والمصدر الدروس. ودرسته الرياح أي عفته. والدرس: درس الكتاب للحفظ، ودرس دراسة، ودارست فلانا كتابا لكي أحفظ. والدريس: الثوب الخلق، وكذلك من البسط ونحوها. وقتل رجل رجلا من جلساء النعمان في مجلسه فأمر بقتله فقال: أيقتل الرجل جاره ويضيع ذماره، قال: نعم اذا قتل جليسه وخضب دريسه، ويجمع الدريس على الدرسان.'),
(2586, 'سدل', 'سدل', 'سدل', 'السدل: شعر منسدل كثير طويل، وقع على الظهر. وكره السدل في الصلاة، وهو إرخاء الثوب من المنكبين الى الأرض.'),
(2587, 'دلس', 'دلس', 'دلس', 'ودلس في البيع وفي كل شيء اذا لم يبين له عيبه.'),
(2588, 'سدن', 'سدن', 'سدن', 'السدن: الستر، والسدانة: الحجابة 151 . والسدين: الحاجب، وسدنه البيت حجابه.'),
(2589, 'سند', 'سند', 'سند', 'السند: ما ارتفع من الارض في قبل جبل أو واد. وكل شيء أسندت اليه شيئا فهو مسند. والكلام سند ومسند كقولك: عبد الله رجل صالح، فعبد الله سند و [رجل] صالح مسند إليه. وناقة سناد أي طويلة القوائم مسندة السنام. والسند: ضرب من الثياب، قميص ثم يلبس فوقه قميص أقصر منه. وكذلك قمص قصار من خرق مغيب بعضها تحت بعض، وكل ما ظهر من ذلك يسمى سمطا، قال العجاج في الثور وما على قوائمه من الوشي 152 : كتانها أو سند أسماط 153 والمسند: الدهر لأن الاشياء تسند إليه، تقول: كان كذا في زمان كذا. والسناد في الشعر: اختلاف حرف المقيد والمردف نحو الدين مع الدين في القوافي، يقال: ساندت في شعرك كقوله: ألا هبي بصحنك فاصبحينا 154 ثم قال: تصفقها الرياح اذا جرينا 155 والسندأوة: الجريء الشديد، قال: سندأوة مثل الفنيق الحافر 156 والسناد: أن يسلخ شعر غيره فيسنده الى نفسه فيدعيه أنه من شعره.'),
(2590, 'ندس', 'ندس', 'ندس', 'رجل ندس وندس أي فطن. والندس: السريع الاستماع للصوت الخفي، ويكون الصوت الخفي ندسا، وقد ندس ندسا.'),
(2591, 'سدف', 'سدف', 'سدف', 'السدف: ظلام الليل، أو سواد شخص تراه من بعيد. والسدفة طائفة من الليل، يقال أسدف الليل. والسديف: شحم السنام. [والسدفة: الباب، وأنشد لامرأة من قيس تهجو زوجها: لا يرتدي مرادي الحرير ... ولا يرى بسدفة الأمير] 157'),
(2592, 'دسف', 'دسف', 'دسف', 'الدسفان: الذي يطلب الشيء شبه الرسول، وجمعه قال أميه: وأرسلوه يسوف العيث دسفانا 158'),
(2593, 'فسد', 'فسد', 'فسد', 'الفساد: نقيض الصلاح، وفسد يفسد، وأفسدته.'),
(2594, 'سفد', 'سفد', 'سفد', 'وسفدها سفادا، ولغة سفدها سفدا. والسفافيد: جمع السفود.'),
(2595, 'دبس', 'دبس', 'دبس', 'الدبس: الكثير. والدبس: عصارة الرطب والتمر. والدبسة: لون في سواد الشعر أحمر مشرب سوادا. والدبوس: خلاص تمر يلقى في مسلأ السمن فيذوب فيه، وهو مطيب للسمن. والمسلأ: البرمة التي يسلأون فيها السمن. والدبوسية اسم كورة.'),
(2596, 'سبد', 'سبد', 'سبد', 'السبد: الشعر، وقولهم: ما له سبد ولا لبد أي ما له ذو شعر ولا وبر متلبد، وبه سمي سبدا. والسبد: الشؤم: [حكاه عن أبي الدقيش في قوله: أمرؤ القيس بن أروى مؤليا ... ان رآني لأبوأن بسبد قلت بحرا قلت قولا كاذبا ... إنما يمنعني سيف ويد] 159 وسبد رأسه وسمده اي استأصله، ويقال: التسبيد حلق الرأس فينبت بعد ايام شعره فذلك التسبيد. والسبد طائر مثل الخطاف اذ أصابه المطر سال عنه 160 .'),
(2597, 'دسم', 'دسم', 'دسم', 'الدسم كل شيء له ودك من اللحم والشحم، والنعت دسم، والفعل دسم يدسم. والدسام سداد كل خرق أو جحر، ودسمته أدسمه دسما والديسم 161 : الثعلب.'),
(2598, 'سدم', 'سدم', 'سدم', 'السدم هم في ندم، [وتقول: رأيته سادما، ورأيته سدمان ندمان. وقلما يفرد السدم] 162 وماء سدم: وقعت فيه الأقمشة والجولان حتى يكاد يندفن، وقد سدم يسدم، ومياه أسدام. ويقال: منهل سدوم وسدم، قال: ومنهلا وردته سدوما 163 وقال: سدم المساقي آجنات صفرا 164 وسدوم: مدينة من مدائن لوط- عليه السلام-، وكان قاضيها يقال له: سدوم.'),
(2599, 'دمس', 'دمس', 'دمس', 'دمس الظلام وأدمس، والدمس: نفس الظلام اذا اشتد، وليل دامس. والتدميس: إخفاء الشيء تحت التراب، ويخفف ايضا. [وأنشد: اذا ذقت فاها قلت علق مدمس ... أريد به قيل فغودر في سأب 165 ] 166 والدودمس: ضرب من الحيات محرنفش الغلاصيم ينفخ نفخا فيجرح 167 ما أصاب، والجميع الدودمسات والدواميس.'),
(2600, 'سمد', 'سمد', 'سمد', 'السمد من السير: [الدأب، ويقال] : سمدت الإبل تسمد سمودا أي لم تعرف الإعياء، وأنشد: سوامد الليل خفاف الأزواد 168 والسمود في الناس: الغفلة والسهو عن الشيء، وقوله- عز وجل-: وأنتم سامدون 169 ، أي ساهون لاهون، ويقال: دع عنك سمودك. [وروي عن علي- رضي الله عنه- أنه خرج الى المسجد والناس ينتظرونه للصلاة قياما، فقال: ما لي أراكم سامدين] 170 . والسامد: القائم، وكل رافع رأسه فهو سامد، وسمد يسمد ويسمد سمودا. والسماد: تراب قوي يسمد به النبات. وسمد شعره: أخذه كله.'),
(2601, 'مسد', 'مسد', 'مسد', 'المسد: ليف لين يتخذ من النخل. والمسد: إدآب السير في الليل، وأنشد: يكابد الليل عليها مسدا 171 والمساد: نحي السمن او العسل، قال أبو ذؤيب: غدا في خافة معه مساد ... [فأضحى يقتري مسدا بشيق 172 والخافة: خريطة يتقلدها المشتار ليجعل فيها العسل] 173 . والمسد: المحور اذا كان من حديد. وجارية ممسودة: مطوية ممشوقة.'),
(2602, 'ستر', 'ستر', 'ستر', 'جمع الستر ستور وأستار في أدنى العدد، وسترته أستره سترا وامرأة ستيرة: ذات ستارة، والسترة: ما استترت به [من شيء كائنا ما كان] 174 ، وهو الستار والستارة 175 . والسترة: ما استتر الوجه به 176 . والستار: موضع. [ويقال: ما لفلان ستر ولا حجر، فالستر الحياء والحجر العقل] 177 .'),
(2603, 'ترس', 'ترس', 'ترس', 'الترسة جمع ترس. وكل شيء تترست به فهو مترسة لك.'),
(2604, 'ستل', 'ستل', 'ستل', 'الستل من قولك تساتل علينا الناس أي خرجوا من موضع واحدا بعد واحد تباعا متساتلين. وكذلك ما جرى قطرانا فهو تساتل، نحو الدمع واللؤلؤ اذا انقطع سلكه. والستالة: الرذالة من كل شيء.'),
(2605, 'سلت', 'سلت', 'سلت', 'السلت: شعير لا قشر له [أجرد، يكون] 178 بالغور، وأهل الحجاز يتبردون بسويقه في الصيف. والسلت: قبضك على الشيء [أصابه قذر أو لطخ فتسلته عنه سلتا] 179 وسلت أنفه بالسيف سلتا: قطعه كله، وهو من الجدعان أسلت، وامرأة سلتاء لا تتعاهد يديها ورجليها بالحناء، وامرأتان سلتاوان، ونسوة سلتى مثل غوثى. واسم ما يخرج من المعى سلاتة، وكل ما يطرح ويرمى به، شيء من شيء فهو على فعالة نحو مزاقة ومضاغة وسلافة وشبهها.'),
(2606, 'ستن', 'ستن', 'ستن', 'ستن الفرس يستن ستانا 180 : اضطرب ورقص.'),
(2607, 'سنت', 'سنت', 'سنت', 'وأسنت القوم أي أصابتهم سنة شديدة من القحط، قال: ورجال مكة مسنتون عجاف 181'),
(2608, 'سبت', 'سبت', 'سبت', 'سبت اليهودي يسبت يتخذ السبت عيدا. والسبات: النوم الغالب الكثير 182 والمريض يسبت سبتا فهو مسبوت. والسبات من النوم: شبه غشية. وسبت رأسه إذا جزه مستأصلا. [والسبت برهة من الدهر، وقال لبيد: وغنيت سبتا قبل مجرى داحس] 183 ... لو كان للنفس اللجوج خلود 184 والسبت: ضرب من السير، وبعير سبوت اذا سار تلك السيرة. والسبت: الجريء المقدم، وهو السنبت، قال ابن أحمر: لأنت خير من غلام بتا ... تصبح سكرانا وتمسي سبتا 185 والنعل السبتية: [ما] دبغ بالقرظ، قال عنترة: يحذى نعال السبت ليس بتوأم 186'),
(2609, 'بست', 'بست', 'بست', 'بست من مدائن سجستان، قال: أيا قبرا ببست يجن معنى ... عليك ولا على بست السلام 187 والبستان معروف.'),
(2610, 'متس', 'متس', 'متس', 'المتس لغة في المطس. والمطس: الفعل بالجعس.'),
(2611, 'سمت', 'سمت', 'سمت', 'السمت: حسن النحو، وسمت يسمت سمتا. وهو حسن السمت. والسمت: السير بالحدس والظن على غير الطريق، قال: ليس بها زيغ لسمت السامت 188 والتسميت: ذكر الله على الشيء. والتسميت: دعاؤك للعاطس إذا حمد الله، وبالشين أيضا.'),
(2612, 'رسل', 'رسل', 'رسل', 'الرسل: الذي فيه استرسال 189 ولين. وناقة رسلة القوائم أي سلسة لينة المفاصل: [وأنشد: برسلة وثق ملتقاها ... موضع جلب الكور من مطاها] 190 والرسل: جماعات الإبل. والرسل: القطيع من كل شيء، وجمعه إرسال، قال: [و] رسلا واردة بعد رسل والرسل يذكر ويؤنث. والرسل: الهيئة والسكون، يقال: تكلم على رسلك. والرسل: اللبن. والاسترسال إلى شيء كالاستئناس والطمأنينة، [يقال: غبن المسترسل إليك ربا] 191 . والترسل في الأمر والمنطق كالتمهل والتوقر والتثبت. والرسول بمعنى الرسالة [يؤنث ويذكر، فمن أنث جمعه أرسلا، وقال: قد أتتها أرسلي] 192 والرسل جمع الرسول، وفي لغة: هي رسول وهن رسول. والرسائل جمع الرسالة. وامرأة مراسل: كان لها زوج والخطاب يراسلونها الخطبة، وقال: وقالوا تزوج ذات مال مراسلا ... فقلت عليكم بالجوار الصعالك 193 وناقة مرسال: وهي الرسلة القوائم، الكثيرة شعر الساقين، الطويلة.'),
(2613, 'سرل', 'سرل', 'سرل', 'السراويل عربت، وتجمع سراويلات. وسرولته: ألبسته إياه فتسرول. والعرب [تقول] : سروال.'),
(2614, 'رسن', 'رسن', 'رسن', 'الرسن: الحبل، وجمعه الأرسان، والمرسن: الأنف، [وجمعه المراسن] 194 .'),
(2615, 'نسر', 'نسر', 'نسر', 'النسر: طائر معروف والنسران: نجمان في السماء يقال لأحدهما الواقع وللآخر الطائر، معروفان 195 . والنسر: نتف اللحم بالمنقار. ومنقار البازي ونحوه منسر. والمنسر: ما بين المائة إلى المائتين 196 ، ويقال: ما بين الثلاثين إلى الأربعين، قال: وأدرك منسر منا جذاما 197 والناسور في العربية: العرق الغبر، يقال: أصابه غبر في عرقه، ومنه يقال: داهية الغبر أي بلية لا تكاد تذهب. ونسر الحافر: لحمة يابسة يشبهه الشعراء بالنوى قد أقتمها الحافر [وجمعه نسور] 198 قال: صحيح النسر والأشعر ... والعرقوب والكعب 199 [وقال سلمة بن الخرشب: غدوت به تدافعني سبوح ... فراش نسورها عجم جرير] 200 والنسرين من الرياحين ترجمة الفارسية. والمنسر: الجيش الذي لا يمر بشيء إلا اقتلعه نسره كما يفعل الطائر. والمنسر: اللص.'),
(2616, 'سنر', 'سنر', 'سنر', 'السنور والسنورة. والسنور: السلاح الذي يلبس.'),
(2617, 'سرف', 'سرف', 'سرف', 'الأسرف وسرف موضعان بالحجاز. والأسراف نقيض الاقتصاد. وللحم سرف كسرف الخمر، وهو الضراوة. والمسروفة من الشاء: التي تقطع أذنها أصلا. وفي المثل: أصنع من سرفة، وهي دويبة صغيرة تنقب الشجر وتبني فيه بيتا، وسرف الشجر أي أصابته السرفة. والسرف: الجاهل، وقال: إن امرءا سرف الفؤاد يرى ... عسلا بماء سحابة شتمي 201 والسرف: الخطأ، يقال 202 : أردتكم فسرفتكم، قال: ما في عطائهم من ولا سرف 203 أي لا يخطئون ويضعونه موضعه.'),
(2618, 'رسف', 'رسف', 'رسف', 'الرسف والرسيف والرسفان: مشية المقيد، [وقد رسف في القيد يرسف رسيفا فهو راسف] 204 . والمرسفة: الممشى لما نجدها ووجدنا المرسف.'),
(2619, 'فرس', 'فرس', 'فرس', 'هذا فرس وهذه فرس والفروسة، مصدر الفارس، لا فعل له والفراسة مصدر التفرس. والفرس: دق العنق. والفريسة فريسة الأسد، ونادى منادي عمر فقال: لا تنخعوا ولا تفرسوا، أي لا تكسروا العنق. وأبو فراس: كنية الأسد، وكنية الفرزدق أيضا. والفريس: حلقة الحبل من خشب، قال: فلو كان الرشا مائتين باعا ... لكان ممر ذلك في الفريس 205'),
(2620, 'رفس', 'رفس', 'رفس', 'الرفسة: الصدمة بالرجل في الصدر.'),
(2621, 'سفر', 'سفر', 'سفر', 'السفر: قوم مسافرون وسفار، والأسفار جماعة السفر. والسفر: بياض النهار، وأسفرت: أصبحت، وأسفر الصبح، تقول: رح بنا إلى المنزل بسفر أي قبل الليل. ووجه مسفر: منير مشرق سرورا وحسنا. وسفرت الشيء عن الشيء سفرا أي كشطته فانسفر وذهب قال: سفر الشمال الزبرج المزبرجا 206 وانسفرت الإبل: تصرفت فذهبت. والسفير: ما تساقط من الشجر أيام الخريف، سفرت به الريح. ويقال: اعلفوه سفيرا. وسفرت البيت بالمسفرة أي كنسته بالمكنسة سفرا. والسفير: الكناسة. والسفور: سفر المرأة نقابها عن وجهها فهي سافر وهن سوافر، قال توبة: فقد رابني منها الغداة سفورها 207 والسفار: خيط يشد طرفه على خطام البعير فيدار عليه ويجعل بقيته زمامها، وربما كان السفار من حديد، والجمع أسفرة. والسفير: رسول بعض القوم إلى قوم، وهم السفراء. والأسفار أجزاء التوراة، وجزء منه سفر، والتوراة خمسة أسفار أي كتب. سفر يخرج من بني إسرائيل من مصر، وسفر لسيرة الملوك، وسفر الوصية وسفر مكرر. والسفرة: الكتبة، وملائكة السماء والأرض سفرة أي كتبة، وهم الكتبة الذين يحصون أعمال أهل الأرض من قوله سبحانه: بأيدي سفرة 208 . ويقال: سفرت الكتاب أي كتبت أسفره سفرا. والسفسير: الفيج والتابع والخادم. وسفرة الطعام تتخذ للمسافر 209 .'),
(2622, 'فسر', 'فسر', 'فسر', 'الفسر: التفسير وهو بيان وتفصيل للكتاب، وفسره يفسره فسرا، وفسره تفسيرا. والتفسرة: اسم للبول الذي ينظر فيه الأطباء، يستدل به على مرض البدن، وكل شيء يعرف به تفسير الشيء فهو التفسرة.'),
(2623, 'سرب', 'سرب', 'سرب', 'السرب: مال القوم، والجميع السرب، قال: لعل الخيل تعجل سرب تيم 210 وفلان آمن السرب أي لا تغزى نعمه من عزه. وقول الله عز وجل-: وسارب بالنهار 211 أي ساع في أموره نهارا يسرب في حوائجه بالنهار سروبا. ويراد بآمن السرب آمن القلب. والسرب: قطيع من الظباء والجواري والقطا. والسربة: الطائفة من السرب، قال ذو الرمة: سوى ما أصاب الذئب منه وسربة ... أطافت به من أمهات الجوازل 212 يصف بقية ماء في الحوض. وفلان منساح السرب يراد به [شعر] 213 صدره [وبدنه] 214 . والمسرب: الموضع الذي يسرب فيه الظباء والوحش لمراعيها. والماء يسرب أي يجري فهو سرب أي قاطر من خرز السقاء، وسرب سربا. والمسربة: شعرات تنبت في وسط الصدر إلى أصل السرة كقضيب. ومسارب الدواب: مراقها من حوالي بطونها وأرفاغها وآباطها. والسراب: الآل. وسربت سربا وهو المحفور سفلا لا نفاذ له، وإنما انسرب الماء في موضع سرب اي قطع. وسرب قربتك حتى تعيبها أي تتبع عيوبها فتذهبها حتى تكتم الماء. وقوله تعالى: فاتخذ سبيله في البحر سربا 215 ، أي دخولا في الماء.'),
(2624, 'رسب', 'رسب', 'رسب', 'الرسوب: الذهاب في الماء سفلا، والفعل: رسب يرسب. وسيف رسوب: يغيب في الضريبة ماضيا. وبنو راسب: حي من العرب، وبنو راسب 216 : اسم ذي الحيتين وهو الضحاك.'),
(2625, 'بسر', 'بسر', 'بسر', 'البسر الاعجال، وبسر الفحل قلوصا أي ضربها قبل حينها. والباسر: القاهر بسرا أي قهرا. وابتسر الفحل الناقة أي قهرها على نفسها حتى ينزو عليها. والبسور: العبوس، ويبسر فهو باسر من هم أو فكر. والبسر من التمر قبل أن يرطب، والواحدة بسرة، وأبسر النخل صار بسرا بعد ما كان بلحا، وفي الحديث: لا تبسروا أي لا تخلطوا البسر بالتمر للنبيذ، وقد بسره بسرا. والبسرة: ما قد ارتفع من النبات عن وجه الأرض شيئا ولم يطل، وهو غض أطيب ما يكون، وقيل: البسرة البهمى خاصة تخرج في فرعها في وسط الربيع ثم يمسكها البرد فتصمع تلك البسرة ثم تتفقا عن السفى 217 الذي يكون للبسرة، قال ذو الرمة: رعت بأرض البهممى جميما وبسرة 218 والبياسرة: قوم من أهل السند يؤاجرون 219 أنفسهم من أهل السفن لمحاربة عدوهم، وهو رجل بيسري. والبسار: مطر يصيب أهل السند أيام الصيف لا يقلع عنهم ساعة فتلك أيام البسار 220 . والباسور معربة 221 .'),
(2626, 'سبر', 'سبر', 'سبر', 'السبر: التجربة، وسبر 222 ما عنده أي جربه. وسبر الجرح بالمسبار أي نظر ما ما مقداره. والسبار: فتيلة تجعل في الجرح، قال: ترد على السابري السبار 223 والسبر: الأسد. والسبرة: الغداة الباردة، ومنه إسباغ الوضوء في السبرات والسبر: طائر دون الصقر، قال: حتى تعاوره العقبان والسبر 224'),
(2627, 'ربس', 'ربس', 'ربس', 'الربس منه الارتباس، يقال: عنقود مرتبس، [ومعناه انهضام حبه وتداخل بعضه في بعض] 225 . وكبش ربيس وربيز أي مكتنز أعجز. وارتبس الأمر أي اختلط بعضه ببعض. والريباس معرب.'),
(2628, 'برس', 'برس', 'برس', 'البرس: القطن، [وهو قطن البردي] 226 قال: سبائخ من برس وطوط 227'),
(2629, 'رسم', 'رسم', 'رسم', 'الرسم بقية الأثر. وترسمت: نظرت إلى رسوم الدار والروسم: لويح فيه كتاب منقوش يختم به الطعام [والجميع الرواسيم] 228 . وقيل: قرحة بروسم 229 أي بوجه الفرس. وناقة رسوم ترسم رسما أي تؤثر في الأرض من شدة وطئها. والروسم: رسم الدار.'),
(2630, 'سرم', 'سرم', 'سرم', 'السرم: باطن طرف الخوران من الدبر. والسرم: ضرب من زجر الكلاب، تقول: سرما سرما إذا هيجته.'),
(2631, 'مرس', 'مرس', 'مرس', 'المرس: الحبل، ويسمى مرسا لكثرة مرس الأيدي إياه. ومرس الحبل يقع بين الخطاف والبكرة فأنت تعالجه لتخرجه. ورجل مرس: شديد الممارسة ذو جلد وقوة. والمرس كالمرث، ومرثت دواء في الماء ومرسته. وامترسته الألسن في الخصومات: أخذ بعضها بعضا. وفحل مرس ومراس، وهو ذو المراس الشديد، قال: أذى الدواهي وامتراس الألسن 230 وقال: مراس الأواني عن نفوس عزيزة 231 والمرس: السير الدائم. والمرمريس: الصعب العالي من الجبال.'),
(2632, 'رمس', 'رمس', 'رمس', 'الرمس: التراب، ورمس القبر: ما حثي عليه، وقد رمسناه بالتراب 232 . والرمس تراب تحمله الريح فترمس به الآثار أي تعفوها. ورياح روامس. وكل شيء نثر عليه التراب فهو مرموس قال لقيط بن زرارة: يا ليت شعري اليوم دختنوس ... إذا أتاها الخبر المرموس أتحلق القرون أم تميس ... لا بل تميس أنها عروس 233 وهذا رماس هذا أي غطاؤه، يرمس به أي يغطى.'),
(2633, 'مسر', 'مسر', 'مسر', 'المسر فعل الماسر 234 يقال: هو يمسر الناس أي يغريهم، والميسر: كل نعت وفعل يقمر عليه فهو القمار.'),
(2634, 'سمر', 'سمر', 'سمر', 'السمر: شدك شيئا بالمسمار. والسمر: حديث الليل، والفعل المسامرة، وهم سمار، والسامر: الموضع الذي يجتمعون فيه للسمر، وقال: وسامر طال فيه اللهو والغزل 235 ويروى: والسمر. والسمرة: لون إلى سواد [خفي] 236 ، وفتاة سمراء، وحنطة سمراء. والمسمر: مكان يسمر فيه المسمر، وهو أن يحمي مسمارا فيدنيه من العين دون أن تمس العين حرارته، فتصل حرارته إلى العين فتذيبها. والسمر: ضرب من شجر الطلح، الواحدة سمرة. والمثل [لا أفعل ذلك] 237 السمر والقمر، فالسمر هيهنا سواد الليل. وفلان سمير فلان أي يسامره. والسماسرة: جمع السمسار، معربة، وهم الذين يبيعون. ومن قال: سمر عينه أراد سمرها بالمسمار.'),
(2635, 'لسن', 'لسن', 'لسن', 'اللسان: ما ينطق، يذكر ويؤنث، والألسن بيان التأنيث في عدده، والألسنة في التذكير 238 . ولسن فلان فلانا يلسنه أي أخذه بلسانه، وقال طرفة: وإذا تلسنني ألسنها ... انني لست بموهون فقر 239 ورجل لسن: بين اللسن. وشيء ملسن: جعل طرفه كطرف اللسان. ولسن الرجل أي قطع طرف لسانه فهو ملسون. واللسان: الكلام من قوله- عز وجل-: وما أرسلنا من رسول إلا بلسان قومه 240 .'),
(2636, 'نسل', 'نسل', 'نسل', 'النسل: الولد لتناسل بعضه بعد بعض. والنسلان: مشية الذئب إذا أعنق وأسرع، والماشي ينسل أي يسرع نسلانا. وقوله تعالى: إلى ربهم ينسلون 241 ، أي يهرولون ويسرعون. وأما ينسل نسولا فخروج الشيء من الشيء وسقوطه كنسيل شعر الدابة إذا نسل فسقط قطعا قطعا، والقطعة: نسالته. وكذلك نسال الطير وهو ما تحات من أرياشها. ونسل الشيء إذا مضى، قال في اهتزاز الرمح: عسلان الذئب أمسى قاربا ... برد الليل عليه فنسل 242 وقال أبو دواد في نسال الطير: من الطير مختلف لونه ... يحط نسالا ويبقى نسالا 243 وعلى هذا المعنى قول امرىء القيس: فسلي ثيابي من ثيابك تنسل 244'),
(2637, 'سلف', 'سلف', 'سلف', 'أسلفته مالا: أقرضته، والسلف من القرض. والسلف: كل شيء قدمته فهو سلف، والفعل سلف يسلف سلوفا. والقوم إذا أرادوا أن ينفروا فمن تقدم من نفيرهم فسبق فهو سلف لهم، قال: نحن منعنا منبت النصي ... بسلف أرعن عنبري 245 والسلفة: ما يتسلف الرجل فيأكل قبل غدائه. والأمم السالفة الماضية أمام الغابرة، قال: ولاقت مناياها القرون السوالف ... كذلك تلقاها القرون الخوالف 246 أي يموت من بقي كما مات من مضى. والسالفة: أعلى العنق. [وسالفة الفرس وغيرها: هاديته، أي ما تقدم من عنقه] 247 . والسلف: جراب ضخم، والجميع سلوف. وسلافة كل شيء: خلاصته. والسلف 248 : غرلة الصبي. والسلفان: أولاد الحجل واحدها سلف. والسلفة: الطعام يتعلل به قبل الغداء 249 ، وكذلك اللهنة، وقد سلفتهم. والمسلف من النساء: التي بلغت خمسا وأربعين ونحوها. والسلفة: جلد رقيق يجعل بطانة للخفاف أحمر وأصفر والسلوف من نصال السهام: ما طال [وأنشد: شك كلاها بسلوف سندري] 250 وسلفت الأرض بالمسلفة إذا سويتها للزرع، وأرض مسلوفة أي مستوية. والسلفان: رجلان تزوجا بأختين، [وكل واحد منهما سلف لصاحبه] 251 ، والمرأة سلفة لصاحبتها [إذا تزوجت أختان بأخوين] 252 . والسلافة من الخمر أفضلها يتحلب من غير عصر ولا مرث. وهذا سلفي وأنا سلفه.'),
(2638, 'فلس', 'فلس', 'فلس', 'وأفلس الرجل إذا صار ذا فلوس بعد الدراهم [والفلس معروف، وجمعه فلوس] 253 . [وقد فلسه الحاكم تفليسا] 254 . والتفليس في اللون إذا كان على جلده لمع كالفلوس، ودابة مفلس: فيها لمع كالفلوس. والفلس: خاتم من رصاص يختم به عنق من يعطى الجزية.'),
(2639, 'فسل', 'فسل', 'فسل', 'الفسل: الرذل النذل الذي لا مروءة له ولا جلد، وفسل فسالة. والفسيل: صغار النخل، والواحدة بالهاء. وفسالة الحديد: ما تناثر منه عند الضرب إذا طبع.'),
(2640, 'سفل', 'سفل', 'سفل', 'وأسفل وأعلى، وسفل وعلو، وتسفل وتعلى، وسافلة وعالية، وسفلى وعليا، وسفال وعلاء، وسفول وعلو نقائض. وسفلة وعلية وسفلة.'),
(2641, 'سلب', 'سلب', 'سلب', 'كل لباس على الإنسان سلب، وسلب يسلب: أخذ سلبه، [والسلب: ما يسلب به، والجميع الأسلاب] 254 . والسلوب من النوق: التي يؤخذ ولدها، وجمعه سلائب. وقيل: هي الناقة إذا ألقت ولدها لغير تمام وجمعه سلب، وأسلبت: فعلت ذلك ويقال للشاء أسلبت. ويقال: السلب: الطوال، وفرس سلب القوائم وبعير مثله والسليب: الشجرة أخذت أغصانها وورقها. وامرأة مسلب: سلبت على زوجها أو غيره أي محد. وفرس سلب القوائم: خفيف نقلها. ورجل سلب اليدين بالطعن: خفيفهما. وثور سلب القرن بالطعن أي خفيفه. وشجر السلب يكون فيه الليف الأبيض، الواحدة سلبة، هذلية. والسلب: ليف المقل وهو المسد.'),
(2642, 'لسب', 'لسب', 'لسب', 'لسبته الحية تلسبه لسبا. وجوز لسب لصب نقيض الفرك. ولسبت السمن ألسبه لسبا لعقته.'),
(2643, 'بلس', 'بلس', 'بلس', 'المبلس: الكئيب الحزين المتندم. وسمي إبليس لأنه أبلس من الخير أي أويس، وقيل: لعن. والمبلس: البائس. والبلسان: شجر حبه يجعل في الدواء، ولحبه دهن [يتنافس فيه] 255 .'),
(2644, 'لبس', 'لبس', 'لبس', 'اللباس: ما واريت به جسدك، ولباس التقوى: الحياء، ولبس يلبس. واللبس: خلط الأمور بعضها ببعض إذا التبست. واللبوس: الدرع، وكل ما تحصنت به، قال: البس لكل حالة لبوسها 256 وثوب وملاءة لبيس، وجمعه لبس لأنه مفعول 257 . واللبسة: ضرب من الثياب، ولبس لبسا ولبسة واحدة. واللبسة: بقلة.'),
(2645, 'سبل', 'سبل', 'سبل', 'المسبل: اسم خامس سهام القداح. والسبيل: يذكر ويؤنث، وجمعه سبل. والسابلة: المختلفة في الطرقات للحوائج، وجمعه سوابل. وسبيل سابل كقولهم: شعر شاعر. والسبلة: ما على الشفة العليا من الشعر تجمع الشاربين وما بينهما، وامرأة سبلاء: لها هناك شعر. وسبلت المرأة: نبتت سبلتها. والسبل: المطر. والسبولة: سنبلة الذرة والأرز. وأسبل الزرع أي سنبل. والفرس أسبل ذنبه، والمرأة (اسبلت) ذيلها. ورجل مسبال: عادته إسبال ثيابه أي إرساله. وطريق مسبول أي مسلوك. وسبلت مالا في سبيل الله أي وقفته. والسبال جمع السابل. وسبلل بلدة.'),
(2646, 'بسل', 'بسل', 'بسل', 'بسل يبسل بسولا فهو باسل، وهو عبوسة الشجاعة والغضب، وأسد باسل. واستبسل الرجل إذا وطن نفسه عليه واستيقن به. وأبسل نفسه للموت: وطنها عليه واستيقن به. والانسان يبسل بعمله إبسالا أي يخذل ويوكل إليه، ويبسل: يسلم. والبسل: المحرم الذي لا تتأول حرمته، قال: سواد دجوجي وبسل محرم 258 والبسل: الحلال، قال: دمي إن أسيغت هذه، لكم بسل 259 وبسلت الراقي: أعطيته بسلته، وهو ما يعطى على رقيته، وابتسل الراقي: أخذ على رقيته. [وإذا دعا الرجل على صاحبه يقول: قطع الله مطاك، فيقول الآخر: بسلا أي آمين، وانشد: لا خاب من نفعك من رجاكا ... بسلا وعادى الله من عاداكا] 260'),
(2647, 'سلم', 'سلم', 'سلم', 'السلم: دلو مستطيل له عروة واحدة، وجمعه: سلام، قال: سلم ترى الدالح منه أزورا 261 والسلم: لدغ الحية. والملدوغ يقال له: مسلوم، وسليم. وسمي به تطيرا [من اللديغ] ، لأنه يقال: سلمه الله. ورجل سليم، أي: سالم، وقد سلم سلامة. والسلام: الحجارة، لم أسمع واحدها، ولا سمعت أحدا يفردها، وربما أنث على معنى الجماعة، وربما ذكر، وقيل: واحدته: سلمة، قال: زمن الفطحل إذ السلام رطاب 262 والسلام: ضرب من دق الشجر. والسلام يكون بمعنى السلامة. وقول الناس: السلام عليكم، أي: السلامة من الله عليكم. وقيل: هو اسم من أسماء الله، وقيل: السلام هو الله، فإذا قيل: السلام عليكم [فكأنه] يقول: الله فوقكم. والسلامى: عظام الأصابع والأشاجع والأكارع، وهي كعابر كأنها كعاب، والجميع: السلاميات. ويقال [إن] آخر ما يبقى [فيه] المخ.. في السلامى وفي العين. والسلم: ضرب من الشجر، الواحدة بالهاء، وورقه: القرظ، [يدبغ به، ويقال] للمدبوغ بالقرظ: مقروظ، وبقشر السلم: مسلوم. والإسلام: الاستسلام لأمر الله تعالى، وهو الانقياد لطاعته، والقبول لأمره. والاستلام للحجر: تناوله باليد، وبالقبلة، ومسحه بالكف. ويقال: أخذه سلما، أي: أسره. والسلم: ما أسلفت به. وقوله عز اسمه: أم لهم سلم يستمعون فيه 263 . يقال: هي السلم، وهو السلم، أي: السبب والمرقاة، والجميع: السلاليم. والسلم: ضد الحرب، ويقال: السلم والسلم واحد.'),
(2648, 'سمل', 'سمل', 'سمل', 'السمل: الثوب الخلق. والسملة: الخلق من الثياب، فإذا نعت، قيل: ثوب سمل. وأسمل الثوب إسمالا، أي: أخلق. وسمل يسمل سملا. والسمل: فقء العين.. سملت عينه: أدخلت [المسمل] فيها. قال أبو ذؤيب: 264 فالعين بعدهم كأن حداقها ... سملت بشوك فهي عور تدمع والسمل، [وواحدها: سملة] : بقية الماء في الحوض. والسمال: بقايا الماء في فقر الصفا. والسمل: الإصلاح 265 ، [يقال: سمل بينهم سملا: أصلح] 266 . واسمال الظل: قلص. ولز بأصل الحائط. والسموأل: اسم رجل في الجاهلية. أو في أهل زمانه. والسوملة: فنجانة صغيرة.'),
(2649, 'مسل', 'مسل', 'مسل', 'المسلان 267 ، وواحدها مسيل: مسايل ماء ظاهر من الأرض.'),
(2650, 'ملس', 'ملس', 'ملس', 'الملس: النجاء، أي: السرعة. والملس أيضا: سل الخصيتين بعروقها.. خصي مملوس. والملوسة: مصدر الأملس. وأرض ملساء، وسنة ملساء، وسنون أماليس وأمالس. ورمان إملس وإمليسي: وهو أطيبه وأحلاه، ليس له عجم.'),
(2651, 'لسم', 'لسم', 'لسم', 'ألسمته حجته: ألزمته إياها، كما يلسم ولد المنتوجة ضرعها.'),
(2652, 'لمس', 'لمس', 'لمس', 'اللمس: طلب الشيء باليد من هيهنا وهنا ومن ثم. لميس: اسم امرأة. وإكاف ملموس الأحناء، أي: قد أمر عليه اليد 268 ، فإن كان فيه ارتفاع أو أود نحت. والملامسة في البيع: أن تقول: إذا لمست ثوبي أو لمست ثوبك فقد وجب البيع.'),
(2653, 'سنف', 'سنف', 'سنف', 'السناف للبعير بمنزلة اللبب للدابة. بعير مسناف، إذا كان يؤخر الرحل، والجميع: مسانيف. وأسنفته: شددته بسناف. وأسنفوا أمرهم، أي: أحكموه. وصار الإسناف مثلا في رجل قد دهش فلم يدر أين يشد السناف: قد عي فلان بالإسناف، قال عمرو: 269 إذا ما عي بالإسناف حي ... من الأمر المشبه أن يكونا والسنف: ثياب توضع على أكتاف الإبل كالأشلة على مآخيرها. والواحد: سنيف.'),
(2654, 'سفن', 'سفن', 'سفن', 'السفن: جلد [الأطوم، وهي] سمكة في البحر يجعل على قوائم السيوف، وقد يسفن به الخشب أي: يحك حتى يلين، فإذا كان مثله من غير سفن فهو مسفن.. والسفن: الحديدة التي ينحت بها، قال الأعشى: 270 وفي كل عام له غزوة ... تحت الدوابر حت السفن والريح تسفن التراب: تجعله دقاقا، قال 271 : إذا مساحيج الرياح السفن والسفن: جماعة السفينة.'),
(2655, 'نسف', 'نسف', 'نسف', 'النسف: انتساف الريح الشيء كأنه يسلبه. وربما انتسف الطائر الشيء عن وجه الأرض بمخلبه.. وطير شبه الخطاطيف ينتسف الشيء من الهواء سميت: النساسيف، الواحد: نساف، وقيل: إنه الخطاف بعينه، ويسمى خطاف المطر، لأنه يجيء مع المطر وهو أكبر من الخطاف.. والنسفة والنشفة: من حجارة الحرة تكون نخرة فيها نخاريب ينسف بها الوسخ عن الأقدام في الحمام. وكلام نسيف، أي: خفي، هذلية. والمنسف: المنخل، ونسف الطعام به نسفا. ويقال: اعزل النسافة [وكل من الخالص] 272 . واتخذ فلان في جنب بعيره نسيفا إذا تحاص عنه الوبر من أثر قدمه. وانتسف ما في أيديهم، أي: اختطفه. وفرس نسوف السنبك إذا دنا من الأرض في عدوه. ويقال للحمار الذي يشد على الحمار فيكدمه: ترك به نسيفا.'),
(2656, 'نفس', 'نفس', 'نفس', 'النفس، وجمعها النفوس: لها معان. النفس: الروح الذي به حياة الجسد، وكل إنسان نفس حتى آدم عليه السلام، الذكر والأنثى سواء. وكل شيء بعينه نفس. ورجل له نفس، أي: خلق وجلادة وسخاء. والنفس: التنفس، أي: خروج النسيم من الجوف. وشربت الماء بنفس، وثلاثة أنفاس. وكل مستراح منه نفس. وشيء نفيس: متنافس فيه. ونفست به علي نفسا ونفاسة: [ضننت] . ونفس الشيء نفاسة، أي: صار نفيسا. وهذا المكان أنفس من ذاك، أي: أبعد شيئا. والنفاس: ولادة المرأة، فإذا وضعت كانت نفساء حتى تطهر. ونفست فهي منفوسة، وغاية نفاسها: أربعون يوما. والنافس: الخامس من القداح.'),
(2657, 'سنب', 'سنب', 'سنب', 'السنبة: الدهر، قال: إذا سنبة خلفتها بعد سنبة ... تقحمت أخرى فعل من لم يخلد 273'),
(2658, 'نسب', 'نسب', 'نسب', 'النسب في القرابات. فلان نسيبي، وهؤلاء أنسبائي. ورجل نسيب منسوب: ذو حسب ونسب. والنسبة: مصدر الانتساب، والنسبة: الاسم. والنسب في الشعر: ما كان نسيبا. شعر منسوب وجمعه: مناسيب، وهو الشعر في النساء.. وما أحسن نسيبه، أي: ما أحسن قوله في النساء، قال الكميت: إذ أنت أغيد من أشعارك النسب والنيسسب والنيسبان: الطريق المستدق الواضح. كطريق النمل والحية، وطريق حمر الوحش إلى المورد، وهو طريقة واحدة.'),
(2659, 'نبس', 'نبس', 'نبس', '[يقال] : ما نبس فلان بكلمة، أي: ما تكلم، ينبس نبسا.'),
(2660, 'بسن', 'بسن', 'بسن', 'يقال: هو حسن بسن، [وهو] إتباع. والباسنة: جوالق غليظ.'),
(2661, 'بنس', 'بنس', 'بنس', 'بنس، أي: تأخر وتخلف، يبنس فلان.'),
(2662, 'سنم', 'سنم', 'سنم', 'السنم: رأس شجرة من دق الشجر، على رأسها شبه ما يكون على رأس القصب، إلا أنه لين تأكله الإبل أكلا خضما. وأفضل السنم سنمة تسمى الأسنامة، من أعظمها سنمة. وجمل سنم: عظيم السنام، وناقة سنمة، قال 274 : يسفن عطفي سنم همرجل وأسنمت النار: عظم لهبها فارتفع، قال لبيد: 275 [مشمولة غلثت بنابت عرفج ... كدخان] نار ساطع أسنامها سنام: اسم جبل بالبصرة، يقال إنه يسير مع الدجال إذا خرج. وأسنمة الرمل: ظهوره المرتفعة من أثباجها، يقال: أسنمة وأسنمة بالرفع، فمن قال: أسنمة جعلها اسما لرملة بعينها، ومن قال: أسنمة بالكسر جعلها جماعة السنام. وتسنمت الحائط، إذا علوته من عرضه. وسنام الحمى: موضع.'),
(2663, 'سمن', 'سمن', 'سمن', 'السمن: نقيض الهزال. سمن يسمن.. ورجل مسمن: سمين. وأسمن الرجل: اشترى سمينا أو أعطاه أو ملكه. واستسمنته: وجدته سمينا. والسمنة: دواء تسمن به النساء، وامرأة مسمنة: سمينة بالأدوية، [وفي الحديث] 276 : ويل للمسمنات يوم القيامة من فترة في العظام 277 . ومسمنة- خفيفة: سمينة، أسمنتها إسمانا. وسمنت الطعام أسمنه سمنا، إذا عملته بالسمن. والسمن: سلاء اللبن. والسمانى: طائر شبه الفروجة، الواحدة: سماناة، وقيل: إنه السلوى. والسمينة: قوم من أهل الهند لهم دين على حدة، دهريون. والسمان: هذه الأصباغ التي يزخرف بها، قال: فما أحدثت فيه العهود كأنما ... تلعب بالسمان فيه الزخارف أكب عليه كاتب بدواته ... يقيم عليه مرة ويخالف 278 وسمنان: بلدة. والتسمين: أن تقسم شيئا بين الشركاء فيكون في الأنصباء فضل لبعضهما على بعض فيرد كل من في يده فضل على الذي خسر نصيبه، يعطيه ذاك ورقا، فهذا يسمى التسمين، كأنه يسمن بصاحبه حتى يساوي الذي عليه الفضل.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2664, 'نسم', 'نسم', 'نسم', 'النسم: نفس الروح. [يقال] : ما بها ذو نسم، أي: ذو روح. والنسمة في العتق: المملوك ذكرا كان أو أنثى. وكل إنسان نسمة. ونسيم الإنسان: تنفسه. ونسيم الريح: هبوبها، قال امرؤ القيس: 279 [إذا التفتت نحوي تضوع ريحها] ... نسيم الصبا جاءت بريا القرنفل ومنسم البعير: خفة، [ومنسما البعير: كالظفرين في مقدم خفه، بهما يستبان أثر البعير الضال] . ولخف الفيل منسم. والمنسم: الصدر، قال: بها نسم الأرواح من كل منسم 280'),
(2665, 'نمس', 'نمس', 'نمس', 'النمس: فساد السمن، وفساد الغالية. وكل طيب ودهن تغير وفسد فسادا لزجا فقد نمس ينمس نمسا، والنعت: نمس، وقد يقال للشعر إذا توسخ وأصابه دهن: نمس. والنمس: سبع من أخبث السباع. ونمس من الرجال، خبيث منهم. والنمس: دواب سود الواحدة: نمسة. والناموس: قترة الصياد. ولما نزل جبريل على النبي عليهما السلام قيل: جاء الناموس الأكبر الذي كان يأتي موسى عليه السلام. ويقال: هو وعاء لا يوعى فيه إلا العلم. وناموس الرجل: صاحب سره، وقد نمس ينمس نمسا. ونامسته منامسة، أي: ساررته 281 .'),
(2666, 'مسن', 'مسن', 'مسن', 'مسنه بسوط مسنا، أي: ضربه، قال رؤبة: 282 وفي أخاديد السياط المسن وبالشين أيضا.'),
(2667, 'بسم', 'بسم', 'بسم', 'بسم يبسم بسما: فتح شفتيه كالمكاشر. ورجل بسام، وامرأة بسامة، وبسم وابتسم وتبسم بمعنى واحد، [وفي صفة النبي صلى الله عليه وسلم: أن كان جل ضحكة التبسم] 284 .'),
(2668, 'زط', 'زط', 'زط', 'الزط: جيل من السودان، [والزط: أعراب جت بالهندية، وهم جيل من أهل الهند، إليهم تنسب الثياب الزطية] 1 .'),
(2669, 'زر', 'زر', 'زر', 'الزر: الشل، وهو الطرد، قال: يزر الكتائب بالسيف زرا 2 وزره: طعنه. والزر: العض. والزر: جويزة الجيب، وجمعه: أزرار.. وأزررت [القميص] ، أي: اتخذت له أزرارا. وزررته: علقته بالعرى. والزرير: نبات له نور أصفر يصبغ به. والزرزور، وجمعه: زرازير: هنات كالقنابر ملس الرؤوس، تزرزر بأصواتها زرزرة. وعيناه تزران في رأسه [زريرا] ، إذا توقدتا.'),
(2670, 'رز', 'رز', 'رز', 'رززت السكين والسهم في الحائط فارتز، أي: ثبت فيه. وأرزت الجرادة، إذا أدخلت ذنبها في الأرض لتبيض. والرز: الصوت تسمعه من بعيد، قال 3 : فتسمعت رز الأنيس فراعها ... عن ظهر غيب والأنيس سقامها'),
(2671, 'زل', 'زل', 'زل', 'زل السهم عن الدرع زليلا، والإنسان عن الصخرة يزل زليلا. فإذا زلت قدمه قيل: زل زلا وزلولا، وإذا زل في مقال أو نحوه قيل: زل زلة وزللا، قال سليمان بن يزيد العدوي: وإذا رأيت ولا محالة زلة ... فعلى صديقك فضل حلمك فاردد واتخذ فلان زلة للناس، أي: صنيعا. وأزلة الشيطان عن الحق، إذا أضله. [والزليل: مشي خفيف، زل يزل زليلا، قال 4 : وعادية سوم الجراد وزعتها ... فكلفتها سيدا أزل مصدرا لم يعن بالأزل الأرسح، ولا هو من صفة الفرس ولكنه أراد: يزل زليلا خفيفا] 5 . والمزلة: المكان الدحض. والمزلة: الزلل في الدحض. والزلة، عراقية: اسم لما يحمل من المائدة لقريب أو صديق، وإنما اشتق ذلك من الصنيع إلى الناس. والإزلال: الإنعام، من أزللت إليه نعمة، أي: أسديت، واصطنعت عنده. والأزل: الأرسح، وقد زل زللا، فهو أزل، [وهي زلاء] . والأزل: الصغير المؤخر، الضخم المقدم. والسمع الأزل: سبع بين الذئب والضبع. والزلزلة: تحريك الشيء [والزلزال أيضا] . والزلزال 6 : كلمة مشتقة، جعلت اسما للزلزلة. والزلازل: البلايا.'),
(2672, 'لز', 'لز', 'لز', 'اللز: لزوم الشيء بالشيء. ولزاز الباب: نجافها، وهي خشبة يلز بها الباب. ورجل ملز في خصوماته وأموره. وإنه للزاز خصم، أي: شديد الخصومة، قال 7 : لزاز خصم معك ممرن ورجل ملزز الخلق، أي: مجتمع [الخلق] . ولزه، أي: طعنه.'),
(2673, 'زن', 'زن', 'زن', 'أبو زنة: كنية [القرد] 8 . والإزنان: الأبن، وهو مصدر المأبون.. أزنة بخير، أي: أبنه. وفلان يزن بخير أو بشر. ولا يقال: يؤبن إلا بشر، قال 9 : لا يزنون في العشيرة بالسوء ... ولا يفسدون ما صلحا'),
(2674, 'نز', 'نز', 'نز', 'النز: ما تحلب من الأرض من الماء. وأنزت الأرض، أي: صارت ذات نز، ونزت: تحلب منها النز وصارت هذه الأرض منابع النز ومواقع الوز. وظليم نز: لا يكاد يستقر في مكان. والمنز: مهد الصبي. وغلام نز، أي: خفيف، وغلمان نزون، أي: خفاف.'),
(2675, 'زف', 'زف', 'زف', 'زفت العروس إلى زوجها زفا.. وتزف الريح زفيفا، أي: تهب هبوبا ليس بالشديد وهو ماض في ذاك. وزف الطائر زفيفا ترامى بنفسه، قال: زفيف الزبانى بالعجاج القواصف 10 والزفزفة: تحريك الريح يبس الحشيش وصوتها، قال 11 : زفزفة الريح الحصاد اليبسا والزفزاف: النعام الذي يزفزف في طيرانه، يحرك جناحيه إذا عدا وجاء فلان يزف زفيف النعامة، أي: من سرعته. والزف: صغار ريش النعام والطائر. والمزفة: المحفة التي تزف فيها العروس. والقوم يزفون في مشيهم، أي: يسرعون في سكون.'),
(2676, 'فز', 'فز', 'فز', 'الفز: ولد البقرة، قال 12 : كما استغاث بسيء فز غيطلة ... [خاف العيون ولم ينظر به الحشك] أفزه يفزه: أفزعه.. واستفزه: أخرجه من داره.. واستفزوه: ختلوه حتى ألقوه في مهلكة 13 .'),
(2677, 'زب', 'زب', 'زب', 'الزب: ملؤك القربة إلى رأسها، [تقول: زببتها فازدبت. والزباب، خفيفة: ضرب من عظيم الجرذان. والزبيب: معروف، والزبيبة الواحدة. وفعل الزبيب: التزبيب. والزبيبة: قرحة تخرج في اليد [تسمى: العرفة] 14 . والزبب: مصدر الأزب، وهو كثرة شعر الذراعين والحاجبين والعين، والجميع: الزب. وبعير أزب: كثير الوبر. والزب: اللحية بلغة اليمن، قال: ففاضت دموع الجحمتين بعبرة ... على الزب حتى الزب في الماء غامس 15 وزب الصبي: معروف، [وهو ذكره بلغة أهل اليمن] 16 . والتزبب في الكلام: التزيد. وأبو زبان 17 : كنية.'),
(2678, 'بز', 'بز', 'بز', 'البز: ضرب من الثياب. والبزازة: حرفة البزاز. والبز [أيضا] : ضرب من المتاع. والبز: السلب، [يقال] : غزوته فبززته. ويقال: من عز بز، أي: من غلب سلب. والابتزاز: التجرد من الثياب. وابتزت من ثيابها، أي: جردت. والبزة: الشارة الحسنة من الثياب، قال 18 : كنت إذا أتوته من غيبي ... يشم عطفي ويبز ثوبي والبزابز: الشديد من الرجال.'),
(2679, 'زم', 'زم', 'زم', 'زم: فعل من الزمام، [تقول] : زممت الناقة أزمها زما. والزمام: الخيط الذي في أنفها، والجميع: الأزمة. والعصفور يزم بصوت له ضعيف، والعظام من الزنابير يفعلن ذلك. والذئب يذهب بالسخلة زاما، أي: رافعا رأسه، وقد ازدم سخلة فذهب بها. والزمزمة، تكلف العلوج الكلام عند الأكل والشرب من غير استعمال اللسان والشفة، ولكنه صوت تديره في خياشيمها وحلوقها. والزمزمة: الجماعة من الناس. وزمزم: بئر في مسجد مكة عند البيت. والرعد يزمزم ثم يهدهد، قال 19 : هدا كهد الرعد ذي الزمازم'),
(2680, 'مز', 'مز', 'مز', 'المز: اسم الشيء المزيز. مز يمز مزازة، وهو الذي يقع موقعا في بلاغته وكثرته وجودته. والمز من الرمان: ما كان طعمه بين حموضة وحلاوة. والمزة: الخمر اللذيذة الطعم. وهي: المزاء، جعل ذلك اسما لها، ولو كان نعتا لقلت: مزى، قال 20 : [لا تحسبن الحرب نوم الضحى] ... وشربك المزاء بالبارد والتمزز: شرب المزاء وأكل الرمان [المز] .. والتمزز: المص. تمززته: تمصصته قليلا قليلا، والمزة: المصة، قال أبو دواد: تمززتها ومعي فتية ... يميتون مالا ويحيون مالا'),
(2681, 'طزر', 'طزر', 'طزر', 'الطزر: بيت إلى الطول. [والطزر: هو النبت الصيفي] 21 فارسية معربة.'),
(2682, 'طرز', 'طرز', 'طرز', 'الطراز: الثوب الحسن المعلم، ومنه: رجل طراز مطرز، لتعليمه الثياب، ويقال للرجل القديم: إنه لمن الطراز الأول.. والطراز: العلم نفسه. [والطراز: الموضع الذي تنسج فيه الثياب الجياد] 22 .'),
(2683, 'زرد', 'زرد', 'زرد', 'الزرد: حلق يتخذ منها المغفر، ومنه الزراد [وهو صانعه] . والزرد: الابتلاع. ازدرد الطعام. والزرد الخنق.'),
(2684, 'درز', 'درز', 'درز', 'الدرز: درز الثوب ونحوه، وهو معرب، وجمعه: الدروز.'),
(2685, 'زند', 'زند', 'زند', 'الزند والزندة: خشبتان يستقدح بهما، العليا: زند، والسفلى: زندة. والزندان: عظمان في الساعد، [أحدهما أرق من الآخر] 23 فطرف الزند الذي يلي الإبهام هو الكوع، وطرف الزند الذي يلي الخنصر هو: الكرسوع، والرسغ: مجتمع الزندين، ومن عندهما تقطع يد السارق. والمزند: اللئيم.'),
(2686, 'زبد', 'زبد', 'زبد', 'الزبد: زبد السمن قبل أن يسلأ، والقطعة منه: زبدة. والزبد: لعاب ابيض على مشفر الجمل، وأكثر ما يكون في الاغتلام. والبحر واللبن زبد، وهو ما يرتفع فوقه إذا حلبت. أزبد اللبن والبحر. وتزبد الإنسان: خرج على شدقيه زبد من الغضب. والزبد: الرفد.. زبدته [أزبده] زبدا: رفدته ووهبت له، قال زهير: 24 أصحاب زبد وأيام لهم سلفت ... [من حاربوا أعذبوا عنهم بتنكيل]'),
(2687, 'ترز', 'ترز', 'ترز', 'ترز الرجل، إذا مات ويبس بلا روح، [والتارز: اليابس بلا روح] 25 ، قال 26 : [قليل التلاد غير قوس وأسهم] ... كأن الذي يرمي من الوحش تارز وقال أبو ذؤيب: 27 : فكبا كما يكبو فنيق تارز ... بالخبت إلا أنه هو أبرع'),
(2688, 'زتن', 'زتن', 'زتن', 'الزيتون من الشجر والجبل: معروف، والنون فيه زائدة.'),
(2689, 'زفت', 'زفت', 'زفت', 'الزفت: القير، ويقال لبعض أوعية الخمر: المزفت، ونهي أن ينبذ فيه.'),
(2690, 'زمت', 'زمت', 'زمت', 'الزميت: الساكن، والمزمت: الساكت، وفيه زماته، [والزميت أيضا] ، قال: والقبر صهر ضامن زميت 28'),
(2691, 'زنر', 'زنر', 'زنر', 'الزنار: ما يتزنر به أهل الذمة، والزنارة أيضا. والزنانير: الحجارة، الواحدة: زنيرة وزنارة.'),
(2692, 'رزن', 'رزن', 'رزن', 'شيء رزين. رزن رزانة، وأنا أرزنه رزنا، ثقلته بيدي لأعرف ثقله. وامرأة رزان: ذات وقار وعفاف، ورجل رزين: وقور. والأرزن: شجر يتخذ منه العصي.'),
(2693, 'نزر', 'نزر', 'نزر', 'نزر الشيء ينزر نزارة ونزرا فهو نزر. وعطاء منزور: قليل، وامرأة نزور: قليلة الولد، قال 29 : بغاث الطير أكثرها فراخا ... وأم الصقر مقلاة نزور وقد يقال للقليل الكلام: نزور. والتنزر: التقلل. ونزره: ألح عليه، وفي الحديث: لا تنزروا العلماء ، أي: لا تلحوا عليهم.'),
(2694, 'رنز', 'رنز', 'رنز', 'الرنز: لغة في الأرز.'),
(2695, 'زرف', 'زرف', 'زرف', 'ناقة زروف: طويلة الرجلين، واسعة الخطو. والزرافة: دابة له خلق حسن عند الله مستشنع عند الناس، شبه البعير. وأزرف القوم: أعجلوا في هزيمة وخوف وبحثوه. والزرافات. المواكب، وكل جماعة زرافة وقال الحجاج: إياي وهذه الزرافات 30 .'),
(2696, 'زفر', 'زفر', 'زفر', 'الزفر: الزفير، والفعل: يزفر، وهو أن يملأ صدره غما ثم يزفر به، والشهيق مد النفس، ثم يزفر، أي: يرمي به ويخرجه من صدره. والمزفور [من الدواب] : الشديد تلاحم المفاصل، تقول: ما أشد زفرة هذا البعير، اي: هو مزفور الخلق. والزفر: السيد. وزفر: اسم رجل مدحه القطامي. والزفر: القربة، والزافر: الذي يعين على حمل القربة، قال 31 : [رئاب الصدوع غياث المضوع] ... لأمتك الزفر النوفل والزوافر: الإماء. والزافرة: العشيرة، [يقال] : جاء فلان في زافرته. وزافرة الرمح والسهم: نحو الثلث منه.'),
(2697, 'فزر', 'فزر', 'فزر', 'الفزور: الشقوق والصدوع، وتفزر الحائط والثوب ونحوه [إذا تشقق] 32 . والفزر: ابن الببر، والفزارة: أمه، والفزرة: أخته، والهدبس: أخوه، قال: ولقد رأيت فزارة وهدبسا ... والفزر يتبع فزره كالضيون 33 والفازر: طريق يأخذ في رملة ودكادك لينة كأنها صدع في الأرض منقاد طويل.. وكل شيء قطع شيئا فقد فزره. وفزارة [أبو حي من غطفان، وهو فزارة] بن ذبيان. والفزر: لقب لسعد بن زيد مناة.'),
(2698, 'فرز', 'فرز', 'فرز', 'فرز له نصيبه من الدار، أي: عزل، وقد فرزت فهي مفروزة وأفرزته فهو مفرز. وفرزان: اسم أعجمي من الشطرنج.'),
(2699, 'زرب', 'زرب', 'زرب', 'الزرب والزريبة: موضع الغنم. والزربة: قترة الرامي. والزرابي، وواحدتها: زربية: من القطوع الحيرية وما كان على صنعتها.'),
(2700, 'زبر', 'زبر', 'زبر', 'الزبر: طي البئر، تقول: زبرتها، أي: طويتها. والزبور: الكتاب. والزبور: اسم الكتاب الذي أنزل على داود. والزبرة من الكاهل: الهنة الناتئة من الأسد، وهو شعر مجتمع على موضع الكاهل منه، وكل شعر مجتمع كذلك فهو زبرة. والزبرة: قطعة من الحديد ضخمة. والأزبر: الضخم زبرة الكاهل، والأنثى: زبراء. وكان للأحنف خادم تسمى زبراء، فكانت إذا غضبت قال الأحنف: هاجت زبراء، فذهبت مثلا حتى قيل لكل من غضب: هاجت زبراؤه. وزبر فلان فلانا يزبره زبرا وزبرة: انتهره. وكبش زبير، أي: ضخم مكتنز.. وكيس زبير: أعجر مملوء. وزئبر الثوب: ما يرتفع من قطنه، وزئبر القطيفة: ما تعلق منها. والجميع: الزآبر. والزبر: الشديد، قال الفقعسي 34 : أكون ثم أسدا زبرا'),
(2701, 'رزب', 'رزب', 'رزب', 'المرزاب: الميزاب، والجميع: مرازيب وميازيب. والمرزبة: شبه عصية من حديد، وكذلك: الإرزبة، ويخففون الباء، إذا قالوا بالميم.'),
(2702, 'بزر', 'بزر', 'بزر', 'البزر: كل حب ينثر على الأرض للنبات، [وتقول] : بزرته وبذرته والبزر: الهيج بالضرب. والمبزر: مثل خشبة القصارين. والبيزر أيضا: خشب يبزر به الثياب في الماء. وبزر الكتان: حبه. وبزور النبات: حبوبه الصغار.'),
(2703, 'برز', 'برز', 'برز', 'رجل برز، أي: طاهر الخلق عفيف. وامرأة برزة: موثوق برأيها، وفضلها، وعفافها. والفعل: برز يبرز برازة. قال العجاج 35 في الرجل البرز: برز وذو العفافة البرزي والبراز: المكان الفضاء من الأرض، البعيد الواسع. وتبرز فلان: خرج إلى البراز. وقيل تبرز في التغوط، كناية عنه. أي: خرج إلى براز من الأرض. وبرز [فلان] يبرز بالتخفيف، أي: ظهر بعد الخفاء. وإذا تسابقت الخيل قيل لسابقها: قد برز عليها. وأبرزت الكتاب والشيء، أي: أظهرته. وكتاب مبروز، مبرز أي: منشور، قال 36 : أو مذهب جدد على ألواحه ... الناطق المبروز والمختوم والبراز: المبارزة من القرنين في الحرب، وتبارزا تبارزا، وبارز القرن مبارزة وبرازا.'),
(2704, 'زرم', 'زرم', 'زرم', 'الزرم من السنانير والكلاب: ما يبقى جعره في دبره، والفعل: زرم، والسنور يسمى: أزرم. والإزرام: القطع. وأزرم بوله: قطعه. وزرم البول نفسه: انقطع فهو زرم، قال 37 : [أو كماء المثمود بعد جمام] ... زرم الدمع لا يؤوب نزورا وزرم عطاؤه، أي: قل.'),
(2705, 'زمر', 'زمر', 'زمر', 'الزمر بالمزمار، والجميع: المزامير.. زمر الزامر، يزمر زمرا. والزمار: صوت النعام. زمرت النعامة تزمر زمارا. والزمرة: فوج من الناس، ويقال: جماعة في تفرقة، بعض على أثر بعض. والزمارة: الزانية. وفي الحديث: نهى عن كسب الزمارة 38 .'),
(2706, 'رزم', 'رزم', 'رزم', 'الإرزام: صوت الرعد. ورزمت الناقة ترزم رزوما، أي: قامت من إعياء أو هزال فهي رازمة، والجميع: رزمى.. ويقال: أرزمت الناقة إرزاما، وهو صوت تخرجه من حلقها، لا تفتح به فاها. والرزمة من الثياب: ما شد في ثوب واحد، [يقال] : رزمت الثياب ترزيما.'),
(2707, 'رمز', 'رمز', 'رمز', 'الرمازة: من أسماء الدبر، والفعل: رمز يرمز، أي: ينضم. والرمز باللسان: الصوت الخفي. ويكون [الرمز] : الإيماء بالحاجب بلا كلام، ومثله الهمس. ويقال للرجل الوقيد: ارتمز. وقد يقال للجارية الغمازة الهمازة بعينها، واللمازة بفمها: رمازة، ترمز بفمها، وتغمز بعينها. ويقال: الرمز: تحريك الشفتين.'),
(2708, 'مزر', 'مزر', 'مزر', 'المزر: نبيذ الشعير والحبوب، ويقال: نبيذ الذرة خاصة. والمزارة: مصدر المزير، وهو القوي النافذ في الأمور. والمزر: الذوق، والشرب القليل، ويقال: الشرب بمرة. قال 39 : تكون بعد الحسو والتمزر ... في فمه مثل عصير السكر'),
(2709, 'مرز', 'مرز', 'مرز', 'المرز: دون القرص، تقول: مرزه مرزا. وقام عمر ليصلي على جنازة فمرز حذيفة يده، كأنه أراد أن يكفه عن الصلاة عليها، لأن الميت كان من المنافقين، فأمسك عنه عمر، وكان عمر بعد ذلك لا يصلي على جنازة إذا لم يتابعه حذيفة، لأن النبي صلى الله عليه وآله وسلم ذكرهم لحذيفة.'),
(2710, 'لزن', 'لزن', 'لزن', 'اللزن: اجتماع القوم على البئر للاستقاء حتى ضافت بهم وعجزت عنهم، وكذلك في كل أمر وشدة وازدحام.. والماء ملزون، ولزن القوم يلزنون [ويلزنون] لزنا ولزنا.'),
(2711, 'نزل', 'نزل', 'نزل', 'النازلة: الشديدة من شدائد الدهر تنزل بالقوم وجمعها: النوازل. ونزل فلان عن الدابة، أو من علو إلى سفل، والنزلة: المرة الواحدة. قال [تعالى] : ولقد رآه نزلة أخرى 40 . أي: مرة أخرى. والنزل: ما يهيأ للقوم والضيف إذا نزلوا. والنزل: ريع ما يزرع. والنزال: المنازلة في الحرب، أن ينزلا معا فيقتتلا. ويقال: نزال نزال، بالكسر، أي: انزلوا للحرب.'),
(2712, 'زلف', 'زلف', 'زلف', 'المزلفة: قرية تكون بين البر وبلاد الريف، والجميع: مزالف. والزلف المصانع، واحدتها: زلفة، قال لبيد: 41 حتى تحيرت الدبار كأنها ... زلف وألقي قتبها المحزوم والزلف: جمع الزلفة، وهي الزلفى وهي: القربة.. وزلفة من الليل: طائفة من أوله. والزلفة: الصحفة، وجمعها: زلف. وأزلفته: قربته. وازدلف: اقترب، وسميت المزدلفة، لاقتراب الناس إلى منى بعد الإفاضة من عرفات.'),
(2713, 'زفل', 'زفل', 'زفل', 'الأزفلة: الجماعة من الناس.'),
(2714, 'فلز', 'فلز', 'فلز', 'الفلز [والفلز] : نحاس أبيض يجعل منه قدور عظام مفرغة. وقيل: الفلز: الحجارة. ورجل فلز: غليظ شديد.'),
(2715, 'زبل', 'زبل', 'زبل', 'الزبل: السرقين 42 وما أشبهه، والمزبلة: ملقاه. والزبيل: الجراب، والزنبيل أيضا. وجمعه: زنابيل، وهو عند العامة ما يتخذ من الخوص بعروتين. [وجمع الزبيل: زبل وزبلان] 43 .'),
(2716, 'لزب', 'لزب', 'لزب', 'اللزب: الأزبة. والأزب: الشدة والصلابة. ولزب لزوبا، أي: لزق، والطين اللازب منه، قال النابغة: 44 [ولا يحسبون الخير لا شر بعده] ... ولا يحسبون الشر ضربة لازب واللزوب أيضا: الضيق والقحط.'),
(2717, 'لبز', 'لبز', 'لبز', 'اللبز: الأكل الجيد، يقال: لبز يلبز لبزا فهو لابز. واللبز: ضرب الناقة بجمع خفها ضربا لطيفا في تحامل، قال 45 : خبطا بأخفاف ثقال اللبز'),
(2718, 'بزل', 'بزل', 'بزل', 'ناقة بازل، وبعير بازل [الذكر والأنثى فيه] سواء، لأن هذا شيء ليس لها فيه فعل إنما هو بزل نابه يبزل بزولا، أي: فطر وانشق، والجميع: بزل وبزل في الذكور، وفي الإناث: بزل وبوازل وبزل يشتركان فيه ... وبزل نابه ونابه بازل. والبزل: تصفية الشراب ونحوه، والمبزل: الذي يصفى به، ويكون في موضع من الوعاء، شبه طبي فيه خرق، فذلك نفسه المبزل، وبزل الخمر وابتزلها وتبزلها: ثقب إناءها، قال: تحدر من نواطب ذي ابتزال 46 والناطبة: شيء يتخذ فيه خروق كثيرة يصفى به.'),
(2719, 'زلم', 'زلم', 'زلم', 'الزلم، والزلم، وجمعه: أزلام، وهي القداح التي لا ريش لها، كانت العرب تستقسم بها عند الأمور إذا هم بها أحدهم، مكتوب عليها: افعل.. لا تفعل، قال 47 : فرمى فأخطأه وجال كأنه ... زلم على'),
(2720, 'زفن', 'زفن', 'زفن', 'الزفن، الرقص. والزفن، بلغة عمان: ظلة يتخذونها فوق سطوحهم تقيهم ومد البحر، أي: حره ونداه.'),
(2721, 'نزف', 'نزف', 'نزف', 'نزف دم [فلان] فهو نزيف منزوف، أي: انقطع عنه، قال الله عز وجل: ولا هم عنها ينزفون 55 ، أي: لا تنزف الخمر عقولهم. والسكران نزيف، أي: منزوف عقله. والنزف: نزح الماء من البئر أو النهر شيئا بعد شيء. والفعل: ينزف، والقليل منه: نزفة. وأنزف القوم: نزف ماء بئرهم. والنزف: الدمع. ويقال للرجل الذي عطش حتى يبست عروقه وجف لسانه: نزيف، قال: شرب النزيف ببرد ماء الحشرج 56 والحشرج: كوز، ويقال: بل حفيرة تحفر للماء. [وقالت بنت الجلندى ملك عمان حين ألبست السلحفاة حليها ودخلت البحر فصاحت وهي تقول: نزاف نزاف، ولم يبق في البحر غير قذاف.. أرادت: انزفن الماء فلم يبق غير غرفة] 57 .'),
(2722, 'نفز', 'نفز', 'نفز', 'نفز الظبي ينفز نفزا، إذا وثب في عدوه. والتنفيز: أن تضع سهما على ظفرك، ثم تنفزه بيدك الأخرى، فتديره حتى يدور فيستبين لك اعوجاجه أو استقامته.. والمرأة تنفز ابنها كأنما ترقصه. والنفيزة: زبدة تتفرق في المخض، فلا تجتمع.'),
(2723, 'زبن', 'زبن', 'زبن', 'المزابنة: بيع التمر في رأس النخل بالتمر. والزبن: دفع الشيء عن الشيء، كالناقة تزبن ولدها عن ضرعها برجلها. والحرب تزبن الناس إذا صدمتهم، وحرب زبون. وزبنه: منعه، قال: إذا زبنته الحرب لم يترمرم 58 وزبينة: اسم حي من العرب. والزبانية: ملائكة موكلون بتعذيب أهل النار.'),
(2724, 'نزب', 'نزب', 'نزب', 'نزب تيس الظباء عند السفاد ينزب نزبا ونزيبا، وهو صوته.'),
(2725, 'نبز', 'نبز', 'نبز', 'النبز: مصدر النبز، وهو اسم كاللقب، والتنبيز: التسمية. والأسماء على وجهين: أسماء نبز كزيد وعمرو. وأسماء عام مثل فرس ودار ورجل ونحو ذلك.'),
(2726, 'زنم', 'زنم', 'زنم', 'زنمتا العنز من الأذن، وزنمتا الفوق من السهم، والزنمة: اللحمة المتدلية في الحلق، تسمى ملازة. والزنمة والزنمة شيء واحد. والزنمة: سمة تحز ثم تترك. والزنيم: الدعي، ومنه قوله [تعالى] : عتل بعد ذلك زنيم 59 . والمزنم: المستعبد، قال 60 : [فإن نصابي إن سألت ومنصبي ... من الناس] قوم يقتنون المزنما والمزنم: صغار الإبل، وكل مستلحق 61 فهو مزنم.'),
(2727, 'زمن', 'زمن', 'زمن', 'الزمن: من الزمان. والزمن: ذو الزمانة، والفعل: زمن يزمن زمنا وزمانة، والجميع: الزمنى في الذكر والأنثى. وأزمن الشيء: طال عليه الزمان.'),
(2728, 'نزم', 'نزم', 'نزم', 'النزم: شدة العض، والمنزم: السن بلغة أهل اليمن كلهم، قال 62 : ولا أظنك إن عضتك نازمة ... من النوازم الا سوف تدعوني'),
(2729, 'مزن', 'مزن', 'مزن', 'مزن [فلان] يمزن مزونا، إذا مضى لوجهه. والمزن: السحاب، والقطعة: مزنة. والمازن: بيض النمل. ومازن: حي من تميم. [ومزينة: قبيلة من مضر، وهو] : مزينة بن أد بن طابخة.'),
(2730, 'بزم', 'بزم', 'بزم', 'الإبزيم: ما على طرف المنطقة، ذو لسان يدخل في الطرف الآخر. ولغة فيه: إبزام. والبزيم: حزمة من بقل، وكذلك: الوزيم.'),
(2731, 'طث', 'طث', 'طث', 'الطث: لعبة للصبيان، يرمون بخشبة مستديرة تسمى المطثة.'),
(2732, 'ثط', 'ثط', 'ثط', 'الثطط: مصدر الأثط والثط أصوب، [فمن قال: رجل أثط] قال: ثط يثط ثططا، ومن قال: رجل ثط ثطاطة وثطوطة، ويثط ويثط لغتان. وقوم ثط. والثطاء: التي لا إسب لها. والثطاء: دويبة.'),
(2733, 'طر', 'طر', 'طر', 'الطر: كالشل، يطرهم بالسيف طرا. وسنان مطرور وطرير: محدد. ورجل طرير: ذو طرة وهيئة حسنة. وفتى طار: طر شاربه. وطرة الثوب: شبه علمين، يخاطان بجانبي البرد على حاشيته. وطرة الجارية: أن يقطع لها في مقدم ناصيتها كالطرة تحت التاج. والطرار، وواحدها طرة: تتخذ من رامك تلزق بالجنبين، والطرور: اسم منه.'),
(2734, 'طل', 'طل', 'طل', 'الطل: المطر الضعيف القطر الدائم، وهو أرسخ المطر ندى. [تقول] : طلت الأرض. وتقول: رحبت الأرض وطلت. ومن قال: طلت ذهب إلى معنى: طلت عليك السماء، ورحبت عليك الأرض، أي: أتسعت. والطل: المطل للديات وإبطالها. والإطلال: الإشراف على الشيء. وطلل السفينة: جلالها، والجميع: الأطلال. وطلل الدار: يقال: [إنه] موضع في صحنها يهيأ لمجلس أهلها، قال أبو الدقيش: كأن يكون بفناء كل حي دكان عليه المأكل والمشرب، فذلك الطلل، قال جميل: 1 رسم دار وقفت في طلله ... كدت أقضي الغداة من جلله'),
(2735, 'لط', 'لط', 'لط', 'اللط: إلزاق الشيء، والناقة تلط بذنبها، أي: تلزقه بفرجها وتدخله بين فخذيها. واللط: [الستر والإخفاء] كما [يقال] : لط فلان الحق بالباطل. والملطاط: حرف من الجبل في أعلاه. وملطاط البعير: حرف في وسط رأسه. والإلطاط: الإلحاح.. ألط عليه: ألح. واللطلط: الغليظ من الأسنان، قال جرير: تفتر عن قرد المنابت لطلط ... مثل العجان وضرسها كالحافر واللطلط واللطاء: [العجوز] الدرداء التي سقطت أسنانها [وتأكلت] وبقيت أصولها، وهي: الجعماء واللطعاء [أيضا] .'),
(2736, 'طن', 'طن', 'طن', 'الطن: ضرب من التمر. والطن: الحزمة من القصب والحطب. والطنين: صوت الأذن والطست، ونحوه. وطن الذباب، إذا طار فسمعت لطيرانه صوتا، قال 2 : كذباب طار في الجو فطن والطنطنة في الصوت: الكلام الكثير. والإطنان: سرعة القطع، [يقال] : ضربته بالسيف فأطننت ذراعه، وقد طنت ذراعه يحكي بذلك صوتها حين قطعت.'),
(2737, 'طف', 'طف', 'طف', 'الطف: طف الفرات، وهو الشاطىء. والطفاف: ما فوق المكيال. والتطفيف: أن يؤخذ أعلاه فلا يتم كيله، فهو طفان، والتجميم والتطفيف واحد، وإناء طفان. وأطف فلان لفلان، أي: طبن له وأراد ختله. واستطف لنا شيء، أي: بدا لنا حده. والطفيف: الشيء الخسيس الدون. والطفطفة: معروفة [وجمعها: طفاطف] 3 . وبعض العرب يسمي كل لحم مضطرب طفطفة، قال: وتارة ينتهس الطفاطفا 4 وقال ابو ذؤيب: 5 قليل لحمها إلا بقايا ... طفاطف لحم ممحوص مشيق ويروى: منحوص.'),
(2738, 'طب', 'طب', 'طب', 'الطب: السحر، والمطبوب: المسحور. والطب: من تطبب الطبيب. والطب: العالم بالأمور. [يقال] : هو به طب، أي: عالم. وبعير طب، أي: يتعاهد مواضع خفه أين يضعه. والطبة: شقة مستطيلة من الثوب. والطبب: طرائق شعاع الشمس إذا طلعت. والطبطبة: شيء عريض يضرب بعضه ببعض. والطبطابة: خشبة عريضة يلعب الفارس بها بالكرة. والمتطبب: الطبيب، وقوله 6 : إن يكن طبك الفراق [فإن البين ... أن تعطفي صدور الجمال] أي: طويتك وشهوتك. والطبابة من الخرز: السير بين الخرزتين. والطبابة: الكردة من الأرض. والطبابة: القطعة من السحاب، والجميع: طبب.'),
(2739, 'بط', 'بط', 'بط', 'بط الجرح بطا، والمبط: المبضع. والبطة: الدبة بلغة مكة. والبط: معروف، الواحدة: بطة. [يقال] : بطة أنثى، وبطة ذكر.. والبطبطة: صوت البط. والبطيط: العجيب من الأمر، قال: ألم تتعجبي وتري بطيطأ 7'),
(2740, 'طم', 'طم', 'طم', 'الطم: طم الشيء بالتراب، قال ذو الرمة: 8 كأن [أجلاد] حاذيها وقد لحقت ... أحشاؤها من هيام الرمل مطموم وطم على طمك، أي: جاء بأكثر مما في يدك. وطم إناءه، أي: ملأه، ويقال: جاءوا بالطم والرم، في مثل، أي: بأمر عظيم 9 . والرجل يطم في سيره طميما، أي: يمضي ويخف. والطامة: التي تطم على ما سواها، أي: تزيد وتغلب. وطم البحر: غلب سائر البحور. وبحر طمطام، وطم البحر إذا زاد على مجراه أيضا، والطم: البحر. والطمطم، والطمطمي، والطمطماني: هو الأعجم الذي لا يفصح.'),
(2741, 'مط', 'مط', 'مط', 'المط: سعة الخطو، وقد مط يمط.. وتكلم فمط حاجبيه، أي: مدهما. ومط كلامه، أي: مده وطوله. والمطيطاء والمطواء: التمطي. والمطائط: مواضع حفر قوائم الدواب في الأرض، تجتمع فيها الرداغ، قال: فلم يبق إلا نطفة في مطيطة ... من الأرض فاستصفينها بالجحافل 10'),
(2742, 'طرد', 'طرد', 'طرد', 'طردته أطرده طردا، أي: نحيته. والطرد: مطاردة الصيد، أي: علاج أخذه. والطريدة: صيد أقبلت عليه الكلاب والقوم يطردونه ليأخذوه. والطريدة: قصبة يوضع فيها سكين يبرى بها القداح. والمطاردة: مطاردة الفرسان وطرادهم، وهو حملة بعضهم على بعض في الحرب وغيرها. والمطرد: رمح قصير يطعن به حمر الوحش. والريح تطرد الحصى والجولان على وجه الأرض، وهو عصفها وذهابها بها. والأرض ذات الآل تطرد السراب طردا. وتقول: طردت فلانا فذهب، ولا يقال: فاطرد في مطاوعة الفعل. واطرد الماء: [جرى] . وجدول مطرد: [سريع الجرية، وأمر مطرد] 11 : مستقيم على جهته. وأطردت فلانا: تركته طريدا شريدا.'),
(2743, 'طثر', 'طثر', 'طثر', 'لبن خاثر طاثر، أي: عكر. وطثر اللبن: زبد. ورجل طيثارة 13 : لا يبالي على من أقدم. وأسد طيثارة: لا يبالي على ما أغار.'),
(2744, 'طرث', 'طرث', 'طرث', 'الطرثوث: نبات كالفطر مستطيل دقيق يضرب إلى الحمرة، وهو دباغ للمعدة، منه مر، ومنه حلو، يجعل في الأدوية، والجميع: طراثيث.'),
(2745, 'ثلط', 'ثلط', 'ثلط', 'الثلط: هو سلح الفيل ونحوه إذا كان رقيقا.'),
(2746, 'نثط', 'نثط', 'نثط', 'النثط: خروج الكمأة من الأرض. والنبات إذا صدع الأرض وظهر. وفي الحديث: كانت الأرض تميد فوق [الماء] 14 فنثطها الله بالجبال فصارت لها أوتادا 15 .'),
(2747, 'ثبط', 'ثبط', 'ثبط', 'ثبطه عن الأمر تثبيطا، إذا شغله عنه.'),
(2748, 'طمث', 'طمث', 'طمث', 'الطمث: الافتضاض. وطمثت الجارية: افترعتها، وقول الله عز وجل: لم يطمثهن إنس قبلهم ولا جان* 16 . أي: لم يمسسهن. والطامث: لغة في الحائض. وطمثت البعير طمثا، إذا عقلته.'),
(2749, 'رطل', 'رطل', 'رطل', 'الرطل: مقدار نصف من، وتكسر الراء فيه. والرطل من الرجال: الذي فيه قضافة.'),
(2750, 'طرن', 'طرن', 'طرن', 'الطرن: الخز، والطاروني ضرب منه: [وفي النوادر: طرين الشرب، وطريموا، إذا اختلطوا من السكر] 17 .'),
(2751, 'رطن', 'رطن', 'رطن', 'الرطانة: تكلم الأعجمية. تقول: رأيتهما يتراطنان، وهو كل كلام لا تفهمه العرب.'),
(2752, 'نطر', 'نطر', 'نطر', 'الناطر: الذي يحفظ الزرع، سوادية، غير عربية.'),
(2753, 'طرف', 'طرف', 'طرف', 'الطرف: تحريك الجفون في النظر. [يقال] : شخص بصره فما يطرف. والطرف: اسم جامع للبصر، لا يثنى ولا يجمع. والطرف: إصابتك عينا بثوب او غيره، والأسم: الطرفة. [تقول] : طرفت عينه، واصابتها طرفة. وطرفها الحزن بالبكاء. قال 18 : والعين مطروفة إنسانها غرق وقال 19 : فلا يغرك من فتاة ضحكها ... واعمد لأخرى صامت ما تطرف طرح الهاء من صامت على لزوم الصموت كالطبيعة فيها، كما يقال: تصلي صلاة الصبح والشمس طالع ... وتسجد للرحمن والقلب كاره طرح الهاء من (طالع) للزوم الطلوع لها طوعا أو كرها. ومنتهى كل شيء طرفه. والأطراف: اسم الأصابع، لا يفرد إلا بالإضافة إلى الإصبع، يقال: أشار بطرف إصبعه، قال 20 : يبدين أطرافا لطافا عنمه وأطراف الأرض: نواحيها، الواحد: طرف. والطرف: الطائفة من الشيء، [تقول] : أصبت طرفا من الشيء. والطرف: اسم يجمع الطرفاء، قلما يستعمل إلا في الشعر، الواحدة: طرفة، وجمع ذلك: الطرفاء، ممدود، وقياسه: قصبة وقصب وقصباء، وشجرة وشجر وشجراء. والطرف: الفرس، تقول: هو كريم الأطراف، يعني: الآباء والأمهات. ويقال: هو المستطرف، ليس من نتاج صاحبه، الأنثى: طرفة، قال: وطرفة شدت دخالا مدمجا 21 وقد يوصف بالطرفة النجيب والنجيبة، قال حسان: نحث الخيل والنجب الطروفا 22 والطرف من مال الرجل، هو: الطارف والمستطرف الذي قد استفاده، ولم يكن أصليا من ميراث ولا اعتقار قبل ذلك، والطارف في الكلام أحسن. وفي الشعر الطرف والطارف والطريف سواء، قال: بذلت له من كل طرف وتالد 23 والشيء الطريف: المستحدث المستطرف، وهو الطريف وما كان طريفا، ولقد طرف يطرف، والأسم: الطرفة. وأطرفته شيئا لم يملك مثله فأعجبه. وإبل طوارف: تطرف مرعى بعد مرعى، إذا أكثرت من ذا ثم تتناول من غيره، قال: إذا طرفت في مربع بكراتها ... أو استأخرت عنها الثقال القناعس 24 وناقة طرفة: لا تثبت في مرعى واحد، إنما تتطرف من النواحي. ورجل طرف: لا يثبت على امرأة ولا على صاحب. وسباع طوارف: تشل الصيد، قال: تنفي الطوارف عنه دعصا بقر 25 والطراف: بيت سماؤه من أدم، وله كسران، وليس له كفاء، وهو ضرب من الأبنية للأعراب، قال طرفة: 26 رأيت بني غبراء لا ينكرونني ... ولا أهل هذاك الطراف الممدد والمطرف: ثوب كانت الرجال والنساء يلبسونه، والجميع: مطارف، قال: فلو أن طرفا صاد طرفا بطرفه ... لصدت بطرفي طرف ذات المطارف 27 وأطرفت شيئا، أي: أصبته، ولم يكن لي. وبعير مطرف، أي: أصيب من قوم آخرين، قال 28 : كأنني من هوى خرقاء مطرف ... دامي الأظل بعيد الشأو مهيوم'),
(2754, 'طفر', 'طفر', 'طفر', 'الطفر: وثوب في ارتفاع، كما يطفر الإنسان حائطا، أي: يثبه إلى ما وراءه. وطيفور: طويئر صغير.'),
(2755, 'فطر', 'فطر', 'فطر', 'الفطر: ضرب من الكمأة، وهو المروزي ونحوه، الواحدة بالهاء والفطر: شيء قليل من اللبن يحلب ساعتئذ، تقول: ما احتلبناها إلا فطرا، قال المرار: عاقر لم يحتلب منها فطر 29 وفطرت الناقة أفطرها فطرا، أي: حلبتها بأطراف الأصابع، قال [الفرزدق:] 30 : [شغارة تقذ الفصيل برجلها] ... فطارة لقوادم الأبكار وفطر ناب البعير: طلع. وفطرت العجين والطين، أي: عجنته واختبزته من ساعته، وإذا تركته ليختمر قلت: خمرته، وهو الفطير والخمير. وفطر الله الخلق، أي: خلقهم، وابتدأ صنعة الأشياء، وهو فاطر السماوات والأرض. والفطرة: التي طبعت عليها الخليقة من الدين. فطرهم الله على معرفته بربوبيته. ومنه: حديث: النبي صلى الله عليه وكل مولود يولد على الفطرة حتى يكون أبواه يهودانه وينصرانه ويمجسانه 31 . وانفطر الثوب وتفطر، أي: انشق. وتفطرت الجبال والأرض: انصدعت. وتفطرت يده، أي: تشققت. وفطرت إصبعه، أي: ضربتها وغمزتها فانفطرت دما، قال خلف: وأرنبة لك محمرة ... نكاد نفطرها باليد وفطرت وأفطرت الرجل وفطرته. كل يقال من الفطر بمعنى ترك الصوم. وفي الحديث أفطر الحاجم والمحجوم 32 .'),
(2756, 'فرط', 'فرط', 'فرط', 'الفرط: الحين من الزمان 33 . والفرط: ما سبق من عمل وأجر. وفرط له ولد: [مات صغيرا] . وفي الدعاء: اللهم اجعله لنا فرطا [أي: أجرا يتقدمنا حتى نرد عليه] 34 . والفارط: الذي يسبق القوم إلى الماء. والفارطان: كوكبان متباينان أمام سرير بنات نعش، شبها بالفارط الذي يبعثه القوم لحفر القبر، قال أبو ذؤيب: 35 وقد بعثوا فراطهم فتأثلوا ... قليبا سفاها كالإماء القواعد وأفراط الصباح: أوائل تباشيره، الواحد: فرط، قال 36 : باكرته قبل الغطاط اللغط ... وقبل جوني القطا المخطط وقبل أفراط الصباح الفرط وفرط إلينا من فلان خير أو شر، أي: عجل، ومنه قوله [جل وعز] : إننا نخاف أن يفرط علينا، أو أن يطغى 37 ، أي: يسبق ويعجل. وفرط علينا، أي: عجل علينا بمكروه. والإفراط: إعجال الشيء في الأمر قبل التثبت. وأفرط [فلان] في أمره، أي: عجل فيه وجاوز القدر. والسحابة تفرط الماء في أول الوسمي، إذا عجلت فيه. قال كعب بن زهير: 38 تجلو الرياح القذى عنه وأفرطة ... من صوب سارية بيض يعاليل والفرط: الأمر الذي يفرط فيه صاحبه، وتقول: كل أمر من فلان فرط. وفرط فلان في جنب الله، أي: ضيع حظه من عند الله في اتباع دينه ورضوانه. وفرط الله عنه ما يكره، أي: نجاه، يستعمل في الشعر. وكل شيء جاوز قدره فهو مفرط. طول مفرط، وقصر مفرط. وتفارطته الهموم، أي: لا تصيبه الهموم إلا في الفرط. وفرس فرط: [السريع] الذي يتقدم الخيل ويسبقها، قال لبيد: 39 [ولقد حميت الحي تحمل شكتي] ... فرط، وشاحي، إذ غدوت، لجامها'),
(2757, 'طرب', 'طرب', 'طرب', 'الطرب: الشوق. والطرب: ذهاب الحزن، وحلول الفرح. طرب يطرب طربا فهو طرب. وطرب في غنائه تطريبا، [إذا رجع صوته] 40 ، وأطربني هذا الشيء. والأطراب: نقاوة الرياحين، وأذكاؤها. واستعمل الطرب في الإبل في قوله:'),
(2758, 'طرم', 'طرم', 'طرم', 'الطرم في قول: الشهد، وفي قول: الزبد. قال الشاعر: [فمنهن من يلفى كصاب وعلقم] ... ومنهن مثل الشهد قد شيب بالطرم 48 يعني: الزبد. وقال: [فأتينا بزغبد وحتي] ... بعد طرم وتامك وثمال 49 والطرم: الكانون. والطرمة: البثرة في وسط الشفة السفلى، والترفة في العليا، فإذا جمعوا قالوا: طرمتين، بتغليب الطرمة على الترفة. والطريم: السحاب الكثيف، قال رؤبة 50 : في مكفهر الطريم الشرنبث وقيل: الطريم ما يكون فوق الماء من دمن وغثاء. والطرامة: خضرة في الأسنان، وقد أطرمت أسنانه. والطارمة، دخيل: وهو بيت كالقبة، من خشب.'),
(2759, 'طمر', 'طمر', 'طمر', 'طمر فلان شيئا، أي: خبأه حيث لا يدري. والمطمورة: حفرة، أو مكان تحت الأرض قد هيىء خفيا، يطمر فيه طعام أو مال 51 . والطمر: الثوب الخلق. والطمرور: نعت الفرس الجواد. والطمور: شبه الوثوب. وطامر بن طامر، أي: برغوث بن برغوث.'),
(2760, 'رطم', 'رطم', 'رطم', 'رطمت الشيء رطمأ فارتطم، أي: أوحلته فوحل. وارتطم فلان في أمر فلا مخرج له منه. والرطوم: من نعت الحر الكبيرة الواسعة.'),
(2761, 'رمط', 'رمط', 'رمط', 'الرمط: مجمع العرفط ونحوه من شجر العضاه كالغيضة. وأنكره بعض وقال: إنما هو الرهط والرهاطة، وهو ما اجتمع من العرفط.'),
(2762, 'مطر', 'مطر', 'مطر', 'المطر: الاسم [وهو الماء المنسكب من السحاب] ، والمطر: فعله. والمطرة: الواحدة. ويوم مطير: ماطر. وواد مطير: ممطور. ومطرتنا السماء تمطرهم مطرا، وأمطرتهم [السماء] وهو أقبحهما. وأمطرهم الله مطرا أو عذابا. ورجل مستمطر: طالب خير من إنسان. ومكان مستمطر: قد احتاج إلى المطر، وإن لم يمطر، قال خفاف [بن ندبة:] لم يكس من ورق مستمطر عودا 52 يصف القحط، وقال رؤبة: 53 والطير تهوي في السماء مطرا يعني: مسرعة. وجاءت الخيل متمطرة، [أي: مسرعة] يسبق بعضها بعضا.'),
(2763, 'مرط', 'مرط', 'مرط', 'المرط: نتفك الشعر والريش والصوف عن الجسد، [تقول] : مرطت شعره فانمرط، وقد تمرط الذئب إذا سقط شعره وبقي شيء قليل، فهو أمرط. والأمرط: من لا شعر على جسدة إلا قليل، فإن ذهب كله فهو أملط، وقد مرط مرطأ. وسهم أمرط: سقط قذذه. وسهم مراط: لا ريش عليه والجميع [مرط] 54 ، وقيل: قد يقال: سهم مرط، وجمعه: أمراط، قال ذو الرمة:'),
(2764, 'نطل', 'نطل', 'نطل', 'الناطل: مكيال يكال به اللبن ونحوه، وجمعه: النواطل والنيطل: الداهية الشنعاء، والجميع: النياطل. والنئطل [أيضا] مهموز.'),
(2765, 'طلف', 'طلف', 'طلف', 'الطلف: شبه الأخذ، وقيل: الطلف: الفضل، وهو زيادة تفضل. وقيل: هذا الشيء طلف، أي: مجان. ويقال: أطلفني، [و] 57 أسلفني، فالطلف: العطاء المجان، والسلف: الذي يقتضى. [ويقال] : أطلفه وأطلف عليه، أي: أعطاه مجانا، وأفضل عليه.'),
(2766, 'طفل', 'طفل', 'طفل', 'غلام طفل، إذا كان رخص القدمين واليدين. وامرأة طفلة الأنامل، أي: رخصتها في بياض، بينة الطفولة، قال الأعشى: 58 حرة طفلة الأنامل ترتب ... سخاما تكفه بخلال والفعل: طفل يطفل طفولة، مثل: رخوصة ورخاصة. والطفل: الصغير من الأولاد للناس والبقر والظباء ونحوها. وتقول: فعل ذلك في طفولته، أي: هو طفل ولا فعل له، لأنه ليس له قبل ذاك حال فتحول منها إلى الطفولة. وأطفلت المرأة والظبية [والنعم] 59 إذا كان معها والد طفل، فهي مطفل قال لبيد: 60 فعلا فروع الأيهقان وأطفلت ... بالجلهتين ظباؤها ونعامها أدخل النعام اضطرارا إلى القافية. والطفل: طفل الغداة وطفل العشي من لدن [أن] تهم الشمس بالذرور إلى أن يستمكن الصبح من الأرض. طفلت الشمس تطفل طفلا. ثم تضيء وتصبح، ويقال: طفلت تطفيلا، أي: وقع الطفل في الهواء، وعلى الأرض وذلك بالعشي، قال لبيد: 61 فتدليت عليه قافلا ... وعلى الأرض غيايات الطفل والتطفيل من كلام العرب 62 : أن يأتي الرجل وليمة أو صنيعا لم يدع إليه، فكل من فعل فعله نسب إليه، وقيل 63 : طفيلي.'),
(2767, 'لطف', 'لطف', 'لطف', 'اللطف: البر والتكرمة. وأم لطيفة بولدها تلطف [إلطافا] . واللطف: من طرف التحف ما ألطفت به أخاك ليعرف به برك. وأنا لطيف بهذا الأمر، أي: رفيق بمداراته. واللطيف: الشيء الذي لا يتجافى، من الكلام وغيره، والعود ونحوه، كلام لطيف، وعود لطيف، لطف لطافة.. وإن فيها للطافة خلق: غير جسيمة.'),
(2768, 'فلط', 'فلط', 'فلط', 'أفلطني، في لغة تميم: بمعنى أفلتني، وهي قبيحة. ولقيت فلانا أفلاطا، أي: بغتة.. هذلية.'),
(2769, 'طلب', 'طلب', 'طلب', 'الطلب: محاولة وجدان الشيء. والطلبة: ما كان لك عند آخر من حق تطالبه به. والمطالبة: أن تطالب إنسانا بحق لك عنده، ولا تزال تطالبه وتتقاضاه بذلك. والغالب في باب الهوى: الطلاب والمعنى واحد. والتطلب: طلب في مهلة من مواضع. وكلأ مطلب: بعيد المطلب، وقد أطلب الكلأ، أي: تباعد وطلبه القوم. والمطلب: ابن عبد مناف.'),
(2770, 'طبل', 'طبل', 'طبل', 'الطبل: معروف. وفعله: التطبيل، وحرفته: الطبالة، ويجوز: طبل يطبل، وهو ذو الوجه الواحد والوجهين. ويقال لكثير الكلام الكذب: لا تطبل علينا.'),
(2771, 'بطل', 'بطل', 'بطل', 'بطل الشيء يبطل بطلأ، أي: ذهب باطلا. والباطل: نقيض الحق، قال النابغة: 64 [لعمري، وما عمري علي بهين] ... لقد نطقت بطلا علي الأقارع وأبطلته: جعلته باطلا. وأبطلت: جئت بكذب، وادعيت غير الحق. والتبطل: فعل البطالة، وهو اتباع اللهو والجهالة. والبطل: الشجاع الذي يبطل جراحته ولا يكترث لها، ولا تكفه عن نجدته، وإنه لبطل بين البطولة. وبطلني فلان: منعني عملي. وتقول: البطل الرجل هذا، أي: إنه بطل، والبطل الشيء هذا، أي: إنه باطل، وجمع البطل: أبطال.'),
(2772, 'لبط', 'لبط', 'لبط', 'لبط فلان بفلان الأرض لبطا، أي: صرعه صرعا عنيفا. ولبط بفلان، إذا صرع من عين أو حمى، أو أمر يغشاه شبه مفاجأة.'),
(2773, 'بلط', 'بلط', 'بلط', 'بلاط الأرض: متنها الصلب من غير جمع، يقال: لزم [فلان] بلاط الأرض. والبلاط: ما بلطت به الأرض من حجارة أو آجر يفرش بها فرشا مستويا بها، أملس، فهي مبلوطة، وبلطناها بلطا، وبلطناها تبليطا. ويقال: بلطت الأرض وملطت، إذا سويت. والبلوط: ثمر شجر له حمل يؤكل، ويدبغ بقشره. والتبليط: عراقية: أن تضرب فرع أذن بطرف سبابتك ضربا يوجعه، [تقول] : بلطت أذنه تبليطا. وأبلط المطر الأرض، أي: أصاب بلاطها، وهو ألا ترى على متنها 65 ترابا وغبارا، قال رؤبة: 66 تفضي إلى أبلاط جوف مبلط'),
(2774, 'طلم', 'طلم', 'طلم', 'الطلمة: الخبزة، وقيل: الطلمة، بنصب اللام. والتطليم: ضربك الخبز.'),
(2775, 'طمل', 'طمل', 'طمل', 'الطمل: الرجل الفاحش الذي لا يبالي ما أتى وما قيل له. تقول: إنه لملط طمل، والجميع: طمول. وهو بين الطمولة، وقيل: الأطمال: اللصوص الخبثاء، قال 67 : أطاعوا في الغواية كل طمل ... يجر المخزيات ولا يبالي'),
(2776, 'لطم', 'لطم', 'لطم', 'اللطم: ضرب الخد، وصفحات الجسم ببسط اليد. والملاطم: الخدود. والفعل: لطم يلطم لطما.. واللطيم، بلا فعل، من الخيل: الذي يأخذ خديه بياض. ورجل ملطم، أي: لئيم. والملطم: الخد. وفرس أسيل الملطم، وجمعه: الملاطم. واللطيمة: سوق فيها أوعية العطر ونحوه من البياعات. وكل سوق يحمل إليها غير الميرة فهو اللطيمة من حر البياعات، غير ما يؤكل، قال النابغة: 68 [على ظهر مبناة جديد سيورها] ... يطوف بها وسط اللطيمة بائع واللطيمة: المسك في قول ذي الرمة: 69 [كأنه بيت عطار يضمنه] ... لطائم المسك يحويها وتنتهب يعني: أوعية المسك.'),
(2777, 'مطل', 'مطل', 'مطل', 'المطل: مدافعتك العدة، والدين، وليانه، [يقال] : ما طلني بحقي، ومطلني حقي. وهو مطول ومطال قال رؤبة: 70 داينت أروى والديون تقضى ... فمطلت بعضا وأدت بعضا ويروى: فامتطلت.. وفي الحديث: مطل الغني ظلم 71 والمطل: أيضا: مد المطال حديدة البيضة التي تذاب للسيوف حتى تحمى وتضرب وتمد وتربع. يقال: مطلها المطال، وهو الطباع، ثم يطبعها بعد المطل، فيجعلها صفيحة. والمطيلة: اسم الحديدة التي تمطل من البيضة، ومن الزبرة. والمطال: الحداد. والزبرة: العلاة التي يضرب عليها. والمطالي: من مناقع الماء.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2778, 'ملط', 'ملط', 'ملط', 'الملط: الرجل الذي لا يرفع له شيء إلا ألمأ عليه، فذهب به سرقة واستحلالا، والجميع: الملوط، والأملاط، وقد ملط ملوطا. والملاط: الذي يملط أرحام الخيل والإبل، يدهن يده ثم يدخل بها حياء الناقة، لينظر أي شيء في رحمها من داء، وربما نزع ولدها. والملاطان جانبا السنام مما يلي مقدمه. والملطاء، بوزن الحرباء، ممدود، مذكر: هي الشجة التي يقال لها: المسحاق، [يقال] : شج رأسه شجة ملطاء. والأملط: الرجل الذي لا شعر على جسده كله إلا الرأس واللحية، والفعل: ملط يملط ملطا وملطة، وكان قيس بن الأحنف أملط. وقيل: المليط: الذي أعجل عن التمام من الولد، والذي لم يخرج شعره. والملاط: الذي يملط الطين، والملاط: هو الطين الذي يجعل بين سافي البناء.'),
(2779, 'طفن', 'طفن', 'طفن', 'الطفانية: نعت سوء في الرجل والمرأة.'),
(2780, 'طنف', 'طنف', 'طنف', 'الطنف: نفس التهمة. ورجل مطنف، أي: متهم. طنفته: اتهمته. ويطنف فلان بهذه السرقة، وإنه لطنف بهذا الأمر، أي: متهم.'),
(2781, 'فطن', 'فطن', 'فطن', 'رجل فطن بين الفطنة والفطن. وقد فطن لهذا الشيء يفطن فطنة فهو فاطن. وأما الفطن فذو فطنة بين الفطنة. ولا يمتنع كل فعل من النعوت من أن يقال: قد فعل، وفطن، أي: صار فطنا إلا القليل. وفطنته لهذا الأمر تفطينا ففطن، قال رؤبة 72 : وقد أعاصي في الشباب الميال ... موعظة الأدنى وتفطين الوال يعني بالتفطين: تأديبه إياه، وبيانه له الشر.'),
(2782, 'نطف', 'نطف', 'نطف', 'النطف: التلطخ بالعيب، قال الكميت: فدع ما ليس منك ولست منه ... هما، ردفين، من نطف قريب وفلان ينطف بسوء. أي: يلطخ، وفلان ينطف بفجور، أي: يقذف به. والنطف: عقر الجرح، ونطف الجرح، أي: عقر. والنطف: اللؤلؤ، الواحدة: نطفة، وهي الصافية الماء، وقيل: الواحدة: نطفة، والجميع: النطف. تشبيها بقطرة الماء. والنطفة: الماء الصافي، قل أو كثر، والجميع: النطف والنطاف. وليلة نطوف: [قاطرة] تمطر حتى الصباح. والنطف: الصب، و [القطر] . والناطف: القاطر. وأنف نطوف: كثير القطران. ووصيفة منطفة: مقرطة بتومتين، قال 73 : كأن ذا فدامة منطفا والتنطف: التقزز. والنطفة: التي يكون منها الولد. والناطف: القبيط.'),
(2783, 'نفط', 'نفط', 'نفط', 'النفط، والنفط لغة: حلابة جبل في قعر بئر توقد به النار. والنفاطات: ضرب من السرج يرمى فيها بالنفط و [يستصبح بها] . والنفاطة أيضا: الموضع الذي يستخرج منه النفط. والنفط: قيح يخرج في اليدين من العمل ملآن ماء، وقد نفطت يده، وأنفطها العمل، وإن انفقأت تلك النفطة فهي أيضا كذلك لم تصلب، فإذا صلبت صارت: مجلة.'),
(2784, 'طنب', 'طنب', 'طنب', 'الطنب: حبل الخباء [والسرادق] ونحوهما. وأطناب الشجر: عروقها، وأطناب الجسد: عصب يصل المفاصل والعظام ويشدها. والإطناب: البلاغة في المنطق في مدح أو ذم. والإطنابة: سير يوصل بوتر القوس العربية، ثم يدار على كظرها، وقوس مطنبة.'),
(2785, 'طبن', 'طبن', 'طبن', 'طبن فلان لهذا الأمر يطبن طبانة وطبنا، إذا فطن له فهو طبن.. وقيل: الطبن في الخير، والتبن في الشر. ويقال: هو أطبن، أي: غامض شديد [الغموض] . والطبن: خطة يخطها الصبيان، يلعبون بها، يسمونها الرحى، وقيل: هي الطبنة. واطبأن: لغة في اطمأن.'),
(2786, 'نطب', 'نطب', 'نطب', 'النواطب: خروق تجعل في مبزل الشراب، وفيما يصفى به الشيء، فيتصفى منه ويبتزل. والواحدة: ناطبة.'),
(2787, 'نبط', 'نبط', 'نبط', 'النبط: الماء الذي ينبط من قعر البئر إذا حفرت، وقد نبط ماؤها ينبط نبطا ونبوطا، وقد أنبطنا الماء، أي: استنبطناه، يعني: انتهينا إليه. والنبط: ما يتحلب من الجبل كأنه عرق يخرج من أعراض الصخر. والنبط والنبطة: بياض يكون تحت إبط الفرس، وكل دابة وبهيمة، وربما عرض حتى يغشى البطن والصدر. وشاة نبطاء: موشحة، أو نبطاء مجوزة 74 ، أي: [البياض] محيط بجوزها، وهو الصدر، فإن كانت بيضاء فهي نبطاء بسواد، وإن كانت سوداء فهي نبطاء ببياض، قال ذو الرمة: 75 كمثل الجواد الأنبط البطن قائما ... تمايل عنه الجل واللون أشقر والنبط والنبيط: كالحبش والحبيش في التقدير، وسموا به، لأنهم أول من استنبط الأرض، والنسبة إليهم: نبطي، وهم قوم ينزلون سواد العراق، والجميع: الأنباط. وعلك الأنباط: هو الكاماني المذاب يجعل لزوقا للجرح.'),
(2788, 'بطن', 'بطن', 'بطن', 'البطن في كل شيء خلاف الظهر، كبطن الأرض وظهرها، وكالباطن والظاهر، وكالبطانة والظهارة، يعني: باطن الثوب وظاهره، قال الله عز وجل: متكئين على فرش بطائنها من إستبرق 76 وفي بعض التفسير: بطائنها: ظواهرها. وبطانة الرجل: وليجته من القوم الذين يداخلهم ويداخلونه في دخلة أمرهم. وبطانته: سريرته. وكذلك يقال: أهل بطانته، ولحاف مبطون ومبطن. والباطنة من الكوفة والبصرة ونحوهما: مجتمعهم في وسطها. والظاهرة: ما تنحى. وبطن الراحة وظهر الكف، وباطن الإبط، ولا يقولون: بطن. وباطن الخف: [الذي تليه الرجل] 77 . والنعمة الباطنة: التي قد خصت، والظاهرة: التي عمت، قال الله عز وجل: وأسبغ عليكم نعمه ظاهرة وباطنة 78 . والبطنة: امتلاء البطن من الطعام، وهي الأشر من كثرة المال أيضا، ومنه قيل: نزت به البطنة. ورجل بطين: ضخم 79 البطن، ورجل بطين: كثير المال أيضا، قال رؤبة: 80 وكرز يمشي بطين الكرز ... لا يحذر الكي بذاك الكنز ورجل مبطون: قد بطن، وبه البطن. وألقت الدجاجة ذا بطنها: كناية عن مزقها، أي: سلحها. وألقت المرأة ذا بطنها، أي: ولدت، ونثرت للزوج بطنها، أي: أكثرت ولدها. والبطان للبعير كالحزام للدابة، وجمعه: بطن، والعدد: أبطنه.. وتبطينك الدابة: ضربك بطنها بالسوط. وتبطنت في هذا الأمر، أي: دخلت فيه حتى عرفت باطنه. وتبطنت الأرض والكلأ، أي: جولت فيه. ورجل مبطان: يغيب بالعشيات عن الناس في الشرب وغيره، قال متمم: 81 لقد كفن المنهال تحت ردائه ... فتى غير مبطان العشيات أروعا ورجل مبطان، [إذا كان لا يزال ضخم البطن] يأكل أكلا شديدا دون أصحابه. وتقول: أنت أبطن بهذا الأمر خبرة، وأطول به عشرة، أي: أخبر بباطنه.'),
(2789, 'طمن', 'طمن', 'طمن', 'اطمأن الرجل، واطمأن قلبه، واطمأنت نفسه إذا سكن واستأنس. والمطمئن من الأرض، أرض منخفضة، وهي: المتطأمنة'),
(2790, 'نمط', 'نمط', 'نمط', 'النمط: ظهارة الفراش. والنمط: جماعة من الناس أمرهم واحد، وفي الحديث: خير الناس النمط الأوسط 82 . وقول علي عليه السلام: عليكم بالنمط الأوسط 83 ، يعني الطريقة. ونمط من العلم والمتاع وكل شيء، أي: نوع منه.'),
(2791, 'فطم', 'فطم', 'فطم', 'فطمت الصبي أمه تفطمه، أي: تقطعه عن الرضاع والغلام فطيم مفطوم، والجارية: فطيمة مفطومة، وفطمت فلانا عن عادته.'),
(2792, 'بطم', 'بطم', 'بطم', 'البطم: شجرة الحبة الخضراء، الواحدة: بطمة.'),
(2793, 'دظ', 'دظ', 'دظ', 'الدظ: الشل بلغة أهل اليمن، يقال: دظظناهم في الحرب، ونحن ندظهم دظا 1 .'),
(2794, 'دث', 'دث', 'دث', 'دث فلان دثة، وذلك التواء في جنبه وبعض جسده. والتدثيث: التليين، ودثثت الأمر الصعب ودثيته: لينته. والديايثة جمع الديوث، وهو المحتمل لما يناله من سوء في حرمته.'),
(2795, 'در', 'در', 'در', 'در اللبن يدر درا، وكذلك الناقة إذا حلبت فأقبل منها على الحالب شيء كثير، قيل: درت وإذا اجتمع في الضرع من العروق [وسائر الجسد قيل: در اللبن] 3 ودرت العروق إذا امتلأت دما. ودرت السماء إذا كثر مطرها، وسحابة مدرار وناقة درور، وقال: وقالوا لدنياهم أفيقي فدرت 4 [وروي عن عمر بن الخطاب أنه أوصى عماله حين بعثهم فقال في وصيته لهم: أدروا لقحة المسلمين] 5 ، أراد بذلك فيئهم وخراجهم، والأسم من كل ذلك الدرة. وفي الشتم يقال: لا در دره، أي لا كثر خيره، ولله درك أي خيرك وفعالك. والدرير من الدواب: السريع المكتنز الخلق، المقتدر، قال: درير كخذروف الوليد أمره ... تتابع كفيه بخيط موصل 6 والدر: العظام من اللؤلؤ، والواحدة درة. وكوكب دري أي ثاقب مضيء وجمعه دراري. ودراية 7 من أسماء النساء. والدردور: موضع من البحر يجيش ماؤه، وقلما تسلم السفينة منه، يقال: لججوا فوقعوا في الدردور 8 . والدردر: موضع منابت الأسنان قبل نباتها وبعد سقوطها. [ويقال: درد الرجل فهو أدرد إذا سقطت أسنانه وظهرت درادرها، وجمعه الدرد] 9 . [ومن أمثال العرب السائرة: أعييتني بأشر فكيف أرجوك بدردر] 10 . ودرة السلطان: ما يضرب بها.'),
(2796, 'رد', 'رد', 'رد', '[الرد مصدر رددت الشيء] . وردود الدراهم واحدها رد، وهو ما زيف فرد على ناقده بعد ما أخذ منه 11 . والرد: ما صار عمادا للشيء الذي تدفعه وترده. والردة: مصدر الارتداد عن الدين. والردة: تقاعس في الذقن. وإن كان في الوجه بعض القباحة ويعتريه شيء من جمال، يقال: هي جميلة ولكن في وجهها بعض الردة. ورداد اسم الرجل المجبر ينسب إليه المجبرون لأنه يرد العظم المنكسر إلى موضعه'),
(2797, 'دل', 'دل', 'دل', 'الدل دلال المرأة إذا تدللت على زوجها تريه جراءة عليه في تغنج وتشكل كأنها تخالفه وليس بها خلاف. والرجل يدل على أقرانه في الحرب يأخذهم من فوق. والبازي يدل على صيده. والدالة: مما يدل الرجل على من له عنده منزلة أو قرابة قريبة: شبه جراءة منه. والدلالة: مصدر الدليل (بالفتح والكسر) . والدليلاء، يمد ويقصر، ومعناه ما دلكم عليه. والدلدل: شيء أعظم من القنفذ، ذو شوك طوال. والتدلدل كالتهدل. والدلدل اسم بغلة رسول الله- صلى الله عليه وآله وسلم-'),
(2798, 'لد', 'لد', 'لد', 'اللد: فعلك باللدود حين تلد به، وهو الدواء يوجر في أحد شقي الفم، وتقول: لددته ألده لدا، والجمع ألدة. وأخذ اللدود من لديدي الوادي، وهما جانباه، والوجور في وسط الفم. واللديدان: صفقا العنق من دون الأذنين، وجانبا كل شيء لديداه، قال رؤبة: على لديدي مصمئل صلخاد 12 والتلدد في التلفت، أن يعطف بعنقه مرة كذا ومرة كذا. واللدد مصدر الألد أي السيىء الخلق الشديد الخصومة، العسر الانقياد. ورجل ألندد ويلندد: كثير الخصومات شرس المعاملة، قال: عقيلة شينخ كالوبيل ألندد 13 وهذيل تقول: لده عن كذا أي حبسه.'),
(2799, 'دن', 'دن', 'دن', 'الدن ما عظم من الرواقيد كهيئة الحب، إلا أنه طويل مستوى الصنعة في أسفله كهيئة قونس البيضة. والدنين والدنينة: أصوات النحل والزنابير ونحوها [وأنشد: لدندنة النخل في الخشرم] 14 والدندنة من هينمة الكلام الذي لا يفهم. والدندن: أصول الشجر البالي، وجمعه دنادن 15 .'),
(2800, 'ند', 'ند', 'ند', 'الند: ما كان مثل الشيء يضاده في أموره. والنديد والند سواء، وجمع الند أنداد. وند البعير ندودا: انفرد واستعصى، وأندت البعير فند. ويوم التناد 16 : يوم التناص أي ينادي بعضهم بعضا، أصحاب الجنة أصحاب النار، وقرىء: يوم التناد 17 بتشديد الدال أي يندون فينفرون، هكذا في بعض التفسير. والتنديد: أن تندد بإنسان أي تسمع الناس بعيوبه وتشتمه. ويندد: اسم موضع، قال: لو كنت بالشروين شروى يندد 18 والند: ضرب من الدخنة من غير فعل.'),
(2801, 'دف', 'دف', 'دف', 'الدف والدفة: الجنب لكل شيء، قال: ووانية زجرت على وجاها ... قريح الدفتين من البطان 19 والدف لغة أهل الحجاز في الدف الذي يضرب به، والدفاف عامله. ودفتا الطبل: اللتان على رأسه. ودفتا المصحف: ضمامتاه من جانبيه. والدفيف: أن يدف الطائر على وجه الأرض بتحريك جناحيه، ورجلاه في الأرض، وهو يطير ثم يستقل، قال الراجز: والنسر قد ينهض وهو دافي 20 فخفف وكسر على كسرة دافف وحذف الفاء. والدافة: قوم يسيرون سيرا لينا ليس بالشديد، وهم يدفون دفيفا. وداففت الرجل دفافا ومدافة، وهو إجهازك عليه أي مبادرة إلى قتله، والآمر الذي يأمر يقول: داف الرجل أي ائت عليه، ويخفف في لغة جهينة فيقال: دافيته، ويأمر فيقول: داف يا هذا. وتداف القوم: ذكر بعضهم بعضا، ولا أراه مأخوذا في الأمر من هذا.'),
(2802, 'فد', 'فد', 'فد', 'الفديد: صوت كالحفيف، وقد فد يفد فديدا، ومنه الفدفد 21 ، قال النابغة: أوابد كالسلام إذا استمرت ... فليس يرد فدفدها التظني 22 وفلاة فدفد: لا شيء فيها وبها (كذا) ، قال: قلائص إذا علون فدفدا 23 وفي الحديث: هلك الفدادون إلا من أعطاها في نجدتها ورسلها ، والفدادون هنا أصحاب الإبل، يقول: إلا من أخرج زكاتها في شدتها ورخائها. ويقال: فديد من الإبل، يصف الكثرة.'),
(2803, 'دب', 'دب', 'دب', 'دب النمل يدب دبيبا، والمدب موضع دبيب النمل. ودب القوم يدبون دبيبا إلى العدو أي مشوا على هينتهم ولم يسرعوا. والديدبة: العجروف من النمل، وذلك أنه أوسع خطوا وأعجل نقلا. والدبابة: آلة تتخذ في الحروب يدخل فيها الرجال بسلاحهم، ثم تدفع في أصل حصن فينقبون وهم في جوفها. والدبة لزوم حال الرجل في فعاله، وتقول: ركب فلان دبة فلان واخذ بدبته أي يعمل بعمله ويركب طريقته. والدب من السباع مضر عاد، والأنثى دبة، والجميع دببة. وكل شيء مما خلق الله يسمى دابة، والأسم العام الدابة لما يركب، وتصغيرها دويبة، الياء ساكنة وفيها إشمام من الكسرة، وكذلك كل ياء في التصغير إذا جاء بعدها حرف مثقل في كل شيء. وديابوذ 24 : ثوب له سدان، ويقال: هو كساء، ليست بعربية، وهو بالفارسية دوبود فعربت.'),
(2804, 'بد', 'بد', 'بد', 'البد: بيت فيه أصنام وتصاوير، وهو إعراب بت بالفارسية، [وأنشد: لقد علمت تكاكرة ابن تيري ... غداة البد أني هبرزي] 25 ويقال: ليس لهذا الأمر بد أي لا محالة. والتبدد: التفرق، وذهب القوم في الأمر بداد بداد أي تفرقوا. وجاءت الخيل بداد بداد أي واحدا واحدا 26 . واستبد فلان [برأيه] أي انفرد بالأمر 27 . والبداد: لبد يشد مبدودا على الدابة الدبرة، تقول: بد عن دبرها أي شق. والبدد مصدر الأبد، وهو الذي في يديه تباعد عن جنبيه. وبرذون أبد، والحائك أبدا أبد. وفلاة بدبد: لا أحد فيها. ورجل له جسم وباد وباده: طول فخذيه، والبادان: باطنا الفخذين. ورجل أبد أي عظيم الخلق، وامرأة بداء.'),
(2805, 'دم', 'دم', 'دم', 'الدم: الفعل من الدمام، وهو كل دواء يلطخ به على ظاهر العين، قال: تجلو بقادمتي حمامة أيكة ... بردا تعل لثاته بدمام 28 يعني النؤور قد طليت به حتى رسخ. ويقال للشيء السمين كأنما دم بالشحم دما [وقال علقمة: كأنه من دم الأجواف مدموم] 29 ويدم الصدع بالدم والشعر المحرق يجمع بينهما، ثم يطلى الصدع فيعض عليه ويشد، وقد دممنا يديه بالشعر والصوف والدمام دما 30 والدمامة مصدر الشيء الدميم. وأساء فلان وأدم أي أقبح، والفعل اللازم: دم يدم، ولغة ثانية على قياس فعل يفعل، وليس في باب التضعيف على فعل يفعل غير هذا. وتقول: دممت يا هذا، وإذا أردت اللازم قلت: دممت. والدأماء: بيت اليربوع غير القاصعاء والنافقاء، والجميع الدأماوات. والدمدمة: الهلاك المتأصل.'),
(2806, 'مد', 'مد', 'مد', 'المد: الجذب، والمد: كثرة الماء أيام المدود. ومد النهر، وامتد الحبل، هكذا قالته العرب. والمدد: ما أمددت به قوما في الحرب وغيره من الطعام والأعوان. والمادة: كل شيء يكون مددا لغيره، ويقال: دعوا في الضرع مادة اللبن، والمتروك في الضرع هو الداعية، وما اجتمع إليه هو المادة. والمادة: أعراب الإسلام، وأصل العرب وهم الذين نزلوا البوادي. والمداد: ما يكتب به، يقال: مدني يا غلام، أي أعطني مدة من الدواة، وأمددني جائز، فإن قلت: أمدني خرج على مجرى المدد بها والزيادة ويكون في معنى المدد 31 . والمديد: شعير يجش ثم يبل فتضفره الابل. والمدة: الغاية، وتقول: هذه مدة عن غيبته، وله مدة أي غاية في بقاء عيشه. ومد الله عمرك أي جعل لعمرك مدة طويلة. والمد نصف صاع، والصاع خمسة أرطال وثلث، ويقال: إنه مثل القفيز السناني (كذا) . ولعبة للصبيان يقال لها: مداد قيس. والتمدد كتمدد السقاء، وكذلك كل شيء يبقى فيه شبه المد. والامتداد في الطول، وامتد بهم السير أي طال. وأمد الجرح أي: اجتمعت فيه المدة. وسبحان الله مداد كلماته من المد لا من المداد 32 الذي يكتب (به) ، ولكن معناه على قدر كثرتها وعددها. والأمدة: المساك في جانبي الثوب إذا ابتدىء في عمله، والتثنية أمدان بوزن أفعلان. والمديد: بحر من العروض نحو قوله: يا لبكر انشروا لي كليبا ... يا لبكر أين أين الفرار 33'),
(2807, 'تلد', 'تلد', 'تلد', 'التلاد: كل ما ترثه عن أبيك وغيره فهو تالد وتليد ومتلد. والتليدة من الجواري هي التي تولد في ملك قوم وعندهم أبواها.'),
(2808, 'دلظ', 'دلظ', 'دلظ', 'دلظ يدلظ دلظا وهو الدفع الشديد. والدلظ: الزحم بالمناكب في القتال والمزاحمة، ومنه الدوالظة. والدلاظ وهو الصدم، قال البراض بن قيس: فيا لك شدة ما قد شددنا ... صبرنا للصفائح والدلاظ 34 والدلنظى: الجمل الضخم الغليظ المناكب، وناقة دلنظاة، واشتق من الدلظ، والجميع الدلائظ والدلاظى، وما كان دلنظى. وقد ادلنظى ادلنظاء.'),
(2809, 'دثر', 'دثر', 'دثر', 'الدثور: كثرة المال، ويقال: هم أهل دثر [ومال دبر بمعناه] 35 . ودثر أي درس فهو داثر، [وروي عن الحسن أنه قال: حادثوا هذه القلوب بذكر الله فإنها سريعة الدثور] 36 والدثار من فعل المتدثر.'),
(2810, 'ثرد', 'ثرد', 'ثرد', 'الثريدة معروفة. والتثريد في الذبيحة: تفسيخ الجلد وترك الإجهاز عليها، والكلالة 37 أداة للذبح'),
(2811, 'دلث', 'دلث', 'دلث', 'يقال: الدلاث [من الإبل] 38 : السريع، [قال كثير: دلاث العتيق ما وضعت زمامه ... منيف به الهادي إذا احتث ذامل 39 والمتدلث: المسرع، واندلث على وجهه أي مشى مسرعا.'),
(2812, 'ثند', 'ثند', 'ثند', 'الثندوة: لحم الثدي، وجماعتها ثندوات. والمثدن: الكثير اللحم المسترخي.'),
(2813, 'دمث', 'دمث', 'دمث', 'الدماثة: اللين، والدمث المكان السهل. والدميث: السهل الخلق، وقد دمث دمثا، والاسم الدماثة.'),
(2814, 'ثمد', 'ثمد', 'ثمد', 'الثمد: الماء القليل يبقى في الأرض الجلد. ويقال: الثمد الماء القليل يظهر في الشتاء ويذهب في الصيف. والإثمد: حجر الكحل'),
(2815, 'درن', 'درن', 'درن', 'الدرن: تلطخ الوسخ، وثوب درن وأدرن داخل عليه ويجوز في الشعر، [قال رؤبة يمدح رجلا: إن إمرؤ دغمر لون الأدرن ... سلمت عرضا ثوبه لم يدكن] 40 والفعل درن يدرن. والدرين: اليبيس الحولي، ويقال: ما في الأرض من اليبيس إلا الدرانة. والدرينة: الأحمق بلغة ناس من أهل الكوفة 41 .. ودرانة على فعلانة: من أسماء الجواري.'),
(2816, 'ردن', 'ردن', 'ردن', 'الردن: مقدم كم القميص. والأردن: أرض بالشام، وقيل: هو نهر بالحجز بين تيه بني إسرائيل وبين أرض الشام. والرادني من الإبل: ما جعد وبره، وهو منها كريم جميل يضرب إلى السواد شيئا. وليل مردن، أي مظلم. وعرق مردن: قد نمس الجسد كله. والردن: الخز ويقال: الحرير.'),
(2817, 'رند', 'رند', 'رند', 'ضرب من العود يدخن به.'),
(2818, 'ندر', 'ندر', 'ندر', 'ندر الشيء إذا سقط، وإنما يقال ذلك لشيء من بين شيء أو من جوف شيء، وكذلك نوادر الأشياء تندر. والأندري 42 ، والجميع الأندرون، وهم الفتيان الذين يجتمعون من مواضع شتى، قال ولا تبقى خمور الأندرينا 43 وقيل: الأندر موضع، وهي قرية أبي عبيد الوزير. ويقال: إنما يكون ذلك في الندرة بعد الندرة أي الأحيان، [وكذلك الخطيئة بعد الخطيئة] 44 . والأندر: البيدر في لغة أهل الشام. [ويقال للرجل إذا خضف: ندر بها] 45 .'),
(2819, 'دنر', 'دنر', 'دنر', 'دنر وجه فلان إذا أشرق وتلألأ. ودينار مدنر أي مضروب دينارا. وبرذون مدنر اللون أي أشهب على متنيه وعجزه سواد مستدير يخالطه شهبه.'),
(2820, 'نرد', 'نرد', 'نرد', 'النرد: الكعب الذي يلعب به. ومن لعب بالنرد فكأنما غمس يديه في لحم الخنزير.'),
(2821, 'ردف', 'ردف', 'ردف', 'الردف: ما تبع شيئا فهو ردفه، وإذا تتابع شيء خلف شيء فهو الترادف، والجميع: الردافى، قال: عذافرة تقمص بالردافى ... [تخونها نزولي وارتحالي] 46 ويقال: جاء القوم ردافى أي بعضهم يتبع بعضا. ورديفك: الذي تردفه خلفك، ويرتدفك، ويردفه غيرك. ونزل بالقوم أمر قد ردف لهم أمر أعظم منه. والرداف: هو موضع مركب الردف، وقال: لي التصدير فاتبع في الرداف 47 ويقال: برذون لا يردف ولا يرادف أي يدع رديفا يركبه. والرديف: كوكب قريب من النسر الواقع، والرديف في قول أصحاب النجوم هو النجم الناظر إلى النجم الطالع، [وقال رؤبة: وراكب المقدار والرديف ... افنى خلوفا قبلها خلوف 48 فراكب المقدار هو الطالع، والرديف هو الناظر إليه] 49 . والردف: الكفل 50 . وأرداف النجوم: تواليها أي ترادفها. والترادف: كناية عن فعل قبيح وذلك انه إذا عمل أحدهما عمل إثم ردفه الآخر.'),
(2822, 'فرد', 'فرد', 'فرد', 'الفرد ما كان وحده، يقال: فرد يفرد، وانفرد انفرادا. وأفردته: جعلته واحدا. والفريد: الشذر، الواحدة فريدة، وهو بلسان العجم الجاورسق، والجميع الجوارس، قال: وأكراس در فصلت بالفرائد 51 وجاء القوم فرادى، وعددت الخرز والدراهم 52 أفرادا أي واحدا واحدا. وقوله تعالى: لقد جئتمونا فرادى جميع فردان. والله الفرد: تفرد بالربوبية والأمر دون خلقه. ومن صفة الفارس في طراده قال: واستطرد لهم فكلما استفرد رجلا كر عليه فجدله، يريد أنه يندر من أصحابه فيطارد ساعة، فلما أمكنته الفرصة قتل منهم واحدا ومضى. والفراد: بياع الفريد، والفارد والفرد: الثور.'),
(2823, 'رفد', 'رفد', 'رفد', 'الرفد: المعونة بالعطاء، وسقي اللبن، والقول، وكل شيء. ورفدته بكذا، ورفدني أي أعانني بلسانه، وترافدوا على فلان بألسنتهم إذا تناصروا، قال: رفدت ذوي الأحساب منهم مرافدي 53 والواحد مرفد، ومن هذا سميت رفادة السرج لأنها تدعم السرج من تحته حتى يرتفع. والرفادة: شيء كانت قريش ترافد به في الجاهلية، فيخرجون أموالا بقدر طاقتهم فيشترون بها الجزور والطعام والزبيب للنبيذ، فلا يزالون يطعمون الناس حتى ينقضي الموسم. وأول من سن ذلك هاشم بن عبد مناف. والمرفد: عس تحلب فيه الرفود من النوق التي تملأ مرفدها، والرفد المصدر. وارتفدت مالا إذا سألته أن يرفدك، وارتفدت مالا إذا أصبته من كسب، قال الطرماح: عجبا ما عجبت من جامع المال ... يباهي به ويرتفده ويضيع الذي قد أوجبه الله ... عليه فليس يعتقده 54 [والترفيد نحو من الهملجة، وقال أمية بن أبي عائذ الهذلي: وإن غض من غربها رفدت ... وسيجا وألوت بجلس طوال 55 وأراد ب الجلس أصل ذنبها] 56 . والرافدان: دجلة والفرات . دفر: الدفر: وقوع الدود في الطعام واللحم ونحوهما. والدنيا دفرة أي منتنة، وهي أم دفر أيضا. ويقال للأمة: يا دفار.'),
(2824, 'فدر', 'فدر', 'فدر', 'فدر الفحل فدورا إذا فتر عن الضراب. والفدور: الوعل العاقل في الجبال. والفادرة: الصخرة الضخمة تراها في رأس الجبل، شبهت بالوعل. والفدرة: قطعة من الجبل دون الفنديرة. والفدرة: قطعة من اللحم المطبوخ البارد، وهو الفادر أيضا. [ويقال للوعل: فادر، وجمعه فدر، وقال الراعي: وكأنما انبطحت على أثباجها ... فدر بشابة قد يممن وعولا] 57'),
(2825, 'درب', 'درب', 'درب', 'كل مدخل من مداخل الروم درب من دروبها. والدرب باب السكة الواسعة، وربما كان ما بين. والدربة: عادة وجرأة على الحرب وكل أمر. ورجل مدرب: دربته الشدائد حتى قوي ومرن عليها، قال: ومن يحرص على كبر فإني ... أنا الكهل المدرب بالكلوم 58 والدرب: داء في المعدة. وما زال فلان يعفو عن فلان حتى اتخذها دربة. ودرب الإنسان بالشيء إذا عمله حتى بسأ به أي أتقن 59 . ودربت البازي على الصيد 60 أي ضريته. وشيخ مدرب أي مجرب 61 ، والدربة: كثرة العبر حتى يتدرب بالذنوب . برد: البرد: مطر كالجمد. وسحاب برد: ذو قر وبرد، [وقد برد القوم إذا أصابهم البرد] 62 . [وأما قول الله- جل وعز-: وينزل من السماء من جبال فيها من برد فيصيب به من يشاء، 63 ففيه قولان: أحدهما: وينزل من السماء من أمثال جبال فيها من برد، والثاني: وينزل من السماء من جبال فيها برد. ومن صلة] 64 . والأبردان: الغداة والعشي، وبرد يبرد برودة. وبردت الخبز بالماء: صببته عليه فبللته، واسم ذلك الخبز المبلول البريد والمبرود، تطعمه النساء للسمنة، وتقول: اسقني شربة أبرد بها كبدي. وبرد القر، وأبردوا: صاروا في وقت القر آخر النهار. وبردت الماء تبريدا. وبرد عليه حق كذا وكذا درهما أي لزمه ذلك. والبرود: كحل تبرد به العين من الحر. وفي الحديث: أبردوا بالظهر فإن شدة الحر من فيح جهنم. ويقال: جئناك مبردين إذا جاءوا وقد باخ الحر. والبرادة: الكوازة 65 . والبريد: ستة أميال يتم بها فرسخان. والبريد: الرسول المبرد على دواب البريد، [وإبراده إرساله] 66 ، وقال الراجز: رأيت للموت رسولا مبردا [ويروى عن النبي- صلى الله عليه وسلم- أنه قال: إذا أبردتم إلي بريدا فاجعلوه حسن الوجه حسن الاسم] 67 . [وقال بعض العرب: الحمى بريد الموت، أراد أنها رسول الموت تنذر به. وسكك البريد، كل سكة منها اثنا عشر ميلا، والسفر الذي يجوز فيه قصر الصلاة أربعة برد، وهي ثمانية وأربعون ميلا بالأميال الهاشمية التي في طريق مكة. وقيل لدابة البريد: بريد لسيره في البريد، وقال الشاعر: إني انص العيس حتى كأنني ... عليها بأجواز الفلاة بريد 68 ] 69 والبرد: سحكك الحديد بالمبرد أي السوهان (بالفارسية) . والبرد: ثوب من برود العصب والوشي. والبردد: كساء [مربع أسود فيه صغر ونحو ذلك] 70 تلتحف به العرب. وقوله تعالى: لا يذوقون فيها بردا ولا شرابا 71 ، يقال: نوما. وبردى: نهر دمشق، قال حسان: يسقون من ورد البريص عليهم ... بردى يصفق بالرحيق السلسل 72 وضربه حتى برد أي مات. وبرد فلان في أيديهم أي صار في أيديهم لا يفدى ولا يطلب. وبردا الجراد: جناحاه، قال ذو الرمة: إذا تجاوب من برديه ترنيم 73'),
(2826, 'ربد', 'ربد', 'ربد', 'ربد السيف فرنده، هذلية. والربدة في لون النعام قطعة كدراء، وأخرى 74 سوداء ونحوها من لون مختلط غير حسن. والأربد: ضرب من الحيات [خبيث] 75 . وتربد وجهه من الغضب، كأنه تسود منه مواضع. وإذا اضرعت الناقة قيل: ربدت، وتربد ضرعها إذا رأيت فيه لمعا من سواد ببياض خفي، قال: إذا والد منها تربد ضرعها ... جعلت له السكين إحدى القلائد 76 وإنما ذكر والد لأن الولد في بطنها، فإذا وضعت فهي والدة لأن الذكر لا يلد، فكل نعت لا يشترك فيه الذكر فهو للإناث بغير الهاء إذا اردت الاسم، فإن أردت الفعل ألحقت الهاء. والمربد: متسع بالبصرة كان موقف العرب ومتحدثهم، وكذلك مربد المدينة، والمربد: كل موضع للإبل، والمربد: شبه حجرة في كل دار مما يلي المرافق بمنزلة الدار المستديرة، ومثل المتوضأ وبئر الماء. والمربد: الذي يجعل فيه التمر عند الجداد لييبس. [وفي حديث النبي- صلى الله عليه وسلم-: إن مسجده كان مربدا ليتيمين في حجر معوذ بن عفراء فاشتراه منهما معاذ بن عفراء فجعله للمسلمين، فبناه رسول الله- صلى الله عليه وسلم- مسجدا] 77 .'),
(2827, 'دبر', 'دبر', 'دبر', 'دبر كل شيء خلاف قبله ما خلا قولهم: جعل فلان قولي دبر أذنه أي خلف أذنه ودبر أذنه 78 . ويقال للقوم في الحرب: ولوهم الدبر والإدبار والإدبار التولية نفسها. وما لهم من مقبل ولا مدبر 79 أي مذهب في إقبال وإدبار. وأدبار السجود 80 أي أواخر الصلوات. وإدبار النجوم 81 ، عند الصبح في آخر الليل إذا أدبرت مولية نحو المغرب. والدابر: التابع، ودبر يدبر دبرا أي تبع الأثر، وقوله تعالى: والليل إذ أدبر 82 أي ولى ليذهب، ومن قرأ: دبر أي تبع النهار. وقطع الله دابرهم أي آخر من بقي منهم. وجعل الدبرة عليهم أي الهزيمة. والدبور: ريح من قبل القبلة دابرة نحو المشرق، وجمعه دبر، والدبائر أصوب. والدابرة من الطائر اصبع من خلف وهي للديك، أسفل من الصيصية يطأ بها، وبها يضرب البازي. ودابرة الحافر: ما ولي مؤخر الرسغ، قال: افنى دوابرهن الركض في الأكم ومثل للعرب: ما يدري فلان قبيلا من دبير، القبيل: ما وليك، والدبير: ما خالفك. ويقال: الدبير فتل الكتان والصوف، والقبيل فتل القطن. ودبار: اسم ليلة الأربعاء في الجاهلية. والدبار: الهلاك، ودبر القوم يدبرون دبارا. ودبر ظهر الدابة، والاسم الدبر، ودابة دبرة. وأدبر أمره أي تولى إلى الفساد. ودابرته: عاديته. والمدابر من المنازل نقيض المقابل 83 . والدبرة: الكردة من مزرعة ومبقلة، وتجمع على دبار 84 . والدبران: نجم بين الثريا والجوزاء من منازل القمر، نحس من برج الثور. والتدبير: عتق المملوك بعد الموت. والتدبير: نظر في عواقب الأمور، وفلان يتدبر أعجاز أمور قد ولت صدورها. واستدبر من أمره ما لم يكن استقبل، أي نظر فيه مستدبرا فعرف ما عاقبة ما لم يعرف من صدره. واستدبر فلان فلانا من حينه، أي حين تولى تبع أمره. والدبر: النحل، والجميع الدبور. والتدابر: المصارمة والهجران، وهو أن يولي الرجل صاحبه دبره ويعرض عنه بوجهه . بدر: البدر: القمر ليلة البدر وهي أربع عشرة، وسمي بذلك لأنه يبادر بالطلوع عند غروب الشمس، 85 [لأنهما يتراقبان في الأفق صبحا] 86 . [والبدرة كيس فيه عشرة آلاف درهم أو ألف والجميع: البدور، وثلاث بدرات] 87 . ويقال لمسك السخلة ما دام يرضع: مسك فإذا فطم فمسكه البدرة. والبادرة: ما يبدر من حدة الرجل عند الغضب، يقال: فلان مخشي عند البادرة، وأخاف حدته وبادرته. والبادرتان: جانبا الكركرتين، ويقال: عرقان اكتنفاها [وأنشد: تمري بوادرها منها فوارقها 88 يعني فوارق الإبل وهي التي أخذها المخاض ففرقت نادة، فكلما أخذها وجع في بطنها مرت، أي ضربت بخفها بادرة كركرتها، وقد تفعل ذلك عند العطش] 89 . والبيدر مجمع الطعام حيث يداس وينقى. وابتدر القوم أمرا وتبادروا أي بادر بعضهم بعضا فبدر بعضهم فسبق وغلب عليهم. وبوادر الإنسان وغيره: اللحمة التي بين المنكب والعنق، قال: وجاءت الخيل محمرا بوادرها 90'),
(2828, 'درم', 'درم', 'درم', 'الدرم: استواء الكعب وعظم الحاجب ونحوه إذا لم ينبتر فهو أدرم. [والفعل درم يدرم فهو درم] 91 . ودرم: اسم رجل من بني شيبان ذكره الأعشى فقال: ولم يود من كنت تسعى له ... كما قيل في الحرب أودى درم 92 والدرامة من النساء: السيئة المشي] 93 ، قال: من البيض، لا درامة قملية ... تبذ نساء الناس دلا وميسما 94 والدرم في الأسنان: كسرها وانثلامها. والدرمان: مشية الأرنب والفأرة والقنفذ ونحوها، والفعل درم يدرم. والدرامة: اسم القنفذة والأرنب. والدرامة: نعت للمرأة القصيرة. وبنو درام من تميم، فيها بيتها وشرفها . ردم: ردمت الثلمة والباب أردم ردما أي سددته، والاسم الردم وجمعه ردوم، وثوب مردم وملدم إذا رفع، وقال عنترة: هل غادر الشعراء من متردم 95 أي مرقع مستصلح. والردم: سد ما بيننا وبين يأجوج ومأجوج.'),
(2829, 'مرد', 'مرد', 'مرد', 'المرد: حمل الأراك. والمرد: دفعك السفينة بالمردي أي خشبة يدفع بها الملاح السفينة، والفعل مرد يمرد مردا. ومراد: حي في اليمن، ويقال: الأصل من نزار. والمرادة: مصدر المارد. والمريد: من شياطين الإنس والجن. وقد تمرد عليه أي عصى واستعصى. ومرد على الشيء أي عتا وطغى، وكذلك قوله تعالى: مردوا على النفاق 96 . والتمراد: بيت صغير يجعل في بيوت الحمام لمبيضة، فإذا كانت نسقا بعضها فوق بعض فهي التماريد، وقد مردها صاحبها تمريدا وتمرادا بالكسر. والتمراد: بالفتح، اسم. والتمريد: تمليس الطين والتسوية كما مرد صرح سليمان- عليه السلام- ومرد الأمرد مرودة ومردا، وجمعه مرد. وتمرد فلان زمانا ثم خرج وجهه، وذلك أن يبقى حسنا أمرد. ورملة مرداء: لا تنبت شجرة إلا نبذا من بقول، أي قليلا، وهي صلبة الموطىء. وإمرأة مرداء: لم يخلق لها إسب . رمد: الرمد: وجع العين، وعين رمداء، ورجل أرمد ورمد. وقد رمدت عينه وأرمدت. وصار الرماد رمددا أي هباء أدق ما يكون، [والرماد دقاق الفحم من حراقة النار 97 ] . والمرمد من اللحم: الشواء يمل في الجمر، ورمدته فهو مرمد. ورمدت الناقة ترميدا فهي مرمدة إذا أنزلت شيئا من اللبن عند النتاج أو قبيله. ورمد القوم وأرمدوا: هلكوا. وارمد الظليم، أي أسرع، قال: وارمد مثل شهاب النار منصلتا ... كأنه خشرم بالقاع يأتلق 98'),
(2830, 'مدر', 'مدر', 'مدر', 'المدر: قطع طين يابس، الواحدة مدرة. والمدر: تطيينك وجه الحوض بالطين الحر لئلا ينشف الماء. والممدرة: موضع فيه طين حر يستعد لذلك. ومدرت الحوض أمدره. ورجل أمدر الجنبين أي عظيمهما، ويقال: منتبرهما. والأمدر من الظباء: الذي يرى على جسده لمع من سلحه. والمدرار: المطر الغزير الديمة 99 ، قال: وسقاك من نوء الثريا مزنة ... سحرا تحلب وابلا مدرارا 100'),
(2831, 'دمر', 'دمر', 'دمر', 'الدمار: استئصال الهلاك، يقال: دمر القوم يدمرون دمارا أي هلكوا. ودمر عليهم: مقتهم 101 . ودمرهم الله تدميرا 102 . [وقال الله- عز وجل-: فدمرناهم تدميرا] ، 103 يعني فرعون وقومه الذين مسخوا قردة وخنازير 104 . والمدمر: اسم الصياد. وتدمر: اسم مدينة بناها الشياطين بإذن سليمان بن داود- عليه السلام-، قال: يبنون تدمر بالصفاح والعمد 105 . والتدمري من اليرابيع: ضرب لئيم الخلقة علب اللحم أي عضل. يقال: هو من معزى اليرابيع، وأما ضأنها فهو شفاريها، وعلامة الضأن فيها أن له في وسط ساقه ظفرا في موضع صيصية الديك، ويوصف به الرجل اللئيم. والدمور: الدخول على القوم بلا إذن، ودمر يدمر دمرا ودمورا.'),
(2832, 'لدن', 'لدن', 'لدن', 'لدن بمعنى عند، وتقول: وقفوا له من لدن كذا إلى المسجد ونحو ذلك، إذا اتصل ما بين الشيئين، وكذلك في الزمان: من لدن طلوع الشمس إلى غروبها، أي من حين، قال: فما زال مهري مزجر الكلب منهم ... لدن غدوة حتى دنت لغروب 106 وقال الله- جل وعز-: قد بلغت من لدني عذرا 107 . واللدن: اللين من كل شيء، ولدن لدونه، ورمح لدن، وقناة بالهاء،: لينة المهزة.'),
(2833, 'ندل', 'ندل', 'ندل', 'الندل: الوسخ من كل شيء من غير استعمال [في العربية] 108 . وتندلت بالمنديل أي تمسحت به من أثر الوضوء أو الطهور، وتمندلت، ويقال: أندل عنه الوسخ أي ألقه'),
(2834, 'دلف', 'دلف', 'دلف', 'يقال: دلف الشيخ يدلف دلفانا ودليفا، وهو فوق الدبيب كما تدلف الكتيبة نحو الكتيبة في الحرب، قال طرفة: لا كبير دالف من هرم ... أرهب الناس ولا أكبو لضر 109'),
(2835, 'دلب', 'دلب', 'دلب', 'الدلب شجرة العيثام، ويقال: شجر الصنار، وهو بالصنار أشبه، والواحدة دلبة.'),
(2836, 'بلد', 'بلد', 'بلد', 'البلد: كل موضع مستحيز من الأرض، عامر أو غير عامر، خال أو مسكون، والطائفة منه بلدة، والجميع البلاد. والبلد اسم يقع على الكور. والبلد المقبرة، ويقال: هو نفس القبر. وربما عني بالبلد التراب. وبيضة البلد: بيضة تتركها النعامة في قي من البلاد، ويقال: هو أذل من بيضة البلد. وقوله تعالى: لا أقسم بهذا البلد 110 يعني مكة نفسها. وبلدة النحر: الثغرة وما حواليها، قال: أنيخت فألقت بلدة فوق بلدة ... قليل بها الأصوات إلا بغامها 111 والبلدة: موضع [لا نجوم فيه] 112 بين النعائم وسعد الذابح ليس فيه كواكب عظام تكون علما، وهي من منازل القمر، وهي من آخر البروج، سميت بلدة وهي من برج القوس خالية، إلا من كواكب صغار. والبلدة: بلجة ما بين الحاجبين. والبلادة نقيض النفاذ والمضاء في الأمر [ورجل بليد إذا لم يكن ذكيا] 113 ، وفرس بليد، إذا تأخر عن الخيل السوابق، وقد بلد بلادة. والتبلد: نقيض التجلد، وهو من الاستكانة والخضوع، قال: ألا لا تلمه اليوم أن يتبلدا 114 وبلد الرجل أي نكس 115 وضعف في العمل وغيره حتى في الجود، قال: جرى طلقا حتى إذا قيل سابق ... تداركه أعراق سوء فبلدا 116 والمبالدة كالمبالطة بالسيوف والعصي إذا اجتلدوا بها على الأرض، ويقال: اشتق من بلاد الأرض 117 . وبلدوا بها: لزموها فقاتلوا على الأرض. ورجل بالد، في القياس: مقيم ببلده. والأبلاد آثار الوشم في اليد، وبه شبه ما بقي من آثار الدار، قال جرير حي المنازل بالبردين قد بليت ... للحى لم يبق منها غير أبلاد 118'),
(2837, 'لبد', 'لبد', 'لبد', 'لبد يلبد لبودا: لزم الأرض بتضاؤل الشخص. وصبيان الأعراب إذا رأوا سمانى قالوا: سمانى لبادى البدي لا تراعي 119 ، أي لا تفزعي والبدي لا تري، ولا يزالون يقولون ذلك 120 وهي لابدة، ويدورون بها حتى يأخذوها. وكل شعر وصوف تلبد فهو لبد، ولبدة الأسد شعر كثير تلبد على زبرته، وقد يكون مثل ذلك على سنام البعير، قال: كأنه ذو لبد ولهمس 121 واللبادة: لباس من لبود. ولبد آخر نسور لقمان بن عاد وسمي به، أي أنه قد لبد فلا يموت، واللبد واللبد: الرجل اللازم لموضع لا يفارقه. ومال لبد أي لا يخاف فناؤه من كثرته. وصار القوم لبدة ولبدا في شدة ازدحامهم. وما له سبد ولا لبد أي ما له ذو شعر وصوف ووبر من المال أو ما لهم خيل وإبل وبقر فذهبت مثلا.'),
(2838, 'دبل', 'دبل', 'دبل', 'الدبلة شبه كتلة من ناطف أو حيس أو شيء معجون، ودبلته تدبيلا أي جعلته دبلا. والدبيل موضع باليمامة، وجمعه دبل، قال الشاعر: لولا رجاؤك ما تخطت ناقتي ... عرض الدبيل ولا قرى نجران 122'),
(2839, 'بدل', 'بدل', 'بدل', 'البدل: خلف من الشيء، والتبديل: التغيير. واستبدلت ثوبا مكان ثوب، وأخا مكان أخ، ونحو ذلك المبادلة. والأبدال: قوم يقيم الله بهم الدين وينزل الرزق، أربعون بالشام وثلاثون في سائر البلدان، إذا مات واحد منهم يقوم مقامه مثله ولا يؤبه لهم. ويقال: واحد منهم بعقبة حلوان ربي بها، اسمه ذؤيب بن برتملى (كذا) 123 ، ويقال: قرأ القرآن وأبدال الشام. والبأدلة: لحمة بين الإبط والثندوة، والرعثاوان أعاليهما، قال: فتى قد قد السيف لا متآزف ... ولا رهل لباته وبآدله 124'),
(2840, 'دلم', 'دلم', 'دلم', 'الأدلم: الطويل الأسود من الرجال، ومن الجبال 125 كذلك في ملوسة الصخر غير جد شديد السواد، [قال رؤبة: كأن دمخا ذا الهضاب الأدلما يصف جبلا] 126 . وبلاد الديلم معروفة. والديلم: مجتمع النمل والقردان عند أعقاب الحياض وأعطان الإبل.'),
(2841, 'لدم', 'لدم', 'لدم', 'اللدم: ضرب المرأة صدرها وعضديها في النياحة. والالتدام فعلها بنفسها، ولدمت صدرها والتدمت مثله، قال: لدم الغلام وراء الغيب بالحجر 127 وأم ملدم: الحمى، يقال: أنا أم ملدم 128 آكل اللحم وأمص الدم. واللدم: ضربك خبز الملة إذا أخرجته منها. ولدمت الثوب: رقعته. ورجل ملدم ضغن. واللدم واللديم: صوت الشيء يقع على الأرض.'),
(2842, 'دمل', 'دمل', 'دمل', 'الدمال: السرقين ونحوه، وما رمى به البحر من خشارة ما فيه [من الخلق ميتا] 129 نحو الأصداف والمناقيف والنباح 130 ، وهو شيء تتخذ منه سبحة 131 ، قال الكميت في السرقين: رأى إرة منها تحش لفتنة ... وإيقاد راج إن يكون دمالها 132 ويقال: أدملت الأرض أي سمدتها بالسرقين، ودملتها: أصلحتها. وداملت الرجل: داريته لأصلح ما بيننا. واندمل أي تماثل من العلة والجرح، ودمله الدواء. والدمل، ويجمع الدماميل، قال: قذى بعينك أم بظهرك دمل 133 [وأنشد: وامتهد الغارب فعل الدمل] 134'),
(2843, 'ملد', 'ملد', 'ملد', 'الأملد: الشاب الناعم، وامرأة ملداء أملود أملدانية، وشاب أملود أملداني شبه بالقضيب الناعم، قال: بعد التصابي والشباب الأملد 135 والمصدر الملد.'),
(2844, 'دنف', 'دنف', 'دنف', 'الدنف: المرض المخامر الملازم، ورجل دنف، وفعله دنف وأدنف. وامرأة دنفة ورجل مدنف أيضا، فإذا قلت: رجل دنف فالرجل والمرأة فيه سواء وكذلك الجمع لأنه مصدر، قال: والشمس قد كادت تكون دنفا 136 [أي حين اصفرت] 137 .'),
(2845, 'ندف', 'ندف', 'ندف', 'الندف: طرق القطن بالمندف، والفعل يندف. والدابة تندف في سيرها ندفا، وهو سرعة رجع اليدين. والنديف: القطن الذي يباع في السوق مندوفا. [والندف: شرب السباع الماء بألسنتها] 138 . والندف: الأكل السريع بنهمة.'),
(2846, 'فند', 'فند', 'فند', 'الفند: إنكار العقل من هرم، يقال: شيخ مفند، ولا يقال: عجوز مفندة لأنها لم تكن في شبيبتها ذات رأي فتفند في كبرها. وفي التفسير لولا أن تفندون 139 أي تكذبون، وقيل: تعذلون وتجهلون وتوبخون، فصار الفند في مواضع كثيرة الكذب. وأفند: تكلم بالفند من الكلام وبلغ وقت الهرم، قال النابغة: إلا سليمان إذ قال الإله له ... قم في البرية واحددها عن الفند 140 وقال رؤبة: يا أيها القائل قولا فندا 141 والفند: الشمراخ من الجبل.'),
(2847, 'نفد', 'نفد', 'نفد', 'نفد الشيء نفادا أي فني. وأنفد القوم: نفد زادهم، واستنفدوا: نفد ما عندهم.'),
(2848, 'دفن', 'دفن', 'دفن', 'الدفين: المدفون، وتدافن القوم: دفن بعضهم بعضا. والدفن والدفن: بئر أو حوض أو منهل سفت الريح فيه التراب فاندفن. وبئر دفان ودفن، وجمع دفن دفان، قال: دفن وطام ماؤه كالجريال 142 والمدفان: السقاء البالي والمنهل الدفين أيضا، وهو مدفان 143 . والمدفان والدفون من الناس والإبل: الذي يأبق ويذهب على وجهه من غير حاجة ولا أمر، يقال: إن فيه لدفنا. والداء الدفين: الذي لا يعلم حتى يظهر منه شره وعره.'),
(2849, 'فدن', 'فدن', 'فدن', 'الفدن: القصر المشيد، [وجمعه أفدان، وأنشد: كما تراطن في أفدانها الروم] 144 والفدان يجمع أداة ثورين 145 في القران، قال عنترة: فوقفت فيها ناقتي فكأنها ... فدن لأقضي حاجة المتلوم 146'),
(2850, 'ندب', 'ندب', 'ندب', 'الندب: أثر جرح قد أجلب، قال ذو الرمة: ملساء ليس بها خال ولا ندب 147 والندب: الفرس الماضي، وندب ندابة نقيض بلد بلادة. والنادبة تندب بالميت بحسن الثناء: وا فلاناه، وا هناه، والندبة الاسم. والندب إن تندب إنسانا أو قوما إلى أمر في حرب تدعوهم إليه وإلى غيره فينتدبون أي يتسارعون، وانتدبوا له من قبل أنفسهم من غير أن يندبوا. وجرح نديب أي ذو ندب. ورجل ندب: أريب لبيب متيقظ.'),
(2851, 'بدن', 'بدن', 'بدن', 'البدن من الجسد ما سوى الشوى والرأس. والبدن: شبه درع إلا أنه قصير قدر ما يكون على الجسد، قصير الكمين، ويجمع على أبدان، [وقال الله- جل وعز: فاليوم ننجيك ببدنك] 148 . وبدن الرجل: صار بدينا فهو مبدن، ورجل بادن ومبدن وامرأة مبدنة أي سمينان جسيمان. وبدن تبدينا أي أسن. والبدنة: ناقة أو بقرة، الذكر والأنثى فيه سواء، يهدى إلى مكة، والجميع البدن.'),
(2852, 'بند', 'بند', 'بند', 'البند دخيل، ويقال: فلان كثير البنود [أي كثير الحيل] 149 . والبند أيضا كل علم من الأعلام للقائد، والجميع البنود، وتحت كل بند عشرة آلاف [رجل، أو أقل أو أكثر] 150 ، قال: يا صاحب الأعلام والبنود'),
(2853, 'ندم', 'ندم', 'ندم', 'الندم والندامة واحد، وندم فلان فهو نادم سادم، وهو ندمان سدمان أي نادم مهتم، وجمعة ندامى سدامى وندام سدام 151 . ونديم الرجل: شريبه وندمانه 152 ، وجمعه الندماء والندامى. والتندم: التحسر، وهو أن يتبع الإنسان أمرا ندما، وقيل: التقدم قبل التندم.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2854, 'مدن', 'مدن', 'مدن', 'المدينة فعيلة تهمز في الفعائل، لأن الياء زائدة، ولا تهمز ياء المعايش لأن الياء أصلية. [والمدينة اسم مدينة الرسول- عليه السلام- خاصة،] 153 والنسبة إلى المدينة مدني، للإنسان، وحمامة مدينية، فرق بين الإنسان والحمامة. وكل أرض يبنى بها حصن في أصطمتها فهو مدينتها، [والنسبة إليها مدني. ويقال للرجل العالم بالأمر: هو ابن بجدتها، وابن مدينتها، قال الأخطل: ربت وربا في كرمها ابن مدينة ... يظل على مسحاته يتركل 154 وابن مدينة أي العالم بأمرها. ويقال للأمة: مدينة أي مملوكة، والميم ميم مفعول، ومدن الرجل إذا أتى المدينة] 155 .'),
(2855, 'دمن', 'دمن', 'دمن', 'الدمن: ما تلبد من السرقين وصار كرسا على وجه الأرض، وكذلك ما اختلط من البعر والطين عند الحوض، قال لبيد: راسخ الدمن على أعضاده ... ثلمته كل ريح وسبل 156 واسم البقعة وخصوص الموضع الدمنة. والدمنة: ما اندمن من الحقد في الصدر. وفلان يدمن الخمر والشرب أي يديم شربها، ومدمن الخمر: الذي لا يقلع عن شربها. والمدمن: موضع الدمنة من النار.'),
(2856, 'فدم', 'فدم', 'فدم', 'الفدم: العيي عن الحجة والكلام، وفدم فدامة، [والجميع فدم] 157 .، قال الشاعر: فأنكرت إنكار الكريم ولم أكن ... كفدم عبام سيل شيئا فجمجما 158 والفدام: شيء تشده العجم على أفواهها عند السقي، الواحدة فدامة. والفدام: مصفاة الكوز والإبريق ونحوه، وإبريق مفدم ومفدوم قال أبو الهندي: مفدمة قزا كأن رقابها ... رقاب بنات الماء تفزع للرعد 159'),
(2857, 'تر', 'تر', 'تر', 'الترارة: امتلاء الجسم من اللحم، وري العظم، ورجل تار، وقصرة تارة، والفعل تر يتر. والترور: وثبة النواة من الحيس، يقال: تر يتر ترورا. وأتررت يده بالسيف إترارا. [وضرب فلان يد فلان بالسيف فأترها وأطرها وأطنها] 1 . والغلام يتر القلة بمقلاة، [وقال طرفة: تقول وقد تر الوظيف وساقها ... ألست ترى أن قد أتيت بمؤيد] 2 وتر الوظيف أي انقطع فبان وسقط. والترترة أن تقبض على يدي رجل ثم تترتره أي تحركه. والتر كلمة تتكلم بها العرب إذا غضب أحدهم على الآخر، قال: والله لأقيمنك على التر، وهو الحبل الذي يمتد ليمسح به الأرض. والترة: 3 الباطل وهي الترهات أيضا. والتار: الغائب المنفرد من قومه.'),
(2858, 'رت', 'رت', 'رت', 'الرتة: عجلة في الكلام، وتقول: رجل أرت، ورت يرت رتا. والرت: شيء يشبه بالخنزير البري، والجمع الرتوت.'),
(2859, 'تل', 'تل', 'تل', 'التل: الرابية من التراب مكبوس 4 ليس خلقة. والتليل: العنق، [قال لبيد: يتقيني بتليل ذي خصل] 5 أي بعنق ذي خصل. والتليل: الصريع، وجمعه تلى 6 . والتلة: شيء من وصف الإبل. والمتل: القوي الشديد، أسد، وريح متل. وتللته في يديه: دفعته إليه سلما. والتلتلة: الإقلاق [والحركة] 7 . والتلتلة: المشربة تتخذ من قيقاءة الطلع. ورجل متل: منتصب في الصلاة، قال: على ظهر عادي كأن أرومة ... رجال يتلون الصلاة قيام 8 أي يقضونها. وتل فلان فلانا أي صرعه، وما اسوء تلته أي صرعته. وتلوه في قبره متلا أي أوردوه 9 . والتلتلة مثل الترترة في التحريك.'),
(2860, 'لت', 'لت', 'لت', 'اللت: الفعل من اللتات، وكل شيء يلت به سويق وغيره نحو السمن وشبهه. والخيل تلت الحصى لتا.'),
(2861, 'تن', 'تن', 'تن', 'التن: الترب، يقال: صبوة أتنان. والتن: الصبي الذي يقصعه المرض فلا يشب، وقد أتنه المرض. والتنين من الحيات: أعظمها، وربما بعث الله سحابة فاحتملتها، وذلك فيما يقال والله أعلم: أن دواب الأرض تشكوها إلى الله فيرفعها عنها. والتنين: نجم من نجوم الحساب وليس بكوكب ولكنه بياض خفي يكون جسده في شبيه من الماء وذنبه دقيق أسود فيه التواء يكون في البرج السابع من رأسه، وهو يتنقل كتنقل الكواكب الجواري، واسمه بالفارسية هشت أبير في حساب النجوم، وهو من النحوس 10 .'),
(2862, 'تف', 'تف', 'تف', 'التف: وسخ الأظفار، والأف: وسخ الأذن. والتتفيف من التف كالتأفيف من الأف، ويقال: أفة لك، وأف وأف وإف.'),
(2863, 'فت', 'فت', 'فت', 'الفتيت كل شيء مفتوت إلا أنهم خصوا الخبز المفتوت. والفتيت الشيء الذي يقع فينقطع. والفتة: بعرة أو روثة مفتوتة توضع تحت الزندة. والفتات: أن تأخذ الشيء بإصبعك فتصيره فتاتا، أي دقاقا.'),
(2864, 'بت', 'بت', 'بت', 'البت من الطيالسة يسمى الساج، مربع غليظ، لونه أخضر، والجميع البتوت. والبت: القطع المستأصل، يقال: بتت الحبل فانبت أي قطعته. وتقول: أعطيته هذه القطيعة بتا بتلا. والبتة اشتقاقها من القطع، غير أنه مستعمل في كل أمر لا رجعة فيه ولا التواء. وأبت فلان طلاق فلانة، أي طلقها طلاقا باتا. والمجاوز منه الابتات في كل شيء من هذا 11 . ورجل أحمق بات: شديد الحمق. وانقطع فلان عن فلان فانبت وانقبض. [وانبت حبله عنه أي انقطع وصاله وانقبض، وأنشد: فحل في جشم وانبت منقبضا ... بحبله من ذوي العز الغطاريف] 12 [وفي الحديث انه- عليه السلام- كتب لحارثة بن قطن ومن بدومة الجندل من كلب: أن لنا الضاحية من البغل ولكم الضامنة من النخل، ولا يؤخذ منكم عشر البتات] 13 . والبتات يعني متاع البيت. وفي الحديث: أن المنبت لا أرضا قطع ولا ظهرا أبقى، فالمنبت الذي عطب ظهره وبقي منقطعا به. والبتات: الزاد بتته أهله أي زودوه تبتيتا، وتبتتنا أي تزودنا.'),
(2865, 'تب', 'تب', 'تب', 'التب الخسار، وتبأ له، نصب لأنه مصدر محمول على فعله كما تقول: سقيا لفلان، معناه: سقي فلان سقيا، وتب يتب تبابا وتبا، ولم يجمع اسما مسندا إلى ما قبله. وتببت القوم أي قلت لهم: تبا لكم. وتبا لفلان تتبيبا، ويقال: تبا لفلان تبيبا، والتباب الهلاك، قال: أرى طول الحياة وإن تأتى ... تصيره الدهور إلى تباب 14 واستتب له الأمر أي تهيأ. ورجل تاب أي ضعيف، وجمعه أتباب.'),
(2866, 'تم', 'تم', 'تم', 'تم الشيء يتم تماما، وتممه الله تتميما وتتمة. وتتمة كل شيء ما يكون تماما لغايته كقولك: هذه الدراهم تمام هذه المائة، وتتمة هذه المائة. والتم: الشيء التام، يقال: جعلته تما، أي بتمامه. والتميمة: قلادة من سيور، وربما جعلت العوذة التي تعلق في أعناق الصبيان، قال: وكيف يضل العنبري ببلدة ... بها قطعت عنه سيور التمائم [وفي حديث ابن مسعود: أن التمائم والرقى والتولة من الشرك] 15 . وأتممته إتماما: علقت عليه التميمة. واستتم نعمة الله بالشكر. والتمتمة في الكلام ألا يبين اللسان، يخطىء موضع الحرف فيرجع إلى لفظ كأنه التاء والميم. ورجل تمتام. وتمم الرجل إذا صار تميمي الرأي والهوى. والتمام: أطول ليلة في السنة، ويقال: ليلة التمام ثلاث لا يستبان فيها نقصان من زيادة، وقيل: بل ليلة أربع عشرة، وهي ليلة البدر، وهي الليلة التي يتم فيها القمر فيصير بدرا. والتميم في لغة،: التمام، قال رؤبة: جرت تميما لم تخنق جهضا 16 والتميم: الشديد. ويقال: أبى قائلها إلا تما أي أبى إلا أن يتم على ما قال.'),
(2867, 'مت', 'مت', 'مت', 'المت كالمد، إلا أن المت يوصل بقرابة ودالة يمت بها، [وأنشد فقال: إن كنت في بكر تمت خؤولة ... فأنا المقابل في ذرى الأعمام] 17 ومتى اسم والد يونس- عليه السلام- بوزن فعلى، وذلك أنهم لما لم يكن في كلامهم في آخر الاسم بعد فتحة على بناء متى حملوا الياء على الفتحة التي قبلها فجعلوها ألفا [كما يقولون: من غنيت غنى، ومن تغنيت تغنى، وهي بلغة السريانية متي] 18 .'),
(2868, 'ثتن', 'ثتن', 'ثتن', 'وثتن اللحم وتثتن: تغير.'),
(2869, 'ثتل', 'ثتل', 'ثتل', 'الثيتل: الذكر من الأروى، وجمعه ثياتل.'),
(2870, 'رتل', 'رتل', 'رتل', 'الرتل: تنسيق الشيء، وثغر رتل: حسن المتنضد، ومرتل: مفلج. ورتلت الكلام ترتيلا إذا أمهلت فيه وأحسنت تأليفه، وهو يترتل في كلامه، ويترسل إذا فصل بعضه من بعض. والرتيلاء: دابة تسم فتقتل.'),
(2871, 'رتن', 'رتن', 'رتن', 'المرتنة: الخبزة المشحمة، والترتين: خلط الشحم بالعجين.'),
(2872, 'تنر', 'تنر', 'تنر', 'التنور عمت بكل لسان، وصاحبه تنار، وجمعه تنانير.'),
(2873, 'نتر', 'نتر', 'نتر', 'النتر: جذب فيه جفوة، والإنسان ينتتر في مشيه كأنما يجذب جذبا. والنواتر: القسي التي تقطعت أوتارها.'),
(2874, 'ترف', 'ترف', 'ترف', 'الترف: تنعيم الغذاء، وصبي مترف، والمترف: الموسع عليه عيشه، القليل فيه همة، وأترفه الله. والترفة والطرمة في وسط الشفة السفلى، وهي هنة ناتئة خلقة، والنعت أترف. والترفة كل ما ترفت به نفسك تتريفا إذا خففت عنها.'),
(2875, 'فتر', 'فتر', 'فتر', 'فتر فتورا: سكن عن حدته، ولان بعد شدته. وطرف فاتر: فيه فتور وسجو، وليس بحاد النظر. ويجد في جسده فترة، أي ضعفا، كما تقول: كبر فلان كبرا، وعليه كبرة والفتر: مقدار ما بين طرف الإبهام وطرف المشيرة، وفترت الشيء فترا بفتري، وشبرته شبرا بشبري. والفترة: ما بين كل رسول إلى رسول.'),
(2876, 'رفت', 'رفت', 'رفت', 'رفت الشيء بيدي رفتا فارفت كما يرفت العظم البالي والمدر ونحوه حتى يصير رفاتا فيترفت أي يتكسر.'),
(2877, 'فرت', 'فرت', 'فرت', 'ماء فرات أي عذب، والفروتة مصدر، ولو قيل: ماء فرت، لكان صوابا.'),
(2878, 'رتب', 'رتب', 'رتب', 'الرتوب: الانتصاب كما يرتب الصبي الكعب إرتابا، والمصلي يرتب أي ينتصب. والرتب: ما أشرف من الأرض كالدرج. ورتبة كقولك: درجة، ويجمع على رتب كما يقال: درج سواء. والرتبة واحدة من رتبات الدرج. ورتبته ورتبته سواء. والمرتبة: المنزلة عند الملوك ونحوها. وترتب فلان أي علا رتبة أي درجة. والمراتب في الجبال والصحارى من الأعلام التي يرتب عليها العيون والرقباء. وما في عيشه رتب ولا في هذا الأمر [رتب ولا عتب] 19 أي: هو سهل مستقيم. وقوله: وكان لنا فضل على الناس ترتبا 20 أي جميعا، ويقال: ثابتا 21 .'),
(2879, 'ترب', 'ترب', 'ترب', 'التراب والترب واحد، وإذا أنثوا قالوا: تربة. وأرض طيبة التربة أي خلقة ترابها، فإذا أردت طاقة واحدة، قلت: ترابة واحدة، ولا تدرك بالبصر إلا بالتوهم. ولحم ترب إذا تلوث بالتراب، [ومنه حديث علي- عليه السلام-: لئن وليت بني أمية لأنفضنهم نفض القصاب الوزام التربة] 22 . وتربت الكتاب تتريبا. والتيرب: التراب. وقوله: وهذا الشيء عليك ترتب أي واجب. وأترب الرجل إذا كثر ماله. وفي الحديث: تربت يداك أي هو الفقر، وترب إذا خسر، وأترب: استغنى. والترباء: نفس التراب، قال: لأضربنه حتى يعض بالترباء. وريح تربة: حملت ترابا. [وفي الحديث: خلق الله التربة يوم السبت، وخلق فيها الجبال يوم الأحد، والشجر يوم الاثنين] 23 . والترب والتريب: اللدة، وهما تربان، وقوله- عز وجل-: عربا أترابا 24 أي نشاطا أمثالا. والتريبة: ما فوق الثندوتين إلى الترقوتين، وقيل: كل عظم منه تريبة، وتجمع الترائب.'),
(2880, 'تبر', 'تبر', 'تبر', 'التبر: الذهب والفضة قبل أن يعملا. ويقال: كل جوهر قبل أن يستعمل تبر من النحاس والصفر، كل قوم صيغة من تبرهم ... وبنو عبد مناف من ذهب 25 والتبار: الهلاك والفناء، وتبر يتبر تبارا، وتبرهم الله تتبيرا.'),
(2881, 'بتر', 'بتر', 'بتر', 'البتر: قطع الذنب ونحوه إذا استأصلته. وأبترت الدابة فبترت، وأبترت الذنب وبترته، وبترت الشيء فانبتر. والأبتر: الذي لا عقب له، ومن ذلك قوله عز وجل: إن شانئك هو الأبتر 26 . برت: البرت: الفأس بلغة اليمن، والبرت بلغتهم السكر الطبرزد. وقال مزاحم: المبرت والبريت في شعر رؤبة اسم اشتق من البرية في قوله: ينشق عني الخرق والبريت فكأنما أسكن الياء فصارت الهاء تاء فغلبت، وجعله اسما للبرية، وهو الصحراء، والجمع البراريت، فصارت التاء كأنها أصلية في التصاريف كما لزمت التاء في عفريت. والبرت: الدليل الهادي ولم أسمع له جمعا.'),
(2882, 'رتم', 'رتم', 'رتم', 'الرتم خيط يعقد على الإصبع أو الخاتم للعلامة وهي الرتيمة. والرتمة: نبات من دق الشجر، ومن دقته شبه بالرتم، ورتمت ارتم رتما، قال: هل ينفعنك اليوم إن همت بهم ... كثرة ما توصي وتعقاد الرتم 27'),
(2883, 'مرت', 'مرت', 'مرت', 'مرت: أرض مرت، ومكان مرت بين المروتة، قال: مرت يناصي خرقها مروت 28'),
(2884, 'متر', 'متر', 'متر', 'المتر: السلح إذا رمي به. والنار إذا قدحت رأيتها تتماتر أي تتساقط.'),
(2885, 'تمر', 'تمر', 'تمر', 'أتمرت النخلة، وأتمر الرطب، [والتمر حمل النخلة] 29 . والتتمير: القديد ييبس فيصير تتميرا، اسما له. وتمرني فلان: أطعمني تمرا، ويقال عليك بالتمران والسمنان. ورجل تامر إي ذو تمر. والتمرة: طائر أصغر من العصفور. والمتمئر 30 : الشاب. وتمرة الغراب: أطيب التمر لأنه لا يقصد إلا الطيب فإذا سقطت بادروا إلى أخذها.'),
(2886, 'نتل', 'نتل', 'نتل', '[قال الأعشى: لا يتنمى لها في القيظ يهبطها ... إلا الذين لهم، فيما أتوا، نتل] 31 زعموا إن العرب كانوا يملؤون بيض النعام ماء في الشتاء ويدفنونها في الفلوات البعيدة من الماء، فإذا سلكوها في القيظ استثاروا البيض وشربوا ما فيها من الماء، فذلك النتل. والنتل: الجذب إلى قدم، واستنتل الرجل من بين أصحابه أي تقدم 32 . ونتلت الجراب: نثرت ما فيها.'),
(2887, 'تلف', 'تلف', 'تلف', 'التلف: عطب وهلاك في كل شيء، والفعل تلف يتلف تلفا. وفي الحديث: القرف أدنى للتلف ، يريد بالقرف أمرا يتهمه ويتخوف عاقبته 33 . والمتلفة: مهواة مشرفة على تلف، والمتالف: المهالك. وأتلف فلان ماله: أفناه إسرافا، [وقال: الفرزدق: وقوم كرام قد نقلنا إليهم ... قراهم فأتلفنا المنايا وأتلفوا] 34 وأتلفنا المنايا: وجدناها ذات تلف أي ذات إتلاف ووجدناها كذلك.'),
(2888, 'لفت', 'لفت', 'لفت', 'اللفت: لي الشيء عن جهته كما تقبض على عنق إنسان فتلفته، قال رؤبة: ولفت كسار العظام خضاد 35 واللفت والفتل واحد. ولفت فلانا عن رأية أي صرفته عنه، ومنه الالتفات ويقال: لفت فلان مع فلان، كقولك صغوه معه، ولفتاه شقاه. [وفي حديث حذيفة: من أقرأ الناس للقرآن منافق لا يدع منه واوا ولا ألفا، يلفته بلسانه كما تلفت البقرة الخلا بلسانها] 36 . والألفت من التيوس: الذي قد أعوج قرناه والتويا. واللفوت: العسر الخلق 37 . والفيتة: مرق يشبه الحيس، وقريبا منه. قال أبو الدقيش: اللفوت من النساء التي لها زوج وولد من زوج آخر، فهي تلتفت إلى الولد.'),
(2889, 'فلت', 'فلت', 'فلت', 'الفلتة آخر يوم من الشهر الذي بعده الشهر الحرام كآخر يوم من جمادى الآخرة وذلك أن الرجل يرى فيه ثأره، فربما توانى فيه، فإذا كان الغد، دخل الشهر الحرام ففاته، فيسمى ذلك اليوم فلتة، قال: فسائل لقيطا وأشياعها ... ولا تدعن واسألن جعفرا غداة العروبة من فلتة ... لمن تركوا الدار والمحضرا 38 والفلتة: الأمر الذي يقع من غير إحكام، يقال: كان ذلك الأمر فلتة أي مفاجأة. وأفلتني فلان أي انفلت مني، وأفلتني أيضا: خلصني 39 . وتفلت فلان إلى فلان، وإلى هذا الأمر أي نازع إليه. وفرس 40 فلتان صلتان أي نشيط حديد الفؤاد. وتفلت إلى الشر: تعرض له، والفلتان: المفلت إلى الشر، والفلتان جمع. وثوب فلوت: لا ينضم طرفاه من صغره يفلت من اليد. [وأفلت فلان بجريعة الذقن يضرب مثلا للرجل يشرف على هلكة، ثم يفلت كأنه جرع الموت جرعا ثم أفلت منه. والإفلات يكون بمعنى الانفلات لازما، وقد يكون واقعا، يقال: افلته من الهلكة أي خلصته] 41 .'),
(2890, 'تفل', 'تفل', 'تفل', 'التفل: رميك بالبزاق، والتفل: البزاق نفسه. والتفل: سوء ريح جلد الإنسان، ورجل تفل، وامرأة تفلة متفال. والتتفل 42 الثعلب.'),
(2891, 'فتل', 'فتل', 'فتل', 'ناقة فتلاء إذا كان في ذراعها فتل وبانت عن الجنب. والفتيل: سحاة في شق النواة. وتفتل الشعر أي التوى بعضه ببعض. والفتل: لي الشيء كليك الحبل، وفتل الفتيلة فتلا.'),
(2892, 'تبل', 'تبل', 'تبل', 'التبل: الذحل، وتبلني فلان، أي وترني. وتبلهم الدهر: رماهم بصروف الموت، قال: ودهر خابل تبل والرجل يعشق المرأة فتتبل فؤاده ثم لم تبله. وتوبلت القدر توبلة: جعلت فيه التوابل، الواحد تابل 43 .'),
(2893, 'بتل', 'بتل', 'بتل', 'البتل: كلمة توصل بالبت، تقول: أعطيته بتا بتلا، وأصله القطع، وبتلته: قطعته. وتبتل إليه تبتيلا ، فالتبتل الانقطاع إلى الله تعالى، أي أخلص إليه إخلاصا. والبتول: كل امرأة تنقبض عن الرجال فلا حاجة لها فيهم ولا شهوة، ومنه التبتل وهو ترك النكاح، [قال ربيعة بن مقروم الضبي: لو أنها عرضت لأشمط راهب، ... عبد الإله، صرورة متبتل] 44 ونخل متبتل: قد تدلت عذوقه. والبتيل: فسيل النخل يبتل عنه أي يقطع عنه ويعزل. والبتيلة: كل عضو بلحمه مكتنز من أعضاء اللحم على حياله، قال: إذا المتون مدت البتائلا 45 وامرأة مبتلة: تامة الأعضاء والخلق، وجمل مبتل، وناقة مبتلة. والبتل: أسفل الجبل، الواحد بتيل. [والبتل: تمييز الشيء من الشيء] 46 .'),
(2894, 'بلت', 'بلت', 'بلت', 'المبلت بلغة حمير: المهر المضمون، قال: وما زوجت إلا بمهر مبلت 47'),
(2895, 'تلب', 'تلب', 'تلب', 'التلب: كلمة توصل بالتب، يقال: تبا له تبا تلبا. واتلأب صدره على الطريق أي استقام.'),
(2896, 'لتب', 'لتب', 'لتب', 'اللتب: اللبس، ولتب عليه ثوبه، والتتب وهو لبس كأنه لا يريد أن يخلعه. ولتب عليك لتوبا أي ثبت.'),
(2897, 'تلم', 'تلم', 'تلم', 'التلم: مشق الكراب في الأرض بلغة اليمن، والجميع الأتلام. والتلام: الصاغة، والواحد تلم 48 .'),
(2898, 'لتم', 'لتم', 'لتم', 'اللتم: طعن منحر البعير بالشفرة، يقال: لتم نحره، ولطم خده، ولدم صدره.'),
(2899, 'تمل', 'تمل', 'تمل', 'التميلة: دويبة تكون بالحجاز مثل الهر، والجميع التملان 49 . والتملول: البرغست بلسان العجم، والغملول أيضا مثل المتل من الرماح وغيره، مفعل من تل، وهو الدفع، وتل في يده شيئا أي دفع.'),
(2900, 'نتف', 'نتف', 'نتف', 'النتف: نزع الشعر والريش وما أشبهها، والنتافة ما انتتف من ذلك. وأنتف الشيء: أمكن نتفه.'),
(2901, 'نفت', 'نفت', 'نفت', 'نفتت القدر تنفت نفتانا إذا غلا المرق فيها فلزق بجوانب القدر فيبس عليه، فذلك النفت، وانضمامه النفتان حيث يهم المرق بالغليان 50 ، يقال: نفتت القدر إذا رمت مثل السهام تنفت نفتا.'),
(2902, 'تنف', 'تنف', 'تنف', 'التنوفة: الأرض القفر، والجميع التنائف.'),
(2903, 'فتن', 'فتن', 'فتن', 'فتن فلان يفتن فهو فاتن أي مفتتن، والفتون مصدره، وهو اللازم، ويقال: فتنة غيره، وأنشد: رخيم الكلام قطيع الرجام ... أمسى فؤادي بها فاتنا 51 أي مفتتنا. والفتن: إحراق الشيء بالتار كالورق الفتين أي المحترق، وقوله تعالى: يوم هم على النار يفتنون 52 ، أي يحرقون. وكان أصحاب النبي- صلى الله عليه و [على] اله وسلم- يفتنون بدينهم، أي يعذبون ليردوا عن دينهم، ومنه قوله تعالى: والفتنة أشد من القتل 53 ، والفتنة: العذاب. والفتنة: أن يفتن الله قوما أي يبتليهم. والفتن: ما يقع بين الناس من الحروب، ويقال في أمر العشق: فتن بها وافتتن بها أي عشقها. والفتان: الشيطان، والفتان جماعة. وقوله تعالى: ما أنتم عليه بفاتنين 54 ، أي مضلين، عن الحسن ومجاهد. وفتن وأفتن واحد، قال: لئن فتنتني لهي بالأمس أفتنت ... سعيدا فأمسى قد قلا كل مسلم 55 أي اختارها على كل مسلم، وقول امرىء القيس: كأني ورحلي والفتان ونمرقي 56 أي غاشية الرحل.'),
(2904, 'تبن', 'تبن', 'تبن', '[التبن: يروي العشرين وهو أعظم الأقداح، ثم الصحن، مقارب له، ثم العس يروي الثلاثة والأربعة] . والتبن: العس الضخم في قول أبي المقدام لقوله: ثم تبنا رأيته مكيالا 57 ورجل تبن فطن وطبن، وقيل: التبن: الفطن في الخير، والطبن في الشر. وتبن: ذو تبن وتبانة. وتبن لفلان أي فطن لوجه غيلته وخديعته. وهو تبن بالخير، لا يقال منه فاعل. ويقال: تبنت أي دققت النظر في الأمور، ولا يقال للأمر اللازم في القلب: إن في قلبه لأمرا تبنا. والتبان: شبه سراويل، والتبابين: الأقبية القصار الأكمام 58 . والتبن معروف، والواحدة تبنة، والتبن لغة.'),
(2905, 'بنت', 'بنت', 'بنت', 'ومنه قول امرىء القيس: غير بانات على وتره 59 ويقال: هو بانات على هذا الأمر، أي مقبل عليه بنفسه، منكب. ويقال: البانات هاهنا كل قطعة من العقب بانه. ويقال: أراد: بائنة. ثم رجع إلى بانات بلغته.'),
(2906, 'نبت', 'نبت', 'نبت', 'النبت: الحشيش، والنبات فعله، ويجري مجرى اسمه. [تقول: أنبت الله النبات إنباتا ونباتا، ونحو ذلك] . والرجل ينبت الحب تنبيتا، إذا غرسه وزرعه. والنبتة: ضرب من فعل النبات لكل شيء، تقول: إنه لحسن النبتة. والمنبت: الأصل، والموضع الذي ينبت فيه الشيء، وقول الله تعالى: والله أنبتكم من الأرض نباتا 60 ، ويفسر كالنبات. وأحسن من ذلك قال: ترى الفتى ينبت إنبات الشجر 61 أي كما أنبتكم فنبتم نباتا، وربما رفعوا مصدرا إلى فعل غيره بعد إن يكون الاشتقاق واحدا، قال: ترى الفتى ينبت إنبات الشجر أي كما أنبت الله الشجر، ونحو ذلك قول رؤبة: صحراء لم ينبت بها تنبيت 62 بكسر التاء وتغيير البناء، وكل صواب. والرجل ينبت الجارية، أي يغذوها ويحسن القيام عليها رجاء فضل ربحها. والينبوت: شجر الخشخاش، الواحدة ينبوتة وخشخاشة وخروبة. والنبيت: حي من الأنصار.'),
(2907, 'تنم', 'تنم', 'تنم', 'التنوم: شجر له حمل صغاره كمثل خلقه الخروع، ينفلق عن حب يأكله أهل البادية، وكيفما زالت الشمس تبعها بأعراض الورق.'),
(2908, 'متن', 'متن', 'متن', 'المتن والمتنة لغتان، يذكر ويؤنث، وهما متنتان لحمتان معصوبتان بينهما صلب الظهر معلوتان بعقب، والجميع المتون. ومتنته: ضربت متنه بالسياط. والمتين: القوي من كل شيء، ومتن متانة. والمتن في الأرض: ما ارتفع وصلب، وجمعه متان. ومتن كل شيء: ما ظهر منه، ومتن القدر والمزادة: وجهها البارز. والمتن: متن السيف. والمماتنة: المباعدة في الغاية، وسار سيرا مماتنا، أي بعيدا. والمتن: أن يشقق صفن الدابة فيستخرج أنثياه بعروقهما، ومتنته متنا، فالدابة ممتون.'),
(2909, 'بتم', 'بتم', 'بتم', 'البتم 63 : بلاد بناحية فغانة، ويقال: حصن.'),
(2910, 'ظر', 'ظر', 'ظر', 'الظر: قطعة حجر لها حد كحد الفأس والسكين، وتقول: ظررت مظرة، وذلك أن الناقة إذا أبلمت وهو داء يأخذها في حلقة الرحم فيضيق، فيأخذ الراعي مظرة، ويدخل يده في بطنها من ظبيتها ثم يقطع من ذلك الموضع هنة مثل الثؤلول. وقد يقال للحجر ظرر، يذكر إذا كان محددا، والجميع الظران، وقيل: الظران جمع الظرير، نعت كالحزين والحزان، غير أن الظران أعظم حجارة، وهي أشد من المرد، وهي حجارة القداح، وأشد بياضا وادق. والأظرة من الأعلام التي يهتدي بها مثل الأمرة، ومنها ما يكون ممطولا صلبا تتخذ منه الرحى.'),
(2911, 'ظل', 'ظل', 'ظل', '[ظل فلان نهاره صائما، ولا تقول العرب: ظل يظل الا لكل عمل بالنهار، كما لا يقولون: بات يبيت إلا بالليل، ومن العرب من يحذف لام ظللت ونحوها حيث يظهران] 1 ، فأما أهل الحجاز فيكسرون الظاء على كسرة اللام التي ألقيت، فيقولون ظلنا وظلتم، والمصدر الظلول، [والأمر منه ظل واظلل، وقال الله- جل وعز-: ظلت عليه عاكفا 2 وقرىء: ظلت عليه، فمن فتح فالأصل فيه ظللت عليه، ولكن اللام حذفت لثقل التضعيف والكسر، وبقيت الظاء على فتحها، ومن قرأ: ظلت، بالكسر، حول كسرة اللام على الظاء، وقد يجوز في غير المكسور نحو: همت، بذاك أي هممت، وأحست تريد أحسست، وحلت في بني فلان، بمعنى حللت وليس بقياس إنما هي أحرف قليلة معدودة] 3 . وتميم تقول: ظلت. وسواد الليل يسمى ظلا، قال: وكم هجعت وما أطلقت عنها ... وكم دلجت وظل الليل داني 4 ومكان ظليل: دائم الظل دامت ظلاله. والظلة كهيئة الصفة، وعذاب يوم الظلة، يقال: عذاب يوم الصفة، والله أعلم. والمظلة: البرطلة، والظلة والمظلة سواء وهما ما يستظل به من الشمس، ويقال: مظلة. والإظلال: الدنو، يقال: أظلك فلان، أي كأنه ألقى عليك ظله من قربه، [وأظل شهر رمضان، أي دنا منك] 5 . ويقال: لا يجاوز ظلي ظلك. وملاعب ظله: طائر يسمى بذلك، وهما ملاعبا ظلهما وملاعبات ظلهن في لغة، فإذا جعلته نكرة أخرجت الظل على العدة فقلت: هن ملاعبات [أظلالهن] . والأظل: باطن منسم البعير، والجميع الأظلال، قال: تشكو الوجى من أظلل وأظلل 6 أظهر التضعيف، وإنما هو أظل، [وقال ذو الرمة: دامي الأظل بعيد السأو مهيوم] 7 والظل لون النهار تغلب عليه الشمس. والظل من الخيال ستر من الجن. والمظلمة تتخذ من الخشب يستظل بها. والظليلة: مستنقع ماء قليل في مسيل، وينقطع السيل ويبقى ذلك الماء فيه، قال رؤبة: غادرهن السيل في ظلائلا 8'),
(2912, 'لظ', 'لظ', 'لظ', 'الإلظاظ: الإلحاح على الشيء، وألظ به، ومنه الملاظة في الحرب. ورجل ملظاظ: ملظ شديد الإيلاع بالشيء، ملج، قال: عجبت والدهر له لظيظ ويقال: رجل كظ لظ، أي عسر متشدد. والتلظلظ واللظلظة من قولك: حية تتلظلظ، وهو تحريك رأسها من شدة اغتياظها. وحية تتلظى من خبثها وتوقدها، والحر يتلظى كأنه يلتهب مثل النار، وسميت النار لظى من لزوقها بالجلد، ويقال: اشتقاقه من الإلظاظ، فأدخلوا الياء كما أدخلوها على الظن فقالوا: تظنيت، وإنما هو: تظننت، وفي الحديث: ألظوا بيا ذا الجلال والإكرام أي سلموا بها وداوموا عليها، أي على هذه الكلمة. [وأما قولهم في الحر: يتلظى فكأنه يتلهب كالنار من اللظى] 9 .'),
(2913, 'ظن', 'ظن', 'ظن', 'الظنين: المعادي، والظنين: المتهم، والاسم الظنة. وهو موضع ظنتي أي تهمتي، واضطننت: افتعلت. والظنون: الرجل السيء الظن بكل أحد. والتظني: التحري، وهو من التظنن، حذفت النون الأخيرة وجعلوا اشتقاق الفعل على ميزان تفعلي، قال: فليس يرد فدفدها التظني 10 والظنون: البئر التي لا يدرى أفيها ماء أم لا. والظن يكون بمعنى الشك وبمعنى اليقين كما في قوله تعالى: يظنون أنهم ملاقوا ربهم 11 أي يتيقنون. وقد يجعل الظن اسما فيجمع كقوله: أتيتك عاريا خلقا ثيابي ... على دهش تظن بي الظنون 12 وتقول: اطننته وتظننت عنده، أردت افتعلت فصيرت التاء طاء ثم أدغمت الظاء في الطاء حتى حسن الكلام، ولو تركت الظاء مع التاء لقبح اللفظ. وفلان يطن به، أي يفتعل، أي يتهم به، مدغمة، فثقلت الظاء مع الطاء فقلبت طاء، قال: وما كل من يطنني أنا معتب ... ولا كل ما يروى علي أقول 13'),
(2914, 'فظ', 'فظ', 'فظ', 'رجل فظ: ذو فظاظة، أي فيه غلظ في منطقه وتجهم [والفظظ خشونة في الكلام] 14 . والفظ: ماء الكرش، والعرب إذا اضطرت شقوا الكرش وشربوا منها الماء، ويقال: افتظ ماءها وافتظوا ماءها.'),
(2915, 'ظب', 'ظب', 'ظب', 'قولهم: ما به ظبظاب أي قلبته، يريد به الداء. والظابان، يقال،: السلفان المتزوجان بأختين.'),
(2916, 'بظ', 'بظ', 'بظ', 'بظ يبظ أوتاره بظا، وهو تحريك الضارب أوتاره ليهيئها للضرب، وفي لغة بالضاد، والظاء أحسن. ويقال: بظ على كذا، أي ألح عليه، ويقال: بظي يبظى بظى 15 فهو باظ إذا اكتنز لحما وسمنا.'),
(2917, 'مظ', 'مظ', 'مظ', 'المظ شجرة الرمان، والمماظة المشارة والمنازعة، وماظظته وشاررته، وكذلك المظاظ. قال: إن لليلى غلمة غلاظا ... معاودين عندها المظاظا 16'),
(2918, 'نظر', 'نظر', 'نظر', 'نظر إليه ينظر نظرا، ويجوز التخفيف في المصدر تحمله على لفظ العامة 17 في المصادر، وتقول: نظرت إلى كذا وكذا من نظر العين ونظر القلب. وقوله تعالى: ولا ينظر إليهم يوم القيامة 18 ، أي لا يرحمهم. وقد تقول العرب: نظرت لك، أي عطفت عليك بما عندي، وقال الله- عز وجل: لا ينظر إليهم، ولم يقل: لا ينظر لهم فيكون بمعنى التعطف. ورجل نظور: لا يغفل عن النظر إلى ما أهمه. والمنظرة: موضع في رأس الجبل فيه رقيب يحرس أصحابه من العدو. ومنظرة الرجل: مرآته إذا نظرت إليه أعجبك أو ساءك، وتقول: إنه لذو منظرة بلا مخبرة. والمنظر مصدر كالنظر، وإن فلانا لفي منظر ومسمع أي فيما أحب النظر إليه والاستماع، قال: لقد كنت عن هذا المقام بمنظر 19 أي بمعزل فيما أحببت. وقال أبو زبيد لغلامه وكان في خفض ودعة، فقاتل حيا من الأراقم فقتل: قد كنت في منظر ومستمع ... عن نصر بهراء غير ذي فرس 20 [والمنظر: الشيء الذي يعجب الناظر إذا نظر إليه فسره] 21 . [وتقول العرب: إن فلانا لشديد الناظر إذا كان بريئا من التهمة، ينظر بملء عينيه، وشديد الكاهل أي منيع الجانب] 22 . والنظرة من الجن تصيب الإنسان مثل الخطفة 23 ، ونظر فلان: أصابته نظرة فهو منظور. ونظار كقولك انتظر، اسم وضع في موضع الأمر. وناظر العين: النقطة السوداء الخالصة في جوف سواد العين، [وبها يرى الناظر ما يرى] 24 . ونظير الشيء: مثله لأنه إذا نظر إليهما كأنهما سواء في المنظر وفي التأنيث نظيرة، وجمعه نظائر، وتقول: ما كان هذا نظيرا لهذا، ولقد انظر به وما كان خطيرا، ولقد أخطر به. ويقول القائل للمؤمل يرجوه: إنما أنظر إلى الله ثم إليك، أي أتوقع فضل الله ثم فضلك. ونظرت فلانا وانتظرته بمعنى، فإذا قلت: انتظرت فلم يجاوزك فعله فمعناه وقفت وتمهلت 25 ونحو ذلك. وتقول: انظرني يا فلان، أي استمع إلي، وكذلك قوله تعالى: وقولوا انظرنا 26 . ويقول المتكلم لمن يعجله: انظرني ابتلع ريقي. وبعث فلان شيئا فأنظرته، أي أنشأته، والاسم منه النظرة. واشتريته بنظرة أي بانتظار، وقوله- جل وعز-: فنظرة إلى ميسرة 27 ، أي إنظار. واستنظر المشتري فلانا: سأله النظرة. والتنظر: توقع من ينتظره. وبفلان نظرة، أي سوء هيئة. [والمناظرة: أن تناظر أخاك في أمر إذا نظرتما فيه معا كيف تأتيانه؟] 28 .'),
(2919, 'ظرف', 'ظرف', 'ظرف', 'ظرف يظرف ظرفا، وهم الظرفاء، وفتية ظروف في الشعر أحسن ونسوة ظراف وظرائف. والظرف وهو البراعة وذكاء القلب، لا يوصف به السيد والشيخ إلا الفتيان الأزوال، والفتيات الزولات، ويجوز في الشعر ومصدره الظرافة. والظرف: وعاء كل شيء، حتى الإبريق ظرف لما فيه. والصفات نحو أمام وقدام تسمى ظروفا، تقول: خلفك زيد، إنما انتصب لأنه ظرف لما فيه وهو موضع لغيره.'),
(2920, 'ظفر', 'ظفر', 'ظفر', 'جماعة الأظفار أظافير، لأن الأظفار بوزن الأعصار، وتقول: أظافير وأعاصير، وإن جاء بعض ذلك في الأشعار جاز كقوله: حتى تغامز ربات الأخادير 29 أراد جماعة الأخدار، والأخدار جماعة الخدر. ويقال للرجل القليل الأذى: إنه لمقلوم الظفر. ويقال للرجل المهين الضعيف: إنه لكليل الظفر أي لا ينكي عدوا، قال: لست بالفاني ولا كل الظفر 30 وظفر فلان في وجه فلان إذا غرز ظفره في لحمه فعقره، وكذلك التظفير في القثاء والبطيخ والأشياء كلها، وإن قلت: ظفره فجائز. والأظفار: شيء من العطر شبيه بالظفر مقتلع من أصله يجعل في الدخنة لا يفرد منه الواحد، وربما قالوا: أظفارة واحدة، وليس بجائز في القياس. ويجمعونها على أظافير، وهذا في الطيب، وإذا أفرد شيء من نحوها ينبغي أن يكون ظفرا وفوها وهم يقولون: أظفار وأظافير وأفواه وأفاويه لهذين العطرين. والظفرة: جليدة تعشى العين تنبت من تلقاء المآقي، وربما قطعت، وإن تركت غشيت بصر العين حتى يكل. ويقال: ظفر فلان فهو مظفور، وعين ظفرة، وقد ظفرت عينه. والظفر: الفوز بما طالبت، والفلج على من خاصمت، وظفرت بفلان ظفرا فأنا ظافر، وظفر الله فلانا على فلان، وأظفره إظفارا مثله. وفلان مظفر أي لا يؤوب الا بالظفر فثقل نعته للكثرة والمبالغة، وإن قيل: ظفر الله فلانا أي جعله مظفرا جاز، وظفرت فلانا تظفيرا، أي دعوت له بالظفر، وظفرته على فلان: غلبته عليه، وذلك إذا سئل: أيهما ظفر فأخبر عن واحد غلب الآخر فقد ظفره. وظفره بالأظفار: خدشه بها.'),
(2921, 'ظلف', 'ظلف', 'ظلف', 'الظلف: ظلف البقرة وما أشبهها مما يجتر، وهو ظفرها. غير أن عمرو بن معديكرب قال اضطرارا: وخيلي تطأكم بأظلافها 35 أي بحوافرها. والأظلوفة: أرض ذات حجارة حداد إذا كانت خلقة تلك الأرض جبلا، وجمعه أظاليف. ومكان ظليف خشن فيه رمل كثير. والظلفة: طرف حنو القتب وحنو الإكاف وأشباه ذلك مما يلي الأرض من جوانبها. وظلفته عن هذا الأمر ظلفا إذا طمع في شيء لا يجمل به فكففته، قال: لقد أظلف النفس عن مطعم ... إذا ما تهافت ذبانه 36 والظليف: الذليل السيء الحال في معيشته. [وذهب به مجانا وظليفا إذا أخذه بغير ثمن، وأنشد: أيأكلها ابن وعلة في ظليف ... وبأمن هيثم وابنا سنان] 37'),
(2922, 'لفظ', 'لفظ', 'لفظ', 'اللفظ: الكلام ما يلفظ بشيء الا حفظ عليه. واللفظ: أن ترمي بشيء كان في فيك، والفعل لفظ يلفظ لفظا. والأرض تلفظ الميت أي ترمي به، والبحر يلفظ الشيء يرمي به إلى الساحل، والدنيا لافظة ترمي بمن فيها إلى الآخرة. وفي المثل: أسخى من لافظة يعني الديك. ولفظ فلان: مات. كل طائر يزق فرخه فهو لافظه 38'),
(2923, 'ظلم', 'ظلم', 'ظلم', 'تقول: لقيته أول ذي ظلم، وهو إذا كان أول شيء سد بصرك في الرؤية، ولا يشتق منه فعل، ويقال: لقيته أدنى ظلم. والظلم: الثلج، ويقال الماء الجاري على الأسنان من صفاء اللون لا من الريق، قال كعب: تجلو عوارض ذي ظلم إذا ابتسمت 39 ويقال: الظلم ماء البرد، ويقال: الظلم صفاء الأسنان وشدة ضوئها، قال: إذا ما رنا الرائي إليها بطرفه ... غروب ثناياها أضاء وأظلما 40 والظليم: الذكر من النعام، والجميع الظلمان، والعدد أظلمة. والظلم: أخذك حق غيرك. والظلامة: مظلمتك تطلبها عند الظالم. وظلمته تظليما إذا أنبأته إنه ظالم. وظلم فلان فاظلم، أي احتمل الظلم بطيب نفسه، افتعل وقياسه اظتلم فشدد وقلبت التاء طاء فأدغمت الظاء في الطاء، وإن شئت غلبت الظاء كما غلبت الطاء. وإذا سئل السخي ما لا يجد يقال هو مظلوم، قال زهير:'),
(2924, 'نظف', 'نظف', 'نظف', '[النظافة: مصدر النظيف، والفعل اللازم منه: نظف، والمجاوز: نظف ينظف تنظيفا. واستنظف الوالي ما عليه من الخراج، أي: أستوفى، ولا يستعمل التنظيف في هذا المعنى] 49'),
(2925, 'ظنب', 'ظنب', 'ظنب', 'الظنبوب: حرف الساق اليابس من قدم 50 . والظنبوب: مسمار يكون في حبة السنان حيث يركب في عالية الرمح، والجميع الظنابيب، قال سلامة: إنا إذا ما أتانا صارخ فزع ... كانت إجابتهم قرع الظنابيب 51 عنى بالبيت إن تقرع ظنابيب الخيل بالسياط ركضا إلى العدو، وقيل: عنى قرع الظنبوب أي المسمار في جبة السنان حيث يركب، كل قد قيل، واسم ذلك المسمار الكلب.'),
(2926, 'ذر', 'ذر', 'ذر', 'الذر: صغار النمل. والذر مصدر ذررت وهو أخذك الشيء بأطراف أصابعك تذره ذر الملح على الخبز، وتذر الدواء في العين، والذرور اسم الدواء اليابس للعين. والذريرة: فتات قصب من الطيب يجاء به من الهند، كأنه قصب النشاب. والذرارة: ما تناثر من الشيء الذي تذره. والذرية فعلية من ذررت لأن الله ذرهم في الأرض فنثرهم فيها، كما أن السرية من تسررت، والجميع الذراري، وإن خفف جاز. وذرور الشمس: طلوعها وسقوطها على الأرض، وذر قرن الشمس، أي طلع، قال: صورة الشمس على صورتها ... كلما تغرب شمس أو تذر 1'),
(2927, 'رذ', 'رذ', 'رذ', 'الرذاذ: مطر كالغبار، واحدها رذاذة. ويوم مرذ، وأرذت السماء إرذاذا ورذاذا.'),
(2928, 'ذل', 'ذل', 'ذل', 'الذل مصدر الذلول أي المنقاد من الدواب، ذل يذل، ودابة ذلول: بينة الذل، ومن كل شيء أيضا، وذللته تذليلا. ويقال للكرم اذا دليت عناقيده: قد ذلل تذليلا. والذل: مصدر الذليل، ذل يذل وكذلك الذلة. والذلذل: أسفل القميص والقباء ونحو ذلك، ويقال: شمر ذلاذلك، قال: وعلمها في السعي رفع الذلاذل 2'),
(2929, 'لذ', 'لذ', 'لذ', 'شراب لذ ولذيذ يجريان مجرى واحدا في النعت، ويلذ لذاذة. ولذذت الشيء: وجدته لذيذا، ويجمع اللذ لذاذا، قال: تلوم على لذ من العيش أغيد 3 وتقول: ما كنت لذا، ولقد لذذت بعدي.'),
(2930, 'ذن', 'ذن', 'ذن', 'ذن يذن ذنينا إذا سال من أنف الفحل ماء خاثر، ومن المزكوم. والذءنون: نبات أمثال العراجين ينبت، الواحدة بالهاء، وهي مستطيلة، يأكلها الناس من نبات الفطر.'),
(2931, 'فذ', 'فذ', 'فذ', 'الفذ أول سهم القداح. والفذ: الفرد، ويقال: كلمة شاذة فذة. ويجمع الفذ على الفذوذ والفذاذ. وأتانا بتمر فذ أي لم يأخذ بعضه بعضا.'),
(2932, 'ذف', 'ذف', 'ذف', 'الذفيف: الخفيف، وذف يذف ذفافة، وخفاف ذفاف. وماء ذفاف والجمع دفف: وأذفة، أي قليل. وذففت على الرجل أي أجهزت عليه.'),
(2933, 'بذ', 'بذ', 'بذ', 'تقول العرب بذ يبذ بذا إذا خرج شيء على الآخر في حسن أو عمل كائنا ما كان. والبذاذة: سوء الهيئة، ورجل باذ الهيئة، ولقد بذد وأبذه غيره.'),
(2934, 'ذب', 'ذب', 'ذب', 'ذب يذب ذبوبا وهو يبس الشفة، وقد ذبت شفتاه. وهما ذابتان، والجميع الذواب. وهو يذب في الحرب عن حريمه وأصحابه، أي يدفع عنهم ذبا. والمذبة التي تذب بها الذباب، والذباب اسم واحد للذكر والأنثى، والغالب في الكلام التذكير كما أن الغالب في العقاب التأنيث فلا يقولون أبدا إلا: هذه عقاب، وانقضت عقاب. ويجمع الذباب على أذبة، فإن كثر فهو الذبان. وذباب السيف: رأسه الذي فيه ظبته. وجاء في الحديث: كثمرة السوط يتبعها ذباب السيف، وثمرة السوط: طرفه. والذبذبة: تردد شيء في الهواء معلق. والذباذب: أشياء تعلق من الهوادج، أول رأس البعير للزينة، الواحد ذبذب، ورجل مذبذب ومتذبذب أي متردد بين أمرين وبين رجلين لا يثبت على صحابته لأحد. والذباذب: ذكر الرجل لأنه يتذبذب أي يتردد.'),
(2935, 'ذم', 'ذم', 'ذم', 'الذم: اللوم في الإساءة، ومنه التذمم، فيقال من التذمم: قد قضيت مذمة صاحبي، أي أحسنت أن لا أذم. ويقال: افعل كذا وكذا وخلاك ذم، أي خلاك لوم. والذمام: كل حرمة تلزمك، إذا ضيعتها، المذمة، ومنه سمي أهل العهد أهل الذمة الذين يردون الجزية على رءوسهم من المشركين كلهم. والذم: المذموم الذميم. وفي حديث يونس- عليه السلام-: أن الحوت قاءه زريا ذما أي مذموما مهزولا يشبه الهالك. والذميم: بثر أمثال بيض النمل تخرج على الأنف من الحر ونحوه، الواحدة ذميمة، ويجمع على ذمام، قال: وترى الذميم على مراسنهم ... يوم الهياج كمازن الجثل 4 ويروى: النمل. وركية ذمة: قليلة الماء، والجمع الذمام.'),
(2936, 'رذل', 'رذل', 'رذل', 'الرذل: الدون من كل شيء، مصدره الرذالة، وقد رذل، والجميع الأرذال، والأرذلون والرذلون، ورذالة كل شيء أردؤه. ورجل رذل أي وسخ، وامرأة رذلة، وثوب رذيل أي رديء.'),
(2937, 'نذر', 'نذر', 'نذر', 'النذر: ما ينذر الإنسان فيجعله على نفسه نحبا واجبا. والنذر: اسم الإنذار. والنذر: جماعة النذير، وتقول: أنذرتهم فنذروا ولم يستعملوا مصدرا 5 . والتناذر: إنذار بعضهم بعضا. والنذير: اسم الشيء الذي يعطى. وربما جعلت اليهودية ولدها نذيرة للكنيسة، والجمع النذائر. ونذر القوم بالعدو أي علموا بمسيرهم. ومناذر اسم رجل، ومنذر كذلك.'),
(2938, 'ذرف', 'ذرف', 'ذرف', 'ذرفت عينه دمعها ذرفا وذرفانا، وذرف الدمع نفسه يذرف ذروفا، وذرفتها تذريفا وتذرافا وتذرفة، قال: ما بال عيني دمعها ذروف 6 ومذارف العين: مدامعها.'),
(2939, 'ذفر', 'ذفر', 'ذفر', 'الذفر مصدر الأذفر، وهو سوء ريح الإبط، والاسم الذفرة. ومسك أذفر أي ذكي جيد. والذفرى من القفا: الموضع الذي يعرق من البعير وكل شيء، وهما ذفريان عن يمين النفزة من الإنسان وشمالها، قال: والقرط في حرة الذفرى معلقة 7 ومنهم من يصرف ذفرى البعير فينون، كأنهم يجعلون الألف أصلية، وكذلك يجمعون على الذفارى. والذفرة: النجيبة الغليظة الرقبة. والذفر: القوي الشديد.'),
(2940, 'ذبر', 'ذبر', 'ذبر', 'الذبر، بلغة هذيل خفية يذبرها ذبرا. وبعضهم يقول: ذبر الكتاب 8 أي كتب، وبعض يقول: الذبور الفقه بالشيء والعلم به، وقيل: ذبره أي فهمه وقتله علما.'),
(2941, 'بذر', 'بذر', 'بذر', 'بذرت الشيء والحب بذرا، بمعنى نثرت، ويقال للنسل: البذر، يقال: هؤلاء بذر سوء. والبذر اسم جامع لما بذرت من الحب. والبذير: من لا يستطيع أن يمسك سر [نفسه] 9 . ورجل بذير وبذور: مذياع، وقوم بذر: مذاييع، والفعل والمصدر في القياس بذر بذارة. [وفي الحديث: ليسوا بالمساييح البذر] 10 ، ويقال: بذر بذرا. والتبذير: إفساد المال وإنفاقه في السرف، [قال الله- جل وعز: ولا تبذر تبذيرا] 11 . [وقيل: التبذير إنفاق المال في المعاصي، وقيل: هو أن يبسط يده في إنفاقه حتى لا يبقي منه ما يقتاته، واعتباره بقوله- عز وجل-: ولا تبسطها كل البسط فتقعد ملوما محسورا] 12 . [ويقال: طعام كثير البذارة أي كثير النزل، وهو طعام بذر أي نزل، وقال: ومن العطية ما ترى ... جذماء ليس لها بذاره]'),
(2942, 'ربذ', 'ربذ', 'ربذ', 'الربذة: موضع. والربذ: خفة القوائم في المشي، وخفة الأصابع في العمل، وأنه لربذ، قال جرير: خزر لهم ربذ إذا ما استأمنوا ... وإذا تتابع في الزمان الأمرع 13 والربذة: صوفة يؤخذ بها القطران فيهنأ بها البعير، وشبهت الخرقة التي تلقيها الحائض بها فسميت الربذة.. والربذة تميمة، والثملة حجازية وهما صوفة الهناء. وشيء ربيذ أي بعضه على بعض.'),
(2943, 'ذرب', 'ذرب', 'ذرب', 'الذرب: الحاد من كل شيء، لسان ذرب، وسيف ذرب أي حاد. وسم ذرب ومذروب، وقد ذرب ذربا وذرابة. والذربة و [الذربة] 14 : السليطة من النساء، قال: إني لقيت ذربة من الذرب 15 وفلان ذرب: منكر. وتذريب السيف: أن ينقع في السم فإذا أنعم سقيه أخرج فشحذ. وذرب الجرح إذا ازداد اتساعا ولا يقبل البرء، قال الكميت: أنت الطبيب بأدواء القلوب إذا ... خيف المطاول من أسقامها الذرب 16 والذرب من الأمراض مأخوذ من الجرح، وهو الذي لا يبرأ، واستعير من الجرح للمرض، قال الغنوي: إذا أساها طبيب زادها مرضا 17'),
(2944, 'رذم', 'رذم', 'رذم', 'قصعة رذوم، رذمت أي امتلأت حتى إن جوانبها لتصبب. ورذمته أرذمه، وقل ما يستعمل الا بفعل مجاوز، قال: لا تملأ الدلو صبابات الوذم ... إلا سجال رذم على رذم 18 الرذم هاهنا: الامتلاء، والرذم الاسم، والرذم المصدر.'),
(2945, 'ذمر', 'ذمر', 'ذمر', 'الذمر: اللوم والحض معا، والقائد يذمر أصحابه اي يلومهم ويسمعهم ما يكرهون ليكون أجد لهم في القتال. والتذمر: اشتق منه، وهو أن يقصر الرجل في أمر فيلوم نفسه ويعاتبها كي يجد في الأمر. والقوم يتذامرون في الحرب. وذمار الرجل: كل شيء يلزمه الدفع عنه، وإن ضيعه لزمه الذمر أي اللوم. والمذمر للناقة كالقابلة للنساء، وذلك أنه يذمر أي يلمس إذا خرج، وهو القبض على علباويه، فإن كان ذكرا أو أنثى عرفه بذلك، قال الكميت: وقال المذمر للناتجين ... متى ذمرت قبلي الأرجل 19 وذامر فلان فلانا فذمره أي غلبه في المذامرة. والمذمر: الكاهل والعنق وما حوله إلى الذفرى من أصل الأذن.'),
(2946, 'مذر', 'مذر', 'مذر', 'مذرت البيضة إذا غرقلت وفسدت، وقد امذرتها الدجاجة. والتمذر: خبث النفس. والمذروان: فرعا الأليتين، قال: أحولي تنفض استك مذرويها ... لتقتلني فها أنا ذا عمارا 20'),
(2947, 'نذل', 'نذل', 'نذل', 'النذل والنذيل من تزدريه في خلقته وعقله، ونذل نذالة وهم الأنذال.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(2948, 'فلذ', 'فلذ', 'فلذ', 'الفلذ: كسرك قطعة من كبد أو فضة أو ذهب، وافتلذت فلذة من كبد، أي قطعت قطعة. وفلذت له من مالي فلذة: أعطيته منه شيئا، والفلذ الأسم، والفلذ مصدر. والفلذة قطعة من كبد، وفي الحديث: ترمي بأفلاذ كبدها، يعني ما فيها من الكنوز والأموال.'),
(2949, 'ذلف', 'ذلف', 'ذلف', 'الذلف: غلظ واستواء في طرف الأنف وليس بجد غليظ تعتري منه الملاحة.'),
(2950, 'ذبل', 'ذبل', 'ذبل', 'الذبل: جلد السلحفاة البحرية. والذبل: أسورة العاج والقرون. والذبول: مصدر الذابل، وهو دقة كل شيء كان ريان من الناس والنبات ثم ذبل. والتذبل: مشية للنساء إذا مشين مشية الرجال إذا كانت مع ذلك دقيقة. والذبالة: الفتيلة. والذبلة: البعرة، والذبلة: الريح الهيف، والجمع: الذبلات.'),
(2951, 'بذل', 'بذل', 'بذل', 'البذل نقيض المنع، وكل من طابت نفسه لشيء فهو باذل. والبذلة من الثياب: ما يلبس ولا يصان. ورجل متبذل: يلي الأعمال بنفسه.'),
(2952, 'لذم', 'لذم', 'لذم', 'لذم بالشيء أي لهج وأولع به، قال: ثبت اللقاء في الحروب ملذما 21'),
(2953, 'ذمل', 'ذمل', 'ذمل', 'الذميل: ضرب من العدو، وهو الذملان، وذمل يذمل.'),
(2954, 'مذل', 'مذل', 'مذل', 'الامذلال: الاسترخاء والفترة، قال: ويجري في العظام امذلالها 22 والمذيل: المريض، وهو الذي لا يتقار وهو في ذلك ضعيف، وقد مذل مذلا ومذل مذالة. ورجل مذل به: طيب النفس، ومذلت به نفسي. والمذل: القلق، تقول: مذل بسره ويمذل أي أخذه القلق حتى أفشاه وأظهره، قال: فلا تمذل بسرك، كل سر ... إذا ما جاوز الاثنين فاشي 23 والاسم المذال.'),
(2955, 'ملذ', 'ملذ', 'ملذ', 'ملذ يملذ ملذا، وهو أن ترضي صاحبك بكلام لطيف وتسمعه ما يسره، وليس معه فعل، ورجل ملاذ ملذاني، قال: تسليم ملاذ على ملاذ 24'),
(2956, 'نفذ', 'نفذ', 'نفذ', 'النفاذ: الجواز والخلوص من الشيء، ونفذت أي جزت، وطريق نافذ: يجوزه كل احد ليس بين قوم خاص دون العامة، [ويقال: هذا الطريق ينفذ إلى مكان كذا وكذا، وفيه منفذ 25 للقوم أي مجاز] . ونفذ السهم وأنفذته، والنفذ يستعمل في إنفاذ الأمر، تقول: قام المسلمون بنفذ الكتاب، أي بإنفاذ ما فيه 26 . [وقال قيس بن الخطيم: طعنت ابن عبد القيس طعنة ثائر ... لها نفذ لولا الشعاع أضاءها 27 أراد بالنفذ المنفذ. يقول: نفذت الطعنة: أي جاوزت الجانب الآخر حتى يضيء نفذها خرقها، ولولا انتشار الدم الفائر لأبصر طاعنها ما وراءها، أراد أن لها نفذا أضاءها لولا شعاع دمها، ونفذها نفوذها إلى الجانب الآخر] 28 .'),
(2957, 'ذنب', 'ذنب', 'ذنب', 'الأذناب جمع الذنب. والذنب: الإثم والمعصية، والجمع الذنوب. والمذنب: مسيل الماء بحضيض الأرض وليس بجد واسع، وإن كان في سفح أو سند فهو التلعة. ويقال لمسيل ما بين التلعتين: ذنب التلعة. والذانب: التابع للشيء على أثره. والمستذنب الذي يتلو الذنب لا يفارق أثره، قال: مثل الأجير استذنب الرواحلا 29 والذنوب: الفرس الواسع هلب الذنب. والذنوب: ملء دلو من ماء، ويكون النصيب من كل شيء كذلك، قال: لنا ذنوب ولكم ذنوب والذناب آخر كل شيء، قال: ونأخذ بعده بذناب عيش ... أجب الظهر ليس له سنام 30 الذناب أيضا من مذانب المسايل، وهو شبيه أن يكون جماع الذنب، وقد يجمعون على الذنائب. والذنابى: موضع منبت الذنب 31 . والتذنوب، الواحدة تذنوبة هي البسرة المذنبة التي قد أرطب طرفها من قبل ذنبها. وذنب الجراد: سمن وسمنه في أذنابه. والتذنيب: التعاظل للضباب والفراش والجراد ونحوها، والتذنيب: إخراجها أذنابها من جحرتها وضربها على أفواه جحرتها 32 .'),
(2958, 'نبذ', 'نبذ', 'نبذ', 'النبذ: طرحك الشيء من يدك أمامك أو خلفك. والمنابذة: انتباذ الفريقين للحرب، ونبذنا عليهم على سواء أي نابذناهم الحرب إذا أنذرهم وأنذروه. والمنبوذ: ولد الزنى المطروح. والنبائذ: واحدها نبيذة، وهم المنبوذون، منه المنابذة والمنبوذة: المهزولة التي لا تؤكل.'),
(2959, 'منذ', 'منذ', 'منذ', 'النون والذال فيها أصليتان، وقد تحذف النون في لغة. وقيل: إن بناء منذ مأخوذ من قولك: من إذ، وكذلك معناها من الزمان إذا قلت: منذ كان، كان معناه: من إذ كان ذلك، فلما كثر في الكلام طرحت همزتها 33 ، وجعلتا كلمة واحدة ورفعت على توهم الغاية 34 .'),
(2960, 'بذم', 'بذم', 'بذم', 'البذم مصدر البذيم، وهو العاقل الغضب من الرجال، يعلم ما يغضب له، وبذم بذامة، قال: كريم عروق النبعتين مطهر ... ويغضب مما فيه والبذم يغضب 35 وبذيمة: اسم رجل.'),
(2961, 'ثر', 'ثر', 'ثر', 'عين ثرة أي غزيرة الماء، وقد ثرت تثر و [تثر] ثرا وثرارة، وعين السحاب مثله وطعنة ثرة: واسعة. وكل نعت في حد المدغم إذا كان على تقدير فعل فأكثره على تقدير يفعل نحو: طب يطب وثر يثر، وقد يختلف في نحو: خب يخب فهو خب. وكل شيء في باب التضعيف فعله من يفعل مفتوح العين فهو في فعيل مكسور في كل شيء [نحو: شح يشح وضن، يضن فهو شحيح وضنين] 1 . [ومن العرب من يقول: شح يشح وضن يضن] 2 . وما كان من نعت على مثال أفعل فعلاء 3 في باب التضعيف فالفعل منهما على فع يفع 4 والأصل فعل يفعل. وكذلك ما كان من نعت على بناء فعل فأكثره يفعل، وناقة ثرة وثرور، أي كثيرة اللبن. والثرثرة في الكلام: الكثرة، وفي الأكل الإكثار والتخليط، ورجل ثرثار وامرأة ثرثارة وقوم ثرثارون. وثرثار: نهر بالجزيرة.'),
(2962, 'رث', 'رث', 'رث', 'الرث: الثوب البالي، وحبل رث وثوب رث، ورجل رث الهيئة في لبسه. والفعل: رث يرث ويرث رثاثة ورثوثة. والرثة: أسقاط البيت من الخلقان ونحوه، والجميع رثث 5 . وإذا ضرب الرجل في الحرب فأثخن فحمل من موضعه حيا، ثم يموت من بعد ذلك قيل: ارتث فلان. والمرث الذي قد رث حبله أو ثيابه 6 .'),
(2963, 'لث', 'لث', 'لث', 'التث السحاب التثاثا: دام بالمكان لا يبرح، قال: ألث بها عارض ممطر 7 ولثلث السحاب: تردد في مكان كلما ظننت أنه ذهب عاد، قال: لثلاثة مدجوجن ملثلث 8 ورجل لثلاث: بطيء في كل أمر، كلما ظننت أنه أجابك إلى القيام في حاجتك تقاعس 9 ، [وأنشد لرؤبة: لا خير في ود امرىء ملثلث] 10 ولم يلث أن صنع كذا، أي لم يلبث. ولثلث البعير رحله إذا أنتقه أي زعزعه، قال: قد طال ما لثلثت رحلي مطيته ... في دمنة وسرت صفوا بأكدار 11 ثلث 12 : الثلاثة: من العدد. وثلثت القوم أثلثهم ثلثا، [إذا أخذت ثلث أموالهم] 13 . وقد يقال: ثلثت الرجلين أي كانا اثنين فصرت لهما ثالثا. وثلاث ومثلث لا تدخل عليهما اللام ولا يصرفان. والمثلث من الأشياء: ما كان على ثلاثة أثناء. والمثلوث من الحبل: ما كان على ثلاث قوى، وكذلك ما ينسج ويضفر، والمضفور والمفتول والمثلوث: ما أخذ ثلثه. والثلاثاء: لما جعل اسما جعلت الهاء التي كانت في العدد مدة، فرقا بين الحالين، وكذلك الأربعاء من الأربعة، فهذه الأسماء جعلت بالمد توكيدا للأسم، كما قالوا: حسنة وحسناء، وقصبة وقصباء، حيث ألزموا النعت إلزام الاسم، وكذلك الشجراء والطرفاء، وكان في الأصل نعتا فجعل اسما، لأن حسنة نعت، وحسناء اسم من الحسن موضوع، والواحد من كل ذلك بوزن فعلة. وإذا أرسلت الخيل في الرهان، فالأول السابق، والثاني المصلي لأنه يتلو أصلا الذي قبله، ثم يقال بعد ذلك: ثلث وربع وخمس، قال: سبق عباد وصلت لحيته ... وثلثت بعدهما مرزبته 14 والثليث في وجه واحد الثلث، ولكن أحسن ما تكلمت به العرب أن يقال: عشر وثلث وكذلك المثلاث والمثلث كقولك: جاءوا مثلث مثلث وموحد موحد ومثنى مثنى، لا يجر، وكذلك ثلاث، ثلاث، ورباع رباع، أي ثلاثة ثلاثة وأربعة أربعة لا يجر 15 . والثلاثي: ما نسب إلى ثلاثة أشياء، أو كان طوله ثلاثة أذرع ثوب ثلاثي ورباعي. وغلام ثلاثي ورباعي وخماسي، ولا يقال سداسي، لأنه إذا تمت له ستة أشبار صار رجلا 16 . والثلث في الإبل: ظمء يومين بعد شربين، ولكن لم يستعمل إنما يخرج في القياس على الأظماء.'),
(2964, 'ثل', 'ثل', 'ثل', 'وثل عرشه أي زال قوام أمره، واثله الله. ويقال: لعرش الكرم، وعرش العريش الذي تتخذ منه ظللة ونحوه من الأشياء إذا انهدم: قد ثل. والثلة: قطيع من الغنم غير كثير، قال: آليت بالله ربي لا أسالمهم ... حتى يسالم رب الثلة الذيب 17 وقول لبيد: وصداء ألحقتهم بالثلل 18 أي بالثلال، يعني أغناما أي يرعونها فقصر. والثلة: جماعة من الناس كثيرة. والثلة: تراب البئر. والثلة: الهلاك، وكذلك الثلل والثلال، قال الكميت 19 : تناوم أيقاظ واغضاء أعين ... على مخزيات أن يهيج ثلالها'),
(2965, 'نث', 'نث', 'نث', 'النث: نشر الحديث الذي كتمانه أحق، ونث ينث نثا، ونثث ينثث تنثيثا إذا عرق من سمنه.'),
(2966, 'ثن', 'ثن', 'ثن', 'الثنة: شعرات مشرفات على رسغ الدابة من خلف. والثنة: ما دون السرة من أسفل البطن فوق العانة من الإنسان ومن كل شيء.'),
(2967, 'فث', 'فث', 'فث', 'الفث: نبت يؤكل في الجذب.'),
(2968, 'بث', 'بث', 'بث', 'بث الشيء: تفريقه. وبثثت الشيء والخبر: نشرته، وابتثثته أيضا. يقال: بث الخيل في الغارة، وبث الكلاب كلابه على الصيد.'),
(2969, 'مث', 'مث', 'مث', 'المث: مسحك أصابعك بمنديل أو حشيش أو نحوه من دسم، قال: نمث بأطراف الجياد أكفنا 20 ونمش مثله. وتقول للرجل الأكول الضخم البطن: إنه ليمث كأنه زق، وكأنه يخرج منه الدسم من سمنه.'),
(2970, 'ثم', 'ثم', 'ثم', 'ثم معناه هناك للتبعيد، وهنالك للتقريب. وثم: حرف من حروف النسق لا تشرك ما قبلها بما بعدها، إلا أنها تبين الآخر من الأول، ومنهم من يلزمها هاء التأنيث فيقول: ثمت كان كذا وكذا قال: ثمت جئت حية أصما ... أرقم يسقي من يعادي السما 21 والثمة: قبضة من حشيش، أو أطراف شجر بورقه يغسل به شيء، يقال: امسحها بثمة أو تربة. والثمام: ما كسر من أغصان الشجر فوضع نضدا للثياب ونحوه، وإذا يبس فهو الثمام. وقيل: بل هو شجر اسمه الثمام، الواحدة ثمامة. وثممت الشيء أثمة ثما: أصلحته وأحكمته، قال هميان 22 : وملأت حلابها الخلانجا ... منها وثموا الأوطب النواشجا 23'),
(2971, 'نثر', 'نثر', 'نثر', 'النثر: رميك الشيء بيدك متفرقا، ويقال: أخذ درعا فنثرها على نفسه، ويسمى الدرع النثرة إذا كانت سلسلة الملبس. والنثرة: الفرجة التي بين الشاربين حيال وترة الأنف، وكذلك هي من الأسد. والنثرة: كوكب في السماء كأنه لطخ سحاب حيال كوكبين صغيرين تسميه العرب نثرة الأسد، وهو من منازل الشمس والقمر. وهو في علم النجوم من بروج السرطان. والنثارة: فتات ما يتناثر من الخوان ونحوه. والنثرة للدواب: شبه العطس للناس، إلا أنه ليس بغالب، ولكنه شيء يفعله بأنفه، تقول: نثر الحمار ينثر نثيرا. والإنسان يستنثر إذا استنشق، ثم استخرجه بنفس الأنف. وامرأة نثور: كثيرة الولد، يقال: نثرت بطنها. ويقال للرجل يجأ بطن الآخر بالسكين: قد نثر أمعاءه. والنثر: اسم للجوز والسكر وما ينثر من الأشياء، والنثار الفعل، يقال: أما شهدت نثار فلان، وما أصبت من نثر فلان، أي ما نثر. ويقال: رضوا فتناثروا موتى 24 .'),
(2972, 'رفث', 'رفث', 'رفث', 'الرفث: الجماع، رفث إليها وترفث، وهذه كناية. وفلان يرفث، أي يقول: الفحش، وقال ابن عباس: الرفث ما قيل عند النساء، وقوله- عز وجل-: فلا رفث ولا فسوق 25 ، إنما نهى عن قول الفحش.'),
(2973, 'فرث', 'فرث', 'فرث', 'الفرث: السرقين ما دام في الكرش. يقال: ضربته حتى فرثت كبده في جوفه أي فتتتها. وأفرثت الكرش والجلة: نثرت فرثها وتمرها. وأفرث أصحابه: سعى بهم فألقاهم في بلية ونحوها.'),
(2974, 'ثفر', 'ثفر', 'ثفر', 'ثفر الدابة وغيرها من السباع بمنزلة الحياء من الناس، وهو القبل. والثفر: السير في مؤخر السرج، يلي الذنب، وجمعه أثفار. والمثفار من الدواب التي ترمي بسرجها إلى مؤخرها. والاستثفار: ادخال الكلب ذنبه بين فخذيه حتى يلزقه ببطنه، قال: تعدو الذئاب على من لا كلاب له ... وتتقي مربض المستثفر الحامي 26 والرجل يستثفر بإزاره عند الصراع، إذا لواه على فخذيه، ثم أخرجه من بين فخذيه فشد طرفه في حجزته.'),
(2975, 'فثر', 'فثر', 'فثر', 'الفاثور عند العامة الطست خان، وأهل الشام يتخذون خوانا من رخام يسمونها الفاثور، قال: والأكل في الفاثور بالظهائر 27 وقوله: في الفاثور، أي على الفاثور، كما قال تعالى: ولأصلبنكم في جذوع النخل 28 ، أي على جذوع النخل. وفي بعض كلام أهل الشام والجزيرة: على الفاثور الواحد، يعني على البساط الواحد. والفواثير: الجواسيس، الواحد فاثور في كلام أرمينية.'),
(2976, 'ثرب', 'ثرب', 'ثرب', 'الثرب: شحم رقيق يغثي الكرش والأمعاء، والجمع ثروب. وقوله- عز وجل-: لا تثريب عليكم اليوم 29 ، أي لا لوم عليكم، والتثريب: الإفساد، والتثريب بالذنب، لا أثرب عليك.'),
(2977, 'ثبر', 'ثبر', 'ثبر', 'الثبر: أرض حجارتها كحجارة الحرة إلا أنها بيض، تقول: انتهينا إلى ثبرة كذا، أي حرة كذا. وثبير: اسم جبل. والثبور: الهلاك. والمثابر: الملح المداوم على الشيء، قال: فثابر بالرمح حتى نحاه ... في كفل كسراة المجن 30 والمثبر: مسقط الولد بالأرض إذا ولد للناقة والمرأة أيضا. وثبر البحر إذا جزر بعد ما مد، يثبر ثبرا.'),
(2978, 'بثر', 'بثر', 'بثر', 'البثر: خراج صغار، الواحدة بثرة، وقد بثر 31 جلده يبثر بثرا وبثورا. وصار الغدير بثرا: ذهب ماؤه وبقي شيء قليل، ثم نشر على وجه الأرض منه شبه عرمض.'),
(2979, 'برث', 'برث', 'برث', 'البرث: شبه جبل من رمل إلا أن برثه صلب أي تربه. ويقال: بل البرث اسهل الأرض وألينها، وجمعه البروث.'),
(2980, 'ربث', 'ربث', 'ربث', 'الربث: حبسك إنسانا عن أمر، يقال: ربثته عن حاجته ربثا، والاسم: الربيثة. ويبعث إبليس يوم الجمعة شياطينه إلى الناس فيأخذون عليهم بالربائث، أي يذكرونهم بالحوائج ليربثوهم بها عن الجمعة، قال: جري كريث أمرها ربيث 32 وكريث أي مكروث، وربيث أي مربوث. والربيثي 33 : اسم مشتق من هذا.'),
(2981, 'ثمر', 'ثمر', 'ثمر', 'الثمر: حمل الشجر. والثمر: أنواع المال، والولد ثمرة القلب. وأثمرت الشجرة. والعقل المثمر عقل المسلم، والعقل العقيم عقل الكافر. وثمر الله: مالك. والثامر: نور بقلة تسمى الحماض، وهو أحمر شديد الحمرة، قال: من علق كثامر الحماض 34 وقد أثمر السقاء إذا آن أن يحمض، وسقاء مثمر. يقال: الثامر اسم للثمرة، ومن أنشد: كثمر الحماض عنى به الحمل. وثمرت للغنم أي خبطت الشجر لها لينتثر الورق.'),
(2982, 'ثرم', 'ثرم', 'ثرم', 'وثرمت الرجل فثرم 35 ، وثرمت ثنيته فانثرمت، والنعت أثرم.'),
(2983, 'رثم', 'رثم', 'رثم', 'ورثمت أنفه، أي دققته. والرثم: بياض على أنف الفرس 36 ، ورثم فهو أرثم. والرثم: تخديش وشق من طرف الأنف حتى يخرج الدم فيقطر، وهو كسر من طرف منسم البعير، يقال: رثم منسمة فسال منه الدم، قال ذو الرمة: تثني النقاب على عرنين أرنبة ... شماء مارنها بالمسك مرثوم 37 جعل لطخ المسك بالمارن تشبيها بالدم.'),
(2984, 'مرث', 'مرث', 'مرث', 'المرث: مرثك الشيء تمرثه في ماء شبه دواء وغيره حتى يتفرق فيه. والصبي يمرث أمه، أي يرضعها. ويمرث الكسرة: يمصها ويكدمها. والمراثة: ما بقي في فيه.'),
(2985, 'رمث', 'رمث', 'رمث', 'الرمث: ضرب من الحطب، وهو من المراعي، وهي ضروب كلها تسمى رمثا، والواحدة رمثة. والغالب عليها عند العامة أنها شجرة تشبه الغضى، ولكنها ينبسط ورقها، شبيه بالأشنان. والرماثة: الرمازة. والرمث: الطوف 38 في الماء وجمعه أرماث. ويقال: الأرماث خشب يضم بعضه الى بعض، ثم يركب في البحر، الواحد رمث، قال جميل: تمنيت من حبي علية أننا ... على رمث في الشرم ليس لنا وفر 39'),
(2986, 'نثل', 'نثل', 'نثل', 'يقال: أخذ درعه فنثلها عليه. والنثل: نثرك الشيء كله بمرة. ونثل الرجل: سلح.'),
(2987, 'ثفل', 'ثفل', 'ثفل', 'الثفل 40 : نثرك الشيء بمرة. والثفل: ما رسب خثارته وعلا صفوه من كل شيء. وثفل القدر والدواء ونحوه. والثفال: البعير الثقيل البطيء. والثفال: أديم ونحوه يبسط تحت الرحى، يقع عليه الطحن، أي الدقيق.'),
(2988, 'لبث', 'لبث', 'لبث', 'اللبث: المكث، ولبث لبثا. واللبث: البطيء.'),
(2989, 'ثلب', 'ثلب', 'ثلب', 'الثلب: البعير الهرم. والثلب: الشيخ، هذلية. والأثلب 41 : التراب، وفي لغة: فتات الحجارة. وفي الحديث: وللعاهر الأثلب. والثلب: شدة اللوم، والأخذ باللسان. وهو المثلب يجري في العقوبات.'),
(2990, 'بلث', 'بلث', 'بلث', 'البلث: الحرك 42 ، الواحدة بلثة.'),
(2991, 'مثل', 'مثل', 'مثل', 'المثل: الشيء يضرب للشيء فيجعل مثله. والمثل: الحديث نفسه. وأكثر ما جاء في القرآن نحو قوله- جل وعز-: مثل الجنة التي وعد المتقون 43 * فيها أنهار، فمثلها هو الخبر عنها. وكذلك قوله تعالى: ضرب مثل فاستمعوا له 44 ، ثم أخبر: أن الذين تدعون من دون الله، فصار خبره عن ذلك مثلا، ولم تكن هذه الكلمات ونحوها مثلا ضرب لشيء آخر كقوله تعالى: كمثل الحمار يحمل، 45 وكمثل الكلب 46 . والمثل: شبه الشيء في المثال والقدر ونحوه حتى في المعنى. ويقال: ما لهذا مثيل. والمثال: ما جعل مقدارا لغيره، وجمعه مثل، وثلاثة أمثلة. والمثول: الانتصاب قائما، والفعل: مثل يمثل، قال لبيد: ثم أصدرناهما في وارد ... صادر وهم صواه قد مثل 47 والتمثيل: تصوير الشيء كأنه تنظر إليه. والتمثال: اسم للشيء الممثل المصور على خلقة غيره، كسرت التاء حيث جعلت اسما بمنزلة التجفاف وشبهه، ولو أردت مصدرا لفتحت، وجاءت تفعال في حروف قليلة نحو تمراد وتلقاء، وإنما صار تلقاء اسما لأنه صار في حال لدن، وفي حال حيال، وما كان مصدرا فالتاء مفتوحة يجرى مجرى المصدر في كلام العرب، لا يجمع ولا يصغر، وهذا أمثل من ذلك، أي أفضل.'),
(2992, 'ثمل', 'ثمل', 'ثمل', 'الثميلة: الماء القليل الباقي في الحوض والسقاء. والثملة: خرقة الهناء، وتكون ايضا من الصوف ونحوه. والثمل: الظل. والثمل: السكر. والمثمل: السم لأنه يثمل من يلجأ إليه.'),
(2993, 'لثم', 'لثم', 'لثم', 'اللثم: وضعك فاك على في آخر، ومنه اللثام، أي شدك الفم بالمقنعة.'),
(2994, 'ثلم', 'ثلم', 'ثلم', 'الثلمة معروفة، ثلمة الحائط ونحوه.'),
(2995, 'ملث', 'ملث', 'ملث', 'ملث الظلام ونحوه أي اختلاط السواد.'),
(2996, 'نفث', 'نفث', 'نفث', 'النفث: نفثك في العقد ونحوها، يقال: نفث ينفث نفثا، ومن ذلك قوله تعالى: ومن شر النفاثات في العقد 48 يعني السواحر.'),
(2997, 'نبث', 'نبث', 'نبث', 'النبيثة: التراب الذي ينبث من البئر والنهر، أي يخرج، والجمع النبائث. وكان أبو دلامة عند أبي ليلى، وهو على القضاء، وكانت عنده شهادة لرجل، فقال ابن أبي ليلى: لا تقبل شهادته، فأبى إلا أن يشهد. وكان ابن أبي ليلى يغمز في نسبه، فلما جلس للشهادة أنشد: إن الناس غطوني تغطيت عنهم ... وان بحثوا عني ففيهم مباحث وان حفروا بئري حفرت بئارهم ... فسوف يرى آثارهم والنبائث 49 فأجاز شهادته.'),
(2998, 'بثن', 'بثن', 'بثن', 'البثنة اسم رملة لينة، ويصغر بثينة، وبها سميت المرأة بثينة للينها. والبثنية بلاد بالشام.'),
(2999, 'ثبن', 'ثبن', 'ثبن', 'ثبنت ثبانا، وتثبنت اذا جعلت شيئا في الوعاء ثم حملته بين يديك. والثبان: طرف الرداء، ثبنه ثبنا وثبانا 50 . وثبنة: موضع. والثبنية: جنس من الحنطة.'),
(3000, 'رف', 'رف', 'رف', 'الرف: رف البيت، والجميع: الرفوف. والرف: شبه المص والتشفف. رففت أرف رفا. والرف: أكل الرفيف، وهو الحنظل وشبهه، سمي رفيفا لأنه يؤكل بالمشافر. والرفرفة: تحريك الطائر جناحه في الهواء وهو لا يبرح مكانه. والرفيف والوريف: النبات الذي يهتز خضرة وتلألؤا، وقد رف يرف رفيفا، وورف يرف وريفا، قال الأعشى: ومها ترف غروبه ... يشفي المتيم ذا الحرارة 1 يذكر ثغر امرأة. والرفراف: الظليم يرفرف بجناحيه، ثم يعدو. والرفرف: كسر الخباء ونحوه، وهو أيضا خرقة تخاط في أسفل السرادق والفسطاط ونحوه. والرفرف: ضرب من الثياب خضر تبسط، الواحدة: رفرفة. وضرب من السمك [يقال] له: رفرف. والرفة 2 : عناق الأرض، تصيد كما يصيد الفهد.'),
(3001, 'فر', 'فر', 'فر', 'الفرار والمفر لغتان، وقيل: بل المفر: المهرب، وهو الموضع الذي يهرب إليه. ورجل فرور وفرورة من الفرار. ورجل فر ورجلان فر ورجال فر لا يثنى ولا يجمع. والفر: مصدر فررت عن أسنان الدابة، أي: كشفت عنها. وافتر عن ثغره إذا تبسم. وفر فلان عما في نفسه، وفر عن هذا الأمر، أي: فتشه. والفرفرة: الطيش والخفة، ورجل فرفار، وامرأة فرفارة. وما زال فلان في أفرة شر من فلان، [أي: في أول] . والفر: الرجل الفار، وأفررته: ألجأته إلى الفرار. والفرفور: الحمل السمين، والفرار: ولد النعجة.'),
(3002, 'رب', 'رب', 'رب', 'الربيون: الذين صبروا مع الأنبياء، نسبوا إلى العبادة والتأله في معرفة الربوبية لله، الواحد: ربي. ومن ملك شيئا فهو ربه، لا يقال بغير الإضافة إلا لله عز وجل. ورجل ربابي نسب إلى الرباب، حي من ضبة. والرباب: السحاب الذي فيه ماء، الواحدة: ربابة، وأربت السحابة بهذه البلدة: أدامت بها المطر، قال: أرب بها عارض ممطر 3 وأرض مرباب: أرب بها المطر، ومرب أيضا، لا يزال بها مطر، وكذلك مصل، فيها صلال من مطر، أي: أمطار متفرقة، شيء بعد شيء، قال 4 : [بأول ما هاجت لك الشوق دمنة] ... بأجرع مقفار مرب محلل ورببت قرابة فلان ربا، أي: زدت فيها لئلا يعفوا أثرها. ورببت الصبي والمهر، يخفف ويثقل، قال الراجز: كان لنا وهو فلو نرببه 5 والربيبة: الحاضنة. ورببته ورببته: حضنته. وربيبة الرجل: ولد امرأته من غيره، والربيب: يقال لزوج الأم لها ولد من غيره، ويقال لامرأة الرجل إذا كان له ولد من غيرها: ربيبة وهو الراب، وهي: الرابة، والجميع: الرواب. والربى: الشاة من حين تلد إلى عشرين يوما، ويقال: الشاة في ربابها إلى ذلك الوقت، قال: حنين أم البو في ربابها 6 والسقاء يربب: [أي: يجعل فيه الرب] . والشيء يربب بخل أو عسل. والجرة تربب فتضرى تربيبا. ودهن مربب: مطبوخ بالطيب، قال في وصف الزق 7 : لنا خباء وراووق ومسمعة ... لدى حضاج، بجون القار، مربوب ويروى: لدى حضجر، وهو الزق العظيم. والربرب: القطيع من بقر الوحش. والربة: نبات في الصيف، والجميع: الربب. والرب: السلاف الخاثر من كل شيء من الثمار. والإرباب: الدنو من كل شيء، قال ذو الرمة في وصف الشول 8 : فيقبلن إربابا ويعرضن رهبة ... صدود العذارى واجهتها المجالس ورب: كلمة تفرد واحدا من جميع يقع على واحد يعنى به الجميع، كقولك: رب خير لقيته، ويقال: ربتما كان ذلك، وكل يخفف الباء، كقوله 9 : ألا رب ناصر لك من لوي ... كريم لو تناديه أجابا والربابة: خرقة تجعل فيها القداح، هذلية، واشتقاقه من رببت الشيء، أي: جمعته، قال 10 : [بأول ما هاجت لك الشوق دمنة ... بأجرع مقفار] مرب محلل'),
(3003, 'بر', 'بر', 'بر', 'البر: خلاف البحر، ونقيض الكن، تقول: خرجت برا وجلست برا، على النكرة تستعمله العرب. والبرية: الصحراء. والبر: البار بذوي قرابته. وقوم بررة وأبرار. وتقول: ليس ببر وهو بار غدا. والمصدر والاسم: البر، مستويان. وبرت يمينه، أي: صدقت، وأبرها الله، أي: امضاها على الصدق، وأبررت يميني إبرارا. وبر الله حجك فهو مبرور.. وفلان يبرك، [أي] : يطيعك، قال: يبرك، الناس ويفجرونكا 11 والبرير: حمل الأراك. وقد أبر عليهم، أي: غلبهم. وابتر فلان، أي: انتصب منفردا من أصحابه. والبربرة: كثرة الكلام، والجلبة باللسان، قال:'),
(3004, 'رم', 'رم', 'رم', 'الرم: إصلاح الشيء الذي فسد بعضه، من نحو حبل بلي فترمه، أو دار ترم شأنها مرمة. ورم الأمر: إصلاحه بعد انتشاره، قال:'),
(3005, 'رفل', 'رفل', 'رفل', 'الرفل: جر الذيل، وركضه بالرجل.. امرأة رافلة ورفلة، أي: تترفل في مشيها، أي: تجر ذيلها إذا مشت وماست في ذلك. وامرأة رفلاء، أي: لا تحسن المشي في الثياب.. عن أبي الدقيش. وفرس رفل، وثور رفل إذا كان طويل الذنب. وبعير رفل [يوصف به على وجهين: إذا كان طويل الذنب، وإذا كان] 20 واسع الجلد، قال 21 : جعد الدرانيك رفل الأجلاد والرفن: لغة في الرفل، ولا يشتق الفعل إلا باللام. وامرأة مرفال: كثيرة الرفول في ثوبها. وشعر رفال: طويل، قال: بفاحم منسدل رفال 22 وقوله 23 : [أو زير بيض] ترفل المرافلا أي: تمشي كل ضرب من الرفل، وهذا كقولهم. يمشي المماشي، ويأكل المآكل، أي: يفعل كل نوع من ذلك، ولو قيل: امرأة رفلة تطول ذيلها وترفل فيه كان حسنا. ورفلوا فلانا ترفيلا، أي: سودوه على قومه ... والترفيل: بر الملك، قال 24 : إذا نحن رفلنا امرأ ساد قومه ... وإن لم يكن من قبل ذلك يذكر والرجل يرفل في سيفه وحمائله. وقيل امرأة رفلاء ورفلة، أي: خرقاء، وهي التي لا تحسن عملا. [والمرفل من أجزاء العروض: ما زيد في آخر الجزء سبب آخر فيصير متفاعلان مكان متفاعلن] .'),
(3006, 'ربل', 'ربل', 'ربل', 'الربلة: باطن الفخذ، مما يلي القبل إلى مؤخر العجز. وامرأة ربلة: ضخمة الربلات. وامرأة ربلاء رفغاء. أي: ضيقة الأرفاغ. قال: كأن مجامع الربلات منها ... فئام ينظرون إلى فئام 25 والربل أيضا: ما اخضر من الشجر من دقه وجله في القيظ بعد ما يبس. وتربل الشجر وأربلت الأرض. وأرض مربال: لا يزال بها ربل، إذا أصاب نباتها برد الليل في آخر الصيف فنبت بلا مطر، قال ذو الرمة 26 : ربلا وأرطى نفت عنه ذوائبه ... كواكب الحر حتى ماتت الشهب والرئبال: الأسد، ويقال: ذئب رئبال، ولص رئبال، وهو من الجرأة وارتصاد الشر، وقد فعل ذلك من رأبلته وخبثه. وقد ترأبل، أي: تشبه بالأسد.'),
(3007, 'برل', 'برل', 'برل', 'البرءولة، والجمع: البرائيل: ريش سبط لا عرض له على عنق الديك ونحوه من الخلق، فإذا نفشه للقتال قيل: برأل الديك، وتبرأل ريشه وعنقه. الواحدة: برءولة. والبرائل: للديك خاصة. ولنحوه إن كان.'),
(3008, 'رمل', 'رمل', 'رمل', 'الرمل: معروف، والجميع: رمال، والقطعة منه: رملة. وأرمل القوم: فني زادهم. ورملت الثوب: لطخته لطخا شديدا. ورملت الطعام ترميلا: جعلت فيه رملا وترابا. والأرملة: التي مات زوجها، ولا يقال: شيخ أرمل إلا أن يشاء شاعر في تمليح كلامه، كقول جرير: هذي الأرامل قد قضيت حاجتها ... فمن لحاجة هذا الأرمل الذكر يعني بالأرمل: نفسه. وغلام أرمولة، كقولك بالفارسية: زاذه. وأرملت النسج، إذا سخفته تسخيفا، ورققته، قال: كأن نسج العنكبوت المرمل 27 ورملت الحصير: نسجته. ورملت السرير: زينته بالجوهر ونحوه. والروامل: نواسج الحصر. والرملان والرمل واحد، وهو فوق المشي ودون العدو. والرمل: ضرب من الشعر يجيء على: فاعلاتن فاعلاتن فاعلاتن.'),
(3009, 'رنف', 'رنف', 'رنف', 'الرانف: جليدة طرف الروثة، وطرف غرضوف الأذن. وما استرخى من ألية الإنسان. والرانف: ألية اليد.'),
(3010, 'نفر', 'نفر', 'نفر', 'النفر: من الثلاثة إلى العشرة. يقال: هؤلاء عشرة نفر، أي: عشرة رجال، ولا يقال: عشرون نفرا، ولا ما فوق العشرة. وهؤلاء نفرك، أي: رهطك الذين أنت منهم. والنفر النفير، والجماعة: أنفار، وهم الذين إذا حزبهم أمر اجتمعوا ونفروا إلى عدوهم، قال 28 : ونفر قومك في الأنفار مكتوب والنفر: نفر الحجاج في الثاني والثالث. وامرأة نافرة، وهي التي نفرت من زوجها لإضراره بها مذعورة من فرقه. والمنافرة: المحاكمة إلى من يقضى في خصومة أو مفاخرة، قال زهير: 29 فإن الحق مقطعه ثلاث ... يمين أو نفار أو جلاء ونافرت فلانا إلى فلان، فنفرني، أي: غلبني، وقضى لي. وكأنما جاءت المنافرة في بدء ما استعملت، أنهم كانوا يسألون الحاكم: أإنا أعز نفرا.'),
(3011, 'فرن', 'فرن', 'فرن', 'الفرني: طعام، الواحدة: فرنية، وهي: خبزة مسلكة مصعنبة، تشوى، ثم تروى لبنا وسمنا وسكرا، ويسمى ذلك المختبز: فرنا.'),
(3012, 'رنب', 'رنب', 'رنب', 'الأرنب: معروف، للذكر والأنثى، وقيل: الأرنب: الأنثى، والخزر: الذكر. وألف أرنب زائدة، ولا تجيء كلمة في أولها ألف فتكون أصلية إلا أن تكون ثلاثة أحرف مع الألف مثل الأرض، والأمر ... والمرنب: جرذ في عظم اليربوع، قصير الذنب. ويقال: كساء مرنباني ومؤرنب، فأما المرنباني فالذي لونه لون الأرنب. وأما المؤرنب فالذي يخلط غزله بوبر الأرنب، وقيل: بل هو كالمرنباني، كلاهما مخلوط بوبر الأرانب.'),
(3013, 'ربن', 'ربن', 'ربن', 'أربنت الرجل: أعطيته ربونا، وهو دخيل، وهو نحو عربون.'),
(3014, 'نرب', 'نرب', 'نرب', 'النيرب: النميمة. ورجل نيرب: ذو نيرب، أي: نميمة.. نيرب ينيرب نيربة، وهو خلط القول بعضه ببعض، كما تنيرب الريح التراب على الأرض فتنسجه. ولا تطرح منه الياء، لأنها جعلت فصلا بين الراء والنون. والنيرب: الرجل الجلد.'),
(3015, 'نبر', 'نبر', 'نبر', 'النبر بالكلام: الهمز، وفي الحديث: أن رجلا قال: يا نبيء الله، فقال النبي صلى الله عليه وآله وسلم: لا تنبر باسمي 30 أي: لا تهمز. وكل شيء رفع شيئا فقد نبره. وانتبر الأمير فوق المنبر. [وسمي المنبر منبرا لارتفاعه وعلوه] 31 . وانتبر الجرح، إذا ورم. ورجل نبار بالكلام: فصيح بليغ، قال: بمعرب من فصيح القوم نبار 32 والنبرة: شبه ورم في الجسد ونحوه. والنبر: ضرب من السباع ليس بدب ولا ذئب.'),
(3016, 'برن', 'برن', 'برن', 'البرني: ضرب من التمر أحمر مشرب صفرة، كثير اللحاء، عذب الحلاوة، ضخم. والبراني بلغة أهل العراق: الديكة الصغار أول ما تدرك، الواحدة: برنية. والبرنية: شبه فخارة ضخمة خضراء من القوارير الثخان الواسعة الأفواه.'),
(3017, 'رنم', 'رنم', 'رنم', 'الترنيم: ما استلذذت من صوت الطرب وتطريب الصوت، وهو ترنم الصوت للقوس والعود والحمامة ونحوها. وهو يرنم الصوت، ويترنم في صوته.'),
(3018, 'رمن', 'رمن', 'رمن', 'الرمان: معروف، من الفواكه، الواحدة: رمانة.'),
(3019, 'نمر', 'نمر', 'نمر', 'النمر: سبع أخبث من الأسد. ويقال للرجل السيىء الخلق: نمر، وقد نمر وتنمر. ونمر وجهه، أي: غبره وعبسه. والنمر من السباع لونه أنمر. وسحاب نمر: فيه آثار كآثار النمر، قال أعرابي: أرنيها نمرة أركها مطرة. ويثنى، فيقال: أرنيهما نمرتين أركهما مطرتين. ويجمع: أرنيهن نمرات أركهن مطرات. والنمير من الماء: العذب الهنيء المريء، المسمن الناجع، قال 33 : [كبكر مقاناة البياض بصفرة] ... غذاها نمير الماء غير المحلل أي: لم ينزل به أحد. وأنمار: حي من ربيعة هم اليوم في اليمن. والنامرة: مصيدة يربط فيها شاة، للذئب.'),
(3020, 'مرن', 'مرن', 'مرن', 'مرن الشيء يمرن مرونة، إذا استمر، وهو لين في صلابة. ومرنت يده على العمل: صلبت واستمرت. ومرن وجه فلان على هذا الأمر، وإنه لممرن الوجه، قال 34 : لزاز خصم مرن ممرن والمارن: ما لان من الأنف، وفضل عن القصبة. والمارن من الرماح: ما لان. والمران: الرماح الصلبة اللدنة.'),
(3021, 'برم', 'برم', 'برم', 'البرم: الذي لا يياسر القوم، ولا يدخل معهم في الميسر، وجمعه: أبرام، قال: إذا عقب القدور عددن مالا ... تحث حلائل الأبرام عرسي 36 والبرم: ثمر الأراك وشبهه من الأشجار. وبرمت بكذا، أي: ضجرت منه برما، ومنه: التبرم، وأبرمني فلان إبراما [أي: أضجرني] . والإبرام: إحكام الشيء، وأبرمت الأمر: أحكمته. والبرام: جمع البرمة، وهو قدر من حجر. والبريم: خيط ينظم فيه خرز فتشده المرأة على حقويها. والبرم: قنان صغار من الجبال، الواحدة: برمة، يعني حبال الرمل فافهم. والبريم: كل ذي لونين. والنضر بن بريم: كان من سادات حمير.'),
(3022, 'لف', 'لف', 'لف', 'اللفف: كثرة لحم الفخذين، وهو في النساء نعت، وفي الرجال عيب، تقول: رجل ألف، أي: ثقيل، قال نصر بن سيار: ولو كنت القتيل وكان حيا ... لشمر لا ألف ولا سؤوم واللفيف: ما اجتمع من الناس من قبائل شتى، ليس أصلهم واحدا، يقال: جاء القوم بلفهم ولفيفهم. واللفف: ما لففوا من هاهنا وهاهنا، كما يلفف الرجل شهود زور. واللفف في المطعم: الإكثار منه مع التخليط. وحديقة لفة، ويقال: لف، والجميع الألفاف، وهي الملتفة الشجر. وألف الرجل رأسه، إذا جعله تحت ثوبه. وألف الطائر رأسه إذا جعله تحت جناحه، قال أمية 1 : ومنهم ملف رأسه في جناحه ... يكاد لذكرى ربه يتفصد'),
(3023, 'فل', 'فل', 'فل', 'الفل: المنهزم 2 ، والجميع: الفلول والفلال. والتفليل: تفلل في حد السيف، وفي غروب الأسنان، ونحو ذلك، قال النابغة 3 : ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائب ويقال: الفلول الجماعة، والواحد: فل، ويقال: الفلول: مصدر. والاستفلال: أن تصيب من الموضع العسر شيئا قليلا من موضع طلب حق أو فلا يستفل إلا شيئا صغيرا أو يسيرا. والفليل: ناب البعير إذا انكسر منه شيء. والفلفل: معروف يحمل من الهند'),
(3024, 'لب', 'لب', 'لب', 'لب كل شيء من الثمار: داخله الذي يطرح خارجه، نحو اللوز وما إليه. ولب الرجل ما جعل في قلبه من العقل وجمع اللب: ألباب. واللباب جامع في كل ما خلا الإنسان، لا يقال في موضع اللب من الإنسان: لباب. ولباب القمح، يعني الحنطة، ولباب الفستق. واللباب من الإبل: خيارها وأفضلها. ولباب الحسب: محضه. واللباب: الخالص من كل شيء، قال: وأهل العز والحسب اللباب 4 وقال 5 : سبحلا أبا شرخين أحيا بناته ... مقاليتها فهي اللباب الحبائس يصف الإبل. وقال الحسن في وصف الفالوذج: لباب القمح بلعاب النحل. واللبابة: مصدر اللبيب، والفعل منه: لبب 6 يلب. ورجل ملبوب، أي: موصوف باللب. ولبابة: من أسماء النساء، قال حسان: وجارية ملبوبة ومنجس ... وطارقة في طرقها لم تشدد 7 واللب: موضع اللبب من الصدر. واللبب: البال، يقال: ذاك الأمر منه في بال رخي، وفي لبب رخي. واللبب من الرمل: شبه حقف، قال ذو الرمة 8 : براقة الجيد واللبات واضحة ... كأنها ظبية أفضى بها لبب وأما قول أبي ذؤيب 9 : ونميمة من قانص متلبب ... في كفه جشء أجش وأقطع فإنه كل من جمع ثيابه وتحزم فقد تلبب، وهو هاهنا المتسلح، شبهه بمن جمع ثيابه. واللبة من الصدر: موضع القلادة، وهي واسطة حواليها اللؤلؤ وخرز قليل وسائرها خيط. والتلبيب: مجمع ما في موضع اللبب من ثياب الرجل، يقال: أخذ فلان بتلبيب فلان. ولببته، إذا جعلت في عنقه ثوبا أو حبلا، وقبضت على موضع تلبيبه، [وأنت] 10 تعتله. والصريخ يصرخ إلى القوم ويلبب، لأنه يجعل كنانته أو قوسه في عنقه ثم يقبض على تلبيب نفسه ويصرخ. قال: إنا إذا الراعي اعترى ولببا ويقال: هو في هذا الموضع: التردد. واللبلبة: فعل الشاة بولدها إذا لحسته بشفتها. واللبلاب: حشيشة يتداوى بها.'),
(3025, 'بل', 'بل', 'بل', 'البلل اسم من (بل) . والبلة والبلل: الدون. وبلة اللسان: وقوعه على مواضع الحروف، واستمراره على المنطق، يقال: ما أحسن بلة لسانه، أو ما يقع لسانه إلا على بلته. والبلال: البلل وهو الاسم، والواحد مثله، ويقال: هو جمع بلة، قال الساجع: اضربوا أميالا تجدوا بلالا. ويقال: بلال هاهنا اسم رجل. والبليل: الريح الباردة. ويقال: بل فلان من مرضه وأبل واستبل، أي: برأ، والاسم منه: البل. وفي الحديث: وهي لشارب حل وبل ، البل: المباح بلغة حمير، وقال: إذا بل من داء به ظن أنه ... نجا وبه الداء الذي هو قاتله 11 وبل فلان بفلان، أي: وقع في يديه، قال: بلت به غير طياش ولا رعش 12 وقال طرفة 13 : [إذا ابتدر القوم السلاح وجدتني] ... منيعا إذا بلت بقائمه يدي والبل: مصدر الأبل من الرجال، وهو الذي لا يستحي ولا يبالي ما قال، قال: ألا تتقون الله يا ال عامر ... وهل يتقي الله الأبل المصمم 14 ويقال للإنسان إذا حسنت حاله بعد الهزال: قد ابتل وتبلل. والبلبل: طائر يكون في أرض الحرم، حسن الصوت، يألف الحرم. والبلبلة: ضرب من الكيزان في جنبه بلبل ينصب منه الماء. والبلبلة: وسواس الهموم في الصدر، وهو البلبال، والجميع: البلابل. والبلبلة: بلبلة الألسن المختلفة، يقال والله أعلم: إن الله عز وجل لما أراد أن يخالف بين ألسنة بني آدم بعث ريحا فحشرتهم من كل أفق إلى بابل فبلبل الله بها ألسنتهم، ثم فرقتهم تلك الريح في البلاد. وفي الحديث: كان الناس بذي بلى 15 ويروى: بذي بليان، مكسورة الباء، مشددة اللام، يقال: أراد بذلك، والله أعلم، تفرق الناس وتشتت أمورهم. قال: ينام ويذهب الأقوام حتى ... يقال: أتوا على ذي بليان 16 يعني: أنه أطال النوم ومضى أصحابه حتى صاروا متفرقين إلى مواضع لا يعرف مكانهم فيها.'),
(3026, 'لم', 'لم', 'لم', 'لم، خفيفة: من حروف الجحد بنيت كذلك. ولم، اللام مفصولة من الميم، إنما هي لام ضمت إلى (ما) ، ثم حذفت الألف، كما قالوا: بم، ونحو ذلك غير أنها لما كانت كثيرة الجري على اللسان أسكنت الميم، وقد تسكن في (بم) في لغة رديئة. ولم: عزيمة فعل قد مضى فلما جعل الفعل معها على حد الفعل الغابر جزم، وذلك قولك: لم يخرج زيد، وإنما معناه: لا خرج زيد، فاستقبحوا هذا اللفظ في الكلام فحملوا الفعل على بناء الغابر فإذا أعيدت (لا) و (لا) مرتين أو أكثر حسن حينئذ لقول الله عز وجل: فلا صدق ولا صلى 17 ، أي: لم يصدق ولم يصل، وإذا لم تعد (لا) فهو في المنطق قبيح، وقد جاء في الشعر، قال: إن تغفر اللهم تغفر جما ... وأي عبد لك لا ألما 18 أي: لم يلم. [وأما (ألم) فالأصل فيها لم أدخل فيها ألف استفهام. وأما (لم) فإنها (ما) التي تكون استفهاما وصلت باللام] 19 . وأما (لما) فعلى معنيين: أحدهما: من جمع (ما) و (لم) فجعلت لما بناء واحدا. وثانيهما: بمعنى (إلا) كقوله تعالى: إن كل نفس لما عليها حافظ 20 . ومنهم من يقول: لا، بل الألف في (لما) أصلية والميم منها في موضع العين، وهو بوزن فعل. واللمم: الجمع الكثير الشديد، [تقول] : كتيبة ملمومة، وحجر ملموم، وطين ملموم، قال أبو النجم: ملمومة لما كظهر الجنبل 21 يصف هامة العبير. والآكل يلم الثريد، فيجعله لقما عظاما ثم يأكله أكلا لما. واللمم: مس الجنون. ورجل ملموم: به لمم. واللمم: الإلمام بالذنب الفينة بعد الفينة، يقال: بل هو الذنب الذي ليس من الكبائر، ومنه قوله [تعالى] : الذين يجتنبون كبائر الإثم والفواحش إلا اللمم 22 . والإلمام: الزيارة غبا. والفعل: ألممت به، ويجوز في الشعر: ألممت عليه. والملمة: الشديدة من شدائد الدهر. واللمة: شعر الرأس إذا كان فوق الوفرة. ولمة الوتد: ما تشعث من رأسه الموتود بالفهر. واللمة، مخففة: الجماعة من الرجال والنساء أيضا، قال الكميت: فقد أراني والإيفاع في لمة ... في مرتع اللهو لم يكرب لي الطول 23 أي: في جماعة. وفي الحديث: جاءت فاطمة إلى أبي بكر في لميمة من حفدها ونساء قومها 24 . واللملمة: إدارة الحجر واستدارة الطين، قال: لما لممنا عزنا الململما 25 وتقول: أعوذ بالله من اللامة والسامة، فأما اللامة فما يخاف من مس، أي: فزع، ومن جعل السامة المنية فإن الكلام محال، لأن الموت لا استعاذة منه، ومن جعله بلية جاز. والعين اللامة، هي التي تصيب الإنسان ولا يقولون: لمته العين، ولكنه نعت من اللمم على حذو الذراع والفارس ونحوهما مما يحمل على النسب بذي وذات. ويلملم: هو ميقات أهل اليمن، الموضع الذي يحرمون منه إلى مكة.'),
(3027, 'مل', 'مل', 'مل', 'الملة: الرماد والجمر: يقال: مللت الخبزة أملها في الملة ملا فهي مملولة، وكل شيء تمله في الجمر فهو مملول. والمملول: الممتل من الملة، قال حميد: 26 كأنه غول علاه غول ... كأنه في ملة مملول يصف الفيل، أي: كأنه مثال ممثل مما يعبد في بعض ملل الأديان من المشركين. وطريق ممل: قد سلك حتى صار معلما، قال أبو دواد: رفعناها ذميلا في ... ممل معمل لحب 27 وملة رسول الله صلى الله عليه وآله وسلم: الأمر الذي أوضحه للناس. وامتل الرجل: أخذ في ملة الإسلام، أي: قصد ما أمل منه. والملل والملال: أن تمل شيئا، وتعرض عنه. ورجل ملولة، وامرأة كذلك، قال: وأقسم ما بي من جفاء ولا ملل 28 وملل: اسم موضع في طريق البادية على طريق مكة، قال: على ملل يا لهف نفسي على ملل 29 والإملال: إملال الكتاب ليكتب. والململة: أن يصير الإنسان من جزع أو حرقة كأنه يقف على جمر. والملمول: المكحال. وبعير ملامل، أي: سريع.'),
(3028, 'نفل', 'نفل', 'نفل', 'النفل: الغنم، والجميع: الأنفال. ونفلت فلانا: أعطيته نفلا وغنما. والإمام ينفل الجند، إذا جعل لهم ما غنموا. والنافلة: العطية يعطيها تطوعا بعد الفريضة من صدقة أو صلاح أو عمل خير. والنافلة: ولد الولد. والنفل: ضرب من النبات من دق الشجر. والنوفل: السيد من الرجال. ويقال لبعض السباع: نوفل. والانتفال: شبه الانتفاء، وهو التنصل من الأمر، يقال: قال لي فلان قولا فانتفلت منه، أي: أنكرت أن أكون فعلته. وانتفل فلان من بني فلان، أي: انتفل. وانتفل من معونتهم ونصرهم، قال: أمنتفلا من نصر بهثة خلتني ... ألا إنني منهم وإن كنت أينما 30 والنوفلة: المملحة.'),
(3029, 'فلن', 'فلن', 'فلن', 'أما فلان فيقال في تقديره: فعال، وتصغيره: فلين. وبعض يقول: هو في الأصل: فعلان حذفت منه واو أو ياء، كما حذفت من الإنسان، وتصغيره في هذا القول: فليان، وحجتهم في قولهم: فل بن فل، كقولهم: هي بن بي، وهيان بن بيان. وفلان وفلانة: كناية عن أسماء الناس، معرفة، لا يحسن فيه الألف واللام، ويقال: هذا فلان آخر، لأنه لا نكرة له، ولكن العرب إذا سموا به الإبل قالوا: هذا الفلان، وهذه الفلانة، فإذا نسبت قلت: فلان الفلاني لأن كل اسم ينسب إليه فإن الياء تلحقه تصيره نكرة، وبالألف واللام يصير معرفة في كل شيء.'),
(3030, 'لبن', 'لبن', 'لبن', 'اللبن: خلاص الجسد، ومستخلصه من بين الفرث والدم، وإذا أرادوا الطائفة القليلة قالوا: لبنة. وفي الحديث أن النبي صلى الله عليه وآله وسلم قال الخديجة ما يبكيك، فقالت: درت لبنة القاسم فذكرته 31 ، ويقال: درت دريرته. وناقة لبون ملبن، قد ألبنت، إذا نزل لبنها في ضرعها، وإذا كانت ذات لبن في كل أحايينها فهي لبون. وولدها في تلك الحال: ابن لبون. وكل شجرة لها ماء أبيض فهو لبنها. واللبنى: شجرة لها لبن كالعسل، يقال له: عسل لبنى. واللبان: الكندر. واللبانة: الحاجة، لا من فاقة، بل من همة. ولبينى: اسم ابنة إبليس عليهما لعنة الله. واللبان: الصدر. واللبنة: واحدة اللبن، والملبن: الذي يضرب به اللبن، والملبن أيضا: شبه محمل ينقل فيه اللبن ونحوه. والتلبين: فعلك حين تضربه، وكل شيء ربعته فقد لبنته. واللبنة: رقعة في الجيب. وفرس ملبون: يسقى اللبن. ورجل لابن تامر في قوله 32 : وغررتني وزعمت أنك ... لابن بالصيف تامر أي: ذو لبن وذو تمر. وأما قوله 33 : فهل لبينى من هوى التلبن ... راجعة عهدا من التأسن فقد اشتق هذا الفعل من اسمها، كقولهم: تمضر، أي: صار مضري الهوى. والتلبين: مرق من ماء النخالة، يجعل فيها اللبن. وبنات اللبن: معى في البطن معروفة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(3031, 'نبل', 'نبل', 'نبل', 'النبل: في الفضل والفضيلة، وأما النبالة فهي أعم، تجري مجرى النبل، وتكون مصدرا للشيء النبيل الجسيم، قال: كعثبها نبيل 34 وهو يعيبها بذلك. والنبل: في معنى جماعة النبيل، كما أن الأدم جماعة الأديم، وكرم [قد يجيء جماعة] كريم، قال 35 : [وأن يعرين إن كسي الجواري ... فتنبو العين] عن كرم عجاف وفي بعض القول: رجل نبل. وامرأة نبلة وقوم نبال. وفي المعنى الأول: قوم نبلاء. والنبل: عظام المدر والحجارة ونحوها، الواحدة: نبلة، ويقال للصغار أيضا: نبل، وهذا من الأضداد. وقال رجل من العرب توفي أخوه فأورثه إبلا فعيره رجل بأنه فرح بموت أخيه لما ورثه، فقال الرجل: أفرح أن أرزأ الكرام وأن ... أورث ذودا شصائصا نبلا إن كنت أزننتني بها كذبا ... جزء، فلاقيت مثلها عجلا 36 يعني: صغار الأجسام. والنبل: اسم للسهام العربية، وصاحبها: نابل، وحرفته النبالة، وهو أيضا النبال، وإذا رجعوا إلى واحد قالوا: سهم. وتقول: نبلت فلانا بكسرة أو بطعام أنبله نبلا إذا ناولته شيئا بعد شيء، قال: فلا تجفواني وانبلاني بكسرة 37'),
(3032, 'نمل', 'نمل', 'نمل', 'النمل: قروح تخرج في الجنب، ورقيتها: [أن يقال] : العروس تحتفل، وتقتال وتكتحل، غير أن لا تعصي الرجل ... والنمل، والجميع: النمال، والواحدة: نملة، قال 38 تدب دبيبا في العظام كأنه ... دبيب نمال في نقا يتهيل ورجل نمل: نمام، قال الكميت: ولا أزعج الكلم المحفظات ... للأقربين ولا أنمل 39 أي: لا أمشي بالنميمة، وهي: النملة. ورجل نمل الأصابع: لا يكاد يكف عن العبث بأصابعه، وكذلك [يقال] للفرس الذي لا يكاد يستقر: إنه لنمل القوائم. والنمل: الخدر، تقول: نملت يده نملا. والأنملة: المفصل الأعلى الذي فيه الظفر من الإصبع. ورجل مؤنمل الأصابع، أي: غليظ أطرافها. ويقال له: نمل، نعت له في الغلظ ... والنمل: الرجل الذي لا ينظر إلى شيء إلا عمله. والنملة: مشق في حافر الدابة. والنأملة: مشي المقيد. ينأمل في قيده.. والبعير ينأمل في مشيه. وكتاب منمل: مكتوب، هذلية.'),
(3033, 'لفم', 'لفم', 'لفم', 'اللفام: النقاب على طرف الأنف مثل اللثام على الفم، وقد لفمت فاها بلفام، إذا نقبته.'),
(3034, 'فلم', 'فلم', 'فلم', 'الفيلم: المشط الكبير، وإنما هو المدرى. والفيلم: العظيم، قال البريق الهذلي: 40 ويحمي المضاف إذا ما دعا ... إذا فر ذو اللمة الفيلم'),
(3035, 'بلم', 'بلم', 'بلم', 'أبلمت الناقة، إذا ضبعت فورم حياها. [والمبلم: الناقة البكر التي لم تنتج، ولم يضربها الفحل] 41 . والأبلمة: ما يشد على حرزة البقل والرياحين. والبلم: صغار السمك ... [والبيلم: قطن القصب]'),
(3036, 'ملب', 'ملب', 'ملب', '42 الملاب: نوع من القطن، والملاب: نوع من العطر.'),
(3037, 'نف', 'نف', 'نف', 'النفنف: الهواء. وكل شيء بينه وبين الأرض مهوى فهو نفنف. قال ذو الرمة 1 : ترى قرطها في واضح الليت مشرفا ... على هلك في نفنف يترجح وقال 2 : إذا علون نفنفا فنفنفا يريد: المفازة.'),
(3038, 'فن', 'فن', 'فن', 'الفن: الحال، والفنون: الضروب، يقال: رعينا فنون النبات، وأصبنا فنون الأموال، ويجمع على أفنان أيضا، قال: قد لبست الدهر من أفنانه ... كل فن ناعم منه حبر 3 وأفانين الشباب: أوائله، ويقال: الأفانين: أشياء مختلفة، مثل، ضروب الرياح، وضروب السيل، وضروب الطبخ، ونحوها. والرجل يفنن الكلام، أي: يشتق في فن بعد فن. والتفنن: فعلك. والتفنين: فعل الثوب إذا بلي من غير تشقق. والفنن: الغصن، وجمعه: أفنان.'),
(3039, 'نب', 'نب', 'نب', 'نب التيس ينب نبيبا.. وقال عمر لوفد أهل الكوفة حين شكوا سعدا: ليكلمني بعضكم، ولا تنبوا عندي نبيب التيوس.'),
(3040, 'بن', 'بن', 'بن', 'البنة: ريح مرابض الغنم والبقر والظباء.. وتقول: أجد لهذا الثوب بنة طيبة من عرف تفاح أو سفرجل. والإبنان: اللزوم، تقول: أبنت السحابة، إذا لزمت ودامت. وأبن القوم بمحلة، أي: أقاموا بها، قال: يا أيها الركب المبنون 4'),
(3041, 'نم', 'نم', 'نم', 'النميمة والنميم: هما الاسم، والنعت: نمام، والفعل: نم ينم نما ونميما ونميمة ... ونمى تنمية. والنميمة: صوت الكتابة، ويقال: همس الكلام، كما قال أبو ذؤيب: 8 ونميمة من قانص متلبب ... [في كفه جشء أجش وأقطع] يريد: أن الحمر سمعت حسا من نميمة القانص. والنمنمة: خطوط متقاربة قصار شبه ما تنمنم الريح دقاق التراب. ولكل وشي تمنمة. والنمنم: البياض الذي يكون على الأظفار، الواحدة: نمنمة، قال رؤبة يصف قوسا رصع مقبضها بسيور منمنمة: رصعا كساها شية نميما 9 أي: نقشها. وكتاب منمنم: منقش.'),
(3042, 'من', 'من', 'من', 'المن: كان يسقط على بني إسرائيل من السماء، إذ هم في التيه، وكان كالعسل الحامس حلاوة. وسئل النبي صلى الله عليه و [على] آله وسلم عن الكمأة، فقال: بقية من المن، وماؤها شفاء للعين. والمن: قطع الخير، وقوله [جل وعز] : لهم أجر غير ممنون* 10 ، أي: غير مقطوع. والمن: الإحسان الذي تمن على من لا يستثيبه. والمنة: الاسم، والله المنان علينا بالإيمان والإحسان في الأمور كلها، الحنان بنا. والمنة، يقال: قوة القلب، ويقال: انقطاع قوة القلب، قال: فلا تقعدوا وبكم منة ... كفى بالحوادث للمرء غولا 11 وفلان ضعيف المنة، وليس لقلبه منة. ومن ومن: حرفان من أدوات الكلام. والمنون: الموت، وهو مؤنث، قال: كأن لم يغن يوما في رخاء ... إذا ما المرء منته المنون 12 وسميت منونا، لأنها تمن الأشياء، أي: تنقصها.'),
(3043, 'قال الخليل', 'قال الخليل', 'قال', 'القافُ والکاف لا يجتيعان فى كلمةٍ واحدق الا أن تکون الكلمة معرب من كلام العَجم وكذلك الحيمٌ مع القاف لا يالف لاف لازم. وغيرٌ هذه الكلمات المعربة وهی الحوالِقٌ والقبَجُ لَيْسّتا بعربية مَحْضة ولا فارسية.'),
(3044, 'معربة مثل', 'معربه مثل', NULL, 'البوم وليبة وهی فارسية وبم العود. ویبنیم وهو موضع.'),
(3045, 'آو', 'او', 'او', 'نظر ما يأنى فى (أوأ).'),
(3046, 'آس', 'اس', 'اس', 'انظر ما يأتى فى (أوس).'),
(3047, 'آف', 'اف', 'اف', 'انظر ما يأتى فى (أوف).'),
(3048, 'آم', 'ام', 'ام', 'انظر ما يأتى فى (أوم).'),
(3049, 'آید', 'اید', 'اید', 'وأتان أبد :فی کل عام تلد وقیل: الآبد الوحشية ویقال: بل بث وليس فى كلام العرب فيل لا أن کلف کل ف * قینی کلم خن على فول یکلم بهاء فا ما جاء عن العرب فهو الذى جَمّعناهء ويقال: اب وجطبٌ ونکخ. وآبادُ الدهر: طوال الدهرء والأبيد مثل الآباد. والآبدة: الغريبة من الكلام والجميع آوابد والأوابد: الرخن. وابد فلاث: طالت غربته. وتابّدت الداز: حلت من أهلها.'),
(3050, 'أير', 'اير', 'اير', 'الأبْرُ: ضَرْبُ العقرب بإبرتهاء وهى تأبرٌ. والأبر: تلفح النحل؛ ومثله: التأبير يأبرُها ويُوَبَرُها. وَالْأَبْر: علا الرَرْع بها يُصْلِحُهُ من السقى والتعاهد. قال طرفة: وی الأصلٌ الذى فى مله يُطْلِعٌ الآبرٌ ززع ابر'),
(3051, 'أى', 'اي', 'اي', 'صاحبه. والأبار: صانع الب وصنعته: الإبارة. وأبر فلانٌ عليه أى: غَلبه.'),
(3052, 'الإبرة', 'الابره', NULL, 'عم مسو مع طرف الزند ما يلى الذّراع إلى طرف الاصّع قال: ۱ حيث تلاقى الإبرة القبي'),
(3053, 'قبيح', 'قبيح', NULL, 'طرف الرّنْدٍ نفسه. وفى الحديث: وخير الال مر مسأمورق وس کة (۱) ديوانه (ص 4 وتهذيب اللغة )۲٦٠/٠١(‏ ولسان العرب (أبر). (۲) الرجز لأبى النجم فى لسان العرب (قبح). o‏ باب الهمزة ۶ ل (۱) و و £ 5 عدن 2 فس 51 مأبورق( 5 يريد [عابورة]: طريقة مستقيمة. والابار: صانع الإبرة وصنعته: الابارة.'),
(3054, 'الأبار', 'الابار', NULL, 'حافر البثر کالیثار. كج نياع ند o‏ 9 ما ةوه و له'),
(3055, 'أدر', 'ادر', 'ادر', 'یقال : فلان یابز فى عدوی ای: پستریح ساعة ویمضی ساعة.'),
(3056, 'أيس', 'ايس', 'ايس', 'الْأَبْس: يكونُ توبيخاء ويكون ترويعا .. بسنت بها صنع سس قال: ولا تسه بالذى كان فاعله'),
(3057, 'آی', 'ای', 'ای', 'بزحر ر وتژویم. وأبسنته تأبيسًا [إذا قابلته عکروه]. وأَبْسَهُ یابسه بسا أى: ذلله والوابس : الذلل.'),
(3058, 'الأبس', 'الابس', 'ابس', 'السلحفاة.'),
(3059, 'آیض', 'ایض', 'ایض', 'الأض: العَقْل فى الرّخْليْن وربّما استعملَ فى الأيدى قال: آکلف لم يشن يديه و ابض أى عاقل ويأبضه: يَحْتله. والأبضان: باطنا ار کین وباطنا ارف والإباضييّة: رم من الور لهم را وضوی. ویقال للشراب: مض شاه لأنه يَمْجِلْ كأنّه مُأبوض.'),
(3060, 'أيط', 'ايط', 'ايط', 'تابط فلا سَيّفًا أو شيئًاء إذا أحذه تحت إبطه ومنه سُمّى: تابط شرا'),
(3061, 'أبق', 'ابق', 'ابق', '۱ بق: قشر القنب. والإباق: ذهابُ لد من غير حوفي ولا كد عَمَلِ وا پر ڏه فإذا كان من كد عَمَل أو حوفي لم یرد'),
(3062, 'أبل', 'ابل', 'ابل', 'الابل رب التى حلت فَطِيعًا قطیعاء نعت فى الإبل خاصّة. والإنّؤل: طول الإقامة فى الرْعی والوضع. ورجُلْ آبل: ذو إبل .. وجمار آبل: مقیم فى مکانه لا يبرح. وأبلت الابل تأبل أبلاً أى: احترات بالرطب عن الاء. وتأبّل الرَجْلُ عن امرأته (۱) أورده الهیثمی فى المجمع )٠١۸/١(‏ وقال: رواه هد والطبرانى ورحال أحمد ثقات. (۲) فى ديوانه (۲۱۲/۷) ولسان العرب (أبس). ويروى وليث غاب. (۳) الرجز فى لسان العرب (أبض) لأبى محمد الفقعسى. )٤(‏ وهم الخوارج الذين يكفرون مرتكب الكبيرة.'),
(3063, 'تأبلاء أى', 'تابلاء اي', NULL, 'اجتزأ عنهاء كما يجتزئ الوحش عن الماء قال لبيد : وإذا ركت غرّزی أَجْمَرّت أو قرابى عدو حون قد بل'),
(3064, 'آین', 'این', 'این', 'آبان: اسم رجحل وجیل. ویقال: لا و خر وش ا أى: یرد به فهو مأبون ع لد'),
(3065, 'يقال', 'يقال', NULL, 'لا يؤين ع إلا فى الشر. والأبنة: عقدة فى العصا؛ وجمعها: ین قال: وأرزنات ليس فيها أنن'),
(3066, 'تقول', 'تقول', NULL, 'ليس فى حسب فلان نت کقولك: ليس فيه وصمة. والأَبْن: تس المأبون'),
(3067, 'الفعل', 'الفعل', 'فعل', '۳ یبن ما أى : عاب. والتأبين: مد الميت عند مرئیته قال الا © ھت 0 مره رر f o‏ و تاك'),
(3068, 'انه', 'انه', 'انه', 'الابهة: العظمق وفی ری( : '': رما فعلت 1 1 ویقال لاب أبيه.'),
(3069, 'أيو', 'ايو', 'ايو', 'أَبَوْت الرّجل آبوه إذا كنت له أبَا. ویقال: فلا يأبو هذا اليتيم إباوة أى يغذوه كما یغذو الوالد وله ویقال فى المثل: لا أبا لك كأنه عدحه. وتصغير الأب: ی و تصعير الاباء على وجهين: فأحودهما: ییون والآخر: آبیاء لأ كلّ جماعة على £ 7 .0 3 كر سای 1 3 3" 13 5 2 أفعال فانها تصغر على حذها. والابوة: الفعل من الاب كقولك: تابيت أباء وتبنيت ابنا وتأْمت ۳ . وقلا ن الاب والبنوة والامومة. و یحور ه فى الشعر أن 7 تقول: هذان اباك وأنت تريد أباك وأمّك. ومن العرب من يقول: أبوتنا آکرم الآباء یجمعون (الأب) على فعولة كما يقولون: هؤلاء عمومتنا وحؤولتنا. ومنهم من يجْمِّمٌ الأب: أبين قال الرّاحز: (۱) ديوانه (ص )١7‏ ولسان العرب (غرز) (أبل) الراد: حركت غرزى أو قرابى. فخ الييت فى اللسان (فجر) و صدره فيه: نازع القوم إذا نازعتهم). (۳) الراجز: رب دیوانه (ص ۱۰۲). (؛) لم أجده. o٤‏ ۱ باب الهمزة أقبل بَهُسوی من دوين الطرب‌ال وهو يُفَدَى بالأيينَ واضال)'),
(3070, 'آیی', 'ایی', 'ایی', 'الأبى مقصور: داءٌ يأحذ العز فى رُؤُوميهاء فلا تكادُ تلم .. ...ا بيت العثر تأَبَى أب شديدًا .. وعنژ أبية وتي" آب قال: وی فلان یی ابا أى: ترك الطاعة ومال إلى المغصية قال الله عر وحل: فکذب وآلی4 [طه: 1ه] . .. ووخ آحر: كل من ترك أمرًا ورد فقد آبی. ورجا'),
(3071, 'آبی', 'ابی', 'ابی', 'ذو بای وقوم ییون 0 حفيف قال: بى اليم من فرم ابا'),
(3072, 'أتب', 'اتب', 'اتب', 'الإتب: غير الإزارء رايا Ed‏ وليس على خياطة ة السّراويل ولكنه قمیص مخیط امحانبین.'),
(3073, 'أقل', 'اقل', 'اقل', 'الأثلاث: أن تقارب الخَطْوَ فى عضب وتقول: لبیل ومثله آنن بای قال: آرانی لا آتيك الا كأنمسا أسأت ولا آنت غَضْبانُ تأ“'),
(3074, 'أقم', 'اقم', 'اقم', 'وَالَأتمٌُ: الحماعة من الرجال والنساء فى فرح أو خزن.'),
(3075, 'آتن', 'اتن', 'اتن', 'الأتوك: آتون الحَمّام وامصَاصة ونخوهما. والأثوث: یوت فى الکان ون ووت 7 بالمكان أى ام به . والأتاث: العانق ویّلات آتن.'),
(3076, 'أقو', 'اقو', 'اقو', 'الأتوٌ: الاستقامة فى الستیر والسرعت وياتو لب آتّا. وتقول العرب: توت فلانا من أرض كذاء أى ميرت إليه ويجوز فى معنی أنيته قال: .)1۰۲/۱۵( الرجز فى التهذيب‎ )١( ديوانه (۰۱۳۹۱/۲ ولسان العرب (مرأ).‎ )۲( البیت لثروان العکلی فى لسان العرب (أتل).‎ )۳('),
(3077, 'امؤاتاة', 'امؤاتاه', NULL, 'حن الطاوّعة. وتَأنَى لفلان آمره واه الله تأتيةء قال: وأنا تی 1 الدهرٌ حتى انح والآنى والأتى لغتان والصواب: الأتئ. والتیْ حماعة وكذلك الآتاء الجماعة وهو ما وَقعّ فى النهر من حشب أو ورق ونحوه ًا لا بحبس لاء. والأتئ عند العامّة النهِرُ الذى يجرى فيه الماء إلى الحوض واشمع لت والآناء وقالت طائفة من الناس: الأتى السَيّل الذى لا يَدْرَى من أينَ آتی. وأَيْتْ للماء تأتيا إذا حرفت له مُجری قال الشاعر: وبعض القول ليس له عِناجٌ كيل الماء ليس له إتاءا" وقال: حلت سبل انی كان يسه ورفعته إلى السجفی فالنّد۹)'),
(3078, 'آنی', 'انی', 'انی', 'وتقول: أتانى فلانٌ اتيا واتیانا وأتيّة و احدة ولا يقال: إتيانة واحدة [لأن الصادر كلها إذا جُعِلَت واحدة ردّت إلى بناء فغلة,] ۱ وذلك إذا كان:منها الفمل على دهعل أو قل فإذا أدسِلَت فى الفعل زيادات فوق ذلك أَدْخِلَتْ فيها زيادتها فى الواحدة كقولك: إقبالة واحدة ومثل تَفَكّلَ تفعلة واحدة وأشباه ذلك وذلك فى الشیء (۱) البيتان خالد بن زهير فى المحكم (۲۳۰۰۲۲۹/۱۰). (۲) الشطر بلا نسبة فى التهذيب (557/ ؛ وتاج العروس (أتى). (۳) البيت فى اللسان (عنج) غير منسوب. (ه) ما بين المعقوفتين من اللسان. ۹ باب الهمزة الذی يَحَسُنُ أن تقول: فغلة واحدة والا فلاء قال: نی وأ ابن غلاق لیقرتسی ‏ کفابط الکلب تیغی الطرّق فى الدب'),
(3079, 'أثث', 'اثث', 'اثث', 'أث التبات والشعر یه مت ان فهو آثیت ویوصف به الشّعر الكثير والتبات الف قال : ۱ وفترع یفشی ال أسْوَدَ فاحم نوک انحل تک [والأنّاث: : أنواعٌ التاع من متاع ابیت و ونحوو]!'''),
(3080, 'آثر', 'اثر', 'اثر', 'لأر بقيّة ما ترى من کل شىء وما لا ری بعد ما بیع والإثرُ: جلاص السّمُن. ور السّيف: ضربتة. وذهبت فى إِنْرٍ فلان, أى: اسقَفیت لا يشت منه فعل هاهناء قال : بانت معاد فقلبی الوم مول ميم ار مَنْ لم جز مکبول الق الصّفة. ار حدیث: آن یأیره رم عن قوب أى: يُحدّث به فى آثارهې أى: بَعْدَهُم والصدر: الأثارة. والمأئرة: الکرمت وانما جذت من هذا؛ لأنها یهافر عن قرن يَتَحدّثون بها. مار کل قوم: مساعى آبائهم. والأثير: الكريم : توثره بفضلك على غیره والمصدر: الإثرة. [تقول]: له عندنا ثْرة. واستأئر الله بفلانه إذا مات وهو من يُرجَى له الحنة. واستأئرت على فان بکذا وكذاء آی: یت به تفسی عليه دونه. واثر'),
(3081, 'سیف', 'سیف', 'سیف', 'وشیه الذى يقال له: الفرند و[قولهم]: سیف مأثور من ذلك ويقال: هو اير اسف مثل ذميل [فعيل] وأثرٌ السّيف [فعل] مخقف قال: کانهم اسف یض یماد عضب مَضاريها باق بها الأ [فتقل] بض بضمتین. وقال: كأنٌ بقايا ال فوق متونه مدب الدَبّى فوق النقا وهو سارح (۱) البيت بلا نسبة فى التهذيب ٥۹/۸(‏ ۳۰۰/۱ وراللسان (أتى) (غبط). (۲) البيت من معلقة امرئ القيس فى ديوانه (ص .)١١١‏ (۳) تكملة ما نقل من العين فى التهذیب 155/ . متيم إثرها لم يجز eens‏'),
(3082, 'یر خفيفة', 'یر خفيفه', 'یر', 'یه مرفقة تتحد للسسّرْج کالصفةه > تلقى على السَّرْجء ویلقی عليها الستّرْج. وقد أئرت أن أفعل کذا و کذا؛ وهو هم فى عَزم . .. وتقول: افعَلْ يا فلا هذا آثرا مّاه أى إن أحرّت ذلك الفعل فافعل هذا إِمّا لا. والآثر: بوزن فاعل. وتفسير (إمَالا: إن (لا) و(ما) صلة فجعلت كلمة واحدة فأییلت. والآثر والواثر: لغتان هو الذى بر تحت حف البعير المعروف الرقيق بذلك.'),
(3083, 'أفف', 'افف', 'افف', 'آلفته آنفه آنفا: تبعته ولاف ؛: الشايع. وتأثفناه: صرنا حواليه كالأثافى.'),
(3084, 'الأثفية', 'الاثفيه', NULL, 'معروفة وهى: ْلب فى قول من قال: أثفت. وهی: أفعولة فيمن قال: ٠‏ ثفیت'),
(3085, 'أذكل', 'اذكل', NULL, 'الأنَكُولَ: لغة فى العتکول.'),
(3086, 'أثل', 'اثل', 'اثل', 'الأثل: شجر يشبةُ شب الطرقاء إلا أنه عم ينها وأَحُودُ مها عُوداء بع منه ضاخ الصفر الجياد . وتقول: لل الله ماله أى: کرد وقد 5 فلا تأثيلاً إذا کر .. وتال مُلکه وأمواله .. وتال فلا : فى م مَعْنى انل ... قال۳: أثل ملک خندفا فُدَعَما وقد أل يأل وله وهو آثل قال رؤبة": ربابة يت وملا آثلا'),
(3087, 'أثم', 'اثم', 'اثم', 'نم فلان أن إثماء أى: وقع فى الإنم كقولك: حرج إذا وقع فى فى ارج. وتنم'),
(3088, 'الأثيمة', 'الاثيمه', NULL, 'فى كثرة رکوب الإنم. والاثم: الفاعل.'),
(3089, 'آفی', 'افی', 'افی', 'أَنَى يأثى فلا أثيّا وأثوا وإثاوة وإثايق أى: نم عليه وسعی به إلى السلطان واصله الواو فى اَی نی ولكن حَمَلُوه على یفیل كما قالوا: خدى يُخدىء ثم رجعوا فى الصدر إلى الواو فقالوا: حدوة وإثاوة وتأنينا: نم بعضنا على بَعْض. وأنوّت مثل أَنْيِت إذا سعيت به.'),
(3090, 'أجج', 'اجج', 'اجج', 'أَجَّتٍ النارٌ توج أحيجًا. وأَحَّجْتها تأحیجا. وائعج ارّ: اشتدت أجّة الصّيف.'),
(3091, 'الأجاج', 'الاجاج', NULL, 'الماء المر الملح قال الله تعال: #وهذا ملح أجا ج4 [الفرقان: ۰۲75۳ وهو الشّديدُ اللوحة والرارق مثل ماء البحر. ويأجوج وماجوج يقرأ بالهمز وبغير الهمزء ومن لم يهمز قال: هو مأحوذ من يج ومج على بناء فاعول. (۱) الرجز لرؤبة فى اللسان (أثل) وتهذيب اللغة (۱۳۲/۱۰). (۲) ديوانه (ص ۱۲۲) واللسان (أثل). مه باب الهمزة'),
(3092, 'أجد', 'اجد', 'اجد', 'الْأَجِد: : اشتقاقه من الإجاذ والاحاد كالطاق القصير يقال: عقد موحد [أى: ثيقٌ مُحکم ]. وناقة مُوْجَدةٌ القرى. [ويقال]: ناقة أَحْك وهی التى فا رها متصل ی و احد.'),
(3093, 'أجر', 'اجر', 'اجر', 'الأجر: حرا العَمّل.. آخر یاج والفعول: مأجور. والأجير: الستأجر.'),
(3094, 'الاجارة', 'الاجاره', NULL, 'ما أعطيت من جر فى عمل وَآحَرْتُ مَملوکی إيجارًا فهو مُوْحَر. والأجوز: جَبْر الکسر على عوج العظم. وأَحَرَت يده تأجُرُ أحورًا فهى آحرة. والأجار: سط [ليس”"] حواليه سترة. والحميع: أحاحیر وأجاحرة. والإنجارٌ: لغ قبيحة.'),
(3095, 'أجز', 'اجز', 'اجز', 'الاجازة: ارتفاق العرب وكانت العرب تحتبى وتستأحز على وسادة ولا كي على ین وشمال7©.'),
(3096, 'أجل', 'اجل', 'اجل', 'الْأَجَلٌ: غاية الوقت فى الوت. وع لین ونحوه. . تقول: أُحَلَّ هذا السّی یأحل فهو آجل وهو نقيضُ عاحل. والأجيل: رل إلى رقت قال: وغاية الأحيل مَهُواة الكوّى9؟)'),
(3097, 'مصدر قولك', 'مصدر قولك', NULL, '۳۳۹ إبلهم أحلونها ان أى: حَبَسُوها فى الرعغی والأخل: الضيقٌ أيضًا. وتقول: أجل عليهم شرا احلا أى: جناه وبحنه. وَالْأَجْلٌ: وحم فى العنق.'),
(3098, 'أجم', 'اجم', 'اجم', 'أَجَمَ الطْعام: أى: كرح يأحم أَُحُوماء وآجمه غيره حتى احم قال الكميت: من هلوك شمطا وتنزل للا مير ما يؤحم العشيرٌ العشيرا وَالْأَجَمَةٌ: میت الشعر كالغيضة.'),
(3099, 'أجن', 'اجن', 'اجن', 'اجن الاء ی اجوناه وحن لغة. وماءٌ جر وأحون قال: کض فد ع ماء حون ينق'),
(3100, 'یقال', 'یقال', NULL, 'الأجن: الذى غشیّه الیرمض والورق. قال رؤبة": أحن کنیء اللخم لم بش بط وقال ابن عَبّدة: 1 رها ماء كأن حمامه من الاح طحناء معا وصّبيب وَالممْجِنَةٌ ٠‏ تقمز: عص غليظة مع القصّار تب بها رب إذا عَسله فى النهر.'),
(3101, 'أحن', 'احن', 'احن', 'الاختة: لد فى الصّدْن وربما قالوا: جنة'),
(3102, 'أخخ', 'اخخ', 'اخخ', 'اخ ارس بها عد الو من شی 0"'),
(3103, 'أخذ', 'اخذ', 'اخذ', 'الأخذ: التناول. والأخذة: رقي تأحذ لين ونحوها. والإخاذة: الضَّيْعَة يتخيذها الانسان لنفسه. ورجل ۳۹ عن النساء كأنه حبس عن تایه كالعنين ونحوهء ويقال الاتخاذ من تخذ یتحذ تحذابه وتخت مالاً أى كسبته ألمت التاءٌ کانها أصلية. والأصلّ من . الأأحذ إن شاء الله تعال .'),
(3104, 'فى القرآن', 'في القران', 'في', 'لتخذت عليه أجرًا74". والأَخذ بغير مه من الإبل: حين يأحذ فيه السسّمَنُ وهن الگواعد ونو ذلك: أذ البعير يأحد أَحَذَاء فهو أذ ای شن المئون یأخذه. وكذلك الشّاة. والاخافُ والاخاذةٌ )١(‏ تكملة من التهذيب )١15/١1(‏ ما نقل فيه من | (۲) هو فى ديوانه ؛ وفى التهذيب (۲۰۲/۱۱). وفى اللسان (أحن): للعجاج. (۲) سورة الكهف الآية (۰)۷۷ وهی قراءة عبد الله .والحسن وقتادة وان بحرية. البحر المحيط .)١55/5(‏ 56 باب الهمزة'),
(3105, 'الإخذ', 'الاخذ', 'اخذ', 'ما حَفَرْت لنفسيك كهيعة الحؤض. وحم على أخذان؛ وهو أن تمسيك الماءً آیمّا. والأخذ على تقدير فثل غدر, سُمّىَّ به؛ لأنه يذه لنفسه من احذ یاخذ. ورجا نيان كثير الشر . والمستاخذ: کین ومريض ماحد أى سكين لمرضه.'),
(3106, 'أخر', 'اخر', 'اخر', 'تقول: هذا ره وهاه أحری. والآجر والآخجرة: نقيض المتقدم والْمَقَدّمَة ومد الشىء ومُوّخرهُ. وآخرة الرجل وقادمته ومقدم لین ومُؤْجرهاء فى العين خاصّة بالتخفيف. وجاء فلال أخيراء أى بأخرق وبعته الشىءَ بأحرق أى بتأخير. وقعل الله بالآحر أى بالأبعد. والاخر: الغائب. والأخر: تقيض الق تقول: مَضَى ماه و تخر أخخرًا. ولقيته أخريًا: أى آخريًا. ويقال الأخیر: الأبعَدُ وأحرى الوم أخرياتهم. قال: آنا الذی لت فى ا أحری الایل وأما خر فجماعة آخری. أخا (أهو): : أخ وأخوان وإخوة وإخواث. . وبينى وبینه أخحوّة واحاء. وتقول: أحيته'),
(3107, 'لغة طيى', 'لغه طيي', 'لغه', 'واحیته. وهذا رجل من آخائي بوزن أفعالى وتقول: ات على أصل التأسيس ومن قال: واحَيْت بلغة طيِّئْء أحذه من الوخماء”". وتأنيث الأخ: أت وتاؤها هاء. وتقول: آخت وأحتان وأخوات. والأَحيّة: ُو برض فى الط إليه ال وتجمع على الأواحي. ولفلان عند الأمير ید ثابتة, والفعل: یت ید و تحت أناء واشتقاقه من آحّة العو وهی فى تقدیر الفعل: فاعولة. ویقال: آحية بالتحفیف فى کل ذلك. َع'),
(3108, 'أخت', 'اخت', 'اخت', 'الأخت. أصلها انیت وتصغيرها: لحية.'),
(3109, 'أدب', 'ادب', 'ادب', 'رجل دیب مَُدّب يُوَدّبْ غيره ودب بغيره. والآوب: صاحب الاب وقد أدب القوم أذباء وأَدَبْتْ أنا. وللادوبة: المرأة التى صِيِمَ لها الصنيع. والأذبة والاذب'),
(3110, 'لغتان', 'لغتان', NULL, 'دعوة على الطعام. ٠‏'),
(3111, 'أده', 'اده', 'اده', 'انظر (ودد).'),
(3112, 'أدل', 'ادل', 'ادل', 'الإذل: صَرْبْ من اللبن يتغيّر عن مضه فيَصِيرُ إذلاً.'),
(3113, 'أدم', 'ادم', 'ادم', ': الأَدْم: الاتفاق وأدم م الله بینهما یأدم دما وآدم بينهما یدام فهو موّدم بینهما قال: والبیض لا بودن إلا مود أى لا يُحْببْنَ الا محّا. ويقال: بينهما أذمة وملحَة أى حلطة. وقالوا: الأدمة فى الناس شرب من ن مود وفی الابل والظباء بياض يقال: ظبّية آدسای ولم أسمع أحدا یقول للذ کر من الظباء آم وإ كان قياسًا . وادیم کل شىء: ظاهر حلده وأَدَمَة'),
(3114, 'أرض', 'ارض', 'ارض', 'وجهها؛ وقيل: سمى آدَمَ - عليه السلام - لأنه حل من أدّمة الأرض وقيل: بل من دم بعلت فيه . والإدام وال ما یونم به مع الخبز وأَدَسْتُ ابر داز جَعَلتْ فيه الأَحْمَ والسَمنْ وَاللّحْمُ وال كله ۳ والإدامٌ جماعة وثلاثة آدمة'),
(3115, 'أدو', 'ادو', 'ادو', 'والإداوة: مطهرة للماء والجمع الأداوى. والأذو: حتل منه قال: لكسن آذوت لآخعسذه فأصبكت خرااررعا و م'),
(3116, 'آدی', 'ادی', 'ادی', 'انظر (أيد).'),
(3117, 'إذء إذا', 'اذء اذا', 'اذ', 'إذ لا مَضَّى وقد یکون لما يُستَقبّل وإذا لما يستقبّل. وإذا جوابٌ توکید الشرط يتن فى [الاتصال] ويُسَكنُ فى الوقف. واذا أضيفت إلى ذ كلمة جُعِلّت غاية للوقت تن ونَجَرٌ كقولك: يومَئِذٍ وساعتَيذِ وكتابتها ملترقة فا وصلتّها بكلام يكون صلة ولا يكون خبرًاء كقول الشا 0 إذ يقول بنو لؤئ كانت فى الأصل حيث جَعَلتَ ,تقول, صلة أخرجتها من حَدٌَ الإضافة إلى قولك: إذ تقول, جملة؛ فإذا أفرذتها نها لالتراقها بالكلمة التى معها كأنها كلمة واحدته'),
(3118, 'کقولك', 'کقولك', NULL, 'عَیعٍْ بنو فلان یقولون كذاء لان تقول, هاهنا خبرٌ وفی البيت صلةء وإنما حاءت فى سبع كلمات مُقتتٍ فى حيط ویومَیار وین وساعتعن وغداتهن وعامتيل (۱) الرحز فى التهذيب وواللسان غير منسوب. ۲ باب الهمزة وعشيعاٍ ولم یقَل: لقن وإنما خصّت هولاء الکلمات بها لأنّ آقربٌ ما یکون فسی الحال قولّك: الآنَ فلما لم يحول هذا الاسم عن وقت الحال ولم يتباعَد عن ساعتك التى أنتَ فيها - لم يتمكن ولذلك نُصِبَتْ فى كل وخ فلما أرادوا أن يتباعدوا بها ويحوّلوها من حال إلى حال ولم تقد أن يقولوا: الآنئذٍ عکسوا لیعرّف بها وقت ما تباعَد من الحال فقالوا: حينعذ ولكن قالوا: الآن لساعتك فى التقريب وفى التبعيد: حینقلد وترّل عترلتها الساعة وساعتئلٍ وصار فى حدّهما اليومٌ ويوممارٍ والحروف التى وصفنا على ميزان ذلك مخصوصة بتوقیت لم يحص به سائر أسماء الأزمنة لا بیان وقست نحو: لقيته سنة حرح ورأيته شَهْرَ دم الحاج كقوله: فى شهر يَصِطادُ الغلا الحلا فمن صب الکلام فإنه يَجْعَلُ الإضافة إلى هذا الكلام أجمع كما قالوا: زمن الحَجّاجٌ آمیر. ۱'),
(3119, 'أذن', 'اذن', 'اذن', 'يقال للرجل: هو اذد وللمراة: هى أن وللقوم كذلكء أى یسمَمٌ من کل أحد. وَالأَدُنُ العُروة أى عُروة الکوز ونحوه وال کواب: کیزان لا ادن لها. والأَذَنُ: الاستما ع للشیء قال: فى سماع یادن سیخ له وحدیست مغل ما فی مشار ورجل أَذَنَةُ: یستمغ لكل شىء وأَمنَة يأْمَنُ بكل إنسان. وأذنت بهذا الشىء أى علمت. وآذتنی: أَعْلمَىء وفعله بإذنى أى بعلمى وهو فى معنى بأمرى وكذلك الذى ین بالدحول على الوالى وغيره. والأذانُ اسم للتأذين كما أنّ العذاب اسم للتعذیب؛ قال: حتى إذا نسُودِىَ بالأذين حه إلى فعيل. والتَذّنُ من قولك: تأذنت لأَفْعَلّنَّ كذاء يراد به إيجاب الفعل فى ذلك؛ أى سأفْعَلُ لا مَحالة. ويقال: هل سيعت الأذان من المذنة. وتَأذّنت: تست كالأمير یذ قبل العُقوبة ومنه: إوإذ تاذ ربك [الأعراف: .]١55‏ (۱) کذا فى (ط) وفى اللسان (إذا): وعشيتقل وساعتئد وعامئل. (۲) البيت لعدى فى اللسان (أذن).'),
(3120, 'آذی', 'اذی', 'اذی', 'الاذى: 03 ما یت به ورحل أذ أى شديد التأذى وأذی دی أذى.'),
(3121, 'أرب', 'ارب', 'ارب', 'قطعت اللّحْمَ آرابّاء والواحذ: رب أئ: قطفاه ویقال فى الدّعاء: ریت يدي'),
(3122, 'فى الحديث', 'في الحديث', 'في', 'مُؤاربة الأريب جهن وعناءا ©“ لأنّ الأريب لا يُحدّع عن عقله قال: على ذى الاربة البق الرفيق'),
(3123, 'التأریب', 'التاریب', NULL, 'التحریش ۰ وترب فلا عليناء أى: تعسر و حالف والتوی. والمستأرب'),
(3124, 'من الأؤتار', 'من الاؤتار', 'من', 'ابلیّد الشّديدء قال: ۳'),
(3125, 'أرج', 'ارج', 'ارج', 'الأرح: نفحة اليح الطببة. تقول: رج ابیت یار ارجا فهو: أَرِح. والتاریج: شىء من کتب أصحاب الدّواوین. والأوارحة من کتب أصحاب الدواوین فى الخراج.'),
(3126, 'التاریج', 'التاریج', NULL, 'شْبْهُ التأريش فى الحربء قال العجّاج: انا إذا مذ کی سروب ارجا'),
(3127, 'أرخ', 'ارخ', 'ارخ', 'الأزخ والازجی, لغتان: فقی من البق والأنقى أ أَرْيّة والجميع: الأراخ والإراخ لغتان. وتقول: أَلقَحَتْ ازحهم. والأرْحية: ولد التتل. وأزخت الناقة'),
(3128, 'إرخاؤها', 'ارخاؤها', NULL, 'إصلاؤهاء فاذا ترت قيل: أْصْلَتْ وإصلاؤها إنهاكُ أصّلابهاء أى انفراجُها لعظم امین وذلك إذا عظم وَلَدُها فى بطنها. ۱'),
(3129, 'آرر', 'ارر', 'ارر', 'الاراژ: شب ظوْرةٍ ور بها الرّاعى رَحِم الناقة إذا ما رَنَسْ ومارنتها: أن بضربها الفحل فلا تلقح. وتفسير یر بها الرّاعى: أن یل یه فى رها فيقطع ما هناك بالإرار ويُعاحة. والأر: أن يأحذ الرحل إداراء وهو عصنْ من شوك القتاد وغيره فيضربه بالأرض حى تبينَ آطراف شو كه ثم يبل نم یذ عليه ملحا مدقوقا فور به تشر الناقة حتى یدمیّها. یقال: ناقة ثمارن والفعل: أرّها یورها. والأرير: حكاية صوت الاجن عند القمار والغلبة .. أرّ یر أريرًا. (۱) أورده ابن الأثير فى النهاية (۳/۱). :5 باب الهمزة'),
(3130, 'ارز', 'ارز', 'ارز', 'الارژ: معروف. والارژ: شده تلاحم وتلازم فى کزازة وصلابة. وت فللانا'),
(3131, 'ارو آی', 'ارو ای', 'ارو', 'ضيق بخیل شحاه قال: فاك بحال آروز الارز ویقال للذابة: إن فقارّها لآرزة أى: متضايقة متَدّدة, قال: وما بلغ فلان أغلى ابل إلا آرژا. أى: مُنقبضًا عن الانبساط فى مثيه من شِدَةٍ إعيائه. يُقال: اعيا فلانٌ فارّن أى: وقف لا یمضی. وسيل فلا شيئا فآرَلٌ أى: انقبض سدم رھ عن أن يَجُودَ به وامتنع: ومن لم يَعْرفْ هذا قال: أرّر فأحطا مثقلا. رسب مر اسم سیل'),
(3132, 'أرش', 'ارش', 'ارش', 'الأرّش: ية الجراحة. قال حماس: الأَرْش: تم الماء إذا ورد عليك قوم فلا مكنهم من الماء حتى تأححد الشمن. والتأريش: التخريشء قال رژبة: بحت من حرص على التأريش وقال: وب کت قن أي ازب يهم'),
(3133, 'الأرض', 'الارض', 'ارض', 'الركاءُ. وأَرضَ فهو مَأَرُوض.'),
(3134, 'أرف', 'ارف', 'ارف', 'الأرفي: اللبن المحصن الطَيّبء ويقال أيضًا لبن الظباء. أَرَفْتْ الذار تأريقاء أى: قسّمتها وحَدّدتها. وت ارف الذار وهی: العالم. الواحدة: ارف ورفة خحفيفة. (۱) (ط): سقطت الكلمة وترجمتها من الأصولء فأثبتناها من مختصر العين (الورقة ۲۱۳). (۲) (ط): فى الأصول الحطوطة ورد آن: أرض أيضا جاعة كذا وییدو أن فيه تصحيفاء'),
(3135, 'الصواب', 'الصواب', NULL, 'آرض على أفعل وهو ما آثبتناه من اللسان (آرض). ام مس و ر باع ر ا ره 8 مه سدع ق يس 7 #85'),
(3136, 'اری', 'اری', 'اری', 'الارقاد - واليرقان احسن 06 : رافة تصيب الزرع) يقال: زرع ماروق ونحلة ۱ ماروقت ولا یقال: میروقة وارقت: أصابّها الیرقانْ. والیارقان والیارجان من آمنورة النسای ۶ وهما د دخيلان. والارق: ذهاب الوم الیل وتقول: أرقت فانا ارق ار لے ر رل رسام لورقا . وساب من سم وما بى ملق'),
(3137, 'أرك', 'ارك', 'ارك', 'الأراك: شَحر السواك. وإبلٌ أوارك : اعتادت أكل الأراك. وقد أركت تارد رکا وار وکا وهی آوارك إذا آرمت مکانها فلم تجر تيْرّح. وارك الرَّجْلْ بالکان یأر'),
(3138, 'ار وکا', 'ار وکا', 'ار', 'أقام به. الأريكة: سوا فى حلع شلد دشر : أريكة. وارك وأريك: جبّلان بين النقرة والعسيلة قال النابغة( عفا حسم من فرتنی فالقوارعٌ فجنبا اريك فالتلاعٌ الوافم'),
(3139, 'أرة', 'اره', 'اره', 'الأرام: مُلتقَى قبائل الرأس وبذلك سى الرأس الحم مُوَوَمًا .'),
(3140, 'مؤرمة', 'مؤرمه', NULL, 'واسعة الأعلى. والأرمى: من أعلام قوم عاد كانوا ينونه كهيئة المنارة وكهيفة القَبُورء قال ابو الدقيْش: الأروم: قبور عاد وكذلك الإرّم قال: بهاأرُومٌ کهسوادی الت [ويقال]: ما بها ارم أى: ما بها أحذ. وارم كان أبا عاد الأول.. والأرومة: أصل کل شجرة. وأصل الحسّب: روم و امحمیع: ارو وأرومات. وأرومُ الأضراس: اأصول منابتها. ارو بضمّ الألف: غلط لأنها اسم واجد ولا یَحی؛ اس واحدٌ على فغولة إلا فى الصادر. والأرّم: احجارة هكذا جمم. قال: يلوك من حَرْدٍ علي الأ'),
(3141, 'أرن', 'ارن', 'ارن', 'رن ارڈ آرنا وإراناء أى: تشط. والفاعل: ار واروه كما يُقال: : مرح ومروح. حّ. والاراث: سرير الميت قال ۹ وعنس كألواح الاران نساتها على لاجب کاته ظَهْرُ برحد وآران القَوْمٌ: هلک مواشیهم أو هرلت فهم مُرينون.'),
(3142, 'أرى', 'اري', 'اري', 'وأرئ القدر: ما یلترق بحوانبها نار وكفلك من ال مق بجوانب العسّالةء قال2©9: ر صمو [إذا ما توت بالخلئ بدن به ترییس] ماتانری ونْتِيِعٌ'),
(3143, 'يقول', 'يقول', NULL, 'یا کل القَفارَ الذى لا أدم فيه. وقوله: لا یتاری أى: لا ینتظر غدًا القوغ ولا ما فى قذرهم أَنْ يطعموه منه. ويقال: لا یتاری لذلك أى: لا يُنتظرء ولا يهمّه. وان بینهم لأرى عداوق أى: : أشدّها وألزقها وأقدمها. وأزی الندی: ما وقع من الندى على الذى هو مثل العْشْب والشّحّر والصّخر فلا يزال لتق بعضه ببعض .. والدّايّة تأرى إلى الذابّةء إذا انضمّت إليها وت معها معلفا واحداه وبذلك سن المعلف: تاه فهو فى )١(‏ البيت لطرفة فى اللسان (أرن) ومطلعه: أمون كألواح 00 (۲) البيت للطرماح فى اللسان (أرى) وفيه: إذا ما تأرت. (۳) اللسان (أرى) وفيه: بروقها, مكان بروقه.'),
(3144, 'تقدير', 'تقدير', NULL, 'فاعول, قال(: يعتساد ربا ا لها آری'),
(3145, 'الواری', 'الواری', NULL, 'الشَحِم السّمين والوری مثله. وزند وار للذى پوری انار سريعًا .. ری اند ویوری لغتان وآوریت زندا. وتقول للرحل حل الكريم: إنه لواری الرّنادء ووریْت بك'),
(3146, 'زنادی؛ أى', 'زنادی؛ اي', NULL, 'رأيت منك ما سأ من النصلح والتجابة والسماحة. زرجل یوری بالأمر, إذا آراد آمرا وهو یظهر للناس غیرّه. وأوریت الثار إذا كانت خامدةً فأحّجتها.'),
(3147, 'آزب', 'ازب', 'ازب', 'الاژب: الذی تق مَفاصله يكون [ضتیلاع( فلا تکون زیادته فى آلواحه وعظامه ولک فى بطیه وسّیلته. کانه ضاوئ مُحل.'),
(3148, 'آزح', 'ازح', 'ازح', 'رح يرح أزوحًا إذا تخلف.'),
(3149, 'أزد', 'ازد', 'ازد', 'آزد: ی من العرب.'),
(3150, 'أزف', 'ازف', 'ازف', 'آزف الیء یاف أَرََا واژوف. والآزفة القيامة. والآزف: الكان الق'),
(3151, 'التازف', 'التازف', NULL, 'الَْطْوُ التقارب. وزالتآزف: القصير من الرحال قال(۳: فى فد قَدَ السّيّف لا ازفا ولا رل اة وباو'),
(3152, 'أزق', 'ازق', 'ازق', 'الأزق: الضيق فى الحرب ومنه الازق وهو الفعل.'),
(3153, 'أزل', 'ازل', 'ازل', 'الاْژل: شد الزمان [یقال]: هم فى ال من العيش والسنة وأزل من شدائد البلوى. وأَرَلْت القرس أزلا: : قصرت حَبْله ثم أَرْسَلْته فى الرعی.'),
(3154, 'أزم', 'ازم', 'ازم', 'الأوازم - وواحذها: آزمة - الأنياب. وا مت ید الرحل آزمها از ما. وهو العض. ارم علينا الدّهرٌ يأزمُ ماه إذا ما اشتد وقل خيْره]. وسیل الحارث بن کلدة: ما (۱) العجاج كما فى اللسان (أرى). (۲) (ط): ما روى عن العين فى التهذيب (۲۰۰/۱۳) .. فى الأصول: (صبيا). (۲) التهذيب (۲۰۱/۱۳) بلا نسبة وهو للعجير فى اللسان (أزف). ۸ باب الهمزة الدواء؟؟ قال: الأز آراد به: يت وألا يُوْكَلَ الا بقدر ومعناه القبض للأسنان'),
(3155, 'أزن', 'ازن', 'ازن', 'الأَرَنُ: نة فى اليرنء مثل الأب فى الیلب. أزا (أزى): آژی الشىء يأزى بَعْضَه إلى بعض نحو اكتناز الم وما سم من نحوه قال: عض السقال فهو آز یش'),
(3156, 'أسب', 'اسب', 'اسب', 'الاسشب: شَعر الفرج أصله: وب واشتقاقه من وسب العشب والتبات.'),
(3157, 'است', 'است', 'است', 'انظر سته.'),
(3158, 'اسحنطر', 'اسحنطر', NULL, 'امْحَنطرَ إذا امتد ومال.'),
(3159, 'اسحنفر', 'اسحنفر', NULL, 'امْحَنقَرَ الرّجل: استمر.'),
(3160, 'اسحنكك', 'اسحنكك', NULL, 'امْحَنْكَك الیل إذا اشتدّت ظلمته.'),
(3161, 'أسد', 'اسد', 'اسد', 'الأسَد: معروف وجمعه: أذ وأساود والاسدة له معنيان يقال لموضع الأسد: مَأَسّدة ويّقالٌ للأَسّدٍ: مأسدة, كما يُقال: مَسْیفه للسٌّيُوف ومّجنة للحن ومَصْبَّة للضب اب ويقال: آسَدْت بين الکلاب والقوب أى: هارشت وأغريت 0 والمسِد: الكلاّب الذى یوس کلبه للصَیٌد يدعوه ويُغريه. واستأسد فلال: صار فى جرأته كالأسدء قال آبو النجم(: مستأسد ذبانه فى غيُطَل”" يقول للرائد غیت انزل واستأسد التبات: طال وذهب كل مَذهب.'),
(3162, 'أسر', 'اسر', 'اسر', 'سر فُلانٌ لانا: شته واقاه وهو مأسوز. ور بالإسارء أى: بالرساط'),
(3163, 'الإسار', 'الاسار', NULL, 'مصدر كالأسر. ودابّة مأسورٌُ الفاصل أى: شديدٌ لامُهاء وَالأَمْرٌ: قوّة المفاصل والأوصال. وشدّ الله اسر فلان أى: قوّة خلقه قال الله عر وحل: وشدذنا آنرهم4 (۱) (ط): ما بين القوسين فى هذه الترجمة فمما روى عن العين فى التهذيب .)۲۷٤/١۷(‏ (۲) التهذیب (۳/۱۳). اللسان (اسد). وفیه: ....... آذبانه فى عیطل ۱ 69 الغيطلة: الأحمق والبقرة الوحشية وازدحام الناس وغیر ذلك اللسان: (غطل).'),
(3164, 'أسس', 'اسس', 'اسس', 'الرّاقون إذا رَقوا الحية ليأحذوها ففرغ أحدهم من رقیته قال لها: رن فتخضع وتلين. وال أصل تأسيس البناء والجميع: الإساس وفى لغة: الأسّس: والجميع: الآساس ممدود. وأس الرّماد: ما بقى فى الوقد قال: و عر ور ۱(۶) فلم يسق الا آل حیسم مب وسفغ على أس ونوی مب وأسَّمْت دارًا: بنیت حدودها: ورفعت من قواعدهاء ویقال: هذا تأسیس حسن. والتاسیس فى الشغر لف تارم القافية وبینها وبين خرف الى حرف يجوز رفعه و سره ونه نحو: ماعل فلو جاء مثل (محمّد) فى قافية لم يكن فيه تأسیس, حتی'),
(3165, 'يكون نحو', 'يكون نحو', NULL, 'مجاهد. فالألف تأسيسّه؛ وان جاء شىء من غير تأسيس فهو المؤسّس وهو عيب فى الشعرء غير أنه ریما اضْطرٌ إليه وأحسن ما يكون ذلك إذا كان الحرف اذى بعد الألف مفتوحًاء لأن فتحته تغلب على فتحة الألف كأنها ترال من الوه كما قال العجَاج: عم آی الفدى مه فلو قال حاتم بكسر التاء لم خسن'),
(3166, 'أسف', 'اسف', 'اسف', 'الأسّف: الحرن فى حال. والغضب فى حال فإذا حاءك آمر مِم هو دونك فأنت أمیف. أى: غضبان وإذا حاءك من فوقك أو من متلك فأنت ايف'),
(3167, 'أسل', 'اسل', 'اسل', 'الْأسّلُ: نبات لهُ أغصانٌ كثيرةٌ قاق لا وَرَقَ ولا يكون آبدا الا وفی أصله ماء راكد خد منه الغرابيلٌ بالعراق .. الواحدة: أسّلة: ويُجْمّع الأَسّل بغير الهاء. وَيُسَمّى القنا سا تشبيهًا بطوله واستوائه قال: عدو المنايا على أسامة فى ال خيس عليه الطرفاء والأَسَّل7") وأسلة اللسان: طرف شبات أى: ده 0 واسلة الذراع: مستدق السّاعد ۳ یلسی الکف, وکف أسيلة الأصابع: وهى الليّنة السسّبْطة وخ أسيلٌ: سَهْلٌ لين وقد سل أسالة ... ومَأسّل: اسم جبل.'),
(3168, 'أسم', 'اسم', 'اسم', 'أسامةٌ: من أسماء الأَمّد .. یقال: جع من أسامة.'),
(3169, 'أسن', 'اسن', 'اسن', 'آسن الماء أي شا واسونا فهو آم أى: متغير الطّمُم. وأمین الرّجْلُ آسنا فهو سین إذا دحل را فأصابه مرت الماء الآسن ففثیی عليه أو مات وأسِنَ إذا دار م يور مرو م عادر القن عقا اناي يميد فى الرّمْح مد الماح لأسن وتأسَّنَ عَهْدٌ فلان وده أى: تغيّرء قال رؤبة : ۱ . راحعة عَهْدًا من التَأَسُنٍ وتاس على تأسناء أى: اعتل وابطا. والأسُن: قديم الحم ویقال: العْسْء واللجميع: الاسان. وريقال] : هذا علی آسان ذاك أى: شبيهه. والأسيدة: سير من سيور تضفر جميمًاء فتجعل نسغا أو عنانا كأعنة البغال وكذلك كل قو من رى او رام (ط): سقطت الكلمة وترجمتها من الأصولء فأثبتناها من ختصر العين (الورقة ۱۷). (۲) بلا نسبة فى التهذيب )47/١7(‏ واللسان (أسل). (۲) البيت لزهير فى اللسان (أسن).'),
(3170, 'قیل', 'قیل', 'قیل', 'الآسية: المعالجة والداوية والجمع: آسيات وأواس. وأما أواسى المسجد'),
(3171, 'فواحدتها', 'فواحدتها', NULL, 'آسية وهی السّارية. وجعل الأعشّى الأسّى مصدر الأممُوَّة وإنما الأسى جماعة الأيسوة من المواساة والتأسى. تقول: هؤلاء القوم أسوة فى هذا الأمر أى: حالهم فيه و احدة, وفلان يأتسى بفلان أى : یری أن له فيه أسوة إذا اقتدی به و کان فى مثل حاله والحمع: الأسى ویقال: إسوة وإسىء وفلان يأتسى لفلان أى: یرضی للفسه ما رضیه قال: هلا ذكرت أسّی فى مثلها عبر بل وافق الشّوق من معتاده وفقا'),
(3172, 'آسی', 'اسی', 'اسی', 'الآسى مقصور: ان علی الشىء ۳ آمیی يَأْسَى اسي فهو أسيانء والمرأة: آمنیی والدميع: أساياء وأسيانون وأسیّیات .. ويجوز فى الوحدان: أسيان وأسُوان قال: ماذا هنالك من أسوان مكتيب وساهفي ليل فى مدوم ۹'),
(3173, 'أشما', 'اشما', NULL, 'والأشاءُ: صغار النخل الواحدة: أشاءة على فعالة.'),
(3174, 'أشب', 'اشب', 'اشب', 'الأشب: شِدة التفاف الشّجرء حتی لا جار فيه.. عَيضة شب ورماحٌ آشبة.'),
(3175, 'التأش', 'التاش', 'تاش', 'التجمم من هنا وهنا. قال: من تأشّبء لا دین ولا سب'),
(3176, 'أشبا', 'اشبا', NULL, 'لامه وعابه ... وأشبة: من آسماء الذئاب)'),
(3177, 'آشر', 'اشر', 'اشر', 'الأشر: الرح وابّطر. ورحل اشر واشرانْ. وقوم آشازی وأشازی.'),
(3178, 'آشش', 'اشش', 'اشش', 'والاش والأشاش: الهشاش, وهو الإقبال على الشیء بنشاط قال: كيف يؤاتيه ولا يۇ شه.'),
(3179, 'أشل', 'اشل', 'اشل', 'الأشْل من الذزع بلغة امل البَصْرةء يقولون: كذا وكذا حَبْ وكذا وكذا'),
(3180, 'لا والحميع', 'لا والحميع', 'لا', 'الأشؤل.'),
(3181, 'أصد', 'اصد', 'اصد', 'الإصد والإصاد والوصاد اسم والإيصاد الصدر. والإصاد والاصد هما عنزلة الُطبق يقال طب عليهم الإصاد والوصاد والإصد. وأصّلات عليهم وأوصدته؛ والهمز أعرف. لإونارٌ مؤصدة) [البلد: ۲۷۰ أى مطبقة.'),
(3182, 'أصر', 'اصر', 'اصر', 'الإصر: ۳ والأصر: ایس [هو] أن يُحبسوا أموالهم بأفنيتهم فلا بُرعونها تمس مَرعی وكذلك الْأَصرٌ يأصروتها ولا ُسَرحونها وهذا لشِدّة الرّمان(.'),
(3183, 'يصر', 'يصر', 'يصر', 'خبیل قصير یش فى أسفل الخباء إلى ول ويُجمّع یا وفی لغة أصارة. وك شو عط على یم هو ع من غد آو جم فد عليه واه'),
(3184, 'أصف', 'اصف', 'اصف', 'لصف لغة فى اللصّف. واصف: کاتب سلیمانٌ بن داودّ - عليه السلام - الذى دعا الله - حل وعَرَّ - باسمه الأعظم فرأى سليمانٌ لعش مستقيًا عنده.'),
(3185, 'أصل', 'اصل', 'اصل', 'واستأصلت هذه الشّحَرة أى يت أصلّها. واستاصل الل فلاا أى لم يَدَغْ له أصلاً. ويقال: إن الل بأرضنا أصيلٌ ی هو بها لاف ولا زول. وفلان أصيل الرأى. وقد أَصّلَّ رأيه أصالة وإنه اصیل الرأى والعقل. [والأصل سل کل شىء]. والأصيل: لش وهو الاْصل وتصغيره آصیّلال. یه فا ای بأصيل. والأصِلَُ: حية قصيرة يِب فتساور الإنسانٌ وتكون رمل عاقر شبيهة بالركة مُنضّمّة فإذا انتفحت ظنتها بهاء لا رل واحدة تقوم عليه ثم تور کب لا تصيب نها شنا إلا که اه 2 فيها. [والأصيل: الهلاك وقال أوس: حافوا الأصيل وقد أعيت مُلْوكُهُم ونوا من ذوى غرم بأتقال'),
(3186, 'الأصيل', 'الاصيل', NULL, 'الأصیل" ) ورحل أصیل: له أصل]. ۱'),
(3187, 'أصى', 'اصي', 'اصي', 'وأصاة اللسان: حصاته أى رزانته ویروی لطرفة: وان لسانت المرء ما لم تكن له أصاة على عَوْراتِه لدلی 0'),
(3188, 'یروی', 'یروی', NULL, 'حصاة. وطائر سيه أهل العراق: ابن آصی فغلی وهو شبيه بالباشق, الا أنه أطول جناحًا وأحبث صيداء وهو ادا ل'),
(3189, 'أضم', 'اضم', 'اضم', 'الأضّم: الحسد والیقد فى القلب لا یقیر على أن یمضیه. ورجل أضمٌ وقد'),
(3190, 'أضو', 'اضو', 'اضو', 'الخد ٠‏ والأضین: جاعة الأضات ا سنين وسنة. ٠‏ ويقال (ضاة وأضاة (۱) گذا فى (ط). (؟) البيت فى الديوان (ط أوربا) ص ٠١‏ وروايته: وان لسان المرء ما لم تک كن له حصاة 0 (۳) (ط) ورد بعد هذه العبارة فى الأصول المخطوطة: قال أبو ليلى: : الأضاة عندنا موضع مستدیر يكون فى القاع من الأرض فتندفع فيه السيول فيمتلىء ويتحير فيه الماء ورعا طفح فذهب بعض مائة والجمع الأضًا. V٤‏ باب الهمزة ورد اما مَطائط الإيا 1 آراد بالإياض الاضاء وهو الغذران فَلب. واضّی هذا الأمر, أى بلغ منی المشّقة وهو يؤضّنى. وقد انتضّ فلانْ منه وله. وأضتنى إليه الحاحة.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(3191, 'أطد', 'اطد', 'اطد', 'الأطيدٌ, أى: الشدید الو کید وفى شعر آخر: أطد واشتقاق ذلك كله من: وَطَدَ.'),
(3192, 'آطر', 'اطر', 'اطر', 'الط عَرْحُكَ الشَیء تقبض على أحد طرفي یه ثم تأطره فیتأطر قال العجاج(: نَضْر ب بالسيّف إذا ارم ان وأطرت الشّىء: ء عَطفته و کل شىء عطفته فقد آطرته أَطرًا. والأطرة: عَقّبة تلری على ريش الم وفى کل مرضع ید فهو: أطرة بعد لا يكون جلارًا . والاطار اطار الف وإطارٌ تخل وإطارٌ الفم وهو الحيد الشاحص ما بين مِقَصّ الشارب وطَرّف الشفة المحيط بالفم وإطار البّت: كامنطّقة حول البيت ... والاطار: قضبان الکرّم 27 للتعريش. و کل شىء حيط بالشّىء فهو إطار له والتأطر: لزوم المرأة لبيتها حتى لا ح قال : ا سی قلت یبور ودب كما ذاب السديف اسرد'),
(3193, 'أط. أطيط', 'اط. اطيط', 'اط.', 'الأط والأطيط: صنت تقبض الحایل, أذ أطیطاه وکل شيء تقل حل بَعْضنه على بض یط والأطاط: الصياح .. واطبط الإبل: أنينها من ثقّل الجثلء أو صوت هره عليها.'),
(3194, 'أطل', 'اطل', 'اطل', 'الاطل: لغة فى الأيطل وهو الشّاكلة؛ ولقرّب تحت الشاكلة. تقول إنه للاحقٌ الأَيطليْن وجمعه: أياطل والآطال: جماعة الإطل وَالأَيَصَل: خسن ورف ۰۰ و نظیره قوّلهم للمجنون: به أؤلق وقد الق يؤل ألقا'),
(3195, 'أطم', 'اطم', 'اطم', 'الأطّم: حصن بناه هل الدينة من حجارة. وتأطُمَ الستَيْلُ إذا ارتفع فى وجهه (۱) زيادة من رالتهذیب). ما آحذه الأزهرى عن والعين. (۲) ديوانه ص ۳۰ بروایة: يمكن السیف .. (۳) فى التتهذیب ۹/۱4 غير منسوب أيضاء ونسب فى اللسان إلى عمر بن أبى ربيعة ولیس فى دیوانه.'),
(3196, 'رجل ماو خ', 'رجل ماو خ', 'رجل', 'شج فى يَأَفُوخه. وهی البآفيخ.'),
(3197, 'أفر', 'افر', 'افر', 'أفرت القدر تافر آفرّه إذا حاشت واشتد غليانهاء كأنما تنزو تروء قال: باعوا وقدرٌ ارب تغلی افر“ والتفر من الرّجال: الذى يُسْعَى بين يدى الرحل يُعينَهُ ویحامه ویقال: اه یأر بين دی وقد اد مقفراه قال: والإنسان يَأْفِرُ أفرَاء إذا ونب وَمَشَى علوا.'),
(3198, 'ثلاث لغات', 'ثلاث لغات', NULL, 'الكسرٌ والضمٌ والفتح بلا تنوين, واه الكسْره فإذا نرّنت فارفع تقول: أف لأنه يصير اسما عنزلة قولك: ويل له. والعرب تقول: أفة له مؤنثة مرفوعة. لا يقال ذلك إلا بالنوین إمّا مرفوعًا وإمّا منصوباء والتصب على طلّب الفعل کانك تقول: (۱) ديوانه (ص .)١155‏ والرواية فيه: إذا رمی فى زاره تأطمه. (۲) فى المحكم (۰۱54/0 ۱5۵): اليافوخ: ملتقى عظم مقدم الرأس وموحره. وقيل: ما بين الهامة والجبهة. قال: وقد تقدم فى الهمزت وإنما شجعنا على وضعه فى هذا الباب آنا وجدنا جمعه: يوافيخ فاستدللنا بذلك على أن یاءه أصلا. (۲) الرجز بلا نسبة فى التهذيب (۲7/۱۰) واللسان (أفر). ۷٦‏ باب الهمزة آقفت أفا. وتقول: الأفٌ والتف الأف: رسخ الأذن والتف: وسَخ الأظفار. ویقال: عليهم اللعنة والتأفیف.'),
(3199, 'أفق', 'افق', 'افق', 'أَقْقَ الرَجُلٌ يَأفِقّ أى: رکب رأسَّهُ فمضى فى الآفاق. والأفيق: الأديم إذا فرغ من دباغه وريحَهُ فيه بعد والجميع: أفق وهو فى التقدير مثل: أديم وأدّم وعمود وعَمّده وإهاب وأَهَّبِء ليس فَعُول ولا فعيل على فعل غير هذه الأخْرف الأربعة. وقول ای( : ولا لك النعمان يوم لقیشه ‏ یامه يُعطى القطوط ویافت'),
(3200, 'أفك', 'افك', 'افك', 'الإفك: الکذب. أفك يأفنك أفكًا. وأفكته عن الْمُر: صرفته عنه بالکذب والباطل. والأفيك: الکَذّب عن حيلته وحزمه قال: مالى أراك عاجرا أفيكا؟'),
(3201, 'المأفوك', 'المافوك', NULL, 'اذى یب الاك وهو الوتفك. والمؤتفكة : الأمم الماضية الضالة یلک والأفاك: اذى يأفك الئاس عن الق أى: یصنهم عنه بالکذب والباطل.'),
(3202, 'أفل', 'افل', 'افل', 'فلت الشَمْس تأفل أفولاً. وکل شىء غاب فقد أَقَلَ وهو آفل. وإذا استقر اللقاح فى قرار الرجم قيل: قد أفل والآفل فى هذا المعنى: هى التى حملت. ويقولون: لبوءة آفل وآفلة إذا حَمَلَتْ. والأفيل: الفصيلء واللجميع: الإفال قال: وحاء قريع الشّول قبل إفالها'),
(3203, 'أفن', 'افن', 'افن', 'أفِنَ الرّجُل أَفْنا فهو مأفون, أى: همق لا رای له رجع إليه.'),
(3204, 'أقط', 'اقط', 'اقط', 'واحدة الأقط أقطة؛ وهو تخد من اللبن الخیض طخ ثم بتر حدى يمل'),
(3205, 'الأقطة', 'الاقطه', NULL, 'هة دون القبّة ما يلى الكرش. والمأقط: المضيقُ فى الحرب. )۱( البيت له فى اللسان (أفق) وفيه: بخبطته ) مكان وبأمته). (۲) الرّحز بلا نسبة فى التهذیب (۳۹۷/۱۰) واللسان (أفك). (۳) تصحفت فى (ط) إلى المؤتكفة.'),
(3206, 'أقن', 'اقن', 'اقن', 'الأقنة: شِبْهُ حُمْرةٍ فى ظهور القفاف وأعالى ابلبال ضيّقة الرأس قغها قثر قامة أو قامتين علقة وربّما كانت مَهُواة بين نيقين. قال الطَرماح217: فى شناظى أقن ییا عر لير کصوم التعام'),
(3207, 'أقا', 'اقا', 'اقا', 'الإقاة: شجرة.'),
(3208, 'أكد', 'اكد', 'اكد', 'أكذت العقد واليمين: ونُقته وو كدت لغة والهمزة فى العقّد أحود.'),
(3209, 'أكر', 'اكر', 'اكر', 'الأكرة: حفرة تحفر إلى جنب الغدير والْحوْض ليصفى فيها الاء والجميع: الأكر. وتا کرت أكرة. [وبه سم سُمَی الا کار ۲۲۲'),
(3210, 'أكف', 'اكف', 'اكف', 'آکفت الذَابّة: : وضعت عليها الإكاف. وأكفتها: اتحذت لها اکافا؛ [وال وکاف لغة فى الا کاف](۳) ۱'),
(3211, 'أكل', 'اكل', 'اكل', 'الأكلة: المرة. وَالأكلَة: اسم کالم والأكال: أن اکل عود أو شىء. والأكولة من الشاء: لنى ترزعی للأكل لا للتسطل والبيع. وأكيلك: الذى يُواكلك وتؤاكله . وأكيل الذنُب: شاه أو غیرها إذا آردت معنی الأ کول سواء فيه الک والأنثى وان ارت به اسمًا جعلته: أكيلة ذئب. والاکلة: ماحل للانسان لا پحاسب عليه ولاز إذا اشد التهابهاء كأنها يأكل بَحْضُها بَعْضًا تقو ل: اتتکلت النار. وَالرَّحَلُ إذا ۲ ا غضبه یاتکل قال ئ اا أبا یت آما تنفك تالک ۳ والرَجُل يَستأَكِلُ قوماه أى: يأ کل أموالّهم من [الإسنات] *. ورجلٌ أكول: كثير الأكل. وامرأة أكول. والمأكل کالطعم والظرب. ال کل: الط وفى الحديث: ِن آكل الربا ومو كله 8 ''. والآكال: ماكل الُلُوكِء أى: قطائعهم. وال والمأكُلَةُ: اللّعام. (۱) اللسان (أقن). (۲) (ط): تكملة من ختصر العين (الورقة .)١51/‏ (۳) (ط): من مختصر العين (الورقة .)١57‏ (؟) البيت للأعشى فى اللسان (أكل). ره (ط): فی الأصول: الأسباب والتصویب من التهذیب ۰ ۳۹۹/۱( عن العین ومن اللسان (أكل). )1( آحرجحاه له الصحيحين بلفظ: لعن الله آکل الربا وموكله...ي وقد جاءالحديث بروايات وطرق مختلفة انظرها فى الارواء؛ رح ۳۳۹ ۷۸ باب الهمزة باتوا على لته أى: على طعام ویقال: استغنينا بال عن المأكلة أ ی: باللبّن عن الطعام. والمتكل: إن کل فيه. والمعكلة: قَصعة 7 تشبع الرّحلين والثلاثة.'),
(3212, 'أكم', 'اكم', 'اكم', 'الأَكَمَهُ: تل من فف والجميع: ال کم والأکم والآكام وهو من خجر واحده. والْماکمتان: لخْمتان بن لعج والتبّن والجميع: الماكم.. قال: إذا ضَرينُها اريخ فى ارط شرفت ماکنها وال فى الزیسح تفخ'),
(3213, 'ألا', 'الا', 'ا', 'ألا معناها فى حال: هلاًء وفى حال: تتبیث كقولك: ألا أكرمٌ زیذاء وتكون (الا) صلة بابتداء الكلام کانها تنبيةٌ للمُخاطب وقد تردف (ألا) بلا أخرى فيقال: ألا ل كما قال: فقام یدود الناس عنها بسَيّفه وقال: ألا لا من سبیل إلا هند۱) ویقال للرّجل: هل كان کذا ‏ وکذا فیقول: ألا لا. حعل (ألا) تنبيها ورلا) نفيًا.'),
(3214, 'احدة', 'احده', NULL, ': ألا وأرض مألأة” : كثيرة الألاء کقولك: ماسة ومقصبت وتأليفها من لام ين همزتين وهو ریب ال له ساق شب اليح .. تقول: أديمٌ مَأُلويٌ أى: مدبو غ بالألاى وتصغيره: ۳۹ قال: إذا الا واله اندخسا فى ضاله وفی الألاء کنسا ولغة للعرب فى کل جماعة لیس فى آخرها علامة التأنيث الهاء والياء الوقوفة سل والالف المدودة وكانت من غير جماعة الآدمّيين ما يفهم ولا يفهم .. أَنْ بذ كر ويُجعل فعله واحداء وأكثر ما یحیء فى الأشعار.'),
(3215, 'ألب', 'الب', 'ب', 'الألب: الصغو .. یقال: أله مَعَهُ .. وصار الناس علینا أا واحدا فى العداوة والسترٌ. وقد تألبوا عليه تب إذا تضافروا علیه. والالب: الطرّد قال: ییا حمران ائ لب'),
(3216, 'ألت', 'الت', 'ت', 'اللات: معروف. وقول اللب عر وحَلّ: #وما تساهم من غملهم من شىء [الطور: ۰۲۲۱ أى: ما نقصناهی ولت یالت ويقال: یت ويقال: وت يلت وَلنَا.'),
(3217, 'ألس', 'الس', 'س', 'الْأَلْس: الكذب. والألوس: الضّعيف البخيل شبه المحبّلء قال: کابی الزّنَادٍ یم ال ذى أن وه ذاه والعقل مالسوس'),
(3218, 'ألف', 'الف', 'ف', 'الف فى العدد: عشر مائة والجميع: آلاف .. وقد آلفت الإبلء ؛ مدودة: صارت آلفا. والألفان: مَم” مَصْدرٌ آلفت الشّىء فأنا آلَمَهُ من الألفة. والْألَمَةٌ: مَصد الاتلاف. وإلْفك وأليفك: الذى يألفك. وأوالف الطیر: التى قد القت مَكة قال(: آولگا مكة من وق الحمى'),
(3219, 'اللوقة', 'اللوقه', NULL, 'ارده ويقال: هى الب بلرْطب, والوقة لغةء وفى الحديث: لا اكل إلا ما رق لى أى لَيّنَ من الطعام فصارّ كالرُيْدةٍ فى لینه. قال: وإنى لِمَن سالشم لألوقة وانسی لمن عادَيتم سم آسودا وَالإلقَةُ نُوصّف بها السّعْلاةٌ والذتبة والمرأة الجريئة هن. والولق: سرعة سير البعی'),
(3220, 'ألك', 'الك', 'ك', 'الألوك: الرّسالة وهی الْمألكة على مفعْلة؛ سُمّيت آلوکا لأنها تولك فى الف'),
(3221, 'من قولهم', 'من قولهم', 'من', 'یت لفرس اللجام أى: یلک قال(©: کی ی اعتی و إليك قولاً ستهّدیه ال واه لیسك عنی'),
(3222, 'ألل', 'الل', 'ل', 'الال: الرّبوبيّة. قال أبو بكر: [لما تلى عليه سجْع مُسیلمة]: وما حرج هذا من إِل,. (والإلً] فى قوله [تعالى]: لإإلا ولا ذمّة) [التوبة: ۰۸ ۰]۱۰ يقال فى بعسض'),
(3223, 'تفسير', 'تفسير', NULL, 'هو الله عر وحل. والال: فربّی ارجم قال": نك ان لت فى فرش کل الب من رأل التعام )١(‏ بلا نسبة فى اللسان (ألك). (۲) البيت لحسان بن ثابت فى اللسان (ألل) وفیه ومن قریش).'),
(3224, 'الال', 'الال', 'ال', 'هو جبل ممكة عرفات قال" *: مصطح ات من صاف ويرو يرز إلالا سيره التدافسم وال یل ول أليلاً وال والألية: الاسم وهو ما يجد الإنسانُ من وحم الحمّى ونحوها فى جَسّدو دون الأنين قال: وفی الصَّدر البلابل والأل ل وقال: آمساترین أشتكى الألاثلا من قحم الدّين وقلا اقلا وال الرزجل يول وییل ألا إذا أسرع. وال ونه يول ألآء إذا صفا وبَرّق. واه ادا ارب وكلّ الأدوات التى یم بها ألّة. . وال الحربة ونحوها من الم نة نة العی تتحذ على هيئة رأس الحربة والحميع: الال والالال قال: قياملًا بالججراب وبالالال وإنما سم أله لأنه دقيق.'),
(3225, 'التأليل', 'التاليل', NULL, 'تحريفك الشّىءَ كما یجرف رأس القلم. وَيُجْعَلُ طرف السسّكين ذا حدّين فیکون موه قال: له شوكة لته الشففار وف فردا إلى رده'),
(3226, 'ألم', 'الم', 'م', 'الألم: الوَجَعْ والمؤلم: الموجع. والفخل: ألم یلم ألما فهو: آبم. والحاوز: آلم يولم إيلامًاء فهو مولم. ۱'),
(3227, 'أله', 'اله', 'ه', 'إنّ اسم الله الأكبر هو: الم لا إله إل هو وحده. وتقول العرّب: الله ما فعلت ذاكء تریذ: والله ما فعلته. والتاله: التَعنّد. قال رؤية0©: من واسترجَعْسّ من تألهى وقولهم فى الجاهليّة الجَهْلاء: لاو أنت أى له أنت. ويقولون: لا هم اغفر لناء وكره ذلك فى الإسلام وقول" : لاه ابن عم لك لا ما ف الوبقات من العواقب'),
(3228, 'قوله', 'قوله', NULL, '۱ ۱ لاه در الشاب والتّمَرٌ الأس سود والراتکات تحت الرحال'),
(3229, 'قوله تعالى', 'قوله تعالي', NULL, 'ويّدَرَك وآلهتك [الأعراف: ۱۲۷]: طویذرَك وإلاهتك) أى عبادتك.'),
(3230, 'إلى', 'الي', 'ي', 'إلى: حرف من حروف الصفات. والالاء: انعم واحدتها: إل وأليّة: مين ومنها لو قال: یکذب أقوالى وجنت الوتلى (۱) ديوانه .)١58(‏ (۲) نسب فى التهذيب (7/؟ واللسان (أله) إلى ذى الأصبع. (۳) آحرجه البعاری فى ابحهاد؛ باب: التحريض على القتال رح ۶ ) وفى غير موضع ومسلم وح ۱۸۰۰).'),
(3231, 'الألية', 'الاليه', NULL, 'حمولة على فَعُولة وألوة على فعْلّةء والفغل: آلَيْت إيلاء. وتقول: ما یت عن الجهّد فى حاحتك. وما آلرَتك نصحًاء والصدر: الا وَالأُلىٌ عنزلة العْتَىّ والعتی لآ أن ای أكثرء وقال فى الفترة والعْجز: آل ومافى صَبرها الى ولولا اضطراره ال إقامة لت لكان یت قد وصفه بالعجز وهو يريد د معني غير آل. والألوّة: مود یدححن به ويتبخر یسَمّی عُود الا وهو أَجْرَدُ المود. [وألا یالی أى: لم یذ ع] قال: نحن فضلنا جهدن لم ناأتله وتقول عن الائتلاء: تألى إذا احتراً على أمر غيب فحلف عليه. والائتلاء والایلاء واحد. والأَلية: أله الشّاة وألية الإنسان .. و کیش أليان ونعجة أليانة ویجوز فى الضغر: آلی بوزن أفعل وألياء بوزن فغلاء. وَأْيّةْ الخنصر: اللحمة التى تحتهاء وهی ألية اليد.'),
(3232, 'المئلاة', 'المئلاه', NULL, 'حرقة مع النائحة سوداء تشیر بهاء والجميع: المآلى قال(: کال مُصفحات فى ذراه 2 وأنواحًا علیهن المآللى'),
(3233, 'أما', 'اما', 'اما', 'الأمة: المرأة ذات العْبُوديّة وقد رت بِالأمُوَة. قال: تركت لیر حاجلة عليه كماتردى إلى العُرُسات آمی("'),
(3234, 'لو قيل', 'لو قيل', 'لو', 'تأمّسء أى: صارت أمة كان صوابا. با وبال فى جمع آمة: إماء وآم أيضا قال يزيد: إذا تبارین معا کالاسی (۱) لبید دیوانه (ص ۱۰۳). (۲) اللسان (أما) وفیه: العرشات آم. (۲) رژبة دیوانه (ص ۳ ۱). فى سب بو مطرد القص ام'),
(3235, 'يعنى', 'يعني', NULL, 'قطا كأنهن إماء يبتدرنَ شيئا. وأَمَيّةُ: اسم رل والنسبة إليه: موئ .'),
(3236, 'بها', 'بها', 'بها', 'إمّا. وتقول: افعل كذا إمّا ممُصيبًا وإمّا محطتاء فلو قلت فى هذا المعنى: ان مصيبًا وان مُخَطْبًا جاز ذلك .. وتقول العرب على هذا المعنى: إن أصبت أو أحطأت. فاضا إذا'),
(3237, 'كان نحو', 'كان نحو', 'كان', 'بر فمّا أن تزور فلانا ولا فلانا فان (ما) لا تخرج من هذا الکلام؛ لان سا إذا وقعت [علی] نحو (آن) لزمت. وأمًا ایح حروج (ما) منه فاذا وقعت على فل أو نع أو اس کقولك: أعطنى من غلمانك إمّا فلاا وإِمّا فلانًا فلو شعت قلت: إن فلانا ول فلانا وكذلك جاء فى الشّعْر. وأمًا مّا) بالفتح فتوحب كل كلام عطفته كإيجاب أوّل الكلام وحوابها بالفاء کقولك: أمّا زي فحوك وأما عمرو فابن عمّك.'),
(3238, 'اما لا', 'اما لا', 'اما', 'وأمّا قولهم: إمّا لا فافعل كذا فإنما هو: إن لا تفعل ذاك فافعل ذاء ولكنهم لما جمعوا هولاء الأحرف فصرّنْ فى مَجْرى اللفظ مثقلة فصار (لا) فى آخرها كأنه عَجُرُ کلمة فيها ضمير ما ذکرت لك فى كلام طلبت فيه شيئا فرُدٌ عليك أمرك فقلت: الا فافعل ذا. وتقول: الق زيدًا ولا فلاء معناه: والاً تلق زيدً فد غ قال(: فطلقها فاست لها بكُفاء ولا یل مفرقك انس'),
(3239, 'فاضمر فیه', 'فاضمر فیه', NULL, 'وإلا ها يله وغير البيان أحسن.'),
(3240, 'أمت', 'امت', 'امت', 'فى القرآن عوجا ولا تا [طه: ۱۰۷]. والأمت: أن تصبٌ فى السّقاء ماءً فلا موه فيتتنى وذلك انیم هو الأشت وإذا مُلِىءَ وتمدَد فلا مت فيه. وهذا شىء مأموت, أى معروف قال رؤبة: (۱) فى اللسان (أما): النسبة أُمَوى بالضم ورا فتحوا. (۲) الأحوص ديوانه (ص ۱۹۰) برواية: فلست لها بأهل... وإلاشق...'),
(3241, 'آمچ', 'امچ', 'امچ', 'آمجت الابل تامج أَمَجًا: انس بها حر وعَطَّشنٌ والإنسان كذلك. وتقول: بعر'),
(3242, 'مج أى', 'مج اي', 'مج', 'یشرب فلا یکاد یی حتی يموت.'),
(3243, 'آمد', 'امد', 'امد', 'الأمَُ: دہ منتهی كل شىء وآحره.'),
(3244, 'أمر', 'امر', 'امر', 'الأمر: نقیض النهى والأمرٌ واحدٌ من أمور الناس. وإذا أَمَْتَ من الأمر قلت: مر يا هذاء فيمن قرأ: ام أهلك بالصلاة4 زطه: .]٠١١‏ لا يُقال: ولا اذ منه یه ولا اكلء نما بقال: مر وحذ وكل فى الابتداء بالأم استئقالاً لین فإذا تقدم قبل الكلام واو أو فاءٌ قلت: وأمن فاأمن كما قال عز وجل: وأمر أهلك بالصتلاة فأمًا کل من ال يَأَكُلُ فلا يكاد ذحلون فيه الهمزة مع الفاء والواو'),
(3245, 'یقولون', 'یقولون', NULL, 'و کلا وجذواه وارفعاه فكلا ولا ولو فأكلاه .. وهذه أحرف جاءت ا نوادرٌ وذلك أن أكثر كلامها فى کل فعل وله همزة مثل: بل یابل وأسر أن يكسروا یفعل منه وكذلك ابق يأبق فإذا كان | الفعل الذی وله همزة وفیل منه کر مردودًا إلى الأمر قيل: ايسر يا فلا ایس يا غلام وكأن أصلَّهُ یر بهمزتين فکرهوا جَمْمًا بين رین فحولوا إحداهما یا إذ كان ما تلا مکسوراه وكان حى الأمر من أَمَرَ يأمرٌ أن يقال ام اژحذه و کل بهمزتین فتر کت لیس الثانية وحولت واوا للضّمّة فاحتمع فى الحرف ضمّتان بينهما واو والضَّمّة من جنس جنس الواوء فاستتقلت العربٌ جمعًا بين ضمتین وواو فطّرّحوا همزة الواو لأنه بقلى بعد طرحها حرفان فقالوا: مر فلاا بکذا وكذاء وحذ من فلان وک ولم یقولوا: کا ود ُمُه ولا آخذه الا آنهم قالوا ذ فى مر ار تم قبل لف آثره و ار أو فاء أو کلام یتصل به الأمر من مر يم فقالوا: الق فلانا وآمره فردوه إلى آصله. وإنما فعلوا ذلك لأنّ آلف الأمر إذا اتصلت بکلام قبلها سقطت الأَلِفُ فى اللفظء ولم يفعلوا ذلك فى کل وخذ إذا اتصل الأَمْرُ بهما بكلام قبله فقالوا: الى فلانا وذ منه كذاء ولم نع وأحذ كما سمعنا وَأُمّرْ. قال الله تعالى: لوکلا مها رغد [البقرة:'),
(3246, '۵ ولم یقل', '۵ ولم یقل', '۵', 'وأکلا. فان قیل: لِم رتوا مر إلى أصلها ولم یروا وكلاء ولا [وخن؟'),
(3247, 'شىء أى', 'شيء اي', 'شي', 'کنرّ. والإمّرة: الأنثى من الحمّلان .. والإمَرٌ الضعیف من الرحال قال امرژ القي : ولست بذى رة ار إذاقيد ستكرهماأصحبا'),
(3248, 'الإمرة', 'الامره', NULL, 'الإمارة وهو أمير مُوّمّر. والأمارٌ: الموعدء قال : إلى أمار وأمارٌ متنی وار ولذها. أى: كثر ما فى بَطنها .. وأَمِرَ بدو فلان أمارة أى: كثروا وكثرت لهم'),
(3249, 'أمس', 'امس', 'امس', 'أمْس: ظرف مبنى على الكسرء وينسب إليه: إمسيى'),
(3250, 'أمض', 'امض', 'امض', 'أمض الرخل یأمَض فهو أمضة: إذا لم یبال العاتبة وعزعته ماضية فى قلبه؛ و کذلك إذا أبدى بلسانه غيرَ ما بریده فهو آمض. ۱'),
(3251, 'أمل', 'امل', 'امل', 'الأَمَلُ: الرحای تقول: لته آمل وأملته أَومّله تأمیلا. والتأمُل: الت فى النظی قال : تمل حلیلی هل تری من ظعائن تحملن بالعلیاء من فوّق حرم'),
(3252, 'الأميل', 'الاميل', NULL, 'یل من الرمْلٍ معتزل على تقدیر فویل قال“ يصف القؤر: فانصاع مَذعورًا وما تصّدّفا كالبورق یحتاز أميلا آعرفا ر'),
(3253, 'قال بعضهم', 'قال بعضهم', 'قال', 'أراد: الأَميّل فحفف. (۱) هذا من أصول الصرف وعلوم اللغة المبثوثة فى هذا الکتاب فتنبه. (۲) اللسان (آمر). ۳ العجاج فى اللسان (أمر) وفيه: وأمار مدتى ۰4 وقال ابن برى: وصواب إنشاده وأمار مدتی ) بالاضافة. .)۲۱ 4 (ط): الکلمة وترجتها من ختصر العين (الورقة‎ )٤('),
(3254, 'أمم', 'امم', 'امم', 'اعلم أنّ كلّ شىء يضم إليه سائر ما يليه فان العرب تسمّی ذلك الشّئْء ًا ..'),
(3255, 'فمن ذلك', 'فمن ذلك', 'فمن', 'ام الرأس وهو: الدماغ ورحل مأموم. والشَجة الآمّة: السی تبلغ أم التماغ.'),
(3256, 'الأميم', 'الاميم', NULL, 'المأموم. والأميمة: الحجارة اتی شدخ بها الرلس قال: ویوم جَلَيا عن الأهاتم بال منجنيقات وبالأما'),
(3257, 'قولهم', 'قولهم', NULL, 'لم لك: مخ وهو فى موضع ذم. وأمَ القری: مک وکل مديدةٍ هی ام ما حولها من القرى. وأمٌ القرآن: کل آية مُخکمة من آيات الشرائع والفرائئض والأحكام. وفى الحديث: رن أمّ الكتاب هى فاتحة الکتاب, لأنها هى المتقدّمة آمام كل سُورةٍ فى جميع الصّلوات. وقوله تعالى: #إوإنه فى أَمّ الكتاب لیا [الزحرف: .۲4'),
(3258, 'تعالى', 'تعالي', NULL, 'إن هذه أمعكم أُمَةَ واحدة4 [الأنبياء: ]٩۲‏ أى: دين واحد و کل من كان على دين واحدٍ مخالفا لسائر الأديان فهو أمّة على جدة وكان إبراهيم عليه السّلام أمّة .. وعن النبى صلى الله عليه وآله وسلم أنه قال: ويبعث يوم القيامة زيد بن عمرو أمّة على (۱) الرجز فى التهذيب )77١/١5(‏ غير منسوب. (۲) الحديث فى التهذيب .)٠۳۲/٠١(‏ بنحوه آحرجه البخارى فى التفسير (ح )٤۷٠٤‏ ولفظه: ام القرآن هى السبع المثانى...). (۳) البيت بلا نسبة فى التهذيب )٦۳۲/٠١(‏ واللسان (أمم). .)۱۳۲/۲( الرحز للعجاج فى دیوانه‎ )٤( ۸۸ باب الهمزة حدة, ۱ وذلك أنه تبرّأ من أديان اش رکین؛ وآمن بالله قبل مبعث النبى عليه السلام وكان لا يدرى كيف الدّين وكان يقول: اللّهم إنى أَعْبُدك؛ وأبرأ إليك من کل ما عبد دونك ولا أعلم الذى يُرضيك عنى فَأفْعَلَهُ حتى مات على ذلك . وکل قوم سبوا إلى نبی وأضيفوا إليه فهم أمّة .. وقد يجىءُ فى بعض الكلام أنّ أمّة حمّد صلى الله عليه وآله وسلم هم المسلمون خاصّة؛ وجاء فى بعض الحديث: أن أمّته من رسل إليه من آمن به أو كفر به فهم أُمّته فى اسم الأمّة لا فى الملة.. و کل حيل من الناس هم أمّة على حدةٍ. وكل حنس من السباع أَمّة كما جاء فى الحديث: لولا أن الكلاب أمّة لأمرت بقتلها فاقتلوا منها کل أسود بهيم" وقول النابغة: حلفت فلم أترك لنفسك ريبة ٠‏ وهل یامن ذو أمّة وهو طائم*) من رفع الألف جعله اقتداء بسنة ملکه ومن جعل (إنة) مکسورة الألف جعله دينا من الائتمام كقولك: ائتم بفلان إمة. والغرب تقول: إن بنی فلان لطوال الم يعنى: القامّة وابسم كأنهم يتومّمون بذلك طول الم تشبيهاء قال الأعشّى: فان مُعاوية الأكرمي سن صبا الوّحُوهِ طوال الأ'),
(3259, 'الائتمام', 'الائتمام', NULL, 'مصدر الإمّة .. ائتم بالامام إِمَّةء وفلان أحق بامّة هذا الشجده أى: بإمامته وإماميّته و کل من اقتدئ به وقّم فى الأمور فهو ما والنبى عليه السلام إمام ال والخليفة: إمام الرعية والقرآن: إمام المسلمين؛ والصحف الذى يوضع فى المساجد يُسَمّى الإمام والامام إمام الغلام وهو ما يتعلّم کل يوم والجميع: الأئمة على زنة الأعمة. إلا أن من العرب من یطرخ الهمزة ويكميرٌ الياءَ على طلب الهَمْرة؛ ومنهم من یف يومعدٍ فأمّا فى الأئمة فالتحفيف قبيح. والامام: الطريق قال [تعال]: إوإنهما -؟ وروم و ليامام مبين 4 [الحجر: ۷۹ والإمام: .عنزلة القدا وفلانٌ یوم م القوم؛ أى: یقدمهم. (۱) أحرجه أحمد (۱۸۹/۱)ء الحاكم (۰4۳۹/۳ 46۰ وقال الشيخ شاكر (ح :)١5148‏ إسناده (۲) أخرجه بنحوه الذهبى فى السير (۰)۱۲۹/۱ وقال الشيخ شعيب: رحاله ثقات. ۳ صحيح خر حه أبو داود والنسائى والترمذى وابن ماجه وغيرهم وانظر صحيح أبى داود وح ۶۷۱ ۲). )٤(‏ اللسان (آمم). :2( اللسان (أمم) وفيه: بیض) مكان وصباح).'),
(3260, '۷ أى', '۷ اي', '۷', 'لا تتوخوا أَردَاً ما عندكم فتتصدّقوا به. ولمم بالصّعيد من ذلك. والمعنى: أن تتو حو اطیب الصّعيدء فصار یسم نی أفواء العامة فعلاً لمح بالصعید. حتى [إنهم] یقولون: تم بالتراب وتيمّم بالثوب أى: بغبار القوب وقول الله عر وجل: #افتيمّموا صعيدًا 33 [المائدة:5, النساء: ۲4۳ أى: توخوا قال: فعمدًا على عمد تيمّمت مالکا؛ کسه'),
(3261, 'كقولك', 'كقولك', NULL, 'أم عندكم غدًا حاضر؟ أى: أعندكم وهی لغة حَسّنة. ويكون (أم) مبتداً الكلام فى الخبر وهی لغة بمانيّة يقول قائلهم: هو من خيار الناس أم يطعم الطعام أم يضرب الهام. وهو يخبر.'),
(3262, 'أمن', 'امن', 'امن', 'الأَمْنْ: ضد الخوف والفعل منه: امن یامن متا واأمنْ: مضع الأُمْن. وَالأَمَنَةٌ من الم اسم مَوْضوعٌ من أمنت. والأمال: إعطاء الأمّسة. والمانة: نقيضُ الخيانة'),
(3263, 'الفعول', 'الفعول', NULL, 'مأمون وأمين ومؤتمن من ائتمنه. والإبمان: التصديق نفسه؛ وقوله تعالى: وما آنت من لا [یوسف: ۲۱۷ أى: .عصدق. والتأمين من قولك: آمين وهو اسم من أسماء الله. وناقة أَمُون, وهی الأمينة الوثيقة وهذا فَعُولٌ جاء فى معنی المفعول ومثله: ناقة عضوب عضب فعذها حين تحلب ختى تدر 7۳ 9 و'),
(3264, 'آمه', 'امه', 'امه', 'الأَمّه: النسیان. وقد أيه يَأْمَهُ آمهٌاه أى: نسيى. والاءٌ هی: الوالدة والجميع: الأمهات. ويقال: تأمّم فلانٌ نّا أى: اتخذ لنفسه أمًا. وتفسير الأمّ فى كل معانيها: فة؛ لأن تأسِيسَهُ من حرفين صحيحين والهاء فيه أصلية ولكن العرب حذفت تلك الهاء إذا أمنوا الْنْس. ويقول بعضهم فى تصغير دم أَمَيْمة. والصّواب. أميهة ترد إلى أصل تأسيسها ومن قال: أميمة صغرها على لفظهاء وهم الذين يقولون [فی الجمع]: أمّاتء'),
(3265, 'قال', 'قال', 'قال', '[وقد جمع بين اللغتين]: إذا لمات تب الوُحُوه ‏ فرت للم بأاتكا”" ومن العرب من يحذف ألف رم كقول عدى بن زيد: ها العافِب عِنْدهٌ زيب أنت تفدى من أراك تعيب إنما اراد عدی بن زيد: عندى ام زید فلما حذفت الألف التزقت (ياء) عندى بصدر الیم فالتقی ساکنان فسقطت الیاء لذلك فكأنه قال: عندم. ۱'),
(3266, 'أن', 'ان', 'ان', 'الا خفيفة: نصف اسم وتمامه بِفِمُْلء كقولك: أُحِبُ أن آلقاك أى: أحب لِقَاءَك فصار (أن) و(ألقاك) فى الميزان اسمّا واحدًا. وإ حفيفة: حرف مُجازاةٍ فى .)۱۳۰/۱۰( بلا نسبة فى التهذيب‎ )١('),
(3267, 'قولك', 'قولك', NULL, 'إِنْ رب رحل: فإذا اعتمدت قلت: إنه رب رحل ونحو ذلك وهی فى الصّفات مشدّدة فيكون اعتمادُها على ما بعد الصّفات إِنّ لك و فيها وان بك وأشباهها. وللعرب فى (إنُ) لغتان: التحفيف والتثقيل فاّا من حفف فإنه رف بهاء إلا أن ناس من أهل الحجاز يخففون وينصبون على توهم الثقيلة وقرئ: وان كلا ل ونیم [هود: ]١١١‏ حففوا ونصبوا (كلا). وأمّا ان هذان لساحران [طه: ۱۲۱۳ فم حفف فهو بلغة الذين يخففون ویرفعون فذلك وحه ومنهم من عل السلام فى موضع (إلأ) ويجعل (ان) حَحْدَاء على تفسير: ما هذان الا ساحران؛ وقال الشاعر: نی باه ذليلاً بَمْدَ عرّته وإن ابان لَمِنْ أغلاج سُوراء'),
(3268, 'قالوا', 'قالوا', NULL, 'ان .. تكون الهاء صلة فى الوقوف وتسقط [الهاء] إذا صرفوا. وبلغنا عن عبد الله بن الرُبَيْر أن أعراييًا أناه فسأله فحرمه فقال: لعن الله ناقة حملتنى إليكء فقال ابن'),
(3269, 'لزیر', 'لزیر', NULL, 'ان وراكبهاء أى: آحل. فما قيم فانهم علوت اف كل رأ ورن مصوبته من لتقل والحفف عيناء کقولك: أريد عَنْ اکلمك, و [بلغنى عنك مقيم]. وأذ الزجل'),
(3270, 'يعن', 'يعن', 'يعن', 'من الأنين قال7: تشکو الخشاش ومَجْرَى لنسعتین كما أن الْرِيضُ إلى عوَاده لیب'),
(3271, 'رجل أننة', 'رجل اننه', 'رجل', '[كثير الکلام والبت والشكوى0”” وهو البليغ القَوّالَة والجميع: الأنن (۱) هذه قراءة نافع وابن عامر وحهزةق والکسائی. السبعة لابن بحاهد (ص 4۱۹). (۲) البیت لذی الرمة فى اللسان (أنن). (۳) من التهذیب )٥٦۲/٠١(‏ عن العین. ۹۲ باب الهمزة ولا يشتق منه فِعل. ومن الأنين يُقال: أن يِن أنيناء وأنا وأنة وإذا آمرت قلت: اين لأن . الهمزتين إذا التقتا فسكنت الأخيرة احتمعوا على تليينها. ويقال للمرأة: إنى کما یقال'),
(3272, 'للرحل', 'للرحل', NULL, 'اقرن وللمرأة قرّى. وإنما یقاس حرف التضعيف على الخَرَكة والسکون بالأمثلة من الفِمْل فحيئما سكنت لام الفعل فَأَظْهرْ حرفى التَضّْعيف على ميزان ما كان فى مثاله نحو قولك للرّحل فى الأمر: افعَل بحزومة اللآم فتقول فى باب التضعيف: اغضض واقرر وائدّذ فإذا تَحَرَكت لام الفعل فمثال ذلك من التضعيف مُذْغم الحرفين يقال للمرأة: افعلی فتحرّكت اللام قلت: غضّی وقَرَى وانی وجدّى فهذا قياس الجزوم كله فى باب التضعيف لذلك قلت: اين'),
(3273, 'أنب', 'انب', 'انب', 'التانیب: التَرْبيخ واللوم. والأناب: ضَرْبٌ من العطر يضاهى السْكَ. والأئب: الباذنحان. والأنبوب: ما بين العُقَدتَيْن فى القَصّب والقناة. وأنبوب القَررن: ما بين اعد إلى الطرّف قال: ۱ 56 £ | ل ویقال لأشراف الأَرْض إذا كانت رقاقا مرتفعة: أنابيب قال العجّاج فى وصف ورود العير الماع : 1 یک[ آثبوب له امتثال)'),
(3274, 'أنث', 'انث', 'انث', 'الأنثى: حلاف ال کر من کل شىء .. والأنشيان: الخصنيتان والأنثيان: الأذنان'),
(3275, 'أنع', 'انع', 'انع', 'آنح الرجل يأ أنيحًا وأنسًا إذا تأڏی من مَرَضٍ أو بر یتح ولا یر آنینا'),
(3276, 'أفس', 'افس', 'افس', 'الانسن: جماعة الناس وهم انس (تقول]: ریت عکان كذا أَنَسا كثيراء أى: ناسًا. وإنسيىّ القؤس: ما أقبل عليك والوحشي: ما أدبر عنك. وانسی الإنسان: شِقه (۱) التهذيب (4۸9/۱۰). (۲) البیت فى التهذیب (۱5/۱۰). واللسان (أنث) منسوب إلى ذی الرمة.'),
(3277, 'أنض', 'انض', 'انض', ': لحم أنيض: بقى فيه لهُوءَة ای لم ینضَج. وآنضته إيناضًا أى آنضجته فتضج واللازم آنض أناضة فهو أ أنيض قال زهير: یلح مُضغة فيها آنب ض اصلت فهی تحت الکشح داء۶)'),
(3278, 'أنف', 'انف', 'انف', 'الأنف معروف والجميع: الأنوف. وبعيرٌ مأنوفا, أى: يساق بأنفه أن إذا عقره الخشاش انقاد وفی الحديث: اِنْ المؤمن کالبعیر الأنف حیتما قي انقاد( 5 أى: مأترف كأته عل فى نف حشاش يُقاد به. والأنف: : الحمية) ورحل حَمِيُ الأنف [إذا كان افا ینف آن ضام" ''. والأنف من الرعی والسالك والمشارب: ما لم يُسبّق إليه ۳1 5 3 5 عر ر كلا آنف؛ و کاس انف ومنهل آنف قال: والأنف أيضا: الذلول النقاد لصاحبه. وقال بعضهم: النف: الذی يأنف من الرّحر والسّوْط والحث فهو سمح موات يعنى الدّواب. وائتنف اتناف وهو أوّل ما تبُتدئ به من كل شىء من الأَسْر والكلام كذلك وهو من نف الشّىء؛ يقال: هذا نف ال'),
(3279, 'أنق', 'انق', 'انق', 'الأنق: الاعغجاب بالشیء تقول: قت به وأنا نی به أثقاء وانا به ابق مُعْجَب. وآنقنی 1۳ يۇنقنى إيناقاء واه لأنيق مون إذا حبك حُسنه. وروضة أنیق ونبات أنيق قال : لا این حَلِيسُهُ ولا نس'),
(3280, 'أنك', 'انك', 'انك', 'الآنك: الب والقطعة: آنكة.'),
(3281, 'أنم', 'انم', 'انم', 'الأنام: ما على ظهر الأرض من جميع الخلق ویجوز فى الشعر: الأنيم.'),
(3282, 'أنن', 'انن', 'انن', 'انظر (أن). أنى (آنا): آنی معناها: کیف؟ ومن آین؟. آنی شفت: [کیف شئت؟] ومن أين شغت؟ قال الکمیت: أنى ومن أين آبك المرب وقوله جلّ وعرّ: [أنى لك هذا [آل عمران: ۲۳۷ أى: من ین لك هذا؟ وقوله [حل وعز]: انى يكون له الملك علينا [البقرة:۲4۷] أى: كيف یکون؟ وقال(: ومطعم الغنم یوم لخنم مُطْعَمُهُ | آنی توجّه والضرومْ مخروم'),
(3283, 'شعت', 'شعت', 'شعت', 'آنا وحذفها أحسن. وقوله تعالى: لکنا هو الله رنی4 [الکهف: ۲۳۸ معناه: لكنّ أناء فحُذفت الهمزةٌ وحذفت [إحدى نونى] لكنّ فالتقت نونان فأدغمتها فى صاحبتها. والانی والانی؛ مقصور: ساعة من ساعات الیل والجميع: آناء وكلٌ إنى ساعة.'),
(3284, 'أضى', 'اضي', 'اضي', 'والانی مقصور آیضا: الادراك والبلوغ وإِنَى الیء بلوغه وإدراكة فتقول: انتظرنا إنى الطعام أى: إدراكه؛ و [قوله تعالى]: غیر ناظرین إناه) [الأحزاب: ۳*]'),
(3285, 'الأناة', 'الاناه', NULL, 'احلی والفغل: انی وتأنی؛ واستأئی أى: یت قال: وتان إنك غير صا ويقال للمتمکث فى الأمر: التأنی. وفی الحديث: آذیت وآنیت)) أى: أخرت المجىء وأبطأت وقال الحطيئة: وآنيت العشاء إلى سْهَيّل أو الشّعرى فطال بى الأناءٌ واستأنيت فلاناه أى: لم أُعْجِلَةُ .. ويقال: استان فى أمرك أى: لا تعجل قال: استأن تفر فى أمورك كلها وإذاعزمت على الهوى وکر“ (۱) بلا نسبة فى التهذيب (5 0005/١‏ واللسان نی) (۲) أخرحه أحمد )۱۸۸/٤(‏ وانظر غریب الحديث لأبى عبيد (0۳/۱). (۳) البيت فى التهذيب )555/١5(‏ غير منسوب. ۹۹ باب الهمزة واستأنيت فى الطعای أى: انتظرت إدراكه. ويقال للمرأة المباركة الحليمة الواتية: أناة والجميع: الأنوات. قال أهل الكوفة: إنما هی من الوّنی وهو العف ولكنهم همزوا الواو. والانای ممدود: واحد الآنية والأوانى: جمع ابحمع جمع فعال على أفعلة ثم جمع أفعلة على أفاعل.'),
(3286, 'أهب', 'اهب', 'اهب', 'رالأهبَةُ: العدة وجغها: أُمَب]. وَتَأَمَبُوا للمسير: أحذوا أَمْبَبَهُ. [والاهاب: الجلد وحمعة: اهب .'),
(3287, 'آهل', 'اهل', 'اهل', 'أَهْل الرجل: روه وأص الناس به. والأهُل: التروج. وأهل البيست: سُكَانه وأهلٌ الإسلام: من يّدِينُ به ومن هذا يُقال: فلان آهل كذا أو كذا. قال الله عر وجل: هر أهل التقوى وأهل المغفرة4 [الدتر: <ه], جاء فى التفسير أنه جل وعرّ أهلّ لأن یی فلا يُخْصَّىء وهو أهل لمغفرةٍ من اتقاه''"2. وجمع الأهل: آملون وأمْلات والأهالى: جع ابلمع وحاعت الياء التى فى الأهالى من الواو التى فى الأهلون. وألته لهذا الأمر تأهیلاه ومن قال: وَمَّلْنْهِ ذهب به إلى لغة من يقول: وامَرنهُ وواکلته. ومكاث مأهول: فيه أفل. ومكانٌ آهل: له أَهْلّ. قال الشاعر”): وقذمسًا كان ماه سول فأنتى مرح الغفر وقال*: عرفت بالنطریه التازلا قفرا وکانت لبم مآيلا وکا" دابة وغیرها إذا الف مکانا فهو آهل وأهلی أى صار آهلیاه ومنه قیل: أهلي لا ألف الناس والمنازل؛ وبرّىّ لا استوحش ووحشی وحرّم رسول الله صلی الله عليه وعلی آله وسلم يوم خیبر حوم الحمر الأهليّة””). والعرب تقول: مرحبًا وال ومعناه: نزلت راء أى سعة وأثیت أهلاً لا غرباء. والإهالة: الأَلية ونحوهاء بوذ فیقطن ثم يُذَابُ وهى: امحمیل ایض (۱) (ط) تكملة من مختصر العين ورقة (۹۸). (۲) التهذيب (417/ مما نقل فيه عن العين. (۲) التهذيب (518/ اللسان (أهل). غير منسوب. (ه) آحر جه البخاری فى الجهاد رح ۱ ) وفى غير موضع من صحیحه؛ ومسلم (ح .)١556‏ 5 EE 1!'),
(3288, 'أهن', 'اهن', 'اهن', 'الإهان: : العرجون يعنى ما فوق شماریخ عذق مر إلى التحلة والعدد: آهنة ويُحْمَعُ على هن قال: أرى لها کب دا ملسا َيّسة مثل الاهان وبَطنًا بات صان'),
(3289, 'أوأ', 'اوا', 'اوا', 'ی مدودة: فى رَجْر الخيل فى العساكر ونحوهاء قال: فى جَحفل لحب حم صواهلة تسمعٌ باللیل فى حافاته 0047© وتقول فى النداء: آا فلان.'),
(3290, 'دواء قلت', 'دواء قلت', 'دوا', 'هو موَوء مثل مَعُوع ویقال من ذلك: أؤته بالاء آء.'),
(3291, 'أوب', 'اوب', 'اوب', 'يقال: آب فلان إلى سیفه أى: رد يده إلى سيفه. وآب الغائب يووب أوباء'),
(3292, 'التأويب', 'التاويب', NULL, 'من سير الليل رت الإبل تأويباء والتأويبة: مرّة لا غير ویقال: التأویب: سیر التهار إلى اللیْل. وتقول: لتهنك أوبة الغائبي أى: لیابه ورجوعه”. والمآب؛ ارحم. والمتأوّب: الجيّد الأوب أى: سريع الرُحوع. وآبت الشّمس إياباء إذا غابت فى (۱) البیت بلا نسبة فى اللسان (أوأ) وعجزه فیه: بالليل تسمم ... (۲) البيت لكعب بن زهيرء فى اللسان (أوب). (۳) الرحز فى التهذیب (ه ٩/۱‏ ۰ وفى اللسان (أوب) بلا نسبة. )٤(‏ فى (ط): وحوعه. وهو تصحیف بیّن. ۹۸ ۱ ۱ باب الهمزة'),
(3293, 'مآبهاء أى', 'مابهاء اي', NULL, 'مَغِيبهاء قال تب : ۱ زا تنب الت عند ماب فى عين ذى خلب وتأط خر رم'),
(3294, 'آود', 'اود', 'اود', 'وَالأَوْدُ: مصدر آد ی وود أَوْداه وتقول: أَدْتُ الود فأنا آووده دا فانآد'),
(3295, 'تفسيره', 'تفسيره', NULL, 'ته فانعاج قال: لم يلك یناد فأستی انآدى”")'),
(3296, 'أور', 'اور', 'اور', 'الأوار: حر د التغور من بعیل. ویقال: إرة فى ورة فالإرة: النار بعينهاء بعينهاء والورة: الحفرة.'),
(3297, 'الستأوز', 'الستاوز', NULL, 'الفزع قال: كأنه بزوان نام عن غنم مُسستأورٌ فى سواد الليل موب"'),
(3298, 'أوز', 'اوز', 'اوز', 'الاوز: من طیر الاء والواحدة بالهای ورحل و وامرأة ورف أى: غليظة لّجيمة فى غير طول لا یخذف ألفها. واوزة على فِعَلَّةء ومَأُوَرَ على مَفْعَلة وكات ينبغى أن تقول: مار ولكنه قییخ. ومن العَرّب من يُحْذف ألف لور ويقول: ورت ویقال من ذلك: موزة. ۱'),
(3299, 'آوس', 'اوس', 'اوس', 'آرم: قبيلة من اليمن واشتقاقه من آس يؤوس أوساء والاسم: الایاس؛ وهو من العِوّض. أَسْتَهُ آژوسه أوسًا: مضه أَعُوضُهُ عَرْضًا .. واستآسنی فاشته أى: (۱) البیت لتبع فى اللسان (أوب). 9( فى اللسان (أود): انادا.'),
(3300, 'قال الضرير', 'قال الضرير', 'قال', 'وأدته أى دفنته وأنشد البيت قال: ويروى تلمأت عليه مثل معناه.. 43 البيت بلا نسبة فى اللسان (أور) وفیه مدعوب بالدال المهملة.'),
(3301, 'أوف', 'اوف', 'اوف', 'الآفة: عرض مُفسيكٌ ند لما أصاب من شی واحمیم: الافات. ویقال: آفة ارف الصلف وآفة العلم النسيان. إذا دخلت + الآفة على قوم قيل: قد إفواء ويقال فى لغة: قد افوا'),
(3302, 'أوق', 'اوق', 'اوق', 'الأوقة: هط يجتمع فيها الاء. . واحمیع: ال وق قال(: واغتمس الرامى لها بين الق'),
(3303, 'الأوقية', 'الاوقيه', NULL, 'وزن من أوزان الذهب وهى سبعة ة ماقیل. وآق فلان عليناء أى: أشرف قال20. آق علينا وهو شرآ يق'),
(3304, 'الأؤق', 'الاؤق', 'اق', '۳ وشدّة الأمر رظن قال )١(‏ التهذیب (۱۳۷/۱۳) اللسان (أوس). (ط). فى الأصول: قال لبيد وليس فى ديوانه. (۲) ما روى عن العين فى التهذيب (۱۳۷/۱۳). (۳) (ط): ديوان الهذليين (۲/۳). فى الأصول: قال لبيد. (") بلا نسبة فى التهذیب (۰)۳۷/۹ واللسان (أوق). (۷) رؤبة ديوانه وص .)٩۲‏ و ماسم 00 اليل آنسی ى آوته اوقم سم مج وأوّفته تأويقا [أى: ماه المشقة والکروه! 3 قال(: عر على قومك أن تَوَوّقى أو آن تبيتى ليلة لم تغبقى'),
(3305, 'أول', 'اول', 'اول', 'فأما الأوائل من الأول فمنهم من یقول: تأسيس ؛ بنائِه من همزةٍ وواو ولام. ومنهم من يقول: تأسيسه من واوين بعدهما لام؛ ولكلّ حجَتّ قال فى وصف الثور والكلاب: جهام تحث الوائلات ار رواية أبى الدُكيْض. وقال أبو حيرة: تحث الأرّلات آواحره. والاول والأولى عنزلة أَفْمَل وفغلی. وحم اوّل: أوّلون: وجمع أولی: آولیات كما أن حَنْعٌ الأخرَى: أخريات. فمن قال: إن تألیفها من همزة وواو ولام فكان یبغی أن یکون أفعل منه: آوّل مدود [کما] تقول من آب يَؤُوب: آوّب ولكنهم احتجوا بأن قالوا: أَدْغِمَتْ . تلك المدهُ فى الواو لكثرة ما جری على الألسن .. ومن قال: إِنّ تأليفها من واوين ولام [حعل الهمزة 91 سل وأذغم إحدى ؛ الواوين فم 5 لاعری وشتدهما] . وتقول: ر ف بام قال ] 9 ماذاق یلا منذ عام أوّل'),
(3306, 'أولى', 'اولي', NULL, 'الاولی بالشىء: الأحقّ به من غيره وهم ار والاشان: الأَوْلّيان وكذلك کل كلمة فى آخرها ألف إذا جمعته بالنون كان اعتماد الواو والياء اللتين قبل النون على نصبه نحو: مُثنى. وأَؤْلّى: معروف وهو وعيد وتهدد وتلّف.'),
(3307, 'أولاه', 'اولاه', NULL, 'أولاء: يقصر فى لغة تميم وأهل الحجاز بمدّون أولاء والهاء فى أوّله زيادة للتنبيه إذا قلت هولای وقلما يُقال هؤلائك فى المخاطبة وهو جائز فى الشعر. أوم (أيم): الأَيْمُ من الحيّات: الأبيض للطیت. قال: كان زمامهاأَئِمٌ شحاغ تراد فى غصون مُعْضة شبّه تحريك الرّمام بحيّة بين أغصان متشابكة. والإيامٌ: الدّحان قال أبو ذؤيب'': فلمّا احتلاها بالإيام تحيزت 2 بات عليها ذلها واكتتابها وامرأة یم قد مت یمت. إذا كانت ذات روج أو كان لها قبل ذلك زوج فمات وهی تصلح للازواج لان فيها سوّرة من شباب والأيامّى: جمغها؛ تقول: آمت المرأة تيم لك 4 وأعة واحدة وتأيمَت) قال(*0. مغايرًا أو يرهب التأييما'),
(3308, 'الامة', 'الامه', 'امه', 'العيب قال عبيك: ميلا ابیت الله . مھ لا ان فيما قلت امه والآمة من الصّبى فيما يقال: هی ما يعلق بسرّته حين یولد ويقال: مالف فيه من حرقة وما حرج معه قال حسان: )١(‏ التهذيب (ه ۹/۱( و اللسان (أول): ونضربکم؛ باجحزم لضرورة الوزن. . (۲) البيت لأبى ذؤيب الهذلى فى اللسان (أيم) وشرح أشعار الهذليين (0۳/۱). ويروى ثباتاء بالنصب. (۳) تصحفت فى (ط) إلى أعنا والتصويب من اللسان (أيم). (۶) رؤبةء ديوانه وص .)١185‏ ۱۰ باب الهمزة وموعودة مقرورة فى معاوز بآمتهامرسومة لم توس'),
(3309, 'الأوام', 'الاوام', NULL, 'حر العطش فى اجحوف؛ ولم اسمع منه فعلا ولو جاء فى شعر: راومه تأوعا لما كان به بأس.'),
(3310, 'أون', 'اون', 'اون', 'الأؤنان: جانبا اج يقال: حرج ذو أَوْنيْنِ. والأؤنان: العدلان والأوانان يقال للأتان إذا أقربت وعظم بطنها: قد أوّنت تأوينا. وإذا لت وشَرِبْت وانتفخحت خاصرتاك فقد آونت تأويناء قال*: ۱ سرا وقد أذ تأوین العُقَقْ'),
(3311, 'عقق', 'عقق', 'عقق', 'التی استبان حملهاء ونبتت العقيقة على ولدها فى بَطنها. والأوان: الحين والژمان تقول: جاء أوان البرد قال العجاج: هذا آوان امد إذ جح عُمَرْ'),
(3312, 'مع الأوان', 'مع الاوان', 'مع', 'آونة. والآث: عنزلة الساعة إل أن السّاعة جز موقت من أجْزاء الیل والنهار. وأما الآن فاه يلزم السّاعة التی يكون فيها الكلام والأمور ریثما يبتدئ ویسکت. والعَرَبُ تتصبه فى الجر والتصب والرّفع؛ لأنّه لا يتمكن فى التصریف, فلا نی ولا يثلث ولا يصغرّء ولا بصرف ولا يضاف إليه شیء.'),
(3313, 'أوه', 'اوه', 'اوه', '[و: حكاية لاه فى صوته وقد يفعله الإنسان من التَوَجّع. قال اقب العبدی(۲): ّ هجو - إذا مساقنت أَرْحَلها بلیل تأوه اف ال الریسن'),
(3314, 'يروى', 'يروي', NULL, 'نَهَوَهَ هاهقء وبيان القطع ا حْسَن. واه فلان واه إذا توخع فقال: آو. أو'),
(3315, 'ابن آوی', 'ابن اوی', 'ابن', 'لا يصرف على حال ويُحْمَلُ على (أفعل) مثل: خوی.'),
(3316, 'للرجل', 'للرجل', NULL, 'احذر البئر لا تفع فيهاء فيقول: أو یعافی الله أى: بل يعافى اللهُ. وتكون رأو) ععنى (حتى) قال امرؤ القیس(: فقلت له لا تبك عيناك نما نحاول ملكا أو موت قنفذرا'),
(3317, 'آیاء أى', 'ایاء اي', 'ایا', 'تقول فى النداء: أئ فلات وقد يُمّدُ: آى فلان. وقد تکون (أى): تفسیرا'),
(3318, 'للمعانی', 'للمعانی', NULL, 'أئْ كذا وكذا. وأمّا رای) فانها تدحلٌ فى اليمين كالصّلة رالاتا ومنه قول الله عر وحلّ: ای وربّى إنه لحق) [یونس: 4 5] [العنی: : نعم والله]". وا (أئ) مثقلة فانها عنرلة (مَنْ) و(ما). تقول: يهم أخوك هن أحتك؟ وآیما الأحوين حب إليك؟ وأيا ما تحب منهم؟ ؟ تحعل (ما) صلةء وكذلك فى ,أيّما الأحوين (ما) صلة. وأى لاتنون؛ لأنّ (أئ) مضاف. وقوله تعالى: یا ماتدعوة [الإسراء: ۱۱۰]: (ما) صلة (آیا) يجعل مكان اسم منصوب کقولك: ضربتك فالکاف: اسم الضروب, فاذا أردت تقدیم اسمه غير ظهوره قلت: ایاك ضربت فتکون (إيَا) عمادا للكاف لأنْها لا تفرد من الفعل ولا تکون (یّا) مع کاف ولا هاء ولا ياء فى موضع الرّفع وابسر ولکن تکون كقول الْحَذْر: [اك وزيدًا. فمنهم من يجعل التحذير وغيرَ التحذیر مكسوراء ومنهم من ینصبه فى التحذیر ویکسیر ما سوی ذلك للتفرقة. وأيَانَ): عنرلة [متى] ۱ بحتلن فى نونهاء فیقال: هی أصليّة ویقال: هى زائدة. و(كأيّن) فى معنی: رکم) يقال: الكاف فيها زائدة والنون .عنزلة التنوین وأصل بنائها: (أئ) ويقال: بل النون مع ی أصل والكاف زائدة لازمة كما لزمت كاف (كم) ونحوها.'),
(3319, 'أيا', 'ايا', 'ايا', ': الآبة: القلامك والآية: من آيات الله والجميع: الآى. وتقديرها: فَعَلَة. قال');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(3320, 'خليل', 'خليل', NULL, 'إن الألف التى فى وسط الآية من القرآن والآيات العلامات هى فى الأصل: یای وكذلك ما جاء من بناتها على بنائها نحو: الغاية والراية وأشباء ذلك .. فلو تکلفت اشتقاقها من (الآية) على قياس علامة معلمة لقلت: آية مأياة قد یت فاعلم إن شاء )١(‏ البيت بلا نسبة فى التهذيب )170/١8(‏ برواية: (فأو ..) ورواية اللسان (أوه): فأوه. (۲) (ط): تکملة ما روی عن العين فى التهذیب (۰ 15۷/۱). ۳( ما روی عن العين فى التهذیب .)٠١١/٠١(‏'),
(3321, 'أيد. أدى', 'ايد. ادي', NULL, 'الأَيْدُ: القرَّ وبلغة ميم الآ ومنه قيل: لد فلانٌ فلانا إذا آعانه وقواه.'),
(3322, 'التأیید', 'التایید', NULL, 'مصدر يدنه أى فَوَيته. وقوله تعالى: #والسماء تناها بأَيْدٍ [الذاريات: ۲4۷ أى بقوّة. وإياذ کل شىء ما قى به من جَانِيُهه وهما إياداه وإياد العسكر الم وللیْسرق و کل شیء كان واقيّا شىء فهو إياده قال العجّاج: عن ذى [یاین لهام ذو دسر برکنه أركان دسخ در ۱) وأدّی فلانٌ ما عليه أداء وتأدية وفلانٌ آدّی للامانة 2 من فلان غير أن العامة قد لهجوا بالخطاء یقولون: فلان أدّى للأمانة وهذا فی النحُو غير جائر وألف الأداة هى الواو لأنك تقول: أدوات لکل ذى حرّفة دا وهی آلته يقيم بها حرفته. وأداة'),
(3323, 'الإير', 'الاير', 'اير', 'ريح حارّة ذات إيار ياؤها فى الأصل وا مثل واو الرّيح صارت يا لكسرة ما قبلهاء وتصغيرها: رُوَيْحة وأُويرة. وقال بعضهم: بل الإير: امال الباردة بلغة هُذيل قال: وإنا مساميح إذا هبّت الصا وإنا مساميح إذا الإير هت وناس يقولون: هو جمع الأدار فى هذا البیت كأنهم يجعلون الأوار من حر الستموم.'),
(3324, 'الایاس', 'الایاس', NULL, 'انقطاع المطمع واليأس: نة نقيض الرحاء. يفست منه يأسًاء وآيست فلانا إياسّاء اما ایستة فهو خط إلا أن يجرء فى لغة على التحویل وهو قبيحٌ جدًا. وتقول: أيأسته فاستيأس والصدر منه إياس. فأمّا الغامّة فيحذفون الهمزة الأخيرة ويفتحون الياء غليهاء فيقولون: أيسته إياسًا. وتقول فى معنى منه: قد يعست أنك رحل صِذق أى: علمت. قال جل وعز: أفلم ييأس الذين آمنوا [الرعد: ۰۲۳۱ وقال الشاعر: ألم یی أس الأقوامُ أنى أنا ابن وان كنت عن عُرْض العٌشيرة نائيا'),
(3325, 'أيض', 'ايض', 'ايض', 'والأَيْض: صيرورة الشىء شيئًا غيره وتحوله عن ال حالة ويقال: آض سواد شعره بیاضاء قال: حتى إذا مسا آض ذا آعراف کالک ون ال و کف بالاکاف'),
(3326, 'أيق', 'ايق', 'ايق', 'الق : الوطیف قال الطرمّاح: وقام الها یقن کل مک كما رص أيْقا مُذْهَبٍ ان صافن'),
(3327, 'أيك', 'ايك', 'ايك', 'یک : عَيْضة تنبت المسّدرَ والأراك ونحوهما من ناعم الشّجّر. یقال: أيكة'),
(3328, 'آیکت أى', 'ایکت اي', NULL, 'مثمرة.'),
(3329, 'أيل', 'ايل', 'ايل', 'جاء فى التفسیر أن كلّ اسم فى آخر إيل نحو [حبرائیل] فهو معبّد لله كما'),
(3330, 'هو', 'هو', 'هو', 'اثر وكذلك بول الإبل [التى جزأت بالرُطبع قال: ومن آیل كالورس نضَحا کسونه . متون الصفا من مُصْمَحِلَ وناقع والمصدر منه: الأول والأوول. والوئل: : الملجأ من ولت وكذلك الآل من آلت. وَالرَّحُلٌ يؤول من مَآلة بوَرّن مَعالة“ قال: اشغ ساس سا یر السّماء ولا عم الذَرَى الووق المآل فى هذا الموضع: للحأ وه غير أذ وأل يل لا بعر فى سعة مایا آل يوو ل إليه ار تقول: طبحت | لنبيذ والدّواء فآل إلى قذر كذا وكذاء إلى الثلث أو الربع أى: رجع.'),
(3331, 'أيم', 'ايم', 'ايم', 'انظر مادة (أوم)'),
(3332, 'أين', 'اين', 'اين', 'أين: وقت من الأمكنة تقول: أين فلات؟ فیکون منتصبًا فى الحالات کلها. و اما ان من الإعياء فإنه یصرف وهو يجرى بحرى الكلام فى كل شیء والعَرَبُ لا تشتق منه فغلاً الا فى الشع فقالوا: آن يكين أينًا. والاوا: شبه رح غير مشدود الوه (۱) ما روی فى التهذیب (۰)4۲/۱۰ عن العین. (۲) التهذیب (4۲/۱۰). ۱۰۸ باب الهمزة'),
(3333, 'الإيوان', 'الايوان', NULL, 'لغة فيه قال: إيوان ری ذی القِرَى والرّيحان”") وجماعة الإوان: أردْ. وجاعة الإيوان: أواوين وإيوانات:'),
(3334, 'أيه', 'ايه', 'ايه', 'إيه الکسورة: فى الاسترادة والاستنطاق. قال ذو الرّمة: و تایه عن ام سلم وما بال تم شوم اباقع'),
(3335, 'المفتوحة', 'المفتوحه', NULL, 'جر وتهی كقولك: إية حبك يا رجُل وقد ونان ياء فيقال: یه وایها. والتأییه: التصویت أيه بالناس والابل: صَّوَّتَ وهو أن يقال لها: ياه یاه.'),
(3336, 'بأیا', 'بایا', NULL, 'البأبأة: قول الانسان لصاحبه: بأبى آنت ومعناه: آفديك بأبى ويشتق من ذلك فغل فيقال: باب به. ومن العرب من يقول: وابأبا أنت حعلوها كلمة مبنية على هذا التأسيس. والبأبأة: هدير الفحل فى ترجيعه بتكرار قال رو بة(: بَحبَحَهُ مرا وما با البَحْبّخَة: هدير الفَحْل دون الکبّش والتَيْسء وكذلك البغبغة وقال . يَسُوقَها أعيس هدار يبب بب'),
(3337, 'بأج', 'باج', 'باج', 'البأج: الان . وقال عمر بن الخطاب: لأجعلنٌ الناس بأحاً واحداء أى یبا'),
(3338, 'احداء أى', 'احداء اي', NULL, 'طريقة واحدة فى العطاء. وقوله: هم بَأجّ واحدء أى: ضر واحدٌ. وبأج'),
(3339, 'شیء أى', 'شیء اي', 'شی', 'رخص فلم يشتر.'),
(3340, 'بار', 'بار', 'بار', 'ارت لشیء واتار وائتبرته لغات أى: حبأته. . وفى الحديث: وإن عبدا قى الله ولم يبور حير . وبرت بورق أى: حفيرة فأنا رها بأراء وهی حفيرة صغيرة للنار توعد فيهاء والبثار أيضا: حافر البگر.'),
(3341, 'سأس', 'ساس', 'ساس', 'البأس: احرب. ورجل مس قد بوس باسة أى: شجاع. والبأساء: اسم للحرب والمشقة والضّرر. والبائس: الرحل التازل به بليّة أو عُدْمٌ برجم لما به قد ؤس یوس بۇسًا وبوسی ومنه اشتقاق بلس وهو نقیض صلح؛ ری بحری نعم فى المصادر إلا آنهم إذا صرّفوه قالوا عسوا ونعمواه وإذا جعلوه نعتا قالوا: تیم وبئيسء كما يقرا (۱) دیوانه (ص ۰۱۷۰ وفیه بفتی بدل بخبخة). (۲) رؤبة دیوانه (ص ۱۹۹). (۲) فى (ط): البیان بباء موحدة تحتية ثم ياء مثناة تحتية وفی اللسان (بأج): التبان. والثبت من کلام الصنف فى مادة وببب. حيث قال عن الببان: ووهو والبأج معنى واحد. وانظر اللسان (ببب) حيث ذکر أن منهم من يسميه بیانا كما فى (ط). 11۰ 00 باب الباء [قوله تعالى]: إبعذاب بئيس) [الأعراف: ]٠٠١‏ على فعيل ولغة لسفلى مُضر: نعيم ویئیس يكسيرؤن الفاء فى فعيل إذا كان الحرف الثانى منه من حروف الحلق الستق وبلختهم کسیر الضئين ورئيس ودهین, وأمًا من کسر کثیر وأشباه ذلك من غير حروف الحلق فانهم نس من أهل ان وأهل الشّحر یکسرون کل فعيل وهو قبيحٌ ال فى الحروف السّتة وفيها أيضًا یکسیرون صَّدْر كل فعل يجىء على بناء عيل نحو قولك: شهد وسعد. ویقرعون: روما شهدنا لا با علمنا# [یوسف: ۰]۸۱ ۱'),
(3342, 'البسة', 'البسه', 'بسه', 'اسم للفقر وهی التى عنی علری بن رَد حين قال: فی غير مسق'),
(3343, 'بأل', 'بال', 'بال', 'البَييلٌ: الصّغيرٌ النحیف الضتعیف مثل: الضّكيل. وقد بول يبول بآلة. والبألة: القارورة بلغة بلحارث وهی بالنبطية بالتاء. بای (بأو): البأوٌ: من الهو والافتخار والکیر .. بأی يََأَى فلا على أصحابه بارا شدیدّا قال: ار مه إذا ازدهاهم یرم محا وا بارا ومدتهم رحال شم'),
(3344, 'أكمخواء أى', 'اكمخواء اي', NULL, 'رفعوا رءوسّهم من الكبر.'),
(3345, 'بیب', 'بیب', 'بیب', 'ببة: لقب رَجُلٍ من قريش كان كثر الم ويوصف به الأحمق التقيل. ويقال: هم بان واحد أى: سواء. وان على تقدير فعلان ويقال: على تقدير فعال والنون [على هذا] أصليّة ولا يُصرّف منه فِعْلء وهو والبأج ععنی واحد .. وقال عمر بن'),
(3346, 'خطاب', 'خطاب', NULL, 'لولا أن يكون الناس ببّانا واحدًا لفعلت کذا و کذا.'),
(3347, 'بقت', 'بقت', 'بقت', 'البَتْ من الطيالسة يُسَمّى الساج مُرَبع غليظ لونه أحضّر و والجميع توت'),
(3348, 'البت', 'البت', 'بت', 'القطع المستَاصلُ؛ يقال: بعت الل یت أى قطعته. وتقول: أعطيته هذه القعريعة بت بل والبَتَةٌ اشتقاقها من القطع ؛ غير أنه مستعمل فى کل آمر لا رجعة فيه ولا التواء. وت فلانٌ طلاق فلانة ای طلقها طلاقًا بانًا. والحاوز منه الإبتات فى کل شىء من هذا . ورجل أحمق بات: شديد الحمق. وانقطع فلانٌ عن فلان فان وانقّیض. [وانت حبلّه عنه أى انقطع وصاله وانقبَض وأنشد: ۱ فل فى حم وات قبط ْله من ذوى العِرٌ الغطاريف )١(‏ العجاج دیوانه (ص )451١145٠0‏ برواية: جبال شمخ.'),
(3349, 'البتك', 'البتك', 'بتك', 'قطمٌ الأذن من أصلها. قال الله تعَالى: فتك آذان الأنعام [النساء: ۹'),
(3350, 'بقل', 'بقل', 'بقل', 'البعل: كلمة توصل بالست, تقول: اعطیته با بان وأصله القطي وبتلته: قمه. )١(‏ ما بين القوسين من التهذيب من أصل العين والحديث فى غريب الحديثشى لأبى عبید 2454/1١‏ النهاية .)٩۲/۱(‏ (۲) ضعيف انظر ضعيف الجامع (ح ۲۰۲۰). (۲) الدسيع: مضیق مولج الری فى سم نغرة النحر وهو بحرى الطعام فى الحلق والدسيع من'),
(3351, 'انسان', 'انسان', NULL, 'العظم الذی فيه الترّقوتان وهو مركب العنق فى الكاهل وقیل الدسیع: الصدر والکاهل. اللسان (دسع). )٤(‏ دیوانه: (ص ۱۷۸). والرواية فیه: وقصيًا فعمّا ورسفا أبتعا. ۱۹ 5 باب الباء وتبتل إليه تبتيلاء فالتبتل الانقطاع إلى الله تعالى أى حلص إليه ليه إخعلاصًا. والتتول: کل امرأةٍ تتقبض عن الرحال فلا حاجة لها فيهم ولا هوق ومنه ال وهو تر النكاح [قال ربيعة بن مقروم الصبى: لو أنها عَرَضّت لأَشْمّط راهب عبد الإلة صرورة ی ونَحْلٌ مُتبكّل: قد تلت عُذُوقه. والبتیل: فسيل النخل بل عنه أى يُقَطعٌ عنه ویشوّل.'),
(3352, 'البتيلة', 'البتيله', NULL, 'کل عضو بلحمه مکتیز من أعضاء اللّحْم على جياله قال: إذا امون مدت البتائلا وامرأة بل تامة الأعضاء والخَلّق وحمل مت وناقة مبتلة. والبشل: أسفل الحبّلء الواحد بتیل. [والبقل: تمييز الشىء من الشىء].'),
(3353, 'يقم', 'يقم', 'يقم', 'البته"2: بلا بناحية فرغانت ويقال: جصن.'),
(3354, 'يشث', 'يشث', 'يشث', 'بت الشیء: تفریقه. وت الشیء واخبرَ: نضرته وابتشه أيضًا. يقال: بث الیل فى الغارة 38 الکلاب کلابه على الصيّد.'),
(3355, 'يقر', 'يقر', 'يقر', 'البثر: حراج صيغارٌ الواحد بر وقد بثر جلده يبر بر وبشورا. وصار الغديرٌ راد ذعب ماؤه وی شىءٌ قلیل ثمّ نش" على وه الأرض منه ثيه عرمض.'),
(3356, 'يشن', 'يشن', 'يشن', 'البغة: اسم رملة ينق ويصغر بُنيَة وبها سمَیتٍ المرأة تينة للينها. والبغيَة: بلا بالشام.'),
(3357, 'بحج', 'بحج', 'بحج', 'البج: اطع قال رؤبة: نقعا على الهام وجا وض'),
(3358, 'البجحة', 'البجحه', NULL, 'شىء يفعله الانسان عند مُناغاة الصّبئ. قال زائدة: والبَحبّحَة صرت البطن. وبح اجرح يجه بجا أى شقه ويقال: انیت ما شيتك من الكل اذا فتقها ال فأوسع خاصرتيّهاء قال: 0.00 ب ها عسالیجه والثامر اماو'),
(3359, 'لجع', 'لجع', 'لجع', 'فلاث یج بفلان یمجح به: أى یهٌدی به إعجابًاء وكذلك إذا تمرح © به . وَبَحّحنى فبحت ٩‏ : أى فرَّحَى ففرخت. وبححت وبَجَحْت لغتان قال: ولكنا بقرباك حح'),
(3360, 'بحر', 'بحر', 'بحر', 'البجرة: ال الناتغة وصاحبها بن وقد بجر بَجَرا وج . وقد تسمی سره البعير رة عَظمت أم لم تخطم. والنجر: الامر العطیم. [ویقال]: حثت بأمر بخر و داهية نکر وقال( (۱) الرجز فى التهذیب و اللسان والدیوان ص .۸١‏ (۲) البیت فى رالتهذيب سیَهاء الأسلمى وهو كذلك فى راللسان يصف عنرًا بسن القبول وسرعة السمن على أدنى الرتع وقلة الا کل (قسر ظنب). وصدره: (بساءغت كان القَسْوّر اجون بحّها). (۳) (ط): كذا فى التهذيب وراللسان وفى الأصول المخطوطة: تمدّح. ۸) وفيه: ووبجّحنى فبجحت إلى نفسى..). (ه) بلا نسبة فى اللسان (زوج). ۱۱ باب الباء )0( 2 عن or‏ بر عَحبّت من امرأةٍ خصان رآیتها لها ولد من زوجهاوهی عاقر'),
(3361, 'فقلت لها', 'فقلت لها', NULL, 'برا فقالت یی أَنَعْحَبْ من هذا ول روج آخحم؟'),
(3362, 'یعنی', 'یعنی', NULL, 'رجا من الحمام. والبجری والبحاری جَمْعُهما من دواهی الدَهْرٍ.'),
(3363, 'لا یقال', 'لا یقال', 'لا', 'امرأة بحالق ورجلٌ باحل وقد بحل يَبْجْلُ بجولاه وهو الحسّن املسم (اخصیب فى حسمه)) وقال: الّقَدُ دی والطعانُ عاحل وأنت بالباب سّمينٌ باج'),
(3364, 'البحخت', 'البحخت', NULL, 'الشىء الخالص معهما.'),
(3365, 'بحع', 'بحع', 'بحع', 'عرد بح إذا كان فى صوته علظ. والبَحَحْ مصدر لاح والح إذا كان من داء , فهو البحاح. والتبحبح: التمكن فى الول والقام والمرأة إذا ضَرَبّها الطلق قال'),
(3366, 'أعرابي”', 'اعرابي”', NULL, 'تركتها تبحم على أيدى القوابل. وقال فى البَحَح أى مصدر الأبَحّ: ولقد بجخت من لدا علجيْهكمهل من مبارز وَالبُحْبُوحَةٌ: وسط مَحلة القوم قال حرير: =بالرای وقد م فى باب الراء والجيم ولم أسمعه باللام لغير الليث وأرحو أن تكون اللام )۱( البيتان فی التهذيب وواللسان) والرواية فى اللساتن) : امرأ القیس es‏ والرواية فیه: إليه موارد مهل الخصاصض ومن عننده الصدر البحل (۲) (ط): الشطر فى التهذیب وراللسان غير منسوب ولم يرد فى الأصول المحطوطة ۱۹۹ باب الباء ینفون تغلب عن بحبوحة الدار !'),
(3367, 'يجر', 'يجر', 'يجر', 'البَحر س سمی به لاستبحاره وهو ایساطه وسَعته. وتقول: استح فى العلم. وتبَخر ر الراعى: وقع فى رعی کثیر " قال أميّة انع بضأنك فى بقل تبحسره من فیح ای بر فى المال. وإذا كان ابر صغيرًا قبل له: بُحَيْرة وأما البُحَيْرَة فى طبر فإنها بَحْرٌ عظیم(" أ وهو حو من عر أميال فى ستو ال يقال: هى علامة لخروج الدَّال تس حتى لا یقی فيها قطرة ماو" ''. والبجيرة: : كانت الناقة ۷ تبحر بَحْرَاء وهو شو ی أذنهاء یل بها ذلك إذا یکت عشرة أبن فلا ترکب ولا ی بظهرهاء فته احم اللهُ عن ذلك قال الله تعالى: ما جَعَلَ الله من بَحِيرةٍ ولا سائبةٍ ولا وصيلةٍ ولا حام# [المائدة ۲۳. والسائبة التى تسیب فلا نع بظهرها ولا لبها والوّصيلة فى الغنم إذا وَضَعَْت أنقى ت رکتا وان وَضَعَتْ ذکر! أكله الرحال دون النساء وَإِنْ ماتت الأنشى الموضوعة اشتركوا فى أكلهاء ون وُلِدَ مع اليتة ذَكَرٌ حى انصَلّتْ وكانت للرحال دون النساءء ویسَمُونها الوّصيلة. وبنات بجر (): ضرب من السحاب. والباجر: الأَحمَقُ الذى |ذا کلم بجر وبقى کالَبْهُوت. ورجل بحرانی: منسوب إلى البحرین؛ وهو موضع بين البصرة وعمان یقال: (۱) وصدر البيت كما فى التهذيب و اللسان والديوان: قومى تیم هم القوم الذين هم (۲) (ط): سقطت العبارة وتبحر الراعی فى رعى كثير من التهذيب مما نسب إلى الليث. (۲) (ط): وردت معرّفة الطبرية فى (ط) ورالتهذیب (۳۸/۰) ولم ترد فى كتب البلدان معرفق ولا فى سائر العجمات. (ه) جاء هذا العنی فى صحیح مسلم فى کتاب الفتن فى حدیث ابحساسة الشهور وفیه أن الدحال سأل تميمًا ومن معه فقال: آحبرونی عن بحيرة الطبرية... هل فیها ماء؟ قالوا: هى كثيرة'),
(3368, 'ماء. قال', 'ماء. قال', 'ما.', 'أما إن ماءها يوشك أن پذهب.... (ح ۲۹۲). )١(‏ (ط): عقب الأزهرى فى التهذيب (۰/۰ ۰ فقال: وهذا تصحیف منکر والصواب بنات بخر. وجاء فى اللسان (بخر): ووبنات خر ور سحاب يأتين قبل الصّيف منتصبة رقاق بیض حسان؛ وقد ورد بالحاء المهملة أيضًا فقیل: بناتٌ بحر. وفى التاج (بحر): وبنات بحره بالجاء والخاء جمیعا, أما الصحاح ففيه ما فى العين.'),
(3369, 'بحظل', 'بحظل', NULL, 'بخن لجز تل بح إذا قفز قفزان البربوع'),
(3370, 'رجل بخټیر', 'رجل بخټیر', 'رجل', ': حسن الشية الجسم وامرأة بختيرة.'),
(3371, 'يضخ', 'يضخ', 'يضخ', 'تبخبخ الخر: سکن بعض قورت وبحت الم سكنت حيث کانت وتبحبخ مه إذا صّوت من الوُزال ٠‏'),
(3372, 'درهم بخی', 'درهم بخی', NULL, 'کتب عليه بخ ودره مَعْمِع: کتب عليه معْمضاعفًا؛ لأنه منقوص وإنما يضاعف إذا كان فى حال رده ما لأنه لا يتمكن فى التصریف فى حال تخفيفه فیختمل طول التضاعف ومن ذلك ما يقل فیکتفی بتتقیله وإِنما حُيل ذلك على ما یری على الهج فوحدوا بخ مفلا فى عمل الكلام ووجدوا مه وجرس الخاء أمتن من چرس العين فكرهوا تثقيل العينء, فافهم ذلك. وبخباخ الجَمَل رل دیره. وبخبّخة البعير وبخجاحه: هديرٌ یلا القم شقشقته شقشقته 8 قال 7: بخ وبحباخ الهدیر لزغد و اه وا (ه) ‏ 0( (۱) (ط): وحاء فى التهذیب: ويقولون هذه البحرین وانتهینا إلى البحرین فيما نسب إلى اللیت. (۲) زيادة من التهذیب (۰)۳۱۲/۷ عن العین. (۲) من التهذیب (۱4/۷) فى روایته عن العين واللسان (بخ). )٤(‏ نسبة فى التهذيب )١15/0‏ إلى روبق ولیس فى ديوانه. وورد فى اللسان (جخبخ) غير منسوب. ونسب فيه (زغد) إلى أبى نخيلة وروايته هنا: قلخا وبخباخ. لذ من لمکم 00101 لتقويم العبارة وتوضيح المعنى. ۱۱۸ باب الباء إذا الأعادى حسبونا بَخبخحوا'),
(3373, 'أى قالوا', 'اي قالوا', 'اي', 'بخ بخ. كما قال الشاعر"" فى عبد الرهن بن الأشعث: بين لح وبين قيس باذخ بخبخ لوالده وللمولود فأَحَدَهُ جاح وقَبَلَهُ. وقال: والله لا تبخبخ بعد هذا أبدا.'),
(3374, 'بخدن', 'بخدن', NULL, 'بدن من أسماء النساء.'),
(3375, 'بخص اليد', 'بخص اليد', 'بخص', 'لحم أصول الأصابع ما لى الرّاحة. [والبْحَصُ فى العين]: لحم عند المفن الأسفل. کاللحص عند الحفن الأَعْلى. والبخص: لحم الذراع أيضاء وبالسّين لغة. 9 مر مام و حَمَْتَ يزارا انأ وض شتی فأ ر كما جَمَعَتْ کف إِلَيْها لبا آلا دی نا الباخع الرجد تسه (۱) فى اللسان (بخخ): آعشی همدان. (۲) اللسان (بخس). وفیه شعوبها بدل فأصبحت.'),
(3376, 'يخنق', 'يخنق', NULL, 'البحنق: برقع یغشی العنق والصدر. والبرنس الصغیر یسمی بخنقا. قال ذو عله الم و ا و (Ta,‏ يه من الظلماء حل وبخنق وبحنق اطراد: جلبابه على أصل عنقه وحمعه بخانق.'),
(3377, 'بدا پدو', 'بدا پدو', 'بدا', 'بدا الشیء يَبْدُو بَدْوَا ودرا أى ظهر. وبدانی فلان بکذا. وبّدا له فى هذا الامر بداء وبدوا. والبادية: اس للأرض التی لا حَضَرَ فيها أى لا مَحلة فیها دائمة فإذا حرجوا من احضر إلى الراعی والصحاری قیل: بدوا بذوا. ویقال: أهل البذو وأهل الحضر. والبدء مهمون وبداً الشیء یبدا أى یِفعله قبل غيره واللة بدا اخلق وأبْداً واحد. والبّدیء: الشیء الخلوق؛ وربّما استعملوه فى أمر عجیب. قالوا: أَمْرٌ بدیء أى ولام عجيب. والبّداء يكنى عنه الفعل أبدّى يُبدى. والبَّدْمُ من الرجال: السيّد الذى يُعَدُ فى أول من يعد فى سادات قومه. وأعطيته بدع! من لحم وجمعه آبدای يقال: نخخضة أى قطعة ويقال: عضو تام قال طرفة: ۱ مهم ابر لقمان إذا آغلت الشتوة بدا اد وقال أبو عمرو: الأبداء: المفاصل والواحد بای مقصور ویقال: بدی و جمعه بدوء مثال بدوع. ورجلٌ مبدوء أى مَجْدور أصابّه الحدرئ. وتقول: قعل ذلك عَوْدًا وبدءل (۱) روبة دیوانه (۱۰۷)- (۲) (ط): تکملة من ختصر العین ورقة (۱۰ . (؟) عجز بيت للشاعر فى اللسان (بخنق). ۱۳۰ باب الباء أو فى عَوْدِه وبّذئه أو فى عودته وبذأته. وب بدیء: ليست بعاديّة ابترشت فحفرّت دیا حديثًا.'),
(3378, 'بدډ', 'بدډ', 'بدډ', 'المد بيست فيه أصنام وتصاوير وهو إعراب بت بالفارسية [ وأنشد: لقد عَلِمَتْ تکاکرة ابن تیری غداة ال آنی هبرزئ]"'),
(3379, 'يدر', 'يدر', 'يدر', 'البذر القمّر ليلة البَذْر وهی ريع عشرة؛ وسمی بذلك لأنه يباور بالطلوع عند غروب الشمس [لأنهما يتراقبان فى الأفق صّبحًا]. [والبلذرة: كِيسٌ فيه عشرة آلاف درم أو آلف والجميع: دور وثلاث بذرات]. ويقال لسك السّخلة ما دام يرضّع: مَك فإذا فطع فسشنکه البَدْرة. والبادرة: ما در من حدق الرحل عند الفضّب. یقال: (۱) كذا فى التهذيب PT‏ (۲) المحكم (40/ وفيه: ذيلا أبنخا (۲) البيت فى المحكم ۱۲/۱۰ كرواية العين وبلا نسبة فى اللسان (بدد) و(تكر) والتهذيب (۱۳۳/۱۰) تکاترق وقال: التكرى: القائد من قواد السند والجمع تكاترة. )٤(‏ (ط) أصلحنا هذه العبارة ما ورد فى المعجمات وأما فى الأصول المخطوطة فقد جاء: التبدد التفرق وذهب القوم بداد وحاعت الیل بداد بداد وفى الأمر تفرقوا وتفرقوا (كذا).'),
(3380, 'البذغ', 'البذغ', 'بذغ', 'الشیء الذی يكون أولاً فى كل أمر كما قال الله عرّ وحل: قل ما کشت بذعا من الرَسُل [الأحقاف: ۰۲٩‏ أى: لست بأول مُرْسّل. وقال الشاعر: فلست يدع من النائبات ونقض الخطوب وامرارها'),
(3381, 'الباعة', 'الباعه', NULL, 'اسم ما ابتدع من الدين وغيره. ونقول: لقد حئت بأمر بدییع أى: : مبتداع عجيب. وابتدعت: جشت بأمر مختلف لم يعرف ذلك قال: إن نب اوومطيكقا خلت اخلابدیصا'),
(3382, 'وق', 'وق', 'وق', 'بدیع السموات والأرض [البقرة: ۰۱۱۷ بالنصب على جهة التعجب لما قال الشر كون بدعا ما قلتم وبديعًا ما اخترقتي أى: عجيباء فنصبه على التعجب. (۱) الشطر فى اللسان (بدر) غير منسوب. (۲) صدر بيت ثانی اثنين فى اللسان لخراشة بن عمرو العبسی والعجز: زورا وزلت ید الرامی عن الفوق. وفی الحکم (۲۹/۱۰) رواية البیت كاملا والعجز: زورا وحرّت ید الرامی عن الفوق. (۲) قرأ المنصور: بديعٌ بالنصب على الدح. کذا فى البحر المحيط ۳۶/۱. ۱ باب الباء والله أعلم بالصّواب. ویقال: هو اسم من آسماء الله وهو البدیع لا أحد قبله. وقراءة العامّة الرّفع وهو أولى بالصواب. والبدعة: ما استحدئت بعد رسول الله صلی الله عليه وال من أهواء وأعمال ویجمع علی البد ع. قال الشاعر: ما زال طعن العادی والوشاة بنا والطعن أمر من الواشين لا بدع وآندع البعیر فهو مد زر من داء و نحوه؛ ویقال هو . داء بعينه وَأَبْدِعَت إلا لابل إذا ت ركت فى الطریق من الهّزال. وأَبْوِعَ بالرّجل إذا سیر عليه ظَهْرُهُ.'),
(3383, 'يدع', 'يدع', 'يدع', 'البدغ: التَرّحّفُ بالات على الأرض. قال : لولا دبوقاء استه لم يدغ'),
(3384, 'ندن', 'ندن', 'ندن', 'البَدَنُ من اجسّد ما سوى الشّْوّى والرأس. والبَدَن: : شبه ورع | إلا أنه قصير قَدر ما يكون على تسد قصيرٌ لک ويجمّع على أبدان وقال الله حل وعرً: طفالیوم ننجيك ببدنك 46 [یونس: .]٩۲‏ وَبَدُن الرجل: صار بدینا فهو مُبدِنَ ورحل باون من وامرأة من أى: سمینان جسیمان. وبَّدَن تبدینا أى اسر والبانة: ناقة أو بَقَرَةٌ الذکر والأنثى فيه سوای یهدی إلى مکة والحميع البدد. (۱) ذکر النووی رحمه الله فى الأذكار (ص 4 ۱۷) أنه لا يصح الاقتصار على الصلاة على النبی کر دون السلام ولا السلام دون الصلاة. (۲) فى الحکم (۲۷۸/۰) لرؤبة وفيه الشطر الأول: واللغ یلکی بالک لام انلس وهو فى دیوانه رص . (۳) جاء فى هذا المعنى عدة أحاديث لكن كلها ضعيفة انظر ضعيف الجامع (ح 255568 0۹۹'),
(3385, 'بذأ. بذی', 'بذا. بذی', NULL, 'بلری الرجل إذا ازدرئ به. ورجل بذ إذا نطق به وامرأة بَذمّة: بينة البذاءة وقد بذی قال : َذر البَذِيئةٍ یلها لم نَهْجَع 0'),
(3386, 'لطاج', 'لطاج', NULL, 'ج: ا لحمل ونح على البذجان وهو أَضعف ما یکون قال: 7 وان 7 تج تاکن عَتَودًا أو بذج'),
(3387, 'بذح', 'بذح', 'بذح', 'لیذ خ: التطاول والافتخار بخ یذ خ دحا وبذوخا. ورجل باذخ وبذاخ قال: گر سره ام بذاخ نمّسی البح ۱'),
(3388, 'جیل باذخ', 'جیل باذخ', 'جیل', 'طويل وجمعه بواذخ وباذحات وقد بخ يُدُوعًا. وأنا آبذخ منه آی آفحر وأعز.'),
(3389, 'بدد', 'بدد', 'بدد', 'تقول العربئ بدي ذا إذا مرج شىء على الآخحر فى من أو عمل کائنا ما كان. والبذاذة: سوء هی ورحل باذ الهّيئة ولقد بَذِذْت وابله یره'),
(3390, 'يذع', 'يذع', 'يذع', 'البَدَعٌ: شبه القرّع. والبذوع کالفزوع. قال الأعرابى: بُذِعُوا فِابْدَعَرُوا. أى فرعوا فتفرقوا.'),
(3391, 'يذم', 'يذم', 'يذم', 'اذم مصدر البذيم وهو العاقل الغضب من الرحال يَعْلَمِ ما يُعْضَّب له وبْذم ذامق قال: کریسم عُروق التبعتين مُطْهِّرٌ ویفضب ما فيه والبذم یَضب()'),
(3392, 'بذعة', 'بذعه', NULL, 'اسم رحل.'),
(3393, 'يرأ', 'يرا', 'يرا', 'ابر مهموز: الخلق. برأ الله الخلق رهم ره فهو بارىء. والیر: السّلامة من السّقم تقول: با یر دب برعا وبروءا .. وبرئ يَبْرَأ.معناه. والبراءة من الب والکروه ولا يقال الا: بری یر وفاعله: بریء ء كما تری وبرا وامرأة براي ونسوة رای فى کل ذلك سواء. وبرَآء على قياس فعلاء: جمع البریء ومن ترك الهمز قال: براء. ویقال: بارأت الرَخُلء أى: بری إلى وبرئت إليه مثل بارأت المرأة أى: صالحتها على الفارقة. وتقول: أبرأت الجا من لین والطنمانه وبراتة.'),
(3394, 'الاستبراء', 'الاستبراء', NULL, 'أن بر یشتری رح الحارية فلا يَطَؤْها حتى تحيض. والاستبراء: نقاء الذکر بعد البول. برل, برأل”": ارو والجمع: البرائيل: ريش سبط لا عرض له على عن الدّيك (۱) البيت بلا نسبة فى اللسان 60 فى ختصر الین وص ۳ تقلا عن وط).'),
(3395, 'بریج', 'بریج', NULL, 'البربحة: الاب'),
(3396, 'بريص', 'بريص', NULL, 'ویقال: بَرْبَصْت الأرض إذا أرسلت فیها الاء فمخرتها النجُود.'),
(3397, 'بربط', 'بربط', NULL, 'البرئط: معرب وهو من ملاهى العجم. [والبربطیاء: موضعٌ يسبب إليه الوشئ].'),
(3398, 'برت', 'برت', 'برت', 'البرّت: الفأس بلغة اليمن والبرت بلغتهم السكر الطبررد. وقال مُراجم: رت والبرّيت فى شعر رؤبة اسم اشتق من البرّية فى قوله: يش عنى ارق والبریت فكأنما سکن الیاء فصارت الهاء تاء فلت وحعله اسم ری وهو الصحرای والجمع البراريت فصارت التاء كأنها أصلية فى التصاریف كما لزمّت التاء فى عفریت.'),
(3399, 'البرت', 'البرت', 'برت', 'الدلیل الهادی ولم أسمّع له جمعا. ۱'),
(3400, 'برثن', 'برثن', NULL, 'البَرائْنُ وواحدها: البرر: محالب الأَسّد. قالوا: كأن براه الأشافى.'),
(3401, 'الميطن', 'الميطن', NULL, 'یوت نی على السورء وتسَمّی الوت نی على أركان القَصْر بُرًْا. وكوب برج صوّرت فيه تُصاويرٌ کبروج السُون قال العجّاج: فقد شا وشیه الى'),
(3402, 'البرج', 'البرج', 'برج', 'سّعَة تیاض العين مع خسن الحدقة. وإذا بت المرأةٌ مخاسن جيدها م27 ماس مر'),
(3403, 'وجهها قیل', 'وجهها قیل', NULL, 'قد تبرحت ومع ذلك تری من عينيها حسن نظر. وحساب البرجان (۱) ما روی فى التهذیب (۵۹/۱ عن العین. (۲) دیوانه ص ۲۵ وفیه: ینشق عنی ار والبریت. (۳) فى (ط): صوّر تغيه وهو تصحيف بين. انظر اللسان (برج). (۵) فى (ط): وإذ. انظر الصدر السابق. ۱۳۹ باب الباء (وهو قولك)(: ما جُداء کذا فى كذاء وما حدر كذا وكذاء فجداژه: مه وحذره أصله الذى رب بعضه فى بعض وجنلته البرْحانُ. يُقال: ما جَدَرُ مائة؟ فيقال: عشرة. ويُقال: ما جُداء عشرةٍ فى عشرة؟ فیقال: مائة. والبارجةٌ: ستفينة من سفن اضر تتحذ للقتال.'),
(3404, 'يرجد', 'يرجد', NULL, 'الرجٌد: كساءٌ مخطط للأعراب قال طرفة: مون كألواح الإران تس أتها على لاحب كأنه ظَهْرُ برد'),
(3405, 'پرجس', 'پرجس', NULL, 'البرجیس: من آسماء النجوم. والثوق والشّاء الغزيرة الكرعة.'),
(3406, 'پرجم', 'پرجم', NULL, 'البرْجمة للمفصل وهو الظاهر فى الأصابع كالعُقد. وَالأَصِبَعُ الؤسْطى من كل طائر هى البَرْجمة. والبراجم: أحياءٌ من تميم. والنسبة: برجی. الزجان: اللؤلؤ امار'),
(3407, 'أرض براح', 'ارض براح', 'ارض', 'لا بناغ فيها ولا عُمْران. والبرحاء: الحمّى الشّديدة. وتقول: برح بنا فلا تبريمًا إذا آذاك بالحاح المشقةء قال ذو الرّمّة: e‏ و بدوره) والهوی برح على من یخالبه'),
(3408, 'التباریح', 'التباریح', NULL, 'کلف العيشة فى مَشَتَة والاسم ار وتقول: رب ضرا مرح ولا (۱) (ط): زيادة من التهذیب). (۲) (ط): زيادة للتوضیح. (۳) عجز بيت فى اللسان (بر ح) والرواية فیه: أقول لها حين جد لرحیت. سل أبرحت ربا وابرَخت جرا (ه) عجز بيت فى اللسان (برح) والحکم (۲4۳/۳) (ط): وقد ورد فى الأصول الخطوطة من'),
(3409, 'سهو الناسخ', 'سهو الناسخ', 'سهو', 'على من يطالبه.'),
(3410, 'البراح', 'البراح', NULL, 'البيان تقول: جاء الک براحاء وعلى هذا العنی جوز بر فا أى ظَهّر ما كنت أخفى. والبرو ح: مصدر البارح وهو حلاف السّانح من الظباء والطیر وما یتیمن به أو یتشاعم بى قال: فهر رن ب هبرُوحا وتارة ياتينه سنورحا ۹ والبارح من الریاح: ما تحيل لتراب فى شدَة الهبوب قال: وم مر بارخ ترب'),
(3411, 'يرخ', 'يرخ', 'يرخ', 'البزْخ: ضَرّب بالسَیّف يقطع , بعض اللخم. والبَرخ : الرحیص بلغة عُمان. وخ ارب وأهل عمان يقولون: كيف آمنعارکم؟ فيقول المجيب: بر هكذاء أى رحیص. وقول رژبة: ولو اقول برحوا لسبرخوا لار سرجیس وقد تددح )٩(‏ وه رخا ی رک تما مد [وأما قول الله - حل وعرّ -: وییوّل من السّماء من جبال فیها من برد فيصيب به من يشاء [النور: ]٤١‏ ففيه قولان: آحدهما: ويُنزل من السماء من آمشال حبال فيها من برد والثانى: ویترل من السماء من جبال فيها بر . ودمن) صلة]. والأَبْردان: العَداةٌ ولعشیی؛ وبرد یبرد پرودة, رت ابر بالماء: صبَينه عليه فل واسم ذلك الخبز لول البريد وَاْبْرودٌ تطعمه النساءٌ للست وتقول اسقنى شرب د بها كبدى. وبرد (۱) ما بين القوسين من العبارة وبيت ذى الرمة من التهذيب ما نسب إلى الليث (/۰)۲۹ وهو فى الحکم (۲:۳/۳). (۲) الرحز فى اللسان (برح) غير منسوب وفی الحکم (/44 ؟) غير منسوب کذلك. (۳) من التهذیب (۲۸/۵) عن العين. ۱۳۸ 5 باب الباء مه الق وأَبْرَّدوا: صاروا فى وقت لق آخر التهار. برد الاء تبريدًا. وَبَرَدَ عليه حَق كذا وكذا دِرْهَمًا أى لَرمّه ذلك. والیروذ: كخل برد به العين من ار وفى الحديث: آبردوا بالظهر فان شه اه من فیح جهنم . ويقال: جتناك مبردین إذا جاءوا وقد باخ الحر.'),
(3412, 'الیرادة', 'الیراده', NULL, 'الكَوَارَة”"©. والبريد: ستة أميال یم بها مرُسخان. والبرية: الرسول الْمَبْرّدِ على واب البريدء [وإبراده إرسالّه] وقال الراجز: رأَيتُ للموت رَسُولاً مُبرّدا وروی عن النبى - صلى الله عليه وسلم - أنه قال: إذا بردتم إل بَرِيدًا فاجعلوه حَسَّنَّ الوه حَسَنَ الاملب] 7 ''. توقال بعض العرب: الى بريد الموت أراد أنها رسول الموت تنذر به. وسِكَكُ البرید كل سک 3 منها اثنا عشر ميلاً والستّفر الذى يجوز فيه قَصْرٌ الصلاة أربعة برد وهی ثمانية وأربعون میلا بالأميال الهاشمية التى فى طريق مَكة. وقيل لدابّة البريد: بريد لِسَيْرِ فى البريد وقال الشاعر: إنى ان ص لیس حتى کاننی عليها بأحواز الفلاة بریذ]'),
(3413, 'البرد', 'البرد', 'برد', 'سَحْككَ الحديد بالیرد أى السٌوهان (بالفارسية). والبُّرْدُ: توب من برود لعَصلب والوّشی. والبُرْدد: کساء [مرَّع أَمْوَدُ فيه صفرٌ ونحو ذلك] تلتجفٌ به العرب.'),
(3414, 'قوه تعالى', 'قوه تعالي', 'قوه', 'إلا يذوقون فيها برد ولا شرابا) [النبأ: 4 7] يقال: نَوْمًا. وبَرَدى: نهر مشق قال حسان: ا ع 9 ف يسقون من ورد البريص عليهم بردی صفق بالرحيق يق السلْسَلٍ )١(‏ أخرجه البحاری فى المواقيت (ح )٥۳۸‏ وفى غير موضع من صحيحه واللفظ له ومسلم (ح 1۱). )١(‏ رط): كذا فى الأصول المحطوطةء وأما فى التهذيب واللسان من أصل العين فهى الکوارة وقد علق الأزهرى فقال: ولا أدرى أهى من كلام العرب أو من كلام المولدين؟'),
(3415, 'نقول', 'نقول', NULL, 'لم بحد الكوارة بهذا المعنى فى العحمات ولعلها الکوازة بالزای كمنا وردت فى الأصول الحطوطة على أنها لغة سائرة قائمة على الکوز! (۲) آورده الهيثمى فى الجمع (4۷/۸) وقال: رواه البزار والطبرانی فى الأوسط وفی إسناد الطبرانی عمر بن راشد وثقه العجلی وضعفه جمهور الأئمة وبقية رحاله ثقات وطرق البزار ضعیفة) . (ه) البيت فى الحکم (44/۱۰) كرواية العين واللسان برص ومعجم البلدان البريص.'),
(3416, 'بردج', 'بردج', NULL, 'البرد ج: السبی؛ دخيل.'),
(3417, 'پرفع', 'پرفع', NULL, 'برع ۱: الیلس الذى يُلْقَى تحت الرّخْل وهو القرطاط.'),
(3418, 'برذن', 'برذن', NULL, 'لته سره البرذون والفرس والفرس يَبَرْذِنُ فى مَشیه أى _عشی مَشى البرذون.'),
(3419, 'برر', 'برر', 'برر', 'البر: حلاف لحر ونقیض الک تقول: حرَشت برا وحلنت براه على النكرة تستعمله العرب. والبَرْيَّةٌ: الصّحراء. والبّرُ: لباز بذوى قرابته . . قوم يَرَرة وأبرار. وتقول: ليس بير وهو بار غدًا. والمصدر والاسم: الب مستويان. وبرت یمین'),
(3420, 'البرير', 'البرير', NULL, 'حمل الأراك. وقد 75 عليهم: أى: غلبهم. وابتر فلا أى: انتصب منفردا من أصحابه. والبزبرة: كر الكلام والحلبة باللسان قال: (....) کل غدور بربار'),
(3421, 'بربر', 'بربر', NULL, 'جيلٌ من الناس سَبّىء الخلقء ویقال إنهم من ولد بر بن قيس بن عیلان. وال الجنطة. والبربور: ابشیش من ار'),
(3422, 'البراژ', 'البراژ', NULL, 'المكان الفضاء من الأرضء البعيدُ الواسع. وتبرّز فلان: : حرج م إلى البزار. وقيل تبرز فى لوط كناية عنه. أى: حرج إلى براز من الأرض. ویر [فلان] يبر بالتخفيف )١(‏ وهى بالدال المهملة أيضًا. (۲) الرحز فى التهذيب ( ۱۹۰/۱ واللسان (برر) غير منسوب. ۱۳۰ باب الباء'),
(3423, 'البراز', 'البراز', NULL, 'المبارزة من الرنین فى الحرب وتبارزا تباررًاء وباررٌ القِرْنَ مُبارَرَة وبرارًا.'),
(3424, 'برزخ', 'برزخ', NULL, ': ررخ: ما ین کل شینین. وليت فى البَرْرَخ؛ لأنه بين انیا والآعجرة. وترازخ الإيمان: ما بين الك والبقين. والبرْرّخ: أمَدُ ما بين الدّنيا والاخجرة بعد فناء الخلق. وما بين ال والشّمس ب برْرّخ. ويقال: الب فسحة ما بين الجن ة والنار.'),
(3425, 'برزع', 'برزع', NULL, 'البرژخ: تشاط الشبابي قال رؤبة: هيهات میعادٌ الشّباب البرزغ'),
(3426, 'برزق', 'برزق', NULL, 'البرزيق: جماعة عیّل دون الب كما قال زیاد: ما هذه البرازيق التى تتردّد'),
(3427, 'الرزق', 'الرزق', 'رزق', 'نبات. ۱'),
(3428, 'پرس', 'پرس', 'پرس', 'البُرْسُ: القطن [وهو قطن البردئ" قال: سّباإفخ من برس وطوط " درس: البرش والبرشة: لون مختلط بنقطة حمراء وأخرّى سَؤداء أو برای أو نحو ذلك. وشاةٌ بَرْشاء: فى وجهها نقط محتلفة ورَجُلٌ أبرش. وسْمّی حَذية الأبرش الذی أصابه حرق فبقى فيه من أثر الخَرْق نقط سود وحم فقيل: جذيعة الأبْرشء وهو ملك من ملوك لیمن.'),
(3429, 'پرشم', 'پرشم', NULL, 'البرشمة: إدامة الظر. والبرُشام: الاسم والُرْشِم: الحادٌ النظرء وبرشم'),
(3430, 'يرص', 'يرص', 'يرص', 'البَرَصُ: داء. وسام أبرص: مضافٌ غير مصروفيء والجمع ۳ آبرص.'),
(3431, 'برطل', 'برطل', NULL, 'البزطيل: حر أو حدية فيه طول ر به خی مه كذلك؛ لس ی يُطَوْله الناس ولا يُحَدَّدونه وقد یشب به َطم التحييق, قال: کان ما فات عینیها و مذب بحها من ` خحطمها ومن ١‏ للحيين برطيل وَالبُرْطلّة: اللطلة الصيفيّة. هه (۲).'),
(3432, 'برطم', 'برطم', NULL, 'البَرْطَمةٌ: وس فى انتفاخ [وغيظ تقول)": بُرطمَه؟ لم و رو ع دوع : 7 ۳ ۲ OD.‏'),
(3433, 'بیغ', 'بیغ', 'بیغ', 'برع يبرع برعاء وهو يتبرع من قبل نفسه بالعطاء إذا لم يطلب عوضا . قالت الخنساء:'),
(3434, 'يرعل. فرعل', 'يرعل. فرعل', NULL, 'البَرْعْلٌ والفرغل: ولد الضبع الواحدة فلت قال: سّواء على المرء الغریب أحاره ‏ أبو حش أم كان لحم الفراعل'),
(3435, 'يرعم', 'يرعم', NULL, 'البرعمة والبراعم: أكمام ثمرَ الشّجر. و۳ عم رم و یه مُبَرْطِمًا. وما اذى (۱) الرجز فى اللسان (برض) لرؤبة وهو فى الدیوان (ص ۸۱). (۲) ما روی فى التهذیب (4 ۰5۷/۱ عن العین. (۲) قال فى الحکم (4/5 :)٠١‏ وبرع فهو بارع: أى تم فى کل فضيلة وجمال وقد توصف به المرأة). ۱۳۲ 0 باب الباء'),
(3436, 'برفت', 'برفت', NULL, ': البُرغوث: و سوداء صغيرة 7 تشب ونان وابحمیع: الب راغیت قال: اقول والقول یی بَعْدَ صاحبه لا بارك الله ربی فى البراغيث كأنهنّ وجلدى إذ لو به مکاتبون آغاروا ذ فى الواریسث'),
(3437, 'برعر', 'برعر', NULL, 'البرغز: ولد البَمَرَهَ والجمع: البراغز. قال: ويضر بس بالأیدی وراء راز چسان الوشوه كالظباء الوق'),
(3438, 'الأبارق ق', 'الابارق ق', NULL, 'الآكام يُخالطها الحصّى والرمال قال: ۱ لنا الصانِع من بُصْرَى إلى هر إلى اليمامة فالأخزاع فَالِرَّق وهَضْب الأبارق: موضعٌ ينه والبُروق: بيضُ السحاب؛ وبرق يبرق بروفا وبريقاء ف ل ال وأبْرق لغة. والبارقةٌ: سّحاب يبرق وكل شىء یا فهو بارق ویبرق بريقا. ويقال للسيّوف بُوارق. واذا اشتدّ مُوعِدٌ بالوعید یا أَبْرَقَ وَأَرْعَدَء قال: ابرق وأعبذيايزيا فما وَعيدُكَ لى بضائ © وبَرَقَ ورَعَدَ لغة قال: فارْعد هنالك ما بدا لك وابرق وارقت الناقة: رت بدنبها مره على فَرْجهاء ومَرَةَ على عجزها. والإنسان البَروق هو الفرق لا یرال قال: ۱ روع لكل وار روق كأنه من قولك: برق بصره فهو برق أى بهن فهو قرع مهو وكذلك يُفِسَرٌ من : طفاذا برق ق ابر [القيامة: ۲۷. ومن قَرا: ربُرّق يقول: تراه لمع من شِدَةٍ )١(‏ هو للکمیت كما فى اللسان (برق) والحکم (44/5 ؟). (۲) هی قراءة ابن كثير وأبو عمرو وابن عامر وعاصم وحزة والکسائی وقرأ نافع وآبان عن'),
(3439, 'عاصم', 'عاصم', NULL, '(برق). السبعة لابن بحاهد (ص .‏'),
(3440, 'برقع', 'برقع', NULL, 'البرقع: لَه الدّوابٌ ونساء الأعراب فيه عرقان میتی قال: قيس وكنت إذا ما رت یقت فقد رابنی منها العَداة سُفورُها'),
(3441, 'البركة', 'البركه', NULL, 'ما ول رص سن جه لطن ريلد من مک سب موم رو و )1 ن £ 0 له أعضادٌ فوق صعيد الأرض قال و آنت التى 5 مت البرك شاتيًا وتاب فانظری آی مورد (۱) فى المحكم (55/ ١‏ قيل البراق فرس جبریل عليه السلام. (۲) (ط) فى الأصول: والبوارك والصواب ما أثبتناه. (۳) تكملة ما روى فى التهذيب (۲۲۸/۱۰) عن العين. (۱۲۱/۱۷). ۱ (۷) البيت فى التهذیب (۰)۲۲۸/۱۰ وفی اللسان (برك) بدون عزو. ۳٤‏ باب الباء'),
(3442, 'يركع', 'يركع', NULL, 'الک القِيامُ على أربع ويقال: تبرت الحمامة للحمامة الذكرء ويقال: أصبح فلان متب ركمّاء ی: لا يقوم إلا على كراسيعه. قال رؤية: مَيْهِاتَ أَعْيا جَدَّنا أن يُصْرَعا ولو أرادُوا غیره ترك'),
(3443, 'برکن', 'برکن', NULL, 'البرتكاث: کساء أسودٌ بلغة أهل العراق.'),
(3444, 'يرم', 'يرم', 'يرم', 'البرّمٌ: الذى لا تیار القوم ولا يدحل معهم فى الَيْسِر وجمعه: أبُرام قال: إذا تب الشذور عُدِدْنَ مالا تحت حلائل الأبرام عرسي'),
(3445, 'البرم', 'البرم', 'برم', 'ثمر الأراك وشبهه من الأشجار. وَبَرمْتْ كذاء أى: ضّجرت منه رما ومنه: رق ع ۳ 3 2 £ 0 90 3 ممه زر و م التبرم وابرمنی فلا إبراما [أى: اضجرنی ]. والإبرام: إحكام الشیء وابرمت الامر: )١(‏ (ط): جاء بعد كلمة (النماء) عبارة رأينا أنها مقحمة فى الأصل وليست منه وهی: قال'),
(3446, 'البر نية', 'البر نيه', 'بر', 'شبه فخارة ضحمة 2 حضراء من القواریر لشحان الواسعة الأفواه.'),
(3447, 'پرنس', 'پرنس', NULL, 'البُرنس: کل ثوب رأسه منه مُلتزق به دُرّاعة كان أو منطرا أو جْبّة.'),
(3448, 'المبرنس', 'المبرنس', NULL, ': مشى الكلب وإذا مشى الانسان على نحو ذلك قيل: تبَرْنسَ قال: ومستتکر لى لم أكنْ بيلاده ففاحأنه من غربة اتنس'),
(3449, 'يرهمن', 'يرهمن', NULL, 'البرهمن بالسمنية : عالمهم وعابدهم. دراء سرو تقول : هذه رة مبر وق أى : معمو لقن وهی: الحلقة. [یقال ]: ناقة مبراة: فی (۱) تكملة من التهذيب (/۲۹۵) عن الع (۲) تكملة من التهذيب (55/5؟) عن العين. ۳ العجاج؛ الحکم ( ۰۳۰۳ واللسان (برهم) وفيه بدلن مكان ومرجن. )٤(‏ السمنیة: قوم من أهل الهند دهریون. اللسان (سمن). ۱۳۹ ۱ باب الباء آنفها برة. [والرَة] کذلك: الَلْقَةٌ من الذَهَب والفضَة ونحوهما إذا كانت دقيقة مَعْطوفة الطرفين ويُجْمّع على: البُرَى والبرین.'),
(3450, 'برى', 'بري', 'بري', 'بیت ود اريه بَرْيّاء وكذلك القلم. ونا يقولون: بَرَوَت وهم الذينَ'),
(3451, 'يقولون', 'يقولون', NULL, 'قلوت الم ألو والیاءأَصَوّب. الباراة: أن يبارى الرّحلٌ الرّحلَ فيطع كما یصنع؛ یغالب أحدهما الآخر زوهما يتباريان]. وبَرّى فلانٌ لفلان إذا عرض له وهو ری له بَرياء وینبری له انبراء .. قال ذو الرّمّة: ۱ ری له صَعْلة حرحاء خاضعة فاق دون بات ایض منتهّب'),
(3452, 'الیری', 'الیری', 'یری', 'لس الذى قد اَم یه ولم رش ولم يُنصّل. لیخ آول ما يقطع. ویقتضب يُسَمّى مَمّى: فطع واحمیع: قطوع نم ری فيْسَمّى : ري وذلك قبل أن قفوم فإذا قوم رم وأنى له أن پراش ويُنصّلَ فهو: القدح فإذا ريش ورکب صله صار سّهُمًا.'),
(3453, 'يزخ', 'يزخ', 'يزخ', 'البْخ: ارف بلغة عُمان. والبرّخ: تقاعس الظّهر عن البطن ورحل أبرّخ وأبرّى. وأمًا البَرَى فكأ العجز حرجت حتی أشرفت على الفخذین والأبزخ ما به ويف وما مى الإنسان یازا كمشية القجوز إذا تکلفستا إقامة لها فتقاعس كاهلها وانحنى بها . وتبازّخت عن کذا أى تقاغشت عنه وبحت ظهره بالعصًا رخا إذا ضَرَبتُ ذلك الموضع. وبزاخةٌ: موضيعٌ [ويوم بزاحة من أيّام العرب معروف].'),
(3454, 'الابتراز', 'الابتراز', NULL, 'جرد من الثياب. وابتژت من ثيابهاء أى: جردت. والبرّة: الشّارة الحسنة من الثياب قال : كنت إذا ره من غیی یشم عطعی وی یی'),
(3455, 'البزابؤ', 'البزابؤ', NULL, 'الشّديدُ من الرحال. (۱) حالد بن زهير الهذل؛ ديوان الهذليين القسم الأول ص .١58‏'),
(3456, 'يزع', 'يزع', 'يزع', 'بَرْعَ الغلام براعة فهو بزیع؛ وجارية بزيعة یوصّف بالظرافة والملاحة (و) ذکاء القلب. لا يقال الا للأحداث. وتَبَرّعَ الشر أى: هاج وأَرْعَدَ ولا يقع. قال(: إنا إذا أمر العدى تبرّعا وأجمعت بالشسر أن تلق وبوزع رملة لبنی سعد. قال : برمل يرنا وبرمل بوزعا'),
(3457, 'بوزغ', 'بوزغ', NULL, 'من أسماء النساء.'),
(3458, 'جزق', 'جزق', 'جزق', 'البرّق: البَضّى وهو البراق والبصاق. وبرقوا الأرض أى بذروهاء وهی يُمانية.'),
(3459, 'فى الاناث', 'في الاناث', 'في', 'برل وبوازل وبل يشتر كان فيه. وبل نابه, ونابه بازل. والبزل: تصفية الشراب ونحوه. وَالِبرَلُ: الذى یصفی به ويكون فى مُوْضِعٍِ من الوعاء شِبّْه طىي فيه حرق فذلك نفس البرّلء وبزل ار وابترلها وتَبَرّلها: ثقب إناءهاء قال: تحدّر من نواطب ذی ابتزال(۲)'),
(3460, 'الناطبة', 'الناطبه', NULL, 'شىء تخد فيه خرو كثيرة صف به.'),
(3461, 'يزم', 'يزم', 'يزم', 'الإبْريم: ما على طرّف النطقة ذو لسان يدحل فى الطرّف الآحر. ولغة فيه: ابزام. والبزیم: حزمة من بقل وكذلك: الوزيم. بزا (بزو): آحذت منه بو كذا وكذاء أى: عل كذا و کذا. والبازی يبرو فى تطاو له وتأنیه. ورجل آبزی أى: فى یره انحناء عند العَجُر فى أصل القن وربا قیل: هو یی بر كالعجوز البّرُواء البَْخاء [التى] إذا مشت [ف]كأتها راکعته وقد (۱) رژبة دیوانه .)٩۱(‏ والرواية فيه: تترعا. (۲) رژبة دیوانه ۰)٩۱(‏ اللسان (بزع). (۳) بلا نسبة فى التهذیب (۲۱۷/۱۳). واللسان (بزل). ۱۳۸ باب الباء ۳ 20 4 ی ۰ 8 7 رر 5 ۱ , بزیت تبزی بزی. والتبازی فى الشی كانه سعة الخطو قال 5 وتبازیت كما يَمْشى الأشق ابیت بفلانه إذا بشت به وقهرته.'),
(3462, 'بسا', 'بسا', 'بسا', 'بسا بهذا الأمر: مرن عليه واستمرٌ فلم یکترث لقبْحهء وما قيل له فيه وكذلك إذا كان عملا أو أمرا وطن نفسّه عليه فاستمر وصبّر قیل: بسا به يَيْسَأ بسا. ویس به رن لاع م وع با بسا وبُسُوءا ویس بسا بسا إذا یس به.'),
(3463, 'البستان', 'البستان', NULL, 'معروف.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(3464, 'البياسرة', 'البياسره', NULL, ': قوم من أهل السند یواحرون أنفسّهم من أهل السّفن لحاربة عدوهم (۱) بلا نسبة فى اللسان (شقق) وتاج العروس (شق) ویروی تباريت بالراء. (ط): فى الأصول: قال رؤبة.. (؟)الحديث فى النهاية )١757/١(‏ (بسر) بلفظ: ولا تنجروا ولا تبسروا وقال: اسر بفتح الباء حاط البسر بالتمر وانتباذهما معا. (۳) صدر بيت له فى اللسان (بسر) وعجزه: وصَّمْعَاءَ حتى آنفتها نصالها 6 (ط): كذا فى الأصول الحطوطة وأما فى رالتهذیب من أصل ما أحذه الازهری من العین'),
(3465, 'فهو', 'فهو', 'فهو', 'يستأجرهم. أهل السفن لمحاربة عدوهم.'),
(3466, 'يسس', 'يسس', 'يسس', 'پس: زجر للجمارء تقول منه: : بس بس . ویست وایسَت وهم يَيُسسُون ویسُون. والیس: اتف للناقة الستکنها بکلام حتی لبها ویسْبس: اسم رحل. وانبَسّت الات إذا تفرقت فى الارض. والبسبس: شر تتحد منها الرحال والبسایس: الکذب الذی ليس له أصا" و کذلك مات والبسباسة: بقلة. [وابس بالناقة إبساسًا: دعاها للحلب وإذا درت على الابساس قیل: ناقة بسوس]. والبسوس: كانت ناقة ترعی فرماها کل ۳ فقتلها؛ ويقال: بل اسّم المرأة التى كانت الناقة لهاء وبذلك السبب هاجت الحروب بين بکر وتغلب حتی تفانوا فیقال: أشأمٌ من البسوس.'),
(3467, 'تتسل', 'تتسل', NULL, 'بَسَلَ ببسل بُسُولا فهو باسل وهو عُبُوسة الشجاعة والعَضّبء وأسَّدّ باسل. واستبْسَلَ رل إذا وطن نفسّه عليه واستيّقن به. وأَبْسَلَ نفسّه للموت: وَطَنَها عليه واستْقنَ به. والانسال سل بعمله إبسالاً أى يخذل ویوکل إليه ویسیل: يُسلم. (۱) وهو زحر للإبل أيضا كما فى اللسان. (۲) (ط): بعد هذا جاء قول للأصمعى فى الأصول المخطوطة وهو: وناقة بسيط وهی التى تخلى لولدها لا تعطف على غيره. ۱:۰ باب الباء'),
(3468, 'البسل', 'البسل', 'بسل', 'الحرم الذی لا تتأول خرمته قال:'),
(3469, 'بيسم', 'بيسم', NULL, 'بَسَم يَنْسِمُ بَْمًا: فتح شفتیه كالمكاشر. ورحل بسّام وامرأة بسّامة وبسم وایتسم وتبسم بمعنى واحد [وفی صفة الب ول أنه كان حل ضحکه سم'),
(3470, 'يسمل', 'يسمل', NULL, 'بَسْمَلَ الرجل. إذا کتب: بسم الله قال: لقد سمل هند غداةً لقيتها فيا حبّذا ذاك الّلال سمل'),
(3471, 'البشرة', 'البشره', NULL, 'أعلى جلد الوه وابسّد من الإنسان وهو ابر إذا جَمَعْمَه وإذا غیت به اللون وله و نع انم سا وت اشتقت مباشرة الأحل الراة إتضاة أبشارهما. ومباشرة الم أن تحخضره ١ه‏ بنفسك. والبَشرٌء جزم الشين: قشرك البْسَرة عن (۱) عجز بيت ثمامه فى اللسان (بسل) لابن همام وروايته: يشت ما زدتم وتلغى زيادتى؟ دمی إن آجلت هذه لکم يَسْلُ زه ما روی عن العین فى التهذیب (۰)۲۳/۱۳ والحديث رواه الترمذی بنحوه ( ۳۹۰) وهو صحیح انظر صحیح الترمذی (۲۸۸۱). (۳) التهذیب (۱5۰/۱۳). باب الباء ۱:۱ بده وقد يقال لجميع الخلُود: بشرته إذا شرت عنه قظرته التى بت فيها لش والقطعة منه بشرة. والبشارة: ما بشت به. والبشرير: ابر بخير أو شر. والبشارة: حو ما يُعْطَى على ذلك والبتْرَى الاسم. والبشارة: الحمال. وامرأة بشيرة قال الأعشى: ورأت بأ الشیب حا نة البشاشَة والبشاره'),
(3472, '| والبشارة', '| والبشاره', '|', '9 وتشرتة شروش واسیّشی ولد ی بش 2 اللطف فى المسالةء والإقبال على أخييك تقول: برشت بسا ويّشاشة. ورجل هش بش. والبثییش: الوحه؛ یقال: رجحل مُطْيىء البشیش. أى: مضىء الوجه. شو ای کي نوف رز شم هش ورجل بشع'),
(3473, 'يشم', 'يشم', 'يشم', 'البشامٌ: من شجر السّواك ترعاه الظباء. والبشم: تحمّة على الدَّسَّى ورا بشم القصيل من كثرة شرب الب حتى يَذْقَى سَلْسًا فك يُقال: ذقی العِجْل إذا كثر سَلْحُةُ. قال الحسن: وأنت تَتَجََاُ من اشع بَشَماء.'),
(3474, 'بصص', 'بصص', 'بصص', 'ص تیص ؛ بصيصاء وفى لغة: ربص يبص وبیصا أى برق . وال لبصبصة: تحريك الكلب ذنبه طْمَعًا طَمّعًا وحوفا. والإبل تفعلهُ إذا حدی بهاء قال: ضبن إذ خبرین بالأذناب'),
(3475, 'بصع', 'بصع', 'بصع', 'مخ حرق لباب مه اه لشيته. تلع تصاعة رصح اهر سل المسد أى نبع من أصول ار قليلا قليلا. قال عرّام: ارق هو البغ؛ بالضاد. بَضَّعْتَ'),
(3476, 'ثوب بشما', 'ثوب بشما', 'ثوب', 'مه توا وتم التق من ده أى: سرج قال أبو یب (۱) اللسان (بصر). (۲) (ط): ورد بعد هذه العبارة فى الاصول المحطوطة: بالفارستية بكال ثم عقب على ذلك'),
(3477, 'بقوله', 'بقوله', NULL, 'وبلساننا ند بارد. قول: وليس من علاقة بين البصر وهو الغلظ وبين البارد الندى ولعل شيعا قد سقط. (۳) (ط): ديوان الهذليين. القسم الأول (ص ۷) والرواية فيه: إذا ما استكرهت ... يتبضع بالضاد المعجمة. وفى الجمهرة (557/ . يتبصع بالصاد الهملة ناسبا ذلك إلى الخليل: إذا قال: ووكان اخلیل يدشد بيت أبى ذویب ... يتبصع وغیره ینشد: یتبضع. ۳ باب الباء ۱۰:۳ تأبى بدرتها إذا ما استعطب(۱) إلا الحميم فانه يتمع'),
(3478, '‏ صق', '‏ صق', '‏', 'بصق لغة فى بُسّق وبٌصاق اراد لعايه. والبصاق: هنات من ار تبدو منها إلى الستوی الواحدة بَصّفة كأدٌ الح صقها بصنقا. بالبصلت قال لبيد: (قَرُدّمانيا)”'' وت ڑکا کالبصل'),
(3479, 'بضض', 'بضض', 'بضض', 'امرأة بَضَةُ تارف مكتنزة الحم فى نصاعة لون. وَبَشْرَة َة تضيضة. وامرأة بْضّة تضاط قال ر نه لو كان حرا فی الکلی ما بسا ب وقال: کل رداح م َة طباض وض اج إذا حرج منه الما و خر منه بضاطت [وبئز بت وض: یجیء ماژها قليلاً قلیلاع ۳1 . والبضباض: قالوا: الكَمْأَةَ ولیست عحضق(.'),
(3480, 'بضع', 'بضع', 'بضع', 'بضغت اللحم أَبْضَعُه بضع وبضَعْته تبضيعاء أى: جعلته قِطّعا. وَالبَضْعَةُ القطعة وهى لبر . وفلان شديد البضع والبضعت أى: حسنها إذا كان ذا جسم مر (۲۷). وبضعت من صاحبى بضرعا إذا أمرته بشیء فلم یفعله فدحلك منه شیء وبضعت من عرجاء فى التهذيب (57/ : أن ابن دريد أذ هذا من كتاب ابن المظفر فمر على التصحيف الذى صحفه) . (۲) (ط): زيادة من التهذیب واللسان وهو ما نقله الأزهرى عن العین. (۳) الرحز فى الدیوان, ص ۷۹. )٤(‏ الرجز فى الحکم .١١١/۸‏ )٥(‏ زیاده من التهذیب ما أحذه الأزهرى من العین). )1 زيادة من التهذیب أيضًا. (۷) وقال فى التهذیب (4۸۷/۱). وآنشد أى اللیث: حاظی البضیع لحمه حظا بظا. ٤‏ باب الباء الاء بضوعاء أى: رویت. والبضع اسم باضعتهاء أى: باشرتها. وبضعتها بضعاء وبضعاء وهو الجماع. والبضاعة: ما أبضعت للبيع کائنا ما كان. ومنه الابضاغ والابتضاع.'),
(3481, 'الباضعة', 'الباضعه', NULL, 'شجة تقطع اللحم. والباضعةٌ: قطعة من الغنم انقطعت عن الغنم. يقال: فرقا بواضع. والبضيع: البحر قال: ساو رم فى البَضِيع ثمانيًا يُلْرَى بفيفاء البحور وينب'),
(3482, 'يطأ', 'يطا', 'يطا', 'البطء: : الابطاء. ع فى ص بط نرب ویقال: ما أَبْطأً بطاً بك عناء وقَوْمٌ بط وفلان بط مثل: بطوع. وباطية: اسم بحهول أصْلّه.'),
(3483, 'بطع', 'بطع', 'بطع', 'بَطَحْيُه فابطح. والبَطحاء: مسیل فيه دُقاق الْحَصّى ٠‏ فإ عرض ولسع ی أبطّح. والببطحية: ماء مستنقع بين واسطٍ والبصرق لا يُرَى طرّفاه من سَعته وهو مغيض دحلة والفرات وكذلك مَغايض ما بين البصرة والأهوازه والطَّفُ: ساحل البطيحة. وتَبَطّحَ السیل أى: سال سيلا عريضًاء قال ذو الرمة: ولا زالَ من وء السّماكِ علیکما ونوء ثرا وابل م وقال الراجز: ۱ إذا یط على الحایل بطح لبط بشّط الساجل”" والبطحاء والْطْحٌ ومتی من الأبُطح. ویقال: بين قرية كذا وقرية كذا بطحة بعيدة. (0 البيت فى الحکم (۱۸۹/۳). (۲) الرحز فى المحكم .)۱۸٤/۳(‏ باب الباء :۱ پدهشك. . وفى معنى: : كالأشر وط لته يقال : بط فلا شمه الل أ أى : 0003 حتی جاوز الشّكْرَ فت رکه وراءه. والبْطرة: مُعالحة البيطار الدّواب من الدّای قال: شك الفريصة بالدری فأنفذها شلك البیّطر اذ یشفی من العَضّدٍ س( [يساقطها تسری بكل حميلة] كبَرَغ البيطر الثقفي رَهْص الكواون وهو بطر الدواب أى: يُعالحها. ورجل بطرین وامرأة بطريرة واکثر ما یقال للمرأة. قال آبو الدقيْش: هى التى قد بطرت حتى تمادت فى الغی. A (۲) 5 : ۳ 0 5‏ اس ی رع 1 5'),
(3484, 'يطط', 'يطط', 'يطط', 'بط اجرح بط والیط: المنْضّع. والبطة: اه بلغة مَكّة .. والبّط: معروف'),
(3485, 'أنطلته', 'انطلته', NULL, 'جعلته باطلاً. و بطلت: جحت بکذبی وااعیت عير الحق. والتبطا: فعل البطالت هر قاع ی وی وَالبَطلٌ: الشحاغ الذى يطل حراحته ولا یکترث لها ولا نك عن دنه واه سل ين طولة. وبطلنى فلاث: منعنى عملی. وتقول: البطل الرحل هد أى: إنه بطل وابطل الشىء هذا أى: إنه باطل وجمع ابطل: أبطال. (۱) اللسان (بطر). (۲) (ط): زيادة من مختصر العين (الورقة ۱5۷). (۳) التهذیب ۳۰۳/۱۳. اللسان (طیب) غير منسوب أيضًا. ۱:۹ باب الباء'),
(3486, 'باطنة', 'باطنه', NULL, 'التى قد حصت والظاهرة: التى عمّت. قال الله عز وجل: وأسْبغ عليكم نِعَمَهُ ظاهرة وباطنة [لقمان: ۲۰]. والبطنة: امتلاء ابطن من الطعام؛ وهی الأَشّر من كثرة لمال أيضاء ومنه قيل: نزت به البطنة. ورَجُلٌ بطين: :ضحم م البطن؛ ورحلٌ بطينٌ: کنیر للال أيضًا. قال رؤية”"©: وکرژعشی بَطِينَ الكرز لا يڌر الكى بذاك الکنسز ورجل مَبطوت: قد بط وبه البطن. لقت الدّجاجة ذا بَطيها: كناية عن مَرقهاء أى: سلحها. وأقّت المرأةٌ ذا بَطيها. أى: رت ونثرّت اروج بَطُنهاء آی: كرت ولدّها. والبطان للبعیر كا خزام لابق وجمعه: بط و العدد: أبْطِنة .. وتبطينك الدابة: ضربك بَطْنها بالسرط. وت فى هذا الأمرء أى: دحلت فيه حتى عرفت باطنة .. وتبطنت الأرض والکلك أى: حَوّلْت فيه. ورَجُلّ ميْطان: يُغيب بالعَشيّات عن الناس فى الشُرْبٍ وغيره قال متمم لقد کش التهال تحت ردام فتی غير مبّطان العثییات أَرْوَعا ورجل مبّطاث [إذا كان لا يزال ظ ضحم البطن] يأكل اکلا شديدًا دون أصحابه'),
(3487, 'بظر', 'بظر', 'بظر', 'قال أبو الدقیش: امرأة بريد شب لسانها بالبظر وهو معروف "۲ . [وامرأة بظْريرٌ وهی الصحابة الطّويلة اللسان وروی بعضهم: بطرير لأنها قد بَطِرَّت وأشرت]. وقول أبى الیش إلى الصواب آقرّب. ورجل آبظر: فى شَفته العُليا طول مع توء وَسَطهاء ولو قيل للرجل الصخاب أْظرُ حارٌ. َه بَطراء وا بظره ومصدره بَظِْرٌ من غير أن يقال: بَظِرَ لأنه لازم وليس بحادث. وفلان بيص فلا ویر به. وروی عن على أله اتی فی ُريضة وعنده ري فقال له عل ما تقول فيها أيّها الب الب [ويقال للتى تَحنیض ابخواری مُبظرة].'),
(3488, 'بظظ', 'بظظ', 'بظظ', 'بط يبظ أوتاره باه وهو تحريك الضارب آوتاره یا للعتّرْب وفى لغة بالضاد والظاء حسن. ويقال: بظ على كذاء أى لح عليه ويقال: بی یی بَغلى فهو با إذا اكتنز لحما وميمنًا.'),
(3489, 'يظا.ء ظو', 'يظا.ء ظو', NULL, 'قال الأغلب حاظی البَضيع لحه حظا بل وربا صلة ل_رعظا,. وقال آبو الأسود لابن أخيه وقد أغْرّس: كيف وَجَدْت أهلّكَ؟'),
(3490, 'بعثر', 'بعثر', NULL, 'يقال: بعثره بغترة: إذا قلب التراب عنه. )١(‏ عادة الخليل فى كتابه الإعراض عن تفسير الألفاظ التى بحرح الذوق وقد مضى لذلك أمثلة (۲) اللسان (بظا). (۳) رواه البخارى فى كتاب التفسير .)٤۷٤١(‏ ۱:۸ باب الباء'),
(3491, 'يعد', 'يعد', 'يعد', 'بعد: حلاف شىء وضد قبل فإذا أفردوا قالوا: هو من بعد ومن قبل رفع؛ لأنهما غايتان مقصود إليهماء فإذا لم يكن قبل وبعد غاية فهما نصب لأنهما صفة. وما خلف بعقبه فهو من بعده. تقول: أقمتْ حلاف زيل أى: بعد زيد. قال الخليل: هو بغير تنوين على الغاية مثل قولك: ما رأيته قطء فإذا أضفته نصبت إذا وقع موقع الصفة'),
(3492, 'حهه ووحهه', 'حهه ووحهه', 'حهه', 'آبعده الله وأسحقه والصروف ينصب لیعلم أنه منقول من حال إلى حال ألا تری آنهم یقولون: مرحبًا وأهلاً وسهلاًء ووجهه: أرحب الله منزلك وأهلك له وسهّله لك. ومن رفع فقال: بَعْدٌ له وسَحق يقول:هو موصوف وصفته قوله [له]'),
(3493, 'باعجة', 'باعجه', NULL, 'اسم موضع. التهذيب (۳۸۹/۱). )٤(‏ (ط): تكملة من المحكم (۰)۲۰۳/۱ وبنو بعجة: بطن. باب الباء ۱:۹ مر موي ري ار هج 2 ۹3 رو'),
(3494, 'على معنيين', 'علي معنيين', 'علي', 'أحدهما: ضا القرب بعد يبعد بعد فهو بعید. وباعلته اعد وابعده'),
(3495, 'الباعدة', 'الباعده', NULL, 'تباعد الشىء عن الشىء. والأَبْعَدُ ضد الأقرب, والجمع: أقربون وأبعدون وأباعد وأقارب. قال(): من الناس من يُعْشَى الأباعد نفعُه ويشقى به حتى الممات آقاربه وان یلك حيرا فالبعية يناله وان یلك شرا فان عمك صاب ويقرأ ربیدت تَمُودُ زهود: ]٩0‏ ومبغذت تموذه. لا أنهم يقولون: بَعِدَ الرّحل وأبعده الله. والبُعْدُ والبعادٌ أيضًا من اللعن کقولك: آبعده الله أى: لا يرثى له ما نزل به. قال: ۱ وقلنا أبتعدوا کبعاد عاد وهذا من قولك: بدا وسحقاء والفعل منه: بعد ید بَعدًا. وإذا أَهَلعَهُ لا نزل به من'),
(3496, 'سوء قلت', 'سوء قلت', 'سو', 'بُعْدَا له كما قال: وعدت مود ونصبه فقال: بُعْدَا له لأنه جعله مصدرًاء ولم يجعله اسما. وفى لغة تميم يرفعون وفى لغة أهل الحجاز أيضًا.'),
(3497, 'بعر', 'بعر', 'بعر', 'البَعَرُ للإبل ولكلّ دی ظلف لا للبقر الأهلىّ فإنه بخشی. والوحشی یم'),
(3498, 'بعص', 'بعص', 'بعص', 'البغصوصة: دويبة صغيرة لها بريق من بياضها. يقال للصبی: يا بعصوصة لصغره وضعفه. لم يعرفه أبو لیلی وعرفه عرام.'),
(3499, 'دعض', 'دعض', 'دعض', 'بعض كل شىء: طائفة منه. و بعضته تبعيضا: إذا فرقته أجزاء. وبعض مذ کر فى (۱) البيتان فى التهذيب (547/ . ۱۰ باب الباء الوجوه کلها؛ کقولك: هذه الدّار متصل بعضها ببعض. وبعض العرب یصل ب (بعض) كما یصل ب(ما) کقول الله عر وحلّ: فبما رحمة من الله [آل عمران: .]١59‏ وکذلك ببعض فى هذه الایة: وان يك صادقا یْصیکم بعض الذى يعدكم [غافر:'),
(3500, '۸ والبعوض', '۸ والبعوض', '۸', 'جع البعوضة, ومی المؤذية العاضّة فى الصیف.'),
(3501, 'يعع', 'يعع', 'يعع', 'البعاع: بقل السحاب بع السحاب والطر عا وبعاعا: إذا أ بالکان َالبَعَاعٌ أيضا: نبات قال امرؤ القيّس: رال بن ف تاعا ور O‏ تج بعد الكل فهو نییص'),
(3502, 'قال زائدة', 'قال زائده', 'قال', 'رباع( 1 شیء اما هو رلعاعٌای وبطرن قر واد. قال: والبعبعَة: صَوْتُ ایس آیضا. والبمبُعَة: حكاية بعض الأصوات.'),
(3503, 'یعق', 'یعق', 'یعق', 'البعاق: شدء ة الصّؤات. بَعتت الاب بعاقا. والطر الباعق: الذی يفاجئك بشدة. قال: ۱ يعن فيه الوابسل التهطل'),
(3504, 'الانبعاق', 'الانبعاق', NULL, 'أن یبعق السَىءُ عليك مُاحَا قال أبو دُوَادِ: وار س ينما الرء آمساراع هرا تم حتفي لم خش منه انبواق ۳14 .)۸4( دیوانه‎ )1١'),
(3505, 'باعق', 'باعق', NULL, '۹ إذا اب بصوته والکنی ون" یقال: اللقیل من الدّواب. وبعشت'),
(3506, 'إتاء', 'اتاء', 'اتا', 'الثمرة. والبَعْلُ: الذكر من النخلء والتاس یسمونه: الفَحْل. قال التابغة: من الواردات الماء بالقاع تستقى بأذنابها قبل استقاء الحناحر آراد بأذنابها: العروق. والبَعْلٌ: نم كان لقوم إلياس. قال الله عرٌ وجا”: أتدعون غلا الصافات: ۱۲۵]. والتباغل وَالباعلَةُ والبعال: ملاعب الرّحل آهله تقول: باعلها )١(‏ اللسان (بعق) وفيه: تقریظ بدل تفريط. (۲) قال محقق (ط): فى القاموس: الکذیرن بوزن فرعون دقاق التراب عليه ذرّدی الزیت بحلی به الدروع. وهذا بعيد عن عبارة العین: ولعل صاحب العین قد وهم يدل على هذا قوله: (یقال). (۳) اللسان (بعل). o۲‏ باب الباء مباعلة وفى الحديث: أيام شرب وبعال('),
(3507, 'تعليك', 'تعليك', NULL, 'لك اسم أرض بالشام. بعا (يعو): البَغو: ابرم قال . وابسالسی نی بر جرم بَعونسساة ولا بسدم ماق وبعوا من فلان أى حقروا وتجرءوا.'),
(3508, 'نخت', 'نخت', 'نخت', 'ات البَغْة. قال DA, وباغته مباغتة أى فاحاه تة‎'),
(3509, 'بفث', 'بفث', 'بفث', 'الأنغث من طیر الماء کلون الرّمادء طویل العُدق وجَنمه: يُفث وأباغث.'),
(3510, 'البغاث', 'البغاث', NULL, 'رز كالبواشيي لا تصيد شتا من الط الوّاحدة بغاثة وَيُجْمَعُ على البغفان. قال أبو عبد الله: هو الر عم(" " وشبهه. ويُومٌ بغاث: وقعة كانت بين الوس واخزرج 60 تق مس 27'),
(3511, 'بتدر', 'بتدر', NULL, 'بر حبث النفس. يقال: مالى أراك میحر'),
(3512, 'يغر', 'يغر', 'يغر', 'بَعيرٌ بَغِرٌ أى لا بروی. وبغرّ النوء إذا ماج بالطر. قال: (۱) رواه الامام أحمد (۱۹/۱) وقال الشیخ شاکر إسناده ضعیف. (۲) هو عوف بن الأحوص ابلعفری (اللسان) (بعو) وفیه: بغیر بعو جرمناه وفی الصحاح مشل لفظ المصنف هنا. (۲) عجز بيت فى الحکم (۲۸۱/۵) ویروی الشطر الأول: ولكنهم بانوا ولم أحش بغتة بالقذر. ` وذكر ابن المظفر هذا فى كتاب العين فجعله يوم بغاث وصحفه؛ وما كان الخليل - رحمه الله - ليخفى عليه يوم بعاث؛ لأنه من مشاهير أيام العرب وإنما صحفه الليث وعزاه إلى الخليل نفسه وهو لسانه, ومثل هذا ورد فى معجم البلاد لياقوت.'),
(3513, 'يفض', 'يفض', 'يفض', 'البغضة والبغضاء: شد البغض. وقد بَفض بَاضّة فهو بفیطن. وبغض ب إلى بغضّة وبَغاضة. وعم بك الله عينا وأبغض بعدوك عَينا.'),
(3514, 'بضغ', 'بضغ', 'بضغ', 'البغبَغة: حكاية صوت من الهدین قال:'),
(3515, 'لبغشيغة', 'لبغشيغه', NULL, 'ضيْعَة حفر ذى الجناحين بالدينة.'),
(3516, 'يغم', 'يغم', 'يغم', 'بَغم الظبی یم بُغومًا وهو أَرْحمٌ صوته. قال ذو الرمّة: داع يُناديه بامم الماء تنغو أئ لمجاب ینام والبْوم : الوَلدُ أن مه تبغمه أى تصیح به. والناقة والبَقَرةٌ تبغمان. وامرأة بغوش أى رخيم الصّوت. قال: ذا أنت بابَعُومُ انا أى ما أَحبَّكَ إلينا. بدا (منى): ب بَغى بغای أى: فش وهو يبغى. والبغية: نقيض الرّشّدة ذ فى الولد يقال: (۱) الشطر فى اللسان غير منسوب. (۲) البيت فى المحكم (717/5؟) وفيه: غرمسا بالغين المعجمة. (۳) عجز بيت فى اللسان, والمحكم (۳۲۱/۰) وصدره: لا نکش الطرف الا ما تخوّنه وانظر الديوان (ص ١لاه).‏ ١٠6‏ باب الباء لدى رشدة من امه أو لبغيسة" فيغلبها فحلٌ على الل حب وابن رشدة إذا كان من ماء صاف. والبغية من الزنى. والبغية: مصدر الابتغاء تقول: هو بُْيّتى أى: طبتی وطيتى. وبَفیت الشّىء أبغيه بغای وابتغيته: طلبته. وتقول: لا ببغی لك أن تَفعلَ كذاء وما انبغى لك فى الماضى؛ أى: ما ينبغى. وی فى عدو'),
(3517, 'الباغى', 'الباغي', NULL, 'الظالم. والبغايا : الجوارى. والبغايا : الطلائع. الواحدة: بغية أيضا. ويقال: انك عالم ألآ نبا ولا تباغا ولاتباغوا ولا تباغی وفی لغة: ولا تباغو وفى الاشین: ولا تباغيا وفى الواحد ولا تباغ. يقال: معناها لا يباغيك أحد. وقال آحر: أى: لا تصيْك عينٌ على الدعاء. وتقول: لا تبغت بك عين يعنى: لا ينازعك أحد فيبغى عليك أى قد سلم لك فلا تنازع.'),
(3518, 'الباقر', 'الباقر', NULL, 'جع البقر مع راعيهاء وكذلك ابحامل: جمع احمل مع راعيها. والبَّشرٌ: شق البُطن قال الراجز: ضرا وطعنا باقِرًا عشنو ۲٩‏'),
(3519, 'البقيرة', 'البقيره', NULL, 'ی قمیص سه بساء له ین إلى السثرة. ور لسع من یرت البَطَّ وئهی عن التبقر فى المال. ور لاب بای وهى لغبة بمب بها. وبقروا حَؤلّهم أى حفروا ویقال: کم بقرتم لسیلکم أى كم حفرتم وقال طفسل الغنوئ: ومِأْنَ فما يك حول مالع بهامشل آثار ابقر مَلْعَبْ'),
(3520, 'بقق', 'بقق', 'بقق', 'البق: عِظام البعوض الواحدة بَقَة. والبقاق ق: أسقاط مناع البيت. ووضع حبر فى بنى إسرائيل سبعِينَ كتابًا من صنوف العلم فأُوحَى إلى نب من أنبيائهم: أن قل لفلان إنكَ قد مَاذَّتَ الارض بغاقاء وان اله لا يقب من بقاقكم شین ويقال لكغير الكلام: بقباق . والبقبقة: حكاية لصو كما يبقبق الكو فى الماء.'),
(3521, 'الباقل', 'الباقل', NULL, 'ما رُح فى أعراض الشجر إذا ما دنت یا امع رک ا ا فى أعراطيه شئة أغْيْنٍ اراد قبل أن يُستبين ورقه فذلك الباقل وقد لاجر ۰ ويقا'),
(3522, 'عند ذلك', 'عند ذلك', 'عند', 'صار الجر بقلة واحدة. وابقلت الارض فهى مه أى أت ۳'),
(3523, 'البقلة', 'البقله', NULL, 'ذات البقل. . والباقنّى اسم سوادئ وهو الفول وه الجرّحر. ويقال للمرّد إذا'),
(3524, 'حرج وجهه', 'حرج وجهه', 'حرج', 'قد بقل وَحْهُهُ. وباقل: اسم رجل یوصف بالعی؛ وبلغ من عیّه أنه اشتری'),
(3525, 'یا فقيل له', 'یا فقيل له', 'یا', 'بکم اشتریت؟. فأحرح أصابع يدَيْهِ ولسانه أى أَحَدَ عَشَرَ درهمًا؛ فأفلت الظیی وذهب.'),
(3526, 'يقى', 'يقي', 'يقي', 'رتقول العَرَبْ: نشذتك الل والبقياء وهى: البق قال: وما صد عنى حال من ية ھی الثثئء يَنْقى بقَاء وهو ضِدٌ الفناء. يُقال: ما بَقِيَتْ منهم باقية ولا وقاهم من درد . وبقی يَبْقَى : : لخق وكل ياء مكسورة ذ فى الفعل يجعلونها ألقاء نحو: بى ورَضّى وفنی. . واستبقيت فلانا؛ إذا أوجبت عليه قتلاً وعفوت عنه؛ واستبقیت فلانا فى معنى: عفوت عن له واستبقیت مودته قال : ولت شتبی أحا لا تله على شع أئ الرّحال الهَذْب؟!! وإذا أعطيت شينا وت بعضه قلت: استبقيت بعضّةُ. وفلانٌ يُبقيسى ببَصّره إذا كان يُنظر إِلَيْهِ ويَرْصدهُ قال يصف حمارًا: ۱ ظلَّتْ وظل عَذوبًا فوق رابية ‏ تبقیه بالأعين المحزومة العَذْبْ'),
(3527, 'أراد', 'اراد', NULL, 'أن هذا مار يريد أن يرد بأتيه فوقف بهن فوق رابية وانتظر غروب التشّمْس. وبات فلان یی البَرْقَ أى: ينظر إليه من أين يلمع؟ قال الفزاری: قدهاجنى الليلة برق لامع بت آبقی ه لعینی رامع'),
(3528, 'بكا', 'بكا', 'بكا', 'البكيئة من الثناء أو الإبل: القليلة الب. یوت الشّاة تكو بكاءةً وبُكُوءًا.'),
(3529, 'البكء', 'البكء', 'بك', 'نبات کاب جیر. الواحدة: بكأًة.'),
(3530, 'احدها', 'احدها', NULL, 'بکر وهو الكرّم الذی حمل اول جل“ . وأبكارٌ کرم یعنی: العنب. وعسل أبكار یس أبكار النحلء أى: أفتاؤهاء ويقال: بل الأبكار من ابحواری تلينه.'),
(3531, 'يكك', 'يكك', 'يكك', 'البَكُ دق الغنق. وسمیت مكة: بكة لان الناس يبك بعضهم بعضا فی ‏ الطواف أى: یدفع بعضًا بالازدحام. ویقال: بل سيت لأنها كانت تب عناق الحبابرة إذا ألحدوا فيها بظلم. والبَكْبَكَةُ: شىء تفعله العنر بولدها. (۱) من التهذيب (۲۲۹/۱۰) عن العين واللسان (بكر). (ط): فى الأصول المخطوطة: بكرة. (۲) زيادة من التهذيب (۲۲/۱۰) عن العين. (۳) (ط): جاء بعد كلمة رحمله) بلا فصل عبارة أكبر الظن أنها مقحمة فى الأصل وليست منه'),
(3532, 'هى', 'هي', 'هي', 'ويُسَمّى الكرم بكرا لا يكاد يفرد منه الواحد. قال غيره وفى (س): قال غير الخليل: لا'),
(3533, 'يكم', 'يكم', 'يكم', 'الأنكة: خرس الذى لا يكلم وإذا امتنع الرَّخُلُ من الکلام جَهْلاً أو تعمّدًا فقد بكم عنه وقد یال لأذى لا يُقْصِحٌ: إنه لأَبْكَمْ. والأبكم فى التفسير هو الذى ود أخرس. بكا (یکی): البکاء مدود ومقصور. بکی ینکی. وباکیته فبكيقه أى: كنت آبکی منه.'),
(3534, 'رجل أبلج', 'رجل ابلج', 'رجل', 'طَليق الوَحْهِ بالعروفي ورجل بلج أى: طلقّ. وابلخت الشَمْسْ ابلاجٌاه أنارت وأضاءّت. ولج احق فهو بلج بل رویقال: بلج الصبح إذا آضاء).'),
(3535, 'البلخاء', 'البلخاء', NULL, 'التى دحلها ار مس خر'),
(3536, 'البلدة', 'البلده', NULL, 'موضع [لا نحوم فيه] بين النعائم وسَئد الذابح ليس فيه کواکب عِظامٌ تكون عَلْمّاء وهی من مُنازل القَمّره وهی من آخجر البروج سمت بلدة وهى من برج القوس خالية إلا من کواکب صغار. والبلدة: بلْحَة ما بين اطساحیّن. والبلادة نقيض النفاذ والضاء فى ال [ورحل ی إذا لم يكن ذكيّا]ء وفرس بلیده إذا تأحر عن ال السوابق وقد بل يَلادة. و الب نقیض التجلد وهو من الاستکانة واخضوع قال: ألا لا تلمه الوم أن يبدا“ ول الرحلٌ أى نكس وضمّف فى العمل وغیره حتى فى ابلمود قال: جَرَى طلقا حتى إذا قیل ساب تداركه أعراق سُوء فبلدا والبالدة كامبالّطة بالسيّوف والعصي إذا احتلدوا بها على الارض ويقال: اشتو من بلادٍ الأرض. وِبَلّدوا بها: لَرمُوها فقائلوا على الأرض. ورجل بالد؛ فى القياس: مُقيم بیلده. والأبلاد آثار لوم فى الي وبه شه ما بھی من آثار الدارء قال حرير: خی النازل رین قد يليت للضی لم بق منها غير أبلاد'),
(3537, 'بلدح', 'بلدح', NULL, 'بَلْدَحَ الرّجل أئ: بلد وأَغْيّى. والبلندح من الرحال: السّمين القصير. (۱) البيت فى المحكم (۰)1۰/۱۰ كرواية العين والتاج والأساس والصحاح والمقاييس (۲۹۸/۱). (۲) بلا نسبة فى اللسان (بلد) وعجزه: فقد غلب المحزون أن يتجلدا ۱-۹ باب الباء'),
(3538, 'بلدم', 'بلدم', NULL, 'البَلْدَمُ: الثقيل فى المنطقء البلید المخبّر ومُّقَدمُ الصذر بل'),
(3539, 'یلسن', 'یلسن', NULL, 'البلسن: العدس. بلص (بلخص): البلنصاة: بقلة وتحمَع البلنصی وقد تسَمّی بلنصوصة [ویقال: إنها طائرة]. ۱ بلط بلاط الأرْض: متنها الصلب من غير مي قال: لزم [غلاث] بلاط الأرض.'),
(3540, 'البلاط', 'البلاط', NULL, 'ما بلطت به الارض من حجارةٍ أو آحر فرش بها فرشا مستویّا بهاء آملس فهى وت وبلطناها بَلْطّاء وبلطناها تبليطًا. ويقال: بلطت الأرض وملّطست إذا سویت. والبُوط: مر شحر له حمل يُؤكل دیع بقِشره. والتبليطء عراقية: أن تضرب فرع أذن بطرّف سبابتك ضربا یوحعه؛ [تقول]: باطت بلطت اد تبلیطا. الط الطز الأرض'),
(3541, 'بلعك', 'بلعك', NULL, 'ویقال: حمل بَلْعَلكٌ وهو البَايدُ.'),
(3542, 'بلعم', 'بلعم', NULL, 'البْلْعُومْ: البياضٌ الذى فى حَحفلة الجمار فى طرّف الق قال: بیض البلاعيم أمثال الخواتيم'),
(3543, 'البالغة', 'البالغه', NULL, 'أن بلع من العمل حُهْدَلة. قال الضریر: سيعت أبا عمرو يقول: لب ما یبلغلك هه ور من احبر الذى لا يُعْحِبكء القول: اللهُمّ سَمْمٌّ لا بلغ أى اللَهُمَّ د نسم ثل هذا فلا قزل'),
(3544, 'یلخم', 'یلخم', NULL, 'البَلعَمْ: حلط من علاط الجسّد.'),
(3545, 'بلق', 'بلق', 'بلق', 'البق والبلقة مصدر الأبلق. ويقال للدابة آبلق وبلقای والفعل: بلق یبلق وحبل بلق ونعف ؛ بلق يعنى الشَرّف من الأرض. والبلُوقة. وتحمَع بلاليق وهی مَواضِع لا یت فيها الشّحر. بلقت الباب فانبَلقَ أى فتحته فانفتت قال: فامجصن مثلم والباب تبلق'),
(3546, 'فی لغة', 'فی لغه', 'فی', 'أبلقت الباب. وخبل أبْلق.'),
(3547, 'بلقع', 'بلقع', NULL, 'بقع القفر لا شَئءً فيه. منزل یلم وديارٌ بلاقع. وإذا كانت اسما متفردا'),
(3548, 'أت تقول', 'ات تقول', 'ات', 'انتهينا إلى يَلقَعَةِ مَلْساءً.'),
(3549, 'بلل', 'بلل', 'بلل', ': لب اسم من (بلٌ). والبلة وال الدون. . وبلة اللسان: ووغه على مواضع ارف واستمراژه على الق يقال: ما خسن بل لسانه أو ما يْقَعُ لسانه الا على بلته. والبلال :بل وهو الاسمء والواحد مثلك ویقال: هو جمع بلة قال السسّاجع: اضربوا أميالا تحدوا بلالا .. ویقال: بلال هاهنا اسم رحل. والبلیل: الرّيح الباردة.'),
(3550, 'حديث', 'حديث', NULL, 'وهی لشارب حل وبل" البل: ابا بلغة هیر وقال: (۱) ذكره أبو عبيد فى غريب الحديث )551/١(‏ وهو من قول العباس بن عبد المطلب فى ماء زمزم. ل باب الباء إذا بل من داء به ظن أنه نحا وبه الداء اذى هو قاتا وبل فلانٌ بغلان أى: وقع فى بدیه قال: بلت به غير طیاش ولا زعش وقال طرفة: [إذا ابتدر القومٌ المسّلاح وجدتبی] ميا إذا بلس بقائمه یسندی'),
(3551, 'البل', 'البل', 'بل', 'مصدرٌ الأبلّ من الرّحال وهو الذى لا يستحى ولا يبالى ما قال قال: ألا تقون الله يا آل عامر؟ وهل یتقی الله بل المصَّمّهة ویقال للإنسان إذا حَسُنَتْ حاله بعد الهزال: قد ابعل ول َالبُلبْلُ: طائرٌ يكون فى أرض الحرم < حَسَنْ الصوت يأل الخَرّم. وال : صرب من الكيزان فى جنبه بل يَنصّب منه الماغ. ولیل وسواس الهموم فی لکش وهو بیان داس تال تم نك لزي اد . وفی الحديث: کان اس بنی پل" '' ویروی: : بذی ن مکسورة البای مشددة اللا يقال: أراد بذلك والله أعلم؛ تفرّق اناس وتشتت ینام ريدمب الوا حى يُقال: نا على ذى بيان مکانهم فیها. ‏'),
(3552, 'بلخط', 'بلخط', NULL, 'البلنط: شىء یه ارحام إلا أن الرحام هش وأرخى. قال فى وصف ساتي الجارية: ر ور ع اي لل 8 رد مب (۲)'),
(3553, 'التبله', 'التبله', NULL, 'تطا تطلب الضالة. له کلمة .ععنی أَحَل. قال : له إنى لم آحن عَهْدًا ولم آقترف دنا فتخریسی القم'),
(3554, 'البلية', 'البليه', NULL, 'الذابة التى كانت تشد فى الجاهليّة على قبر صاحبهاء رأسها فى الولية حتی تموت قال : کالبلایا رءوسّها فى الوّلايا ‏ مانحات السموم حر الخدود'),
(3555, 'بلىئ', 'بليئ', 'بلي', 'حی والنسبة إليه: بلوئ. وناقة بل سَفر من مثل بط وقد آبلاها السفر قال: (۱) (ط): من ختصر العينء (الورقة .)٠٠١‏ (۲) (ط): سقطت الكلمة وترجتها من الأصول وأثبتناها من ختصر العين (الورقة )٠٠١‏ ومن التهذیب فى روايته عن العين (۳۰۸/۱۰). (۳) نسب فى التهذيب .)27/١5(‏ واللسان (بلنط) إلى عمرو بن كلثوم وهو من معلقته كما فى شرح المعلقات العشر (ص . .)۱۱۹4 ضعيف رواه البزار عن أنسء وانظر ضعيف الجامع (ح‎ )٤( (۷) التهذيب (۳۹۱/۱۰). “٤‏ باب الباء منازل ما تری الأنصاب فيها ٠‏ ولا خفر ای للمنون'),
(3556, 'يضت', 'يضت', 'يضت', 'ومنه قول امرئ القیس: غير بانات على وتسره'),
(3557, 'پنچ', 'پنچ', 'پنچ', 'البَنج: من الأدوية مُعَرّب.'),
(3558, 'بفد', 'بفد', 'بفد', 'البنْدُ: دَيلٌ ويقال: فلا كثيرٌ السود [أى كثيرٌ اليلِ]. والبَندُ أيضًا: کل علم من الأعلام للقائدء والجميع امود وتحت كر بند عشرةٌ آلاف [رجلء أو أقلٌ أو أكتر]ء قال: يا صاحب الأعلام والبنود'),
(3559, 'بندر', 'بندر', NULL, 'البنادرة والدرابنة دخيل؛ هم التجّار الذين يلزمون المعادن وأحدهم بندارة.'),
(3560, 'يندق', 'يندق', NULL, 'البُندُّق: والواحدة: بندقة: ما یرمی به.'),
(3561, 'پنس', 'پنس', 'پنس', 'تس أى: تحر وتخلف ینس فلان.'),
(3562, 'پنصر', 'پنصر', NULL, 'البنصر: الاصبع ین السّطی والخنصیر..'),
(3563, 'بفق', 'بفق', 'بفق', 'البَيقةُ: کل رقعَة فى ارب نحو اللبنة وشِبههاء والجميع: بنائقء قال: )١(‏ تكملة مما روی فى التهذیب (۳۹۱/۱۰) عن العین.'),
(3564, 'بظك', 'بظك', 'بظك', 'یقال: رده إلى بنکه, أى: أصله. وتیل فلا فى عز ومتعة [أى: تمکرم(.'),
(3565, 'بنن', 'بنن', 'بنن', 'ال : ريح مرابض الغنم والبقر والظباء .. وتقول: أحدُ لهذا الثؤب بنة طيبة من عرف تفاح أو سفرحل. والإبناك: اللزوم تقول: أبنت السحابق إذا رت ودامت. وان القوم .بمحلة أى: آقاموا بهاء قال: يا أيّها الرکب البنون 5'),
(3566, 'بفى', 'بفي', 'بفي', 'نى البناءٌ البتاء نی با ون وبنى مقصور. وال الكعبة يُقال: لا ورب هذه البنيّة. وَاليناة: كهيئة الستر غير أنه واسغ يُلْقَى على مقدّم الطراف. وتکون البناة كهيئة [القبّة] 7 تمل بيتا عظيماء ويُسكنُ فيها من الط ویکنون رحالهم ومتاعهم وهی مستديرة عظيمة واسعة لو ألقيت على ظَهْرها الوص تساقط من حولهاه ویرل الطر عنها ريلا قال۳): على ظَهْرٍ میناة حديدٍ سیُورها ‏ یط وف بها وط اللّطيمة با'),
(3567, 'دهت', 'دهت', 'دهت', 'الب ولد البغى. وه اسم أبى حی من سیم'),
(3568, 'یری', 'یری', 'یری', '7 والباهر من الرّيش: ما يلى الخوافى؛ وهی [الحوانب القصار]. الب من'),
(3569, 'قوس', 'قوس', 'قوس', 'ما دون الطائف. والبهار قبطية: ثلانمائة رطل. والبهار: من الانية کالابریق قال فى نعت الفرس(*) على العلیاء کوب أو بهار وانهاه یل أى انتصف. وبهرَة الشىء: وسطه. والبهار: نوع من نبات الربيع.'),
(3570, 'بهراء', 'بهراء', NULL, 'حي من من الیمن. (۱) بلا نسبة فى التهذيب (54/ واللسان (بهج) وفى الثانى: نواره. (۲) البيت لابن مقبل فى اللسان (بهر). (۳) البخارى فى كتاب الغازی (ح 57/8 ) رواه بنحوه. ره) وفى اللسان: قال الأصمعى: الأبهر من القوس: كبدها.'),
(3571, 'يهرم', 'يهرم', NULL, 'البهرمان: ا'),
(3572, 'بهزر', 'بهزر', NULL, 'يُقال للنخلة التى تباولها بيدِك: هى اور '' والجميع: البهازر. قال7": يَهَازرَاً لم تتعذ مازرا'),
(3573, 'بهصل', 'بهصل', NULL, 'البَهْصّلةٌ من النساء: الشّديدةٌ البياض. والبيْصّلة: المرأة الصّحابة الجريئة.'),
(3574, 'يهق', 'يهق', 'يهق', 'البهق: بیاض دون البرص. [قال رؤبة: كأنه فى ابید . تولیغ البق لبهق 0 5'),
(3575, 'بهکن', 'بهکن', NULL, 'جارية بيكنة: تارّةَ عظيمة الصّدر عريضته وه بَوُكنات وبهاکن وإنها کر فى مشیهاء يقال ذلك لذات العجيزة. (۱) رؤبة ديوانه 2779 وفى اللسان: الضزز: لزوق الحنك الأعلى بالأسفل إذا تكلم الرحل. (۲) فى اللسان: البهزّرة. (۲) بلا نسبة فى اللسان (يهرز). ۸ باب الباء'),
(3576, 'يهل', 'يهل', 'يهل', 'باملت فلاناء أى: دعونا على الظالم منا. وبهلته: لعنته. وابتهل إلى الله فى الدٌعای أى حذ واحتهد. وامرأة بهيلة لغة فى البهيرة. والأنقل: شجر يقال له: الأيرس '' ولیس بعربية حضة ویسّمی بالعربية عرعرا. والباهل: ترد بلا عمل وهو ایضا: الرّاعى بلا عصا. ول الراعی ! إبله: ت ركها. والباهل: الناقة التى ليست َصْرُورة؛ لبنها مباح لمن حل ورحل و بل بل ورجل بهلول: حيئ كريم وامرأة بُهلول. والبَّهْل: السّیء الیسیر احقی یقال: أعطاهُ قلیلا بَهّلا. قال": وأعطاك ی لا منهما فَرَضينَهُ وذو الب للبَهْل الحقير عیوف'),
(3577, 'البهل', 'البهل', 'بهل', 'واحدٌ لا یجمع. وامرأة باهلة: لا زوج لهاء وباهلة: حي من العرب. o‏ ۲ 3 و “ر ۳ ۳ ۳'),
(3578, 'بهلص', 'بهلص', NULL, 'بلص الرجل: حرج من ثيابه. قال : یت بای فلت أنه هص من أثوابه لم حا'),
(3579, 'بهلق', 'بهلق', NULL, 'البَهْلَّق: الحَّجُورٌ الکثیر الصّحبي وتقول: امرأة بهلق والجميع: بهالق. یرل ول من جوبهن اللي ل بالل ولولة البهلسق'),
(3580, 'وم', 'وم', 'وم', 'البهمة: ۳ والأنتى من اولاز يقر لو شش ورو لنم واس أيضًا. والإبهام :المع و a‏ ۳ والجميع: الأباهيم. رول مفصلان]. وأَبْهمَ ال أى اش لا یعرف وجهّه. واستبْهُمَ على هذا الأمر. وكان ابن عباس سكل عن قوله عز ر وحل: #وحلائل أبنائكم الذين من أصلابكم [النساء: ۳ فلم ین اذل بها أم لا؟ فقال: هموا ما أَبْهَمَ الله". وباب مُبْهَم: لا یهّتدی )١(‏ التهذیب ۹/5 ۰ واللسان (بهل). (۲) فى (ط): تتبهلص والثبت من اللسان (بهلص) ویدل عليه الشاهد التالى. (۳) التهذیب (۰۱۸/۰ واللسان (بهلص) ونسب فى اللسان إلى أبى الأسود العجلى. (ه) زيادة من التهذیب (/۲۳۹) عن العین. (۷) التهذیب (۳۳۵/۲).'),
(3581, 'البهيج', 'البهيج', NULL, 'ما كان من الألوان لونا واحدا لا شِيّةَ فيه من الدَّهْمّة والكمتة. وصوات هی أى لا ترحیع فیه ولیل بهيم: لا ضوء فيه إلى الصّباح. والبهيمة: ذات أربع قوائم من دواب ابر والبحر. ویحُشر الناس يوم م القيامة غلابم( أى لیس بهم شىء ها كان فى الدناه نحو العَمّى والعرج وابذام والیرصء ویقال: بل غُراة ليس معهم شی: من متاع الدّنيا. والبهْمة: الأبطال. قال متمم بن نویر و(" وللشَرّب فایکی مالكنًا ولبهمة شديدٍ نواحیها على من تشجعا'),
(3582, 'يهن', 'يهن', 'يهن', 'البَهْونى من الابل: ما يكون بين العربيّة والكرمائيّة دخيلٌ فى الکلام. وجارية بهنانة وَهْنانةٌ أى: ليّنة فى منطقها وعملها. [والبهنانة أيضًا: الطيبة الرّيم]7"'),
(3583, 'بهنس', 'بهنس', NULL, 'الأسد يُتبَهْنَسُ فى مشيه أى يتبختر وهو نعت للأسد خاصة.'),
(3584, 'بهه', 'بهه', 'بهه', 'البَهْبَهِىُ: الجسيم الحجرىء. قال : لا تراه فى حادث الذهر إلا وهويفدو تھی جریم'),
(3585, 'البهبهة', 'البهبهه', NULL, 'من هدير الفخل. والأبَةُ: لام بها (بهو): البَهُوُ: ابیت لدم ما البيوت والجميع: الأبهای والبهٌو: کناس واسع يتحذه الثؤرٌ فى أصل الْأَرْطَى. قال": جرف بَهَى بَهُوَهُ فاستوسعا وَالبَهُوُ من کل حامل: مب الولد بين الوركين. والبهئ: الشیء ذو أبهاء 2 8 العين روع وخسنه. بها هی وب یله و يَهاءً. وفى الحديث: لبوا ال" 3 عَطلوهاء فقد وضعت أوزارهاء قال هذا عند الفتح. وهی الإناء: فَرَعْتَه ب .)٤٦٥/۳( هذا لفظ حديث رواه أحمد‎ )١( (۲) التهذيب (۳۰/۱). (۲) (ط): تکملة من ختصر العين ورقة .)٩۷(‏ ۱۷۰ باب الباء'),
(3586, 'خالى', 'خالي', NULL, 'باوه ومن أمثالهم: المْرّى تبهی ولا تَببى 7 ل أى: تخرق ایام وتعطلهاء وأبنيته أعطيته بیتا.'),
(3587, 'بوأ', 'بوا', 'بوا', 'الباءة والمباءة: منزل القوم حين تبون فى قبل واد أو سند حبل ويقال: بل هو] كل منزل رل الوم يقال: تبَوَّهُوا منزلا .. وقال تعالى: إولقد بوأنا بسی إسرائيل رس ۳ مُبَوَأ صق [یونس: .۲٩۳‏ وقال طرفة: طيّبو الباءة سهل ولهم سبل إن شعت فى وعثر وعز وقال: ۱ یرت فى صمیم معشرها فتم فی قومها مبوؤّها'),
(3588, 'المباءة', 'المباءه', NULL, 'مَعْضِن الإبل حيث تناخ فى الموارد یقال: أبأنا الابل إباءة مدودق أى: أنخنا بعضها إلى بعض قال: حليفان بينيما مئرة یشان فى عَطن ضيّق""ا'),
(3589, 'بوب', 'بوب', 'بوب', 'البابا: معروف: والفعل منه التبويب. والبابة فى الحدود واليساب ونحوه: الغاية. والبابة: بغر من تُغور الرّوم. وباب الأبواب: من ثغور النزر. والسواب: الحاحب. ولو اشتقّ منه فِعْنُ على فعالة لقيل: بوابة بإظهار الواوء ولا بقلب ياء لأنه ليس عصدر محض, إنما هو اسدٌ. وأهل البْصْرةٍ فى أسواقهم يُسَمُون السّاقى الذی وف علیهم بالاء: بيّابًا. [والبأببة: هدیر الفخل فى ترجيعه تکرار له قال رژبة: بغبغة مرا ومرا بای ۲۲۱'),
(3590, 'بيبة', 'بيبه', NULL, 'اسم قال: دسا أبا مندوسة القين بالقنا ومار دم من جار بيبة ناقع وبالبحرين موضع یعرف ب (بابين) وفيه يقول قائلهم: إن ابن بور بين بابين وحم'),
(3591, 'البؤباة', 'البؤباه', NULL, 'الفلاق وهی: بل (۱) البیت للتغلبی فى التهذیب (9۹۸/۱۰) واللسان (بوأ). (۲) سبق. (۳) ما بين العقوفتین من التهذیب (1۱۲/۱۰) ما نقل فيه عن العین. ۱۷ باب الباء راو و مه فى ام 3 8 | ای 2 ټ 5 و 1'),
(3592, 'يوج', 'يوج', 'يوج', 'البوج: من تبوج البرق فى السحاب. إذا تفرق فى وحهه. وتقول: بجتهم بشرء'),
(3593, 'بوح', 'بوح', 'بوح', 'البوح: ظهور الشع. يقال: باح به صاحبه بوحا وبقوحا. قال: وبحت اليو بالأمرال الى قد كنت تخفيه ويُقال للرحل البؤوحح: بیُحان .عا فى صدره. والباحة: عَرْصَّة الدار. وفی الحديث: نظفوا َفنیتکم ولا تَدَعُوها كباحة اليهود.والإباحة: شبه النهبی. استباخوه: انتهبوه.'),
(3594, 'يوخ', 'يوخ', 'يوخ', 'باخت النار تبوخ بوّخا وبؤوحاء وابحتها: خدتها. وابخت الحرّب إباحة. قال:'),
(3595, 'يور', 'يور', 'يور', 'البّوارٌ: الهلاك. یقال: هو بور وهى بو وهما بوز [وهم بو وهن بور] هذا فى لغة وأمّا فى اللغة الفضنلی فهو بائر وهما باثران وهم بون أى: ضالون هلکی؛ ومنه قول الله عرّ وحل: لوکنتم قومًا بُورا [الفتح: ]١١‏ .. وسوق بائرة أى: کاسدة وبارت البياعات آی: کسدت. والبور: التجربة. يرت فلانا وبرت ماعنده: جرّبته ویقال: برت الناقة أبورهاء أى من الفحْل, لأنظرَ أحامل هى آم لا؟ وذلك'),
(3596, 'فخل', 'فخل', 'فخل', 'مِبْوَرٌ إذا كان عارفا بالحالين قال : بضَرب كآذان الفراء فضوله وطمْن كإيزاغ المحاض تبورها'),
(3597, 'البورية', 'البوريه', NULL, 'البارية.'),
(3598, 'يوش', 'يوش', 'يوش', 'البوشُ: الجماعة الكثيرة... بوش القوم؛ أى: كثروا واختلطوا.'),
(3599, 'يوص', 'يوص', 'يوص', 'البوص: أن تستعجل إنسانا فى تحمیلکه آمر لا تدعه یتمه فى الرويّة أى فى التقدير قال: .)۲۳١( اللسان (بوح). وليس عروی فى شىء من الصحاح لكنه .معناه فى الصحيحة‎ )١( البيت لمالك بن زغبة فى اللسان (بور).‎ )۲('),
(3600, 'بوط', 'بوط', 'بوط', 'البوطة: التى يريب فيها الصّاغة ونحوهم من الصناع.'),
(3601, 'بوع', 'بوع', 'بوع', 'لو والبَاعٌ لغتان. ولکن يُسَمّى لوغ فى الخلقة وبلط الباع فى الکرم ونحوه فلا يقال إلا كريم الباع قال: له فى الخد سابقة وبا والبوع آیضا مصدر باع یبوع بوعاء وهو بسط الباع فى المشى والتناول وفی الذر ع. والابل تبوغ فى سیرها. وقال فى بسط الباع: لقد عجفت أن ألقى المنايا ولم أن من المال ما أسْمُو به وأبوعٌ'),
(3602, 'بوغ', 'بوغ', 'بوغ', 'البَغاء: التراب الهابی فى الهواء. وطاشة الناس وحمقاهم وسفلتهم هم البوغاء والغوغاء.'),
(3603, 'يوق', 'يوق', 'يوق', 'البَوْق من الطر: الکثیر یقال: أصابهم بوق من الطر. وقول روبة1: من باکر الوسمی نضاخ الب وّق جمع بوقة كما قالوا فى جمع الأوقة: أوّق. ویقال: هو جاعة بوق الطر ویقال: بل البُوقة شُحرة من دق السَحر شديدة [الالتواء](۳. وهذا كما قال: منهتك الشعران نضتساح العذب'),
(3604, 'العذب', 'العذب', 'عذب', 'شجرة من الدّق. وباقتهُم بائقة تبوقهم بُؤُوقاء أى: نزلتٌ بهم نازلة شدیدة. (۱) البيت فى اللسان وفیه روایات عدة. وفی الحکم قال: أنشد ابن الأعرابى... فذ کره ولفظه: فانك إن تبصنی أستبييص (۲) دیوانه ۱۰۰. (۳) (ط): فى النسخ: الارتواء. ۱۷ باب الباء'),
(3605, 'البوائق', 'البوائق', NULL, 'الدواهی وكذلك: البوائج. والبوق: شبه به [منقاف ]| ؟ مُتتوی الخرّق وربما نفع فيه الطَحَاتُ فيعلو صوته ويلم راد به ویقال لِمَنْ لا يكم شيئا: إنما هو بُوق.'),
(3606, 'بوك', 'بوك', 'بوك', 'لقيئه رل بوك أى: ول مره ویقال: أوّل بوك وصّوْكِ وعزلیه کلها واحد والبائكة والبوائك من حیاد الابل.'),
(3607, 'يول', 'يول', 'يول', 'الَوْل: معروف وقد بال يُبول. والبال: بال النسء وهو الاكتراث ومن اشتق باليْت والمصدر: البالاة. وفى مواعظط ا لحسن: لا يبالهم بالة ولم أبال ولم أَبَلْ على القصر. والبال أيضا: رخاء الیش تقول: إنه لناعم البال ورخی البال.'),
(3608, 'بون', 'بون', 'بون', 'یقال: بینهما بون بعید . والبوان: من أعمدة الخباء عند الباب والجميع: الأبُونة والبوائن'),
(3609, 'بوه', 'بوه', 'بوه', 'البوهةً: ما ارت به الرّيح من جُلال التراب. يُقال: هو أهونُ عليه من صوفة فى بُوهة. والبُوهةٌ: الضَّعيفُ من الرحال, الطائش. قال:'),
(3610, 'الباة', 'الباه', 'باه', 'الحلوة فى النكاح. ومن كلامهم: طلبن الاه إذْ فاته الباهُ. وفى الحديث: وأن امرأة مات عنها زوجُهاء فمرّ بها رحل وقد ریت للباه,( أى للتكاح. | يوا (بوو): البو غير مهموز: جلد خوار یخشی 59 فتعطفُ عليه الناقة. والرماد: بسو الأثافى.'),
(3611, 'بيت', 'بيت', 'بيت', 'یت من بیوت الناس وت من أبيات الشّعْر. وتات العرّب: أحياؤها. وی پیا ای بَنْنُه. یت بسو فلان قولهم أى قدّروه وأصلخوه شب بتقدير بيات الشّعره ونوا هذا العَمّل بیاّا ای عولوه ليا قال عبید بن هلال: ونی فلم ارضَ ما بوا وکانسوا آتونی بشسیء نکر'),
(3612, 'البينوتة', 'البينوته', NULL, 'دولك فى الليل تقول: بت + أصنعٌ كذا إذا كان باللیل وبالتهار ظللت ومن قَسرَ بات على الوم فقد أخطأء ألا ری أنك تقول: بت أراعى الوم معناه: 3 آنظر إليهاء فكيف نام وهو ينظر إليها؟. وتقول: باهم الله إباتة حَسَنة فباتوا بيتوتة (۱) (ط): فى النسخ: منقاب بالبای وما أثبتناه فمن التهذيب (۳۵۰/۹) عن العين والمحكم (-/>۳). واللسان (بوق). (۲) الحديث آورده ابن الأثير فى النهاية (۱۳۰/۱) بلفظ الباعة. وو'),
(3613, 'ييد', 'ييد', 'ييد', 'البَيْدُ من قولك: باد يبيد وأباده الله. والبَيْداءُ: مفازة لا شیء فيهاء [وبين السجدین أرض ملساء اسمها البيْداء]. وفى الحديث: أنّ قومًا يغزون البيت فإذا نلوا بیدا وهی مَغازة بين مَك والمدينة مَلْساءُ بَعّت الله ملكا فیقول: يا يَبْداءُ ییدی بهم فیحسّف بهم. وبَيْدمعنى غير ویقال: ععنی على وید لغة فیها. وأتادٌ بيدانة أى تسكن البيداء.'),
(3614, 'بیس', 'بیس', 'بیس', 'بَيْسان: موضع.');
INSERT INTO entries (id, word, normalized_word, root, meanings) VALUES
(3615, 'پیص', 'پیص', 'پیص', 'یقال: هو فى حَیْص بیص أى فى اخلاط من أمر لا مرح له منه. ومن قال: حیص بیص آحرحه مخرّج الفعل الاضی؛ معناه: کان الأرض حيطت عليه فليس يد عنها مذهبًا. ويَيْص شيعة لِحیّص.'),
(3616, 'بيض', 'بيض', 'بيض', 'البَيْضْ: معروف ودجاحة بيوض وهن ایض [للجماعة مثل حَيّد جع حَيُود وهی التى تحيد عنك]. وه الحديد معروفة وَبَيِضَةُ الإسلام: جماعاتهم. واجارية بيضة الخذر لأنها فى جذوها مُكنونة قال امرؤ القيس: وبَيِضّةٍ جدر لا يرام خجياؤها تمتفت من لو بها غیر مُعْجَلٍ [ویقال: ابتیض القوم إذا استبييحت بیضتهم]. وابتاضهم الکو إذا استأصلهم. وَغْرابٌ بائضٌ, وديك بائضّ؛ ۲ [وهما مشل الوالد]. وبَيْضَةٌ العقر: مَتَلّ یضرّب وذلك (۱) الرجز بلا نسبة فى التهذیب (۰)۲۱۷/۰ واللسان (بيح). (۲) الحديث رواه بنحوه مسلم فى کتاب الفتن (۲۸۸۲). (۲) (ط): آثبتناها من مختصر العین (ق ۲۱ . )٤(‏ (ط): علق الأزهرى فقال: قلت: يقال دحاجة بائض بغیر هاء لأن الديك لا يبيض. ۱۷۹ ۱ باب الباء ار وم أن تغتصب الحارية فتفتض ذ فتحرّب پیضة وتسَمّی تلك البَيْضَّة بيضة العقر(. وبیضة'),
(3617, 'البیضة', 'البیضه', NULL, 'أصل القوم ومجمعهم.'),
(3618, 'بيظ', 'بيظ', 'بيظ', 'الب یقال: ماءُ الرحل؛ ولم أسمَّعْ منه فعل فإ جع فقياسٌّه البُيُوظ والأبياظ.'),
(3619, 'بيغ', 'بيغ', 'بيغ', 'الببْغ: نوور الدّم وفوْرته حتى يظهرَ فى العروق وقد تبيغ به الدّم.'),
(3620, 'يين', 'يين', 'يين', 'وأمًا البائن فأحَدُ الحالبين اللديْن یخلبان الناقة. والآخر یسَمّی المستعلى قال(: یش تع ابائ من الحالبين بألا غرارا'),
(3621, 'البانا', 'البانا', NULL, 'شجر الواحدة: بانة. والیْونة: مصدر بان بين بَيْنَا وبينونة أى: قطم.'),
(3622, 'البين', 'البين', 'بين', 'الفرقت والاسم: این أيضًا. والبين: الوصل قال عر من قائل: لإلقد تقطع بینم [الأنعام: ]٩ ٤‏ أى: وَصلكم. وزيقال]: بانت يذ الناقةٍ عن جنبها بينونة وبَينونًا.'),
(3623, 'بیی', 'بیی', 'بیی', 'فى مثل تضربه العرب: هی بن بئ ومنهم من یقول: هيان بن بيان وهو عنزلة طامر بن طاس لا يذكر أصله وفتلة. قال أميّة بن أشكر ابحندعی: (۱) (ط): ذکر الأزهرى معلقا: قال غير اللیث: بيضة العقر بيضة يبيضها الديك مرة واحدة ثم لا تعود تضرب مثلا لمن یصنع صنيعة إلى انسان ثم لا يربها عثلها. (۲) ما بين القوسین زيادة ضرورية لتمام الاية. (ط). (۳) الکمیت. كما فى اللسان (بين).'),
(3624, 'قا', 'قا', 'قا', 'التاء: حرف من حروف العجم لا یغرب. ورتا) و(ته) لغتان كقولك: (ذا) وَ(ذِة) وتقول: هذى فلانق كقولك: هذه. وفى لغة: هاتا فلانق وهی بغیر هاء أحسن كقول الشاعر: ها إن تا عذرة إلا تكن نفعت فاد صاحبّها قد تاه فى الب لد وعلى هاتيْن الغتین قالوا: تي تيك وتلك وتالك كما قالوا: ذلك وهی اقح اللغات فإذا یت لم تقل لا تاه وتاك وتین وتیل فى امسر والنصْب فى اللغات كلهاء وإذا صرت ت لم تقل لاه وبها سيت المرأة ام ودالّتى هی معرفة (تا) لا يقولونها فى المعرفة إلا على هذه اللغة وجَعَلوا إحدى امین تقوية للأخرى استقباحًا أن يقولوا التى وانما آرادوا بها الألف واللام العرفت وابحمیع اللاتی؛ واللواتی جمع اللاتی؛ ویلقون التاء فیقولون: اللانی, ممدودة [وقد تحرج الياء فيقال: اللاء] بكسرة تدل على الياء. وتصغیر التی: : اه ویمَع: لت . وانما صار تصغير (ته) ورذ وما فیهما من اللغات (نيّا) لأنْ التاء والذال من (ذو) (وته) كل واحدةٍ هی تفس الكلمة ومالحقها من بعدها فإنه ما تمه لكى ينطلق به اللسانء فلما صرت لم تماد ياء التصغير حَرْفيْن من أصل البناء تجىء بعدها كما جاءت فى ُعَيْد وعُميْر. والتصغير على أربعة'),
(3625, 'أنحاء', 'انحاء', NULL, 'تقريب وتقليل وتصغير وتحقير ولکنهما وتا بعد القاء فجحاءت بعد فتحق والحرف الذى قبل ياء التصغير يحنبها لا يكون إل مفتوحًّاء ووقعت التاء إلى جنبها فانتصبّت وصار ما بعدها وة لها ولم يُنضمٌ قبلها شىءٌ لأنه ليس قبلها حَرْفان؛ وجميع التصغير صدره مضموم؛ والحرف الثانى منصوب؛ ثم بعدهما ياء التصغير ومنعَهم أن يرفعوا الياءَ التى فى التصغير؛ ان هذه الأحرف خلت عمادًا سان فى آخجر الكلمة فصارت الياء التى قبلها فى غير موضعهاء لأنها بت للسان عمادًاء فإذا وقَعَتْ فى الحشو لم تكن عمادًاء وهی فى بناء الألف التى كانت فى (تا) قال الشاعر فى تصغير التى: مع اللا وال" وات (۱) بلا نسبة فى اللسان (تا) وفيه: (بعد) مكان مع.'),
(3626, 'تأتا', 'تاتا', NULL, 'اس وتات الي عند السار'),
(3627, 'تأق', 'تاق', 'تاق', 'التأق: شد الامتلاء. 559 الف تا تاق تقد تن ا (تآقا. وتَقِقَ فلان إذا امتلاً خرن وکاد ينكى. وفرس تبق: ممتل؛ جریا. وأتأقت القوس: ترعتها فآغرقت'),
(3628, 'تأل', 'تال', 'تال', 'التألاث: الذی كأنه [ينهض] برأسه إذا مَشَىء بحر که إلى فوق مثل الذی يعدو وعليه حمل ثقيل. تام انظر مادة (توم).'),
(3629, 'تبب', 'تبب', 'تبب', 'التبا الخسار؛ وتنا له تعیب لأنه مصدرٌ محمول على فعله. كما تقول: ستيًا لفلان معناه: سُقَىَ فلا سقيّء وتب يقب تبابا وتبا ولم يُجمّع اسْمًا مسندًا إلى ما قبله. تبت القومٌ ای قلت لهم: تنا لكم. ونا لفلان تتبًاء ويقال: با لفلان تبيناء والتساب الهلاك قال: أرَى طول الحياة وان تى تصيّرُه اور إلى تباب( واستتبٌ له الامر أى تیا ورجل تاب أى ضعيف وجمعه أتباب.'),
(3630, 'قير', 'قير', 'قير', 'التبر: الدَهَبْ وال قبل أن يُعْمَلا. ویقال: كل جَوْهرٍ قبل أن يُستعمّل یب من التحاس والصّفر. کل قوم صيغة من برهم وشو عبد مناف من ذه'),
(3631, 'التباز', 'التباز', NULL, 'الهلاك والفناء وتبرَ تبر تبارّا؛ وتبرهم الله تتبيرا.'),
(3632, 'نیع', 'نیع', 'نیع', 'التابع: التال ومنه التتبع والمتابعة والاتباع یتبعه : یتلوه. تبعه عه يتبَعْهُ تبکا. والتتبع: فعلك شيئًا بعد شىء. تقول: تتْعت علمه أى: اتبعت آثاره. والابعة: حمّة تکون مع الإنسان تتبعه حیثما ذهب. وفلاد يسابع الامای أى: یزانیهن. والتابعة آن تتبعَةُ هواك وقلبك. تقول: هؤلاء تبع وأتباع أى: بكوك ومتابعوك على هواك. والقوائم يقال لها: (۲) البيت بلا نسبة فى اللسان (تبر). ۱۸۰ باب التاء تبع. قال أبو دو اد وتونم سم لیا من خلفهازتغ ملق یصف الظبية. وقال: ۱ سحب الیل نوما طلا وتواليها بطیفات التبم وی الل رك من ولد يقر لكر لأنه يتبع أَمَه بعدو. والعدد: أتبعت فلانا إذا تَبعَه يُريد شرا. قال لله عت و اه الشيطان فكان من الغاوين [الأعراف: 76 .]١‏ والتتابُعٌ ما بين الأشياء إذا فعل هذا على إثر هذا لا مهلة بینهما كتتابع الأمطار والأمور واحدًا حلف آحرء كما تقول: تابع بين الصلاة والقراءة كما'),
(3633, 'التبيع', 'التبيع', NULL, 'التصیر. والَبِعَةٌ هى التباعت وهو اسم الشىء الذى لك فيه بغية شبه ظلامة : و و و و ۱ سا رع و ىس ونحوها. والتبع والتبع: الظل؛ لأنه متبع حيثما زال. قال الفرزدق: 00 وز لطا د تان الخ بر و 3 ملوك اليمن و کان مومن و لهم هذا ا ون شمه'),
(3634, 'ضرير', 'ضرير', NULL, 'تبوك اسم بركة لأبناء سعد من عذرة سميت لأن النبى صلى الله عليه ولآله وسلم لما غزا تلك الناحية رآهم يحفرون البركة ولم يمهوها بعد ف ركز عنزته فيها ثلاث ركزات فجاشت'),
(3635, 'قهن', 'قهن', 'قهن', '[الَبْنَ: يُروى العشرين وهو أعظم الأقداح, ثم الصّحْنُ مقاربٌ له ثم العس يُروى الثلاثة والأربعة]. والتبْن: الس الم فى قول أبى القدام لقوله: نمتبسارأيٌه مكبالاً ورجل لبن فَطنّ وطن وقیل: النُ: الفطن فى ابر والطین ف اش وكبن: ذو تن وتان ٠‏ وين لفلان أى فطن وجه غیلته و عدیعته. وهو تب بالخ لا يقال منه فاعل. ویقال: نت أى دققت ال ف الأمور رلا يقال للأمر للازم فى القلب: إن ق قلبه لأمرًا تن'),
(3636, 'البان', 'البان', 'بان', 'شب سَراويلَ والمابين: الأقبية القصارٌ الأكمام. والَبْنُ: معروف والواحدة 3 والّین لد ۱ ۱'),
(3637, 'ق حديث', 'ق حديث', 'ق', 'ولا تقوم الساعة حي يظهر الوت ê‏'),
(3638, 'دحف', 'دحف', 'دحف', 'الحفة: أبدلّت التاء فيها من الواو إلا أن هذه التاء تلزم فى التصريف كلف الا ف ِيُتفَكّل كقوطم: يَكَرَحَّفء ويقولون: أنْحَفْنُه تُحفهٌ يعن طرف الفواكه.'),
(3639, 'نضغ', 'نضغ', 'نضغ', 'التختخة: فى حكاية بعض الأصوات كأصوات الجنان وبه سُمى التختاخ.'),
(3640, 'التخ', 'التخ', 'تخ', 'لمجین اخامض؛ تخ يتخ تخا وتخوحاء وا ناسا'),
(3641, 'التريبة', 'التريبه', NULL, 'ما فوق تین إلى تزقوتین وقيل: کل عظم منه تريبة وتجمع الترائب [تریص: ترتمت الأرض إذا أَرسلت فیها الاء فمخرتها لعجودع(؟)'),
(3642, 'قرج', 'قرج', 'قرج', 'الترنج: لغة فى لح والرنژ: لغة فى الأَررٌ.'),
(3643, 'المتراح', 'المتراح', NULL, 'الناقة التى يسرع انقطاعٌ لبنهاء وتجمّع: مُتاريح. (۱) رواه أحمد (۳۲۷/۲). (۲) (ط): سقطت هذه الكلمة وترجمتها من الأصول فأثتئاها من التهذيب (۲۷۳/۱۲) عن العين.'),
(3644, 'قرر', 'قرر', 'قرر', 'الترارة: امتلاء الجسم من اللحم وری العظب ورحل تا وقصرة تارق والفغل'),
(3645, 'رت والترور', 'رت والترور', 'رت', 'و النّواة من الحَيْسء یقال: تر یت تروًا. وأترّرت ید بالسَیّف إترارًا. [وضرّب > فلان ید فلان بالسيف فأترّها وأَطَرّها وأطنها] 00 . والغلام یر الق مقلا [وقال طرفة: تقول وقد تم الويف وساقها . الست تری أن قد اتيت ویر( ا انقطع فبانَ وسقط. والتئّرة أن تقبض على يدَى رحل ثم رت أى 7 که. والتر كلمة تتکلم بها العرب إذا عضب أحذهم على الآحر قال: والله منك على ال وهو اليل الذى يتدٌ یسح به الأرض. والترَة: الباطل وهی الترّهات ایض . والتارٌ: الغائب النفرد من قومه.'),
(3646, 'قرز', 'قرز', 'قرز', 'ترز الرَجْل إذا مات ويبس بلا روح [والتارز: الیابس بلا روح]) قال: (قلیل التلاد غَيْرَ قوس وأسهم] كأنّ الذى يرمى من الوحش تار وقال أبو ذؤيب: فكبا كما يكبو فیق تاررٌ بلحت إلآأقههوابرع'),
(3647, 'نرس', 'نرس', 'نرس', 'رس مح ترس. و کل شىء تست به فهو مِتَرّسّة لك.'),
(3648, 'ترا أى', 'ترا اي', 'ترا', 'متلا نشیطاء جاحماء أى: لهبّا ووقودًا. وإنه لمتترّعٌ إلى كذاء أى: متسر ع. وقول رسول الله صلی الله عليه و آلم(۲) : وان منبرى على ترْعَةٍ من ترّع الجنة. يقال: هى الرجة ويقال: هی الباب كأنه قال: إن ری على باب من أبواب الجنة. والترعَةٌ - والجماعة رم -: أفواه الجداول تفجر من الأنهار فيها وتسکر إذا ساقوا الماء.'),
(3649, 'نرفت', 'نرفت', NULL, 'الترف: تعیم الغذاءء وصبی متفه والترف: لسع عليه عَيْشُه؛ لقلیل فيه همق وأترقه | الله ورف والأزمة فى سط شمه الشفلى. ؛ وهی هَنة نامه خلقت'),
(3650, 'قرق', 'قرق', 'قرق', 'الترقوة: اد وهو وال عظم ين رد خر وی فى ان والتریاق: لغة فى الدریاق وهو ذواء.'),
(3651, 'التريكة', 'التريكه', NULL, 'ما يَمْضى عنه سل ویت رکه ناقعا. وسْمّی الغدی لأنّ السَیْل غادره. (۱) البيت فى التهذيب )۲٦۷/۲(‏ وفى اللسان (ترع). وفيه: وحاميًا بردا. (۲) سبق التنبيه على أنه ينبغى الجمع بين الصلاة والتسليم. انظر الأذكار للنووی (ص ۰۱۷ (Yo وفى المحكم (۳۰/۲) والرواية‎ DY الحديث فى مسند أحمد (/۳۳۹) وفی التهذيب‎ )۳('),
(3652, 'فيه', 'فيه', 'فيه', 'إن متیری هدا'),
(3653, 'قرمس', 'قرمس', NULL, 'التْرمُسٌ: شجر له حب مُضَلّعْ مُحرّزء وبه سم الحمان : ترامس. والمترس الخَلّق: الق المضيّر.'),
(3654, 'الواحدة', 'الواحده', NULL, 'ترهة.'),
(3655, 'قعع ۲', 'قعع ۲', 'قعع', 'التشتعة: أن يَعيَا الرحلٌ بكلامه ويتردَّدُ من عى أو خصّر. ويقال: ما الذى تعتعه؟ فتقول: العی. وبه شه ارتطام الدَابّة فى الرَمْلء قال الشاعر") (۱) (ط): فى الأصول: الحمار بالراء وهو تصحيف ظاهر والتصويب من اللسان (ترمس). (۲) رژبة ديوانه .)١55(‏ (۳) (ط): زيادة اقتضاها السياق. (كانهياض التعب). )٥(‏ أوردها الخليل فى (باب العين والتاء (ع ت ت ع مستعملان). ۱۸۹ باب التاء تيع فى اخبار إذا عسلاه وبع فى الطرسی المستقيم'),
(3656, 'تغت', 'تغت', 'تغت', 'تغت الجارية الضَحلت إذا رات أن تحفيه ویغالیها.'),
(3657, 'قغر', 'قغر', 'قغر', 'تفرت القدر تفرا وتغرانها: غلیانیه وآنفرتها: اغلینهه قال: وصَاء ماه لم يقم بها خیف ولم تتفر بها ساعة قلر'),
(3658, 'قغغ', 'قغغ', 'قغغ', 'والتغتغة فى جكاية ای . وفی نسخة الحاتمي: حكاية الحيلى.'),
(3659, 'قفج', 'قفج', 'قفج', 'التقاح: فاکهت الواحدة تقاحة.'),
(3660, 'تفطر', 'تفطر', NULL, 'التفاطير: اول بت یم فى مواقم من الأَرْض مختلفة, قال: تفاطير وسمی رواء جُذُورُها'),
(3661, 'تفف', 'تفف', 'تفف', 'الف رسخ الأظفارء والأف: رسخ الأذن. والتتفیف من النفّ كال أفيف من'),
(3662, 'لاف ویقال', 'لاف ویقال', 'لاف', 'اة لك وف وأفٌ ولاف'),
(3663, 'قفه', 'قفه', 'قفه', 'تفة الشّیء يتفه تفا فهو تفه أى قليلٌ حسیسن. وتف الرجل يتفه تفرهٌا فهو تافه ورج تافهٌ العقل: أحمق.'),
(3664, 'ققر', 'ققر', 'ققر', 'التقرة والتقرُ أحَذهما الكَرَويا" والاحر التوابل.'),
(3665, 'آرضهم. أى', 'ارضهم. اي', NULL, 'آرسلوا فيها الماء الخائرَ لتَحود. والإتقاث: الاحکام قال: ولكنه بالسّهُل أتقن'),
(3666, 'تكا', 'تكا', 'تكا', 'تکاة بوزن فعَلة أصل هذه التاء من الواو والتاء مستعملة فى هذه را) علق الأزهرى فقال: غلط اللیت لأن التغتغة صوت الضحك. (۲) كذا فى (ط). وفی اللسان (تقر): الکرویا.'),
(3667, 'تکك', 'تکك', 'تکك', 'كل ہے اكه زوم بك الستراویل) 7 وفلا کت بالمرير. یتک بالادغام أيضا.'),
(3668, 'متالع', 'متالع', NULL, 'اسم موضع بالبادية. قال لبيد: درس القَايمُتالع فأبان فتقادَمَت باس فالسوبان'),
(3669, 'التلعة', 'التلعه', NULL, 'أرضٌ مرتفعة غليظة ورعا كانت مع غلظها عريضة يتردّد فيها السّيل ثم يدفع منها إلى تلعة سفل منها. قال النابغة: فاق لاع التوانسسم'),
(3670, 'تلل', 'تلل', 'تلل', 'التَلُ: الرابية من الثراب مكبوس ليس عيلقة. والتلیا: العنق [قال لبيد: یتقینی بتلیل ذى خضل )١(‏ الأعشى: فى اللسان والتاج (تلع) والمحكم (۳۷/۲) بلفظه. وتمامه فيه: يوم تبدى لنا فة عن حي ل تلیع تریسنه الأطلواق (۲) أورده ابن الأثير فى معناه (45/ . (۳) عجز بيت وصدره كما فى الديوان (ص ۱۹۰): وتأييت عليه ثانيا. وهذا العجز من التهذیب وراللسان من أصل العين).'),
(3671, 'المتل', 'المتل', 'متل', 'القوی الشدید أَسَدٌ وريخ سل وتللته فى ید دفعته إليه سِلمً . والتلتلة: الإقلاق [والحركة] ۰ والتلعلة: المشربة تتحذ من قيقاءة الطلع. ورجل متل: منتعیبٌ فى الصلاق قال: على فهر عادی كأ أرُومَه رحال تون الصلاةً ي۸ أى يَقَضُوتها. وتّلَّ فلا فلانا أى صَرَعَه وما آسوء تلته أى صرَعته. وقوه فى قبره متلا أى آوردوه. والتلعلة مثل رت فى التحريك.'),
(3672, 'قلاء تلو', 'قلاء تلو', 'قلا', 'ثلا فلا القرآن يتلو تلاوةٌ. وتلا الشىء: تبعه تلو والأمّهات EE:‏ تلا لاهن والواحد مت والتلؤ: وَلَدُ الحمارء وکل شىء تلا يتلو شيا فهو تلوه.'),
(3673, 'التلية', 'التليه', NULL, 'الحاحة . وأثليت فلانا على فلان. أى: أحلته.'),
(3674, 'التمرة', 'التمره', NULL, 'طائرٌ أصعْرٌُ من العُصفور. والْحُمَئرٌ: الشّابٌ. وتمرة الفراب: أطيب ال له لا يقصد الا الطيّب فإذا سَقَطَت بادَرُوا إلى آحنها.'),
(3675, 'صحیح', 'صحیح', NULL, 'یتلون على ما لم یسم فاعله. (۳) روبة دیوانه (۷ ۰۱ والرواية فیه: میله. ۱۹۰ باب التاء بلسان العجم؛ والفّلول أيضًا مت ال من الماح وغيره یفعل من تل وهو الدفع ول فى يده شینا أى ذَفَعْ. هم تم الشیء يعم تماما وتشنه الله تشميمًا و تمه تِه کل شىء ما يكون ناما لغايته كقولك: هذه الدراهم تمام هذه المائة وة هذه المائة. والتم: الشی؛ اتا يقال: عه تماه أى بتمايه. والتمیمة: قلادة من سيور وربّما خولت العُوذة التى تعلق أعناق الصبيان قال: وكيف یل العّرئ یلو بها قشت عده سور سیم [وفی حدیث ابن مسعود: ران التمائم والرقی والتوّلة من الب ٠‏ وأتمّمته اقامٌا: عَلَفَتْ عليه التميمة. واستتمٌ نعمة الله بالشكر. نی تکام تن سا عطي موضيع الحرف فيرجع إلى لفظر كأنه التاء والميم. . ورحل تَمْتاةٌ. وتمّمّ الرجل إذا صار تمیمی الرأى والهَوى. والتمام: أطوّلُ ليلةٍ فى السنة ويقال: يله السام ثلاث ل يستبان فيها تقصان من زيادة وقيل: بل ليلة آربع عشرته وهی ليلة انار وهى الليلة التى يتم فيها القَمَرُ فيصير بدرًا. والتميم فى لغة: التمام قال رژ جرت تمیما لم تخنق حَهْضا(")'),
(3676, 'التمیم', 'التمیم', NULL, 'الشديد. ويقال: ابی قائلها إلا تًا أى ابی الا أن لیم على ما قال.'),
(3677, 'نمه', 'نمه', 'نمه', 'تمه الب مه تما فهو تي إذا تغیر. وشاة متماة: مه لها ریت" يُحلب. وال فی ال کالنمّس فى الدّسّم وغیره والطیب ونخوه. نيس الم وغیره: تغيّر'),
